comms.text:
@1 וּקְרָא לְמֹשֶׁה וּמַלֵיל יְיָ עִמֵיהּ מִמַשְׁכַּן זִמְנָא לְמֵימָר:
@2 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֱנַשׁ אֲרֵי יְקָרֵב מִנְכוֹן קוּרְבָּנָא קֳדָם יְיָ מִן בְּעִירָא מִן תּוֹרֵי וּמִן עָנָא תְּקָרְבוּן יָת קוּרְבַּנְכוֹן:
@3 אִם עֲלָתָא קוּרְבָּנֵיהּ מִן תּוֹרֵי דְכַר שְׁלִים יְקָרְבִנֵהּ לִתְרַע מַשְׁכַּן זִמְנָא יְקָרֵיב יָתֵיהּ לְרַעֲוָא לֵיהּ קֳדָם יְיָ:
@4 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ עֲלָתָא וְיִתְרְעֵי לֵיהּ לְכַפָּרָא עֲלוֹהִי:
@5 וְיִכּוֹס יָת בַּר תּוֹרֵי קֳדָם יְיָ וִיקָרְבוּן בְּנֵי אַהֲרֹן כָּהֲנַיָא יָת דְמָא וְיִזְרְקוּן יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר דִי בִתְרַע מַשְׁכַּן זִמְנָא:
@6 וְיַשְׁלַח יָת עֲלָתָא וִיפַלֵג יָתַהּ לְאֶבְרָהָא:
@7 וְיִתְּנוּן בְּנֵי אַהֲרֹן כַּהֲנָא אֶשָׁתָא עַל מַדְבְּחָא וִיסַדְרוּן אָעַיָא עַל אֶשָׁתָא:
@8 וִיסַדְרוּן בְּנֵי אַהֲרֹן כָּהֲנַיָא יָת אֶבְרַיָא יָת רֵישָׁא וְיָת תַּרְבָּא עַל אָעַיָא דִי עַל אֶשָׁתָא דִי עַל מַדְבְּחָא:
@9 וְגַוֵיהּ וּכְרָעוֹהִי יְחַלֵל בְּמַיָא וְיַסֵק כַּהֲנָא יָת כּוֹלָא לְמַדְבְּחָא עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@10 וְאִם מִן עָנָא קוּרְבָּנֵיהּ מִן אִמְרַיָא אוֹ מִן בְּנֵי עִזַיָא לַעֲלָתָא דְכַר שְׁלִים יְקָרְבִינֵיהּ:
@11 וְיִכּוֹס יָתֵיהּ עַל צִדָא דְמַדְבְּחָא צִפּוּנָא קֳדָם יְיָ וְיִזְרְקוּן בְּנֵי אַהֲרֹן כָּהֲנַיָא יָת דְמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@12 וִיפַלֵג יָתֵיהּ לְאֶבְרוֹהִי וְיָת רֵישֵׁיהּ וְיָת תַּרְבֵּיהּ וְיַסְדַר כַּהֲנָא יָתְהוֹן עַל אָעַיָא דִי עַל אֶשָׁתָא דִי עַל מַדְבְּחָא:
@13 וְגַוָא וּכְרָעַיָא יְחַלֵל בְּמַיָא וִיקָרֵב כַּהֲנָא יָת כּוֹלָא וְיַסֵק לְמַדְבְּחָא עֲלָתָא הוּא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קָדָם יְיָ:
@14 וְאִם מִן עוֹפָא עֲלָתָא קוּרְבָּנֵיהּ קֳדָם יְיָ וִיקָרֵב מִן שַׁפְנִינַיָא אוֹ מִן בְּנֵי יוֹנָה יָת קוּרְבָּנֵיהּ:
@15 וִיקָרְבִינֵהּ כַּהֲנָא לְמַדְבְּחָא וְיִמְלוֹק יָת רֵישֵׁהּ וְיַסֵק לְמַדְבְּחָא וְיִתְמְצֵי דְמֵיהּ עַל כּוֹתֶל מַדְבְּחָא:
@16 וְיַעֲדֵי יָת זְפָקֵיהּ בְּאוּכְלֵיהּ וְיִרְמֵי יָתַהּ לִסְטַר מַדְבְּחָא קִידוּמָא לַאֲתַר דְמוֹשְׁדִין קִטְמָא:
@17 וִיפָרֵיק יָתֵיהּ בְּגַדְפוֹהִי לָא יַפְרֵישׁ וְיַסֵק יָתֵיהּ כַּהֲנָא לְמַדְבְּחָא עַל אָעַיָא דִי עַל אֶשָׁתָא עֲלָתָא הוּא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@18 וֶאֱנַשׁ אֲרֵי יְקָרֵב קוּרְבַּן מִנְחָתָא קֳדָם יְיָ סוּלְתָּא יְהֵי קוּרְבָּנֵיהּ וִירִיק עֲלָהּ מִשְׁחָא וְיִתֵּן עֲלָהּ לְבוֹנְתָּא:
@19 וְיַיְתִינָהּ לְוַת בְּנֵי אַהֲרֹן כַּהֲנַיָא וְיִקְמוֹץ מִתַּמָן מְלֵי קוּמְצְיהּ מִסִלְתָּהּ וּמִמִשְׁחָהּ עַל כָּל לְבוֹנְתָּהּ וְיַסֵק כַּהֲנָא יָת אַדְכַּרְתָּהּ לְמַדְבְּחָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@20 וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקוּרְבָּנַיָא דַיְיָ:
@21 וַאֲרֵי תְקָרֵיב קוּרְבַּן מִנְחָתָא מַאֲפֵה תַנוּרָא סוּלְתָּא גְרִיצָן פַּטִירָן דְפִילָן בִּמְשָׁח וְאִסְפּוּגִין פַטִירִין דִמְשִׁיחִין בִּמְשָׁח:
@22 וְאִם מִנְחָתָא עַל מַסְרֵיתָא קוּרְבָּנָךְ סוּלְתָּא דְפִילָא בִמְשַׁח פַּטִיר תְּהֵי:
@23 בְּצַע יָתָהּ בִּיצוּעִין וּתְרִיק עֲלָהּ מִשְׁחָא מִנְחָתָא הִיא:
@24 וְאִם מִנְחָתָא דְרַדְתָּא קוּרְבָּנָךְ סוּלְתָּא בִּמְשַׁח תִּתְעֲבֵד:
@25 וְתַיְתֵי יַת מִנְחָתָא דִי יִתְעֲבֵיד מֵאִלֵין קֳדָם יְיָ וִיקַרְבִינָהּ לְוַת כַּהֲנָא וִיקַרְבִינָהּ לְמַדְבְּחָא:
@26 וְיַפְרֵישׁ כַּהֲנָא מִן מִנְחָתָא יָת אַדְכַּרְתָּהּ וְיַסֵק לְמַדְבְּחָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@27 וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִּבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקוּרְבָּנַיָא דַיְיָ:
@28 כָּל מִנְחָתָא דִי תְקַרְבוּן קֳדָם יְיָ לָא תִתְעֲבֵיד חֲמִיעַ אֲרֵי כָּל חֲמִיר וְכָל דְבַשׁ לָא תַסְקוּן מִנֵיהּ קוּרְבָּנָא קֳדָם יְיָ:
@29 קוּרְבַּן קַדְמַי תְּקָרְבוּן יַתְהוֹן קֳדָם יְיָ וּלְמַדְבְּחָא לָא יִתַּסְקוּן לְאִתְקַבָּלָא בְּרַעֲוָא:
@30 וְכָל קוּרְבַּן מִנְחָתָךְ בְּמִלְחָא תִּמְלַח וְלָא תְבַטֵל מְלַח קְיַם אֱלָהָךְ מֵעַל מִנְחָתָךְ עַל כָּל קוּרְבָּנָךְ תְּקָרֵב מִלְחָא:
@31 וְאִם תְּקָרֵב מִנְחַת בִּכּוּרִין קֳדָם יְיָ אָבִיב קְלֵי בְנוּר פֵּירוּכִין רַכִּיכָן תְּקָרֵיב יַת מִנְחַת בִּכּוּרָךְ:
@32 וְתִתֵּן עֲלַהּ מִשְׁחָא וּתְשַׁוֵי עֲלַהּ לְבוֹנְתָּא מִנְחָתָא הִיא:
@33 וְיַסֵק כַּהֲנָא יַת אַדְכַּרְתַּהּ מִפֵּרוּכַהּ וּמִמִשְׁחַהּ עַל כָּל לְבוֹנְתָּהּ קוּרְבָּנָא קֳדָם יְיָ:
@34 וְאִם נִכְסַת קוּדְשַׁיָא קוּרְבָּנֵיהּ אִם מִן תּוֹרֵי הוּא מְקָרֵב אִם דְכַר אִם נוּקְבָא שְׁלִים יְקָרְבִינֵיהּ קֳדָם יְיָ:
@35 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ קוּרְבָּנֵיהּ וְיִכְסִינֵיהּ בִּתְרַע מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן כַּהֲנַיָא יַת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@36 וִיקָרֵב מִנִכְסַת קוּדְשַׁיָא קוּרְבָּנָא קֳדָם יְיָ יַת תַּרְבָּא דְחָפֵי יַת גַוָא וְיַת כָּל תַּרְבָּא דִי עַל גַוָא:
@37 וְיַת תַּרְתֵּין כֻּלְיָן וְיַת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חַצְרָא דְעַל כַּבְדָא עַל כּוּלְיָתָא יַעֲדִינָהּ:
@38 וְיִסְקוּן יָתֵיהּ בְּנֵי אַהֲרֹן לְמַדְבְּחָא עַל עֲלָתָא דִי עַל אָעַיָא דִי עַל אֶשָׁתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@39 וְאִם מִן עָנָא קוּרְבָּנֵיהּ לְנִכְסַת קוּדְשַׁיָא קֳדָם יְיָ דְכַר אוֹ נוּקְבָא שְׁלִים יְקָרְבִינֵיהּ:
@40 אִם אִימַר הוּא מְקָרֵב יַת קוּרְבָּנֵיהּ וִיקָרֵיב יָתֵי קֳדָם יְיָ:
@41 וְיִסְמוֹךְ יַת יְדֵיהּ עַל רֵישׁ קוּרְבָּנֵיהּ וְיִכּוֹס יָתֵיהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יַת דְמֵיהּ עַל מַדְבְּחָא סְחוֹר םְחוֹר:
@42 וִיקָרֵב מִנִכְסַת קוּדְשַׁיָא קֻרְבָּנָא קֳדָם יְיָ תַּרְבֵּיהּ אֲלִיתָא שְׁלִמְתָּא לָקֳבֵל שֵׁזַרְתָּא יֶעְדִנַהּ וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא:
@43 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חַצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@44 וְיַסְקִנֵהּ כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא קֳדָם יְיָ:
@45 וְאִם מִן בְּנֵי עִזַיָא קֻרְבָּנֵהּ וִיקָרְבִנֵהּ קֳדָם יְיָ:
@46 וְיִסְמוֹךְ יָת יְדֵהּ עַל רֵישֵׁיהּ וְיִכּוֹס יָתֵהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יָת דְמֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@47 וִיקָרֵב מִנֵהּ קֻרְבָּנֵהּ קֻרְבָּן קֳדָם יְיָ יָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא:
@48 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חַצְרָא דִי עַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@49 וְיַםְקִנוּן כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא לְאִתְקַבָּלָא בְּרַעֲוָא כָּל תַּרְבָּא קֳדָם יְיָ:
@50 קְיָם עָלָם לְדָרָתֵיכוֹן בְּכָל מוֹתְבָנֵיכוֹן כָּל תַּרְבָּא וְכָל דְמָא לָא תֵיכְלוּן:
@51 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@52 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר אֱנַשׁ אֲרֵי יֵחוֹב בְּשָׁלוּ מִכָּל פִּקוּדַיָא דַיְיָ דִי לָא כַשְׁרִין לְאִתְעֲבָדָא וְיַעְבֵּד מִן חָד מִ נְה וֹן:
@53 אִם כַּהֲנָא רַבָּא יֵיחוֹב לְחוֹבַת עַמָא וִיקָרֵב עַל חוֹבְתֵהּ דִי חָב תּוֹר בַּר תּוֹרֵי שְׁלִים קֳדָם יְיָ לְחַטָאתָא:
@54 וְיַיְתִי יָת תּוֹרָא לִתְרַע מַשְׁכַּן זִמְנָא לָקֳדָם יְיָ וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ תּוֹרָא וְיִכּוֹס יָת תּוֹרָא קֳדָם יְיָ:
@55 וְיִםַב כַּהֲנָא רַבָּא מִדְמָא דְתוֹרָא וְיָעֵל יָתֵהּ לְמַשְׁכַּן זִמְנָא:
@56 וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵהּ בִּדְמָא וְיַדִי מִן דְמָא שְׁבַע זִמְנִין קֳדָם יְיָ קֳדָם פָּרוּכְתָּא דְקוּדְשָׁא:
@57 וְיִתֵּן כַּהֲנָא מִן דְמָא עַל קַרְנַת מַדְבַּח קְטוֹרֶת בּוּסְמַיָא קֳדָם יְיָ דִי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְמָא דְתוֹרָא יֵישׁוּד לִיסוֹדָא דְּמַדְבְּחָא דַעֲלָתָא דִי בִתְרַע מַשְׁכַּן זִ מְנָא:
@58 וְיָת כָּל תְּרַב תּוֹרָא דְחַטָאתָא יַפְרֵשׁ מִנֵהּ יָת תַּרְבָּא דְחָפֵי עַל גַוָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא:
@59 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חִצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@60 כְּמָא דִי מִתַּפְרֵשׁ מִתּוֹר נִכְסַּת קוּדְשַׁיָא וְיַסֵקִנוּן כַּהֲנָא עַל מַדְבְּחָא דַעֲלָתָא:
@61 וְיָת מְשַׁךְ תּוֹרָא וְיָת כָּל בִּסְרֵהּ עַל רֵישֵׁיהּ וְעַל כְּרָעוֹהִי וְגַוֵהּ וְאוּכְלֵהּ:
@62 וְיַפֵּק יָת כָּל תּוֹרָא מִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְכֵי לַאֲתַר בֵּית מֵישַׁד קִטְמָא וְיוֹקִיד יָתֵהּ עַל אָעַיָא בְּאֶשָׁתָא עַל אֲתַר בֵּית מֵישַׁד קִטְמָא יִתּוֹקָד:
@63 וְאִם כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל יִשְׁתְּלוּן וִיהֵי מְכַסָא פִּתְגָמָא מֵעֵינֵי קְהָלָא וְיַעְבְדוּן חָד מִכָּל פִּקוּדַיָא דַיְיָ דִי לָא כָשְׁרִין לְאִתְעֲבָדָא וִיחוֹבוּן:
@64 וְתִתְיְדַע חוֹבְתָא דִי חָבוּ עֲלַהּ וִיקַרְבוּן קְהָלָא תּוֹר בַּר תּוֹרֵי לְחַטָּאתָא וְיַיְתוּן יָתֵהּ לָקֳדָם מַשְׁכַּן זִמְנָא:
@65 וְיִסְמְכוּן סָבֵי כְנִשְׁתָּא יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא קֳדָם יְיָ וְיִכּוֹס יָת תּוֹרָא קֳדָם יְיָ:
@66 וְיָעֵל כַּהֲנָא רַבָּא מִדְמָא דְתוֹרָא לְמַשְׁכַּן זִמְנָא:
@67 וְיִטְבּוֹל כַּהֲנָא אִצְבְּעֵהּ מִן דְמָא וְיַדִי שְׁבַע זִמְנִין קֳדָם יְיָ יָת קֳדָם פָּרֻכְתָּא:
@68 וּמִן דְמָא יִתֵּן עַל קַרְנַת מַדְבְּחָא דִי קֳדָם יְיָ דִי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְמָא יֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא דַעֲלָתָא דִי בִתְרַע מַשְׁכַּן זִמְנָא:
@69 וְיָת כָּל תַּרְבֵּהּ יַפְרֵשׁ מִנֵהּ וְיַסֵק לְמַדְבְּחָא:
@70 וְיַעְבֵּד לְתוֹרָא כְּמָא דִי עֲבַד לְתוֹרָא דְחַטָאתָא כֵּן יַעְבֵּד לֵהּ וִיכַפֵּר עֲלֵיהוֹן כַּהֲנָא וְיִשְׁתְּבֵק לְהוֹן:
@71 וְיַפֵּק יָת תּוֹרָא לְמִבָּרָא לְמַשְׁרִיתָא וְאוֹקִיד יָתֵהּ כְּמָא דִי אוֹקִיד יָת תּוֹרָא קַדְמָאָה חַטַאת קְהָלָא הוּא:
@72 אִם רַבָּא יֵחוֹב וְיַעְבֵּד חַד מִכָּל פִּקוּדַיָא דַיְיָ אֱלָהֵיהּ דְלָא כַשְׁרִין לְאִתְעֲבָדָא בְּשָׁלוּ וְיֵחוֹב:
@73 אוֹ אִתְיְדַע לֵהּ חוֹבְתֵהּ דִי חַב בַּהּ וְיַיְתִי יָת קֻרְבָּנֵהּ צְפִיר בַּר עִזִין דְכַר שְׁלִים:
@74 וְיִסְמוֹךְ יְדֵהּ עַל רֵישָׁא דִצְפִירָא וְיִכּוֹס יָתֵהּ בַּאֲתַר דְיִכּוֹס יָת עֲלָתָא לָקֳדָם יְיָ חַטָאתָא הוּא:
@75 וְיִסַב כַּהֲנָא מִדְמָא דְחַטָּאתָא בְּאֶצְבְּעֵהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת דְמֵהּ יֵשׁוֹד לִיסוֹדָא לְמַדְבְּחָא דַעֲלָתָא:
@76 וְיָת כָּל תַּרְבֵּה יַסֵק לְמַדְבְּחָא כִּתְרַב נִכְסַת קוּדְשַׁיָּא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵהּ וְיִשְׁתְּבֵק לֵהּ:
@77 וְאִם אֱנַשׁ חַד יֵחוֹב בְּשָׁלוּ מֵעַמָא דְאַרְעָא בְּמֶעְבְּדַהּ חַד מִפִּקוּדַיָא דַיְיָ דְלָא כַשְׁרִין לְאִתְעְבָדָא וְיֵחוֹב:
@78 אוֹ אִתְיְדַע לֵהּ חוֹבְתֵהּ דִי חָב וְיַיְתִי קֻרְבָּנֵהּ צְפִירַת עִזִין שְׁלֶמְתָּא נְקוּבְתָא עַל חוֹבְתֵהּ דִי חָב:
@79 וְיִסְמוֹךְ יָת יְדֵהּ עַל רֵישׁ חַטָאתָא וְיִכּוֹס יָת חַטָאתָא בַּאֲתַר דַעֲלָתָא:
@80 וְיִסַב כַּהֲנָא מִדְמַהּ בְּאֶצְבְּעֵהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְמַהּ יֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא:
@81 וְיָת כָּל תַּרְבַּהּ יֶעְדֵי כְּמָא דִי מִתַּעְדָא תְרַב מֵעַל נִכְסַת קוּדְשַׁיָא וְיַסֵק כַּהֲנָא לְמַדְבְּחָא לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִשְׁתְּבֵק לֵהּ:
@82 וְאִם אִימַר יַיְתִי קֻרְבָּנֵהּ לְחַטָאתָא נֻקְבָא שְׁלֶמְתָּא יַיְתִנַהּ:
@83 וְיִסְמוֹךְ יַת יְדֵהּ עַל רֵישׁ חַטָאתָא וְיִכּוֹס יָתַהּ לְחַטָאתָא בְּאַתְרָא דִי יִכּוֹס יַת עֲלָתָא:
@84 וְיִסַב כַּהֲנָא מִדְמָא דְחַטָאתָא בְּאֶצְבְּעֵהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְמַהּ יֵשׁוֹד לִיסוֹדָא דְ מַ דְבְּחָא:
@85 וְיָת כָּל תַּרְבַּהּ יֶעְדֵי כְּמָא דִי מִתַּעְדָא תְרַב אִמְרָא מִנִכְסַת קוּדְשַׁיָא וְיַסֵק כַּהֲנָא יַתְהוֹן לְמַדְבְּחָא עַל קֻרְבָּנַיָא דַיְיָ וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל חוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ:
@86 וֶאֵנַשׁ אֲרֵי יֵחוֹב וְיִשְׁמַע קַל מוֹמֵי וְהוּא סָהִיד אוֹ חֲזָא אוֹ יְדָע אִם לָא יְחַוִי וִיקַבֵּל חוֹבֵהּ:
@87 אוֹ אֱנַשׁ דִי יִקְרַב בְּכָל מִדַעַם מְסָאָב אוֹ בְּנִבְלַת חַיְתָא מְסָאָבָא אוֹ בְּנִבְלַת בְּעִירָא מְסָאָבָא אוֹ בְּנִבְלַת רִחֲשָׁא מְסָאָב וִיהֵי מְכַסָא מִנֵהּ וְהוּא מְסָאָב וְחָב:
@88 אוֹ אֲרֵי יִקְרַב בְּסוֹאֲבַת אֱנָשָׁא לְכָל סוֹבְתֵהּ דִי יִסְתָּאַב בַּהּ וִיהֵי מְכַסָא מִנֵהּ וְהוּא יְדַע וְחָב:
@89 אוֹ אֱנַשׁ אֲרֵי יְקַיֵם לְפָרָשָׁא בְסִפְוָן לְאַבְאָשָׁא אוֹ לְאוֹטָבָא לְכֹל דִי יְפָרֵשׁ אֱנָשָׁא בְּקִיוּם וִיהֵי מְכַסָא מִנֵהּ וְהוּא יָדַע וְחָב לַחֲדָא מֵאִלֵין:
@90 וִיהֵי אֲרֵי יֵחוֹב לַחֲדָא מֵאִלֵין וִיוַדִי דִי חָב עֲלַהּ:
@91 וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ עַל חוֹבְתֵהּ דִי חָב נְקוּבְתָא מִן עָנָא אִמְרָתָא אוֹ צְפִירַת עִזִין לְחַטָאתָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא מֵחוֹבְתֵהּ:
@92 וְאִם לָא תִמְטֵי יְדֵהּ כְּמִסַת שֵׂיתָא וְיַיְתִי יָת חוֹבְתֵהּ דִי חָב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה קֳדָם יְיָ חַד לְחַטָאתָא וְחַד לַעֲלָתָא:
@93 וְיַיְתִי יָתְהוֹן לְוָת כַּהֲנָא וִיקָרֵב יָת דִי לְחַטָאתָא קַדְמֵיתָא וְיִמְלוֹק יָת רֵישֵׁהּ מִלְקָבֵל קְדָלֵהּ וְלָא יַפְרֵשׁ:
@94 וְיַדִי מִדְמָא דְחַטָּאתָא עַל כֹּתֶל מַדְבְּחָא וּדְאִשְׁתָּאַר בִּדְמָא יִתִּמְצֵי לִיסוֹדָא דְמַדְבְּחָא חַטָאתָא הוּא:
@95 וְיָת תִּנְיָנָא יַעְבֵּד עֲלָתָא כִּדְחָזֵי וִיכַפֵּר עֲלוֹהִי כַהֲנָא מֵחוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ:
@96 וְאִם לָא תַדְבֵּק יְדֵהּ לְתַרְתֵּין שַׁפְנִינִין אוֹ לִתְרֵין בְּנֵי יוֹנָה וְיַיְתִי יָת קֻרְבָּנֵהּ דִי חָב חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא לְחַטָּאתָא לָא יְשַׁוִי עֲלַהּ מִשְׁחָא וְלָא יִתֵּן עֲלַהּ לְבֻנְתָּא אֲרֵי חַטָאתָא הִיא:
@97 וְיַיְתִנַהּ לְוַת כַּהֲנָא וְיִקְמוֹץ כַּהֲנָא מִנַהּ מְלֵי קֻמְצֵהּ יָת אִדְכַּרְתַּהּ וְיַסֵק לְמַדְבְּחָא עַל קֻרְבָּנַיָא דַיְיָ חַטָאתָא הִיא:
@98 וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל חוֹבְתֵהּ דִי חָב מֵחֲדָא מֵאִלֵין וְיִשְׁתְּבֵק לֵהּ וּתְהֵי לְכַהֲנָא כְּמִנְחָתָא:
@99 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@100 אֱנַשׁ אֲרֵי יְשַׁקַר שְׁקַר וְיֵחוֹב בְּשָׁלוּ מִקוּדְשַׁיָא דַיְיָ וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵהּ כְּסַף סִלְעִין בְּסִלְעֵי קוּדְשָׁא לַאֲשָׁמָא:
@101 וְיָת דִי חָב מִן קוּדְשָׁא יְשַׁלֵם וְיָת חֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי וְיִתֵּן יָתֵהּ לְכַהֲנָא וְכַהֲנָא יְכַפֵּר עֲלוֹהִי בְּדִכְרָא דַאֲשָׁמָא וְיִשְׁתְּבֵק לֵהּ:
@102 וְאִם אֱנַשׁ אֲרֵי יֵחוֹב וְיַעְבֵּד חֲדָא מִכָּל פִּקוּדַיָא דַיְיָ דִי לָא כָשְׁרִין לְאִתְעֲבָדָא וְלָא יָדַע וְיֵחוֹב וִיקַבֵּל חוֹבֵהּ:
@103 וְיַיְתִי דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵהּ לַאֲשָׁמָא לְוָת כַּהֲנָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל שָׁלוּתֵהּ דְאִשְׁתְּלִי וְהוּא לָא יָדַע וְיִשְׁתְּבֵק לֵהּ:
@104 אֲשָׁמָא הוּא עַל חוֹבְתֵהּ דְהוּא חָב אֲשָׁמָא יְקָרֵב קֳדָם יְיָ:
@105 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@106 אֱנַשׁ אֲרֵי יֵחוֹב וִישַׁקַר שְׁקַר קֳדָם יְיָ וִיכַדֵב בְּחַבְרֵהּ בְּפִקְדוֹנָא אוֹ בְשֻׁתָּפוּת יְדָא אוֹ בִגְזֵלָא אוֹ אַנִיס יָת חַבְרֵהּ:
@107 אוֹ אַשְׁכַּח אֲבֶדְתָּא וִיכַדֵב בַּהּ וְאִשְׁתְּבַע עַל שִׁקְרָא עַל חֲדָא מִכֹּל דִי יַעְבֵּד אֱנָשָׁא לְמֵיחַב בְּהֵן:
@108 וִיהֵי אֲרֵי יֶחְטֵי וְיֵחוֹב וְיָתֵב יָת גְזֵלָא דִי גְזַל אוֹ יָת עֻשְׁקָא דִי עֲשַׁק אוֹ יָת פִּקְדוֹנָא דִי אִתְפָּקַד לְוָתֵהּ אוֹ יָת אֲבֶדְתָּא דִי אַשְׁכַּח:
@109 אוֹ מִכֹּל דִי יִשְׁתְּבַע עֲלוֹהִי לְשִׁקְרָא וִישַׁלֵם יָתֵהּ בְּרֵישֵׁיהּ וְחֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי לְדִי הוּא דִילֵהּ יִתְּנִנֵהּ בְּיוֹמָא דְחוֹבְתֵהּ:
@110 וְיָת אַשָׁמֵיהּ יַיְתִי לָקֳדָם יְיָ דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵהּ לַאֲשָׁמָא לְוָת כַּהֲנָא:
@111 וִיכַפֵּר עֲלוֹהִי כַהֲנָא קֳדָם יְיָ וְיִשְׁתְּבֵק לֵהּ עַל חֲדָא מִכֹּל דִי יַעְבֵּד לְמֵיחַב בַהּ: פפפ:
@143 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@144 פַּקֵד יָת אַהֲרֹן וְיָת בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דַעֲלָתָא הִיא עֲלָתָא דְמִתּוֹקְדָא עַל מַדְבְּחָא כָל לֵילְיָא עַד צַפְרָא וְאֶשָׁתָא דְמַדְבְּחָא תְּהֵא יָקְדָא בֵהּ:
@145 וְיַלְבֵּשׁ כַּהֲנָא לְבוּשִׁין דְבוּץ וּמִכְנְסִין דְבוּץ יַלְבֵּשׁ עַל בִּסְרֵהּ וְיַפְרֵשׁ יָת קִטְמָא דִי תֵיכוּל אֶשָׁתָא יָת עֲלָתָא עַל מַדְבְּחָא וִישַׁוִנֵהּ בִּסְטַּר מַדְבְּחָא:
@146 וְיַשְׁלַח יָת לְבוּשׁוֹהִי וְיִלְבַּשׁ לְבוּשִׁין אָחֳרָנִין וְיַפֵּק יָת קִטְמָא לְמִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְכֵי:
@147 וְאֶשָׁתָא עַל מַדְבְּחָא תְהֵי יָקְדָא בֵהּ לָא תִטְּפֵי וְיַבְעַר עֲלַהּ כַּהֲנָא אָעַיָא בִּצְפַר בִּצְפָר וְיַסְדַר עֲלַהּ עֲלָתָא וְיַסֵק עֲלַהּ תַּרְבֵּי נִכְסַת קוּדְשַׁיָא:
@148 אֶשָׁתָא תְּדִירָא תְּהֵי יָקְדָא עַל מַדְבְּחָא לָא תִטְפֵי:
@149 וְדָא אוֹרַיְתָא דְמִנְחָתָא דִיקָרְבוּן יָתַהּ בְּנֵי אַהֲרֹן קֳדָם יְיָ לָקֳדָם מַדְבְּחָא:
@150 וְיַפְרֵשׁ מִנֵהּ בְּקֻמְצֵהּ מִסֻלְתָּא דְמִנְחָתָא וּמִמִשְׁחַהּ וְיָת כָּל לְבוּנְתָּא דִי עַל מִנְחָתָא וְיַסֵק לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא אַדְכַּרְתָּא קֳדָם יְיָ:
@151 וּדְאִשְׁתָּאַר מִנַהּ יֵכְלוּן אַהֲרֹן וּבְנוֹהִי פַּטִיר תִּתְאַכֵל בַּאֲתַר קַדִּישׁ בְּדָרַת מַשְׁכַּן זִמְנָא יֵכְלֻנַהּ:
@152 לָא תִתְאֲפֵי חֲמִיעַ חָלָקְהוֹן יְהָבִית יָתַהּ מִקֻרְבָּנָי קֹדֶשׁ קוּדְשִׁין הִיא כְּחַטָאתָא וְכַאֲשָׁמָא:
@153 כָּל דְכוּרָא בִּבְנֵי אַהֲרֹן יֵכְלֻנַהּ קְיָם עָלָם לְדָרָתֵיכוֹן מִקֻרָבָּנַיָא דַיְיָ כֹּל דְיִקְרַב בְּהוֹן יִתְקַדָּשׁ:
@154 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@155 דֵין קֻרְבַּן אַהֲרֹן וּבְנוֹהִי דִי יְקָרְבוּן קֳדָם יְיָ בְּיוֹמָא דְרַבִּיאוּ יָתֵהּ חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא מִנְחָתָא תְּדִירָא פַּלְגוּתַהּ בְּצַפְרָא וּפַלְגוּתַהּ בְּרַמְשָׁא:
@156 עַל מַסְרֵיתָא בִּמְשַׁח תִּתְעֲבֵד רְבִיכָא תַיְתִנַהּ תּוּפִינֵי מִנְחַת בִּצוּעִין תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@157 וְכַהֲנָא דִמְרַבָּא תְחוֹתוֹהִי מִבְּנוֹהִי יַעְבֵּד יָתַהּ קְיָם עָלָם קֳדָם יְיָ גְמִיר תִּתַּסָק:
@158 וְכָל מִנְחָתָא דְכַהֲנָא גְמִיר תְּהֵי לָא תִתְאֲכֵל:
@159 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@160 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דְחַטָאתָא בַּאֲתַר דִי תִתְנְכֵס עֲלָתָא תִּתְנְכֵס חַטָאתָא קֳדָם יְיָ קֹדֶשׁ קוּדְשִׁין הִיא:
@161 כַּהֲנָא דִמְכַפֵּר בִּדְמַהּ יֵיכְלִנַהּ בַּאֲתַר קַדִישׁ תִּתְאֲכֵל בְּדָרַת מַשְׁכַּן זִמְנָא:
@162 כֹּל דִי יִקְרַב בְּבִסְרַהּ יִתְקַדַשׁ וְדִי יַדִי מִדְמַהּ עַל לְבוּשׁ דִי יַדִי עֲלַהּ תִּתְחַוָר בַּאֲתַר קַדִישׁ:
@163 וּמָן דַחֲסַף דִי תִתְבַּשֵׁל בֵּהּ יִתָּבָר וְאִם בְּמָנָא דִנְחָשָׁא תִּתְבַּשֵׁל וְיִתְמְרֵק וְיִשְׁתַּטֵף בְּמַיָא:
@164 כָּל דְכוּרָא בְּכַהֲנַיָא יֵכוּל יָתַהּ קֹדֶשׁ קוּדְשִׁין הִיא:
@165 וְכָל חַטָאתָא דִי יִתָּעַלּ מִדְמַהּ לְמַשְׁכַּן זִמְנָא לְכַפָּרָא בְקוּדְשָׁא לָא תִתְאֲכֵל בְּנוּרָא תִּתּוֹקָד:
@166 וְדָא אוֹרַיְתָא דַאֲשָׁמָא קֹדֶשׁ קוּדְשִׁין הוּא:
@167 בְּאַתְרָא דִי יִכְּסוּן יָת עֲלָתָא יִכְּסוּן יָת אֲשָׁמָא וְיָת דְמֵהּ יִזְרַק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@168 וְיָת כָּל תַּרְבֵּהּ יַפְרֵשׁ מִנֵהּ יָת אֲלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא:
@169 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חִצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@170 וְיַסֵיק יָתְהוֹן כַּהֲנָא לְמַדְבְּחָא קוּרְבָּנָא קֳדָם יְיָ אֲשָׁמָא הוּא:
@171 כָּל דְכוּרָא בְּכַהֲנַיָא יֵיכְלִנֵהּ בַּאֲתַר קַדִישׁ יִתְאֲכָל קוֹדֶשׁ קוּדְשִׁין הוּא:
@172 כְּחַטָאתָא כַּאֲשָׁמָא אוֹרַיְתָא חֲדָא לְהוֹן כַּהֲנָא דִי יְכַפֵּר בֵּהּ דִילֵהּ יְהֵי:
@173 וְכַהֲנָא דִמְקָרֵב יַת עֲלַת גְבַר מְשַׁךְ עֲלָתָא דִי יְקָרֵב לְכַהֲנָא דִילֵהּ יְהֵי:
@174 וְכָל מִנְחָתָא דִי תִתְאֲפֵי בְּתַנוּרָא וְכָל דְתִתְעֲבֵד בְּרִדְתָּא וְעַל מַסְרֵיתָא לְכַהֲנָא דִמְקָרֵב יָתַהּ דִילֵהּ תְּהֵי:
@175 וְכָל מִנְחָתָא דְפִילָא בִמְשַׁח וּדְלָא פִילָא לְכָל בְּנֵי אַהֲרֹן תְּהֵי גְבַר כַּאָחוֹהִי:
@176 וְדָא אוֹרַיְתָא דְנִכְסַת קוּדְשַׁיָא דִי יְקָרֵב קֳדָם יְיָ:
@177 אִם עַל תּוֹדְתָא יְקָרְבִנֵהּ וִיקָרֵב עַל נִכְסַת תּוֹדְתָא גְרִיצָן פַּטִירָן דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִירִין דִּמְשִׁיחִין בִּמְשָׁח וְסוּלְתָּא רְבִיכָא גְרִיצָן דְפִילָן בִּמְשָׁח:
@178 עַל גְּרִיצָן דִלְחֵם חָמִיעַ יְקָרֵב קוּרְבָּנֵיהּ עַל נִכְסַת תּוֹדַת קוּדְשׁוֹהִי:
@179 וִיקָרֵב מִנֵהּ חַד מִכָּל קוּרְבַּן אַפְרָשׁוּתָא קֳדָם יְיָ לְכַהֲנָא דְיִזְרַק יָת דַם נִכְסַת קוּדְשַׁיָא דִילֵהּ יְהֵי:
@180 וּבְשַׂר נִכְסַת תּוֹדַת קוּדְשׁוֹהִי בְּיוֹם קֻרְבָּנֵהּ יִתְאֲכֵל לָא יַצְנַע מִנֵהּ עַד צַפְרָא:
@181 וְאִם נִדְרָא אוֹ נְדַבְתָּא נִכְסַת קֻרְבָּנֵהּ בְּיוֹמָא דִי יְקָרֵב יָת נִכְסְתֵיהּ יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר מִנֵהּ יִתְאֲכֵלּ:
@182 וּדְאִשְׁתָּאַר מִבְּסַר נִכְסָתָא בְּיוֹמָא תְּלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@183 וְאִם אִתְאֲכָלָא יִתְאֲכֵל מִבְּסַר נִכְסַת קוּדְשׁוֹהִי בְּיוֹמָא תְּלִיתָאָה לָא יְהֵי לְרַעֲוָא דִמְקָרֵב יָתֵהּ לָא יִתְחַשֵׁב לֵהּ מְרָחָק יְהֵי וֶאֱנַשׁ דְתֵכוּל מִנֵהּ חוֹבֵהּ יְקַבֵּל:
@184 וּבְסַר קוּדְשָׁא דִי יִקְרַב בְּכָל מְסָאָב לָא יִתְאֲכֵל בְּנוּרָא יִתּוֹקָד וּבְסַר קוּדְשָׁא כָּל דִי דְכֵי לְקוּדְשָׁא יֵיכוּל בְּסַר קוּדְשָׁא:
@185 וֶאֱנַשׁ דִי תֵכוּל בִּסְרָא מִנִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְסוֹבְתֵהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@186 וֶאֱנַשׁ אֲרֵי תִקְרַב בְּכָל מְסָאָב בְסוֹאֲבַת אֱנָשָׁא אוֹ בִּבְעִירָא מְסָאֲבָא אוֹ בְּכָל שִׁקְצָא מְסָאָב וְיֵיכוּל מִבְּסַר נִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@187 וּמַלֵיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@188 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר כָּל תְּרַב תּוֹר וְאִמַר וְעִזָא לָא תֵיכְלוּן:
@189 וּתְרַב נְבִילָא וּתְרַב תְּבִירָא יִתְעֲבֵד לְכָל עִבִדְתָּא וּמֵיכַל לָא תֵיכְלוּנֵהּ:
@190 אֲרֵי כָל דְיֵכוּל תַּרְבָּא מִן בְּעִירָא דִי יִקָרְבוּן מִנַהּ קוּרְבָּנָא קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא דִי תֵיכוּל מֵעַמַּהּ:
@191 וְכָל דְמָא לָא תֵיכְלוּן בְּכֹל מוֹתְבָנֵיכוֹן דְעוֹפָא וְדִבְעִירָא:
@192 כָּל אֱנָשָׁא דִי תֵיכוּל כָּל דְמָא וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַהּ:
@193 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@194 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דִמְקָרֵב יָת נִכְסַת קוּדְשׁוֹהִי קֳדָם יְיָ יַיְתִי יָת קֻרְבָּנֵהּ לָקֳדָם יְיָ מִנִכְסַת קוּדְשׁוֹהִי:
@195 יְדוֹהִי תַיְתוּן יָת קֻרְבָּנַיָא דַיְיָ יָת תַּרְבָּא עַל חַדְיָא יַיְתִנֵהּ יָת חֶדְיָא לַאֲרָמָא יָתֵהּ אֲרוּמָא קֳדָם יְיָ:
@196 וְיַסֵק כַּהֲנָא יָת תַּרְבָּא לְמַדְבְּחָא וִיהֵי חֶדְיָא לְאַהֲרֹן וְלִבְנוֹהִי:
@197 וְיָת שׁוֹקָא דְיַמִינָא תִּתְּנוּן אַפְרָשׁוּתָא לְכַהֲנָא מִנִכְסַת קוּדְשֵׁיכוֹן:
@198 דִמְקָרֵב יָת דָם נִכְסַת קוּדְשַׁיָא וְיָת תַּרְבָּא מִבְּנֵי אַהֲרֹן דִילֵהּ תְּהֵי שׁוֹקָא דְיַמִינָא לָחֳלָק:
@199 אֲרֵי יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא נְסֵבִית מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן וִיהָבִית יָתְהוֹן לְאַהֲרֹן כַּהֲנָא וְלִבְנוֹהִי לִקְיָם עָלָם מִן בְּנֵי יִשְׂרָאֵל:
@200 דָא רְבוּת אַהֲרֹן וּרְבוּת בְּנוֹהִי מִקוּרְבָּנַיָא דַיְיָ בְּיוֹמָא דְקָרֵב יָתְהוֹן לְשַׁמָשָׁא קֳדָם יְיָ:
@201 דִי פַקִיד יְיָ לְמִתַּן לְהוֹן בְּיוֹמָא דְרַבִּי יָתְהוֹן מִן בְּנֵי יִשְׂרָאֵל קְיָם עָלָם לְדָרֵיהוֹן:
@202 דָא אוֹרַיְתָא לַעֲלָתָא לְמִנְחָתָא וּלְחַטָּאתָא וְלַאֲשָׁמָא וּלְקוּרְבָּנַיָא וּלְנִכְסַת קוּדְשַׁיָא:
@203 דִי פַקִיד יְיָ יָת מֹשֶׁה בְּטוּרָא דְסִינָי בְּיוֹמָא דְפַקְדֵהּ יָת בְּנֵי יִשְׂרָאֵל לְקָרָבָא יָת קֻרְבָּנְהוֹן קֳדָם יְיָ בְּמַדְבְּרָא דְסִינָי:
@204 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@205 קָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי עִמֵהּ וְיָת לְבוּשַׁיָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת תּוֹרָא דְחַטָאתָא וְיָת תְּרֵין דִכְרִין וְיָת סַלָא דְפַטִירַיָא:
@206 וְיָת כָּל כְּנִשְׁתָּא כְּנֵשׁ לִתְרַע מַשְׁכַּן זִמְנָא:
@207 וַעֲבַד מֹשֶׁה כְּמָא דִי פַקִיד יְיָ יָתֵהּ וְאִתְכְּנִשַׁת כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@208 וַאֲמַר מֹשֶׁה לִכְנִשְׁתָּא דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֶעְבָּד:
@209 וְקָרִיב מֹשֶׁה יָת אַהֲרֹן וְיָת בְּנוֹהִי וְאַסְחֵי יָתְהוֹן בְּמַיָא:
@210 וִיהַב עֲלוֹהִי יָת כִּתּוּנָא וְזָרֵז יָתֵהּ בְּהֶמְיָנָא וְאַלְבֵּשׁ יָתֵהּ יָת מְעִילָא וִיהַב עֲלוֹהִי יָת אֵפוֹדָא וְזָרֵז יָתֵהּ בְּהֶמְיַן אֵפוֹדָא וְאַתְקֵן לֵהּ בֵּהּ:
@211 וְשַׁוִי עֲלוֹהִי יָת חוּשְׁנָא וִיהַב בְּחוּשְׁנָא יָת אוּרַיָא וְיָת תֻּמַיָא:
@212 וְשַׁוִי יָת מִצְנַפְתָּא עַל רֵישֵׁיהּ וְשַׁוִי עַל מִצְנֶפְתָּא לָקֳבֵיל אַפּוֹהִי יָת צִיצָא דְדַהֲבָא כְּלִילָא דְקוּדְשָׁא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@213 וּנְסִיב מֹשֶׁה יָתּ מִשְׁחָא דִרְבוּתָא וְרַבִּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וְקַדִישׁ יָתְהוֹן:
@214 וְאַדִי מִנֵהּ עַל מַדְבְּחָא שְׁבַע זִמְנִין וְרַבִּי יָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְיָת כִּיוֹרָא וְיָת בְּסִיסֵהּ לְקַדָשׁוּתְהוֹן:
@215 וַאֲרֵיק מִמִשְׁחָא דִרְבוּתָא עַל רֵישָׁא דְאַהֲרֹן וְרַבִּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@216 וְקָרִיב מֹשֶׁה יָת בְּנֵי אַהֲרֹן וְאַלְבֵּשִׁנוּן כִּתּוּנִין וְזָרֵז יָתְהוֹן הֶמְיָנִין וְאַתְקֵן לְהוֹן כּוֹבָעִין כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@217 וְקָרֵב יָת תּוֹרָא דְחַטָאתָא וּסְמַךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא דְחַטָאתָא:
@218 וּנְכֵס וּנְסִיב מֹשֶׁה יָת דְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר בְּאֶצְבְּעֵהּ וְדַכִּי יָת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא וְקַדְשֵׁהּ לְכַפָּרָא עֲלוֹהִי:
@219 וּנְסִיב יָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְאַסֵק מֹשֶׁה לְמַדְבְּחָא:
@220 וְיָת תּוֹרָא וְיָת מַשְׁכֵהּ וְיָת בִּסְרֵהּ וְיָת אָכְלֵהּ אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@221 וְקָרִיב יָת דִכְרָא דַעֲלָתָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@222 וּנְכֵס וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@223 וְיָת דִכְרָא פַּלֵג לְאֶבְרוֹהִי וְאַסֵק מֹשֶׁה יָת רֵישָׁא וְיָת אֶבְרַיָא וְיָת תַּרְבָּא:
@224 וְיָת גַוָא וְיָת כְּרָעַיָא חַלִיל בְּמַיָא וְאַסֵק מֹשֶׁה יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא לְאִתְקַבָּלָא בְרַעִוָא קוּרְבָּנָא הוּא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@225 וְקָרִיב יָת דִכְרָא תִנְיָנָא דְכַר קוּרְבָּנַיָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@226 וּנְכֵס וּנְסִיב מֹשֶׁה מִן דְמָא וִיהַב עַל רוּם אוּדְנָא דְאַהֲרֹן דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@227 וְקָרֵיב יָת בְּנֵי אַהֲרֹן וִיהַב מֹשֶׁה מִן דְמָא עַל רוּם אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@228 וּנְסִיב יָת תַּרְבָּא וְיָת אֲלִיתָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְיָת שׁוֹקָא דְיַמִינָא:
@229 וּמִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ נְסִיב גְרִצְתָּא פַטִירָא חֲדָא וּגְרִיצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד וְשַׁוִי עַל תַּרְבַּיָא וְעַל שׁוֹקָא דְיַמִינָא:
@230 וִיהַב יָת כֹּלָא עַל יְדֵי אַהֲרֹן וְעַל יְדֵי בְנוֹהִי וַאֲרֵים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@231 וּנְסִיב מֹשֶׁה יָתְהוֹן מֵעַל יְדֵיהוֹן וְאַסֵק לְמַדְבְּחָא עַל עֲלָתָא קוּרְבָּנַיָא אִנוּן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא הוּא קֳדָם יְיָ:
@232 וּנְסִיב מֹשֶׁה יָת חֶדְיָא וַאֲרִימֵהּ אֲרָמָא קֳדָם יְיָ מִדְכַר קוּרְבָּנַיָא לְמֹשֶׁה הֲוָה לָחֳלָק כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@233 וּנְסִיב מֹשֶׁה מִמִשְׁחָא דִרְבוּתָא וּמִן דְמָא דִי עַל מַדְבְּחָא וְאַדִי עַל אַהֲרֹן עַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְקַדִישׁ יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְיָת בְּנוֹהִי וְיָת לְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@234 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי בַּשִׁילוּ יָת בִּסְרָא בִּתְרַע מַשְׁכַּן זִמְנָא וְתַמָן תֵּיכְלוּן יָתֵהּ וְיָת לַחְמָא דִי בְּסַל קוּרְבָּנַיָא כְּמָא דִי פַקֵדִית לְמֵימָר אַהֲרֹן וּבְנוֹהִי יֵיכְלוּנֵהּ:
@235 וּדְאִשְׁתָּאַר בְּבִשְׂרָא וּבְלַחְמָא בְּנוּרָא תּוֹקְדוּן:
@236 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן שִׁבְעָא יוֹמִין עַד יוֹם מִשְׁלַם יוֹמֵי קוּרְבָּנֵיכוֹן אֲרֵי שִׁבְעָא יוֹמִין יְקָרֵב יָת קֻרְבָּנֵיכוֹן:
@237 כְּמָא דִי עֲבַד בְּיוֹמָא הָדֵין פָּקִיד יְיָ לְמֶעְבַּד לְכַפָּרָא עֲלֵיכוֹן:
@238 וּבִתְרַע מַשְׁכַּן זִמְנָא תֵּיתְבוּן יְמָם וְלֵילֵי שִׁבְעָא יוֹמִין וְתִטְרוּן יָת מַטְרַת מֵימְרָא דַיְיָ וְלָא תְמוּתוּן אֲרֵי כֵן אִתְפַּקָדִית:
@239 וַעֲבַד אַהֲרֹן וּבְנוֹהִי יָת כָּל פִּתְגָמַיָא דִי פַקִיד יְיָ בִּידָא דְמֹשֶׁה: פפפ:
@259 וַהֲוָה בְּיוֹמָא תְמִינָאָה קְרָא מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי וּלְסָבֵי יִשְׂרָאֵל:
@260 וַאֲמַר לְאַהֲרֹן סַב לָךְ עֵגֶל בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא שַׁלְמִין וְקָרֵב קֳדָם יְיָ:
@261 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר סִבוּ צְפִיר בַּר עִזִין לְחַטָאתָא וְעֵגֶל וְאִמָר בְּנֵי שְׁנָא שַׁלְמִין לַעֲלָתָא:
@262 וְתוֹר וּדְכַר לְנִכְסַת קוּדְשַׁיָא לְדַבָּחָא קֳדָם יְיָ וּמִנְחָתָא דְפִילָא בִמְשָׁח אֲרֵי יוֹמָא דֵין יְקָרָא דַיְיָ מִתְגְלִי לְכוֹן:
@263 וּנְסִיבוּ יָת דִי פַקִיד מֹשֶׁה לָקֳדָם מַשְׁכַּן זִמְנָא וּקְרִיבוּ כָּל כְּנִישְׁתָּא וְקָמוּ קֳדָם יְיָ:
@264 וַאֲמַר מֹשֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ תַּעְבְּדוּן וְיִתְגְלִי לְכוֹן יְקָרָא דַיְיָ:
@265 וַאֲמַר מֹשֶׁה לְאַהֲרֹן קְרַב לְמַדְבְּחָא וְעִבֵד יָת חַטָאתָךְ וְיָת עֲלָתָךְ וְכַפֵּר עֲלָךְ וְעַל עַמָא וְעִבֵד יָת קֻרְבַּן עַמָא וְכַפֵּר עֲלֵיהוֹן כְּמָא דִי פַקִיד יְיָ:
@266 וּקְרַב אַהֲרֹן לְמַדְבְּחָא וּנְכֵס יָת עֶגְלָא דְחַטָאתָא דִי לֵהּ:
@267 וְקָרִיבוּ בְּנֵי אַהֲרֹן יָת דְמָא לֵהּ וּטְבַל אֶצְבְּעֵהּ בִּדְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא:
@268 וְיָת תַּרְבָּא וְיָת כָּלְיֵתָא וְיָת חִצְרָא מִן כַּבְדָא מִן חַטָאתָא אַסֵק לְמַדְבְּחָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@269 וְיָת בִּשְׂרָא וְיָת מַשְׁכָא אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא:
@270 וּנְכֵס יָת עֲלָתָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן לֵּהּ יָת דְמָא וּזְרָקֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@271 וְיָת עֲלָתָא אַמְטִיאוּ לֵהּ לְאֵבָרָהָא וְיָת רֵישָׁא וְאַסֵק עַל מַדְבְּחָא:
@272 וְחַלִיל יָת גַוָא וְיָת כְּרָעַיָא וְאַסֵק עַל עֲלָתָא לְמַדְבְּחָא:
@273 וְקָרֵב יָת קֻרְבַּן עַמָא וּנְסִב יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְנָכְסֵהּ וְכַפֵּר בִּדְמֵהּ כְּקַדְמָאָה:
@274 וְקָרֵב יָת עֲלָתָא וְעָבְדַהּ כִּדְחָזֵי:
@275 וְקָרִיב יָת מִנְחָתָא וּמְלָא יְדֵהּ מִנַהּ וְאַסֵק עַל מַדְבְּחָא בַּר מֵעֲלַת צַפְרָא:
@276 וּנְכֵס יָת תּוֹרָא וְיָת דִכְרָא נִכְסַת קוּדְשַׁיָא דִי לְעַמָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן יָת דְמָא לֵהּ וּזְרָקֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@277 וְיָת תַּרְבַּיָא מִן תּוֹרָא וּמִן דִכְרָא אֲלִיתָא וְחָפֵי גַוָא וְכָלְיֵתָא וַחֲצַר כַּבְדָא:
@278 וְשַׁוִיאוּ יָת תַּרְבַּיָא עַל חֶדְוָתָא וְאַסֵק תַּרְבַּיָא לְמַדְבְּחָא:
@279 וְיָת חֶדְוָתָא וְיָת שׁוֹקָא דְיַמִינָא אֲרֵים אַהֲרֹן אֲרָמָא קֳדָם יְיָ כְּמָא דִי פַקִיד מֹשֶׁה:
@280 וַאֲרֵם אַהֲרֹן יָת יְדוֹהִי עַל עַמָא וּבָרֵכִנוּן וּנְחַת מִלְמֶעְבַּד חַטָאתָא וַעֲלָתָא וְנִכְסַת קוּדְשַׁיָא:
@281 וְעַל מֹשֶׁה וְאַהֲרֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ וּבָרִיכוּ יָת עַמָא וְאִתְגְלִי יְקָרָא דַיְיָ לְכָל עַמָא:
@282 וּנְפָקַת אֶשָׁתָא מִן קֳדָם יְיָ וַאֲכָלַת עַל מַדְבְּחָא יָת עֲלָתָא וְיָת תַּרְבַּיָא וַחֲזָא כָּל עַמָא וְשַׁבָּחוּ וּנְפָלוּ עַל אַפֵּיהוֹן:
@283 וּנְסִיבוּ בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא גְבַר מַחְתִּיתֵהּ וִיהָבוּ בְהוֹן אֶשָׁתָא וְשַׁוִיאוּ עֲלַהּ קְטוֹרֶת וְקָרִיבוּ קֳדָם יְיָ אֶשָׁתָא נוּכְרֵיתָא דִי לָא פַקִיד יָתְהוֹן:
@284 וּנְפָקַת אֶשָׁתָא מִן קֳדָם יְיָ וַאֲכָלַת יָתְהוֹן וּמִיתוּ קֳדָם יְיָ:
@285 וַאֲמַר מֹשֶׁה לְאַהֲרֹן הוּא דִי מַלִיל יְיָ לְמֵימַר בְּקָרִיבַי אִתְקַדַשׁ וְעַל אַפֵּי כָל עַמָא אִתְיַקָר וּשְׁתִיק אַהֲרֹן:
@286 וּקְרָא מֹשֶׁה לְמִישָׁאֵל וּלְאֶלְצָפָן בְּנֵי עֻזִיאֵל אַח אֲבוּהִי דְאַהֲרֹן וַאֲמַר לְהוֹן קְרִיבוּ טוּלוּ יָת אֲחֵיכוֹן מִן קֳדָם אַפֵּי קוּדְשָׁא לְמִבָּרָא לְּמַשְׁרִיתָא:
@287 וּקְרִיבוּ וּנְטָלֻּנוּן בְּכִתֻּנֵיהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִיל מֹשֶׁה:
@288 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וּלְאֶלְעָזָר וּלְאִיתָמָר בְּנוֹהִי רֵישֵׁיכוֹן לָא תְרַבּוּן פֵּרוּעַ וּלְבוּשֵׁיכוֹן לָא תְבַזְעוּן וְלָא תְמוּתוּן וְעַל כָּל כְּנִשְׁתָּא יְהֵא רוּגְזָא וַאֲחֵיכוֹן כָּל בֵּית יִשְׂרָאֵל יִבְכּוּן יָת יְקִדְתָּא דִי אוֹקִיד יְיָ:
@289 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְקוּן דִלְמָא תְמוּתוּן אֲרֵי מְשַׁח רְבוּתָא דַיְיָ עֲלֵיכוֹן וַעֲבָדוּ כְּפִתְגָמָא דְמֹשֶׁה:
@290 וּמַלִיל יְיָ עִם אַהֲרֹן לְמֵימָר:
@291 חֲמַר וּמְרַוֵי לָא תִשְׁתֵּי אַתְּ וּבְנָיךְ עִמָךְ בְּמֵעַלְכוֹן לְמַשְׁכַּן זִמְנָא וְלָא תְמוּתוּן קְיַם עָלָם לְדָרֵיכוֹן:
@292 וּלְאַפְרָשָׁא בֵּין קוּדְשָׁא וּבֵין חֻלָא וּבֵין מְסָאֲבָא וּבֵין דַכְיָא:
@293 וּלְאַלָפָא יָת בְּנֵי יִשְׂרָאֵל יָת כָּל קְיָמַיָא דִי מַלִיל יְיָ לְהוֹן בִּידָא דְמֹשֶׁה:
@294 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם אֶלְעָזָר וְעִם אִיתָמָר בְּנוֹהִי דְאִשְׁתָּאֲרוּ סִבוּ יָת מִנְחָתָא דְאִשְׁתָּאָרָת מִקֻרְבָּנַיָא דַיְיָ וְאִכְלוּהָ פַטִיר בִּסְטַר מַדְבְּחָא אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא:
@295 וְתֵיכְלוּן יָתַהּ בַּאֲתַר קַדִישׁ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ הִיא מִקֻרְבָּנַיָא דַיְיָ אֲרֵי כֵן אִתְפַּקָדִית:
@296 וְיָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא תֵּיכְלוּן בַּאֲתַר דְכֵי אַתְּ וּבְנָיךְ וּבְנָתָיךְ עִמָךְ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ אִתְיְהִיבוּ מִנִכְסַת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל:
@297 שׁוֹקָא דְאַפְרָשׁוּתָא וְחֶדְיָא דַאֲרָמוּתָא עַל קֻרְבָּנֵי תַרְבַּיָא יַיְתוּן לַאֲרָמָא אֲרָמָא קֳדָם יְיָ וִיהֵי לָךְ וְלִבְנָיךְ עִמָךְ לִקְיַם עָלָם כְּמָא דִי פַקִיד יְיָ:
@298 וְיָת צְפִירָא דְחַטָאתָא מִתְבַּע תָּבְעֵי מֹשֶׁה וְהָא אִתּוֹקָד וּרְגֵז עַל אֶלְעָזָר וְעַל אִיתָמָר בְּנֵי אַהֲרֹן דְאִשְׁתָּאֲרוּ לְמֵימָר:
@299 מָדֵין לָא אֲכַלְתּוּן יָת חַטָאתָא בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא וְיָתַהּ יְהַב לְכוֹן לְסַלָחָא עַל חוֹבֵי כְנִשְׁתָּא לְכַפָּרָא עֲלֵיהוֹן קֳדָם יְיָ:
@300 הָא לָא אִתָּעַל יָת דְמַהּ לְבֵית קֻדְשָׁא גַוָאָה מֵיכַל תֵּכְלוּן יָתַהּ בְּקֻדְשָׁא כְּמָא דִי פַקֵדִית:
@301 וּמַלִיל אַהֲרֹן עִם מֹשֶׁה הָא יוֹמָא דֵין קְרִיבוּ יָת חַטָּאתְהוֹן וְיָת עֲלָתְהוֹן קֳדָם יְיָ וַעֲרָעָא יָתִי עָקָן כְּאִלֵין וְאִלוּפוֹן אֲכָלִית חַטָאתָא יוֹמָא דֵין הֲתַקֵן קֳדָם יְיָ:
@302 וּשְׁמַע מֹשֶׁה וּשְׁפַר בְּעֵינוֹהִי:
@303 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימַר לְהוֹן:
@304 מַלִילוּ עִם בְּנֵי יִשְׂרָאֵל לְמֵימַר דָא חַיְתָא דִי תֵיכְלוּן מִכָּל בְּעִירָא דִי עַל אַרְעָא:
@305 כֹּל דִי סְדִיקָן פַּרְסָתָא וּמַטִלְפָן טִלְפִין פַּרְסָתָא מַסְקָּא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@306 בְּרָם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַּרְסָתָא יָת גַמְלָא אֲרֵי מַסִיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@307 וְיָת טַפְזָא אֲרֵי מַסִיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@308 וְיָת אַרְנְבָא אֲרֵי מַסְקָא פִשְׁרָא הִיא וּפַרְסָתָא לָא סְדִיקָא מְסָאָבָא הִיא לְכוֹן:
@309 וְיָת חֲזִירָא אֲרֵי סְדִיק פַּרְסָתָא הוּא וּמַטִּלְפָן טִּלְפִין פַרְסָתֵהּ וְהוּא פִּשְׁרָא לָא פָשָׁר מְסָאָב הוּא לְכוֹן:
@310 מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבִלְתְּהוֹן לָא תִקְרְבוּן מְסָאֲבִין אִנוּן לְכוֹן:
@311 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין בְּמַיָא בְּיַמְמַיָא וּבְנַחֲלַיָא יַתְהוֹן תֵּיכְלוּן:
@312 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין בְּיַמְמַיָא וּבְנַחֲלַיָא מִכֹּל רִחֲשָׁא דְמַיָא וּמִכֹּל נַפְשָׁא חַיְתָא דִי בְמַיָא שִׁקְצָא אִנוּן לְכוֹן:
@313 וְשִׁקְצָא יְהוֹן לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וְיָת נְבִלְתְּהוֹן תְּשַׁקְצוּן:
@314 כֹּל דִי לֵית לֵהּ צִיצִין וְקַלְפִין בְּמַיָא שִׁקְצָא הוּא לְכוֹן:
@315 וְיָת אִלֵין תְּשַׁקְצוּן מִן עוֹפָא לָא יִתְאָכְלוּן שִׁקְצָא אִנוּן נִשְׁרָא וְעֲר וְעַזְיָא:
@316 וְדַיְתָא וְטָרָפִיתָא לִזְנַהּ:
@317 יָת כָּל עוּרְבָא לִזְנֵהּ:
@318 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָא וְנָצָא לִזְנוֹהִי:
@319 וְקַרְיָא וְשָׁלֵינוּנָא וְקִפּוֹפָא:
@320 וּבַוְתָא וְקָתָא וִירַקְרֵקָא:
@321 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַלֵפָא:
@322 כֹּל רִחֲשָׁא דְעוֹפָא דִמְהַלֵךְ עַל אַרְבַּע שִׁקְצָא הוּא לְכוֹן:
@323 בְּרַם יָת דֵין תֵּיכְלוּן מִכֹּל רִחֲשָׁא דְעוֹפָא דִמְהַלֵךְ עַל אַרְבַּע דִי לֵהּ קַרְצוּלִין מֵעִלַוֵי רַגְלוֹהִי לְקַפָּצָא בְהוֹן עַל אַרְעָא:
@324 יָת אִלֵין מִנְהוֹן תֵּיכְלוּן יָת גוֹבָא לִזְנֵהּ וְיָת רָשׁוּנָא לִזְנוֹהִי וְיָת חַרְגוֹלָא לִזְנוֹהִי וְיָת חַגָבָא לִזְנוֹהִי:
@325 וְכֹל רִחֲשָׁא דְעוֹפָא דִי לֵהּ אַרְבַּע רַגְלִין שִׁקְצָא הוּא לְכוֹן:
@326 וּלְאִלֵין תִּסְתָּאָבוּן כָּל דְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמשָׁא:
@327 וְכָל דְיִטוֹל:מִנְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@328 לְכָל בְּעִירָא דִי הִיא סְדִיקָא פַרְסָתָא וְטִלְפִין לֵיתָהָא מַטִלְפָא וּפִשְׁרָא לֵיתָהָא מַסְקָא מְסָאֲבִין אִנוּן לְכוֹן כָּל דְיִקְרַב בְּהוֹן יְהֵי מְסָאָב:
@329 וְכֹל דִמְהַלֵךְ עַל יְדוֹהִי בְּכָל חַיְתָא דִמְהַלְכָא עַל אַרְבַּע מְסַאֲבִין אִנוּן לְכוֹן כָּל דְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵא מְסָאָב עַד רַמְשָׁא:
@330 וּדְיִטוֹל יָת נְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא מְסַאֲבִין אִנוּן לְכוֹן:
@331 וְדֵין לְכוֹן מְסַאָבָא דְּרִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא חֻלְדָא וְעַכְבָּרָא וְצָבָא לִזְנוֹהִי:
@332 וְיָלָא וְכוֹחָא וְחֻלְטֵיתָא וְחֻמְטָא וְאָשׁוּתָא:
@333 אִלֵין דִמְסַאֲבִין לְכוֹן בְּכָל רִחֲשָׁא כֹּל דְיִקְרַב בְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:
@334 וְכָל דִי יִפֵּל עֲלוֹהִי מִנְהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב מִכָּל מָאן דְעָא אוֹ לְבוּשׁ אוֹ מְשַׁךְ אוֹ שָׂק כָּל מָאן דִי תִתְעֲבֵד עִבִידָא בְּהוֹן בְּמַיָא יִתָּעַל וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@335 וְכָל מָאן דַחֲסַף דִי יִפֵּל מִנְהוֹן לְגַוֵהּ כֹּל דִי בְגַוֵהּ יִסְתָּאַב וְיָתֵהּ תְּתַבְּרוּן:
@336 מִכָּל מֵיכְלָא דְמִתְאֲכֵל דִי יַעֲלוּן עֲלוֹהִי מַיָא יְהֵי מְסָאָב וְכָל מַשְׁקֵה דִי יִשְׁתֵּתֵי בְּכָל מָאן יְהֵי מְסָאָב:
@337 וְכֹל דִי יִפֹּל מִנְבִלְתְּהוֹן עֲלוֹהִי יְהֵי מְסָאָב תַּנוּר וְכִירַיִם יִתָּרְעוּן מְסַאֲבִין אִנוּן וּמְסַאֲבִין יְהוֹן לְכוֹן:
@338 בְּרַם מַעְיָן וְגוֹב בֵּית כְּנִישׁוּת מַיָא יְהֵי דְכֵי וּדְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב:
@339 וַאֲרֵי יִפֵּל מִנְבִלְתְּהוֹן עַל כָּל בַּר זְרַע זֵרוּעַ דִי יִזְדְרָע דְכֵי הוּא:
@340 וַאֲרֵי יִתְיַהֲבוּן מַיָא עַל בַּר זַרְעָא וְיִפֵּל מִנְבִלְתְּהוֹן עֲלוֹהִי מְסָאָב הוּא לְכוֹן:
@341 וַאֲרֵי יְמוּת מִן בְּעִירָא דִי הִיא לְכוֹן לְמֵיכָל דְיִקְרַב בִּנְבִלְתַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@342 וּדְיֵכוּל מִנְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטוֹל יָת נְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@343 וְכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא שִׁקְצָא הוּא לָא יִתְאָכֵל:
@344 כֹּל דִמְהַלֵךְ עַל מְעוֹהִי וְכֹל דִמְהַלֵךְ עַל אַרְבַּע עַד כָּל סְגִיאוּת רַגְלָאִין לְכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא לָא תֵיכְלֻנוּן אֲרֵי שִׁקְצָא אִנוּן:
@345 לָא תְשַׁקְצוּ יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְרָחֵשׁ וְלָא תִסְתַּאֲבוּן בְּהוֹן וְתִסְתַּאֲבוּן פּוֹן בְּהוֹן:
@346 אֲרֵי אֲנָא יְיָ אֶלָהָכוֹן וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא וְלָא תְסַאֲבוּן יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא:
@347 אֲרֵי אֲנָא יְיָ דְאַסֵק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ וּתְהוֹן קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא:
@348 דָא אוֹרַיְתָא דִבְעִירָא וּדְעוֹפָא וּדְכָל נַפְשָׁתָא חַיְתָא דִרְחֵשָׁא בְּמַיָא וּלְכָל נַפְשָׁא דִרְחֵשָׁא עַל אַרְעָא:
@349 לְאַפְרָשָׁא בֵּין מְסָאָבָא וּבֵין דַכְיָא וּבֵין חַיְתָא דְמִתְאַכְלָא וּבֵין חַיְתָא דִי לָא מִתְאַכְלָא: פפפ:
@390 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@391 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר אִתְּתָא אֲרֵי תְעַדִי וּתְלִיד דְכָר וּתְהֵי מְסָאָבָא שִׁבְעַת יוֹמִין כְּיוֹמֵי רִחוּק סוֹבְתַהּ תְּהֵי מְסָאָבָא:
@392 וּבְיוֹמָא תְּמִינָאָה יִגְזַר בִּסְרָא דְעָרְלְתֵהּ:
@393 וּתְלָתִין וּתְלָתָא יוֹמִין תֵּיתֵב בְּדַם דְכוּ בְּכָל קוּדְשָׁא לָא תִקְרַב וּלְמִקְדְשָׁא לָא תֵעוֹל עַד מִשְׁלַם יוֹמֵי דָכוּתַהּ:
@394 וְאִם נְקוּבְתָא תְלִיד וּתְהֵי מְסָאָבָא אַרְבְּעָה עֲסַר כְּרִחוּקַהּ וְשִׁתִּין וְשִׁתָּא יוֹמִין תֵּיתֵב עַל דַם דְכוּ:
@395 וּבְמִשְׁלַם יוֹמֵי דָכוּתַהּ לִבְרָא אוֹ לִבְרַתָּא תַּיְתִי אִמָר בַּר שַׁתֵּהּ לַעֲלָתָא וּבַר יוֹנָה אוֹ שַׁפְנִינָא לְחַטָאתָא לִתְרַע מַשְׁכַּן זִמְנָא לְוַת כַּהֲנָא:
@396 וִיקָרְבִנֵהּ קֳדָם יְיָ וִיכַפֵּר עֲלַהּ וְתִדְכֵּי מִסוֹאֲבַת דְמָהָא דָא אוֹרַיְתָא דְיַלֶדְתָּא לְדוּכְרָא אוֹ לִנְקֻבְתָא:
@397 וְאִם לָא תַשְׁכַּח יְדַהּ כְּמִסַת אִמְרָא וְתִסַב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה חַד לַעֲלָתָא וְחַד לְחַטָאתָא וִיכַפֵּר עֲלַהּ כַּהֲנָא וְתִדְכֵּי:
@398 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@399 אֱנַשׁ אֲרֵי יְהֵי בִמְשַׁךְ בִּסְרֵהּ עַמְקָא אוֹ עַדְיָא אוֹ בַהֲרָא וִיהֵי בִמְשַׁךְ בִּסְרֵהּ לְמַכְתַּשׁ סְגִירוּ וְיִתֵּתֵי לְוַת אַהֲרֹן כַּהֲנָא אוֹ לְוַת חַד מִבְּנוֹהִי כַּהֲנַיָא:
@400 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא בִמְשַׁךְ בִּסְרָא וְשֵׂעָר בְּמַכְתָּשָׁא אִתְהַפִיךְ לְמֶחֱוָר וּמֶחֱזֵי מַכְתָּשָׁא עַמִיק בִּמְשַׁךְ בִּסְרֵהּ מַכְתַּשׁ סְגִירוּתָא הוּא וְיֶחֱזִנֵהּ כַּהֲנָא וִיסָאֵב יָתֵהּ:
@401 וְאִם בַּהֲרָא חַוְרָא הִיא בִּמְשַׁךְ בִּסְרֵהּ וְעַמִיק לֵית מֶחֱזָהָא מִן מַשְׁכָא וּשְׂעָרָא לָא אִתְהֲפִיךְ לְמֶחֱוָר וְיַסְגַר כַּהֲנָא יָת מַכְתָּשָׁא שִׁבְעָא יוֹמִין:
@402 וְיֶחֱזִנֵהּ כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְהָא מַכְתָּשָׁא קָם כַּד הֲוָה לָא אוֹסֵף מַכְתָּשָׁא בְּמַשְׁכָּא וְיַסְגְרִנֵהּ כַּהֲנָא שִׁבְעָא יוֹמִין תִּנְיָנוּת:
@403 וְיֶחֱזֵי כַהֲנָא יָתֵהּ בְּיוֹמָא שְׁבִיעָאָה תִּנְיָנוּת וְהָא עַמְיָא מַכְתָּשָׁא וְלָא אוֹסֵף מַכְתָּשָׁא בְּמַשְׁכָּא וִידַכִּנֵהּ כַּהֲנָא עֲדִיתָא הִיא וִיצַבַּע לְבוּשׁוֹהִי וְיִדְכֵּי:
@404 וְאִם אוֹסָפָא תוֹסֵף עֲדִיתָא בְּמַשְׁכָּא בָּתַר דְאִתְּחֲזִי לְכַהֲנָא לְדַכּוּתֵהּ וְיִתַּחֲזִי תִנְיָנוּת לְכַהֲנָא:
@405 וְיֶחֱזֵי כַהֲנָא וְהָא אוֹסֵפַת עֲדִיתָא בְּמַשְׁכָּא וִיסָאֵבִנֵהּ כַּהֲנָא סגִירוּתָא הִיא:
@406 מַכְתַּשׁ סְגִירוּ אֲרֵי תְהֵי בֶּאֱנָשָׁא ויִתֵּתֵי לְוָת כַּהֲנָא:
@407 וְיֶחֱזֵי כֲהֲנָא וְהָא עַמְקָא חַוְרָא בְּמַשְׁכָּא וְהִיא הֲפָכַת שֵׂעָר לְחִוָר וְרֹשֶׁם בִּסְרָא חַיְתָא בְּעַמִקְתָּא:
@408 סְגִירוּת עַתִּיקָא הִיא בִּמְשַׁךְ בִּסְרֵהּ וִיסָאֵבִנֵהּ כַּהֲנָא לָא יַסְגְרִנֵהּ אֲרֵי:מסָאָב הוּא:
@409 וְאִם מִסְגָא תִסְגֵי סְגִירוּתָא בְּמַשְׁכָּא וְתַחְפֵי סְגִירוּתָא יָת כָּל מְשַׁךְ מַכְתָּשָׁא מֵרֵישֵׁהּ וְעַד רַגְלוֹהִי לְכָל חֵיזוּ עֵינֵי כַהֲנָא:
@410 וְיֶחֱזֵי כַהֲנָא וְהָא חֲפַת סְגִירוּתָא יָת כָּל בִּסְרֵהּ וִידַכִּי יָת מַכְתָּשָׁא כֻּלֵהּ אִתְהֲפִיךְ לְמֶחֱוַר דְכֵי הוּא:
@411 וּבְיוֹמָא דְאִתַּחֲזִי בֵהּ בִּסְרָא חַיָא יְהֵי מְסָאָב:
@412 וְיֶחֱזֵי כַהֲנָא יָת בִּסְרָא חַיָא וִיסָאֵבִנֵהּ בִּסְרָא חַיָא מְסָאָב הוּא סְגִירוּת הוּא:
@413 אוֹ אֲרֵי יְתוּב בִּסְרָא חַיָא וְיִתְהֲפִיךְ לְמֶחֱוָר וְיִתֵּתֵי לְוַת כַּהֲנָא:
@414 וְיֶחֱזִנֵהּ כַּהֲנָא וְהָא אִתְהֲפִיךְ מַכְתָּשָׁא לְמֶחֱוָר וִידַכֵּי כַהֲנָא יָת מַכְתָּשָׁא דְכֵי הוּא:
@415 וּבִסְרָא אֲרֵי יְהֵי בֵהּ בְּמַשְּׁכֵּהּ שִׁחֲנָא וְיִתַּסֵי:
@416 וִיהֵי בַאֲתַר שִׁחֲנָא עַמְקָא חַוְרָא אוֹ בַהֲרָא חַוְרָא סַמְקָא וְיִתַּחֲזִי לְכַהֲנָא:
@417 וְיֶחֱזֵי כַהֲנָא וְהָא מֶחֱזָהָא מַכִּיךְ מִן מַשְׁכָּא וּשְׂעָרַהּ אִתְהַפִיךְ לְמֶחֱוָר וִיסָאֵבִינֵהּ כַּהֲנָא מַכְתַּשׁ סְגִירוּתָא הִיא בְּשִׁחַנָא סְגִיאַת:
@418 וְאִם יֶחֱזִנַהּ כַּהֲנָא וְהָא לֵית בַּהּ שֵׂעָר חִוָר וּמַכִּיכָא לֵיתָהָא מִן מַשְׁכָּא וְהִיא עָמַיָא וְיַסְגְרִנֵהּ כַּהֲנָא שִׁבְעָא יוֹמִין:
@419 וְאִם אוֹסָפָא תוֹסֵף בְּמַשְׁכָּא וִיסָאֵב כַּהֲנָא יָתֵהּ מַכְתָּשָׁא הִיא:
@420 וְאִם בְּאַתְרָהָא קָמַת בֶּהַרְתָּא לָא אוֹסֵפַת רֹשֶׁם שִׁחֲנָא הִיא וִידַכִּנֵהּ כַּהֲנָא:
@421 אוֹ בִסְרָא אֲרֵי יְהֵי בְמַשְׁכֵּהּ כְּוָאָה דְנוּר וּתְהֵי רֹשֶׁם כְּוָאָה בַּהֲרָא חַוְרָא סֲמקָא אוֹ חַוְרָא:
@422 וְיֶחֱזֵי יָתַהּ כַּהֲנָא וְהָא אִתְהֲפִיךְ שֵׂעָר חִוָר בְּבַהֶרְתָּא וּמֶחֱזָהָא עַמִיק מִן מַשְׁכָּא סְגִירוּתָא הִיא בִּכְוָּאָה סְגִיאָה וִיסָאֵב יָתֵהּ כַּהֲנָא מַכְתַּשׁ סְגִירוּתָא הִיא:
@423 וְאִם יֶחֱזִנַהּ כַּהֲנָא וְהָא לֵית בְּבַהֶרְתָּא שֵׂעָר חִוָר וּמַכִּיכָא לֵיתָהָא מִן מַשְׁכָּא וְהִיא עָמְיָא וְיַסְגְרִנֵהּ כַּהֲנָא שִׁבְעָא יוֹמִין:
@424 וְיֶחֱזִנֵהּ כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה אִם אוֹסָפָא תוֹסֵף בְּמַשְׁכָּא וִיסָאֵב כַּהֲנָא יָתֵהּ מַכְתַּשׁ סְגִירוּתָא הִיא:
@425 וְאִם בְּאַתְרָהָא קָמַת בַּהֶרְתָּא לָא אוֹסֵפַת בְּמַשְׁכָּא וְהִיא עָמְיָא עוֹמֶק כְּוָאָה הִיא וִידַכִּנֵהּ כַּהֲנָא אֲרֵי רֹשֶׁם כְּוָאָה הִיא:
@426 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵא בֵהּ מַכְתָּשָׁא בְּרֵישׁ אוֹ בִּדְקָן:
@427 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא וְהָא מֶחֱזוֹהִי עַמִיק מִן מַשְׁכָּא וּבֵהּ שֵׂעָר סֻמָק דַעְדָק וִיסָאֵב יָתֵהּ כַּהֲנָא נִתְקָא הוּא סְגִירוּת רֵישָׁא אוֹ דִקְנָא הוּא:
@428 וַאֲרֵי יֶחֱזֵי כַהֲנָא יָת מַכְתַּשׁ נִתְקָא וְהָא לֵית מֶחֱזוֹהִי עַמִיק מִן מַשְּׁכָּא וְשֵׂעָר אֻכָם לֵית בֵּיהּ וְיַסְגַר כַּהֲנָא יָת מַכְתַּשׁ נִתְקָא שִׁבְעַת יוֹמִין:
@429 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא בְּיוֹמָא שְׁבִיעָאָה וְהָא לָא אוֹסֵף נִתְקָא וְלָא הֲוָה בֵהּ שֵׂעָר סֻמָק וּמֶחֱזֵי נִתְקָא לֵית עַמִיק מִן מַשְׁכָּא:
@430 וִיגַלַח סָחֳרָנֵי נִתְקָא וּדְעִם נִתְקָא לָא יְגַלַח וְיַסְגַר כַּהֲנָא יָת נִתְקָא שִׁבְעָא יוֹמִין תִּנְיָנוּת:
@431 וְיֶחֱזֵי כַהֲנָא יָת נִתְקָא בְּיוֹמָא שְׁבִיעָאָה וְהָא לָא אוֹסֵף נִתְקָא בְּמַשְׁכָּא וּמֶחֱזוֹהִי לֵיתוֹהִי עַמִיק מִן מַשְׁכָּא וִידַכֵּי יָתֵהּ כַּהֲנָא וִיצַבַּע לְבוּשׁוֹהִי וְיִדְכֵּי:
@432 וְאִם אוֹסָפָא יוֹסֵף נִתְקָא בְּמַשְׁכָּא בָּתַר דָכוּתֵהּ:
@433 וְיֶחֱזִנֵהּ כַּהֲנָא וְהָא אוֹסֵף נִתְקָא בְּמַשְׁכָּא לָא יְבַקֵר כַּהֲנָא לְשֵׂעָר סֻמָק מְסָאָב הוּא:
@434 וְאִם כַּד הֲוָה קָם נִתְקָא וְשֵׂעָר אֻכָּם צְמַח בֵּהּ אִתַּסִי נִתְקָא דְכֵי הוּא וִידַכִּנֵהּ כַּהֲנָא:
@435 וגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בִמְשַׁךְ בִּסְרְהוֹן בַּהֲרָן בַּהֲרָן חַוְרָן:
@436 וְיֶחֱזֵי כַהֲנָא וְהָא בִמְשַׁךְ בִּסְרְהוֹן בַּהֲרָן עָמְיָן חַוְרָן בָּהֲקָא הוּא סָגֵי בְמַשְׁכָּא דְכֵי הוּא:
@437 וּגְבַר אֲרֵי יַתַּר שְׂעַר רֵישֵׁהּ קְרַח הוּא דְכֵי הוּא:
@438 וְאִם מִלָקֳבֵל אַפּוֹהִי יַתַּר שְׂעַר רֵישֵׁהּ גְלוֹשׁ הוּא דְכֵי הוּא:
@439 וַאֲרֵי יְהֵי בְקָרָחוּתֵהּ אוֹ בִגְלוֹשׁוּתֵהּ מַכְתַּשׁ חִוָר סַמוֹק סְגִירוּת סָגְיָא הִיא בְּקָרָחוּתֵהּ אוֹ בִגְלוֹשּׁוּתֵהּ:
@440 וְיֶחֱזֵי יָתֵהּ כַּהֲנָא וְהָא עַמִיק מַכְתָּשָׁא חַוְרָא סַמְקָא בְּקָרָחוּתֵהּ אוֹ בִגְלוֹשׁוּתֵהּ כְּמֶחֱזֵי סְגִירוּתָא מְשַׁךְ בִּסְרָא:
@441 גְבַר סְגִיר הוּא מְסָאָב הוּא סָאֳבָא יְסָאֵבִנֵהּ כַּהֲנָא בְּרֵישֵּׁהּ מַכְתָּשֵׁהּ:
@442 וּסְגִירָא דִי בֵהּ מַכְתָּשָׁא לְבוּשׁוֹהִי יְהוֹן מְבַזְעִין וְרֵישֵׁהּ יְהֵי פְרִיעַ וְעַל שָׂפָם כַּאֲבֵלָא יִתְעַטָף וְלָא תִסְתַּאֲבוּן וְלָא תִסְתַּאֲבוּן יִקְרֵי:
@443 כָּל יוֹמֵי דִי מַכְתָּשָּׁא בֵהּ יְהֵי מְסָאָב מְסָאָב הוּא בִּלְחוֹדוֹהִי יֵיתֵב מִבָּרָא לְמַשְׁרִיתָא מוֹתְבֵהּ:
@444 וּלְבוּשָׁא אֲרֵי יְהֵי בֵהּ מַכְתַּשׁ סְגִירוּ בִּלְבֻשׁ עֲמַר אוֹ בִּלְבוּשׁ כִּתָּן:
@445 אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא לְכִתָּנָא וּלְעַמְרָא אוֹ בְמַשְׁכָּא אוֹ בְּכָל עֲבִידַת מְשָׁךְ:
@446 וִיהֵי מַכְתָּשָׁא יָרוֹק אוֹ סַמוֹק בִּלְבוּשָׁא אוֹ בְמַשְׁכָּא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְכָל מַאן דִמְשַׁךְ מַכְתַּשׁ סְגִירוּתָא הוּא וְיִתַּחֲזֵי לְכַהֲנָא:
@447 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא וְיַסְגַר יָת מַכְתָּשָׁא שִׁבְעַת יוֹמִין:
@448 וְיֶחֱזֵי יָת מַכְתָּשָׁא בְּיוֹמָא שְׁבִיעָאָה אֲרֵי אוֹסֵף מַכְתָּשָּׁא בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְמַשְׁכָּא לְכֹל דִי יִתְעֲבֵד מַשְׁכָּא לְעִבִידָא סְגִירוּת מְחַסְרָא מַכְתָּשָׁא מְסָאָב הוּא:
@449 וְיוֹקִיד יָת לְבוּשָׁא אוֹ יָת שִׁתְיָא אוֹ יָת עַרְבָא בְעַמְרָא אוֹ בְכִתָּנָא אוֹ יָת כָּל מָאן דִמְשַׁךְ דִי יְהֵי בֵהּ מַכְתָּשָׁא אֲרֵי סְגִירוּת מְחַסְרָא הִיא בְּנוּרָא תִּתּוֹקָד:
@450 וְאִם יֶחֱזֵי כַהֲנָא וְהָא לָא אוֹסֵף מַכְתָּשָׁא בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְּכָל מָאן דִמְשָׁךְ:
@451 וִיפַקֵד כַּהֲנָא וִיחַוְרוּן יָת דִי בֵהּ מַכְתָּשָׁא וְיַסְגְרִנֵהּ שִׁבְעַת יוֹמִין תִּנְיָנוּת:
@452 וְיֶחֱזֵי כַהֲנָא בָּתַר דְחַוָרוּ יָת מַכְתָּשָׁא וְהָא לָא שְׁנָא מַכְתָּשָׁא מִן כַּד הֲוָה וּמַכְתָּשָׁא לָא אוֹסֵף מְסָאָב הוּא בְּנוּרָא תּוֹקְדִנֵהּ תַּבְרָא הִיא בִּשְׁחִיקוּתֵהּ אוֹ בחַדָתוּתֵהּ:
@453 וְאִם חֲזָא:כַהֲנָא וְהָא עָמְיָא מַכְתָּשָׁא בָּתַר דְחַוָרוּ יָתֵהּ וּבְזַע יָתֵהּ מִן לְבוּשָׁא אוֹ מִן מַשְׁכָּא אוֹ מִן שִׁתְיָא אוֹ מִן עַרְבָא:
@454 וְאִם תִּתְחֲזֵי עוֹד בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְכָל מָאן דִמְשַׁךְ סָגְיָא הִיא בְּנוּרָא תוֹקְדִנֵהּ יָת דִי בֵהּ מַכְתָּשָׁא:
@455 וּלְבוּשָׁא אוֹ שַׁתְיָא אוֹ עַרְבָא אוֹ כָל מָאן דִמְשָׁךְ דִי יִתְחַוַר וְיֶעְדֵי מִנְהוֹן מַכְתָּשָׁא וְיִצְטַּבַּע תִּנְיָנוּת וְיִדְכֵּי:
@456 דָא אוֹרַיְתָא דְמַכְתַּשׁ סְגִירוּ בִּלְבוּשׁ עֲמַר אוֹ כִתָּנָא אוֹ שִׁתְיָא אוֹ עַרְבָא אוֹ כָּל מָאן דִמְשָׁךְ לְדַכָּיוּתֵהּ אוֹ לְסַאֲבוּתֵהּ: פפפ:
@479 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@480 דָא תְהֵי אוֹרַיְתָא דִסְגִירָא בְּיוֹמָא דְדָכוּתֵהּ וְיִתֵּתֵי לְוָת כַּהֲנָא:
@481 וְיִפּוֹק כַּהֲנָא לְמִבָּרָא לְמַשְׁרִיתָא וְיֶחֱזֵי כַהֲנָא וְהָא אִתַּסִי מַכְתַּשׁ סְגִירוּתָא מִן סְגִירָא:
@482 וִיפַקֵד כַּהֲנָא וְיִסַב לְמִדַכֵּי תַּרְתֵּין צִפֳּרִין חַיִין דָכְיָן וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:
@483 וִיפַקֵד כַּהֲנָא וְיִכּוֹס יָת צִפְּרָא חֲדָא לְמָאן דַחֲסַף עַל מֵי מַבּוּעַ:
@484 יָת צִפְּרָא חַיְתָא יִסַב יָתַהּ וְיָת אָעָא דְאַרְזָא וְיָת צְבַע זְהוֹרִי וְיָת אֵזוֹבָא וְיִטְבּוֹל יָתְהוֹן וְיָת צִפְּרָא חַיְתָא בִּדְמָא דְצִפְּרָא דִנְכִיסָא עַל מֵי מַבּוּעַ:
@485 וְיַדִי עַל דְמִדַכֵּי מִן סְגִירוּתָא שְׁבַע זִמְנִין וִידַכִּנֵהּ וִישַׁלַח יָת צִפְּרָא חַיְתָא עַל אַפֵּי חַקְלָא:
@486 וִיצַבַּע דְמִדַכֵּי יָת לְבוּשׁוֹהִי וִיגַלַח יָת כָּל שַׂעֲרֵהּ וְיַסְחֵי בְמַיָא וְיִדְכֵּי וּבָתַר כֵּן יֵעוֹל לְמַשְׁרִיתָא וִיתֵב מִבָּרָא לְמַשְׁכְּנֵהּ שִׁבְעַת יוֹמִין:
@487 וִיהֵי בְיוֹמָא שְׁבִיעָאָה יְגַלַח יָת כָּל שַׂעֲרֵהּ יָת רֵישֵׁהּ וְיָת דִקְנֵהּ וְיָת גְבִינֵי עֵינוֹהִי וְיָת כָּל שַׂעֲרֵהּ יְגַלָח וִיצַבַּע יָת לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וְיִדְכֵּי:
@488 וּבְיוֹמָא תְמִינָאָה יִסַב תְּרֵין אִמְרִין שַׁלְמִין וְאִמַרְתָּא חֲדָא בַּת שַׁתָּא שְׁלֶמְתָּא וּתְלָתָא עֶסְרוֹנִין סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח וְלֻגָא חַד דְמִשְׁחָא:
@489 וִיקִים כַּהֲנָא דִמְדַכֵּי יָת גַבְרָא דְמִדַכֵּי וְיָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@490 וְיִסַב כַּהֲנָא יָת אִמְרָא חֲדָא וִיקָרֵב יָתֵיהּ לַאֲשָּׁמָא וְיָת לֻגָא דְמִשְׁחָא וִירִים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@491 וְיִכּוֹס יָת אִמְרָא בַּאֲתַר דִי יִכּוֹס יָת חַטָאתָא וְיָת עֲלָתָא בַּאֲתַר קַדִישׁ אֲרֵי כְּחַטָאתָא אֲשָׁמָא הוּא לְכַהֲנָא קֹדֶשׁ קוּדְשִׁין הוּא:
@492 וְיִסַב כַּהֲנָא מִדְמָא דַאֲשָׁמָא וְיִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@493 וְיִסַב כַּהֲנָא מִלֻגָא דְמִשְׁחָא וִירִיק עַל יְדָא דְכַהֲנָא דִשְׁמָאלָא:
@494 וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵהּ דְיַמִינָא מִן מִשְׁחָא דִי עַל יְדֵהּ דִּשְׂמָאלָא וְיַדִי מִן מִשְׁחָא בְּאֶצְבְּעֵהּ שְׁבַע זִמְנִין קֳדָם יְיָ:
@495 וּמִשְׁאָר מִשְׁחָא דִי עַל יְדֵהּ יִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַּמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא עַל דְמָא דַאֲשָׁמָא:
@496 וּדְאִשְׁתָּאַר בְּמִשְׁחָא דִי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְמִדַכֵּי וִיכַפֵּר עֲלוֹהִי כַּהֲנָא קֳדָם יְיָ:
@497 וְיַעְבֵּד כַּהֲנָא יָת חַטָאתָא וִיכַפֵּר עַל דְמִדַּכֵּי מִסּוֹבְתֵהּ וּבָתַר כֵּן יִכּוֹס יָת עֲלָתָא:
@498 וְיַסֵק כַּהֲנָא יָת עֲלָתָא וְיָת מִנְחָתָא לְמַדְבְּחָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִדְכֵּי:
@499 וְאִם מִסְכֵּן הוּא וְלֵית יְדֵהּ מַדְבְּקָא וְיִסַּב אִמַר חַד אֲשָׁמָא לַאֲרָמָא לְכַפָּרָא עֲלוֹהִי וְעִסְרוֹנָא סֻלְתָּא חַד דְפִיל בִּמְשַּׁח לְמִנְחָא וְלֻגָא דְמִשְׁחָא:
@500 וְתַרְתֵּין שַּׁ:פנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה דִי תַדְבֵּק יְדֵהּ וִיהֵי חַד חַטָאתָא וְחַד עֲלָתָא:
@501 וְיַיְתִי יָתְהוֹן בְּיוֹמָא תְמִינָאָה לְדַכָּיוּתֵהּ לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ:
@502 וְיִסַב כַּהֲנָא יָת אִמְרָא דַאֲשָׁמָא וְיָת לֻגָא דְמִשְׁחָא וִירִים יָתְהוֹן כַּהֲנָא אֲרָמָא קֳדָם יְיָ:
@503 וְיִכּוֹס יָת אִמְרָא דַאֲשָׁמָא וְיִסַב כַּהֲנָא מִדְמָא דַאֲשָׁמָא וְיִתֵּן עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@504 וּמִן מִשְׁחָא יְרִיק כַּהֲנָא עַל יְדָא דְכַהֲנָא דִשְׂמָאלָא:
@505 וְיַדִי כַהֲנָא בְּאֶצְבְּעֵהּ דְיַמִינָא מִן מִשְׁחָא דִי עַל יְדֵהּ דִשְׂמָאלָא שְׁבַע זִמְנִין קֳדָם יְיָ:
@506 וְיִתֵּן כַּהֲנָא מִן מִשְׁחָא דִי עַל יְדֵהּ עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא עַל אֲתַר דְמָא דַאֲשָׁמָא:
@507 וּדְיִשְׁתָּאַר מִן מִשְׁחָא דִי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְמִדַכֵּי לְכַפָּרָא עֲלוֹהִי קֳדָם יְיָ:
@508 וְיַעְבֵּד יָת חַד מִן שַׁפְנִינַיָא אוֹ מִן בְּנֵי יוֹנָה מִדִי תַדְבֵּק יְדֵהּ:
@509 יָת דִי תַדְבֵּק יְדֵהּ יָת חַד חַטָאתָא וְיָת חַד עֲלָתָא עַל מִנְחָתָא וִיכַפֵר כַּהֲנָא עַל דְמִדַכֵּי קֳדָם יְיָ:
@510 דָא אוֹרַיְתָא דִי בֵהּ מַכְתַּשׁ סְגִירוּ דִי לָא תַדְבֵּק יְדֵהּ בְּדָכוּתֵהּ:
@511 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@512 אֲרֵי תֵעֲלוּן לְאַרְעָא דִכְנַעַן דִי אֲנָא יָהֵב לְכוֹן לְאַחֲסָנָא וְאֶתֵּן מַכְתַּשׁ סְגִירוּ בְּבֵית אַרְעָא אַחֲסַנְתְּכוֹן:
@513 וְיֵיתֵי דִי דִילֵהּ בֵּיתָא וִיחַוִי לְכַהֲנָא לְמֵימָר כְּמַכְתָּשָׁא אִתְחֲזִי לִי בְּבֵיתָא:
@514 וִיפַקֵד כַּהֲנָא וִיפַנוּן יָת בֵּיתָא עַד לָא יֵעוֹל כַּהֲנָא לְמֶחֱזֵי יָת מַכְתָּשָׁא וְלָא יִסְתָּאַב כָּל דִי בְּבֵיתָא וּבָתַר כֵּן יֵיעוֹל כַּהֲנָא לְמֶחֱזֵי יָת בֵּיתָא:
@515 וְיֶחֱזֵי יָת מַכְתָּשָׁא וְהָא מַכְתָּשָׁא בְּכָתְלֵי בֵיתָא פַּחֲתִין יַרְקָן אוֹ סַמְקָן וּמֶחֱזֵיהוֹן מַכִּיךְ מִן כָּתְלָא:
@516 וְיִפּוֹק כַּהֲנָא מִן בֵּיתָא לִתְרַע בֵּיתָא וְיַסְגַר יָת בֵּיתָא שִׁבְעָא יוֹמִין:
@517 וִיתוּב כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְיֶחֱזֵי וְהָא אוֹסֵף מַכְתָּשָׁא בּכָתלֵי בֵיתָא:
@518 וִיפַקֵד כֲּהֲנָא וִישַׁלְפוּן יָת אַבְנַיָא דִי בְהוֹן מַכְתָּשָׁא וְיִרְמוּן יָתְהוֹן לְמִבָּרָא לְקַרְתָּא לַאַתַר מְסָאָב:
@519 וְיָת בֵּיתָא יְקַלְפוּן מִגָיו סְחוֹר סְחוֹר וְיִרְמוּן יָת עַפְרָא דִי קַלִיפוּ לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@520 וְיִסְבוּן אַבְנַיָא אָחֳרָנִין וְיַיְתוּן בַּאֲתַר אַבְנַיָא וַעֲפַר אָחֳרָן יִסַב וִישׁוּעַ יָת בֵּיתָא:
@521 וְאִם יְתוּב מַכְתָּשָׁא וְיִסְגֵי בְּבֵיתָא בָּתַר דְשַׁלִיפוּ יָת אַבְנַיָא וּבָתַר דְקַלִיפוּ יָת בֵּיתָא וּבָתַּר דְאִתְּשָׁע:
@522 וְיֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא סְגִירוּת מְחַסְרָא הִיא בְּבֵיתָא מְסָאָב הוּא:
@523 וִיתָרַע יָת בֵּיתָא יָת אַבְנוֹהִי וְיָת אָעוֹהִי וְיָת כָּל עֲפַר בֵּיתָא וְיַפֵּק לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@524 וּדְיֵיעוֹל לְבֵיתָא כָּל יוֹמִין דְיַסְגַר יָתֵהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@525 וּדְיִשְׁכּוּב בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי וּדְיֵיכוּל בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי:
@526 וְאִם מֵעַל יֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא לָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא בָּתַר דְאִתְּשַׁע יָת בֵּיתָא וידַכֵּי כַהֲנָא יָת בֵּיתָא אֲרֵי אִתַּסִי מַכְתָּשָׁא:
@527 וְיִסַב לְדַכָּאָה יָת בֵּיתָא תַּרְתֵּין צִפֲּרִין וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:
@528 וְיִכּוֹס יָת צִפֲּרָא חֲדָא לְמַאן דַחֲסַף עַל מֵי מַבּוּעַ:
@529 וְיִסַב יָת אָעָא דְאַרְזָא וְיָת אֵזוֹבָא וְיָת צְבַע זְהוֹרִי וְיָת צִפֲּרָא חַיְתָא וְיִטְבּוֹל יָתְהוֹן בִּדְמָא דְצִפֲּרָא דִנְכִיסָא וּבְמֵי מַבּוּעַ וְיַדִי לְבֵיתָא שְׁבַע זִמְנִין:
@530 וִידַכֵּי יָת בֵּיתָא בִּדְמָא דְצִפֲּרָא וּבְמֵי מַבּוּעַ וּבְצִפֲּרָא חַיְתָא וּבְאָעָא דְאַרְזָא וּבְאֵזוֹבָא וּבִצְבַע זְהוֹרִי:
@531 וִישַׁלַח יָת צִפֲּרָא חַיְתָא לְמִבָּרָא לְקַרְתָּא לְאַפֵּי חַקְלָא וִיכַפֵּר עַל בֵּיתָא וְיִדְכֵּי:
@532 דָא אוֹרַיְתָא לְכָל מַכְתַּשׁ סְגִירוּתָא וּלְנִתְקָא:
@533 וְלִסְגִירוּת לְבוּשָׁא וּלְבֵיתָא:
@534 וּלְעַמְקָא וּלְעַדְיָא וּלְבַהֲרָא:
@535 לְאַלָפָא בְּיוֹמָא מְסָאָבָא וּבְיוֹמָא דַכְיָא דָא אוֹרַיְתָא דִסְגִירוּתָא:
@536 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@537 מַלִילוּ עִם בְּנֵי יִשְׂרָאֵל וְתֵימְרוּן לְהוֹן גְבַר גְבַר אֲרֵי יְהֵי דָאִיב מִבִּשְׂרֵהּ דוֹבֵהּ מְסָאָב הוּא:
@538 וְדָא תְּהֵי סוֹבְתֵהּ בְּדוֹבֵהּ רָר בִּשְׂרֵהּ יָת דוֹבֵהּ אוֹ חָתִים בִּשְׂרֵהּ מִדוֹבֵהּ סוֹבְתֵהּ הִיא:
@539 כָּל מִשְׁכְּבָא דִי יִשְׁכּוּב עֲלוֹהִי דוֹבָנָא יְהֵי מְסָאָב וְכָל מָנָא דְיֵיתֵב עֲלוֹהִי יהֵי מְסָאָב:
@540 וּגְבַר דִי:יִקְרַב בְּמִשְׁכְּבֵהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@541 וּדְיֵיתֵב עַל מָנָא דְיֵיתֵב עֲלוֹהִי דוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@542 וּדְיִקְרַב בִּבְסַר דוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@543 וַאֲרֵי יֵרוֹק דוֹבָנָא בְּדַכְיָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָּׁא:
@544 וְכָל מֶרְכְּבָא דִי יִרְכּוּב עֲלוֹהִי דוֹבָנָא יְהֵי מְסָאָב:
@545 וְכָל דְיִקְרַב בְּכֹל דִי יְהֵי תְחוֹתוֹהִי יְהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטוֹל יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@546 וְכֹל דִי יִקְרַב בֵּהּ דוֹבָנָא וִידוֹהִי לָא שְׁטַף בְּמַיָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@547 וּמָאן דַחֲסַף דִי יִקְרַב בֵּהּ דוֹבָנָא יִתָּבָר וְכָל מָאן דְאָע יִשְׁתַּטַּף בְּמַיָא:
@548 וַאֲרֵי יִדְכֵּי דוֹבָנָא מִדוֹבֵהּ וְיִמְנֵי לֵהּ שִׁבְעַת יוֹמִין לְדָכוּתֵהּ וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בִשְׂרֵהּ בְּמֵי מַבּוּעַ וְיִדְכֵּי:
@549 וּבְיוֹמָא תְמִינָאָה יִסַב לֵהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה וְיֵיתֵי לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא וְיִתְּנִנוּן לְכַהֲנָא:
@550 וְיַעְבֵּד יָתְהוֹן כַּהֲנָא חָד חַטָאתָא וְחָד עֲלָתָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא קֳדָם יְיָ מִדוֹבֵהּ:
@551 וּגְבַר אֲרֵי תִפוֹק מִנֵהּ שִׁכְבַת זַרְעָא וְיַסְחֵי בְמַיָא יָת כָּל בִּשְׂרֵהּ וִיהֵי מְסָאָב עַד רַמְשָׁא:
@552 וְכָל לְבוּשׁ וְכָל מְשַׁךְ דִי יְהֵי עֲלוֹהִי שִׁכְבַת זַרְעָא וְיִצְטַבַּע בְּמַיָא וִיהֵי מְסָאָב עַד רַ:משָׁא:
@553 וְאִתְּתָא דִי יִשְׁכּוּב גְבַר יָתָהּ שִׁכְבַת זַרְעָא וְיַסְחוּן בְּמַיָא וְיִסְאֲבוּן עַד רַמְשָׁא:
@554 וְאִתְּתָא אֲרֵי תְהֵי דָיְבָא דָם יְהֵי דוֹבָהּ בְּבִשְׂרָהּ שִׁבְעָא יוֹמִין תְּהֵי בְרִחוּקָהּ וְכָל דְיִקְרַב בָּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@555 וְכֹל דִי תִשְׁכּוּב עֲלוֹהִי בְּרִחוּקָהּ יְהֵי מְסָאָב וְכֹל דִי תֵיתֵב עֲלוֹהִי יְהֵי מְסָאָב:
@556 וְכָל דְיִקְרַב בְּמִשְׁכְּבָהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@557 וְכָל דְיִקְרַב בְּכָל מָנָא דִי תֵיתֵב עֲלוֹהִי יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@558 וְאִם עַל מִשְׁכְּבָא הוּא אוֹ עַל מָנָא דִי הִיא יָתְבָא עֲלוֹהִי בְּמִקְרְבֵהּ בֵּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@559 וְאִם מִשְׁכַּב יִשְׁכּוּב גְבַר יָתָהּ וּתְהֵי רִחוּקָהּ עֲלוֹהִי וִיהֵי מְסָאָב שִׁבְעַת יוֹמִין וְכָל מִשְׁכָּב דִי יִשְׁכּוּב עֲלוֹהִי יְהֵי מְסָאָב:
@560 וְאִתְּתָא אֲרֵי יְדוּב דוֹב דְמָהּ יוֹמִין סַגִיאִין בְּלָא עִדַן רִחוּקָהּ אוֹ אֲרֵי תְדוּב עַל רִחוּקָהּ כָּל יוֹמֵי דוֹב סוֹבְתָהּ כְּיוֹמֵי רִחוּקָהּ תְּהֵי מְסָאֳבָא הִיא:
@561 כָּל מִשְׁכְּבָא דִי תִשְׁכּוּב עֲלוֹהִי כָּל יוֹמֵי דוֹבָהּ כְּמִשְׁכַּב רִחוּקָהּ יְהֵי לָהּ וְכָל מָנָא דִי תֵתֵב עֲלוֹהִי מְסָאָב יְהֵי כְּסוֹאֲבַת רִחוּקָהּ:
@562 וְכָל דְיִקְרַב בְּהוֹן יְהֵי מְסָאָב וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@563 וְאִם דְכִיאַת מִדוֹבָהּ וְתִמְנֵי לָהּ שִׁבְעַת יוֹמִין וּבָתַר כֵּן תִדְכֵּי:
@564 וּבְיוֹמָא תְמִינָאָה תִּסַב לָהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה וְתַיְתִי יָתְהוֹן לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא:
@565 וְיַעְבֵּד כַּהֲנָא יָת חָד חַטָאתָא וְיָת חָד עֲלָתָא וִיכַפֵּר עֲלָהּ כַּהֲנָא קֳדָם יְיָ מִדוֹב סוֹבְתָהּ:
@566 וְתַפְרְשׁוּן יָת בְּנֵי יִשְׂרָאֵל מִסוֹאֲבַתְהוֹן וְלָא יְמוּתוּן בְּסוֹאֲבַתְהוֹן בְּסָאָבְהוֹן יָת מַשְׁכְּנִי דִי בֵינֵיהוֹן:
@567 דָא אוֹרַיְתָא דְדוֹבָנָא וְדִי תִפּוֹק מִנֵהּ שִּׁכְבַת זַרְעָא לְאִסְתָּאָבָא בָהּ:
@568 וְלִדְסוֹבְתָה בְּרִחוּקָהּ וְלִדְדָאִיב יָת דוֹבֵהּ לִדְכַר וּלְנֻקְבָא וְלִגְבַר דִי יִשְׁכּוּב עִם מְסָאָבָא: פפפ:
@587 וּמַלֵיל יְיָ עִם מֹשֶׁה בָּתַר דְמִיתוּ תְּרֵין בְּנֵי אַהֲרֹן בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ וּמִיתוּ:
@588 וַאֲמַר יְיָ לְמֹשֶׁה מַלֵל עִם אַהֲרֹן אָחוּךְ וְלָא יְהֵי עָלֵל בְּכָל עִדָן לְקוּדְשָׁא מִגָיו לְפָרֻכְתָּא לָקֳדָם כַּפֻּרְתָּא דִי עַל אֲרוֹנָא וְלָא יְמוּת אֲרֵי בַּעֲנָנָא אֲנָא מִתְגְלִי עַל בֵּית כַּפֻּרְתָּא:
@589 בְּדָא יְהֵי עָלֵל אַהֲרֹן לְקוּדְשָׁא בְּתוֹר בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא:
@590 כִּתּוּנָא דְבוּצָא קוּדְשָׁא יִלְבָּשׁ וּמִכְנְסִין דְבוּץ יְהוֹן עַל בִּסְרֵהּ וּבְהֶמְיָנָא דְבוּץ יֵסַר וּבְמִצְנֶפְתָּא דְבוּצָא יָחֵת בְּרֵישֵׁהּ לְבוּשֵׁי קוּדְשָׁא אִנוּן וְיַסְחֵי בְמַיָא יָת בִּ:סרֵהּ וְיַלְבְּשִׁנוּן:
@591 וּמִן כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יִסַב תְּרֵין צְפִירֵי עִזִין לְחַטָאתָא וּדְכַר חַד לַעֲלָתָא:
@592 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ:
@593 וְיִסַב יָת תְּרֵין צְפִירִין וִיקִים יָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@594 וְיִתֵּן אַהֲרֹן עַל תְּרֵין צְפִירִין עַדְבִין עַדְבָא חַד לִשְׁמָא דַיְיָ וְעַדְבָא חַד לַעֲזָאזֵל:
@595 וִיקָרֵב אַהֲרֹן יָת צְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לִשְׁמָא דַיְיָ וְיַעְבְּדִנֵהּ חַטָאתָא:
@596 וּצְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לַעֲזָאזֵל יִתָּקַם כַּד חַי קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי לְשַׁלַח יָתֵהּ לַעֲזָאזֵל לְמַדְבְּרָא:
@597 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְיִכּוֹס יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ:
@598 וְיִסַב מְלֵי מַחְתִּיתָא גוּמְרִין דְאֶשָׁא מֵעִלַוֵי מַדְבְּחָא מִן קֳדָם יְיָ וּמְלֵי חָפְנוֹהִי קְטוֹרֶת בּוּסְמִין דַקִיקִין וְיָעֵל מִגָיו לְפָרֻכְתָּא:
@599 וְיִתֵּן יָת קְטוֹרֶת בּוּסְמַיָא עַל אֶשָׁתָא לָקֳדָם יְיָ וְחָפֵי עֲנָנָא קְטָרְתָּא יָת כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא וְלָא יְמוּת:
@600 וְיִסַב מִדְמָא דְתוֹרָא וְיַדֵי בְאֶצְבְּעֵהּ עַל אַפֵּי כַּפּוּרְתָּא קִדוּמָא וְלָקֳדָם כַּפֻּרְתָּא יַדִי שְׁבַע זִמְנִין מִן דְמָא בְּאֶצְבְּעֵהּ:
@601 וְיִכּוֹס יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְיָעֵל יָת דְמֵהּ לְמִגָיו לְפָרֻכְתָּא וְיַעְבֵּד לִדְמֵהּ כְּמָא דִי עֲבַּד לִדְמָא דְתוֹרָא וְיַדִי יָתֵהּ עַל כַּפֻּרְתָּא וְלָקֳדָם כַּפֻּרְתָּא:
@602 וִיכַפֵּר עַל קוּדְשָׁא מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל וּמִמֶרְדֵיהוֹן לְכָל חֲטָאֵיהוֹן וְכֵן יַעְבֵּד לְמַשְׁכַּן זִמְנָא דְשָׁרֵי עִמְהוֹן בְּגוֹ סוֹאֲבָתְהוֹן:
@603 וְכָל אֱנַשׁ לָא יְהֵי בְּמַשְׁכַּן זִמְנָא בְּמֵעֲלֵהּ לְכַפָּרָא בְקוּדְשָׁא עַד מִפְּקֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְעַל כָּל קְהָלָא דְיִשְׂרָאֵל:
@604 וְיִפּוֹק לְמַדְבְּחָא דִי קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי וְיִסַב מִדְמָא דְתוֹרָא וּמִדְמָא דִצְפִירָא וְיִתֵּן עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר:
@605 וְיַדֵי עֲלוֹהִי מִן דְמָא בְּאֶצְבְּעֵהּ שְׁבַע זִמְנִין וִידַכִּנֵהּ וִיקַדְשִׁנֵהּ מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל:
@606 וִישֵׁיצֵי מִלְכַפָּרָא עַל קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא וִיקָרֵב יָת צְפִירָא חַיָא:
@607 וְיִסְמוֹךְ אַהֲרֹן יָת תַּרְתֵּין יְדוֹהִי עַל רֵישׁ צְפִירָא חַיָא וִיוַדֵי עֲלוֹהִי יָת כָּל עֲוָיַת בְּנֵי יִשְׂרָאֵל וְיָת כָל מֶרְדֵיהוֹן לְכָל חֲטָּאֵיהוֹן וְיִתֵּן יָתְהוֹן עַל רֵישׁ צְפִירָא וִישַׁלַח בְּיַד גְבַר דִזְמִין לִמְהַךְ לְמַדְבְּרָא:
@608 וְיִטוֹל צְפִירָא עֲלוֹהִי יָת כָּל חוֹבֵיהוֹן לְאַרְעָא דְלָא יָתְבָא וִישַׁלַח יַת צְפִירָא בְּמַדְבְּרָא:
@609 וְיֵיעוֹל אַהֲרֹן לְמַשְׁכַּן זִמְנָא וְיַשְׁלַח יָת לְבוּשֵׁי בוּצָא דִי לְבַשׁ בְּמֵעֲלֵהּ לְקוּדְשָׁא וְיַצְנִעוּן תַּמָן:
@610 וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא בַּאֲתַר קַדִישׁ וְיִלְבַּשׁ יָת לְבוּשׁוֹהִי וְיִפּוֹק וְיַעְבֵּד יָת עֲלָתֵהּ וְיָת עֲלַת עַמָא וִיכַפַּר עֲלוֹהִי וְעַל עַמָּא:
@611 וְיָת תַּרְבָּא דְחַטָאתָא יַסֵק לְמַדְבְּחָא:
@612 וּדְמוֹבִיל יָת צְפִירָא לַעֲזָאזֵל יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:
@613 וְיָת תּוֹרָא דְחַטָאתָא וְיָת צְפִירָא דְחַטָאתָא דִי אִתָּעַל מִדִמְהוֹן לְכַפָּרָא בְקוּדְשָׁא יִתַּפְּקוּן לְמִבָּרָא לְמַשְּׁרִיתָא וְיוֹקְדוּן בְּנוּרָא יָת מַשְׁכֵּיהוֹן וְיָת בִּסְרְהוֹן וְיָת אָכְלֵיהוֹן:
@614 וּדְמוֹקִיד יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל למַשְׁרִיתָא:
@615 וּתְהֵי:לְכוֹן לִקְיַם עָלָם בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא תְּעַנוּן יָת נַפְשָׁתֵיכוֹן וְכָל עִבִידָא לָא תַעְבְּדוּן יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@616 אֲרֵי בְיוֹמָא הָדֵין יְכַפֵּר עֲלֵיכוֹן לְדַכָּאָה יָתְכוֹן מִכָּל חוֹבֵיכוֹן קֳדָם יְיָ תִּדְכּוּן:
@617 שְׁבַת שְׁבָתָא הִיא לְכוֹן וּתְעַנוּן יָת נַפְשָּׁתֵיכוֹן קְיַם עֲלָם:
@618 וִיכַפֵּר כַּהֲנָא דִי רַבִּי יָתֵהּ וְדִי יְקָרֵב יָת קֻרְבָּנֵהּ לְשַׁמָשָׁא תְּחוֹת אֲבוּהִי וְיִלְבַּשׁ יָת לְבוּשֵׁי בוּצָא:לבוּשֵׁי קוּדְשָׁא:
@619 וִיכַפֵּר עַל מִקְדַשׁ קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא יְכַפַּר וְעַל כַּהֲנַיָא וְעַל כָּל עַמָא דִקְהָלָא יְכַפַּר:
@620 וּתְהֵי דָא לְכוֹן לִקְיַם עָלָם לְכַפָּרָא עַל בְּנֵי יִשְׂרָאֵל מִכָּל חוֹבֵיהוֹן חֲדָא בְּשַׁתָּא וַעֲבַד כְּמָא דִי פַּקִיד יְיָ יָת מֹשֶׁה:
@621 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@622 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֵימָר:
@623 גְבַר גְבַר מִבֵּית יִשְׂרָאֵל דִי יִכּוֹס תּוֹר אוֹ אִמַר אוֹ עִזָא בְּמַשְׁרִיתָא אוֹ דִי יִכּוֹס מִבָּרָא לְמַשְׁרִיתָא:
@624 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתֵהּ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ קֳדָם מַשְׁכְּנָא דַיְיָ דְמָא יִתְחַשַׁב לְגַבְרָא הַהוּא דְמָא אֲשַׁד וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מִגוֹ עַמֵהּ:
@625 בְּדִיל דִי יַיְתוּן בְּנֵי יִשְׂרָאֵל יָת דִבְחֵיהוֹן דִי אִנוּן דָבְחִין עַל אַפֵּי חַקְלָא וְיַיְתוּנוּן לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא וְיִכְסוּן נִכְסַת קוּדְשִׁין קֳדָם יְיָ יָתְהוֹן:
@626 וְיִזְרוֹק כַּהֲנָא יָת דְמָא עַל מַדְבְּחָא דַיְיָ בִּתְרַע מַשְׁכַּן זִמְנָא וְיַסֵק תַּרְבָּא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@627 וְלָא יִדְבְּחוּן עוֹד יָת דִבְחֵיהוֹן לַשֵׁדִין דִי אִנוּן טָעָן בַּתְרֵיהוֹן קְיַם עָלָם תְּהֵי דָא לְהוֹן לְדָרֵיהוֹן:
@628 וּלְהוֹן תֵּימַר גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יַסֵק עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָא:
@629 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתִנֵהּ לְמֶעְבַּד יָתֵהּ קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@630 וּגְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יֵיכוּל כָּל דְמָא וְאֶתֵּן רוּגְזִי בַּאֲנָשָׁא דְיֵיכוּל יָת דְמָא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@631 אֲרֵי נְפַשׁ בִּסְרָא בִּדְמָא הִיא וַאֲנָא יְהָבִתֵּהּ לְכוֹן עַל מַדְבְּחָא לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן אֲרֵי דְמָא הוּא עַל נַפְשָׁא מְכַפֵּר:
@632 עַל כֵּן אֲמָרִית לִבְנֵי יִשְׂרָאֵל כָּל אֱנַשׁ מִנְכוֹן לָא יֵיכוּל דְמָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן לָא יֵיכוּל דְמָא:
@633 וּגְבַר גְבַר מִן בְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יְצוּד צֵידָא חַיְתָא אוֹ עוֹפָא דִי מִתְאֲכֵל וְיֵשׁוֹד יָת דְמֵהּ וִיכַסִנֵהּ בְּעַפְרָא:
@634 אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ בְּנַפְשֵׁהּ הוּא וַאֲמָרִית לִבְנֵי יִשְׂרָאֵל דַם כָּל בִּסְרָא לָא תֵיכְלוּן אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ הִיא כָּל דְיֵיכְלִנֵהּ יִשְׁתֵּיצֵי:
@635 וְכָל אֱנַשׁ דִי יֵיכוּל נְבִילָא וּתְבִירָא בְּיַצִיבָא וּבְגִיוֹרָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@636 וְאִם לָא יְצַבַּע וּבִסְרֵהּ לָא יַסְחֵי וִיקַבֵּל חוֹבֵהּ:
@637 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@638 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@639 כְּעוֹבָדֵי עַמָא דְאַרְעָא דְמִצְרַיִם דִי יְתֶבְתּוּן בַּהּ לָא תַעְבְּדוּן וּכְעוֹבָדֵי עַמָא דְאַרְעָא דִכְנַעַן דִי אֲנָא מָעֵל יָתְכוֹן תַּמָן לָא תַעְבְּדוּן וּבְנִימוֹסֵיהוֹן לָא תְהָכוּן:
@640 יָת דִינַי תַּעְבְּדוּן וְיָת קְיָמַי תִּטְרוּן לְהַלָכָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@641 וְתִטְרוּן יָת קְיָמַי וְיָת דִינַי דִי יַעְבֵּד יָתְהוֹן אֲנָשָׁא וְיֵחֵי בְהוֹן לְחַיֵי עָלְמָא אֲנָא יְיָ:
@642 גְבַר גְבַר לְכָל קָרִיב בִּסְרֵהּ לָא תִקְרְבוּן לְגַלָאָה עֶרְיָא אֲנָא יְיָ:
@643 עֶרְיַת אֲבוּךְ וְעֶרְיַת אִמָךְ לָא תְגַלֵי אִמָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@644 עֶרְיַת אִתַּת אָבוּךְ לָא תְגַלֵי עֶרְיַת אָבוּךְ הִיא:
@645 עֶרְיַת אֲחָתָךְ בַּת אֲבוּךְ אוֹ בַת אִמָךְ דִילִידָא מִן אֲבוּךְ מִן אִתַּת אָחֳרִי אוֹ מִן אִמָךְ לִגְבַר אָחֳרָן לָא תְגַלֵי עֶרְיַתְהֶן:
@646 עֶרְיַת בַּת בְּרָךְ אוֹ בַת בְּרַתָּךְ לָא תְגַלֵי עֶרְיַתְהֶן אֲרֵי עֶרְיְתָךְ אִנוּן:
@647 עֶרְיַת בַּת אִתַּת אֲבוּךְ דִילִידָא מִן אֲבוּךְ אֲחָתָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@648 עֶרְיַת אֲחַת אֲבוּךְ לָא תְגַלֵי קָרִיבַת אֲבוּךְ הִיא:
@649 עֶרְיַת אֲחַת אִמָךְ לָא תְגַלֵי אֲרֵי קָרִיבַת אִמָךְ הִיא:
@650 עֶרְיַת אַח אֲבוּךְ לָא תְגַלֵי לְאִתְּתֵהּ לָא תִקְרַב אִתַּת אַח אֲבוּךְ הִיא:
@651 עֶרְיַת כַּלָתָךְ לָא תְגַלֵי אִתַּת בְּרָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@652 עֶרְיַת אִתַּת אֲחוּךְ לָא תְגַלֵי עֶרְיַת אֲחוּךְ הִיא:
@653 עֶרְיַת אִתְּתָא וּבְרַתָּהּ לָא תְגַלֵי יָת בַּת בְּרָהּ וְיָת בַּת בְּרַתָּהּ לָא תִםַב לְגַלָאָה עֶרְיָתָהּ קָרִיבָן אִנוּן עֵצַת חִטְאִין הִיא:
@654 וְאִתְּתָא עִם אֲחָתָהּ לָא תִסָב לְעָקָאָה לְגַלָאָה עֶרְיְתָהּ עֲלָהּ בְּחַיָיהָא:
@655 וּלְאִתְּתָא בְּרִחוּק סוֹבְתַהּ לָא תִקְרַב לְגַלָאָה עֶרְיְתָהּ:
@656 וּבְאִתַּת חַבְרָךְ לָא תִתֵּן שְׁכֻבְתָּךְ לְזַרְעָא לְאִסְתָּאָבָא בָהּ:
@657 וּמִבְּנָיִךְ לָא תִתֵּן לְאַעְבָּרָא לְמוֹלֶךְ וְלָא תַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@658 וְעִם דְכוּרָא לָא תִשְׁכּוּב מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא הִיא:
@659 וּבְכָל בְּעִירָא לָא תִתֵּן שְׁכֻבְתָּךְ לְאִסְתָּאָבָא בָהּ וְאִתְּתָא לָא תְקוּם קֳדָם בְּעִירָא לְמִשְׁלַט בָּהּ תִּבְלָא הוּא:
@660 לָא תִסְתַּאֲבוּן בְּכָל אִלֵין אֲרֵי בְּכָל אִלֵין אִסְתַּאָבוּ עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן:
@661 וְאִסְתָּאָבַת אַרְעָא וְאַסְעָרִית חוֹבָהּ עֲלָהּ וְרוֹקֵינַת אַרְעָא יָת יָתְבָהָא:
@662 וְתִטְרוּן אַתּוּן יָת קְיָמַי וְיָת דִינַי וְלָא תַעְבְּדוּן מִכֹּל תּוֹעֶבְתָּא הָאִלֵין יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@663 אֲרֵי יָת כָּל תּוֹעֶבְתָּא הָאִלֵין עֲבָדוּ אֱנָשֵׁי אַרְעָא דִי קֳדָמֵיכוֹן וְאִסְתָּאָבַת אַרְעָא:
@664 וְלָא תְרוֹקֵן אַרְעָא יָתְכוֹן בְּסָאֳבֵיכוֹן יָתָהּ כְּמָא דְרוֹקֵינַת יָת עַמְמַיָא דִי קֳדָמֵיכוֹן:
@665 אֲרֵי כָּל דִי יַעְבֵּד מִכֹּל תּוֹעֶבְתָּא הָאִלֵין וְיִשְׁתֵּיצוּן נַפְשָׁתָא דְיַעְבְּדוּן מִגוֹ עַמְהוֹן:
@666 וְתִטְרוּן יָת מַטְרַת מֵימְרִי בְּדִיל דְלָא לְמֶעְבַּד מִנִימוֹסֵי תוֹעֶבְתָּא דְאִתְעֲבָדָא קֳדָמֵיכוֹן וְלָא תִסְתַּאֲבוּן בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן: פפפ:
@686 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@687 מַלֵל עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן קַדִישִׁין תְּהוֹן אֲרֵי קַדִישׁ אֲנָא יְיָ אֱלָהָכוֹן:
@688 גְבַר מִן אִמֵהּ וּמִן אֲבוּהִי תְּהוֹן דָחֲלִין וְיָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן אֲנָא יְיָ אֱלָהָכוֹן:
@689 לָא תִתְפְּנוּן בָּתַר טַעֲוָן וְדַחֲלָן דְמַתְּכָא לָא תַעְבְּדוּן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@690 וַאֲרֵי תִכְסוּן נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְסֻנֵהּ:
@691 בְּיוֹמָא דְיִתְנְכֵס יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר עַד יוֹמָא תְלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@692 וְאִם אִתְאֲכָלָא יִתְאֲכֵל בְּיוֹמָא תְלִיתָאָה מְרָחַק הוּא לָא יְהֵי לְרַעַוָא:
@693 וּדְיֵיכְלִנֵהּ חוֹבֵהּ יְקַבֵּל אֲרֵי יָת קוּדְשָׁא דַיְיָ אַחֵל וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@694 וּבְמֶחְצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ לְמֶחְצָד וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט:
@695 וְכַרְמָךְ לָא תְעַלֵל וְנִתְרָא דְכַרְמָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@696 לָא תִּגְנְבוּן וְלָא תְכַדְבוּן וְלָא תְשַׁקְרוּן אֱנַשׁ בְּחַבְרֵהּ:
@697 וְלָא תִשָׁבְעוּן בִּשְׁמִי לְשִׁקְרָא וְתַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@698 לָא תַעֲשׁוֹק יָת חַבְרָךְ וְלָא תְאַנֵס לָא תְבִית אַגְרָא דַאֲגִירָא לְוָתָךְ עַד צַפְרָא:
@699 לָא תְלוּטּ דְלָא שָׁמַע וְקֳדָם דְלָא חָזֵי לָא תְשִׂים תַּקְלָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:
@700 לָא תַעְבְּדוּן שְׁקַר בְּדִינָא לָא תִסַב אַפֵּי מַסְכֵּנָא וְלָא תֶהְדַר אַפֵּי רַבָּא בְּקוּשְׁטָא תְּדִינֵהּ לְחַבְרָךְ:
@701 לָא תֵיכוּל קוּרְצִין בְּעַמָךְ לָא תְקוּם עַל דְמָא דְחַבְרָךְ אֲנָא יְיָ:
@702 לָא תִשְׂנֵי יָת אֲחוּךְ בְּלִבָּךְ אוֹכָחָא תוֹכַח יָת חַבְרָךְ וְלָא תְקַבֵּל עַל דִי לֵהּ חוֹבָא:
@703 לָא תִקוֹם וְלָא תִטַר דְבָבוּ לִבְנֵי עַמָךְ וּתְרַחֵם לְחַבְרָךְ כְּוָתָךְ אֲנָא יְיָ:
@704 יָת קְיָמַי תִּטְרוּן בְּעִירָךְ לָא תַרְכֵּב עֵרוּבִין חַקְלָךְ לָא תִזְרַע עֵרוּבִין וּלְבוּשׁ עֵרוּבִין שַׁעַטְנֵזָא לָא יִסַק עֲלָךְ:
@705 וּגְבַר אֲרֵי יִשְׁכּוּב עִם אִתְּתָא שִׁכְבַת זַרְעָא וְהִיא אַמְתָא אֲחִידָא לִגְבַר וְאִתְפְּרָקָא לָא אִתְפְּרִיקַת בְּכַסְפָּא אוֹ חֵרוּתָא לָא אִתְיְהִיבַת לַהּ בִּשְׁטָר בִּקֻּרְתָּא תְהֵי לָא יוּמְתוּן אֲרֵי לָא אִתְחָרָרַת:
@706 וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא דְכַר לַאֲשָׁמָא:
@707 וִיכַפֵּר עֲלוֹהִי כַּהֲנָא בְּדִכְרָא דַאֲשָׁמָא קֳדָם יְיָ עַל חוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ מְחוֹבְתֵהּ דִי חַב:
@708 וַאֲרֵי תֵעֲלוּן לְאַרְעָא וְתִצְבוּן כָּל אִלָן דְמֵיכַל וּתְרַחֲקוּן רָחָקָא יַת אִבֵּהּ תְּלַת שְׁנִין יְהֵי לְכוֹן מְרָחָק לַאֲבָדָא לָא יִתְאֲכֵל:
@709 וּבְשַׁתָּא רְבִיעֵתָא יְהֵי כָּל אִבֵּהּ קֹדֶשׁ תּוּשְׁבְּחָן קֳדָם יְיָ:
@710 וּבְשַׁתָּא חֲמִישֵׁתָא תֵּיכְלוּן יָת אִבֵּהּ לְאוֹסָפָא לְכוֹן עֲלַלְתֵּהּ אֲנָא יְיָ אֱלָהָכוֹן:
@711 לָא תֵיכְלוּן עַל דְמָא לָא תְנַחֲשׁוּן וְלָא תְעוֹנוּן:
@712 לָא תַקְפוּן פָּאתָא דְרֵישְׁכוֹן וְלָא תְחַבֵּל יָת פָּאתָא דְדִקְנָךְ:
@713 וְחִבּוּל עַל מִית לָא תִתְּנוּן בְּבִסְרְכוֹן וְרוּשְׁמִין חֲרִיתִין לָא תִתְּנוּן בְכוֹן אֲנָא יְיָ:
@714 לָא תַחֵל יָת בְּרַתָּךְ לְאַטְעֲיוּתַהּ וְלָא תִטְעֵי אַרְעָא וְתִתְמְלֵי אַרְעָא עֵצַת חִטְאִין:
@715 יָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ:
@716 לָא תִתְפְּנוּן בָּתַר בִּדִין וּדְכוּרוּ לָא תִתְבְּעוּן לְאִסְתָּאָבָא בְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@717 מִן קֳדָם דְסַבַּר בְּאוֹרַיְתָא תְּקוּם וּתְהַדַר אַפֵּי סָבָא וְתִדְחַל מֵאֳלָהָךְ אֲנָא יְיָ:
@718 וַאֲרֵי יִתְגַיַר עִמָךְ גִיוֹרָא בְּאַרְעֲכוֹן לָא תוֹנוּן יָתֵהּ:
@719 כְּיַצִיבָא מִנְכוֹן יְהֵי לְכוֹן גִיוֹרָא דְיִתְגַיַר בֵּינֵיכוֹן וּתְרַחֵם לֵהּ כְּוָתָךְ אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@720 לָא תַעְבְּדוּן שְׁקַר בְּדִין בִּמְשַׁחְתָּא בְּמַתְקְלָא וּבִמְכִלְתָּא:
@721 מֹאזְנָוָן דִקְשׁוֹט מַתְקְלָן דִקְשׁוֹט מְכִילָן דִקְשׁוֹט וְהִינִין דִקְשׁוֹט יְהוֹן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן דִי אֲפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@722 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@723 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@724 וְלִבְנֵי יִשְׂרָאֵל תֵּימַר גְבַר גְבַר מִבְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בְּיִשְׂרָאֵל דִי יִתֵּן מִזַרְעֵהּ לְמוֹלֶךְ אִתְקְטָלָא יִתְקְטֵל עַמָא בֵית יִשְׂרָאֵל יִרְגְמֻנֵהּ בְּאַבְנָא:
@725 וַאֲנָא אֶתֵּן יָת רוּגְזִי בְגַבְרָא הַּהוּא וְאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ אֲרֵי מִזַרְעֵהּ יְהַב לְמוֹלֶךְ בְּדִיל לְסָאָבָא יָת מַקְדְשִׁי וּלְאַחַלָא יָת שְׁמָא דְקוּדְשִׁי:
@726 וְאִם מִכְבַּשׁ יִכְבְּשׁוּן עַמָא בֵית יִשְׂרָאֵל יָת עֵינֵיהוֹן מִן גַבְרָא הַהוּא בִּדְיָהֵב מִזַרְעֵהּ לְמוֹלֶךְ בְּדִיל דְלָא לְקַטָלָא יָתֵהּ:
@727 וֶאֱשַׁוֵי אֲנָא יָת רוּגְזִי בְגַבְרָא הַהוּא וּבִסְעָדוֹהִי וֶאֱשֵׁיצֵי יָתֵהּ וְיָת כָּל דְטָעָן בַּתְרוֹהִי לְמִטְעֵי בָּתַר מוֹלֶךְ מִגוֹ עַמְהוֹן:
@728 וֶאֱנַשׁ דִי יִתְפְּנֵי בָּתַר בִּדִין וּדְכוּרוּ לְמִטְעֵי בַתְרֵיהוֹן וְאֶתֵּן יָת רוּגְזִי בַּאֲנָשָׁא הַהִיא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@729 וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@730 וְתִטְּרוּן יָת קְיָמַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא:ייָ מַקְדִשְׁכוֹן:
@731 אֲרֵי גְבַר גְבַר דִי יְלוּט יָת אֲבוּהִי וְיָת אִמֵהּ אִתְקְטָּלָא יִתְקְטֵל אֲבוּהִי וְאִמֵהּ לַטּ קְטָלָא חַיָב:
@732 וּגְבַר דִי יְגוּף יָת אִתַּת גְבַר דִי יְגוּף יָת אִתַּת חַבְרֵהּ אִתְקְטָלָא יִתְקְטֵל גַיָפָא וְגַיַפְתָּא:
@733 וּגְבַר דִי יִשְׁכּוּב עִם אִתַּת אֲבוּהִי עֶרְיְתָא דַאֲבוּהִי גַלִי אִתְקַטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן קְטָלָא חַיָבִין:
@734 וּגְבַר דִי יִשְׁכּוּב יָת כַּלָתֵהּ אִתְקְטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן תִּבְלָא עֲבָדוּ קְטָלָא חַיָבִין:
@735 וּגְבַר דִי יִשְׁכּוּב יָת דְכוּרָא מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא עֲבָדוּ תַּרְוֵיהוֹן אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@736 וּגְבַר דִי יִסַב יָת אִתְּתָא וְיָת אִמַהּ עֵצַת חִטְאִין הִיא בְּנוּרָא יוֹקְדוּן יָתֵהּ וְיָתְהֶן וְלָא תְהֵי עֵצַת חִטְאִין בֵּינֵיכוֹן:
@737 וּגְבַר דִי יִתֵּן שְׁכָבְתֵּהּ בִּבְעִירָא אִתְקְטָלָא יִתְקְטֵל וְיָת בְּעִירָא תִּקְטְלוּן:
@738 וְאִתְּתָא דִי תִקְרַב לְכָל בְּעִירָא לְמִשְׁלַט בַּהּ וְתִקְטוֹל יָת אִתְּתָא וְיָת בְּעִירָא אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@739 וּגְבַר דִי יִסַב יָת אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֶחֱזֵי יָת עֶרְיְתַהּ וְהִיא תֶחֱזֵי יָת עֶרְיְתֵהּ קְלָנָא הוּא וְיִשְׁתֵּיצוּן לְעֵינֵי בְּנֵי עַמְהוֹן עֶרְיַת אֲחָתֵהּ גַלִי חוֹבֵהּ יְקַבֵּל:
@740 וּגְבַר דִי יִשְׁכּוּב יָת אִתְּתָא סוֹאֲבָתָא וִיגַלֵי יָת עֶרְיְתַהּ יָת קְלָנַהּ גַלִי וְהִיא תְגַלֵי יָת סוֹאֲבַת דְמָהָא וְיִשְׁתֵּיצוּן תַּרְוֵיהוֹן מִגוֹ עַמְהוֹן:
@741 וְעֶרְיַת אֲחַת אִמָךְ וַאֲחַת אָבוּךְ לָא תְגַלֵי אֲרֵי יָת קָרִיבֵהּ גַלִי חוֹבְהֶן יְקַבְּלוּן:
@742 וּגְבַר דִי יִשְׁכּוּב יָת אִתַּת אַח אֲבוּהִי עֶרְיַת אַח אֲבוּהִי גַלִי חוֹבְהֶן יְקַבְּלּוּן בְּלָּא וְלָד יְמוּתוּן:
@743 וּגְבַר דִי יִסַב יָת אִתַּת אֲחוּהִי מְרָחָקָא הִיא עֶרְיְתָא דַאֲחוּהִי גַלִי בְּלָא וְלָד יְהוֹן:
@744 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן וְלָא תְרוֹקֵן יָתְכוֹן אַרְעָא דִי אֲנָא מָעֵיל יָתְכוֹן תַּמָן לְמִתַּב בַּהּ:
@745 וְלָא תְהָכוּן בְּנִימוֹסֵי עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן אֲרֵי יָת כָּל אִלֵין עֲבָדוּ וְרָחִיק מֵימְרִי יָתְהוֹן:
@746 וַאֲמָרִית לְכוֹן אַתּוּן תִּירְתוּן יָת אַרְעֲהוֹן וַאֲנָא אֶתְּנִנַהּ לְכוֹן לְמֵירַת יָתַהּ אַרְעָא עַבְדָא חַלָב וּדְבָשׁ אֲנָא יְיָ אֱלָהָכוֹן דִי אַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא:
@747 וְתַפְרְשׁוּן בֵּין בְּעִירָא דַכְיָא לִמְסָאָבָא וּבֵין עוֹפָא מְסָאָבָא לִדְכֵי וְלָא תְשַׁקְצוּן יָת נַפְשָׁתֵיכוֹן בִּבְעִירָא וּבְעוֹפָא וּבְכֹל דִי תַרְחֵשׁ אַרְעָא דִי אַפְרֵשִׁית לְכוֹן לְסָאָבָא:
@748 וּתְהוֹן קֳדָמַי קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא יְיָ וְאַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא לְמֶהֱוֵי פָלְחִין קֳדָמַי:
@749 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בְהוֹן בִּדִין אוֹ דְכוּרוּ אִתְקְטָלָא יִתְקַטְלוּן בְּאַבְנָא יִרְגְמוּן יָתְהוֹן קְטָלָא חַיָבִין: פפפ:
@778 וַאֲמַר יְיָ לְמֹשֶׁה אֱמַר לְכַהֲנַיָא בְּנֵי אַהֲרֹן וְתֵימַר לְהוֹן עַל מִית לָא יִסְתָּאַב בְּעַמֵהּ:
@779 אֱלָהֵן לְקָרִיבֵהּ דְקָרִיב לֵהּ לְאִמֵהּ וְלַאֲבוּהִי וְלִבְרֵהּ וְלִבְרַתֵּהּ וְלַאֲחוּהִי:
@780 וְלַאֲחָתֵהּ בְּתֻלְתָּא דְקָרִיבָא לֵהּ דִי לָא הֲוַת לִגְבַר לַהּ יִסְתָּאָב:
@781 לָא יִסְתָּאַב רַבָּא בְעַמֵהּ לְאַחֲלוּתֵהּ:
@782 לָא יִמְרְטוּן מְרַט בְּרֵישְׁהוֹן וּפָאתָא דְדִקְנְהוֹן לָא יְגַלְחוּן וּבְבִשְׂרְהוֹן לָא יְחַבְּלוּן חִבּוּל:
@783 קַדִישִׁין יְהוֹן קֳדָם אֱלָהֲהוֹן וְלָא יְחַלוּן שְׁמָא דֶאֱלָהֲהוֹן אֲרֵי יָת קֻרְבָּנַיָא דַיְיָ קֻרְבַּן אֱלָהֲהוֹן אִנוּן מַקְרִיבִין וִיהוֹן קַדִישִׁין:
@784 אִתְּתָא מַטְעֲיָא וּמְחַלְלָא לָא יִסְבוּן וְאִתְּתָא דִמְתָרְכָא מִבַּעְלַהּ לָא יִסְבוּן אֲרֵי קַדִישׁ הוּא קֳדָם אֱלָהֵהּ:
@785 וּתְקַדְשִׁנֵהּ אֲרֵי יָת קֻרְבַּן אֱלָהָךְ הוּא מְקָרֵב קַדִישׁ יְהֵא לָךְ אֲרֵי קַדִישׁ אֲנָא יְיָ מְקַדִשְׁכוֹן:
@786 וּבַת גְבַר כָּהֵן אֲרֵי תִתְחַל לְמִטְעֵי מִקְדֻשַׁת אֲבוּהָ הִיא מִתַּחֲלָא בְּנוּרָא תִּתּוֹקָד:
@787 וְכַהֲנָא דְאִתְרַבָּא מֵאֲחוֹהִי דְיִתָּרִיק עַל רֵישֵׁהּ מִשְׁחָא דִרְבוּתָא וְדִי קָרִיב יָת קֻרְבָּנֵהּ לְמִלְבָּשׁ יָת לְבוּשַׁיָא יָת רֵישֵׁהּ לָא יְרַבֵּי פֵרוּעַ וּלְבוּשׁוֹהִי לָא יִבְזַע:
@788 וְעַל כָּל נַפְשַׁת מֵתָא לָא יֵיעוֹל לַאֲבוּהִי וּלְאִמֵהּ לָא יִסְתָּאָב:
@789 וּמִן מַקְדְשָׁא לָא יִפּוֹק וְלָא יַחֵל יָת מַקְדְשָׁא דֶאֱלָהֵהּ אֲרֵי כְּלִיל מְשַׁח רְבוּתָא דֶאֱלָהֵהּ עֲלוֹהִי אֲנָא יְיָ:
@790 וְהוּא אִתְּתָא בִבְתֻלְתָּהָא יִסָב:
@791 אַרְמְלָא וּמְתָרְכָא וְחַלִילָא מַטְעֲיָא יָת אִלֵין לָא יִסָב אֱלָהֵין בְּתֻלְתָּא מֵעַמֵהּ יִסַב אִתְּתָא:
@792 וְלָא יַחֵל זַרְעֵהּ בְּעַמֵהּ אֲרֵי אֲנָא יְיָ מְקַדְשֵׁהּ:
@793 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@794 מַלֵל עִם אַהֲרֹן לְמֵימָר גְבַר מִבְּנָיִךְ לְדָרֵיהוֹן דִי יְהֵּי בֵהּ מוּמָא לָא יִקְרַב לְקָרָבָא קֻרְבָּנָא קֳדָם אֱלָהֵהּ:
@795 אֲרֵי כָל גְבַר דִּי בֵהּ מוּמָא לָא יִקְרַב גְבַר עַוִיר אוֹ חֲגִיר אוֹ חָרִים אוֹ שָׂרִיע:
@796 אוֹ גְבַר דִי יְהֵי בֵהּ תְּבַר רַגְלָא אוֹ תְּבַר יְדָא:
@797 אוֹ גְבִין אוֹ דֻקָא אוֹ חִלִיז בְּעֵינֵהּ אוֹ גַרְבָן אוֹ חֲזָזָן אוֹ מְרִיס פַּחֲדִין:
@798 כָּל גְבַר דִי בֵהּ מוּמָא מִזַרְעָא דְאַהֲרֹן כַּהֲנָא לָא יִקְרַב לְקָרָבָא יָת קֻרְבָּנַיָא דַיְיָ מוּמָא בֵהּ יָת קֻרְבַּן אֱלָהֵהּ לָא יִקְרַב לְקָרָבָא:
@799 קֻרְבַּן אֱלָהֵהּ מִקֹדֶשׁ קוּדְשַׁיָא וּמִן קוּדְשַׁיָא יֵיכוּל:
@800 בְּרַם לְפָרֻכְתָּא לָא יֵיעוֹל וּלְמַדְבְּחָא לָא יִקְרַב אֲרֵי מוּמָא בֵהּ וְלָא יַחֵל יָת מַקְדְשַׁי אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@801 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל:
@802 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@803 מַלֵיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְיִפָּרְשׁוּן מִקוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל וְלָא יְחַלוּן יָת שְׁמָא דְקוּדְשִׁי דִי אִנוּן מְקַדְשִׁין קֳדָמַי אֲנָא יְיָ:
@804 אֱמַר לְהוֹן לְדָרֵיכוֹן כָּל גְבַר דִי יִקְרַב מִכָּל בְּנֵיכוֹן לְקוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ וְסֹאבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהִיא מִן קֳדָמַי אֲנָא יְיָ:
@805 גְבַר גְבַר מִזַרְעָא דְאַהֲרֹן וְהוּא סְגִיר אוֹ דָאִיב בְּקוּדְשַׁיָא לָא יֵיכוּל עַד דִי יִדְכֵּי וּדְיִקְרַב בְּכָל טְמֵא נַפְשָׁא אוֹ גְבַר דִי תִפּוֹק מִנֵהּ שִׁכְבַת זַרְעָא:
@806 אוֹ גְבַר דִי יִקְרַב בְּכָל רִחֲשָׁא דִי יִסְתָּאַב לֵהּ אוֹ בַאֲנָשָׁא דִי יִסְתָּאַב לֵהּ:לכָל סֹאבְתֵיהּ:
@807 אֱנַשׁ דִי יִקְרַב בֵּהּ וִיהֵי מְסָאָב עַד רַמְשָׁא וְלָא יֵיכוּל מִן קוּדְשַׁיָא אֱלָהֵן אַסְחֵי בִשׂרֵהּ בְּמַיָא:
@808 וּבְמֵעַל:שִׁמְשָׁא וְיִדְכֵּי וּבָתַר כֵּן יֵיכוּל מִן קוּדְשַׁיָא אֲרֵי לַחְמֵהּ הוּא:
@809 נְבִילָא וּתְבִירָא לָא יֵיכוּל לְאִסְתָּאָבָא בָהּ אֲנָא יְיָ:
@810 וְיִטְרוּן יָת מַטְּרַת מֵימְרִי וְלָא יְקַבְּלוּן עֲלוֹהִי חוֹבָא וִימוּתוּן בֵּהּ אֲרֵי יְחַלֻנֵהּ אֲנָא יְיָ מְקַדִשְׁהוֹן:
@811 וְכָל חִלוֹנַי לָא יֵיכוּל קוּדְשָׁא תּוֹתָבָא דְכַהֲנָא וַאֲגִירָא לָא יֵיכוּל קוּדְשָׁא:
@812 וְכָהֵן אֲרֵי יִקְנֵי נְפַשׁ קִנְיַן כַּסְפֵּהּ הוּא יֵיכוּל בֵּהּ וִילִיד בֵּיתֵהּ אִנוּן יֵיכְלוּן בְּלַחְמֵהּ:
@813 וּבַת כָּהֵן אֲרֵי תְהִי לִגְבַר חִלוֹנָי הִיא בְּאַפְרָשׁוּת קוּדְשַׁיָא לָא תֵיכוּל:
@814 וּבַת כָּהֵן אֲרֵי תְהֵי אַרְמְלָא וּמְתָרְכָא וּבַר לֵית לַהּ וּתְתוּב לְבֵית אֲבוּהָא כְּרַבְיוּתָהָא מִלַחְמָא דַאֲבוּהָא תֵּיכוּל וְכָל חִלוֹנַי לָא יֵיכוּל בֵּהּ:
@815 וּגְבַר אֲרֵי יֵיכוּל קוּדְשָׁא בְּשָׁלוּ וְיוֹסֵף חוּמְשֵׁהּ עֲלוֹהִי וְיִתֵּן לְכַהֲנָא יָת קוּדְשָׁא:
@816 וְלָא יְחַלוּן יָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל יָת דִי יַפְרְשׁוּן קֳדָם יְיָ:
@817 וִיקַבְּלוּן עֲלֵיהוֹן עֲוָיָן וְחוֹבִין בְּמֵיכָלְהוֹן בְּסוֹאֲבָא יָת קוּדְשֵׁיהוֹן אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@818 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@819 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא בְּיִשְׂרָאֵל דִי יְקָרֵב קֻרְבָּנֵהּ לְכָל נִדְרֵיהוֹן וּלְכָל נִדְבָתְהוֹן דִי יְקָרְבוּן קֳדָם יְיָ לַעֲלָתָא:
@820 לְרַעֲוָא לְכוֹן שְׁלִים דְכוּרָא בְּתוֹרֵי בְּאִמְרַיָא וּבְעִזַיָא:
@821 כֹּל דִי בֵהּ מוּמָא לָא תְקָרְבוּן אֲרֵי לָא לְרַעֲוָא יְהֵי לְכוֹן:
@822 וּגְבַר אֲרֵי יְקָרֵב נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְפָרָשָׁא נִדְרָא אוֹ לִנְדַבְתָּא בְּתוֹרֵי אוֹ בְעָנָא שְׁלִים יְהֵי לְרַעֲוָא כָּל מוּמָא לָא יְהֵי בֵהּ:
@823 עַוִיר אוֹ תְבִיר אוֹ פְסִיק אוֹ יַבְּלָן אוֹ גַרְבָן אוֹ חֲזָזָן לָא תְקָרְבוּן אִלֵין קֳדָם יְיָ וְקֻרְבָּנָא לָא תִתְּנוּן מִנְהוֹן עַל מַדְבְּחָא קֳדָם יְיָ:
@824 וְתוֹר וְאִמַר יַתִּיר וְחַסִיר נְדַבְתָּא תַּעְבֵּד יָתֵהּ וּלְנִדְרָא לָא יְהֵי לְרַעֲוָא:
@825 וְדִי מְרִיס וְדִי רְסִיס וְדִי שְׁלִיף וְדִי גְזִיר לָא תְקָרְבוּן קֳדָם יְיָ וּבְאַרְעֲכוֹן לָא תַעְבְּדוּן:
@826 וּמִן בַּר עַמְמִין לָא תְקַרְבוּן יָת קֻרְבַּן אֱלָהֲכוֹן מִכָּל אִלֵין אֲרֵי חִבּוּלְהוֹן בְּהוֹן מוּמָא בְהוֹן לָא לְרַעֲוָא יְהוֹן לְכוֹן:
@827 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@828 תּוֹר אוֹ אִמָר אוֹ עִזָא אֲרֵי יִתְיְלִיד וִיהֵי שִׁבְעָא יוֹמִין בָּתַר אִמֵהּ וּמִיוֹמָא תְמִינָאָה וּלְהַלָא יִתִּרְעִי לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ:
@829 וְתוֹרְתָּא אוֹ שֵׂיתָא לֵהּ וְלִבְרֵהּ לָא תִכְּסוּן בְּיוֹמָא חָד:
@830 וַאֲרֵי תִּכְּסוּן נִכְסַת תּוֹדְתָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵהּ:
@831 בְּיוֹמָא הַהוּא יִתְאֲכֵל לָא תַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא אֲנָא יְיָ:
@832 וְתִטְרוּן פִּקוּדַי וְתַעֲבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@833 וְלָא תְחַלְלוּן יָת שְׁמָא דְקוּדְשַׁי וְאִתְקַדַשׁ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲנָא יְיָ מְקַדִשְּׁכוֹן:
@834 דְאַפִּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֵאלָהָא אֲנָא יְיָ:
@835 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@836 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ אִלֵין אִנוּן מוֹעֲדָי:
@837 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שְׁבָתָא מְעָרַע קַדִישׁ כָּל עִבִידָא לָא תַעֲבְּדוּן שַׁבְּתָא הִיא קֳדָם יְיָ בְּכֹל מוֹתְבָנֵיכוֹן:
@838 אִלֵין מוֹעֲדַיָא דַיְיָ מְעָרְעֵי קַדִישׁ דִי תְעָרְעוּן יָתְהוֹן בְּזִמְנֵיהוֹן:
@839 בְּיַרְחָא קַדְמָאָה בְּאַרְבְּעַת עַשְׂרָא לְיַרְחָא בֵּין שִׁמְשַׁיָא פִּסְחָא קֳדָם יְיָ:
@840 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא דְפַטִירַיָא קֳדָם יְיָ שִׁבְעָא יוֹמִין פַּטִיר תֵּיכְלוּן:
@841 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@842 וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@843 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@844 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַחְצְדוּן יָת חֲצָדַהּ וְתַיְתוּן יָת עוּמְרָא רֵישׁ חֲצָדְכוֹן לְוָת כַּהֲנָא:
@845 וִירִים יָת עוּמְרָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן מִבָּתַר יוֹמָא טָבָא יְרִימִנֵהּ כַּהֲנָא:
@846 וְתַעֲבְּדוּן בְּיוֹמָא דַאֲרָמוּתְכוֹן יָת עוּמְרָא אִמַר שְׁלִים בַּר שַׁתֵּהּ לַעֲלָתָא קֳדָם יְיָ:
@847 וּמִנְחָתֵהּ תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא דְפִילָא בִמְשַׁח קֻרְבָּנָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא וְנִסְכֵּהּ חַמְרָא רַבְעוּת הִינָא:
@848 וּלְחֵם וּקְלִי וּפֵרוּכָן לָא תֵיכְלוּן עַד כְּרַן יוֹמָא הָדֵין עַד אַיְתוֹאֵיכוֹן יָת קֻרְבָּן אֱלָהָכוֹן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@849 וְתִמְנוּן לְכוֹן מִבָּתַר יוֹמָא טָּבָא מִיוֹם אַיְתוֹאֵיכוֹן יָת עוּמְרָא דַאֲרָמוּתָא שִׁבְעָא שָׁבוּעִין שַּׁלְמִין יְהֶוְיָן (נ''א תְּהֶוְיָן):
@850 עַד מִבָּתַר שְׁבוּעֲתָא שְׁבִיעֵתָא תִּמְנוּן חַמְשִׁין יוֹמִין וּתְקַרְבוּן מִנְחָתָא חֲדַתָּא קֳדָם יְיָ:
@851 מִמוֹתְבָנֵיכוֹן תַּיְתוּן לְחֵם אֲרָמוּתָא תַּרְתֵּין (גְרִיצַן) תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא יְהֶוְיָן חֲמִיעַ יִתְאַפְיָן בִּכּוּרִין קֳדָם יְיָ:
@852 וּתְקָרְבוּן עַל לַחְמָא שִׁבְעָא אִמְרִין שַׁלְמִין בְּנֵי שְׁנָא וְתוֹר בַּר תּוֹרֵי חַד וְדִכְרִין תְּרֵין יְהוֹן עֲלָתָא קֳדָם יְיָ וּמִנְחָתְהוֹן וְנִסְכֵּיהוֹן קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@853 וְתַעְבְּדוּן צְפִיר בַּר עִזֵי חַד לְחַטָאתָא וּתְרֵין אִמְרִין בְּנֵי שְׁנָא לְנִכְסַת קוּדְשַׁיָא:
@854 וִירִים כַּהֲנָא יָתְהוֹן עַל לְחֵם בִּכּוּרַיָא אֲרָמוּתָא קֳדָם יְיָ עַל תְּרֵין אִמְרִין קוּדְשָׁא יְהוֹן קֳדָם יְיָ לְכַהֲנָא:
@855 וּתְעָרְעוּן בִּכְרַן יוֹמָא הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן קְיַם עָלָם בְּכָל מוֹתְבָנֵיכוֹן לְדָרֵיכוֹן:
@856 וּבְמֶחֱצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ בְּמֶחֱצָדָךְ וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהֲכוֹן:
@857 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@858 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּיַרְחָא שְׁבִיעָאָה בְּחַד לְיַרְחָא יְהֵי לְכוֹן נְיָחָא דוּכְרָן יַבָּבָא מְעָרַע קַדִישׁ:
@859 כָּל עִבִידַת פָלְחָנָא לָא תַעֲבְּדוּן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@860 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@861 בְּרַם בְּעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין יוֹמָא דְכִפּוּרַיָא הוּא מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@862 וְכָל עִבִידָא לָא תַעֲבְּדוּן בִּכְרַן יוֹמָא הָדֵין אֲרֵי יוֹמָא דְכִפּוּרַיָא הוּא לְכַפָּרָא עֲלֵיכוֹן קֳדָם יְיָ אֱלָהֲכוֹן:
@863 אֲרֵי כָל אֲנָשָׁא דִי לָא מִתְעַנֵי בִּכְרַן יוֹמָא הָדֵין וְיִשְׁתֵּיצֵי מֵעַמָהָא:
@864 וְכָל אֱנַשׁ דִי תַעְבֵּד כָּל עִבִידָא בִּכְרַן יוֹמָא הָדֵין וְאוֹבֵד יָת אֲנָשָׁא הַהִיא מִגוֹ עַמָהּ:
@865 כָּל עִבִידָא לָא תַעֲבְּדוּן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@866 שְׁבַת שְׁבָתָא הוּא לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן בְּתִשְׁעָה לְיַרְחָא בְּרַמְשָׁא מֵרַמְשָׁא עַד רַמְשָׁא תְּנוּחוּן נְיַחֲכוֹן:
@867 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@868 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּחַמְשָׁא עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה הָדֵין חַגָא דִמְטַלַיָא שִׁבְעַת יוֹמִין קֳדָם יְיָ:
@869 בְּיּוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@870 שִׁבְעָא יוֹמִין תְּקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ בְּיוֹמָא תְמִינָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ כְּנֵשׁ תְּהוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@871 אִלֵין מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ עֲלָתָא וּמִנְחָתָא נִכְסַת קוּדְשִׁין וְנִסוּכִין פִּתְגַם יוֹם בְּיוֹמֵהּ:
@872 בַּר שַׁבַּיָא דַיְיָ וּבַר מַתְּנָתֵיכוֹן וּבַר כָּל נִדְרֵיכוֹן וּבַר כָּל נִדְבָתֵיכוֹן דִי תִתְּנוּן קֳדָם יְיָ:
@873 בְּרַם בְּחַמְשָׁא עֲשַׂר יוֹמָא לְיַרְחָא שְׁבִיעָאָה בְּמִכְנְשֵׁיכוֹן יָת עֲלַלַת אַרְעָא תְּחַגוּן יָת חַגָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא קַדְמָאָה נְיָחָא וּבְיוֹמָא תְמִינָאָה נְיָחָא:
@874 וְתִסְבוּן לְכוֹן בְּיוֹמָא קַדְמָאָה פֵּרֵי אִילָנָא אֶתְרוֹגִין וְלֻלָבִין וַהֲדַסִין וְעַרְבִין דִנְחָל וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן שַׁבְעַת יוֹמִין:
@875 וּתְחַגוּן יָתֵהּ חַגָא קֳדָם יְיָ שַׁבְעַת יוֹמִין בְּשַׁתָּא קְיַם עָלָם לְדָרֵיכוֹן בְּיַרְחָא שְׁבִיעָאָה תְּחַגוּן יָתֵהּ:
@876 בִּמְטַלַיָא תֵיתְבוּן שַׁבְעַת יוֹמִין כָּל יַצִיבָא בְּיִשְׂרָאֵל יֵתְבוּן בִּמְטַלַיָא:
@877 בְּדִיל דְיִדְעוּן דָרֵיכוֹן אֲרֵי בִמְטַלָיוּת עֲנָנֵי אוֹתֵבִית יָת בְּנֵי יִשְׂרָאֵל בְּאַפָּקוּתִי יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@878 וּמַלִיל מֹשֶׁה יָת סְדַר מוֹעֲדַיָא דַיְיָ וְאַלֵפִנוּן לִבְנֵי יִשְׂרָאֵל:
@879 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@880 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מְשַׁח זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@881 מִבָּרָא לְפָרֻכְתָּא דְסַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא יַסְדַר יָתֵהּ אַהֲרֹן מֵרַמְשָׁא עַד צַפְרָא קֳדָם יְיָ תְּדִירָא קְיָם עָלָם לְדָרֵיכוֹן:
@882 עַל מְנַרְתָּא דָכִיתָא יַסְדַר יָת בּוֹצִינַיָא קֳדָם יְיָ תְּדִירָא:
@883 וְתִסַב סֻלְתָּא וְתֵיפֵי יָתַהּ תַּרְתָּא עַשְׂרֵי גְרִיצָן תְּרֵין עֶשְׂרוֹנִין תְּהֵי גְרִצְתָּא חֲדָא:
@884 וּתְשַׁוִי יָתְהוֹן תַּרְתֵּי סִדְרִין שִׁית סִדְרָא עַל פָּתוֹרָא דַכְיָא קֳדָם יְיָ:
@885 וְתִתֵּן עַל סִדְרָא לְבֹנְתָּא דָכִיתָא וּתְהֵי לִלְחֵם לְאִדְכַּרְתָּא קֻ:רבָּנָא:קָדָם יְיָ:
@886 בְּיוֹמָא דְשַׁבְּתָא בְּיוֹמָא דְשַׁבְּתָא יַסְדְרִנֵהּ קֳדָם יְיָ תְּדִירָא מִן קֳדָם בְּנֵי יִשְׂרָאֵל קְיַם עָלָם:
@887 וּתְהֵי לְאַהֲרֹן וְלִבְנוֹהִי וְיֵכְלֻנֵהּ בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הוּא לֵהּ מִקֻרְבָּנַיָא דַיְיָ קְיַם עָלָם:
@888 וּנְפַק בַּר אִתְּתָא בַת יִשְׂרָאֵל וְהוּא בַּר גְבַר מִצְרָאָה בְּגוֹ בְּנֵי יִשְׂרָאֵל וּנְצוֹ בְּמַשְׁרִיתָא בַּר אִתְּתָא בַת יִשְׂרָאֵל וְגַבְרָא בַּר יִשְׂרָאֵל:
@889 וּפָרֵשׁ בַּר אִתְּתָא בַת יִשְׂרָאֵל יָת שְׁמָא וְאַרְגֵז וְאַיְתִיאוּ יָתֵהּ לְוָת מֹשֶׁה וְשׁוּם אִמֵהּ שְׁלֹמִית בַּת דִבְרִי לְשִׁבְטָא דְדָן:
@890 וְאַסְרוֹהִי בְּבֵית מַטְרָא עַד דְיִתְפָּרַשׁ לְהוֹן עַל גְזֵרַת מֵימְרָא דַיְיָ:
@891 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@892 אַפֵּק יָת דְאַרְגֵז לְמִבָּרָא לְמַשְּׁרִיתָא וְיִסְמְכוּן כָּל דִי שְׁמָעוּ יָת יְדֵיהוֹן עַל רֵישֵׁהּ וְיִרְגְמוּן יָתֵהּ כָּל כְּנִשְּׁתָּא:
@893 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר גְבַר גְבַר דִי יַרְגֵז קֳדָם אֱלָהֵהּ וִיקַבֵּל חוֹבֵהּ:
@894 וְדִי פָרֵשׁ שְׁמָא דַיְיָ אִתְקְטָּלָא יִתְקְטֵל מִרְגַם יִרְגְמוּן בֵּהּ כָּל כְּנִשְׁתָּא כְּגִיוֹרָא כְּיַצִיבָא בְּפָרָשׁוּתֵהּ שְׁמָא יִתְקְטֵל:
@895 וּגְבַר אֲרֵי יִקְטוֹל כָּל נַפְשָׁא דַאֲנָשָׁא אִתְקְטָלָא יִתְקְטֵל:
@896 וּדְיִקְטוֹל נְפַשׁ בְּעִירָא יְשַׁלְמִנַהּ נַפְשָׁא חֳלַף נַפְשָׁא:
@897 וּגְבַר אֲרֵי יִתֵּן מוּמָא בְּחַבְרֵהּ כְּמָא דִי עֲבַד כֵּן יִתְעֲבֵד לֵיהּ:
@898 תַּבְרָא חֳלַף תַּבְרָא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא כְּמָא דִי יִתֵּן מוּמָא בַּאֲנָשָׁא כֵּן יִתְיְהֵב בֵּהּ:
@899 וּדְיִקְטוֹל בְּעִירָא יְשַׁלְמִנַהּ וּדְיִקְטוֹל אֲנָשָׁא יִתְקְטֵל:
@900 דִינָא חֲדָא יְהֵי לְכוֹן כְּגִיוֹרָא כְּיַצִיבָא יְהֵי אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@901 וּמַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל וְאַפִּיקוּ יָת דְאַרְגֵז לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵהּ אַבְנָא וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּמָא דִי פַּקֵיד יְיָ יָת מֹשֶׁה: פפפ:
@919 וּמַלִיל יְיָ עִם מֹשֶׁה בְּטּוּרָא דְסִינַי לְמֵימָר:
@920 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעַלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַשְּׁמֵט אַרְעָא שְׁמִטְתָא קֳדָם יְיָ:
@921 שִׁית שְׁנִין תִּזְרַע חַקְלָךְ וְשִׁית שְׁנִין תִכְסַח כַּרְמָךְ וְתִכְנוֹשׁ יָת עֲלַלְתָּהּ:
@922 וּבְשַׁתָּא שְׁבִיעֲתָא נְיַח שְׁמִטְתָא יְהֵי לְאַרְעָא דְתַשְׁמֵט קֳדָם יְיָ חַקְלָךְ לָא תִזְרַע וְכַרְמָךְ לָא תִכְסָח:
@923 יָת כַּתֵּי דַחֲצָדָךְ לָא תֶחֱצַד וְיָת עִנְבֵי שִׁבְקָךְ לָא תִקְטוֹף שְׁנַת שְׁמִטְתָא יְהֵי לְאַרְעָא:
@924 וּתְהֵי שְׁמִטַת אַרְעָא לְכוֹן לְמֵיכַל לָךְ וּלְעַבְדָךְ וּלְאַמְתָךְ וְלַאֲגִירָךְ וּלְתוֹתָבָךְ דְדָיְרִין עִמָךְ:
@925 וְלִבְעִירָךְ וּלְחַיְתָא דִי בְאַרְעָךְ תְּהֵי כָל עֲלַלְתַּהּ לְמֵיכָל:
@926 וְתִמְנֵי לָךְ שְׁבַע שְׁמִיטִין דִשְׁנִין שְׁבַע שְׁנִין שְׁבַע זִמְנִין וִיהוֹן לָךְ יוֹמֵי שְּׁבַע שְׁמִטִין דִשְׁנִין אַרְבְּעִין וְתֵשַׁע שְׁנִין:
@927 וְתַעֲבַר שׁוֹפָר יַבָּבָא בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא בְּיוֹמָא דְכִפּוּרַיָא תַּעַבְרוּן שׁוֹפָרָא בְּכָל אַרְעֲכוֹן:
@928 וּתְקַדְשׁוּן יָת שְׁנַת חַמְשִׁין שְׁנִין וְתַקְרוּן חֵרוּתָא בְּאַרְעָא לְכָל יָתְבָהָא יוֹבֵלָא הִיא תְּהֵי לְכוֹן וּתְתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ וּגְבַר לְזַרְעִיתֵהּ תְּתוּבוּן:
@929 יוֹבֵלָא הִיא שְׁנַת חַמְשִׁין שְׁנִין תְּהֵי לְכוֹן לָא תִזְרְעוּן וְלָא תַחְצְדוּן יַת כַּתָּהָא וְלָא תִקְטְפוּן יַת שִׁבְקָהָא:
@930 אֲרֵי יוֹבֵלָא הִיא קוּדְשָׁא תְּהֵי לְכוֹן מִן חַקְלָא תֵּיכְלוּן יָת עֲלַלְתָּהּ:
@931 בְּשַׁתָּא דְיוֹבֵלָא הָדָא תְּתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ:
@932 וַאֲרֵי תְזַבֵּן זְבִינִין לְחַבְרָךְ אוֹ תִזְבֵּן מִידָא דְחַבְרָךְ לָא תוֹנוּן גְבַר יָת אֲחוֹהִי:
@933 בְּמִנְיַן שְׁנַיָא בָּתַר יוֹבֵלָא תִּזְבֵּן מִן חַבְרָךְ בְּמִנְיַן שְׁנֵי עֲלַלְתָּא יְזַבֶּן לָךְ:
@934 לְפוּם סְגִיאוּת שְׁנַיָא תַּסְגֵי זְבִינוֹהִי וּלְפוּם זְעֵרוּת שְׁנַיָא תַּזְעֵר זְבִינוֹהִי אֲרֵי מִנְיַן עֲלַלְתָּא הוּא מְזַבֵּן לָךְ:
@935 וְלָא תוֹנוּן גְבַר יָת חַבְרֵהּ וְתִדְחַל מֵאֱלָהָךְ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@936 וְתַעְבְּדוּן יָת קְיָמַי וְיָת דִינַי תִּטְּרוּן וְתַעֲבְּדוּן יָתְהוֹן וְתֵיתְבוּן עַל אַרְעָא לְרָחֲצָן:
@937 וְתִתֵּן אַרְעָא אִבַּהּ וְתֵיכְלוּן לְמִשְׂבָּע וְתֵיתְבוּן לְרָחֲצָן עֲלַהּ:
@938 וַאֲרֵי תֵימְרוּן מָא נֵיכוּל בְּשַׁתָּא שְׁבִיעֵתָא הָא לָא נִזְרָע וְלָא נִכְנוֹשׁ יָת עֲלַלְתָּנָא:
@939 וֶאֱפַקֵד יָת בִּרְכְּתִי לְכוֹן בְּשַׁתָּא שְׁתִיתֵתָא וְתַעְבֵּד יָת עֲלַלְתָּא לִתְלַת שְׁנִין:
@940 וְתִזְרְעוּן יָת שַׁתָּא תְמִינֵתָא וְתֵיכְלוּן מִן עֲלַלְתָּא עַתִּיקָא עַד שַׁתָּא תְשִׁיעֵתָא עַד מֵעַל עֲלַלְתַּהּ תֵּיכְלוּן עַתִּיקָא:
@941 וְאַרְעָא לָא תִזְדַבַּן לַחֲלוּטִין אֲרֵי דִילִי אַרְעָא אֲרֵי דַיָרִין וְתוֹתָבִין אַתּוּן קֳדָמַי:
@942 וּבְכֹל אַרְעָא אַחֲסַנְתְּכוֹן פֻּרְקָנָא תִּתְּנוּן לְאַרְעָא:
@943 אֲרֵי יִתְמַסְכַּן אָחוּךְ וִיזַבֵּן מֵאַחֲסַנְתֵּהּ וְיֵיתֵי פָרִיקֵהּ דְקָרִיב לֵהּ וְיִפְרוֹק יָת זְבִינֵי אֲחוּהִי:
@944 וּגְבַר אֲרֵי לָא יְהֵי לֵהּ פָּרִיק וְתַדְבֵּק יְדֵהּ וְיַשְׁכַּח כְּמִסַת פֻּרְקָנֵהּ:
@945 וִיחַשֵׁב יָת שְׁנֵי זְבִינוֹהִי וְיָתֵב יָת מוֹתָרָא לִגְבַר דִי זַבֶּן לֵהּ וִיתוּב לְאַחֲסַנְתֵּהּ:
@946 וְאִם לָא תַשְׁכַּח יְדֵהּ כְּמִסַת אֲתֵב לֵהּ וִיהֵי זְבִינוֹהִי בִּידָא דִזְבַן יָתֵהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִפּוֹק בְּיוֹבֵלָא וִיתוּב לְאַחֲסַנְתֵּהּ:
@947 וּגְבַר אֲרֵי יְזַבֵּן בֵּית מוֹתַב קַרְתָּא מַקְפָא שׁוּר וּתְהֵי פוּרְקָנֵהּ עַד מִשְׁלַם שַׁתָּא דִזְבִינוֹהִי עִדָן בְּעִדָן תְּהֵי פוּרְקָנֵהּ:
@948 וְאִם לָא יִתְפָּרַק עַד מִשְׁלַם לֵהּ שַׁתָּא שְׁלֶמְתָּא וִיקוּם בֵּיתָא דִי בְקַרְתָּא דִי לֵהּ שׁוּרָא לַחֲלוּטִין לְדִי זְבַן יָתֵהּ לְדָרוֹהִי לָא יִפּוֹק בְּיוֹבֵלָא:
@949 וּבָתֵּי פַצְחַיָא דִי לֵית לְהוֹן שׁוּר מַקַף סְחוֹר סְחוֹר עַל חֲקַל אַרְעָא יִתְחַשָׁב פֻּרְקָנָא תְּהֵי לֵהּ וּבְיוֹבֵלָא יִפּוֹק:
@950 וְקִרְוֵי לֵיוָאֵי בָּתֵּי קִרְוֵי אַחֲסַנְתְּהוֹן פּוּרְקַן עָלָם תְּהֵי לְלֵיוָאֵי:
@951 וְדִי יִפְרוֹק מִן לֵיוָאֵי וְיִפּוֹק זְבִין בֵּיתָא וְקַרְתָּא אַחֲסַנְתֵּהּ בְּיוֹבֵלָא אֲרֵי בָתֵּי קִרְוֵי לֵיוָאֵי הִיא אַחְסַנְתְּהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@952 וַחֲקַל רְוַח קִרְוֵיהוֹן לָא יִזְדַבָּן אֲרֵי אַחֲסָנַת עָלָם הוּא לְהוֹן:
@953 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ וּתְמוּט יְדֵהּ עִמָךְ וְתַתְקַף בֵּהּ דַיַר וְתוֹתָב וִיחֵי עִמָךְ:
@954 לָא תִסַב מִנֵהּ חִבּוּלְיָא וְרִבִּיתָא וְתִדְחַל מֵאֱלָהָךְ וִיחֵי אָחוּךְ עִמָךְ:
@955 יָת כַּסְפָּךְ לָא תִתֵּן לֵהּ בְּחִבּוּלְיָא וּבְרִבִּיתָא לָא תִתֵּן מֵיכְלָךְ:
@956 אֲנָא יְיָ אֱלָהֲכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם לְמִתַּן לְכוֹן יָת אַרְעָא דִכְנַעַן לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ:
@957 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ עִמָךְ וְיִזְדַבַּן לָךְ לָא תִפְלַח בֵּהּ פָּלְחַן עַבְדִין:
@958 כַּאֲגִירָא כְתוֹתָבָא יְהֵי עִמָךְ עַד שַׁתָּא דְיוֹבֵלָא יִפְלַח עִמָךְ:
@959 וְיִפּוֹק מֵעִמָךְ הוּא וּבְנוֹהִי עִמֵהּ וִיתוּב לְזַרְעִיתֵהּ וּלְאַחֲסָנַת אֲבָהָתוֹהִי יְתוּב:
@960 אֲרֵי עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם לָא יִזְדַבְּנוּן זְבוּן עַבְדִין:
@961 לָא תִפְלָח בֵּהּ בְּקַשְׁיוּ וְתִדְחַל מֵאֱלָהָךְ:
@962 וְעַבְדָךְ וְאַמְתָךְ דִי יְהוֹן לָךְ מִן עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן מִנְהוֹן תִּקְנוּן עַבְדִין וְאַמְהָן:
@963 וְאַף מִבְּנֵי תוֹתָבַיָא עָרְלַיָא דְדָיְרִין עִמְכוֹן מִנְהוֹן תִּקְנוּן וּמִזַרְעִיתְהוֹן דְעִמְכוֹן דִי אִתְיְלִידוּ בְּאַרְעֲכוֹן וִיהוֹן לְכוֹן לְאַחֲסָנָא:
@964 וְתַחֲסוּן יָתְהוֹן לִבְנֵיכוֹן בַּתְרֵיכוֹן לִירוּתַת אַחֲסָנָא לְעָלָם בְּהוֹן תִּפְלְחוּן וּבְאֲחֵיכוֹן בְּנֵי יִשְׂרָאֵל גְבַר בַּאֲחוּהִי לָא תִפְלַח בֵּהּ בְּקַשְׁיוּ:
@965 וַאֲרֵי תַדְבֵּק יַד עָרֵל וְתוֹתָב עִמָךְ וְיִתְמַסְכַּן אָחוּךְ עִמֵהּ וְיִזְדַבַּן לְעָרֵל תּוֹתָב עִמָךְ אוֹ לְאַרְמַי זַרְעִית גִיוֹרָא:
@966 בָּתַר דְיִזְדַבַּן פֻּרְקָנָא תְּהֵי לֵהּ חַד מֵאֲחוֹהִי יִפְרְקִנֵהּ:
@967 אוֹ אַח אֲבוּהִּי אוֹ בַר אַח אֲבוּהִי יִפְרְקִנֵהּ אוֹ מִקָרִיב בִּשְׂרֵהּ מִזַרְעִיתֵהּ יִפְרְקִנֵהּ אוֹ דְתַדְבֵּק יְדֵהּ וְיִתְפָּרָק:
@968 וִיחַשֵׁב עִם זָבְנֵהּ מִשַׁתָּא דְאִזְדַבַּן לֵהּ עַד שַׁתָּא דְיוֹבֵלָא וִיהֵי כְּסַף זְבִינוֹהִי בְּמִנְיַן שְׁנַיָא כְּיוֹמֵי אֲגִירָא יְהֵי עִמֵהּ:
@969 אִם עוֹד סְגִיוּת בִּשְׁנַיָא לְפוּמְהֵן יָתֵב פֻּרְקָנֵהּ מִכְּסַף זְבִינוֹהִי:
@970 וְאִם זְעֵר יִשְׁתָּאַר בִּשְׁנַיָא עַד שַׁתָּא דְיוֹבֵלָא וִיחַשֶׁב לֵהּ כְּפוּם שְׁנוֹהִי יָתֵב יָת פּוּרְקָנֵהּ:
@971 כַּאֲגִיר שְׁנָא בִּשְׁנָא יְהֵי עִמֵהּ לָא יִפְלַח בֵּהּ בְּקַשְׁיוּ לְעֵינָיךְ:
@972 וְאִם לָא יִתְפָּרַק בְּאִלֵין וְיִפּוֹק בְּשַׁתָּא דְיוֹבֵלָא הוּא וּבְנוֹהִי עִמֵהּ:
@973 אֲרֵי דִילִי בְנֵי יִשְׂרָאֵל עַבְדִין עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@974 לָא תַעְבְּדוּן לְכוֹן טַעֲוָן וְצֶלֶם וְקָמָא לָא תְקִימוּן לְכוֹן וְאֶבֶן סָגְדָא לָא תִתְּנוּן בְּאַרְעֲכוֹן לְמִסְגֻד עֲלַהּ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@975 יָת יוֹמֵי שַׁבַּיָא דִילִי תִטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ: פפפ:
@998 אִם בִּקְיָמַי תְּהָכוּן וְיָת פִּקוֹדַי תִּטְרוּן וְתַעֲבְּדוּן יָתְהוֹן:
@999 וְאֶתֵּן מַטְּרְכוֹן בְּעִדָנְהוֹן וְתִתֵּן אַרְעָא עֲלַלְתָּהּ וְאִילַן חַקְלָא יִתֵּן אִבֵּהּ:
@1000 וִיעָרַע לְכוֹן דְיָשָׁא יָת קְטָפָא וּקְטָפָא יְעָרַע לְאַפּוֹקֵי בַר זַרְעָא וְתֵיכְלוּן לַחְמְכוֹן לְמִשְׂבַּע וְתֵיתְבוּן לְרָחְצָן בְּאַרְעַכוֹן:
@1001 וְאֶתֵּן שְׁלָמָא בְּאַרְעָא וְתִשְׁרוּן וְלֵית דְמָנִיד וֶאֱבַטֵל חַיְתָא בִשְׁתָּא מִן אַרְעָא וּדְקַטְלִין בְּחַרְבָּא לָא יְעִדוּן בְּאַרְעֲכוֹן:
@1002 וְתִרְדְפוּן יָת בַּעֲלֵי דְבָבֵיכוֹן וְיִפְּלוּן קֳדָמֵיכוֹן לְחַרְבָּא:
@1003 וְיִרְדְפוּן מִנְכוֹן חַמְשָׁא מְאָה וּמְאָה מִנְכוֹן לְרִבּוֹתָא יֵיעִירְקוּן וְיִפְּלוּן בַּעֲלֵי דְבָבֵיכוֹן קֳדָמֵיכוֹן לְחַרְבָּא:
@1004 וְאֶתְפְּנֵי בְּמֵימְרִי לְאוֹטָבָא לְכוֹן וְאַפֵּשׁ יָתְכוֹן וְאַסְגֵי יָתְכוֹן וַאֲקֵם יָת קְיָמִי עִמְכוֹן:
@1005 וְתֵיכְלוּן עַתִּיקָא דְעַתִּיק וְעַתִּיקָא מִן קֳדָם חֲדַתָּא תְּפַנוּן:
@1006 וְאֶתֵּן מַשְׁכְּנִי בֵּינֵיכוֹן וְלָא יְרַחֵק מֵימְרִי יָתְכוֹן:
@1007 וְאַשְׁרֵי שְׁכִינְתִּי בֵּינֵיכוֹן וְאֶהֱוֵי לְכוֹן לֶאֱלָהּ וְאַתּוּן תְּהוֹן קֳדָמַי לְעָם:
@1008 אֲנָא יְיָ אֱלָהֲכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם מִלְמֶהֱוֵי לְהוֹן עַבְדִין וְתַבָּרִית נִיר עַמְמַיָא מִנְכוֹן וְדַבָּרִית יָתְכוֹן לְחֵרוּתָא:
@1009 וְאִם לָא תְקַבְּלוּן לְמֵימְרִי וְלָא תַעְבְּדוּן יָת כָּל פִּקוּדַיָא הָאִלֵין:
@1010 וְאִם בִּקְיָמַי תְּקוֹצוּן וְאִם יָת דִינַי תְּרַחֵק נַפְשְׁכוֹן בְּדִיל דְלָא לְמֶעְבַּד יָת כָּל פִּקוֹדַי לְאַשְׁנָיוּתְכוֹן יָת קְיָמִי:
@1011 אַף אֲנָא אֶעְבֶּד דָא לְכוֹן וְאַסְעַר עֲלֵיכוֹן בַּהֶלְתָּא יָת שַׁחֶפְתָּא וְיָת קַדַחְתָּא מְחַשְׁכָן עַיְנִין וּמַפְּחַן נְפָשׁ וְתִזְרְעוּן לְרֵקָנוּן זַרְעֲכוֹן וְיֵיכְלֻנֵהּ בַּעֲלֵי דְבָבֵיכוֹן:
@1012 וְאֶתֵּן רוּגְזִי בְּכוֹן וְתִתַּבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן וְיִרְדוּן בְּכוֹן סַנְאֵכוֹן וְתֵעִירְקוּן וְלֵית דְרָדִיף יָתְכוֹן:
@1013 וְאִם עַד אִלֵין לָא תְקַבְּלוּן לְמֵימְרִי וְאוֹסֵף לְמִרְדֵי יָתְכוֹן שְׁבַע עַל חוֹבֵיכוֹן:
@1014 וְאֶתְבַּר יָת יְקַר תָּקְפְּכוֹן וְאֶתֵּן יָת שְׁמַיָא דִי עִלָוֵיכוֹן תַּקִיפִין כְּפַרְזְלָא מִלַאֲחָתָא מִטְרָא וְאַרְעָא דִתְחוֹתֵיכוֹן חֲסִינָא כִּנְחָשָׁא מִלְמֶעְבַּד פֵּירִין:
@1015 וִיסוּפוּן לְרֵיקָנוּ חֵילֵיכוֹן וְלָא תִתֵּן אַרְעֲכוֹן יָת עֲלַלְתָּהּ וְאִילַן אַרְעָא לָא יִתֵּן אִבֵּהּ:
@1016 וְאִם תְּהָכוּן קֳדָמַי בְּקַשְׁיוּ וְלָא תֵיבוּן לְקַבָּלָא לְמֵימְרִי וְאוֹסֵף לֶאֱתָאָה עֲלֵיכוֹן מָחָא שְׁבַע כְּחוֹבֵיכוֹן:
@1017 וֶאֶגָרֵי בְכוֹן יָת חֵוַת בָּרָא וּתְתַכֵּל יָתְכוֹן וּתְשֵׁיצֵי יָת בְּעִירְכוֹן וְתַזְעֵר יָתְכוֹן וִיצַדְיָן אוֹרְחָתְכוֹן:
@1018 וְאִם בְּאִלֵין לָא תִתְרְדוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:
@1019 וְאֵהַךְ אַף אֲנָא עִמְכוֹן בְּקַשְׁיוּ וְאַלְקֵי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:
@1020 וְאַיְתִי עֲלֵיכוֹן דְקָטְלִין בְּחַרְבָּא וְיִתְפָּרְעוּן מִנְכוֹן פּוּרְעֲנוּתָא עַל דַעֲבַרְתּוּן עַל פִתְגָמֵי אוֹרַיְתָא וְתִתְכַּנְשׁוּן לְקִרְוֵיכוֹן וֶאֱגָרֵי מוֹתָנָא בֵּינֵיכוֹן וְתִתְמַסְרוּן בִּידָא דְסָנְאָה:
@1021 בִּדְאִתְּבַר לְכוֹן סָעִיד מֵיכְלָא וְיָפְיָן עֲסַר נְשִׁין לַחְמְכוֹן בְּתַנוּרָא חַד וִיתִיבוּן לַחְמְכוֹן בְּמַתְקְלָא וְתוֹכְלוּן וְלָא תִשְׂבְּעוּ ן:
@1022 וְאִם בְּדָא לָא תְקַבְּלוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:
@1023 וְאֵהַךְ עִמְכוֹן בִּתְקוֹף רְגַז וְאִרְדֵי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:
@1024 וְתֵיכְלוּן בְּשַׂר בְּנֵיכוֹן וּבְשַׂר בְּנָתֵיכוֹן תֵּיכְלוּן:
@1025 וֶאֱשֵׁיצֵי יָת בָּמָתֵיכוֹן וֶאֱקַצֵץ יָת חֲנִיסְנְסֵיכוֹן וְאֶתֵּן יָת פִּגְרֵיכוֹן עַל פִּגוּר טַעֲוָתְכוֹן וִירַחֵק מֵימְרִי יָתְכוֹן:
@1026 וְאֶתֵּן יָת קִרְוֵיכוֹן צָדָא וְאֶצְדֵי יָת מַקְדְשֵׁיכוֹן וְלָא אֲקַבֵּל בְּרַעֲוָא קֻרְבַּן כְּנִשָׁתְכוֹן:
@1027 וְאֶצְדֵי אֲנָא יָת אַרְעָא וִיצָרְיוּן עֲלַהּ בַּעֲלֵי דְבָבֵיכוֹן דְיָתְבוּן בַּהּ:
@1028 וְיָתְכוֹן אֲבַדַר בֵּינֵי עַמְמַיָא וֶאֱגָרֵי בַתְרֵיכוֹן דְקַטְלִין בְּחַרְבָּא וּתְהֵי אַרְעֲכוֹן צָדְיָא וְקִרְוֵיכוֹן יְהוֹן חָרְבָּא:
@1029 בְּכֵן תַּרְעֵי אַרְעָא יָת שְׁמִטָהָא כֹּל יוֹמִין דִי צְדִיאַת וְאַתּוּן בְּאַרַע בַּעֲלֵי דְבָבֵיכוֹן בְּכֵן תַּשְׁמֵט אַרְעָא וְתִרְעֵי יָת שְׁמִטָּהָא:
@1030 כָּל יוֹמִין דִי צְדִיאַת תַּשְׁמֵט יָת דִי לָא שְׁמֵטַת בִּשְׁמִטֵיכוֹן כַּד הֲוֵיתוּן יָתְבִין עֲלַהּ:
@1031 וּדְיִשְׁתַּאֲרוּן בְּכוֹן וְאָעֵל תַּבְרָא בְּלִבְּהוֹן בְּאַרְעֲתָא דְסַנְאֵיהוֹן וְיִרְדוֹף יָתְהוֹן קַל טַרְפָּא דְשַׁקִיף וְיֵעַרְקֻן כְּמֵעִירוֹק מִן קֳדָם דְקַטְלִין בְּחַרְבָּא וְיִפְּלוּן וְלֵית דְרָדִיף:
@1032 וְיִתַּקְלוּן גְבַר בְּאָחוּהִי כְּמִקֳדָם דְקָטְלִין בְּחַרְבָּא וְרָדִיף לָיִת וְלָא תְהֵי לְכוֹן תְּקוּמָה קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@1033 וְתֵבְדוּן בֵּינֵי עַמְמַיָא וּתְגַמַר יָתְכוֹן אֲרַע בַּעֲלֵי דְבָבֵיכוֹן:
@1034 וּדְיִשְׁתַּאֲרוּן בְּכוֹן יִתִּמְסוּן בְּחוֹבֵיהוֹן בְּאַרְעֲתָא בַּעֲלֵי דְבָבֵיכוֹן וְאַף בְּחוֹבֵי אֲבָהַתְהוֹן בִּישַׁיָא דַאֲחִידִין בִּידֵיהוֹן יִתִּמְסוּן:
@1035 וִיוַדוּן יָת חוֹבֵיהוֹן וְיָת חוֹבֵי אֲבָהַתְהוֹן בְּשִׁקְרְהוֹן דְשַׁקָרוּ קֳדָמַי וְאַף דִי הַלִיכוּ קֳדָמַי בְּקַשְׁיוּ:
@1036 אַף אֲנָא אֱהַךְ עִמְהוֹן בְּקַשְׁיוּ וְאָעֵיל יָתְהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן אוֹ בְּכֵן יִתָּבַר לִבְּהוֹן טַפְשָׁא וּבְכֵן יִרְעוּן יָת חוֹבֵיהוֹן:
@1037 וְדָכִירְנָא יָת קְיָמִי דְעִם יַעֲקוֹב וְאַף יָת קְיָמִי דְעִם יִצְחָק וְאַף יָת קְיָמִי דְעִם אַבְרָהָם אֲנָא דָכִיר וְאַרְעָא אֲנָא דָכִיר:
@1038 וְאַרְעָא תִתְרְטֵשׁ מִנְהוֹן וְתַרְעֵי יָת שְׁמִיטָהָא בְּדִצְדִיאַת מִנְהוֹן וְאִנוּן יִרְעוּן יָת חוֹבֵיהוֹן לְוָטִין חֳלַף בִּרְכָן אַיְתִי עֲלֵיהוֹן בְּדִיל דִבְדִינַי קָצוּ וְיָת קְיָמַי רְחֵקַת נַפְשְׁהוֹן:
@1039 וְאַף בְּרַם דָא בְּמֶהֱוֵיהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן לָא אַרְטֵשִׁנוּן וְלָא אַרְחֵקִנוּן לְשֵׁיצָיוּתְהוֹן לְאַשְׁנָאָה קְיָמִי עִמְהוֹן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן:
@1040 וְדָכִירְנָא לְהוֹן קְיַם קַדְמָאֵי דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְעֵינֵי עַמְמַיָא לְמֶהֱוֵי לְהוֹן לֵאלָהָא אֲנָא יְיָ:
@1041 אִלֵין קְיָמַיָא וְדִינַיָא וְאוֹרָיָתָא דִי יְהַב יְיָ בֵּין מֵימְרֵהּ וּבֵין בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְסִינַי בִּידָא דְמֹשֶׁה:
@1042 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@1043 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר אֲרֵי יַפְרֵשׁ נְדַר בְּפֻרְסַן נַפְשָׁתָא קֳדָם יְיָ:
@1044 וִיהֵי פֻרְסָנֵהּ דְכוּרָא מִבַּר עֶסְרִין שְׁנִין וְעַד בַּר שִׁתִּין שְׁנִין וִיהֵי פֻרְסָנֵהּ חַמְשִׁין סִלְעִין דִכְסַף בְּסִלְעֵי קוּדְשָׁא:
@1045 וְאִם נְקוּבְתָא הִיא וִיהֵי פֻרְסָנֵהּ תְּלָתִין סִלְעִין:
@1046 וְאִם מִבַּר חֲמֵשׁ שְׁנִין וְעַד בַּר עֶסְרִין שְׁנִין וִיהֵי פֻרְסָנֵהּ דְכוּרָא עֶסְרִין סִלְעִין וְלִנְקוּבְתָא עֲסַר סִלְעִין:
@1047 וְאִם מִבַּר יַרְחָא וְעַד בַּר חֲמֵשׁ שְׁנִין וִיהֵי פֻרְסָנֵהּ דְכוּרָא חֲמֵשׁ סִלְעִין דִכְסָף וְלִנְקוּבְתָא פֻרְסָנֵהּ תְּלַת סִלְעִין דִכְסָף:
@1048 וְאִם מִבַּר שִׁתִּין שְׁנִין וּלְעֵלָא אִם דְכוּרָא וִיהֵי פֻרְסָנֵהּ חֲמֵשׁ עֶסְרֵי סִלְעִין וְלִנְקוּבְתָא עֲסַר סִלְעִין:
@1049 וְאִם מִסְכֵּן הוּא מִפֻּרְסָנֵהּ וִיקִימִנֵהּ קֳדָם כַּהֲנָא וְיִפְרוֹס יָתֵהּ כַּהֲנָא עַל מֵימַר דִי תַדְבֵּק יְדָא דְנוֹדֵרָא יִפְרְסִנֵהּ כַּהֲנָא:
@1050 וְאִם בְּעִירָא דִי יְקָרְבוּן מִנַהּ קֻרְבָּנָא קֳדָם יְיָ כָּל דִי יִתֵּן מִנֵהּ קֳדָם יְיָ יְהֵי קוּדְשָׁא:
@1051 לָא יְחַלְפִנֵהּ וְלָא יְעִבַּר יָתֵהּ טַּב בְּבִישׁ אוֹ בִישׁ בְּטָב וְאִם חַלָפָא יְחַלֵף בְּעִירָא בִּבְעִירָא וִיהֵי הוּא וְחִלוּפֵי יְהֵי קַדִישׁ:
@1052 וְאִם כָּל בְּעִירָא מְסָאָבָא דִי לָא יְקָרְבוּן מִנַהּ קֻרְבָּנָא קֳדָם יְיָ וִיקִים יָת בְּעִירָא קֳדָם כַּהֲנָא:
@1053 וְיִפְרוֹס כַּהֲנָא יָתַהּ בֵּין טַב וּבֵין בִּישׁ כְּפֻרְסָנָא דְכַהֲנָא כֵּן יְהֵי:
@1054 וְאִם מִפְרַק יִפְרְקֻנֵהּ וְיוֹסֵף חֻמְשֵׁה עַל פֻּרְסָנֵהּ:
@1055 וּגְבַר אֲרֵי יַקְדֵשׁ יָת בֵּיתֵהּ קוּדְשָׁא קֳדָם יְיָ וְיִפְרְסִנֵהּ כַּהֲנָא בֵּין טַב וּבֵין בִּישׁ כְּמָא דִי יִפְרוֹס יָתֵהּ כַּהֲנָא כֵּן יְקוּם:
@1056 וְאִם דְאַקְדֵשׁ יִפְרוֹק יָת בֵּיתֵהּ וְיוֹסֵף חוֹמֶשׁ כְּסַף פֻּרְסָנֵהּ עֲלוֹהִי וִיהֵי לֵהּ:
@1057 וְאִם מֵחֲקַל אַחֲסַנְתֵּהּ יַקְדִישׁ גְבַר קֳדָם יְיָ וִיהֵי פֻרְסָנֵהּ לְפוּם זַרְעֵהּ בַּר זְרַע כּוֹר שְׂעוֹרִין בְּחַמְשִׁין סִלְעִין דִכְסָף:
@1058 אִם מִשַּׁתָּא דְיוֹבֵלָא יַקְדֵשׁ חַקְלֵהּ כְּפֻרְסָנֵהּ יְקוּם:
@1059 וְאִם בָּתַר יוֹבֵלָא יַקְדֵשׁ חַקְלֵהּ וִיחַשֵׁב לֵהּ כַּהֲנָא יָת כַּסְפָּא עַל מֵימַר שְׁנַיָא דְאִשְׁתָּאָרָן עַד שַׁתָּא דְיוֹבֵלָא וְיִתִּמְנַע מִפֻּרְסָנֵהּ:
@1060 וְאִם מִפְרַק יִפְרוֹק יָת חַקְלָא דְאַקְדֵשׁ יָתֵהּ וְיוֹסֵף חוֹמֶשׁ כְּסַף פֻּרְסָנֵהּ עֲלוֹהִי וִיקוּם לֵהּ:
@1061 וְאִם לָא יִפְרוֹק יָת חַקְלָא וְאִם זַבִּין יָת חַקְלָא לִגְבַר אָחֳרָן לָּא יִתְפָּרַק עוֹד:
@1062 וִיהֵי חַקְלָא בְּמִפְּקֵהּ בְּיוֹבֵלָא קוּדְשָׁא קֳדָם יְיָ כַּחֲקַל חֶרְמָא לְכַהֲנָא תְּהֵי אַחֲסַנְתֵּהּ:
@1063 וְאִם יָת חֲקַל זְבִינוֹהִי דִי לָא מֵחֲקַל אַחֲסַנְתֵּהּ יַקְדֵשׁ קֳדָם יְיָ:
@1064 וִיחַשֶׁב לֵהּ כַּהֲנָא יָת מִנְיַן פֻּרְסָנֵהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִתֵּן יָת פֻרְסָנֵהּ בְּיוֹמָא הַהוּא קוּדְשָׁא קֳדָם יְיָ:
@1065 בְּשַׁתָּא דְיוֹבֵלָא יְתוּב חַקְלָא לִדְזַבְנֵהּ מִנֵהּ לִדְדִילֵהּ אַחֲסָנַת אַרְעָא:
@1066 וְכָל פֻּרְסָנֵּה יְהֵי בְּסִלְעֵי קוּדְשָׁא עֶסְרִין מָעִין יְהֵי סִלְעָא:
@1067 בְּרַם בּוּכְרָא דִי יִתְבַּכַּר קֳדָם יְיָ בִּבְעִירָא לָא יַקְדֵשׁ גְבַר יָתֵהּ אִם תּוֹר אִם אִמַר דַיְיָ הוּא:
@1068 וְאִם בִּבְעִירָא מְסָאָבָא וְיִפְרוֹק בְּפֻרְסָנֵהּ וְיוֹסֵף חֻמְשֵׁהּ עֲלוֹהִי וְאִם לָא יִתְפָּרַק וְיִזְדַבַּן בְּפֻרְסָנֵהּ:
@1069 בְּרַם כָּל חֶרְמָא דִי יַחְרֵם גְבַר קֳדָם יְיָ מִכָּל דִי לֵהּ מֵאֲנָשָׁא וּבְעִירָא וּמֵחֲקַל אַחֲסַנְתֵּהּ לָא יִזְדַבַּן וְלָא יִתְפָּרָק כָּל חֶרְמָא קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ:
@1070 כָּל חֶרְמָא דִי יִתַּחְרַם מִן אֱנָשָׁא לָא יִתְפָּרָק אִתְקְטָלָא יִתְקְטֵל:
@1071 וְכָל מַעְשְׂרָא דְאַרְעָא מִזַרְעָא דְאַרְעָא מִפֵּירֵי אִילָנָא דַיְיָ הוּא קוּדְשָׁא קֳדָם יְיָ:
@1072 וְאִם מִפְרַק יִפְרוֹק גְבַר מִמַעַשְׂרֵהּ חֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי:
@1073 וְכָל מַעֲשַׂר תּוֹרִין וְעָן כֹּל דְיֵעִבַּר תְּחוֹת חֻטְרָא עֲשִׂירָאָה יְהֵי קַדִישׁ קֳדָם יְיָ:
@1074 לָא יְבַקַר בֵּין טַב לְבִישׁ וְלָא יְחַלְפִנֵהּ וְאִם חַלָפָא יְחַלְפִנֵהּ וִיהֵי הוּא וְחִלוּפֵהּ יְהֵי קוּדְשָׁא לָא יִתְפָּרָק:
@1075 אִלֵין פִּקוֹדַיָא דִי פַקִיד יְיָ יָת מֹשֶׁה לְוָת בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְסִינָי: חזק:

@1 **ויקרא אל משה.** לכל דברות ולכל אמירות ולכל צוויים קדמה קריאה, לשון חבה, לשון שמלאכי השרת משתמשים בו, שנאמר (ישעיה ו ג) וקרא זה אל זה, אבל לנביאי אמות העולם נגלה עליהן בלשון עראי וטמאה, שנאמר (במדבר כג ד) ויקר אלהים אל בלעם: **ויקרא אל משה.** הקול הולך ומגיע לאזניו, וכל ישראל לא שומעין. יכול אף להפסקות היתה קריאה, תלמוד לומר וידבר, לדבור היתה קריאה, ולא להפסקות. ומה היו הפסקות משמשות, לתן רוח למשה להתבונן בין פרשה לפרשה ובין ענין לענין, קל וחומר להדיוט הלומד מן ההדיוט: **אליו.** למעט את אהרן. ר' יהודה בן בתירא אומר שלשה עשר דברות נאמרו בתורה למשה ולאהרן, וכנגדן נאמרו שלשה עשר מיעוטין, ללמדך שלא לאהרן נאמרו אלא למשה שיאמר לאהרן. ואלו הן שלשה עשר מיעוטין לדבר אתו, מדבר אליו, וידבר אליו, ונועדתי לך, כלן בתורת כהנים. יכול שמעו את קול הקריאה, תלמוד לומר קול לו, קול אליו (במדבר ז פט) , משה שמע, וכל ישראל לא שמעו: **מאהל מועד.** מלמד שהיה הקול נפסק ולא היה יוצא חוץ לאהל. יכול מפני שהקול נמוך, תלמוד לומר את הקול (שם) , מהו הקול, הוא הקול המפורש בתהלים (כט ד. ה) קול ה' בכח קול ה' בהדר, קול ה' שובר ארזים, אם כן למה נאמר מאהל מועד, מלמד שהיה הקול נפסק. כיוצא בו (יחזקאל י ה) וקול כנפי הכרובים נשמע עד החצר החיצונה, יכול (מפני) שהקול נמוך, תלמוד לומר (שם) כקול אל שדי בדברו, אם כן למה נאמר עד החצר החיצונה, שכיון שמגיע שם היה נפסק: **מאהל מועד לאמר.** יכול מכל הבית, תלמוד לומר מעל הכפורת. יכול מעל הכפורת כלה, תלמוד לומר מבין שני הכרובים: **לאמר.** צא ואמר להם דברי כבושים, בשבילכם הוא נדבר עמי, שכן מצינו שכל שלשים ושמונה שנה שהיו ישראל במדבר כמנדים, מן המרגלים ואלך, לא נתיחד הדבור עם משה, שנאמר (דב' ב טז) ויהי כאשר תמו כל אנשי המלחמה למות וידבר ה' אלי לאמר, אלי היה הדבור. דבר אחר צא ואמור להם דברי והשיבני אם יקבלום, כמו שנאמר (שמות יט ח) וישב משה את דברי העם וגו' :
@2 **אדם כי יקריב מכם.** כשיקריב, בקרבנות נדבה דבר הענין: **אדם.** למה נאמר, מה אדם הראשון לא הקריב מן הגזל, שהכל היה שלו, אף אתם לא תקריבו מן הגזל: **הבהמה.** יכול אף חיה בכלל, תלמוד לומר בקר וצאן: **מן הבהמה.** ולא כלה, להוציא את הרובע ואת הנרבע: **מן הבקר.** להוציא את הנעבד: **מן הצאן.** להוציא את המקצה: **ומן הצאן.** להוציא את הנוגח שהמית. כשהוא אומר למטה מן הענין (פסוק ג) מן הבקר, שאין תלמוד לומר, להוציא את הטרפה: **תקריבו.** מלמד ששנים מתנדבים עולה בשותפות: **קרבנכם.** מלמד שהיא באה נדבת צבור, היא עולת קיץ המזבח הבאה מן המותרות:
@3 **זכר.** ולא נקבה. כשהוא אומר זכר למטה, שאין תלמוד לומר, זכר ולא טומטום ואנדרוגינוס: **תמים.** בלא מום: **אל פתח אהל מועד.** מטפל בהבאתו עד העזרה. מהו אומר יקריב יקריב, אפלו נתערבה עולת ראובן בעולת שמעון, יקריב כל אחת לשם מי שהוא. וכן עולה בחלין, ימכרו החלין לצרכי עולות, והרי הן כלן עולות ותקרב כל אחת לשם מי שהוא. יכול אפלו נתערבה בפסולין או בשאינו מינו, תלמוד לומר יקריבנו: **יקריב אתו.** מלמד שכופין אותו. יכול בעל כרחו, תלמוד לומר לרצונו, הא כיצד כופין אותו עד שיאמר רוצה אני: **לפני ה' וסמך.** אין סמיכה בבמה:
@4 **על ראש העולה.** להביא עולת חובה לסמיכה ולהביא עולת הצאן: **העלה.** פרט לעולת העוף: **ונרצה לו.** על מה הוא מרצה לו, אם תאמר על כריתות ומיתות בית דין או מיתה בידי שמים או מלקות, הרי ענשן אמור, הא אינו מרצה אלא על עשה ועל לאו שנתק לעשה:
@5 **ושחט' והקריבו' הכהנים.** מקבלה ואלך מצות כהנה, למד על השחיטה שכשרה בזר: **לפני ה'.** בעזרה: **והקריבו.** זו קבלה שהיא הראשונה ומשמעה לשון הולכה, למדנו ששתיהן בבני אהרן: **בני אהרן.** יכול חללים, תלמוד לומר הכהנים: **את הדם וזרקו את הדם.** מה תלמוד לומר דם דם שתי פעמים, להביא את שנתערב במינו או בשאינו מינו. יכול אף בפסולים או בחטאות הפנימיות או בחטאות החיצוניות, שאלו למעלה והיא למטה, תלמוד לומר במקום אחר את דמו: **וזרקו.** עומד למטה וזורק מן הכלי לכתל המזבח למטה מחוט הסיקרא כנגד הזויות, לכך נאמר סביב, שיהא הדם נתן בארבע רוחות המזבח. או יכול יקיפנו כחוט, תלמוד לומר וזרקו, ואי אפשר להקיף בזריקה. אי וזרקו יכול בזריקה אחת, תלמוד לומר סביב, הא כיצד נותן שתי מתנות שהן ארבע: **אשר פתח אהל מועד.** ולא בזמן שהוא מפורק:
@6 **והפשיט את העלה.** מה תלמוד לומר העלה, לרבות את כל העולות להפשט ונתוח: **אתה לנתחיה.** ולא נתחיה לנתחים:
@7 **ונתנו אש.** אף על פי שהאש יורדת מן השמים, מצוה להביא מן ההדיוט: **בני אהרן הכהן.** כשהוא בכהונו, הא אם עבד בבגדי כהן הדיוט, עבודתו פסולה:
@8 **בני אהרן הכהנים.** כשהם בכהונם, הא כהן הדיוט שעבד בשמונה בגדים, עבודתו פסולה: **את הנתחים את הראש.** לפי שאין הראש בכלל הפשט, שכבר התז בשחיטה, לפיכך הצרך למנותו לעצמו: **ואת הפדר.** למה נאמר, ללמדך שמעלהו עם הראש ומכסה בו את בית השחיטה, וזהו דרך כבוד של מעלה: **אשר על המזבח.** שלא יהיו הגזירין יוצאין חוץ למערכה:
@9 **עלה.** לשם עולה יקטירנו: **אשה.** כשישחטנו יהא שוחטו לשם האש. וכל אשה לשון אש פויאד''א בלע''ז : **ניחוח.** נחת רוח לפני, שאמרתי ונעשה רצוני:
@10 **ואם מן הצאן.** וי''ו מוסיף על ענין ראשון. ולמה הפסיק, לתן רוח למשה להתבונן בין פרשה לפרשה: **מן הצאן מן הכבשים או מן העזים.** הרי אלו שלשה מיעוטין פרט לזקן, לחולה ולמזוהם:
@11 **על ירך המזבח.** על צד המזבח: **צפנה לפני ה'.** ואין צפון בבמה:
@14 **מן העוף.** ולא כל העוף, לפי שנאמר (ויקרא כב יט) תמים זכר בבקר בכשבים ובעזים, תמות וזכרות בבהמה, ואין תמות וזכרות בעופות, יכול אף מחסר אבר, תלמוד לומר מן העוף: **התרים.** גדולים ולא קטנים: **בני היונה.** קטנים ולא גדולים: **מן התרים או מן בני היונה.** פרט לתחלת הצהוב, שבזה ושבזה שהוא פסול, שגדול הוא אצל בני יונה וקטן אצל תורים:
@15 **והקריבו.** אפלו פרידה אחת יביא: **הכהן ומלק.** אין מליקה בכלי אלא בעצמו של כהן. קוצץ בצפרנו ממול העורף וחותך מפרקתו עד שמגיע לסימנין וקוצצן: **ונמצה דמו.** לשון מיץ אפים (משלי ל לג) , כי אפס המץ (ישעיה טז ד) , כובש בית השחיטה על קיר המזבח והדם מתמצה ויורד: **ומלק' והקטיר' ונמצה.** אפשר לומר כן, מאחר שהוא מקטיר הוא מוצה, אלא מה הקטרה הראש בעצמו והגוף בעצמו, אף מליקה כן. ופשוטו של מקרא מסורס הוא ומלק והקטיר, וקודם הקטרה, ונמצה דמו כבר:
@16 **מראתו.** מקום הרעי וזה הזפק: **בנצתה.** עם בני מעיה. ונוצה לשון דבר המאוס, כמו כי נצו גם נעו (איכה ד טו) וזה שתרגם אנקלוס באוכליה. וזהו מדרשו של אבא יוסי בן חנן, שאמר נוטל את הקרקבן עמה. ורבותינו זכרונם לברכה אמרו קודר סביב הזפק בסכין כעין ארבה ונוטלו עם הנוצה שעל העור. בעולת בהמה, שאינה אוכלת אלא באבוס בעליה, נאמר (פסוק יג) והקרב והכרעים ירחץ במים והקטיר, ובעוף, שנזון מן הגזל, נאמר והשליך, את המעים, שאכל מן הגזל: **אצל המזבח קדמה.** במזרחו של כבש: **אל מקום הדשן.** מקום שנותנין שם תרומת הדשן בכל בקר ודשון מזבח הפנימי והמנורה. וכלם נבלעים שם במקומן:
@17 **ושסע.** אין שסוע אלא ביד, וכן הוא אומר בשמשון (שופטים יד ו) וישסעהו כשסע הגדי: **בכנפיו.** עם כנפיו, אינו צריך למרוט כנפי נוצתו: **בכנפיו.** נוצה ממש. והלא אין לך הדיוט שמריח ריח רע של כנפים נשרפים ואין נפשו קצה עליו, ולמה אמר הכתוב והקטיר, כדי שיהא המזבח שבע ומהדר בקרבנו של עני: **לא יבדיל.** אינו מפרקו לגמרי לשתי חתכות, אלא קורעו מגבו. נאמר בעוף ריח ניחוח, ונאמר בבהמה ריח ניחוח, לומר לך אחד המרבה ואחד הממעיט, ובלבד שיכון את לבו לשמים:
@18 **ונפש כי תקריב.** לא נאמר נפש בכל קרבנות נדבה אלא במנחה, מי דרכו להתנדב מנחה, עני, אמר הקדוש ברוך הוא מעלה אני עליו כאלו הקריב נפשו: **סלת יהיה קרבנו.** האומר הרי עלי מנחה סתם, מביא מנחת סלת, שהיא הראשונה שבמנחות ונקמצת כשהיא סלת, כמו שמפורש בענין. לפי שנאמרו כאן חמשה מיני מנחות, וכלן באות אפויות קודם קמיצה חוץ מזו, לכך קרויה מנחת סלת: **סלת.** אין סלת אלא מן החטין, שנאמר (שמות כט ב) סלת חטים, ואין מנחה פחותה מעשרון, שנאמר (ויק' יד כא) ועשרון סלת למנחה, עשרון לכל מנחה: **ויצק עליה שמן.** על כלה: **ונתן עליה לבנה.** על מקצתה, מניח קמץ לבונה עליה לצד אחד. ומה ראית לומר כן, שאין רבוי אחר רבוי בתורה אלא למעט. דבר אחר שמן על כלה, מפני שהוא נבלל עמה ונקמץ עמה, כמו שנאמר (פסוק ב) מסלתה ומשמנה, ולבונה על מקצתה, שאינה נבללת עמה ולא נקמצת עמה, שנאמר (פסוק ב) על כל לבנתה, שלאחר שקמץ מלקט את הלבונה כלה מעליה ומקטירה: **ויצק' ונתן' והביאה.** מלמד שיציקה ובלילה כשרים בזר:
@19 **הכהנים וקמץ.** מקמיצה ואלך מצות כהנה: **וקמץ משם.** ממקום שרגלי הזר עומדות, ללמדך שהקמיצה כשרה בכל מקום בעזרה, אף באחת עשרה אמה של מקום דריסת רגלי ישראל: **מלא קמצו.** יכול מבורץ, מבצבץ ויוצא לכל צד, תלמוד לומר במקום אחר (ויק' ו ח) והרים ממנו בקמצו, אין לך כשר אלא מה שבתוך הקומץ. אי בקמצו יכול חסר, תלמוד לומר מלא. הא כיצד, חופה שלש אצבעותיו על פס ידו, וזהו קומץ במשמע לשון העברית: **על כל לבנתה.** לבד כל הלבונה יהא הקומץ מלא: **לבנתה והקטיר.** אף הלבונה בהקטרה: **מלא קמצו מסלתה ומשמנה.** הא אם קמץ ועלה בידו גרגיר מלח או קורט לבונה פסולה: **אזכרתה.** הקומץ העולה לגבוה הוא זכרון המנחה, שבו נזכר בעליה לטובה ולנחת רוח:
@20 **לאהרן ולבניו.** כהן גדול נוטל חלק בראש שלא במחלוקת, וההדיוט במחלוקת: **קדש קדשים.** היא להם: **מאשי ה'.** אין להם חלק בה אלא לאחר מתנות האשים:
@21 **וכי תקרב** וגו' **.** שאמר הרי עלי מנחת מאפה תנור, ולמד הכתוב שיביא או חלות או רקיקין, החלות בלולות, והרקיקין משוחין. ונחלקו רבותינו במשיחתן יש אומרים, מושחן וחוזר ומושחן עד שיכלה כל השמן שבלוג, שכל המנחות טעונות לוג שמן. ויש אומרים מושחן כמין כי יונית ושאר השמן נאכל בפני עצמו לכהנים. מה תלמוד לומר בשמן בשמן שתי פעמים, להכשיר שמן שני ושלישי היוצא מן הזיתים, ואין צריך שמן ראשון אלא למנורה, שנאמר בו (שמות כז כ) זך. ושנינו במנחות (עו א) כל המנחות האפויות לפני קמיצתן ונקמצות על ידי פתיתה, כלן באות עשר עשר חלות, והאמור בה רקיקין, באה עשרה רקיקין:
@22 **ואם מנחה על המחבת.** שאמר הרי עלי מנחת מחבת. וכלי הוא שהיה במקדש, שאופין בו מנחה על האור בשמן, והכלי אינו עמוק אלא צף, ומעשה המנחה שבתוכו קשין, שמתוך שהיא צפה, האור שורף את השמן. וכלן טעונות שלש מתנות שמן, יציקה, ובלילה, ומתן שמן בכלי קודם עשיתן: **סלת בלולה בשמן.** מלמד שבוללן בעודן סלת:
@23 **פתות אתה פתים.** לרבות כל המנחות, הנאפות קודם קמיצה, לפתיתה: **ויצקת עליה שמן מנחה הוא.** לרבות כל המנחות ליציקה. יכול אף מנחת מאפה תנור כן, תלמוד לומר עליה, אוציא את החלות ולא אוציא את הרקיקין, תלמוד לומר היא:
@24 **מרחשת.** כלי הוא שהיה במקדש עמוק, ומתוך שהיא עמוקה שמנה צבור ואין האור שורפו, לפיכך מעשה מנחה העשויין לתוכה רוחשין. כל דבר רך על ידי משקה נראה כרוחש ומנענע:
@25 **אשר יעשה מאלה.** מאחד מן המינים הללו: **והקריבה.** בעליה אל הכהן: **והגישה.** הכהן: **אל המזבח.** מגישה לקרן דרומית מערבית של מזבח:
@26 **את אזכרתה.** היא הקומץ:
@28 **וכל דבש.** כל מתיקת פרי קרויה דבש:
@29 **קרבן ראשית תקריבו.** מה יש לך להביא מן השאור ומן הדבש קרבן ראשית שתי הלחם של עצרת הבאים מן השאור, שנאמר (ויק' כג יז) חמץ תאפינה, ובכורים מן הדבש, כמו בכורי תאנים ותמרים:
@30 **מלח ברית.** שהברית כרותה למלח מששת ימי בראשית, שהבטחו המים התחתונים לקרב במזבח במלח, ונסוך המים בחג: **על כל קרבנך.** על עולת בהמה ועוף ואימורי כל הקדשים כלן:
@31 **ואם תקריב.** הרי אם משמש בלשון כי, שהרי אין זה רשות, שהרי במנחת העומר הכתוב מדבר, שהיא חובה, וכן (במדבר לו ד) ואם יהיה היובל וגו' : **מנחת בכורים.** במנחת העומר הכתוב מדבר, שהיא באה אביב בשעת בשול התבואה, ומן השעורים היא באה. נאמר כאן אביב, ונאמר להלן (שמות ט לא) כי השעורה אביב: **קלוי באש.** שמיבשין אותה על האור באבוב של קלאים, שאלולי כן אינה נטחנת בריחים, לפי שהיא לחה: **גרש כרמל.** גרוסה בעודה לחה: **גרש.** לשון שבירה וטחינה, גורסה בריחים של גרוסות, כמו (איכה ג טז) ויגרס בחצץ, וכן גרסה נפשי (תהלים קיט כ) : **כרמל.** בעוד הכר מלא, שהתבואה לחה ומלאה בקשין שלה, ועל כן נקראים המלילות כרמל, וכן (מלכים ב' ד מב) וכרמל בצקלונו:
@34 **שלמים.** שמטילים שלום בעולם. דבר אחר שלמים שיש בהם שלום למזבח ולכהנים ולבעלים:
@36 **ואת כל החלב** וגו' **.** להביא חלב שעל הקבה, דברי רבי ישמעאל. רבי עקיבא אומר להביא חלב שעל הדקין:
@37 **הכסלים.** פלנק''ש בלע''ז . שהחלב שעל הכליות, כשהבהמה חיה, הוא בגובה הכסלים והם מלמטה, וזהו החלב שתחת המתנים, שקורין בלע''ז לונביל''ש , לובן הנראה למעלה בגובה הכסלים, ובתחתיתו הבשר חופהו: **היתרת.** הוא דופן המסך, שקורין איברי''ש ובלשון ארמי חצרא דכבדא: **על הכבד.** שיטול מן הכבד עמה מעט. ובמקום אחר הוא אומר (ויק' ט י) ואת היותרת מן הכבד: **על הכבד על הכליות.** לבד מן הכבד ולבד מן הכליות יסירנה לזו:
@38 **על העלה.** מלבד העולה. למדנו שתקדים עולת תמיד לכל קרבן על המערכה:
@40 **אם כשב.** לפי שיש באימורי הכשב מה שאין באימורי העז, שהכשב אליתו קרבה, לכך נחלקו לשתי פרשיות:
@41 **וזרקו.** שתי מתנות שהן ארבע, ועל ידי הכלי הוא זורק, ואינו נותן באצבע אלא חטאת:
@42 **חלבו.** המבחר שבו. ומהו זה, האליה תמימה: **לעמת העצה.** למעלה מן הכליות היועצות:
@44 **לחם אשה לה'.** לחמו של אש לשם גבוה: **לחם.** לשון מאכל, וכן (ירמיהו יא יט) נשחיתה עץ בלחמו, (דניאל ה א) עבד לחם רב, (קהלת י יט) לשחוק עשים לחם:
@50 **חקת עולם.** יפה מפורש בתורת כהנים כל הפסוק הזה:
@52 **מכל מצות ה'.** פרשו רבותינו אין חטאת באה אלא על דבר שזדונו לאו וכרת (ושגגתו חטאת) : **מאחת מהנה.** ממקצת אחת מהן, כגון הכותב בשבת שם משמעון, נח מנחור, דן מדניאל:
@53 **אם הכהן המשיח יחטא לאשמת העם.** מדרשו אינו חיב אלא בהעלם דבר עם שגגת מעשה, כמו שנאמר לאשמת העם ונעלם דבר מעיני הקהל ועשו (פסוק יג) . ופשוטו לפי אגדה, כשכהן גדול חוטא, אשמת העם הוא זה, שהן תלויין בו לכפר עליהם ולהתפלל בעדם, ונעשה מקלקל: **פר.** יכול זקן, תלמוד לומר בן, אי בן יכול קטן, תלמוד לומר פר, הא כיצד, זה פר בן שלש:
@55 **אל אהל מועד.** למשכן, ובבית עולמים להיכל:
@56 **את פני פרכת הקדש.** כנגד מקום קדשתה, מכון כנגד בין הבדים, ולא היו נוגעים דמים בפרכת, ואם נגעו נגעו:
@57 **ואת כל דם.** שירי הדם:
@58 **ואת כל חלב פר.** חלבו היה לו לומר, מה תלמוד לומר פר, לרבות פר של יום הכפורים לכליות ולחלבים וליותרת: **החטאת.** להביא שעירי עבודה זרה לכליות ולחלבים ויותרת: **ירים ממנו.** מן המחבר, שלא ינתחנו קודם הסרת חלבו, [ ת''כ ] :
@60 **כאשר יורם.** מאותן אימורין המפורשין בשור זבח השלמים. וכי מה פרש בזבח השלמים שלא פרש כאן, אלא להקישו לשלמים מה שלמים לשמן, אף זה לשמו. ומה שלמים שלום לעולם, אף זה שלום לעולם. ובשחיטת קדשים מצריכו ללמוד המנו, שאין למדין למד מן הלמד בקדשים, בפרק איזהו מקומן [ זבחים מט ] : **על הכבד על הכליות'** יא **על ראשו ועל כרעיו.** כלן לשון תוספת הן, כמו מלבד:
@62 **אל מקום טהור.** לפי שיש מחוץ לעיר מקום מוכן לטמאה להשליך אבנים מנגעות ולבית הקברות, הצרך לומר מחוץ למחנה, זה שהוא חוץ לעיר, שיהא המקום טהור: **מחוץ למחנה.** חוץ לשלש מחנות, ובבית עולמים חוץ לעיר, כמו שפרשוהו רבותינו במסכת יומא (סח א) ובסנהדרין (מב ב) : **אל שפך הדשן.** מקום ששופכין בו הדשן המסלק מן המזבח, כמו שנאמר (ויקרא ו ד) והוציא את הדשן אל מחוץ למחנה: **על שפך הדשן ישרף.** שאין תלמוד לומר אלא ללמד, שאפלו אין שם דשן:
@63 **עדת ישראל.** אלו סנהדרין: **ונעלם דבר.** טעו להורות באחת מכל כריתות שבתורה שהוא מתר: **הקהל ועשו.** שעשו צבור על פיהם:
@67 **את פני הפרכת.** ולמעלה הוא אומר את פני פרוכת הקדש, משל למלך שסרחה עליו מדינה, אם מיעוטה סרחה, פמליא שלו מתקימת, ואם כלה סרחה, אין פמליא שלו מתקימת. אף כאן כשחטא כהן משיח עדין שם קדשת המקום על המקדש, משחטאו כלם, חס ושלום, נסתלקה הקדשה:
@68 **יסוד מזבח העלה אשר פתח אהל מועד.** זה יסוד מערבי, שהוא כנגד הפתח:
@69 **ואת כל חלבו ירים.** אף על פי שלא פרש כאן יותרת ושתי כליות, למדין הם מועשה לפר כאשר עשה וגו' . ומפני מה לא נתפרשו בו, תנא דבי ר' ישמעאל (זבחים מא ב) משל למלך שזעם על אוהבו ומעט בסרחונו מפני חבתו:
@70 **ועשה לפר.** זה כאשר עשה לפר החטאת, כמו שמפורש בפר כהן משיח, להביא יותרת ושתי כליות שפרש שם מה שלא פרש כאן. ולכפול במצות העבודות, ללמד שאם חסר אחת מכל המתנות פסול, לפי שמצינו בנתנין על המזבח החיצון שנתנן במתנה אחת כפר, הצרך לומר כאן שמתנה אחת מהן מעכבת:
@72 **אשר נשיא יחטא.** לשון אשרי, אשרי הדור שהנשיא שלו נותן לב להביא כפרה על שגגתו, קל וחומר שמתחרט על זדונותיו:
@73 **או הודע.** כמו אם הודע. הרבה או יש שמשמשין בלשון אם, ואם במקום או, וכן או נודע כי שור נגח הוא (שמות כא לו) : **הודע אליו.** כשחטא היה סבור שהוא התר, ולאחר מכאן נודע לו שאסור היה:
@74 **במקום אשר ישחט את העלה.** בצפון, שהוא מפורש בעולה: **חטאת הוא.** לשמו כשר, שלא לשמו פסול:
@75 **ואת דמו.** שירי הדם:
@76 **כחלב זבח השלמים.** כאותן אימורין המפורשים בעז האמור אצל שלמים:
@81 **כאשר הוסר חלב מעל זבח השלמים.** כאימורי עז האמורים בשלמים:
@83 **ושחט אתה לחטאת.** שתהא שחיטתה לשם חטאת:
@85 **כאשר יוסר חלב הכשב.** שנתרבו אימוריו באליה, אף חטאת, כשהיא באה כשבה, טעונה אליה עם האימורין: **על אשי ה'.** על מדורות האש העשויות לשם. פואיי לי ''ש ב לע ''ז [מדורות] :
@86 **ושמעה קול אלה.** בדבר שהוא עד בו, שהשביעוהו שבועה שאם יודע לו בעדות, שיעיד לו:
@87 **או נפש אשר תגע** וגו' **.** ולאחר הטמאה הזו יאכל קדשים, או יכנס למקדש, שהוא דבר שזדונו כרת. במסכת שבועות (יד ב) נדרש כן: **ונעלם ממנו.** הטמאה: **ואשם.** באכילת קדש או בביאת מקדש:
@88 **בטמאת אדם.** זו טמאת מת: **לכל טמאתו.** לרבות טמאת מגע זבין וזבות: **אשר יטמא.** לרבות הנוגע בבועל נדה: **בה.** לרבות בולע נבלת עוף טהור: **ונעלם.** ולא ידע, (נ''א: **והוא ידע** ) ששכח הטמאה: ואשם. באכילת קדש או בביאת מקדש:
@89 **בשפתים.** ולא בלב: **להרע.** לעצמו: **או להיטיב.** לעצמו, כגון אוכל ולא אוכל אישן ולא אישן: **לכל אשר יבטא.** לרבות לשעבר: **ונעלם ממנו.** ועבר על שבועתו, כל אלה בקרבן עולה ויורד, כמפורש כאן, אבל שבועה שיש בה כפירת ממון אינה בקרבן זה אלא באשם:
@93 **והקריב את אשר לחטאת ראשונה.** חטאת קודמת לעולה. למה הדבר דומה, לפרקליט שנכנס לרצות, רצה פרקליט נכנס דורון אחריו: **ולא יבדיל.** אינו מולק אלא סימן אחד. ערף, הוא גובה הראש המשפע לצד הצואר. מול ערף. מול הרואה את העורף, והוא אורך כל אחורי הצואר:
@94 **והזה מדם החטאת.** בעולה לא הטעין אלא מצוי, ובחטאת הזאה ומצוי. אוחז בעורף ומתיז, והדם נתז והולך למזבח: **חטאת הוא.** לשמה כשרה, שלא לשמה פסולה:
@95 **כמשפט.** כדת האמור בעולת העוף שלנדבה בראש הפרשה:
@96 **כי חטאת הוא.** ואין בדין שיהא קרבנו מהדר:
@97 **חטאת הוא.** נקמצה ונקטרה לשמה כשרה, שלא לשמה פסולה:
@98 **על חטאתו אשר חטא.** כאן שנה הכתוב, שהרי בעשירות ובדלות נאמר (פסוק י) מחטאתו, וכאן בדלי דלות נאמר על חטאתו, דקדקו רבותינו (כריתות כז ב) מכאן, שאם חטא כשהוא עשיר והפריש מעות לכשבה או שעירה והעני, יביא ממקצתן שתי תורים. הפריש מעות לשתי תורים והעני יביא ממקצתן עשירית האיפה [לכך נאמר מחטאתו] . הפריש מעות לעשירית האיפה והעשיר, יוסיף עליהן ויביא קרבן עשיר, לכך נאמר כאן על חטאתו: **מאחת מאלה.** מאחת משלש כפרות האמורות בענין, או בעשירות או בדלות או בדלי דלות. ומה תלמוד לומר, שיכול החמורין שבהם יהיו בכשבה או שעירה, והקלין יהיו בעוף, והקלין שבקלין יהיו בעשירית האיפה, תלמוד לומר מאחת מאלה, להשוות קלין לחמורין לכשבה ושעירה אם השיגה ידו, ואת החמורין לקלין לעשירית האיפה בדלי דלות: **והיתה לכהן כמנחה.** ללמד על מנחת חוטא שהיו שיריה נאכלין, זהו לפי פשוטו. ורבותינו דרשו והיתה לכהן כמנחה, ואם חוטא זה כהן הוא, תהא לו כשאר מנחת נדבת כהן, שהיא בכליל תהיה לא תאכל (ויקרא ו טז) :
@100 **כי תמעל מעל.** אין מעילה בכל מקום אלא שנוי, וכן הוא אומר (דה''א ה כה) וימעלו באלהי אבותיהם ויזנו אחרי אלהי עמי הארץ, וכן הוא אומר בסוטה (במדבר ה יב) ומעלה בו מעל: **וחטאה בשגגה מקדשי ה'.** שנהנה מן ההקדש. והיכן הזהר, נאמר כאן חטא ונאמר להלן חטא בתרומה (ויקרא כב ט) ולא ישאו עליו חטא, מה להלן הזהיר, אף כאן הזהיר. אי מה להלן לא הזהיר אלא על האוכל, אף כאן לא הזהיר אלא על האוכל, תלמוד לומר תמעול מעל, רבה: **מקדשי ה'.** המיוחדים לשם, יצאו קדשים קלים: **איל.** לשון קשה, כמו (יחזקאל יז יג) ואת אילי הארץ לקח, אף כאן קשה, בן שתי שנים: **בערכך כסף שקלים.** שיהא שוה שתי סלעים:
@101 **ואת אשר חטא מן הקדש ישלם.** קרן וחומש להקדש:
@102 **ולא ידע ואשם:. והביא.** הענין הזה מדבר במי שבא ספק כרת לידו ולא ידע אם עבר עליו אם לאו, כגון חלב ושומן לפניו, וכסבור ששתיהן התר, ואכל את האחת. אמרו לו אחת של חלב היתה, ולא ידע אם זו של חלב אכל, הרי זה מביא אשם תלוי ומגין עליו כל זמן שלא נודע לו שודאי חטא, ואם נודע לו לאחר זמן יביא חטאת: **ולא ידע ואשם ונשא עונו.** ר' יוסי הגלילי אומר הרי הכתוב ענש את מי שלא ידע, על אחת כמה וכמה שיעניש את שידע. רבי יוסי אומר אם נפשך לידע מתן שכרן של צדיקים, צא ולמד מאדם הראשון, שלא נצטוה אלא על מצות לא תעשה ועבר עליה, ראה כמה מיתות נקנסו עליו ולדורותיו. וכי איזו מדה מרבה, של טובה או של פרענות, הוי אומר מדה טובה. אם מדת פרענות המעוטה ראה כמה מיתות נקנסו לו ולדורותיו, מדה טובה המרבה, היושב לו מן הפגולין והנותרות והמתענה ביום הכפורים, על אחת כמה וכמה שיזכה לו ולדורותיו ולדורות דורותיו עד סוף כל הדורות. רבי עקיבא אומר הרי הוא אומר (דברים יז ו) על פי שנים עדים או שלשה עדים וגו' , אם מתקימת העדות בשנים, למה פרט לך הכתוב שלשה, אלא להביא שלישי להחמיר עליו ולעשות דינו כיוצא באלו לענין ענש והזמה. אם כך ענש הכתוב לנטפל לעוברי עברה כעוברי עברה, על אחת כמה וכמה שישלם שכר טוב לנטפל לעושי מצוה כעושי מצוה. רבי אלעזר בן עזריה אומר כי תקצר קצירך בשדך ושכחת עמר בשדה (דברים כד יט) , הרי הוא אומר (דברים כד יט) למען יברכך וגו' , קבע הכתוב ברכה למי שבאת על ידו מצוה בלא ידע, אמור מעתה היתה סלע צרורה בכנפיו ונפלה המנו ומצאה העני ונתפרנס בה, הרי הקדוש ברוך הוא קובע לו ברכה:
@103 **בערכך לאשם.** בערך האמור למעלה (פסוק טו) : **אשר שגג והוא לא ידע.** הא אם ידע לאחר זמן, לא נתכפר לו באשם זה עד שיביא חטאת. הא למה זה דומה לעגלה ערופה שנתערפה ואחר כך נמצא ההורג, הרי זה יהרג:
@104 **אשם הוא אשם אשם.** הראשון כלו קמץ שהוא שם דבר, והאחרון חציו קמץ וחציו פתח שהוא לשון פעל. ואם תאמר מקרא שלא לצורך הוא, כבר נדרש הוא בתורת כהנים. **אשם אשם.** להביא אשם שפחה חרופה שיהא איל (בן שתי שנים) שוה שתי סלעים. יכול שאני מרבה אשם נזיר ואשם מצורע, תלמוד לומר הוא:
@106 **נפש כי תחטא.** אמר ר' עקיבא מה תלמוד לומר ומעלה מעל בה', לפי שכל המלוה והלוה והנושא והנותן אינו עושה אלא בעדים ובשטר, לפיכך בזמן שהוא מכחש מכחש בעדים ובשטר, אבל המפקיד אצל חברו אינו רוצה שתדע בו נשמה אלא שלישי שביניהם, לפיכך כשהוא מכחש, מכחש בשלישי שביניהם: **בתשומת יד.** ששם בידו ממון להתעסק או במלוה: **או בגזל.** שגזל מידו כלום: **או עשק.** הוא שכר שכיר:
@107 **וכחש בה.** שכפר על אחת מכל אלה אשר יעשה האדם לחטוא ולהשבע על שקר לכפירת ממון:
@108 **כי יחטא ואשם.** כשיכיר בעצמו לשוב בתשובה, ולדעת ולהתודות כי חטא ואשם:
@109 **בראשו.** הוא הקרן ראש הממון: **וחמשתיו.** רבתה תורה חמשיות הרבה לקרן אחת, שאם כפר בחומש ונשבע והודה, חוזר ומביא חומש על אותו חומש. וכן מוסיף והולך עד שיתמעט הקרן שנשבע לו פחות משוה פרוטה: **לאשר הוא לו.** למי שהממון שלו:
@112 **עם זו יצרתי לי.** למען תהלתי יספרו:
@113 **ולא אותי קראת.** ואתה לא אותי קראת בפנותך אחרי עכו"ם: **כי יגעת בי.** נלאיתם מהר בעבודתי:
@114 **לא הבאת לי שה עולותיך.** כ"א לעכו"ם: **לא העבדתיך.** עבודה רבה במנחה קומץ מעט עולה לגבוה וגם הוא לא אמרתי לך להקריב לך חובה אלא נדבה:
@115 **לא קנית לי בכסף קנה.** לקטרת לא הוצרכת לקנותה בכסף לפי שהיתה מצויה בארצכם הרבה אמר רבי אבא קינמני' היתה גדילה בארץ ישראל והיו אוכלין אותה עזים וצביים במדרש איכה: **העבדתני בחטאותיך.** אתם גרמתם לי להיות שמש לעובדי פסילים כמו שראה יחזקאל והנה רוח סערה באה מן הצפון שהיתה חוזרת מרכבת השכינה מבבל שהלכה לכבוש את כל העולם תחת ידו של נבוכדנצר שלא יאמרו ביד אומה שפלה מסר את בניו כדאיתא בחגיגה:
@116 **אנכי אנכי.** אני הוא שמחיתים מאז ואני מוחה אותם גם עתה: **למעני.** לא בזכותך ולא בצדקת אבותיך:
@117 **הזכירני.** כל תגמול שיש לך ולאבותיך עלי: **נשפטה יחד.** נבא למשפט:
@118 **אביך הראשון חטא.** באומרו במה אדע ( בראשית טו ): **ומליציך פשעו בי.** אין לך בכל מליצי' שאתה סומך על זכותם שלא מצאתי בו פשע יצחק אהב את שונאי:
@119 **ואחלל שרי קדש.** בשביל עונותיכם:
@120 **ועתה שמע.** לשוב לתורתי יעקב עבדי:
@122 **כי אצק מים על צמא.** כמו שאני יוצק מים על צמא כן אצק רוחי על זרעך:
@123 **וצמחו בבין חציר.** בתוך עמלק על ידי גרים שיתוספו עליהם, בין חציר הוא עמלק שנאמר עליו והיתה נוה תנים חציר לבנות יענה ( לעיל ד ):
@124 **זה יאמר לה' אני.** אלו צדיקים גמורים: **וזה יקרא בשם יעקב.** אלו קטנים בני רשעים: **זה יכתוב ידו לה'.** אלו בעלי תשובה: **ובשם ישראל יכנה.** אלו הגרים מעכו"ם כך שנויה באבות דרבי נתן:
@126 **ומי כמוני יקרא.** ומי יקרא שהוא כמוני ויגיד ויערוך לי את כל מה שהיה משומי עם עולם ועד עתה: **עם עולם.** כל בריות: **ואותיות.** דברי מופת: **ואשר תבאנה.** ואת העתידות לבא יגידו כמו שאני עושה עתה שעדיין לא חרב הבית ולא גליתם ולא נולד כורש ואני מבשר אתכם עליו:
@127 **ואל תרהו.** אין לו דמיון ופתרונו לפי הענין כמו אל תחתו מלהודיע את שמי לבין העכו"ם: **הלא מאז השמעתיך.** מהר סיני והגדתי לכם שם שאין אלוהי מבלעדי. ואתם עדי. שפתחתי לכם שבעה רקיעים והראיתי אתכם שאין אחר ואתם עדי בדבר הזה שאין אלוה מבלעדי: **ואין צור בל ידעתי.** ת"י ולית דתקיף אלהן דמן קדמי מתיהב ליה תקיף: **בל ידעתי.** לשון ואדעך בשם ( שמות לג ) ידע לכתך ( דברים ב ) אני ידעתיך במדבר ( הושע יג ):
@128 **ועדיהם המה.** הפסילי' הם עדים על בושת עובדיהם שהרי אנו רואין שאינן לא רואין ולא יודעין והיו עובדין להם: **למען יבושו.** העובדים להם:
@129 **נסך.** לשון יציקה ומסכה והנו"ן בתיבה יסוד הנופל ממנו כגון נו"ן של נשך ושל נגף:
@130 **הן כל חביריו.** של אותו יוצר ונוסך פסילים המתחברים אליו לעבוד את יצירתו ונסכו יבושו: **וחרשים המה.** אותם יוצרים ונוסכים מבני אדם הם קל וחומר ליצירתם שהיא הבל:
@131 **חרש ברזל.** חרש של ברזל: **מעצד.** הוא אחד מכלי הנפחים: **ופעל.** הפסל. בפחם. קרבו"ן בלע"ז: **ובמקבות.** מרטי"ל בלע"ז: **יצרהו.** ל' ציור: **ויפעלהו בזרוע כחו גם רעב וגו'.** גם הוא היוצר חסר כח וחלש הוא שאם ירעב אין בו כח או אם לא שתה מים ויעף לאלתר קל וחומר שפעולתו אין בה תועלת לעזור:
@132 **חרש עצים.** ואם בא לעשותו של עץ וחרש עצים הוא כך דרכו: **נטה קו.** כדרך הנגרים ועל פי הקו יתארהו בשרד מיישר אותו במסור שקורין דאלאור"א בלע"ז. יתארהו. ייפהו: **יעשהו במקצועות.** ומחליקו ברהיטני ואיזמל, מקצועות ת"י אזמליא: **ובמחוגה יתארהו.** לשון ותאר הגבול ( יהושע טו ) אם בא לעשו' בו ציורים עגולים מסבב אותו במחוגה קונפ"ש בלע"ז: **כתפארת אדם.** כמין איש:
@133 **תרזה ואלון.** מיני אילני סרק: **ויאמץ לו בעצי יער.** עושה לו חיזוקי' בין לחיזוק בין לנוי במיני עצי' המשונים זה מזה במראיהן: **נטע אורן.** כשמוצא ייחור ונטע הראוי לכך נוטעו לכך והגשם מגדלו: **אורן.** ל' נטע יונק פרנצו"ן בלע"ז:
@134 **והיה לאדם לבער.** והיה אותו עץ מקצתו לצרכי אדם לבער: **ויקח.** מן העצים ויחם גופו לנגדם: **אף ישיק.** מהם תנור ואופה לחם: **אף יפעל אל.** מן הנותר:
@138 **ולא ישיב אל לבו.** חציו שרפתי במו אש: **ולא דעת ולא תבונה.** בו לאמר זאת: **לבול עץ.** לרקבון עץ:
@139 **רועה אפר לב הותל הטהו.** לבו אשר הותל הטהו לעשות לו רועה של אפר הדמות שנשרף חציו ונעשה אפר השוטה הזה היה אומר שהוא לו לרועה ולמפרנס, דבר אחר רועה אפר ל' ריעות עובד עבודת אחרים ומחבר אליו עבודת אחרים שהיא אפר: **ולא יציל.** הנתעה את נפשו לאמר הלא שקר בימיני ויפרד מעליו:
@140 **לא תנשני.** לא תהיה שכוח מיראתי:
@141 **מחיתי כעב פשעיך.** במצרים ובמדבר גם עתה שובה אלי:
@142 **פצחו.** ל' פתחון פה:
@144 **צו את אהרן.** אין צו אלא לשון זרוז מיד ולדורות. אמר ר' שמעון ביותר צריך הכתוב לזרז במקום שיש בו חסרון כיס: **זאת תורת העלה** וגו' **.** הרי הענין הזה בא ללמד על הקטר חלבים ואיברים שיהא כשר כל הלילה, וללמד על הפסולין איזה אם עלה ירד, ואיזה אם עלה לא ירד, שכל תורה לרבות הוא בא, לומר תורה אחת לכל העולים, ואפלו פסולין, שאם עלו לא ירדו: **הוא העלה.** למעט את הרובע ואת הנרבע וכיוצא בהן, שלא היה פסולן בקדש, שנפסלו קודם שבאו לעזרה:
@145 **מדו בד.** היא הכתנת. ומה תלמוד לומר מדו, שתהא כמדתו: **על בשרו.** שלא יהא דבר חוצץ בנתים: **והרים את הדשן.** היה חותה מלא מחתה מן המאכלות הפנימיות ונותנן במזרחו של כבש: **הדשן אשר תאכל האש את העלה.** ועשאתה דשן, מאותו דשן ירים תרומה ושמו אצל המזבח: **על המזבח.** מצא אברים שעדין לא נתעכלו, מחזירן על המזבח, לאחר שחתה גחלים אלך ואלך ונטל מן הפנימיות, שנאמר את העלה על המזבח:
@146 **ופשט את בגדיו.** אין זו חובה אלא דרך ארץ, שלא ילכלך בהוצאת הדשן בגדים שהוא משמש בהן תמיד. בגדים שבשל בהן קדרה לרבו אל ימזג בהן כוס לרבו, לכך ולבש בגדים אחרים פחותין מהן: **והוציא את הדשן.** הצבור בתפוח, כשהוא רבה ואין מקום למערכה, מוציאו משם. ואין זה חובה בכל יום, אבל התרומה חובה בכל יום ה **והאש על המזבח תוקד בו.** רבה כאן יקידות הרבה על מוקדה, ואש המזבח תוקד בו, והאש על המזבח תוקד בו, אש תמיד תוקד על המזבח, כלן נדרשו במסכת יומא (מג ב) שנחלקו רבותינו במנין המערכות שהיו שם: **וערך עליה העלה.** עולת תמיד היא תקדים: **חלבי השלמים.** אם יביאו שם שלמים. ורבותינו למדו מכאן עליה, על עולת הבקר השלם כל הקרבנות כלם. מכאן שלא יהא דבר מאוחר לתמיד של בין הערבים:
@148 **אש תמיד.** אש שנאמר בה תמיד, היא שמדליקין בה את הנרות, שנאמר בה (שמות כז כ) להעלות נר תמיד, אף היא מעל המזבח החיצון תוקד: **לא תכבה.** המכבה אש על המזבח עובר בשני לאוין:
@149 **וזאת תורת המנחה.** תורה אחת לכלן להטעינן שמן ולבונה האמורין בענין. שיכול אין לי טעונות שמן ולבונה אלא מנחת ישראל שהיא נקמצת, מנחת כהנים שהיא כליל מנין, תלמוד לומר תורת: **הקרב אתה.** היא הגשה בקרן מערבית דרומית: **לפני ה'.** הוא מערב שהוא לצד אהל מועד: **אל פני המזבח.** הוא הדרום, שהוא פניו של מזבח, שהכבש נתון לאותו הרוח:
@150 **והרים ממנו.** מהמחבר, שיהא עשרון שלם בבת אחת בשעת קמיצה: **בקמצו.** שלא יעשה מדה לקומץ: **מסלת המנחה ומשמנה.** מכאן שקומץ ממקום שנתרבה שמנה: **המנחה.** שלא תהא מעורבת באחרת: **ואת כל הלבנה אשר על המנחה והקטיר.** שמלקט את לבונתה לאחר קמיצה ומקטירו. ולפי שלא פרש כן אלא באחת מן המנחות בויקרא (ב, א. ג) , הצרך לשנות פרשה זו, לכלול כל המנחות כמשפטן:
@151 **במקום קדש.** ואיזהו, בחצר אהל מועד:
@152 **לא תאפה חמץ חלקם.** אף השירים אסורים בחמץ: **כחטאת וכאשם.** מנחת חוטא הרי היא כחטאת, לפיכך קמצה שלא לשמה פסולה. מנחת נדבה הרי היא כאשם, לפיכך קמצה שלא לשמה כשרה:
@153 **כל זכר.** אפלו בעל מום. למה נאמר, אם לאכילה הרי כבר אמור לחם אלהיו מקדשי הקדשים וגו' , אלא לרבות בעלי מומין למחלוקת: **כל אשר יגע** וגו' **.** קדשים קלים או חלין שיגעו בה ויבלעו ממנה: **יקדש.** להיות כמוה, שאם פסולה יפסלו, ואם כשרה יאכלו כחמר המנחה:
@155 **זה קרבן אהרן ובניו.** אף ההדיוטות מקריבין עשירית האיפה ביום שהן מתחנכין לעבודה, אבל כהן גדול בכל יום, שנאמר מנחה תמיד וגו' והכהן המשיח תחתיו מבניו וגו' חק עולם וגו' (פסוק טו) יד **מרבכת.** חלוטה ברותחין כל צרכה: **תפיני.** אפויה אפיות הרבה, שאחר חליטתה אופה בתנור וחוזר ומטגנה במחבת: **מנחת פתים.** מלמד שטעונה פתיתה:
@157 **המשיח תחתיו מבניו.** המשיח מבניו תחתיו: **כליל תקטר.** אין נקמצת להיות שיריה נאכלין אלא כלה כליל, וכן כל מנחת כהן של נדבה כליל תהיה טז **כליל.** כלה שוה לגבוה:
@161 **המחטא אתה.** העובד עבודותיה שהיא נעשית חטאת על ידו: **המחטא אתה יאכלנה.** הראוי לעבודה, יצא טמא בשעת זריקת דמים שאינו חולק בבשר, ואי אפשר לומר שאוסר שאר כהנים באכילתה חוץ מן הזורק דמה, שהרי נאמר למטה (פסוק כב) כל זכר בכהנים יאכל אתה:
@162 **כל אשר יגע בבשרה.** כל דבר אוכל אשר יגע ויבלע ממנה: **יקדש.** להיות כמוה, אם פסולה תפסל, ואם היא כשרה תאכל כחמר שבה: **ואשר יזה מדמה על הבגד.** ואם הזה מדמה על הבגד, אותו מקום דם הבגד אשר יזה עליה, תכבס בתוך העזרה: **אשר יזה.** יהא נזה, כמו (איוב טו כט) ולא יטה לארץ מנלם, יהא נטוי:
@163 **ישבר.** לפי שהבליעה שנבלעת בו נעשה נותר, והוא הדין לכל הקדשים: **ומרק.** לשון תמרוקי הנשים (אסתר ב יב) אישקורימינ''ט בלע''ז [נקוי] : **ומרק ושטף.** לפלוט את בליעתו, אבל כלי חרס למדך הכתוב כאן שאינו יוצא מידי דפיו לעולם:
@164 **כל זכר בכהנים יאכל אתה.** הא למדת שהמחטא אותה האמור למעלה לא להוציא שאר הכהנים, אלא להוציא את שאינו ראוי לחטוי:
@165 **וכל חטאת** וגו' **.** שאם הכניס מדם חטאת החיצונה לפנים פסולה: **וכל.** לרבות שאר קדשים:
@166 **קדש קדשים הוא.** הוא קרב ואין תמורתו קרבה:
@167 **ישחטו.** רבה לנו שחיטות הרבה, לפי שמצינו אשם בצבור, נאמר ישחטו רבים. ותלאו בעולה להביא עולת צבור לצפון:
@168 **ואת כל חלבו** וגו' **.** עד כאן לא נתפרשו אמורין באשם, לכך הצרך לפרשם כאן, אבל חטאת כבר נתפרשו בה בפרשת ויקרא (פרק ב) : **את האליה.** לפי שאשם אינו בא אלא איל או כבש, ואיל וכבש נתרבו באליה:
@170 **אשם הוא.** עד שינתק שמו ממנו. למד על אשם שמתו בעליו או שנתכפרו בעליו, אף על פי שעומד להיות דמיו עולה לקיץ המזבח, אם שחטו סתם, אינו כשר לעולה קודם שנתק לרעיה. ואינו בא ללמד על האשם שיהא פסול שלא לשמו, כמו שדרשו הוא, הכתוב בחטאת, לפי שאשם לא נאמר בו אשם הוא, אלא לאחר הקטרת אמורין, והוא עצמו שלא הקטרו אמוריו כשר:
@171 **קדש קדשים הוא.** בתורת כהנים הוא נדרש:
@172 **תורה אחת להם.** בדבר זה: **הכהן אשר יכפר בו.** הראוי לכפרה חולק בו, פרט לטבול יום ומחסר כפורים ואונן:
@173 **עור העלה אשר הקריב לכהן לו יהיה.** פרט לטבול יום ומחסר כפורים ואונן שאינן חולקים בעורות:
@174 **לכהן המקריב אתה** וגו' **.** יכול לו לבדו, תלמוד לומר לכל בני אהרן תהיה. יכול לכלן, תלמוד לומר לכהן המקריב, הא כיצד לבית אב של אותו יום שמקריבין אותה:
@175 **בלולה בשמן.** זו מנחת נדבה: **וחרבה.** זו מנחת חוטא ומנחת קנאות שאין בהן שמן:
@177 **אם על תודה יקריבנו.** אם על דבר הודאה על נס שנעשה לו, כגון יורדי הים והולכי מדברות וחבושי בית האסורים וחולה שנתרפא שהם צריכין להודות שכתוב בהן (תהלים קז כא. כב) יודו לה' חסדו ונפלאותיו לבני אדם ויזבחו זבחי תודה. אם על אחת מאלה נדר שלמים הללו, שלמי תודה הן, וטעונות לחם האמור בענין, ואינן נאכלין אלא ליום ולילה, כמו שמפורש כאן: **והקריב על זבח התודה.** ארבעה מיני לחם חלות, ורקיקין, ורבוכה, שלשה מיני מצה, וכתיב (פסוק יג) על חלת לחם חמץ וגו' , וכל מין ומין עשר חלות, כך מפורש במנחות (עז א) . ושעורן חמש סאין ירושלמיות שהן שש מדבריות, עשרים עשרון: **מרבכת.** לחם חלוט ברותחין כל צרכו יג **יקריב קרבנו על זבח.** מגיד שאין הלחם קדוש קדשת הגוף להפסל ביוצא וטבול יום ומלצאת לחלין בפדיון, עד שישחט הזבח:
@179 **אחד מכל קרבן.** לחם אחד מכל מין ומין יטול תרומה לכהן העובד עבודתה, והשאר נאכל לבעלים ובשרה לבעלים, חוץ מחזה ושוק שבה, כמו שמפורש למטה (פסוקים כט. לב) תנופת חזה ושוק בשלמים. והתודה קרויה שלמים:
@180 **ובשר זבח תודת שלמיו.** יש כאן רבויין הרבה, לרבות חטאת ואשם ואיל נזיר וחגיגת ארבעה עשר, שיהיו נאכלין ליום ולילה: **ביום קרבנו יאכל.** וכזמן בשרה זמן לחמה: **לא יניח ממנו עד בקר.** אבל אוכל הוא כל הלילה, אם כן למה אמרו עד חצות, כדי להרחיק אדם מן העברה:
@181 **ואם נדר או נדבה.** שלא הביאה על הודאה של נס, אינה טעונה לחם ונאכלת לשני ימים, כמו שמפורש בענין: **וממחרת והנותר ממנו.** בראשון יאכל. וי''ו זו יתרה היא, ויש כמוה הרבה במקרא, כגון (בראשית לו כד) ואלה בני צבעון ואיה וענה, (דניאל ח יג) תת וקדש וצבא מרמס:
@183 **ואם האכל יאכל** וגו' **.** במחשב בשחיטה לאכלו בשלישי הכתוב מדבר. יכול אם אכל ממנו בשלישי יפסל למפרע, תלמוד לומר המקריב אותו לא יחשב, בשעת הקרבה הוא נפסל, ואינו נפסל בשלישי. וכן פרושו בשעת הקרבתו לא תעלה זאת במחשבה, ואם חשב פגול יהיה: **והנפש האכלת ממנו.** אפלו בתוך הזמן עונה תשא:
@184 **והבשר.** של קדש שלמים אשר יגע בכל טמא לא יאכל: **והבשר.** לרבות אבר שיצא מקצתו, שהפנימי מתר: **כל טהור יאכל בשר.** מה תלמוד לומר, לפי שנאמר (דברים יב כז) ודם זבחיך ישפך וגו' והבשר תאכל, יכול לא יאכלו שלמים אלא הבעלים, לכך נאמר כל טהור יאכל בשר: **והבשר כל טהור יאכל בשר.** כלומר כל מה שאסרתי לך בחטאת ואשם, שאם יצאו חוץ לקלעם אסורין, כמו שכתוב (ו ט) בחצר אהל מועד יאכלוה, בבשר זה אני אומר לך כל טהור יאכל בשר אפלו בכל העיר:
@185 **וטמאתו עליו.** בטמאת הגוף הכתוב מדבר, אבל טהור שאכל את הטמא, אינו ענוש כרת, אלא באזהרה והבשר אשר יגע בכל טמא וגו' (פסוק יט) . ואזהרת טמא שאכל את הטהור אינה מפורשת בתורה, אלא חכמים למדוה בגזרה שוה. שלש כריתות אמורות באוכלי קדשים בטמאת הגוף, ודרשוה רבותינו בשבועות (ז א) אחת לכלל ואחת לפרט ואחת ללמד על קרבן עולה ויורד, שלא נאמר אלא על טמאת מקדש וקדשיו:
@189 **יעשה לכל מלאכה.** בא ולמד על החלב שאינו מטמא טמאת נבלות: **ואכל לא תאכלהו.** אמרה תורה יבוא אסור נבלה וטרפה ויחול על אסור חלב, שאם אכלו, יתחיב אף על לאו של נבלה, ולא תאמר אין אסור חל על אסור:
@191 **בכל מושבתיכם.** לפי שהיא חובת הגוף ואינה חובת קרקע, נוהגת בכל מושבות, ובמסכת קדושין בפרק א' (לז א) מפרש למה הצרך לומר: **לעוף ולבהמה.** פרט לדם דגים וחגבים:
@195 **ידיו תביאינה** וגו' **.** שתהא יד הבעלים מלמעלה והחלב והחזות נתונין בה, ויד כהן מלמטה ומניפן: **את אשי ה'.** ומה הן האשים, **את החלב על החזה יביאנו.** כשמביאו מבית המטבחים נותן החלב על החזה, וכשנותנו ליד הכהן המניף נמצא החזה למעלה והחלב למטה, וזהו האמור במקום אחר (ויק' י טו) שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף וגו' , ולאחר התנופה נותנו לכהן המקטיר, ונמצא החזה למטה, וזהו שנאמר (ויק' ט כ) וישימו את החלבים על החזות ויקטר החלבים המזבחה. למדנו ששלשה כהנים זקוקין לה, כך מפורש במנחות (סב א) : **את החלב על החזה יביאנו.** ואת החזה למה מביא, להניף אותו הוא מביאו, ולא שיהא הוא מן האשים. לפי שנאמר את אשי ה' את החלב על החזה, יכול שיהא אף החזה לאשים, לכך נאמר את החזה להניף וגו' :
@196 **והקטיר הכהן את החלב.** ואחר כך והיה החזה לאהרן, למדנו שאין הבשר נאכל בעוד שהאמורים למטה מן המזבח:
@197 **שוק.** מן הפרק של ארכבה הנמכרת עם הראש עד הפרק האמצעי, שהוא סובך של רגל:
@198 **המקריב את דם השלמים** וגו' **.** מי שהוא ראוי לזריקתו ולהקטיר חלבו, יצא טמא בשעת זריקת דמים או בשעת הקטר חלבים, שאינו חולק בבשר לד **התנופה' התרומה.** מוליך ומביא, מעלה ומוריד לז **ולמלואים.** ליום חנוך הכהנה:
@205 **קח את אהרן.** פרשה זו נאמרה שבעת ימים קודם הקמת המשכן, שאין מקדם ומאחר בתורה: **קח את אהרן.** קחנו בדברים ומשכהו: **ואת פר החטאת** וגו' **.** אלו האמורים בענין צואת המלואים בואתה תצוה, ועכשיו ביום ראשון למלואים חזר וזרזו בשעת מעשה:
@206 **הקהל אל פתח אהל מועד.** זה אחד מן המקומות שהחזיק מועט את המרבה:
@208 **זה הדבר.** דברים שתראו שאני עושה לפניכם צוני הקדוש ברוך הוא לעשות, ואל תאמרו לכבודי ולכבוד אחי אני עושה. כל הענין הזה פרשתי בואתה תצוה:
@211 **את האורים.** כתב של שם המפורש:
@212 **וישם על המצנפת.** פתילי תכלת הקבועים בציץ נתן על המצנפת, נמצא הציץ תלוי במצנפת:
@214 **ויז ממנו על המזבח.** לא ידעתי היכן נצטוה בהזאות הללו:
@215 **ויצק' וימשח.** בתחלה יוצק על ראשו, ואחר כך נותן בין ריסי עיניו ומושך באצבעו מזה לזה:
@216 **ויחבש.** לשון קשירה:
@218 **ויחטא את המזבח.** חטאו וטהרו מזרות להכנס לקדשה: **ויקדשהו.** בעבודה זו: **לכפר עליו.** מעתה כל הכפרות:
@219 **ואת יתרת הכבד.** על הכבד (שמות כט יג) לבד הכבד, שהיה נוטל מעט מן הכבד עמה:
@225 **איל המלאים.** איל השלמים, שמלואים לשון שלמים, שממלאים ומשלימים את הכהנים בכהנתם:
@229 **וחלת לחם שמן.** היא רבוכה, שהיה מרבה בה שמן כנגד החלות והרקיקין, כך מפורש במנחות (עח א) :
@231 **ויקטר המזבחה.** משה שמש כל שבעת ימי המלואים בחלוק לבן: **על העלה.** אחר העלה. ולא מצינו שוק של שלמים קרב בכל מקום חוץ מזה:
@237 **צוה ה' לעשת.** כל שבעת הימים. ורבותינו זכרונם לברכה דרשו לעשות. זה מעשה פרה. לכפר. זה מעשה יום הכפורים, וללמד שכהן גדול טעון פרישה קודם יום הכפורים שבעת ימים, וכן הכהן השורף את הפרה:
@238 **ולא תמותו.** הא אם לא תעשו כן, הרי אתם חיבים מיתה:
@239 **ויעש אהרן ובניו.** להגיד שבחן שלא הטו ימין ושמאל:
@240 **עולותיכם.** שאתם מקריבים כליל טוב לכם שתוסיפו אותם על שלמיכם ותקריבו אותם שלמים ותאכלו הבשר שהרי אינם מקובלות לפני ולמה תפסידום:
@241 **ביום הוציאי אותם.** תחלת תנאי לא היתה אלא אם שמוע תשמעו בקולי ושמרתם את בריתי והייתם לי סגול' ( שם יט ):
@243 **בשרירות לבם.** במראה לבם ל' אשורנו ( במדבר כד ):
@244 **יום השכם ושלוח.** מידי יום ביום השכם ושלוח:
@248 **גזי נזרך.** תלשי שערך כמו ויגז שלוים ( שם ט ) ויגז את ראשו ( איוב א ) ל"א נזרך כתרך ל' גדולה וכן תרגם יונתן רברביך וכן חיברו מנחם: **ויטוש.** ויעזוב:
@250 **במות התופת.** הוא המולך שהיה של נחשת ומסיקין אותו מתחתיו וידיו פשוטות וניסקות ונותנין את הילד על ידיו והוא נכוה ונוהם והכומרים היו מקישין בתופים שלא ישמע האב קול הבן ויכמרו רחמיו, תופת על שם התוף: **הנם.** על שם נהמת הבן: **לא צויתי.** במצות שיקריבו בניהם לקרבן ולא דברתי לאחד מן הנביאים וכשדברתי לאברהם לשחוט את בנו לא עלתה על לבי שישחוט אלא להודיע צדקו:
@252 **ואין מחריד.** את העופות מעל הפגרים:
@255 **ושטחום לשמש.** והכשדים ישכנו לצור על העיר בקברי השרים שהיו נאים כפלטין: **לדומן.** לזבל:
@256 **ונבחר מות מחיים.** אע"פ שהם רואים את המתים נתונין בבזיון צרת החיים גדולה הימנה ויבחרו את המות:
@257 **אל יתהלל חכם.** אל תתהללו לומר חכמים אנחנו הנה בדברי מאסתם וחכמת מה לכם אם השכלתם וידעתם אותי אז תתהללו בחכמתכם: בלע"ז:
@259 **ויהי ביום השמיני.** שמיני למלואים, הוא ראש חדש ניסן, שהוקם המשכן בו ביום ונטל עשר עטרות השנויות בסדר עולם (פרק ז) : **ולזקני ישראל.** להשמיעם שעל פי הדבור אהרן נכנס ומשמש בכהנה גדולה, ולא יאמרו מאליו נכנס:
@260 **קח לך עגל.** להודיע שמכפר לו הקדוש ברוך הוא על ידי עגל זה על מעשה העגל שעשה:
@262 **כי היום ה' נראה אליכם.** להשרות שכינתו במעשה ידיכם לכך קרבנות הללו באין חובה ליום זה:
@265 **קרב אל המזבח.** שהיה אהרן בוש וירא לגשת. אמר לו משה למה אתה בוש, לכך נבחרת: **את חטאתך.** עגל בן בקר: **ואת עלתך.** איל: **קרבן העם.** שעיר עזים ועגל וכבש. כל מקום שנאמר עגל, בן שנה הוא, ומכאן אתה למד:
@269 **ואת הבשר ואת העור** וגו' **.** לא מצינו חטאת חיצונה נשרפת אלא זו ושל מלאים, וכלן על פי הדבור:
@270 **וימצאו.** לשון הושטה והזמנה:
@273 **ויחטאהו.** עשהו כמשפט חטאת: **כראשון.** כעגל שלו:
@274 **ויעשה כמשפט.** המפורש בעולת נדבה בויקרא (פרק א) :
@275 **וימלא כפו.** היא קמיצה: **מלבד עלת הבקר.** כל אלה עשה אחר עולת התמיד:
@277 **והמכסה.** חלב המכסה את הקרב:
@278 **וישימו את החלבים על החזות.** לאחר התנופה נתנן כהן המניף לכהן אחר להקטירם, נמצאו העליונים למטה:
@280 **ויברכם.** ברכת כהנים יברכך, יאר, ישא: **וירד.** מעל המזבח:
@281 **ויבא משה ואהרן** וגו' **.** למה נכנסו, מצאתי בפרשת מלאים בבריתא הנוספת על תורת כהנים שלנו למה נכנס משה עם אהרן, ללמדו על מעשה הקטרת. או לא נכנס אלא לדבר אחר, הריני דן ירידה וביאה טעונות ברכה, מה ירידה מעין עבודה, אף ביאה מעין עבודה, הא למדת למה נכנס משה עם אהרן, ללמדו על מעשה הקטרת. דבר אחר כיון שראה אהרן שקרבו כל הקרבנות ונעשו כל המעשים ולא ירדה שכינה לישראל, היה מצטער ואמר יודע אני שכעס הקדוש ברוך הוא עלי ובשבילי לא ירדה שכינה לישראל. אמר לו למשה, משה אחי כך עשית לי, שנכנסתי ונתבישתי. מיד נכנס משה עמו ובקשו רחמים וירדה שכינה לישראל: **ויצאו ויברכו את העם.** אמרו ויהי נועם ה' אלהינו עלינו (תהלים צ יז) , יהי רצון שתשרה שכינה במעשה ידיכם. לפי שכל שבעת ימי המלואים, שהעמידו משה למשכן ושמש בו ופרקו בכל יום, לא שרתה בו שכינה, והיו ישראל נכלמים ואומרים למשה, משה רבנו, כל הטורח שטרחנו, שתשרה שכינה בינינו ונדע שנתכפר לנו עון העגל. לכך אמר להם זה הדבר אשר צוה ה' תעשו וירא אליכם כבוד ה' (פסוק ו) , אהרן אחי כדאי וחשוב ממני שעל ידי קרבנותיו ועבודתו תשרה שכינה בכם ותדעו שהמקום בחר בו:
@282 **וירנו.** כתרגומו:
@284 **ותצא אש.** רבי אלעזר אומר לא מתו בני אהרן אלא על ידי שהורו הלכה בפני משה רבן. רבי ישמעאל אומר שתויי יין נכנסו למקדש, תדע שאחר מיתתן הזהיר הנותרים שלא יכנסו שתויי יין למקדש. משל למלך, שהיה לו בן בית וכו' , כדאיתא בויקרא רבה:
@285 **הוא אשר דבר** וגו' **.** היכן דבר ונועדתי שמה לבני ישראל ונקדש בכבודי (שמות כט מג) . אל תקרי בכבודי אלא במכבדי. אמר לו משה לאהרן, אהרן אחי יודע הייתי שיתקדש הבית במידעיו של מקום והייתי סבור או בי או בך, עכשיו רואה אני שהם גדולים ממני וממך: **וידם אהרן.** קבל שכר על שתיקתו. ומה שכר קבל, שנתיחד עמו הדבור, שנאמרה לו לבדו פרשת שתויי יין: **בקרבי.** בבחירי: **ועל פני כל העם אכבד.** כשהקדוש ברוך הוא עושה דין בצדיקים מתירא ומתעלה ומתקלס, אם כן באלו, כל שכן ברשעים, וכן הוא אומר (תהלים סח לו) נורא אלהים ממקדשיך, אל תקרא ממקדשיך אלא ממקדשיך:
@286 **דד אהרן.** עזיאל אחי עמרם היה, שנאמר (שמות ו יח) ובני קהת וגו' : **שאו את אחיכם** וגו' **.** כאדם האומר לחברו העבר את המת מלפני הכלה, שלא לערבב את השמחה:
@287 **בכתנתם.** של מתים. מלמד שלא נשרפו בגדיהם אלא נשמתם, כמין שני חוטין של אש נכנסו לתוך חטמיהם:
@288 **אל תפרעו.** אל תגדלו שער. מכאן שאבל אסור בתספורת, אבל אתם אל תערבבו שמחתו של מקום: **ולא תמתו.** הא אם תעשו כן תמותו: **ואחיכם כל בית ישראל.** מכאן שצרתן של תלמידי חכמים מטלת על הכל להתאבל בה:
@291 **יין ושכר.** יין דרך שכרותו: **בבאכם אל אהל מועד.** אין לי אלא בבואם להיכל, בגשתם למזבח מנין, נאמר כאן ביאת אהל מועד, ונאמר בקדוש ידים ורגלים ביאת אהל מועד, מה להלן עשה גישת מזבח כביאת אהל מועד, אף כאן עשה גישת מזבח כביאת אהל מועד:
@292 **ולהבדיל.** כדי שתבדילו בין עבודה קדושה למחללת, הא למדת שאם עבד, עבודתו פסולה:
@293 **ולהורת.** למד שאסור שכור בהוראה. יכול יהא חיב מיתה, תלמוד לומר אתה ובניך אתך ולא תמותו (פסוק ט) , כהנים בעבודתם במיתה, ואין חכמים בהוראתם במיתה:
@294 **הנותרים.** מן המיתה. מלמד שאף עליהם נקנסה מיתה על עון העגל, הוא שנאמר (דברים ט כ) ובאהרן התאנף ה' מאד להשמידו, ואין השמדה אלא כלוי בנים, שנאמר (עמוס ב ט) ואשמיד פריו ממעל, ותפלתו של משה בטלה מחצה, שנאמר (דברים ט כ) ואתפלל גם בעד אהרן בעת ההיא: **קחו את המנחה.** אף על פי שאתם אוננין וקדשים אסורים לאונן: **את המנחה.** זו מנחת שמיני ומנחת נחשון: **ואכלוה מצות.** מה תלמוד לומר, לפי שהיא מנחת צבור ומנחת שעה ואין כיוצא בה לדורות, הצרך לפרש בה דין שאר מנחות:
@295 **וחק בניך.** אין לבנות חק בקדשים: **כי כן צויתי.** באנינות יאכלוה:
@296 **ואת חזה התנופה.** של שלמי צבור: **תאכלו במקום טהור.** וכי את הראשונים אכלו במקום טמא, אלא הראשונים שהם קדשי קדשים הזקקה אכילתם במקום קדוש, אבל אלו אין צריכים תוך הקלעים, אבל צריכים הם להאכל תוך מחנה ישראל, שהוא טהור מלכנס שם מצורעים. מכאן שקדשים קלים נאכלין בכל העיר: **אתה ובניך ובנתיך.** אתה ובניך בחלק, אבל בנותיך לא בחלק, אלא אם תתנו להן מתנות, רשאות הן לאכול בחזה ושוק. או אינו אלא אף הבנות בחלק, תלמוד לומר כי חקך וחק בניך נתנו, חק לבנים ואין חק לבנות:
@297 **שוק התרומה וחזה התנופה.** לשון אשר הונף ואשר הורם. תנופה מוליך ומביא, תרומה מעלה ומוריד. ולמה חלקן הכתוב, תרומה בשוק ותנופה בחזה, לא ידענו, ששניהם בהרמה והנפה: **על אשי החלבים.** מכאן שהחלבים למטה בשעת תנופה, וישוב המקראות שלא יכחישו זה את זה, כבר פרשתי שלשתן בצו את אהרן (ז ל) :
@298 **שעיר החטאת.** שעיר מוספי ראש חדש. ושלשה שעירי חטאות קרבו בו ביום שעיר עזים, ושעיר נחשון ושעיר ראש חדש, ומכלן לא נשרף אלא זה. ונחלקו בדבר חכמי ישראל יש אומרים, מפני הטמאה שנגעה בו נשרף. ויש אומרים, מפני אנינות נשרף, לפי שהוא קדשי דורות, אבל בקדשי שעה סמכו על משה שאמר להם במנחה (פסוק יב) ואכלוה מצות: **דרש דרש.** שתי דרישות הללו מפני מה נשרף זה, ומפני מה נאכלו אלו, כך הוא בתורת כהנים: **על אלעזר ועל איתמר.** בשביל כבודו של אהרן הפך פניו כנגד הבנים וכעס: **לאמר.** אמר להם, השיבוני על דברי:
@299 **מדוע לא אכלתם את החטאת במקום הקדש.** וכי חוץ לקדש אכלוה, והלא שרפוה, ומה הוא אומר במקום הקדש, אלא אמר להם שמא חוץ לקלעים יצאה ונפסלה: **כי קדש קדשים הוא.** ונפסלת ביוצא, והם אמרו לו לאו. אמר להם הואיל ובמקום הקדש היתה, מדוע לא אכלתם אותה: **ואתה נתן לכם לשאת** וגו' **.** שהכהנים אוכלים ובעלים מתכפרים: **לשאת את עון העדה.** מכאן למדנו ששעיר ראש חדש היה, שהוא מכפר על עון טמאת מקדש וקדשיו, שחטאת שמיני וחטאת נחשון לא לכפרה באו:
@300 **הן לא הובא** וגו' **.** שאלו הובא היה לכם לשרפה, כמו שנאמר (ויקרא ו כג) וכל חטאת אשר יובא מדמה וגו' : **אכל תאכלו אתה.** היה לכם לאכלה אף על פי שאתם אוננים: **כאשר צויתי.** לכם במנחה:
@301 **וידבר אהרן.** אין לשון דבור אלא לשון עז, שנאמר (במדבר כא ה) וידבר העם וגו' . אפשר משה קצף על אלעזר ועל איתמר, ואהרן מדבר, הא ידעת שלא היתה אלא מדרך כבוד. אמרו אינו בדין שיהא אבינו יושב ואנו מדברים לפניו, ואינו בדין שיהא תלמיד משיב את רבו. יכול מפני שלא היה באלעזר להשיב, תלמוד לומר (במדבר לא כא) ויאמר אלעזר הכהן אל אנשי הצבא וגו' , הרי כשרצה, דבר לפני משה ולפני הנשיאים, זו מצאתי בספרי של פנים שני: **הן היום הקריבו.** מהו אומר, אלא אמר להם משה שמא זרקתם דמה אוננים, שהאונן שעבד חלל. אמר לו אהרן וכי הם הקריבו, שהם הדיוטות, אני הקרבתי, שאני כהן גדול ומקריב אונן: **ותקראנה אתי כאלה.** אפלו לא היו המתים בני אלא שאר קרובים שאני חיב להיות אונן עליהם כאלו, כגון כל האמורים בפרשת כהנים שהכהן מטמא להם: **ואכלתי חטאת.** ואם אכלתי הייטב וגו' : **היום.** אבל אנינות לילה מתר, שאין אונן אלא יום קבורה: **הייטב בעיני ה'.** אם שמעת בקדשי שעה אין לך להקל בקדשי דורות:
@302 **וייטב בעיניו.** הודה ולא בוש לומר לא שמעתי:
@303 **אל משה ואל אהרן.** למשה אמר שיאמר לאהרן: **לאמר אליהם.** אמר שיאמר לאלעזר ולאיתמר, או אינו אלא לאמר לישראל, כשהוא אומר דברו אל בני ישראל, הרי דבור אמור לישראל, הא מה אני מקים לאמר אליהם, לבניו לאלעזר ולאיתמר:
@304 **דברו אל בני ישראל.** את כלם השוה להיות שלוחים בדבר זה, לפי שהשוו בדמימה וקבלו עליהם גזרת המקום באהבה: **זאת החיה.** לשון חיים, לפי שישראל דבוקים במקום וראויין להיות חיים, לפיכך הבדילם מן הטמאה וגזר עליהם מצות, ולאמות העולם לא אסר כלום. משל לרופא שנכנס לבקר את החולה וכו' , כדאיתא במדרש רבי תנחומא: **זאת החיה.** מלמד שהיה משה אוחז בחיה ומראה אותה לישראל, זאת תאכלו וזאת לא תאכלו: **את זה תאכלו** וגו' **.** אף בשרצי המים אחז מכל מין ומין והראה להם. וכן בעוף ואת אלה תשקצו מן העוף. וכן בשרצים וזה לכם הטמא: **זאת החיה מכל הבהמה.** מלמד שהבהמה בכלל חיה:
@305 **מפרסת.** כתרגומו סדיקא: **פרסה.** פלאנט''ה בלע''ז [כף רגל] : **ושסעת שסע.** שמבדלת מלמעלה ומלמטה בשתי צפרנין, כתרגומו ומטלפא טלפין, שיש שפרסותיו סדוקות מלמעלה ואינן שסועות ומבדלות לגמרי, שמלמטה מחברות: **מעלת גרה.** מעלה ומקיאה האוכל ממעיה ומחזרת אותו לתוך פיה לכתשו ולטחנו הדק: **גרה.** כך שמו. ויתכן להיות מגזרת מים הנגרים (שמואל ב יד יד) , שהוא נגרר אחר הפה. ותרגומו פשרא שעל ידי הגרה האוכל נפשר ונמוח: **בבהמה.** תיבה זו יתרה היא לדרשה, להתיר את השליל הנמצא במעי אמו: **אתה תאכלו.** ולא בהמה טמאה. והלא באזהרה היא, אלא לעבור עליה בעשה ולא תעשה:
@310 **מבשרם לא תאכלו.** אין לי אלא אלו, שאר בהמה טמאה שאין לה שום סימן טהרה מנין, אמרת קל וחמר ומה אלו שיש בהן קצת סימני טהרה אסורות וכו' : **מבשרם.** על בשרם באזהרה, ולא על עצמות וגידין וקרנים וטלפים: **ובנבלתם לא תגעו.** יכול יהו ישראל מזהרים על מגע נבלה, תלמוד לומר אמור אל הכהנים וגו' (ויקרא כא א) , כהנים מזהרין ואין ישראל מזהרין. קל וחמר מעתה ומה טמאת מת חמורה, לא הזהיר בה אלא כהנים, טמאת נבלה קלה לא כל שכן. ומה תלמוד לומר לא תגעו, ברגל. זהו שאמרו חיב אדם לטהר עצמו ברגל:
@311 **סנפיר.** אלו ששט בהם: **קשקשת.** אלו קלפים הקבועים בו, כמו שנאמר (שמואל א יז ה) ושריון קשקשים הוא לבוש:
@312 **שרץ.** בכל מקום משמעו דבר נמוך שרוחש ונע ונד על הארץ:
@313 **ושקץ יהיו.** לאסר את עירוביהן, אם יש בו בנותן טעם: **מבשרם.** אינו מזהר על הסנפירים ועל העצמות: **ואת נבלתם תשקצו.** לרבות יבחושין שסננן. יבחושין מושקירונ''ש בלע''ז :
@314 **כל אשר אין לו** וגו' **.** מה תלמוד לומר, שיכול אין לי שיהא מתר אלא המעלה סימנין שלו ליבשה, השירן במים מנין, תלמוד לומר כל אשר אין לו סנפיר וקשקשת במים, הא אם היו לו במים אף על פי שהשירן בעליתו מתר:
@315 **לא יאכלו.** לחיב את המאכילן לקטנים. שכך משמעו לא יהיו נאכלים על ידך. או אינו אלא לאסרו בהנאה, תלמוד לומר (דברים יד יב) לא תאכלו, באכילה אסורין בהנאה מתרין. כל עוף שנאמר בו למינה, למינו, למינהו, יש באותו המין שאין דומין זה לזה, לא במראיהם ולא בשמותם, וכלן מין אחד:
@318 **הנץ.** אישפרויי''ר :
@319 **השלך.** פרשו רבותינו זה השולה דגים מן הים. וזהו שתרגם אנקלוס ושלינונא: **כוס וינשוף.** הם צואיטי''ש הצועקים בלילה ויש להם לסתות כאדם. ועוד אחר דומה לו שקורין יב''ן [לילית] :
@320 **התנשמת.** היא קלב''א שורי''ץ [עטלף] ודומה לעכבר ופורחת בלילה. ותנשמת האמורה בשרצים היא דומה לה, ואין לה עינים וקורין לה טלפ''א [חפרפרת] :
@321 **החסידה.** זו דיה לבנה ציגוני''ה . ולמה נקרא שמה חסידה, שעושה חסידות עם חברותיה במזונות: **האנפה.** היא דיה רגזנית. ונראה לי שזו היא שקורין לה היירו''ן : **הדוכיפת.** תרנגול הבר וכרבלתו כפולה ובלע''ז הירופ''א , ולמה נקרא שמו דוכיפת, שהודו כפות, וזו היא כרבלתו. תרגום אנקלוס ונגר טורא נקרא על שם מעשיו, כמו שפרשו רבותינו במסכת גטין בפרק מי שאחזו (דף סח ב) :
@322 **שרץ העוף.** הם הדקים הנמוכים הרוחשין על הארץ, כגון זבובים וצרעין ויתושין וחגבים:
@323 **על ארבע.** על ארבע רגלים: **ממעל לרגליו.** סמוך לצוארו יש לו כמין שתי רגלים לבד ארבע רגליו, וכשרוצה לעוף ולקפוץ מן הארץ מתחזק באותן שתי כרעים ופורח, ויש הרבה מהם במקומנו בינותינו, כאותן שקורין לנגושט''א , אבל אין אנו בקיאין בהן, שארבעה סימני טהרה נאמרו בהם ארבע רגלים, וארבע כנפים, וקרסלין אלו כרעים הכתובים כאן, וכנפיו חופין את רבו. וכל סימנים הללו מצויין באותן שבינותינו, אבל יש שראשן ארוך ויש שאין להם זנב וצריך שיהא שמו חגב, ובזה אין אנו יודעים להבדיל ביניהם:
@325 **וכל שרץ העוף** וגו' **.** בא ללמד שאם יש לו חמש טהור:
@326 **ולאלה.** העתידין להאמר למטה בענין: **תטמאו.** כלומר בנגיעתם יש טמאה:
@327 **וכל הנשא מנבלתם.** כל מקום שנאמרה טמאת משא, חמורה מטמאת מגע, שהיא טעונה כבוס בגדים:
@328 **מפרסת פרסה ושסע איננה שסעת.** כגון גמל שפרסתו סדוקה למעלה, אבל למטה היא מחברת. כאן למדך שנבלת בהמה טמאה מטמאה, ובענין שבסוף הפרשה פרש על בהמה טהורה:
@329 **על כפיו.** כגון כלב ודב וחתול: **טמאים הם לכם.** למגע:
@331 **וזה לכם הטמא.** כל טמאות הללו אינן לאסור אכילה אלא לטמאה ממש, להיות טמא במגען ונאסר לאכול תרומה וקדשים ולכנס במקדש: **החלד.** מושטיל''ה [נמיה] : **והצב.** פרוי''ט [קרפדה] שדומה לצפרדע:
@332 **והאנקה.** היריצו''ן [קפוד] : **והלטאה.** לישרד ''ה: **והחמט.** לימצ''ה [חלזון] : **והתנשמת.** טלפ''א [חפרפרת] :
@334 **במים יובא.** ואף לאחר טבילתו טמא הוא לתרומה עד הערב, ואחר כך וטהר בהערב השמש:
@335 **אל תוכו.** אין כלי חרס מטמא אלא מאוירו: **כל אשר בתוכו יטמא.** הכלי חוזר ומטמא מה שבאוירו: **ואתו תשברו.** למד שאין לו טהרה במקוה:
@336 **מכל האכל אשר יאכל.** מוסב על מקרא העליון, כל אשר בתוכו יטמא, מכל האכל אשר יאכל אשר יבא עליו מים והוא בתוך כלי חרס הטמא, יטמא. וכן כל משקה אשר ישתה בכל כלי, והוא בתוך כלי חרס הטמא, יטמא. למדנו מכאן דברים הרבה. למדנו שאין אוכל מכשר ומתקן לקבל טמאה עד שיבאו עליו מים פעם אחת, ומשבאו עליו מים פעם אחת מקבל טמאה לעולם ואפלו נגוב. והיין והשמן וכל הנקרא משקה מכשיר זרעים לטמאה כמים. שכך יש לדרוש המקרא, אשר יבא עליו מים או כל משקה אשר ישתה בכל כלי יטמא האוכל. ועוד למדו רבותינו מכאן, שאין ולד הטמאה מטמא כלים, שכך שנינו יכול יהיו כל הכלים מטמאין מאויר כלי חרס, תלמוד לומר כל אשר בתוכו יטמא מכל האוכל, אוכל מטמא מאויר כלי חרס, ואין כל הכלים מטמאין מאויר כלי חרס, לפי שהשרץ אב הטמאה והכלי, שנטמא ממנו, ולד הטמאה, לפיכך אינו חוזר ומטמא כלים שבתוכו. ולמדנו עוד, שהשרץ שנפל לאויר תנור והפת בתוכו, ולא נגע השרץ בפת, התנור ראשון והפת שניה. ולא נאמר רואין את התנור כאלו מלא טמאה ותהא הפת תחלה, שאם אתה אומר כן לא נתמעטו כל הכלים מלהטמא מאויר כלי חרס, שהרי טמאה עצמה נגעה בהן מגבן. ולמדנו עוד על ביאת מים, שאינה מכשרת זרעים אלא אם כן נפלו עליהן משנתלשו, שאם אתה אומר מקבלין הכשר במחבר, אין לך שלא באו עליו מים, ומהו אומר אשר יבוא עליו מים, משנתלשו. ולמדנו עוד שאין אוכל מטמא אחרים אלא אם כן יש בו כביצה, שנאמר אשר יאכל, אוכל הנאכל בבת אחת, ושערו חכמים אין בית הבליעה מחזיק יותר מביצת תרנגולת:
@337 **תנור וכירים.** כלים המטלטלין הם, והם של חרס ויש להן תוך, ושופת את הקדרה על נקב החלל ושניהם פיהם למעלה: **יתץ.** שאין לכלי חרס טהרה בטבילה: **וטמאים יהיו לכם.** שלא תאמר מצוה אני לנתצם, תלמוד לומר וטמאים יהיו לכם, אם רצה לקימן בטמאתן רשאי:
@338 **אך מעין ובור מקוה מים.** המחברים לקרקע, אין מקבלין טמאה. ועוד יש לך ללמוד יהיה טהור הטובל בהם מטמאתו: **ונגע בנבלתם יטמא.** אפלו הוא בתוך מעין ובור ונוגע בנבלתם יטמא, שלא תאמר קל וחומר אם מטהר את הטמאים מטמאתם, קל וחמר שיציל את הטהור מלטמא, לכך נאמר ונוגע בנבלתם יטמא:
@339 **זרע זרוע.** זריעה של מיני זרעונין. זרוע שם דבר הוא, כמו ויתנו לנו מן הזרועים: (דניאל א יב) **טהור הוא.** למדך הכתוב שלא הכשר ונתקן לקרות אוכל לקבל טמאה, עד שיבואו עליו מים:
@340 **וכי יתן מים על זרע.** לאחר שנתלש, שאם תאמר יש הכשר במחבר, אין לך זרע שלא הכשר: **מים על זרע.** בין מים בין שאר משקין, בין נפלו הם על הזרע, בין הזרע נפל לתוכן, הכל נדרש בתורת כהנים: **ונפל מנבלתם עליו.** אף משנגב מן המים, שלא הקפידה תורה אלא להיות עליו שם אוכל, ומשירד עליו הכשר קבלת טמאה פעם אחת, שוב אינו נעקר המנו:
@341 **בנבלתה.** ולא בעצמות וגידים ולא בקרנים וטלפים ולא בעור:
@342 **והנשא את נבלתה.** חמורה טמאת משא מטמאת מגע, שהנושא מטמא בגדים, והנוגע אין בגדיו טמאין, שלא נאמר בו יכבס בגדיו: **והאכל מנבלתה.** יכול תטמאנו אכילתו, כשהוא אומר בנבלת עוף טהור (ויקרא כב ח) נבלה וטרפה לא יאכל לטמאה בה, אותה מטמאה בגדים באכילתה, ואין נבלת בהמה מטמאה בגדים באכילתה בלא משא, כגון אם תחבה לו חברו בבית הבליעה, אם כן מה תלמוד לומר האכל, לתן שעור לנושא ולנוגע כדי אכילה והוא כזית: **וטמא עד הערב.** אף על פי שטבל צריך הערב שמש:
@343 **השרץ על הארץ.** להוציא את היתושין שבכליסין ושבפולין ואת הזיזין שבעדשים, שהרי לא שרצו על הארץ אלא בתוך האוכל, אבל משיצאו לאויר ושרצו הרי נאסרו: **לא יאכל.** לחיב על המאכיל כאוכל. ואין קרוי שרץ אלא דבר נמוך קצר רגלים, שאינו נראה אלא כרוחש ונד:
@344 **הולך על גחון.** זה נחש, ולשון גחון שחיה, שהולך שח ונופל על מעיו: **כל הולך.** להביא השלשולין ואת הדומה לדומה: **הולך על ארבע.** זה עקרב: **כל.** להביא את החפושית אישקרבו''ט בלע''ז ואת הדומה לדומה: **מרבה רגלים.** זה נדל, שרץ שיש לו רגלים מראשו ועד זנבו לכאן ולכאן, וקורין ציינפיי''ש :
@345 **אל תשקצו.** באכילתן, שהרי כתיב נפשותיכם, ואין שקוץ נפש במגע, וכן ולא תטמאו באכילתן: **ונטמתם בם.** אם אתם מטמאין בהם בארץ אף אני מטמא אתכם בעולם הבא ובישיבת מעלה:
@346 **כי אני ה' אלהיכם.** כשם שאני קדוש שאני ה' אלהיכם, כך והתקדשתם קדשו עצמכם למטה: **והייתם קדשים.** לפי שאני אקדש אתכם למעלה ובעולם הבא: **ולא תטמאו** וגו' **.** לעבור עליהם בלאוין הרבה. וכל לאו מלקות, וזהו שאמרו בתלמוד [ מכות טז ] אכל פוטיתא לוקה ארבע, נמלה לוקה חמש, צרעה לוקה שש:
@347 **כי אני ה' המעלה אתכם.** על מנת שתקבלו מצותי העלתי אתכם. דבר אחר כי אני ה' המעלה אתכם, בכלן כתיב והוצאתי, וכאן כתיב המעלה, תנא דבי רבי ישמעאל אלמלי לא העלתי את ישראל ממצרים אלא בשביל שאין מטמאין בשרצים כשאר אמות, דים, ומעליותא היא גבייהו, זהו לשון מעלה:
@349 **להבדיל.** לא בלבד השונה, אלא שתהא יודע ומכיר ובקי בהן: **בין הטמא ובין הטהר.** צריך לומר בין חמור לפרה והלא כבר מפורשים הם, אלא בין טמאה לך לטהורה לך, בין נשחט חציו של קנה לנשחט רבו: **ובין החיה הנאכלת.** צריך לומר בין צבי לערוד, והלא כבר מפורשים הם, אלא בין שנלדו בה סימני טרפה כשרה, לנלדו בה סימני טרפה פסולה:
@350 **ויוסף עוד דוד.** לאסוף: **את כל בחור בישראל שלשים אלף.** לפי שנאספו עליו כשהמליכוהו בחברון, וזו היתה אסיפה שניה, לכך נאמר ויוסף עוד:
@351 **מבעלי יהודה.** היא קרית יערים; כמו שנאמר ביהושע ( טו ט ): ותאר הגבול ועלה בעלה היא קרית יערים, וכן בדברי הימים ( יג ו ): **ויעל דוד וכל ישראל בעלתה היא קרית יערים.** ו'בעל' לשון 'מישור': **ויקם וילך דוד וגו' מבעלי יהודה.** שנאספו שם להעלות משם את הארון וגו': **אשר נקרא שם שם.** אשר נקרא לו לארון שם, ומהו השם, שהיה שם ה' צבאות עליו:
@352 **אל עגלה חדשה.** טעה בדבר שאפילו תינוקות של בית רבן יודעין אותו, כי עבודת הקדש עליהם בכתף ישאו ( במדבר ז ט ), ולפי שאמר ( תהלים קיט נד ): זמירות היו לי חקיך בבית מגורי, נענש לבא לידי כך, ומת עוזא על ידו, לפיכך כשהביאו מבית עובד, הביאו בכתף, שנאמר ( בדברי הימים א טו יב יג ): **ויאמר להם אתם ראשי האבות ללוים התקדשו אתם ואחיכם והעליתם את ארון וגו'.** כי למבראשונה לא אתם פרץ ה' אלהינו בנו כי לא דרשנוהו כמשפט:
@353 **עם ארון האלהים.** הרי זה מקרא קצר, והם באים עם ארון האלהים:
@354 **בבל עצי ברושים.** שמתקנים מהם כלי זמר:
@355 **כי שמטו הבקר.** כי שמטוהו הבקר ונענעוהו, וכן תרגם יונתן: ארי מרגוהי תוריא; כמו שמתרגם ( דברים יט ה ): ונדחה ידו בגרזן, ותתמריג ידיה בפרזלא:
@356 **על השל.** על השגגה, שהיה לו לדרוש קל וחומר, נושאיו נשא בירדן, הוא עצמו לא כל שכן:
@359 **עובד אדום.** לוי היה, כמו שכתוב בדברי הימים ( א טו יח ), ומן השוערים היה ( שם ):
@360 **ויברך ה' וגו'.** אשתו ושמונה כלותיה ילדו ששה בנים בכרס אחד, שנאמר ( דברי הימים-א כו ו ח ): ופעלתי השמיני; ששים ושנים לעובד אדום:
@363 **מכרכר.** מרקד: **אפוד בד.** מעיל בוץ, פורציינ"ט בלע"ז, ויונתן תרגם: כרדוט; וכן תרגם יונתן 'מעילים' דתמר אחות אבשלום ( לקמן יג יח ), כרדוטין:
@368 **ואשפר.** אחד מששה בפר ( פסחים לו ב ): **אשישה אחת.** גרבא דחמרא ( שם ):
@369 **אחד הרקים.** ( תרגום: ) חד מן סריקיא ( לשון תרגום יונתן ):
@371 **ונקלותי עוד.** לפניו, יותר מזאת שהקילותי בעצמי עתה: **עמם אכבדה.** אינם מבזין אותי, אלא חשוב אני בעיניהם על זאת:
@372 **לא היה לה ילד.** מאותו היום והלאה:
@373 **וה' הניח לו.** אמר, הרי נתקיים ( דברים יב י ): והניח לכם מכל אויביכם וגו', מה כתיב אחריו, והיה המקום אשר יבחר וגו', מעתה עלינו לבנות בית הבחירה:
@376 **ויהי בלילה ההוא.** אמר רבי חנינא בר פפא: **אמר לו הקב"ה לנתן, האדם הזה שאני משלחך אצלו, מהיר הוא, שמא ישכור פועלים ונמצאתי מפסידו, מהר ואמור לו, לא אתה תבנה הבית.** רבי סימון אומר: האדם הזה שאני משלחך אצלו, נדרן הוא, כענין שנאמר ( תהלים קלב ב ג ): אשר נשבע לה' נדר לאביר יעקב אם אבא באהל ביתי, שמא יאמר איני אוכל ואיני שותה עד שאעשה כך, ונמצאתי מפסידו ( ילקוט שמעוני רמז קמג ):
@378 **באהל ובמשכן.** משכן שילה לא היתה בו תקרה, אלא בית של אבנים מלמטן, ויריעות מלמעלן:
@379 **הדבר דברתי.** לשון תמיה הוא, לכך הוא נקוד ה"א חטף פת"ח, והדל"ת רפי:
@380 **מן הנוה.** דיר הרועים, כמו ( צפניה ב ו ): נות כרות רועים:
@381 **כשם הגדולים.** זהו שאומרים מגן דוד: **ואכריתה את כל איביך.** ולכך עלה על לבך לבנות הבית, כמה שכתוב בתורה:
@382 **ושמתי מקום.** עוד אני חפץ להשקיט, שיהא שקט ושליו את עמי בימי בנך:
@383 **ולמן היום אשר צויתי.** מחובר על העליון, ולא יוסיפו לענותו כאשר בראשונה קודם השופטים, וכאשר עשו מימי השופטים עד כאן: **והניחותי לך.** יותר ויותר, עד שתנוח מכל אויביך: **והגיד לך ה'.** היום על ידי, כי בית יעשה לך להושיב בנך על כסאך, ויתקיים לך בית המלכות, והוא יבנה הבית:
@386 **בשבט אנשים.** זה הדד ורזון בן אלידע: **ונגעי בני אדם.** זה אשמדאי, שדחהו ממלכותו, והשדים בני אדם הראשון הם, שכל מאה ושלשים שנה שפירש אדם מאשתו במות הבל, היו הרוחות מתייחמות ויולדות הימנו ( ילקוט שמעוני רמז קמו ):
@391 **אשה כי תזריע.** אמר ר' שמלאי כשם שיצירתו של אדם אחר כל בהמה חיה ועוף במעשה בראשית, כך תורתו נתפרשה אחר תורת בהמה חיה ועוף: **כי תזריע.** לרבות שאפלו ילדתו מחוי, שנמחה ונעשה כעין זרע, אמו טמאה לידה: **כימי נדת דותה תטמא.** כסדר כל טמאה האמורה בנדה מטמאה בטמאת לידה, ואפלו נפתח הקבר בלא דם: **דותה.** לשון דבר הזב מגופה. לשון אחר לשון מדוה וחולי, שאין אשה רואה דם שלא תחלה (י''ג: תחלה) ראשה ואבריה כבדין עליה:
@393 **תשב.** אין תשב אלא לשון עכבה, כמו (דברים א מו) ותשבו בקדש, וישב באלני ממרא (בראשית יג יח) : **בדמי טהרה.** אף על פי שרואה דם טהורה. בדמי טהרה לא מפיק ה''א, והוא שם דבר, כמו טוהר: **ימי טהרה.** מפיק ה''א, ימי טוהר שלה: **בכל קדש** וגו' **.** לרבות את התרומה, לפי שזו טבולת יום ארוך, שטבלה לסוף שבעה ואין שמשה מעריב לטהרה עד שקיעת החמה של יום ארבעים, של מחר תביא את כפרת טהרתה: **לא תגע.** אזהרה לאוכל, כמו ששנויה ביבמות (עה א) :
@396 **והקריבו.** למדך שאין מעכבה לאכול בקדשים אלא אחד מהם. ואי זה הוא, זה חטאת, שנאמר וכפר עליה הכהן וטהרה, מי שהוא בא לכפר, בו הטהרה תלויה: **וטהרה.** מכלל שעד כאן קרויה טמאה:
@397 **אחד לעלה ואחד לחטאת.** לא הקדימה הכתוב אלא למקראה, אבל הקרבת חטאת קודם לעולה, כך שנינו בזבחים בפרק כל התדיר (זבחים צ א) :
@399 **שאת או ספחת** וגו' **.** שמות נגעים הם ולבנות זו מזו: **בהרת.** חברבורות טיי''א בלע''ז [כתם] וכן (איוב לז כא) בהיר הוא בשחקים: **אל אהרן** וגו' **.** גזרת הכתוב היא שאין טמאת נגעים וטהרתן אלא על פי כהן:
@400 **ושער בנגע הפך לבן.** מתחלה שחור והפך ללבן בתוך הנגע, ומעוט שער שנים: **עמק מעור בשרו.** כל מראה לבן עמק הוא, כמראה חמה עמוקה מן הצל: **וטמא אתו.** יאמר לו טמא אתה, ששער לבן סימן טמאה הוא גזרת הכתוב:
@401 **ועמק אין מראה.** לא ידעתי פרושו: **והסגיר.** יסגירנו בבית אחד ולא יראה עד סוף השבוע, ויוכיחו סימנים עליו:
@402 **בעיניו.** במראהו ובשיעורו הראשון: **והסגירו שנית.** הא אם פשה בשבוע ראשון טמא מחלט:
@403 **כהה.** הכהה מראיתו, הא אם עמד במראיתו או פשה טמא: **מספחת.** שם נגע טהור: **וכבס בגדיו וטהר.** הואיל ונזקק להסגר נקרא טמא וצריך טבילה:
@405 **וטמאו הכהן.** ומשטמאו הרי הוא מחלט וזקוק לצפרים ולתגלחת ולקרבן האמור בפרשת זאת תהיה: **צרעת הוא.** המספחת הזאת: **צרעת.** לשון נקבה: **נגע.** לשון זכר:
@407 **ומחית.** שינמינ''ט בלע''ז [רפוי] , שנהפך מקצת הלובן שבתוך השאת למראה בשר, אף הוא סימן טמאה, שער לבן בלא מחיה, ומחיה בלא שער לבן, ואף על פי שלא נאמרה מחיה אלא בשאת, אף בכל המראות ותולדותיהן הוא סימן טמאה:
@408 **צרעת נושנת הוא.** מכה ישנה היא תחת המחיה, וחבורה זו נראית בריאה מלמעלה ותחתיה מלאה לחה, שלא תאמר הואיל ועלתה מחיה אטהרנה:
@409 **מראשו.** של אדם ועד רגליו: **לכל מראה עיני הכהן.** פרט לכהן שחשך מאורו:
@411 **וביום הראות בו בשר חי.** אם צמחה בו מחיה הרי כבר פרש שהמחיה סימן טמאה, אלא הרי שהיה הנגע באחד מעשרים וארבעה ראשי אברים שאין מטמאין משום מחיה, לפי שאין נראה הנגע כלו כאחד ששופע אלך ואלך, וחזר ראש האבר ונתגלה שפועו על ידי שמן, כגון שהבריא ונעשה רחב ונראית בו המחיה, למדנו הכתוב שתטמא: **וביום.** מה תלמוד לומר, ללמד יש יום שאתה רואה בו ויש יום שאין אתה רואה בו, מכאן אמרו חתן נותנין לו כל שבעת ימי המשתה לו ולכסותו ולביתו, וכן ברגל נותנין לו כל ימי הרגל:
@412 **צרעת הוא.** הבשר ההוא. בשר לשון זכר:
@415 **שחין.** לשון חמום, שנתחמם הבשר בלקוי הבא לו מחמת מכה, שלא מחמת האור: **ונרפא.** השחין העלה ארוכה ובמקומו העלה נגע אחר:
@416 **או בהרת לבנה אדמדמת.** שאין הנגע לבן חלק אלא פתוך ומעורב בשתי מראות לובן ואודם:
@417 **מראה שפל.** ואין ממשה שפל, אלא מתוך לבנוניתו הוא נראה שפל ועמוק, כמראה חמה עמוקה מן הצל:
@419 **נגע הוא.** השאת הזאת או הבהרת:
@420 **תחתיה.** במקומה: **צרבת השחין.** כתרגומו רושם שיחנא, אינו אלא רושם החמום הנכר בבשר. כל צרבת לשון רגיעת עור הנרגע מחמת חמום, כמו (יחזקאל כא ג) ונצרבו בה כל פנים, רייטרי''ר בלע''ז : **צרבת.** ריטריימינ''ט בלע''ז :
@421 **מחית המכוה.** שיינימנ''ט בלע''ז [רפוי] כשחיתה המכוה נהפכה לבהרת פתוכה או לבנה חלקה. וסימני מכוה וסימני שחין שוים הם, ולמה חלקן הכתוב, לומר שאין מצטרפין זה עם זה, נלד חצי גריס בשחין וחצי גריס במכוה לא ידנו כגריס:
@426 **בראש או בזקן.** בא הכתוב לחלק בין נגע שבמקום שער לנגע שבמקום בשר, שזה סימנו בשער לבן וזה סימנו בשער צהוב:
@427 **ובו שער צהב.** שנהפך שער שחור שבו לצהוב: **נתק הוא.** כך שמו של נגע, שבמקום שער:
@428 **ושער שחר אין בו.** הא אם היה בו שער שחור, טהור. ואין צריך להסגר ששער שחור סימן טהרה הוא בנתקים, כמו שנאמר (פסוק לז) ושער שחר צמח בו וגו' :
@429 **והנה לא פשה** וגו' **.** הא אם פשה או היה בו שער צהוב טמא:
@430 **והתגלח.** סביבות הנתק: **ואת הנתק לא יגלח.** מניח שתי שערות סמוך לו סביב, כדי שיהא נכר אם פשה, שאם יפשה ועבר השערות ויצא למקום הגלוח, טמא:
@432 **אחרי טהרתו.** אין לי אלא פושה לאחר הפטור, מנין אף בסוף שבוע ראשון ובסוף שבוע שני, תלמוד לומר פשה יפשה:
@434 **ושער שחר.** מנין אף הירוק והאדום שאינו צהוב, תלמוד לומר ושער. ולמה צהוב דומה, לתבנית הזהב. צהוב, כמו זהוב אורבל''א בלע''ז [זהוב] : **טהור הוא וטהרו הכהן.** הא טמא שטהרו הכהן, לא טהור:
@435 **בהרת.** חברבורות:
@436 **כהות לבנת.** שאין לובן שלהן עז אלא כהה: **בהק.** כמין לובן הנראה בבשר אדם אדום, שקורין רו''ש [אדמוני] , בין חברבורות אדמימותו, קרוי בהק, כאיש עדשן שבין עדשה לעדשה מבהיק הבשר בלובן צח:
@437 **קרח הוא טהור הוא.** טהור מטמאת נתקין, שאינו נדון בסימני ראש וזקן, שהם מקום שער, אלא בסימני נגע עור בשר בשער לבן, מחיה ופשיון:
@438 **ואם מפאת פניו.** משפוע קדקד כלפי פניו קרוי גבחת, ואף הצדעין שמכאן ומכאן בכלל. ומשפוע קדקד כלפי אחוריו, קרוי קרחת:
@439 **נגע לבן אדמדם.** פתוך. מנין שאר המראות, תלמוד לומר נגע:
@440 **כמראה צרעת עור בשר.** כמראה הצרעת האמור בפרשת עור בשר (פסוק ב) אדם כי יהיה בעור בשרו. ומה אמור בו, שמטמא בארבע מראות ונדון בשני שבועות, ולא כמראה צרעת האמור בשחין ומכוה, שהוא נדון בשבוע אחד, ולא כמראה נתקין של מקום שער שאין מטמאין בארבע מראות שאת ותולדתה, בהרת ותולדתה:
@441 **בראשו נגעו.** אין לי אלא נתקין, מנין לרבות שאר המנגעים, תלמוד לומר טמא יטמאנו, לרבות את כלן. על כלן הוא אומר בגדיו יהיו פרומים וגו' :
@442 **פרמים.** קרועים: **פרוע.** מגדל שער: **ועל שפם יעטה.** כאבל: **שפם.** שער השפתים גירנו''ן בלע''ז [שפם] : **וטמא טמא יקרא.** משמיע שהוא טמא ויפרשו ממנו:
@443 **בדד ישב.** שלא יהיו שאר טמאים יושבים עמו. ואמרו רבותינו מה נשתנה משאר טמאים לישב בדד, הואיל והוא הבדיל בלשון הרע בין איש לאשתו ובין איש לרעהו, אף הוא יבדל: **מחוץ למחנה.** חוץ לשלש מחנות:
@445 **לפשתים ולצמר.** של פשתים או של צמר: **או בעור.** זה עור שלא נעשה בו מלאכה: **או בכל מלאכת עור.** זה עור שנעשה בו מלאכה:
@446 **ירקרק.** ירוק שבירקין: **אדמדם.** אדם שבאדמים:
@448 **צרעת ממארת.** לשון סלון ממאיר (יחזקאל כח כד) . פוינינ''ט בלע''ז [דוקר] . ומדרשו תן בו מארה שלא תהנה המנו:
@449 **בצמר או בפשתים.** של צמר או של פשתים, זהו פשוטו. ומדרשו יכול יביא גזי צמר ואניצי פשתן וישרפם עמו, תלמוד לומר היא באש תשרף, אינה צריכה דבר אחר עמה. אם כן מה תלמוד לומר בצמר או בפשתים, להוציא את האימריות שבו, שהן ממין אחר. אימריות לשון שפה, כמו אימרא:
@451 **את אשר בו הנגע.** יכול מקום הנגע בלבד, תלמוד לומר את אשר בו הנגע. יכול כל הבגד כלו טעון כבוס, תלמוד לומר הנגע. הא כיצד, יכבס מן הבגד עמו:
@452 **אחרי הכבס.** לשון העשות: **לא הפך הנגע את עינו.** לא הכהה ממראיתו: **והנגע לא פשה.** שמענו שאם לא הפך ולא פשה טמא, ואין צריך לומר לא הפך ופשה. הפך ולא פשה איני יודע מה יעשה לו, תלמוד לומר והסגיר את הנגע, מכל מקום, דברי רבי יהודה. וחכמים אומרים וכו', כדאיתא בתורת כהנים. ורמזתיה כאן לישב המקרא על אפניו: **פחתת היא.** לשון גמא, כמו (שמואל ב' יז ט) באחת הפחתים, כלומר שפלה היא, נגע שמראיו שוקעין: **בקרחתו או בגבחתו.** כתרגומו בשחיקותיה או בחדתותיה: **קרחתו.** שחקים ישנים. ומפני המדרש שהצרך לגזרה שוה מנין לפריחה בבגדים שהיא טהורה, נאמרה קרחת וגבחת באדם, ונאמרה קרחת וגבחת בבגדים, מה להלן פרח בכלו טהור, אף כאן פרח בכלו טהור, לכך אחז הכתוב לשון קרחת וגבחת. ולענין פרושו ותרגומו זהו משמעו קרחת לשון ישנים, וגבחת לשון חדשים, כאלו נכתב באחריתו או בקדמותו, שהקרחת לשון אחוריים והגבחת לשון פנים, כמו שכתוב (פסוק מא) ואם מפאת פניו וגו' , והקרחת כל ששופע ויורד מן הקדקד ולאחריו, כך מפורש בתורת כהנים:
@453 **וקרע אתו.** יקרע מקום הנגע מן הבגד וישרפנו:
@454 **פרחת הוא.** דבר החוזר וצומח: **באש תשרפנו.** את כל הבגד:
@455 **וסר מהם הנגע.** אם כשכבסוהו בתחלה על פי כהן, סר ממנו הנגע לגמרי: **וכבס שנית.** לשון טבילה. תרגום של כבוסין שבפרשה זו לשון לבון ויתחור, חוץ מזה שאינו ללבון אלא לטבול, לכך תרגומו ויצטבע, וכן כל כבוסי בגדים שהן לטבילה מתרגמין ויצטבע:
@457 **מבעל שלישה.** שם מדינה. ויונתן תרגם: **מארעא דרומא.** 'בעל' לשון 'מישור', והרבה במקרא: **לחם בכורים.** בפסח, שהתבואה מבכרת: **בצקלונו.** בלבושיה: **לעם.** לתלמידים שהיה זן:
@458 **מה אתן זה.** כל לחם ולחם:
@460 **ונעמן שר צבא.** נסים שנעשו על ידי אלישע, מסדר והולך: **תשועה לארם.** הוא משך בקשת לתומו, והרג את אחאב ( ילקוט שמעוני רמז רכב ):
@461 **יצאו גדודים.** כשהולכין מאה או מאתים מעצמן לשלול כאשר ימצאון, הוא קרוי גדוד: **נערה קטנה.** ריבה קטנה, מעיר נערון ( חולין ה א ): **ותהי לפני.** והות משמשא קדם אתת נעמן:
@462 **אחלי אדני לפני הנביא.** לשון ( שמות לב יא ): ויחל משה בקשות כל המתפללים עליו יהיו, שיבא הנס לפני הנביא: **אחלי.** שוהיידמנ"ס בלע"ז, כלומר זו היא בקשה שהוא צריך לה:
@463 **ויבא.** נעמן: **ויגד לאדוניו.** מלך ארם:
@464 **ויקח בידו.** מנחה לנביא: **וששת אלפים זהב.** זהובים:
@465 **לאמר ועתה כבוא הספר הזה וגו'.** הספר אמר לו, ועתה כבוא הספר הזה וגו': **ואספתו מצרעתו.** 'אסיפה' במצורע היא לשון רפואתו, כי בהתרפאותו הוא נאסף אל תוך בני אדם, ובחליו הכל בדלין הימנו:
@466 **האלהים אני.** ה"א נקוד פת"ח, ללמד שהוא בלשון תמיהה: **מתאנה.** מבקש תואנה להתגרות בי: **מתאנה.** לשון עלילות דברים ( דברים כב יד ):
@470 **הנה אמרתי.** סבור הייתי, אלי יצא הנביא וידבר 'עמי ויראה את החולי: **והניף ידו אל המקום.** הצרעת:
@472 **אבי.** כמו אדוני: **הלא תעשה.** וכי לא תעשהו, אפילו אמר לך דבר טורח: **ואף כי.** קל וחומר שאמר לך דבר קל, רחץ וטהר:
@474 **ברכה.** מנחת שלום של הקבלת פנים, ששואל תלמיד או עבד בשלום הרב, שולד"ו בלע"ז:
@475 **אם אקח.** שדמי עבודה זרה מעורבין בו:
@476 **ולא.** לשון בקשה, לשון הלואי: **יותן נא.** מאדמה זו מארץ ישראל שהיא קדושה, משא שני פרדים, ואשאנה לעירי ואעשה אותה מזבח:
@477 **בית רמון.** שם עבודה זרה: **והשתחויתי.** על כרחי, כששוחה אדוני והוא נשען על ידי:
@478 **כברת ארץ.** שם מדה של קרקע, כמו ( ישעיהו ה י ): צמדי כרם, ארפינ"ט בלע"ז:
@480 **זאת תהיה תורת המצרע ביום טהרתו.** מלמד שאין מטהרין אותו בלילה:
@481 **אל מחוץ למחנה.** חוץ לשלש מחנות שנשתלח שם בימי חלוטו:
@482 **חיות.** פרט לטרפות: **טהרות.** פרט לעוף טמא. לפי שהנגעים באין על לשון הרע, שהוא מעשה פטפוטי דברים, לפיכך הזקקו לטהרתו צפרים, שמפטפטין תמיד בצפצוף קול: **ועץ ארז.** לפי שהנגעים באין על גסות הרוח: **ושני תולעת ואזב.** מה תקנתו ויתרפא, ישפיל עצמו מגאותו, כתולעת וכאזוב: **עץ ארז.** מקל של ארז: **ושני תולעת.** לשון של צמר צבוע זהורית:
@483 **על מים חיים.** נותן אותם תחלה בכלי, כדי שיהא דם צפור נכר בהם. וכמה הם, רביעית:
@484 **את הצפר החיה יקח אתה.** מלמד שאינו אוגדה עמהם, אלא מפרישה לעצמה, אבל העץ והאזוב כרוכים יחד בלשון הזהורית, כענין שנאמר ואת עץ הארז ואת שני התולעת ואת האזוב, קיחה אחת לשלשתן. יכול כשם שאינה בכלל אגדה כן לא תהא בכלל טבילה, תלמוד לומר וטבל אותם ואת הצפור החיה, החזיר את הצפור לכלל טבילה:
@486 **וישב מחוץ לאהלו.** מלמד שאסור בתשמיש המטה:
@487 **את כל שערו** וגו' **.** כלל ופרט וכלל. להביא כל מקום כנוס שער ונראה:
@488 **וכבשה אחת.** לחטאת: **ושלשה עשרנים.** לנסכי שלשה כבשים הללו, שחטאתו ואשמו של מצורע טעונין נסכים: **ולג אחד שמן.** להזות עליו שבע ולתן ממנו על תנוך אזנו ומתן בהונות:
@489 **לפני ה'.** בשער נקנור, ולא בעזרה עצמה, לפי שהוא מחסר כפורים:
@490 **והקריב אתו לאשם.** יקריבנו לתוך העזרה לשם אשם: **והניף.** שהוא טעון תנופה חי: **והניף אתם.** את האשם ואת הלוג:
@491 **במקום אשר ישחט** וגו' **.** על ירך המזבח בצפון. ומה תלמוד לומר, והלא כבר נאמר בתורת אשם בפרשת צו את אהרן שהאשם טעון שחיטה בצפון, לפי שיצא זה מכלל אשמות לדון בהעמדה, יכול תהא שחיטתו במקום העמדתו, לכך נאמר ושחט במקום אשר ישחט וגו' : **כי כחטאת.** כי ככל החטאות: **האשם.** הזה: **הוא לכהן.** בכל עבודות התלויות בכהן השוה אשם זה לחטאת, שלא תאמר הואיל ויצא דמו מכלל שאר אשמות לנתן על תנוך ובהונות, לא יהא טעון מתן דמים ואימורים לגבי מזבח, לכך נאמר כי כחטאת האשם הוא לכהן. יכול יהא דמו נתן למעלה כחטאת, תלמוד לומר וכו' , בתורת כהנים:
@492 **תנוך.** גדר אמצעי שבאוזן. ולשון תנוך לא נודע לי. והפותרים קורים לו טנדרו''ס : **בהן.** גדל:
@494 **לפני ה'.** כנגד בית קדשי הקדשים:
@498 **ואת המנחה.** מנחת נסכים של בהמה:
@499 **ועשרון סלת אחד.** לכבש זה שהוא אחד יביא עשרון אחד לנסכיו: **ולוג שמן.** לתת ממנו על הבהונות ושמן של נסכי המנחה לא הזקק הכתוב לפרש:
@501 **ביום השמיני לטהרתו.** שמיני לצפרים ולהזאת עץ ארז ואזוב ושני תולעת:
@506 **על מקום דם האשם.** אפלו נתקנח הדם, למד שאין הדם גורם אלא המקום גורם:
@512 **ונתתי נגע צרעת.** בשורה היא להם שהנגעים באים עליהם, לפי שהטמינו אמוריים מטמוניות של זהב בקירות בתיהם כל ארבעים שנה שהיו ישראל במדבר, ועל ידי הנגע נותץ הבית ומוצאן:
@513 **כנגע נראה לי בבית.** אפלו תלמיד חכם שיודע שהוא נגע ודאי לא יפסוק דבר ברור לומר נגע נראה לי, אלא כנגע נראה לי:
@514 **בטרם יבא הכהן** וגו' **.** שכל זמן שאין כהן נזקק לו, אין שם תורת טמאה: **ולא יטמא כל אשר בבית.** שאם לא יפנהו ויבא הכהן ויראה הנגע, נזקק להסגר, וכל מה שבתוכו יטמא. ועל מה חסה תורה, אם על כלי שטף, יטבילם ויטהרו, ואם על אוכלין ומשקין, יאכלם בימי טמאתו, הא לא חסה התורה אלא על כלי חרס, שאין להם טהרה במקוה:
@515 **שקערורת.** שוקעות במראיהן:
@518 **וחלצו את האבנים.** כתרגומו וישלפון, יטלום משם, כמו (דברים כה ט) וחלצה נעלו, לשון הסרה: **אל מקום טמא.** מקום שאין טהרות משתמשות שם, למדך הכתוב שהאבנים הללו מטמאות מקומן בעודן בו:
@519 **יקצע.** רודוניי''ר בלע''ז . ובלשון משנה יש הרבה: **מבית.** מבפנים: **סביב.** סביבות הנגע, בתורת כהנים נדרש כן, שיקלוף הטיח שסביב אבני הנגע: **הקצו.** לשון קצה, אשר קצעו בקצות הנגע סביב:
@521 **הקצות.** לשון העשות וכן הטוח, אבל חלץ את האבנים מוסב הלשון אל האדם שחלצן והוא משקל לשון כבד, כמו כפר, דבר: **ואם ישוב הנגע** וגו' **.** יכול חזר בו ביום יהא טמא, תלמוד לומר ושב הכהן ואם ישוב, מה שיבה האמורה להלן לסוף שבוע, אף שיבה האמורה כאן בסוף שבוע:
@522 **ובא הכהן וראה והנה פשה.** יכול לא יהא החוזר טמא אלא אם כן פשה, נאמר צרעת ממארת בבתים ונאמר צרעת ממארת בבגדים, מה להלן טמא את החוזר אף על פי שאינו פושה, אף כאן טמא את החוזר אף על פי שאינו פושה, אם כן מה תלמוד לומר והנה פשה, אין כאן מקומו של מקרא זה, אלא ונתץ את הבית היה לו לכתוב אחר ואם ישוב הנגע וראה והנה פשה, הא לא בא ללמד אלא על נגע העומד בעיניו בשבוע ראשון ובא בסוף שבוע שני ומצאו שפשה, שלא פרש בו הכתוב למעלה כלום בעומד בעיניו בשבוע ראשון, ולמדך כאן בפשיון זה שאינו מדבר אלא בעומד בראשון ופשה בשני ומה יעשה לו, יכול יתצנו, כמו שסמך לו ונתץ את הבית, תלמוד לומר ושב הכהן ובא הכהן, נלמד ביאה משיבה, מה שיבה חולץ וקוצה וטח ונותן לו שבוע, אף ביאה חולץ וקוצה וטח ונותן לו שבוע. ואם חוזר, נותץ. לא חזר, טהור. ומנין שאם עמד בזה ובזה חולץ וקוצה וטח ונותן לו שבוע, תלמוד לומר ובא ואם בא יבא, במה הכתוב מדבר, אם בפושה בראשון הרי כבר אמר, אם בפושה בשני הרי כבר אמור, הא אינו אומר [ובא] , ואם בא יבא, אלא את שבא בסוף שבוע ראשון ובא בסוף שבוע שני וראה והנה לא פשה. זה העומד מה יעשה לו, יכול יפטר וילך, כמו שכתוב כאן וטהר את הבית, תלמוד לומר כי נרפא הנגע, לא טהרתי אלא את הרפאוי, מה יעשה לו, ביאה אמורה למעלה וביאה אמורה למטה, מה בעליונה חולץ וקוצה וטח ונותן לו שבוע, דגמר לה זהו שיבה זהו ביאה, אף בתחתונה כן וכו' , כדאיתא בתורת כהנים. גמרו של דבר אין נתיצה אלא בנגע החוזר אחר חליצה וקצוע וטיחה ואין החוזר צריך פשיון. וסדר המקראות כך הוא ואם ישוב, ונתץ, והבא אל הבית, והאוכל בבית, ובא הכהן וראה והנה פשה. ודבר הכתוב בעומד בראשון שנותן לו שבוע שני להסגרו, ובסוף שבוע שני להסגרו בא וראהו שפשה, ומה יעשה לו, חולץ וקוצה וטח ונותן לו שבוע. חזר, נותץ. לא חזר, טעון צפרים, שאין בנגעים יותר משלשה שבועות:
@524 **כל ימי הסגיר אתו.** ולא ימים שקלף את נגעו, יכול שאני מוציא המחלט שקלף את נגעו, תלמוד לומר כל ימי: **יטמא עד הערב.** מלמד שאין מטמא בגדים, יכול אפלו שהה בכדי אכילת פרס, תלמוד לומר והאוכל בבית יכבס את בגדיו. אין לי אלא אכל, שכב מנין, תלמוד לומר והשוכב. אין לי אלא אוכל ושוכב, לא אוכל ולא שוכב מנין, תלמוד לומר יכבס יכבס, רבה. אם כן למה נאמר אוכל ושוכב, לתן שיעור לשוכב כדי אכילת פרס:
@526 **ואם בא יבא.** לסוף שבוע שני: **וראה והנה לא פשה.** מקרא זה בא ללמד בעומד בעיניו בראשון ובשני מה יעשה לו, יכול יטהרנו כמשמעו של מקרא וטהר הכהן את הבית, תלמוד לומר כי נרפא הנגע, לא טהרתי אלא את הרפאוי, ואין רפוי אלא הבית שהקצה והוטח ולא חזר הנגע, אבל זה טעון חליצה וקצוי וטיחה ושבוע שלישי. וכן המקרא נדרש ואם בא יבא בשני, וראה והנה לא פשה יטיחנו, ואין טיחה בלא חלוץ וקצוי. ואחרי הטוח את הבית וטהר הכהן את הבית אם לא חזר לסוף השבוע, כי נרפא הנגע, ואם חזר כבר פרש על החוזר שטעון נתיצה:
@535 **להורת ביום הטמא.** איזה יום מטהרו ואיזה יום מטמאו:
@537 **כי יהיה זב.** יכול זב מכל מקום יהא טמא, תלמוד לומר מבשרו ולא כל בשרו. אחר שחלק הכתוב בין בשר לבשר זכיתי לדון, טמא בזב וטמא בזבה, מה זבה ממקום שהיא מטמאה טמאה קלה, נדה, מטמאה טמאה חמורה, זיבה, אף הזב ממקום שמטמא טמאה קלה, קרי, מטמא טמאה חמורה, זיבה: **זובו טמא.** למד על הטפה שהיא מטמאה. זוב דומה למי בצק של שעורין ודחוי, ודומה ללובן ביצה המוזרת. שכבת זרע קשור כלובן ביצה שאינה מוזרת:
@538 **רר.** לשון ריר שזב את בשרו: **את זובו.** כמו ריר שיוצא צלול: **או החתים.** שיוצא עב וסותם את פי האמה ונסתם בשרו מטפת זובו, זהו פשוטו. ומדרשו מנה הכתוב הראשון ראיות שתים וקראו טמא, שנאמר זב מבשרו זובו טמא הוא, ומנה הכתוב השני ראיות שלש וקראו טמא, שנאמר טמאתו בזובו רר בשרו את זובו או החתים בשרו מזובו טמאתו היא. הא כיצד, שתים לטמאה, והשלישית מזקיקתו לקרבן:
@539 **כל המשכב.** הראוי למשכב, יכול אפלו מיוחד למלאכה אחרת, תלמוד לומר אשר ישכב, אשר שכב לא נאמר, אלא אשר ישכב, המיוחד תמיד לכך, יצא זה שאומרים לו עמוד ונעשה מלאכתנו: **אשר ישב.** ישב לא נאמר אלא אשר ישב עליו הזב, במיוחד תמיד לכך:
@540 **ואיש אשר יגע במשכבו.** למד על המשכב שחמור מן המגע, שזה נעשה אב הטמאה לטמא אדם לטמא בגדים, והמגע שאינו משכב אינו אלא ולד הטמאה, ואינו מטמא אלא אוכלין ומשקין:
@541 **והישב על הכלי.** אפלו לא נגע, אפלו עשרה כלים זה על זה, כלן מטמאין משום מושב וכן במשכב:
@543 **וכי ירק הזב בטהור.** ונגע בו או נשאו, שהרוק מטמא במשא:
@544 **וכל המרכב.** אף על פי שלא ישב עליו, כגון התפוס של סרגא שקורין ארצו''ן [שלד האכף] טמא משום מרכב. והאכף, שקורין אלוו''ש טמא טמאת מושב:
@545 **וכל הנגע בכל אשר יהיה תחתיו.** של זב. בא ולמד על המרכב, שיהא הנוגע בו טמא ואין טעון כבוס בגדים, והוא חמר במשכב מבמרכב: **והנושא אותם.** את כל האמור בענין הזב, זובו ורקו ושכבת זרעו ומימי רגליו והמשכב והמרכב והמושב, שיהא משאן מטמא אדם לטמא בגדים:
@546 **וידיו לא שטף במים.** בעוד שלא טבל מטמאתו, ואפלו פסק מזובו וספר שבעה ומחסר טבילה, מטמא בכל טמאותיו. וזה שהוציא הכתוב טבילת גופו של זב בלשון שטיפת ידים, ללמדך שאין בית הסתרים טעון ביאת מים, אלא אבר הגלוי, כמו הידים:
@547 **וכלי חרש אשר יגע בו הזב.** יכול אפלו נגע בו מאחוריו וכו' , כדאיתא בתורת כהנים, עד איזהו מגעו שהוא בכלו הוי אומר זה הסיטו:
@548 **וכי יטהר.** כשיפסוק: **שבעת ימים לטהרתו.** שבעת ימים טהורים מטמאת זיבה, שלא יראה זוב, וכלן רצופין:
@553 **ורחצו במים.** גזרת מלך היא שתטמא האשה בביאה. ואין הטעם משום נוגע בשכבת זרע, שהרי מגע בית הסתרים הוא:
@554 **כי תהיה זבה.** יכול מאחד מכל איבריה, תלמוד לומר (ויקרא כ יח) והיא גלתה את מקור דמיה, אין דם מטמא אלא הבא מן המקור: **דם יהיה זבה בבשרה.** אין זובה קרוי זוב לטמא אלא אם כן הוא אדום: **בנדתה.** כמו (איוב יח יח) ומתבל ינדהו, שהיא מנדה ממגע כל אדם: **תהיה בנדתה.** אפלו לא ראתה אלא ראיה ראשונה:
@558 **ואם על המשכב הוא.** השוכב או היושב על משכבה או על מושבה, אפלו לא נגע בה, אף הוא בדת טמאה האמורה במקרא העליון שטעון כבוס בגדים: **על הכלי.** לרבות את המרכב: **בנגעו בו יטמא.** אינו מדבר אלא על המרכב שנתרבה מעל הכלי: **בנגעו בו יטמא.** ואינו טעון כבוס בגדים שהמרכב אין מגעו מטמא אדם לטמא בגדים:
@559 **ותהי נדתה עליו.** יכול יעלה לרגלה, שאם בא עליה בחמישי לנדתה לא יטמא אלא שלשה ימים כמותה, תלמוד לומר וטמא שבעת ימים. ומה תלמוד לומר ותהי נדתה עליו, מה היא מטמאה אדם וכלי חרס, אף הוא מטמא אדם וכלי חרס:
@560 **ימים רבים.** שלשה ימים: **בלא עת נדתה.** אחר שיצאו שבעת ימי נדתה: **או כי תזוב.** את שלשת הימים הללו: **על נדתה.** מפלג מנדתה יום אחד, זו היא זבה ומשפטה חרוץ בפרשה זו, ולא כדת הנדה, שזו טעונה ספירת שבעה נקיים וקרבן, והנדה אינה טעונה ספירת שבעה נקיים, אלא שבעת ימים תהיה בנדתה בין רואה בין שאינה רואה. ודרשו רבותינו בפרשה זו, אחד עשר יום יש בין סוף נדה לתחלת נדה, שכל שלשה רצופין שתראה באחד עשר יום הללו, תהא זבה:
@566 **והזרתם.** אין נזירה אלא פרישה, וכן (ישעיה א ד) נזורו אחור, וכן (בראשית מט כו) נזיר אחיו: **ולא ימתו בטמאתם.** הרי הכרת של מטמא מקדש קרוי מיתה:
@567 **זאת תורת הזב.** בעל ראיה אחת, ומהו תורתו, **ואשר תצא ממנו שכבת זרע.** הרי הוא כבעל קרי טמא טמאת ערב:
@568 **והזב את זובו.** בעל שתי ראיות ובעל שלש ראיות, שתורתן מפורשת למעלה:
@572 **השמיע את מחנה ארם.** נדמה להם כאלו שומעין:
@575 **ומצאנו עון.** מתחייבין אנו למלכות:
@576 **כאשר המה.** כמו שהיו מלאים מתחלתם, לא הוציאו מה שבתוכם:
@578 **כי רעבים אנחנו.** ותאבים לצאת אל השלל ואל המזון:
@579 **אשר נשארו בה.** בתוך העיר, שלא מתו ברעב: **הנם ככל המון ישראל אשר נשארו בה.** אם יאמרו מסוכנין הם שלא יהרגם אדם, הרי הנם בעיר הזאת בסכנת הרעב כשאר כל המון ישראל אשר נשארו בה, ואם ימותו הנם ככל המון ישראל, אשר תמו ברעב:
@581 **בחפזם.** במהרם לנוס:
@583 **אשר נשען על ידו.** אתמול כשבא לבית אלישע:
@587 **וידבר ה' אל משה אחרי מות שני בני אהרן** וגו' **.** מה תלמוד לומר, היה רבי אלעזר בן עזריה מושלו משל לחולה שנכנס אצלו רופא. אמר לו אל תאכל צונן ואל תשכב בטחב. בא אחר ואמר לו אל תאכל צונן ואל תשכב בטחב שלא תמות כדרך שמת פלוני. זה זרזו יותר מן הראשון, לכך נאמר אחרי מות שני בני אהרן:
@588 **ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבא.** שלא ימות כדרך שמתו בניו: **ולא ימות.** שאם בא הוא מת: **כי בענן אראה.** כי תמיד אני נראה שם עם עמוד ענני. ולפי שגלוי שכינתי שם, יזהר שלא ירגיל לבא, זהו פשוטו. ומדרשו לא יבא כי אם בענן הקטרת ביום הכפורים:
@589 **בזאת.** גימטריא שלו ארבע מאות ועשר, רמז לבית ראשון: **בזאת יבא אהרן** וגו' **.** ואף זו לא בכל עת, כי אם ביום הכפורים, כמו שמפורש בסוף הפרשה (פסוק כט) בחדש השביעי בעשור לחדש:
@590 **כתנת בד** וגו' **.** מגיד שאינו משמש לפנים בשמונה בגדים שהוא משמש בהם בחוץ, שיש בהם זהב, לפי שאין קטגור נעשה סנגור, אלא בארבעה, ככהן הדיוט, וכלן של בוץ: **קדש ילבש.** שהיו משל קדש: **יצנף.** כתרגומו יחית ברישיה, יניח בראשו, כמו (בראשית לט טז) ותנח בגדו ואחתתיה: **ורחץ במים.** אותו היום טעון טבילה בכל חליפותיו. וחמש פעמים היה מחליף מעבודת פנים לעבודת חוץ ומחוץ לפנים, ומשנה מבגדי זהב לבגדי לבן ומבגדי לבן לבגדי זהב, ובכל חליפה טעון טבילה ושני קדושי ידים ורגלים מן הכיור:
@592 **את פר החטאת אשר לו.** האמור למעלה. ולמדך כאן שמשלו הוא בא, ולא משל צבור: **וכפר בעדו ובעד ביתו.** מתודה עליו עונותיו ועונות ביתו:
@594 **ונתן אהרן על שני השעירים גרלות.** מעמיד אחד לימין ואחד לשמאל, ונותן שתי ידיו בקלפי ונוטל גורל בימין וחברו בשמאל, ונותן עליהם, את שכתוב בו לשם הוא לשם, ואת שכתוב בו לעזאזל משתלח לעזאזל: **עזאזל.** הוא הר עז וקשה, צוק גבוה, שנאמר (פסוק כב) ארץ גזרה, חתוכה:
@595 **ועשהו חטאת.** כשמניח הגורל עליו קורא לו שם ואומר לה' חטאת:
@596 **יעמד חי.** כמו יעמד חי על ידי אחרים, ותרגומו יתקם כד חי. מה תלמוד לומר חי, לפי שנאמר לשלח אתו לעזאזל, ואיני יודע שלוחו אם למיתה אם לחיים, לכך נאמר יעמד חי, עמידתו חי עד שישתלח, מכאן ששלוחו למיתה: **לכפר עליו.** שיתודה עליו, כדכתיב (פסוק כא) והתודה עליו וגו' :
@597 **וכפר בעדו** וגו' **.** ודוי שני עליו ועל אחיו הכהנים, שהם כלם קרויים ביתו, שנאמר (תהלים קלה יט) בית אהרן ברכו את ה' וגו' , מכאן שהכהנים מתכפרים בו, וכל כפרתן אינה אלא על טמאת מקדש וקדשיו, כמו שנאמר (פסוק טז) וכפר על הקדש מטמאות וגו' :
@598 **מעל המזבח.** החיצון: **מלפני ה'.** מצד שלפני הפתח והוא צד מערבי: **דקה.** מה תלמוד לומר דקה, והלא כל הקטורת דקה היא, שנאמר (שמות ל לו) ושחקת ממנה הדק, אלא שתהא דקה מן הדקה, שמערב יום הכפורים היה מחזירה למכתשת:
@599 **על האש.** שבתוך המחתה: **ולא ימות.** הא אם לא עשאה כתקנה, חיב מיתה:
@600 **והזה באצבעו.** הזאה אחת במשמע: **ולפני הכפרת יזה שבע.** הרי אחת למעלה ושבע למטה:
@601 **אשר לעם.** מה שהפר מכפר על הכהנים מכפר השעיר על ישראל, והוא השעיר שעלה עליו הגורל לשם: **כאשר עשה לדם הפר.** אחת למעלה ושבע למטה:
@602 **מטמאת בני ישראל.** על הנכנסין למקדש בטמאה ולא נודע להם בסוף, שנאמר לכל חטאתם, וחטאת היא שוגג: **ומפשעיהם.** אף הנכנסין מזיד בטמאה: **וכן יעשה לאהל מועד.** כשם שהזה משניהם בפנים אחת למעלה ושבע למטה, כך מזה על הפרוכת מבחוץ משניהם אחת למעלה ושבע למטה: **השכן אתם בתוך טמאתם.** אף על פי שהם טמאים שכינה ביניהם:
@604 **אל המזבח אשר לפני ה'.** זה מזבח הזהב שהוא לפני ה' בהיכל. ומה תלמוד לומר ויצא, לפי שהזה ההזאות על הפרוכת ועמד מן המזבח ולפנים והזה, ובמתנות המזבח הזקיקו לצאת מן המזבח ולחוץ, ויתחיל מקרן מזרחית צפונית: **וכפר עליו.** ומה היא כפרתו, ולקח מדם הפר ומדם השעיר, מעורבין זה לתוך זה:
@605 **והזה עליו מן הדם.** אחר שנתן מתנות באצבעו על קרנותיו, מזה שבע הזאות על גגו: **וטהרו.** ממה שעבר: **וקדשו.** לעתיד לבא:
@607 **איש עתי.** המוכן לכך מיום אתמול:
@609 **ובא אהרן אל אהל מועד.** אמרו רבותינו, שאין זה מקומו של מקרא זה, ונתנו טעם לדבריהם במסכת יומא (דף לב א) ואמרו כל הפרשה כלה אמורה על הסדר, חוץ מביאה זו, שהיא אחר עשית עולתו ועולת העם והקטרת אימורי פר ושעיר שנעשים בחוץ בבגדי זהב, וטובל ומקדש ופושטן ולובש בגדי לבן: **ובא אל אהל מועד.** להוציא את הכף ואת המחתה שהקטיר בה הקטרת לפני ולפנים: **ופשט את בגדי הבד.** אחר שהוציאם ולובש בגדי זהב לתמיד של בין הערבים. וזהו סדר העבודות תמיד של שחר בבגדי זהב, ועבודת פר ושעיר הפנימיים וקטרת של מחתה בבגדי לבן, ואילו ואיל העם ומקצת המוספין בבגדי זהב, והוצאת כף ומחתה בבגדי לבן, ושירי המוספין ותמיד של בין הערבים וקטורת ההיכל שעל מזבח הפנימי בבגדי זהב. וסדר המקראות לפי סדר העבודות כך הוא ושלח את השעיר במדבר, ורחץ את בשרו במים וגו' ויצא ועשה את עולתו וגו' ואת חלב החטאת וגו' . וכל הפרשה עד ואחרי כן יבא אל המחנה, ואחר כך ובא אהרן: **והניחם שם.** מלמד שטעונין גניזה, ולא ישתמש באותן ארבעה בגדים ליום כפורים אחר:
@610 **ורחץ את בשרו** וגו' **.** למעלה למדנו מורחץ את בשרו ולבשם (פסוק ד) , שכשהוא משנה מבגדי זהב לבגדי לבן טעון טבילה, שבאותה טבילה פשט בגדי זהב שעבד בהן עבודת תמיד של שחר ולבש בגדי לבן לעבודת היום, וכאן למדנו שכשהוא משנה מבגדי לבן לבגדי זהב טעון טבילה: **במקום קדוש.** המקדש בקדשת עזרה והיא היתה בגג בית הפרוה, וכן ארבע טבילות הבאות חובה ליום, אבל הראשונה היתה בחול: **ולבש את בגדיו.** שמונה בגדים שהוא עובד בהן כל ימות השנה: **ויצא.** מן ההיכל אל החצר שמזבח העולה שם: **ועשה את עלתו.** איל לעולה האמור למעלה (פסוק ג) בזאת יבא אהרן וגו' : **ואת עלת העם.** ואיל אחד לעולה האמור למעלה (פסוק ה) ומאת עדת בני ישראל וגו' :
@611 **ואת חלב החטאת.** אימורי פר ושעיר: **יקטיר המזבחה.** על מזבח החיצון, דאלו בפנימי כתיב (שמות ל ט) לא תעלו עליו קטרת זרה ועולה ומנחה:
@613 **אשר הובא את דמם.** להיכל ולפני ולפנים:
@618 **וכפר הכהן אשר ימשח** וגו' **.** כפרה זו של יום הכפורים אינה כשרה אלא בכהן גדול, לפי שנאמרה כל הפרשה באהרן, הצרך לומר בכהן גדול הבא אחריו שיהא כמוהו: **ואשר ימלא את ידו.** אין לי אלא המשוח בשמן המשחה, מרבה בגדים מנין, תלמוד לומר ואשר ימלא את ידו וגו' , והם כל הכהנים הגדולים שעמדו מיאשיהו ואילך, שבימיו נגנזה צלוחית של שמן המשחה: **לכהן תחת אביו.** ללמד שאם בנו ממלא את מקומו הוא קודם לכל אדם:
@620 **ויעש כאשר צוה ה'** וגו' **.** כשהגיע יום הכפורים עשה כסדר הזה, ולהגיד שבחו של אהרן שלא היה לובשן לגדלתו, אלא כמקיים גזרת המלך:
@623 **אשר ישחט שור או כשב.** במקדשין הכתוב מדבר, שנאמר להקריב קרבן: **במחנה.** חוץ לעזרה:
@624 **דם יחשב.** כשופך דם האדם שמתחייב בנפשו: **דם שפך.** לרבות את הזורק דמים בחוץ:
@625 **אשר הם זבחים.** אשר הם רגילים לזבוח:
@627 **לשעירם.** לשדים, כמו (ישעיה יג כא) ושעירים ירקדו שם:
@628 **אשר יעלה עלה.** לחיב על המקטיר איברים בחוץ כשוחט בחוץ, שאם שחט אחד והעלה חברו שניהם חיבין:
@629 **ונכרת.** זרעו נכרת וימיו נכרתין:
@630 **כל דם.** לפי שנאמר בנפש יכפר, יכול לא יהא חיב אלא על דם המקדשים, תלמוד לומר כל דם: **ונתתי פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו:
@631 **כי נפש הבשר.** של כל בריה בדם היא תלויה, ולפיכך נתתיו על המזבח לכפר על נפש האדם. תבוא נפש ותכפר על הנפש:
@632 **כל נפש מכם.** להזהיר גדולים על הקטנים:
@633 **אשר יצוד.** אין לי אלא ציד, אוזין ותרנגולין מנין, תלמוד לומר ציד מכל מקום. אם כן למה נאמר אשר יצוד, שלא יאכל בשר אלא בהזמנה הזאת: **אשר יאכל.** פרט לטמאים:
@634 **דמו בנפשו הוא.** דמו הוא לו במקום הנפש, שהנפש תלויה בו: **כי נפש כל בשר דמו הוא.** הנפש היא הדם. דם ובשר לשון זכר' נפש לשון נקבה:
@635 **אשר תאכל נבלה וטרפה.** בנבלת עוף טהור דבר הכתוב' שאין לה טמאה אלא בשעה שנבלעת בבית הבליעה' ולמדך כאן שמטמאה באכילתה' ואינה מטמאה במגע. וטרפה האמורה כאן לא נכתבה אלא לדרוש. וכן שנינו יכול תהא נבלת עוף טמא מטמאה בבית הבליעה' תלמוד לומר טרפה' מי שיש במינו טרפה' יצא עוף טמא שאין במינו טרפה:
@636 **ונשא עונו.** אם יאכל קדש או יכנס למקדש חיב על טמאה זו ככל שאר טמאות: **ובשרו לא ירחץ ונשא עונו.** על רחיצת גופו ענוש כרת ועל כבוס בגדים במלקות:
@638 **אני ה' אלהיכם.** אני הוא שאמרתי בסיני (שמות כ ב) אנכי ה' אלהיך, וקבלתם עליכם מלכותי, מעתה קבלו גזרותי. רבי אומר גלוי וידוע לפניו שסופן לנתק בעריות בימי עזרא, לפיכך בא עליהם בגזרה אני ה' אלהיכם, דעו מי גוזר עליכם, דין להפרע ונאמן לשלם שכר:
@639 **כמעשה ארץ מצרים.** מגיד שמעשיהם של מצריים ושל כנעניים מקלקלים מכל האמות, ואותו מקום שישבו בו ישראל מקלקל מן הכל: **אשר אני מביא אתכם שמה.** מגיד שאותן עממין שכבשו ישראל מקלקלים יותר מכלם: **ובחקתיהם לא תלכו.** מה הניח הכתוב שלא אמר, אלא אלו נמוסות שלהן, דברים החקוקין להם, כגון טרטיאות ואצטדיאות. רבי מאיר אומר אלו דרכי האמורי שמנו חכמים:
@640 **את משפטי תעשו.** אלו דברים האמורים בתורה במשפט, שאלו לא נאמרו, היו כדאי לאמרן: **ואת חקתי תשמרו.** דברים שהם גזרת המלך, שיצר הרע משיב עליהם, למה לנו לשמרן, ואמות העולם משיבין עליהם, כגון אכילת חזיר ולבישת שעטנז וטהרת מי חטאת, לכך נאמר אני ה' גזרתי עליכם, אי אתם רשאים להפטר: **ללכת בהם.** אל תפטר מתוכם, שלא תאמר למדתי חכמת ישראל אלך ואלמד חכמת האמות:
@641 **ושמרתם את חקתי** וגו' **.** לרבות שאר דקדוקי הפרשה, שלא פרט הכתוב בהם. דבר אחר לתן שמירה ועשייה לחקים ושמירה ועשייה למשפטים, לפי שלא נתן אלא עשייה למשפטים ושמירה לחקים: **וחי בהם.** לעולם הבא, שאם תאמר בעולם הזה, והלא סופו הוא מת: **אני ה'.** נאמן לשלם שכר:
@642 **לא תקרבו.** להזהיר הנקבה כזכר, לכך נאמר לשון רבים: **אני ה'.** נאמן לשלם שכר:
@643 **ערות אביך.** זו אשת אביך, או אינו אלא כמשמעו, נאמר כאן ערות אביך, ונאמר להלן (ויקרא כ יא) ערות אביו גלה, מה להלן אשת אביו, אף כאן אשת אביו: **וערות אמך.** להביא אמו שאינה אשת אביו:
@644 **ערות אשת אביך.** לרבות לאחר מיתה:
@645 **בת אביך.** אף בת אנוסה במשמע: **מולדת בית או מולדת חוץ.** בין שאומרים לו לאביך קים את אמה ובין שאומרים לו לאביך הוצא את אמה, כגון ממזרת או נתינה:
@646 **ערות בת בנך.** בבתו מאנוסתו הכתוב מדבר, ובתו ובת בתו מאשתו אנו למדין מערות אשה ובתה לא תגלה, בין שהיא ממנו ובין שהיא מאיש אחר: **ערות בת בנך.** קל וחמר לבתך, אלא לפי שאין מזהירין מן הדין למדוה מגזרה שוה במסכת יבמות (ג א) :
@647 **ערות בת אשת אביך.** למד שאינו חיב על אחותו משפחה ונכרית לכך נאמר בת אשת אביך בראויה לקדושין:
@650 **ערות אחי אביך לא תגלה.** ומה היא ערותו, אל אשתו לא תקרב:
@651 **אשת בנך היא.** לא אמרתי אלא בשיש לבנך אישות בה, פרט לאנוסה ושפחה ונכרית:
@653 **ערות אשה ובתה.** לא אסר הכתוב אלא על ידי נשואי הראשונה, לכך נאמר לא תקח, לשון קיחה, וכן לענין הענש אשר יקח את אשה ואת אמה (ויקרא כ יד) , לשון קיחה, אבל אנס אשה מתר לשא בתה: **שארה הנה.** קרובות (הן) זו לזו: **זמה.** עצה כתרגומו עצת חטאין, שיצרך יועצך לחטוא:
@654 **אל אחתה.** שתיהן כאחת: **לצרר.** לשון צרה לעשות את זו צרה לזו: **בחייה.** למדך שאם גרשה לא ישא את אחותה כל זמן שהיא בחיים:
@657 **למלך.** עבודה זרה היא ששמה מולך, וזו היא עבודתה, שמוסר בנו לכומרים ועושין שתי מדורות גדולות ומעבירין את הבן ברגליו בין שתי מדורות האש: **לא תתן.** זו היא מסירתו לכומרים: **להעביר למלך.** זו (היא) העברת האש:
@659 **תבל הוא.** לשון קדש וערוה ונאוף, וכן ואפי על תבליתם (ישעיה י כה) . דבר אחר תבל הוא לשון בלילה וערבוב, זרע אדם וזרע בהמה:
@664 **ולא תקיא הארץ אתכם.** משל לבן מלך שהאכילוהו דבר מאוס, שאין עומד במעיו אלא מקיאו, כך ארץ ישראל אינה מקימת עוברי עברה. ותרגומו ולא תרוקין, לשון רקון, מריקה עצמה מהם:
@665 **הנפשות העשת.** הזכר והנקבה במשמע:
@666 **ושמרתם את משמרתי.** להזהיר בית דין על כך: **ולא תטמאו בהם אני ה' אלהיכם.** הא אם תטמאו, אני אלהיכם, ואתם נפסלים מאחרי, ומה הנאה יש לי בכם, ואתם מתחיבים כליה, לכך נאמר אני ה' אלהיכם:
@667 **ויהי.** דבר ה' אלי לאמר:
@668 **התשפוט את עיר הדמים.** ירושלים: **והודעתה.** מפיק ה"א והודעתה אותה:
@669 **עיר שופכת דם בתוכה לבוא עתה.** הרי זה מקרא מסורס וזהו פיר' עיר שופכת דם בתוכה אמר ה' אלהים לבוא עתה: **ועשתה גילולים.** כמו ואשר עשתה גלולים וגו':
@670 **עד שנותיך.** גזירת ונושנתם ( דברים ד ) בגי' שאמר משה: **וקלסה.** דבה שהכל נדברים ביד פרלרי"ץ בלע"ז:
@671 **יתקלסו בך.** ומה היא הקלסות טמאת השם זו היא שטמאת את שמה שהיו נקראים עם קדוש בנים ליוצרם וגרמו עצמם להקראו' עם טמא שפתים ( ישעיה ו ):
@672 **איש לזרועו.** כל דאלים גבר:
@673 **אב ואם הקלו בך.** כל התועבות שבפ' קדושים תהיו שהוזהרו עליהם נמנו כאן:
@674 **קדשי בזית.** ולא כמו שאמרתי לרצונכם תזבחו ( ויקרא י"ט ):
@675 **ואל ההרים אכלו בך.** ובטוריא פלחו ביך לטעותא: **זמה עשו.** עצות של רשעה:
@678 **ותבצעי רעיך בעושק.** העשרת את אוהביך בעושק שעשקת מן העניים לשון אחר ותבצעי לשון גזל כמו ובוצע ברך נאץ ה' ( תהלים ו' ) וכה פתרונו ותגזלי לרעיך בעושק:
@679 **הכיתי כפי.** צעקתי ווי וקינה: **אל בצעיך.** כאן למדנו שהגזל קשה מן הכל שעליו נתחתם גזר דין:
@680 **אשר אני עושה אותך.** פועל לך כפעלך:
@681 **והתימותי.** וכליתי:
@682 **ונחלת בך.** תתחלחלי בעצמך על מה שעשית:
@684 **לסיג.** תערובת פסולת המעורב בכסף וזהב וצריך להתיכו באש לצורפו: **כור.** שצורפין בו זהב:
@687 **דבר אל כל עדת בני ישראל.** מלמד שנאמרה פרשה זו בהקהל, מפני שרוב גופי תורה תלויין בה: **קדשים תהיו.** הוו פרושים מן העריות ומן העברה, שכל מקום שאתה מוצא גדר ערוה אתה מוצא קדשה, אשה זונה וחללה וגו' אני ה' מקדשכם, (ויקרא כא ז. ח) ולא יחלל זרעו אני ה' מקדשו (ויקרא כא טו) קדשים יהיו אשה זונה וחללה וגו' (ויקרא כא ו. ז) :
@688 **איש אמו ואביו תיראו.** כל אחד מכם תיראו אביו ואמו, זהו פשוטו. ומדרשו אין לי אלא איש, אשה מנין, כשהוא אומר תיראו, הרי כאן שנים אם כן למה נאמר איש, שהאיש ספק בידו לעשות, אבל אשה רשות אחרים עליה: **אמו ואביו תיראו.** כאן הקדים אם לאב, לפי שגלוי לפניו שהבן ירא את אביו יותר מאמו, ובכבוד הקדים אב לאם, לפי שגלוי לפניו שהבן מכבד את אמו יותר מאביו, מפני שמשדלתו בדברים: **ואת שבתתי תשמרו.** סמך שמירת שבת למורא אב, לומר אף על פי שהזהרתיך על מורא אב, אם יאמר לך חלל את השבת אל תשמע לו, וכן בשאר כל המצות: **אני ה' אלהיכם.** אתה ואביך חיבים בכבודי, לפיכך לא תשמע לו לבטל את דברי. איזהו מורא, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. ואיזהו כבוד, מאכיל ומשקה, מלביש ומנעיל, מכניס ומוציא:
@689 **אל תפנו אל האלילם.** לעבדם. אלילים לשון אל, כלא הוא חשוב: **ואלהי מסכה.** תחלתן אלילים הם, ואם אתה פונה אחריהם, סופך לעשותן אלהות: **לא תעשו לכם.** לא תעשו לאחרים ולא אחרים לכם. ואם תאמר לא תעשו לעצמכם אבל אחרים עושין לכם, הרי כבר נאמר (שמות כ ג) לא יהיה לך, לא שלך ולא של אחרים:
@690 **וכי תזבחו** וגו' **.** לא נאמרה פרשה זו אלא ללמד שלא תהא זביחתן אלא על מנת להאכל בתוך הזמן הזה, שאם לקבוע להם זמן אכילה, הרי כבר נאמר (ויקרא ז טז) ואם נדר או נדבה זבח קרבנו וגו' : **לרצנכם תזבחהו.** תחלת זביחתו תהא על מנת נחת רוח שיהא לכם לרצון, שאם תחשבו עליו מחשבת פסול לא ירצה עליכם לפני: **לרצנכם.** אפיימנ''ט [פיוס] . זהו לפי פשוטו. ורבותינו למדו (חולין יג א) , מכאן למתעסק בקדשים שפסול, שצריך שיתכון לשחוט:
@691 **ביום זבחכם יאכל.** כשתזבחוהו, תשחטוהו על מנת לאכלו בזמן שקבעתי לכם כבר:
@692 **ואם האכל יאכל** וגו' **.** אם אינו ענין לחוץ לזמנו, שהרי כבר נאמר (ויקרא ז יח) ואם האכל יאכל מבשר זבח שלמיו וגו' , תנהו ענין לחוץ למקומו. יכול יהיו חייבין כרת על אכילתו, תלמוד לומר (שם) והנפש האכלת ממנו עונה תשא, ממנו ולא מחברו, יצא הנשחט במחשבת חוץ למקומו: **פגול.** מתועב, כמו (ישעיה סה ד) ומרק פגולים כליהם:
@693 **ואכליו עונו ישא.** בנותר גמור הכתוב מדבר ואינו ענוש כרת על הנשחט חוץ למקומו שכבר מיעטו הכתוב. וזהו בנותר גמור מדבר. ובמסכת כריתות (ה א) למדוהו מגזרה שוה:
@694 **לא תכלה פאת שדך.** שיניח פאה בסוף שדהו: **ולקט קצירך.** שבלים הנושרים בשעת קצירה אחת או שתים, אבל שלש אינן לקט:
@695 **לא תעולל.** לא תטל עוללות שבה והן נכרות. איזהו עוללות כל שאין לה לא כתף ולא נטף: **ופרט כרמך.** גרגרי ענבים הנושרים בשעת בצירה: **אני ה' אלהיכם.** דין להפרע ואיני גובה מכם אלא נפשות, שנאמר (משלי כב. כג) אל תגזל דל וגו' כי ה' יריב ריבם וגו' :
@696 **לא תגנבו.** אזהרה לגונב ממון, אבל לא תגנוב (שמות כ יג) שבעשרת הדברות, אזהרה לגונב נפשות, דבר הלמד מענינו, דבר שחיבין עליו מיתת בית דין: **ולא תכחשו.** לפי שנאמר (ויקרא ה כב) וכחש בה, משלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תכחשו: **ולא תשקרו.** לפי שנאמר (שם) ונשבע על שקר, ישלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תשקרו: **לא תגנבו ולא תכחשו ולא תשקרו ולא תשבעו.** אם גנבת, סופך לכחש, סופך לשקר, סופך להשבע לשקר:
@697 **ולא תשבעו בשמי.** למה נאמר, לפי שנאמר (שמות כ ז) לא תשא את שם ה' אלהיך לשוא, יכול לא יהא חיב אלא על שם המיוחד, מנין לרבות כל הכנויין, תלמוד לומר ולא תשבעו בשמי לשקר, כל שם שיש לי:
@698 **לא תעשק.** זה הכובש שכר שכיר: **לא תלין.** לשון נקבה מוסב על הפעלה: **עד בקר.** בשכיר יום הכתוב מדבר, שיציאתו מששקעה החמה, לפיכך זמן גבוי שכרו כל הלילה. ובמקום אחר הוא אומר (דברים כד טו) ולא תבוא עליו השמש, מדבר בשכיר לילה, שהשלמת פעלתו משיעלה עמוד השחר, לפיכך זמן גבוי שכרו כל היום, לפי שנתנה תורה זמן לבעל הבית עונה לבקש מעות:
@699 **לא תקלל חרש.** אין לי אלא חרש, מנין לרבות כל אדם, תלמוד לומר (שמות כב כז) בעמך לא תאר, אם כן למה נאמר חרש, מה חרש מיוחד שהוא בחיים אף כל שהוא בחיים, יצא המת שאינו בחיים: **ולפני עור לא תתן מכשל.** לפני הסומא בדבר לא תתן עצה שאינה הוגנת לו, אל תאמר מכור שדך וקח לך חמור, ואתה עוקף עליו ונוטלה המנו: **ויראת מאלהיך.** לפי שהדבר הזה אינו מסור לבריות לידע אם דעתו של זה לטובה או לרעה, ויכול להשמט ולומר לטובה נתכונתי, לפיכך נאמר בו ויראת מאלהיך המכיר מחשבותיך. וכן כל דבר המסור ללבו של אדם העושהו ואין שאר הבריות מכירות בו, נאמר בו ויראת מאלהיך:
@700 **לא תעשו עול במשפט.** מלמד שהדין המקלקל את הדין קרוי עול, שנאוי ומשקץ, חרם ותועבה. שהעול קרוי תועבה, שנאמר (דברים כה טז) כי תועבת ה' וגו' כל עשה עול, והתועבה קרויה שקץ וחרם, שנאמר (שם ז כו) ולא תביא תועבה אל ביתך והיית חרם כמוהו שקץ תשקצנו וגו' : **לא תשא פני דל.** שלא תאמר עני הוא זה והעשיר חיב לפרנסו, אזכנו בדין, ונמצא מתפרנס בנקיות: **ולא תהדר פני גדול.** שלא תאמר עשיר הוא זה בן גדולים הוא זה, היאך אבישנו ואראה בבשתו, עונש יש בדבר, לכך נאמר ולא תהדר פני גדול: **בצדק תשפט עמיתך.** כמשמעו. דבר אחר הוי דן את חברך לכף זכות:
@701 **לא תלך רכיל.** אני אומר על שם שכל משלחי מדנים ומספרי לשון הרע הולכים בבתי רעיהם לרגל מה יראו רע או מה ישמעו רע לספר בשוק, נקראים הולכי רכיל, הולכי רגילה אשפיימנ''ט בלע''ז [רגול] . וראיה לדברי, שלא מצינו רכילות שאין כתוב בלשון הליכה לא תלך רכיל, הולכי רכיל נחשת וברזל (ירמיה ו כח) , ושאר לשון הרע אין כתוב בו הליכה מלשני בסתר רעהו (תהלים קא ה) , לשון רמיה (שם קכ ב) , לשון מדברת גדולות (שם יב ד) , לכך אני אומר שלשון רכיל לשון הולך ומרגל, שהכ''ף נחלפת בגימ''ל, שכל האותיות שמוצאיהם ממקום אחד מתחלפות זו בזו, בי''ת בפ''א ובוי''ו, גימ''ל בכ''ף וקו''ף, נו''ן בלמ''ד, ורי''ש וז''ן בצד''י וכן (ש''ב יט כח) וירגל בעבדך, רגל במרמה לומר עלי רעה, וכן (תהלים טו ג) לא רגל על לשונו, וכן רוכל הסוחר ומרגל אחר כל סחורה, וכל המוכר בשמים להתקשט בהם הנשים, על שם שמחזר תמיד בעירות נקרא רוכל, לשון רוגל. ותרגומו לא תיכול קרצין, כמו (דניאל ג ח) ואכלו קרציהון די יהודיא, אכל ביה קרצא בי מלכא (ברכות נח א) . נראה בעיני שהיה משפטם לאכול בבית המקבל דבריהם שום הלעטה, והוא גמר חזוק, שדבריו מקימים ויעמידם על האמת, ואותה הלעטה נקראת אכילת קרצין, לשון קורץ בעיניו (משלי ו יג) , שכן דרך כל הולכי רכיל לקרוץ בעיניהם ולרמוז דברי רכילותן, שלא יבינו שאר השומעים: **לא תעמד על דם רעך.** לראות במיתתו ואתה יכול להצילו, כגון טובע בנהר, וחיה או לסטים באים עליו: **אני ה'.** נאמן לשלם שכר, ונאמן להפרע:
@702 **ולא תשא עליו חטא.** לא תלבין את פניו ברבים:
@703 **לא תקם.** אמר לו השאילני מגלך. אמר לו לאו. למחר אמר לו השאילני קרדמך. אמר לו איני משאילך כדרך שלא השאלתני, זו היא נקימה. ואיזו היא נטירה, אמר לו השאילני קרדמך. אמר לו לאו. למחר אמר לו השאילני מגלך. אמר לו הא לך ואיני כמותך, שלא השאלתני. זו היא נטירה, שנוטר האיבה בלבו אף על פי שאינו נוקם: **ואהבת לרעך כמוך.** אמר רבי עקיבא זה כלל גדול בתורה:
@704 **את חקתי תשמרו.** ואלו הן בהמתך לא תרביע כלאים וגו' , חקים אלו גזרות מלך שאין טעם לדבר: ובגד כלאים. למה נאמר, לפי שנאמר לא תלבש שעטנז צמר ופשתים יחדו (דבר' כב יא) , יכול לא ילבש גיזי צמר ואניצי פשתן, תלמוד לומר בגד. מנין לרבות הלבדים, תלמוד לומר שעטנז, דבר שהוא שוע טווי ונוז. ואומר אני נוז לשון דבר הנמלל ושזור זה עם זה לחברו, מישטי''ר בלע''ז [לערבב] , כמו (מועד קטן יב ב) חזיין לנאזי דאית בהון, שאנו מפרשין לשון כמוש פלישטר''א . ולשון שעטנז פרש מנחם, מחברת צמר ופשתים:
@705 **נחרפת לאיש.** מיועדת ומיוחדת לאיש, ואיני ידע לו דמיון במקרא. ובשפחה כנענית שחציה שפחה וחציה בת חורין המאורסת לעבד עברי שמתר בשפחה, הכתוב מדבר: **והפדה לא נפדתה.** פדויה ואינה פדויה וסתם פדיון בכסף: **או חפשה.** בשטר: **בקרת תהיה.** היא לוקה ולא הוא, יש על בית דין לבקר את הדבר שלא לחיבה (י''ג: לחיבו) מיתה: **כי לא חפשה.** ואין קדושיה קדושין גמורין. ורבותינו למדו מכאן שמי שהוא במלקות יהא בקריאה, שהדינים המלקין קורין על הלוקה (דברים כח נח, נט) אם לא תשמר לעשות וגו' והפלא ה' את מכותך וגו' : **כי לא חפשה.** לפיכך אין חיב עליה מיתה, שאין קדושיה קדושין, הא אם חפשה, קדושיה קדושין וחיב מיתה:
@707 **ונסלח לו מחטאתו אשר חטא.** לרבות את המזיד כשוגג:
@708 **וערלתם ערלתו.** ואטמתם אטימתו, יהא אטום ונסתם מליהנות ממנו: **שלש שנים יהיה לכם ערלים.** מאימתי מונה לו, משעת נטיעתו. יכול אם הצניעו, לאחר שלש שנים יהא מתר, תלמוד לומר יהיה, בהויתו יהא:
@709 **יהיה כל פריו קדש.** כמעשר שני שכתוב בו (ויקרא כז ל) וכל מעשר הארץ וגו' קדש לה'. מה מעשר שני אינו נאכל חוץ לחומת ירושלים אלא בפדיון, אף זה כן. ודבר זה הלולים לה' הוא, שנושאו שם לשבח ולהלל לשמים:
@710 **להוסיף לכם תבואתו.** המצוה הזאת שתשמרו תהיה להוסיף לכם תבואתו, שבשכרה אני מברך לכם פרות הנטיעות. היה רבי עקיבא אומר דברה תורה כנגד יצר הרע, שלא יאמר אדם הרי ארבע שנים אני מצטער בו חנם, לפיכך נאמר להוסיף לכם תבואתו: **אני ה'.** אני ה' המבטיח על כך ונאמן לשמור הבטחתי:
@711 **לא תאכלו על הדם.** להרבה פנים נדרש בסנהדרין (סג א) אזהרה שלא יאכל מבשר קדשים לפני זריקת דמים, ואזהרה לאוכל מבהמת חלין טרם שתצא נפשה, ועוד הרבה: **לא תנחשו.** כגון אלו המנחשין בחלדה ובעופות, פתו נפלה מפיו, צבי הפסיקו בדרך: **ולא תעוננו.** לשון עונות ושעות, שאומר יום פלוני יפה להתחיל מלאכה, שעה פלונית קשה לצאת:
@712 **לא תקפו פאת ראשכם.** זה המשוה צדעיו לאחורי אזנו ולפדחתו, ונמצא הקף ראשו עגל סביב, שעל אחורי אזניו עקרי שערו למעלה מצדעיו הרבה: **פאת זקנך.** סוף הזקן וגבוליו. והן חמש שתים בכל לחי ולחי למעלה אצל הראש שהוא רחב ויש בו שתי פאות, ואחת למטה בסנטרו מקום חבור שני הלחיים יחד:
@713 **ושרט לנפש.** כן דרכן של אמוריים להיות משרטין בשרם כשמת להם מת: **וכתבת קעקע.** כתב המחקה ושקוע שאינו נמחק לעולם שמקעקעו במחט והוא משחיר לעולם: **קעקע.** לשון (במד' כה ד) והוקע אותם, (שמואל ב כא ו) והוקענום. תוחבין עץ בארץ ותולין אותם עליהם ונמצאו מחקין ותחובין בקרקע, פורפויינ''ט בלע''ז [נעוץ] :
@714 **אל תחלל את בתך להזנותה.** במוסר בתו פנויה לביאה שלא לשם קדושין: **ולא תזנה הארץ.** אם אתה עושה כן הארץ מזנה את פירותיה לעשותן במקום אחר ולא בארצכם. וכן הוא אומר (ירמיה ג ג) וימנעו רבבים וגו' :
@715 **ומקדשי תיראו.** לא יכנס בהר הבית לא במקלו ולא במנעלו ובאפונדתו ובאבק שעל רגליו. ואף על פי שאני מזהירכם על המקדש, את שבתותי תשמרו אין בנין בית המקדש דוחה שבת:
@716 **אל תפנו אל האבת.** אזהרה לבעל אוב וידעוני. בעל אוב זה פיתום המדבר משחיו. וידעוני מכניס עצם חיה ששמה ידוע לתוך פיו והעצם מדבר: **אל תבקשו.** להיות עסוקים בם, שאם תעסקו בם אתם מטמאין לפני ואני מתעב אתכם: **אני ה' אלהיכם.** דעו את מי אתם מחליפין במי:
@717 **מפני שיבה תקום.** יכול זקן אשמאי, תלמוד לומר זקן, אין זקן אלא שקנה חכמה: **והדרת פני זקן.** איזהו הדור, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. יכול יעצים עיניו כמי שלא ראהו, לכך נאמר ויראת מאלהיך, שהרי דבר זה מסור ללבו של עושהו, שאין מכיר בו אלא הוא, וכל דבר המסור ללב נאמר בו ויראת מאלהיך:
@718 **לא תונו.** אונאת דברים. לא תאמר לו אמש היית עובד עבודה זרה ועכשיו אתה בא ללמוד תורה שנתנה מפי הגבורה:
@719 **כי גרים הייתם.** מום שבך אל תאמר לחברך: **אני ה' אלהיכם.** אלהיך ואלהיו אני:
@720 **לא תעשו עול במשפט.** אם לדין, הרי כבר נאמר לא תעשו עול במשפט (פסוק טו) , ומהו משפט השנוי כאן, הוא המדה והמשקל והמשורה. מלמד שהמודד נקרא דין, שאם שקר במדה הרי הוא כמקלקל את הדין וקרוי עול, שנאוי, ומשקץ, חרם ותועבה. וגורם לחמשה דברים האמורים בדין מטמא את הארץ, ומחלל את השם, ומסלק את השכינה, ומפיל את ישראל בחרב, ומגלה אותם מארצם: **במדה.** זו מדת הארץ: **במשקל.** כמשמעו: **ובמשורה.** היא מדת הלח והיבש:
@721 **אבני צדק.** הם המשקולות ששוקלין כנגדן: **איפת.** היא מדת היבש: **הין.** זו היא מדת הלח: **אשר הוצאתי אתכם.** על מנת כן. דבר אחר אני הבחנתי במצרים בין טפה של בכור לטפה שאינה של בכור, ואני הנאמן להפרע ממי שטומן משקלותיו במלח להונות את הבריות שאין מכירים בהם:
@724 **ואל בני ישראל תאמר.** ענשין על האזהרות: **מות יומת.** בבית דין, ואם אין כח לבית דין עם הארץ מסיעין אותן: **עם הארץ.** עם שבגינו נבראת הארץ. דבר אחר עם שעתידין לירש את הארץ על ידי מצות הללו:
@725 **אתן את פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו: **באיש.** ולא בצבור, שאין כל הצבור נכרתין: **כי מזרעו נתן למלך.** לפי שנאמר מעביר בנו ובתו באש (דברים יח י) , בן בנו ובן בתו מנין, תלמוד לומר כי מזרעו נתן למלך. זרע פסול מנין, תלמוד לומר בתתו מזרעו למלך: **למען טמא את מקדשי.** את כנסת ישראל, שהיא מקדשת לי, כלשון (ויקרא כא כג) ולא יחלל את מקדשי:
@726 **ואם העלם יעלימו.** אם העלימו בדבר אחד, סוף שיעלימו בדברים הרבה. אם העלימו סנהדרי קטנה, סוף שיעלימו סנהדרי גדולה:
@727 **ובמשפחתו.** אמר ר' שמעון וכי משפחה מה חטאה, אלא ללמדך שאין לך משפחה שיש בה מוכס שאין כלם מוכסין, שכלם מחפין עליו: **והכרתי אתו.** למה נאמר, לפי שנאמר ובמשפחתו, יכול יהיו כל המשפחה בהכרת, תלמוד לומר אותו. אותו בהכרת ולא כל המשפחה בהכרת, אלא ביסורין: **לזנות אחרי המלך.** לרבות שאר עבודה זרה שעבדה בכך, ואפלו אין זו עבודתה:
@729 **והתקדשתם.** זו פרישות עבודה זרה:
@731 **אביו ואמו קלל.** לרבות לאחר מיתה: **דמיו בו.** זו סקילה, וכן כל מקום שנאמר דמיהם בם. ולמדנו מאוב וידעוני שנאמר בהם באבן ירגמו אותם דמיהם בם (פסוק כז) . ופשוטו של מקרא, כמו דמו בראשו (יהושע ב יט) , אין נענש על מיתתו אלא הוא, שהוא גרם לעצמו שיהרג:
@732 **ואיש.** פרט לקטן: **אשר ינאף את אשת איש.** פרט לאשת קטן, למדנו שאין לקטן קדושין. ועל איזו אשת איש חיבתי לך: **אשר ינאף את אשת רעהו.** פרט לאשת גוי, למדנו שאין קדושין לגוי: **מות יומת הנאף והנאפת.** כל מיתה האמורה בתורה סתם אינה אלא חנק:
@734 **תבל עשו.** גנאי. לשון אחר מבלבלין זרע האב בזרע הבן:
@735 **משכבי אשה.** מכניס כמכחול בשפופרת:
@736 **ישרפו אתו ואתהן.** אי אתה יכול לומר אשתו הראשונה ישרפו, שהרי נשאה בהתר ולא נאסרה עליו, אלא אשה ואמה הכתובין כאן, שתיהן לאסור, שנשא את חמותו ואמה. ויש מרבותינו שאומרים, אין כאן אלא חמותו. ומהו אתהן, את אחת מהן, ולשון יוני הוא הן אחת:
@737 **ואת הבהמה תהרגו.** אם אדם חטא בהמה מה חטאה, אלא מפני שבאה לאדם תקלה על ידה, לפיכך אמר הכתוב תסקל. קל וחמר לאדם שיודע להבחין בין טוב לרע וגורם רעה לחברו לעבור עברה. כיוצא בדבר אתה אומר (דברים יב ב) אבד תאבדון את כל המקומות, הרי דברים קל וחמר, מה אילנות שאינן רואין ואינן שומעין על שבאת תקלה על ידם אמרה תורה השחת, שרוף וכלה, המטה את חברו מדרך חיים לדרכי מיתה על אחת כמה וכמה:
@739 **חסד הוא.** לשון ארמי חרפה (בראשית לד יד) חסודא. ומדרשו אם תאמר קין נשא אחותו, חסד עשה המקום לבנות עולמו ממנו, שנאמר (תהלים פט ג) עולם חסד יבנה:
@740 **הערה.** גלה. וכן כל לשון ערוה גלוי הוא, והוי''ו יורדת בתבה לשם דבר, כמו זעוה, מגזרת (אסתר ה ט) ולא קם ולא זע, וכן אחוה מגזרת אח. והעראה זו נחלקו בה רבותינו, יש אומרים זו נשיקת שמש, ויש אומרים זו הכנסת עטרה:
@741 **וערות אחות אמך** וגו' **.** שנה הכתוב באזהרתן, לומר שהזהר עליהן בין על אחות אביו ואמו מן האב בין על אחיותיהן מן האם, אבל ערות אשת אחי אביו לא הזהר אלא על אשת אחי אביו מן האב:
@742 **אשר ישכב את דדתו.** המקרא הזה בא ללמד על כרת האמור למעלה, שהוא בענש הליכת ערירי: **ערירים.** כתרגומו בלא ולד, ודומה לו (בראשית טו ב) ואנכי הולך ערירי. יש לו בנים קוברן, אין לו בנים מת בלא בנים, לכך שנה בשני מקראות אלו ערירים ימותו ערירים יהיו. ערירים ימותו, אם יהיו לו בשעת עברה, לא יהיו לו כשימות לפי שקוברן בחייו. ערירים יהיו, שאם אין לו בשעת עברה, יהיה כל ימיו כמו שהוא עכשו:
@743 **נדה הוא.** השכיבה הזאת מנדה היא ומאוסה. ורבותינו דרשו לאסור העראה בה כנדה, שהעראה מפורשת בה (פסוק יח) את מקורה הערה (לעיל יח) :
@745 **ואקץ.** לשון מיאוס, כמו (בראשית כז מו) קצתי בחיי, כאדם שהוא קץ במזונו:
@747 **והבדלתם בין הבהמה הטהרה לטמאה.** אין צריך לומר בין פרה לחמור, שהרי מבדלין ונכרין הם, אלא בין טהורה לך לטמאה לך, בין שנשחט רבו של סימן לנשחט חציו. וכמה בין רבו לחציו, מלא שערה: **אשר הבדלתי לכם לטמא.** לאסור:
@748 **ואבדל אתכם מן העמים להיות לי.** אם אתם מבדלים מהם הרי אתם שלי, ואם לאו הרי אתם של נבוכדנצר וחבריו. רבי אלעזר בן עזריה אומר מנין שלא יאמר אדם נפשי קצה בבשר חזיר, אי אפשי ללבוש כלאים, אבל יאמר אפשי, ומה אעשה ואבי שבשמים גזר עלי, תלמוד לומר ואבדיל אתכם מן העמים להיות לי, שתהא הבדלתכם מהם לשמי, פורש מן העברה ומקבל עליו עול מלכות שמים:
@749 **כי יהיה בהם אוב** וגו' **.** כאן נאמר בהם מיתה ולמעלה כרת. עדים והתראה בסקילה, מזיד בלא התראה בהכרת ושגגתם חטאת, וכן בכל חיבי מיתות שנאמר בהם כרת:
@750 **הלא כבני כושיים אתם לי.** למה אמנע מלהפרע מכם אחרי אשר אינכם שבים אלי הלא מן בני נח באתם כשאר עכו"ם ככושיים אשר נדמיתם להם כענין שנאמר ( ירמיה יג ) היהפוך כושי עורו כך אתם תוכלו להטיב: **הלא.** בטובתי תחילת בוחרי בכם היא הוצאה שהוצאתי אתכם מארץ מצרים ומה לי בכך אף פלשתים כך הוצאתי מכפתור כשבאו כפתורים על עוים כענין שנאמר ( דברים ב ) והעוים היושבים בחצרים עד עזה וגו' כבשו גם בני עזה ושאר סרני פלשתים תחתיהם והוצאתים מידם ואעפ"כ לא עשיתים לי לעם: **וארם מקיר.** וכן אני עתיד להעלות את ארם מקיר שיגלם שם סנחריב ולקץ הימים משתבטל מלכות אשור יצאו:
@751 **והשמדתי אותה.** הממלכה הם בית יהוא אבל בית יעקב לא אשמיד:
@752 **כי הנה אנכי מצוה.** להגלותם ולהניעם בכל הגוים הנעה רבה ויתירה כאשר ינוע מה שכוברין בכברה לאחר שנפלו ממנו סובין הדקין ונותרו הגסין שאין יכולין לצאת ואז המנענע מנענע בכל כחו: **ינוע.** על ידי אחר ולא יתכן לקרות ינוע שהוא דבר הנע מאליו:
@753 **לא תגיש ותקדים בעדינו הרעה.** בשביל עוונינו לא תמהר הרעה לגשת ולבא:
@754 **ביום ההוא.** אחרי בא עליהם כל אלה יבא יום ההוא המוכן לגאולה ובו אקים סוכת דוד הנופלת, י"ת מלכותא דבית דוד:
@755 **למען יירשו.** ישראל את שארית וגו' ואת כל העכו"ם כי נקרא שמי עליהם. אשר. כמו כי:
@756 **ונגש חורש בקוצר.** והשיג דיש את בציר ובציר ישיג את זרע ( ויקרא כו ) לא יספיקו לחרוש עד שיבא הקציר ולא יספיקו לבצור עד שיבא עת הזרע: **תתמוגגנה.** תרגם יונתן יתפלחן, קרקע עבודה מתמוגגת בבא גשמים: **עסיס.** יין טוב ומתוק:
@760 **אם אדרש לכם.** בבקשתכם ובסוף הספר הזה הוא אמר אדרש לבית ישראל זו אחת מן המקומות המלמדים אותנו שהקב"ה חוזר בו על הרעה ועל כיוצא בזה ההוא אמר ולא יעשה ( במדבר כג ) מדרש תנחומא:
@761 **התשפוט אותם.** לשון ויכוח:
@762 **ביום בחרי בישראל.** הרי שהיתה שנאה זו כבושה לפני המקום קרוב לתשע מאות שנה משהיו במצרי' עד יחזקאל והיתה אהבתו מחפ' עליהם ועל ידי שהיו עתה מרבים לפשוע נתעוררה ועל זה נאמר שנאה תעורר מדנים וגו' ( משלי י ):
@764 **ואומר אליהם.** אהרן ניבא להם נבואה זו קודם שנגלה הקב"ה על משה בסנה וזהו שנאמר ( שמואל א ב ) לעלי הנגלה נגלתי אל בית אביך בהיותם במצרים וגו':
@765 **וימרו בי.** הם הרשעים רובם של ישראל שמתו בשלשת ימי אפלה כמו שנאמר וחמושים עלו בני ישראל וגו' ( שמות יד ) אחד מחמשים ויש אומרים אחד מחמש מאות:
@766 **לבלתי החל.** שלא יתחלל שמי מאחר שנודעתי להם והבטחתים להוציאם והכירו מצרים שהם עמי אילו הייתי משחיתם היו אומרים אויביהם מבלתי יכולת בידו להוציאם:
@769 **להיות לאות.** אות גדול הוא להם שנתתי את יום מנוחתי להם למנוחה הרי היכר גדול שקדשתים לי:
@770 **בחוקותי לא הלכו.** נסו אותי בעגל וברפידים מלקבל את התורה והותירו מן המן: **ואת שבתותי חללו.** יצאו מן העם ללקוט מן:
@778 **אמר אל הכהנים.** אמר ואמרת, להזהיר גדולים על הקטנים: **בני אהרן.** יכול חללים, תלמוד לומר הכהנים: **בני אהרן.** אף בעלי מומין במשמע: **בני אהרן.** ולא בנות אהרן: **לא יטמא בעמיו.** בעוד שהמת בתוך עמיו, יצא מת מצוה:
@779 **כי אם לשארו.** אין שארו אלא אשתו:
@780 **הקרובה.** לרבות את הארוסה: **אשר לא היתה לאיש.** למשכב: **לה יטמא.** מצוה:
@781 **לא יטמא בעל בעמיו להחלו.** לא יטמא לאשתו פסולה שהוא מחלל בה בעודה עמו. וכן פשוטו של מקרא לא יטמא בעל בשארו בעוד שהוא בתוך עמיו, שיש לה קוברין, שאינה מת מצוה, ובאיזה שאר אמרתי, באותו שהוא להחלו, להתחלל הוא מכהנתו:
@782 **לא יקרחו קרחה.** על מת. והלא אף ישראל הזהרו על כך, אלא לפי שנאמר בישראל (דברים יד א) בין עיניכם, יכול לא יהא חיב על כל הראש, תלמוד לומר בראשם, וילמדו ישראל מהכהנים בגזרה שוה, נאמר כאן קרחה ונאמר להלן בישראל קרחה, מה כאן כל הראש אף להלן כל הראש במשמע, כל מקום שיקרח בראש. ומה להלן על מת, אף כאן על מת: **ופאת זקנם לא יגלחו.** לפי שנאמר בישראל (ויקרא יט כז) ולא תשחית, יכול לקטו במלקט וברהיטני יהא חיב, לכך נאמר לא יגלחו, שאינו חיב אלא על דבר הקרוי גלוח ויש בו השחתה, וזהו תער: **ובבשרם לא ישרטו שרטת.** לפי שנאמר בישראל (ויקרא שם כח) ושרט לנפש לא תתנו, יכול שרט חמש שריטות לא יהא חיב אלא אחת, תלמוד לומר לא ישרטו שרטת, לחייב על כל שריטה ושריטה. שתיבה זו יתרה היא לדרוש, שהיה לו לכתוב לא ישרטו ואני יודע שהיא שרטת:
@783 **קדשים יהיו.** על כרחם יקדישום בית דין בכך:
@784 **זנה.** שנבעלה בעילת ישראל האסור לה, כגון חיבי כרתות או נתין או ממזר: **חללה.** שנלדה מן הפסולים שבכהנה, כגון בת אלמנה מכהן גדול או בת גרושה וחלוצה מכהן הדיוט, וכן שנתחללה מן הכהנה על ידי ביאת אחד מן הפסולים לכהנה:
@785 **וקדשתו.** על כרחו, שאם לא רצה לגרש, הלקהו ויסרהו עד שיגרש: **קדש יהיה לך.** נהוג בו קדשה לפתוח ראשון בכל דבר ולברך ראשון בסעודה:
@786 **כי תחל לזנות.** כשתתחלל על ידי זנות, שהיתה בה זיקת בעל וזנתה או מן האירוסין או מן הנשואין. ורבותינו נחלקו בדבר, והכל מודים שלא דבר הכתוב בפנויה: **את אביה היא מחללת.** חללה ובזתה את כבודו, שאומרים עליו ארור שזו ילד, ארור שזו גדל:
@787 **לא יפרע.** לא יגדל פרע על אבל. ואיזהו גדול פרע, יותר משלשים יום:
@788 **ועל כל נפשת מת** וגו' **.** באהל המת: **נפשת מת.** להביא רביעית דם מן המת שמטמא באהל: **לאביו ולאמו לא יטמא.** לא בא אלא להתיר לו מת מצוה:
@789 **ומן המקדש לא יצא.** אינו הולך אחר המטה. ועוד מכאן למדו רבותינו שכהן גדול מקריב אונן, וכן משמעו, אף אם מתו אביו ואמו אינו צריך לצאת מן המקדש אלא עובד עבודה: **ולא יחלל את מקדש.** שאינו מחלל בכך את העבודה שהתיר לו הכתוב, הא כהן הדיוט שעבד אונן חלל:
@791 **וחללה.** שנלדה מפסולי כהנה:
@792 **ולא יחלל זרעו.** הא אם נשא אחת מן הפסולות, זרעו המנה חלל מדין קדשת כהנה:
@794 **לחם אלהיו.** מאכל אלהיו, כל סעודה קרויה לחם, כמו (דניאל ה א) עבד לחם רב:
@795 **כי כל איש אשר בו מום לא יקרב.** אינו דין שיקרב, כמו (מלאכי א ח) הקריבהו נא לפחתך: **חרם.** שחטמו שקוע בין שתי העינים, שכוחל שתי עיניו כאחת: **או שרוע.** שאחד מאיבריו גדול מחברו, עינו אחת גדולה ועינו אחת קטנה, או שוקו אחת ארכה מחברתה:
@797 **או גבן.** שורצילו''ש בלע''ז [בעל גבות ארוכות] שגביני עיניו שערן ארוך ושוכב: **או דק.** שיש לו בעיניו דוק שקורין טיל''א [קרום] , כמו (ישעיה מ כב) הנוטה כדוק: **או תבלל.** דבר המבלבל את העין, כגון חוט לבן הנמשך מן הלבן ופוסק בסירא, שהוא עוגל המקיף את השחור, שקוראים פרוניל''א [אישון] , והחוט הזה פוסק את העוגל ונכנס בשחור. ותרגום תבלל חליז, לשון חלזון, שהוא דומה לתולעת אותו החוט. וכן כנוהו חכמי ישראל במומי הבכור חלזון נחש עינב (בכורות לח א) : **גרב וילפת.** מיני שחין הם: גרב, זו החרס. שחין היבש מבפנים ומבחוץ: ילפת, היא חזזית המצרית. ולמה נקראת ילפת שמלפפת והולכת עד יום המיתה, והוא לח מבחוץ ויבש מבפנים. ובמקום אחר קורא לגרב שחין, הלח מבחוץ ויבש מבפנים, שנאמר (דברים כח כז) ובגרב ובחרס, כשסמוך גרב אצל חרס קורא לילפת גרב, וכשהוא סמוך אצל ילפת קורא לחרס גרב, כך מפורש בבכורות (מא א) : **מרוח אשך.** לפי התרגום מריס פחדין, שפחדיו מרססים, שביצים שלו כתותין. פחדין כמו (איוב מ יז) גידי פחדו ישורגו:
@798 **כל איש אשר בו מום.** לרבות שאר מומין: **מום בו.** בעוד מומו בו פסול, הא אם עבר מומו כשר: **לחם אלהיו.** כל מאכל קרוי לחם:
@799 **מקדשי הקדשים.** אלו קדשי הקדשים: **ומן הקדשים יאכל.** אלו קדשים קלים. ואם נאמרו קדשי הקדשים למה נאמרו קדשים קלים, אם לא נאמרו הייתי אומר בקדשי הקדשים יאכל בעל מום, שמצינו שהתרו לזר, שאכל משה בשר המלואים, אבל בחזה ושוק של קדשים קלים לא יאכל, שלא מצינו זר חולק בהן, לכך נאמרו קדשים קלים. כך מפורש בזבחים (קא:) :
@800 **אך אל הפרכת.** להזות שבע הזאות שעל הפרכת: **ואל המזבח.** החיצון. ושניהם הצרכו להכתב, ומפורש בתורת כהנים: **ולא יחלל את מקדשי.** שאם עבד, עבודתו מחללת להפסל:
@801 **וידבר משה.** המצוה הזאת: **אל אהרן ואל בניו ואל כל בני ישראל.** להזהיר בית דין על הכהנים:
@803 **וינזרו.** אין נזירה אלא פרישה, וכן הוא אומר (יחזקאל יד ז) וינזר מאחרי, (ישעיה א ד) נזורו אחור, יפרשו מן הקדשים בימי טמאתן. דבר אחר: וינזרו מקדשי בני ישראל אשר הם מקדישים לי ולא יחללו את שם קדשי. סרס המקרא ודרשהו, אשר הם מקדשים לי ולא יחללו את שם קדשי: **אשר הם מקדשים לי.** לרבות קדשי כהנים עצמן:
@804 **כל איש אשר יקרב.** אין קריבה זו אלא אכילה, וכן מצינו שנאמרה אזהרת אכילת קדשים בטמאה בלשון נגיעה בכל קדש לא תגע (ויקרא יב ד) , אזהרה לאוכל. ולמדוה רבותינו מגזרה שוה. ואי אפשר לומר שחיב על הנגיעה, שהרי נאמר כרת על האכילה בצו את אהרן (ויקרא ז כ. כא) שתי כריתות זו אצל זו, ואם על הנגיעה חיב לא הצרך לחיבו על האכילה, וכן נדרש בתורת כהנים וכי יש נוגע חיב, אם כן מה תלמוד לומר יקרב, משיכשר לקרב, שאין חיבין עליו משום טמאה, אלא אם כן קרבו מתיריו. ואם תאמר שלש כריתות בטמאת כהנים למה, כבר נדרשו במסכת שבועות אחת לכלל ואחת לפרט וכו' (שבועות ז א) : **וטמאתו עליו.** וטמאת האדם עליו, יכול בבשר הכתוב מדבר, וטמאתו של בשר עליו, ובטהור שאכל את הטמא הכתוב מדבר, הרי כבר נאמר (ויק' ז יט) והבשר אשר יגע בכל טמא לא יאכל, אלא על כרחך ממשמעו אתה למד, במי שטמאתו פורחת ממנו הכתוב מדבר, וזהו האדם שיש לו טהרה בטבילה: **ונכרתה** וגו' **.** יכול מצד זה לצד זה, יכרת ממקומו ויתישב במקום אחר, תלמוד לומר אני ה', בכל מקום אני:
@805 **מזרע אהרן.** אין לי אלא זרעו, גופו מנין, תלמוד לומר והוא צרוע, שיכול הואיל ומקריב אונן יקריב צרוע וזב, תלמוד לומר והוא: **עד אשר יטהר.** ביאת השמש, או אינו אלא טבילה, נאמר כאן וטהר, ונאמר למטה וטהר (פסוק ז) ובא השמש וטהר, מה להלן ביאת שמש, אף כאן ביאת שמש: **בכל טמא נפש.** במי שנטמא במת:
@806 **בכל שרץ אשר יטמא לו.** בשעור הראוי לטמא, בכעדשה: **או באדם.** במת: **אשר יטמא לו.** כשיעורו לטמא, וזהו כזית: **לכל טמאתו.** לרבות נוגע בזב וזבה, נדה ויולדת ובמצורע:
@807 **נפש אשר תגע בו.** באחד מן הטמאים הללו:
@808 **ואחר יאכל מן הקדשים.** נדרש ביבמות בתרומה, שמתר לאכלה בהערב השמש: **מן הקדשים.** ולא כל הקדשים:
@809 **נבלה וטרפה לא יאכל לטמאה בה.** לענין הטמאה הזהיר כאן, שאם אכל נבלת עוף טהור, שאין לה טמאת מגע ומשא אלא טמאת אכילה בבית הבליעה, אסור לאכול בקדשים. וצריך לומר וטרפה, מי שיש במינו טרפה, יצא נבלת עוף טמא שאין במינו טרפה:
@810 **ושמרו את משמרתי.** מלאכול תרומה בטמאת הגוף: **ומתו בו.** למדנו שהיא מיתה בידי שמים:
@811 **לא יאכל קדש.** בתרומה הכתוב מדבר, שכל הענין דבר בה: **תושב כהן ושכיר.** תושבו של כהן ושכירו, לפיכך תושב זה נקוד פתח, לפי שהוא דבוק. ואיזהו תושב, זה נרצע שהוא קנוי לו עד היובל, ואיזהו שכיר, זה קנוי קנין שנים, שיוצא בשש, בא הכתוב ולמדך כאן שאין גופו קנוי לאדוניו לאכול בתרומתו:
@812 **וכהן כי יקנה נפש.** עבד כנעני שקנוי לגופו: **ויליד ביתו.** אלו בני השפחות. ואשת כהן אוכלת בתרומה מן המקרא הזה, שאף היא קנין כספו. ועוד למד ממקרא אחר (במדבר יח יא) כל טהור בביתך וגו' בספרי:
@813 **לאיש זר.** ללוי ולישראל:
@814 **אלמנה וגרושה.** מן האיש הזר: **וזרע אין לה.** ממנו: **ושבה.** הא אם יש לה זרע ממנו אסורה בתרומה כל זמן שהזרע קים: **וכל זר לא יאכל בו.** לא בא אלא להוציא את האונן שמתר בתרומה. זרות אמרתי לך, ולא אנינות:
@815 **כי יאכל קדש.** תרומה: **ונתן לכהן את הקדש.** דבר הראוי להיות קדש, שאינו פורע לו מעות אלא פירות של חלין, והן נעשין תרומה:
@816 **ולא יחללו** וגו' **.** להאכילם לזרים:
@817 **והשיאו אותם.** את עצמם יטענו עון באכלם את קדשיהם, שהבדלו לשם תרומה וקדשו ונאסרו עליהם. ואנקלוס שתרגם במיכלהון בסואבא, שלא לצורך תרגמו כן: **והשיאו אותם.** זה אחד משלשה אתים שהיה רבי ישמעאל דורש בתורה שמדברים באדם עצמו, וכן (במ' ו יג) ביום מלאת ימי נזרו יביא אתו, הוא יביא את עצמו. וכן (דברים לד ו) ויקבור אתו בגיא, הוא קבר את עצמו, כך נדרש בספרי:
@819 **נדריהם.** הרי עלי: **נדבתם.** הרי זו:
@820 **לרצנכם.** הביאו דבר הראוי לרצות אתכם לפני, שיהא לכם לרצון אפיימני''ט בלע''ז . ואיזהו הראוי לרצון, **תמים זכר בבקר בכשבים ובעזים.** אבל בעולת העוף אין צריך תמות וזכרות, ואינו נפסל במום אלא בחסרון אבר:
@822 **לפלא נדר.** להפריש בדבורו:
@823 **עורת.** שם דבר של מום עורון בלשון נקבה, שלא יהא בו מום של עורת: **או שבור.** לא יהיה: **חרוץ.** ריס של עין שנסדק או שנפגם, וכן שפתו שנסדקה או נפגמה: **יבלת.** ורוא''ה בלע''ז : **גרב.** מין חזזית וכן ילפת. ולשון ילפת, כמו (שופטים טז כט) וילפת שמשון, שאחוזה בו עד יום מיתה, שאין לה רפואה: **לא תקריבו.** שלש פעמים, להזהיר על הקדשן ועל שחיטתן ועל זריקת דמן: **ואשה לא תתנו.** אזהרת הקטרתן:
@824 **שרוע.** אבר גדול מחברו: **וקלוט.** פרסותיו קלוטות: **נדבה תעשה אתו.** לבדק הבית: **ולנדר.** למזבח: **לא ירצה.** איזהו הקדש בא לרצות, הוי אומר זה הקדש המזבח:
@825 **ומעוך וכתות ונתוק וכרות.** בביצים או בגיד: **מעוך.** ביציו מעוכין ביד: **כתות.** כתושים יותר ממעוך: **נתוק.** תלושין ביד עד שנפסקו חוטים שתלויים בהן, אבל נתונים הם בתוך הכיס, והכיס לא נתלש: **וכרות.** כרותין בכלי ועודן בכיס: **ומעוך.** תרגומו ודמריס, זה לשונו בארמית, לשון כתישה: **וכתות.** תרגומו ודרסיס, כמו (עמוס ו יא) הבית הגדול רסיסים, בקיעות דקות, וכן (שבת פ ב) קנה המרסס: **ובארצכם לא תעשו.** דבר זה, לסרס שום בהמה וחיה ואפלו טמאה, לכך נאמר בארצכם, לרבות כל אשר בארצכם, שאי אפשר לומר לא נצטוו על הסרוס אלא בארץ, שהרי סרוס חובת הגוף הוא, וכל חובת הגוף נוהגת בין בארץ בין בחוצה לארץ:
@826 **ומיד בן נכר.** נכרי שהביא קרבן ביד כהן להקריבו לשמים לא תקריבו לו בעל מום. ואף על פי שלא נאסרו בעלי מומין לקרבן בני נח אלא אם כן מחסרי אבר, זאת נוהגת בבמה שבשדות, אבל על המזבח שבמשכן לא תקריבוה, אבל תמימה תקבלו מהם, לכך נאמר למעלה איש איש (לעיל פסוק יח) , לרבות את הנכרים שנודרים נדרים ונדבות כישראל: **משחתם.** חבולהון: **לא ירצו לכם.** לכפר עליכם:
@828 **כי יולד.** פרט ליוצא דופן:
@829 **אתו ואת בנו.** נוהג בנקבה, שאסור לשחוט האם והבן או הבת, ואינו נוהג בזכרים, ומתר לשחוט האב והבן או האב והבת: **אתו ואת בנו.** אף בנו ואותו במשמע:
@830 **לרצנכם תזבחו.** תחלת זביחתכם הזהרו שתהא לרצון לכם. ומהו הרצון, ביום ההוא יאכל. לא בא להזהיר אלא שתהא שחיטה על מנת כן, אל תשחטוהו על מנת לאכלו למחר, שאם תחשבו בו מחשבת פסול לא יהא לכם לרצון. דבר אחר לרצונכם, לדעתכם, מכאן למתעסק שפסול בשחיטת קדשים. ואף על פי שפרט בנאכלים לשני ימים, חזר ופרט בנאכלין ליום אחד שתהא זביחתן על מנת לאכלן בזמנן:
@831 **ביום ההוא יאכל.** לא בא להזהיר אלא שתהא שחיטה על מנת כן, שאם לקבוע לו זמן אכילה, כבר כתוב (ויקרא ז טו) ובשר זבח תודת שלמיו וגו' : **אני ה'.** דע מי גזר על הדבר ואל יקל בעיניך:
@832 **ושמרתם.** זו המשנה: **ועשיתם.** זה המעשה:
@833 **ולא תחללו.** לעבור על דברי מזידין. ממשמע שנאמר ולא תחללו, מה תלמוד לומר ונקדשתי, מסור עצמך וקדש שמי. יכול ביחיד, תלמוד לומר בתוך בני ישראל, וכשהוא מוסר עצמו, ימסור עצמו על מנת למות, שכל המוסר עצמו על מנת הנס, אין עושין לו נס, שכן מצינו בחנניה מישאל ועזריה שלא מסרו עצמן על מנת הנס, שנאמר (דניאל ג יח) והן לא, ידיע להוא לך מלכא די לאלהך לא איתנא פלחין וגו' , מציל ולא מציל, ידיע להוא לך וגו' :
@834 **המוציא אתכם.** על מנת כן: **אני ה'.** נאמן לשלם שכר:
@836 **דבר אל בני ישראל** וגו' **מועדי ה'.** עשה מועדות שיהיו ישראל מלמדין בהם, שמעברים את השנה על גליות שנעקרו ממקומם לעלות לרגל ועדין לא הגיעו לירושלים:
@837 **ששת ימים.** מה ענין שבת אצל מועדות, ללמדך שכל המחלל את המועדות מעלין עליו כאלו חלל את השבתות. וכל המקים את המועדות, מעלין עליו כאלו קים את השבתות:
@838 **אלה מועדי ה'.** למעלה מדבר בעבור שנה, וכאן מדבר בקדוש החדש:
@839 **בין הערבים.** משש שעות ולמעלה: **פסח לה'.** הקרבת קרבן ששמו פסח:
@842 **והקרבתם אשה** וגו' **.** הם המוספין האמורים בפרשת פנחס ולמה נאמרו כאן, לומר לך שאין המוספין מעכבין זה את זה: **והקרבתם אשה לה'.** מכל מקום, אם אין פרים הבא אילים, ואם אין פרים ואילים, הבא כבשים: **שבעת ימים.** כל מקום שנאמר שבעת שם דבר הוא, שבוע של ימים, שטיינ''א בלע''ז [קבוצה של שבעה ימים רצופים] , וכן כל לשון שמונת, ששת, חמשת, שלשת: **מלאכת עבדה.** אפלו מלאכות החשובות לכם עבודה וצורך, שיש חסרון כיס בבטלה שלהן, כגון דבר האבד. כך הבנתי מתורת כהנים, דקתני יכול אף חלו של מועד יהא אסור במלאכת עבודה וכו' :
@844 **ראשית קצירכם.** שתהא ראשונה לקציר: **עמר.** עשירית האיפה, כך היתה שמה, כמו (שמות טז יח) וימדו בעמר:
@845 **והניף.** כל תנופה מוליך ומביא, מעלה ומוריד. מוליך ומביא לעצור רוחות רעות, מעלה ומוריד לעצור טללים רעים: **לרצנכם.** אם תקריבו כמשפט זה, יהיו לרצון לכם: **ממחרת השבת.** ממחרת יום טוב הראשון של פסח, שאם אתה אומר שבת בראשית, אי אתה יודע איזהו:
@846 **ועשיתם:. כבש.** חובה לעמר הוא בא:
@847 **ומנחתו.** מנחת נסכיו: **שני עשרנים.** כפולה היתה: **ונסכה יין רביעית ההין.** אף על פי שמנחתו כפולה, אין נסכיו כפולים:
@848 **וקלי.** קמח עשוי מכרמל רך שמיבשין אותו בתנור: **וכרמל.** הן קליות שקורין גרניד''ש [שבלים] : **בכל משבתיכם.** נחלקו בו חכמי ישראל, יש שלמדו מכאן שהחדש נוהג בחוצה לארץ, ויש אומרים לא בא אלא ללמד שלא נצטוו על החדש אלא לאחר ירשה וישיבה, משכבשו וחלקו:
@849 **ממחרת השבת.** ממחרת יום טוב: **תמימת תהיינה.** מלמד שמתחיל ומונה מבערב, שאם לא כן אינן תמימות:
@850 **השבת השביעת.** כתרגומו שבועתא שביעתא: **עד ממחרת השבת השביעת תספרו.** ולא עד בכלל, והן ארבעים ותשעה יום: **חמשים יום והקרבתם מנחה חדשה לה'.** ביום החמשים תקריבוה. ואומר אני זהו מדרשו, אבל פשוטו עד ממחרת השבת השביעית, שהוא יום חמשים, תספרו. ומקרא מסורס הוא: **מנחה חדשה.** היא המנחה הראשונה שהובאה מן החדש. ואם תאמר, הרי קרבה מנחת העומר, אינה כשאר כל המנחות, שהיא באה מן השעורים:
@851 **ממושבתיכם.** ולא מחוצה לארץ: **לחם תנופה.** לחם תרומה המורם לשם גבוה, וזו היא המנחה החדשה האמורה למעלה: **בכורים.** ראשונה לכל המנחות, אף למנחת קנאות הבאה מן השעורים, לא תקרב מן החדש קודם לשתי הלחם:
@852 **על הלחם.** בגלל הלחם, חובה ללחם: **ומנחתם ונסכיהם.** כמשפט מנחה ונסכים המפורשים בכל בהמה בפרשת נסכים (במדבר טו ד. י) שלשה עשרונים לפר ושני עשרונים לאיל ועשרון לכבש, זו היא המנחה. והנסכים חצי ההין לפר ושלישית ההין לאיל ורביעית ההין לכבש:
@853 **ועשיתם שעיר עזים.** יכול שבעת הכבשים והשעיר האמורים כאן הם שבעת הכבשים והשעיר האמורים בחומש הפקודים, כשאתה מגיע אצל פרים ואילים אינן הם, אמור מעתה אלו לעצמן ואלו לעצמן, אלו קרבו בגלל הלחם ואלו למוספין:
@854 **והניף הכהן אתם תנופה.** מלמד שטעונין תנופה מחיים, יכול כלם, תלמוד לומר על שני כבשים: **קדש יהיו.** לפי ששלמי יחיד קדשים קלים, הזקק לומר בשלמי צבור שהם קדשי קדשים:
@856 **ובקצרכם.** חזר ושנה לעבור עליהם בשני לאוין. אמר רבי אבדימי ברבי יוסף מה ראה הכתוב לתנה באמצע הרגלים, פסח ועצרת מכאן וראש השנה ויום הכפורים והחג מכאן, ללמדך שכל הנותן לקט שכחה ופאה לעני כראוי, מעלין עליו כאלו בנה בית המקדש והקריב קרבנותיו בתוכו: **תעזב.** הנח לפניהם והם ילקטו, ואין לך לסיע לאחד מהם: **אני ה' אלהיכם.** נאמן לשלם שכר:
@858 **זכרון תרועה.** זכרון פסוקי זכרונות ופסוקי שופרות, לזכור לכם עקידת יצחק שקרב תחתיו איל:
@859 **והקרבתם אשה.** המוספים האמורים בחומש הפקודים:
@861 **אך.** כל אכין ורקין שבתורה מיעוטין, מכפר הוא לשבים ואינו מכפר על שאינם שבים:
@864 **והאבדתי.** לפי שהוא אומר כרת בכל מקום ואיני יודע מה הוא, כשהוא אומר והאבדתי, למד על הכרת שאינו אלא אבדן:
@865 **כל מלאכה** וגו' **.** לעבור עליו בלאוין הרבה, או להזהיר על מלאכת לילה כמלאכת יום:
@869 **מקרא קדש.** קדשהו בכסות נקיה ובתפלה, ובשאר ימים טובים במאכל ובמשתה ובכסות נקיה ובתפלה:
@870 **עצרת הוא.** עצרתי אתכם אצלי כמלך שזמן את בניו לסעודה לכך וכך ימים, כיון שהגיע זמנן להפטר אמר בני בבקשה מכם, עכבו עמי עוד יום אחד, קשה עלי פרידתכם: **כל מלאכת עבדה.** אפלו מלאכה שהיא עבודה לכם, שאם לא תעשוה יש חסרון כיס בדבר: **לא תעשו.** יכול אף חלו של מועד יהא אסור במלאכת עבודה, תלמוד לומר היא:
@871 **עלה ומנחה.** מנחת נסכים הקרבה עם העולה: **דבר יום ביומו.** חק הקצוב בחומש הפקודים: **דבר יום ביומו.** הא אם עבר יומו בטל קרבנו:
@873 **אך בחמשה עשר יום:. תחגו.** קרבן שלמים לחגיגה. יכול תדחה את השבת, תלמוד לומר אך, הואיל ויש לה תשלומין כל שבעה: **באספכם את תבואת הארץ.** שיהא חדש שביעי זה בא בזמן אסיפה, מכאן שנצטוו לעבר את השנים, שאם אין העבור, פעמים שהוא בא באמצע הקיץ או החורף: **תחגו.** שלמי חגיגה: **שבעת ימים.** אם לא הביא בזה יביא בזה. יכול יהא מביאן כל שבעה, תלמוד לומר וחגתם אתו, יום אחד במשמע, ולא יותר. ולמה נאמר שבעה, לתשלומין:
@874 **פרי עץ הדר.** עץ שטעם עצו ופריו שוה: **הדר.** הדר באילנו משנה לשנה, וזהו אתרוג: **כפת תמרים.** חסר וי''ו, למד שאינה אלא אחת: **וענף עץ עבת.** שענפיו קלועים כעבותות וכחבלים, וזהו הדס העשוי כמין קליעה:
@876 **האזרח.** זה אזרח: **בישראל.** לרבות את הגרים:
@877 **כי בסכות הושבתי.** ענני כבוד:
@880 **צו את בני ישראל.** זו פרשת מצות הנרות. ופרשת ואתה תצוה לא נאמרה אלא על סדר מלאכת המשכן לפרש צורך המנורה. וכן משמע, ואתה סופך לצוות את בני ישראל על כך: **שמן זית זך.** שלשה שמנים יוצאים מן הזית, הראשון קרוי זך, והן מפורשים במנחות (פט א) ובתורת כהנים: **תמיד.** מלילה ללילה, כמו עולת תמיד שאינה אלא מיום ליום:
@881 **לפרכת העדת.** שלפני הארון, שהוא קרוי עדות. ורבותינו דרשו על נר מערבי, שהוא עדות לכל באי עולם שהשכינה שורה בישראל, שנותן בה שמן כמדת חברותיה וממנה היה מתחיל ובה היה מסים: **יערך אתו אהרן מערב עד בקר.** יערוך אותו עריכה הראויה למדת כל הלילה, ושערו חכמים חצי לוג לכל נר ונר, והן כדאי אף ללילי תקופת טבת, ומדה זו הקבעה להם:
@882 **המנרה הטהרה.** שהיא זהב טהור. דבר אחר על טהרה של מנורה, שמטהרה ומדשנה תחלה מן האפר:
@884 **שש המערכת.** שש חלות המערכה האחת: **השלחן הטהר.** של זהב טהור. דבר אחר על טהרו של שלחן, שלא יהיו הסניפין מגביהין את הלחם מעל גבי השלחן:
@885 **ונתת על המערכת.** על כל אחת משתי המערכות היו שני בזכי לבונה, מלא קומץ לכל אחת: **והיתה.** הלבונה הזאת: **ללחם לאזכרה.** שאין מן הלחם לגבוה כלום, אלא הלבונה נקטרת כשמסלקין אותו בכל שבת ושבת. והיא לזכרון ללחם, שעל ידה הוא נזכר למעלה, כקומץ שהוא אזכרה למנחה:
@887 **והיתה.** המנחה הזאת, שכל דבר הבא מן התבואה בכלל מנחה הוא: **ואכלהו.** מוסב על הלחם, שהוא לשון זכר:
@888 **ויצא בן אשה ישראלית.** מהיכן יצא, רבי לוי אומר מעולמו יצא. רבי ברכיה אומר מפרשה שלמעלה יצא. לגלג ואמר ביום השבת יערכנו, דרך המלך לאכול פת חמה בכל יום, או שמא פת צוננת של תשעה ימים, בתמיהה. ומתניתא אמרה מבית דינו של משה יצא מחיב. בא לטע אהלו בתוך מחנה דן, אמרו לו מה טיבך לכאן, אמר להם מבני דן אני. אמרו לו (במדבר ב) איש על דגלו באתת לבית אבותם כתיב. נכנס לבית דינו של משה ויצא מחיב, עמד וגדף: **בן איש מצרי.** הוא המצרי שהרגו משה: **בתוך בני ישראל.** מלמד שנתגיר: **וינצו במחנה.** על עסקי המחנה: **ואיש הישראלי.** זה שכנגדו, שמחה בו מטע אהלו:
@889 **ויקב.** כתרגומו ופרש, שנקב שם המיוחד וגדף, והוא שם המפורש ששמע מסיני: **ושם אמו שלמית בת דברי.** שבחן של ישראל שפרסמה הכתוב לזו, לומר, שהיא לבדה היתה זונה: **שלמית.** דהות פטפטה שלם עלך, שלם עלך, שלם עליכון, מפטפטת בדברים שואלת בשלום הכל: **בת דברי.** דברנית היתה מדברת עם כל אדם, לפיכך קלקלה: **למטה דן.** מגיד שהרשע גורם גנאי לו גנאי לאביו גנאי לשבטו, כיוצא בו (שמות לא ו) אהליאב בן אחיסמך למטה דן, שבח לו שבח לאביו שבח לשבטו:
@890 **ויניחהו.** לבדו, ולא הניחו מקושש עמו, ששניהם היו בפרק אחד. ויודעים היו שהמקושש במיתה, שנאמר (שמות לא יד) מחלליה מות יומת אבל לא פרש להם באיזו מיתה, לכך נאמר (במדבר טו לד) כי לא פרש מה יעשה לו. אבל במקלל הוא אומר לפרוש להם, שלא היו יודעים אם חיב מיתה אם לאו:
@892 **השמעים.** אלו העדים: **כל.** להביא את הדינים: **את ידיהם.** אומרים לו דמך בראשך ואין אנו נענשים במיתתך שאתה גרמת לך: **כל העדה.** במעמד כל העדה. מכאן ששלוחו שלאדם כמותו:
@893 **ונשא חטאו.** בכרת, כשאין התראה:
@894 **ונקב שם.** אינו חיב עד שיפרש את השם, ולא המקלל בכנוי: **ונקב.** לשון קללה, כמו (במדבר כג ח) מה אקב:
@895 **ואיש כי יכה.** לפי שנאמר (שמות כא יב) מכה איש ומת, אין לי אלא שהרג את האיש, אשה וקטן מנין, תלמוד לומר כל נפש אדם:
@898 **כן ינתן בו.** פרשו רבותינו, שאינו נתינת מום ממש אלא תשלומי ממון, שמין אותו כעבד, לכך כתוב בו לשון נתינה, דבר הנתון מיד ליד:
@899 **ומכה בהמה ישלמנה.** למעלה דבר בהורג בהמה, וכאן דבר בעושה בה חבורה: **ומכה אדם יומת.** אפלו לא הרגו אלא עשה בו חבורה, שלא נאמר כאן נפש ובמכה אביו ואמו דבר הכתוב, ובא להקישו למכה בהמה מה מכה בהמה מחיים, אף מכה אביו ואמו מחיים, פרט למכה לאחר מיתה, לפי שמצינו שהמקללו לאחר מיתה חיב, הצרך לומר במכה שפטור. ומה בבהמה בחבלה, שאם אין חבלה אין תשלומין, אף מכה אביו ואמו אינו חיב עד שיעשה בהם חבורה:
@900 **אני ה' אלהיכם.** אלהי כלכם, כשם שאני מיחד שמי עליכם כך אני מיחד שמי על הגרים:
@901 **ובני ישראל עשו.** כל המצוה האמורה בסקילה במקום אחר דחיה, רגימה ותליה:
@902 **והכהנים הלוים.** משבט לוי: **בני צדוק.** לפי שהיה כ"ג ששימש ראשון במקדש בימי שלמה נקראו על שמו: **בתעות.** קנאינשר"ר בלע"ז:
@904 **אל שערי החצר הפנימית.** לפני ולפנים בי"ה: **ולא יעלה עליהם צמר.** תכלת שהיה במעיל ובאבנט לא ילבשנו בי"ה בעבודת פנים: **וביתה.** ולפנים:
@905 **פארי.** קאפייל"ש בלע"ז: **לא יחגרו ביזע.** שנינו בברייתא אין חוגרין במקום שמזיעין לא למעלה מאציליהם ולא למטה ממתניהם שהוא מקום זיעה אנלאשויי"רא בלע"ז ל"א אסרה התורה לכהנים מלבושי הצמר כי הצמר מזיע הגוף ומזיע את הבשר, ( סא"א ):
@906 **אל החצר החיצונה.** לפי שהיה מדבר בהיכל לפני ולפנים וקראם חצר הפנימית ואצלם יש לו לקרות עזרת ישראל חצר החיצונה לכך הוצרך לכפול שתי פעמים לומר שעל עזרת נשים הוא אומר מקום שכל ישראל נכנסין: **והניחו אותם בלשכות הקודש.** כמו שאמר מרע"ה ( ויקרא ט"ז ) ופשט את בגדי הבד אשר לבש והניחם שם: **ולא יקדשו את העם.** ת"י ולא יתערבון עם עמא בלבושיהון כלומר לא יגעו אל העם בבגדיהם הקדושים שאין בגדי חול טהורין אצל בגדי הקודש:
@907 **וראשם לא יגלחו.** להעביר את כל השער: **ופרע לא ישלחו.** גידול שער לא ירבו: **כסום יכסמו.** ככוסמת הזו שסדורין בשבולת ראשו של זה לצד עיקרו של זה כך שמעתי משמו של רבי מנחם זצ"ל ויתכן לפרשו לשון מדת דבר השוה לא גזיזת ראש ולא גדול שער אלא במדה שוה אמולי"ר בלע"ז:
@908 **בבואם אל החצר הפנימית.** אל ההיכל:
@909 **כי אם בתולות.** יקחו. הכהנים הגדולים אבל יש מן הכהנים אשר יקחו את האלמנה כגון הדיוטין וזהו מכהן יקחו יש מן הכהן שמותרין באלמנה, מצאתי: **אשר תהיה אלמנה.** גמורה פרט לגרושה וחלוצה אע"פ שפנויה היא אסורה אף להדיוט:
@913 **ואחרי טהרתו.** אחר פרישתו מן המת כך שנויה במ"ק:
@914 **וביום בואו.** תחילה אל הקדש להתחנך לעבודה יקריב חטאתו זו עשירית האיפה שלו כך שנויה במ"ק שהכהן הדיוט טעון עשירית האיפה ביום חינוכו כענין שנאמר ( שם ו' ) זה קרבן אהרן ובניו וגו' וכמו שמפרש במסכת מנחות:
@915 **והיתה להם.** הכהונה לנחלה:
@916 **חרם.** לשון קדש וכן כל לשון חרמה שהוא על הקדש:
@917 **להניח.** אפושי"ר בלע"ז כמו ( שמות ח' ) וינח בכל גבול מצרים:
@918 **כל נבלה וטרפה וגו'.** לפי שהותרה להם מליקת חטאת העוף שהיא נבלה וטריפה הוצרך להזהירם על שאר נבלות וטריפות כך פירשו רבותינו:
@919 **בהר סיני.** מה ענין שמטה אצל הר סיני, והלא כל המצות נאמרו מסיני, אלא מה שמטה נאמרו כללותיה ופרטותיה ודקדוקיה מסיני, אף כלן נאמרו כללותיהן ודקדוקיהן מסיני, כך שנויה בתורת כהנים. ונראה לי שכך פרושה לפי שלא מצינו שמטת קרקעות שנשנית בערבות מואב במשנה תורה, למדנו שכללותיה ופרטותיה כלן נאמרו מסיני, ובא הכתוב ולמד כאן על כל דבור שנדבר למשה שמסיני היו כלם כללותיהן ודקדוקיהן, וחזרו ונשנו בערבות מואב:
@920 **שבת לה'.** לשם ה', כשם שנאמר בשבת בראשית:
@922 **יהיה לארץ.** לשדות ולכרמים: **לא תזמר.** שקוצצין זמורותיה. ותרגומו לא תכסח, ודומה לו (ישעיה לג יב) קוצים כסוחים, (תהלים פ יז) שרפה באש כסוחה:
@923 **את ספיח קצירך.** אפלו לא זרעתה והיא צמחה מן הזרע שנפל בה בעת הקציר, הוא קרוי ספיח: **לא תקצור.** להיות מחזיק בו כשאר קציר, אלא הפקר יהיה לכל: **נזירך.** שהנזרת והפרשת בני אדם מהם ולא הפקרתם: **לא תבצר.** אותם אינך בוצר, אלא מן המפקר:
@924 **והיתה שבת הארץ** וגו' **.** אף על פי שאסרתים עליך, לא באכילה ולא בהנאה אסרתים, אלא שלא תנהוג בהם כבעל הבית, אלא הכל יהיו שוים בה, אתה ושכירך ותושבך: **שבת הארץ לכם לאכלה.** מן השבות אתה אוכל, ואי אתה אוכל מן השמור: **לך ולעבדך ולאמתך.** לפי שנאמר (שמות כג יא) ואכלו אביוני עמך, יכול יהיו אסורים באכילה לעשירים, תלמוד לומר לך ולעבדך ולאמתך, הרי בעלים ועבדים ושפחות אמורים כאן: **ולשכירך ולתושבך.** אף הגוים:
@925 **ולבהמתך ולחיה.** אם חיה אוכלת בהמה לא כל שכן, שמזונותיה עליך, מה תלמוד לומר ולבהמתך, מקיש בהמה לחיה, כל זמן שחיה אוכלת מן השדה האכל לבהמתך מן הבית, כלה לחיה מן השדה כלה לבהמתך מן הבית:
@926 **שבתת שנים.** שמטות שנים. יכול יעשה שבע שנים רצופות שמטה ויעשה יובל אחריהם, תלמוד לומר שבע שנים שבע פעמים, הוי אומר כל שמטה ושמטה בזמנה: **והיו לך ימי שבע** וגו' **.** מגיד לך שאף על פי שלא עשית שמטות עשה יובל לסוף ארבעים ותשע שנה. ופשוטו של מקרא יעלה לך חשבון שנות השמטות למספר ארבעים ותשע:
@927 **והעברת.** לשון (שמות לו ו) ויעבירו קול במחנה, לשון הכרזה: **ביום הכפורים.** ממשמע שנאמר ביום הכפורים איני יודע שהוא בעשור לחדש, אם כן למה נאמר בעשור לחדש, אלא לומר לך תקיעת עשור לחדש דוחה שבת בכל ארצכם, ואין תקיעת ראש השנה דוחה שבת בכל ארצכם, אלא בבית דין בלבד:
@928 **וקדשתם.** בכניסתה מקדשין אותה בבית דין ואומרים מקדשת השנה: **וקראתם דרור.** לעבדים, בין נרצע, בין שלא כלו לו שש שנים משנמכר. אמר ר' יהודה מהו לשון דרור, כמדייר בי דירא ומסחר בכל מדינה וכו' , שדר בכל מקום שהוא רוצה ואינו ברשות אחרים: **יובל הוא.** שנה זאת מבדלת משאר שנים בנקיבת שם לה לבדה. ומה שמה, יובל שמה, על שם תקיעת שופר: **ושבתם איש אל אחזתו.** שהשדות חוזרות לבעליהן: **ואיש אל משפחתו תשבו.** לרבות את הנרצע:
@929 **יובל הוא שנת החמשים שנה.** מה תלמוד לומר, לפי שנאמר וקדשתם וגו' , כדאיתא בראש השנה (ח ב) ובתורת כהנים: **את נזריה.** את הענבים המשמרים. אבל בוצר אתה מן המפקרים, כשם שנאמר בשביעית כך נאמר ביובל, נמצאו שתי שנים קדושות סמוכות זו לזו, שנת ארבעים ותשע שמטה ושנת החמשים יובל:
@930 **קדש תהיה לכם.** תופסת דמיה כהקדש. יכול תצא היא לחלין, תלמוד לומר תהיה, בהויתה תהא: **מן השדה תאכלו.** על ידי השדה אתה אוכל מן הבית, שאם כלה לחיה מן השדה אתה צריך לבער מן הבית, כשם שנאמר בשביעית כך נאמר ביובל:
@931 **תשבו איש אל אחזתו.** והרי כבר נאמר (פסוק י) ושבתם איש אל אחזתו, אלא לרבות המוכר שדהו ועמד בנו וגאלה שחוזרת לאביו ביובל:
@932 **וכי תמכרו** וגו' **.** לפי פשוטו כמשמעו. ועוד יש דרשה מנין כשאתה מוכר, מכור לישראל חברך, תלמוד לומר וכי תמכרו ממכר לעמיתך מכור, ומנין שאם באת לקנות קנה מישראל חברך, תלמוד לומר או קנה מיד עמיתך: **אל תונו.** זו אונאת ממון:
@933 **במספר שנים אחר היובל תקנה.** זהו פשוטו לישב מקרא על אפניו על האונאה בא להזהיר, כשתמכור או תקנה קרקע דע כמה שנים יש עד היובל. ולפי השנים ותבואות השדה שהיא ראויה לעשות ימכור המוכר ויקנה הקונה, שהרי סופו להחזירה לו בשנת היובל. ואם יש שנים מועטות וזה מוכרה בדמים יקרים הרי נתאנה לוקח, ואם יש שנים מרבות ואכל ממנה תבואות הרבה ולקחה בדמים מועטים הרי נתאנה מוכר, לפיכך צריך לקנותה לפי הזמן. וזהו שנאמר במספר שני תבואות ימכר לך, לפי מנין שני התבואות שתהא עומדת ביד הלוקח תמכור לו. ורבותינו דרשו מכאן, שהמוכר שדהו אינו רשאי לגאול פחות משתי שנים, שתעמוד שתי שנים ביד הלוקח מיום ליום, ואפלו יש שלש תבואות באותן שתי שנים, כגון שמכרה לו בקמותיה. ו''שני'' אינו יוצא מפשוטו, כלומר מספר שנים של תבואות, ולא של שדפון, ומעוט שנים שנים:
@934 **תרבה מקנתו.** תמכרנה ביקר: **תמעיט מקנתו.** תמעיט בדמיה:
@935 **ולא תונו איש את עמיתו.** כאן הזהיר על אונאת דברים, שלא יקניט איש את חברו לא ישיאנו עצה שאינה הוגנת לו לפי דרכו והנאתו של יועץ. ואם תאמר, מי יודע אם נתכונתי לרעה, לכך נאמר ויראת מאלהיך, היודע מחשבות הוא יודע. כל דבר המסור ללב, שאין מכיר אלא מי שהמחשבה בלבו, נאמר בו ויראת מאלהיך:
@936 **וישבתם על הארץ לבטח.** שבעון שמטה ישראל גולים, שנאמר (ויקרא כו לד) אז תרצה הארץ את שבתתיה והרצת את שבתתיה, ושבעים שנה שלגלות בבל, כנגד שבעים שמטות שבטלו, היו:
@937 **ונתנה הארץ** וגו' **וישבתם לבטח עליה.** שלא תדאגו משנת בצורת: **ואכלתם לשבע.** אף בתוך המעים תהא בו ברכה:
@938 **ולא נאסף.** אל הבית: **את תבואתנו.** כגון יין ופרות האילן וספיחין הבאים מאליהם:
@939 **לשלש השנים.** למקצת הששית מניסן ועד ראש השנה, ולשביעית ולשמינית, שיזרעו בשמינית במרחשון ויקצרו בניסן:
@940 **עד השנה התשיעת.** עד חג הסכות של תשיעית, שהיא עת בא תבואתה של שמינית לתוך הבית, שכל ימות הקיץ היו בשדה בגרנות, ובתשרי הוא עת האסיף לבית. ופעמים שהיתה צריכה לעשות לארבע שנים, בששית שלפני השמטה השביעית, שהן בטלין מעבודת קרקע שתי שנים רצופות השביעית והיובל, ומקרא זה נאמר בשאר השמטות כלן:
@941 **והארץ לא תמכר.** לתן לאו על חזרת שדות לבעלים ביובל, שלא יהא הלוקח כובשה: **לצמתת.** לפסיקה, למכירה פסוקה עולמית: **כי לי הארץ.** אל תרע עינך בה שאינה שלך:
@942 **ובכל ארץ אחזתכם.** לרבות בתים ועבד עברי, ודבר זה מפורש בקדושין בפרק ראשון (דף כא א) . ולפי פשוטו סמוך לפרשה שלאחריו, שהמוכר אחזתו רשאי לגאלה לאחר שתי שנים או הוא או קרובו, ואין הלוקח יכול לעכב:
@943 **כי ימוך אחיך ומכר.** מלמד שאין אדם רשאי למכור שדהו אלא מחמת דחק עוני: **מאחזתו.** ולא כלה, למד דרך ארץ שישיר שדה לעצמו: **וגאל את ממכר אחיו.** ואין הלוקח יכול לעכב:
@944 **ואיש כי לא יהיה לו גאל.** וכי יש לך אדם בישראל שאין לו גואלים, אלא גואל שיוכל לגאול ממכרו:
@945 **וחשב את שני ממכרו.** כמה שנים היו עד היובל, כך וכך. ובכמה מכרתיה לך בכך וכך. עתיד היית להחזירה ביובל, נמצאת קונה מספר התבואות כפי חשבון של כל שנה. אכלת אותה שלש שנים או ארבע הוצא את דמיהן מן החשבון וטול את השאר, וזהו והשיב את העדף. בדמי המקח על האכילה שאכלה, ויתנם ללוקח: **לאיש אשר מכר לו.** המוכר הזה שבא לגאלה:
@946 **די השיב לו.** מכאן שאינו גואל לחצאין: **עד שנת היובל.** שלא יכנס לתוך אותה שנה כלום, שהיובל משמט בתחלתו:
@947 **בית מושב עיר חומה.** בית בתוך עיר המקפת חומה מימות יהושע בן נון: **והיתה גאלתו.** לפי שנאמר בשדה שיכול לגאלה משתי שנים ואלך כל זמן שירצה ובתוך שתי שנים הראשונים אינו יכול לגאלה, הצרך לפרש בזה שהוא חלוף, שאם רצה לגאול בשנה ראשונה גואלה, ולאחר מכאן אינו גואלה: **והיתה גאלתו.** של בית: **ימים.** ימי שנה שלמה קרויים ימים, וכן (בראשית כד נה) תשב הנערה אתנו ימים:
@948 **וקם הבית** וגו' **לצמיתת.** יצא מכחו של מוכר ועומד בכחו של קונה: **אשר לא חמה.** לו קרינן, אמרו רבותינו זכרונם לברכה אף על פי שאין לו עכשיו, הואיל והיתה לו קודם לכן. ועיר נקבה היא והצרך לכתוב לה, אלא מתוך שצריך לכתוב לא בפנים, תקנו לו במסרת, זה נופל על זה: **לא יצא ביבל.** אמר רב ספרא אם פגע בו יובל בתוך שנתו לא יצא:
@949 **ובתי החצרים.** כתרגומו פצחין, עירות פתוחות מאין חומה. ויש הרבה בספר יהושע (יהושע יג כח) הערים וחצריהם, (בראשית כה טז) בחצריהם ובטירותם: **על שדה הארץ יחשב.** הרי הן כשדות הנגאלים עד היובל ויוצאין ביובל לבעלים אם לא נגאלו: **גאלה תהיה לו.** מיד אם ירצה. ובזה יפה כחו מכח שדות, שהשדות אין נגאלות עד שתי שנים: **וביבל יצא.** בחנם:
@950 **וערי הלוים.** ארבעים ושמנה עיר שנתנו להם: **גאלת עולם.** גואל מיד אפלו לפני שתי שנים, אם מכרו שדה משדותיהם הנתונות להם באלפים אמה סביבות הערים, או אם מכרו בית בעיר חומה, גואלין לעולם, ואינו חלוט לסוף שנה:
@951 **ואשר יגאל מן הלוים.** ואם יקנה בית או עיר מהם: **ויצא ביבל.** אותו ממכר של בית או של עיר וישוב ללוי שמכרו, ולא יהיה חלוט כשאר בתי ערי חומה של ישראל. וגאלה זו לשון מכירה. דבר אחר לפי שנאמר (פסוק לב) , גאלת עולם תהיה ללוים, יכול לא דבר הכתוב אלא בלוקח ישראל שקנה בית בערי הלוים, אבל לוי שקנה מלוי יהיה חלוט, תלמוד לומר ואשר יגאל מן הלוים, אף [לוי] הגואל מיד לוי גואל גאלת עולם: **ויצא ממכר בית.** הרי זו מצוה אחרת, ואם לא גאלה יוצאה ביובל, ואינו נחלט לסוף שנה כבית של ישראל: **כי בתי ערי הלוים הוא אחזתם.** לא היה להם נחלת שדות וכרמים אלא ערים לשבת ומגרשיהם, לפיכך הם להם במקום שדות, ויש להם גאלה כשדות, כדי שלא תפקע נחלתם מהם:
@952 **ושדה מגרש עריהם לא ימכר.** מכר גזבר, שאם הקדיש בן לוי את שדהו ולא גאלה ומכרה גזבר, אינה יוצאה לכהנים ביובל, כמו שנאמר בישראל (ויק' כז) ואם מכר את השדה לאיש אחר לא יגאל עוד, אבל בן לוי גואל לעולם:
@953 **והחזקת בו.** אל תניחהו שירד ויפול ויהיה קשה להקימו, אלא חזקהו משעת מוטת היד. למה זה דומה, למשאוי שעל החמור, עודהו על החמור אחד תופס בו ומעמידו, נפל לארץ, חמשה אין מעמידין אותו: **גר ותושב.** אף אם הוא גר או תושב, ואיזהו תושב, כל שקבל עליו שלא לעבוד עבודה זרה, ואוכל נבלות:
@954 **נשך ותרבית.** חד שוינהו רבנן, ולעבור עליו בשני לאוין: **ויראת מאלהיך.** לפי שדעתו של אדם נמשכת אחר הרבית וקשה לפרוש המנו ומורה לעצמו התר בשביל מעותיו שהיו בטלות אצלו, הצרך לומר ויראת מאלהיך. או התולה מעותיו בנכרי, כדי להלוותם לישראל ברבית, הרי זה דבר המסור ללבו של אדם ומחשבתו, לכך הצרך לומר ויראת מאלהיך:
@956 **אשר הוצאתי** וגו' **.** והבחנתי בין בכור לשאינו בכור, אף אני יודע ונפרע מן המלוה מעות לישראל ברבית ואומר של נכרי הם. דבר אחר אשר הוצאתי אתכם מארץ מצרים על מנת שתקבלו עליכם מצותי אפלו הן כבדות עליכם: **לתת לכם את ארץ כנען.** בשכר שתקבלו מצותי: **להיות לכם לאלהים.** שכל הדר בארץ ישראל אני לו לאלהים, וכל היוצא ממנה כעובד עבודה זרה:
@957 **עבדת עבד.** עבודה של גנאי, שיהא נכר בה כעבד, שלא יוליך כליו אחריו לבית המרחץ ולא ינעול לו מנעליו:
@958 **כשכיר כתושב.** עבודת קרקע ומלאכת אמנות כשאר שכירים התנהג בו: **עד שנת היבל.** אם פגע בו יובל לפני שש שנים, היובל מוציאו:
@959 **הוא ובניו עמו.** אמר רבי שמעון אם הוא נמכר בניו מי מכרן, אלא מכאן שרבו חיב במזונות בניו: **ואל אחזת אבתיו.** אל כבוד אבותיו, ואין לזלזלו בכך: **אחזת.** חזקת:
@960 **כי עבדי הם.** שטרי קודם: **לא ימכרו ממכרת עבד.** בהכרזה כאן יש עבד למכור, ולא יעמידנו על אבן הלקח:
@961 **לא תרדה בו בפרך.** מלאכה שלא לצורך, כדי לענותו. אל תאמר לו החם לי את הכוס הזה, והוא אינו צריך, עדור תחת הגפן עד שאבא. שמא תאמר אין מכיר בדבר אם לצורך אם לאו, ואומר אני לו שהוא לצורך, הרי הדבר הזה מסור ללב, לכך נאמר ויראת:
@962 **ועבדך ואמתך אשר יהיו לך.** אם תאמר אם כן במה אשתמש. בעבדי איני מושל, באמות איני נוחל, שהרי הזהרתני (דברים כ טז) לא תחיה כל נשמה, אלא מי ישמשני: **מאת הגוים.** הם יהיו לך לעבדים: **אשר סביבתיכם.** ולא שבתוך גבול ארצכם, שהרי בהם אמרתי לא תחיה כל נשמה:
@963 **וגם מבני התושבים.** שבאו מסביבותיכם לשא נשים בארצכם וילדו להם, הבן הולך אחר האב, ואינו בכלל לא תחיה, אלא אתה מתר לקנותו כעבד: **מהם תקנו.** אותם תקנו:
@964 **והתנחלתם אתם לבניכם.** החזיקו בהם לנחלה לצורך בניכם אחריכם. ולא יתכן לפרש הנחילום לבניכם, שאם כן היה לו לכתוב והנחלתם אותם לבניכם. והתנחלתם, כמו והתחזקתם: **איש באחיו.** להביא נשיא בעמיו ומלך במשרתיו שלא לרדות בפרך:
@965 **יד גר ותושב.** גר והוא תושב, כתרגומו ערל תותב, וסופו מוכיח ונמכר לגר תושב: **וכי תשיג יד גר ותושב עמך.** מי גרם לו שיעשיר, דבוקו עמך: **ומך אחיך עמו.** מי גרם לו שימוך, דבוקו עמו, על ידי שלמד ממעשיו: **משפחת גר.** זהו הגוי. כשהוא אומר לעקר זה הנמכר לעבודה זרה עצמה להיות לה שמש, ולא לאלהות, אלא לחטוב עצים ולשאוב מים:
@966 **גאלה תהיה לו.** מיד, אל תניחהו שיטמע: **עד שנת היובל.** שהרי כל עצמו לא קנאו אלא לעבדו עד היובל, שהרי ביובל יצא, כמו שנאמר למטה (פסוק נד) ויצא בשנת היובל. ובגוי שתחת ידך הכתוב מדבר ואף על פי כן לא תבא עליו בעקיפין, מפני חלול השם, אלא כשבא לגאל ידקדק בחשבון לפי המגיע בכל שנה ושנה ינכה לו הגוי מן דמיו, אם היו עשרים שנה משנמכר עד היובל וקנאו בעשרים מנה, נמצא שקנה הגוי עבודת שנה במנה, ואם שהה זה אצלו חמש שנים ובא לגאל, ינכה לו חמשה מנים ויתן לו העבד חמש עשרה מנים, וזהו: **והיה כסף ממכרו במספר שנים' כימי שכיר יהיה עמו.** חשבון המגיע לכל שנה ושנה יחשב כאלו נשכר עמו כל שנה במנה וינכה לו:
@969 **אם עוד רבות בשנים.** עד היובל: **לפיהן.** הכל כמו שפרשתי:
@971 **לא ירדנו בפרך לעיניך.** כלומר ואתה רואה:
@972 **ואם לא יגאל באלה.** באלה הוא נגאל, ואינו נגאל בשש: **הוא ובניו עמו.** הנכרי חיב במזונות בניו כישראל:
@973 **כי לי בני ישראל עבדים.** שטרי קודם: **אני ה' אלהיכם.** כל המשעבדן מלמטה כאלו משעבדן מלמעלה:
@974 **לא תעשו לכם אלילם.** כנגד זה הנמכר לגוי, שלא יאמר הואיל ורבי מגלה עריות אף אני כמותו, הואיל ורבי עובד עבודה זרה אף אני כמותו, הואיל ורבי מחלל שבת אף אני כמותו, לכך נאמרו מקראות הללו. ואף הפרשיות הללו נאמרו על הסדר, בתחלה הזהיר על השביעית, ואם חמד ממון ונחשד על השביעית סופו למכור מטלטליו, לכך סמך לה וכי תמכרו ממכר (ויק' כה יד) , מה כתיב ביה או קנה מיד עמיתך (שם) , דבר הנקנה מיד ליד. לא חזר בו, סוף מוכר אחזתו. לא חזר בו, סוף מוכר את ביתו. לא חזר בו, סוף לוה ברבית. כל אלו האחרונות קשות מן הראשונות. לא חזר בו, סוף מוכר את עצמו. לא חזר בו, לא דיו לישראל אלא אפלו לגוי: **ואבן משכית.** לשון כסוי, כמו (שמות לג כב) ושכתי כפי, שמכסין הקרקע ברצפת אבנים: **להשתחות עליה.** אפלו לשמים, לפי שהשתחואה בפשוט ידים ורגלים היא, ואסרה תורה לעשות כן חוץ מן המקדש:
@975 **אני ה'.** נאמן לשלם שכר:
@976 **ויאמר ירמיהו וגו'.** לא לצדקיהו אמר כן אלא פי' הכתוב למה כלאו וחוזר לדבורו הראשון לפרש מה הדבר אשר הי' אל ירמיהו:
@977 **בא אליך.** על פי הדבור:
@981 **את ספר המקנה.** שטר המכירה: **את החתום וגו'.** עם חתימתו כשהוא חתום כדת וחוק: **ואת הגלוי.** שהוחזק בבית דין על פי עדיו וכתבו וחתמו הדיינין אשרתא דדייני הוא קיום השטרות לעשות הדבר גלוי ומפורסם פן ימותו העדים ורבותינו פירשו לענין גט פשוט ומקושר בבבא בתרא:
@982 **לעיני חנמאל דודי.** ועד עכשיו קראו בן דודי שמא שנים היו ואם אין זאת לא ידעתי מהו ויש נוטים לומר דודו ובן דודו היה חנמאל לירמיה כגון ראובן נשא את בת שמעון אחיו וילדה לו נמואל וכבר הוליד שמעון ימין הרי ימין דודו לנמואל שבן אחי אמו הוא וגם בן דודו שהוא בן שמעון אחי אביו של נמואל ואינה היא המדה שלא מצינו בכל המקרא אח האם קרוי דוד:
@984 **כה אמר וגו'.** אל תאמר לחנם אני מצניעם שהרי הכל גולים:
@985 **כי כה אמר ה'.** סופן לקנות בתים:
@987 **לא יפלא.** לא יכחד ויודע אתה שסופנו לגלות ולמה אמרת לי לקנות שדה:
@988 **ומשלם עון אבות אל חיק.** הדור הזה ההולכים אחרי אבותיהם בדרך הרעה: **הגדול הגבור.** ולא אמר והנורא אמר עובדי אלילים מרקדין בהיכלו איה נוראותיו במסכת יומא:
@990 **ובאדם.** בשאר אנשים, ד"א אותות שהיו שקולין לישראל ולמצרים כיצד ויהי הענן והחשך ויאר הלילה ( שמות יד ) אותו מזל ששימש חשך למצרים שימש אור לישראל מדרש אגדה:
@993 **ותקרא אותס.** הקרית אותם לשון מקרה:
@994 **ואשר דברת.** רעה עליה היה ובא:
@995 **והעיר נתנה.** ולמה לי שדה:
@997 **הממני יפלא.** וכי העתידות עלומות ממני:
@998 **אם בחקתי תלכו.** יכול זה קיום המצות, כשהוא אומר ואת מצותי תשמרו, הרי קיום המצות אמור, הא מה אני מקים אם בחקתי תלכו, שתהיו עמלים בתורה: **ואת מצותי תשמרו.** הוו עמלים בתורה על מנת לשמור ולקים, כמו שנאמר (דברים ה א) ולמדתם אתם ושמרתם לעשותם:
@999 **בעתם.** בשעה שאין דרך בני אדם לצאת, כגון בלילי שבתות ובלילי רביעיות: **ועץ השדה.** הן אילני סרק, ועתידין לעשות פרות:
@1000 **והשיג לכם דיש את בציר.** שיהא הדיש מרבה ואתם עסוקים בו עד הבציר, ובבציר תעסקו עד שעת הזרע: **ואכלתם לחמכם לשבע.** אוכל קמעא והוא מתברך במעיו:
@1001 **ונתתי שלום.** שמא תאמרו הרי מאכל והרי משתה, אם אין שלום אין כלום, תלמוד לומר אחר כל זאת ונתתי שלום בארץ, מכאן שהשלום שקול כנגד הכל. וכן הוא אומר עושה שלום ובורא את הכל: **וחרב לא תעבר בארצכם.** אין צריך לומר שלא יבאו למלחמה, אלא אפלו לעבור דרך ארצכם ממדינה למדינה:
@1002 **לפניכם לחרב.** איש בחרב רעהו:
@1003 **ורדפו מכם.** מן החלשים שבכם, ולא מן הגבורים שבכם: **חמשה מאה ומאה מכם רבבה.** וכי כך הוא החשבון, והלא לא היה צריך לומר אלא מאה מכם שני אלפים ירדפו, אלא אינו דומה מועטין העושין את התורה למרבין העושין את התורה: **ונפלו איביכם** וגו' **.** שיהיו נופלין לפניכם שלא כדרך הארץ:
@1004 **ופניתי אליכם.** אפנה מכל עסקי לשלם שכרכם, משל למה הדבר דומה, למלך ששכר פועלים וכו' , כדאיתא בתורת כהנים: **והפריתי אתכם.** בפריה ורביה: **והרביתי אתכם.** בקומה זקופה: **והקימתי את בריתי אתכם.** ברית חדשה, לא כברית הראשונה שהפרתם אותה, אלא ברית חדשה שלא תופר, שנאמר (ירמיה לא ל) וכרתי את בית ישראל ואת בית יהודה ברית חדשה לא כברית הראשונה:
@1005 **ואכלתם ישן נושן.** הפרות יהיו משתמרין וטובים להתיישן, שיהא ישן הנושן של שלש שנים יפה לאכול משל אשתקד: **וישן מפני חדש תוציאו.** שיהיו הגרנות מלאות חדש והאוצרות מלאות ישן, וצריכים אתם לפנות האוצרות למקום אחר לתת החדש לתוכן:
@1006 **ונתתי משכני.** זה בית המקדש: **ולא תגעל נפשי.** אין רוחי קצה בכם. כל געילה לשון פליטת דבר הבלוע בדבר אחר, כמו (שמואל ב' א כא) כי שם נגעל מגן גבורים, לא קבל המשיחה שמושחין מגן של עור בחלב מבשל, כדי להחליק מעליו מכת חץ או חנית, שלא יקוב העור:
@1007 **והתהלכתי בתוככם.** אטייל עמכם בגן עדן כאחד מכם, ולא תהיו מזדעזעים ממני. יכול לא תיראו ממני, תלמוד לומר והייתי לכם לאלהים:
@1008 **אני ה' אלהיכם.** כדאי אני שתאמינו בי שאני יכול לעשות כל אלה, שהרי הוצאתי אתכם מארץ מצרים ועשיתי לכם נסים גדולים: **מטת.** כמין יתד [התחובה] בשני ראשי העול המעכבים המוסרה שלא תצא מראש השור ויתיר הקשר, כמו (ירמיה כז ב) עשה לך מוסרות ומוטות קוניונגל''א בלע''ז [רצועת העול] : **קוממיות.** בקומה זקופה:
@1009 **ואם לא תשמעו לי.** להיות עמלים בתורה, לדעת מדרש חכמים. יכול לקיום המצות, כשהוא אומר ולא תעשו וגו' , הרי קיום מצות אמור, הא מה אני מקים ואם לא תשמעו לי, להיות עמלים בתורה. ומה תלמוד לומר לי, אין לי אלא זה המכיר את רבונו ומתכון למרוד בו, וכן בנמרוד (בראשית י ט) גבור ציד לפני ה', שמכירו ומתכון למרוד בו, וכן באנשי סדום (שם יג יג) רעים וחטאים לה' מאד, מכירים את רבונם ומתכונים למרוד בו: **ולא תעשו.** משלא תלמדו לא תעשו הרי שתי עברות:
@1010 **ואם בחקתי תמאסו.** מואס באחרים העושים: **משפטי תגעל נפשכם.** שונא החכמים: **לבלתי עשות.** מונע את אחרים מעשות: **את כל מצותי.** כופר [במצוות] שלא צויתים, לכך נאמר את כל מצותי, ולא נאמר את כל המצות: **להפרכם את בריתי.** כופר בעיקר הרי שבע עברות, הראשונה גוררת השניה, וכן עד השביעית ואלו הן: לא למד, ולא עשה, מאס באחרים העושים, שונא את החכמים, מונע את האחרים, כופר במצות, כופר בעיקר:
@1011 **והפקדתי עליכם.** וצויתי עליכם: **שחפת.** חולי שמשחף את הבשר, אנפולי''ש בלע''ז [בועות] , דומה לנפוח שהוקלה נפיחתו ומראית פניו זעופה: **קדחת.** חולי שמקדיח את הגוף ומחממו ומבעירו, כמו (דברים לב כב) כי אש קדחה באפי: **מכלות עינים ומדיבת נפש.** העינים צופות וכלות לראות שיקל וירפא, וסוף שלא ירפא, וידאבו הנפשות של משפחתו במותו. כל תאוה שאינה באה ותוחלת ממשכה קרויה כליון עינים: **וזרעתם לריק.** תזרעו ולא תצמח, ואם תצמח ואכלוהו אויביכם:
@1012 **ונתתי פני.** פנאי שלי, פונה אני מכל עסקי להרע לכם: **ורדו בכם שנאיכם.** כמשמעו ישלטו בכם: אגדת תורת כהנים מפרשה זו, **אף אני אעשה זאת.** איני מדבר אלא באף, וכן והלכתי אף אני עמכם בקרי (פסוק כד) : **והפקדתי עליכם.** שיהיו המכות פוקדות אתכם מזו לזו, עד שהראשונה פקודה אצלכם אביא אחרת ואסמכנה לה: **בהלה.** מכה המבהלת את הבריות, ואיזו, זו מכת מותן: **את השחפת.** יש לך אדם שהוא חולה ומטל במטה אבל בשרו שמור עליו, תלמוד לומר שחפת, שהוא נשחף. או עתים שהוא נשחף אבל נוח ואינו מקדיח, תלמוד לומר ואת הקדחת, מלמד שהוא מקדיח. או עתים שהוא מקדיח אבל סבור הוא בעצמו שיחיה, תלמוד לומר מכלות עינים. או הוא אינו סבור בעצמו שיחיה אבל אחרים סבורים שיחיה, תלמוד לומר ומדיבות נפש: **וזרעתם לריק זרעכם.** זורעה ואינה מצמחת, ומעתה מה אויביכם באים ואוכלים, ומה תלמוד לומר ואכלוהו אויביכם, הא כיצד, זורעה שנה ראשונה ואינה מצמחת, שנה שניה מצמחת ואויבים באים ומוצאים תבואה לימי המצור, ושבפנים מתים ברעב, שלא לקטו תבואה אשתקד. דבר אחר וזרעתם לריק זרעכם, כנגד הבנים והבנות הכתוב מדבר, שאתה עמל בהם ומגדלן, והחטא בא ומכלה אותם, שנאמר (איכה ב כב) אשר טפחתי ורביתי אויבי כלם: **ונתתי פני בכם.** כמו שנאמר בטובה ופניתי אליכם, כך נאמר ברעה ונתתי פני. משלו משל, למלך שאמר לעבדו פונה אני מכל עסקי ועוסק אני עמכם [לרעה] : **ונגפתם לפני איביכם.** שיהא המות הורג אתכם מבפנים ובעלי דבביכון מקיפין אתכם מבחוץ: **ורדו בכם שנאיכם.** שאיני מעמיד שונאים אלא מכם ובכם, שבשעה שאמות העולם עומדים על ישראל אינם מבקשים אלא מה שבגלוי, שנאמר (שופטים ו ג. ד) והיה אם זרע ישראל ועלה מדין ועמלק ובני קדם וגו' ויחנו עליהם וישחיתו את יבול הארץ, אבל בשעה שאעמיד עליכם מכם ובכם, הם מחפשים אחר המטמוניות שלכם, וכן הוא אומר (מיכה ג ג) ואשר אכלו שאר עמי ועורם מעליהם הפשיטו וגו' : **ונסתם.** מפני אימה: **ואין רדף אתכם.** מבלי כח:
@1013 **ואם עד אלה.** ואם בעוד אלה המכות עמכם לא תשמעו: **ויספתי.** עוד יסורין אחרים: **שבע על חטאתיכם.** שבע פרעניות על שבע העברות האמורות למעלה:
@1014 **ושברתי את גאון עזכם.** זה בית המקדש, וכן הוא אומר (יחזקאל כד כא) הנני מחלל את מקדשי גאון עזכם: **ונתתי את שמיכם כברזל ואת ארצכם כנחשה.** זו קשה משל משה, ששם הוא אומר (דברים כח כג) והיו שמיך אשר על ראשך נחשת וגו' , שיהיו השמים מזיעין כדרך שהנחשת מזיעה והארץ אינה מזיעה כדרך שאין הברזל מזיע והיא משמרת פירותיה, אבל כאן השמים לא יהיו מזיעין כדרך שאין הברזל מזיע ויהא חורב בעולם והארץ תהא מזיעה כדרך שהנחשת מזיעה והיא מאבדת פירותיה:
@1015 **ותם לריק כחכם.** הרי אדם שלא עמל שלא חרש שלא זרע שלא נכש שלא כסח שלא עדר ובשעת הקציר בא שדפון ומלקה אותו, אין בכך כלום, אבל אדם שעמל וחרש וזרע ונכש וכסח ועדר ובא שדפון ומלקה אתו, הרי שניו של זה קהות: **ולא תתן ארצכם את יבולה.** אף מה שאתה מוביל לה בשעת הזרע: **ועץ הארץ.** אפלו מן הארץ יהא לקוי, שלא יחניט פירותיו בשעת החנטה: **לא יתן.** משמש למעלה ולמטה אעץ ואפרי: **לא יתן פריו.** כשהוא מפרה משיר פירותיו, הרי שתי קללות, ויש כאן שבע פרעניות:
@1016 **ואם תלכו עמי קרי.** רבותינו אמרו עראי, במקרה, שאינו אלא לפרקים, כן תלכו עראי במצות. ומנחם פרש לשון מניעה, וכן (משלי כה יז) הקר רגלך, וכן יקר רוח (משלי יז כז) , וקרוב לשון זה לתרגומו של אנקלוס לשון קושי, שמקשים לבם להמנע מהתקרב אלי: **שבע כחטאתיכם.** שבע פרעניות אחרים במספר שבע כחטאתיכם:
@1017 **והשלחתי.** לשון גרוי: **ושכלה אתכם.** אין לי אלא חיה משכלת שדרכה בכך, בהמה שאין דרכה בכך מנין, תלמוד לומר (דברים לב כד) ושן בהמות אשלח בם, הרי שתים. ומנין שתהא ממיתה בנשיכתה, תלמוד לומר (שם) עם חמת זחלי עפר. מה אלו נושכין וממיתין, אף אלו נושכין וממיתין. כבר היו שנים בארץ ישראל חמור נושך וממית, ערוד נושך וממית: **ושכלה אתכם.** אלו הקטנים: **והכריתה את בהמתכם.** מבחוץ: **והמעיטה אתכם.** מבפנים: **ונשמו דרכיכם.** שבילים גדולים ושבילים קטנים, הרי שבע פרעניות, שן בהמה, ושן חיה, חמת זחלי עפר, ושכלה, והכריתה, והמעיטה, ונשמו:
@1018 **לא תוסרו לי.** לשוב אלי:
@1020 **נקם ברית.** ויש נקם שאינו בברית כדרך שאר נקמות, וזהו סמוי עיניו של צדקיהו. דבר אחר נקם ברית נקמת בריתי אשר עברתם. כל הבאת חרב שבמקרא היא מלחמת חילות אויבים: **ונאספתם.** מן החוץ אל תוך הערים מפני המצור: **ושלחתי דבר בתוככם.** ועל ידי הדבר ונתתם ביד האויבים הצרים עליכם, לפי שאין מלינים את המת בירושלים, וכשהם מוציאים את המת לקברו, נתנים ביד אויב:
@1021 **מטה לחם.** לשון משען, כמו (ירמיה מח יז) מטה עז: **בשברי לכם מטה לחם.** אשבור לכם כל מסעד אוכל, והם חצי רעב: **ואפו עשר נשים לחמכם בתנור אחד.** מחוסר עצים: **והשיבו לחמכם במשקל.** שתהא התבואה נרקבת ונעשית פת נפולה ומשתברת בתנור, והן יושבות ושוקלות את השברים לחלקם ביניהם: **ואכלתם ולא תשבעו.** זו מארה בתוך המעים. הרי שבע פרעניות חרב, מצור, דבר, שבר מטה לחם, חוסר עצים, פת נפולה, מארה במעים. ונתתם (פסוק כה) אינה מן המנין, שהיא החרב:
@1025 **במתיכם.** מגדלים ובירניות: **חמניכם.** מין עבודה זרה שמעמידין על הגגות. ועל שם שמעמידין בחמה קרויין חמנים: **ונתתי את פגריכם.** תפוחי רעב היו, ומוציאים יראתם מחיקם ומנשקים אותם, וכרסו נבקעת ונופל עליה: **וגעלה נפשי אתכם.** זה סלוק שכינה:
@1026 **ונתתי את עריכם חרבה.** יכול מאדם, כשהוא אומר והשמותי אני את הארץ (פסוק לב) הרי אדם אמור, הא מה אני מקים חרבה מעובר ושב: **והשמותי את מקדשיכם.** יכול מן הקרבנות, כשהוא אומר ולא אריח הרי קרבנות אמורים, הא מה אני מקים והשמותי את מקדשיכם, מן הגדודיות, שירות של ישראל שהיו מתקדשות ונועדות לבא שם. הרי שבע פרעניות אכילת בשר בנים ובנות, והשמדת במות, הרי שתים. כריתת חמנים אין כאן פרענות אלא על ידי השמדת הבירניות יפלו החמנים שבראשי הגגות ויכרתו. ונתתי את פגריכם וגו' הרי שלש. סלוק שכינה ארבע. חרבן ערים, שממון מקדש מן הגדודיות, ולא אריח קרבנות, הרי שבע:
@1027 **והשמתי אני את הארץ.** זו מדה טובה לישראל שלא ימצאו האויבים נחת רוח בארצם, שתהא שוממה מיושביה:
@1028 **ואתכם אזרה בגוים.** זו מדה קשה, שבשעה שבני מדינה גולים למקום אחד רואים זה את זה ומתנחמין, וישראל נזרו כבמזרה, כאדם הזורה שעורים בנפה ואין אחת מהן דבוקה בחברתה: **והריקתי.** כששולף החרב מתרוקן הנדן. ומדרשו חרב הנשמטת אחריכם אינה חוזרת מהר, כאדם שמריק את המים ואין סופן לחזור: **והיתה ארצכם שממה.** שלא תמהרו לשוב לתוכה ומתוך כך עריכם יהיו חרבה, נראות לכם חרבות שבשעה שאדם גולה מביתו ומכרמו ומעירו וסופו לחזור כאלו אין כרמו וביתו חרבים, כך שנויה בתורת כהנים:
@1029 **אז תרצה.** תפייס את כעס המקום שכעס על שמטותיה: **והרצת.** למלך את שבתותיה:
@1030 **כל ימי השמה.** לשון העשות ומ''ם דגש במקום כפל שממה: **את אשר לא שבתה.** שבעים שנה של גלות בבל הן היו כנגד שבעים שנות השמטה ויובל שהיו בשנים שהכעיסו ישראל בארצם לפני המקום ארבע מאות ושלשים שנה. שלש מאות ותשעים היו שני עונם משנכנסו לארץ עד שגלו עשרת השבטים, ובני יהודה הכעיסו לפניו ארבעים שנה משגלו עשרת השבטים עד חרבות ירושלים, הוא שנאמר ביחזקאל (יחזקאל ד ד. ו) ואתה שכב על צדך השמאלי וגו' וכלית את אלה ושכבת על צדך הימני שנית ונשאת את עון בית יהודה ארבעים יום. ונבואה זו נאמרה ליחזקאל בשנה החמישית לגלות המלך יהויכין. ועוד עשו שש שנים עד גלות צדקיהו, הרי ארבעים ושש. ואם תאמר, שנות מנשה חמשים וחמש היו, מנשה עשה תשובה שלשים ושלש שנה וכל שנות רשעו עשרים ושתים שנה, דכתיב ויעש אשרה כאשר עשה אחאב (מלכים ב' כא ג) ואחאב מלך עשרים ושתים שנה, כמו שאמרו באגדת חלק (סנהדרין קג א) ושל אמון שתים, ואחת עשרה ליהויקים, וכנגדן לצדקיהו. צא וחשוב לארבע מאות ושלשים ושש שנה שמטין ויובלות שבהם, והם שש עשרה למאה, ארבע עשרה שמיטין ושני יובלות, הרי לארבע מאות שנה ששים וארבע. לשלשים ושש שנה חמש שמטות, הרי שבעים חסר אחת, ועוד שנה יתרה שנכנסה בשמטה המשלמת לשבעים. ועליהם נגזר שבעים שנה שלמים. וכן הוא אומר בדברי הימים (דה''ב לו כא) עד רצתה הארץ את שבתותיה למלאת שבעים שנה:
@1031 **והבאתי מרך.** פחד ורך לבב. מ''ם של מרך יסוד נופל הוא, כמו מ''ם של מועד ושל מוקש: **ונסו מנסת חרב.** כאלו רודפים הורגים אותם: **עלה נדף.** שהרוח דוחפו ומכהו על עלה אחר ומקשקש ומוציא קול, וכן תרגומו קל טרפא דשקיף, לשון חבטה, שדופות קדים (בראשית מא ו) שקיפן קדום, לשון משקוף, מקום חבטת הדלת, וכן תרגומו של חבורה (שמות כא כה) משקופי:
@1032 **וכשלו איש באחיו.** כשירוצו לנוס, יכשלו זה בזה, כי יבהלו לרוץ: **כמפני חרב.** כאלו בורחים מלפני הורגים, שיהא בלבבם פחד וכל שעה סבורים שאדם רודפם. ומדרשו וכשלו איש באחיו, זה נכשל בעונו של זה, שכל ישראל ערבין זה לזה:
@1033 **ואבדתם בגוים.** כשתהיו פזורים תהיו אבודים זה מזה: **ואכלה אתכם.** אלו המתים בגולה:
@1034 **בעונת אבתם אתם.** כשאוחזים מעשה אבותיהם בידיהם: **ימקו.** לשון המסה, כמו ימסו, וכמו (זכריה יד יב) תמקנה בחוריהן, (תהלי' לח ו) נמקו חבורתי:
@1036 **והבאתי אתם.** אני בעצמי אביאם, זו מדה טובה לישראל, שלא יהיו אומרים, הואיל וגלינו בין האמות נעשה כמעשיהם, אני איני מניחם, אלא מעמיד אני את נביאי ומחזירן לתחת כנפי, שנאמר (יחזקאל כ לב. לג) והעולה על רוחכם היו לא תהיה וגו' חי אני וגו' אם לא ביד חזקה וגו' : **או אז יכנע.** כמו (שמות כא לו) או נודע כי שור נגח הוא, אם אז יכנע. לשון אחר אולי שמא אז יכנע לבבם וגו' : **ואז ירצו את עונם.** יכפרו על עונם ביסוריהם:
@1037 **וזכרתי את בריתי יעקוב.** בחמשה מקומות נכתב מלא, ואליהו חסר בחמשה מקומות, יעקב נטל אות משמו של אליהו ערבון שיבא ויבשר גאלת בניו: **וזכרתי את בריתי יעקוב.** למה נמנו אבות אחורנית, לומר כדאי הוא יעקב הקטן לכך, ואם אינו כדאי הרי יצחק עמו, ואם אינו כדאי, הרי אברהם עמו, שהוא כדאי. ולמה לא נאמרה זכירה ביצחק, אלא אפרו של יצחק נראה לפני צבור ומנח על המזבח:
@1038 **יען וביען.** גמול ובגמול אשר במשפטי מאסו:
@1039 **ואף גם זאת.** ואף אפלו אני עושה עמהם זאת הפרענות אשר אמרתי בהיותם בארץ אויביהם, לא אמאסם לכלותם ולהפר בריתי אשר אתם:
@1040 **ברית ראשנים.** של שבטים:
@1041 **והתורת.** אחת בכתב ואחת בעל פה, מגיד שכלם נתנו למשה בסיני:
@1043 **כי יפלא.** יפריש בפיו: **בערכך נפשת.** לתן ערך נפשו לומר ערך דבר שנפשו תלויה בו עלי:
@1044 **והיה ערכך** וגו' **.** אין ערך זה לשון דמים, אלא בין שהוא יקר בין שהוא זול, כפי שניו הוא הערך הקצוב עליו בפרשה זו: **ערכך.** כמו ערך. וכפל הכפי''ן לא ידעתי מאיזה לשון הוא:
@1046 **ואם מבן חמש שנים.** לא שיהא הנודר קטן, שאין בדברי קטן כלום, אלא גדול שאמר ערך קטן זה, שהוא בן חמש שנים, עלי:
@1048 **ואם מבן ששים שנה** וגו' **.** כשמגיע לימי הזקנה האשה קרובה להחשב כאיש, לפיכך האיש פוחת בהזדקנו יותר משליש בערכו, והאשה אינה פוחתת אלא שליש בערכה, דאמרי אנשי, סבא בביתא, פחא בביתא. סבתא בביתא, סימא בביתא וסימנא טבא בביתא:
@1049 **ואם מך הוא.** שאין ידו משגת לתן הערך הזה: **והעמידו.** לנערך לפני הכהן ויעריכנו לפי השגת ידו של מעריך: **על פי אשר תשיג.** לפי מה שיש לו יסדרנו וישאיר לו כדי חייו מטה כר וכסת וכלי אמנות, אם היה חמר, משאיר לו חמורו:
@1050 **כל אשר יתן ממנו.** אמר רגלה של זו עולה, דבריו קימין, ותמכר לצרכי עולה ודמיה חלין, חוץ מדמי אותו האבר:
@1051 **טוב ברע.** תם בבעל מום: **או רע בטוב.** וכל שכן טוב בטוב ורע ברע:
@1052 **ואם כל בהמה טמאה.** בבעלת מום הכתוב מדבר, שהיא טמאה להקרבה, ולמדך הכתוב שאין קדשים תמימים יוצאין לחלין בפדיון אלא אם כן הממו:
@1053 **כערכך הכהן כן יהיה.** לשאר כל אדם הבא לקנותה מיד הקדש:
@1054 **ואם גאל יגאלנה.** בבעלים החמיר הכתוב להוסיף חמש, וכן במקדיש בית וכן במקדיש את השדה וכן בפדיון מעשר שני הבעלים מוסיפין חמש, ולא שאר כל אדם:
@1057 **והיה ערכך לפי זרעו.** ולא כפי שויה. אחת שדה טובה ואחת שדה רעה, פדיון הקדשן שוה, בית כור שעורים בחמשים שקלים, כך גזרת הכתוב. והוא שבא לגאלה בתחלת היובל, ואם בא לגאלה באמצעו, נותן לפי החשבון סלע ופונדיון לשנה, לפי שאינה הקדש אלא למנין שני היובל, שאם נגאלה הרי טוב, ואם לאו הגזבר מוכרה בדמים הללו לאחר ועומדת ביד הלוקח עד היובל כשאר כל השדות המכורות, וכשהיא יוצאה מידו חוזרת לכהנים של אותו משמר שהיובל פוגע בו ומתחלקת ביניהם, זהו המשפט האמור במקדיש שדה. ועכשיו אפרשנו על סדר המקראות:
@1058 **אם משנת היבל יקדיש** וגו' **.** אם משעברה שנת היובל מיד הקדישה ובא לגאלה מיד: **כערכך יקום.** כערך הזה האמור יהיה, חמשים כסף יתן:
@1059 **ואם אחר היבל יקדיש.** וכן אם הקדישה משנת היובל ונשתהה ביד גזבר ובא זה לגאלה אחר היובל: **וחשב לו הכהן את הכסף על פי השנים הנותרת.** כפי חשבון. כיצד, הרי קצב דמיה של ארבעים ותשע שנים חמשים שקל, הרי שקל לכל שנה, ושקל יתר בין כלן, והשקל ארבעים ושמנה פונדיונין, הרי סלע ופונדיון לשנה אלא שחסר פונדיון אחד לכלן, ואמרו רבותינו שאותו פונדיון קלבון לפרוטרוט, והבא לגאול יתן סלע ופונדיון לכל שנה לשנים הנותרות עד שנת היובל: **ונגרע מערכך.** מנין השנים שמשנת היובל עד שנת הפדיון:
@1060 **ואם גאל יגאל.** המקדיש אתו, יוסיף חמש על הקצבה הזאת:
@1061 **ואם לא יגאל את השדה.** המקדיש: **ואם מכר.** הגזבר: **את השדה לאיש אחר לא יגאל עוד.** לשוב ליד המקדיש:
@1062 **והיה השדה בצאתו ביבל.** מיד הלוקחו מן הגזבר, כדרך שאר שדות היוצאות מיד לוקחיהם ביובל: **קדש לה'.** לא שישוב להקדש בדק הבית ליד הגזבר אלא כשדה החרם הנתון לכהנים, שנאמר (במדבר יח יד) כל חרם בישראל לך יהיה, אף זו תתחלק ביובל לכהנים של אותו משמר, שיום הכפורים של יובל פוגע בו:
@1063 **ואם את שדה מקנתו** וגו' **.** חלוק יש בין שדה מקנה לשדה אחזה, ששדה מקנה לא תתחלק לכהנים ביובל, לפי שאינו יכול להקדישה אלא עד היובל, שהרי ביובל היתה עתידה לצאת מידו ולשוב לבעלים, לפיכך אם בא לגאלה, יגאל בדמים הללו הקצובים לשדה אחזה. ואם לא יגאל וימכרנה גזבר לאחר, או אם לא יגאל הוא, בשנת היובל ישוב השדה לאשר קנהו מאתו, אותו שהקדישה. ופן תאמר לאשר קנהו הלוקח הזה האחרון מאתו, וזהו הגזבר, לכך הצרך לומר לאשר לו אחזת הארץ (פסוק כד) , מירשת אבות, וזהו בעלים הראשונים שמכרוה למקדיש:
@1066 **וכל ערכך יהיה בשקל הקדש.** כל ערכך שכתוב בו שקלים יהיה בשקל הקדש: **עשרים גרה.** עשרים מעות. כך היו מתחלה ולאחר מכאן הוסיפו שתות. ואמרו רבותינו שש מעה כסף דינר, עשרים וארבע מעות לסלע:
@1067 **לא יקדיש איש אתו.** לשם קרבן אחר, לפי שאינו שלו:
@1068 **ואם בבהמה הטמאה** וגו' **.** אין המקרא הזה מוסב על הבכור, שאין לומר בבכור בהמה טמאה ופדה בערכך. וחמור אין זה, שהרי אין פדיון פטר חמור אלא טלה, והוא מתנה לכהן ואינו להקדש, אלא הכתוב מוסב על ההקדש. שהכתוב של מעלה (פסוק יא) דבר בפדיון בהמה טהורה שהוממה, וכאן דבר במקדיש בהמה טמאה לבדק הבית: **ופדה בערכך.** כפי מה שיעריכנה הכהן: **ואם לא יגאל.** על ידי בעלים: **ונמכר בערכך.** לאחרים:
@1069 **אך כל חרם** וגו' **.** נחלקו רבותינו בדבר יש אומרים סתם חרמים להקדש, ומה אני מקים (במדבר יח יד) כל חרם בישראל לך יהיה, בחרמי כהנים שפרש ואמר הרי זה חרם לכהן, ויש שאמרו סתם חרמים לכהנים: **לא ימכר ולא יגאל.** אלא ינתן לכהן. לדברי האומר סתם חרמים לכהנים, מפרש מקרא זה בסתם חרמים. והאומר סתם חרמים לבדק הבית, מפרש מקרא זה בחרמי כהנים, שהכל מודים שחרמי כהנים אין להם פדיון עד שיבואו ליד כהן, וחרמי גבוה נפדים: **כל חרם קדש קדשים הוא.** האומר סתם חרמים לבדק הבית מביא ראיה מכאן, והאומר סתם חרמים לכהנים מפרש כל חרם קדש קדשים הוא לה', ללמד שחרמי כהנים חלים על קדשי קדשים ועל קדשים קלים, ונותן לכהן, כמו ששנינו במסכת ערכין (כח ב) אם נדר נותן דמיהם, ואם נדבה נותן את טובתה: **מאדם.** כגון שהחרים עבדיו ושפחותיו הכנענים:
@1070 **כל חרם אשר יחרם** וגו' **.** היוצא להרג ואמר אחד ערכו עלי, לא אמר כלום: **מות יומת.** הרי הולך למות, לפיכך לא יפדה אין לו לא דמים ולא ערך:
@1071 **וכל מעשר הארץ.** במעשר שני הכתוב מדבר: **מזרע הארץ.** דגן: **מפרי העץ.** תירוש ויצהר: **לה' הוא.** קנאו השם ומשלחנו צוה לך לעלות ולאכלו בירושלים, כמו שנאמר (דברים יד כג) ואכלת לפני ה' אלהיך מעשר דגנך תירושך וגו' :
@1072 **ממעשרו.** ולא ממעשר חברו, הפודה מעשר של חברו אין מוסיף חומש. ומה היא גאלתו, כדי להתירו באכילה בכל מקום. והמעות יעלה ויאכל בירושלים, כמו שנאמר (דברים יד כד) ונתת בכסף וגו' :
@1073 **תחת השבט.** כשבא לעשרן מוציאן בפתח זה אחר זה, והעשירי מכה בשבט צבוע בסיקרא להיות נכר שהוא מעשר, כן עושה [לגדיים] לטלאים ולעגלים של כל שנה ושנה: **יהיה קדש.** לקרב למזבח דמו ואמוריו, והבשר נאכל לבעלים, שהרי לא נמנה עם שאר מתנות כהנה, ולא מצינו שיהא נתן לכהנים:
@1074 **לא יבקר** וגו' **.** לפי שנאמר (שם יב יא) וכל מבחר נדריכם, יכול יהא בורר ומוציא את היפה, תלמוד לומר לא יבקר בין טוב לרע, בין תם בין בעל מום חלה עליו קדשה, ולא שיקרב בעל מום, אלא יאכל בתורת מעשר ואסור לגזז ולעבד:
@1076 **ה' עוזי ומעוזי ומנוסי.** אנטיפויימאנ"ט בלעז ומנחם חברו ל' פלא כמו נתת ליראיך נס להתנוסס ( תהלים ס ) וכן ה' נסי ( שמות ז ) ודונש פתר אותו ל' מנוס ממש: **אליך גוים יבאו.** סוף האומות לשוב אליך ולעבדך שכם אחד ועמך איך עשו להם אלהים והמה לא אלהים: **מאפסי.** כמו מקצה: **נחלו.** ל' נחלה: **מועיל.** ל' תועלת:
@1078 **כי שמי ה'.** כמשמעו מושל ושליט לקיים גזרתי:
@1079 **בעט ברזל.** משל הוא כלומר חקוקה בשיקוע ואין נוחה למחוק, ומדרש אגדה בעט ברזל בצפורן שמיר על ידי ירמיה שנקרא עמוד ברזל ועל ידי יחזקאל שנאמר לו כשמיר חזק מצור נתתי מצחך: **חרושה.** חקוקה כזה שהוא חורש בעומק: **על לוח לבם.** שאינם שוכחין עכו"ם שלהם:
@1080 **כזכור בניהם מזבחותם.** כזכירת בניהם כן היתה להם זכירת מזבחותם כאדם שיש לו געגועין על בנו: **ואשריהם.** אשר על עץ רענן. על עץ כמו אצל וכת"י תחות כל אילן עבוף:
@1081 **הררי בשדה.** ירושלים היושבת בהר המישור כל סביב העיר מישור שדה ול' הררי כמו ערבי ( ישעיה יג ) על שם שיושב בערבה מונטיינד"ש בלעז יושבי ההר ( ס"א יושבת ההר ): **חילך.** כמו ממונך: **במותיך בחטאת.** במותך עשויות בחטא לשם עכו"ם בכל גבוליך:
@1082 **ושמטתה.** על כרחך תשמט ארצך את אשר לא שבתה בשבתותיכם שאמרתי לכם ושבתה הארץ ( ויקרא כה ): **ובך.** אנקם מחמת נחלתך אשר נתתי לך שלא עשית רצוני להשמיטה, ד"א ובך מנחלתך ובך אנקם מנחלתך שאגלה אותך ממנה: **כי אש קדחתם באפי.** יקדתם בנחירי:
@1083 **אשר יבטח באדם.** בחרישו וקצירו לומר אזרע בשביעית ואוכל: **זרועו.** כמו עזרו וכן תרגם יונתן רוחצניה: **ומן ה' יסור לבו.** שהבטיחו וצויתי את ברכתי לכם ( שם ) כך שמעתי:
@1084 **כערער.** כעץ יחידי ל' ערירי ( בראשית טו ) ויש אומר דגאשטי"ה בלעז ומנחם פי' שם עץ מעצי היער וערער שמו וכן פי' כערער במדבר עץ אחד מעצי היער: **בערבה.** לשון מישור: **חררים.** יובש כמו חרה מני חורב ( איוב ל ): **ארץ מליחה.** ארץ שהיא מליחה ולא תהא מיושבת:
@1086 **ולא יראה.** העץ כי יבא חום: **בצורת.** ל' רעב פאמצ"א בלעז, ל"א בצורת ל' מבצר וכן חברו מנחם: **לא ידאג.** לא יפחד:
@1087 **עקוב הלב.** מלא תואנה ועקובה מכל רעה: **ואנוש.** לשון חולי וחליו הוא זה: **מי ידענו.** הוא סבור מי ידענו אני ה' חוקרו:
@1089 **קורא דגר.** קוק"ו גלונצנ"ט בלעז: **ולא ילד.** הקורא הזה מושך אחריו אפרוחים שלא ילד. דגר. ציפצוף שמצפצף העוף בקולו למשוך אפרוחין אחריו ואלו שהקורא דגר לא ילכו אחריו משיגדלו שאינם מינו כך עושה עושר ולא במשפט: **יהיה נבל.** מתקרי רשיעא:
@1090 **כסא כבוד וגו'.** לפי שבא לומר כל עוזביך יבושו מתחיל בקילוסו של מקום ומדבר לפניו אתה שכסא כבוד ומרום מראשית בריאת עולם ומכוון כנגד מקדשנו:
@1091 **מקוה ישראל.** ה' יושב עליו לפיכך כל עוזביך יבושו: **וסורי בארץ יכתבו.** אותם שסרים מדברי שאינם שומעים שליחותי בקברות תחתיות ארץ יכתבו:
@1092 **כי תהלתי אתה.** בך אני מתהלל ומתפאר לומר שאתה מושיעי: **תהלתי.** וונטנצ"א בלעז:

@2 **אדם כי יקריב מכם קרבן ליי'.** ראוי שתדע כי אדם להיותו שם המין כולל האיש והאשה. והרצון בזה הקרבן שהוא בא בנדר ונדבה וביאר תחלה עניין העולה ואחר כך באר ענין שאר הקרבנות האחרים הבאים בנדר ונדבה כמו המנחה והשלמים ומה שהתנה ואמר מכם אין ראוי שיובן שלא נקבל קרבן מן הגוים כי כבר התבאר בפרשת אמור אל הכהנים שכבר נקבל הקרבנות מן הגוים דרך נדר ונדבה אלא שלא נקבל מהם בעלי מומין שנאמר ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה כי משחתם בהם מום בם לא ירצו לכם ועוד שאלו היתה כוונת התורה להוציא הגוים לא היה צריך לומר מכם שהרי עם בני ישראל היו הדברים שנא' דבר אל בני ישראל ולזה יהיה הרצון באמרו מכם כמי שהוא מבני ישראל במדרגתם באמונה בשם יתע' והוציא כזאת המלה המשומד שהוא בבני ישראל ואיננו ממנו באמונה והסבה כשנקח זה מן הגוים לא מן המשומד כי הגוים לא היו קרובים לשם יתעלה ונתרחקו ואמנם הם רחוקים ממנו ואם ישתדלו להתקרב אליו ראוי שיקובל מהם ואולם המשומד שידע האמונה האמתית ועזב אותה מצד רוע תכונתו ופחיתותו הנה אין ראוי שיקובל ממנו זה כי אין כונתו להתקרב לשם יתעלה שאם היה הענין כן לא המיר כבודו. ועוד שכבר יראה שמי שנתחייב חטאת ועולה לא תקובל ממנו העולה אלא אחר החטאת כדי שיהיה נקי מחטאו קודם שיתקרב לשם בזה האופן כי לא יקבל האדון דורון מהשנוא לו ואע"פ שיהיה החטא בשגגה ובהיות הענין כן הנה קל וחומר שלא תקובל העולה מהמשומד שעבר במזיד:
@2 ואמר **קרבן ליי'** כי הוא ראוי שתהיה הכונה בקרבן לשם יתע' ואמר שאם היה זה הקרבן מן בהמה לא יהיה כי אם מהבקר או מן הצאן והרצון בצאן מן הכבשים או מן העזים כמו שאמר אחר זה ואם מן הצאן קרבנו מן הכבשים או מן העזים. וידמה שכמו שיאמר שה על הכבשים או על העזים כן יאמר צאן על הכבשים והעזים. ואולם ממיני החיה לא יהיה קרבן ואע"פ שיש בהם מינים טהורים ואחשוב שנבחרו שני אלו המינים לשתי סבות האחת מפני היותם יותר נבחרים והשני להיותם יותר נמצאים בקלות ולא רצה השם להעמיס עלינו להביא קרבן מה שיקשה מציאותו ולזה בחר מין ממיני העוף תורים ובני יונה לשתי אלו הסבות גם כן זכר תמים באמרו זכר מיעט נקבה וטומטום ואנדרוגינוס ובאמרו תמים הוציא הבעלי מומים וכבר יתבארו במה שיבא המומין הפוסלים בקרבן:
@3 **אל פתח אהל מועד יקריב אותו.** למדנו מזה שמטפל בו להביאו אל פתח אהל מועד ובאמרו יקריב אותו למדנו שהוא מחוייב להקריב אותו ושכופין אותו על זה ר"ל מי שיש לו כח על זאת הכפיפה והוא ב"ד ובהיות הענין כן הנה מה שאמר אחר זה לרצונו לא כוון בו שאם לא רצה יהיה פטור אבל יכריחוהו עד שיתרצה בזה וכבר נשער שהוא יתרצה בזה כשיאמר רוצה אני אע"פ שהכריחוהו בזה וזה כי האדם ראוי שימשך אחר המצות התוריות. וכאשר יביאהו יצרו הרע להתרחק מהם ויסרנוהו על זה עד שאמר שהוא רוצה בהם הנה ראוי שנשפט שכבר קבל מוסרנו ואמרו לפני יי' ירצה בו שיהיה ראש הבעל חי לצד המערב ששם קדש הקדשים:
@4 **וסמך ידו על ראש העולה.** מפני שזאת הסמיכה היא כלי מה לכפר עליו כמו מה שדרך העולה לכפר הנה יתודה בעת סמיכתו אותן העונות והנה למדנו זה ממה שנאמר בפרשת אחרי מות וסמך אהרן את שתי ידיו על ראש השעיר החי והתודה עליו את כל עונות בני ישראל וגו'. ולזאת הסבה היתה הסמיכה להורות שהוא כאלו סלק מעליו אותן העונות והעתיק אותן על ראש הבעל חי ההוא כדי שיתישב בלבו שכבר נתכפרו לו אותם החטאים ולזה תועלת מבואר שאם לא יחשוב שיתכפרו לו עונותיו בשובו אל השם יתע' הנה מי שחטא חטאים עצומים יחשוב כי כאשר אבד אבד ויוסיף לחטא תמיד לחשבו שאין לו תועלת בשובו לשם יתע' אלא יאבד בסבת העונות שחטא בהם וזהו התועלת הכולל בענין הקרבנות הבאים על החטאים והם לא יכפרו בזולת התשובה. ויתבאר מזה גם כן שהסמיכה לא תנהג בלבד בעולת נדבה אבל תנהג גם כן בעולת חובה כי היא יותר ראויה בזה להיותה באה על חטא מה. ובכלל הנה מצאנו הסמיכה נוהגת בקרבנות הבאים על החטא כמו שיתבאר במה שיבא וזאת הסמיכה היתה לצד המערב ר"ל שפני הסומך היה לצד המערב שהרי מצאנו במקום אחר בזאת הפרשה מבובא זה בענין הסמיכה אמר בפר העלם דבר של צבור וסמכו זקני העדה את ידיהם על ראש הפר לפני יי'. ולמדנו גם כן מזה המקום שהסמיכה היא בשתי ידים ועל ראש הב"ח ההוא לא על אבר זולתו כאלו בכל כוחו העתיק ממנו אלו העונות ושמם על ראש הב"ח ההוא ולפי שהכונה בסמיכה זאת הכונה למדנו שבעל הקרבן בעצמו יחוייב שיסמוך ידיו על ראש קרבנו לא בנו ולא אשתו ולא שלוחו. וכבר בארנו זה עוד ממה שנזכר בפרשת ואתה תצוה וסמך אהר' ובניו את ידיה' על ראש הפר כמו שבארנו שם:
@5 **ושחט את בן הבקר לפני יי'.** הנה השחיטה או הזביחה יורו לפי הוראת הנדר על חתיכה בצואר דרך הולכה והובאה לא בדרך הובאה כמו שיכו בגרון או במה שידמה לו ולא בדרך דרסה כי זה גם כן לא יכנס בגדר השחיטה אך ישים הסכין על הצואר ויחתוך לא שינקב ויכניס הסכין בצואר ויחתוך כי גם זה לא יקרא שחיטה וזה כלו מבואר מצד היראת הנדר. והוא בכלי שאין בו פגימה שאם היה בו פגימה כמו העניין במגרה לא יקרא זה שחיטה אבל נקב. וראוי שתהיה זאת החתיכה באופן שיתכן שתמות הבהמה בהזמן קצר אחר החתיכה והוא מה שמבואר לפי מה שהתבאר מן החוש ישלם בחתיכתו שני אלו הסימנין או רובם. ר"ל הקנה והוושט. ואולם בעוף ישלם זה לפי מה שהתבאר מן החוש בחתיכה סימן אחר או רובו. והיה זה כן מפני היותו חלוש ההיות ביחס אל הב"ח ההולך על ארבע כמו שבארנו בפרשת בראשית ולזה תמצא בדגים שהם יותר חלושים בחיות שבזולת שחיטה הותרו באכילה כי הם ימותו בזולת זה במעט זמן כשיוציאם מן המי'. וצריך שלא ישהא השוחט באמצע השחיטה כדי שלא תהיה נבלה קודם היותה שחוטה וראוי שלא יזבח לשם ע"ז כי הנזבח יאסר בזה וזה שורש כולל בכל שחיטה היתה לקדשים או לחולין ואולם בקדשים יחוייב עם זה שיהיו פני השוחט וראש הבהמה לפני יי' בשיהיו פניהם לצד המערב ששם קדש הקדשים שנאמר ושחט את בן הבקר לפני יי' הנה מפני שאמר ושחט ולא התנה שיהיה השוחט כהן כמו שהתנה אחר זה בהקרבת הדם ובזריקתו שיהיה נעשה על יד בני אהרן הכהנים הנה למדנו מזה שהשחיטה כשרה בזרים ומה שאמר בזאת השחיטה שתהיה לפני יי' כבר נתבאר אחר זה שהוא על ירך המזבח צפונה לפני יי' ר"ל בצפון העזרה אשר בה המזבח ולא יתכן שנאמר שכאשר היתה העולה מן הצאן תהיה השחיטה בצפון לא כאשר היתה מן הבקר שהרי כבר נאמר בפרשת צו במקום אשר תשחט את העולה תשחט החטאת למדנו מזה ששחיטת העולה בכללה היא במקום אחר בעזרה:
@5 ואמרו **לפני יי'** ירצה בו שתהיה השחיטה לצד המערב ששם קדש הקדשים וזה יהיה כשיהיה ראש הבהמה ופני השוחט לצד המערב:
@5 **והקריבו בני אהרן הכהנים אל הדם.** ר"ל בעת שהם כהנים וראוים לשרת וזה יהיה כשאינם חללים ובעלי מומין ושאר מה שידמה לזה ממה שפוס לאותם מהשירו' ושיהיו לבושים בגדי כהונה והיו עושים זה בכלי שרת כי כל זה מתנאי הכהן המשרת כמו שהתבאר במה שקדם ויתבאר במה שיבא והנה זאת ההקרבה היא הגשת הדם אל המזבח והיא כוללת עם זה קבלת הדם בכלי שרת כי לא מצאנו שיהיה כשר בזר זולת השחיטה ולזה לא נתר קבלת הדם כי אם בכהן וכבר ימצא מבואר בדברי הימים ויקבלו הכהנים את הדם וזרקו את הדם על המזבח סביב. מצאנו בחטאת על קרנות המזבח וזה הלשון נכלל בכל המקומות שנזכר שם מעשה החטאת בבהמה. ובמעשה העולה כתוב בכל המקומות על המזבח סביב וכבר ידענו כי הקרנות היו בחלק העליון מהמזבח ולזה למדנו שזריקת דם העולה הוא בחצי התחתון מהמזבח וזריקת דם החטאת בחצי העליון כי גובה המזבח היה נחלק לשני חלקים כמו שכתוב בפרשת ויקחו לי תרומה והיתה הרשת עד חצי המזבח. ולפי שאמר סביב הנה הוא מבואר שזה ישלם בשתי זריקות בשתי צדי האלכסון ברוחב בדמיון חוט יחגור המזבח כי כל זריקה תכלול שני צדדין ואלו הזריקות היו בקרן צפונית מזרחית מערבית דרומית. לפי שבצפון היתה השחיטה ומשם ההתחלה ומפני זה היו שירי הדם נשפכין ביסוד דרומית כי שם היה כלה עניין הזריקה ולפי שהיה אז שם והיה המקום ההו' ראוי לשפוך שירי הדם הנה היה ראוי שלא יעתקו מהמקום ההוא לשפוך שירי הדם אל מקום אחר כמו שהתבאר בשרשים הכוללים וכבר ביארנו גם כן במה שקדם כי יסוד דרומית מערבית הוא היותר נבחר ובחרתהו התורה בהגשת המנחה וחטאת העוף ועולת העוף. ולפי שאמר את הדם למדנו שיהי הדבר הנזרק הוא הדם לא תמצית הדם ולא שיריו. ובאמרו אשר פתח אהל מועד למדנו שזאת הזריקה תהיה במזב העולה לא במזב הקטרת. והנה זאת הזריקה היה בכלי אשר בו הדם:
@6 **והפשיט את העולה וגומ'.** לפי שלא התנה בכאן שיהיה זה נעשה על יד כהן למדנו מזה שההפשט והנתוח כשרים בזר. ובאמרו ונתח אותה לנתחי' הנתחי' וכבר יתבאר מצד הוראת הגדר מה הם נתחיה הראשונים והנה היה הראש נתח אחד ואף על פי שיש בו אברים רבים כמו שאמר אחר זה את הנתחים את הראש ואת הפדר כי הכונה היתה לנתח אותה לנתחיה הראשונים כמו שזכרנו וכבר נשלים הסבה בזה במה שיבא לפי מה שאפשר לנו:
@7 **ונתנו בני אהרן הכהן אש על המזבח.** למדנו שנתינת האש על המזבח לא יהיה כי אם בכהן בעת שהוא בכהנו. וזאת ההצתה ר"ל הצתת האש היתה בבקר על המזבח כמו שיתבאר בפרשת צו:
@7 **וערכו עצים על האש.** אין הרצון בזה מערכת העצים אשר היו עושים שם בהדליקם האש אבל אלו העצים היו נותנים שם בשומם הנתחים על המזבח כדרך שיהיו הנתחים על העצים אשר הם באש כמו שזכר בפסוק הבא אחר זה שאם היתה הכונה בזה במערכת העצים הנעשית בבקר להדליק האש הנה אפשר שלא יהיה עצים בעת הנתחים על המזבח להיות האש בוער בהם קודם זה ולזה אמרו רז"ל שהוא היה מצוה לשני גזירי עצים שהיו משימים שם שני כהנים בעת עריכת נתחי העולה על המזבח לפי שאי אפשר קיום מה שאמר וערכו עצים על האש בפחות משני כהנים וזה אמנם יהיה כתמיד של בין הערבים ואולם בתמיד של שחר יספיק בכהן אחד שישים שני גזירי עצים שנאמר בפרשת צו וביער עליה הכהן עצים בבקר בבקר וערך עליה העולה והקטיר עליה חלבי השלמים למדנו משם שכהן אחד די בתמיד של שחר ולזה יהיה זה המאמר שהקפיד שיהיה נעשה בשני כהנים כתמיד של בין הערבים:
@8 **וערכו בני אהרן הכהנים את הנתחים את הראש ואת הפדר.** לפי שאין הפדר נתח מהנתחים וזה מבואר מענינו למדנו מזה שחבור הפדר לראש היה לכסות בית השחיטה שהוא מלוכלך לכבוד השם והנה היה הראש קודם לשאר נתחים למעלתו עליהם מצד רבוי האברים הנכבדים אשר בו והנה זאת הערכה לא תכשר כי אם בכהנים רבים בעת היותם בכהונתם וזה שיקח אחד מהם הנתחי' אשר מדרכם שישאו מהם שני ולזה אמר בפרשה הבאה אחר זה וערך הכהן אותם להורות שיש לכהן אחד לשאת שני נתחים והנה זכר זה בצאן להיות זה יותר נמצא בו. ואמנם הנתח אשר היה מדרכו שישאהו אחד היה נושאו אחד ואשר היה מדרכו שישאוהו שנים היו שנים נושאים אותו וכן על זה האופן וזה כולו אמנם הוא בקרבנות צבור כמו התמידין כמו שנתבאר בפרשת צו באמרו זאת תורת העולה שהמאמר היה בתמידים ולזה לא ינהג דין שני גזירי עצים ורבוי הכהנים בעריכת האיברים כי אם בעולת צבור ואמנם בעולת יחיד לא נקפיד בזה אם היה נעשה על יד כהנים רבים או על יד אחד. ואין שם דין נתינת שני גזירי עצים ולפי שצוה לתת הנתחים על העצים אשר על האש אשר על המזבח למדנו שהוא ראוי שישי' הנתחי' כמו שהם על האש אר על המזבח לא שיצלם תחלה באש אחר שאינו על המזבח ואחר ישימם שם צלויים:
@9 **וקרבו וכרעיו ירחץ במים.** להסיר לכלוכם לכבוד השם יתעלה ולזה ראוי שתהיה זאת הרחיצה באון שיוסר הלכלוך בשלמות:
@9 **והקטיר הכהן את הכל המזבח.** ר"ל כל מה שזכר והם הנתחים והקרב והכרעים וכשנעשה על זה האופן אז היא נקראת עולה והוא הקרבן שהוא ריח ניחוח ליי' להניח לו מהחטאי' אשר מדרך העולה לכפר אותם ואם מן הצאן קרבנו וגו' זה כולו מבואר במה שקדם ואולם אמרו וערך אותם הכהן מלמד שכהן אחד אפשר שישא שני נתחים כמו שזכרנו למעלה:
@14 **ואם מן העוף וגו' מן התורים או מן בני היונה.** הקפידה התורה שנקח התורים בהיותם גדולים לא בהיותם קטנים ובני יונה בהיותם קטנים לא בהיותם גדולים וידמה שהם יותר נבחרים אז או היה זה להיותם אז יותר קלי המציאה כי ברב היונים גדלים בבית ויקל לתפשם בקטנותם והתורים אינם גדלים בבית ואפשר שנתקבצו בזה שתי אלו הסבות ולא הקפידה התורה בהם בהיותם תמימים או זכרים כמו העניין בעולם בהמה מפני החסרון שיש בזה הקרבן כי מדרג' המעופף היא שפלה מאד ממדרגת הב"ח ההולך כמו שהתב' בספר ב"ח כ"ש שהי' שפלה ממדרגת הטהורים בב"ח ההולך. ועוד כי רבי' מהמומי' הנמצאים ב"ח ההול הם בלתי נמצאים במעופף ולזה לא השגיחה התורה בזה כי התור' לא תביט בדבר זה. וזה מבואר מאד מן החוש והוא אפשר שלהכנת הנקבה הזרע אשר ממנו יהיה האפרוח בזה רושם לשמור ההויה ההיא משבושי החומר ומזה המקום יתבאר שאם היה העוף חסר אבר כמו שיבש גפו או יהיה שנסמית עינו ומה שידמה לזה שהוא פסול כי בזה המום לא ימצא הבדל בטבע בין העוף ובין הבהמה וכבר יורה שזה הוא רצון התורה שכבר הקפידה התורה בלקיחת אלו המינים בזמן היותם יותר נבחרים ועוד שכבר תמצא שכאשר זכרה התורה המומין הפוסלין בבהמה לא זכרה אלא לרוב העניין הגלות בהם וכשהקל בעוף בעניין המומין הנה ראוי שנדון שכבר הקל במה שזכר בבהמה וזה מבואר אחר עיון מהשרשים הכוללים והקריבו הכהן אל המזבח למדנו שהגשתו למזבח למקלו הוא בכהן בכהונו לא בזר וכבר זכרנו עם זה ג"כ שכבר יתכן שיביא האדם תור אחד או בן יונה אחד ולא יצטרך להביא שנים וראוי שתדע שזאת ההקרבה היא לקרן דרומית מערבית מהמזבח לפי ששם היה הכבש ומשם יעלה להקטיר ועוד כי ההקרבה אל המזבח ראוי שתהיה לפני י' אל פני המזבח כמו שביאר התור במנחה בפרשת צו שנאמר בה גם כן והגישה אל המזבח כמו שאמרה בכאן והקריבו הכהן אל המזבח וההגשה היא תהיה בהכרח לצד קרן דרומית מערבית כמו שנבאר אחר זה:
@15 **ומלק את ראשו והקטיר המזבח.** הנה ענין המליקה היא לפי מה שיורה עליו הגדר חתיכת הסימנים מאחורי העורף בצפורן הכהן לא בסכין ולא בכלי אחר וזה אמנם יהיה כשיחתוך בציפורנו שדר' ומפרקת בלא רוב בשר כדי שלא תהיה מתה קודם שימלוק כי המליקה לא תהיה כי אם בחי כמו שהזביחה לא תהיה כי אם בחי. וראוי שתדע כי אין הרצון נאמרו והקטיר המזבחה שיקטירוהו המזבח וזה כי ההקטרה לא תהיה קודם זריקת דמים כמו שהתבאר בפרשיות הקודמות וכבר נזכרה אחר זה בזה הפסוק זריקת הדם ולזה יחוייב שלא יהיה הרצו' בזה שיקטיר הוא המזבח ועוד שכבר נזכר אחר זה הקטרה באמרו והקטיר אותו הכהן המזבח. ואי אפשר שנאמר שזאת ההקטרה היתה לראש וההקטרה הנזכרת בסוף לשארית העוף כי הקטרה היתה יחד לא פעמים פעמי' וזה מבואר ממה שקדם ולזה יהיה הרצון באמרו והקטיר המזבחה בזה המקום שתהיה זאת המליקה במקום שיוכל להקטיר ממנו העוף המזבחה והוא בחצי העליון מהמזבח ולמדנו עם זה שהוא ראוי שתהיה זאת המליקה באופן שיוכל להקטיר הראש בפני עצמו ולזה יחוייב שיחתוך שני הסימנין ויחתוך כל הראש באופן שיוכל להקטירו בפני עצמו ונמצה דמו על קיר המזבח לפי שכבר קדם שזאת המליקה היא בכבש בחצי העליון מהמזבח למדנו שמצוי הדם היה בחי העליון מהמזבח בהפך העניין בעולת בהמה וכבר נאמר זה גם כן מתאר זאת הזאה שהיא דומה להזאה אשר לחטאת וזה שהזאת החטא' היא מלמעלה למטה לא ברוחב קירות המזבח כמו שיתבאר והזאת העולה היא ברוחב קירות המזבח כי היא סביב וזאת ההזאה היא באורך כמו העניין בהזאת החטאת שנאמר ונמצה דמו על קיר המזבח והדם הנמצא שותת מלמעלה למטה וההזאות שהם בזה התואר היו בחצי העליון מהמזבח והסיר את מראתו בנוצתה הוא הופק עם העור והנוצה שעליו ובני מעים היוצאים עמו כי זה כולו בכלל במלת מראתו ר"ל מקום הראי:
@16 **והשליך אותה אצל המזבח קדמה אל מקום הדשן.** למדנו מזה שמקום הדשן הוא אצל המזבח מלמטה. וכבר היה למזרח לפי ששם זריחת השמש ולפי שלא יחשוב חושב שהעבודה היא לשמש היו הדברי' הנכבדי' במקדש לפאת מערב והפחותים לפאת מזרח ושם היה מקום מוראת העוף. ולפי שהמזבח היה מוכן לעבודת השם היה מקום הדשן למזרח הכבש שהוא אצל המזבח לא למזרח המזבח בעצמו:
@17 **שסע אותו בכנפיו לא יבדיל.** לפי שכבר אמר בעולת בהמה ונתח אותה לנתחיה היה מקום לחשוב שיהיה העניין כן בעוף הנה מפני זה אמר לא יבדיל ר"ל שלא יצטרך להבדיל ולזה לא יהיה אמו לא יבדיל מצות לא תעשה וזה מבואר מאד:
@17 **והקטיר אותו הכהן המזבח על העצים אשר על האש.** אין הרצון בזה שיהיו שם שני גזירי עצים שאין כתוב כאן עריכה לעצים אבל הרצון אצלי שהוא ראוי שיקטירהו על היוקד מהעצים לא על מה שנשלמה כבר שריפתו והוא הדשן והנה יקראם עצים מפני מה שבהם עדין לישרף:
@18 **ונפש כי תקריב קרבן מנחה ליי'** לפי שזכר מעשה העולה שהיא באה בנדר ונדבה והיתה המנחה באה עם העולה כמו שיתבאר במה שיבא באר בזה המקום שיש לאדם להתנדב מנחה בפני עצמה וביאר ענינה בכל אופניה וזכר תחלה מנחת הסלת כי לסלת קדימה על מה שיעשה ממנו ואחר זה זכר מאפה תנור להיות יותר נמצא ממעשה מחבת ומעשה מרחשת והנה הסלת היא סלת החטים וכבר יתבאר שלא יהיה זה פחות מעשרון כי הוא המנחה הקטנה שכל המנחות הבאות עם העולה כמו שיתבאר במה שיבא:
@18 **ויצק עליה שמן.** שיהא בו מהשמן מה שראוי שיוצק על כללות הסלת וזה אמנם יהיה כשהיא בכמות ראוי שיהיה נכלל בו ושערו חכמים לוג שמן לכל עשרון ולזאת הסבה ראוי שיושם מהשמן בתחתית הכלי ואחר כן יושם בו הסולת ויוצק ממנו עליו ויבלול ונתן עליה לבונה כבר יתבאר במה שיבא בזאת הפרשה ששיעור הלבונה היה קומץ אחד והביאה אל בני אהרן הכהנים וקמץ משם מלא קמצו וגומ'. ראוי שהכהן היה מגישה אל המזבח כמו שכתוב אחר זה והקריבה אל הכהן והגישה אל המזבח. וכבר קדם להגשה קבולה בכלי שרת והוא מתנאיה ולזה לא יהיה קבולה בכלי שרת כי אם בכהן ובכלל הנה לא התירה התורה בזה אלא הבאת המנחה אל הכהן ולזה לא נתיר הקבלה בכלי שרת כי אם בכחן ואחר ההגשה אל המזבח תהיה הקמיצה בדרך שבני אדם קומצים מלא קמצם בזולת הרחבת האצבעות ובזולת קבוצם אל קצת יותר מן הראוי:
@19 **מסלתה ומשמנה.** למדנו מזה שראוי שיהיה בלול באופן שכאשר יקח מסלתה יקח משמנה עמה ושהוא ראוי שיהיה זה הקומץ מסלתה ומשמנ' לא מסולת חברתה ולא משמן חברתה ולזה אם נתערבו מנחות זו עם זו באופן שלא יוכל לקמוץ מזו בפני עצמה ומזו בפני עצמה הרי הן פסולות והיה זה כן לפי שקומץ מתיר המנחה לכהנים וזלה ראוי שיהיה מהמנחה ההיא על כל לבונתה לפי שאמרנו דבר על דבר הוא שני לו במספר ואחרי המספ' הם בהכרח מסכימי' כמו שהתב' במקומותיו הנה יחוייב שיהיה שיעור הלבונה כשיעור מה שיקח מהסולת והשמן ר"ל קומץ:
@19 **והקטיר הכהן את אזכרתה המזבח.** ר"ל הקומץ והלבונה. ולא תכשר זאת ההקטרה כי אם בכהן בכהונו ולזה יהיו במנחה ארבע עבודות דומות לארבע הנזכרים בעולה והם קבלה והולכה וזריקה והקטרה וכמנחה הם קבלה והגשה וקמיצה והקטרה:
@20 **והנותרת מן המנחה לאהרן ולבניו.** מגיד שלא זכו בה עד שתהיה נותרת ר"ל שיוקטר הקומץ ומגיד לך שכהן גדול קודם לכהן הדיוט באכילת שירי המנחה וכן הענין בשאר הדברים. ולזה אמרו רז"ל שהוא נוטל חלק בראש והוא מבואר שלא תותר זאת האכילה כי אם לזכרי כהונ' וזה יתבאר בפרשת צו:
@21 **וכי תקריב קרבן מנחה מאפה תנור.** הנה תהיה באחד משני פנים. והוא שאם יעשה מסולת החטים. חלות מצות בלולות בשמן. ר"K שיבללו הסולת בשמן לוג שמן לכל עשרון ואחר יגמרו הלישה באופן הנהוג ר"ל המים פושרין ואפה זה בתנור או שיעשה מהסלת מצות רקיקות בזולת שמן בלישתם אבל אחר העשותם ישמחו הרקיקים בשמן באופן שיבלה לוג שמן בכל עשרון. ואחשוב שזאת המשיחה היא קודם האפייה כי בזאת האופן יהיו הרקיקה יותר ערבים:
@22 **ואם מנחה על מחבת.** הוא כלי מנחשת שאין לו שפה ועושה הבצק קשה שלא יצא מהכלי ואופן מעשיהו הוא שבולל הסולת בשמן לוג לכל עשרון ואחר לש הבצק בפושרין כמנהג וצוה שתהיה מצה לא חמץ:
@23 **פתות אותה פתים ויצקת עליה שמן.** אמרו ז"ל שכבר היה פותת אותה בזה האופן שכופל תחלה לשנים ואחר חוזר וכפלה לארבעה וכותת בזה האופן ונותן הפתיתין בכלי שרת ויצק עליה שמן:
@24 **ואם מנחת מרחשת קרבניך.** הוא כלי שיש לו שפה ועושה הבצק רך והשאר נעשה כמעשה מחבת אין הבדל ביניהם אלא שזה בצקו רך וזה בצקו קשה ולזה הוא מבואר שהוא פותת אותה פתים וצק עליה שמן כמו הענין במנחת מחבת אבל מנחת המרחשת יותר ראויה ביציקת השמן כי נתינת השמן בה הוא יותר ראוי ונהוג ולפי שפתיתת החלות היה כדי שיתכן לקמוץ הוא יותר מבואר שזה משותף למאפה תנור ומחבת ומרחשת ואמנם יציקת השמן לא תהיה במאפה תנור כי התורה לא זכרה אותו כי אם במנחת מחבת שהיא יותר ראוי בזה ממנחת מאפה תנור לפי הנהוג. ולזה לא נלמד ממנה זה הדין במאפה התנור והגישה אל המזבח ר"ל הכהן שכבר זכר כי ההגשה תהיה על יד כהן כמו שנתבאר בפרשת צו אמר שם זאת תורת המנחה הקרב אותה בני אהרן לפני יי' אל פני המזבח ולזה יהיה הרצון באמרו כאן והגישו אל המזבח שתהיה ההגשה לפני יי' אל פני המזבח וזה יהיה כשתהיה הדגשה לקרן דרומית מערבית בחודה של קרן כמו שיתבאר בג"ה בפרשת צו:
@26 **והרים הכהן מן המנחה את אזכרתה.** ר"ל מלא קומצו ולבונה כמו העניין באזכרתה הכתוב למעלה וככלל הנה ראוי שיהיו כל אלו המנחות שוות בענין הקמיצה והלבונ' וזה מבואר בנפשו מן בעטן בעצמו ומלשון התור בזה כל המנחה אשר תקריבו ליי' לא תעשה חמץ לפי שבפרשת צו חזר והזכיר לא תאפה חמץ למדנו שהוא חייב על חלק מהעשייה כי האפיה היא חלק מהעשייה ולפי השרשים הכוללים יתבאר שהקומץ אשר יקרב ליי' אם חמצו אחר שהקריבו לראש המזבח אינו לוקה שנאמר אשר תקריבו וזה כבר קרב והוא מבואר שאפילו שירי המנחה אם עשה מהם חמץ לוקה שכבר אמר בפרשת צו על שירי המנחה לא תאפה חמץ כי כל שאור וכל דבש לא תקטירו ממנו אשה ליי' הנה התבאר הסבה בזה במה שיבא לפי מה שאפשר לנו והוא מבואר שלא ימנעו מפני זאת האזהרה אכילת שירי מנחות בדבש ואמנם נמנע חמוץ שירי מנחות לסבה שזכרנו קרבן ראשית תקריבו אותם ליי' ר"ל שתי הלחם שהיו באים חמץ בעצרת והוא ראשית לכל המנחות הבאות מן החיטים ולזה לא יותר להביא מנחות מן החדש מהחטים קודם זה לפי שהוא קרבן ראשית שיהא ראשית לכל המנחות הבאות מהחטי' ואל המזבח לא יעלו לריח ניחוח כי לא היה מהם דבר למזבח אבל היו שתי הלחם בעצרת נאכלים לכהנים כמו שיתבאר במה שיבא. ולפי שאמר לריח ניחוח למדנו שאם העלה חמץ למזבח שלא לעבודה אינו לוקה:
@30 **וכל קרבן מנחתך במלח תמלח.** ר"ל כל מה שהוא קרב ממנחתך תקריב עמו מלח כאלו תאמר הקומץ והלבונה ואמר אחר זה ולא תשבית מלח ברית אלהיך מעל מנחתיך לעבור עליו בעשה ובלא תעשה והוא מבואר שהמלח בא משל צבור כמו העצים והמי' אשר ידיחו בהם הקרב והכרעי' כי אין אלו דבר מעצם הקרבן אבל הם תקון לו:
@30 **על כל קרבנך תקריב מלח.** זה כולל לכל הקרבנות הקרבים למזבח כמו איברי העולה ואמורי קדשי הקדשים וקדשים קלים ואם תקריב מנחת בכורים ליי' זו מנחת העומר שהיתה קרבה בי"ו בניסן והיא היתה באה חובה כמו שיתבאר בפרשת אמור אל הכהנים:
@31 ואולם אמר מלת **ואם** לפי שהיא תלוי' בארץ והרצון בזה כשתהי' באר באופן שתתחיי' בה וידענו שזאת המנחה בא מן השעורים שאם היתה באה מן החטים לא היו שתי הלחם של עצרת מנחה חדשה וכבר קראה הכתוב מנחה חדשה בפרשת אמור אל הכהנים ועוד שלא היו החטים נקצרים בי"ו בניסן בארץ ישראל. ואמנם היה אז קציר שעורים וזה מבואר מן החוש אביב קלוי באש ר"ל שהוא קולה השעורים באש כדי ליבשם באופן שיהיה שולט האש בכולם:
@31 **גרש כרמל.** היו טוחנין אותו ברחיים של גרוסו' כדי שיהיה הסולת יותר יפה:
@32 **ונתת עליה שמן.** ר"ל על הסלת של זאת המנחה והנ' היה המעשה בה כמו מעש' מנח' הסלת הנזכר למעלה וזה מבוא' מלשון הכתוב והנה בזה המקום נשלם זכר המנחות הבאות בפני עצמן:
@34 **ואם זבח השלמים קרבנו.** אחר שביאר הדין המנחה בא לבאר דין מעשה זבח השלמים וכבר נקרא שלמים מענין שלום ר"ל שהוא יבא אחרי היות שלום בין האדם למקום ולזה היה עניינו שיאכלו בו על שלחן אחד הבעלים והכהנים וה' יתע' וזה כי הדם והאמורים היו למזבח וחזה ושוק לכהנים והעור והבשר לבעלים. וכבר נבאר זה באור שלם אחר שישלמו לב עניני הקרבנות:
@34 **אם זכר אם נקבה תמים יקריבנו.** מי שהוא זכר ודאי או נקבה ודאית יצא טומטום ואנדרוגינוס:
@34 **תמי'.** להוציא בעל מום והנה לא הקפידה התורה בו שיהיה זכר כמו שהקפידה בעולה לפי שהעולה כלה לשם יתעלה:
@34 **לפני יי'.** ר"ל בעזרה באופן שיהיו פניו לצד המערב:
@35 **וסמך ידעו על ראש קרבנו.** כבר בארנו זה במה שקדם. וראוי שיובן מזה שאין הסמיכה נוהגת אלא במה שאפשר שיאמר בו שהוא קרבן שלו ולזה לא תהיה הסמיכה בפסח ובכור ובמעשר ועוד שהם אינם באים על חטא כלל והסמיכה הוא בעבור החטא כמו שקדם:
@35 **ושחטו פתח אהל מועד.** מגיד שהשחיטה כשרה בזר. ושחיטת השלמים כשרה בכל העזרה. כי על העזרה היתה נקראת פתח אוהל מועד ר"ל מבוא אהל מועד ולזה אם שחטה בעזרה אפילו אחורי ההיכל כשרה כי כל העזרה היא מבוא אוהל מועד ר"ל שממנה יבואו אל אוהל מועד. ואולם אם שחטה בגגו של היכל פסולה וכן אם שחטה בעזרה והיו דלתות ההיכל נעולות כי אז אין העזרה בעצמותה מבוא אבל מועד אם אל באמצעות פתיחת דלתות ההיכל וזה מבואר מאד:
@35 **וזרקו בני אהרן הכהנים.** בעת שהם בכהונם להוציא החללים ומחוסרי בגדים ושאר מה שידמה לזה ויתבאר שמשחיטה ואילך מצות כהונה על האופן שהתבאר במה שקדם:
@35 **על המזבח סביב.** ר"ל למטה מחוט הסקרא ושם היה נותן שתי מתנות שהן ארבע בשתי קרנות לאלכסון המזבח כמו שביארנו במה שקדם:
@36 **החלב המכסה את הקרב ואת כל החלב אשר על הקרב.** זה מבואר כי קצת החלב היה המכסה הקרב בלתי דבק בו וקצת דבק בו כמו חלב שעל גבי הקבה. ומשני אלו החלבים דבר בזה המקום:
@37 **ואת שתי הכליות ואת החלב אשר עליהם אשר על הכסלים.** אלו לא אמר כי אם החלב אשר עליהן היה לחשוב שלא יהיה קרב מהחלב ההוא רק מה שהיא ממנו על הכליות לבד ולזה אמר אשר על הכסלים וכלל בה הנשאר מהחלב ההוא ופתילות החלב אשר על הכסלים שהוא תחת החלב הנמשך לחלב הכליות:
@37 **ואת היותרת על הכבד על הכליות יסירנה.** הנה היה נוטל מעט מן הכבד עם היותרת כמנהג הטבחי' והוא מה הו מן הכבד אצל הכליות והנה ביאור הפסוק כן והיותרת נוסף על הכבד שהוא אצל הכליות יסירנה:
@38 **והקטירו אותו בני אהרן המזבח.** ר"ל בעל שהם בכהונם לפי שכבר אמר אחר זה בהשלמת באור מעשה זבח השלמי' והקטירו הכהן:
@38 **והקטירם הכהן על העולה אשר על האש אשר על המזבח.** ר"ל על עולת התמיד של בקר שהיא ראשונה לכל שאר הקרבנות. וכבר ישימו שם עצים על האש קודם הקטרה כמו שקדם ומזה המקום יתבאר שאין דין גזירי עצים נוהג כי אם בעולת התמיד שאם היה נוהג כן בעולת יחיד הנה אל היה ראוי שיהיה הבדל בזה העניין בין העולה ויתר הקרבנות:
@39 **ואם מן הצאן קרבנו לפני אהל מועד.** ר"ל בעזרה וכל מקומות העזרה כשרים בזה. כמו שהתבאר במה שקדם כי אין ראוי שיהיה הבדל בזה בין קצת מיני זבח השלמים ובין קצת חלבו האליה תמימה:
@42 **לעומת העצה יסירנה.** רוצה לומר שמנו והנבחר ממנו והוא האליה ויסיר אותה בשלמות עם חליות השדרה עד מקום חבור הכליות והוא נקרא העצה בלשוננו:
@49 **כל חלב ליי'.** רוצה לומר שהמכוון בהקטרת חלבים האלו הוא שיהיה כל חלב ליי' באופן שלא יאכלוהו בני ישראל והנה יתבאר במה שיבא חלק הכהנים בזבח השלמים והשאר יהי' נאכל לבלעי':
@50 **חקת עולם לדורותיכם בכל מושבתיכם כל חלב וכל דם לא תאכלו.** מגיד שלא נאסר לבד החלב והדם של הקרבנות אבל נאסר כל חלב וכל דם מהבהמות המותרות באכילה ולזה אע"פ שהותר בשר תאוה אחר הכנס ישראל בארץ הנה ינהג בבשר ההוא זה הדין ולמדנו עוד עם זה שאין המצוה הזאת תלויה בארץ ולזה אמר בכל מושבותיכם שלא יחשוב חושב מזה יהיה נוהג לבד בקרבנות כי אין הקרבנות נוהגות בכל מושבות כמו שיתבאר במה שיבא. ולפי שסמך אזהרת החלב למה שאמר כל חלב ליי' למדנו שהחלבים שהם ליי' הם הנאסרים לבד מזה המקום יתבאר שהחלב שבתוך הכליות ושבתוך הכסלי' אינו נאסר מן התורה כי התורה לא זכרה בחלבי' אשר לה' כי אם החלב שעל הכליות ועל הכסלים ולא שבתוך הכליות ובתוך הכסלים. ולפי שלא זכר בקרבנות בדם מינים שונם כמו שזכר בחלבים ואמר כל דם לא תאכלו למדנו שכל אחד ממיני הדם הוא בלאו לא הדם היוצא בשעת שחיטה לבד אשר היה נזרק על המזבח כמו דם האברים ודם התמצית ומה שידמ' להם ובכאן נשלם זכר הקרבנו' שיהיו על צד הנדר והנדבה ואולם למה היו אלו הקרבנות בזה האופן הנזכר הנה נבא זה אחר שנשלם זכר הקרבנות כלם כדי שלא נכפול המאמר בזה ושם נבאה בג"ה התועלות המגיעות מהם ומה מהם על הכונה הראשונה ומה מהם על הכונה השנית:
@52 אחר שזכר הקרבנות הבאים בנדר ונדבה ובאר קצת מהם וקצת דיניהם שב לבאר לזכור הקרבנות הבאים על חטא והחל מהבאים על החטאים היותר עצומים והם אשר יתחייבו על זדונם כרת וכבר למדנו זה ממה שאמר והוא שכבר זכר בכאן בזה החטאת דין מיוחד מיחיד ודין מיוחד אם נעשה מפני העלם דבר מעיני העדה יש לספק בזה המקום על הדם למה מנה שתי מצות בעניין החטאת וידמה שהכל מצוה אחת כי כבר התחיל בכללות נפש כי תחטא ואחר כך ביאר דיניו אם היה החוטא כהן משוח או כל עדת ישראל או נפש אחת מהם. והנראה בעיני שכל זה מצוה אחת לפי העקרים הכוללים שעליהם ונבנתה שרש המנות המצות ובכמו זה תמצא זאת החלוקה במה שאמר בפרשת שלח לך וכי תשגו ולא תעשו את כל המצות האלה והנה חייב שם לצבור פר כמו שחייב בכאן אלא שהוסיף שם שעיר ותמצא שחייב שם ליחיד עז בת שנתה לחטאת כמו שחייב בכאן שעירה או כשבה ולזה למדנו שהמצות אשר יהיה זה הקרבן עליהם הוא מסוג המצוה הנזכרת בפרש' שלח לך. ואמנם המצוה הנזכרת בפרשת שלח לך היא אשר יתחייבו על זדונה כדת כמו שנתבאר שם באמרו והנפש אשר תעשה ביד רמה וגומר הכרת תכרת הנפש ההיא עונה בה ולזה יהיה מה שאמר בזה המקום מכל מצו' יי' אשר לא תעשינה במצו' לא תעשה מחייבין על זדונה כרת. ואמנ' נתיחדה מהם הנזכרת בפרש' שלח לך לפי שהיא בע"ז כמו שנבאר שם בג"ה. ומזה המקום יתבאר שלא יתחייבו חטאת על מצות עשה ואע"פ שחייבין על זדונו כרת כמו פסח ומילה שנאמר אשר לא תעשינה מכלל שבלא תעשה הכתוב מדבר וכן לא יתחייבו חטאת על מצות לא תעשה שחייבין על זדונה כרת אם לא היה מעשה כמו המגדף כי הדבור איננו מעה שנאמר אשר לא תעשנה וזה ממה שיורה שיש מעשה באלו המצות אשר ידבר בבזה המקום:
@52 **ועשה מאחת מהנה.** מגיד שכל אחת ואחת מהנה חייב חטאת ולזה יתבאר על דרך משל אם אכל חלב ודם בשגגה חייב שני חטאות וכן על כל מצוה ומצוה מאלו:
@53 **אם הכהן המשיח יחטא לאשמת העם.** בעבור שהכהן המשיח הוא היותר נכבד שבעם ונתקדש יותר התחיל המאמר בו כזה תמצא במה נזכר בחטאת יום הכפורים שראשונה הקדים פר חטאת אשר לו לזאת הסבה בעינה. וראוי שתדע כי הכהן המשיח היה מוכן להורות משפטי ה' לישראל כמו שנאמר בפרשת שופטים ושוטרים. לבלתי שמוע אל הכהן העומד לשרת שם את יי' אליך והנה נשתתפו בזה כל הכהנים כמו שאמר שם ובאתה אל הכהנים הלויים ואמר יורו משפטיך ליעקב ותורתך לישראל והנה הנבחר מהם היה כהן גדול ולזה היה הוא יותר מיוחד בזה ולזה יהיה אמו לאשמת העם ר"ל שיהיה חטאו במה שאולי יהיה סבה שיאשמו בו העם וזה יהיה כשיטעה בהוראה באלו המצות הנזכרות כי בזה האופן אפשר שיחטאו העם בסבה זה הטעות והנה יהיה כשישאלו ממנו שיורה אותם זה הדין ומזה המקום יתבאר שזה הדין יהיה כשטעה בהוראתו אם עשה על פי הוראתו כמו שקדם אמרו ועשה מאחת מהנה ושיהיה ראוי להוראה כי בזולת זה לא יתכן שיאשמו העם בסבת הוראתו והוא מבואר מלשון התורה שהוא ראוי שיהיה כהן משיח בעת שחטא ואז ינהג בו זה הדין. ובזה יתבאר ממנו שהוא ראוי גם כן שיהיה כהן משיח בעת שיקריב קרבנו ואז ינהג בו זה הדין:
@53 **והקריב על חטאתו אשר חטא פר בן בקר תמים ליי' לחטאת.** למדנו מאמרו תמים שלא יתכן בזה הפר שיהיה בעל מום. ולמדנו מאמרו פר שלא יתכן שיהיה עגל ומאמרו בן בקר שלא יתכן שיהיה זקן וכבר נתבאר מצד הוראת הגדר שזה השם לא יפול כי אם כאשר אין לו יותר משלש שנים ולא פחות משנה ומאמרו על חטאתו אשר חטא למדנו שהקרבת החטאת ר"ל שחיטתו וקבלת דמו והולכתו וזריקתו ראוי שתהיה לשם הבעלים ולשם החטא אשר עליו בא ומאמרו ליי' לחטאת למדנו שצריך שיקריבהו לשם הקב"ה ולשם החטאת וכבר למדנו שזה הדין נוהג בכל חטאת ר"ל שיהיה קרב לשם הבעלים ולשם החטא שעליו בא ולשם חטאת לפי שכבר נאמר בחטאת יחיד על חטאתו אשר חטא ושחט אותה לחטאת:
@54 **והביא את הפר פתח אהל מועד.** ר"ל מבוא אהל מועד והוא העזרה:
@54 **לפני יי'.** שיהיה ראשו לפאת מערב ששם קדש הקדשים באופן שיהיו פני הכהן לפאת מערב כשיסמוך ידו על ראש הפר. וכבר זכרנו בהם שקדם עניין הסמיכה ושיש עמה ודוי ושחט את הפר לפני יי' שיהיה ראשו לפאת מעב באופן שיהיו פני השוחט לפאת המערב כשישחט אותו:
@55 **מדם הפר.** מהדם שהוא דם הפר והוא דם הנפש לא דם העור ודם התמצית ומגיד שזאת הקבלה מצוותה בכהן משוח אך אין זה מעכב ר"ל שאם קבל דמו כהן הדיוט כשר שהרי אמר אחר כן וטבל הכהן ונתן הכהן והקטירם הכהן ולא זכר שם משוח ואין ראוי שידקדק יותר בקבלת הדם מזריקתו שהוא מהלך אל השלמות אל הקבלה. ואם אמר אומר שכבר הקפידה התורה שתעשה הקבלה על ידו ולא הזריקה כי בה תלויה הכפרה ואין ראוי שיהיה המכפר והמתכפר איש אחד בעינו אמרנו לו שכבר יראה דברי התורה הפך זה והוא שבעבודת יום הכפורים יכפר הכהן הגדול תחלה על עצמו ולא יתכן שתעשה העבודה ההיא על יד אחר כמו שירא' מלשון התורה כזה בפרשת אחרי מות והביא אותו אל אהל מועד. לפי ששם תהיה ההזאה על הפרוכת ועל קרנות מזבח הזהב וטבל הכהן את אצבעו בדם כבר התבאר בשרשים הכוללים כי זה האצבע הוא ימיני וכן הקבלה וההולכה והזריקה הוא בימין והזה מן הדם שבע פעמים לפני יי' את פני פרכת הקדש אחרי שטבל אצבעו בדם יזה מן הדם אשר באצבעו ולזה הוא ראוי שיהיה באצבעו כדי הזאה וכזה יעשה שבע פעמים ר"ל שיטבול אצבעו בדם ויזה באופן שיהיה כל הזאה טבילה ויהיו פניו למעבר בעת הזאתו באופן שתהיה הזאתו את פני פרכת הקדש ותהיה ההזאה נכח קדש הקדשים:
@57 **ונתן הכהן מן הדם על קרנות מזבח קטרת הסמים.** והם ארבע מתנות על ארבע קרנותיו וזה המזבח הוא מזבח הזהב שהוא באהל מועד ובו יקטירו קטרת הסמים לא זולת זה כמו שהתבאר במה שקדם ואמרו לפני יי' אין הרצון בו שתהיינה אלו הזאות הארבע לפני יי' כי זה בלתי אפשר אך היה בזה שזה המזבח הוא לפני יי' לפי שהוא סמוך לקדש הקדשים כמו שהתבאר במה שקדם ואולם מזבח העולה היה מחוץ לאהל מועד בעזרה:
@57 **ואת כל דם הפר ישפוך אל יסוד מזבח הועלה.** ר"ל הנשאר מדם הפר אחר אלו ההזאות. וכבר זכרנו במה שקדם מה הוא יסוד מזבח העולה. ומזה המקום למדנו זה הענין גם כן בשאר הקרבנות הנוהגים זה המנהג כמו פר יום הכפורים:
@57 **אשר פתח אל מועד.** ר"ל ממה שיהיה היסוד ההוא לפארת מבוא אהל מועד והוא יסוד המערבי:
@58 **ואת כל חלב הפר וגו'.** עד כאשר יורם משור זבח השלמים כבר נתבאר כל זה במה שקדם כאשר יורם משור זבח השלמי'. ידוע שזה לא יהיה צריך להזכיר להודיע מה ירים ממנו שכבר זכרו בזה המקום בשלמות כמו שזכר בשור זבח השלמים. ואמנם לבאר שזה יעשה בזה הקרבן לסבה בעינה שיעשה בשור זבח השלמים. וכן אמרו בספרא מה שלמים מביאי' שלום לעולם אף זה מביא שלום לעולם. וכבר נבאר זה בג"ה כאשר נבאר למה היו הקרבנות באופן שבאה המצוה בהם:
@61 **ואת כל עור הפר ואת כל בשרו על ראשו ועל כרעיו.** למה שמנה הראש והכרעים אחר כירתו כל בשרו. למדנו שכבר ינתחהו לנתחיו כמו העניין בעולה וזה כי הראש הוא נתח מהנתחים כמו שהתבאר במה שקדם וכן הענין בכרעים אין הבדל אלא שאלו הנתחים יעשו בזולת הפשט העור כי הם היו נשרפים עם עורם מה שאין כן בנתחי העולה:
@61 **קרבו ופרשו.** ר"ל הקרב עם פרשו מה שאין כן בקרב העולה שכבר היו מסירים את פרשו ורוחצין אותו כמו שהתבאר במה שקדם:
@62 **והוציא את כל הפר אל מחוץ למחנה.** ר"ל חוץ למחנה ישראל במקום שהיה שם היה נקרא בית הדשן ומגיד שאחר שקרעוהו והוציאו אימוריו והקטירום על מזבח העולה מוציאין אותו שלם חוץ למחנה ישראל ושם מנתחין אותו באופן שקדם ושורפים אותו שם ולפי שלא אמר והוציא הכהן למדנו שזאת ההוצאה כשרה בזר:
@62 **אל מקום טהור.** שיהא מקומו טהור:
@62 **אל שפך הדשן.** אל מקום ששופכין שם הדשן:
@62 **ושרף אותו על עצים באש.** מפני שלא אמר ושרף אותו הכהן למדנו שהשרפה הזאת כשרה בזר. ולפי שאמר על עצים ולא אמר על העצים. למדנו שאיזה עצים שיהיו כשרים לזה ואפילו קש וגבבה שהם נקראים עצים גם כן בלשוננו. ובכלל הנה כונת התורה להסיר היופי והנוי מזה החלק מזה הקרבן הנשרף בחוץ. ולזה לא רצה השם יתעלה שישרף בחוץ במקום בלתי קדוש עם עורו ועם פרשו ולא דקדק בשורפו שיהיה כהן. וזה יורה שכאשר אמר עצים הוא לכונה שלא יקפיד אי זה עצים שיהיו אלו העצים:
@62 **על שפך הדשן ישרף.** רוצה לומר על מקום ששופכין שם הדשן:
@63 **ואם כל עדת ישראל ישגו.** רוצה לומר כל ישראל או רובם וכבר יבאר אחר זה זאת השגגה איך תהיה:
@63 **ונעלם דבר מעיני הקהל.** הנה לפי שהעינים מורים לב"ח איזה הדרך ילך בה וישמרוהו מהכשל בהליכתו קרא עיני הקהל ב"ד הגדול כי הם המורים לכל ישראל אי זה הדרך ילכו בו בדרכי התורה כמו שהתבאר בפרשת זקן ממרא או יהיה הרצון באומרו אל כל עדת ישראל בית דין הגדול כי הוא כולל לכל ישראל. והנה מצאנו בתורה שקראה הבית דין עדה אמר ושפטו העדה. והצילו מעיני העדה להורות כי מבית דין ידבר. ולפי שאינם עיני הקהל אם אינם ראויים להוראה חוייב שיהיו כלם ראויים להוראה ואז ינהג בם זה הדין הנזכר פה ומזה גם כן יתבאר שהוא ראוי שיהיה נעלם מכלם לא מקצתם ואז ינהג בם זה הדין ואמרו ונעלם דבר רוצה לומר שיזכור אחר זה והם אשר לא תעשינה שחייבין על זדונם כרת כמו שבארנו ולפי שאמר ונעלם דבר חוייב שלא תעלם מהם כל המצות אבל דבר ממנה כאלו תאמר שיורו שהדם היוצא מהשחיטה הוא אשר אסרתהו התורה אבל דם הלב הוא מותר:
@63 **ועשו אחת מכל מצות יי' אשר לא תעשנה.** ר"ל ישראל שכבר זכרם בראש הפסוק או יהיה שב אל הקהל שזכר קודם תיבת ועשו. והנה הרצון בו כל ישראל לא קהל מקהלות ישראל כי כבר לקח העניין כולל בבית דין מפני כללות העושים על פיהם. ולפי שסמך העשייה להעלם הדבר מעיני הקהל הנה יחוייב שיהיה ההעלם ההוא סבת עשייתם זאת ההעברה. ואמנם זה יהיה כשיאמרו להם מותרים אתם לעשות זה. ואם עשו או ישראל כלם או רובם כי הוא בכם כמו שהתבאר בשרשים הכוללים מפני הוראתם זאת אך ינהג בהם זה הדין ולפי שאמרו ועשו שב אל הקהל או אל ישראל לא הב"ד הנה יתבאר שאם עשו בית דין על פי הוראתם לא ימנו עם העושים מישראל להשלימם לרוב ונודעה החטאת אשר חטא עליה ר"ל למי שהיה להם ההעלם נודעה שגג' ההוראה אשר חטאו עליה ישראל ועשו אחת מאלו העבירות החמורות והוא ראוי שתודע להם החטאת אחר שעשו כל ישראל או רובם על פיהם ואז ינהג בהם זה הדין לפי שכבר זכרם התורה זאת הידיעה אחר המעשה. וראוי שתודע להם החטאת ההוא בייחוד לא שיודע להם שטעו בדבר מה שהורו ולא יזכרו מעצמם איזה דבר הוא שנאמר ונודעה החטאת ולא שיודיעוה להם:
@64 **והקריבו הקהל.** ידוע כי השבט האחד נקרא קהל שנאמר ויעמוד יהושפט בקהל יהודה וכל ישראל גם כן קרוי קהל ואלו היה הרצון בזה כל ישראל לא היה צריך לומר כי אם והקריבו כי אמרו ועשו שב אל כל ישראל כמו שבארנו. ולזה יהיה אמרו והקריבו הקהל שב אל כל שבט ושבט ואם אמר אומרו שאם יהיה הענין כן יהיה כל קבוץ שבמקום מקו מעיירות ישראל מביא פר לפי שכל קבוץ מהם נקרא קהל אמרנו לו שזה בלתי ראוי וזה כי החלק כלל כל ישר' חלוקה ראשונה הוא לשבטים לא אללו הקהלות והנה יקריבו כל שבט ושבט פר אע"פ שלא חטאו כיון שחטאו רוב ישראל והנה שאר מה שבא בזאת הפרשה עד אשר נשיא יחטא מבואר ממה שזכרנו בפרשת כהן משיח בכל דבריו כי ענין זאת החטאת שוה לחטאת כהן משוח לכל דבריו כמו שנזכר בזאת הפרשה:
@72 **אשר נשיא יחטא.** ראוי שתדע כי נשיא השבט יקרא נשיא והמלך גם כן יקרא נשיא כאמרו ועבדי דוד נשיא להם לעולם. ויתבאר במה שיבא זה שהמאמר בזה המקום הוא במי שוהא מלך לא בנשיא השבט וזה שכבר לקח מן הכהנים מי שאין שם כהן עליו גדול ממנו והוא הכהן המשיח. ולקח מהב"ד ב"ד הגדול שאין עליו ב"ד. וראוי שיקח בכאן הנשיא שאין עליו אדם מישראל והוא המלך והוא מבואר מלשון התורה שזה הדין ינהג כשהיה נשיא ואחר כך חטא לא אם חטא ואח"כ היה נשיא ובזה יתבאר שאם עבר מנשיאותו אדם שיקריב קרבנו לא ינהג בו זה הדין:
@72 **ועשה אחת מכל מצות יי' אשר לא תעשנה.** כבר בארנו במה שקדם שהמאמר פה הוא למצות לא תעשה שחייבין על זדונן כרת שיש בהן מעשה:
@73 **או הודע אליו חטאתו אשר חטא.** עניינו והודע אליו חטאתו אשר חטא. למדנו מזה ממה שאמר בשגגת בית דין בהוראה ונודעה החטאת וכאשר תמצא גם כן בנפש כי לחטא מעם הארץ או הודע אליו חטאתו ועניינו בהכרח והודע. לפי שאם לא הודע לו לא יתחייב חטאת אבל יתחייב אשם כמו שאמר אחר זה ואם נפש כי תחטא וגו' ולא ידע ואשם וגו'. והנה הענין במלת או כמו העניין באות וא""ו זה כי אות וא""ו פעם עודפת ופעם עניינה עניין מלת או כמו אביו ואמו קלל ורבים זולתו וכן מלת או מחלקת ולפעמים עודפת וכבר מנה מהם ר' יונה מהמדקדק רבים. ועניין הודע אליו שיהיה ידוע אליו באי זה אופן שיהיה אבל אם לא היה ידוע לו אף על פי שהעדים מעידים שכן הוא לא יתחייב חטאת אם לא היה לבו סומך על דבריהם. וראוי שיהיה ידוע לו חטאתו אשר חטא בה אבל אם לא נודע לו אף על פי שנודע בודאי שחטא לא ינהג בו זה הדין משל זה אם היה חלב ונותר לפניו ואכל מהם בשגגה ואינו יודע אי מזה מהם אכל פטור מקרבן חטאת:
@73 **שעיר עזים זכר תמים.** זכר ולא נקבה ולא טומטום ואנדרוגינוס:
@73 **תמים.** ולא בעל מום וכבר יזכרו המומין הפוסלין בקרבנות במה שיבא:
@74 **וסמך ידו.** כבר ביארנו דיני הסמיכה ושהיא עם ודוי ועל ידי בעלים ולא על ידי זולתם:
@74 **ושחט אותה במקום אשר ישחט את העולה.** רוצה לומר לצפון העזרה ואמרו חטאת הוא רוצה לומ' שישחטוה לשם חטאת וכבר פירשנו במה שקדם איך ישחטנה לפני השם. וכן אמר בפרשה הבאה אחר זה ושחט את החטאת רוצהלומר שיהיה חטאת כשישחטוהו וזה אמנם יהיה כשישחטוהו לשם חטאת:
@75 **ולקח הכהן.** מקבלה ואילך מצות כהונה:
@75 **באצבעו.** רוצה לומר הימני וכן הקבלה היא ביד הימנית באופן הנהוג רוצה לומר בכלי וזה אמנם יהיה בכלי השרת:
@75 **על קרנות מזבח העולה.** הם ד' קרנות על ד' הזאות:
@75 **ואת דמו ישפוך אל יסוד מזבח העולה.** ר"ל הנשאר מדמו וכבר ביארנו באי זה חלק מהיסוד יהיה זה:
@76 **וכפר עליו הכהן מחטאתו.** שתהיה הכפרה לשם הבעלים ולשם חטאת:
@77 **ואם נפש אחת תחטא בשגגה מעם הארץ.** רוצה לומר שאינו מלך ולא כהן משוח:
@77 **בעשותה אחת מכל מצות השם אשר לא תעשנה.** כבר ביארנו שאלו המצות הם מצות לא תעשה שיש בה מעשה שחייבין על זדונו כרת וזה הדין. אמנם יהיה כשלא עשה זה על הוראת בין דין באופן הנזכר במה שקדם כי יפטר היחיד ויביא כל שבט ושבט פר כמו שהתבא' והנה הנמשך מזאת הפרשה עד ונפש כי תחטא ושמעה קול אלה מבואר ממה שקדם:
@86 **ונפש כי תחטא ושמעה קול אלה.** ר"ל שבועה או קללה בשם מן השמות הקדושים כי על כל אחת מאלו יפול שם האלה כבר תמצא בקללת סוטה שנקראת אלה ושם התבאר גם כן שהאלה היא שבועה וזה אמנם כשישביעהו בעל דין שיעיד לו אותו עדות שיודע לו. ולמדנו שזאת השבועה היא על פי בין דין ר"ל התובע ולפי שאמר והוא עד הנה יחוייב שיהיה ראוי לעדות לא קרוב או פסול או שומע מפי שומע ולפי שאין דבר העד עדות אל בפני בית דין הנה לא יתחייב העד אם לא יגיד חוץ לבית דין כי שם אין דבריו עדות אלא ספור דברים לבד ולא יתחייב גם כן אם לא היה שם עד זולתו כי דברי העד האחד אינה עדות על דרך האמת אם לא היה שם עד אחר זולתו שנאמר על פי שנים עדים אם שלשה עדים יקום דבר. וראוי גם כן שיהיה השומע הוא העד שנאמר ושמעה והוא עד רוצה לומר שיהיה עד בעת ששמע:
@86 **וראוי** גם כן שתהיה ספירתם העדות אחר שמיעת הקול שנאמר ושמעה קול אלה אם לא יגיד ולזה אם קדמו וכפרו ונשבעו שאין יודעין לו עדות לא ינהג בהם זה הדין. וראוי גם כן שתדע שזה הדין לא ינהג אלא בדבר של ממון ויהיה עם זה מטלטל וגופו ממון ולזה לא ינהג בעבדים ושטרות וקרקעות אף על פי שהם ממון באופן מה וזה יתבאר ממה שאומר אמנם לא ינהג אלא בתביעת ממון כי התורה אמרה והוא עד או ראה או ידע מכלל שהנושא אשה בו העדות יוכל להתקיים העדות בו בראייה שלא בידיעה ובידיעה שלא בראיה וזה שלא יתכן אלא בתביעת ממון. והמשל שכבר יראו עדים שראובן הלוה לשמעון ויעידו מה שראו או יודה בפניהם שמעון ויאמר להם שיהיו עדים לראובן שהוא הלוהו ויתבאר שלא ינהג זה הדין בקרקעות ועבדים ושטרות כי הוא ראוי שלא נחמיר בעדים יותר ממה שנחמיר בנתבע וזה שהנתבע לא יחוייב שבועה באלו הדברים אף על פי שיהיה מודה מקצת כמו שהתבאר בפרשת ואלה המשפטים ואם הוסר דין שבועה מהנתבע באלו הדברים כל שכן שראוי שיוסר מהעדים והוא מבואר שבשבועת העדות אין הבדל בהבאת הקרבן בין שוגג למזיד שהרי לא נאמר בה ונעלם ממנו כמו שאמר בשאר הדברים הנזכרים עמה וזה אמנם הוא לחייב על המזיד כשוגג ואם אמר אומר שלא יתכן שיבא קרבן על הזדון אמרנו לו שכבר מצאנו בשפחה חרופה קרבן על הזדון וכן הענין באשם גזלות הנזכר אחר זה ולזה נשפוט בזה המקום שיבא זה הקרבן גם על הזדון או נפש אשר תגע בכל דבר טמא לפי שלא זכר פרטי זה הכלל כי אם אבות הטמאות למדנו שאינו מדבר במגע וולד הטמאה וזה כי נבלות הבהמה והחיה והשרץ הם אבות הטומאה כמו שיתבאר:
@87 **ונעלם ממנו והוא טמא.** ר"ל שנעלם ממנו היותו טמא ואינו זכור שנגע באלו הטמאות והנה הוא עדין טמא ר"ל שלא טהר עדיין מטמאתו:
@87 **ואשם.** ר"ל שעשה מה שלא יתכן עשותו לטמא לפי משפטי התורה וזה אמנם יהיה אם כשנכנס למקדש או כשאכל קדש כי משני אלו נזהר הטמא כמו שיתבאר במה שיבא. והנה אף על פי שיש בזדון אלו העבירות כרת כמו שיתבאר במה שיבא הנה הבדילה התורה בין אלו העברות ושאר העברות שחייבים על זדונם כרת כי בשנים אלו יביא קרבן עולה ויורד ולא חלק בו בין נשיא ובין כהן משיח וכהן הדיוט:
@87 והנה אמר **בנבלת חיה טמאה** אף על פי שכל נבלת חיה היא טמאה להתנות שיהיה בה שעור טומאה והוא כזית כי פחות מכזית ממנה לא יטמא במגע וכן העניין במה שאמר בנבלת בהמה טמאה או בנבלת שרץ טמא או כי יגע בטומאת אדם לכל טומאתו אשר יטמא בה רוצה לומר הן טמאת מת הן טומאת זב וזבה ונדה ויולדת ובועל נדה ומה שידמה לזה:
@89 **או נפש כי תשבע לבטא בשפתי'.** לא שיגמור בלבו לבד ולא יוציא בשפתיו:
@89 **להרע או להטי'.** כמו שנשבע שאוכל ולא אוכל שארחץ ושלא ארחץ:
@89 **לכל אשר יבטא האדם בשבועה.** רוצה לומר לכל מה שדרך האדם לבטא בו בשבועה למנוע ממנו דבר מה או הפך זה וזה אמנם יהיה כשיוציא בפיו מה שגמר בלבו לא שיהיה בלבו דבר מתחלף למה שהוציא מפיו כי אין זה דרך האנשים לבטא בו באופן הזה וכ"כ בשבועה כי אז ידקדקו יותר שיהיה מה שהוציאו מפיהם לפי מה שבלבם ויתבאר עוד שזאת השבועה אמנם תהיה בדבור הרשות לא בדבר של מצוה כי אין הענין ההוא בבחירתו להתרחק ממנו ולהמשך אליו אבל יחוייב לו שינהג בו לפי משפטי התורה וכבר יתבאר זה עוד ממה שפירשה התורה באחד מנדרי אסר ר"ל בנזיר שהוא למנוע ממנו היין שאין שם מצוה תכריחהו לשתות יין או שלא לשתות ובכלל הנה זה ממה שאינו צריך אל ביאור. וזה שכבר אמר שהשבועה תהיה להרע או להטיב ואם היתה השבועה בקיום דבר מצוה הנה היא שבועת שוא אחר שאי אפשר לו לקיימה ואם אפשר לו לקיימה אינה להרע או להטיב כי בזולת השבועה היה מוכרח בזה. ואם היתה הבטול בדבר מצוה הנה היא שבועת שוא אחר שאי אפשר לו לקיימה כפי משפטי התורה ולזה יתבאר שאין שבועת בטוי נוהגת בדבר מצוה:
@89 **ונעלם ממנו.** ר"ל שנעלמה ממנו השבועה שזכר קודם זה:
@89 **ונעלם ממנו והוא ידע ואשם.** רוצה לומר שאחר שידע היותו טמא נעלם ממנו ואשם אם כשנכנס למקדש או כשאכל קדש ולזה יחוייב שתהיה לו ידעיה אחר ההעלם כי לולי הידיעה לא יתעורר להביא קרבן על חטאתו ולא יוכל להתודות אשר חטא ולזה יחוייב שתהיה לו ידיעה בתחלה וידיעה בסוף והעלם בנתים ואז ינהג בהם זה הדין:
@89 **והוא ידע ואשם.** ר"ל שכבר ידע קודם זה השבועה ואחר כך אשם כשנעלמה ממנו ועבר עליה או יהיה הרצון בזה שיודע אחר שנעלמה ממנו השבועה שעבר עליה מפני העלם ממנו השבועה כאלו תאמר שנשבע שלא יאכל תאנים ואחר כך נעלמה ממנו השבועה ואכל תאנים ואחר כך זכר ענין שבועתו ויתברר לו שכבר עבר עליה:
@89 **לאחת מאלה.** רוצה לומר לשבועת העדות או לטמאת מקדש או לטמאת קדשיו או לשבועת בטוי וזה יתבאר שאם עבר על כל אלו חייב על כל אחת ואחת ואין צריך לומר אם עבר על אחת מהם פעמים רבות באופן הנזכר שכבר יתחייב קרבן על כל פעם ופעם:
@90 **והתודע אשר חטא עליה.** ר"ל שיתודה בסמכו ידיו על ראש קרבנו כמו שהתבאר במה קדם וכבר קצרה התורה בזה להשענה על מה שכבר התבאר שהוידוי יהיה עם הסמיכה על ראש הב"ח:
@91 **והביא את אשמו ליי'.** שתהא הקרבתו לשם הקב"ה על חטאתו אשר חטא שיהיה לשם אותו החטא:
@91 **נקבה.** ולא טומטום ואנדרוגינוס:
@91 **לחטאת.** שיהיה מעשה לשם חטאת וכבר התבאר במה שקדם איך יעשה החטאת ויתבארו עוד דיניו במה שיבא:
@92 **ואם לא תגיע ידו די שה.** ר"ל שיהיה עני בעת הבאתו וכשיהיה העניין בזה התואר יביא שתי תורים או שני בני יונה ליי' וכבר קדם לנו מה הרצון בתורים ובני היונה:
@93 **והקריב אשר לחטאת ראשונה.** לפי שאין ראוי שיקריב העולה שהיא כמו דורון להשם יתעלה קודם התנקותו מחטאו' ולזה ראוי שיקדם החטאת לכפר חטאו ואחר כך יהיה מרוצה לשם יתעלה באופן שיתכן שיקח דורון ממנו:
@93 **ומלק את ראש ממול עורפו.** כבר נתבאר עניין המליקה במה שקדם וזאת המליקה תהיה בעזרה:
@93 **לא יבדיל.** היא מצות לא תעשה. ר"ל שלא יבדיל הראש מהעוף ההו' אבל יהיה מחובר עמו ולזה יתבאר שבמילקת עוף החטאת לא יצטרך לחתוך בצפורן כי אם סימן אחד או רובו ואולם במליקת העולה יצטרך לחתוך רוב הסימני' כמו הנין בבהמה לפי שלא שלל הכתוב ממנה אלא שלא יצטרך להבדיל כמו העניין בבהמה שיבדיל ממנה הראש בפני עצמו ואולם לחתיכת הסימנין בשחיטה יהיה עניינו בעניין עולת בהמה ר"ל שיצטרך לחתוך שני סימנין או רובם וזאת המליקה תהיה למטה כמו העניין בשחיטת הקרבנות כי לא זכרה התורה בזה דבר יחויב שתהיה מליקה נעשית למעלה אלא שכבר יראה שהיה תהיה לצד שהיתה אליו מליקת עולת העוף אין הבדל ביניהם אלא שמעשה העולה למעלה ומעשה החטאת למטה ושניהם היתה מליקתם לקרן דרומית מערבית וזה יתבאר ממה שנזכר בעולת העוף במעט עיון:
@94 **והזה מדם החטאת על קיר המזבח.** ר"ל על מה שהיה מהקיר אצל המולק והוא חלק התחתון ובכלל הנה הוא הקיר אשר יסוד המזבח סמוך לו שזכר אחר זה עד שהמקום אחד יזה אל הקיר וימצה שארית הדם אל יסוד המזבח ומזה המקום נלמד שההזאה לחטאת העוף היתה בחצי התחתון מהמזבח ואחשוב שזאת ההזאה לא היתה באורך כי אם ברוחב ולזה לא קרא ההזאה הזאת המצוי ר"ל שלא היה הדם נמצה בה מן העוף כמו העניין בעולת העוף אבל היתה בזריקה והיה ברחב כי הענין בזריקת דם עולת בהמה ומה שזה דרכו היה בחצי התחתון מהמזבח כמו שנבאר בנתינתנו סבת מעשה הקרבנות באופן שצותה התורה ואת השני יעשה עולה כמשפט. רוצה לומר כמשפט עולת העוף שזכר במה שקדם והנה אין למזבח חטאת העוף כי אם דמו והנה נבאר במה שיבא למה היה זה החלוף בין חטאת העוף ועולת העוף לחטאת בהמה ועולת בהמה רוצה לומר עולת בהמה היתה למטה והזאת חטאת בהמה למעלה ובעוף העניין בהפך:
@96 **ואם לא תשיג ידו לשתי תורים או לשני בני יונה והביא את קרבנו.** שהיה עני בעת הבאת קרבנו:
@96 **לחטאת.** שיהיו כל מעשיה לשם חטאת:
@96 **לא ישים עליה שמן.** זו מצו' לא תעשה שלא ישים עליה שמן כמו הענין בשאר המנחות שבאות נדבה:
@96 **ולא יתן עליה לבונה.** הוא גם כן מצות לא תעשה והנה סבת זה החלוף בין זאת המנחה ומנחת נדבה:
@97 **מלא קומצו.** התבאר במה שקדם איך תהיה הקמיצה:
@97 **על אשי השם.** רוצה לומר על מזבח העולה ששם מקריבין אשי השם. ואולם אמר אשי השם שלא יקדם הקטרת הקמץ לעולת הבקר ולא קרבן מהקרבנות כמו שהתבאר במה שקדם:
@97 **הוא.** כי חטאת היא. רוצה לומר שהיא באה חטאת ולזה הוסר הנוי והיופי ממנה:
@98 **והיתה לכהן כמנחה.** רוצה לומר שירי הקומץ נכפל לכהנים וראוי שתדע שאם היה החוטא כהן שאין מנחתו נקמצת אבל היא נשרפת כלה שנאמר וכל מנחת כהן כליל תהיה. ואולי זה הוא מה שרצה נאמרו והיתה לכהן כמנחה רוצה לומר שיהיה דינה לכהן כמנחה אם היה הוא המביא זה הקרבן וכבר התבאר דין מנחת כהן במה שקדם:
@100 **נפש כי תמעול מעל וחטאה בשגגה מכל קדשי השם.** רוצה לומר שנהנה מהם כאלו תאמר שאכל מקדשי השם וכבר יורה שהכונה בחטא הוא מה שאמרנו שהרי אמ' אחר זה ואת אשר חטא מן הקדש ישלם וזה אמנם יהיה בשני פנים אם שיחסר ההקדש בזאת ההנאה כמו שהמשלנו בענין האכילה או שלא יחסר ההקדש בזה אבל נהנה מה שיתנו בו האנשים כסף מה בשכירות כאלו תאמר שנשתמש בכלי הזהב שהם קדש להשם ולפי שבאופן הנהוג לא תמצא הנאה שיש עמה חסרון בהקדש כי אם בר החסר בעצמו כמו הענין באכילה יהיה מתנאי המעילה שהיא על הנאת הדבר הנפגם שתהיה הנאתו ופגמו בדבר האחד בעינו לא שיהיה פגם דבר ונהנה מדבר אחר זולתו והשעור הראשון שיהיה בזאת ההנאה היא שוה פרוטה כמו שהתבאר בשרשים הכוללים. וראוי שתדע כי קדשי השם יקראו קדשי בדק הבית וקדשי המזבח רוצה לומר מה שיזכה בו המזבח שיהיה קרב לשם לא מה שיאכלוהו הכהנים כי הם קדשי הכהן ולפי שאמר מקדשי השם למדנו שהם מצטרפים זה עם זה להשלים שעור מעילה ואפילו נהנה היום מקדש מה ולאחר ימים רבים נהנה מקדש אחר מצטרפים וכיון שמכלם נהנה שוה פרוטה מעל:
@100 **והביא את אשמו לשם.** שיהיה לשם הקב"ה:
@100 **איל תמים.** שלא יהיה בו מום:
@100 **מן הצאן.** ולא מן העזים:
@100 **בערכך כסף שקלים.** לפי שהרבוי הראשון הוא שנים הנה הרצון בו שני שקלים רוצה לומר שיהיה ערך האיל שני סלעים של כסף צרוף והנה שקל לפי הוראת הגדר הוא ב"ד מעין וכל אחד מהם היה משקלו י"ח גרגירי שעורה:
@100 **לאשם.** ר"ל שיהיה שוה שני סלעים בעת היותו לאשם וכן בעת ההבאה ראוי שיקנהו שתי סלעים או יותר כי התורה הקפידה שיביאהו בערך כסף שקלים:
@101 **ואת אשר חטא מן הקדש ישלם.** רוצה לומר מה שנהנה ממנו:
@101 **ואת חמישיתו יוסף עליו ונתן אותו לכהן.** ידוע שאין נותן חמישית לבד לכהן אבל מה שישלם מאשר חטא מן הקדש הוא גם כן נתן לכהן ולזה יהיה הרצון בזה שמה שיתן לכהן יוסף חמישיתו על אשר חטא מן הקדש. ולזה אם נהנה מן הקדש ארבעה סלעים משלם חמשה סלעים כי החמשה סלעים מוסיפים חמישיתם על ארבעה סלעים. ואמנם זכר תחלה זאת אשר חטא מן הקדש ישלם להורות כי הקרן יעכב הכפרת לא החמש. וראוי שיהיו התשלומי' קודם הבאת האשם כי איך יתכפר לו והוא מחזיק בחטא. ולזה אמר אחר השתלומין והכהן יכפר עליו באיל האשם וראוי שתדע כי אשם נקרא מה שהחזיק בו שלא כדין אמר בפרשת נשא בגזל הגר והשיב את אשמו בראשו וחמישיתו יוסף עליו. ולזה יתבאר שאמרו איל אשם יתבאר ממנו שכבר אפשר שיקריב אחר שלום הקרן שהוא האשם ולזה יחסו איל האשם כי האשם מעכב הכפרה לא חומשו. והנה יושוו בזה הדין הכהן המשיח והנשיא והדיוט כי התורה לא חלקה ביניהם בזה:
@102 **ואם נפש כי תחטא ועשתה אחת מכל מצות השם אשר לא תעשינה.** כבר ביארנו במה שקדם שאלו המצות הם מצות לא תעשה שיש בהם עשה שחייבין על זדונו כרת והנה במצות ההם בעינם ידבר בזה המקום לפי שכבר ביאר דינם כאשר נודעה החטאת ועתה יבאר דינם כשלא נודעה החטאת שנאמר ולא ידע ואשם ולפי שלא ביאור הכתוב בזה דין בית דין שטעו בהוראה ועשו הקהל על פיהם ודין כהן משיח שהורה בטעות ועשה על פי הוראתו הנה לא ינהג דין אשם תלוי בהם אם לא נודעה להם החטאת אבל הנשיא יתחייב באשם תלוי כמו ההדיוט לפי שלא חלקה התורה בזה בין הנשיא וההדיוט ר"ל בשגגה המעשה. ואולם בשגגת ההוראה לא זכרה דבר בזה ולזה לא ינהג זה הדין בשגגת הוראה וענין זה הקרבן הוא שנזכר שעבר בשגגה על ספק עבירה מהעברות הנזכרת ולפי שבנושא ההוא בעינו שזכר כשנודעה החטאת ידבר בזה המקום והיה האסור קבוע במה שנפל לו בו הספק והמשל שיהיו לניו שתי חתיכות אחת של חלב ואחת של שומן ואכל אחת מהם בשגגה ואחר זה זכר שחת מהם חלב ונסתפק לו אי זה מהם אכל ואולם אם לא היתה שם כי אם חתיכה אחת ואכלה ואחר כך זכר שהוא ספק חלב ספק שומן הנה לא ינהג בזה דין אשר תלוי לפי שלא היתה שם בודאי אחת מכל מצות השם אשר לא תעשנה בערכך לאשם קצרה התורה בזה להשענה על הערך הנזכר באשם הוא כסף שקלים על שגגתו ששגג ולא ידע יתבא' מזה שהוא חייב על כל שגגה ושגגה שנזכ' שעבר על ספר עבירה מאלו העבירות אשר הוא אשום אשם לה. ר"ל שזה האשם הוא על אשר אשם להש"י בשלא נשמר במה שיעשה אותו שלא יהיה בו עבירה או ספק עבירה בכמו אלו העבירות הגדולות:
@106 **נפש כי תחטא ומעלה מעל בה' וכחש בעמיתו.** ולא לגבוה ולא לנכרי:
@106 **בפקדון.** שהפקיד לו והוא הממון שראוי שיהיה בעין ולא ישלח בו יד הנפקד:
@106 **או בתשומת יד.** רוצה לומ' מלוה וקראהו תשומת יד לפי שהושם לוח יד בה רוצה לומ' שנתן לו רשו' להוציאה למה שיצטרך לו ואחר יפרעה אל המלוה:
@106 **או בגזל.** הוא הדבר הנגזל שלקח מיד הבעלים בחזקה:
@106 **או עשק את עמיתו.** כאלו תאמר שכבש שכר שכיר ומה שידמה לזה למה שיחזיק בו שיש לאחרי' חוק עליו ולא בא לידו מביתם אבל הם יודעים זה:
@107 **או מצא אבדה וכחש בה.** הוא דבר שיש לאחרים חק עליו ולא בא לידו מביתם והם אינם יודעים בזה. ובזה נכלל כל דבר שבממון שיהיה לאדם מרעהו והקדימה התורה זכירת הפקדון והמלוה לפי שהוא יותר נמצא ואח"כ זכרה הגזל והעושק ששניהם יודעים בו ואח"כ זכרה ענין האבדה שאין יודע בה כי אם מצאה:
@107 **וכחש בה ונשבע על שקר.** רוצה לומר שנשבע שאין בידו כלום ויהיה נשבע על שקר. ר"ל שיהיה יודע ששקר הוא מה שנשבע עליו הוא כפירתו הממון. ולזה יחוייב שיהיה מזיד בממון:
@107 **על אחת מכל אשר יעשה האדם לחטא בהנה.** עניינו כמו אשר חטא מן הקדש והרצון בו שיהא נהנה ממון מפני כפירתו כמו שזכר בפרטי זה העניין דבר שבממון. ואולם בשאר הדברים שאינם ממון לא ינהג זה הדין והנה יתבאר ממה שאמר על אחת שכל אחת ואחת מאלו השבועות אשר בזה התאר יתחייב זה הקרבן ושלא יתחייב על השבועה האחת אפילו שהיא לדברים רבים יחד בזה התואר או לאנשים רבים כי אם קרבן אחד והנה יתבאר שזה הדין לא יהיה אלא בדבר המטלטל ויתבאר שה הדין אינו בקנסות לפי שאין כפירתו מועילה לו בזה כי אפילו אם יודע יפטר כמו שיתבאר בפרשת ואלה המשפטי' והוא מבואר שאין זה הדין נוהג בקרקעו' ולא בשטרות אף על פי שהן מטלטלין לפי שאין גופן ממון ולא בעבדים לפי שדינן ודין הקרקעות אחד וזה כי הקרקע לא יתכן בה הכפירה והגזל כי הוא לפני בעליו בחזקתו. וכן העבדים לא תתכן בהם חזקה תוציאם מיד הבעלים כי להם בעצמם התחלת תנועה בחירית לשוב אל אישם הראשון והוא עוד מהדברים שלא יתכן בהם כפירה כי ישלו קול עם שהעבד בעצמו יגיד העניין:
@108 **והיה כי יחטא ואשם.** ר"ל כאשר יתן אל לבו שחטא ואשם בזאת הכפירה והשבוע' עליה הנה יתכפר לו בזה האופן שזכר רוצה לומ' שישיב הממון שכחש בו לבעלי' בתוספת חומשו ואחר יביא איל תמים לאשם. וראוי שתדע שזה אמנם יהיה כשיודה מעצמו שיש בידו הממון ההוא אבל אם העידו זה עדי' והוא מכחישם לא ישלם אלא הקרן כי אולי היה יודע ששבועתו תהיה שקר ושכח שיהיה לאיש ההוא הממון בידו וכבר חייבה התורה שיהיה יודע בעת שנשבע שהא נשבע על שקר או מכל אשר ישבע עליו לשקר ממה שידמ' לאלו הפרטי' כאלו תאמ' שנתחייב לו ממון מפני פירו' שמכר לו או מפני ירושה או עסק שנתן בידו להתעסק בו בסחורה ישבע עליו לשקר רוצה לומר שידע ששקר נשבע בעת השבועה ושלם אותו בראשו וחמישיתו יוסף עליו לאשר הוא לו יתננו ביום אשמתו אין בספק שאמרו לאשר הוא לו יתננו אינו שב אל חמישית לבד כי הקרן יותר ראוי שיאמר בו זה המאמר כי בו יתכן שיאמר לאשר הוא לו ולזה יהיה הרצו' בזה שיהיה מה שישלם נוסף חמישיתו על הקרן שהוא הראש ומזה יתבא' שיחוייב לו שישיבהו לבעלים לא לזולתם קודם שיביא קרבנו שנאמר לאשר הוא לו יתננו ביום אשמתו לא לבנו ולא לשלוחו ואת אשמו יביא לה' איל תמים מן הצאן בערכך לאשם רוצה לומר בערכך שני שקלים ויתבאר שלא יתכן להביא הקרבן קרבן השתלומין כמו שהתבאר בקרבן מעילה ולפי שזכר בזה המקום תחלת התשלומין ואח"כ הבאת האשם ויתבאר שאין החמש מעכב מקרבן מעילה שראוי שיהיה הבאת החמש בו יותר חמור לפי שהוא להקדש ועם כל זה איננו מעכב ועוד שכבר אמר בזה המקום והשיב את הגזלה אשר גזל וגו'. וזה ממה שיורה שלא הקפידה התורה שישלם קודם הבאת קרבנו כי אם הקרן ועוד שאמר לאשר הוא לו יתננו יאות לפי הלשון על הקרן לבד:
@111 **וכפר עליו הכהן לפני יי'.** רוצה לומר שיקריבהו הכהן על מזבח העולה כמשפט האשם:
@111 **לאשמה בה.** עניינו כענין לחטא כהנה כי אשם וחטא אחים ויאמר כל אחד מהם על מה שנהנה מהם האדם או יעכב בידו מזולתו שלא כדין אמר בגזל הגר על קרן הגזלה אשם ואמר בפרשת מעילה אשר חטא מן הקדש והנה נלמד מאמרו לאשמה בה לחטא בהנה שאם היה הממון ההוא פחות משוה פרוטה לא יתחייב עליו אשם ולא תוספת חומש וזה יתבא' מהשרשי' הכוללים כי פחות משוה פרוטה אינו נערך בין בני האדם כלל כי אין שם כסף יהיה מחירו:
@144 **ראוי** שתדע כי בעולה התדירה דבר בזה המקו' כי הוא אשר ימצא שיתאכלו אבריה בכל לילה ולילה והוא תמיד של בין הערבים ואמנם תמיד של שחר זכר בסוף כאמרו ובער עליה הכהן עצים בבקר בבקר וערך עליה העולה וזאת תורת החטאת וזאת תורת האשם ראוי הוא להשלי' ביאור מה שזכר מהם כפרש' הקודמת הנה יחוייב שיהיה עניין תמיד של בין הערבים נרמז בפרש' הקודמת ולזה ביארו רבותינו שאמרו בעניין העולה בפרש' הקודמת. ונתנו בני אהרן הכהן אש על המזבח וערכו עצים על האש. שב לתמיד של בין הערבים. וזה יתבאר עוד כי לא מצאנו עריכת העצי' רק בעבור התמידין ולפי שמצאנו זה בזה המקום בלשון יחיד ושם בלשון רבים והיה מה שבזה במקום לתמיד של שחר ידענו כי מה שנזכר במקום ההוא איננו לתמיד של שחר ולזה יהיה לתמיד של בין הערבים ובכלל הנה תמיד של שחר ותמיד של בין הערבים לפי שהם מכוונים לדבר אחד בעינו. ראוי שלא יתחלפו זה מזה בענין עריכת עצים ר"ל שלכל אחד מהם יערכו עצים והסבה בחיוב זאת העריכה בשניהם היא אחת כמו שהתבאר מדברינו במה שיבא וגם כן מפני שאמ' על מוקדה הנה ראוי שיהיה שם מוקד שמיוחד לה לבד וזה אמנם יהיה העצים הנערכים על האש שעליהם ישימו איברי העולה ופדרה ולפי שאמר היא העולה על מוקדה על המזבח למדנו שהיא אחרונה לכל הקרבנות הקרבים ביום ההוא אלא אם יביא בה הכרח שיקרב אחריה קרבן אחר כמו הענין בקרבן פסח שהיה קרב אחר תמיד של בין הערבים ולמדנו מזה שמהפכין כל הלילה באיברי' שלא התאכלו עד הבקר כי אף על פי שהקרבת הקרבנות לא תהיה בלילה כמו שהתבאר מהשרשים הכוללים הנה עכול מה שהקריב ביום ישלם בלילה וזה כולל לעות התמיד ולשאר הקרבנות כי אין ראוי כשיקריבו עולת בין הערבי' שיוציאו משם איברי שאר הקרבנות אבל ראוי שתשלם שם הקטרתם כמו שצותה התורה ואש המזבח תוקד בו רוצה לומר שעם זה המוקד שיהיה יוקד במזבח כל הלילה לעכול הקרבנות היה שם מוקד אחר יוקד בו והוא האש שיקחו ממנו אש למזבח הקטרת כי כבר התבאר הפרשת אחרי מות כי מעל מזכה העולה יקחו מלא המחתה גחלי אש וראוי היה שיהיה זה האש מערכה בפני עצמה כי כבר צוה השם יתעלה שלא יקטיר בו מכל הקרבנות זולתי הקטרת הסמים ואם היה שיקחו זה האש מהמערכה אשר יקריבו עלית הקרבנות לא היו נמלטים שלא יתערב במחתה דבר מה מאברי הקרבנות המאוכלים ויתבאר שזאת המערכה השנית היתה למערב מזבח העולה לפי שאמר בפרש' אחרי מות ולקח מלא המחתה גחלי אש מעל המזבח מלפני השם למדנו שזה האש ייוחד מהאש האחר מהמערכת הגדולה שהיא לפאת מערב וראוי היה להיות כן למעלת הקטרת על הקרבת שאר הקרבנות הנה כמו שיחדה לו התורה מזבח בפני עצמו יותר קרוב לקדש הקדשים כן יחדה לו התורה מערכת האש יותר קרבה לקדש הקדשים ולזאת הסבה בעינה היה ראוי שיהיה הדלקת המנורה מזאת המערכת השנית ולמדנו מזה שאמו תוקד בו שאין הרצון שיציתו האש למטה ויביאוהו אל זאת המערכה אבל יחוייב שתהיה הצתתו בגוף המזבח:
@145 **ולבש הכהן מדו בד ומכנסי בד ילבש על בשרו והרים את הדשן.** למדנו שהרמת הדשן היא עבודה מן העבודות ולזה דקדקה התורה שתהיה על ידי כהן ובבגדי כהן ולא זכרה הורה כל הבגדים להשענה על מה שנזכר בבגדי כהונה שלא ישרתו כי אם בהם ולזה יחוייב שתהיה זאת בבגדי כהונה בכללם ואמנם הוצרכה התורה להזכיר בכאן לבישת בגדי כהונה לפי שהיה עולה על הדעת שלא תהיה העבודה בבגדי כהונה שלא יתלכלכו הבגדי' ההם בדשן המזבח:
@145 **והרים את הדשן אשר תאכל האש.** עם העולה יחד הם הגחלים העליונים אשר איברי העולה סמוכים להם ולזה יהיה זה הדשן הגחלים הפנימיות ואולם הרמת זה הדשן הוא כשיחתה הגחלים העליונים עם איברי העולה אילך ואילך עד שיראו הגחלים הפנימיות עממיות והוא הדשן הנזכר בזה המקום הולכת העצים אינה צריכה כהן:
@145 **ושמו אצל המזבח.** ר"ל שיקחהו במחתה ויורידהו וישימהו אצל המזבח במה שנזכר במה שקדם שהוא מקום דשן והוא אצל מזרח המזבח:
@146 **ופשט את בגדיו ולבש בגדים אחרים.** ראוי שנדע שאלו הבגדים האחרים הם בגדי כהונה גם כן שאם היתה הכונה שלא יצטרכו בגדי כהונה בז לא היה צריך לומר כי אם ופשט את בגדיו והוציא את הדשן ועוד שאמרו אחרים יחוייב שיהיו ממין הבגדים הראשונים ואולם אמרה התורה שילבש בגדי כהונה אחרים שיהיו פחותים מהראשונים להורות שזאת העבודה היא למטה מהעבודה הראשונה:
@146 **והוציא את הדשן אל מחו למחנה אל מקום טהור.** ר"ל האפר אשר על המזבח הנאכל בשלמו' כי הגחלים העליונים ואברי העולה ישארו שם וזה האפר יוציאוהו מחוץ למחנה אל מקום שפך הדשן הנזכר בפרשת ויקרא אל מקום טהור שאם היה טמא יטהרנו והאש על המזבח תוקד בו רוצה לומר שאחר זה יעשה שתוקד אש על המזבח בו בעצמו לא שיציתו האש למטה יעלוהו שם וזה אמנם יהיה כשיערכו שם העצים וידליקום שם וראוי שיהיו פני המדליק לפני יי' שהוא לצד המערב כי כבר דקדקה התורה בזה בכל הענינים כמו שתראה ומפני זה יהיה התחלת הבערתה מפאת מזרח של המערכה:
@147 **לא תכבה.** הוא מצות לא תעשה והמכבה לוקה:
@147 **ובער עליה הכהן עצים בבקר בבקר.** ר"ל על האש המערכה והם שני גזירי עצים שהיה מביא לערוך עליהם העולה באופן שתהיה העולה על העצים ולפי שלא התנה שיהיה שם כהן כי אם בהבערת העצים למד בו שהולכת העצים אינה צריכה כהן:
@147 **וערך עליה העולה והקטיר עליה חלבי השלמים.** למדנו מזה שהעולה היא ראשונה לכל הקרבנות רוצה לומר עולת התמיד ועליה יהיו שאר הקרבנות יאמר בזה המקום והקטיר עליה חלבי השלמים ואמר בפרשת ויקרא בחטאת ובמנחת חוטא והקטיר המזבחה על אשי יי':
@148 **אש תמיד תוקד על המזבח לא תכבה.** היא מערכת שלישית יערכנה באופן שתוקד על המזבח כמו שקדם במערכות האחרות והנה זה ראש לא ישמש דבר אלא שהוא שם תמדיי לא תכבה היא מצות לא תעשה והמכבה אותו לוקה ושתקה התורה מהזהיר על כבוי אש המערכה השלישית היא לצורך מזבח הקטרת לפי שהענין קל וחומר רוצה לומ' שאחר שהזהיר על האש שישתמשו בו במזבח העולה שלא יכבהו כל שכן שתקפיד התורה באש שישתמר בו למזבח הקטרת שהוא יותר נכבד:
@149 **וזאת תורת המנחה הקרב אותה בני אהרן.** ראוי שתדע שזאת ההקרבה כוללת קבלת המנחה בכלי שרת והולכתה לפני המזבח כמו שההקרבה הנזכרת בראש ויקרא כוללת קבלת הדם והולכתו למזבח כמו שבארנו שם ובכלל הנה לא מצאנו במנחה שיהיה רשות לבעלים כי אם להביאה אל הכהן וזה לאות כי מה שאחר ההבאה ההיא לא יהיה כי אם על ידי הכהן ובכלל הנה מתנאי ההקרבה אל המזבח שיהיה מתקבל בכלי ובכלי ההוא יוליכה והנה זה הכלי יחוייב היותו מכלי שרת:
@149 **לפני יי' אל פני המזבח.** הנה מפני שפני המזבח הם לדרומו כי שם היה הכבש הוא מבו' שאם היתה ההגשה שם לא תהיה לפני יי' שהוא למערב ולזה יחוייב שתהיה ההגשה באופן שתהיה לצד המערב שהוא לפני יי' ותהיה ההגשה עם זה אל פני המזבח שהוא הדרום וזה אמנם ישלם כשתהיה ההגשה על קרן דרום מערבית על חודה של קרן כשילך הכהן ופניו למערב לפאת דרום עד שיגיע שם:
@150 **והרים ממנו בקמצו וגו'.** כבר בארנו במה שקדם זאת הקמיצה איך תהיה וששיעור הלבונה הוא ג"כ קומץ והנתרת ממנה יאכלו אהרן ובניו מפני שאמר זה אחר אמרו והקטיר המזבח למדנו שלא יותירו שירי מנחה לכהנים כי אם אחר הקטרת הקומץ והלבונה והקדים אהרון לבניו ללמד שכהן גדול נוטל חלק בראש:
@151 **מצות תאכל במקו' קדוש בחצר אהל מועד יאכלוה.** הוא לפנים מן הקלעים וצוה השם יתעלה שיאכלוה מצות לא חמץ. כמו שאמר אחר זה לא תאפה חמץ וזה המאמר אמנם הוא בשירי המנחות ולזה הוא מבואר שהאופה חמץ שירי המנחה לוקה וכן המחמץ אותה כי התורה זכרה אחד ממעשה תקון החמץ וחייבה עליו והוא הדין בשאר המעשים ויורד שכן הוא שכבר אמר במנחה במה שקדם לא תעשה חמץ ואמנם זכר הנה האפייה לחייב על כל מעשה ומעשה ואמר במנחה במה שקדם כל המנחה אשר תקריבו ליי' לא תעשה חמץ וזה כולל הקומץ ושירי המנחה ולזה יחוייב מלקות על אי זה מהם שיהיה אם עשאו חמץ:
@152 **חלקם נתתי אותה מאשי קדש קדשים היא בחטאת וכאשם.** שהם קדש קדשים כל זכר בבני אהרן יאכלנה פרט לבנות אהרן. והנה למדנו מזה שאפילו בעלי מומים חולקין בה לפי שהם ראוים לאכילתה חק עולם לדורתיכם מאשי יי' הנה אין הכהנים זוכים בה אם לא אחר שיתוארו כשהם אשי יי' וזה יהיה אחר שהוקטר במזבח הראוי לו:
@153 **כל אשר יגע בהם יקדש.** למדנו שאין זה אלא מפני מה שנבלע מהם בדבר הנוגע בהם ולפי שהוא קדש הנה יהיה בקדושה ההיא הדבר שנבלע בו דבר ממנו והנה למדנו זה ממה שאמר בחטאת מזה הענין כמו שיתבאר במה שיבא זה קרבן אהרן ובניו אשר יקריבו ממנו ליי' ביום המשח אותו למדנו שבזה הקרבן ישוה בהן כהן המשיח לכהן הדיוט ולפי שאמר אחר זה והכהן המשיח תחתיו מבניו יעשה אותה חק עולם למדנו שאין זה נוהג אלא בכהן משיח שאם היה נוהג בכל כהן לא היה צריך לזכור זה וזה הפך מה שנזכר קדם זה ולזה יתבאר שהיותר תמידיי הוא מיוחד בכהן משיח ואולם בעת החנוך ישוו בזה כהן משוח לכהן הדיוט ולזה זכר ביום המשח אותו שמורה על חנוך הכהן הגדול והכהן ההדיוט ואף על פי שאינו נמשח הנה עת התחנכו דומה ליום המשח של כהן גדול וראוי שתדע כי לא יתכן שיאמר ביום המשח אותו בעבור כהן גדול כי אין זה הקרבן מיוחד בו ביום המשיחה לבד אבל הוא תמידיי ויתבאר עוד שתמידות זאת המנחה אינו נוהג כי אם בכהן גדול כי לא מצאנו דבר מהענינים התמידיים בבקר ובערב במקדש שהיה נכפל וזה מבואר מאד במנורה ובהקטרת הסמים ובתמידים ולזה יחוייב שיהיה זה נוהג מנהגם רוצה לומר שלא יעשה ממנו כי אם אחר לא הרבה כמו שהיה מחוייב אם יעשה אותו כהן גדול ומזה המקום יתבאר שאין מתנאי זאת המנחה התמידיית שיהיה המקריב אוו כהן משוח אבל תנהג בכל כהן גדול ואמנם זכרה תורה משוח לפי שמדרך כהן גדול שיהיה נמשח בשמן המשחה עשירית האיפה סלת מנחה תמיד מפני שזכר סלת שיורה על הקמח היותר יפה הנה הוא מבואר שזה יהיה מן החטים וכן הענין בשאר המקומות אשר זכרה התורה סלת וראוי שיקחוהו מהחטי' היותר משובחים להמשך לכוונת התורה שיהיה זה קרבן היותר נבחר שאפשר מחציתה בבקר ומחציתה בערב למדנו שהיא קרבה חציין ולזה אם אבד או נטמא המחצית האחד יחוייב שיביאו עשרון אחד ויחצו אותו לשניים ומחציתו יקחו באופן שיהיה זה הקרבן בבקר ובערב מחצית העשרון והוא מבואר מענין זה הקרבן שאף על פי שמת כהן גדול לא תפסק הקרבתו עד שימנו כהן גדול אחר כי זה הקרבן צוה להיות תמידיי ותמידותו ידמה שינהג מנהג שאר הדברים התמידיים במקדש שלא יפסק עניינם מה שהתמיד העבודה במקדש וראוי שתדע שאמרו מחציתה בבקר ומחציתה בערב יהיה במנחה התמידיית והיא מנחת כהן גדול לא במנחת כהן הדיוט והנה המנחה ההיא תהיה עשירית האיפה כי אין שם שיעור במנחה יותר קטן לפי מה שהתבאר בתורה על מחבת בשמן תעשה לפי שכבר נתבאר במנחת מחבת שהוא סלת בלולה בשמן יהיה אמרו בשמן בזה המקום מורה על שמן אחר יקבלוהו במחבת ואופן הטגון בזה האופן שתבאר מן החוש שישלם בשלשת לוגין לעשירי' האיפה מורבכת תביאינה רוצה לומ' שקודם שתשימנה על מחבת תהיה מורבכת וזה יהיה כשתהיה חלוטה ברותחין החלה הבלולה בשמן ואחר כך יקלוה מחבת בשמן תופיני הרצון בו לפי הוראת הגדר מה שהוא ממוצע בין בשל ונא מנחת פתים שיהיו פותחין החלות האלו ולפי שכבר ידענו שמנחת מחבת היא מנחת פתים יהיה אמרו פתים בזה המקום מורה על עניין אחר לפי שכבר הקפידה התורה שיהיה זאת המנחה קרבה חציין למדנו שאמרו פתי' בזה המקו' הוא שלא תהיינה שם בבקר כי אם חצי החלות ובערב חצייהם הנשארים כאלו תאמר שיחצו כל חלה וחלה ויקחו החי האחד ממנה בבקר והחצי האחר בערב ולפי עניין זאת המנחה התמידית נלמד שהיא נעשית שתי' עשרה חלות שכן מצינו בלחם הפני' שידמה היותו לזאת הכוונה בעינה שהיא שתים עשרה חות וזה יתבאר ממה שאמרנו בזה בפרשת ויקחו לי תרומה:
@156 **תקריב ריח ניחוח ליי'.** ראוי שתדע שכבר יהיה עמה קומץ לבונה והיא גם כן חציין חציין קרב כי כבר זכרה התורה באלו המנחות שתבא עמהם לבונה וזה כולל לכל המנחות אלא אם תבאר התורה שלא יתן עליה לבונה כמו שבארה במנחת חוטא ולפי שזכר אהרן שב לבאר שזה ינהג בכל כהן גדול ולזה אמר והכהן המשיח תחתיו מבניו יעשה אותה רוצה לומר שיהיה נבחר לכהן גדול מבניו שהם הכנים הדיוטים:
@157 **חק עולם ליי' כליל תקטר.** רוצה לומר שלא ירימו ממנו קומץ אבל עולה כולה כליל ולפי שאמר חק עולם ליי' למדנו שאין להקרבתה הפסק ולזה חוייב כשמת כהן גדול שיקריבוה יורשיו עד שיתמנה כהן גדל אחר:
@158 **וכל מנחת כהן כליל תהיה לא תאכל.** רוצה לומר שאין מקריבין ממנה קומץ ויאכלו השירים כמו הענין במנחת ישראל אכל עולה כלה כליל והאוכל ממנו עובר על לא תעשה שנאמר לא תאכל וזה אמנם יהיה במנחת כהן לא במנחת כהנת:
@160 **זאת תורת החטאת במקו' אשר תשחט העולה תשחט החטאת.** רוצה לומר בצפון העזרה כמו שאמר במה שקדם על ירך המזבח צפונה לפני יי'. ולמדנו מזה שמקום שחיטת כל עולה וחטאת היא בצפון העזרה:
@160 **לפני יי'.** רוצה לומר שתהיה השחיטה לפני יי' וזה ישלם כשיהיו פני הנשחט ופני השוחט לצד קדש הקדשים:
@160 **קדש קדשים הוא.** למדנו מזה שכבר דקדקה התורה שתהיה שחיטתה בצפון מפני היותר קדש קדשים ומזה המקום יתבאר שכל מה שהוא קדש קדשים תהיה שחיטתו בצפון ושמה שאינו קדש קדשים לא נקפיד בו שתהיה שחיטתו בצפון:
@161 **הכהן המחטא אותה יאכלנה.** ראוי שתדע שאין הכונה בזה שלא יאכל ממנה כי אם הכהן המקריב אותה כי כבר אמרה בפרשת אמור אל הכהנים בבעל מום לחם אלהיו מקדשי הקדשים ומן הקדשים יאכל שהוא מבואר שהוא אינו ראוי להקריב ועוד שכבר אמר בזה המקום חלק כחלק יאכלו שירה כי הכהנים חולקים ביניהם מה שיזכו בו מהמתנות רוצה לומר אנשי בית אב של אותו היום ועוד שאם היה כן לא יתכן שתצוה התורה שלא יותירו ממנה. כי אי אפשר לפי הנהוג שיאכל אדם אחד כל בשר בהמה אחת בסעודה אחת או בשתים ולזה תהיה הכונה בזה הכהן שראוי לעבודה להוציא את הטמא ולא להוציא בעל מום מפני מה שנזכר בפרשת אמור אל הכהנים כמו שזכרנו:
@161 **במקום קדוש תאכל בחצר אוהל מועד.** הוא לפנים מן הקלעים:
@162 **כל אשר יגע בבשרה יקדש.** לפי שזכר בשרה שיבלע ממנו דבר הנוגע בו למדנו שמצד הבליעה הקפידה התורה בזה ולזה לא ינהג זה בנגיעה שתהיה בעצמות החטאת וגידיו הקשים ומזה המקום יתבאר שלא יקדש להיותה כמוה רק שיהיה נבלע בו ממנה דבר והטעם כי דבר הבלוע הוא קדש קדשים ולזה ינהג זה הדין בדבר שהוא בלוע בו וזה מבואר שזה ראוי שינהג בכל הקדשים רצוני' לומר שאם נבלע מהם דבר יהיה עליו חומר מה שהוא נבלע בו:
@162 **ואשר יזה מדמה על הבגד אשר יזה עליה.** מפני שאמר מדמה אשר יזה עליה למדנו שזה יהיה קודש ההזאה ובדם הראוי להזאה והוא הדם שיקבלו בכלי שרת ויש בו שיעור הזאה ובמה שידמה לו שיהיה אפשר שיבלע בו הדם בו ממה שראוי לקבל טומאה כמו שק ועור הרך:
@162 **תכבס במקום קדוש.** רוצה לומ' שיהיו מכבסין אותה בעזרה באופן שלם כדי שייוסר ממנה הדם הנבלע בה:
@163 **וכלי חרס אשר תבושל בו ישבר.** הטעם מפני מה שנבלע ממנה בו והוא נפסל בלינה כמו שיתבאר בענין הקדשים וזה אין דרך להוציא הבלוע מהכלי חרס ולזה יחוייב שישבר וראוי שנדע ששבירתו הואר במקום קדוש כמו הענין הכבוס הבגד וכן העניין במריקה ושטיפה במים לכלי הנחשת אשר תבושל בו כי הכוונה בזה הוא מפני דבר הבלוע שמקום אכילתו הוא בעזרה וראוי שלא נוציא דבר חוץ ממחיצתו כמו שנתבאר מאמרו בפרשת ואלה המשפטים ובשר בשדה טרפה לא תאכלו וראוי שתדע שכן הדין אם שמו בכלי חרס תבשיל רותח של חטאת אך בכלי נחשת אף על פי שלא בשלוהו בו כי בעבור הבליעה יהיה זה הדין ואם בכלי נחשת בשלה ומורק ושוטף במים הנה המריקה תהיה בחמין והשטיפה אחר זה בצונן וזה יתבאר מצד הוראת הגדר וזה אמנם יהיה במים ולא בשאר משקין כי זה הנהוג והתורה דקדקה שתהיה במים ובזה האופן יסור הדבר הבלוע מכלי נחשת והנה נזכר מזה הענין בדם ובבשול לא ינהג כי אם בחטאת הנשחטת כי בה ידבר שנאמר תשחט החטאת ולזה לא ינהג זה בחטאת העוף ולא ינהג זה הדין גם כן בחטאת הנפסלת או הנשרפת כי הם אינם נאכלות והוא ידבר בה המקום בחטאת הנאכלת שנאמר במקום קדוש תאכל בחצר אהל מועד וראוי שהמריקה והשטיפה תנהג בכל הקדשים הנאכלים כדי שלא יפסל בלינה כל זכר בכהנים יאכל אותה למדנו מזה שלא תאכל ממנו כהנת:
@164 **קדש קדשים היא.** למדנו מזה שלא תאכל כהנת קדשי קדשים:
@165 **וכל חטאת אשר יובא מדמה אל אהל מועד לכפר בקדש לא תאכל.** למדנו מזה שאף חטאת יחיד שהיא נאכלת אם בא אפילו מקצת דמה אל אהל מועד לכפר בקדש לא תאכל נפסל אפילו שאר דמה ולזה לא תהיה נאכלת לא למזבח ולא לכהנים כי זריקת הדם מכשיר האמורים למזבח והקטרת האמורים מתיר הבשר לכהנים ואם באשם ולא הזה ממנו בקדש אם היתה כוונתו כשהביאו שם שיכפר בו בקדש הנה נפסל חטאת וראוי שנדע שכמו זה הדין יהיה בדם הנכנס בקדש אם הכניסוהו לבית קדשי הקדשים כי היחס אחד וכן ראוי שנדע שהבשר שנכנס מהחטאת לאהל מועד כשר שנאמר מדמה ולא מבשרה. וכן ראוי שנדע שהדם שיוצא חוץ למחיצתו במקום למטה בקדוש' ממחיצתו שהוא נפסל אבל לא נשפוט בזה שיהיה נפסל כי אם היוצא כמו הענין בבשר שיצא חוץ למחיצתו כי מה שחדש בזה המקום שיהיה מקצת הדם הנכנס באהל מועד פוסל שירי הדם לא נלמוד ממנו לשאר ענייני יציאת הדם ממחיצתו:
@165 **באש תשרף.** אי איפשר שנאמר שיהיה נשרף במזבח העולה כי אין למזבח העולה מהחטאת כי אם האמורים אבל יהיה נשרף במקום אשר ישרפו בו הדברים אשר אינם קרבים לשם יתעלה ולפי שלא ביאר שלא יהיה נשרף מחוץ למחנה. אבל אמר סתם באש תשרף למדנו שהוא נשרף במקומו בעזרה במקום מוכן שם לשרוף פסולי המוקדשין. ואחשוב שזה המקום היה לצד המזרח כמו הענין במקום הדשן וראוי שנבין מזה המקום שהחטאות הנשרפות אשר מחוקם להוציאם חוץ לעזרה אם אירע בהם פסול בחוץ לא ישרפו במחיצתן אבל ישרפו חוץ לעזרה במקום מוכן שם לזה והנה לא בארה התורה אלו המקומות כמו שבארה מקום השלכת מוראת העוף להעיר שכל מקום כשר לזה והוא שיהיה בעזרה במה שנשרף בעזרה או חוץ לעזרה במה שנשרף חוץ לעזרה וראוי שתדע שאין ראוי שיפורש וכל חטאת אשר יובא מדמה אל אהל מועד החטאת אשר מדרכו שיובא מדמו אל אהל מועד והם החטאות הנשרפות שאם היה הדבר כן לא היה ראוי שיאמר באש ישרף לפי שכבר באר זה במה שקדם ועוד שהוא מדבר עתה בחטאות הנאכלות ועוד שכבר יורה לשון התורה שהבאת דמו לכפר בקדש סבת החיוב שלא תאכל רוצה לומר שלולי זה כבר היה נאכל וזה המאמר לא יתכן כי אם בחטאות הנאכלות וראוי גם כן שתדע שכבר כלל באמרו לא תאכל החטאות הנשרפות ולזה אמר וכל חטאת אשר יובא מדמה אל אהל מועד שאם היתה הכוונה בזה בחטאות הנאכלות לבד לא היה צריך לומר וכל חטאת אבל היה אומר ואם יובא מדמה אל אהל מועד ואמרו באש תשרף שם גם כן לכל אלו החטאות והכונה בו בחטאות הנשרפות שלא ישרף כמצוות אל שפך הדשן אבל ישרף באופן השרף פסולי המוקדשים:
@166 **וזאת תורת האשם במקום אשר תשחט העולה ישחט האשם.** רוצה לומר לצפון העזרה:
@167 **ואת דמו ישפך על המזבח סביב.** כמו העניין בעולה וזה נוהג באשם לפי שנאמר זאת תורת האשם:
@168 **ואת כל חלבו יקריב וגו'.** כבר התבאר כל זה במה שקדם:
@172 **הכהן אשר יכפר בו לו יהיה.** רוצה לומר ההן הראוי לכפר בו והם אנשי בית אב של אותו היום ואמר אשר יכפר בו להוציא הטמא אך הבעל מום חולק עמהם כמו שבארנו בפרשה הקודמת ולמדנו מזה שלא זכה בו הכהן עד שיתכפרו בו הבעלים וראוי שנבין שכן העניין בחטאת שנאמר הכהן המחטא אותה יאכלנה רוצה לומר כשחטא אותה כמשפטי התורה:
@173 **והכהן המקריב את עולת איש עור העולה אשר הקריב לכהן יהיה.** למדנו שעור העולה הוא לאנשי בית אב ולא יזכו בו אלא לאחר הקרבה שנאמר עור העולה אשר הקריב ועוד שגדר העולה לא ידבק כי אם בנעשת כמצותה והנה בארה התורה בעור העולה שהוא לכהנים וממנו יתבאר מקל וחמר שעור החטאת והאשם הוא לכהנים לפי שכבר זכו בו הכהנים בבשרם ולזה בארה זה התורה בעולה לפי שהיא עולה כליל והיה עולה על הדעת שלא יהיה לכהנים חלק בה:
@174 **וכל מנחה אשר תאפה בתנור וגומר לכהן המקריב אותה לו תהיה.** רוצה לומר לאנשי בית אב הטהורים כמו שקדם והיא גם כן נאכלת לזכרי כהונה לפנים מן הקלעים כי היא קד קדשים ובאר שאין חולקין מנחה כנגד מנחה ולזה הפריד המנחה האחת מן האחרת להורות שכל אחת מהם חולקין ביניהם ולזה אמר וכל מנחה אשר תאפה בתנור וכל נעשה במרחשת ועל מחבת וגו' ולא אמר וכל מנחת תנור ומרחשת ומחבת:
@175 **וכל מנחה בלולה בשמן וחרבה.** רוצה לומר מנחת הסלת וחרבה תקרא הסלת שאין עמה שמן כי היא יבשה כמו הענין במנחת חוטא ובמנחת סוטה:
@175 **לכל בני אהרן תהיה איש כאחיו.** ראוי שנדע כי אין ראוי שתהיה הבדל בחלוקת המנחה לכהנים ובין מנחת הסלת ובין שאר המנחות וזה מבואר מצד עצם העיון ועוד שכבר אמר במנחת חוטא והיתה לכהן כמנחה למדנו מזה שאין הבדל בעניין היות המנחה לכהן בין מנחה למנחה ועוד שכבר יורה זה שתהיה לכהן המקריב אותה ועוד שלא יתכן שיחלק עשרון סלת לכל הכהנים בכללם כי לא יגיע לאחד מהם בזה האופן חלק מוחש ולזה יחוייב שתהיה הכונה באמרו לכל בני אהרן תהיה איש כאחיו לכל אנשי בית אב של אותו היום והנה לא אמרה תורה בזה המקום לכהן המקריב אותה לו תהיה לשתי סבות האחת ללמד לנו כי מה שאמרה לכהן המקריב אותה לו תהיה אין הרצון בו שיקריב בפעל אבל הכוונה בו הראוי להקריב אז והם אנשי בית אב והשנית שאם אמרה בזה המקום לכהן המקריב אותה לו תהיה היינו חושבים שלא תחלק זאת המנחה כלל לאנשי בית אב אבל יקח אותה האחד מהם והוא המקריב אותה לפי שאינה ראויה ליחלק באופן החלק מנחת מאפה תנור או מנחת מחבת או מרחשת כי המנחות ההם הם אפויות ואי זה חלק שיגיע מהם לכהן הוא ראוי לו לאכלו אבל מנחת הסלת תחסרה לישה ואפייה ולזה לא יהיה החלק המגיע לאחד מאנשי בית אב ראוי בפני עצמו ולזה בארה לנו התורה שזאת המנחה גם כן החלק לאנשי בית אב והם משתי אלו הלשונות שאמרה התורה בזה המקום בזכירת הכהנים בקדשי הקדשים למדנו שכונת התורה היא שיהיו נחלקים לאנשי בית אב כי הם הראוים אז להקריב מפני שהוא יומם ולא יצא מכלל החלוקה הבעל מום ואם אינו ראוי להקריב הוא ראוי לאכול וכבר בארה התורה שכהן בעל מום חולק עם אנשי בית אב כמו שזכרנו ולמדנו מאמרו איש כאחיו שאין הקטן חולק בקדשי הקדשים:
@176 **וזאת תורת זבח השלמים אשר יקריב ליי'.** הוצרך בזה המקום לזכור אשר יקריב ליי' לפי שהוא נאכל לבעלים והיה עולה על הדעת שלזאת הסבה לא יצטרך שיהיו מעשיו לשם הקב"ה וכבר ביא' בפרשה הקודמת עשית השלמים במה שיכלל כל מיני השלמים ועתה שב לבאר כל מה שנתייחדו בו מיני השלמים מקצתו לקצת והוא שאם יקריבנו על תורה יקריב עמם מיני השלמים ועתה שב לבאר כל מה שנתייחדו בו מיני השלמים מקצתו לקצת והוא שאם יקריבנו על תודה יקריב עמם מיני לחם בשלם שבפנים והם כולם מהחטים שהרי זכר סלת אמר וסלת מרבכת חלות בלולות בשמן והנה יראה שמיני הלחם שזכר יהיה מנושא אחד בעינו לפי שהחלפון שזכרה התורה בהם הוא באופן התקון לבד ולזה יהיה קצו חמץ וקצתו מצה והקצת שהוא מצה יהיה קצתו חלות מצות בלולות וקצתו מצות השוחין בשמן ושני אלו המינים הם מאפה תנור וקצתו רכיכין והם חלות בלולות בשמן וחולט אותם ברותחים עד שתאפה כל צרכה ואחר כך קולה אותה על המרחשת בשמן כי היא זאת הכוונה במה שאמר מורבכת לפי הוראת הגדר וראוי שתדע כי שיעור מה שיעשה חמץ הוא כשיעור מה שיעשה מצה שנאמר על חלות לחם חמץ אחת וכבר יורה אמרו על שניות במספר ולפי שאחרי המספר יחוייב שיהיו מסכימים יהיה שעור חמץ כשיעור המצות בכללם כמו שבארנו זה בענין הלבונה הבאה עם המנחות:
@177 **אם על תודה יקריבנו. ביום הקריבו את זבחו יאכל.** רוצה לומר שלא יחשב על מי שיעשה זה הפעל הרצוי והוא הכהן שיאכלו הבעלים מבשרו ביום השלישי ולזה תהיה בעת אמרו ואם האכל יאכל מבשר זבח שלמיו ואם יחשב שיאכלהו הבעלים ביום השלישי הנה לא ירצה הזבח במה שיעשו להגעת הרצוי והוא השחיטה וקבלת הדם והולכתו וזריקתו כי לכל אלו העבודות הם מהכרח הגעת הרצוי. וראוי שנדע שלא תפגל זאת המחשבה הזבח אלא כשחשב בהם המרצה בעבודות אשר הם מהכרח הרצוי כי מפני ששלל הרצוי מפני זאת המחשבה ראוי שיהיה הרצוי מגיע במה שיעשהו אז הבעל המחשבה ההוא לולי זאת המחשבה שתמנענו ומזה המקום יתבאר שלא יתפעל הזבח אלא במחשבת הפועל עבודות הרצוי וכשיהיה ראוי שיגיע הרצוי על ידו המקריב אותו לא יחשב לו המחשב רוצה לומר שלא יחשב על יד הכהן המרצה שיאכלוהו בעלים חוץ לזמנו פגול יהיה והנפש האוכלת מבשר זה הזבח שחשבו בו זאת המחשבה עונה תשא רוצה לומר שהוא בכרת וכן אמר על זה הבאור בפרשת קדושים תהיו ואוכליו עונה ישא כי את קדש יי' חלל ונכרתה הנפש ההיא מעמיה. ולמדנו מה המקום שכל מקום שנאמר בתורה עונו ישא הרצון בו שתכרת הנפש ההיא והנה זכרה זה התורה בקל וממנו נלמד בחמור והמשל שכבר בארה התורה בשלמים שאם יחשב שיאכלוה הבעלים מהם חוץ לזמן אכילתם נתפגלו ואם הקפידה התורה בזה בשלמים שהם קדשים קלים כל שכן שתקפיד בזה בקדשי קדשים ולזה יהיה זה הדין נוהג בכל מיני קדשים רוצה לומר שאם חשב הכהן בעבודות שהם מתנאי הרצוי שיאכל בשר הקרבן אחר זמנו נתפגל הקרבן וכמו זה מאופן יתבאר שאם חשב שיהיה נקטר למזבח הנקטר מהקרבן ההוא שם חוץ לזמנו שהוא פגול. וזה שאם הקפידה התורה בזה בנאכל לבעלים כל שכן שתקפיד בנאכל לגבוה והוא מה שהקטירו מהקרבן ההוא על המזבח. ולזה יתבאר שכבר יתפגל הקרבן בכמו זאת המחשבה הן בנאכל לכהנים בן בנאכל למזבח וראוי שנדע שזה הדין ינהג בקרבן שיתכן שיאכל ממנו למי שהיתה המחשבה לו שיאכל חוץ לזמנו כמו הענין בבשר זבח השלמים שנעשו בהלכתן שיתכן שיאכלו ממנו הבעלים שהיתה המחשבה שיאכלוהו חוץ לזמנו וזה יתחייב ממנו שיהיה זה הזבח כשר ושיהיה מה שנפלה המחשבה בו ראוי לאכילה רוצה לומר שיהיה בו שיעור אכילה שהוא כזית ושיהיה ראוי לאכילה כמו הבשר לא שתהיה המחשבה בזאת בעצמות והגידים והקרנים והטלפים. ראוי שתדע שזה הדין לא ינהג אלא במה שיש לו מתירין לאדם או למזבח כמו הענין בבשר השלמים הנזכר פה שיש לו מתירין והוא זריקת הדם והקטרת האמורין אבל מה שאין לו מתירין לאדם או למזבח אם היתה המחשבה לו הנה לא תהיה המחשבה כפולת כי מתנאי המחשבה המפגלת מה שנזכר פה שתהיה בעת עשיית הפעל אשר הוא מהכרח הרצוי ובדבר אשר באלו הפעולות בו רושם להתירו לאכילה לאדם אם היתה המחשבה לאדם או למזבח אם היתה המחשבה למזבח והנה אמרו לא יחשב לו הוא מצות לא תעשה ולמדנו ממנו שהכהן מוזהר שלא יחשב כמו זאת המחשבה שתפסיד הקדשים ולפי שאנחנו נמצא כי מתנאי הקדשים הזמן והמקום רוצה לומר שכבר קבעה התורה זמן לאכילתם הן לאדם הן למזבח כמו שהתבאר במה שקד' וקבעה עם זה מקום יאכלו בו. וזה שקדשי הקדשים נאכלים לפניו מן הקלעים שהוא מקום קדוש כמו שיתבאר וקדשים קלים אכילתם לפנים מן החומה בירושלם כמו שיתבאר במה שיבא הנה ראוי שנעיין אם הוא ראוי שנלמד מזה שתהיה מחשבת המקום מפגלת ר"ל אם חשב שיאכל קרבן חוץ למקומו. ונאמר שכבר בארה התורה בפרשת קדושים תהיו כי הטעם בפגול הוא מפני שכבר חל את קדש יי' והוא מבואר שהבשר יתחלל בעצמותו אם יעבור זמנו כי ישוב הבשר נבאש ונבזה ואם יצא חוץ למקומו לא יתחלל מעצמותו אלא שאינו במקום קדוש כמו המקום שהיה בו. ולזה יתבאר שלא יתפגל מצד מחשבת המקום. אבל יהיה פסול אחר שהקפידה התורה במחשבות בעניין הקרבנות וראוי שנדע שהאוכל את הנותר חייב כרת וזה שאם נתחייב כרת באכילתו תוך זמנו מפני שחשבו בו לאכלו חוץ לזמנו כל שכן שיתחייב כרת כשאכלו חוץ לזמנו באמת וזה מבואר מאד והבשר אשר יגע בכל טמא ר"ל בשר קדש שנטמא כי בבשר קדש ידבר בזה המקום והנה כלל באמרו כל הטמאות הקלות והחמורות הנזכרות בתורה:
@177 **והקריב על זבח התודה.** למדנו שזבח התודה הוא העקר ולחמי התודה הם באים בכלל הזבח. והנה לא נתבאר בתורה שיעור הלחם הבא עם התודה. והנה מצאנו בתורה מבואר שיעור הלחם הבא עם שני כבשי עצרת שהוא עשרון והוא חמץ. ולזה ידמה שכל לחם ולחם מהחמץ יהיה שעורו עשרון. ולפי שכבר אמר והקריב ממנו אחד מכל קרבן תרומה ליי' שיהיו לחמי החמץ לכל הפחות עשרה כי לא מצאנו תרומה בפחות מזה המספר בתורה ולזה יתבאר שהחמץ יהיה עשרה עשרונות שהוא איפה כי העשרון הוא עשירית האיפה וממה שקדם יתבאר שמיני המצה יהיו גם כן עשרה עשרונות ולזה יהיו לחמי תודה באים מעשרים עשרונות. ויתבאר ממה שקדם שבכל מין ומין יהיו עשרה לחם עד שיהי המספר החלות ארבעים. ולפי שאמר חלות מצות חלות לחם הנה יחוייב שתהיינה שלמות לא פרוסות וכן מה שיקח הכהן הוא אחד שלם פרוס שנאמר והקריב ממנו אחד מכל קרבן יי' והנה השיעור שישימו מהשמן כאלו החלות לפי הנהוג מענינם כשיתוקנו למאכל היה לוג רביעיתו לרקיקין ורביעיתו לחלות מאפה תנור וחצי לרכיכין וראוי שנדע שכבר אפשר להרים תרומת הלחם הזה בעיסה כמו העניין בחלה כי שם נאמר בכ' תרומה:
@179 **לכהן הזורק את דם השלמים לו יהיה.** למדנו מזה שהוא ראוי שיהיה הכהן ראוי בשעת זריקת הדם רוצה לומר שאם היה הכהן טהור בשעת קבלת הדם או הולכתו ואינו טהור בשעת זריקה אינו חולק בלחמי תודה עם אנשי בית אב. והנה הרצון באמרנו הזורק הראוי לזרוק מצד הזמן והם אנשי בית אב של אתו היום ובשר זבח תודה שלמיו ביום קרבנו יאכל ראוי שנדע שאין הכוונה בזה שיאכל קדם בא הלילה שכבר אמר אחר זה לא יניח ממנו עד בקר ואמנם הכוונה בו תוך יום אחד מעת הקרבתו ולא יהיה זה ג"כ מעת לעת אבל יהיה גבול אכילתו עד סוף הלילה והסבה כי אז יהיה הבשר יותר נבחר ממה שיהיה כשיעבור זה הזמן ובאר זה התורה בקצת קדשים קלים ולמדנו מזה שכן הדין בקדשי הקדשים רוצה לומר שאין נאכלים כי אם עד בקר הבא ראשון כי אם הקפידה בזה התורה עם היותר מהקדשים קלים כל שכן שתקפיד בזה בקדשי הקדשים ולפי שאין ממנהג האנשים לאכול בלילה אחר חצי הלילה הנה ראוי שיאכלם קדם עבור חצות הלילה אלא שלא יפסל בנותר עד יעבור הלילה. ואחשוב שקרבן זבח תודה בא על עניין נתינת הודאה לשם במה שהשפיע מהטובות. ולזה נקרא תודה. ולזה תמצא כשיוסיפו על העיר שיקדו התוספת ההוא בב' תודות. לפי מה שהתבאר קצת באור מעזרא ובתודות ההם היו אומרים ארוממך יי' כי דלותני שהוא ענין הודאה על הטובות שהשפיע וידמה כשיסמך על זבח התודה היה אומר בו וודוי הודאה לשם יתעלה כי זה הקרבן לא היה בא על עון:
@181 **ואם נדר או נדבה זבח קרבנו ביום הקריבו את זבחו יאכל.** למדנו מזה המצוה מן המובחר לאכלו ביום הראשון אך לא יפסל הנותר ולזה אמר אחר זה וממחרת והנותר ממנו יאכל או תהיה וי"ו והנותר נוספת כמו וי"ו ואיה וענה. נרדם ורכב וסוס. עניינו וממחרת הנותר ממנו יאכל:
@182 **והנותר מבשר הזבח ביום השלישי באש ישרף.** מפני שלא אמר והנותר ממנו עד בקר למדנו שבבא הלילה אחר עבור היום השני יהיה נפסל בנותר ואמרו באש ישרף יחוייב העשותו בו לפי מה שיתבאר מהשרשים הכוללים ולזה ימתינו לשרפו עד בקר יום שלישי וישרפוהו הבעלים בבתיהם במקום שהיו נאכלים בו כי לא צותה התורה בזה המקום שיוציאוהו מחוץ לשרפו:
@183 **ואם האכל יאכל מבשר זבח שלמיו ביום השלישי לא ירצה.** הנה בביאור זה הפסוק מהעומק וקושי וזה אי אפשר שנאמר שתהיה הכוונה בזה במה שיובן ממנו בתחלת העיון רוצה לומר שאם יאכל מבשר הזבח ביום השלישי שלא ירצה וזה שכבר התבאר בפרשת אחרי מות כי בזריקת הדם תשלם הכפרה אמר שם ואני נתתיו על המזבח לכפר על נפשותיכם כי הדם הוא בנפש יכפר ואחר שלמה הכפרה אין ראוי שיאמן שישוב החטא על עניינו. ובכלל הנה אחר שנרצה הזבח לא יתכן שישוב להיות בלתי נרצה וזה מבואר בנפשו ולזה גם כן יתבאר שאמרו המקריב אותו לא יחשב לו אין הרצון בו שלא יהיה נחשב לו לדבר הזבח אשר אכלו ממנו אחר זמנו ולזה יהיה יחשב לו מעניין מחשבה. והרצון בו שלא יחשב זה העניין למקריב אותו שהוא בעל הזבח כמו שאמר ברא' זאת הפרשה אשר יקריב ליי':
@184 **באש ישרף.** מפני שלא ביאר זכר מקום אחר שריפתו הנה תהיה שריפתו במקום אכילתו אלא אם היה מקום אכילתו מכניס מחייב שלא נכנס הטומאה לשם כמו העניין בעזרה ולזה אם נטמא בעזרה בשר קדשי הקדשים שהוא נאכל שם ישרף ואם יצא חוץ לעזרה ונטמא שם ישרף במקומו כי לא נוכל להכניס הטמא בעזרה:
@184 **והבשר כל טהור יאכל בשר.** ר"ל כי כבר הורשה כל טהור לאכל בשר קדש מזבח השלמים אך אם יאכל ממנו הטמא יתחייב כרת והנה בארה התורה זה הדין בקדשים קלים וממנו יתבאר בקדשי קדשים מקל וחומר ואמרו וטמאתו עליו ירצה בו שיהיה טמא מצד עצמו כאלו תאמר שהיה זב ומצורע או בעל קרי ואמרו ונפש כי תגע בכל טמא הוא בטמאה שיהיה לאדם מצד המגע בדבר הטמא כאלו תאמר שנגע בטומאת אדם כמו זובו ושכבת זרעו או שנגע בזב ומצורע ונדה ושאר מה שידמה לזה או בבהמה טמאה היא הנבלה:
@186 **או בכל שרץ טמא.** הם שמנה שרצים הנזכרים בתורה שיטמא הנוגע בהם כמותם:
@188 **זכרה** התורה אלו המינים לפי שמהם יביאו הקרבנות ולכבוד הקרבנות רצה שלא יאכל חלב אלו הבהמות אף על פי שלא יהיו קרבנות:
@189 **וחלב נבלה וחלב טרפה יעשה לכל מלאכה ואכול לא תאכלוהו.** הנה הנבלה היא לפי מה שיורה עליו הגדר שנזבחה שלא כדרך הזביחה הראויה והטרפה היא שמתה מעצמה או שיש בה חולי או מכה אי אפשר לחיות ממנה כאלו תאמר שטרפה זאב או ארי ואמרו לכל מלאכה רצה בו שכבר הותר לנו ליהנות בו בכל מלאכות כאלו תאבד במשיחה או בהדלקה אבל יאסר באכילה והוצרך להזכיר חלב נבלה וחלב טרפה שלא יחשוב חושב שלא ינהג איסור מחלב אלא בבהמות הראויות להקריב אשי ליי' ולמדנו מזה המקום שהאוכל חלב נבלה וטרפה יתחייב משום חלב גם כן ואם הוא חייב מפני היותו מנבלה וטרפה מצד אחר כמו שיתבאר:
@190 **כי כל אוכל חלב מן הבהמה אשר יקריבו ממנו אשה לה' ונכרתה.** אין ספק שאין הרצון בזה שיקריב ממנה בפעל שכבר זכר בכללות כל חלב שור וכבש ועז לא תאכלו ואין הרצון בזה גם כן שתהיה הבהמה ההיא ראויה להקריב מנה אשה לה' שלא תהיה בעלת מום וזה שכבר זכר נבלה וטרפה ולזה הוא מבואר שהרצון בזה שאינה נאות להקריב ממנה אשה ליי' והבהמה שבזה התואר הוא שור וכבש ועז והנה למדנו מזה המקום שלא נאסר מהחלבים אלא מה שמדרכו להיות קרב להם מאלו הבהמות כי יראה שלכבוד הקרבנות מנע החלב כמו שיבאר במה שקדם:
@191 **וכל דם לא תאכלו בכל מושבותיכם לעוף ולבהמה** אין ראוי שנאמין שיהיה דם החיה מותר כי כבר נתבאר בסדר ויקרא בכללות שכל דם הוא אסור וכן יתבאר זה בפרשת קדושים תהיו ולזאת הסבה צוה שם לכסות דם חיה ועוף ולזה יתבאר שאמרו ולבהמה נכלל בו חיה ובהמה כי שם בהמה יאמר בכללות על החיה והבהמה אמר זאת הבהמה אשר תאכלו כיל וצבי ויחמור וכן הענין בחיה אמר בפרשת ויהי ביום השמיני זאת החיה אשר תאכלו מכל הבהמה אשר על הארץ והנה סמכה התורה צווי אסור החלב והדם אחר זכרון תורת השלמים. כי לזאת הסבה נצטוו שלא יאכלו במדבר כי אם שלמים כמו שזכרנו במה שקדם וזה יתבאר עוד בפרשת אחרי מות:
@194 למדנו מזה שדין התנופה ינהג **בבני ישראל** ולא בבנות ישראל ולא בגוים:
@194 **המקריב את זבח השלמים ליי'.** הם הבעלים:
@194 **יביא את קרבנו ליי' מזבח שלמיו.** רוצה לומר שהבעלים מביאים בידיהם מה שהוא קרב להשם מזבח השלמים וזה שאם היה על תודה יביא בידיו אחד מכל קרבן מהלחם:
@195 **ידיו תביאנה את אשי יי'.** רוצה לומר שהבעלים יביאו בידיהם החלבים שהם אשי השם ועמהם יביאו מה שיהיה מהמזבח לכהנים וזה הדבר השני כולל התודה והשלמים ואמנם הבאת הלחם המיוחד בתודה וראוי שתדע כי הבאת אלו הדברים יחד בסדור הראוי נתבאר בפרשה הבאה אחר זה עם מה שזכר בזה המקום וזה שהלחם הבאה עם התודה יושם עליון שנאמר בפרשה הבאה אחר זדה ומסל המצות אשר לפני השם לקח חלת מצה אחת וחלת לחם שמן אחת ורקיק אחת ויושם על החלבים ועל שוק הימין ולפי שנאמר על החלבים ועל שוק הימין למדנו שהחלבים היו למטה ולמעלה מהם חלק הכהנים שהוא חזה התנופה ושוק התרומה והנשאר מאשי השם לפי שלא נזכר מקומו היה למעלה והוא שתי הכליות הכבד וכאשר היה שם לחם היה למעלה מהם כמו שביארנו:
@195 **את החלב על החזה יביאנו את החזה.** ירצה לפי מה שאחשוב שהשומן שאצל החזה יביאנו את החזה לכהן כי החלב יאמר על השומן אמר חלבו האליה תמימה ולא זכר בכאן כי אם החזה אך אחר זה זכר שוק הימין וקראו שוק התרומה וידענו כי החזה והשוק היו יחד בתנופה אמר בפרשת שמיני שוק התרומה וחזה התנופה על אשי החלבים להניף תנופה:
@196 **והקטיר הכהן את החלב המזבחה והיה החזה לאהרן ולבניו.** ר"ל שלא יזכו הכהנים בחזה ושוק אם לא אחר הקטרת החלבים במזבח ונאמר לאהרן ולבניו להורות כי כהן גדול נוטל חלק בראש אף על פי שאינו מקריב:
@197 **ואת שוק הימין תתנו תרומה לכהן מזבחי שלמיכם.** למדנו בזה המקום ששוק הימין הוא גם כן לכהן והנה יחס התרומה לשוק והתנופה לחזה ואם היתה להם יחד התנופה והתרומה לפי שתנועתיהם הטבעיות נאותות לזה ולזה וזה שתנועת החזה בבהמה היא הולכה והבאה וזה היא תנופה ותנועת השוק שהיא כלי ההליכה היא בהעלאה והורדה כן יעלה כל ב"ח רגליו ויורידם ובזה האופן יעתק המקום למקום:
@198 **המקריב את דם השלמים ואת החלב מבני אהרן לו תהיה שוק הימין למנה.** ר"ל הראויים להקריב אז והם אנשי בית אב כמו שביארנו במה שקדם ולמדנו שמי שהיה מהם טמא בעת זריקת הדם או בעת הקטרת החלבים איננו חולק בחזה ושוק:
@199 **ונתן אותם לאהרן הכהן ולבניו.** למדנו שכהן גדול קודם לבניו בחזה ושוק וממנו נלמד שכן העניין בשאר מתנות כהנה:
@200 **זאת משחת אהרן ומשחת בניו מאשי הש' ביום הקריב אותם לכהן להש'.** ר"ל זאת היה הגדלה שנתגדלו במשיחתם הכהנים מאשי השם ביום הקריב אותם השם יתעלה לכהן להשם כי אז נתן להם זה החלק מהקרבנות שנזכרו בזאת הפר' לעולה ולמנחה ולחטאת לאשם ולתודה ולזבח השלמים ואמר מאשי השם כי כבר נתן להם השם יתעל מתנות אחרות זולת אלו כמו שיבא ולהורות שאלו המתנות יהיו לכהנים לדורות אמר אחר זה אשר צוה השם לתת להם ביום משחו אותם מאת בני ישראל חק עולם לדורותיכם:
@202 **זאת התורה לעולה וגו'.** אמר ולמלואים לפי שמעשה המלואים והשלמים הם שנים והם דומים בענייניהם למעשה התודה אלא שלא היה במלואים לחם חמץ כמו שנזכר בפרשת ואתה תצוה ובזאת הפרשה הבאה ביום צוותו את בני ישראל להקריב קרבניהם להשם למדנו מזה שכל הקרבנו' ראוי שיהיו לשם הקב"ה ולמדנו מזה עוד שאחת מהכונות בקרבנות היתה שלא יקריבו קרבן לע"ז ולזה צוה אותם שיקריבו קרבניהם להשם למען לא יזבחו לע"ז ולזה אמר בפרשת אחרי מות ולא יזבחו עוד את זבחיהם לשעירים:
@204 זאת הפרשה דבקה לפרשת וזה הדבר אשר בסדר ואתה תצוה ושם ביארנו כל הנזכר בזאת הפרשה:
@234 **בשלו את הבשר פתח אהל מועד ושם תאכלו אותו ואת הלחם אשר בסל המלואים.** הנה נוהג איל המלואים ובלחמו מנהג קדשי הקדשים לאכלו במקום קדוש ולבשלו במקום קדוש ואם הוא כשלמים מפני שבו נשלם קדשת אהרן ובניו:
@236 **כי שבעת ימים ימלא את ידיכם.** ר"ל שבכל אחד מהשבעת ימים יעשה להם משה ככה כנזכר בזאת הפרשה להקריב עליהם אלו הקרבנות כי כן כתוב בפרשת ואתה תצוה ועשית לאהרן ולבניו ככה ככל אשר צויתי אותכה שבעת ימים תמלא את ידם:
@237 **כאשר עשה ביום הזה.** מכל הקרבנות והמעשים:
@237 **צוה ה' לעשות לכפר עליכם.** עד שכבר תצטרכו בכל יום מאלו השבעה ימים לפר חטאת להשלים הכפרה כמו שנזכר בפרשת ואתה תצוה ושם זכרנו התועלות המגיע מזה הפעל לחדש הכהונה והקדושה לאהרן ולבניו באופן שיהיו ראויים לכפר על זולתם והנה היו אלו הקרבנות נוהגים שבעה ימים כדי שיבינו מהם עם זה ההכפל מה שהיא הערה עליו באופן שיהיו נקיים בשלמות המחטאים עם שכבר היה זה גם כן לכפר על החטאים רבים דמו להם ולזה ראוי שיהיה ההכפל בזה הקרבן הראשון אשר בו נתחדשה להם הכהונה והיה בכל יום חטא ועולה ושלמים להודות על הגעת הרצוי להם בשלם שבפנים לפי מה שהורם מענין הקרבנות ובכאן נשלם הבאור בזאת הפרשה:
@259 **ויהי ביום השמיני.** ר"ל לאחר עבור שבעת ימי המלואים כי אז נשלם עניין משיחת אהרן ומשיחת בניו באופן שהיו ראוים לכפר עליהם בעצמם ועל זולתם והיה חטאת אהרן עגל לכפר על מעשה העגל ואם היתה כוונתו טובה כמו שבארנו ואמנם היה צריך כפרה כי כבר חטאו בזה העניין קצת ישראל וכאלו היה אהרן בזה סבה מה ואולם בני ישראל מפני שעשו קצתם ממנו ע"ז היה קרבנם דומה באופ' מה לקרבן הבא על שגגת ע"ז שהוא שעיר לחטאת ופר לעולה ובכאן היה שעיר לחטאת ועגל לעולה תמורת הפר להעיר על מעשה העגל והנה היה עמו כבש לעולה לסבה בעינה אשר בא פסח מצרים והוא להוציאם מאמונת המצרים שהיו עובדים מזל טלה והיה שם שור ואיל לשלמים שהם מהמיני הנבחרים והיה שם חטאת ועולה ושלמים להשלים הרצוי לישראל עם השם יתעלה בשלם שבפנים כמו שבארנו מעניין אלו הקרבנות והיתה שם מנחה בלולה בשמן להוסיף שלמות בזה הרצוי וכבר התבאר במה שקדם סדר הקרבת המנחה ושהו' עם קומץ לבונה ולזה לא נשנה הביאור בזה המקום:
@262 **כי היום יי' נראה אליכם.** ר"ל שיראה אליהם כבודו ויגיע בזה רושם מוחש על צד המופת כשתצא האש מלפני יי' ממקום קדש הקדשים שהוא מעיר על אותן הגעת עשיית הקרבנות האלו ולזה לה נצטרכנו לבאר זה בזה המקום:
@273 **וישחטהו ויחטאהו כראשון.** ר"ל שאהרן בעצמו שחטהו וחזה ממנו על קרנות המזבח כמו העניין בראשון אבל לא השוהו לראשון לשאר דיניו כי זה החטאת לא הובא דמו אל הקדש פנימה כמו העניין בחטאת אהרן כמו שנזכר אחר זה ולזה היה דינו שיהיה נאכל לזכרי כהונה כמו שקדם:
@274 **כמשפט.** ר"ל שכבר הקריבה קדם שיקריב חטאתו כי כבר נשלמה לו הכפרה כשבעת ימי המלואים בצד מספיק לו להכשירו להקריב העולה אבל לכפר על ישראל חוייב שיביא קדם זה החטאת לכפר בו יחד בעדו ובעד העם ואחר הביא חטאת העם:
@275 **מלבד עולת הבקר.** ר"ל כי כל אלו הקרבנות הנזכרים שהם קדשי קדשים הקריב אהרן בזה האופן מלבד עולת הבקר שהקריבה קודם אלו הקרבנות כולם:
@277 **האליה והמכסה והכליות ויותרת הכבד.** המכסה הוא החלב אשר על הקרב ולפי שזכר באחרונה הכליות ויותרת הכבד למדנו שהם הושמו עליונים בתנופה כדי שיתעוררו הבעלים בעניינם למה בחר השם יתעלה שיוקטרו עם החלבים והנה הם אינם מהמיטב והשמן כמו שאר מה שיוקטר מזה לשם יתעלה יהיה זה סבה אל שיגיע להם התועלת המכוון בזה העניין:
@280 **וישא אהרן את ידיו אל העם ויברכם.** זו ברכת כהנים שיתבאר עניינה בפר' נשא והיתה עם נשיאות כפים כמו שנבאר הסבה שם בג"ה:
@283 **ויקחו בני אהרן נדב ואביהו איש מחתתו ויתנו בהן אש.** ר"ל להוליך אש אל מזבח הזהב ששם הקטרת קטרת סמים והנה לא ביאר באי זה מקום לקחו זה האש אבל התבאר אחר זה שלא לקחו אותו מהמקום הראוי לפי מצות השם יתעלה ולזה קרא זה האש אש זרה:
@283 **וישימו עליה קטרת.** ר"ל אחר ששמו האש על המזבח הזהב:
@283 **ויקריבו לפני יי' אש זרה אשר לא צוה אותם.** ידמה שלא לקחו זה האש מעל מזבח העולה כמשפט והיה מפני זה זרה או שלא לקחו מאש מערכת מזבח העולה המיוחדת להוליך למזבח הזהב להקטיר עליה קטרת הסמים אבל לקחו אש אם מהמערכה הגדולה אשר עליה יקטירום התמידין ויתר הקרבנות אם מאש המערכת קיום האש אשר שם כמו שהתבאר במה שקדם. והנה ענש אותם השם יתע' זה העונש הנפלא מפני הקלס בזאת העבודה הנכבדת בזה האופן כי לא יתכן שיעמדו על הכונה בה אם לא ידקדקו לעשות אותה באופן שצוה השם יתעלה ויהיה זה סבה אל שיבצר מזאת העבודה התועלת הנפלא המכון בה והוא הגעת השלמות האנושי בעיון לפי מה שאפשר וכל שכן כשיהיה זה המרי בעת הכנס בזאת העבודה כי זה בלי ספק היה סבה אל שלא ידקדקו הם והבאים אחריהם לעשות זאת העבודה לפי מה שצוה השם יתע' לולי ראותם העונש הנפלא כי זה יהיה סבה אל שלא יפילו הכהנים מנימוס מעשה הקרבנות דבר ליראתם משיגיע להם כמו זה העונש וזה יסבב שיעמדו על הכוונה אשר בעבורה נצטוו לעשותה בזה האופן ולזה היה הגעת זה הענש על נדב ואביהו ממה שישלי' כוונת השם יתע' בזאת העבודה והנה בא זה העונש להם על דרך המופת להשגחה על ישראל שלא יבצר מהם הטוב המכוון בקרבנות וכבר בארנו זה האופן מההשגחה ברביעי מספר מלחמות יי':
@285 **בקרובי אקדש ועל פני כל העם אכבד.** ר"ל בקרובי והם המשלימים נפשם בעיון להשיג אותי אתקדש כי הם ראויים שישתדלו להשיג אותי בחזקת היד בצד מהשגה אהיה נבדל בה משאר הנמצאות ובזה ישיגני שיכבדוני כל העם כי קרובי יודיעו להם על צד הקבלה ממהותי ועצמותי מה שיכבדוני בו ואם לא הגיע השגתם אל שאתקדש בה באופן יבדילוני משא הנמצאות בצד מהמציאות המיוחד לי וזה אמנם יהיה לקרובי הנגשים אלי באלו ההערות הנפלאות אשר סדרתי במקדש ובעבודה אשר שם ובהיות העניין כן כשאחזו מי שאבחרם להיות קרובי והם הכהנים הנגשים אלי דרך שלא יכשר עמה שאתקדש בהשגתם עם אילו ההערות הנפלאות אשר סדרתי הנה מנעו הטוב הנפלא אשר כוונתי אליו מהם ומן העם ולזה ראוי שיגיעם עונש נפלא כדי שלא יבצר מישראל התועלת המכוון בזאת העבודה או ירצה בזה בקרובי והם הנגשים אלי לשרתני כוונתי שאתקדש במה שסדרתי מאלו העבודות כדי שיעמדו מהם על אמתת מציאותי ויבדילוני משאר הנמצאות ואמנם על פני כל העם ר"ל די שאתכבד באלו העבודות שישיגו שאלו העבודות הם לתת לי כבוד מזולת שישיגו בשלמות העניין המכוון באלו הקרבנות כמו שאמר זובח תודה יכבדנני והנה הנגשים אל השם יתעלה לשרתו כשלא דקדקו באופן אלו העבודות שיעשו לפי הנימוס שצותה עליו התורה לא יראו שיהיה בעבודה הערה אחרת רק לכבד את השם יתעלה ולזה יראו שהוא יכובד בזה האופן מהמעשה כמו שהיה מכובד באופן האחד ומפני זה לא ידקדקו בו ולא יגיעו אם כן מהתועלת להם באלו העבודות רק מה שיגיע שיתכן להגיע להמון וזה הפך הכוונה האלהית בזה ולפי שכבר ימנע מזה האופן התועלת המכון באלו הקרבנות הגיע השם יתעלה להם זה הענש הנפלא:
@285 **וידום אהרן.** ר"ל ששתק ולא צעק ובכה על זה כחק שאר האנשים כי ליתרון מעלתו לא היה ראוי שיתפעל בהפעליות האלו כשאר האנשים:
@288 **ראשיכם אל תפרעו.** ר"ל שלא יגדלו שער ראשם וישביתו ממנו התגלחת כשאר האבלים ולפי שבאה אזהרה בזה בייחוד לכהנים למדנו שפריעת הראש חק על שאר האבלים:
@288 **ובגדיכם לא תפרומו.** ר"ל אל תקרעו למדנו מזה שהקריעה חק על שאר האבלים והנה נמנעה לכהנים הפריעה והפרימה לכבוד השם יתעלה שלא יכנסו מנוולים בעבודתו אבל יכנסו בבגדי הכהונה יהיו להם לכבוד ולתפארת ולזאת היתה זאת הצואה כוללת לאבלים ולבלתי אבלים ומה שאמר אחר זה ולא תמותו אשר יורה שכבר תחייבו מיתה אם עבר אל עלו האזהרות מבואר הוא שזה יהיה אם עשו עבודתם בהיותם בזה האופן מהנוול לא אם לא שמשו במקדש כלל בהיותם בזה האופן וזה דבר נלמדהו ממה שהזהירה התורה בענין שתיית היין אשר הנוול בה יותר חוק בחק השם יתעלה כי הוא יבלבל שכל הכהן וימנעהו מהשיג הכונה אשר בעבורה יעשה מה שיעשה מהעבודות ועם כל זה לא חייבה התורה בו מיתה אם לא מצד העבודה ולזה יתבאר שחיוב המיתה שנזכר בזה המקום הוא אם עשו העבודה ועוד אם היתה זאת האזהרה שלא בשעת העבודה למה ייוחד בזה כהן גדול מבין שאר הכהנים שנאמר בו ראשו לא יפרע ובגדיו לא יפרום ואמנם ייוחד בזה להיותו תמיד במקדש ותמיד הוא משמש כשירצה. ולזה נמנעה הפריעה והפרימה תמיד ואמנם כהן הדיוט אינו משמש אלא בעת המשמר שלו ולזה לא היתה זאת האזהרה לו תמידית כמו הענין בכהן גדול:
@289 **ומפתח אהל מועד לא תצאו פן תמותו.** ר"ל שלא יניחו עבודתם מפני המקרה הרע הזה שקרה להם ולמדנו מזה המקום שאיזה כהן שיהיה שהניח עבודתו ויצא מן המקדש חייב מיתה יין ושכר אל תשת אתה ובניך אתך ראוי שתדע שהשתייה לא תהיה בפחות מרביעית לפי מה שהתבאר בשרשים הכוללים ולפי שהשכר הוא יין הנה תהיה ואו ושכר תנאית ר"ל מיין שיהיה שכר והוא היין שעברו עליו ארבעים יום והנה אמרו בבאכם אל אהל מועד ירצה בו בבאכם שם לשמש בכהונתכם כי לזה יהיה בואם שם לפי הנהוג ומזה המקום יתבאר שמי ששתה רביעית יין שעברו עליו ארבעים יום ועבד חייב מיתה וראוי שיתבאר מזה שהשכור משאר המשכרין כמו החלב ושאר מה שידמה לו אין ראוי שישמש כי מפני בלבול המחשבה הזהירה התורה בזה אבל לא יתחייב על זה מיתה כי התורה לא חייבה מיתה אלא על היין ולא נלמד ממנו מה שלמטה ממנו בפועל השכרו' למיתה אבל יתבאר שהוא בלאו והנה הזכירה התורה היותר מגונה והיותר חזק בזה הפועל למיתה לפי שלא יתחייבו מיתה אלא עליו חקת עולם לדורותיכם מגיד שזאת האזהרה נוהגת לדורות והנה באה בזה המקום אזהרה פריעת הראש ופרימת בגדים לפי שנתחדש זה המקרא לאהרן אשר היה מביא הוא ובניו לפריעת הראש ופרימת הבגדים מצד האכל לולי אלו האזהרו' וכן באה זה המקום האזהר' שלא יצא מפתח אהל מועד ר"ל שלא יניחו זאת העבודה ויצאו לזאת הסבה בעינה כי זה העניין היה מביא אותם להניח עבודתם ולצאת לולא זאת האזהרה ובאה בכאן האזהרה משתיית היין ושכר להעיר כי מפני בלבול שכלם ושבושם מתו נדב ואביהוא כי אלו היו מתישבים בדבר העבודה הזאת ואופן החכמה אשר בעבורו היתה בזה האופן לא היו מפילים מדברי השם יתעלה בה דבר ולהבדיל בין הקדש ובין החול ר"ל בעת שתזקקו בהוראתם להבדיל בין הקדש ובין החול בעניין הנדרים והערכין והחרמים ומה שידמה להם ממה שיצטרך בו ההוראה אם הוא קדש או חול לא תהיו שתויי יין וכן כשתבאו להבדיל בין הטמא ובין הטהור בענין הנגעי' ובזולתם מהטמאות אשר יפול ספק בעניינם וכן כשתבאו להורות בני ישראל את חקי התורה לא תשתו יין בבואכם להורות אלו ההוראות וראוי שיתבאר מזה ששתוי יין אין ראוי שיורה היה ישראל או כהן אלא שזה לכהן באזהרה לפי מה שנתבאר בזה המקום וישראל אינו באזהרה לפי שזה הדין יותר ראוי בכהן כי השגגה תהיה בהוראתו תזיק יותר לפי שהוא משותף לכל ישראל בעניין האזהרה כענין שנאמר יורו משפטיך ליעקב וגו'. ואמר בפשרת שופטים כי יפלא ממך דבר למשפט ובאת אל הכהנים הלוים ואין הענין כן בישראל המורה הוראות ולפי שהוא מבואר כי מפני אפשרות חדוש השכרות מפני שתיית היין באה זאת האזהרה והתבאר לרבותינו בנסיון כי בשתיית רביעית לוג מיין חי בזולת הפסק יתכן שיתחדש השכרות או ביותר מרביעית יין חי או מזוג אפי' בהפסק לא בפחות מה והיה התנאים האלו בשתיית זה היין אשר יתחייבו עליו מיתה כששמשו במקדש ר"ל שאם שתו יין חי יהיה השעור רביעית לוג ושתהיה השתייה יחד ואם לא שתו אותו יחד אבל הפסיק בשתייה יהיה השעור יותר מרביעית חי או מזוג כי היין המוזג גם כן יקרה ממנו השכרות בקלות כמו שנזכר בספר שאלות טבעיות אצל המזבח ר"ל בעזרה ולזה אמר אחר זדה במקום קדוש ונכלל בזה כל מחנה כהנה והוא העזרה והלשכות הפתוחות להשם תאכלו במקום טהור לפי שהוא שלמים לא חייבנו כי אם במחנה ישראל ושם חוייב שיאכלוהו בטהרה כמו שקדמה האזהרה בזה מלטמא הקרבנות ימלא כלם בטומאה וכבר יתבאר במה שיבא שלא יותר לאכל שלמים כי אם במחנה ישר':
@297 **שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף תנופה לפי יי'.** כבר בארנו במה שקדם והנה כי כבר היתה שם תנופה ותרומה לכל אלו הדברים ויחס התרומה לשוק והתנופה לחזה לסבה שזכרנו במה שקדם והנה למדנו מזה שהשוק והחזה היו על אשי החלבים לא על הכליות ויותרת הכבד ולזה נתחייב שיהיו הכליות ויותרת הכבד על החזה והשוק כמו שזכרנו במה שקדם והנה צוה אותם לאכול באנינות אלו הקדשים לפי שהם לא היו אלא לפי שעה והיתה מעשיהם מצות השם יתעלה שיאכלום באנינות להוראת שעה לפי שזה היה תחלת מעשיהם ולא הסכימה החכמה האלהית שיהיה נגרע חקם במה שנתחננו בו מאלו הקדשים ואמנם הקדשים הנהגים לדורות לא יתכן לאכלם באנינות ולזה התנצל אהרן על שלא נאכל שעיר החטאת מפני האנינות כמו שיתבא' אחר זה והנה יתבא' ששעיר החטא' הזה איננו השעיר הנזכר בזאת הפרשה שאם היה הדבר כן למה זה הסכימו לאכול שירי המנחה וחזה ושוק באנינות ולא אכלו זה השעיר אבל שרפוהו והנה היה ראוי שיהיה הדין שוה ככאלו הקדשים להאכיל באנינות או שלא להאכיל ולזה הסכימו רבותינו ז"ל שזה השעיר הנשרף היה שעיר ראש חדש כי ר"ח היה היום כמו שנבאר במה שיבא ולפי שזה השעיר נוהג לדורות לא הסכים אהרן לאכלו באנינות לחשבו שמה שצוה השם יתעלה להאכיל באנינו' באלו הקדשים לא יהיה נוהג אלא בקדשי שעה:
@298 **ויקצף על אלעזר ועל איתמר בני אהרן הנותרים.** אמר הנותרים. אם להורות שמיתת נדב ואביהו היתה קדם זה או לבאר שהם יהיו נותרים ותתקיים להם הכהונה ולא ימותו באופן מיתת נדב ואביהו או אמר זה להעיר שגם הם היו ראוים ליענש מצד שלא דקדקו כראוי בעניין זאת העבודה ומזה הצד כעס עליהם משה רבינו ע"ה כאלו תאמר שהם לא נוסרו במה שחל עליהם מהרע במיתת נדב ואביהו:
@299 **מדוע לא אכלתם את החטאת במקום הקדש.** מפני שאין הרצון בזה לגנות אותם על שאכלוהו שלא באופן הראוי לפי שהם לא אכלוהו כלל אבל נשרף הנה יהיה בהכרח הרצון בזה מדוע לא אכלתם את החטאת שיהיה במקום הקדש ואמר זה להעיר שלא נפסל זה החטאת מפני יציאה חוץ למקומו כי הוא היה במקום הקדש ולזה לא היה דינו לישרף ומפני זה גנה אותם ומזה המקום נלמד שהיוצא חוץ למקומו דינו שישרף:
@299 **ואותה נתן לכם לשאת את עון העדה לכפר וגומ'.** אע"פ שכבר נשלמה הכפרה בזריקת הדם כמו שקדם הנה ייטיב עניין זאת הכפרה אכילת הכהנים אלו הקדשים כי בזה הערה להתקרב אליהם באופן שיקנה מהשלמו' כפי מה שאפשר וישמר מהשגגות מעניינים התוריים כמו שקדם. או היה הרצון בזה שנתן השם יתעלה לכהנים אלו המתנות בעבור שישאו את עון העדה ויכפרו עליהם כאלו יאמר שזה שכר להם חלף עבודתכם והביאור הא' הוא יותר נאות לפי מה שאחשוב:
@300 **הן לא הובא מדמה על הקדש פנימה.** ר"ל שלא היה דינה לישרף כי לא הובא את דמה אל הקדש פנימה ומזה המקום נלמד שאם נכנס דם חטא' הנאכלת לפנים ממחיצתו דינה לשרף ומפני שאמר פנימה נלמוד מזה בכל חטאות שנכנס דמו לפנים ממחיצתו שהוא נפסל ודינו לישרף ולזה יהיה נפסל החטאת אשר יזו מדמו על הפרכת ועל קרנות מזבח הזהב אם הכניסו מדמו לבית קדשי הקדשים שהוא פנימה כחק הדם ההוא:
@301 **וידבר אהרן אל משה הן היום הקריבו בני את חטאתם ואת עולתם לפני יי' תקראנה אותי.** כמו אלו המקרים הזרים שמתו בהם:
@301 **ואכלתי חטאת היום.** הזה בעינו שהיו בו בני חיים ומתים:
@301 **הייטב בעיני יי'.** שאהיה אוכל החטאת הזאת הנוהגת לדורות באנינות הנה אין ראוי שנקל בקדשים הנוהגים לדורות כי זה השעיר הנשרף היה שעיר ראש חדש כמו שזכרנו ולולא זה לא היה לאהרן התנצלות בזה המאמר והנה יתבאר שהיה ראש חדש ביום ההוא ממה שאומר. וזה שכבר נזכר בסדר ואלה פקודי כי באחד לחדש נשלמה הקמת המשכן שנאמ' באחד לחד' הוקם המשכן ונזכר בפרשת נשא כי ביום כלו' משה להקים את המשכן נשלמה משיחתו וקדושו וקדוש מזבח ומשיחתו ושביום ההוא התחילו הנשיאי' להקריב קרבנם לחנכת המזבח ולזה יתבאר שהוא יום השמיני הנזכר בזאת הפרשה כי אז נשלם קדוש המזבח ומשיחתו ואז היתה חנוכת המזבח על ידי הכהנים ולזה היו שם ביום ההוא שלשה שעירים לחטאות השעיר הנזכר בזאת הפרשה ושעיר נחשון הנזכר בפרשת נשא ושעיר ראש חדש והנה היו שעירי הנשיאים לפי מה שאחשוב לכפר על מעשה העגל כי על חטא ע"ז יקריב כל נשיא בכל שבט פר ושעיר כמו שזכרנו במה שקדם ולזה בא זה הקרבן באופן מתיחס לקרבן שגגת ב"ד הגדול שטעה בהוראה בעניין ע"ז. ואיך שיהיה הנה לא היה קרבן הנשיאים אלא לפי שעה ולזה לא יתכן שנאמר שיהיה זה השעיר שנשרף שעיר נחשון ויתבאר גם כן שזה היה שעיר ראש חדש לפי שנאמר בכאן ואותה נתן לכם לשאת את עון העדה לכפר עליהם וכבר נאמר בשעיר רא'ש חדש ושעיר חטאת אחד לכפר עליכם והנה למדנו מזה שאנינות של תורה אינו נוהג אלא ביום המיתה לבד שנאמר ואכלתי חטאת היום למדנו כי ביום ההו' לבד היה נוהג והנה התנצל אהרן לבדו בזה המאמ' ולא חשש להתנצלות בניו כי בהתנצלותו די התנצלו' להם וזה שאם לא היה ראוי שיאכל כהן גדול קדשים כשהוא אונן אע"פ שהותר לו לעבוד באנינות כמו שיתבאר כל שכן שהכהן הדיוט לא יתכן שיאכלם כי הוא נזהר מעבו' באנינו' כמו שיתבאר:
@302 **וישמע משה ויטב בעיניו.** ר"ל שכבר ראה שמה שנעשה כדין נעשה והנה הורה זה על זריזות משה לקיים מצוות השם יתעלה עד שהעלימה ממנו זריזותו ההתישבות על זאת המצוה שבאתהו מאת השם יתעלה באופן שיעמדו על עניינה אם היא נוהגת בקדשי שעה לבד או תנהג גם כן בקדשי דורות עם שרוב התבודד שכל משה במושכלות היה מונע אותו מהשיב מחשבתו באלו העניינים המעשים הפנמיים באופן שלם הלא תראה שזה היה מונע אותו מלסדר דבריו עם בני אדם באופן ראוי ולזה היה אהרן לו למליץ כמו שנזכר בסדר ואלה שמות:
@303 **וידבר יי' אל משה ואל אהרן לאמר אליהם.** להעיר שרוב התבודדות משה במושכלות היה סבת שגגתו במה שקצף על שריפת שעיר החטאת זכר בזה הדבור אהרן להעיר כי מזה הצד בעינו חייב שיהיה לו לאהרן למליץ לדבר הדברים לישראל בעבורו כמו שזכרנו:
@304 **זאת החיה אשר תאכלו מכל הבהמה אשר על הארץ.** הנה היה הוא שם יאמר בכלל על החיה והבהמה וכן העניין בבהמה כמו שזכרנו במה שקדם:
@305 **כל מפרסת פרסה ושוסעת שסע פרסות.** ר"ל במפרסת פרסה שלא יהיו לה אצבעות וצפורנים כמו הכלב והחתול והדומה להם ולהרחיק בעלי הפרסה העגולה כמו החמור והסוס אמר ושוסעת שסע פרסות רוצה לומר שתהינה ברגל אחד שתי פרסות כמו העניין בבקר ובצאן:
@305 **מעלת גרה בבהמה אותה תאכלו.** התנה עוד בבהמה המותרת באכילה שתהיה מעלת גרה כמו הענין בבקר ובצאן לא תותר באכילה אם לא ישלמו בה שני אלו התנאים כמו שזכר אחר זה וכבר התבאר מהשרשים הכוללים שאמרו מפרסת פרסה ומעלת גרה אינם ענינים מצואים אבל הרצון בו שיהיה דרך הב"ח ההוא להיות טבע מינו להיות לו פרסה שסועה ולהעלות גרה ולזה יתבאר שהנולד מן המינים הטהורים אף על פי שאין לו פרסה שסועה ואינה מעלת גרה בפועל הוא מותר לפי שדרך מינו להמצא בו אלו הסמנין ושהנולד מן המינים הטמאים אף על פי שיש לו פרסה שסועה והיא מעלת גרה בפועל הוא אסור לפי שאין דרך מינו להמצא בו אלו הסמנים אבל היה זה ביצירתו שבוש משבושי החומר:
@306 **אך את זה לא תאכלו וגומ'.** הזכיר התורה לא תעשה באכילת המינין מהבהמה והיה הבאים בסימן אחד מסמני טהרה ושתקח מהמינין שאין להם סמן טהרה כלל כי הם יותר ראוים בזה הדין ולזה יתחיבו מלקות על אכילת כל בהמה היה שאין לה שני סמני טהרה:
@306 **טמא הוא לכם.** אין הרצון בזה שיהיה טמא בעודו חי אבל ירצה שנבלתו טמאה כמו שביאר אחר זה או ירצה בזה שראוי שירחקו מאכילתו:
@310 **מבשרם לא תאכלו.** ר"ל אף על פי שנשחטו כי אין השחיטה מועילה בם:
@310 **ונבלתם לא תגעו טמאים הם לכם.** ראוי שנדע שהנוגע בנבלתם לא יעבוד על לא תעשה שהרי מצאנו כי גם בטומאת מת לא נזהרו כי אם הכהנים והנזיר כמו שיתבאר במה שיבא ולזה יהיה הרצון בזה שאם יגעו בנבלת אלו המינים הטמאים נטמאו וכאלו אמר שיתרחקו מנגוע בנבלת כדי שלא יטמאו ולזה אמר אד זה ולאלה תטמאו ר"ל שאם תגעו בהם תטמאו והוא מבואר שאין אמרו ולאלה תטמאו מצות עשה אך ר"ל שאם תגעו בהם תטאו כמו שביארנו ולזה גם כן לא יהיה אמרו ובנבלתם לא תגעו מצות לא תעשה והנה התנה השם יתעלה בבהמה הנאכלת שיהיו בה שני אלו הסימנין שזכרנו כי היא היותר נאותה למזג האדם להזון ממנה כמו שנבאר וזה שהשם יתעלה לבחרו בישראל ורצותו שיהיה עם חכם ונבון הרחיק מהם המאכלים המעבים החומר ונותנים עבירות לשכל והרחיק מהן גם כן המאכלים המזיקים והבלתי נאותים ואולם שאלו המינים כשימצאו בהם ב' אלו הסמנים הם היותר משובחים הנה יתבאר זה ממה שאומר וזה שהפרסה עגולה הוא כלי מלחמה לבעלי הפרנסה היא וכן האצבעו' בחיה הם כלי כמו שהתבאר בספר ב"ח והנה ב"ח הנלחמים הם בלי נאותים המזג להזון מהם לפי שכבר תגבר עליהן בהכרח הליחה השחורית או האדומית עד שלאלו הב"ח תמצא על הרוב ליחה ארסתי. ואולם הפרסה שסועה איננה כלי להלחם ולזה היו אלו המינים יותר נאותים והתנה שיהיו מעלת גרה כי זה יורה על החומר הדק אשר הוא נאות להיזון ממנו האדם לפי שחמרו הוא בתכלית הדקות ביחס אל שאר המורכבות כי המזון כל מה שיהיה יותר דומה לעצם הנזון היה יותר נאות לו. וכבר התבאר בספר ב"ח כי כל מה שהיה הב"ח יותר נכבד הכין לו הטבע בטנים יותר אל העכול להיות המזון יותר רחוק מעצם הנזון ויצטרך לשנויים רבים קודם שובו לעצצם הניזון לדקות המרו ולזאת הסבה היה דרבוי הבטנים בב"ח הוראה על דקות החומר ולפי שבה עלות הגרה היה נשלם רבוי הבטנים ולזה הב"ח כי עם שלו בטנים רבים הנה הערים הטבע ושמהו מעלה גרה לכפול פועל קצת בטניו הנה הוא מבואר שהיות הב"ח ומעלה גרה מורה על דקות חמרו ולזה הוא מבואר כי אלו הסימנים מורים אל האותות הבעל חי למזנים האנושיים:
@311 **את זה תאכלו מכל אשר וגו'.** הנה מפני שהב"ח היותר נכבד הוא ההולך ואחריו המעופף. והב"ח היותר חסר הוא אשר במים כמו שזכרנו בפרשת בראשית והתבאר זה בספ' הב"ח. הנה היה הסדר נותן שיזכור אחר החיה והבהמה מיני העוף הטמאים והטהורים קודם שיזכור סימני הדגים אך מפני שלא מצאה התורה בעופות אותות נראים לחוש יספיקו לבאר הטהור מהטמא המשיכה התורה המאמר בדגים להמצא בהן סימנים מספיקין לבאר המותר מהאסור כמו הענין בבהמה:
@311 **כל אשר לו וגומ'.** סנפיר הוא כמו כנף שפורה בו במים וקשקשת היא דבוקה בגופה:
@311 **במים בימים ובנחלים.** הנה הימים הם המימות המלוחים כמו ים הגדול והנחלים הם המימות המתוקים ואמר במים תחלה כי הוא יכלול כל המימות המלוחים והמתוקין ואף על פי שלא יקרא משוה המים ההוא ים ולא נחל:
@311 **אותם תאכלו.** ר"ל אותם שיש להם שני אלו הסמנין וראוי שנדע כי אף על פי שלא יהיה להם ב' אלו הסמנין בפעל אם היה מדרכם שימצאו להם הנה הם מותרים באכילה וזה יתבאר מהשרשים הכוללים וכל אשר אין לו סנפיר וקשקשת במים ר"ל במים המלוחים והמתוקים משרץ המים ומכל נפש החיה אשר במים ר"ל במים הדומים לימים והנחלים שאינם בכלים ואמנם המים אשר הם בכלים או בשיחין ומערות אם נתעפשו והתליעו לא יאסר השרץ ההוא מזה הצד ואולם אם פרשו מהמים יאסרו מפני שרץ השורץ על הארץ כמו שיתבאר אחר זה והנה קרא שרץ ב"ח קטני הגוף אשר במים כי שרץ יאמר על מה שהוא קטן הגוף מהב"ח וקרא חיה הב"ח אשר במים שאינם קטני הגוף:
@313 **ושקץ יהיו לכם מבשרם לא תאכלו וגומ'.** הנה באר בזה הפסוק מה שנרצה באמרו שקץ הוא לכם והוא שהאוכל מהם עובר בלא תעשה ושראוי להתרחק מנבלתם אך לא תטמא כמו הענין בנבל' בהמה טמאה:
@314 **כל אשר אין לו סנפיר וקשקשת במים שקץ הוא לכם.** הרצון באמרו במים מה שידמה למיני המים שזכר אבל לא ינהג זה הדין במה שיולד במים שבכלים מעפוש המים ההם כמו שזכרנו והנה התנה השם יתעלה בדגים הנאכלים שיהיו בהם שני אלו הסמנים שזכרנו כי הם היותר נאותים למזב האדם לדקות חמרן ביחס אל שאר הדגים וזה שהקשקש בבעלי הקשקשי' יורה על שלמות החום היסודי לברר החלק הארצי בהויה ולעשות ממנו אלו הקשקשים במקום שילקח בו תועלת לשמירת הב"ח ההוא עם שזה יורה על דקות החמר להתפעל בקלות מהדברים א'ר מחוץ ולזה הערים הטבע לעשות להם אלו המגינים ואין העניין כן בב"ח הקלפי כי הקליפה המקפת בו מורה על עובי החמר כמו שהתבאר בביאורנו לספר ב"ח וכן הסנפיר כלי עוזר לקלות התנועה לזה הדג ויעמוד זה גם כן להשים זה הדג נאות למזגים האנושיים כמו שיתבאר בעיון מעט במלאכת הרפואה כי שם התבאר שהאברים היותר רבי התנועה הם יותר נאותים למזון האדם כי התנועה מביאה שתדחה המותרות ותדקדק החמר:
@314 **שקץ הוא לכם.** הנה לא אמר שיהיו טמאים כמו הענין בבהמה כי אין נבלתן מטמא אבל אף על פי הם משוקצים לנו עד שנתרחק מאכילתם תכלית הרחוק והנה נבאר בג"ה בסוף זה הסדר למה לא תנהג טומאה בדגים ושם נתן סבות ענין הטמאות והטהרות ביותר שלם שאפשר לנו:
@315 **ואת אלה תשקצו מן העוף וגומ'.** הנה הודיענו בזה הפסו' שלא תנהג טומאה בנבלת העוף הטמא כמו שלא תנהג בדגים אבל יהיו משוקצים ונתעבים באופן שנשמר מאכילתם:
@315 **את הנשר ואת הפרס ואת העזניה.** אחשוב שהעזניה הוא שקורין אצטרז' ואוכל הברזל והזכוכית. ופרס גם כן היא עוף גדול בלתי נמצא ביישוב אמרו שהוא נקרא בערבי אלעק"ב:
@316 **והדאה.** היא הראה הנזכרת במשנה תורה ואחשוב שהוא נקרא וולטור"א שהוא שם העופפות ואולי נקרא כן לקלות עופותו אמר כאשר יראה הנשר ונקראה ראה לפי שיש לה ראות טוב ואלו הכלים הכין לה הטבע להשיג הטרף ההכרחי לה ר"ל קלות העופפות וטוב הראות:
@316 **ואת האיה.** אמרו שהוא הנקרא אנסה' בלעז והיא גם כן הדיה הנזכר במשנה תורה ואם הזכיר שם שני אלו השמות כדי שלא יטעה האדם בזה המין כי יש שקורין אותו איה ויש שקורין אותו דיה והנה הפיר' זה המקובל בזה מחוייב שיהיה כן ככי מן השקר שנאמר שבזה המקום התיר הדיה ובמשנת תורה אסורה ואמר למינה להעיר שיש שם מין אחר מתיחס לזה והוא גם כן אסור כמוהו וזה כי מה שזכר הם מינים ולא אישי ולזה יהיה אמרו למינה או למינו או למינהו רבוי בענין זה המין כל עורב למינו אמרו שיש שם מין אחד מתיחס לו והוא הנקרא זרזיר אשטורניל"ו בלעז ונודע לנו זה בניסיון כי הוא שוכן עם העורב אמרו רז"ל לא לחנם הלך זרזיר אצל עורב אלא מפני שהוא מינו ואת בת היענה הוא עוף משמיע קול אבל ויללה והוא שוכן במדבר:
@318 **ואת התחמס ואת השחף.** הם עופו' לא נתבארו לנו ואפשר שנקרא תחמם מרוב הטרף כאלו יחמוס בזה שאר עופות ואפשר גם כן שנקרא שחף מרוב החום הנכרי אשר בו כאלו יהיה תמיד מוקדה:
@318 **ואת הנץ למינהו.** אמרו בו שהוא אשפרווי"ר בלעז ואמר למינהו להעיר כי שם מין אחר מתיחס לו והוא אסור כמוהו ואמרו רז"ל שהוא שורנ"יקא ולא נתבאר לנו עניין זה המין:
@319 **ואת הכוס.** אמרו בו שהוא פלקו"ן:
@319 **ואת השלך.** אמרו בו שהוא עוף השולה דגים מן הים:
@319 **ואת הינשוף.** אמרו שהוא עוף שהוא עף בלילה ונקרא ינשוף מעניין נשף:
@320 **ואת התנשמת.** אמרו שהוא עוף הנקרא ציויטא:
@320 **ואת הקאת.** אמרנו רז"ל שהוא עוף נמצא בכרכי הים הנקרא ג"כ קיק ולא נתבאר לנו עניין זה העוף כמו שלא נתבאר לנו רבי':
@320 **ואת הרחם.** הוא עוף מרחם מאד על אפרוחיו:
@321 **ואת החסידה.** אמרו שהיא דיה לבנה ונקראת כן לפי שעושה חסידות עם חברותיה במזונותיה:
@321 **ואת האנפה.** אמרו שהיא דיה רוגזנית ואמרו למינה לאסור מין אחר מתיחס לה:
@321 **הדוכיפת.** אמרו שהוא תרנגול הבר ונקא כך לפי שיש לו סגולה לחרק הסלע כאלו אמר דוכיפת רצוני שהוא עושה שנים מן הסלע כי הסלעים וההרים נקראו כפים אמר ובכפים עלו:
@321 **והעטלף.** ידוע והוא הנקרא קראט"א פאנדא:
@321 הנה אלו המינים לבדם הם האסורים בעוף השאר טהורים והנה לא נתנו התורה סימנים בזה להבדיל בין הטמא ובין הטהור כי לא נמצאו שם סמנים מורגשים יתנו האמת בזה ולפי שאלו המינים בלתי ידועים וכל שכן לנו להעדר הבקיאות ממנו בלשון הקדש טרחו רז"ל המכירים אלו המינים ומצאו קצת סמני יתכן שיוכרו בהם אלו המינים הטמאים וזה שכבר נתבאר להם בתפוש שאין כאלו המינים זולתי פרס ועזניה מי שלא יהיה דורס ואוכל שיהיה לו זפק או אצבע יתרה או שהיה קרקבנו נקלף ביד ולזה יהיה הדרך בזה לראות אם העוף דורס ואוכל שאם היה אוכל ודורס הוא בלי ספק מאלו המינים האסורי' כי בהם נכללו כל העופות הדורסים לפי מה שנאמר שנתאמת להם ואם אינו דורס ואוכל אם היה לו אחד מהשלשה סימנין שזכרנו הנה הוה טהור אם לא פרס או עזניה שאינם נמצאים בישוב לפי מה שאמרו ז"ל והנה יעזור לזה החפוש שכבר מנה הכתוב מינים טהורים בעוף והם תורים ובני יונה והנה ימצאו להם אלו הסימנין כלם ר"ל שיש להם זפק ואצבע יתרה וקרקבן נקלף ואינם דורסים ואוכלין והנשר הוא נמנה בראש העופות הטמאים והוא דורס האוכל ואין לו זפק ולא אצבע יתרה ולא קרקבן נקלף וכאשר התישב לנו זה הנה אפשר לנו לעמוד על הסבה אשר בעבורה נאסרו אלו המינים הנבחרים בסימנים הנזכרים וזה שהדורס הוא אסור לפי שהוא טורף והב"ח הנלחמין הם בלתי נאותים להזון מהם האדם כמו שזכרנו בעניין הבהמות הטמאות ומציאות הזפק מורה על דקות החמר כי רבוי המבונים אשר בהם יהיה העיכול מורה על דקות החמר וכבר ביארנו במה שקדם כי כל מה שהיה חסר הנזון יותר דק הוא יותר נאות למזון למזנים האנושיים מצורף לזה שמה שהיה עב החמר הוא נותן עכירות בשכל ומכבה אורו וזה הפך מה שכונה התורה בזה כמו שזכרנו במה שקדם וכן נאמר שהיות הקרקבן נקלף יורה על האותות וזה הכלי להטיב עכולו כי יותר יתחזק על פעל העכול בהיות זה העור והקרום בתוכו ממה שיתחזק בזה כשלא היה שם כי אם הבטן הזה בשרי לפי שהחום הטבעי יהיה שם יותר נשמר כשהיה הבטן הבשרי מקיף בבטן האחד וכבר זכרנו כי מה שהכין לו הטבע מהכלים יותר להטיב בו העכול בזה הוראה על רוחק המזון מעצם הנזון ובזה הוראה מה על דקות החמר על שהשלם העכול בזה הבטן הבשרי מורה על עבי החמר עם שכבר ישמר חומו היסודי בזה הבטן הבשרי לעביו ואולם האצבע יתרה איך יתבאר שלה רושם על שזה העוף נאות להזון ממנו האדם הנה הוא מקום עיון ואחשוב שזה אמנם יורה על שמזון זה הב"ח אינו מהטרף ולזה הושמה לו אצבע יתרה לעוזר על ההליכה ללקט הזרעים מעל הארץ ומה שידמה לזה ואמנם העוף הטורף לפי שלא יצטרך ללכת ללקט אבל יעוף וידלג להשיג טרפו לא הושמה לו אצבע יתרה עם שכבר תזיק לו האצבע יתירה לפועל הטריפה כי תסבך תנועתו בטרף ותבלבלה וג"כ מפני שהצפורנים הן כלי המלחמה בעופות הטורפים לא הושם להן אצבע יתרה כי לא יספיק המותר הארצי בהם לעשות ממנו הצפרנים באצבעות הרגל גדולות כמו שיצטרך לפעל הטרפה ושתהיין עם זה חמשה ולזה לא היתה בהם אצבע יתרה כדי שיספיק זה המותר למה שיצטרך לזה הב"ח מחוזק הצפרנים וגדלן ואמנם הפרס והעזניה עם המצא בם קצת אלו הסמנים לא היו מותרים לפי שאלו הכלים היה בהם מצד הזונם במזונות הקשים הנמצאים במדבר לא לדקות חמרם כי כל מה שהיה נזון הב"ח במזון יותר עב התחזק ההוראה על עבי חמרו הנה זהו מה שנראה לנו בזה לפי מה שאפשר לנו השגתו ממה שהנידו רז"ל מענין המינין ואלו הושגו לנו בחוש היינו מבארים זה ביאור יות' רחב אלא שעכ"פ כבר נתננו בזה הסבות הכוללות שאפשר שיתנהו בזה לפי השגתו:
@322 **כל שרץ העוף ההולך על ארבע שקץ הוא לכם.** קרא שרץ העוף קטני הגוף ממנו כגון הזבובין והיתושין והצרעה והדבורה ומה שידמה להן והנה היו אלו המינים אסורים באכילה כי נמצא בהן רבוי הרגלים וכבר נתבאר בספר ב"ח שזה הוראה על חלשת החום היסודי ורבוי החלק הארצי ומה שזה דרכו הוא עב החמר מאד והוא מפני זה בלתי נאות להזנת האדם כמו שזכרנו במה שקדם ואמנם נמצא בהן רבוי הרגלים לפי שכבר היה בהם עם זה כנפים שהם תמורת הידם ולזאת הסבה יהיה כל מרבה רגלים אסור וכן יאסר לזאת הסבה ההולך על גחונו כמו הנחש והתולעים שזה דרכ' כי ליתרון החלק הארצי וחלשת החם היסודי לא יתכן שיתחזקו הרגלים לשאת אותם ואע"פ שיהיו רבים ולזה לא ימצא הנחש כי אם בארץ החמה כי לא יוכל לחיות בזולת הארץ ההיא לחלשת החום היסודי וזה סבה שנית לאסור הדגים אשר אין לו סנפיר:
@323 **אך את זה תאכלו מכל שרץ העוף ההולך על ארבע אשר לו כרעים ממעל לרגליו וגומ'.** ר"ל שהן ידלגו על הארף ולא יעופו בכנפיהן ולפי שהדלוג ישלם בכפיפת הכרעים והתפשטותם הושמו להם אלו הכרעים ויעזרו להם כנפיהם בזה הדלוג כי הם ידביקום זה לזה כשירצה לדלג המו שיעשה האדם באופן מה מידיו כשירצה לדלג והנה מפני שאין אלו הכנפים לעוף בהם ולא יהיו להם כי אם ארבע רגלים ולזה לא ימנו אלו המינים בכלל מרבה רגלים כי הם לא ישאו גופם כי אם בדק' הרגלים והכנפים הושמו בהם להטיב תנועתם לא לתמורת הידים או נאמר כי אין רבוי הרגלים מהן מהכרח החמר לעביו אבל יה זה מפני יתרון השגחת הטבע באלו המינים כי מפני שתנועתם הוא בדלוג הנ מן ההכרח שיהיו להם הכלים שבהם ישלם הדלוג ביותר שלם שאפשר לפי המקבל:
@324 **את אלה מהם תאכלו את הארבה למינו.** הורה בזה שיש שם מין שני מתייחס לו שהוא מותר וארז"ל שהוא צפרת כרמים:
@324 **ואת הסלעם למיניהו.** הורה בזה שיש שם מין שני מתיחס לו הוא גם כן אותר ואמרו רז"ל הוא יוחנה ירושלמית:
@324 **ואת החרגול למינהו.** אמר רז"ל שהמין המתיחס לו הוא גם כן מותר והוא עוצדניא:
@324 **ואת החגב למיניהו.** ארז"ל שהמין המתיחס לו שהוא גם כן מותר הוא הדוכנית ולפי שאלו המינין יקשה הכרתם וכ"ש לנו להעדר הבקיאו' ממנו בלשון הקדש בה העת שאנחנו בו טרחו רבותינו המכירי' אלו המינין שהתירה התורה מהחגבי' ונתנו לנו סימניה' והם שיש להם ד' רגלי' וב' קרסולי ברגליהם האחרוני' ויש להם ד' כפנים חופים רוב ארך גופם ורוב הקפו ומה שזולת זה הם טמאים ומה שהיה מהם ראשו ארוך ויש לו זנב איננו טהור אם לא היה שמו חגב ולזה הוא מבואר שאלו הסימנים לא ישפטו עכ"פ שיהיה הב"ח ההוא נאות למזגים האנושיים ואמנם היה זה כן כי בקצת המינים היה מהכרח החמר לעביו ולזה הוכנו להם רגלים רבים לשאת גופם ובקצת המינים היה להטיב תנועתם כדי שישלם להם הדלוג בקלות ולא לעבי החומר וזה ידוע למי שראה אלו המינים והשיג טבעם יתברך האל היודע טבע הדברים בלבד בשלם שבפנים אשר מהידיעה היא נסתעפו אלו הדינים במיני הב"ח לברור מהן הנאות למזון האדם מהבלתי נאו' אם מצר החליאו הגוף אם לא מצד עבותו החמר באופן שיכבה אור השכל מהשיג מושכליו ולזה תמצא ביארה התור' שכבר נשקץ נפשותינו אם נאכל הב"ח שמנע ממנו וכבר יעיד החוש על אמתת זה במה שנמצא מאומתנו מחזק ההכנה לחכמה יותר משאר אומות כמו שהעיר' התורה באמרה רק עם חכם ונבון וגו'. והנה לזאת הסבה מנעה התו' אכילת פירות אילו ג' שנים כי על הרוב באלו הגק' שנים ישתמש האילן במה שיקחהו מהמזון לגודל גופו ולא יתחזק מפני זה עד שיהיה שם מותר במזון טוב הבשול וההצטמקות אשר יהיה ממנו הפרי כי הטבע לא יתחזק על כל אלו הפעולות יחד ולזה יהיה הפרי ההוא בזה הזמן חלוש החום היסודי ורב הלחות הנכרי ומפני זה בלתי נאות למזון לעניו ומפני זאת הסבה בעינה תמצא באדם שאינו ראוי כלל להוליד עד הגיעו לי"ג שנה ויום א' כי לא יתחזק על טוב בשול הזרע כראוי לרוב המזון שיצטרך לו לגדול גופו וגם כן לא תהיה הולדתו שלמה אחרי כן עד שהגיעו לעשרים שנה כי אז יתחזק באופן שלם על בשול הזרע למעוט הגדול הנמצא בו אז ושלמות טבעו בזה העת ולזה לא יכנס האדם בגדר פריה ורביה עד שהגיעו לעשרים שנה כמו שביארנו בפרשת בראשית:
@325 **וכל שרץ העוף אשר לו ארבע רגלים שקץ הוא לכם.** שב לזכור זה שנית להורות על שלא יטמאו כמו הענין בנבלת בהמה אבל הוא משוקץ ומתועב מלאכלו:
@326 ולזה סמך אמרו **ולאלה תטמאו** כאלו אמר שלאלו לא נטמא אם נגע עם שכבר כלל בזה המינים שלהם כרעים לנתר בהם על ארץ מלבד המינים שזכר מהם שהן מותרין באכילה ולאלה תטמאו בעבור שלא זכר טומאה במיני הבהמה כי אם בנבלת הגמל והשפן והארנבת והחזיר שב לבא' שנבלת שאר המינין שאין להם פרסה שסועה ואינה בעלי גרה היא גם כן טמאה:
@326 **כל הנוגע בנבלתם יטמא עד הערב.** ובערב יטהר כשיטבול במים כמו שיתבאר במה שיבא וכל הנושא מנבלתם יכבס בגדיו וטמא עד הערב למדנו שמשא הנבלה חמר מהמגע שמנעה אינו מטמא בגדים ומשאה מטמא בגדים:
@328 **לכל הבהמה אשר היא מפרסה פרסה ושסע איננה שוסעת.** ר"ל שאין לה פרסה שסועה אבל יש לה פרסה עגולה כמו הענין בגמל ובחמור ובסוס וגרה איננה מעלה כמו הענין בחזיר ושאר המינים שאינן מעלין גרה מהמינים שיש להן פרסה או פרסות:
@328 **טמאים הן לכם כל הנוגע בהם יטמא וגומ'.** ר"ל שנבלתן כמו שזכר בראש זה המאמר:
@329 **וכל הולך על כפיו בכל החיה ההולכת על ד'.** הם אשר יש להן אצבעות ברגליהם כמו הכלב והחתול והזאב והשועל ומה שידמה להם ואמנם אמר בכל החיה ההולכת על ארבע להוציא מזה העופות הטהורים כי הם הולכים על כפיהם אך אינן הולכים על ארבע כי אין להם כי אם שתי רגלים ללכת בהם ובכנפיהם יעופו והנה ביאר שנבלתם מטמאה במגע ובמשא ואמר באחרונה טמאים הם לכם להורות שאסור לאכלם כמו שאר אחר זה בגמל ושפן וארנבת ובחזיר לזאת הכונה בעינה ולזה אמר אחר זה שם מבשרם לא תאכלו:
@329 **הנוגע בנבלתם יטמא עד הערב.** כמו שהתבאר זדה מדין הנבלה והנה לא זכר בזו שתטמא במשא ואי אפשר שנאמר שתהיה טומאתה למטה לטמאת נבלת בהמה טמאה באופן שלא תטמא במשא כי היותר נכבד יותר ראוי בטמאה לפי מה שהקדמנו ולזה הוא מבואר שכבר רמז בטומאת המשא במה שאמר והאוכל מנבלתם יכבס בגדיו והוציא זה בלשון אכילה ללמדנו שני עניינים. האחד שלא נחשוב אם חשב עליה לאכלה שיהיה דינה דין האוכלים והטמאים שנזכרו קודם זה שלא יטמאו אדם וכלים ולא אוכלין ומשקין שהן חולין. והשני ללמדנו השיעור אשר בו תטמא הנבלה הזאת במגע ובמשא והוא כזית שהוא שיעור אכילה ואמנם הוצרכה התורה לזה לפי שבנבלת הבהמה הטמאה למדנו מזה מפני שסמך עניין טומאתה לאסור אכילתה באמרו מבשרם לא תאכלו ובנבלתם לא תגעו וכבר מצאנו במקם אחר שאמר התורה זה הלשון ואין הרצון בו כי אם לשיעור אמרה בבית המנוגע. והאוכל בבית יכבס את בגדיו. והרצון בזה שישהה שם שיעור אכילה כמו שנבאר שם בגזרת השם וכן יהיה הרצון בזה המקום באמרו והאוכל מנבלתה שישא ממנה שיעור יתכן בו אכילה והוא כזית וכן מצאנו שהרצון באמרו ומזה מי הנדה יכבס בגדיו שישא מהן כשעור הזאה כי אם יזה מהן איננו טמא כמו שנבאר שם בגזרת הצור:
@331 **וזה לכם הטמא וגו'.** הנה אעפ"י שאלו השרצים הוא מסוג הבעל חי ההולך והיה ראוי פני זה שיקדים לשרץ העוף הנה לא זכרה התורה עניינם כי אם בסוף לפי שלא מצאנו בהם מין נאות למזון כמו העניין בשרץ העוף ולזה לא היה המאמר בזה להבדיל הנאכל מן הבלתי נאכל כמו הענין במה שזכרה קודם זה מענייני הבעל חי בזאת הפרשה אבל הבדילה המטמא ממנה מהבלתי מטמא ממנה עם היותם כלם אסורים באכילה כמו שזכר אחר זה וכל שרץ השורץ על האד' שקץ הוא לא יאכל:
@331 **החולד והעכבר והצב למינהו.** הנה הצב לפי מה שאחשוב הוא השרץ הנקרא אורא"ן בלעז והוא מתנפח מאד בעת כעסו עד שיבקע וימות ואותו האיד היוצא ממנו ימית כל מה שיפגש מהבעל חי ולזה נקרא מעניין לצבות בטן והאנקה הוא שרץ איריצו"ן בלעז ונקרא כן בעבור שהוא צועק והכח הוא הנקרא לדיר"ט בלעז והוא רב הארס מאד והלטאה הוא לגר"מ וראדה בלע"ז והחמט אמרו בו שהוא הנקא ליאסה ולפי דעתי הוא הקרוי אלברינה והוא מהשרצים הארסיים הממיתים והתנשמת אמרו בו שהוא הנקרא בלעז טלפ"א ואחשוב שהוא שקורים לו דרבוץ בלעז שאין לו עינים ואוכל שרשי העשבי' תחת הקרקע:
@333 **אלה הטמאים לכם בכל השרץ** ר"ל ששאר השרצים לא יטמאו מה שיגעו בו כאלו תאמר הנחש והעקרב והעכביש והדומה להם ואמנם שאלו המינין בלתי נאותי' למזון הנה זה מבואר ממה שהיה מהן בעל ארס או ממית כמו החולדה והצב והכח והחמט ואולם שאר המינין יתבאר שהם עבי החמר מאד ולזה תמצא בעכבר שיזון מהקלף והבגד עם קשים והיותם בלתי ראויים למזון לרב ממשלת הטבע הארצי בהם כי המזון מתיחס ודומה לנזון כמו שהתבאר בטבעיות ותמצא בהלטאה שאם תחתוך זנבו תתנועע אחר זה זמן ארוך לקרבתה מטבע הצמחים כמו שנזכר בספר ב"ח והאנקה גם כן ירה על עבי חמרה היות השער ארש בעורה כדמות קוציות והתנשמת גם כן יורה על עבי חמרה היות משכנה תמיד תחת העפר והיות לזונה תמיד העפר ובמה שהיה מהצמחים יותר מתייחס לטבע העפר וכאשר ישאל שואל ויאמר אם היה שנתרחקו אלו השרצים מפני היותם בלתי נאותים למזון האדם מפני עבי חמרם או ארסיותיהם למה לא נמנו עמהם הנחש והעקרב והעכביש ודומיהם שיראה מעניינם שהם ארסיים והם עם זה עבי החמר מאד וזה יתבאר מהנחש שהוא הולך על גחונו לפי מה שזכר במה שקדם וביתר השרצים זכרנו מפני קרירותם ורבוי הרגלים אשר להם ונאמר שאם היתה בזה העניין לברור הבלתי נאותים מהנאותי היה זה הספק מחויב מזה הצד אלא שאתה לא תמצא שהתירה התורה הנשארים מהשרצים על הארץ באכילה אך מנעתה אותם כלם והנה בררה התורה היותר שלמי הבריאה באלו השרצים לזה הדין שזכרה רוצה לומר לטומאה והשאר אינם מטמאין להיותם חסרי הבריאה ולזה תמצא שכל אלו המינים הנזכרים פה מהשרצים הם הולכים על ארבע כמשפט הבעל חי השלם וכבר תמצא שכבר המשיכה התורה זה הענין בדבר הטומאה ר"ל שכל מה שהיה הב"ח יותר שלם היתה נבלתו יותר חזקת הטומאה מכל הנבלות ואחריה נבלת הבהמה והחיה ואחריה נבלת השרץ השורץ על הארץ והנה בעופות הטמאים ובדגים ובחגבים לא זכרה התורה וטומאה לחסרון יצירתם וכן הענין בזה המקום רוצה לומר של חסרון יצירת שאר השרצים לא זכרה התורה בהם טומאה ולא נשתתפו כל השרצים השורצים על הארץ בעניין האסור באכילה להיותם כלם בלי מנאותים למזון:
@333 **כל הנוגע בהם יטמא עד הערב** אמר במותם לפי שהם לא יטמאו אלא בהיותם לחים אבל אם יבשו באופן שאין בהם כח לשוב לחים לא יטמאו ולזאת הסבה לא יטמאו עצמות השרץ וצפורניו וגידיו ועורו במה שהיה מהם שימצא לו עור יבש והנה אלו השרצים אינם מטמאים במשא ובזה האופן היתה נבלתם למטה מנבלת בהמה וכל אשר יפול מהם עליו במותם יטמא לפי מה שאמר ממנו למדנו שאבר מן החי הפורש מהם הוא יהיה טמא גם כן אלא שהוא יהיה טמא כשיהיה כליי רוצה לומר שיהיה בו בשר גידים ועצמות כמו העניין בכללות השרץ וזה הדין גם כן ינהג בנבלת בהמה כי אמר מנבלתם ובכלל הנה האבר שבזה התאר מתיחס לכללות הבעל חי כי יש בו רבוי המתדמי החלקים ובו כח שומר מציאותו ולזה אם לא היה בשר כדי להעלות בשר ארוכה לחי אינו מטמא והוא מבואר שהבשר הפרוש מן החי אינו ראוי שיקרא נבלת החי ההוא משני צדדין הצר האחד שכבר יתכן שיחליף הבע' חי הבשר ההוא ולא יחסר אבר בעבורו ולזה לא יתכן שיקרא נבלתו והצד השני שאינו דומה לכללות הבע' חי ההוא כשהיה בו רבוי המתדמי החלקים כאלו תאמר בשר וגידים ועצמות והנה שיעור נבלת הבהמה הוא כזית לפי שסמך טומאתה לאכילתה אמר מבשרם לא תאכלו ובנבלתם לא תגעו וכבר התבאר בשרשים הכוללים ששעור האכילה הוא כזית לא יבלעו יחד בבית הבליעה יותר מכזית לפי הנהוג באכילת אדם ואמנם בשרצים לא סמך טומאתם לאכילתם כי אין בהם דבר יהיה ממנהג האדם לאוכלו ואף אם לא היה בעל דת ולזה יהיה שיעור טומאתו שוה לשיעור אבר היותר קטן שבהם והוא כעדשה לפי מה שהתבא' בחפוש ר"ל באבר שהיה בו בשר וגידים ועצמת באופן שיהיה ראוי שיקרא לבדו וזה האבר הוא מקצת השרץ שהוא ככלו וגם כן הנה מפני שהיו אלו השרצים הנאכלים לחיות קטנות הגוף מן האדם כאלו תאמר שהעכבר יאכלהו החתול הנה אולי הנהוג מאכילת אותו הבעל חי יחד בבית הבליעה אינו יותר מבעדשה כי אולי יחס גודל העדשה אל גודל הזית הוא יחס קטן הגוף ההוא לאדם וגם כן אפשר שלמדנו זה השיעור מיחס זה השרץ אל הבהמה והחיה ממוצעת הגוף כי הוא אולי הוא כיחס עדשה אל הזית והנה זה השיעור מקובל איש מפי איש עד משה רבינו ולפי שסמך דין טומאת הנבלה לאכילתה למדנו מזה שכאשר נפסלה מלאכול והבאישה ביותר אינה מטמאה וכן הענין בשרץ כי טמאתו יותר קלה:
@334 **מכל כלי עץ או בגד אנו עור או שק.** למדנו שאלו הכלים כלם יש להם בית קבול כמו השק העשוי לשאת בו הדברים ולהשימם בו אלא שזה הכלי קבול יהיה מער או מבגד והוא הנעשה מצמר או פשתים או משי או קנבץ ופעם מעור ופעם משער העזים והחזיר וזנב הפרה ומה שידמה להם והוא הנקרא שק ולמדנו מזה שראוי שיהיה זה הכלי מטלטל מלא וריקן כמו הענין בשק ואז ינהג בו זה הדין וגם כן מפני שהבגד והעור והשק עשויים לפי הנהוג מהבעל חי הגדלים ביבשה למדנו מזה שאין זה הדין נוהג אלא כשיהיו מהבעל חי הגדלים ביבשה לא מסוג המעופף והשח וגם כן מפני שהבגד והעור והשק הם כלים עשויים ממותר הארצי אשר בבעל חי ההולך שישתמש בו הטבע לתועלת הנה נלמד מזה שכן הדין בכלים העשויים מעצמות הבעל חי ההולך והקרנים והטלפים כי היותם בבעל חי הוא מזה המותר גם כן וכבר ישתמש בהן הטבע לתועלת מבואר. ויתחייב מאמרו כלי עץ או בגד או כל כלי חרש וגומר שתהיה מלאכתו נגמרת קודם שיקבל טומאה כי לא ישתמשו בו לפי הנהוג עד שתגמר מלאכתו ולזה לא יקרא כלי קודם זה וכן יתבאר מזה שמה שנתחבר לכלי שאין לכלי צורך בו ולפי הנהוג לא יטמא הכלי בעבורו ולא יטמא הוא בעצמו כי איננו כלי ולא מהכלי ואולם ידות הכלי ומה שידמה להם מהמחובר לכלים אשר יש לכלי תועלת בהם דינם דין שאר חלקי הכלי וכן ראוי שנבין מעניין הכלים האלה שיהיה כלי לשמש האדם כי זה הנהוג מענין הכלים לא שיהיו כלים לשמש הכלים וג"כ הנה המכון בכלי הוא שיהיו כלי לאדם ובכלל הנה בענין הטמאות לא נלמד הפחות מהנכבד כי היותר נכבד הוא היותר ראוי בטומא' לפי מה שיתבאר ממה שזכרנו בענין הטמאו' וממה שנזכר בזה המקום בכלים וזה שהכלים הנעשים מהצומח והחי הם היותר מקבלים הטומאות מהכלי הנעשה מהעפר והוא כלי חדש כי הוא אינו מקבל טומאה אלא מתוכו כמו שיתבאר אחר זה ומזה המקום יתבאר שהדרך בטמאות שלא ילמד הפחות מהנכבד:
@334 **כל כלי אשר יעשה מלאכה בהם.** ר"ל אשר ישתמשו בהם בעצמם ולמדנו מזה שהכלים המחופים כלם ממתכת או מדבר אחר אין מקבלים טומאה כלל כי לא יעשה בהם בעצמם מלאכה אבל בהפוייהם וההפוי איננו בעצמו כלי ולזה לא יטמא:
@334 **במים יובא וטמא עד הערב וטהר.** רוצה לומר שיובא בכללותו במים ויהיה טהור אחר שיעריב שמשו והוא מבואר שאלו המים שיובא בהם ראוי שלא יהיו מקבלים טומאה שאם היו מקבלים טומאה הנה יטמאם הכלי והנה המים שאינ' מקבלים טומאה הם מיני מעיין ובור ומקוה המים אשר בקרק' כמו שאמר אחר זה אך מעיין ובור ומקוה מים יהיה טהור:
@335 **וכל כלי חרש אשר יפול אל תוכו.** למדנו מזה שאין כלי חרש מטמא אלא מתוכו לא מגבו ושהוא מטמא כשהגיע השרץ לאויר תוכו אף על פי שלא נגעה בו והוא מבואר מזה שאם היה כלי אחר בתוכו ונכנסה הטומאה באויר הכלי הוא שלא יטמא הכלי חד ההוא כי הטומאה היא תוך תוכו ולא בתוכו המיוחד והתורה אמרה כל אשר בתוכו ולא בתוך תוכו כמו שנ' במה שיבא וכן למדנו מזה שהכלי חרש שאין לו תוך אינו מקבל טומאה ושראוי גם כן שיהיה לו תוך עשוי לקבלה שנאמר כל אשר בתוכו יטמא מכלל שדרך הכלי הזה להשתמש בקבולו כל אשר בתוכו יטמא למדנו מזה שהכלי חרש הטמא מטמא האוכלים והמשקין אשר באוירו אף על פי שאינן נוגעין בו והוא שלא יהיו תוך כלי אחר שנאמר בתוכו ולא בתוך תוכו ולמדנו עוד שאינו מטמא הכלים שבתוכו שנאמר מכל האכל אשר יאכל אוכלין ומשקין מטמא ואינו מטמא כלים ואולם יתבאר שהאוכלין ומשקין יותר ראוין בטומאה מכלי' לפי שהם יותר נכבדים ממה שיקח האדם בהם מהתועלת יותר ממה שיקח מהתועלת בכלים כי מהמזונות יחיה וישובו חלק ממנו ואין ספק ששאר הכלין שנטמאו במגע השרץ יהיו גם כן מטמאין אוכלין ומשקין במגע ואמנם זכרה התורה זה בכלי חרש הקל בעניין טומאה וכן נבין שכן הענין בנבלת הבהמה בכל מה שנזכר בזה המקום מטומאת השרץ בכלים ובאוכלין ובמשקין ואולם זכרה התורה זה בטומאת שרץ הקלה כדי שנלמד ממנו טומאת נבלת בהמה. וראוי שנדע שאיך שהיה מצב הכלי חרש כיון שהוטמאה באוירו נטמא או כיון שהאוכלים והמשקין באוירו נטמא ואם היה הכלי חרש טמא וזה יתבאר מלשון זה הכתוב לפי מה שהתבאר. וראוי שלא יעלם ממנו שהכלים אינן מקבלין טמאה אלא ממה שיטמא האדם ולזה תמצא בנבלת השרצים שמטמאה האדם במגע ומטמאה כלים ואולם האדם שיטמא במגעה לזה יטמא הכלים ולזה אין טעון כבוס בגדים וכן העניין בגבלת הבהמה ר"ל שכאשר נגע האדם בה לא יטמא כלים ולזה אין טעון כבוס בגדים ואולם במשא הנבלה יהיה טעון ככוס בגדים כי הוא ובגדיו תטמאין יחד מטומאת הנבלה כאלו נשאות יחד ומזה המקום יתבאר שהטומאה כל מה שתרחק מהמקרה תחלש כי אין טומאה הנוגע בה במדרגת טומאתה ולזה לא יטמא האדם הנוגע בה הכלים כמו שתטמא היא כלים ולזה יתבאר שכל מה שתרחק ממקרה תרד המדרגה ותהיה הנבלה אב הטומאה והיא תטמא האדם וכלים לא מה שלמטה ממנה בטומאה והנה האדם או הכלי הנוגע בה הוא ולד הטמאה הראשון והנה יה שיגיעו בו הוא שני לטומאה ולפי שלא זכרה התורה שיהיו אלו האוכלי' מטמאין מה שיגיעו בו למדנו שאליהם תכלה זאת הטומאה ומזה המקום נתבאר שאין שני עושה שלישי בחולין ואולם בקדשים מדרגות אחרות כמו שיתבאר במה שיבא וראוי היה להיות כן כי הם יותר נכבדים וכל מה שהיה הדבר יותר נכבד הינה יהיה קבולו הטומא' יותר חזק כמו שנתבאר מדברנו וראוי שתדע שהכלי הוא ראשון אחר שטבל נשאר טמא עד הערב כמו שאמר במים יובא וטמא עד הערב וטהר והנה על כל פני' טהור בטבילתו מהטומאה שהיה בה ונתרחקה הטומא' ההיא מדרגה אחת ולזה ישוב הראשון שני כשטבל עד שיעריב השמש ואז יטהר וזה יתבאר ביאור שלם במה שיבא:
@335 **ואותו תשבורו.** למדנו מזה שאין לכלי חרש טהרה בטבילה אבל יטהר כשיבטלו אותו ויבטלו תשמישו וכן מצינו בכלי חרש שבשלו בו את החטאת שאין לו תקנה אלא שבירה וזה לחזק בליעת הכלי חרש מה שיבושל בו וראוי שיובן מזה שכן הדין בשאר הכלים רוצה לומר שכאשר נשברו טהרו כי הם כלי':
@336 **מכל האכל אשר יאכל אשר יבא עליו מים יטמא וכל משקה אשר ישתה בכל כלי יטמא.** ירצה בזה כי מה שאמר כל אשר בתוכו הרצון בו שיהיה מיוחד לאכילת אדם שאם לא היה העניין כן הנה יהיה אמרו אשר יאכל לבטלה כי מה שהוא אכל הוא בלי ספק נאכל מפני שיאכלוה ב"ח מה ואמרו אשר יבא עליו מים למדנו שאין האכל מקבל טומאה אם לא יבא עליו מים וכן זכר זה שנית' בזרעים מפני היותם אבל אמר וכי יותן מים על זרע ונפל הנבלתם עליו טמא הוא לכם ולפי שאמר מים בזולת הידיעה הנה כל מים במשמע ולזה יהיו שאר המשקין אשר יזון בהם האדם ומציאות מאדיי גם כן מכשירין לקבל טומאת כמו הטל והיין והשמן והחלב והדבש והדם ולא יהיו מכשירין מי פירות אחרים זולתם לפי שאין מציאותם מאדיי ולא נזון בהם האדם לפי הנהוג ולזה אין להם שם מים כי אם בקשור הפרות ההם להם כאלו תאמר שהם יקראו מי תותים מי רמונים ואולם ששם מים יתכן שאמר על אלו המינין הוא מבואר ממה שזכרנו בפרשת בראשית כי הגשם הבלתי שומר תמונתו וחלקנו עליו שם מים ולזה תמצא שקראו רז"ל מיין הפרות מי פירות וראוי שנדע שההכשר לאוכל באחד מאלו המשקין לא יהיה כשהיה האכל מחובר לקרקע שאם היה הדבר כן לא היה צריך להתנות וכי יותן מים על זרע בעודו מחובר וכן לא יוכשר האכל במים אשר בקרקע כל זמן שלא נתלשו משם שנאמר אשר יבא עליו מים וכי יותן מים וראוי שתדע שהאכל לא יוכשר לקבל טומאה אם יבא עליו משקה סרוח ונבאש כי הוא יות' ראוי שיבטלהו מתורת אכל למיאוסו לא יקבל טומאה כלל משיכניסוהו בגדר קבול הטומאה ועוד שנאמר אשר יאכל ואין דרך לאכול אוכל בלול במשקה נבאש ומוסרח ואולם שהדם מזון נמצא לאדם הנה זה מבואר מאד שהאכל לא יוזן ממנו האדם אלא באמצעות התהפכו לדם וכבר התבאר שאלו המשקין שיהיו מכשירין האוכלין הם נאותים להזון במה שנתן מהסבה בזה אצל נתינתנו הסבות באלו הטמאות וראוי שנדע שהאכל יקבל טומאה בכל שהוא שנאמר מכל האוכל אשר יאכל. כל זרע אפילו גרגיר זרע וכל משקה אשר ישתה בכל כלי יטמא. וירצה בזה כל משקה שיהיה דרך האדם לשתותו והוציא בזה מזה דין המשקה הנבאש והמשקה שמציאותו מעטי כגון מי פרות שאלו אינם מקבלין טומאה ואמר בכל כלי שהמים שלא היו בכלי כמו מי מקוה ומי מעיין אף על פי שנגע בהם הכלי הטמא או הנבלה והשרץ לא יטמאו כמו שאמר אחר זה אך מעיין ובור ומקוה מים יהיה טהור וכל אשר יפול מנבלתם עליו יטמא ר"ל כל אוכל מוכשר לקבל טומאה ומשקה מהמשקין שכלל בפסוק הקודם אם יפול עליו מגבלת השרצים האלו יטמא ולמדנו מזה שאינם מטמאין אחרים אף על פי שנטמאו בנבלה עצמה אך דינם כשנטמאו בנבלה עצמה כמו דינן שנטמאו בולד הטומאה או ירצה בזה והוא יותר נאות שאע"פ שנתבאר במשקין שמחובר לקרקע לא יקבל טומאה אין העניין כן בכלי חרש כי התנור והכירים שהם מחרס אף על פי שהם דבקים לקרקע הם טמאים מאוירם בנבלת השרץ כמו הענין בשאר כלי חרס ואיך שהיה הנה הדין שהוצאנו מהפירוש הראשון שהוא צודק והוא יתבאר ממה שאמר אחר זה וכי יותן מים על זרה ונפל מנבלתם עליו טמא הוא לכם ולא זכרה התורה שיהיה זה הזרע הטמא מטמא אחרים ולזה יתבאר שאליו תכלה הטמאה וכן העניין במשקין כי טומאתם שוה לפי מה שהתבאר בזה המקום:
@337 **תנור וכירים יותץ טמאים הם וטמאים יהיו לכם.** רוצה לומר שהתנור והכירים שהם מחרס או ממה שהתייחס לו הנה אף על פי שהם מחוברים לקרקע אם נפל בתוכם השרץ יטמאו ולא יצאו מטומאתם כי אם בשבירה כמו העניין בשבירה בכלי חרש אך מעין ובור מקוה מים יהיה טהור רוצה לומר אך לא יהיה זה הדין נוהג במשקין אלו כי המעיין והבור אשר בו מקרה מים הוא טהור אף על פי שנפל מנבלתם בו שלא יטמא המקום ההוא ולא המים אם לא נתלשו ממנו כמו שקדם:
@338 **ונוגע בנבלתם יטמא.** למדנו שאף על פי שהנבלה לא תטמא המים שם לא תטהר הנבלה בבאה במעיין או במקוה אבל הנוגע בנבלתה שם מהדברים שיקבלו טמאה ממנה יטמאו או כפל המאמר בזה להורות שנבלתם מטמאה במגע לבד לא במשא כמו העניין בנבלת הבהמה שמטמאה במשא:
@339 **וכי יפול מנבלתם על כל זרע זרוע אשר יזרע טהור הוא.** הטעם בזה לפי שלא הוכשר לקבל טומאה ואמר אשר יזרע להרבות שומר האכל ויד האכל לטמאה והכשר וזה שבזריעת הזרעים ימצאו קלפותיהם השומרות אותם עמהם וכן ימצאו קצתם בזרעם עם ידותיהם ולזה אמר שאין יותן מים על הזרע שזכר אז יקבל טומאה בכללו עם השומר והיד מנבלת השרץ וראוי שתדע שזה הזרע ראוי שיהיה נאכל לאדם ואז יקבל טמאה כשהוכשר כמו שהתבאר קודם ולפי שאמר וכי יותן מים על זרע שיורה על שלא בא שם במקרה אבל נתנוהו שם בכונה למדנו שלא יכשירו המים האוכלים לקבל טמאה אם לא באו שם ברצון הבעלים ולא יחוייב שיתנוהו הם בעצמם על הזרע שהרי אמר וכי יותן ומזה יתחייב גם כן שיהיו המים אם היו בקרקע נתלשין ברצון הבעלים כי הנתינה תורה על תלישתן מזה ועל עניין מכוון וכבר יתבאר לך שהשני עושה שלישי בקדש שנאמר בפרשת צו והבשר אשר יגע בכל טמא לא יאכל ולפי שכבר נקרא טמא בזאת הפרשה האכל והמשקה שהיה שני למדנו שהשני עושה שלישי בקדשים והנה נבאר בגזרת השם במה שיבא לפי מה שאפשר לנו למה לא יטמאו האוכלין והמשקין כי אם בזה האופן. רוצה לומר 'שתכלה אליהם הטומאה בחולין ואף על פי שכבר נגע בהם אב הטומאה:
@341 **וכי ימות מן הבהמה אשר היא לכם לאוכלה.** רוצה לומר אשר לה פרסה שוסעת והיא עם זה מעלת גרה אם תמות בזולת הזביחה הנזכרת בתורה כי לא נוכל לומר שתהיה בזביחה טמאה שהרי היא נאכלת לכהנים הנזהרים מהטומאות ולמדנו מזה שאם נזבחה אף על פי שנמצאת טרפה אינה מטמאה ולפי שכבר חלק בבהמה הטהורה לבד במיתה בין הזבוחה לשאינה זבוחה למדנו מזה מן הבהמה הטמאה לא יהיה הבדל בנבלתה בין הזבוחה לשאינה זבוחה:
@341 **הנוגע בנבלתם יטמא עד הערב.** כמו שהתבאר זדה מדין הנבלה והנה לא זכר בזו שתטמא במשא ואי אפשר שנאמר שתהיה טומאתה למטה לטמאת נבלת בהמה טמאה באופן שלא תטמא במשא כי היותר נכבד יותר ראוי בטמאה לפי מה שהקדמנו ולזה הוא מבואר שכבר רמז בטומאת המשא במה שאמר והאוכל מנבלתם יכבס בגדיו והוציא זה בלשון אכילה ללמדנו שני עניינים. האחד שלא נחשוב אם חשב עליה לאכלה שיהיה דינה דין האוכלים והטמאים שנזכרו קודם זה שלא יטמאו אדם וכלים ולא אוכלין ומשקין שהן חולין. והשני ללמדנו השיעור אשר בו תטמא הנבלה הזאת במגע ובמשא והוא כזית שהוא שיעור אכילה ואמנם הוצרכה התורה לזה לפי שבנבלת הבהמה הטמאה למדנו מזה מפני שסמך עניין טומאתה לאסור אכילתה באמרו מבשרם לא תאכלו ובנבלתם לא תגעו וכבר מצאנו במקם אחר שאמר התורה זה הלשון ואין הרצון בו כי אם לשיעור אמרה בבית המנוגע. והאוכל בבית יכבס את בגדיו. והרצון בזה שישהה שם שיעור אכילה כמו שנבאר שם בגזרת השם וכן יהיה הרצון בזה המקום באמרו והאוכל מנבלתה שישא ממנה שיעור יתכן בו אכילה והוא כזית וכן מצאנו שהרצון באמרו ומזה מי הנדה יכבס בגדיו שישא מהן כשעור הזאה כי אם יזה מהן איננו טמא כמו שנבאר שם בגזרת הצור:
@343 **וכל שרץ השורץ על הארץ שקץ הוא לא יאכל.** כלל בזה שמנה שרצים שזכר ושאר השרצים וביאר שהאוכל אותם עובר בלא תעשה ואחר כך זכר סוגיהן ואמר כל הולך על גחון וכל הולך על ארבע עד כל מרבה רגלים כי מהן הולך על גחון כמו הנחש ומה שידמה לו מהתולעים השורצים על הארץ ההולכים על גחונם ומהם הולך על ארבע כמו השמנה שרצים הנזכרים ועקרב ושאר השרצים ההולך על ארבע ומהם מרבה רגלים כמו הנדל והעכביש ומה שינהג מנהגם:
@344 **לא תאכלו כי שקץ הם.** ראוי שתדע שכל שנאסר באכילה בזה המקום הוא מותר בהנאה כבר תמצא זה בנבלה לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה או מכור לנכרי וממנה נקח ראיה על השאר וראוי שתדע שהשרצים ההוים מהעפוש באוכלים אינן אסורים באכילה בכל עת שלא יהיו שורצים על הארץ כי לא אסרה התורה מאלו השרצים אשר ביבשה כי אם השרץ השורץ על הארץ:
@345 **אל תשקצו את נפשותיכם בכל השרץ השורץ על הארץ.** למדנו בזה שכבר הרחיקתנו התורה מאכילת אלו השרצים כדי שלא נשקץ נפשותינו בעבי ובעכירות שיקרה לנו מהם אשר יהיו סבה לכבות אור השכל:
@345 **ולא תטמאו בהם ונטמאתם בם.** אין הרצון בזה לצוות שלא נטמא בהם כי אין בני ישראל מוזהרים על הטומאה כמו שביארנו במה שקדם ואין הכונה גם כן בזה טומאת הגוף שאין כל השרצים מטמאין אבל יטמאו מהם השמנה הנזכרים לבד ואמנם הרצון בזאת הטומאה טומאת נפש כאלו תאמר שאם ישקצו את נפשותם בהם ימצאו טמאים במה שעתיד ולא ימשול שכלם להשיג המושכלות אשר ישלם בהם:
@346 **כי אני השם אלהיכם והתקדשתם והייתם קדושי' כי קדוש אני.** רצוני בבזה כי אני השם המנהיג אתכם ולזה יחוייב לכם ללכת בדרכי להדמות אלי כפי היכולת ולפי שאני קדוש ופרוש מחמר ראוי לכם שתהיו פרושים ומובדלים מהחומר כפי מה שאפשר ולזה לא תאכלו המאכלים המעבים החמר והמונעים השכל מהשגת שלמותו אשר בו יתקדש וישאר נבדל מהחומר:
@346 **ולא תטמאו את נפשותיכם בכל שרץ השורץ על הארץ.** כפל המאמר בזה לחזק האזהרה ולהעמידנו על הכונה אשר בעבורה היתה זאת האזהרה כי אני השם המעלה אתכם מארץ מצרים להיות לכם לאלהים והייתם קדושים כי קדוש אני רוצה לומר שכבר העלתי אתכם מארץ מצרים לכונה שאהיה לכם לאלהים ותאמינו בי ותדבק השגחתי בכם ולזה העליתי אתכם משם עם אלו המופתים הנפלאים לקרב אתכם לעבודתי והשגתי ולזאת הסבה נתתי לכם אלו המצות אשר בהם תשלם לכם הקדושה והפרישו' מעניני החמר ותשתדלו בשלמו' השכל כי קדוש ונבדל מהחמר אני ורציתי שתקנו מהשלמות מה שתדמו בו אלי לפי מה שאפשר:
@348 **זאת תורת הבהמה והעוף וכל נפש החיה הרומשת במים.** רוצה לומר להבדיל מהם הנאכל מהבלתי נאכל ובבהמה הבדיל עם זה בין הטומאה ובין הטהור:
@348 **ולכל נפש השורצת על הארץ.** רוצה לומר והתורה אשר לכל נפש השורצת על הארץ והוא להבדיל מהם בין הטמא ובין מה שאיננו טמא והנה הטמא מהם הם השמנה שרצים שזכר ובכאן נשלם הביאור בזאת הפרשה:
@391 **דבר אל בני ישראל.** למדנו מזה שזה הדין אינו נוהג אלא באנשי התורה לא הגויים וכן העניין בשאר הטמאות הנמשכות לה כמו צרעת וזב וזבה ונדה:
@391 **אשה כי תזריע וילדה זכר.** הנה הקדים התורה להזכיר היולדת זכר כי הוא היותר נכבד וכבר התבאר בספר ב"ח שכאשר היה חומר הנקבה מוכן לקבל זרע הזכר יהיה הנולד זכר וכאשר היה הפכי לו הנה יתפעל ממנו זרע הזכר באופן שיחלש חומו ויהיה הנולד נקבה וכבר ביארנו אנחנו בביאור לספר ההוא כי זרע הנקבה יש לו מבוא הולד מזה הצד ר"ל שהוא יכין חומר הנקבה לקבל פועל מה וזה יתבאר בביצת הנקבה אשר תתהוה מזולת זרע הזכר ויתבררו החלבון והחלמון ויתברר בה המותר הארציי אשר תתהו' ממנו הקלפה ובכלל לא יחסר בה דבר אלא שלא יהיה ממנו אפרוח לפי שאין זרע הזכר שם וזה ממה שיתבאר ממנו של זרע הנקבה פעל מה בבשול זה החמר והכנתו מצד זה החום החלוש הנמצא בו והנה בארנו שם בטול דעת מי שיראה שאין לזרע הנקבה מבוא בהולדה וכן היה זה דעת הפלוסוף לפי מה שספר ממנו אכן רשד' ולזאת הסבה אחשוב שרמזה התורה במה שיחסה לידת האשה זכר אל הזרעתה וזה שכאשר תזריע קודם שיזריע האיש תקנה חום מה לדם הנקבה באופן שיהיה מוכן לקבל פועל זרע הזכר בשלמות והיה הנולד זכר וכשיזרע האיש קודם הנה יהיה הנולד נקבה לחוזק הפכיות דם הנקבה לזרע הזכר ולזה אמרו רז"ל אשה מזרעת תחלה יולדת זכר איש מזריע תחלה יולדת נקבה ולזא' הסבה גם כן אמרו הורצה שיהיו בניו זכרים יבעול וישנה והנה הלידה הוא לפי מה שיורה עליו הגדר יציאת הולד דרך הרחם ולזה אם יצא דרך דופן לא ינהג בה דין זאת הטומאה והטהרה והנה ינהג זה הדין בולד בחי ובמת כי בכל אחד מהם יפול שם הלידה ועניין הדם היוצא מהרחם בלידה בולד החי והמת הוא אחד בעינו כי הוא מותר הדם הבלתי נאות בהולדה כמו זכרנו במה שקדם בפרשה הקודמת:
@391 **וטמאה שבעת ימים.** אע"פ שלא תראה דם כי הוא מבואר כי אי אפש' בלידה מזולת דם בלתי נאות להולדה ואולי למיעוט כמותו לא הרגישה בו:
@391 **כימי נדת דותה תטמא.** ר"ל כימי נדה חליה כי עניין הנדות הוא בנשים חלי מה ולזה תרגיש הנדה בבא וסתה שראשה ואיבריה כבדים עליה והנה דין זאת הלידה הוא דין ראיית הנדה שתטמא שבעת ימים ולא יותר אף על פי שתראה דם בכל השבע' ימים מה שאין כן בראיית הזבח כמו שיתבאר:
@392 **וביום השמיני ימול בשר ערלתו.** מפני שקבעה התור' זכרון למילה למדנו שהי' דוחה שבת ויום טוב כשחל השמיני בהן והוצרכה התורה להזכיר זאת המצוה בכאן כדי שלא נחשוב שלא נתנ' התוד' בכללה על ידי משה רבינו ולזה לא תספיק לתורה מה שנזכרה מזאת המצוה לאברהם:
@393 **ושלשים יום ושלשת ימים תשב וגומר.** ר"ל שכל הדמים שתראה אחר ז' ימי הלידה בל"ג ימים הבאים אחריהם הם דמי טהר ולא תטמא בהם וכבר נאמר סבת זה במה שאחר זה:
@393 **בכל קודש לא תגע ואל המקדש לא תבא עד מלאת ימי טהר'.** למדנו מזה שאעפ"י שדמיה טהורים בזה הזמן הנז' הנה היא איננה טהורה לקדש ולא למקדש עד מלאת ימי טהרה שתביא קרבנותיה ואז תטהר לכל הדברים והנה הסבה היותה בלתי טהורה לקדש ולמקדש הנה הוא מפני היותר מחוסרת כפרה להשלים טהרתה וזה כי למעלת הקדש והמקדש ראוי שתרוחק הטומאה בהם יותר כמו שבארנו במה שקדם וראוי שנדע שהדמים האלו הם דמי טהר כשטבלה אחר ז' ימי הלידה אך אם לא טבלה תשא' בטמאת' תמיד ויטמאו קצת המשקים היוצאים ממנה כמו שיתבאר:
@394 **ואם נקבה תלד טמא' שבועים כנדתה.** ר"ל שתהיה נדת טומאתה באלו הי"ד יום כטומאתה הנדה ואף על פי שראת' דם בכלם תטהר בסוף י"ד יום כשתרחץ בשרה במים ודין טומאתה באלו הימים הוא דין טמאה הנדה לכל הדברים ר"ל לטמא בועלה וליתר דיני הנדה הנזכרים אחר זה והוא מבואר שאם נסתפק לנו בולד אם הוא זכר או נקבה נשפט בו להחמיר ותטמא לידה י"ד יום ולזה תטמא לידה י"ד יום היולדת טומטום או אנדרוגינוס כי לא נוכל לומר שלא תהיה טומאה לידה כשלא היה הולד ודאי זכר או ודאי נקבה לפי שאין הבדל לעניין טבע דם לידה בין היות הנולד ודאי זכר או ודאי נקבה בין היותו ספק כי עכ"פ זה הדם הוא ממותר הדם הבלתי נאות להולדה והיתה הלידה דרך הרחם כמנהג:
@394 **וששים יום וששת ימים תשב על דמי טהרה לבן או לבת תביא כבש בן שנתו לעולה ובן יונה או תור לחטאת.** ר"ל שאחר ששלמו ימי הטהרה הנזכרי' ולפי שאי אפשר שיהיה מעשה אלו הקרבנות בלילה לפי מה שנתבאר בשרשים הכוללים הנה היה הבאתה אלו הקרבנות למחרת ימי מלאת אל פתח אהל מועד אל הכהן למדנו שהיא מטפלת בהבאתו אל הכהן עד העזרה ר"ל עד המקדש שהיא יכולה להכנס בעזרת והוא מבואר שהיא אינה יכולה להכנס בעזרה קודם הביאה כפרת' כי טהרתה תלויה בכפרתה לאחר מלאת ימי טהרה שנאמר וכפר עליה הכהן וטהרה ממקור דמיה מכלל שלא טהרה ממקור דמיה עד שהביאה כפרתה והקריבו לפני ה' וכפר עליה וטהרה ממקור דמיה למדנו מזה שטהרתה תלויה באחד מאלו הקרבנות והוא החטאת כי הוא הקרב ראשון והוא גם כן המורה על החמר אשר בעבורו היתה זאת הטמאה ובכלל הנה מצאנו בכל מקום שהיה שם חטאת שכפרה תלויה בחטאת וכבר נתבארה סבת זה מדברנו בענין הקרבנות ואמנם תהא העולה אחר זה להשלים הרצוי בין המטהר מאלו הדברים החמריים ובין השם יתעלה כי הוא מורה על הצורה וטהרה ממקור דמיה קרא מקור מקום שיצאו משם בטבע אלו הדמים כי הוא מקודם ומשם נובעים ומפני היותם נובעים מהם כזה בזה האופן היתה הטומאה כמו שביארנו ולזה לא יטמא דם מכתרו אע"פ שהו' מן המקור לדם הבא מצדדי הרחם שאינו מן המקור וראוי שתדע כי אלו הקרבנות שאינם באים על חטא לא יכפלו בהכפל ענינם כמו העניין בקרבנות הבאים על חטא ולזה אמר וטהרה ממקור דמיה שאע"פ שהיו שם לידו' מרובות כיון שהביאה חטאתה טהרה מכל אלו הטמאות ולזה אלו ילדה תאומים או ילדה ולדות הרבה זה אחר זה קודם הבאת קרבנותיה הנה תביא קרבן אחד ובו תשלם טהרת לכל אלו הלידות מצד ההערה אשר לקרבן להתרחק מענייני החמר אם לא מן הצד שישרת בו הצורה ואמנם בקרבנות הבאים על חטא ימצא העין בהפך שנאמר על חטאתו כמו שבארנו במה שקדם וראוי היה להיות כן כי כמו שהטבילה לא תכפל בהכפל הטומאות כן ראוי שיהיה ענין הקרבנות הבאים להשלים טהרת הטבילה אלא שהלידות שיקרו לה אחר התחייבה בקרבן והם אחר ימי מלאת ימי טוהר הלידה הראשונה תתחייב עליהם קרבן שנית וכן בזה האופן אבל על כל פנים היא טהורה בחטאת אחד כמו שבארנו והשאר מהקרבנות חובה עליה להקריבם אבל אינם מעכבים טהרתה וכפרתה:
@396 **זאת תורה היולדת לזכר או לנקבה.** ר"ל עניין טומאת הלידה וימי טהרתה וקרבנותיה:
@397 **ואם לא תמצא ידה די שה.** ר"ל שהיתה ענייה שלאתהשיגה ידה למה שהיתה חובה עליה לקחת שתי תורים או שני בני יונה אחד לעולה ואחד לחטאת תור לעולה ובין יונה לחטא' או הפך והיה זה כן כי מפני חסרות חטאת העוף לא נשלמה בו הערת חטאת בשלמות ולזה ישלים ההערה העולה הבאה עמו כמו שבארנו בסוף פרשת צו. ולזאת הסבה חויב שיהיה החטאת ממין העולה כשיהיו שניהם מסוג העוף אלא שעל כל פנים כבר נשלמה זאת הכפרה בחטאה כמו שבארנו למעלה וכפר עליה הכהן וטהרה ר"ל שכבר תשלם טהרתה לאכילת קדשים ולהכנס למקדש במה שיכפר בו עליה הכהן והיא החטאת כמו שבארנו. ואולם מה הסבה אשר בעבורה היתה טומאת לידת נקבה יותר חזקה מטומא' לידת זכר עד שימי טמאתה הם כפל ימי טומאת הזכר הנה הסבה בזה לפי דעתי מבוארת וזה שהחמר שיתהוה ממנו הכר הוא יותר דק מהחמר שתתהוה ממנו הנקבה וזה מבואר למי שעיין בחכמה הטבעית ולפי שהמותר מתיחס לבעל המותר הנה יהיה בהכרח זה המותר אשר בלידת הנקבה יותר עב ויותר נפסד וגם כן הנה לחוזק החום היסודי בזכר ימשול על הדם להפכו לטבעו יותר ממה שימשול על הנקבה ולזה יהיה המותר יותר רב בלידת הנקב' ממה שימצא מנו בלידת הזכר. ואמנם סבת דמי הטוהר והיותם בנקבה כפל מה שהם בזכר ר"ל שימי טוהר הם בנקבה ס"ו ימים ובזכר אינם כי אם חצי זה המספר הנה הסב' בזה גם כן איננה לפי דעתי ממה שיקשה וזה כי דם היולדת נטמא מפני היותו בלתי נאות להולדה כמו שזכרנו בעניין הטמאות והטהרות וכן הענין בדם הזבח והנדה כמו שביארנו ואולם אם ימצא באשה דם יוצא ממקורה נאות להולדה הנה איננו ראוי שיטמא מזה הצד ואולם שכבר יצא ממקור האשה כמו זה הדם אחר הלידה הנה זה מבואר ממה שאומר וזה שהוא מבוא שכאשר הטבע התחיל למשוך דבר מה לצד מה והמשיך זה הפועל זמן ארוך הנה לא יתחזק הטבע למשוך הדבר ההוא להפך הצד ההוא תכף אבל יהיה זה בהכרח בלתי נשלם לו כי אם לאחר זמן ארוך ולזה הנה כאשר משך הטבע זה הדם הנאות להולדה אל מקור האשה להזון ממנו הולד והתמיד זה זמן ארוך הנה מן השקר שימשך תכף זה המותר אל השדים להתהות ממנו החלב אבל ישלם זה בזמן ארוך ולזה היה חלב היולדת בעת הסמוך ללידה בלתי נאות לפי מה שהגידו הרופאים כי הוא יותר עב מן הראוי לפי שלא ימשך אליו עדיין הדם הנקי אשר היה נמשך אל הולד ברחם ולזה ישאר נביעת זה הדם הנאות להולדה מהמקור זמן ארוך אחר הלידה ואולי שערה החכמה האלהית שזה ישלם לפי הנחות בזה הזמן אשר הגבילה התורה בזכר ונקבה ואמנם היה זה הזמן בנקבה יותר ארוך ממה שהוא בזכר לפי שהדם שתזון ממנו הנקבה יותר עב מהדם שיזון ממנו הזכר וכן הענין בחלב היולדת נקבה עם חלב היולדת זכר כי המזון מתיחס ודומה לנזון ולזה הנה יקרה לזכר לדקו' מזונו שיתחזק הטבע על משיכ' הדם הנקי אל השדים באופן שלא יהיה נובע ממנו דבר ברחם בזמן יותר קצר מהזמן שיתחזק על משיכתו בנקבה כי יספיק לזונה דם יותר עב הדם שיצטרך להיות ממנו חלב הזכר. והנה אחשוב שדמי טוהר היו נשלמים בארבעים יום לזכר לפי שעד מ' יום לא נשלמה יציאת הולד ברחם לי מה שהושג בחוש ואחר זה יהיה נזון בדם הנקי הנובע לו מהמקור אך קודם והאיננו נמשך לו שם כי איננו נזון אז וזה מבואר למי שעיין בטבעיות וכמו שזמן ההשתדלות אל מי שימשך הטבע זה הדם הנקי ברחם הוא ארבעים יום כן יהיה העניין בזמן משיכתו אותם אל שדים ואולם היה הזמן יותר ארוך בזה בנקבה לסבה שזכרנו הנה זהו מה שנראה לנו בסבות מה שנז' בכאן בטומאת היולדת וטהרתה והוא נפלא מאד כמו שתראה והנה היה סדר הטמאות נון לפי מה שביארנו שיזכור תחלת תורת המצורע ואחר כך תורת הזב והזבה והנדה והיולדת אבל הקדים לזכור עניין טמאת היולדת קדם הזכירו עניין הצרעת להעיר אותנו כי הצרעת בא בסבת הדם הבלתי נאות להולדה כי כשנתעברה האשה וחיה העובר הזה מכמו זה הדם הבלתי נאות להולדה יקרה לנולד מההפסד שיהיה מורע או מה שידמה לזה מהעפושים הנפלאים. וראוי שיתבאר ממנו ממה שזכרנו שלא יהיה ליולדת ימי טוהר ולא ימי טומאת לידה אם הפילה תוך ארבעים יום מעת הריונה כי אין שם עדין מותר דם בלתי נאות להולדה כי אין העובר נזון עדין ואין שם גם כן עדין משיכה לדם הנאות להולדה אל המקור ואולם אחר ארבעים יום תטמא לידה לזכר ז' ימים ולנקבה שבועים ואם היה ספק הולכין בזה להחמיר כמו העניין במפלת שפיר מרוקם לפי שיש שם מותר בלתי נאות להולדה אשר הוא סבת טמאת לידה אך לא יתכן שיהיו לה ימי טוהר על האפן הנזכר מה שלא נשלמה בריאת העובר באופן שיתחזק על משיב' הדם הנקי כמו שהתבאר מהסבה שנתננו בזה ולזה יראה שלא ינהג דין ימי טוהר אלא מעת שישעיר הולד כי אז נשלמה ברייתו באופן שיתחזק על זאת המשיכה כי כבר יתילדו אז בגופו מחוזק עכולו אידים עשנים יתהוו ממנו השערות ועל זה יהיה מזונו אז בשלם שבפנים וידבר יי' אל משה ואל אהרן. זכר בכאן אהרן לפי שאליו או לבניו יציטרכו בענין הנגעי' לטמא או לטהר להסגיר או להחליט כמו שיתב':
@399 **אדם כי יהיה בעור בשרו שאת או ספחת או בהרת וגו'.** קרא שאת הנגע שאינו בתכלית הלובן כלובן הבהרה שהוא בתכלית הלובן ונקראת שאת לפי שאין מראיהו עמוק מן העור אבל נראת יותר גבוה. ולזה נקראת שאת והנה יקרא בהרת לפי מה שיורה עליו הגדר הנגע שהיא לבן כלובן השלג ויקרא שאת מה שהוא לבן במדרגת צמר נקי של כבש בן יומו וספחת השאת אשר רמז אליה בזה הפסוק הוא הנגע שהוא למטה בלובן מהשאת והיא טפלה לשאת כעניין ספחני נא אל אחת הכהונות והוא במדרגת לובן קרום נצה וכן תמצא לבהרת ספחת אבל היא יותר ראויה בזה מהשאת וראוי שיהיה יחס ספחת הבהרת אל ספחת השאת יחס הבהרת אל השאת והנה ספחת הבהרת לפי מה שיורה עליו הגדר לבנה בסיד ההיכל והנה סדור אלו המראים היותר לבן הוא הבהרת ואחריו השא' ואחריו ספחת הבהרת ואחריו ספחת השאת והנה מה שהוא בלובן למט' מלובן ספחת השאת איננו נגע צרעת וכל השיעור הקטן שיפול בו שם השאת או הבהרת וספחת לפי מה שיורה עליו הגדר והא כגריס חקלקי שהוא מרובע ושעורו באורך וברוחב כדי צמיחת שש שערות שהם לו' שערות בכלל הנגע:
@399 **והובא אל אהרן הכהן או אל אחד מבניו הכהנים.** כי המשפט בזה הוא לכהן גדול או לכהן הדיוט כמו שיתבאר:
@400 **וראה הכהן את הנגע בעור הבשר ושער בנגע הפך לבן.** ר"ל שיקדם מציאות הנגע למציאות השער הלבן בו באופן שיהיה ההפך השער הלבן בנגע כי זה מאותות הצרעת וזה שהחום הנכרי יהיה סבת לובן השער כמו שירא' באיש שיבה וכבר התב' בשרשים הכוללים כי מפני שהשער מתחדש ממנו רבוי הנה לא יפול שם השער בפחות משתי שערות ולזה יחוייב שיהיו נהפכים בנגע ללבן שתי שערות ואז יהיה זה הסימן טמאה:
@400 **ומראה הנגע עמוק מעור בשרו.** כמו העניין בבהרת:
@400 **וראהו הכהן וטמא אותו.** הנה למדנו בזה המקום כי הפך השער לבן הוא סמן לצרעת בבהרת וכן היקש בשאר מראות נגעים ולזה כלל אותם יחד בראש העניין. ואמר שאת או ספחת או בהרת:
@401 ואחר זה זכר שארית דיני אלו המינים מהצרעת. ואמר **ואם בהרת לבנה היא בעור בשרו.** ראוי שתדע שכבר נשער לובן הבהרת במראה העור הבינוני בלובן ושחרות כי עור הכושי יביא לחשוב בלובן החלוש שהוא לובן הבהרת וכן מראה עור הלבן ביותר יביא לחשוב בלובן הבהרת שהיא כהה:
@401 **ועמוק אין מראה מן העור.** ר"ל שהיא כהה באופן שלא יראה מראה עמוק מן העור והיא ספחת הבהרת שזכרנו. והנה יאמר שם הבהרת גם על מה שהוא למטה בלובן ממראות הנגעים אמר בבוהק במה שאחר זה בהרות לבנות ואחר זה זכר שהם בהרות כהות לבנות. והנה זכר זה המין מהנגעים לפי שלא זכרו בראש העניין ולמדנו כי גם כן שלבנותו כהה ינהג זה הדין ר"ל שיצטרך להסגיר אף על פי שלא הפך שערו ללבן ואפשר שיכלול במה שאמר ועמוק אין מראהו מן העור כל הנגעים זולת הבהרת והנה יתכן שם הבהרת בכללם כמו שזכרנו:
@401 **ושערה לא הפך לבן.** ר"ל שלא הפך הנגע שתי שערות בו בלובן הנה אין בכאן דבר מורה על טמאה כי אם לובן הנגע ואולי אינו צרעת כיון שאין בו א' מאלו הסמנין:
@401 **והסגיר הכהן את הנגע שבעת ימם שנית.** כבר נתבארה הסבה בזה במה שקדם וראה הכהן את הנתק ביום השביעי להסגרו שהוא יום שלשה עשר מהראיה הראשונה:
@402 **וראהו הכהן ביום השביעי והנה הנגע עמד בעיניו.** ר"ל שהוא עדין מראות הנגעים שיהיה בהם תחלה לא נשתנה למטה מהלובן הלובן ההוא ולא אל לובן יותר חזק ולמדנו שזה הדין נוהג בכל הנגעים האחרים. ולזה אמר בעיניו שיורה אל רבוי המראים ולא אמר בעינו ולמדנו עוד מזה שכל המראות הנזכרות מצטרפות להשלים שעור הנגע:
@402 **לא פשה הנגע בעור.** ר"ל שלא נתפשט ממנו דבר בעור שהוא חוץ מהנגע כי זה נקרא פשיון הנגע לפי הנהוג:
@402 **והסגירו הכהן שבעת ימים שנית.** ר"ל שלא נשפוט עדין בזה הנגע שאינו נגע צרעת ואף על פי שעמד בעיניו שלא נשתנה מראהו לא אל חוזק הלובן ולא אל חולשתו ולא הפך שער לבן ולא פשה. ואמנם הוצרכה התורה להורותנו זה כי היה אפשר שנחשוב שזה כתם בעור לבד לא עפוש בבשר ולזה לא נשתנה עורו כלל אבל יהיה טעון הסגר שני לבחון עוד עניין זה הנגע ולפי שאמר לא פשה הנגע למדנו שאם פשה הנגע בעור אחר ההסגר הנה לא יוסגר שנית אבל הוא טמא ולמדנו מזה שהפשיון סימן טומאה משקרה אחר ההסגר כי לא יתכן שיהיה פשיון בראייה הראשונה שיראה הכהן הנגע וזה מבואר בנפשו והנה טעם היות זה ההסגר שבעת ימים מבואר ממה שזכר' ואחשוב שהטעם בזה ההסגר הטע' בעינו אשר בשלוחו מחוץ למחנה ישראל כדי שלא ישא ויתן עם בני אדם ויתעפשו מזה החלי וכאלו זה הדבר ממוצע בין הטהרה והטומאה כי לא יצא מן העיר ולא ישא ויתן עם בני אדם והנה ההסגר באדם תועלת שני והוא כי מפני העדר התנועה יתקבץ החום היסודי ויתחזק ויתכן לו שיגבר על החום הנכרי שהוא סבה הנגע ויוציאהו לחצוני הגוף ויתיכהו וכאשר נתחזק החלי עם ההסגר אז יורה על זה העפוש בגו ולזה יורה על הצרעת:
@403 **וראה אותו הכהן ביום השביעי שנית והנה.** כמו הנגע ר"ל שנשתה מראיתו אל לובן למטה מהלובן שהיה בו אלא שהוא עדין כלובן הארבע מראות הנגעים הנזכרים ולא פשה הנגע בעור. כי אע"פ שנשתנה מראהו שיורה אל העפוש בבשר כיון שלא פשה הנגע הנה הוא טהור כיון שאין שם ההפך שער לבן ולא פשיון וזה כי השתנות מראהו יורה באמת ששם עפוש מה בשר אלא שאין כל נגע מתחדש מעפוש כבשר צרעת ואף על פי שמראהו כמראות הנגעים הנזכרים ולפי שאמר לא פשה הנגע בעור למדנו שאם פשה אחר ההסגר השני הוא טמא:
@403 **וטהרו הכהן מספחת היא.** אמרו שהיא חזזית לבנה ואינה ממין צרעת אף על פי שתמצא כלובן הבהרת ולזה לא נראה בה סמני הצרעל. ר"ל שלא הפכה שער לבנה ולא פש הנגע:
@403 **וכבס בגדיו.** למדנו שהמוסגר ניטמא בגדים:
@404 **ואם פשה תפשה המספחת בעור אחרי הראתו אל הכהן לטהרתו ונראה שנית אל הכהן.** ר"ל אל הכהן שראה אותו קדם זה והסב' בזה כי הוא יכיר אם פשה אם לא:
@405 **וראה הכהן והנה פשתה המספחת בעור וטמאו הכהן צרע' היא.** למדנו מזה שאם פשה אחר הטהרה שהוא טמא:
@406 **נגע צרעת כי תהיה באדם והובא אל הכהן.** ר"ל לראות עניינו אם הוא צרעת אם לא:
@407 **וראה הכהן והנה שאת לבנה בעור והיא הפכה שער לבן ומחית בשר חי בשאת.** ר"ל או מחית בשר חי בשאת. וזה כי כבר ידענו ממה שקדם שהשער לבן הוא סימן טמאה לא יצטרך שתחבר עמו סמן המחיה והנה יהיה זה הוא"ו תמורת או המחלק בוא"ו אביו ואמו קלל. ולפי שסמך עניין המחיה להפכת שער לבן. למדנו שהמחיה יחיב שתהיה כשעור יהיה אפשר בה שיצמחו בה ב' שערות באיזה צד שיהיה מרחיקה ר"ל באורך וברוחב כי הנושא ראוי הוא שיהיה אחד בשני אלו הסמנין המתחלפים הנופלים בו והנה מחית הבשר החי אשר בתוך הנגע סימן טמאה כי זה יורה על שזה העפוש בא לזה המקום מהבשר והעור מחוץ מהם ולזה תגיע אל מקיף המקום ההוא קודם שיגיע אל מרכזו ולזה יורה שזה העפוש הגיע שם מטה שנדחה אליו מהעפוש מפנימי הגוף וזה שאם היתה התחלת הוית זה הנגע בבשר שהוא כן היה מן הראוי שיהיה התחלתו במרכזו ואחר יתפשט לחץ וזה מבוא' מאד ולפי שהנשאר מהשאת סביב המחיה ראוי שיהיה בו אפשרות שיצמחו בו שתי שערות באי זה שיהיה מרחקיו הנה ראוי שיהיה עביו מקום צמיחת שתי שערות ולזה יהיה ארך זה הנגע ורחבו באופן שיתכן שיצמחו בו שש שערות ולפי שכל נגע ראוי שיהיה באופן שיהיה ראוי למחית ולהפכת שער לבן הנה יהיה בזה ראיה ששעירו הנגע לא יהיה פחות מהשיעור שזכרנו במה שקדם ר"ל שיתכן שיצמחו בו לו' שערות שש בארץ ושש ברחב:
@408 **צרעת נושנת היא בעור בשרו.** ר"ל כשהיתה מחית בשר חי בשאת והנה להיות זה העפוש נושן בתוך הגוף ילאה הטבע לדחותו לחיצוני הגוף כי אם בזה האופן החלוש:
@408 **וטמאו הכהן לא יסגירנו כי טמא הוא.** למדנו מזה שאין מסגידין את הטמא והסבה מבוארת במה שקדם כי לחוזק טמאתו ראוי שיצא מחוץ למחנה. והנה למדה אותנו התורה זה הדין בשאת וממנו נלמד כי הבהרת יותר ראוי בזה הדין להיות יותר מורה על חזק צרע':
@409 **ואם פרוח תפרח הצרעת בעור וכסתה הצרעת את כל העור הנגע מראשו ועד רגליו לכל מראה עיני הכהן.** רוצה לומר שתכסה הצרעת את כל עור בעל הנגע מראשו ועד רגליו לכל מה שישלוט בו ראות עיני הכהן פרט לבית הסתרים שאינו מעכב שאין הראות שולט בו כשיעמוד המצורע כמשפט עמידה האדם ומנהגו ולזה לא יעכב העור שתוך הקמטין כי אינו נראה וראוי שיהיה כל הפורח בגופו כמראה הצרעת וכסתה הצרעת את כל עור הנגע ואולם אם היה שם חלק לבן שיהיה לבנו למטה מלבן הצרעת לא ינהג בו זה הדין ולמדה מזה שהרואה הנגעים יצטרך שיהיה לו שתי עינים כי בזה יהיה ראותו יותר שלם שנאמר עיני הכהן ולזה יתבאר גם כן שאין רואין הנגעים אלא בעת שהיה אור היום על שלמותו לא בבקר ובערב כי אז לא תהיה הראייה שלמה להבדיל מראות הנגעים ולזה לא תהיה הראייה בתוך הבית ולא ביום המעונן וראוי שתדע כי ראיית הנגעים אפשר שלא בכהן אבל המשפט אשר בהם לטמא או לטהר או להסגיר לא יהיה אל בכהן כי כבר דקדקה התורה שיהיו אלו הענינים נעשים על יד כהן ואם אמר אומר הנה כבר מצאנו גם כן שכבר דקדקה התורה שתהיה ראיית הנגעים בכהן אמר לו שכבב' מצאנו מה שיורה שהראייה אפשר בזולתו אמר בפרשת כי יפלא בעניין הכהנים על פיה יהיה כל ריב וכל נגע והנה לא יבא אז הנגע אליהם כמו שלא יבאו אז בעלי הריב אליהם אבל יבואו להם המורים באלו ההוראות ובהיות הענין כן הנה מה שיוחד להם מהנגעים הוא שיהיה המשפט על פיהם לא הראייה וראוי היה להיות כן כי הראייה תלויה בבחינת אלו המראות וידיעת משפטם וזה אפשר שישלם באי זה שיהיה ממי שראוי לסמוך עליו ואמנם המאמר לטהר או לטמא או להסגיר ראוי שיהיה על פי הכהנים למעלתם וזה מה שדקדקה התורה באלו הדברים שיהיו על יד כהן:
@410 **וראה הכהן והנה כסתה הצרעת את כל בשרו וטהר את הנגע כלו הפך לבן טהור הוא.** הנה אחשוב שהסבה בזה כי כשראה הכהן שהתחיל לדחות זה העפוש לחיצוני הגוף ואחר כך יראה התפשטותו בכלל הגוף הנה ירה זה על ממשלת החום היסודי על זה העפוש ודחהו מפני זה מכל הצדדי' לחיצוני הגוף. וידחה שם כמו שידחה החום הנכרי בקדחות בימי הגבול לחיצוני הגוף מכל המקומות ויתך בזיעה ואז יהיה הבריאות ולזה לא יטמא זה שפרחה הצרעת בכלוא ע"פ שנהפך כל שערו ללבן כי זה מדרך העפוש הנדחה שם ולזה אמר אחר זה וביום הראות בו בשר חי יטמא למדנו שבמחיה מטמא ולא בשער לבן וכבר העירתנו התורה כי מאמר הכהן באלו הענינים לא יחייב שיהיה כן אלא כשיהיה מסכים לאמת ולזה אמר וטהר את הנגע כלו הפך לבן טהור הוא ויתבאר מזה שאם טהר מי שאינו טהור לא תועיל טהרה שלו וזה תמצא כפול בזה הענין אמר נגע צרעת הוא וראהו הכהן וטמא אותו וטהרו הכהן מספחת היא וטמאו הכהן צרעת היא וטמאו הכהן לא יסגירנו כי טמא הוא. וטמאו הבשר החי טמא הוא צרעת היא וטהר הכהן את הנגע טהור הוא והנה תמצא נכפל כל זה בכל זה העניין ומזה גם כן יתבאר שהראייה ובחינת המשפט בנגעים אפשר שתהיה בזולת כהן וזה שכבר אמר וטהרו הכהן מספחת היא ר"ל שכבר אפשר שיבחן מזולתו שמספחת היא וכשיתבאר שהוא מספחת באי זה צר שיהיה הנה יטוהרנו הכהן וכן מה שאמר וטמאו הכהן צרעת היא כלי אינה צרע' מצד בחינת הכהן ענינה אבל היא צרע' מצד ענינה בעצמה אי זה שיהיה מן האנשים שיבחן ענינה וביום הראות בו בשר חי יטמא הטעם בזה התבאר במה שאמרנו במחיה וזה כי הנגע הוא בהרת או שאת ובו מחית בשר חי שהיא טמאה לפי מה שקדם וג"כ הנה מפני שלא ימשול הטבע לדחו' זה העפוש מכל הצדדין הנה יראה שעדין העפוש בפנימי הגו ולזה אם ישוב אחר כן זה הבשר החי להפך ללבן הנה הוא טהור:
@415 **ובשר כי יהיה בו בעורו שחין ונרפא.** הנה שחין יורה לפי הוראת הגדר על מה שיפסד בו העור בסבת חום שאינו חום אש וכשהיה זה בסבת חום אש יקרא מכות אש וזה החום בכלל איך שיהי' הוא חום נכרי ולזה אפשר שיתחדש ממנו העפוש במקומו ויתחדש שם שצרעת אלא שזה לא יהיה בעת שהוא מוגלא במקום השחין והמכוה אבל יהיה אחר שהתחיל לעשות עור חלוש ולזה אמר צרבת השחין הוא כמו שיתבאר:
@415 ולזה אמר **ונרפא** ר"ל שיהיה נרפא באופן שיהיה שם במקומו מה שידמה לעור ואז יוכל להתחדש בו שאת או בהרת ולזה לא ירצה באמרו ונרפא שיהיה נרפא בשלמות והיה במקום השחין שאת לבנה או בהרת לבנה אדמדמת ר"ל שיהיה צבעה מעורב לבן ואודם בצד שיהיה הלובן המופלג ההוא נוטה לאודם נטייה מה וראוי שנדע שהראייה המעורבת מלובן ואודם ינהג גם בשאת אמר א"כ והנה שאת הנגע לבנה אדמד' מת ומזה נשפט שהענין כן בספחת הבהרת והשאת ויתבאר שזה המראה המעורב עם אודם ינהג גם כן בצרעת עוד בשר שנאמר והנה שאת הנגע לבנה אדמדמת בקדחתו או בגבחתו כמראה הצרעת עור בשר ובכלל הנה מראות נגעי צרעת ראוי שיהיו בלתי מתחלפים באי זה מקום שיהיה מגוף האדם וזה מבואר עם מעט יעיון וכבר ביארו דז"ל איך נשפוט באלו המראין המתמזגין עם אדם לפי מה שקבלו בזה מפי משה איש מפי איש והוא שכבר נקח כוס מלא חלב ונשליך לתוכו שני טפים דם או יהיה מראהו כמראה בהרת לבנה אדמדמת ואם השלכנו לתוכה ארבעה טפים דם יהיה מראהו כמראה השאת אדמדמת ואם השלכנו לתוכו שמנה טפי דם יהיה מראהו כמראה ספחת הבהרת אדמדמת ואם השלכנו לתוכו י"ו טפי דם יהיה מראהו כמראה ספחת השאת אדמדמת והיה זה כן כי האודם להיות הפכיי ללבן באופן מה הנה יחסר לובן הנגע כשהתמזג עמו וכל מה שהיה המראה יותר לבן ישאר יותר לבן וזה בלתי צריך אל ביאור ולזה יתבאר שהבהרת היא יותר לבנה עם אדמומיתה ואחריה השאת ואחריה ספחת הבהרת ואחריה ספחת השאת וזה דומה ליחס מדרגותיהם בלבן ואולם שהמראה הלבן המעורב באודם יורה על הצרעת הוא מבואר מן החוש והסבה בזה כי מפני שהיה שרש הויתו מהדם המעופש הנה יקרה לו והוא היותר נמצא:
@417 **וראה הכהן והנה מראה שפל מן העור.** רוצה לומר שהיא בהרת מצד הלובן כמו שזכרנו במה שקדם:
@417 **ושערה הפך לבן.** זה יורה על העפוש והחום הנכרי כמו שהתבאר במה שקדם:
@417 **וטמאו הכהן נגע צרעת היא בשחין פרחת.** מפני החום הנכרי אשר בסבתו נהיה השחין נשאר שם הרושם עד שהגיע ממנו זה העפוש ולזה ייחס אותו לשחין או אפשר שנאמר שיהיה מיוחס לשחין במקרה כי אפשר שיהיה זה העפוש תוך הגוף ולא משל הטבע לדחותו כי אם בזה המקום החלוש שיהיה בו השחין וזה אמנם יהיה לחולשת הטבע והעניין הראשון הוא יותר נאות כי לזה הבדילה התורה בין השחין והמכוה ולא צרפם זה עם זה ואלו היה מהעפוש אשר תוך הגוף היתה הסבה בשניהם אחת בעינה והנה בארה התורה זה הדין בבהרת וממנה נלמד שכן הדין כל שכן בשאר מראות נגעים כי כבר זכרה אותם בתחלת הענין אמ' שאת לבנה או בהרת לבנה אדמדמת:
@418 **ואם יראנה הכהן והנה אין בה שער לבן.** רוצה לומר שלא הפך הנגע שתי שערות ללבן:
@418 **ושפלה איננה מן העור והיא כהה.** רוצה לומר שאין עמוק מראה מן העור ולזה אינה בהרת אבל היא בהרת כהה והיא ממראות הנגעים:
@418 **והסגירו הכהן שבעת ימים.** כבר התבארה הסבה בזה ההסגר במה שקדם ולמדתנו התורה כי בזה הנגע שלבננותו כהה ינהג זה הדין. רוצה לומר שכבר יצטרך להסגיר אף על פי שלא הפך שערו ללבן:
@419 **ואם פשה תפשה בעור.** רוצה לומר בעור השחין. לא בעור הבשר כי זה הנגע הוא במקום השחין. וחלקו הכתוב מצרעת עור בשר להורות שאינם מצטרפים זה עם זה ולזאת הסבה לא יתכן להם שיפשו זה לתוך זה:
@422 **וטמא אותו הכהן נגע הוא.** רוצה לומר נגע צרעת כי הפשיון הוא סימן טמאה כשנתחדש אחר ההסגר כמו שקדם וכבר התבאר הסבה בזה במה שקדם רוצה לומר למה הוא סימן טמאה ואם תחתיה תעמוד הבהרת לא פשתה צרבת השחין היא וטהרו הכהן ר"ל שכיון שלא פשה הנגע ואין בו סימן טומאה הנה יהיה זה הלובן אשר נתחדש שם מקרה בעור הוא מפני החום אשר בסבתו היה השחין ואין שם עפוש בבשר אשר תחתיו באופן שיתהוה ממנו צרעת ולזה לא יהיה זה נכנס בגדר הצרעת או בשר כי יהיה בעורו מכות אש והיתה מחית המכוה בהרת לבנה אדמדמת או לבנה והנה זכר קצת מראות הנגעים והוא הדין לנשארים וקרא מחית המכוה העור החלוש שנתחדשה שם אחר שנתרפאה מהמוגלא אשר בה והנה כל הנמשך בעניין המכוה שוה למה שנאמ' בעניין השחין וממה שאמרנו שם יתבאר כל מה שנאמר בעניין המכוה לא יתחלף אלא שכבר אמר בסוף והיא כהה שאת המכוה היא מה שלא אמר מה שיתיחס לזה בשחין והנה הבאור בו בשחין שהיא כהה שנשתנו מראיה של לובן למטה מהלובן שהיתה בו אלא שמראיתה ממראות הנגעים והנה עם כל זה לא נשפט שיהיה זה נגע צרעת ואף על פי שכבר יורה השתנות מראה ששם עפוש בבשר שתת העור הנה אינו באופן שיהיה צרעת אבל הוא נגע אחר מתחדש בסבת המכוה ולזה לא פשה הנגע ולא נהפך שערו ללבן והנה יתבאר שנגעי השחין והמכוה אינם מצטרפים זה עם זה ואינם עושים זה לתוך זה כי התורה חלקה אותם עם היות דיניהם שוים להורות שנגעיהם חלוקים זה מזה ואין בהם הסגר כי אם שבוע אחד ואין מחית בשר חי בהם סימן טמאה:
@426 **ואיש או אשה כי יהיה בו נגע בראש או בזקן.** רוצה לומר במקו' צמיחת השערות וינהג באשה נגע הזקן אם היה לה זקן ולא ינהג באיש אם לא היה לו זקן והנה זה הנגע נקר' נתק וענינו שנתקו משם השערו' בסבת איזו ליחה שדרכה שיקר' ממנה זה:
@427 **וראה הכהן את הנגע והנה מראהו עמוק מן העור.** ר"ל שהוא במדרגת לובן הבהרת:
@427 **ובו שער צהוב דק.** יקר' צהוב השער שצבעו כצבע הזהב ויקרא רק בזה המקום כשהיה קצר ולקוי לא כשהיה ארוך ודק והיה זה כן כי זה השער הוא ראיה על עפוש הצרעת אשר קרה בסבתו הנתק אלו השערות מזה המקום כי זה מין מה מהצרעת כמו שהתבאר בספר הרפואה ויקראוהו חולי השועל והנה יקרה מזה העפוש שלא יאות האיד העולה אל הראש להתהוו' ממנו שער או אם יתהוה ממנו תהיה הויה חלושה ולזה לא יקרה לו שיארך וזה שזה החולי יקרה משרפה תתחדש בדם ולזה לא יתכן שתהיה ממנו איד עשני נאות להמית השער אם לא באופן חסר ולזה לא יארך להעדר מזונו. ולזאת הסבה הנה אם יתילד שם שער יהיה צהוב להתיחס זה הצבע לזה הדם המעופש בזה האופן ולא יהיה שחור כצבע שער האיש הברי ומפני זה היה זה השער הצהוב הדק בנתק סימן צרעת כשהיה בו שתי שערות בזה התבאר כי שם השער לא יאמר בפחות משתי שערות. כמו שהתבאר בשרשים הכוללים והנה למדתנו התורה שאע"פ שיהיה לבן הנתק כלובן הבהרת לא נשפוט שהוא צרעת אם לא היה בו שער צהוב דק והנה אין מתנאי זה השער שיהיה הנתק מהפך אותו בזה התואר כמו העני' בשער הלבן אבל אף על פי שהיה שם זה השער קודם חדוש הנתק זה השער הנה הוא סימן טמאה וסבת זה כי דקותו יוכיח שהאיד העשני העולה שם איננו נאות להויית השער:
@428 **וכי יראה הכהן את נגע הנתק והנה אין מראהו עמוק מן העור.** ר"ל אף על פי שאין מראהו עמוק מן העור כיון שאין בו שער שחור ר"ל שתי שערות שחורו' ויהיה השער בלתי דק הנה יצטרך להסגר לבחון ענין זה הנגע אם הוא בסבת צרעת אם לא ולמדנו מזה שאם היה בו שער שחור שלם ההויה ר"ל שיצמח באורך לפי הראוי הנה הוא מציל על זה הנגע וכן למדנו מזה שאם לא היה בו שער צהוב דק לא נשפוט מפני זה שיהיה טהור אף על פי שמראה עור הנגע איננו עמוק מן העור אבל יצטרך להסגר והנה הטעם בזה ההסגר התבאר במה שקדם. וראוי שנדע כי עניין השער השחור הוא מתיחס לעניין מחית הבשר החי אלא שהמחיה סימן טומאה והשער השחור סימן טהרה והנה דינו כשעור דין המחיה ודין שעור הנתק אשר סביבו דין שעור הנגע אשר סביב המחיה ולזה ראוי שיקיף הנתק השער השחור בשעור שיהיה בעיניו שעור צמיחת שתי שערות כדי שיתכן שיהיה בו שער צהוב דק ואין צורך לתת טעם למה שהיה השער השחור אשר באמצע הנתק סימן טהרה כי זה מבואר הסבה:
@429 **וראה הכהן את הנגע ביום השביעי.** הוא שביעי ליום ראיית הנתק:
@429 **והנה לא פשה הנתק.** שאם פשה היה זה סימן שהוא מצורע כי זה יורה על שזה העפוש מתחזק בגופו ולזה ימשך ממנו זה הנתק לשער ולא היה בו שער צהוב רוצ' לומר שער צהוב דק שזכר במה שקדם ולפי שידענו ממה שקדם שהשער הצהוב הוא לבדו סימן צרעת בנתקים הנה יתבאר שוא"ו ולא היה בו שער צהוב הוא תמורת או המחלק ולזה יטמא הנתק בשער צהוב דק או בפשיון:
@429 **ומראה הנתק אין עמוק מן העור.** ר"ל הנה כשלא היה בו אחד משני אלו הסימנין הנה אע"פ שאין מראה הנתק עמוק מן העור לא נשפוט שיהיה טהור אבל יצטרך להסגר לבחון ענין זה הנגע אם הוא צרעת אם לא. וזאת הבחינה תהיה בזה התאר שיתגלח שער ראשו או זקנו והנה לא הקפידה התורה שתהיה התגלחת בכהן והשערות שהם סביב הנתק לא יגלח והם הסמוכות לנתק והנה צותה התורה זה כדי שיוכל הכהן לבחון בהם אם פשה הנתק כמו ישראה במה שאמרה התורה בזה ולזה הוא מבואר שאין התגלחת מעכבת ההסגר כדי שיכיר הכהן הפשיון בזולת התגלחת כמו שנתבאר ממה שנזכר בהסגר הראשון בנתקים:
@430 **והסגיר הכהן את הנתק שבעת ימים שנית.** ר"ל שיסגיר בעל הנגע שבעת ימים כי בזה הזמן יתכן שישתנה עניין זה הנגע. ויתבאר עניינו לחוזק רושם שבעת הימים בדברים הטבעיים עם שבזה הזמן תשוב הלבנה במבט מרובע ממה שהיתה בו תחלה כי מפני זה יסודר ממנה פעל מקביל באופן מה למה שהיה סודר ממנה תחלה:
@431 **והנה לא פשה הנתק בעור.** הא אם פשה הנה הוא טמא ומראהו איננו עמוק מן העור רצה לומר אף על פי שאין מראהו עמוק מן העור ואין בו סימן צרעת הנה יהיה טעון כבוס בגדים ולא נאמר שיהיה דינו כדין הקרח והגבח שהוא טהור ואינו טמא כלל אף על פי שכבר נראה עתה שסבת זה ההנתק לשער לא יהיה צרעת אבל הוא סבת הקרחות והגבחות בעינה אבל על כל פנים יטהרנו הכהן שנאמר וטהר אותו הכהן וכבס בגדיו וטהר:
@432 **ואם פשה יפשה הנתק בעור.** למדנו שהפשיון מטמא גם אחר הטהרה לא יבקר הכהן לשער הצהוב טמא הוא רוצה לומר שכיון שפשה הנה הוא טמא אף על פי שאין בנתק שער צהוב דק ולזה לא יצטרך הכהן להסגירו לבחון אם יצמח בו שער צהוב דק כמו הענין בראיה הראשונה של נתק ואמר זה שלא נחשוב מפני שטהרו הכהן שיהיה דין הראייה הזאת דין הראייה ראשונה שאינה מטמאת בזולת שער צהוב והוא מבואר שהשער הצהוב מטמא שלא בפשיון כי זה הדין היה גם כן בראייה הראשונה כמו שקדם:
@434 **ואם בעיניו עמד הנתק.** רוצה לומר שהנתק שנטמא. בשער צהוב דק כי בו יתכן שיאמר שעמד בעיניו מפני היות לו מראה מוגבל והוא הצהובות ואמנם הנתק בעצמו אין לו מראה מוגבל אבל יטמא באי זה מראה שהיה כשהיו בו סימני הטמאה ולזה יהיה זה המאמר בהכרח בנתק שהוחלט מפני שער צהוב ושער צהוב צמח בו נרפא הנתק טהור הוא כיון שאמר נרפא למדנו שכבר היה מצורע קודם זה ואמר שאף על פי שיהיה בו שער צהוב כיון שצמחו בו שתי שערות שחורות במקום הנתק הנה זה ראיה שסר עפוש הדם ושב באופן שיתכן שיצמח ממנו השער לפי הענין הטבעי. וראוי שתדע כי אף על פי שנפלו אלו השערות השחורות ונשאר שם הנתק והשער הצהוב הנה הוא טהור כי אמרה התורה שהוא נרפא והנה תהיה נשירת אלו השערות לסבה אחרת זולת הצרעת כמו שיקרה הקרחות והגבחות בזולת צרעת:
@435 **ואיש או אשה כי יהיה בעור בשרם בהרות בהרות לבנות.** הם כתמים לבנים ואינם נגעים והם רושורוש בלעז אבל לבנים למטה מלובן ארבע מראות נגע צרעת:
@436 **וראה הכהן והנה בעור בשרם בהרות כהות לבנות.** רוצה לומר שהם למטה בלובן ממראות נגעים:
@436 **בהק הוא פרח בעור טהור הוא.** רוצה לומר שאין אלו הכתמים בסבת עפוש בבשר אבל הוא כתם בעור והנה האיש הבהקני נקרא רוש"ו בלעז והוא ענין יקרה מבלבול ליחותיו וערבובם באופן בלתי שלם כמו שיקרה לעוף שתהיה נוצתו מצבעים רבים לזאת הסבה כמו שהתבאר בטבעיות:
@437 **ואיש כי ימרט ראשו.** רוצה לומר שער ראשו:
@437 **קרח הוא טהור הוא.** למדנו שלאי זו סבה שיהיה נמרט שערו כיון שהו קרח עתה שאין בעור ראשו שער הנה הוא טהור ולא יהיה דינו דין הנתקים כי הקרחת יבא הרבה פעמים לאנשים הבריאים וכונת התורה היתה בזה לבאר לנו שער הראש כשלא היה בו שער דינו כשאר עור הבשר להטמא בנגעים. והנה ביארה התורה כי זה המקרה כשיהיה במה שאחורי הראש יקרא קרחת וכשיהיה במה שהוא מפאת פניו יקרא גבחת ודין נגעי הקרחת ונגעי הגבחת הם כדיני נגעי צרעת עור בשר אלא שאין בהם הפכה שער לבן כי אין בהם שער ואין נגעיהם מצטרפים זה עם זה ולזה הבדילה התורה הקרחת מהגבחת עם היות דיניהם שוי' והסבה בזה להתחלף טבע אחורי הראש מטבע הצדדין כמו שנזכר בספרי הרפואה וזה כי אחורי הראש תמשול הלבנה ובצדדיו ימשלו השחור' והאדומה שהלבנה מקבלת לכל אחד מהם ואם היתה הפכיותה לאדומה יותר חזק ולזה יראה שההוה מהם מהנגעים הוא מסבות מתחלפות להתחלפות המקבלים ולזה לא יצטרפו זה עם זה ולא יפשו זה לתוך זה הלא תראה כי בשחין ובמכוה הבדילה התורה גם כן עם היות דיניהן שוים להיות החום הנכרי אשר בהם מסבות מתחלפות:
@439 **וכי יהיה בקרחת או בגבחת נגע לבן אדמדם.** לא שיהיה קצת הנגע בקרחת וישלם שעורו במה שהיה שעורו ממנו בגבחת או בשאר עור בשר הנלוה להם אבל יחוייב שיהיה כלו בקרחת או כלו בגבחת ולזה כפל זה הענין ואמר בקרחתו או בגבחתו והנה למדנו מזה שהנגע הלבן מטמא עם היותו אדמדם כמו שמטמא בהיותו לבן לבד וזה כולל בכל נגעי צרעת עור בשר אף על פי שלא נזכר זה שם כי הצרעת הנזכרת בזה המקום הוא הדין צרעת עור הבשר כמו שיאמר כמראה צרעת עור בשר:
@439 **צרעת פורחת היא בקרחתו או בגבחתו.** ולא נשפוט מפני זה שיהיה המרט השער בקרחת או בגבחת בסבת צרעת אבל ישוב הקרח או הגבח לטהרתו בהרפא זה הנגע שנתחדש בקרחתו או בגבחתו ואף על פי שנשאר הקרחת או הגבחת על כנינו:
@440 **וראה אותו הכהן והנה שאת לבנה אדמדמת בקרחתו או בגבחתו כמראה צרעת עור בשר.** הרצון בזה שיראה אותו הכהן באופן ראיתו צרעת עור בשר להסגירו ולטמא ולטהר כי דיניהם שוים אלא שבזה הנגע לא יקרה שיהפך שערו ללבן מפני שאין בו שער ואמנם יטמא בפשיון ובמחיה וזכרה התורה זה המראה הלבן אדמדם בשאת וממנו נלמד שכן העניין בשאר מראות הנגעים ולזה כללה אותם תחלה במה שאמרה נגע לכן אדמדם ולפי מה שנתבאר בזה המקום שדין הקרחת והגבחת הוא דין עור בשר הנה נלמד מזה שכבר ינהג בהם דין נגעי שחין ומכוה כמו הענין בשאר עור בשר והנה אמר איש בזאת הפרשה לפי שהקרחות והגבחות הוא יותר נמצא בו ולא ימצא באשה כי אם על דרך הזרות הנפלא אבל עכ"פ יתבאר מטבע העניין בעצמו שדינו שוה לאיש ולאשה כי בהפקד השער מאלו המקומות ישוב העור במדרגת עור בשר':
@442 **והמצורע אשר בו הנגע בגדיו יהיו פרומים.** זה כולל כל מיני הצרעת והרצון בו כי כשהיה מוחלט לטמאה יחוייב שיהיו בגדיו קרועים לבזותו והתועלת בזה הבזיון הוא מזה נתעורר על חסרון החומר שהוא סבת זה העפוש וההפסד ונעמוד מזה על אמתת מציאות הצורה:
@442 **וראשו יהיה פרוע.** ראוי שתדע כי פריעת הראש תאמר בפנים שונים וזה כי הוא יאמר על השבתת התגלחת ולא יקרא זה פרוע ראש עד ששבת מהתגלחת שלשים ויאמר על בטול הכסוי והגלוי והנהוג לראש וזה שאם כסהו כלו הנה השבית ממנו מה שהוא נהוג שיתכסה ממנו ולזה העניין השני ופרע ראש האשה רוצה לומר שיסיר הצעיף שהיא מתכסה בו וישאר שערה מגולה והנה הרצון בזה המקום אינו לגדל פרע כי אי אפשר שיהיה פרוע הראש בה האופן תכף היותו טמא אלא אם קרה שעמד קודם זה מהגלוח שלשים יום ולזה ראוי שתהיה הכונה בו אם גלוי הראש אם כסוי הראש ולפי שאמר אחר זה ועל שפם יעטה שיורה על פלגת כסוי הראש יותר מהנהוג הנה יהיה הרצון בזה שיהיה ראשו מכוסה באופן שישבות ממנו הגלוי הנהוג:
@442 **ועל שפם.** הוא השער שעל השפה והיתה הצואה שיכסהו כמו שיעשה זה האבל והנה הטעם בזה הוא הטעם בקריעת בגדול ולפי שאמר הז העניין בלשון זכר והיו קצת הדברים אשר בו בלתי נמצאים לנקבה כמו השפם אם שאין ראוי שינהגו בנקבה כמו קריעת הבגדים כדי שלא יתגלה בשרה ויביא זה לדבר ערוה הנה אין אלו הדברים נוהגים באשה כי אין ראוי שנלמד זה הדין באשה ממה שנזכר בשה לאדם כי זה יותר בלתי ראוי בחק האשה ממה שהוא בחק האדם:
@442 **וטמא טמא יקרא.** ירצה בזה שיקרא טמא לאנשים שהוא טמא כדי שיפרשו ממנו ולפי שאמר וטמא ולא אמר וצרוע למדנו שזה הענין נוהג בכל הטמאים והתועלת בזה מבואר והוא מבואר מעצם הענין שבזה ראוי שתהיה האשה שוה לאיש:
@443 **כל ימי אשר הנגע בו יטמא.** למדנו מזה שכאשר סר הנגע סרה טמאתו כשיטהר. והנה סור הנגע יהיה אם בסבת רפואה אם בסבת קציצת הנגע והנה יטהר בקציצת הנגע כשתהיה הקציצה ההיא לא מבחירתו ואולם אם היתה בבחירתו איננו ראוי שיטהר בה כי הוא החוטא בזה הפועל כמו שיתבאר במה שיבא ומשל הקציצה היא שלא מבחירתו אם קרה שתהיה בהרת בבשר הערלה כי הוא יוכרח למול ולקוץ בהרתו וכן הענין אם נקצצה במקרה שלא בכונה וכן הענין בתלישת סימני טמאה:
@443 **בדד ישב מחוץ למחנה מושבו.** למדנו מזה שהוא יוצא חוץ לשלשה מחנות רוצה לומר חוץ ממחנה ישראל וסבת זה מבוארת ממה שקדם והוא מבואר שזה לא ינהג אלא בעיר המוקפת חומה כי התורה אמרה מחוץ למחנה מושבו והנה המחנה האחד במה שהוא מחנה אחד הוא מוקף מחיצה והנה למדנו מזה שמושבו טמא ולזה חייבה התורה שיהיה חוץ למחנה וכבר יתבאר זה גם כן ממה שנאמר בנגעי בתים שמטמאים בביאה כמו שיתבאר שם והנה להעיר שזה ההפסד בא לאדם מצד החומר לא מצד הצורה זכרה התורה אחר זה טמאת צרעת בקצת הדברים שישתמש האדם בהם הבאים מהצמח והחי והן במדרגת הדומם וענין הצרעת באלו הדברים הוא שיגבר בהן הלחות הנכרי והחום הנכרי ויחלש חומם היסודי אשר היה מעמיד הלחיות אשר בהם באופן שידרכו אל הבלוי וההפסד מההרכבה מצד התכת לחיותיהם אשר בהם קיומם והנה תמצא כי המראה שיורה על כמו זה העפוש הוא הירוק או האדום כבר תמצא זה במקומות העפושים כמו מימי האשפות ומה שידמה להם ולפי שאין באלו הדברים התחלה תובילם אל הרפואה מזה העפוש כמו הענין באדם שהוא חי הנה כשיטמאו אלו הדברים בזה האון ישרפו להעיר על חסרון החמר ושמצד צורתו היה השתמשות האדם בו ולזה נמנעה ההשתמשות בו באדם ונאסרו בהנאה להורות על זה הענין:
@444 **והבגד כי יהיה בו נגע צרעת בבגד צמר או בבגד פשתים** לפי שהיותר נהוג בבגדים הוא שיהיו מצמר או מפשתים. לא הסכימה התורה שיהיה נוהג אלו הנגעים כי אם באלו המינים מהבגדים ולזאת הסבה הוא מבואר שלא ינהג זה בצמר ההוה מהגדל בים כי אינו נהוג שיעשה מזה בגדים ובכלל הנה לא ינהג בצמר אלא הבא ממין הצאן וכבר התבאר מהשרשים הכוללים שאם היה רובו צמר או פשתים הנ יטמא בנגעים ולפי שסמך בגד צמר לבגד פשתים והיה מבואר בבגד פשתים שהוא לבן יחוייב בבגד צמר שיהיה לבן ואז ינהג בו זה הדין ולזה לא ינהגו נגעי בגדים בצבעונים אף על פי שנצבעו בידי שמים וזה כי באלו העניינים שהם חדוש לא נקח אלא מה שבא בתורה בזולת הקש ודמיון:
@445 **או בשתי או בערב לפשתים ולצמר.** רוצה לומר שאם טוו מהפשתים או מהצמר השתי הוא הדק ממנו או הערב יטמאו בנגעים או בעור או בכל מלאכת עור ירצה באומרו או בעור או בכל כלי עור ולזה תראה שאחר זה אמר תמורת או בעור לכל אשר יעשה העור למלאכה:
@446 **והיה הנגע ירקרק או אדמדם.** הנה מפני שההכפל בכל העניינים הוא לחזק הנה ירצה בזה ירוק מאד או אדום מאד:
@446 **בבגד או בשתי או בערב או בכל כלי עור.** למדנו מזה שלא יטמא העור בנגעים אם לא היה כלי משמש את האדם ואם ישמשהו באי זה אופן שיהיה הנה יטמא בנגעים והנה נלמד זה גם כן כי התורה הקדימה בזה המקום היותר נכבד ולזה הקדימה הבגד לשתי ולערב ובזה יתבאר כי בהקדימה העור לכל מלאכת עור יהיה העור יותר נכבד והוא מורה על הכלים המשמשין את האדם שמוש נראה ובאמרו לכל מלאכת העור. הרבה את הכלים שישמשו את האדם באופן חלוש כמו האהלים של עור ומה שינהג מנהגם ולפי שאמר בכל מלאכת עור והמלאכה שתעשה מן העור בעצמות וראשונה אין העור צבוע בידי אדם הנה לא ינהג זה הדין בעור הצבוע בידי שמים כי הבדילה התורה אותו מהבגד ולזה לא נלמד בו זה הדין מבגד:
@447 **והסגיר הנגע שבעה ימים.** לבחון עניינו לאי זה כית יפנה כי למספר השבעה ימים רושם חזק בעניינים הטבעיים והוא דבר ממוצע בין הטהרה ובין השלוח חוץ למחנה כמו שקדם ולזה יתבאר שדין השלוח חוץ למחנה ינהג בבגדים ובכלי עור ובשתי ובערב והנה ביום השביעי ישוב לראותו ואם פשה הנגע יטמאנו כי הנגע הוא צרעת ממארת רוצה לומר שמביאה מארה והשחתה ובלוי לדבר שהוא בו:
@449 **ושרף את הבגד וגו'.** הטעם כדי שלא יגיע ממנה תועלת לאדם וזאת השרפה היא חוץ לעיר כי הבגד המנוגע ישולח חוץ לעיר כמו שביארנו וראוי שנדע שהפשיון יהיה בבגדים ובעור אם כשיתפשט הנגע יותר ממה שהיה חוץ לנגע. וזה יהיה בכל שהוא אם בשיתחדש בהם נגע אחר כי זה גם כן יורה על התפשט זה המקרה בכללות הבגד והכלי עור וזה מבואר בנפשו ויתבאר עוד ממה שאמר בסוף זה העניין פורחת היא כי אף על פי שזה הנגע הוא נגע אחר הנה דינו דין הפשיון:
@450 **ואם יראה** ביום השביעי שלא פשה הנגע. הנה יצוה הכהן וכבסו אשר בו הנגע לא כל הבגד וכל הכלי כי הצורך בזה הכבוס הוא בעבור הנגע להעביר זה הכתם ולזה יעשה כמה שיתכן בו העברת זה הכתם ובזה תהיה בחינת המקרה אשר היה בעבורו זה הנגע כי אם היה דבר מחוץ יסור בזה האופן ואם היה בעצם הבגד או העור לא יסור והסגיר הכהן שבעת ימים שנית לבחון עניינו בסוף השבעה ימים ואם לא הפך את עינו מהמראה שיהיה בו נגעו הנה אף על פי שהנגע לא פשה הנה הוא טמא וישרף באש חוץ למחנה כמו שקדם:
@452 **פחתת היא בקרחתו או בגבחתו.** ור"ל שזה הנגע הוא רכיבה אל הפחו' והחסרון והפרד ההרכבה הוא שיהיה הבגד או העור חדש או הפכו והנה הגבחת באלו הדברים ר"ל בבגדים ובעור יאמר על החדשים לפי מה שירוה עליו הגדר וקרחת יאמר על השחקים:
@453 **ואם ראה הכהן והנה כהה הנגע אחרי הכבס אותו.** רוצה לומר שנשתנה אל ירוקות יותר חלוש ממה שהיה או לאודם חלוש ממה שהיה וקרע אותו מן הבגד או מן העור או מן השתי או מן הערב רוצה לומר שיקרע מקום הנגע ויסירהו משם ולא ביערה התורה מה שיעשה בזה הנגע שקרע והנה נלמד מזה הענין שהוא נשרף ולזאת הסבה הוסר להציל על שאר הבגד או העור ואם תראה עוד בבגד או בשתי או בערב או בכל כלי עור מפני שקרע אותו כלי אחר הקריעה למדנו שהוא ישים בבגד ובעור במקום הקרע מה שיתוקן בו וישאר כלי כמו שהיה ואם תראה עוד באי זה מקום שיהיה מהעור והבגד אפילו במקום שטלו בו המטלית לתקנו:
@454 **פורחת היא באש תשרפנו את אשר בו הנגע.** רוצה לומר שזה העפוש שצומח בזה הבגד והערו להיותר דורך אל ההפסד והנה אם היה זה הנגע בזולת המטלית שנאמר ואת אשר בו הנגע והנה לא היה בו נגע כלל ואמנם אם היה הנגע כמטלית הנה ישרף הבגד והעור שנאמר באש תשרפנו את אשר בו הנגע רוצה לומר עם אשר היה בו הנגע:
@455 **והבגד או השתי או הערב או כל כלי עור אשר תכבס וסר מהם הנגע.** אף על פי שכבר נשתנה למראה אחר שאינו ממראות נגעים אלו ולא חזר למראהו הראשון הנה הוא טהור אחר שיכבסו אותו כבוס שני ויטבלו אותו ולזה רמז באמרו וטהר רוצה לומר שיטהר בטבילה. וראוי שנדע ששיעור אלו הנגעים הוא כגריס כמו העניין בצרעת אדם כי התורה זכרה אלו הנגעים יחד:
@456 **זאת תורת נגע צרעת בגד הצמר וגומר לטהרו או לטמאו.** רוצה לומר שכבר למדה התורה בזאת הפרשה מתי יטהרם הכהן ומתי יטמאם והנה לא זכרה התורה הדין אם סר הנגע בהסגר הראשון כי דינו מבואר ממה שנזכר בזה ההסגר השני כי מה שיטהר בו בהסגר השני כל שכן שיטהר בו אם יקרה בהסגר הראשון וכן לא זכרה התורה מה יהיה הדין אם כהה אחר ההסגר הראשון והנה יתבאר שאם כהה אחר ההסגר הראשון לא יקרע וישרף כמו הענין אם כהה אחר ההסגר השני אבל טעון כבוס והסגר כי התורה לא הבדילה בזה בין הפך עינו ללא הפך עינו כמו שיראה שם אבל כיון שלא פשה הנגע טעון ככוס והסגר ואמנם אחר ההסגר השני לא נזכר מה יהיה דינו אם כהה ופשה אבל נזכר שם דין לא נשתנה מראהו אף על פי שלא פשה ויתבאר שמה שביאר בלא כהה ולא פשה ינהג בכהה ופשה כי עמידת הנגע בעינו הוא סימן הטמאה וכן הפשיון ואין הכהה סימן לסור הנגע כמו שאין העדר הפשיון סימן לסור הנגע ולזה יהיה כהה ופשה מורה על הטמאה במדרגת מה שיורה עליו לא כהה ולא פשה והוא מבואר שהוספת הנגע במראהו אינו למטה בהוראה על הטמאה מעמידת הנגע בעינו ולזה אם הוסיף חוזק במראהו ולא פשה יהיה דינו כאלו עמד בעינו ולא פשה וכל שכן כשיהיה טמא אם הוסיף חוזק בעינו ופשה. ובכאן נשלם ביאור זאת הפרשה והנה נתננו הסבה בסדורה וזכירת תועולותיה יהיה אחר ביאורינו פרשת תורה המצורע כי אז ישלם זכר אלו הטמאו' וטהרתם:
@480 **זאת תהיה תורת המצור' ביום טהרתו.** רוצה לומ' כשיטהר מצרעתו ונרפא אחר שטמאהו הכהן באי זה שיהיה ממיני הצרעת הנזכרים ונשתלח מחוץ למחנה כי כבר יתבאר אחר זה שהכהן יצא אל מחוץ למחנה לראותו אם נרפא נגעו ולזה לא ינהג זה הדין במצורע מוסגר ולמדה התורה שביום עצמו שטהר מנגעו יביא צפורים לטהרו ולא יצטרך להמתין בא יום אחר והיה זה כן לפי שאין הצפורים מסירין טומאתו לגמרי כי מן השקר שיהיה המצורע עצמו טהור כשנרפא קודם הערב שמש והנוגע בו לא יטהר עד הערב והובא אל הכהן אחשוב כי מפני שהיה מושבו טמא כמו שיתבאר יצטרך שיובא אל הכהן בצאת הכהן אל מחוץ למחנה ועוד כי לכבוד הכהן יחוייב שיובא אליו וכבר היה בא אליו תוך המחנה אם היה לו רשות להכנס בו ולזה יצא הכהן מעט אל מחוץ למחנה ושם יבא אליו המצורע לטהרתו:
@481 **ויצא הכהן אל מחוץ למחנה.** למדנו מזה שהוא ראוי בזה שהכהן יטהרנו שלא יהיה מצורע כי זה הכהן עומד תוך המחנה ויצא משם לזאת הטהרה והמצורע לא יתכן בו שיעמוד תוך המחנה וסבת זה מבוארת מאד ממה שאמרנו בסבת הטהרה הזאת:
@481 **וראה הכהן והנה נרפא נגע הצרעת מן הצרוע.** וזה אם בסימני טהרה כמו העניין בצמיחת שער שחור בנתק שיורה על הרפואה או בסור סימני טמאה או בסור נגעו לגמרי:
@482 **וצוה הכהן ולקח למטהר.** הצווי בכהן והלקיחה בכל אדם:
@482 **שתי צפורים חיות טהורות.** הרצון בצפורים שיהו דרין בבית כבשדה שהרי נאמר ושלח את הצפור החיה על פני השדה ואלו לא תהיה דרה בבית הנה בצאתה מידו תשתלח מעצמה על פני השדה והצפור שבזה התאר הוא צפור דרור ואמר חיות להוציא הטרפה שאי אפשר לה להחיות כי לה חולי או מכה יוליכה אל המות ואמר טהורות להוציא העופות הטמאים והנה ראוי שיקח יחד שתי אלו הצפורים ושיהיו שוים כי זה מדרך האחרים שיכון בהן המספר אלא שאין זה מעכב שכבר יתכן שיפול המספר בהם מפני היות כל אחד משניהם צפור:
@482 **ועץ ארז ואזוב ושני תולעת.** ראוי שיעיה עץ הארז כשעור שיוכר בו שהוא עץ ארז. ולא יכבד על הכהן להזות בו עם אלו המינים הקשורים עמו ולזה יחוייב שיהיה בראשו טרף שיוכר בו שהוא ארז ושיהיה גדול מאד על האזוב כי הוא לוקח מצד מה שהוא מהצמח היותר גדול והאזוב לוקח מצד מה שהוא הצמח היותר קטן וכשהביטו מפרשי התורה באלו השרשים הספיק להם שיהיה אורכו אמה ובראשו טרף ועביו כמו רובע כרע המטה כשחלק אחד לשנים ושנים לארבעה ושיעור האזוב אינו פחות מטפח כי הוא יקחהו בידו אם שאר המינים ויטבלם בדם ובמים ויזה כמו שיזכור אחר זה וזה לא יתכן בפחות מטפח כי שעור אצבעות היד אשר בהם תהיה הלקיחה הוא קרוב מטפח. וראוי שיהיה זה האזוב המין ממנו שיקרא אזוב סתם לא המין שיקרא אזוב עם שם לווי כמו אזוב יון או אזוב מדברי כי התורה זכרה אזוב סתם ושיעור השני התולעת אין פחות משקל כי הוא ראוי שיהיה באופן שיקשרו בו אלו המינין וישובו להקיף בו לצפור החיה ראשי אגפיים והזנב באופן שתקשר עם אלו המינים קשירה מה ולא תפרכס בכנפיה ובזנבה וזה לא יתכן בפחות מזה השיעור לפי מה שנראה בחוש וצוה הכהן ושחט את הצפור האחת. אין הרצון בזה שתהיה הצואה בכהן והשחיטה בכל אדם כי כבר נמשך אחר זה לזכור הפעלות הנשארות ולא זכר שיהיה עניינם נעשה על יד כהן והם פעולות מבואר מעניינם שלא יתכן העשותה כי אם על יד כהן והם לקיחת אלו המינים וטבילתם בדם וההזאה על המצורע ולזה הוא מבואר שכבר נזכר בזה המקום כהן להעיר שמזאת הפעולה יתחייב להיות הכל על ידי כהן ולזה יהיה הרצון בזה כי הכהן יצוה להביא אלו הצפרים אליו ויתר המינים הבאים עמהן וישחט האחד מהזוג:
@483 **אל כלי חרש על מים חיים.** רוצה לומר שימצה דם הצפור אל הכלי חדש על מים חיים שלא נשתמשו בו לתועלת האדם והוא מבואר שהוא ראוי שיהיה הענין כן בכלי רוצה לומר שיהיה חדש שלא נשתמ' לתועלת אדם לסבה בעינה אשר היתה זאת המצוה במים שתהיה בהם זאת הטהרה ולפי שאמר אחר זה בדם הצפור השחוטה על מים החיים למדנו שיהיו המים כשיעור שיהיה דם הצפור נכר ויוכר עם זה שהם מים ולזה לא יהיה לפי מה שנתבאר מן החוש כי אם ברביעית עם שבזה שיעור יתכן טבילת המינים האלו וההזאה בהם את הצפור החיה יקח אותה ואת עץ הארז ואת שני התועלת ואת האזוב. למדנו שהוא ראוי שיקח הצפור השנית הנשארת ויקח עמה שלשת המינים הנשארים:
@484 **וטבל אותם ואת הצפור החיה.** למדנו מזה שהם קשורים יחד שלשתם באופן שיהיו אגודה אחת שנאמר ויטבול אותם ושהצפור החיה אינה בכלל אגודתם שנאמר ואת הצפור החיה להורות שהם עמה שנים במספר וזה יהיה כשיהיו הם אגודה אחת וחוץ מהאגודה ההיא תהיה הצפור ותאגד בהם אגודה מה באופן שתהיה הטבילה בהם יחד:
@484 **בדם הצפור השחוטה על מים החיים.** הנה תהיה הטבילה בזה הדם שמתמזג על המים החיים לארבעת אלו המינים יחד להזות על המטהר מן הצרעת:
@485 **והזה על המטהר מן הצרעת שבע פעמים.** אחשוב שכבר יתבאר מלשון התורה כי על כל הזאה טבילה רוצה לומר שיזה ויטבול שבע פעמים והנה לא יחדה התורה אבר מיוחד תהיה בו ההזאה והנה מפני שזה היה לכונה שהוא נפרד עתה ממה שהיה בו מההפסד והחלי ולזה ישלח את הצפור החיה על פני השדה. הנה ראוי שתהיה במקום מורה על ההפרד ולזה תהיה זאת ההזאה אחורי ידו כאלו יאמר שהוא בלתי מחזיק עוד בזה העפוש וההפסד כי תוך היד מורה על החזקה ואחורי ידו מורה על הפך זה והוא מבואר בנפשו ולזאת הסבה בעיני תהיה ההזאה בבית המנוגע כשטהר על משקוף הבית מבחוץ:
@485 **וטהרו ושלח את הצפור החיה על פני השדה.** רוצה לומר שכבר תהיה זאת ההזאה לטהר המצורע וכבר ביארנו סבת זה בסוף פרשת שמיני והיא על יד כהן. ולמדנו מזה ששאר הפעולות שבגופו שבהם רושם לטהרתו הם נעשים על ידי כהן ולזה יתבאר שתגלחתו נעשית על ידי כהן ואחר כך ישלח את הצפור החיה אשר הזה בה על פני השדה וזה השלוח לא יצטרך שיעשה על ידי כהן לפי מה שהגבלנו ממה שאמר הכתב וטהרו ולפי שזה השלוח הוא על פני השדה שהוא חוץ לעיר הנה הוא מבואר שלא יהיה שלוח על פני השדה אם היה בשדה חוץ לעיר אבל יתחייב מזה הלשון שישלחה מתוך העיר על פני השדה:
@486 **וכבס המטהר את בגדיו.** לטהרם מן הטמאה הראשונה ואף על פי שכבר ישוב לטמאם אחר זה בלבשו אותם הנה הטמאה ההיא באופן מה למטה מהטומאה הראשונה כמו שיתבאר:
@486 **ורחץ במים וטהר ואחר יבא אל המחנה.** הנה זאת הטבילה תהיה אפילו במי מקוה כי לא אמר במים חיים ויטהר בה מלטמא בביאה ומלטמא משכב ומושב לא יטמא כי אם הטומאה שזכרה התורה אחר זה והיא שהוא מטמא בגדים במגע ולזה הוא מבואר שהוא מטמא עדיין אדם וכלים במגע ולא נלמד מזה שיטמא במשא כי יש שם מי שיטמא במגע ולא יטמא במשא לחולשת טומאתו כמו שיתבאר בפרשת שמיני ואחר זה גם כן יותר להכנס לפנים מן החומה:
@486 **וגלח את כל שערו.** הנה התגלחת היא על ידי כהן כמו שבארנו ואמרו כל שערו רוצה לומר כל שערו אשר בנראה מגופו שהרי אמר אחר זה בפרטי השער:
@486 **וישב מחוץ לאהלו שבעת ימים.** הטעם בזה הוא להפרישו מאשתו כי המשגל הוא ממה שיזיק לו בהחלישו החום היסודי ואולי יהיה זה סבה להשיבו לעניין חוליו ולפי שאין המשגל מזיק לאשה בזה האופן כי זרעה הוא נא בלתי מבושל והיה מאמר התורה בזה בלשון זכר למדנו שאין הדין נוהג באשה כי היא מותרת בתשמיש המטה והיה ביום השביעי יגלח את כל שערו את ראשו ואת זקנו ואת גבות עיניו ואת כל שער יגלח כבר ביארנו שהתגלחת היא נעשית בכהן וכבס את בגדיו ורחץ את בשרו וטהר הנה בזאת הטבילה יטהר לכל הדברים של חולין זולתי לקדשים ולמקדש שלא יטהר לפי שהוא מחוסר כפרה כמו שנתבאר ביולדת ומשם נלמד זה העניין ולזה אמר בהשלמת הבאה קרבנותיו וכפר עליו הכהן וטהר ולולא שכבר היה טמא לדבר מה לא אמר וטהר:
@487 **את ראשו ואת זקנו ואת גבות עיניו.** שהם כלם בנראה מהגוף ולזה לא יצטרך לגלח השער שבתוך החוטם והוא מחוייב שלא ישארו שתי שערות בשערות שיתחייב בהם התגלחת שאם נשארו שם שתי שערות לא עלתה לו תגלחת שנאמר את כל שערו. ולזה ראוי שלא ישאר שם מה שיפול בו שם שערות והוא שתי שערות לפי מה שהתבאר בשרשים הכוללים:
@488 **וביום השמיני יקח שני כבשים תמימים וכבשה אחת בת שנתה תמימה.** ראוי שתדע כי מה שאמר בזה וביום השמיני אין הרצון בו שאם לא הביא אלו הקרבנות אז לא יוכל להביאם אחר זה להשלים טהרתו אבל לקחה התורה אותו הזמן היותר קצר שיתכן שתשלם בו טהרתו. והנה יקח הכבש לאשם ויקריבהו ראשונה ובו יוכל אל שיקריב חטאתו ועולתו לכפר עליו מטומאתו כמשפט שאר מחוסרי כפרה המביאין קרבן וזה כי מפני שהיה הצפור הנשחט בחוץ חטאת בתכלית החסרון עד שלא היה קרב ממנו דבר למזבח לחסרון החמר שהורה עליו הנה היה ראוי שיביא אחריו מה שישלם בו באופן מה שחסר בחטאת הראשון ואחר יאות לו להקריב חטאתו ועולתו ולא היה ראוי שיסמוך על החטאת הראשון להשלים טהרתו לסבה שזכרנו עם של חוזק טומאת שכבר נשאר טמא אחר החטאת ההוא באופן שהוא מטמא בגדים כמו שקדם והעמיד הכהן המטהר את האיש המטהר ואותם לפני השם פתח אהל מועד הנה יעמיד הכהן את המצורע המטהר חוץ לעזרת ישראל כנגד פתח המזרח ופני המטהר לצד המערב שהוא לפני השם כי לא יוכל להכנס יותר מזה השיעור קודם שתשלם טהרתו ומה שאמר ואותם אין הרצון בו שיעמיד גם כן הקרבנות ומה שהביא עמהם מהסלת והשמן כי לא יתכן שיאמר בהם העמדה אבל הרצון בו שהוא ראוי שיהיו מוכנים שם כל הדברים האלו להשלים טהרתו אם ירצה שתשלם לו הטהרה ביום ההוא ומה שאמר האיש אין הרצון בו שלא ינהג זה באשה ובקטן כי כבר אמר אחר זה על הראש המטהר וכפר המטהר מטמאתו שיורה שאי זה שיהיה המטהר ינהג בו זה הדין. ועוד שאתה תמצא קרבנות טהרה נוהגות באשה כאיש כמו שיתבאר בעניין זב וזבה ואף על פי שכבר היה הזב יותר ראוי בחוזק הטומאה מהזבה כמו שיתבאר מדברנו:
@490 **ולקח הכהן את הכבש האחד והקריב אותו לאשם ואת לוג השמן והניף אותם תנופה לפני השם.** לפי שהכהן היה אז במזרח העזרה הנה הוא מבואר כי התנופה הזאת תעשה במזרח ופניו למערב שנאמר לפני השם וכן העניין בשאר התנופות כמו שקדם והנה התנופה היתה שהיה הכהן מוליך ומביא מעלה ומוריד הכבש ולוג האשם כמו הענין בשאר התנופות:
@491 **ושחט את הכבש.** זה מבואר ולזה יהיה הנאכל ממנו נאכל לפנים מן הקלעים לזכרי כהונה כי הוא קודש הקדשים:
@492 **ולקח הכהן מדם האשם וגומר.** הנה לא זכרה התורה מה שיהיה במזבח מדם האשם והחלבים גם לא זכרה הנאכל לכהנים ממנו להשענה על מה שביארה מזה בתורת האשם וראוי שנעיין אי זה מהנתינות הדם תהיה ראשונה אם יתן ראשונה על המטהר ואחר על המזבח או הפך זה והנה יתבאר שהוא ראוי שיהיה ראשון מה שיהיה למזבח כמו שהיתה החלבים קודם אכילת שאר לכהנים כי המגיע מזה לשם יתעלה מתיר הנשאר לאדם ועוד שהרי מצאנו בביאור בפרשת ואלה המשפטים שחצי הדם זרק על המזבח קודם שיזרוק על העם מהדם הנשאר להביאם בברית עם השם יתעלה ובכלל הנה הוא מבואר שמה שהגיע מהקרבן לשם יתע' קודם מה שמגיע ממנו לאדם ולזה זכרה התורה בזאת הפרשה ההזאה מן השמן שבע פעמים לפני השם קודם הנתינה ממנו על בוהנות המטהר ואזנו ולזה הוא מבואר שאחר זריקת הדם על המזבח סביב בחלק השפל מהמזבח היתה זאת הנתינה מהדם על המקומות מהמצורע שזכר וזה שהדם שיקבל הכהן לתת על בוהנות המצורע ראוי שיהיה דם האשם לא שירי הדם הנזרק שנאמר ולקח הכהן מדם האשם ולזה הוא מבואר שבעת נתינת שחיטת האשם יקובל קצת הדם לתת על המזבח על יד אחר מהכהנים כלי שרת כמשפט וכהן אחר יקבל אז קצת הדם לתת על בוהנות המצורע ואזנו ויתבאר מהנמשך לזה בעניין הזה שזאת הקבלה תהיה בכף הכהן ולפי שהיא עבודה ראוי שתהיה בכף הכהן הימנית כמו שהתבאר בשרשים הכוללים ולפי שהנתינה תהיה מהכף השמאלית באצבע הכהן הימנית כמו שהתבאר בשרשים הכוללים מנתינת השמן על בוהנות המצורע ואזנו בזאת הפרשה הנה יערה הכהן הדם מידו הימנית לידו השמאלית ואחר יטבול אצבעו הימנית בדם אשר על כפו השמאלית ויתן ממנו על תנוך אזן המטהר הימנית וזה יהיה אחר שיכניס המטהר ראשו בעזרה באופן שלא יצא הדם חוץ לעזרה כדי שלא יפסל ואחר יכניס המצורע ידו הימנית בעזרה ויתן הכהן מן הדם באצבעו על בהן ידו הימנית ואחר יכניס המצורע רגלו הימנית ולקח הכהן מלוג השמן ראוי שתדע שהוא ראוי שיהיה לוג השמן בעת זאת הלקיחה והיציקה ולזה אם נשפך ממנו אם אם חסר ממנו אי זה שיעור שיהיה קודם שיציקה לא יתכן לעשות ממנו מה שזכר אם לא ישלים שעורו קודם זה וכן ראוי שיהיה הנתן על בוהנות המצורע מלוג השמן ולזה אם חסר או נפשך קודם הגמר הזאות השמן והנתינה ממנו על בוהנות המצורע ואזנו צריך להביא לוג אחר לעשות ממנו הנזכר בזאת הפרשה בסדר הנזכר:
@494 **והזה מן השמן באצבעו שבע פעמים לפני השם.** הנה ההזאה הזאת היא לצד המערב כנגד קדש הקדשים שנאמר לפני השם ועל כל הזאה והזאה תהיה טבילה ומיתר השמן אשר על כפו יתן הכהן באצבעו הימנית על תנוך אוזן המטהר הימנית ובוהנותיו על דם האשם רוצה לומר אצל דם האשם או עליו ממש. וראוי שתדע שלא יחוייב שיהיה שם דאם האשם בעת זאת הנתינה וזהו שכבר אמר תמורת זה בקרבן מצורע עני על מקום דם האש ולזה אף על פי שנתקנה הדם משם קדם זאת הנתינה יתכן לתת מהשמן בבוהנות המצורע ואזנו באופן הנזכר ולפי שאמר ויצק על כף ההן השמאלית ולא אמר על כפו למדנו שהוא ראוי שתהיה זה על כף כהן אחר אלא שאין זה מעכב וזה שכבר תמצא בפרשה הבאה אחר זה ונתן הכהן מן השמן אשר על כפו וזה מורה שאפשר שיעשה זה בכף כהן עצמו והנותר בשמן אשר על כף ההן יתן על ראש המטהר וכפר עליו הכהן לפני השם למדנו שראוי שיהיה זה העניין לפני השם רוצה לומר שיהיו פניהם לצד המערב ושזאת הנתינה היא מעכבת הכפרה ולזה אמר יתן על ראש המטהר וכפר עליו הכהן הא אם לא נתן לא כפר ועשה הכהן את החטאת וכפר על המטהר מטמאתו רוצה לומר שאחר זה יותר לו לאכל קדשים ולהכנס לעזרה ואולם העולה אינה מעכבת הטהרה כמו שזכרנו בפרשת יולדת ואמנם אמר הקרבת העולה והמנחה וכפר עליו הכהן וטהר לחתימת המאמר כאלו אמר שבסדר הנזכר תשלם הכפרה והטהרה למטהר ואולם למה היו אלו הקרבנות בזה האופן אחר התגלחת והצפרים הנה ראוי שנאמר בזה לפי מנהגנו והשגתנו ונאמר כי מפני שהיה חטאת המצורע הנעשה חוץ לשלש מחנות בתכלית מההוראה על החומר החסר ולזה לא היה ממנו דבר להשם יתעלה ולא לכהנים וגם לא היה מטהר בו המצורע לחסרונו כמו שנזכר הנה לא היה ראוי שתבא אחריו עולה שהיא כלה לשם יתעלה כי אין האיש הזה במדרגה שתקובל ממנו עולת כי היא תבא אחר שלמות הטהרה ולזה בא אחריו אשם המורה על הצורה הוראה מה ולזה היה נזרק דמו למטה וסביב והיתה הוראת האשם בזה המקום לפי הנראה לנו כי מהצורה באה הרפואה למטהר כמו שבא ההפסד מצד החמר ולזה היתה נתינת הדם והשמן מהכף השמאלית על אלו האברים הימניים כאלו יאמר כי מהצורה היתה זאת הדריכה מהשמאל אל הימין כי השמאל מורה על הנטייה וההפסד וחלי הוא נטייה ממנהג הטבעי והיתה נתינת הדם והשמן על אלו האברים שהם קצוות הגוף והם מפני זה חלושים וידחו להן המותרות לזאת הסבה ועם זה כאשר תעשה הצורה פעולתה בשלם שבפנים ידחה העפוש וההפסד גם מאלו המקומות החלושים והנה יזה משמן שבע פעמים לפני השם להעיר כי הכחות השופעות מהגרמים לפי מה שנתן מהם השם יתעלה מהכח ביום הבראם הם שומרים האדם בעצמות מכמו אלו ההפסדים וזה המכוון מהם ואם היה שיהיה במקרה סבה באופן מה לכמו אלו הפסדין כמו שזכרנו ולזאת הסבה היה התנופה לזה האשם להורות כי התנועות הסבוביות הם התחלות לתנועות היסודיות ולתנועות המורכב מהם לפי מה שסודר ביום ברא ארץ ושמים וזה כי ההולכה וההובאה מעירות על התנועות הסבוביות המזריחית והמערבית וההעלאה וההורדה מורה על תנועה מהמרכז ואל המרכז ואלו התנועות הנזכרות סבות שאר התנועות הקודמות כמו שהתבאר בטבעיות והנה היתה זאת הפעולה המורה על הצורה בשמן שנשאר רשומו זמן ארוך והיתה הפעולה המורה על החמר החסר במים שלא ישאר רשומם כי אם מעט כי החלי שוהא מפאת החמר הוא מעט ואולם הבריאות שהוא מצד הצורה הוא מאדיי ולזאת הסבה היה ההקדשה במשיחת השמן והנה היה השמן ההוא רוקח ולמעלת הנמשח בו מה שאין כן בשמן אשר ימשח בו המטהר מהצרעת ואמנם ינתן הנשאר מהשמן על כפי השמאלית על ראש המטהר באצבעו הימנית לפי שהראש לקרירותו יתפעל בקלות מחסרון החום היסודי. ובהיותו שלם ישמר מהרעועים וכאלו יעיר בזה כי הצורה בהיות פעולתה שלמה תשמר הראש מהפסדים עם האותות לקבל הרעועים מצד החמר וזה כלו לפי מה שהשרשנו נוהג מנהג הענינים להעיר על מציאות הצורה ושמנינה יהיו הטובות וההפסדים יהיו בסבת החמר ולפי שדם האשם מורה על הבריאות שהוא מצד הצורה לא יכשר היותו כי אם כבש ואף אם היה המצורע עני וזה שהדם מורה על ההפסד הוא דם העוף להיותו בעל חי חסר כמו שבארנו ולזה יחוייב שיהיה זה הדם השני שמורה על הבריאות דם בעל חי שלם והוא ההולך אשר יוליד בעל חי כגופו ולזה לא תיכן שיהיה תור או בני יונה ולזאת הסבה תמצא במצורע עני שיביא חטאתו ועולתו מן העוף אבל אשמו יהיה כבש עכ"פ ואם דל הוא ואין ידו משגת רוצה לומר שדלותו הוא באופן שאין ידו משגת לכל אלו הקרבנות ולפי שאין המטהר ראוי לחטאתו ולעולתו ולמנחתו אשר בהם הבדל בין דל לעשיר כי אם אחר הביאו אשמו הנה יודע אז אי זה קרבן יתחייב להביא שאם היה אז עשיר יתחייב להביא קרבן עשיר אף על פי שהעני אחר כך ואם היה דל יביא קרבן עני אף על פי שהעשיר אחר זה ולפי מה שהתבאר בשרשים הכוללים יתבאר שהדם העומד לזרק נפשט אותו כזרוק ולזה כיון כשנשחט דם האשם יחול עליו חייוב היות הבאת שאר הקרבן ואז יבחן אם יתחייב להביא קרבן עשיר או עני ושאר מה שנזכר בזאת הפרשה מקרבנות המטהר הכל מבואר ממה שקדם לנו מהמאמר בקרבנות עשיר והנה שם זכרה התורה על הסדר הנשכר בקרבנות עשיר להעיר כי הכל מכוון ולזה לא יתחלף זה הנימוס כלל ואם יתחלפו הב"ח אשר מהם והיה הקרבנות וכמות המנחה:
@512 **כי תבואו אל ארץ כנען.** יעיר שאין נגעי בתים נוהגים אלא בארץ ישראל:
@512 **ונתתי נגע צרעת.** הנה יחס להשם יתע' נתינת נגע צרעת כי הוא סבה אל מה שיתחדש באופן מה ואף על פי שאין הרע מתחדש ממנו בעצמות כמו שיתבאר במקומותיו וגם אפשר עם זה שיהיה הנגע מתחדש בבי' על ההשגחה אם להראותם האוצר הגנוז שם כמו שאמרו ז"ל או לשמור העומדים שם מהמפולת וזה שהם ישבו בבתים אשר לא בנאום ולזה היה אפשר שיהיו רעועים ונכונים אל הנפילה לרוב זמן זה הבנין והם לא ידעו זה ולזה היה הש"י מראה בבית ההוא על צד ההשגחה זה ההפסד אשר לבית בקירות הבית והנה היה מראה זה הנגע ירקרק או אדמדם לסבה בעינה שזכרנו בנגעי בגדים וכלי עור:
@512 **בבית ארץ אחוזתכם.** למדנו מזה שירושלם אינה מטמאה בנגעי' לפי שלא נתחלקה לשבטים ולזה אינה אחזה לאיש מיוחד שיתכן שיאמר בה:
@513 **ובא אשר לו הבית כנגע נראה לי בבית.** ולא יאמ' נגע נראה לי כי המשפט בזה לכהן הוא:
@514 **וצוה הכהן ופנו את הבית בטרם יבא הכהן לראות הנגע ולא יטמא כל אשר בבית.** למדנו מזה שיש לאחר ראיית הנגע עד שיבנו הבית כדי שלא יגיע בזה צער לבעל הבית ומזה המקום נלמד שיש לאחר ראיית נגעי אדם לזאת הסבה ולזה לא יראו הנגעים בשבת ולא בי"ט כדי שלא יקרה מזה צער לבעל הנגע ביום שהיה ראוי שישמח בו:
@514 **ואחר כך יבא הכהן לראות הבית.** למדנו שהוא יראה באופן שיהיה בו לא שיפתחו בו חלונות כדי שיראה נגעו בשלמות וזה יתבאר מאמרו הבית בה"א הידיעה:
@515 **וראה את הנגע והנה הנגע בקירות הבית.** לפי שהנגע יחוייב שתהיה על שתי אבנים ואז ינהג בו זה הין שנאמר וחלצו את האבני אשר בהם הנגע והנה אין האבנים נקשרות בבנין באופן שיהיו לאחת הנה יחוייב בזה הנגע שיהיה שיעורו כשני נגעים ולזה יהיה רחבו כגריס וארכו כשני גריסין ולמד ממה שאמר בקירות הבית שהוא מחוייב שיהיו לבית קירות ואז ינהג בו זה הדי' לא שיהיה עגול ולפי שהנהוג מהבית שיהיה בו קירות שיהיו בו ארבעה כתלים לא פחות ולא יותר הנה לא ינהג זה הדין כי אם בבית בעל ארבעה כתלים והרצון באמרו בקירות הבית באחת מקירות הבית כמו יקבר בערי הגלעד:
@515 **שקערורות.** רוצה לומ' שיהיה מראיהם שוקע מן הקיר כמו שאמר אחר זה ומראיהם שפל מן הקיר:
@515 **ירקרקות או אדמדמות.** רוצה לומר חזק הירוקות או חזק האודם:
@516 **ויצא הכהן מן הבית אל פתח הבית.** למדנו מזה שהנגע ראוי שיהיה תוך הבית ואז ינהג בו זה הדין לא אחריו כי לא יכנס הכהן בבית בראותו אותו שיתכן שיאמר בו שיצא מן הבית ולמדנו מזה שכיון שיצא מהבית יוכל להסגיר את הבית שנאמר אל פתח הבית לא קודם זה ולזה יצא מתחת המשקוף ויעמוד לצד הפתח ולמדנו מזה שאף על פי שהרחיק מאד מהבית יוכל להסגיר שנאמר ויצא הכהן מן הבית וכבר יצא משם ואין ראוי שנאמר שלא יכשר זה אלא כשהיה סמוך לבית כי אין שם דבר יתחייב ממנו שיהיה יותר ראוי בסמוך כי לא יחוייב שיראה הנגע בעת שישפוט להסגיר הבית שאם היה הדבר כן הנה יקרה שיהיה שם נגע ראוי להסגירו עליו ולא יוכל על זה לפי שלא יתכן לו שיראה הנגע ההוא מפתח הבית ולזה הוא מבואר שלא יחוייב שיראה הנגע מהמקום אשר ישפוט שם שדינו להסגירו וראוי שתדע שכבר יתכן לו להסגירו כיון שיצא מחלל הבית אפף על פי שהוא עדיין תחת המשקוף שהרי אני קורא ויצא הכהן מן הבית אל פתח הבית:
@516 **והסגיר את הבית שבעת ימים.** הנה בארנו הסבה כשיהיה ההסגר שבעת ימים:
@517 **ושב הכהן ביום השביעי וראה והנה פשה הנגע בקירות הבית.** הנה הפשיון הזה יהיה בכל שהוא אם היה סמוך או כגריס אם היה מופלג כי זה יורה על התפשט זה העפוש שם כמו שבארנו בנגעי בגדים:
@518 **וצוה הכהן וחלצו את האבנים אשר בהם הנגע.** למדנו מזה שלא ינהג זה הדין אלא כשהיה הנגע על שתי אבנים לכל הפחות וראוי היה להיות כן כי מפני שהבית הוא מקבוץ הא האבנים הנה לא יתכן שילקח ראיה מהם על כללות הבית אם לא היה זה ההפסד בשנים מהם כי הם הקבוץ הראשון והנה זה הענין באבנים דומה דינו לענין נגעי בגדים וזה כי בנגעי בגדים ישרף כל הבגד כיון שפשה הנגע לא מקום הנגע לבד וכן אם פשה הנגע בבית יסירו כל האבנים אשר בה הנגע לא החלק מהם שבו היה הנגע והנה לא יהיה הסגר בנגעי בגדים אחר הפשיון לפי שאין כללות הבגד חלק לדבר אחר כמו הענין באבנים שהם חלק מהבית. ולזה יצטרך להסגיר אחר הפשיון כמו שיתבאר אחר זה לראות אם ישוב הנגע ואז נשפוט על התפשט ההפסד בכללות הבית ומזה המקום יתבאר שהענין בנגעי בתים בשני ההסגרים הראשונים באבנים אשר בהם הנגע כדין הבגדים שבהם הנגע ואמנם קצרה התורה בזה במשפטה לקצר במה שהוא בכח דבריה ולזה הוא מבואר שאם לא פשה הנגע בהסגר הראשון ופשה בסוף ההסגר השני חולץ האבנים אשר בהם הנגע וקוצה העפר סביב הנגע וטח את הבית ומסגירו פעם שלישית ולזה יהיה בבתים הסגר שלשה שבועות מה שאין כן בנגעי בגדים ולסבה שזכרנו ואם כהה בראשון או שסר הנגע אינו טעון הסגר ולפי שאי אפשר לכבס מקום הנגע כמו העניין בבגדים קולף אותו:
@518 ואם עמד בעיניו ולא פשה מסגירו שנית ואם כהה קולף מקום הנגע כמו הענין בבגדים ואם עמד בעיניו ולא פשה חולץ וקוצה וטח כמו הענין בבגדים שישרף אז כללות הבגד ההוא כי אין הבגד חלק לדבר כמו אלו האבנים שהם חלק מהבית ומזה המקום יתבאר על צד התיחס כי כמו שיבא ההכרח להסיר חלק מהבית ישובו לתקנו כשיקחו אבנים אחרות ועפר אחר כך כשיבא ההכרח להסיר חלק מהבגד ישובו לתקנו כשיטלו בו טלאי ממקום אחר ואחר הסגירו שלישית לשפט על כללות הבית והשליכו אתהן אל מחו לעיר כל עיר משמע בין מוקפת חומה בין בלתי מוקפת חומה ואמנם האדם לא יצא אלא מחוץ לעיר מוקפת חומה שנאמר בו מחוץ למחנה והמחנה במה שהוא מחנה אחד הוא מוקף מחיצה:
@518 וראוי שיתבאר מזה שכן הענין בבגד המנוגע כי אין ביניהם הבדל אלא בענין ההסגר השלישי כמו שבארנו ואולם זכרה התורה זה הדין באבנים לפי שהם יותר פחותים ולזה היה ראוי שתהיה טמאתם יותר קלה לפי מה שהשרשנו בעניין הטמאות והטהרות ומפני זה היה אפשר שנלמד מהם זה הדין לבגדים וכלי עור אל מקום טמא כאלו תאמר המקום שישליכו שם הנבלות ומה שדימה להם מהטמאו' ואת הבית יקציע מבית סביב רוצה לומר שיקלף העפר אשר טחו אותו בו בפנים סביב הנגע:
@520 **ולקחו אבנים אחרות והביאו אל תחת האבנים ועפר אחר יקח וטח את הבית.** יתבאר מזה שאין ראוי שיביא אבן תחת האבנים אבל יביא אבנים תחת האבנים אף על פי שמספרם מתחלף וראוי שלא יהיו האבנים שיביא ולא העפר לקוח מזה הבית עצמו שנאמר אבנים אחרות ועפר אחר והנה הכונה היא להשלים הבית מה שחסר בסבת חלוץ האבנים והקציעה והנה אמרה התורה בלשון רבים חלוץ אבנים והשלכתם ושפיכת העפר וקציעתו ולקיחת אבנים והבאתם. ואולם לקיחת העפר והטיחה זכר בלשון יחיד להורות שאם היה זה הכתל משותף לביתו ולבית חבירו שניהם מטפלין בכל זה זולת בלקיחת העפר האר והטוח הבית שאינו מיטפל בו אלא בעל הבית שנראה בו הפגע:
@521 **ואם ישוב הנגע וגו' עד טמא הוא.** הנה זה שאמר ובא הכהן וראה והנה פשה הנגע בבית. רוצה לומר אחר ההסגר ביום השביעי וזה שכבר אמר אחר זה ואם בא יבא הכהן וראה והנה לא פשה הנגע בבית אחר הטוח ואם לא היה שם הסגר מה זאת הביאה שיבא הכהן לראות את הבית והנה אין בו נגע ולזה הוא מבואר שכבר יסגיר הבית אחרי הטוח אותה שבעה ימים ואם נראה שם נגע כשעור נגעי בתים הנה נשפוט שצרעת ממארת היא לכללות הבית והבית כלו יהיה טמא לא מתוכו לבד ויתבאר במה שקדם בנגעי בגדים שאם נראה הנגע באבנים ששמו שם מחדש הנה יוציאו האבנים ההם עם שאר אבני הבית חוץ לעיר ואם תראה בשאר אבני הבית לא יוציאו חוץ לעירה האבנים ששמו מחדש אבל שאר כל האבנים:
@523 **ונתץ את הבית את אבניו ואת עציו ואת כל עפר הבית.** מגיד שאין מיטפל בנתיצה אלא בעל הבית אשר בו הנגע וניתץ את שלו ומניח של חבירו שנאמר את אבניו לא אבני הבית הנלוה לו ולמדנו מזה שאין דין נגעי בתים נוהג אלא בבית שהיו אבנים ועצים ועפר והיה זה כן לפי שהוא כליי ודומה באופן מה לדברים בעלי הצורה השלמה והם בעלי הנפש כי הם כלם כלים כמו שהתבאר בטבעיות ולזה יטמאו האבנים מצד מה שהם חלק מהבית ואף על פי שאין האבנים ראויים לטומאה כמו שקדם והנה יובדל הבית מהבגדים והעור בלקיחת שתי צפורים לטהרתו כמו הענין באדם מה שאין כן בבגדים ובעור כי הם יטהרו בטבילה וידמה שאין זה הענין כן בבתים למעלתם על הבגדים ועל העור אבל היה זה לפי שאי אפשר בהם הטבילה ואין ראוי שתסור טמאתם בזולת פעל כלל ולזה היתה טהרתם בצפורים שיורו על ההנקות מזה ההפסד שבא בסבת החמר כמו שתורה הטבילה על זה והנה עם זה ההבדל בטהרת האדם בצפורים לטהרת הבית מהם מבואר וזה כי האדם ישאר טמא אחר הבאת הצפורים מה שאין כן בבית לפחיתותו והבא אל הבית כל ימי הסגיר אותו יטמא עד הערב זה יהיה באדם או בכלים והנה יטמא בו כלי חרס אם לא היה מוקף צמיד פתיל כי הכלי חרס אינו מטמא אלא מאוירו וזה נוהג גם כן בנגעי האדם ובנגעי בגדים כי הם ראויים בזה הדין כמו הבתים או יותר מהם אלא שזה יהיה בהיותם קבועים במקום כמו הענין בנגעי הבית לא אם היו נעתקי' בזולת עמידה כלל והשוכב בבית יכבס את בגדיו והאוכל בבית יכבס את בגדיו לפי שהוא טמא תכף בואו הנה לא אמר שוכב או אוכל בעבור טמאת האדם אבל אמר זה בעבור טומאת בגדיו ולפי שאין האכילה והשכיבה שם ממה שיש לו רושם בטמאת הבגדים למדנו שלא אמרה התורה אלא שעור שהייתו שם באופן שיטמאו בגדיו וזה שהבגדים שהוא לבוש לא יאמר בהם שהם באים אל הבית בבואו שם ולזה לא יטמא עד שישהה שם שיעור אכילה בינונית והוא כשיעור שלשה ביצים פת חטים ובלפתן ומיסב כי זהו הנהוג מהאכילה וכשיעמוד שם כמו זה השעור אז יטמאו בגדיו שהוא לבוש קודם זה:
@526 **ואם בא יבא הכהן וראה והנה לא פשה הנגע.** רוצה לומר שלא נתחדש שם נגע אחר זה ההסגר הנה זה ראיה שנרפא הנגע במה שהוסר מהאבנים ושאין העפוש ההוא מתפשט בנשאר מן הבית:
@527 **ולקח לחטא את הבית שתי צפורים וגו'.** הנה מפני שנטמא הבית כל ימי ההסגר והיה בלתי ראוי שתסור טומאתו בזולת פועל כלל הנה תהיה טהרתו בצפורים לפי שאי אפשר בו הטבילה כי הם יורו על שזה ההפסד בא מצד החמר וההזאה בזה האופן תורה על הנקות מזה החסרון כמו שבארנו במה שקדם. והנה תהיה ההזאה הזאת על משקוף הבית מבחוץ להורות שסר הנגע כמו שבארנו במה שקדם:
@532 **זאת התורה לכל נגע הצרעת ולנתק.** אמר ולנתק לפי שאינו נגע אבל הוא נשירת שער:
@533 **ולצרעת הבגד ולבית.** מגיד שדין הצרעת הבגד והבית הוא אחד וכבר התבא' מדברינו שהעניין הוא כן:
@534 **ולשאת ולספחת ולבהרת.** אף על פי שכולם טמאים ראוי שיוכרו לכהן כי אז יהיה שלם הבחינה בעניין נגעי הצרעת ויוכל לעמוד יותר על אמיתת ענין הנגע אם עמד הנגע בעיניו או כהה להורות ביום הטמא וביום הטהור:
@535 **זאת תורת הצרעת.** ר"ל כי בזה האופן ישפט הכהן בנגע שהוא טמא או טהור או בבעל הנגע ואם ישפט בזולת זה האופן לא יהיה משפטו משפט וכבר בארנו זה במה שקדם:
@536 **וידבר יי' אל משה ואל אהרן.** לפי שקצת אלו הטהרות תלויות בכהן כמו הענין בזב וזבה בא בזה הדבור שם אהרן:
@537 **דברו אל בני ישראל.** למדנו שאין אלו הטמאות נוהגות אלא בבני ישראל לא בגוים:
@537 **איש כי יהיה זב מבשרו.** הנה הרצון בזיבה בזכר שישפך ממנו זרע דומה ללובן ביצה המוזרת והנה ראוי שתהיה התחלת הזיבה מבשרו שידחה זה המותר לא שיהיה זה בסיבת דבר מחוץ וראוי שתדע שהזוב נוהג בקטן וכן הענין בזוב הנקבה הקטנה שנאמר בסוף זאת הפרשה והזב את זובו לזכר ולנקבה והנה היה זה כי אף על פי שהזרע המבושל אינו ראוי שימצא בפחות מבן תשע שנים ויום אחד כמו שנאמ' אחר זה ולזה אינו ראוי לביאה עד אותו הזמן כי לא יתחזק על בשול הזרע הנה הזוב אפשר שימצא כן לפי שהוא נא בלתי מבושל וכן הענין בנדות האשה והזבה ר"ל שהוא נא ובלתי מבושל ולזה לא ימנע המצאו בנקבה קטנה:
@537 **זובו טמא הוא.** למדנו שהזוב בעצמו הוא טמא ויתבאר שהוא אב הטומאה מרוק הזב שהוא מטמא אדם כמו שיתבאר אחר זה וכל שכן שהענין הוא כן בזובו:
@538 **זאת תהיה טומאתו בזובו רד בשרו את זובו.** ר"ל שישפך הזוב מבשרו ויצא לחוץ בזה האופן או שהחתים בשרו מזובו ר"ל שיצא זובו לחוץ באופן שתסגר בו נקב הערוה סגירה מה כי זה דרך הזוב כשיהיה כמות מעט הנה איך שהיה מאלו הפנים הנה הוא טמא ולפי שזאת הטמאה היא לזב בכל שהוא והיה בלתי אפשר כשיתואר כשהוא זב בראיה הראשונה למעוט השעור הנה לא יטמא הזה טומאות זוב כי אם בראיה השנית וזה שכבר יתואר דבר בתואר מה אם מפני המשך בו הדבר ההוא זמן ארוך אם מפני הרבות לעשות הדבר ההוא והמשל שהוא יתואר שהוא רופא כאשר רפא פעמים רבות ויקרא אדום כשנמצא בו מראה אדום זמן ארוך ולזאת הסבה לא יתכן שיתואר האדם כשהוא זב בראיה הראשונה כי אין שם ריבוי מספר ולא ארך בזמן ובהיות הענין כן הנה הפחות שיתואר כשהוא זב בראיה השנית ולזה יתבאר שדין ראיה ראשונה של זב לטומאה הוא כדין שכבת זרע והוא מבואר מזה כי טומאת הזב תלויה בראיות לא בימים כמו הענין בזבה ולזה ראוי שנחקור מתי תהיה הראיה או הראיות בראיה אחת ומתי תהיה או תהיינה בראיות רבות ונאמר כי מפני שהראיה הזאת הוא הדחות המותר הזרעי מכלי הזרע הנה ראוי שימצא שם עת ראשון לא יתכן שיהיה בו זה ההדחות שני פעמים וכאשר נעמוד על זה העת מצד החפוש בחוש הנה יודע שכל מה שיראה תוך זה העת הוא ראיה אחת ואע"פ שהפסיק בראיה ההוא וראוי שיהיה זה העת הוא הזמן שישלם בו הדחות זה המותר בטבע ולזה כאשר נמשכה הראיה יותר מהשעור ההוא ידענו שזה הוא הדחות שני וכן אם נמשכה הראיה יותר מכפל מזה השעור ידענו שזהו תהיה ראיה הג'. והנה עמדו הראשונים על זה השעור לפי מה שקבלו מפי משה עם שהוא מבואר מן החוש והוא כדי טבילת האדם וספוגו אחר הטבילה ר"K שלא יגיע שיעור הראיה האחת לשיעור טבילה וספוג':
@539 **כל המשכב אשר ישכב עליו הזב יטמא.** ראוי שיהיה הכלי ההוא עשוי לשכב באופ' שהיה אפשר שיתואר כשהוא משכב ואז ינהג כן זה הדין ולזה אם היה משמש למשכב לבד או שהיה משמש למשכב עם שמושו לדבר אחר בעת היותו משכב כאלו תאמר שיהיה בכאן ארגז ופתח בצדו וישכבו עליו וישימו בתוכו דברים לשמרם דרך פתחו בעור שהוא משמש למשכב הנה דינו דין משכב ואמנם אם לא יהיה פתח אלא בעליונו באופן שכאשר ירצו לפתוח פתחו לא יוכל לשמש משכב הנה לא ינהג בו דין המשכב וכן ראוי שנדין העני' במושב שנאמר וכל הכלי אשר ישב עליו יטמא ר"ל שיהיה דרכו שישבו עליו וזה אמנם יהיה כשיהיה מיוחד לישיבה:
@540 **ואיש אשר יגע במשכבו יכבס בגדיו.** למדנו שמשכבו הוא אב הטומאה לטמא אדם באופן שהוא טעון כבוס בגדים ויטמא טומאת ערב וראוי שתדע שמשכב והמושב והדומה להם ינהגו בכלי' המקבלים טומאה אע"פ שאין להם בית קבול כמו כלי עץ וכלי עור שנ' וכל המשכב וכל הכלי אשר ישב עליו והנוגע בבשר הזב יכבס בגדיו למדנו שהנוגע בבשר הזב טעון כבוס בגדים וטמ' טומאת ערב:
@543 **וכי ירוק הזב בטהור.** יכבס למדנו שרוק הזב הוא אב הטומא' ויטמא אדם לטמא בגדים שעליו וראוי שנדע שכן הדין בכל משקה הזב שהוא מתיחס לרוק כגון כוחו ונועו ומיץ האף כי כל זה דומה לרוק שהוא מתגעל ובכלל הנה הוא מותר נא בלתי מבושל וזה שהוא טמא כזוב עם היותו רחוק טבע זובו כל שכן שיהיה טמא בזבה ונדה כי הוא קרוב יותר מטבע זיבתה שהוא מותר נא בלי מבושל וראוי שנדע כי שכבת זרע הזב הוא יותר ראוי בזאת הטומא' מרוקו וכן הענין במימי רגליו לפי שאי אפשר בהם שיהיו בלא צחצוח זיבה וכן הענין בנד' וכל המרכ' אשר ירכב עליו הזב יטמא כאלו תאמר המרדעת והאוכף ומה שידמה להם והנה אין טומאת' באופן שיטמא' הנוגע בהם לטמא בגדים שעליו שהרי אמר אחר זה וכל הנוגע בכל אשר יהיה תחתיו יטמא עד הערב ולא אמ' שיכבס בגדיו ואמנם יטמא המרכב האדם במשא לטמא בגדים שנאמר והנושא אותם יכבס בגדיו וזהו ההבדל שיש בין משכב ומושב למרכב ר"ל שמשכב ומושב מטמאים האדם במגע לטמא בגדים שעליו בנגעו בו ואולם המרכב יטמא האדם במגע לא לטמא בגדים שעליו וכולם מטמאים האדם במשא לטמא בגדיו ר"ל המשכב והמושב והזב זובו ורוקו ומרכבו שנאמר והנושא אותם יכבס בגדיו והנה אמר זה בלשון רבים אחרי זכרו כל אלו הטמאות להעיר שכלם מטמאים במשא בזה האופן וכבר התבאר שהמשכב והמרכב מטמאים זולתם בג' פנים אם כשיגע בהם או כשישאם או כשישאוהו:
@543 וראוי שתדע שהמשכב יטמא איך שהיה ר"ל אע"פ שהיו שם כלים רבים נאים למשכב זה תחת זה הנה יטמאו כולם יחד שנאמר וכל המשכב וזה יהיה אע"פ שקצ' הדברים הם בלתי מקבלים טומאה כאלו תאמר שהיו המשכבות תחת אבן ושכב עליה וכן הענין במוש' ובמרכב וזה מבואר מלשון התורה בזה ולפי שהמשכב והמרכב והמושב מטמאין מפני שנשאו הזב הוא מבואר שבאי זה אופן שישאוהו יתטמאו וזה יהיה אם כשישכב בהם או כשישב עליהם או כשירכב עליהן או כשיעמד עליהן או כשישען גופו עליהם או כישתלה גופו בהם כי בכל אחד מאלו המינים ישאוהו ולפי שאמר והיושב על הכלי אשר ישב עליו הזב יכבס בגדיו למדנו שבכל הפנים שהמושב מטמא מהזב ההוא מטמא מי שינשא עליו ר"ל יושב או רוכב או שוכב או עומד או נשען או נתלה ואפי' היה המושב המתטמא תחת האבן כי הוא מתטמא מהזב בזה האופן כמו שקדם ולפי שהמושב והמרכב והמשכב המטמאים מן הזב הם מטמאים זולתם באלו הג' פנים ר"ל שהם מטמאין אם כשיגע בהם או כשישאם או כשישאוהו הוא מבואר שהזב יותר ראוי שיטמא בכל אלו הפנים וכבר בארה התורה במה שקדם שהזב מטמא במגע ובמשא ולא בארה עדין אם הזב מטמא מה שישאוהו אבל בארה זה במה שאמרה וכל אשר יגע בו הזב וידיו לא שטף במים וכבס בגדיו וזה שאי אפשר שהרצון בזה לבאר שהוא מטמא במגע לטמא בגדים שכבר באר זה במה שקדם במה שאמר והנוגע בשר הזב וגו'. ולזה יהיה הרצון באמרו וכל אשר יגע בו הזב שישאוהו שזאת החלוקה נשארה התורה לבאר מענין הזב והנה הוציאו בלשון נגיעה לבאר שכמו שלא יטמא במגע אלא בנגלה בגופו כן לא יטמא מה שישאהו אם לא נשאהו בנגלה מגופו ולזה זכר בזה המקום ידיו שהם בנגלה מגופו לבאר שלא יטמא חוב מנשיאותו הדברים כי אם בנגלה מגופו והוא מבואר שכבר תתכן לשון נגיעה בשיאה כי כל נשיאה בנגיעה אם באמצעי אם בזולת אמצעי והנה הרצון באמרו וידיו לא שטף במים שלא רחץ בשרו ואמנם אמר זה בלשון נקיה כי הטבילה לא תהיה לידיו לבד אבל לכלל גופו וזכר ידיו כי בהם תהיה הנגיעה הנהוגה לשאת הדברים ועוד שכבר זכר ידיו לבאר שרחיצת בשרו האמורה בזב ובדומה לו לא תחוייב שתהיה אלא שעל כל פנים ראוי שיהיה כל בשר ראוי לביאת המים שלא יהיה שם דבר חוצץ וראוי שתדע שכל מקום שנאמר ורחץ במים לא יחוייב שיהיו חיים כמו מי מעין אבל יספיק שיהיו מי מקוה אלא אם בארה התורה שתהיה הטבילה במים חיים כמו שזכרה זה בזב ובהזאה מצורע במי חטאת ולפי שהרחיצה יחוייב שתהיה לכל חלקי האדם יחד כי אי אפשר שיטהר לחצאין ר"ל כי כשהיה קצתתו טמא הנה כלו טמא ולזה כאשר חלק ממנו בטומאה יטמא כלו הנה יחויב שיהי' המקוה מן המים מה שיתכן שיטבול האדם בהם יחד ושערו חכמים שזה ישלם מ' סאה:
@547 **וכל כלי חרס אשר יגע בו הזב ישבר.** ראוי שיתב' מזה שאין הרצון בזה מגע כי לא חלקה בזה התור' בין תוכו לאחוריו והוא מבואר שאין כלי חרס מקב' טמא' אלא מתוכו אפילו בטמאת מת שהיא היותר חמורה שבטמאות ולזה מציל בו צמיד פתיל כמו שיתבאר בפ' פרה ולזה הוא מבוא' שאין הרצון בזה מגע שלא יטמא בו הכלי חרס וכן אם נגע בו מאחוריו ואם אמר אומר שהרצון בזה שיגע בתוכו ויהיה מה שאמר אשר יגע בו בטעם אמרו וכלי חרס אשר תבושל בו שהרצון בו בתוכו אמרנו לו הוא בלתי צודק וזה שבר אמר וכלי כלי עץ ישטף במים למדנו מזה שבמגע אשר יהיה בעבורו הכלי עץ טעון טבילה יהיה הכלי חרס טעון טבילה לפי שהכלי עץ מתטמא אפילו מאחוריו כמו שקד' הנה יהיה הכלי חדש מתטמא מאחוריו בנגיע' וזה שקר לפי מה שהתבא' ולזה הוא מבואר שהרצון בזה המגע נשיאה ולמדנו שאפילו הכלי חרס המקוף צמיד פתיל יתטמא כשישאהו הזב באי זה אופ' שיהיה מהנשיאה שתהיה בנגלה מגופו כמו שקדם והוא מבואר שהנשיאה תהיה באמצעות דברים בלתי מקבלין טומאה כאלו תאמר שנשא הכלי על אבן כי כבר נשאהו אף על פי שנשאהו באמצעות וזה כולל לכל מה שזכר בו משא מהטמאות וכן תהיה הנשיאה אם הסיט הכלי באמצעות קורה או מאזנים כאלו תאמר ששם ידו או רגלו בכף מאזנים והגביה בזה האופן הכף השני והיה בו כלי מהכלים וראוי שתדע שכל אלו הטמאו' ינהגו גם במצורע כי טמאתו יותר חמורה מטמאת הזב ולזה ראוי שנלמוד אלו הטמאות מהזוב רוצה לומר טמאת משכב ומרכב ומושב ויתר הטמאות הנזכרות בזב:
@548 **וכי יטהר הזב מזובו וספר לו שבעת ימים לטהרתו.** ר"ל שיספר לו ז' ימים יהיה טהור בהם מזובו. ולפי שאמר לטהרתו למדנו שראוי שיהיה טהור בכל אחד מאילו השבע' ימים ולזה אם יראה קרי ביום אחד מהם אינו עולה מהמנין ולפי שמצאנו בזבה שלא תכנס בגדר הבא' הקרבנות כי אם בשלשה ימים תראה בכל אחד מהם זיבה כמו שיתבאר מאמרו ואשה כי יזוב זוב דמה ימים רבים והנה תלה הענין בזב בראיות לא בימים והוא מבואר שלא יכנס הזב בזה הגדר כי אם בג' ראיות או בראיה שיעורה כג' ראיות או ב' ראיות שיעורן כשיעור ג' ראיות כשיהיה שעור הא' כשיעור ב' ראיות וזה יתבאר עוד ממה שאמר בסוף זאת הפרשה זאת תורה הזב ואשר תצא ממנו שכבת זרע לטמאה והדוה בנדתה והזב את זובו לזכר או לנקבה הנה ביאר שבזב שתי תורות הא' לטמאה והוא מה שזכ' תחלה והאחרת לזב שוה דינו לדין הזבה הנקבה ואמר בו בזב את זובו ולא אמר לזב לבד כמו שאמר תחלה להורות כי זה הזב השני יהיה לו זוב אחר היותו זב והוא יהיה מתואר כשהוא זב בב' ראיות כמו שביארנו ואז יהיה טמא אלא שלא ישוה דינו לדין הנקבה שיתחייב קרבן כי אם בשלשה ראיות וראוי שנדע כי הרחיצה במים חיים וספירת ז' ימים לטהרתו נוהג בכל זב אבל הבאת הקרבנות לא תהיה כי אם בזב בעל שלשה ראיות כי בזה ג"כ ישוה דינו לדין הנקבה וזה כי מפני שהנקבה לא תרחץ במים חיים אחר ספירת הז' ימים כמו הענין בזב הנה לא ימצא בזה הדין שוה לזכר ולנקבה מהתחל' הספירה ואילך אלא בקרבנות לבד ולפי שכלל זוב הזכר והנקבה יחד ומצאנו בראיות נקבה שאם הפסיק יום שלם בין הראיות שאין הראיות מצטרפות הנה התבאר בזוב הזכר שאם הפסיק יום שלם בין הראיות שאין הראיות מצטרפות:
@548 **וכבס בגדיו ורחץ בשרו במים חיים וטהר.** ר"ל אחר שעמד שבעת ימים בלא ראיית זוב והנה תהיה טבילתו במי מעין ולא במי מקוה וכבר בארנו הסבה בזה בפרש' שמיני ולפי שהטבילה לא תשל' טהרתה כי אם אחר הערב השמש הנה יטבול ביום הז' מבעוד יום כדי שיבא השמש אחר הטבילה קודם הגיעו ליום השמיני קודם שיביא קרבנות ועוד שהרי מצאנו בשאר טומאת ערב שיטבול מבעוד יום ואם לא יטהר מטמאתו אלא אחר הערב שמש כן ראוי שנשפט בזאת הטבילה:
@549 **וביום השמיני יקח לו שתי תורים או שני בני יונה.** לא תור ובן יונה לא בן יונה ותור:
@549 **ובא לפני יי' אל פתח אהל מועד.** ר"ל חוץ לעזרת ישראל אצל שער המזרחי כי לא יתכן לו להכנס בעזר' עד הביאו חטאתו ואמנם העולה אינה מעכבת את הכפר' ולא הכפרה מעכבת את העולה כמו שהתבאר בזה שקדם וראוי שתדע כי הקרבן הבא על כמו אלו הטמאו' יוכל להביאו אחר על המטהר מטומאתו שלא מדעתו וזה כי אלו הקרבנות ינהגו אפילו בקטן אם קרה לו הצרעת או הזוב ויביא אביו אלו הקרבנו עליו להאכילו קדשים ואם הענין כן בקטן שאין לו דעת מעצמו ואין ראוי לקרב מצד עצמו כלל לפי שאין לו דעת כ"ש שיהיה זה הענין כן בגדול:
@551 **ואיש כי תצא ממנו שכבת זרע.** ראוי שתדע שאין זה נוהג אלא בגדול שנא' ואיש כי תצא ממנו שכבת זרע ר"ל שיהיה דרכו שתצא ממנו שכבת זרע וסבת זה כי הקטן לא יתכן שתצא ממנו שכבת זרע לפי שמזונו יכלה בגדול גופו ולא יתכן שישאר שם מותר מצומק ומבושל יהיה ממנו זרע והנה לא חלקה התורה בשכבת זרע איך שיצאו בו אע"פ שיצא לסבה מחוץ הנה יטמא וענין השכבת זרע ידוע שהוא לבן נקשר כלובן בצח הבלתי מוזרת ואם לא היה בזה האופן הנה אינו שכבת זרע והנה יקרא גדול לזה העניין מי שדרכו שתצא ממנו שכבת זרע כמו שקדם וכבר התבאר מן החוש שה יתכן כבן תשע שנים ויום אחד:
@551 **ורחץ במים את כל בשרו.** ר"ל כל בשרו הנראה כמו שהתבא' במה שקדם ולפי שאמר במים ולא אמר במים חיים הנה יתבאר שזאת הטבילה תכשר אפילו במי מקוה:
@552 **וכל בגד וכל עור אשר יהיה עליו שכבת זרע וכבס במים וטמא עד הערב.** ראוי שתדע שכן הדין בשאר הכלים כי השכבת זרע אב הטמא' ויטמא הכלים ואולם זכרה התורה אלו הכלים כי הם אשר יתכן יותר שתמצא בהם שכבת זרע להתאותם למשכב ורכות':
@553 **ואשה כי ישכב איש אות' שכבת זרע.** הנה מבואר מצד הלשון שזה הדי' יהיה כשהיה הוא והיא ראויים לשכיבה והיתה שכיבתם באופן עושה פרי להולדה כי השכיבה היא שכב' זרע לא אם בא עליה שלא כדרכה ולא הוציא זרע והנה יתבאר מן החוש שהיא ראויה לבעילה מעת היותר בת ג' שנים ויום אחד כי אז היא ראויה לביאה והזכר יהיה ראויה לביאה מעת היותו בן ט' שנים ויום א' ואמנם ימצא המותר הזרעי באשה קודם המצאו באיש לפי שאינו צריך אל שלמות הבשול שיצרך אליו בזכר והנה זה צריך ביאור יותר רחב. וראוי שתדע כי הטמאות לא יטמאו כשיגעו בבית הסתרים כמו שבארנו במה שקדם ויתבאר גם כן מזה המקום וזה שאם היה אבות הטומאה מטמאין על זה האופן לא הוצרכה התורה להזכיר זאת הטמאה בבועל ובנבעלת כי כל אחד מהם נוגע בשכבת זרע אם בית הסתרים אם בנגלה מבשרו גם לא תטהר הנבעלת בערב אלא אם פלטה השכבת זרע קודם הטבילה כי היא עדיין שכבת זרע זה במעיה ולזה הוא מבואר מזה המקום שהטמאות אינם מטמאות בבית הסתרים:
@553 **ורחצו במים וגו'.** ר"ל פנים שנטמאו בזאת הביאה וראוי שתדע שאם פלטה האשה השכבת זרע ועדין לא נפסד בגופה לא ירד מגדר השכבת זרע הנה תטמא משום וגעת שכב' זרע כי היא נגעתהו בצאתו בנגלה מבשרה והנה אין השכבת זרע מטמא במשא כי לא נשכרה בו טומאה במשא:
@554 **ואשה כי תהיה זבה.** ראוי שתדע שזה הדין ינהג אפילו בקטנה שנאמר כי תהיה זבה וכל קטנה ראוי להיו' זבה דם ממקורה להדחו' שם הדם שהוא בלתי מבושל כי הנאות ימצא הרבה במזון הקטנים ללקיחתם מן המזון יותר מן הראוי:
@554 **דם יהיה זובה בבשרה.** ר"ל שאין הלבן מטמא בה אבל האדום כשיצא ממקורה שנאמר בבשרה ולפי שלא אמר מבשרה כמו שאמר בזב למדנו אע"פ שעדין בשרה שלא יצא חוץ מהרחם כיון שזב מהמקור אצל הפרוזדור הנה האש' טמאה ולמדנו גם כן שאע"פ שזב מן המקור באונס הנה היא טמאה כי לא התנה שתהי' ההתחלה בזאת הזיבה מבשר' כמו שהתנה זה בזב:
@554 **שבעת ימים תהיה בנדתה.** ר"ל שהיא קרויה נדה כל ז' ימים אע"פ שלא ראתה דם אלא ביום הא' וכן אם ראתה בכלם תטהר אחר שיכלו ז' ימים אחר שתטבול במים. והנה לא זכרה התורה שיהיה דם הנדה טמא לפי שזה מבואר מעצם הענין וזה שכבר תמצא טומאתה במדרגת טמאת הזב לטמא משכב ומושב ומרכב ולזה ראוי שיהיה משקיה מטמאין כמו הענין בזב וכ"ש דם נדותה כי היא היה סבת טמאתה בצאתו מהרחם ובכלל הנה יתבאר ממה שזכרנו בסוף פרשת שמיני ששרש זאת הטמאה הוא בדם הנדה בעצמו מפני שנעדר ממנו התועלת אשר בעבורו ימשך אל החם והוא ההולדה וראוי שתדע שלא תטבול מבעוד יום ביום השביעי בנדתה מפני שהיום ההוא הוא מימי נדתה ואולי תראה ביום ההוא ותצטרך לחזור ולטבול אחר ששקעה חמה ואולם הזב יתכן שיטבול מבעוד יום כי הוא בחזקת ההנקות מהטמאה ואולי לא יראה וישלם לו ההנקות:
@554 **וכל הנוגע בה יטמא עד הערב.** רוצה לומ' אדם או כלים והוא מבואר שהאדם הנוגע בה יטמא לטמא בגדים שעליו בעת הנגיעה וזה אפילו מושבה מטמא האדם במגע לטמא בגדים כ"ש היא בעצמה:
@555 **וכל אשר תשכב עליו בנדתה יטמא.** רוצה לומר שיהיה הכלי ההוא ראוי שתשב בו וזה מבואר מהשרשים הכוללים עם שכבר נתבאר זב בזב אשר אין ראוי שתהיה טמאתו למטה מטמאת הנדה כמו שנתבאר מדברינו בסוף פרשת שמיני והנה התבאר במה שקדם שטמאה משכב ומושב תהיה כאשר ינשא עליהם הטמא באי זה דרך שיחיה מהדרכים שזכרנו בפרשת זב:
@556 **וכל הנוגע במשכבה יכבס בגדיו ורחץ במים וטמ' עד הערב.** למדנו שמשכבה מטמא האדם במגע לטמא בגדים וכן למדנו מזה הענין במושבה בפסוק הבא אחר זה אם על המשכב הוא או על הכלי אשר היא יושבת עליו בנגעו בו יטמא עד הערב ראוי שתדע שאין הרצון בה שכאשר ינשא האדם על המשכב והמושב שיהיה טמא שאם היה הענין כן לא היה ראוי שיאמר בנגעו בו ועוד שאם היה הענין כן הנה ראוי שיטמא לטמ' בגדים שעליו כמו שהתבאר בפרשת זב שאין מגע המשכב והמושב יות' חמור מהנשא עליהם וכבר אמר בכאן יטמא ולא אמר שיהיה טעון כבוס בגדים ולזה הוא מבואר ממה שנזכר בפרשת זב שמה שהעיר עליו בזה הכתוב הוא המרכב שהוא מטמא לטמא בגדים והנ קראו באש' משכב ומושב כי אין ראוי להזכיר המרכב באש' לפי שיש לו פסוק הרגלים אשר הוא כלי לדבר הערוה אמר ותפסקי רגליך לכל עובר והוא מבואר שהמרכב מתיח' מאד למושב וכ"ש מרכב הנשים והנה שתקה התורה מלהזכיר טמאות הנושא ודם הנדה ומשכב' ומושב' ומרכב' ומשקיה להשענה על מה שזכרה מזה הענין בזב וכן הענין במה שתשאהו או תסיטהו הנדה מהכלי' אבל התורה קצרה בזה במשפטה כי כבר זכרה בזה במה שיספיק ללמד ממנו כי דין טמאת הנדה והזב לטמא זולתה הוא אחד בעינו:
@559 **ואם שכב ישכב איש אותה ותהי נדתה עליו וטמא שבעת ימים.** ר"ל שכבר יהיההדין טמא' נדתה עליו להיות טמא ז' ימים מעת שכיבתו עמה והנה ראוי שיהיה הוא ראוי למשכב והיא גם כן ואז ינהג בהם זה הדין זה מבואר מהשרשים הכוללים ולפי שלא אמר שכבת זרע כמו שאמר בפרש' הקודמת הוא מבואר שאע"פ שלא הוציא שכבת זרע יטמא בזה האופן וזה בין ששכב עמה כדרכה או שלא כדרכה או כי כל אחד קרוי משכב כמו שיתבא' מאמרו ואת זכר לא תשכב משכבי אשה:
@559 **וכל המשכב אשר ישכב עליו יטמא.** ראוי שתדע שכן יהיה הדין במושבו ובמרכבו כאשר ינשא עליהם בועל נדה אלא שאין משכבו ומרכבו מטמאים אדם וכלי' במגע ובמשא כי התורה לא זכרה זה כן כמו שזכרה אותו בזב ובנדה ויתבאר מהשרשים הכוללים כי מזאת הטמאה החמורה הם משללים לא מהטמאה אשר למטה ממנה והוא לטמא אוכלין ומקין ועוד שזה ראוי בהם כי הם ולד הטמאה וזה שהתבאר שהראשון לטמאה מטמא אוכלים ומשקין:
@560 **ואשה כי יזוב זוב דמה ימים רבים.** הנה מפני אמרו ימים יחוייב שיהיו שני ימים לכל הפחות הנה הפחות שיאמר בו ימים רבים הוא שלשה ימים. ולזה לא ינהג הדין שזכר אחר זה בהבאת הקרבנות כי אם בזבה שראתה שלשה ימים זה אחר זה:
@560 **בלא עת נדתה.** ר"ל שלא היה זה בשעת הימים אשר בהם נדה כי כבר התבאר דין הראיה שתהיה בעת נדתה אבל זאת הזיבה תהיה במה שישאר מימי וסתה אחר זמן נדותה כשישפע מהדם בה יותר מהנהוג לפי העניין הטבעי וזה התוספת יקרא זיבה והנה קרא בלא עת נדתה כשלא היה הזיבה נמשכת לשבעת ימי הנדה אך היה שם הפסק יום אחד או יותר ולזה אמר אחר זה כי תזוב על נדתה ר"ל שלא היה הפסק בין ימי הנדה לימי הזיבה:
@560 **כל ימי זוב טמאתה כימי נדתה תהיה טמאה היא.** למדנו מזה שטמאתה בימי זונה אע"פ שלא ראתה שלשה ימים היא כטמאת הנדה באותן הימים ולזה תטהר בערב כשטבלה כמו שתטהר הנדה כשטבלה ביום השביעי ואע"פ שראתה בו דם אלא שראוי שתשמר מזה כי אולי תראה למחרת היום ההוא ותהי' טמאה למפרע עד שאפשר שתבא לכלל זבה גדולה ויצטרכו לה שבע' ימים נקיים מזוב קודם שתטהר כמו שיתבאר:
@561 **כל המשכב אשר תשכב עליו כל ימי זובה כמשפט נדתה יהיה לה.** וכל כלי אשר תשב עליו טמא יהיה כטמאת נדתה. למדנו מזה המקום שהמשכב ומושב טמא בנדה הוא כשהיה מיוחד למשכב ומושב והזבה היא מטמא' משכב ומושב ומרכב כמו הנדה וכן הענין ביתר הטמאות:
@562 **כל הנוגע בה יטמא וכבס בגדיו ורחץ במים וטמא עד הערב.** באר דין נגיעת המשכב והמושב ושתקה מזכירת טמא' נשיאות שלהם או הנשאם להשענ' שזה יתבאר מה שזכרה מזה:
@563 **ואם טהרה מזיבה וספרה לה שבעת ימים ואחר תטהר.** ר"ל שלא תטהר עד שיעברו עליה שבעת ימים תמצא בהם טהורה מזובה ולזה אם ראתה דם בסבת דבר לא יתכן שיקרא זוב כאלו תאמר שתהיה מקשה לילד ותראה דם מחמת קושי ההוא הנה לא תסתר הראייה ההיא מה שעבר מהשבעה ימים הנקיים מזוב. ואמרו ואחר תטהר ר"ל שתטבול במים כמשפט הטמאים והנה תביא אחר זה קרבנות שלה להשלים הטהרה למקדש וקדשיו כמו הענין בזב ויולדת:
@563 וראוי שיתבאר מזה המקום שימי הנד' הם קודמים לימי זיבה שנאמר או כי תזוב על נדתה ויתבאר שהמעט שיהיו ימי הזיבה הם י"א יום וזה כי ימים רבים יהיה על המעט שלשה ימים ושבעה ימים שתמנה אחר זה תטהר בהם מזובה הנה אם כן הם ראוים לזיבה כי מה שתראה בהם יהיה זיבה וההפסק המועט שיהיה בין ימי הנדות לימי הזיבה שרמז עליה באמרו בלא עת נדתה הוא יום אחד ולזה יתבאר שימי זיבה הם על המעט אחד עשר יום אחר ימי נדה והיה זה כן לפי שאי אפשר שתקבע האשה וסת לנדתה בפחות מי"ח יום בין וסת לסת והנה מי שימצא על הרוב בין וסת לוסת הוא חדש יום ולזה הנה כשתראה תחלה תהיה נדה ז' ימים ומה שתראה תוך י"א ימים הבאים אחריהם היא זיבה בהכרח כי אי אפשר שיהיה בין וסת לוסת פחות מי"ח יום ואולם מה שתראה אחר הי"א יום אולי הוא וסת נדתה כיון שלא קבעה לה וסת עדין ואולם אם קבעה לה וסת הנה יהיה כל מה שתרא' אחר ימי הנדה זבה ולזה אמרה התורה בלא עת נדתה שכל מה שתראה בזולת העת שקבעה לנדתה הוא זיבה תדע שכן הוא שהרי אמרה תורה ואשה כי תזוב זוב דמה ימים רבים למדנו מזה שאפילו היה מספר הימים אלו אלף יום הנה הם ימי זיבה ולזה תמצ' שאמרו רז"ל שהרואה עשרה ימים טמא ועשרה ימים טהור הנה יהיה ימי שמושה כימי זיבתה וכן למאה וכן לאלף למדנו מזה שאף ראתה אלף ימים זה אחר זה שכלם ידי זבה לבד השבעה הראשונים שהם ימי נדה והנה תמנה מהימים הטהורים שבעה לטהרה מזיבה והשאר תוכל לשמש בהם והם במספר ימי זיבתה ולזה אמר שהרואה ז' ימים טמא וז' ימים טהור משמשת רביע ימיה. וזה שהשבעה הראשונים הם ימי נדה ותטהר בסופם ותשתמש השבעה הטהורים והשבעה ימים הבאים אחריהם תהיה זבה גדולה ותטהר מזובה בז' ימים הטהורים ולא תשמש כלל ואחר ישובו ימי נדה ויחזור בה בסבות בזה האון הנה תשמש שבוע אחת בכל כ"ח ימים ויהיה בין וסת לוסת כ"ח יום ואם ראתה ז' ימים טמאים ושמנה ימים טהורים משמשת ט"ו יום מתוך מ"ח וזה שהיא תהיה זבה קטנה בעד היום הנוסף ותצטרך לשמור יום אחריו שמא תראה וישארו לה ז' ימים טהורים ולא ישאירו מהי"ח יום כי אם ב' ימים תהיה בהם זבה קטנה והראיה הבאה אחריהן אולי היא וסת נדות כי כבר עברו הי"ח יום ולא הגיע יעדין לגדר הזבה גדול' ולזה תמצא ו' טמאים ויום טוהר להשלים הז' וישארו לה ז' ימים טהורים לשמש עם בעלה ואחר זה יכנסו ארבעה ימים מהשמנה הטמאים תוך ימי זיבה ותהיה זבה גדולה ולזה יהיו כל השמנה הטמאים ימי זיבה ותמנה אחריהם שבעה נקיים וישאר לה יום אחד ואחר זה ישובו ימי נדה בזה האופן וילך זה בסבות והנה לרב המורה בזה דרך אחרת ואינו מסכים ללשון הלכה אשר בנדה בזה לא במה שאמרו משמשת רביע ימיה כי לא תשמש לפי דעתו כי אם שביעית ימיה ולא במה שאמרו ט"ו יום בכל מ"ח וזה כי לפי שרשיו לא תשמש במ"ח יום השניים כי אם שלשת ימים וזה שהוא ימים הראשונים מהשמנה ימים הטמאים הם ימי זיבה לפי שרשי הרב ותהיה בהם זבה גדולה ולזה יתבאר שלא תשמש בח' ימים הטהורים כי אם היום אחרון מהם ואחריהם יהיו הח' ימים הטמאים כלם ימי זבה ולא תשמש בימים הטהורים הבאים אחריהם כי אם ביום אחד וכן לא תשמש במ"ח יום השלישיים כי אם ג' ימים הנה אם כן לא תשמש באלו המ"ח ימים השלישיים כי אם שלשה ימים ואחריהם גם כן יהיו כל הח' ימים הטמאים ימי זיבה ולא תשמש בימי' הטהורים הבאים אחריהם כי אם ביום אחד בלבד וזה כי מהשמנה ימים הטמאים הראשונים יהיו השבעה ימים האחרונים ימי זיבה תהיה בהם זבה גדולה ולא תשמש בימים הטהורים הבאים אחריהם כי אם יום אחד מהם. ואחריהם יהיו השלשה ימים האחרונים משמונה ימים הטמאים ימי זיבה תהיה בהם זבה גדולה ולא תשמש בימים הטהורים הבאים אחריהם כי אם ביום אחד מהם ולזה יתבאר כי דעת רז"ל הוא לפי מה שהושרשנו והוא הנראה מלשון התורה ולולי כי יארכו הדברים יותר מן הראוי היינו מבארים דעתנו בזה ממקומות רבים מדברי רז"ל בזה המתירים במה שאפשר שיסופק על זאת ההנחה אלא שזה יותר ראוי שיהיה בחבורינו התלמודיים. והנה הזבה הקטנה לא יחוייב בה שתהיינה הראייות שתראה אחר זה אחר הי"ח יום מהזיבה כי התורה לא תראה שיקרא זוב בה רק ימי טמאת אבל בזבה גדולה התבאר מהתורה שכל הנמשך לראייתה הוא זוב ואע"פ שתראה אותו באחד מהז' ימים לטהרתה מזובה והנה בזה האופן יתבאר לך מה שאמרו שדמי האשה מעטים בימי זובה ולזה היא בחזק' טהורה אע"פ שלא בדקה עצמה כל זמן שלא ראתה טמא והוא מבואר שכל מה שרחקה האשה מוסתה יהיו דמיה יותר מעטים ולזה היא מהשקר שנאמר במי שקבעה לה וסת מארבעים ים לארבעים יום דרך משל שאחר עבור שבעה ימים יהיו דמיה מועטין וישובו להיות דמיה מרובין אחר עבור י"ח יום אבל מן הראוי שיהיו יותר מועטין ולזה לא תצטרך לבדוק אלא סמוך לוסתה לא בז' ימים הבאים אחר י"ח יום מימי וסתה ולזה לא יהיו ימי נדה אלא כשלא היה לה וסת קבוע שהוא נשפט שזה וסת שני וכבר הארכנו בזה יותר מן הראוי ולפי שלא אמר בזה וספרה לה שבעת ימים לטהרתה כמו שאמר זה בזב למדנו שאלו השבעה ימים אע"פ שלא תהיה בהם טהורה כיון שהיא בהם טהורה מזב שלה הנה אינם סותרת בזה הימים הנקיים וזה יהיה כשתראה דם קושי בהם שהיא טמאה או כשיהיו קצם ימי נדה שאינה רואה בהם ואולם בזב אמר שיטהר בהם מזובו ושיהיו עם זה לטהרתו ולזה אם ראה קרי באלו הז' אע"פ שהם טהורים מזובו הנה אינם לטהרתו וסותר יום ראיי' הקרי כי הלכה טמאתו ביומו והזהרתם את בני ישראל מטמאתם ולא ימותו בטמאם את משכני אשר בתוכם. למדנו מזה שאין ישראל מוזהרים על הטמאה רוצה לומר שלא יטמאו באלו הטמאות אבל ראוי שישמרו מהכנס למקדש בהיותם טמאים כדי שלא ימות ולזאת הסבה ראוי שידקדקו בהם הענין הטמאו' כדי שיתבאר להם מתי הם טמאים כדי שלא יכנסו למקדש בהיום טמאים ולזאת הסבה ראוי שידקדקו בה יותר בעלותם לרגל כי אז היה מדרכם לראות את פני יי':
@567 **זאת תורת הזב ואשר תצא ממנו שכבת זרע לטמאה בה.** לפי שחזר להזכיר אחר זה תורת הזב ואת זובו למדנו כי לזב ב' תורות וזה הזב בעל שתי ראיות הוא טמא ואינו מביא קרבן ולזה אמר לטמאה בה והזב את זובו הוא בעל שלש ראיות והוא יתחייב בקרבן כמו שבארנו במה שקדם:
@568 **והדוה בנדתה והזב את זובו לזכר ולנקבה.** ר"ל החולה בנדתה והוא בעת וסתה כי אז תרגיש שראשה ואיבריה יהיו כבדין עליה והזב את זובו לזכר ולנקבה למדנו מזה שהם טמאים בזוב אע"פ שהם קטנים כי אמרנו זכר ונקבה יכלול הקטנים והגדולים ולמדנו שהזב בעל שלש ראיות יסכים לזבה גדולה בהבאת הקרבנות כמו שבארנו:
@568 **ולאיש אשר ישכב עם טמאה.** לפי שאמר עם טמאה ולא אמר עם נדה למדנו שעם איזו טמאה שישכב מהטמאות הדומות לנדה כגון יולדת וזבה גדולה או קטנה הנה יהיה הבועל טמא באופן שנזכר בבועלי נדה ובכאן נשלם הביאור בזאת הפרשה:
@587 **אחרי מות שני בני אהרן בקרבתם לפני יי' וימותו.** ר"ל בקרבתם לפני יי' להקטיר הקטרת ויהיה עניינו כטעם בגשתם אל המזבח או יהיה זה חטא שני לבני אהרן רוצה לומר שבאו לפני לפנים ובעבור כן סמך לזה הספור אמרו דבר אל אהרן אחיך ואל יבא בכל עת אל הקדש והביאור הראשון הוא יותר נכון לפי מה שאחשוב ואמנם סמך לזה הספור זאת האזהרה לבאר שהדברים שהעונש עליהם מיתה בידי שמים אין ראוי להקל בהם כי השם יתע' יקח נקמתו מהאיש העובר עליהם כמו שלקחה מבני אהן ולזה ראוי שייראו מאד מעבור על כל אלו האזהרות והנה לא בארה התורה מה היה זה הדבור ואפשר שיהיה הדבור ההוא הוא הדבור הנזכר אחר זה במה שאמר ויאמר יי' אל משה דבר אל אהרן אחיך ויהיה כפול המאמר בזה בטעם אמרו תחלת דבר יי' בהושע ויאמר יי' אל הושע ואפשר שרמז בזה המקום אל הדבור הנזכר בפרשת שמיני שהיה אחרי מות שני בני אהרן והם האזהרות שנזכרות שם שנתחייבו עליהם הכהנים מיתה בידי שמים והנה זה הענין שזכר בזה המקום מעבודת יום הכיפורים היה אז ואמנם הפסיקה התורה בין שני אל המאמרים וזכרה ענין המאכלות אסורות והמותרות והטמאות והטהרות כי עבודת יום הכיפורים היתה מכוונת לנקות הטמאות כמו שיתבאר ולזה זכר' אותם התורה קודם שתזכיר זאת הפרשה והנה נזכרו המאכלות קודם הטמאות לפי שענינם מתיחס כמו שהתבאר מדברינו במה שקדם:
@588 **ואל יבא בכל עת אל הקדש מבית לפרכת.** רוצה לומר בבית קדשי הקדשים:
@588 **אל פני הכפרת אשר על הארון ולא ימות.** באר שאם יבא שם בזולת זה האופן שזכר בזאת הפרשה אפילו ביום הכיפורים שצוהל הכנס שם יתחייב מיתה שנאמר בזאת יבא אהרן אל הקדש רוצה לומר בזה האופן לא בזולתו ולא בזולתי היום הזה מהשנה והוא העשירי לחדש שביעי כמו שנזכר בזאת הפרשה וראוי שתדע כי בבית שני לא היה שם ארון כי כבר גנזו יאשיהו ועם כל זה היה שם קדש הקדשים והיה שם צורת כרובים להורות על מציאות הצורות הנבדלות אשר בעבורו היה קדש הקדשי' אף על פי שאין שם ארון וכפרת ולהעיר על שאין ארון וכפרת מעכבים זאת העבוד אמר אחר זה בזאת יבא אהרן אל הקדש:
@588 **כי בענן אראה על הכפרת.** רוצה לזמר שכבודי נראה משם בענן וממנו מגעת הנבואה כמו שאמר ונועדתי לך וגומר. ולזה ראוי לתת מעלה וכבוד לזה המקום הנכבד שמעיר על אופן הגעת הנבואה ועל מציאות הצורות הנבדלות ולזה היה נראה שם על צד המופת בעת הגעת הנבואה למשה ענן להעיר כי שם מה שיעיר על הנמצא אשר ישפיע הנבואה שהאדם לא יכול להשיגו השגה שלמה כמו שלא יושג בשלמות המוחש לחוש הראות כשהיה ענן בין החוש והמוחש ולהיות העניין כן הנה אין ראוי שיתמידו להכנס בזה המקום הנכבד כי זה מה שיפחית מעלתו בנפש ויהיה זה סבה אל שתעלם הכונה שכונה התורה בענינו:
@589 **בזאת יבא אהרן אל הקדש וגומר.** ראוי שתדע שזה יהיה אחר הקריבו תמיד של שחר עם שאר העבודות הנעשות אז כמו הקטרת הקטרת והטבת הנרות כי כבר התבאר שאין קרבן קרב קודם תמיד של שחר והנה יתבאר אחר זה איך יקריב אלו הקרבנות:
@590 **כתנת בד קדש ילבש וגומר.** למדנו מזה שהוא משמש בעבודות המתיחסות לכפרת היום בבגדי לבן והם של פשתן ולא יחוייב בחוטן שיהיה כפול ששה שנאמר בד ולא ישמש אלא בד' בגדים והנה העבודות המיוחסות לכפרת היום הם חטאתו וחטאת העם ושעיר המשתלח הנזכרים בזאת הפרשה והכנסת הקטרת לפני לפנים כי כל זה נזכר בזאת הפרשה אחרי זכירתו אלו הבגדים להורות שכל אלו העבודות בבגדי לבן הם נעשות ואולם עולתו ועולת העם והקטרת אמורי פר ושעיר הנשרפין היה בבגדי זהב רוצה לומר בשמנה בגדים אשר לכהן גדול אף על פי שיחשב היותו מיוחד לכפרת היום וזה שכבר אמרה התורה זה בביאור בזאת הפרשה שנאמר ורחץ את בשרו במים במקום קדוש ולבש את בגדיו ויצא ועשה את עולתו ואת עולת העם וגו'. ואת חלב החטאת יקטיר המזבחה. והיה זה כן כי שלמות הכפרה היא בחטאת כמו שהתבאר במה שקדם וכיון שנזרק דמו שלמה הכפרה ולזה לא תהיה הקטרת האמורי' של פר ושעיר מהעבודו' המיוחדו' לכפר' חיו' ולא עשיית עולתו ואת עולת העם והנה היו אלו העבודות בגדי לבן כי לחזק ההוראה שהיתה בהם על עניני החמר וחסרונו אשר הוא סבת הטומאה והחטאים שיכפר עליהם ביום הזה ראוי שיוסר ממנו זה הכבוד הנפלא שהיה לו בלובשו בגדי זהב וישמש בדמות הבגדים שישמש בהם כהן הדיוט הלא תראה של זאת הסבה נשרף הפר והשעיר חוץ לשלשה מחנו' ויטמא שורפם ושולח השעיר האחד לעזאזל ויטמא משלחו עם שהלובן מורה על הנקיון מהחטאים כאמרו אם יהיו חטאיכם כשנים כשלג ילבינו וזה גם כן ראוי שילבש בגדי לבן בעבודות אשר תהיינה לנקות מהחטאי' והוא מבוא עוד שאינו ראוי שיכנס לפני לפנים בבגדי זהב כי ראוי שיכיר היותו שפל ונבזה ביחס אל השם יתעלה והשכלים הנפרדים אשר מה שבמקום ההוא מעיר על מציאותם וראוי שלא יעלם ממנו שכל העבודות הנעשות ביום ההוא במקדש היו על יד כהן גדול וזה שאתה תמצא בכל הפרשה הזאת שעל יד אהרן תעשינה אלו העבודות המיוחדות לכפרה והבלתי מיוחדות לכפרה והנה בפרשת פינחס זכר בעבודת היום מוסף היום ושעיר חטאת מלבד חטאת הכפורים ומלבד עולת התמיד וזה ממה שיורה שעל ידי מי שיעשה חטאת יום הכפורים תעשה עולת התמיד ומוסף היום ושעיר חטאת השני אלא שלא יהיה בבגדי לבן כי אם מה שזכרנו:
@590 **ורחץ במים את בשרו ולבשם.** מצינו בזה המקום שבלבישתו בגדי הלבן יצטרך טבילה וכן מצינו במה שאחר זה כי בלבישתו בגדי זהב הוא טעון טבילה ומזה המקום נלמד שבכל עת שימיר מבגדי זהב לבגדי לבן או מבגדי לבן לבגדי זהב טעון טבילה. ומזה המקום יתבאר שהוא טעון קדוש ידים ורגלים בין בגדים לבגדים וזה כי גם כן במקומות שלא הצריכה התורה טבילה הצריכה קדוש ידים ורגלים כל שכן שיצטרך במקום שהוצרך לטבילה ואחשוב שהוצרכו אלו הטבילות הנוספות בזה היום להורות על חוזק ההנקות מאלו הדברים החמריים שהם סבת הטמאות והעברות שיכופר עליהם ביום הכפורים ולפי שהכפרה הזאת כוללת לכל ישראל חוייב שתהיה על יד הנכבד מהכהנים:
@591 **ומאת עדת בני ישראל יקח וגומר.** הנה זה היה לקוח ממה שהיה מכלל ישראל והם חציי השקלים המוכנים לכל עבודת אהל מעד ומזה המקום נלמד שהפר והאיל שהיה מביא כהן גדול היה משלו לא מכלל הצבור ואלו השני שעירות הם שעיר המשתלח ושעיר הנשרף בחוץ שניהם חטאת כמו שנבאר בזה הפסוק והנה תבא העולה אחריהם להורות שנשלם הרצוי:
@592 **והקריב אהרן את פר החטאת אשר לו וכפר בעדו ובעד ביתו.** ראוי שתדע שזאת הכפרה הוא ודוי דברים שהרי אמר אחר זה בשעיר המשתלח יעמד חי לפני ה' לכפר עליו. וכבר התבאר בזאת הפרשה שזאת הכפרה היא ודוי דברים שנאמר וסמך אהרן את שתי ידיו על ראש השעיר החי והתודה עליו את כל עונות בני ישראל. ומשם יתבאר שהודוי הוא אחר הסמיכה והנה זאת ההקרבה הוא שיביאהו לצפון העזרה ויהיה ראש הקרבן מצד המערב ופני הסומך גם כן לצד המערב ויתודה בעדו ובעד ביתו. וראוי שתדע כי ביתו יאמר על אשתו ויאמר על הכהנים הדיוטים שהם בניו. ולפי שאמר אחר זה וכפר בעדו ובעד ביתו ואמר בסוף הפרשה ועל הכהנים ועל כל עם הקהל יכפר למדנו שההודאה בביתו הנאמר ראשונה נאמר על אשתו וביתו הנאמר שנית מורה על הכהנים ולזה ראוי שיהיה לכהן גדול אשה ואז יתכן לו לעבוד עבודת יום הכיפורים והיה זה כן כדי שיהיה יותר נקי מהרהור מעניני המשגל לפי שיש לו פת בסלו:
@593 **ולקח את שני השעירי' והעמיד אות' לפני יי' פתח אהל מועד.** הנה העמדתם תהיה למזרח העזרה לפאת צפון ופניהם לפאת המערב שנ' לפני י' באופן שאשר יהיה ליי' מהם יקריבהו לפאת מערב לשחוט אותו שם שנאמר אחר זה והקריב אהרן את השעיר אשר עלה עליו הגורל ליי' ועשהו חטאת:
@594 **ונתן אהרן על שני השעירים גורלות גורל אחד ליי' וגורל אחד לעזאזל.** לפי שאמר על שני השעירים את שני השעירים שני שעירי עזים לחטאת וההמנות במספר יהיה ביותר שלם שבפנים באחדים השוים והמסכימים למדנו שראוי שיהיו שוים ושתהיה לקיחתם כאחד עד שיהיו שנים תמיד. וענין הגורלות לפי מה שיורה עליו הגדר הוא שישימו שני גורלות במקום מכוסה ויגיעו הדבר אשר בו הגורלות ויקחו ממנו אחד בזולת שיראוהו וישימיהו על אחד מהדברים אשר יפילו עליו הגורל והשני על השני ולזה ראוי שיהיו הגורלות שוים ומסכימים באופן שלא יוכר במשושם בהם דבר והמשל שאם היה אחד של אבן ואחד של עץ הנה יכיר הגורל איזהו במשושו אותו ויהיה ענינו כאלו לא היה שם גורל וכן הענין אם היו שניהם מדבר אחד נהיה האחד גדול והאחד קטן והנה אלו הגורלות היה כתוב באחד מהם להשם ובשני לעזאזל:
@595 **והקריב אהרן את השעיר אשר עלה עליו הגורל ליי' וגו'.** לפי ששניהם חטאת כמו שקדם הנה ראוי שיאמר הכהן שהוא ליי' חטאת והנה יעשהו חטאת לשם יתע' בזה המאמר רק בתחלת ענינו לא היה מבואר בו אם יהיה לשם יתע' או לעזאזל והנה יניעהו ויקריבהו לצד המערב בעת ההיא להורות שהוא יהיה קרב להשם יתעלה:
@596 **והשעיר אשר עלה עליו הגורל לעזאזל יעמד חי לפני יי' לכפר עליו לשלח אותו לעזאזל המדברה.** הנה זה השעיר אשר לעזאזל היה עומד חי יפניו למערב כדי שיתכפר עליו בהתודותו עליו כמו שיזכור אחר זה ולזה היה עומד שם עד השלימו הזאות דם הפר והשעיר כי אחר זה יתודה עליו ואחר זה ישלח אותו לעזאזל המדברה ולזה היה ראוי שיעמוד במקום אשר משם משתלח והוא אצל מזרח העזרה והנה עזאזל הוא מקום גבוה וקשה והיה במדבר שלא יעבד בו ולא יזרע:
@597 **והקריב אהרן את פר החטאת אשר לו וכפר בעדו ובעד ביתו ושחט את פר החטאת אשר לו.** רוצה לומר שיקריבהו עוד שנית לפאת מערב כדי שיהיה במקום שחיטתו ויסמוך עליו ויתודה בעדו ובעד הכהנים והנה יתבאר לשון זה הודוי והודוי הקודם במה שיבא בזאת הפרשה ותכף לסמיכתו וישחט את פר החטאת אשר לו. וראוי שתדע כי מפני שהיה מחוייב שיהי' הוא בעצמו מקבל הדם בכלי שרת בימין ובה ישחוט הנה לא ישחוט כי אם רוב הסימנין כדי שלא יצא דם הפר מפני זאת השחיטה ולפי שבזה האופן נשלמה השחיטה לפר הנה ישלים כהן אחר לחתך הסימנין והעורקין באופן שיצא הדם ואז יקבל הכהן הגדול הדם בכלי שרת כמשפט ואם יאמר אומר שהוא ראוי שתהיה השחיטה באופן שיצא ממנה הדם לחזות בו ולזה לא יכשר זה אלא בכהן גדול אמרנו לו שזה בלתי אפשר אם לא ישפך הדם ואולי ישפך ממנו באופן שלא ישאר ממנו כדי להזות וגם כן הנה לא חייבה התורה שיהיה על ידי כהן גדול כי אם השחיטה לא חתיכת הורידין ולזה יתכן חתיכתם על ידי כהן אחר ולפי שההזא' לא תהיה כי אם אחר הקטרת הקטורת לפני לפנים הנה יהיה אחד מהכהנים מנדנד הדם במזרק כדי שלא יקרש באופן שיוכל להזות ממנו:
@598 **ולקח מלא המחתה גחלי אש מעל המזבח מלפני יי'.** ר"ל מעל מזבח העולה מהמערכה שהיתה שם מוכנת לזה לצד המערב ולזה היו שם ד' מערכות ביום הכיפורים כמו שבארנו בפרשת צו ומזה המקום יש ללמד שמערכת האש אשר יביאוהו למזבח הקטרת הוא יותר מערבית מהמערכה הגדולה וראוי היה להיות כן כי מה שהוא נכנס לפנים הוא יותר ראוי שיהיה יותר מערבי ויותר מערבי היה מה שהיה נכנס לפני לפנים לזאת הסבה בעינה ולפי שאמר גחלי אש למדנו שלא יביאם שם אלא מעוכלות ולא עוממות אלא לוחשות וראוי שיהיה האש בכלם שנאמ' גחלי אש והיה זה כן כדי שלא יהיה מהם בעצמם עשן אבל יהיה כל העשן מקטרת הסמים וכדי שיעלה בקלות ראוי שיהיו הגחלים לוחשות ולא עוממות:
@598 **ומלא חפניו קטרת סמי' דקה והביא מבית לפרכת.** לפי שהקטרת היתה דקה כמו שאמר ושחקת ממנה הדק. למדנו שמחזיר ממנה למכתשת כדי שתהיה בתכלית הדקות באופן שיוכל לקחת משם מלא חפניו מהקטרת השחוקה שנית ולפי שאמר שיביא מבית לפרכת מלא חפניו עם לקיחתו מלא המחתה שהיא בהכרח בידו הימנית לפי מה שהתבאר מהשרשים הכוללים הנה ימדוד מלא חפניו מקטרת הסמים וישימהו בכף אחד לא בחפניו כי לא יוכל עם זה לשאת המחתה בידו ולזה ישא הכף בשמאלו עד אשר יניח המחתה בקדש הקדשים ואחר ישוב הקטרת לחפניו כמו שצותה התורה ומשם יתנהו על האש וכבר נתן הסבה בזה אחר שישלם ביאור זאת הפרשה:
@598 **והביא מבית לפרכת והביא את דמו אל מבית לפרכת.** רוצה לומר אף על פי שאין שם ארון וכפרת ולזה עשו זה בבית שני שהיו שם כמה נביאים והנה אחשוב שהיה הכפרת בבית שני עם הכרובים כי כבר הקפידה התורה בהזאת דם הפר ושעיר של יום הכיפורים שתהיה על פני הכפורת ולפני הכפרת:
@599 **ונתן את הקטרת על האש לפני יי'.** הנה יתבאר מזה שהוא יניח תחלה המחתה לפני לפנים לפני יי'. ר"ל לפני הארון ואחר כך יתן הקטרת עליה ולפי שהוא ראוי שיהיה הקטרת מלא חפניו כמו שנזכר בפסוק הקודם ומשם יתנהו על האש הנה יקח הכף בשיניו או באי זה צד שיוכל ויוציא משם בגודלו הקטרת עד שישיבה לחפניו ומשם יתן אותה על האש במה שיהיה ממנו לצד המערב שנ' לפני יי':
@599 **וכסה ענן הקטרת את הכפרת אשר על העדות ולא ימות.** למדנו מזה שהוא ראוי שיהיה בקטרת מה שיעלה עשן באופן שיהיה עשן הקטרת מוחש והוא הנקרא מעלה עשן והיה נכנס בסמני הקטרת ואם לא היה זה הסם שם יתחייב מיתה. והוא מבואר שאין ראוי שיכניס שם קטרת זרה. ר"ל שלא תהיה במתכונת קטרת הסמי' שאם הכניסה שם הנה נכנס שלא לצורך עבודה ויתחייב מיתה כמו שקדם והנה ישאר שם הכהן עד שיעלה ענן הקטרת וכסה את הכפרת ואחר כך יצא משם וראוי שיהיו פניו לצד המערב גם בצאתו כי אין ראוי שיהיה אחוריו אל ארוך יי' וזה מבואר בנפשו כל שכן מה שנראה שדקדקה התורה בכל הנעשה שיהיה לפני יי':
@600 **ולקח מדם הפר והזה באצבעו על פני הכפרת קדמה ולפני הכפר' יזה שבע פעמים מן הדם באצבעו.** לפי שהכפרת פנים לצד המזרח ולצד צפון ולצד דרום הנה זכרה התורה שתהיה זאת ההזאה אצל פני הכפרת לצד מזרח שהוא כנגד פני הכהן כשיהיה פניו אל הארון והנה מלבד זאת ההזאה שהיא על פני הכפרת יזה לפני הכפרת שבע פעמים וגו' כמו שנתבאר בהזאות הדומות לזה במה שקדם ואמנם קצרה התורה בזה והנה תהיה ההזאה הראשונה למעלה והשבע למטה לפי שנאמר על הכפרת ושאר הזאות הם לפני הכפרת והוא מבואר ממה שקדם שאלו ההזאות יחוייב שיהיו באצבעו הימנית:
@601 **והמשלח את השעיר לעזאזל וגומר.** ראוי שתדע שלא יקרא משלח עד שיצא מהעיר שבית המקדש בתוכה כאלו תאמר חוץ מירושלים כי כל זמן שהוא בעיר הוא במה שממנו התנועה כי העיר הוא הפך המדבר שאליו התנועה ובצאתו מהעיר והוא בדרך אז החל בתנועה הזאת ואז יקרא משלח ומן אז יטמא בגדים שעליו ולא יטמא הנוגע בשעיר הזה אבל יטמא משלחו מצד מה שהוא משלחו אף על פי שלא נגע בו וראוי שיתבאר מזה שהמוציא פר ושעיר הנשרפין מחוץ למחנה הוא טמא ומטמא בגדים כי הוא ראוי בזה כמו שמשלח שעיר המשתלח כי הם נשרפין חוץ למחנה מפני שאתם העונות כמו שישתלח השעיר מפני שאתו העונות ועוד שהרי מצינו בהם שהשורף אותם טעון כבוס בגדים ולזה ראוי שנלמד מזה כי הם יטמאו מוציאם כמו שעיר המשתלח שיטמא משלחו שאם לא יטמאו אלא השורפם לא היה ראוי בשעיר המשתלח שיטמא כי אם מי שידחפנו להמיתו ולא יטמא בגדים קודם זה:
@602 **וכפר על הקדש מטמאות בני ישראל ומפשעיהם לכל חטאתם.** יקרא קדש מקום הקדשים ואמר שבאלו ההזאות יכפר עליו מטמאות בני ישראל בענין מקדש וקדשיו אם נכנסו במקדש בטומאה או אכלו קדשים בטומאה. ומפשעיהם לכל חטאות הטמאה שהם אלו שזכרנו והנה הפשע יאמר על מה שהוא בזדון וזה מבואר מצד הוראת הגדר ולזה יכפר על זדון טומאת מקדש וקדשיו בזה האופן בפר כהן גדול ושעיר הנעשה בפנים ר"ל שבפר כהן גדול יכפר עליו ועל ביתו ועל הכהנים ובשעיר הנעשה בפנים יכפר על כל ישראל. והנה יכפרו אלו הקרבנות החמורות שבעבירות אלו הטמאות וראוי שתשלם הכפרה בכל מיני עבירות אלו הטמאות כי מן השקר שתשגיח התורה בכפרת קצת מיניהם ולא תשגיח בשאר וזה שקרבן עולה ויורד יכפר על טמאת מקדש וקדשיו כשהית' שם ידיעה בתחילה ובסוף והעלם בנתים כמו שיתבאר בפרשת ויקרא ופר ושעיר הנעשה בפנים ביום הכיפורים מכפר על זדון אלו הטמאות וישאר מאלו העברות מה שאין בו ידיעה לא בתחלה ולא בסוף ומה שיש בו ידיעה בסוף ולא בתחלה ומה שיש בו ידיעה בתחלה ולא בסוף וכבר מצאנו כפרת אלו הטמאות בשעיר ביותר חמור שבמיניהם ולזה כשמצאנו שעירים באים לכפרה ולא נתבאר מה יכפרו הנה יתבאר שהם באים לכפר על דבר שהוא מסוג מה שיכפר עליו זה השעיר וכל שכן שיתבאר זה בשעיר חטאת הנעשה במזבח העולה ביום הכפורים שנאמר בו בפרשת פינחס ושעיר חטאת אחד לכפר עליכם מלבד חטאת הכיפורים למדנו שהוא מכפר על דבר הוא מסוג מה שיכפר עליו חטאת הכפורים והנה ראוי שיכפר על דבר שהוא יותר קל מזדון הטמאה כי ראשונה ראוי שיתנקה מהדבר החמור ואחר כן מהקל וזה מבואר במעט עיון ממה שקדם בענין הקרבנות. וכבר מצאנו עוד בראשי חדשים וברגלים שעירי חטאות ונאמר בהם שהם לכפר כמו שנזכר בפרשת פינחס וראוי שיהיו מכפרים הקל שבמיני אלו הטמאות כי החמור יכפר עליו ביום הכיפורים ולזה יכפר השעיר הבא אחריו על החמור שבמינים הנשארים ולזה יכפרו שעירי ראשי חדשים ושעירי הרגלים על שגגת הטומאות במקדש וקדשיו שאין בהם ידיעה לא בתחלה ולא בסוף ויכפר שעיר הנעשה בחוץ ביום הכפורים על היותר חמור מזה שלא יבא בשום פנים לחייב קרבן עולה ויורד והוא מה שאין בו ידיעה בתחלה ויש בו ידיעה בסוף והנשאר מהעברת אלו הטמאות הוא מה שיש לו ידיעה בתחלה ואין בו ידיעה בסוף וזהו אפשר על חיוב קרבן עולה ויורד וזה יהיה כשתתחדש לו הידיעה במה ששגג בו ואין בכאן כי אם אחד משעירי יום הכיפורי' לכפר עליו על זאת הטומאה כל זמן שלא תתחדש לו ידיעה בה וראוי שתיוחס זאת הכפרה לשעיר הנעשה בפנים לפי שהוא היותר חזק לכפר על הטמאות ולזה יכפר על זדון הטומאה ולפי שהחמור שבמיני השגגות אחר המין שיתחייב עליו קרבן עולה ויורד הוא מה שיש בו כח על שיתחייב עליו קרבן עולה ויורד הנה תיוחס זאת הכפרה לשעיר הנעשה בפנים ולא ייחדה התורה שעיר בכפרת זה המין מהטומאה לפי שזאת הכפרה אינה שלמה כי כל זמן שתתחדש לו ידיעה בסוף על שגגתו יתחייב קרבן עולה ויורד מה שאין כן בשאר הכפרות הבאות על הטמאות שייחדה התורה בהם שעיר:
@602 **וכן יעשה לאהל מועד השוכן אתם בתוך טמאתם.** ר"ל שיזה בו מדם הפר ח' הזאות אחרות כמשפט הנזכר ומדם השעיר שמנה הזאות אחרות כמשפט הנזכר ותהיינה אלו ההזאות לכפר על אהל מעד מאלו הטמאות הנזכרות ולזה אמר השוכן אתם בתוך טמאתם והנה לא בארה התורה באי זה מקום מאהל מעד תהיינה אלו ההזאות. והנה יתבאר זה ממה שזכרה בהזאות הנעשות פנים וזה שהם היו לצד המערבי ממנו באופן שתהיה ההזאה לפני יי' ובזה האופן תהיה ההזאה באהל מועד על פני הפרכת קדמה ולפני הפרכת במה שהיה ממנו כנגד הארון כדי שיהיו פני המזה לפני יי' וכזה תמצא זה מבואר בהזאות הנעשו' באהל מועד שהם בפני הפרכת בפרשת ויקרא:
@603 **וכל אדם לא יהיה באהל מועד לכפר בקדש עד צאתו.** ר"ל שבהזאתו לפני לפנים על הכפרת ולפני הכפרת יחוייב שלא יהיה אדם באהל מועד ומזה המקום יתבאר שבהיותו מכפר על אהל מועד ראוי שלא יהיה אדם בין המזבח ואהל מועד כי היחס אחד:
@603 **וכפר בעדו ובעד ביתו ובעד כל קהל ישראל.** רוצה לומר שיכפר מהטמאות הנזכרות באהל מועד בעדו ובעד הכהנים ובעד כל קהל ישראל. ואמנם הכפרה בעדו ובעד הכהנים תהיה בדם הפר והכפרה בעד כל קהל ישראל תהיה בדם השעיר:
@604 **ויצא אל המזבח אשר לפני יי'.** רוצה לומר המזבח היותר מערבי כי הוא לפני יי' והוא מזבח הקטרת הסמים והנה הכפרה הזאת היא גם כן מהטמאות הנזכרות והיא תהיה כשיזו עליו מדם הפר והשעיר באופן שיזכר אחר זה:
@604 **ולקח מדם הפר ומדם השעיר ונתן על קרנות המזבח סביב.** רוצה לומר כשיטבול אצבעו בדם ויתן ממנו בכל קרן וקרן מקרנות המזבח באופן הנזכר בחטאת וזה יהיה כשיערב דם הפר ודם השעיר ויטבול אצבעו בדם המעורב והנה יתחיל להזות על קרן שנפגע בו תחלה בהכנסו לאהל עם הדם המעורב כמו שהתבאר מהשרשים הכוללים ולפי שבהכנסו שם ילך תחלה סביב המזבח לפאת ימין הנה הקרן שיפגע בו תחלה הוא המזרחי הצפוני ואחריו המערבי הצפוני ואחריו הדרומי המערבי ואחריו הדרומי המזרחי והנה נתן הסבה בכל זה אחר שהשלמנו באור דברי זאת הפרשה:
@605 **והזה עליו מן הדם באצבעו שבע פעמים.** הנה זה יהיה בשטח המזבח העליון במקום הקטרת הקטרת והנה לא פרשנו מלת עליו אצלו כשתהיה ההזאה בקירות המזבח כי לא היו במזבח הזהב שני מקומות אחד למעלה ואחד למטה כמו העניין במזבח העולה ועוד שאף על פי שיהיה שם מקום שני מורה על הצורה כמו העניין במזבח העולה הנה לא תהיה ההזאה בו שבע פעמים להורות על הצורה אבל תהיה ההזאה ברוחב וסביב ולא תהיה באצבעו ולזה הוא מבואר שהכונה באמרו עליו הוא שתהיה ההזאה עליו ממש לא בקירותיו והנה יזה אלו ההזאות ממקום שהשלים שם נתינת הדם על הקרנות והוא הצד הדרומי מזרחי:
@605 **וטהרו וקדשו מטמאת בני ישראל.** רוצה לומר מזדון טמאת מקדש וקדשיו והנה תשלם הכפרה בזה באלו הג' מקומות מאלו הטמאות לכהן גדול ולכהנים ולעם הקהל:
@606 **וכלה מכפר אל הקדש ואת אהל מועד ואת המזבח והקריב את השעיר החי.** רוצה לומר שאחר שישלים כפרת זדון מקדש וקדשיו באלו השלשה מקומות יקריב השעיר החי אשר לעזאזל לפאת מערב מעט להתודות עליו ואחר כך ישלחהו:
@607 **וסמך אהרן את שתי ידיו על ראש השעיר החי.** הנה למדנו בזה המקום שהסמיכה היא בשתי ידים על ראש הקרבן ומזה המקום נלמד שתהיה הסמיכה בכל כחו כי לזאת הסבה הקפידה התורה שתהיה הסמיכה בשתי ידיו:
@607 **והתודה עליו את כל עונות בני ישראל וגו'.** רוצה לומר שהוא כאלו יסיר עונות ישראל:
@607 **ומפשעיהם לכל חטאתם.** איזה שיהיו עשה או לא תעשה קלים או חמורים וישימם על ראש השעיר בסמיכתו זאת ויתבאר מלשון הכתוב שהוא יתחיל מהקל ויסיים בחמור ולזה זכרה התורה הפשע אחר העון כי הפשע הוא יותר חמור כי הוא מורה על הזדונות כמו שקדם ולפי שהחטא יאמר על היותר קל כמו שהתבאר בפרשת ויקרא שהחטא יאמר על השגגה אף על פי שלא הודע לו חטאתו אשר חטא הנה יהיה לשון זה הודוי שחטאו ושעוו ושפשעו בני ישראל ויבקש מדבריו מהשם יתע' שיכפר להם זה כי זהו ענין הודוי והנה תלמד גם כן שההדרגה הוא בזה התואר ממה שאמר חטאנו עם אבותינו העוינו והרשענו וראוי שלא יעלם ממנו שהוא ראוי שישובו ישראל בכל לבם לשם יתע' ואז יתכפרו להם כל החטאי' בזה הקרבן וזה שאם דקדקה התורה בזה בקרבנות יחיד הבאות על השגגות כל שכן שתקפיד בזאת הכפרה הנפלאה אשר באה להניח חטאים גדולים ולזאת הסבה היתה התרועה בר"ח השביעי כמו שיתבאר במה שיבא בג"ה ומזה המקום למדנו שהודוי הנעשה על פר כהן גדול הוא גם כן בזה הענין כי פר כהן גדול הוא לו ולכהנים תמורת שני שעירי העזים לכל ישראל שנאמ' בזאת יבא אהרן אל הקדש בפר בן בקר לחטאת ואיל לעולה. ומאת עדת בני ישראל יקח שני שעירי עזים לחטאת ואיל אחד לעולה. והנה אחד מהשעירים יכפר על זדון טמאת מקדש וקדשיו והשני יכפר על כל עבירות שבתורה והוא המשתלח והנה על שני אלו הדברים יכפר כהן גדול בעדו ובעד הכהנים ולזה יהיה לשון הודוי הראשון שחטא ושעוה ושפשע הוא וביתו שיכפר לו השם יתע' ולשון הודוי השני הוא שחטא ושעוה ושפשע הוא וביתו והכהנים ושיתפלל להשם יתע' שיכפר להם זה:
@607 **ושלח אותו ביד איש עתי המדברה.** רוצה לומר איש של רוב הרגלו בהליכה במדברות לא ימתין אכל כל עת הוא נכון לו כאלו הוא בעל העת כי יש אנשים רכי הלב ואולי ילכו שם בעת אחת לא בעת אחר ליראתם מן ההליכה בכמו אלו המקומות כל שכן אם יקרו דברים מונעים כמו המטר ונשיבה הרוחות החזקות ומה שידמה לזה ולפי שהכפרה לא תשלם בזולת שלוח זה השעיר למדבר היה ראוי שידקדקו שיהיה המשתלח איש עתי שיהיה כל עת נכון לו באופן שישלים מה שכוון לזה ובזה לא דקדקה התורה במשלח שיהיה כהן ולזה יהיה שלוח השעיר אפילו בישראל:
@608 **ונשא השעיר עליו את כל עונותם אל ארץ גזרה.** רוצה לומר אל ארץ שלא יעבד בה ולא יזרע והנה בזה תועלת לישב בלבם שכבר נתכפרו להם עונותיהם ולא יתרשלו מעבוד השם יתע' מפני מה שהפליגו לחטא במה שקדם. וראוי שנדע שזה השעיר ימות שם בשלוחו אותו וזה יתבאר מפני' שונים מהם שאם היה שלוחו להניחו חי כמו העניין בשלוח הצפו' החיה של מצורע הנה מפני שזה השעיר הוא חטאת יקרה בו מהתקלה הרבה. ועוד שאם דקדקה התורה במקום שישלחהו בו שלא יהיה בו תועלת לבני אדם כל שכן שתדקדק מה בשעיר בעצמו ולזה יחוייב שיהיה שלוחו לעזאזל באופן שימות. וזה יהיה כשידחהו המשלח שם משן הסלע גבוה כי זה יורה עליו לשון עזאזל מצד הוראת הגדר. ולזאת הסבה היה המשלח טעון כבוס בגדים כמו שטעון כבוס בגדים השורף פר ושעיר וזה כי השעיר החי לא יטמא מצד מה שהוא חי אבל יטמא משלחו מצד ששלוחו להמיתו והנה כמו שהיה תכף לסמיכה שחיטה בקרבנות כן יהיה תכף הסמיכה שלוח בזה השעיר מפני שסופו אל ההמתה:
@608 **ושלח את השעיר במדבר.** רוצה לומ' שכיון שיתברר שישתלח השעיר במדבר אף על פי שלא הגיע עדין למקו' הגבוה שידחפהו משם משלחו להמיתו יעשה הכהן גדול אלו הפעולות שיזכור אחר זה. וראוי שתדע שהמשלח אם לא יכול להשלים השלוח בזולת אכילה הנה יותר לו אז לאכול כי זה הוא מצורך השלוח אשר יחוייב שיעשה ביום הכיפורים וזה מבואר בנפשו:
@609 **ובא אהרן אל אהן מועד ופשט את בגדי הבד אשר לבש בבואו אל הקדש.** ראוי שנדע שלא חייבה אותו התורה לבא אל אהל מועד לפשוט בגדיו שם כי זה בלתי ראוי במקו' הנכבד ההוא רוצה לומ' שיעמוד שם ערום וכ"ש שזה יותר נמנע מצד שימשך לזה שיצא כהן גדול ערום משם וילך ערום אל הלשכה אשר בה המקוה אשר יטבול בו לא צותה התורה גם כן שיבא שם שלא לצורך כי כבר הוזהר מזה במה שקדם ולזה יחוייב שתהיה זאת הביאור לצורך ויחוייב עם זה שתהיה באופן שיחוייב העשותה בבגדי לבן כי לא זכרה התורה שנותו בגדי לבן לבגדי זהב עד אחר זאת הביאה ומזה המקו' יתבאר שזאת הביאה היא להכנס לפני לפנים להוציא הכף והמחת' כי לא נשאר מעבודת יום הכיפורים דבר יהיה ראוי שיעשה בבגדי לבן זולת זה כי אין ראוי שיכנס לפני לפני' בבגדי זהב כמו שקדם ולפי שאין רשאוי שיוציא משם הכף והמחתה טרם השלם העיכול לקטרת ולאש אשר במחתה והיה זה ממה שלא יתאמת שישלם בכמו זה העת הנה יצטרך להמתין לסלק הכף והמחתה עד הערב וראוי שיהיה זה בעת שיצטרך לבא אל אהל מועד להקטיר קטרת הסמים ולהעלות את הנרו קודם שיקטיר קטרת הסמים ויעלה את הנרות כדי שלא יהיה ענן הקטרת לפנים מאהל מועד ולפי לפנים יחד כי ההערה בו באלו השני מקומות קרובה להיות אחת כמו שנבאר ולזה אין ראוי שתהיה בשני המקומות ובכלל הנה אז ישלם בלי ספק העיכול לאש ולקטרת ואין ראוי שיכנס שם הכהן אם לא אחר שיתברר לו שישלם זה כדי שלא יכנס שם שלא לצורך ויתחייב מיתה בידי שמים והנה לא זכרה התורה בביאור סלוק הכף והמחתה לפי שאינו מכוון בעצמו ואינו מצורך הכפרה אבל בהכרח יתחייב לכבוד המקום ההוא שלא ישאר שם האפר בכל השנה עד בא יום הכיפורים אחר שיסירה משם הכהן הגדול בבואו לכפר בקדש והנה לא נזכרה בזה המקום זאת הביאה כי אם להשלים זכרון הדברים שיעשו בבגדי לבן לא שיהיה סדר העניין כן ואולם שאר הדברים כלם נזכרו על הסדר אשר אם נשתנה הסדר ההוא לא יהיה במה שיעשה בזולת סדרו תועלת והנה יפשוט כהן גדול בגדי לבן בלשכה שיטבול בה ושם ילבש בגדי זהב:
@609 **והניחם שם.** רוצה לומר שלא ישמש בהם עוד ומזה יתבאר שהם אסורים בהנאה והנה יתבאר טעם זה אחר השלימנו באור זאת הפרשה. וראוי שתדע כי אח שלוחו השעיר יוציא אמורי פר ושעיר להקטירם על המזבח העולה ואחר שיתבאר לו שהגיע השעיר למדבר ישלח פר ושעיר מחוץ למחנה לשרפם וינתחם באופן שהתבאר בפר כהן משיח בפרשת ויקרא ולזאת הסבה אמרה תורה ושלח את השעיר במדבר ולא הוצרכה להזכיר הוצאה חלבי החטאת כי זה מבואר ממה שקדם מענין הקרבנות והנה סמך אחר זה שלוח השעיר לעזאזל להוצאת פר ושעיר מחוץ למחנה לשרפם להעיר שזה היה נעשה יחד והנה העניין מעמו יעיר על זה כי הפר של כהן גדול היה נכלל בו. כל עניין שני השעירים ולזה ראוי שיהיה ענין השעירים נעשה יחד כמו העניין בפר שהוא גוף אחד:
@610 **ורחץ את בשרו במים במקו' קדוש.** ר"ל באחת הלשכות אשר בעזרה ומזה המקום נלמד שכל עת שיטבול ביום הזה להחליף בגדים מבגדי לבן לבגדי זהב או הפך יהיה טעון טבילה בקדש וראוי שיתבאר מזה ג"כ שבלבשו בבקר בגדי זהב לעבוד עבודת תמיד של שחר והמוספין יצטרך טבילה וזה שבהכנס לעבודה יצטרך כל כהן קדוש ידי' ורגלי' ולט יצטרך לזה בשאר העבודות שיעבוד ביום ההוא כמו שקדם ואם במקום שאין טעון קדוש ידי' ורגלי' חייבתהו התורה לטבול כ"ש שיתחייב לטבול במקו' אשר הוא טעון קדוש ידים ורגלי' ולזה יתבאר גם כן שבכל טבילה יהיה קדוש ידי' ורגלי' כל שכן במקו' שנתחייב טבילה והנה נבאר הסבה בכל זה במה שיבא:
@610 **ולבש את בגדיו.** ר"ל בגדי זהב כי הם בגדיו אשר יעבוד בהם תמיד:
@610 **ויצא ועשה את עולתו ואת עולת העם.** רוצה לומר אילו ואיל העם והנה יעשה תחלה עולתו ואחר כך עולת העם כמו הענין בחטאת והיה זה למעלת הכהן עם שאין ראוי שיכפר על זולתו קודם שיכפר על עצמו מה שלו מהחטאים ההם ולפי ששם שעיר החטאת אחד להשלי' זאת הכפרה כמו שנזכר בפרשת פינחס הנה ראוי שיהיה נעשה קודם עולתו ועולת העם כי החטאת קודם לעולה כמו שיתבאר במה שקדם. ואמנם לא הזכיר זה בזה המקום כי לא נזכר בזה המקום החטאת ההוא. וראוי שתדע כי האיל שנזכר בפרשת פינחס בעולה שיקריבו בני ישראל ביום הכפורים הוא האיל הזה שקרא איל העם. וזה שכבר אמר שם ושעיר עזים אחד לחטאת מלבד חטאת הכפורים ועולת התמיד למדנו מזה שכל העולות והחטאות באות משל צבור ביום הכפורים נזכרו שם מלבד חטאת הכפורים ועולת התמיד של שחר ושל בין הערבים ולזה הוא מבואר שכבר נזכר שם איל העם והוא האיל הנזכר:
@610 **וכפר בעדו ובעד העם.** רוצה לומר שבה תשלם הכפרה בשלמו' כי הקרבת העולה הוא להעיר שכבר נשלם הרצוי במה שהתבאר במה שקדם:
@611 **ואת חלב החטאת יקטיר המזבחה.** רוצה לומר אחר הקרבתו עולתו ועולת העם יקטיר אמורי פר ושעיר הנשרפין על המזבח העולה:
@612 **ורחץ את בשרו במים.** רוצה לומר אחר שיטבול ויעריב שמשו יוכל לבא אל המחנה שיצא ממנו והוא העזרה ואפשר שנמנעה ממנו הביאה אל המחנה אפי' תוך חומת ירושלם ביום ההוא קודם שיטבול להעיר על התחזק מהעונו' אשר נשאום אלו החטאות:
@612 **ואחר יבא אל המחנה.** ראוי שתדע שלא תדחה ביאתו אל המחנה יום הכפורים שהוא אסור במלאכה והנה הרצון בזה שאחר כן יוכל לבא אל המחנה ולהכנס למקדש אחר שיעריב השמש:
@613 **ואת פר החטאת וגומר והשורף אותם יכבס בגדיו.** מפני שאמרה התורה בזה המקום אשר הובא את קדמם לכפר בקדש ולא היה צרך זה בזה המקום לפי שכבר ידענו זה למדנו שהשורף טעון כבוס בגדים מפני שהובא את דמם לכפר בקדש ולזה יתבאר שכל חטאות הנשרפות מחוץ לחנה מטמאות בגדי שורפם וכן הענין בבגדי מוציאם מחוץ למחנה ובכלל הנה לסבה אשר התחייב בזה המקום יתחייב זה בכל חטאות הנשרפות וראוי שתדע שכבר יתואר שהוא מוציא מחוץ למחנה תכף שיצא מן המחנה שהוא בו כי כל עוד שהוא במחנה ההוא בעינו הוא כמה שממנו התנועה ולזה לא יקרא מוציא חוץ למחנה עד שיצא חוץ לעזרה וכן משהיגע למקום שריפתו אינו מטמא המתעסק בו כי לפי מה שאחשוב אלא אם היה מתעסק בשריפתו. והשורף מטמא בגדים כל זמן שיהיה אפשר שיתואר כשהוא שורף ולזה יטמא בגדים המתעסק בשריפתו עד שתשלם השרפה ויעשה האפר והוא מבואר שלא יקרא שורף מפני הבעירו האש אם לא היה באש הזה זה החטאת הנשרף:
@614 **ורחץ את בשרו במים.** רוצה לומר אחר שיטבול ויעריב שמשו יוכל לבא אל המחנה שיצא ממנו והוא העזרה ואפשר שנמנעה ממנו הביאה אל המחנה אפי' תוך חומת ירושלם ביום ההוא קודם שיטבול להעיר על התחזק מהעונו' אשר נשאום אלו החטאות:
@615 **והיתה לכם לחקת עולם.** רוצה לומר זאת העבודה שקדם זכרה:
@615 **בחדש השביעי בעשור לחדש תענו את נפשותיכם וכל מלאכה וגומר.** הרצון בזה הענוי שלא יאכלו ושלא ישתו וזה מבואר מצד הוראת הגדר ומעצם הענין וזה שכבר יראה שהיתה הכונה בזה שיבדלו מאלו ההנאות למען יכנע לבבם ויתנו אל לבם לשוב מדרכם הרעה כי זה כיון ביום הזה כדי שתשלם להם הכפרה ולזאת הסבה היתה התרועה בראש השנה כמו שיתבאר במה שיבא בגזרת הצור. ולפי שהוציאה התורה זה בלשון ענוי ולא אמרה בביאור שלא יאכלו בעצם היום הזה הנה לא יעברו על זאת המצו' באכילת כזית אבל באכילה שמצדה ימנע העינוי ושערו חכמים שזה ישלם בשיעור מהמזון בכותבת הגסה לא בפחות מזה ובשתייה ישלם זה בשיעור רביעית לוג לא בפחות מזה וראוי שיתבאר מזה שאם אכל אוכל בלתי ראוי לאכילה או שתה משקה בלתי ראוי לשתי' לא יענש על זאת הצואה כי אין זה ממה שיעבור הענוי בסבתו אבל הוא ענוי וכן אם אכל על השבע המופלג והנה נאסר בכל מלאכה כמו הענין בשבת:
@615 **האזרח והגר הגר בתוככם.** ר"ל בגר צדק ולמדנו בזה שלא נקבל גר צדק לחציין אם לא יקבל עליו כל התורה כולה:
@616 **כי ביום הזה יכפר עליכם תטהר אתכם.** למדנו שהיום הזה מכפר אע"פ שאין שם בית המקדש לעשות העבודה הנזכרת והיה זה כן מפני שנתנה התורה סבת המצות הנהוגות בפני הבית ושלא בפני הבית היות השם יתעלה מכפר ביום הזה מכל חטאות ישראל והיה זה כן לפי שעיקר הכפרה היא התשובה והצום עם השביתה מהמלאכה ומכל צרכי הגוף מעיר על התשובה הערה נפלאה:
@616 **מכל חטאתיכם לפני יי' תטהרו.** ר"ל שכבר יטהרו מכל חטאתם לפני יי' בזאת העבודה הנעשת בבית המקדש לפני ה' או ירצה בזה שהם יטהרו לפני י' בשובם אליו בזה האופן ויהיו במדרגת מי שלא חטא:
@617 **שבת שבתון היא לכם.** זאת היא מצות עשה לשבות בו מכל מלאכה:
@617 **ועניתם את נפשותיכם חקת עלם.** הנה שתי אלו המצות לפי שאין להם התלות בבית המקדש הוא מבואר מעניינם שהם נוהגות תמיד:
@618 **וכפר הכהן אשר ימשח אותו.** ר"ל שזאת הכפרה הנעשת בבית המקדש תעשה על יד כהן משיח בשמן המשחה או ע"י כהן אשר ימלא את ידו לכהן תחת אביו אף על פי שאינו משוח בשמן המשחה והוא המרובה בגדים ולמדנו מזה שבזמן שבן כהן גדול ראוי לכהונה גדולה הוא קודם לכל אדם ומבואר זה בנפשו כמו שביארנו במה שקדם:
@618 **ולבש את בגדי הבד בגדי הקדש.** למדנו מזה שהדבר המתיחס לכפרת היום יעשהו כהן גדול בבגדי לבן:
@619 **וכפר את מקדש הקדש ואת אהל מועד וגו'.** למדנו שלכל אחד מהם כפרה בפני עצמה ולזה לא תעכב כפרה המתאחר כפרת הקודם. ואולם כפרת הקודם תעכב כפרת המתאחר כדי שלא ישתנה הסדור שסדרה התורה בזה:
@619 **ועל הכהנים ועל כל עם הקהל יכפר.** כבר התבאר מזה מה שאמרה שנית וכפר בעדו ובעד ביתו ירמוז בו אל הכהנים כי הם בניו כמו שביארנו:
@620 **והיתה זאת לכם לחקת עולם לכפר על בני ישראל מכל חטאתם אחת בשנה.** ר"ל שתעשה העבודה הזאת בזה האופן ובסדור הנזכר פעם אחת בשנה והיא בעשור לחדש השביעי:
@620 **ויעש כאשר צוה יי' את משה.** הורה בזה שכל זה מכוון באופן הנזכר ולזה לא הפיל אהרן ממנו דבר הנה זהו ביאור דברי זאת הפרשה:
@622 **דבר אל אהרן ואל בניו ואל כל בני ישראל.** ראוי שתדע כי הגר הוא בכלל כי כבר זכרה התור' בביאור במה שדומה לזה בזאת הפרש' עם שזה מבואר בכללות שמשפטי התורה הם שוים לגר ולאזרח הארץ:
@623 **איש איש מבית ישראל אשר ישחט שור או כבש או עז במחנה.** זכר שור וכבש ועז לפי שמהם יהיו הקרבנות כמו שנזכר בפרשת ויקרא ואמר במחנה ר"ל במחנה ישראל וגומ':
@624 **ואל פתח אהל מועד וגו'.** רוצה לומר מחוץ למחנה ישראל והנה הוא מדבר בקדשים ששחטם חוץ לעזרה היה ששחטם במחנה ישראל או ששחטם חוץ למחנ ישראל כדי שלא הביאו לשחטו אל אהל מועד באופן שצותה התורה כדי שיהיה נאות להקריב קרבן להש' לפני משכן ה' הנה הדם ששפך בזאת השחיטה יחשב לו דם ר"ל שכבר יתחייב עליו מיתה ולזה ביארה התורה שכבר יתחייב עליו כרת והנה התבאר מזה המקום שבקדשים ידבר כי הם ראוים להביא אל אהל מועד ולזה ראוי שיהיו הקדשים ראוים לבא אל אהל מועד ואז יתחיי' כרת על שחיטתן בחוץ. אבל אם היו בעלי מומין או שהיו באופן מה זולת זה שאינן ראויים לבא אל אהל מועד הנה לא יתחייב כרת על שחיטתן וראוי שיתבאר מזה המקום כי הנשחט בחוץ הוא פסול להקריב ממנו קרבן לה' כמו שהתבאר מדברנו בביאור זה הפסוק וראוי שלא יעלם ממנו כי התורה תדבר במה שהיא שחוטה במחנה או מחוץ למחנה רוצה לומר שהוא בגדר השחיטה שם ולזה אם שחט בלילה שם הנה אם תהיה שחיטתו שחיטה כי בשחיטה אשר שם לא יהיו מתנאיה שלא תהיה בלילה כמו העניין בשחיטה אשר בעזרה שאינה אלא ביום כמו שהתבאר ולזאת הסבה לא יתחייב המולק את העוף חוץ לעזרה כי אין זה העניין נכנס בגדר השחיטה חוץ לעזרה אבל ידמה שם זה הענין לנהירה או לנדמה לה ולזה יתחייב על שחיטת עוף שהוא קדשי' בחוץ כיון שלא הביאו אל אהל מועד באופן הראוי להקריב ממנו קרבן להשם:
@625 **למען אשר יביאו בני ישראל את זבחיהם אשר הם זובחים על פני השדה והביאום לה' אל פתח אהל מועד אל הכהן.** קרא על פני השדה מה שהוא חוץ מהמקום המוגבל לזבחי השם יתעלה כי השדה מורה על זאת הכונה כמו שביארנו בפסוק אמרו ובשר בשדה טרפה לא תאכלו עם שכבר היה אפשר שהיו ישראל קודם מתן תורה זובחים זבחים על פני השדה לא לעבודה לשם יתע' הלא תראה במעשה העגל שהעלו עולות ויגישו שלי' והיה זה המנהג הפחות להם ממה שנהגו וגדלו עליהם בהיותם במצרים בדעותיהם הנפסדות ומנהגיהם הפחותים וזבחו זבחי שלמים להשם אותם:
@626 **וזרק הכהן את הדם.** ר"ל שאפילו השלמים נאכלים לבעלים והיה אפשר מפני זה שיחשב שלא יתחייב כרת אם ישחטום בחוץ מפני חלק הבעלים שהוא נאכל במחנה ישראל הנה יחוייב שיביאום אל אהל מועד לשחטם כדי שיהיו להש' ויקריב מהן למזבח הדם והחלבי':
@627 **ולא יזבחו עוד את זבחיהם לשעירים.** ר"ל לשדים והם הדמיונים הכוזבים שיביאום לחשוב במה שאיננו אלוה שהוא אלוה ואחשוב כי מפני ששבתי הוא אשר ייוחס לו עניין השדים כמו שהתבאר במשפטי הכוכבים והיה גדי בית שבתאי הנה נקראו השדים שעירים ואע"פ שדלי גם כן הוא בית שבתאי הנה יתחדשו הדמוינים המפסידים משבתאי מצד טבע השחורה אשר מזל גדי מתיחס לו וכן העניין בשבתאי לא מצד טבע הדם אשר מזל דלי מתיחס לו:
@627 **חקת עולם תהיה זאת לכם לדורותיכם.** ראוי שנדע שזאת החקה הנוהגת לדורות בזה הענין הוא שלא לזבוח לשעירים וכ"ש לע"ז ואמנם השחיטה חוץ מפתח אהל מועד לא יתחייבו עליה כרת כי אם אחר שנגלה להם המקום שנבנה בו המזבח בהר המוריה כי קודם זה היה אפשר להם לשחוט ולהעלות הקרבנות לשם יתעלה בכל המקומות כמו שיתבאר בפרשת ראה אנכי ולפי זה הפירוש יהיה זה מצות לא תעשה והנה הרב המורה לא מנאה ובספרא אמרו והביאום להשם מצות עשה מצות לא תעשה מנין ת"ל ולא יזבחו עוד את זבחיהם לשעירים והנה אפשר שיהיה הרצון בזה כי לולי הבאתם הקרבנות לה' אל אהל מועד יהיה סבה שלא יזבחו עוד את זבחיהם לשעירי' וזה שאם היה מותר להם לזבח לש"י מכל מקום הנה יהיה זה סבה שלא יעמדו על אמתת השם ויחשבו בו רבוי לזאת הסבה על שלמעוט עמידתם על האמת בזה תהיה הקרבתם למה שיהיה האלוה לפי הדמיונים הכוזבים שר הם השרים באמת ולפי זה הפירוש יהיה שב אמרו חקת עולם תהיה זאת לכם לדורותיכם לענין שחיטת קדשים בחוץ וזה אמנם יהיה אחר הגלות בית עולמים כמו שיתבאר בפרת ראה אנכי וכבר יורה שאין אמרו ולא יזבחו עוד את זבחיהם לשעירים מצות לא תעשה שאם היה הדבר כן לא היתה בזה המאמר מלת עוד אבל היה המאמר בזה ולא יזבחו את זבחיהם לשעירים ואולם אמר עוד יורה שהרצון בזה שזה יהיה סבה שלא יזבחו עוד שבחיהם לשעירי' וזה מבואר מאד:
@628 **ואליהם תאמר איש איש מבית ישראל ומן הגר אשר יגור בתוכם אשר יעלה עולה או זבח ואל פתח אהל מועד וגו'.** ר"ל שאם יעלה עולה או זבח חוץ לעזרה יתחייב כרת והנה זכר העולה שהיא כלה כליל ואחר כך הזבח שלא יקריבו ממנה לשם כי אם קצתו להעיר שאיך שיהיה העניין בזה יתחייב עליו כרת ובאמרו אל פתח אהל מועד לא יביאנו למדנו שכל הראוי לבא אל אהל מועד אם עשה אותו בחוץ לקרבן באופן שלא יוכל להביאו אל אהל מועד כמשפטו יתחייב כרת והנה אמרנו שיעשה אותו בחוץ לקרבן לפי שנאמר עולה או זבח ומזה המקום יתבאר שנסוך היין אע"פ שלא היה קרב על המזבח אם עשה אותו בחוץ חייב שהוא ראוי להביאו לאהל מועד שנאמר בקדש הסך נסך שכר לה' ויתבאר שאינ חייב כרת אם לא יעשה זה הקרבן להשם יתעלה שנאמר עולה או זבח והעולה והזבח הם לחש' לפי הוראת הגדר וזה מבואר ממה שקדם במעשה העולה והזבח. וראוי שתדע שלא יתחייב על העלאה בחוץ להשם אם לא נבנה שם מזבח כי המזבח לקוח כנגד העלאת הקרבנות ולזה תמצא בנה ואברהם ויצחק ויעקב ובלעם במה שהקריבו מהקרבנו' ליי' בניית המזבח:
@630 **ואיש איש מבית ישראל ומן הגר הגר בתוכם אשר יאכל כל דם.** לפי שזכר אחר זה ואני נתתיו לכם על הזבח למדנו שלא יתחייבו כרת אלא עם הדם אשר מדרכו שינתן על המזבח והוא דם הנפש כמו שאמר דם הפר ודם השעיר ואולם דם התמצית ודם האברים לא יתחייבו עליו כרת ויתב' מהשרשים הכוללים שהדם ההוא הוא באזהרה:
@631 **כי נפש הבשר בדם הוא.** ר"ל שהד' הוא הכלי לנפש להוביל בו החו' היסודי והמזון לחלקי הגוף ולזה ימות הב"ח רק בהסתלק הדם ולזאת הסבה היתה ההערה בו על הנפש כמו שביארנו בעניין הקרבנות והיה מכפר על הנפש בזה האופן וכבר יתבאר במה שקדם שאסור הדם אינו נוהג כי אם בבהמה ובעוף ואולם דם שאר הב"ח לא יתחייבו עליו מזה הדם ולפי שדם הבהמה ועוף אסור והיתה החיה בלתי קרבה להשם יתעלה ולא העוף באופן שיהיה ממנו שלמים חייבה התורה בחיה ובעוף הטהורים כאשר ישחטם שנכסה דמם בעפר כדי שלא יבאו הנשים לאכול דמם ואולם הבהמה לא הוצרכה בה התורה לזה לפי שלא הותר לישראל בתחלה לאכול בשר כי אם שלמים וכבר היה קרב מהם החלב והדם לשם יתעלה ואולם אחר שארך הזמן וסרו ישראל מהמנהגים הפחותים אשר הסתבכו בהם בהיותם במצרים מאכילת הדם והחלב אז הותר להם בשר תאוה כמו שיתבאר במה שיבא והנה אמרה התורה אשר יצוד ציד חיה או עוף לפי שהנהוג בהם שהם נצודים והוא מבואר ממה שביארנו שכבר ינהג זה הדין בהם אע"פ שלא צד אות' הוא בעצמו כאלו תאמר שנתנו לו במתנה או שקנאם וראוי שנדע שלא ינהג זה הדין אלא בחיה ובעוף הטהורים שנאמר אשר יאכל ולפי שלא ביארה התורה אסור חלב בחיה ובעוף כי אם בבהמה במקום שזכרה אסור דם בבהמה ובעוף ר"ל בפרשת צו הנה למדנו מה שאין אסור חלב נוהג בחיה ובעוף וכבר יתבאר מעצם הענין שאין להם חלב אבל הוא שומן מטבע השומן וראוי שנדע שלא ינהגו כסוי הדם כי אם בשחיטה המותרת באכילה שנאמר אשר יאכל ובכלל הנה כאשר לא יותר לאכול מהבשר בסבת השחיטה כ"ש שיתרחקו מלאכול הדם ולזה לא יצטרכו לכסוי הדם כי עם שהוא אפשר ג"כ שהיה ממנהגיהם הפחותים שיצודו חיה או עוף להיותם מדבריים ויחשבו שיהיו השדים מזה הצד יותר מתייחסים להם ולזה היה ממנהגיהם שישפכו דמם במקום אחד והיו אוכלין הבשר סביב הדם ההוא והיו חובים שיבאו שם השדים לאכל הדם כי הוא מזונם לפי מחשבתם ובזה האופן תשלם האהבה להם עם השדים ויודיעו להם העתידות ולזה אמר לא תאכלו על הדם ואחר כן אמר לא תנחשו ולא תעוננו כמו שיתבאר במה שיבא וכבר זכר זה הרב המורה רצוני לומר שכבר היה ממנהגיהם הפחותים לאכול על הדם לזאת סבה כמו שראה בספריהם הקודמים ולזה גם כן לא היה נוהג כסוי הדם בחיה ועוף ולפי שהתכלית היה לאכול הבשר סביב הדם לזאת הסבה שזכרנו הנה כשלא היה הבשר נאכל לא יתחייבו בכסוי וראוי שנדע שצריך שיהיה עפר למעלה ועפר למטה שנאמר ושפך את דמו וכסהו בעפר ר"ל שישפוך את דמו בעפר ויכסהו בעפר והנה בזה האופן גם כן תעמוד התורה כנגד הכונה ההיא וזה שכאשר ישפך הדם לא ימצא שם במורגש אבל יהיה נבלע בעפר והוא מבואר שכל מה שיקרא עפר בלשון קודש יתכן לכסות בו את הדם:
@634 **כי נפש כל בשר דמו בנפשו הוא.** ר"ל שנפש הבשר וחיותו הוא באמצעות הכח אשר בנפשו להזות דמו ולזה יחדו השם יתע' לכפר על הנפש וכדי שיתיישב יותר בלב האנשים שהכפרה תשלם בזה ראוי שיהיה ענינו מרוחק האכילה כי אם יאכלוהו לא יחשבו בו יתרון על הבשר הזה ובכלל הנה השתנות המזון אל הדם הוא מבואר שהוא מפועל הנפש כי אל ימצאו הדברים המזוניים נהפכים לדם עם הפסדם אם לא כשיזון מהם הב"ח ולא היה בזה מופת על מציאו' הנפש כי אין מדרך החום שימשך ממנו זה אם לא היה חום נפשיי ולפי שאלו הדברים היו להעיר על מציאות הצורה כמו שזכרנו במה שקדם הנה הגבילה התורה ענין הדם בזה האופן:
@635 **וכל נפש אשר תאכל נבילה וטרפה.** ראוי שתדע שאין הרצון באמרו נבלה וטרפה נבלה או טרפה כי הטרפה לא תטמא אם לא היתה עם זה נבלה לא הטרפה השחיטה כמו שהתבאר בפרשת ויהי ביום השמיני בב"ח אשר טומאתו יותר חמורה אמר וכי ימות מן הבהמה אשר היא לכם לאכלה למדנו שהשחיטה אינה מטמאה ולזה יהיה הרצון בזה שתהיה נבלה וטרפה יחד ולפי שהיתה טרפה אינו סבת הטמאה ואין לו רושם בה כמו שהתבאר מדברנו מזה המקום הנה לא יהיה התנאי בזאת הטמאה שתהיה טרפה אבל תטמא גם כן בזה האופן אם היתה נבלה לבד וזה מבואר מאד ואמנם זכרה התורה נבלה וטרפה להורות שהיא תדבר במין מהב"ח שאפשר שיהיה בו נבלה וטרפה יחד והוא המין הטהור כי בב"ח הטמאים לא תנהג טרפה ולפי שזאת הנבלה לא נזכר בה שתהיה מטמאה במגע ובמשא אבל תטמא כשתאכל הנה אינה הנבלה המטמאה במגע ובמשא הנזכרת בפרשת ויהי ביום השמיני עם שאם היה העניין כן הנה זה כפל ומותר ולזה הוא מבואר שאין זאת הנבלה אינה נבלת חיה ולפי שהוא זכר בזה המקום החיה והעוף אשר יאכל למדנו שבנבלת עוף טהור מדבר והוא אינו מטמא כי אם בזה האופן בהיותו בבית הבליעה לא קודם זה ולא אחר שירד משם וכבר ביארנו הסבה למה לא יטמא העוף הטהור כי אם בזה האופן בפרשת שמיני וראוי שיתבאר שאם יהיה בבית הבליעה כשיקיא אותו שאינו מטמא כי אין זו נקראת אכילה אבל הוא מקביל לאכילה:
@636 **ואם לא יכבס ובשרו לא ירחץ ונשא עונו.** ר"ל שיתחייב כרת ולפי שאי אפשר שיתחייב כרת על הטמאה אם אכל קדש או נכנס במקדש בהיותו טמא הנה יהיה הרצון בזה שאם יאכל עם זה קודש או יכנס למקדש בהיותו טמא קודם הטהרו מזאת הטמאה יתחייב כרת:
@639 **כמעשה ארץ מצרים אשר ישבתם בה לא תעשו.** הנה ירא' מלשון התורה בזה שמנהגי ארץ מצרים ונימוסיהם בעניין העדיו' היה בתכלית מהגנות וכן הענין במנהג ארץ כנען ונימוסיהן בענין העריות ולזה הזהירם הזם יתעלה שלא ינהגו בכמו אלה המנהגים הפחותים ההם כמו שאמר בסוף זאת הפרשה אל תטמאו בכל אלה כי בכל אלה נטמאו הגוים אשר אני משלח מפניכם:
@641 **אשר יעשה אותם האדם וחי בהם.** ר"ל שמדרך משפטי השם יתעלה וחקותיו שיהיה חיי האדם בהם כי הם מישרים לשלמות הנפש שהוא החיים הנצחיים עם שכבר ימצא בהם תועלת גם כן באלו החיים הגופיים כמו שנתבאר בהרבה מהמצות:
@642 **איש איש אל כל שאר בשרו לא תקרבו לגלות ערוה.** ראוי שתדע שבזאת ההזהרה תועלת במדות ותועלת בעיון אמנם התועלת אשר בעיון בזה היא הערה שאין המבוא אשר בהולדה לזכר ולנקבה בהדרגה אחת ולזה הזהירה התורה שתהיה הנקבה שאר בשר הזכר כי שאר הבשר יחשב היותה מטבע אחר לפי שחצבו מצור אחד וכבר התבאר בטבעיות שיש הבדל נפלא בשה בין הזכר והנקבה והוא שזרע הזכר הוא הפועל בהולדה והנקבה תתן החומר שהוא המתפעל בהולדה ואמנם התועלת אשר במסות בזה זכרו הרב המורה והוא שאלו הנקבות שהם שאר בשר אם היו מותרות לאדם הנה לרב מציאותם אצלו ולחוזק האהבה אשר ביניהם בטבע יקרה שיהיו נשמעות אליו תמיד ויבא אליהן גם בזולת אישות ואע"פ שיהיו לאיש אחר ויגיע מזה הפסד נפלא בדברים הטבעיים המדיניים עם שכבר ישחית עצמו מצד רבוי המשגל וראוי שתדע כי גלוי הערוה ישלם בפתיחת הרחם כי אז יתגלה הנסתר והפתיחה ההיא תשלם בהכנסת העטרה לבד ואעפ"י שלא נגמרה הביאה והנה תמצא במקומות שכונה התורה שתהיה בשכיבה שכבת זרע כמו שתראה בשפחה חרופה בפרשת קדושים אמר ואיש כי ישכב את אשה שכבת זרע ואולם בזה המקום לא זכרה כי אם גלוי ערוה לתוספת הרחקה בזה כי אפילו בתחלת הביאה יתחייב כרת וראוי שתדע שזאת השכיבה תהיה אם כדרך הנקבות אם בזולת דרך הנקבות שהרי אמר בזה העניין ואיש כי ישכב את זכר משכבי אשה להעיר שהמשכב ההוא גם כן משכבי אשה ואם אינו עושה פרי ולפי שגלוי הערוה הוא התחלת הביאה הנה לא יהיה גלוי הערוה אלא במי שתתכן בו הביאה והוא בזכר מבן ט' שנה ויום אחד ומעלה ובנקבה מבת ג' שנים ויום אחד ומעלה כמו שהתבא בשרשים הכוללים ומזה המקום יתבאר שאם גלה ערוה בזולת קושי לא יתחייב כרת כי אין זה הענין התחלת ביאה והוא מבוא מזאת האזהרה שהקרב לאחת מהעריות קריבה המביאה לגלות הערוה עובר בלאו אבל לא יתחייב כרת אם לא גלה ערוה שהרי אמר בסוף הפרשה כל אשר יעשה מכל התועבות ונכרתו הנפשות העושות למדנו שלא נתחייב כרת אם לא עשה מעשה לא על השתדלותו לעשותו ואמנם הזהירה התורה בזה להוסיף הרחקה בזה הענין:
@643 **ערות אביך וערות אמך לא תגלה.** הרצון בערות אב משכב זכור ויתחייב עליו משני צדדין האחד מפני שהוא משכב זכור והשני מפני שהוא ערות אב ואם עשה זה בשוגג יתחייב שני חטאות כי כבר חייב על הזדון כרת כמו שהתבאר אחר זה והרצון בערות אם בין כדרכה בין שלא כדרכה וכן הענין בשאר העריות וכן אם היתה אמו עם זה אשת אביו יתחייב עליה ג' חטאות משום אשת איש ומשום אשת אב ומשום אם כמו שיתבאר במה שיבא אח' זה:
@644 **ערות אשת אביך לא תגלה.** ר"ל אף על פי שאינה אמו והיא נקראת אשת אב משנתארסה ואע"פ שמת האב מן הארוסין יתחייב עליה משום אשת אב ואולם אנוסת אביו ומפותת אביו אינה אסורה לו משום אשת אב כי אינה אשתו:
@645 **ערות אחותך בת אביך או בת אמך מולדת וגומ'.** אחשוב שמולדת בית היא ההולדה ר"ל שתהיה לאשה מאישה ומולדת חוץ היא ההולדה שתהיה לאב ממי שאינה אשתו או ההולדה שתהיה לאם ממי שאינו אישה וביארה התורה שאע"פ שהיא אחותו בזנות או בממזרות בין מן האב בין מן האם יתחייב עליה משום ערוה וזהו מה שלמדנו באמרו או מולדת חוץ:
@646 **ערות בת בנך או בת בתך לא תגלה ערותן כי ערותך הנה.** הנה יתבאר ממה שאמר כי ערותך שכבר יתחייב אם גלה ערות בתו אבל היא יותר ראויה בזה כי היא יותר אמתית בעניין שאר הבשר וזה ממנהג התורה כמו שהתבאר מהשרשים הכוללים:
@647 **ערות בת אשת אביך מולדת אביך.** ר"ל שתהיה נולדת מאביו שאם לא היה הענין כן כבר תהיה מותרת לו אם לא היתה אמו אשת אביו הנזכרת בזה המקום וכבר יתחייב עליה משום בת אביו כשהיתה אשתו ואולם אם היתה בת אנוסת אביו או מפותת אביו לא יתחייב עליה משום בת אביו אבל יתחייב עליה משום אחותו מן האב:
@648 **ערות אחות אביך.** ביאר שאחות האב ואחו' האם הם ג"כ אסורות משום ערוה כי הם שאר אב או אם ערות אחי אביך לא תגלה. ר"ל למשכב זכור ויתחייב עליה משום משכב זכור ומשום ערות אחי האב. אל אשתו לקרב:
@650 **דודתך היא.** ר"ל שלא יקרה אליה לגלות ערוה והוא מבואר מצד הוראת הגדר שלא יקרא אחי האב סתם אלא כשהיה אחיו מן האב לא כשהיה אחיו מן האם ולא מן האב וכבר יתבאר בפרשת יבמה ועוד כי מפני שמנעה אחות אב ואחות אם ימנע אחי אב ולא אחי אם הנה יראה שלא מנע אלא מי שהוא אחי האם מן האב לא מי שהוא אחי האם מן האם ועוד שהוא מבואר שלא תקרא דודתו אשת אחי האב מן האם:
@651 **ערות כלתך לא תגלה אשת בנך היא.** הטעם לפי שהוא ערות הבן הוא שאר בשר:
@652 **וערות שאר אחיך.** הוא לפי שנתן הסבה בזה שהיא ערות אחיו ומצאנו בערות אחותו שהשוה אחותו מאביו לאחותו מאמו. הנה יתבאר שזה הדין ינהג גם כן באשת אחיו מן האם:
@653 **ערות אשה ובתה לא תגלה את בת בנה ואת בת בתה לא תקח לגלות ערותה.** הרצון בזה שיהיה לו אישות עם אחת מהם ולזה אמר לא תקח ומפני האישות ההוא נאסר עליו האחרת מפני שהוא שאר אשתו כמו שאמר שארה הנה זמה הוא וכזה תמצא באחות אשתו שאמרו בה לא תקח להעיר כי מפני נשואי אשתו נאסרה על האחת ובזה תמצא בפרשת קדושים שאמר לשון קיחה בזה הענין אמר האיש אשר יקח את אשה ואת אמה זימה היא ולא תמצא לשון קיחה בשאר העריות ולזה יראה במה שאין ספר בו שתהיה אחד מהן אשתו ולזה אמר בפרשת תבא ארור שוכב עם חותנתו ואין לאומר שיאמר שיקח שתיהן לנשים ואז יתחייב כרת כשיגלה ערו' השנית שאם נתחייב כרת כשגלה ערותה אחר שלקחה לאשה כ"ש שהוא ראוי שתאמר לו כשלא לקחה לאשה ולזה הוא מבואר שאין לו לקוחין כי אם עם אחת מהן ובעבורה נאסרה לו האחרת וזה שאם היתה היא אשתו הנה נתחייב כרת אם יגלה ערות בתה או בת בתה או בת בנה וכן אם היתה בת הבת אשתו הנה תאסר עליו חמותו ואם חמותו ותאסר עליו גם כן אם חמיו לפי שאשתו היא בת בנה ולזה הוא מבואר שהאונס אשה או המפתה אשה לא תאסרנה עליו קרובותיה לפי שאין לו אישות בה:
@654 **ואשה אל אחותה לא תקח לצרר.** ר"ל כשנשא אשה לא ישא אחותה באופן שתהיין צרות זו לזו ויגלה ערותה על ערות אשתו בחייה אמנם אחר מות אשתו תותר לו אחות אשתו מה שאין כן בשאר קרובות אשתו הנזכרות בפסוק הקודם וראוי שנדע שאין הבדל באחות אשתו בין היותה אחותה מן אביו או מאמה שכבר תמצא בפרשת קדושים שנקראת אחות סתם מי שהיא אחות מן האב או מן האם אמר ואיש אשר יקח אחותו בת אביו או בת אמו וגו'. ערות אחותו גלה:
@655 **ואל אשה בנדת טמאתה לא תקרב לגלות ערותה.** הנה זה כולל טמאת היולדת שהרי נאמר בה כימי נדת דותה תטמא וטמאת שבועים כנדתה וטמאת זבח קטנה וזבה גדולה שהרי נאמר כל ימי זוב טמאתה כימי נדת דותה תהיה ויתבאר שכל זמן שלא טבלה ינהג זה האסור לפי שטהרתה תלויה בטבילה לא בימים וזה עם שהוא מבואר בנפשו יתבאר מטמאת נבלת עוף טהור שהוא טמאת ערב ועם זה אמרה התורה בפרשה הקודמת ואם לא יכבס ובשרו לא ירחץ ונשא עונו אף על פי שארך הזמן אחר זה כיון שלא טבל עדין הוא בטמאתו ומזה המקום יתבאר שהבא על אשתו והרגישה שכבר ראתה דם אסור לו להכניס האבר או להוציא כי הכנסה וההוצאה הם גלויי ערוה והם מעניין הביאה ולזה ראוי שיתעכב וישים לבו לדבר אחר עד שיסור קושי האבר ואז יוציאהו כי זה אינו נכנס בגדר גלוי הערוה:
@656 **ואל אשת עמיתך לא תתן שכבתך לזרע לטמאה בה.** ראוי שתדע שאמרו לזרע איננו תנאי עד שאם לא יוציא זרע לא יתחייב אבל יתחייב כיון שנתן בה שכבתו אף על פי שלא הוציא זרע שכבר נאמר בפרש' כי תצא כי ימצא איש שוכב עם אשה בעולת בעל ומתו גם שניהם ואמנם אמר לזרע להורו' שהשכיבה שאין מדרכה שתהיה לזרע לא יתחייב עליה כאלו תאמר אם הכניס האבר מת והוא באופן שלא יתכן בו הקשי:
@657 **ומזרעך לא תתן להעביר למולך ולא תחלל את שם אלהיך.** כבר התבאר לפי הוראת הגדר כי מולך היתה ע"ז עובדים בה האש והאב נותן מקצת זרעו לכומרי ע"ז ההוא וברשותם יעבירהו ברגליו תוך האש וידמו שבעבודה הזאת כרת ברית עם ע"ז ההיא בתתו מזרעו לה ולזה ידמה שלא היו מעבירים שם כי אם קצת זרע ואחשוב שתהיה הכונה בזאת לעובד מאדים כי הוא אשר ישלוט על הויות האש השורף כמו שנזכר במשפטי הככבים ויתבאר מאד מן החוש ולפי שהוא יורה על המשגל המגונה כשיכונו אל כונה זו זכר בזה המקום כי הוא יזכור אחר זה משכב הזכור והבהמה אשר בתכלית הגנות והנה אפשר שזאת הע"ז היתה מחקות המצריים או הכנענים שזכר ולזה זכרה בזה המקום והוא אפשר עוד שתהיה הכונה בזאת הע"ז שאין שם סבה צוריית אבל הפעולות שנראה לנמצא נמצא הם מצד החום אשר לו עד שתהיה ההזנה מצד החום מזולת נפש כמו שחשבו קצת הקודמים ולזה חשבו שיהיה אלוה מי שהוא התחלת החום אשר בנמצא נמצא ומה שהוא בזה התאר הוא היותר אמתי בחום ולזה היו עובדים אותו והוא מבואר שבעלי זאת האמונה לא יאמינו במציאות הנפש כ"ש שלא יאמינו בהשארותה ולזה לא יגדרו עצמם בכמו אלו הגדרים התוריים אבל ישתדלו בהשגת ההנאות לבד כי אין שם תכלית אחרת לפי זה הדעת ואפשר עוד שזכרו בזה המקום להורות על חוזק גנות אלו העריות שיזכיר עד שהוא מתיחס בגנותו לגנות ע"ז וזה כי כאשר ישכב את זכר שהו' משכב בלתי עושה פרי יורה שהוא לא יתן לא לבו להשיג מה שהיה מן החסד והחנינה במה שנתן השם יתעלה מן הכח בזה הזרע ולזה לא ישתמש בתועלת הנפלא המיוחס לו וכן העניין כמי שיתן שכבתו בבהמה והוא מבואר שמי שמנהגו זה המנהג ר"ל שלא יחקור מה שהיה מן החכמה והסדר והיושר באלו הנמצאות השפלות לא תשלם לו השגה שתהיה בכאן סבה פועלת וצוריית ויבא מפני זה לכמו אלו הדעות הנפסדות עם שהנטיה החזקה להנאות זה החוש בזה האופן תמנעהו מההשתדלות בהשגת שום מושכל ויפול מפני זה ביותר פחות מהדעו' הנפסדות באלו ביארה התורה שלא נקל באלו האזהרות כי המרותנו בהם אפשר שיבא לזאת העברה הנפלאה:
@658 **ואת זכר לא תשכב משכבי אשה תועבה היא.** ר"ל שזה הענין הוא נתעב מצד עצמות:
@659 **ובכל בהמה לא תתן שכבתך לטמאה.** ראוי שתדע שזה הדין שוה בבהמה ובעוף כי הגנות בכלם אחד ואמנם זכר בהמה להיותה יותר קרוב מטבע האדם משאר הב"ח והנה אין הבדל בבהמה בין הגדולה לקטנה שנאמר וכל בהמה וכיון שהערה בה או שהערת בו חייב אם היה גדול כי משכב כולל המשכב אשר כדרך והמשכ' אשר לא כדרך כמו שקדם:
@659 **ואשה לא תעמוד לפני בהמה לרבעה תבל היא.** ר"ל דבר בלי והשחתה להשתמש בכח האנושי להולדה בזה האופן הנפסד שאם היה שתהיה ממנו הולדה לא יהיה הנולד אדם כמו שלא יהיה הנולד מסוס ואתון ולא חמור אבל מין אחר שעם זאת הולדה גם כן תכלה אל מין אחר בלתי מוליד כמו שהתב' בספר ב"ח והוא מבואר שהאדם גדול המעלה מאד ביחס אל הבעלי חיים האחרים ולזה ראוי שיגיע ענש נפלא למי שישתמש במה שהכין הטבע להיות ממנו אדם אל שיהיו ממנו שאר ב"ח:
@660 **אל תטמאו בכל אלה.** ר"ל באי זה שיהיה מאלה כי כן מנהג לשון הקדש אמר וכל דם וכל חלב שור וכבש ועז לא תאכלו והנה ביארה התורה שאלו המעשים המגונים האלו היו סבה לאבדן האמות ההן ולהקיא הארץ יושביה כי לולי רשעת הגוים ההם לא היה מסכים השם יתעלה לאבדן ולגרשן כדי להטיב לישראל כי זה יהיה עול בחק השם יתע' ולפי ששב לכלול בזה הגר שב להזכיר כי גם הגרים בארץ הגיע להם הענש בסבת הפעולות המגונות ולזה אמר כי את כל התעבות האלה עשו אנשי הארץ כי גם הגרים יקראו אנשי הארץ ואמנם תחלה זכר האזרחים במה שאמר כי בכל אלה נטמאו הגוים אשר אני משלח מפניכם כי הגוים אשר בארץ הם האזרחים שהם לגוי אחד ומשפחה אחת כאלו תאמר החתי והאמורי ומה שידמה להם מאלו האמות:
@664 **ולא תקיא אתכם וגו'.** קבלתי בפרוש זה הפסוק מהרב אדוני אבי ז"ל ולא תחשבו שיהיה זה העש המגיע לכם בה שתקיא אתכם כאשר קאה את הגוי אשר לפניכם אבל יתחייבו כרת הנפשות העושות איזה דבר שיהיה מכל התועבות האלה וזהו ההפרש בין העונש שיגיע לכם בזה ובין הענש שהגיע מזה לגוים ההם וכבר יסתפק מספק ויאמר שהו' ראוי שיהי' הענש המגיע מזה לישראל יותר עצום למעלתם כי כל מה שהיה החוטא יותר נכבד היה ראוי שיהיה ענשו יותר חזק וזה הפך מה שיראה מה המאמר ואנחנו אומרים בהתר זה הספק כי אלו האומות התנהגו בכללם באלו הפעולות המגונות ובזולתם ולזה היו ראוים לכמו זה הענש הנפלא ולולי הסתבכם בהם כלם לא הגיע להם זה העונש הכולל ולזה ארך זמנם עם רוע מנהגיהם כמו שאמר כי לא שלם עון האמורי עד הנה ואולם ישראל יענשו אף על פי שלא יחטאו בזה כי אם איש אחד ופעם אחת בשתכרת נפש החוטא ההוא ואמנם שאר האנשים אשר יהיו בקצת עלו המעשים המגונים ע"י ב"ד יתבארו בפרשת קדושים תהיו ושם יתבאר כי כאשר הסתבכו ישראל באלו הפעולות תקיא אותם הארץ אמר ושמרתם את כל חקותי ואת כל משפטי ועשיתם אותם ולא תקיא אתכם הארץ וזה מורה שאם לא ישמרום תקיא אותם הארץ ולזה אחשוב גם כן שתהיה הכונה בזה המקום שישמרו משמרת השם לבלתי עשות מחוקות התועבות האלה כדי שלא תקיא הארץ כאשר קאה את הגוי אשר לפניהם כי זה יקרה להם כשיחטאו בזה רבים מהם והוסיפה התורה להזכיר עונש אחר יקרה לאיש ואיש אשר יחטא בהם והוא הכרת הנפש ההיא ויהיה אמרו כל אשר יעשה וגו'. כאלו יאמר ראוי שתשמרו משמרתי לבלתי חטאו באלו הפעלות המגונות כי כבר יגיע זה העונש לאיש ואיש שיחטא בזה וזכרה תחלה הענש הכולל שיקרה לכלל האומה אם יסתבכו באלו הפעולות ואחר זכר העונש הפרטי שיקרה למי שיחטא בזה היה פרט או כלל ובכאן נשלם ביאור זאת הפרשה:
@687 **קדושים תהיו כי קדוש אני יי' אלהכם.** רוצה לומר שתתקדשו מחסרונו' החומר ותפרדו מעניינו בתכלי' מה שאפשר לכם ובזה תדמו לו לפי מה שאפשר כי אני נבדל מחמר ונקי ממנו בכל האופנים:
@688 **איש אמו ואביו תיראו.** צוה במורא ההורים כי בזה תועלת נפלא לקבל האדם מוסרי התורה וזה כי ההורים יסרו זרעם ויקנו להם המוסר אשר ישמרו בו מהשחית עצמם וזולתם כי זאת התכונה היא להורים בטבע לאהבת זרעם ולזה ישמרו בכל האופנים שאפשר שלא יוזקו מצד רוע מנהגיהם בפעולותיהם ושלא יזיקו זולתם לשמרם שלא יזיקום ועם זה ג"כ ייסרום שלא יטו אל רוב המאכל והמשתה כדי שלא ישחיתו קנייניהם וזה כלו נמשך הוא לכוונת התורה אמר כי באשר ייסר איש את בנו יי' אלהיך מיסרך ולזה התחיל שלמה בספר משלי להזהיר על זה המוסר אמר שמע בני מוסר אביך ואל תטוש תורת אך ולהיות מוסר ההורים הישיר לקבול מוסר התורה הפליגה התורה בעונש הבן שלא יקבל מוסר ההורים כמו שיתבאר בדין סורר ומורה על שבזאת המצוה תועלת נפלא להישיר האדם ליראת השם יתע' וזה שאם צוונו לירא מההורים לפי שכבר היו כלי מה שתולדתינו כל שכן שיותר ראוי לאין שיעור לירא מהשם יתעלה שהוא סבה האמתית במציאותינו ובמציאות ההורים וזה שלא נוכל לייחס הויתנו עם מה שבה מיתרון החכמה אל זר האב והאם כי לא נמצא בהם אומנות בזה המעשה עד שיכונו לעשות האברים בזה האופן הנפלא שהם עליו. ולזה יחוייב שיהיה הפועל האמיתי באלו ההויות שכל משיג מה שיעשהו כמו שביארנו בספר מלחמות יי'. והתבאר עוד במה שאחר הטבע. והנה יראת ההורים הוא לעשות מה שיצוו לעשות ולהשמר ממה שיזהירו מעשותו וכן יהיה מיראתם שלא לחלוק על דבריהם וכן תהיה מיראתם לשום מעלה גדולה בנפש ולזה יחוייב שלא יקל לשבת במקומם או לעמוד במקומם והוא מבואר שלא יחוייב מפני יראת ההורים לעבור את דברי השם יתע' כשיצוו על זה וזה כי יראתנו אותם הוא מפני מצות השם יתע'. ולזה ראוי שנירא יותר מהשם יתע' והוא מבוא גם כן שהאשה אחר שתנשא לא תמשול על זאת המצוה כי היא מוכרחת לעבוד בעלה ולזה לא ימשול האב להפר נדריה בהיותה בית איש אבל ימשול עם זה אישה כי היא מוכרחת להמשך לרצונו כמו שיתבאר בפרשת ראשי המטות:
@688 **את שבתותי תשמורו.** העירנו בזה כי ביראת ההורים תועלת במדות ובדעות כמו העניין בשמירת שבתות השם יתעלה שיש בהם תועלת במדות ובדעות כמו שביארנו במצות שבת. ויתבאר עוד במה שיבא בשאר המועדות:
@689 **אל תפנו אל האלילים.** רוצה לומר שלא תפנו במחשבתיכם לענין האלילים שיהיה זה סבה שתזנו אחריהם והנה קרא הע"ז אליל להורות שאין בה ממש אבל הוא כמו הדבר שאין לו מציאות:
@689 **ואלהי מסכה לא תעשו לכם.** לפי שכבר אמר בפרשת יתרו לא תעשה לך פסל וכל תמונ אשר בשמים ממעל ואמר בזה המקום ואלהי מסכה לא תעשו לכם. הנה נלמד ביאור זה הענין מהעניינים הנמשכים לו וזה שבפרשת יתרו אמר תחלה לא יהיה לך אלהים אחרים ואח כך אמר לא תשתחוה להם וזה מורה ששם הורה על עשיית הפסל לא לעבדו. ובזה המקום לפי שסמכה אל העניין שהוא תוספת קדושה והוא אמרו אל תפנו אל האלילים הנה תהיה הכונה בזה שלא יעשה אלהי מסכה אפילו לזולתנו וזה כי גם הצורות שהם לנוי מנעה התורה שלא נעשם לנו כמו שהתבאר מאמרו ואלהי מסכה לא תעשו לכם ולזה הוא מבואר שנמנע ממנו מעשיית אלהי מסכה לנוי שאם היה לעבדו הנה הוא נכלל באמרו לא תעשה לך פסל ואם הוא לנוי נכלל באמרו ואלהי זהב לא תעשו לכם. ולזה תהיה הכונה בזה המקום שנזהר מעשיית אלהי מסכה גם לזולתינו והנה אמר לכם כי מדרך עושה מלאכה שינתן לו שכר עליה ולזה הוא עושה אותו בעבורו לא בעבור בעל המלאכה ורצתה התורה בזה אף על פי שלא נכוין בזה הפועל בעבור עבודה זרה אבל בעבורנו והוא לקחת שכר מזה המעשה הנה עם כל זה הוא אסור וזהו תוספת הקדושה אשר בזאת האזהרה וכי תזבחו זבח שלמים ליי'. אותם כבר נתבאר זה הדין מהשלמים בפרת צו ומשם יתבאר כי אמרו ואם האכול יאכל מבשר זבח השלמים ביום השלישי רוצה לומר אם יחשוב עליו שיאכל ביום השלישי על יד המקריב אותו באופן שביארנו שם:
@694 **ובקוצרכם את קציר ארצכם לא תכלה פאת שדך לקצור.** צותה התורה בזה לחונן הדלים ממה שהשפיע השם יתעלה לאדם מן הטובות והנה יקל לאדם להניח להם מעט מהקמה כי זה ממה שלא החזיק בו עדיין וכן הענין בשאר המתנות האלו שזכר בזה המקום ואולי אם ימתין עד בא קצירו ותבואתו לידו יקשה בידו לתת לו זה אבל על כל פנים אם לא הניח הפאה באופן שצותה התורה או הלקט או העוללות או הפרט כבר תחייב לתת לעניי ממה שבא בידו מזה שנאמר לעני ולגר תעזוב אותם הנה הוא מצוה לעזבם על כל פנים לעני ולגר והנה הפאה הוא לפי מה שיורה עליו הגדר בסוף השדה כי הוא מה שתכלה אליו הקציר והוא מבואר מצד עצם הענין שבאי זה מקום שתכלה הקציר' וכל להניח פאה אף על פי שהוא באמצע שדהו כי לא דקדקה התורה אלא שיניח קצת מהקמה לעניים ואין הבדל לעניים בין היותר באמצע השדה או בסוף השדה והנה הקצירה תאמר על מה שילקט כלו כאחד והוא אוכל ומכניסו לקיום וגדולו מן הארץ כמו תבואת השדה והוא מבואר עוד שהוא בלתי נוהג במה שאין לו בעלים כמו ההפקר שנאמר פאת שדך ומזה יתבאר שזה בלתי נוהג בשדה הקדש ובשדה הנכרי שאין אני קורא בהם שדך וראוי שיובן מזה שכן הדין במה שיתלש יחד כי התלישה בו דומה לקצירה בתבואת השדה ואמנם זכרה התורה התבואות הנקצרות כי זהו היותר נהוג. והנה נדר הקצירה היא לקיטת התבואות על ידו או על יד שלוחו לתכלית שיאסף זה אל ביתו אמנם מה שישחית הבעלי חיים או ילקטו אותו הלסטים לעצמם או שישחת באון אחר לא יקרא קצירה. וכן לא יקרא קצירה אם קצר זה קודם שתהיה התבואה ההיא ראויה לקצור באופן מהאופנים אבל יהיה השחתה לא קצירה והוא מבוא עוד שאין ראוי שיניח מן השדה על חברתה כי אין זה פאת השדה הנקצרת והוא מבואר שמאלו המתנות אין בהם דבר לכהנים וללויים אבל הם לעניים שנאמר לעני ולגר תעזוב אותם וראוי שתדע שכאשר יגיע העת שלא ילכו העניים עוד לבקש בשדות ובכרמים אלו המתנות יוכלו הבעלים ללקחם שאם יעזבו אותם שם לא יהיו לעני ולגר אבל לעורבים ולעטלפים וכיוצא בהם וזה הפך כוונת התורה:
@694 **ולקט קצירך לא תלקט.** הנה לקט הוא לפי הוראת הגדר מה שיפול מתך ידו בלקטו השבולים הנקצרות או הנופל מתוך המגל שהוא כלי ללקט כאלו תאמר שנשארה שם שבולת אחת או שתים שלא נקצרו ולא נשאר סביב דבר יקצרו עמו ואולם בזולת זה האופן לא יהיה לקט והנה הוא שבולת אחת או שתים יחד אבל אם היה יותר מזה הנה הוא קציר לא לקט הקציר והוא מבואר מצד הוראת הגדר:
@695 **וכרמך לא תעולל.** רוצה לומר שלא תקח העוללות והנה העוללות הם מגזרת עולל שהוא קטן והם לפי הוראת הגדר הענבים חסרי ההווייה שאין משדרתם מסתעפים אשכולות ואין גרגיריהם מתקבצים זה על זה כגון העניין בענבים השלמים אבל גרגיריהם מפוזרים והנה יתבאר מזה שאפי' היה הכרם כלו עוללו' הנה הוא לעניים:
@695 **ופרט כרמך לא תלקט.** פרט הם הגרגרים הנפרטים מהענבים בעת הבצירה וזה כנפרט ממנו מה שאין בעל הבית מקפיד לו לפי הנהוג כמו אם נפרט גרגיר אחד או שנים מאחד מהענבים לא יותר מזה ולזה ראוי שלא ישימו הבוצרים הסל תחת הענבים בעת הבצירה כדי שיפול שם הפרט והוא מבואר שזה הדין יהיה בלקיטתם הענבים בסל ואולם אם שמו הענבים בקרקע בעת הבצירה וחזרו ולקטום משם יהיה פרט אפילו אשכול כי ממנהגם שלא יקפידו האנשים בזה כשיהיה בזה האופן וזה מבואר מן החוש והיה זה כן כי יחסו קטן אל מה שלקטו משם ולזה יקלו האנשים בזה כשהיתה הלקיטה בזה האופן וכבר יתבאר שלמות אלו הדינין בפרשת כי תצא:
@695 **לעני ולגר תעזוב אותם.** ראוי שתדע שהקציר בא לפי הנהוג משנה לשנה ומי שאין לו מהענינים מה שאפשר שיסתפק בו שנה אחת הוא הנקרא עני לזה הענין וזה מבואר מאד כי מה יעשה זה שיש לו כדי פרנסת קצת השנה הימצאו לו אלו המתנות בעת שתחסר לו פרנסתו. והנר הוא גר צדק שקבל עליו לקיים כל התורה וזכרה אותו התורה לפי שיתכן יותר שיהיה עני כי אין לו חלק ונחלה בארץ לפי מה שיתבאר כי מה שיקנה מן הקרקעות ישוב לבעליו בעת היובל:
@696 **לא תגנבו.** היא האזהרה על גנבת ממון וזה יתבאר מהענינים הנלוים לו וכבר נתבאר העונש על גנבתו בפרשת ואלה המשפטים:
@696 **ולא תכחשו.** מפני שהזכירה התורה בפרשת ויקרא העונש על מי שכחש בעמיתו בפקדון או בתשומת יד או בגזל ונשבע על שקר כי האזהרה בזה המקום שלא לכחש ושלא לשקר רוצה לומר שאם כחש לא ישבע על זה לשקר וכבד נתבאר שם העונש:
@697 **ולא תשבעו בשמי לשקר.** הוא האזהרה מעבור על שבועת בטוי שנתבאר העונש בזה בפרשת ויקרא ונתבאר בזה המקום שכבר יעברו על השבועה אף על פי שאינה בשם המיוחד כיון שהיא בשם מהשמות שנקרא בהם השם יתעלה שנאמר ולא תשבעו בשמי לשקר בכל שם שהוא שמי:
@697 **וחללת את שם אלהיך.** הוא מבואר ששבועת שקר הוא חלול הש"י שאם היתה גדולה מעלתו אצל הנשבע כראוי היה נשמר תכלית השמירה שלא ישבע בשמו הנכבד לשקר:
@698 **לא תעשוק את רעך ולא תגזול.** הנה הגזלה הוא דבר הנגזל בעין מיד הבעלים בחזקה כמו שאמר ויגזול את החנית מיד המצרי והעושק הוא מה שיכבוש האדם מזולתו בחזקה ולא ירצה להשיבו לו כאלו תאמר שיכבוש שכר שכיר או הלואה או פקדון וכבר נתבאר בפרשת ויקרא שכבר יתחייב להשיב הגזלה או העושק עם שהוא מבואר בנפשו:
@698 **לא תלין פעולת שכיר אתך עד בקר.** הנה הלנת פעלת שכיר לא תהיה בשכיר לילה כי לא נתחייב לו השוכר שכירותו עד סוף הלילה ולזה תהיה זאת ההלנה בשכיר יום יום ונתנה התורה זמן לבעלים לפרוע השכיר עד סוף הלילה ומשם ואילך יתחייב בלא תעשה ומזה המקום יתבאר שכר שכיר לילה גובה כל היום עד הלילה ובבא הלילה יעבור עליו בלא תעשה כי היחס אחד ועליו אמרה תורה במה שיבא ביומו תתן שכרו:
@699 **לא תקלל חרש.** היא האזהרה שלא לקלל אחד מישראל והנה זכר החרש לפי שהוא בלתי שומע ובלתי מתפעל מזה ועם כל זה הזהיר על קללתו וכל שכן שראוי להזהר מלקלל מי שאינו חרש כי יקרו מזה קטטות והפסדים בקבוצים המדיניים ואולם המקלל את המת אינו חייב כי הוא בזה הדין למנה מהחרש וזה מבואר מהשרשים הכוללים. וראוי שתדע שלא יתחייב על הקללה אם לא יקלל בשם מהשמות המיוחדים לשם יתעלה כמו שביארנו בפרשת ואלה המשפטים:
@699 **ולפי עור לא תתן מכשול.** הרצון בזה שמי שהוא עור בדבר לא תתן מכשול לפניו להפילו כאלו תאמר אם שאל ממך מדבר מה אם הוא מותר או אסור ואמרת לו בדבר האסור שהא מותר או שאל ממך עצה ונתת לו עצה בלתי הוגנת להזיק לו באי זה אופן שיהיה או אם היה האיש ההוא בעל תכונות רעות והמצאת לו הדברים אשר בהם יעשה הרעות הנה בכל זה יעבור משום לפני עור לא תתן מכשול ומי ששם מכשול בדרך להפיל העובר שעובר שם עובר גם כן על זאת האזהרה ויתחייב עם זה בנזקיו לפי מה שנתבאר ממה שנזכר בפשרת ואלה המשפטים:
@700 **לא תעשו עול במשפט.** ראוי שתדע שעשיית העול במשפט יהיה משני צדדין אם שישפוט שלא כדין כשיזכה את החייב או כשיהיה ראוי לשפוט ולגמר הדין ולא יגמר הדין לחמוס על דין הזכאי ולהאריכו כי זהו גם כן עול בעניין המשפט ונכלל הנה כשלא יתנהג בענייני הדין כראוי להוציא המשפט לאור בעת הראוי לפי הדבר ההוא ויעשה זה בכונה לעשוק דין אחר מהבעלי דינין הנה הוא עובר על לאו זה ואמנם אם יעשה זה להוסיף חקירה באימות העניין אין זה עול אבל הוא יושר:
@700 **ולא תשא פני דל.** הנה הכונה בזה לפי הדברים הנלוים לו שלא תשא פני דל למשפט להטות המשפט מפני דלותו והנה הוצרכה התורה להזהיר בזה כי אולי יחשוב השופט כי מפני שהעשיר מחוייב לפרנס העי די מחסורו והיה האופן היותר שלם בזה שינתן זה לעני באופן שלא יבוש כמו שיתבאר בענין הצדקה הנה יהיה צדקה אם יזכה הדל ויתפרנס מהעשיר דרך כבוד לזה הוצרכה התורה להזהיר בזה בבאור כי על כל פנים ראוי שישפטו כדין:
@700 **ולא תהדר פני גדול.** רוצה לומר בבואו לדין ועניין ההידור שלא יכבדהו השופט בבואו לפניו לדין יותר מבעל דינו כטעם והדרת פני זקן והטעם בזה שאם יראה בעל דינו שהגדול מכובד בעיני השופט ירא שתהיה דעת השופט קרובה לו ויצטער מזה ויכאב לבו עד שלא יוכל לסדר טענותיו כראוי בפני השופט לו שבו שלא יועילו לו טענותיו:
@700 **בצדק תשפוט עמיתך.** לפי שלא צוה בזה אחר אמרו לא תעשו עול במשפט והמתין להזכיר זה אחר אלו הלאוין הוא מבואר שזו היא מצות עשה כנגד אלו הלאוין הקודמים ואמנם היותו כנגד לא תעשו עול במשפט. ולא תשא פני דל. הוא מבואר כי מי שיעשה עול במשפט או ישא פני דל במשפט איננו שופט בצדק וכן יתבאר כי מי שיהדר פני גדול איננו שופט צדק כי הוא ככה באופן מה אל שיתחדש עול במשפט כמו שקדם:
@701 **לא תלך רכיל בעמך.** ענין הרכילות הוא שיספר האדם דברים מאיש אחד לאיש אחר אף על פי שהם דברי אמת באופן שתוכל להתחדש בזה שנאה ותחרות ביניהם כי בזה מההפסד בקבוץ המדיני מה שלא יעלם והנה יתבאר מזה שהוא ראוי להזהר מלספר בגנות חברו וזה שאם הזהירה התורה מסיפור הדברים מלספר בגנות חברו וזה שאם הזהירה התורה מסיפור הדברים שיבאישו ריח האיש ההוא בעיני איש אחד או בעיני האנשים מיוחדים כל שכן שראוי שיזהר מסיפור הדברים שיבאישו ריח האיש ההוא בעיני האנשים כלם:
@701 **לא תעמוד על דם רעך.** זכרה התורה זאת האזהרה אחרי הלאו הקודם להורות שהרכילות מביאה להריגת נפשות והנה עניין זאת האזהרה שמי שיוכל למלט מהמות איש אחד אם בדבריו אם בהשתדלותו אם בפעולותיו הנה הוא עובר על זאת האזהרה:
@702 **לא תשנא את אחיך בלבבך.** רוצה לומר אף על פי שלא יזיק לו כלל כיון ששונא אותו בלבו עובר על זאת האזהרה והנה תועלת זאת האזהרה מבואר כי השנאה אפשר שתביאהו להמנע מהשתדלות בהצלתו ולזה סמך עניין זאת האזהרה לאזהרה הקודמת וכן אפשר שתביאהו השנאה להמנע מהוכיחו כשיעשה דברים בלי ראויים ולזה סמך לזה הצווי הנמשך לו הוכח תוכיח את עמיתך ולא תשא עליו חטא. רוצה לומר כשיעשה דבר כנגדך או כנגד השם יתעלה תוכיחנו כדי להשיבו אל הדרך הטובה והנה יש בתוכחתו אותו תועלת אם עשה דבר כנגדו כי אולי יתקן את אשר עותו או יראהו שלא עשה דבר כנגדו או אם עשה כנגד השם יתעלה יש בהוכחתו תועלת להשיבו מדרכו הרעה ולזה ראוי שתהיה הוכחתו אותו באופן שיתכן שיגיע מהתוכחה זה התכלית וזה יהיה כשיאמר לו בינו לבין עצמו דברים מושכים לבבו לעבודת השם יתע' ומרחיקים אותו מאלו הפעולות המגונות לא כשיאמר לו זה בקנטורא ושיספר בגנותו בפני בני אדם כי בזה התוכחת ישא עליו חטא המוכיח רוצה לור שכבר יהיה המוכיח חטא בזה בביישו אז בפני בני אדם ולזה הזהיר התורה שתהיה זאת התוכחת באופן שלא ישא עליו המוכיח חטא:
@703 **לא תקום ולא תטור את בני עמך.** באור אלו האזהרות למד מענינו שהוא במה שבין בני אדם מהעזר קצתם בקצת בדברים שדרך השכנים להעזר קצתם בקצת אשר יקשה בעיניהם כאשר לא יעזרו מהם בזה האופן וזה מבואר מן החוש בדברים המדיניים כי כבר יקשה לאדם בבקשו משכינו שישאלהו כלי מה מעט מהזמן ולא יתרצה להשאילו לו והוא מבואר כי מכמו אלו העניינים תתחדש בינם מריבה ואם יקח האיש נקמתו ממנו בכמו זה האופן תשאר השנאה ביניהם והמריבה ולזה הזהירה תורה לא יקום אבל אם יקרה שישאל ממנו כלי מה מי שמנע ממנו כליו ישאילהו לו כי בזה האופן תסור הקטטה מביניהם והזהירה עם זה שלא יטור בלבבו זה הענין כלל כדי שתסור הקטטה מביניהם ויהיו באהבה ולזה סמך לו הצווי הנמשך לזה. ואולם בנזקי הממון והחבלות לא הזהירה שלא יקום ולא יטור אבל התבאר במה שעבר שכבר יקח נקמתו ממנו על יד בית דין וכל שכן שלא הוזהר מהנטירה ולזה חוייב שתהיה הנקימה והנטירה בכמו אלו הדברים שאמרנו:
@703 **ואהבת לרעך כמוך.** רוצה לומר שיאהבהו כגופו ולזה יבחר לו כפי היכולת הטובות אפשריות לו וירחיק ממנו ההזיקי' כמו שיעשה זה לעצמו אלא שהמצוה בזה הוא באופן שלא יגיע בו נזק לאהוב מפני זאת האהבה ושלא יחוייב לאד' להניח מלאכתו מפני עשיית מלאכת חברו כי אהבתו עצמו קודמת לאהבתו זולתו וכן אם יקום עליו להרגו אינו מחוייב שיאהבהו ולא יזיק לו אבל יחוייב למלט את נפשו ואפילו בנפש הקם עליו וזה יתבאר באור שלם בפרשת נערה המאורשה:
@704 **אם חקתי תשמרו בהמתך לא תרביע כלאים.** הנה הרביעה רמז למשגל כמו שאמ' במה שקדם ואשה לא תעמוד לפני בהמה לרבעה. וענין זאת האזהרה הוא שלא ירביע דבר ממין אחד מהב"ח על נקבה ממין אחר ולפי שאינו מרביע אותם בהעלאותו אותתם זה על זה כי להם מעצמם התחלה בזה הפועל כשיאותו זה לזה למשגל או שלא יאותו הנה לא יעבור על זאת האזהרה אם העלם זה על זה אם לא הכניס בידו אבר הזכר באבר הנקבה והתועלת בזאת המצוה מבואר כי בזה מהפסד הסדר והיושר אשר בדברי' הטבעיים מה שלא יעלם עם שזה יהיה סבה להפסק התולדה מהנולד מכלאים כמו שהתבאר בספר ב"ח ולזה יפסד בזה האופן הרבה מהטוב שהשפיע השם יתע' באלו הנמצאות עם שזה יביא להאמין שאין בכאן צורה יתחלף בה דבר מדבר כמו שחשבו הרבה מהקודמים ובכלל הנה ההאמנה בשיש בכאן מינים מיוחדים יתחלפו קצתם מקצתם במהותם הוא מפני הצרה אשר בה ייוחד מין מין מהם ולזה צותה התורה בזה להחכימני כי זה ממה שיישירנו להשגתו יתעלה כמו שזכרנו פעמים רבות רוצה לומר ההאמנה במציאות הצורות:
@704 **שדך לא תזרע כלאים.** רוצה לומר שלא תזרע בו יחד שני מיני זרעים אלא אם היה הזרע האחד בשדה אחד והזרע השני בשדה אחר והתועלת בזאת האזהרה הוא התועלת אשר באזהרה הקודמת להישירנו שנאמין במציאות הצורות גם באלו הדברים היה אפשר שיחשב בהם שלא יתחלפו כי אם במקרי' כמו שחשבו קצת מהקודמים שיהיה התחלפות אלו הדברי' עם היותם מדברים אחדים בעצמם מצד התחלפות החלקים שמהם הרכבו במצב והסדר והתמונה וראוי שתדע כי זריעתו הזרעים כלאים הוא כשיהיה מהזרע האחד עם האחר שיעור מורגש ואולם אם היה באופן שיקרא כל הזרוע בשם הזרע אחד הנה הוא מבואר שאינו כלאים כי המדקדק לזרוע הזרע האחד לא יקפיד בזה השעור אם נתערב בו מזרע אחר והנה עמדו על זה השעור רבותינו ז"ל לפי מה שקבלו מפי משה רבינו ע"ה והוא אחד מכ"ד רצוני לומר שאם נתערב עם הזרע מזרעים אחרים אחד מכ"ד בתערובת ההוא הנה הם כלאים אבל בפחות מזה השעור אינם כלאים וזה אמנם יהיה כשנתערבו מיני תבואה או קטנית קצתה בקצת ואמנם אם נתערבו זרעוני גנה בתבואה או קטנית לא יהיה שיעורם אחד מכ"ד כי כבר יהיו פחות אחד מכ"ד כשנזרע ועם כל זה היה להם שיעור מורגש בנזרע והמשל כי זרע כרוב אם נתערב שיעור אחד ממנו בשלשים שיעורים מתבואה או קטנית הנה כמעט שיחזיק זרע הכרוב מהארץ הנזרעת שיעור שוה לשיעור שיחזיק בו זרע התבואה או הקטנית ולזה יהיה שיעורו אחד מעשרים וארבעה מהמקום שיזרע בו המעורב רוצה לומר שאם היה הזרע בהזרעו מחזיק שיעור אחד מהארץ כאלו תאמר אמה על אמה והתבואה שנתערב עמה מעשרים ושלש אמות מרובעות הנה הכל כלאים והנה מבואר שאין הסבה בהרחקת כלאי זרעים אלא מפני מראית העין לא מפני יניקתם מחלק אחד מהארץ שאם היה הדבר מפני היניקה לא היתה התורה אומרת שדך לא תזרע כלאים אבל תזהיר שלא תזרע הארץ כלאים ואמנם התורה לא הזהיר בזה והוא מבואר שאפשר לזרוע בשדה אחד חטים ובשדה אחר סמוך לו שעורים ומזה המקום יתבאר שאם היה המקום שזרע בו חיטים בלתי ראוי להקרא שדה אסור לו לזרוע סמוך לו שעורים וכן העניין בשאר זריע' והנה השעורי' יתחלפו לפי מנהג הדבר הנזרע והמשל כי זרעוני גנה יוזרע מהם יחד שיעור קטן כי המקום ההוא הוא שדה לפי הזרע ההוא ולזה אפשר לזרוע מהם במקום קטן מינים רבים והשעורים באלו הדברים עם שהם מקובלים מפי משה רבינו ע"ה הם עוד מבוארים מצד מנהג ההזרע באלו הזרעי' ולפי שהתורה לא חששה בכלאי זרעים אלא מפני מראית עין כמו שביארנו הנה כשיתערב בזרע הנזרע זרע שאין מה שיוציא ראוי לאכילה כי לא יתחייב עליו משום כלאים כי הרואה לא ישפוט שנזרע זה הזרע כלאים בכונה כי הוא בלתי ראוי לאכילה וראוי שתדע כי הזריעה תהיה אם כשיזרעו בידו אלו הזרעי' בשדה או כשיחפה אותם בעפר אם היו בארץ כי הוא ישים אותם זרעוני' בזה החפוי והוא מבואר שזאת האזהרה אינה נוהגת אלא בארץ ישראל כי היא תלויה בארץ וראוי שתדע מזאת האזהרה שאין בזרעי אילנות כלאים כי נזרעו יחד כי אין האילנות דומין לזרעי השדה שסמוכין זה לזה ולזה אם הקפידה התורה בזה בכמו אלו הזרעים אין ראוי שנלמד מהם זה הדין בזרעי האילנות כי הם בזה הדין למטה מזרעי השדה וזה כבר התבאר מהשרשים הכוללים ואולם יתבאר שהרכבת מין במין אילנות התורה אסרה וזה שאם הקפידה התורה בזרעים שלא יזרעו כלאים ואף על פי שכל אחד מהם גדל בפני עצמו כל שכן שתקפיד בהרכבת מין במין ולזה יתבאר שהמרכיב אילן באילן או ירק באילן לוקה:
@704 **ובגד כלאים שעטנז לא יעלה עליך.** כבר יתבאר במה שיבא שזה הכלאים הוא צמר ופשתים לבד שנאמר לא תלבש שעטנז צמר ופשתים יחדיו וידמה שלפי הוראת הגדר אמרו שעטנז על הבגד ששתיו פשתים וערב בו צמר או הפך זה ולזה אמר אחר כך שם צמר ושפתים יחדיו להורות שאיך שיהיה צמר ופשתים יחדיו הוא אסור ללבשו אף על פי שלא היה ארוג הצמר עם הפשתים אלא שהוא שוע עמו כמו הלבדים אם היו מצמר ופשתים או אם היה מחובר עמו חיבור ישים הצמר עם הפשתים כלי אחד ואפשר שיהיה שעטנז שם נאמר בכללות על אלו המינים שזכרנו מהחבור לצמר עם הפשתים ואיך שהיה הנה כשיתחברו הצמר עם הפשתים באחד מהאופנים הנזכרי' יהיה הבגד ההוא אסור ללבשו משום כלאים והוא מבואר מן התורה שאין אסור כי אם ללבשו אבל מותר להציעו מצע תחתיו שנאמר לא תלבש שעטנז ואמר בזה המקו' לא יעלה עליך ראיה שכבר יתכן לשומו תחתיו וראוי שתדע שלא יקרא צמר רק צמר הצאן ויתבאר שחבורי חבורין יחביר לענין כלאים והמשל שאם היה בכאן רצועה של עור והיה בצד אחר ממנה חוט של צמר נקשר בה ומצד השני חוט של פשתן אסור לחגור אותה כי הוא צמר ופשתים יחדיו כמו שהתבאר בט' מכלאים וכן העוש בגד מצמר ארנבי' וארג בו חוט של צמר מצד זה וחוט של פשתן מצד זה הרי זה אסור משו' כלאים כמו שנתבאר בחמישי מתוספו' כלאים ומזה המקו' יתבאר שהבגד של צמר שתפרו בו עורות והיו העורו' תפורין בפשתן או היה בהם חוט של פשתן קשור באופן שיהיה חבור הנה הוא כלאי' כי חבורי חבורים הם יחדיו כמו שביארנו עם שהוא מבואר בנפשו וכבר הארכנו בזה לפי מה שראינו בזמנינו זה רבים בלתי נשמרי' מזה ואם טען אדם עלינו ויאמר שאין שם כלאי' מן התורה אלא כשהיה שוע טווי ונוז כמו שנפסקה ההלכה בזה במסכת נדה כמר זוטרא שאומר עד שיהיה שוע טווי ונוז אמרנו לו שאין פסק ההלכה היא שם מחכמי התלמוד אבל מהגאונים הראשונים ולזה לא תשגיח בפסק ההלכה היא כי שם בתלמוד הלכות רבות שהם מהגאונים הראשונים כמו שזכר הרש"י בפירושו למסכת חולין ולזה הדעת נטה הרב המורה והנה תמצא בד' ממנחות רבא חולק על מאמר מר זוטרא בזה והתבאר בעירובין כי מר זוטרא היה תלמיד לרבא ומשרשינו בתלמוד שאין הלכה כתלמיד במקום הרב ועוד שזה המאמר הוא בנדה אגב גררא ולזה לא יתן רושם גדול בהאמתת זה הפסק ועוד שכל המשניות שהם בט' מכלאים מלאות מסתירת דעת מר זוטרא במסכת נדה ועוד שכבר יתכן שיפורש מאמר מר זוטרא במסכת נדה באופן בלתי סותר זה הדעת וזה שהוא יאמר כי מלשון שעטנז לא יתבאר שיהיה שוע או טווי או נוז אבל אם היתה הוראתו זאת ההוראה רוצה לומר שוע טווי ונוז היה ראוי יותר שיורה על מה שהוא שוע טווי ונוז יחד לא מה שהוא שוע או טווי או נוז ומזה הצד אמרו שם דהלכתא כמר זוטרא מראפקינהו רחמנא בחד לישנא והנה אף על פי שנודה שיהיה האמת מה שיאמ מר זוטרא כי לשון שעטנז יורה על מה שהוא שוע טווי ונוז הנה מה שאמרה התורה אחריו צמר ופשתים יחדיו כלל כל האופנים שיהיה בהם הבגד צמר ופשתים יחדיו. וכבר יצאנו ממנהגנו בזה הביאור ואמנם הביאנו לזה מה שזכרנו במה שקדם והנה התועלת בזאת האזהרה עם שהוא לפי מה שיראה להרחיק מההליכה בחקות הגוים הנה הוא התועלת בעינו אשר בשאר האזהרות הקודמות בעניין הכלאים וזה שהצמר הוא בא מן החי בהכרח החומר כמו שהתבאר בספר ב"ח. והפשתים הם באים מן הצמח והוא מין מכוון בעצמו. והנה יגיע מזה תועלת כי הצמר והפשתים עם היותם מסכימים ברכות והספוגיות ושמהם יעשו בגדים לאדם הנה יש בהם הבדל עצמו מצד צורותיהם כי זה מהצמח וזה מהחי והפשתים הוא צמח יותר שלם מהצמר כמו שיתבאר מפועל הצמיחה בפשתי' ובצמר ועוד שהוא מין מהמיני' מכוון בעצמו והצמר אינו כי אם מהכרח החמר וכל זה להחכימנו בזה האופן להשיג מציאות הצורות והמדרגות הנמצאו' קצתם עם קצת כי מזה נעמוד על מציאות הש"י כמו שזכרנו פעמים רבות:
@705 **ואיש כי ישכב את אשה שכבת זרע.** התבאר במה שקדם שזאת השכיבה תהיה אפשרית בקטן בן ט' שנים ויום אחד והנה זאת השכיבה הוא שישכב עמה כדרכה ויגמור ביאתו כי כבר אמר הכתוב שכבת זרע:
@705 **והיא שפחה נחרפת לאיש.** ר"ל בעולת בעל ולפי שאין אישות לגוי כמו שהתבאר למדנו שזה האיש הוא ישראל ולא יהיה זה בזולת איסור אלא בעבד עברי שכבר התבאר בפרשת ואלה המשפטים שרבו מוסר לו שפחה כנענית ולפי שכבר התבאר שם שאין לו אישות בה ולזה תהיה האשה וילדיה לאדוניה בצאתו ולא תשאר נקשרת עמו כלל בקשר האישות הנה הוא מבואר שזאת השפחה היא בת חורין בצד ושפחה בצד וזה אמנם יהיה כשתהיה משני שותפין וכתב לה אחד מהם גט שיחרור או שנפדית ממנו ונשארה חציה שפחה וחציה בן חורין והנה יהיה הרצון בנחרפת בעולה מענין חרפה כי זה הענין הוא חרפה לנו רוצה לומר המשגל כי הוא לאדם מצד שהוא ב"ח לא מצד שהוא אדם או יהיה מענין כריעה ונפילה ובזה נקראת חורף התקופה שישפל בה השמש תכלית השפלות במקומות מהארץ אשר בהם היישוב וכן אמר לא יחרף לבבי מימי רוצה לומר לא יפול ולא יכנע להודות לדבריכם ומזה הענין נקראו חרפות הדברים אשר יאמרו כנגד איש או אשה להשפיל מדרגתם. ולזה יהיה אמרו נחרפת לאיש נכרעת ונופלת לבעל לשכב עמה והנה לא אמרה התורה בעולת בעל לפי החסרון שיש בזאת הבעילה לפי הנימוס התוריי:
@705 **והפדה לא נפדתה וגו'.** רוצה לומר שאמנם קרא אותה שפחה מפני שלא נפדתה בשלמות או בכסף או בשוה כסף או לא נתן לה שטר שחרור וזה ממה שיורה גם כן שאין הכתוב מדבר במי שהיא שפחה בשלמות שאם היה הענין כן יהיה אמרו והפדה לא נפדתה אם חפשה לא נתן לה מותר אין צורך לזה:
@705 **בקורת תהיה.** ר"ל שהיא לוקה על זאת הבעילה אם היה זה בעדים והתראה:
@705 **לא יומתו כי לא חופשה.** מגיד שאם היה נשלם שיחרורה היו בני מות וזה ממה שיורה גם כן שהיא נשואה לישראל:
@706 **והביא את אשמו ליי'.** לפי שהיה מדבר מתחלה באיש וזכר מתחלה עונש השפחה קודם זכרו עונש הבועל למדנו שלא יחוייב האיש להביא אשם אם לא תתחייב היא מלקות כאלו אמר שכאשר תלקה היא אוז יחוייב להביא את אשמו ובכלל זה הנה יתבאר עוד מהמקומות הכוללים ומזה יתבאר גם כן שהוא יתחייב להביא אשם אם היה בן תשע שנים ויום אחד כיון שהיא לוקה על ידו:
@706 **איל אשם.** רוצה לומר האיל אשר יביאו לאשם והוא הבא בכסף שקלים כמו שהתבאר בפרשת ויקרא:
@707 **על חטאתו אשר חטא.** למדנו שהוא מביא אשם אחד על בעילות הרבה וממה שקדם יתבאר שלא יתחייב אשם אם לא היתה היא גדלה ובעולה ושתהיה מזידה:
@708 **וכי תבאו אל הארץ ונטעתם כל עץ מאכל וערלתם ערלתו את פריו.** למדנו מזה שהנוטע אילן מאכל בארץ ישראל יאסר פריו שלש שנים מיום שנטעו והנה קראו ערלה להורו' שהוא מותר אין בו תועלת כמו הענין בערלת הבשר וטעם זה הוא כי בהתחלה לא יתכן לרוב האילנו' שיתנו פרים באופן שישלם החום היסודי בו כי לכח הזן בהם טרדה במה שיצטר' לו מן המזון לגדול גופם ולזה לא יתחזק על שיהיה שם מהמזון מותר מצומק ומבושל יעשה ממנו הפרי וכבר תראה זה בביאור ביין ענבי הגפן הילדה שהו' חלוש החום היסודי מאד ולפי שרצתה התורה שיהיה ראשית פריו קדש הלולים ליי'. להעי' כי הש"י הוא הפועל באמת בכל הפעולו' הטבעיו' ומאתו הכל חוייב שימתין זה עד השנה הרביעית שיהיה נבחר מה שיהיה ליי':
@708 **שלש שנים יהיה לכם ערלים לא יאכל.** ראוי שתדע שהאכילה היא אחת ממיני ההנאה ולזה נלמד ממנה שפרי זאת הנטיעה אסור בהנאה שלש שנים ולפי שאמר ונטעתם כל עץ מאכל למדנו שאם נטעו לא למאכל פטור מן הערלה והוא מבואר שנטיעת ייחור מן האילן או זריעת זרע האילן הוא אחד לזה הענין וזה מבואר מהמקומות הכוללים. והנה הפרי הוא הכולל הקליפין והגרעינין אשר הם עמו וזה מבואר מצד הוראת הגדר:
@709 **ובשנה הרביעית יהיה כל פריו קדש הלולים ליי'.** רוצה לומר שיהללו עליו ליי' על כל הטובה אשר השפיע להם וזה אמנם הוא להעיד שכל הטובות הם מאתו יתע' ולפי שהוא קדש למדנו שיחוייב לאכלו בירושלם לפני' מן החומה כמו הענין בשאר הקדשי' כמו שיתבאר ואמנם קדשי הקדשים היו נאכלים לפנים מן הקלעים כמו שהתבאר ויתבאר שנטע רבעי פירותיו לבעלים ממה שנאמר בפרשת נשא ואיש את קדשיו לו יהיו ומזה יתבאר גם כן שמעשר בהמה הוא לבעלים נאמר בו קדש ליי' ובכלל הנה אם היה זה הקדש לכהן לא שתקה התורה מזה. ולפי שלא זכרה התורה בזה דבר הנה והוא מבואר שאלו הפירות לבעליהן ולפי שאמר כל פריו למדנו שאין בהם לעניים דבר ולא לכהני' וללויים:
@710 **ובשנה החמישית תאכלו את פריו.** אמר התורה זו שלא יכבד עלינו מה שמנעה התורה פירות שלשה שני' גם פיות השנה הרביעית לא התירה לאכל אותם כי אם במקום אשר יבחר כמו שקדם כי זה יהיה סבה שתדבק השגחת יתע' בנו ויוסיף לנו מפני זה תבואות הצמחים עם מה שישפיע לנו משאר הטובות ומהטובות האנושיות כמו שבארנו בספר מלחמות השם ואפשר עם זה שיהיה זה לתועלת שזכר הרבה המורה להרחיק מעבודות עבודה זרה הקדומות שהיו עושים פעולות מגונות למהר נתינת האילן פריו להוסיף תבואתו והתורה הערימה לעמוד כנגד הדיעות הנפסדות ההם לפי מה שאפשר לנקותנו מטמאתם:
@711 **לא תאכלו על הדם.** הנה מפני שסמך אל זה אמרו לא תנחשו ולא תעוננו למדנו שהאכילה על הדם היתה לכונה שיודעו להם העתידו' וזה אמנם היה שהיו זובחי' הב"ח והיה דמו יורד תוך הפיר' אחת וסביבה היו אוכלין בשר הב"ח ההוא ויחשבו שיהיו אוכלים בזה האופן עם השרים על שלחן אחד ותתחזק האהבה והחברה ביניהם עד שיודיעום השדים העתידות כמו שזכר הרב המורה שראה בספרים ההם:
@711 **לא תנחשו.** הוא שישפטו בדבר טוב או רע מפני דבר אחד בלתי מעיד עליו כלל כמו שיאמר אומ' לא אעשה דבר פלוני שייעדתי לעשות שאם אעשנו לא אשיג בו רצוני והעד על זה שהרי נפלה פתי מפי:
@711 **ולא תעוננו.** ר"ל שלא תשימו העתים סבת הדברים כמו שיעשו הסכלים שיאמרו יום פלוני מחדש פלוני או משנת פלוני טוב ויום פלוני רע כי זה כשלא יאמר בו יותר מזה השיעור הוא מביא להאמין שלא תהיה בכאן סבה פועלת ויהיה הכל מתחדש מהקרי כמו שחשבו רבים מהקודמים ואולם אם חברו עם העת מה שיתכן שיהיה סבת לזה לא יהיה בזה חטא והמשל אם אמרו העת פלוני קשה להקזה לפי שהשמש הוא אז במקום שתחמם האויר חום נפלא וכן אם בחרו לזרוע בעת מהשנה הנאות לזרוע מצד טבע התקופה וטבע הזרע לא יהיה בזה אשם וכמו זה אם אמרו שאין טוב לזמור הכרם בתחלת החדש אם היתה הגפן ילדה או בסוף החדש אם היתה הגפן זקנה כי אלו הדברים כלם הם מבוארי הסבות לפי מה שנתן השם יתעלה מהכח בכוכבים להשגיח באלו הנמצאות השפלות. וראוי שתדע שכן ההיקש במה שיתחייב משאר הכוכבים כי התורה העירה שהם נבראו להשגחה באלו הענינים השפלי' כמו שביארנו בפרשת בראשית ואולם החטא הוא כשיחם זה הענין אל דעת מופשט מסיבות אחרות וזהו מה שאמר רבי עקיבה בביאור זה כגון אלו שהן למודות ערבי שביעיות להיות יפות ולזה יהיה חטא במי שמחשב על פי האצטגנינות מזה הצד אלא אם יחס הפועל לכוכבים עצמם בזולת התחלה קודמת להם כי זהו מכת עבודה זרה בלי ספק ואולם מי שייחס הפועל לשם יתע' באמצעות הכוכבים ממה שנתן להם מהכח בזה לא יחטא בזה האופן אלא שראוי שלא יעלם ממנו שזה המשפט לא יתן האמת עכ"פ אבל ימצא בו הכזב הרבה לקצורנו מהעמידה על מה שיצטרך לעמוד עליו בנסיון למי שירצה שישפוט בזה משפט צדק עם שהשם יתע' הוא השליט על זה הסדור לבלבל אותו על צד ההשגחה כמו שביארנו בספר מ"י. ולזה ימצא בזאת ההודעה מהכזב הרבה ובכלל האזהרה הזאת מי שידמה להודיע העניינים הנעלמים באחיזת עינים כמו שיעשו קצת האנשים שיעשו נר מדברים ידועים וידליקו אותו ויהיה שם קטן שלא ראה קרי ויחשבו שהקטן יראה שם אמתת זה הדבר אשר בקשו לדעת ענינו איך הוא ואולי יקרה לו שיראה שם קצת דמיונים באחיזת עינים ומזה הסוג מה שיעשו שינעצו סכין בלחם אחד ובבא שם האיש החשוד על הדבר ההוא ידומה להם שיתנועע הלחם וזה הסוד מאחיזת עינים יתחייבו עליו מלקות ואמנם האוחז את העינים שהוא פטור הוא כאשר היה בדברים שידומו מפעולות הכשוף מזולת שיהיה כן כמו שתראה שיעשו אנשי' אחיזת עינים שידמה לאנשי' שעומדי' שם שתרנגול קטן ישא קורה גדולה ומה שידמה לזה:
@712 **לא תקיפו פאת ראשכם.** ידוע שמנהג עבוד הזרה היה להקיף פאת ראשם רוצה לומר לגלח אותה בתער וכבר נשאר רושם זה המנהג עד היום. והתורה צותה אלינו שלא נלך בחקותיהם כדי שנתרחק מדעותיהם הנפסדות בתכלית מה שאפשר עם שבזה תועלת להחכימנו ולהעמידנו על סודות הבריאה האנושית וזה שכבר יתבאר שחלקי הראש הם בלתי מתדמה הטבע ומזה הצד הבדילה התורה בין הקרחת והגבחת והנה הקפת הראש יביא לחשוב שיהיה הכל מטבע אחד כי טבע העגול אחד ומתדמה ולזה מנעה התורה זה כדי להעמידנו על הבדל הדברים כי עמידתנו על הבדל הדברים ומה שייוחדה בו קצתם מקצת תביאנו לעמוד על מהות הדברים וטבעיהם ומי שלא יחקור בזה האופן אבל יחשוב כל הדברים כלם מתדמים תבצר ממנו כל החכמה ויהיה זה סבה אל שיאמין שאין בכאן כי אם הצורה החמרית כמו שחשבו הרבה מן הקודמים ולפי שטבע פאת הראש הימנית הוא מתחלף לפאת הראש השמאלית הנה יתחייב על שתי אלו הפאות שתי מלקיות וראוי שתדע שהמגלח פאת חבירו הוא שיתחייב מלקות אף על פי שאינו הוא המתגלה ואמנם המתגלח לא יתחייב מלקות כי לא עשה מעשה ויתחייב שזה הדין הוא באיש לבד לפי שסמך ולזה ולא תשחית את פאת זקנך והאשה אין לה זקן ולזה יתבאר שהאשה שגלחה פאת ראשה או פאת ראש האיש פטורה:
@712 **ולא תשחית את פאת זקנך.** זאת ההשחתה היא לפי הוראת גדר גלוח בתער. והנה המקומות שהם פאה בזקן לפי הוראת הגדר הם חמש פאות שתים מימין אחת בלחי העליון ואחת בלחי התחתון ושתים כנגדן בשמאל ואחת במקום חבור לחי התחתון הימיני לשמאלי:
@713 **ושרט לנפש לא תתנו בבשרכם.** אחשוב כי הקודמים להשכם כי אין יתרון לאדם אחר המות היו שורטים בשרם כמו אחד מקרוביהם שלהם והתורה הזהירה מעשו' כמו זה הפועל המגונה ויתבא' שהוא חייב על כל שריטה ושריטה שנאמר ושרט לנפש לא תתנו וכן אם שרט שריטה אחת על מתים רבים חייב על כל מת ומת שנאמר לנפש לחייב על כל נפש ונפש:
@713 **וכתובת קעקע.** הוא כתב עשוי בצבע מהצבעים בעור האדם אחר הקרע במקום שיעבור בו הצבע. וזה היה מנהג הגוים בזמנים הקודמים לרשום על עצמם רושם העבודה זרה להורות שהם עבדים לה והזהירה התורה מעשות זה אפילו לשם יתעלה שלא לילך בחוקותיהם עם שהתורה בכללה היא להטיב לנו לא להכאיב גופותינו כמו שהיו עושים הסכלים ההם ולזה אמר כי גם את בניהם ואת בנותיהם ישרפו באש לאלהיהם ואולם השם יתע' נהג בזאת התורה השלמה מנהג האב עם הבנים שנשתדל להטיב להם בכל עוז ולשמרם מהפגעים ולזה אמרה במשנה תורה בנים אתם ליי' אלהיכם לא תתגודדו:
@714 **אל תחלל את בתך להזנותה.** זאת היא מצו' לא תעשה לא מנאה הרב המורה ועיינה שלא ימסור אדם בתו לביאה שלא לשם אישות:
@714 **ולא תזנה הארץ ומלאה הארץ זמה.** רוצה לומר שמי שיחלל בתו להזנותה יהיה סבה שתזנה הארץ כי היא תפקיר עצמה לכל ולא תבוש אחרי ראותה שאביה רוצה בזה ויהיה זה סבה שתמלא הארץ זמה כי יקרה מזה שלא יודע ממי הרתה ויבוא הענין שישא האב בתו והאח אחותו:
@715 **את שבתותי תשמורו ומקדשי תיראו אני יי'.** זכר אלו המצות יחד לפי שהם מתדמות בכוונותיהם כמו שיתבאר מדברינו בהם והנח' מורא המקדש הוא שלא יכנס בו שלא לצורך וינהג בו בכבוד וביראה כי זה מה שיישירהו לעמוד על הכוונה אשר בעבורה היה באופן הנפלא הזה שצוה השם יתע':
@716 **אל תפנו אל האובות.** ידוע ממה ששאל שאול באוב לאשה בעת אוב כי האוב הוא פועל יביא לדמות שהעלו בו המת ויתפעל הדמיון באון שיתדמה לו שהוא שומע קול מהמת ההוא יודעי לו העתידות והתבאר שזה הקול המדומה הוא נמוך מאד אמר שפל מאוב קולך וידמה שמה שנתפרסם מההודעה המגעת בכמו זה האופן בלקיחת גלגולת המת הוא מזה הסוג:
@716 **ואל הידעונים אל תבקשו לטמאה בה.** הנה הידעוני היה שהיו לוקחים עצם מעוף ששמו ידוע והיו משימים אותו בפיהם ויעשו פעולות להתבודד דמיונם עד שיגיע מזה שידברו בפיהם דברים ויחשבו שידעו בזה האופן מה שעתיד להיות והנה הפליגה התורה בהרחקת זה לפי שהיותר חזקה שבראיות על שיש בכאן שכל פועל כל אלו הדברים אשר בכאן היא ההודעה שתגיע מזה בחלום או בקסם או בנבואה כמו שבארנו בשני ממ"י ולזה תמצא שאמר הנביא מי פעל ועשה קורא הדורות מראש רוצה לומ' שהודעתו הדברים העתידים טרם היותם הוא ראיה חזקה על היותו פועל אותם ומי שישים סבת הודעת המתי' או העצמות יבטל שיהיה בכאן סדור מסודר משכל אבל יהיה החומר הוא התחלה לכל הדברים וזה בתכלית הגנות וההפסד:
@717 **מפני שיבה תקום.** הוא מצות עשה לקום מפני כל איש שיבה כדי לכבדו לא מנאה הרב המורה ובזה תועלת כי מפני זה ישמעו צעירי הימים לדברי הישישים ויהיו דבריהם אצלם יקרים ולזה יתנהגו במוסריהם כי הישישים לרוב מה שראו מעניני קורות העולם יודיעו להם על צד הנסיון דברים רבים בפיל וספיא המדינית ולזה יקרה למי שישמע דבריהם להנצל מהרבה מהפגעי' אשר היו באים עליו לולא עצת הישישים עם שבזה יתיישב בנפש לתת כבוד נפלא לשם יתעלה שהוא קדמון לא סר מהיות ונמצא ולא יסור:
@717 **והדרת פני זקן.** היא מצות עשה והרצון בזקן לפי הוראת הגדר חכם כי החכם יקרא זקן אף על פי שהוא צעיר לימים אמר זקנים משער שבתו והדור הוא לעמוד מפניו כדי להדרו:
@717 **ויראת מאלהיך.** ירצה בזה שזה יביאך לירא מאלהיך יראה עצומה כי גבוהה חכמתו לאין קץ על חכמת הזקן שתחוייב בו לכבדו ונפלאה קדימת מציאותו לאין קץ מקדימת מציאו' האיש הישיש:
@718 **וכי יגור אתכם גר בארצכם.** זה גר צדק:
@718 **לא תונו אותו.** ידמה שיהיה הרצון בזה אונאת דברים כלאו תאמ' שיזכיר לו מעש' אבותיו לביישו ולפי שצותה התורה לתת כבוד לראוי לו מפני החכמה והישישות צותה שלא לבזות אלו האנשים שתלויה מאחריה' קופה של שרצים:
@719 **ואהבת לו כמוך.** היא מצות עשה והוסיפה התורה לצוות על אהבתו ואם הוא נכלל במה שאמר לרעך כמוך לפי שיאהבוהו מהבלתי קרובים עם שכבר יקל לאדם להתנגד לו כי אין עוזר ולזה צותה התורה שנאהבהו כנפשנו:
@720 **לא תעשו עול במשפט במדה במשקל ובמשורה.** הכונה במשפט בזה הפסוק המשפט שיהיה ע"פ המדה והמשקל והמשורה. והמשל שהמודד הבגד בקנה המדה או המודד בארץ הוא השופט על פי המדה ההיא כמה ראוי שינתן אל זה האיש מהבגד או מהארץ או משאר העניינים הדומים וכן השוקל במאזנים אי זה משקל שיהיה מאיזה דבר שיהיה שופט על פי המשקל ההוא כמה יותן לזה האיש מהענין ההוא וכן הענין במשורה והיא המדה המכילה שעור מה מהפרות או מהמשקין ולזה ראוי שלא יטח השופט המשפט בשום צד מהצדדים:
@721 **מאזני צדק אבני צדק.** צותה התורה שיהיו הכלים הם בעצם שבהם ישלם המשקל בתכלית מהיושר והצדק באופן שלא יהיה עול מצדם במשקל והנה העול יהיה במאזנים מפנים רבי' מהם שיהיה מרחק הכפות מהאמצע מרחק בלתי שוה ומהם שיהיו קשי הנפילה או קלי הנפילה מאד ומהם שיהיו חוטי הכפות בלתי שוים בארך וכן ההקש בשאר הדברים אשר להם רושם כשלא ימצא הצדק במאזנים:
@721 **איפת צדק והין צדק.** הנה האפה היא מדת הפרות היבשים וההין היא מדת חלה והנה העול ימצא באיפה וההין אם היו חסרות או יתרות וכבר ימצא העול באפה מפני היותר מחזקת כשימחוה מצד אחד יותר ממה שתחזיק כשימחוה מצד השני וכן ימצא העול בכלי אשר ימחקו בו אם אינו ישר או הוא יותר כבד מן הראוי או יותר קל מהראוי:
@724 **ואל בני ישראל תאמר איש איש וגו'.** אחר שהזהיר מלהעביר זרעו למולך זכר הענש והיא סקילה אמר עם הארץ ירגמוהו באבן והוא מבואר שהסקילה תהיה בשני פנים אם שישליכו האבן על החוטא אם שישליכו החוטא על האבן אמ' במעמד הר סיני כי סקול יסקל או ירה יירה ולפי שהתורה אמר ואהבת לרעך כמוך ראוי שנבחר הקלה שבב' אלו המיתות ובכלל הנה מפני שתשלם מצות התורה בזה בקלה שבאלו המיתות הנה אין ראוי שנעשה יותר מזה כי בכמו אלו העניינים ראוי שנקח המעט שאפשר שתשלם בו כונת התורה והוא מבואר שההשלכה על האבן היא היותר קלה ההמתה וימצא בה יותר מעט הצער כי כבר נרדם בשרו הרדמה מה בנפילה באופן שלא ירגיש הרגש חזק במכת האבן כמו שהיה מרגיש בזה אם השליכו האבן עליו ולפי שאמרה תורה במה שיבא מענין הסקילה יד העדים תהיה בו בראשונה להמיתו ויד כל העם באחרונה למדנו שהעדים מתחילים מזה הפעל באופן שיהיה כדי להמיתו ולזה היו דוחפין אותו ממקום גבוה שיש בנפילה ממנו כדי המית ואם לא מת בזה משליכין עליו אבן שיש בה כדי להמית:
@725 **ואני אתן את פני באיש ההוא והכרתי אותו מקרב מקרב עמו.** הנה כבר התבאר במה שקד' ענין הכרת:
@725 **למען טמא את מקדשי.** כבר זכרנו במה שקד' כי הקדש הוא מצד הצורה וכל מה שהיתה יותר נקייה מחמר תהיה בו הקדוש' יותר ולזאת הסבה היתה מה שיעיר על הצורות הנבדלות נקרא קדש הקדשים ואין ספק כי מי שעושה מהאש אלוה לא יאמי' שתהיה בכאן צורה אבל תהיינה הפעולות הנמצאות לדברים הטבעיים מצד מה שבהם מהאש והוא החום היסודי אשר בהם והנה יטמא מקדש להשם ית' בהשיבו כחות הצורות האנושיות כלם מיוחסים על החמר ויחלל שם קדשו יתע' ר"ל שישיבהו חול כי הוא לא יאמין שתהיה בכאן התחלה זולת החמר ואמרה התורה שאם יעלימו עם הארץ את עיניהם לבלתי המית זה החוטא שנתחייב מיתה בב"ד הנה ישים הש"י פניו באיש ההוא ובמשפחתו ר"ל בנמשכי' אחריו כי מן השקר שיענשו משפחתו על חטאו ולזה אמ' והכרתי אותו ואת כל הזוני' אחריו לזנות אחרי המולך מקרב עמם מגיד שהזונים הם הנענשין על זה לאלהבלתי זונין אחריו:
@731 **איש איש כי יקלל את אביו.** לפי שכבר זכר בפרשת ואלה המשפטים שהמקלל אביו ואמו הוא במיתה בא לזכור בזה הפסוק באי זו מיתה הוא נענש ואמר דמיו בו רוצה לומר שאין ראוי שיחיה עוד ויתהוה בו דם מן המזון שהוא נזון ממנו אבל כל דמיו הם בו שאין ראוי שיתחדש בו עוד דם וזאת היה חמרה שבעברות לה יהיה העובר בה בסקילה שהיא חמורה שבמיתות אמ' בסוף זאת הפרשה באב' ירגמו אותם דמיהם בם:
@732 **ואיש כי ינאף את אשת איש.** כבר התבאר כי הנאוף ישלם משיהיה הבועל בן תשע שנים ויום אחד ואמנם ראוי שתדע כי האישות לא ישלם למי שאינו בן י"ג שנה ויום אחד כי קודם זה אין זרעו ראוי להולדה ואף על פי שהוא ראוי לביאה מהיותו בן תשע שנים ויום אחד וכבר התבאר זה במקומות הכוללים ולזה לא יתחייב מיתה על אשת קטן:
@732 **אשר ינאף את אשת רעהו.** מגיד שלא יתחייב מיתה כי אם על אשת בן ברית כי לא ישלמו תנאי האישות בזולת בני ברית ולזה תצא בשפחה כנענית שיוצאה בלא גט אחר שהיתה מיוחדת לעבד עברי וכן תמצא ביפת תאר שהותרה לישראל הוא שיהיה לה בעל או שלא יהיה לה בעל:
@732 **מות יומת הנואף והנואפת.** ראוי שתדע שכל מקום שנאמר מות יומת רוצה לומ' על ידי בית דין וזה מבואר מצד עצם הלשון וכל מקום שנאמר ימות רוצה לומר בידי שמים אמר פן ימות גם הוא כאחיו ולפי שלא ביארה התורה באי זה מיתה יומתו הנה יחוייב שיומתו במיתה יותר קלה שאפשר לב"ד שימיתוהו בה והוא מבואר ממה שאמרנו בענין הסקילה ולפי שהקלה באלו המיתו' הוא חנק הנה יומו בחנק:
@733 **ואיש אשר ישכב את אשת וגו'.** מגיד שהבא על אשת אביו או על כלתו או השוכב את זכר משכבי אשה נסקלים הוא והם והנה הרצון באמרו תבל עשו בלילת זרע האב עם זרע הבן רוצה לומ' שישכבו שניהם עם אשה אחת:
@736 **ואיש אשר יקח את אשה ואת אמה.** אמר יקח להעיר שהאחת מהן אשתו והשנית חמותו או בת אשתו:
@736 **באש ישרפו אותו ואתהן.** ידוע כי אשר היא אשתו מהן אינה נשרפת כי לא עשת' עברה ואמר ואתהן הרצון בו הוא ואשר בעברה מהן אם האשה היתה בת אשתו או אמה אם היתה חמותו והוא מבואר כי השרפ' תהיה או אם שישרף הגוף באש בחבלי עצים או שישאר הגוף קיים כמו הענין בנדב ואביהוא כי גם זה יקרא שרפה אמר שם ואחיהם כל בית ישראל יבכו את השרפה אשר שרף השם. והנה יחוייב שנבאר הקלה שבאלו המיתות כמו שזכרנו במה שקדם ולזה תהיה זאת המיתה בשרפת נשמה וגוף קיים כאלו תאמר שיזרקו לתוך פיו מתכת חום נתך והוא יורד ושורף בני מעים וישאר הגוף קיים ולפי שאמ' אשה ואמה ואיננה כ"א לאחר מיתה הנה יתחייב מהמקומו' הכוללים שתהיינה שתיהן קיימות ואז יהיו נדונים בשרפה:
@737 **ואיש אשר יתן שכבתו בבהמה וגומר.** מגיד שהבהמה והרובע והנרבע כלם בסקילה שנאמר מות יומתו דמיהם בם והתועלת המגיע מהריגת הבהמה הוא שלא יזכרה עון הזה ויאמרו זאת היא שנסקל פלוני על ידה וזה כי ההמתה מכפרת לו העון הזה עם התשובה ולזה ראוי שלא יהיה בכאן מה שיביא לזכור העון ההוא עם התשובה כי בזה יתישב יותר בנפש האנשים שהחטא נמחל אחר קבול החוטא העונש המסודר עליו לפי הנימוס התוריי ועוד כי הזכירה הזאת תביא להרהר בעברה כל זמן שיראו הבהמה ההיא בזכרם שכבר שכב איש אותה או נרבעת אשה לה:
@739 **וראה את ערותה והיא תראה את ערותו.** ידוע כי הראיה תאמ' על שאר מיני ההרגש אמר ראה ריח בני וכל העם רואים את הקולות וכמו זה אמ' בזה המקום ראיה על חוש המשוש:
@739 **חסד הוא.** רוצה לומר שזאת הבעילה כבר תהיה ביניהן מחוזק האהבה לעשות חסד זה לזה ולזה יהיו נשמעים זה לזה תמיד אפילו בזולת אישות ומפני זה מנעה התורה זה כמו שזכרנו במה שקדם או יהיה חסד מענין בושת וחרפה כי הוא עזות מצח שישגל האדם שאר בשרו:
@739 **ונכרתו לעיני בני עמם.** אפשר שיהיה הרצון בזה שנפשם תכרת ותאבד ואפשר שיהיה הרצון שכבר יכרת מציאותם מישראל ויפסק רוצה לומר שלא יהיו להם בנים ולבניהם בנים וזה תמיד אבל יכלה זה המציאות באופן שלא ישאר להם יד ושם בישראל וזהו מה שאמר אחר זה תמורת שם הכרת ערירים ימותו ערירים יהיו רוצה לומר בלא בנים כמו ואנכי הולך ערירי ולמדתנו התורה בזה שהבא על אחותו או על הנדה או על אחות הוריו או על דודתו או על אשת אחיו נכרת הוא והן והנה הרצון באמרו נדה היא טמאה היא ומרוחקת להעיר על התעוב אשר בזה השגל:
@744 **ושמרתם את כל חקותי ואת כל משפטי ועשיתם אותם.** אחשוב שיהיה הרצון בשמירה זכירה ר"ל שנזכור אותם בלבנו ונעשה מעשנו על פי החקים והמשפטים ההם:
@744 **ולא תקיא אתכם הארץ וגו'.** מגיד שאם לא ישמרו ולא יעשו אלו החקים והמשפטים תקיא אותם הארץ ואמנם יהיה אם נסתבכו באלו העונות כלל ישראל או רבי' מהם וזה העונש הוא עונש נוסף על העונש שזכרה התורה בזה ליחידים החוטאים באלו החטאים כמו שביארנו בפרשה הקודמת:
@747 **והבדלתם בין הבהמה הטמאה לטהורה.** שב לזכור זה ובזה המקום להעמידנו על הכונה אשר בעבורה צותה התורה בזה כאלו ביאר כי הכונה בכל זה הוא שנהיה נכונים להקרב להשם יתע' בהשגתנו אותו כפי היכולת ולזה מנעה התורה ממנו אלו המשגלים כדי שלא נהיה נמשכים אל הנאות זה החוש כי זה ממה שימנע שלמות בעיון לטרדת המחשבה תמיד באי זה אופן ישיג שישגל האשה הפלונית וזה ממה שלא יצטרך אל ביאור והנה מנעה התורה ממנו אלו המאכלים מהמעבים החמר לכבותם אור השכל וזכותו בעיון כמו שזכרנו במה שקדם ולזה אמר בזה המקו' ואבדיל אתכם מן העמים להיות לי רוצה לומר כי מפני זה הבדילנו באלו החוקים והמשפטי' משאר מעמים כדי שנהיה להשם יתע':
@749 **ואיש או אשה כי יהיה בהם אוב או ידעוני וגו'.** מגיד שהן בסקילה וכבר התבאר שכל אלו העונשים שהם על ידי ב"ד יהיו כשיהיו שם עדים אומר על פי שנים עדים יומת המת וגו' וראוי שנדע שזה אמנם יהיה אחר ההתראה כי כשלא היתה שם התראה לא יודע אם הוא מזיד או שוגג וכבר ביארה התורה שהשוגג לא יתחייב מיתה במה שחייבה אותו קרבן בפרשת ויקרא והנה נשלם בכאן הביאור בזאת הפרשה:
@778 **אמור אל הכהנים בני אהרן.** מגיד שאין אלו האזהרות נוהגות כי אם בזכרי הכהונות להיותם נבדלים לעבוד השם יתע' וזה נוהג בכהנים לא בחללים כי הם מחוללין מהכהנה:
@778 **לנפש לא יטמא בעמיו.** מגיד שאין טמאת מת נוהגת בגוים כי לרחקם משלמות אנושי כמעט שלא נפקד מהם דבר בסבת המות יהיה בו תועלת לאדם במה שהוא אדם והזהיר הכהנים מלהטמא במתים כאלו יאמר שהם ראוים שיתעבו הענינים החמריים אם לא מצד מה שבהם תועלת לצורה האנושית ולזה יהיו מתרחקים מלהטמא למת ואפשר שיהיה הרצון באמרו בעמיו שיהיה המת בעמיו רוצה לומר שיהיו לו קרובים אבל מטמא הוא למת שאינו בעמיו והוא שאין לו קוברין וכן פירשו בתורת כהנים וכבר יתבאר שזה העניין מצוה ממה שאמר' תורה בענין הנתלים לא תלין נבלתו על העץ כי קבור תקברנו ביום ההוא והנה אם צותה אותנו התורה לקבור כמו או הרשעים כ"ש שמצוה בזה בשאר המתים:
@779 **כי אם לשארו הקרוב אליו.** רצה השם יתעלה שיתטמאו לשאר בשר כדי שיתאבלו עליהם באופן ראוי כי בזה תועלת כמו שביארנו בענין ספוד אברהם לשרה ובכותו עליה ולזה באה המצוה לכהנים שיתטמאו לקרוביהם כמו שיתבאר והנה זכר מאלו הקרובים אביו ואמו ובנו ובתו ואחיו ואחותו והתנה באחותו שתהיה בתולה שאם נבעלה באי זה אופן שיהיה אינו מטמא לה והנה התנה שתהיה קרובה אליו והיא אחותו מאביו לא אחותו מאמו כי אינה יורש' ולזה התנה במוחלט כי אם לשארו הקרוב אליו ומה יתבאר שאינו מטמא לאחיו מאמו ובכלל הנה כמו שבנו ובתו הם ראוים לירשו כן ראוי שיהיה בטמא לאחיו ולאחותו הראוין לירשו ומזה יתבאר מאמרו הקרובה אליו שאינו מטמא לאחיו מאמו ובכלל הנה כמו שבנו ובתו הם ראוים לירשו כן ראוי שיהיה נטמא לאחיו ולאחותו הראוין לירשו ומזה יתבאר מאמרו הקרובה אליו שאינו מטמא לאחותו הארוסה כי אינה קרובה אליו אבל היא קרובה לאישה להדבק בה ולהפרד מאחיה:
@780 **אשר לא היתה לאיש.** למדתנו התורה שאינו מטמא לאחותו שהיתה נשואה אע"פ שנתגרשה כי כבר היתה לאיש:
@780 **לה יטמא.** מגיד שהוא חיי' להטמא לה וכן ההקש בשאר הקרובים הנזכרים כי הם ראויים בזה הדין כמוה וראוי שנדע שהוא אינו מטמא להם אלא בזמן שהם שלמי' שנאמר לאביו ולאמו וגו'. לה יטמא שמורה שהן שלמים והוא מבוא' מצד הוראת הגדר שלא יקראהו הנפלי' בנו ובתו כי לא נשלמ' הוייתם ולזה לא יטמא להם וכך הוא מבוא' שלא הותר לכהנים להטמא אלא לאלו לא לזולתם עמם:
@781 **לא יטמא בעל בעמיו להחלו.** ראוי שתדע שכבר יאמר בעמיו על אשתו כמו שאמר בזאת הפרש' ולא יחלל זרעו בעמיו ומאמרו בעל הנה יתבאר שהתורה צותה אותו שלא יטמא מצד מה שהוא בעל והוא מבואר שהוא בעל מצד אשתו ולזה יהיה הרצון בה שלא יטמא הבעל באשתו שהוא להחלו והוא אשתו הפסולה ואע"פ שאיננה מחללת בעלה אבל היא חללה ובניה חללים הנה אמר שהיא לחללו באופן שאמר בבת כהן את אביה היא מחללת וזה כי אע"פ שהנושא הפסולה לו אינו חלל הנה זה הענין חלול מה לו כי הוא מוריד זרעו מקדושתו ומזה המקום יתבאר שאין כהן מיטמא לאשתו הפסולה וראוי שיתבאר מזה שאפשר לו להטמא לאשתו הכשרה אבל לא יתבאר מזה שיחוייב להטמא לאשתו הכשרה:
@782 **לא יקרחו קרחה בראשם.** ר"ל על מת שמת להם כבר ביאר זה במקום אחר ואמר לא תשימו קרחה בין עיניכם למת ומגיד שהוא חייב על כל קרחה וקרחה באי זה מקום שיהיה מהראש שנאמר בראשם והנה שיעור הקרחה יתבאר ממה שאמר בשעורי הנגעים שהוא כגריס הקלקי:
@782 **ופאת זקנם לא יגלחו.** כבר התבאר פירושו בפר' הקודמת:
@782 **ובבשרם לא ישרטו שרטת.** ר"ל על מת כמו שהתב' בפרש' הקודמת אמר ושרט לנפש לא תתנו בבשרכם:
@783 **קדושי' יהיו לאלהיהם.** ר"ל שינהגו קדושה יתרה בעצמם להתרחק מעניינים המגונים:
@783 **ולא יחללו שם אלהיה'.** ר"ל שאם לא נהגו עצמם בקדושה הנה הם משפילים על אנשים מדרגת השם יתע' אשר הם מוכנים לשרתו:
@784 **אשה זונה וחללה לא יקחו.** ראוי שתדע כי הזונה לפי הוראת הגדר היא הנבעלת לאיש האסור לנשאה והרצון בזה שהיא נוטה מהאדם המותר לה אל אדם האסור לה וחללה היא לפי שהוראת הגדר שנבעלה לכהן הפסול לה כי הכהן מחלל אותה כמו שאמר אחר זה ולא יחלל זרעו בעמיו או שבא מפסולי כהנה כי הזרע ההוא הוא מתחלל וחגם כן הנה כמו שהזונה היא זונה מצד הבעילה כן ראוי שתהיה האשה חללה מצד הבעילה והוא מבואר שלא עבר על לאו זה אם לא נשאה שנ' לא יקחו:
@784 **ואשה גרושה מאישה לא יקחו.** כבר יורה היותה גרושה שנמצא בה דבר גנות ואין ראוי שיקח הכהן לאשה מי שלא הית' ראויה לאשה:
@784 **כי קדוש הוא לאלהיו.** ולזה אין ראוי שיקח אלו הנשים אשר הם בזה האופן מהגנות:
@785 **וקדשתו כי את לחם אלהיך הוא מקריב.** ר"ל כבר תצוה לקדשו ולתת לו מהכבוד חקו מפני כבוד השם יתעלה כי כל מה שיהיו הכהנים יותר מכובדים בעיני האנשים תגדל מעלת מי שהם מיוחדים לשרתו בעיניהם ולזה צוה השם יתעלה שיהיה להם בגדי קדש לכבוד לתפארת וצוה בקרבנות שיהיו תמימים:
@786 **ובת איש כהן כי תחל לזנות.** לפי שאמרה התורה באש תשרף ולא אמרה מות תמות באש תשרף כמו שאמרה בשאר העונשים מות יומת עם הארץ ירגמוהו באבן. מות יומת אביו ואמו קלל דמיו בו. מות יומתו דמיהם בם. מות יומתו באבן ירגמו אותם דמיהם בם. למדנו שכבר התבאר שהיא במיתה ולזה לא נצטרכה התורה לזכור שהיא במתיה רק לזכור באי זו מיתה תמות ולזה הוא מבואר שהזנות הזה היא ענשו בישראל מיתה אלא שהיא יותר קלה כי מפני היותה מחללת אביה החמירה התורה במיתתה ולזה יתבאר שהנשואה היתה מיתתה בחנק אם לא היתה בת כהן כמו שהתבאר בפרש' הקודמת והנה היא מחללת את אביה שיבזוהו אנשים מפני שיצא ממנו זרע פגום בזה האופן:
@787 **והכהן הגדול מאחיו וגו'.** ר"ל שכיון שנמשח בשמן המשחה ולבש בגדי כהן גדול אע"פ שלא לבשם כי אם פעם א' הנה תהיינה נוהגו' בו אלו המצות היתרות:
@787 **את ראשו לא יפרע ובגדיו לא יפרום.** לפי שהוא תמיד במקדש הזהירה אותו התורה שלא יהיה מגודל שער וקרוע בגדים בעת מהעתי' וכבר יתבאר שהוא היה תמיד במקדש מהציץ שהזהירה בו שיהיה על מצחו תמיד:
@788 **ועל כל נפשות מת לא יבא.** לפי שזכר אחר הכלל הזה אביו ואמו למדנו שההבדל בין כהן גדול לכהן הדיוט אינו אלא בכמו אלו הקרובים לא במת מצוה והוא המת שאינו בעמיו:
@789 **ומן המקדש לא יצא ולא יחלל את מקדש אלהיו וגו'.** למדנו שזאת האזהרה היא גם כן בכהן הדיוט בפרש' שמיני ובהיות הענין כן הנה ראוי שנעין מה ההבדל בזה בין כהן גדול לכהן הדיוט אשר בעבורו תתן התורה סבה כי נזר שמן משחת אלהיו עליו ונאמר שהרצון בזה שלא יצא מן המקדש ויניח עבודתו מפני מת שימו' לו והנה אמרו ולא יחלל את מקדש אלהיו שלא יירא שיחלל מקדש אלהיו מפני היותו עובד אונן כי אין עבודתו מתחללת מפני האנינות לפי שהוא משוח בשמן המשחה ולזה ראוי שלא יתפעל כלל מכמו אלו הענינים באופן שתבלבל כונתו ואמנם הכהן הדיוט אם עבד אונן חלל וראוי שתדע כי אע"פ שכהן גדול אינו מחלל עבודה מפני האנינו' הנה הוא אסור באכילת קדשים באנינות כמו שהתבא' בפרשת שמיני מאמרו ואכלתי חטאת היום:
@790 **והוא אשה בבתוליה.** יקח למדנו מאמרו אשה כי אינו לוקח כי אם אשה אחת לא ב' נשים או יותר כי לעוצם קדושתו אין ראוי שישתדל ברבוי המשגל אבל יספיק לו ההכרחי לקיום המין ולמדנו מאמרו בבתוליה שלא תהיה בעולה כי שם הבתולה מורה על העדר הבעילה ממנה ולפי שהבעילה שהיא כחיית עליה היא משכב האדם הנה לא תאסר לכהן גדול מן התורה אם לא ישכב איש אותה אע"פ שכלו בתוליה לסבה אחרת:
@791 **אלמנה וגרושה וגו'.** למדנו אעפ"י שנתאלמנה מן האירוסין אסורה לכהן גדול והסבה בזה כי מפני שהיתה לאיש אחר אינו ראוי שיקח אותה כהן גדול לעוצם מדרגתו על שאר האנשים והנה רצון התורה בזה שאין ראוי שיקח אלמנה וכ"ש גרושה וכ"ש חללה וכ"ש זונה. וראוי שתדע שאם ארס אותה קודם שנתמנה כהן גדול מותר לו לנשאה שנא' לא יקח והרי לקחה קודם היותו כהן גדול:
@791 **כי אם בתולה מעמיו יקח אשה.** מגיד שאין נושא גיורת ומשוחררת ואף על פי שהיא בתולה:
@792 **ולא יחלל זרעו בעמיו למדנו.** שהוא מוזהר מלחלל זרעו באשתו הפסולה שיקח ויתבאר שהי' מתחללת בזה ממה שזכרנו במה שקדם וגם כן הנה מפני שזרעו מתחלל מפני היותו בה הנה ראוי יותר שתהיה היא חללה עד שאם לא נודה שתהיה היא חללה מפני זאת הביאה הפסולה לא יהיה לה טעם לזה הסדור הנזכר באלו הפסולות כי ידמה שהזונה היא היותר מגונה ואחריה החללה ואחריה הגרושה והנה החללה היותר מגונה מהגרושה היא אשר נתחללה מפני בעילה פסולה ואולם החללה שנולדה מפסולי כהנו' יותר מגונ' מהגרושה אבל הענין בהפך ולזה יתבאר מזה העניין שיש בכאן חללה היא מתחללת מפני הביאה הפסולה ומזה המקום יתבאר באופן מה שהכהן מוזהר מלחללה כי כבר הוזהר מלחלל מה שלא בא לעולם כ"ש שהוא מוזהר מלחלל זאת האשה הכשרה לכהונה ואפשר שיהיה הרצון באמרו בעמיו עם עמיו כי אות הבי"ת כבר ישתמשו בה בלשון בזה האופן ויתבאר מזה בביאור שהוא מוזהר מלחלל אשתו:
@792 **כי אני ה' מקדשו.** ר"ל הכהן הגדול ולזה ראוי שיתרחק מאלו הזווגים הפחותים:
@794 **איש מזרעך לדורותם אשר יהיה בו מום לא יקרה להקריב להם אלהיו.** ידוע כי מום יקרא אצל האנשים אי זה שנוי שיהיה ביציאת האדם בכמות או באיכות כאלו תאמר מי שצוארו קצר או מי שידמה לאלו השנוים אשר בבריאה אע"פ שאין בהן הפסד בפעולות הטבעיות והנה על כמו אלו המומין לוקה אם עבר וכבר יהיו באילו המומין מה שהתחלל העבוד' בעבורם והם הנזכרי' בפרטי' הבאים אחר זה כמו שיתבאר במה שיבא ויתבאר מאמרו איש שהקטן אינו ראוי להקריב ולא האש' ולא הטמטום ולא אנדרוגינוס:
@795 **כי כל איש אשר בו מום לא יגש להקריב.** ר"ל מום קבוע כי כבר זכר בפרטים הבאים אחריו מומין קבועים והם העור והפסח ואמנם בסוף העניין זכר מומין עוברים כגון גרב או ילפת וסמך לו כל איש אשר בו מום מזרע אהרן ההן לא יגע להקריב אשי הש' מום בו וגו'. והוא אזהרה לבעל מום עובר ולזה אמר מום בו להעיר שאינו נפסל אלא בעת שהמום בו לא אחר עברו והנה זכרה התורה המומים היותר קשים לפי שכבר יזכור שאם עבד הבעל מום יחלל עבודתו ולזה לא יהיה אלא בכמו אלו המומין החמורים ואם היתה כונת התורה שיהיה כל בעל מום מחלל עבודה היתה זוכרת המומים היותר קלים ומהן נלמד היותר חמורין ואמנם הבדילה החמורין לבאר שבהם ענין נוסף על שאר המומים והוא חלול העבודה וזה מבוא' מהשרשים הכוללים:
@795 **איש עור או פסח.** הנה העור הוא מי שנתעוור ראות עינו לאי זו סבה שתהיה ואע"פ שאין שנוי בתמונתו ומראהו והפסח הוא מי שיהיה פוסל בלכתו:
@795 **או חרו.** הוא מענין חרם שהוא מענין השחתה והפסד הוא מי שנפסד ממנו דבר מהדברים שיש להם רושם בפעולותיו והטבעיות כמו הענין במומין הקודמין לזה כאלו תאמר שיבשה אזהנו או מה שידמה לה:
@795 **או שרוע.** הוא שיהיה נוכף בו דבר יהיה בו הפסד מה בפעולותיו הטבעיות כאלו תאמר שיהיה לו שני שחוסין באוזן כי זה העניין ידמה שהוא משוער בטבע מצד הכמות והתמונה וכאשר נפסד הסדר ההוא לא תהיינה פעולות האבר הוא שלמות וזה מבואר למי שעיין בטבעיות ולזאת הסבה היו חלי מום כשיתבלבלו בעבורו הפעילות הטבעיות כי והוא גדר החלי כמו שהתבאר במלאכת הרפואה ולזה תמצא שאמר הנביא והבאתם גזול את הפסח ואת החולה:
@796 **או איש אשר יהיה בו שבר רגל או שבר יד.** למדנו שהשבר אינו פסל אלא בדברים שבגלוי כגון יד. ורגל:
@797 **או גבן.** הוא שיש לו שני גבינים על עינו ולזה יתבאר שאם אין לו גבים על עינו הוא בעל מום גם כן:
@797 **או דק או תבלול בעינו.** דק הוא מי שיש לו כתם לבנה על השחור שבעינו וזה מבואר מצד הוראת הגדר ותבלול שנתערב מהלובן בשחור ונכלל עמו ומזה יתבאר המומים שבעין הדומי' לו לפי מה שנתב' מהשרשים הכוללים:
@797 **או גרב.** הוא החכוך היבש:
@797 **או ילפת.** הוא חזזית המצרית והוא קשה הרפואה:
@797 **או מרוח אשך.** ר"ל שנתמעך אחד מאשכיו או נכתת ומזה יתבארו המומין אשר בכלי ההולדה הדומים להם:
@798 **כל איש אשר בו מום וגו'.** לפי שזכר אשי ה' שהן דברים נקטרים כאלו תאמר החלבים והקמץ והלבונה ולחם אלהיו שהוא נקטר. ר"ל מה שיקריב ממנו הנה נשפט כי על אלו יתחייב מלקות לפי שאין אחריהם עבודה אבל הם בעצמן גמר עבודה ואמנם לא יתחייבו מלקות על הפתיתה ועל הבלילה והתנופה ושאר מה שדומה להם כי הם אינן ראוין בזה הדין כמו אלו העבודות שהן גמר עבודה אמנם על זריקת הדם יתחייבו כי היא עבודה שאין אחריה עבודה אבל היא יותר מכוונת שבעבודו' כמו שהתבאר בענין הקרבנות ובכלל הנה על כל העבודות שהן גמר עבודה יתחייבו מלקות:
@799 **לחם אלהיו מקדשי הקדשים ומן הקדשים יאכל.** למדנו שהבעל מום חולק עם אחיו הכהני' בקדשי הקדשים ובקדשים קלים ר"ל עם אנשי בית אב:
@800 **אך אל הפרכת לא יבא ואל המזבח לא יקרב כי מום בו.** למדנו שהוא מוזהר מלבא אל הפרכת ומלהתקרב אל המזבח אף על פי שלא עבד. וראוי שנדע שהוא אינו מוזהר כי אם מהמזבח ולפנים כי משם יבאו להקריב בו כי שם פני המזבח כמו שביאר' במה שקדם ומזה הצד נמנע ממנו התקרב למזבח ולא נמנע ממנו הכנס למקדש:
@800 **ולא יחלל את מקדשי כי אני השם מקדשם.** ראוי שתדע שאין הכונה בזה חלול בית המקדש שאם היה הענין כן היה אומר אני הש' מקדשו ואולם אמר אני הש' מקדשים ר"ל הקדשים ומזה המקו' למדנו שהבעל מום מחלל עבודתו כשהי' מומו מכמו אלו המומי' החמורים שזכרה התורה כי לזאת הסבה בחרה הורה לזכור היותר קשה שבאלו המומין כמו שביארנו:
@803 **דבר אל אהרן ואל בניו וינזרו מקדשי בני ישראל.** לפי הענין ממה שנלוה לו למדנו שזה ההנזר הוא מעבוד עבודה וביאר שאם עבד חלל שנאמר ולא יחללו את שם קדשי אשר הם מקדישים לי וראוי שתדע שזה ענין הוא בכהן טמא לפי מה שיתב' ממה שנלוה לו אחר זה והנה יתב' שכבר יתחייב על זה החלול מיתה בידי שמים ממה שאמר אחר זה ומתו בו כי יחללוהו וזה שאם חייב מיתה על החלול אשר מפני אכלו הקדשים בטמאה כ"ש שיתחייב מיתה על החלול אשר מפני היותו עובד בטומאה וזה שאנחנו מצאנו בבעל מום שאיננו עובד ואוכל בקדשים כמו שקדם ולזה תהיה יותר חמורה העבודה מהאכילה וכבא יתבא' זה עוד מעצם העניין ממה שאמרנו בעניין הקרבנות:
@804 **אמור אליהם לדורותיכם כל איש אשר יקרב מכל זרעכם וגו'.** הנה זאת הקריבה היא לאכל וזה יתבאר ממה שזכר אחר זה בקדשים לא יאכל כי על הנגיעה לא יתחייב כרת כמו שיתבאר במעט עיון ממה שנזכר בפרשת צו והנה מה שאין לו מתירים יתיחסו עליו משקדשו ומה שיש לו מתירי' לא יתחייבו עליו עד שקרבו מתיריו וזה כי כבר אמר בפרשת צו בזה העניין והנפש אשר תאכל בשר מזבח הלשמים אשר לה' והוא הבשר שקרבו מתיריו כמו שאמר קודם זה והבשר כל טהור יאכל בשר מכלל שהוא מדבר בבשר שקרבו מתיריו וכן הדין בשאר קדשים אי זה שיהיו ולזה בא המאמר בזה הפסוק:
@804 **וטמאתו עליו.** למדנו שלא יתחייב כרת אלא כשהיתה טמאתו עליו בשלמות אבל אם התחיל לטהר מטמאתו כאלו תאמר שטבל הנה אין טמאתו עליו ולזה לא יתחייב כרת אבל הוא לוקח כמו שיתבאר מהשרשים הכוללים וכבר נתבאר שהטמא שטבל והוא מחוסר כפורים מוזהר מאכילת קדשים ממה שאמר ביולדת בכל קודש לא תגע ולפי שהתנה זה התנאי באכילה ולא בעבודה למדנו שבעניין האכילה הקלה התורה לטבול יום או למחוסר כפורים לא בענין העבודה שהיא חמורה ממנה וזה מבואר מהמקומות הכוללים:
@805 **איש איש מזרע אהרן והוא צרוע או זב בקדשים וגו'.** למדנו מזה הענין שהוא מדבר בתרומה לא בשאר קדשים ולפי שכבר ייחס הטהרה באכילתה להערב השמש כמו שזכר אחר זה למדנו שהטבול יום שהעריב שמשו אוכל בתרומה אף על פי שהו' מחוסר כפרה ואולם בשאר קדשים אינו אוכל מחוסר כפרה כמו שקדם והנוגע בכל טמא נפש הוא טמא מת והוא מטמא הנוגע בו כמו שיתבאר בפרשת פרה:
@805 **או איש אשר תצא ממנו שכבת זרע.** כבר נתבאר בפר' מצורע שהבעל קרי הוא טמא:
@806 **או איש אשר יגע בכל שרץ אשר יטמא לו.** הן הח' שרצים הנזכרים בפרשת שמיני או באדם אשר יטמא לו לכל טמא כמו בועל נדה ורוק הזב. והנוגע במשכבו ומושכו ושאר הטומאות לכללם אשר יטמא בהם האדם:
@807 **נפש כי תגע בו וטמאה עד הערב.** ר"ל שהיא טמאה לעניין אכילת תרומה עד הערב בהכרח וכדי שלא נבין שאחר הערב יהיה מותר באכילת תרומה אף על פי שלא טבל הוסיף לבאר זה ואמר ולא יאכל מן הקדשים כי אם רחץ את בשרו במים ובא השמש ואז יטהר לזה הענין. ר"ל אחר שקיעת השמש:
@808 **ואחר יאכל מן הקדשים כי לחמו הוא.** הנה נתן טעם בהיות מותר לאכל בתרומה תכף שהעריב שמשו ואף עלפי שהוא מחוסר כפרה לפי שזה הקדש הוא לחמו אשר הוא אוכל אותו תמיד ולזה לא החמירה התורה בו כחמר שאר הקדשים. ומזה המקום יתבאר שאין הרצון באמרו וטהר שיטהר במוחלט באופן שלא יהיה מחוסר כפר' שאם היה כן לא היה צריך לתת טעם אל היותו מותר לאכול בתרומה וזה מבואר מאד:
@809 **נבלה וטרפה לא יאכל לטמא' בה.** ירצה בזה בנבלת עוף טהור שהי' מטמאה בעת הכילה כמו שקדם והוצרכ' התורה להזהיר זה לפי שהכהנים הותרו באכילת חטאת העוף שאינה שחוטה ואולי יחשבו מפני זה שתהיה נבלת עוף טהור מותרת להם ולזה ביארה התורה שהם גם כן אסורין בה ומטמאין באכילתה:
@810 **ומתו בו כי יחללוהו.** למדנו שהזר יתחיי' מיתה בידי שמים בהיותו נהנה מתרומה בזה האופן:
@810 **ושמרו את משמרתי ולא ישאו עליו חטא ומתו בו כי יחללהו.** ר"ל שישמרו משמרת התרומה ויזהרו מאכילתה בטמאה וביאר שם ש'אם יאכלוה בטמאה יתחייבו מיתה בידי שמים לפי שכבר חללוה והורידוה מקדושתה ומזה יתבאר שעל תרומה טמאה לא יתחייבו מיתה בידי שמי' שהרי היא מחוללת:
@811 **וכל זר לא יאכל קדש.** ר"ל מי שאינו מזרע הרן:
@811 **תושב כהן ושכיר לא יאכל קדש.** הגיד בזה כי אף על פי שהתרומה היא לחמו של כהן הנה לא יותר לו להאכילה לעבדו שאינו קנוי לו קניין הגוף:
@812 **וכהן כי יקנ' נפש קניין כספו הו יאכל בו ויליד ביתו הם יאכלו בלחמו.** מגיד שכיון שנפשו קנוי לו באי זה אופן שיהיה הנה הוא אוכל בתרומה ומזה המקום יתבאר שאפילו בהמתו של כהן אוכלת בתרומה כי נפשה קנויה לו ועוד שאי לאומר שיאמר שיותר עבד כנעני לאכל בתרומה מצד מעלתו כי אין לו מעלה על התושב והשכיר אבל יהיה העניין בהפך כשהיה השכיר עבד עברי ואמנם הותרה לו אכילת תרומה מפני היות גופו קנוי וכן הענין בבהמה כי גופה קנוי. ומזה המקום יתבאר שהמאורסת לכהן אוכלת בתרומה מן התורה כי היא קנויה לו:
@813 **ובת כהן כי תהיה לאיש זר.** ר"ל שהיא מאורסת לא לכהן היא בתרומת הקדשים לא תאכל. הנה המורם מהקדשים הוא חזה ושוק ומגיד שהיא אסורה בו ויתבאר גם כן שהיא אסורה בתרומה ממה שיבא אחר זה הפסוק ועוד כי כבר שבה קני למי שאינו אוכל בתרומה והנה נכלל בזה גם כן הנבעלת לפסול לה כי היתה לאיש זר לה לפי משפטי התורה ויתבאר שהיא אסורה לאכל בתרומה לעולם כי לא הותרה לאכל בתרומה כי אם האלמנה והגרושה שלא היה בהויתה לאיש והוא אסור כמו שנתבאר בפסוק הבא אחר זה:
@814 **ובת כהן כי תהיה לאלמנה וגרושה וזרע אין לה.** ר"ל שאף על פי שנתקדשה לזר או נתאלמנה או נתגרשה ואין לה זרע ממנו היא מותרת לאל בתרומה ולזה יתבאר שלא היתה מותרת בה בעודה אסורה לו ושאינה חוזרת לחזה ושוק שהוא יותר חמור מתרומה ולפי שהזרע הפסול פוסלה מלאכל בתרומה הנה נלמד שהפסולה שיש לה זרע מותר לאכול בתרומה. ר"ל שהי הזרע ההוא מכהן הנה היא אוכלת בעבורו כי ההקש הוא אחד ואין הבדל בזרע בין שיהיה הזרע או זרע הזרע באי זה אופן שיהיה כי הכל יקרא זרעה בלשוננו כמו שיתבאר במקומות רבים ושמתי את זרעך כעפר הארץ וגו'. והנה הכונה בו זרע הזרע והנה יתבאר שהערל אסור בתרומה מפסח שהוא קל ונאסר עם זה הערל מאכילתו וזה יתבאר מהמקומות הכוללים:
@814 **וכל זר לא יאכל בו.** ר"ל בלחם רביה שהוא התרומה:
@815 **ואיש כי יאכל קודש בשגגה ויוסף חמישיתו עליו.** ר"ל שמי שיאכל תרומה מהזרים בשגגה הנה יוסיף עליה החומש שהוא רביע מה שאכל כמו שביארנו בפרשת ויקרא והנה השגגה היא כשלא ידע שהיא תרומה או שלא ידע עשה כי באלו הצדדים יקרא האדם שוגג בעשותו דבר מה שמוזהר מעשותו וזה מבואר מאד וראוי שתדע שהאכילה והשתיה והסיכה דינן אחד בזה העניין כי הכונה בזה היא ההנאה בגופו שיכלה גו התרומה בה והוא מבואר שהאכילה לא תהיה לפי הנהוג כי אם במה שראוי לאכילה מצד עצמותו ושיהיה ראוי לכהן להנות בה ואמנם שהוא מחוייב שיהיה ראוי לאכילה מצד עצמותו הוא מבואר מהשרשים הכוללים ואמנם שהוא מהויי' שיהיה ראוי לכהן להנות בו שנאמר' ונתן לכהן את הקדוש מכלל שהיא היתה קנין לכהן הזה ולזה צוה להשיבה לו ולו היתה אסורה בהנאה הנה אינה קנין לו ולפי שהאכילה לא תהיה לפי הנהוג אלא במה שיאכל האדם עד שיהיה שבע לא במה שיאכל אחר שהוא קץ במזונו מפני שבעו הנה לא יוסיף האדם חומש אם אכל תרומה בזה האופן:
@815 **ונתן לכהן את הקדש.** למדנו מזה שמה שישיב לכהן הוא קדש ודינו כדין התרומה ומזה יתבאר שהחומש ג"כ הוא בתרומה ולפי שאמ' ונתן לכהן שהרצון בו הכהן הידוע הנה הוא בואר שהוא רמז בזה אל הכהן שהיתה ממנו התרומה שאכל והנה יתבאר מזה שהקרן יחוייב שישיב לכהן ההוא שהוא הקודש שאכל ואמנם החומש יתנהו לכל כהן שירצה:
@816 **ולא יחללו את קדשי בני ישראל.** ר"ל שלא יוציאו לחולין התרומה בשיאכלו זרים ממנה או באיזה אופן שיהיה כאלו תאמר כשתיה או בסיכה ולפי שכבר אמר בתרומה קודם זה:
@816 **את אשר ירימו לה'.** הנה יתבאר מזה שאף על פי שלא הרימו תרומה עדיין אם אכלו מן הטבל הראוי להרים ממנו תרומה יתחייבו מיתה לפי שהם חללו מה שבו מהתרומה ולפי שהתורה לקחה החמור שבזה הסוג והיא חייבה בו מיתה והוא הטבל שתרומתו בתוכו הנה יתב' מהשרשי' הכוללים שהטבל שנטלה תרומתו ולא מעשרו הוא באזהרה ולא במיתה:
@817 **והשיאו אותם עון אשמה באכלם את קדשיהם.** הרצון בעון ענש ואשמה שממה כטעם תאשם שומרון שהוא מעניין שממה ור"ל שכבר ישיאו עצמם עונש של שממה באכלם את קדשיהם כי כבר נתחללו כמו שקדם ויהיה עונש עליהם מיתה כי אני הש' מקדשם ולזה יחטא בזה האופן מי שיחללם:
@819 **איש איש מבני ישראל ומן הגר בישראל.** הוא הגר צדק שהוא כישראל לעניין מצות התורה כמו שנזכר בתורה פעמים:
@819 **אשר יקריב קרבנו לכל נדריהם ולכל נדבותם.** הנה הנדבה הוא שיקדיש הבהמה ויאמר הרי זו עולה והנדר שיאמר הרי עלי עולה ואח"כ יפרישנה:
@820 **לרצונכם תמים זכר בבקר בכבשים וגו'.** הנה לא זכר העוף לפי שאן אלו המומין שזכר נוהגין בו ולזה לא נאמר בו תמים והנה יתבאר מהשרשי הכוללים שהוא לא סלק מן הדין כי אם כמו אלו המומין ואולם המומין החמורין מהן כמו מחוסר אבר או מה שישימהו במדרגת הטרפה שהוא אסור אפילו להדיוט הוא פסול בקדשים. הלא תראה כי גם מהמותרין באכילה לא התירה התורה להקריב כי אם התורים ובני היונה:
@821 **כל אשר בו מום לא תקריבו.** לפי שכבר תקרא הקרבה הקדשת הבהמה בנדבה או הפרשת הבהמה לשלם הנדר והוא מבואר מצד הוראת הגדר וממה שנזכר בפרשת ויקרא מזה הנה יתבאר מזה שהמקדיש בהמה בעל מם למזבח עובר בלאו:
@822 **ואיש כי יקריב זבח שלמים להשם.** הבדילו מהעולה לפי שאין התנאי בו שיהיה זכר ואולם לענין המומין דינן שוה:
@822 **לפלא נדר או בנדבה.** ר"ל שזאת ההקרבה היתה על הנדר שפרש או שהקדיש הבהמה לנדבה להיות שלמים:
@822 **תמים יהיה לרצון.** מצות עשה הוא שיהיה תמים ובזה האופן ישלם בו הרצוי:
@822 **כל מום לא יהיה בו.** למדנו מזה שאפילו שאחר שהקדישו מוזהר שלא להטיל בו מום והוא מצות לא תעשה:
@823 **עורת או שבור.** כבר התבאר עניינים במומין הקודשים ושם יתבאר שהשבירה לא תיפסל אלא כאברים הנגלים:
@823 **או חרוץ.** מעניין חרץ כאלו תאמר שנסדק עורו אם עצם מעצמיו והוא מתייחס לשבור וסמך לו ולזה לא ינהג אלא במקומות הנגלים כמו הענין בשבור:
@823 **או יבלת.** הוא בלבן העין לפי מה שיורה עליו הגדר שאם היה בשחור הנה תהיה עורת ולפי שאלו המומין שזכר בפרט הם מומין קבועים למדנו מזאת היבלת היא שיש בה שער שאם לא היה בה שער הוא הום מום עובר לפי מה שהתבאר בחפוש:
@823 **או גרב או ילפת.** כבר נתבארו במומי האדם:
@823 **לא תקריבו אלה להש' ואשה לא תתנו מהם על המזבח להש'.** לפי שכבר קדמה האזהרה מלהקדיש בעל מום הנה תהיה האזהר' בזה המקום באמרו לא תקריבו שלא יזרק דמם על המזבח ולזה סמך לו האזהרה מהקריב אשה מהם על המזבח להשם כי הזריקה מכשרת האשה לתתו על המזבח והנה הזהיר על זה בשלמי' וכ"ש בעולה ושאר הקדשים החמורים מהם:
@824 **ושור ושה שרוע וקלוט נדבה תעשה אותו ולנדר לא ירצה.** הנה השרוע הוא מי שהוא יתר אבר כאלו תאמר שיש לו חמשה רגלים וב' שחוסין של אזן. וקלוט הוא שפרסתו עגולה כפרסת החמור ואמרו נדבה תעשה אותו אין הרצון בו להקדישו למזבח כי כבר קדמה האזהרה בזה ואמנם הרצון בו להקדישו לבדק הבית שהוא קדושת דמים ואולם מה שאמרו ולנדר לא ירצה שמורה לפי מה שביארנו שאם נדר בהמה לבדק הבית מהבהמות הראויות למזבח כמו שו ושה הנה אין ראוי שיפריש על זה הנדר בהמ' בעלת מום ולפי שאין בזאת הפרשה נזק לבדק הבית ועם זה הקפידה בו התור' למדנו שכר הקפידה בזה מצד המנע הקרבתה למזבח ולמדנו מזה שהמקדיש לבדק הבית דבר ראוי למזבח יחוייב שיהיה קרב למזבח:
@825 **ומעוך וכתות ונתוק וכרות.** הנה מעוך הוא שנמעכו אשכיו או אחד מהם וכתות שנכתתו אשכיו או אחד מהם ונתוק וכרות הוא שנתק אחד מאשכיו או נכרת וכ"ש אם נתק הגיד או נכרת כי בזה השחתה יותר עצומה לכלי ההולדה:
@825 **לא תקריבו ליי' ובארצכם לא תעשו.** לפי שסמכה אל אזהרת השחתת כלי ההולדה במוחלט שהיא אזהרה לכל ישראל הנה תהיה זאת האזהרה גם כן לכל ישראל ואם היא להזהר מהקדיש בעלי מומין למזבח או להזהיר משחיטתם שהיא כשרה בזר ולפי שכבר הזהיר' התורה על שחיטתם בביאור בפרשת שופטים שנאמר לא תזבח ליי' אלהיך שור ושה אשר יהיה בו מום כל דבר רע הנה לא ידמה שתהיה זאת האזהרה מהקדשים וכפל האזהרה בזה המקום שלא לחשוב שלא תהיה זאת האזהרה כי אם בעולה לא במה שלמטה ממנה בקדשים והנה אמרו ובארצכם לא תעשו אי אפשר שיהיה הרצון בו שלא תנהג זאת האזהרה כי אם בארץ ובשור ובשה. וזה כי לסבה בעינה שימנע זה העניין בשור ושה ימנעו בשאר בעלי חיים כי אין לאומר שיאמ' שכבר נמנע זה בשור וזה מפני שאפשר להקריבו למזבח שהרי בארה התורה שכבר ימנע להטיל מום בקדשים לא בחולין ואם היתה הכוונה שימנע להטיל מום בחולין במוחלט הנה היה ראוי שתזכור זה בתורה במומין האחרים שאין בהם מהגנות וההפסד אצל הטבע כמו מה שיש באלו המומין ומהם נלמד שכן הענין בשאר המומין והנה גם כן זרות הפעל זה בגנותו אין בו רושם בהעשותו בארץ או בחוצה לארץ ולזה יהיה הרצון באמרו ובארצכם לא תעשו שלא תחשבו שיהיה המנע זה מצד מה שהוא ליי' אבל אם לא היה ליי' יותר זה הפעל לעשות שאפילו חוץ מבית המקדש שהוא לכם ואינו ליי' אתם מוזהרים מעשות זה הפועל המגונה לפי שיש בו השחתה לכלי ההולדה אשר שם השם יתעלה בב"ח לשמור מינו ולזה יהיה נכלל בזה חוצה לארץ וזה מבואר מאד כי אין לצאת המצוה התלות בארץ:
@826 **ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה.** הנה לכם ה' יתעלה הוא העולה כמו שאמר קרבני לחמי וגו'. וראוי שיבאר שאין מקבלים מהגוי כי אם עולה כי אינו במדרגה שיתכן שיקריב שלמים שיאכל הוא וה' ית' על שלחן אחד ואין ראוי ג"כ שיקריב קרבנות באים על חטא כי אינו מחוייב בהם ואולם העולה נקבל ממנו לפי שהיא באה בנדר ונדבה:
@826 **כי משחתם בהם מום בם לא ירצו לכם.** ר"ל שבהם דבר נשחת והוא מום בהם ולזה לא יהיה לרצון אם יקריבום לשם יתע' ולפי שכבר אמר בכללות כל אשר בו מום לא תקריבו למדנו שאי זה מקום שיהיה בבהמה ממה שנקרא מום בה לפי הוראת הגדר אע"פ שהו' מום עובר הוזהרנו מהקרבתה ליי' וכבר התבאר בפרשת שופטים שאפילו בזביחה הוזהרנו אפי' במום עובר שנאמר כל מום רע כ"ש בזריקת דמים ובהקטרה. וראוי שתדע שהטומטום והאנדרוגינוס הם בעלי מומין מצד הפסד כלי ההולדה בהם וזה מבואר בטומטום וכן האנדרוגינוס אין בו כח אל ההולדה כמו שיתבאר לי שעיין בטבעיות עיול שלם עם שאינו לא זכר ולא נקבה והתור' דקדקה בקרבנות בקצתם שיהיה זכר ובקצתם שיהיה נקבה וכאשר לא דקדקה התורה בזה לפי זה הענין מה שהו' זכר או נקבה לא מה שאינו לא זכר ולא נקבה ויתב' שהרובע והנרבע והנעבד והממית את האדם פסולים למזבח לפי שכבר אסרה התורה אתנן זונה ומהיר כלב כ"ש אלו שנעשה הגנות בעצמם:
@828 **שור או כשב או עז.** למדנו שלא יותר למזבח אלא מה שהוא ממין מיוחד לא מה שהוא מורכב משני מינים כי הוא אינו שור ולא כשב ולא עז וכבר יתבאר שלא יותר אם לא היה דומה למינו והמשל שאם היה בכאן עז והוא דומה לכבש הנה לא יותר למזבח כי הוא אינו כבש ולא עז לפי שהוא דומה לכבש:
@828 **כי יולד.** למדנו שלא יותר למזבח אלא הנולד כמשפט לא שקרעו את אמו והוציאוהו דרך דופן כי אין זאת הלידה טבעית ויורה זה על חסרון בטבע בנולד ולזה לא תתחזק לצאת דרך הרחם עם שהוא אפשר שלא נשלמה הויתו עדין אבל התעורר לצאת קודם זמנו לסבה מה כאלו תאמר לחסרון המזון או למה שאפשר שיהיה סבה בזה והם הסבות אשר אפשר שינתנו בהפלת העובר:
@828 **והיה שבעת ימים תחת אמו.** למדנו מזה שראוי שתהיה לו אם ואז יותר למזבח לא אם נשחטה אמו קודם שנולד עם שאין זו לידה לפי הוראת הגדר ובכלל הנה לסבה בעינה אשר נמנעה הקרבת יוצא דופן תמנע הקרבת היתום ואין ראוי שנבין שיחוייב שתהי' לו אם שבעת ימי' כי אין בחיות אחר לידותו רושם בשלמו' הילוד כי כבר אפשר שיינק מבהמה אחרת ולא יהיה בזה לו שום הפסד:
@828 **ומיום השמיני והלאה ירצה לקרבן אישי ליי'.** דקדקה התורה בזה לפי שלא יתבאר לנו מהנולד שלא יהיה נפל אף על פי שנולד באופן שלם אם לא עברו עליו ז' ימים ולזה לא יותר להקריבו קודם זה הזמן:
@829 **ושור או שה אותו ואת בנו לא תשחטו ביום אחד.** לפי שלא אמר ליי' כמו שאמר קודם זה ואחר זה למדנו שזאת האזהרה נוהגת בחולין ובמוקדשין ולפי שאמר בכאן שה תמורת מה שאמר קודם זה או כשב או עז למדנו שהיא נוהגת בכלאים כאלו תאמר שה הבא מכבש ועז ויתבאר שאינו נוהג אלא בבהמה טהורה שנאמר שור או שה ולפי שאמר לא תשחטו למדנו שלא יעברו על זאת האזהרה אם לא נשחטו שניהם לא אם מת אחד מהם באופן אחר או שניהם וידמה שלא יהיה זה הדין נוהג אלא באם ובנה לא באב ובנו כי אינו מפורסם בכמו אלו הב"ח מי אביהם ולא נהגו האנשים ליחס הנולדים האלו לאביהם אבל לאמם כי היא לבדה תשתדל בהזנתם ובגדולם וכבר יסופק אם ינהג זה הדין גם כן בזכרים כשיודע שהוא אביו לפי שכבר הוציאה התור' זה בלשון זכר ולזה לא יתחייב מלקות אם נשחט האב ובנו ביום אחד אף על פי שהוא ידוע שהוא אביו:
@830 **וכי תזבחו זבח תודה ליי' לרצונכם תזבחו.** ר"ל שתהיה כוונתכם להתרצות בזה הוכח לשם יתעלה ולזה יחוייב שיהיה זה לכונה רצויה וברצון ולא באונס:
@831 **ביום ההוא יאכל.** הזהיר שלא יותירו מבשר זבח התודה עד הבוקר וכ"ש מהחלבים ומקדשי הקדשים וכבר הזהיר בזה בחלבים ביותר קל מהם והוא חלב השלמים שנאמר ולא ילין חלב חגי עד בקר:
@832 **ושמרתם מצותי ועשיתם אותם אני יי'.** ר"ל אף על פי שיכריחו אתכם לעבור על דברי להפר את בריתי:
@833 **ולא תחללו את שם קדשי.** ר"ל שלא תקלו בי ותחללו שמי לעבור על דברי לשמוע אל המכריח אתכם לעבור עליהם ליראתכם ממנו כי בזה מהחלול הנפלא אפילו למלך בשר ודם עד שכבר תמצא שיתירו מסירת עצמם להריגה להשמר שלא ימרדו בו ליראת המכריח אותם לבזו' המלך ההוא:
@833 **ונקדשתי בתוך בני ישראל.** זה הקדוש הוא שיתיר עצמו למיתה מיראתו מעבור על דבר השם יתעלה כמו שנפרסם מענין חנניה מישאל ועזריה אלא שזאת המצוה לא יתחייבו בה אם לא היו שם מאנשי האמונה מה שיראו זאת הקדושה שנאמר בתוך בני ישראל והוא מבואר שאמרו בתוך בני ישראל הוא מעיר על הקבוץ ר"ל על הקהל והוא מבואר מצד הוראת הלשון ולזה לא יחוייב להתיר עצמו למיתה על זה אם לא היו שם עשרה מישראל כי הוא הקבוץ הראשון וראוי שנדע שזה הדין יהיה כשתהיה כונת המכריח על זה להעביר אותו על מצות השם יתע' כדי שימרוד בו ולזה סמך זה למה שאמר ולא תחללו את שם קדשי ואולם אם לא כיון חלל הש' יתעלה כבר יותר לו לעבור על מצות התורה להציל עצמו מהמיתה אלא אם היתה העברה ההיא ע"ז או גלוי עריות או שפיכות דמים כמו שהתבאר בשרשים הכוללים:
@833 **אני יי' מקדשכם.** ר"ל שהשם יתעלה מקדש ישראל ומבדיל אותם לעבודתו בזאת התורה השלמה ולזה ראוי שנשמר בכל הפנים שאפשר שלא יקלו אנשי התורה לעבור עליה כי זה אולי יהיה סבה שתסור זאת התורה מישר' במוחלט וזה מבואר מאד עם מה שקדם מהדברים:
@834 **המוציא אתכם מארץ מצרים.** ר"ל שאני השתדלתי בזה האופן הנפלא להוציא אתכם מארץ מצרים עם רבוי הנפלאות והמופתים כדי שתוכנו לקבול התורה באופן שאהיה לכם לאלהים כי בזה תגיע לכם ההצלחה האנושית עם שבזה האופן תדבק בכם השגחתי ותשמרו מהרבה מהרעות הנכונות לבא עליכם ולזה ראוי לכם שלא תאבדו זאת המתנ' הנפלאה אשר נתתי לכם אשר בה אהיה לכם לאלהים ולמנהיג והיא התורה:
@836 **דבר אל בני ישראל ואמרת אליהם מועדי יי' אשר תקראו אותם מקראי קדש.** ראוי שתדע שהמועדים המיוחסים היותם מקראי קדש לקריאתנו הם שאר המועדים זולת השבת כי השבת הוא מקרא קדש מצד עצמותו אין לנו התחלה בהיותו נקרא ביום שהוא בו. ואולם שאר המועדים הם תלוים בעבור השנה והחדש אשר ענינם מסור לב"ד כמו שביארנו בפרשת בא אל פרעה ולזה תמצא שאמרה התורה זה הענין בכללות מפני שאר המועדים לא מפני השבת לזה לא יאמר בשבת דבר אלא שהוא מקרא קדש כי הוא מקרא קדש מצד עצמותו וכאשר התחיל לזכור שאר המועדים הקדים ואמר אלה מועדי יי' אשר תקראו אותם במועדם כי קריאתם במועדם מסור לנו כמו שביארנו במה שקדם:
@837 **כל מלאכה לא תעשו.** הוא כולל מהמלאכות שהם לצורך אוכל נפש ושאר המלאכות שהם מלאכת עבודה וכבר בארנו במה שקדם שכבר יתחייב בשבת על כל מלאכה ומלאכה אף על פי שנכללו כלם בלאו אחת לפי שהתורה בארה שכבר נכלל בזה הלאו מה שיתחייב עליו בייחוד והיא ההבערה שנאמר לא תבערו אש בכל מושבותיכם ולזה יתבאר שכבר יתחייב על כל אחת משאר המלאכות כמו שהתבאר מהשרשים הכוללים:
@837 **שבת היא ליי' בכל מושבותיכם.** לפי שלא זכר בכאן דבר שלא יהיה נוהג בכל מושבות אמר בכל מושובותיכם לא שלא יהיו שאר המועדים גם כן נוהגים בכל מושבות אלא שכבר זכר מהם מה שאינו נוהג בכל מושבות והם הקרבנות:
@838 **אלה מועדי יי' אשר תקראו אותם במועדם.** למדנו מזה שמה שנקרא מהם הוא קיים איך שיהיה. ר"ל מה שיקראו ב"ד הגדול כי הדבר מסור להם ואף על פי שטעו בקריאתם אין לנו אשם בזה וכבר בארנו בפרשת בא אל פרעה איך תהיה זאת הקריאה ושהיא באמצעות הראייה. ולזה אפשר שיקרא בזה הטעו' שלא יראה הירח בזמנו אם בסבת אידים או בסבת הרים מונעים מראיית הירח ולפי שכבר אמר אשר תקראו אותם במועדם והקריאה הזאת היא באמצעות הראיי' למדנו שהרואין הירח יותר להם ללכת לב"ד להעיד שכבר ראוהו אפילו בשבת כדי שיקדשו החדש בזמנו כי התורה צותה שיקדשו בזמנם ולפי שזה הענין יהיה בקבלת עדות ובדרישה ובחקירה אם דבריהם אמיתיים לפי מה שאפשר אם מצד הסכמת העדים קצתם לקצת אם מצד הסכמת מה שיראה מחכמת הכוכבים למה שהעידו וכמו אלו הפעולות לא יורגש העשותם כי אם ביום הנה לא תהיה זאת הקריאה כי אם ביום קודם עבור יום החדש כי לא יתכן שיקדשוהו אחרי עברו וזה מבואר בנפשו ולזאת הסבה ארז"ל שאף על פי שראוהו ב"ד וכל ישראל בליל שלשים ולא הספיקו לומר מקודש ביום השלשים עד שחשכה הרי החדש ההוא מעובר לפי שאין מקדשין את החדש אחר עבור יומו ותימה על הר"ם ז"ל שכתב מה שהוא סותר זה הדעת מפני מה שאמרו בראשון מראש השנה מאיימין את העדים על החדש שנראה בזמנו וכו'. וכבר יתבאר שיפורש המאמר ההוא באופן בלתי סותר למאמר הראשון והוא גם כן פסק זה המאמר הראשון ולזה היו דברי' סותרים קצת מקצת או יהיה זה טעות נפל בספרים והנה בקדוש החדש תלוי קדוש המועדי' ולזה יהיה הקדוש הרמוז בזה הפסוק קדוש החדש לא קדוש המועדים כי אחר שנקבע החדש כבר יודע מעצמו המועד אשר באותו כאלו תאמר שהוא יום העשירי או יום חמשה עשר לחדש ההוא בחדש הראשון הוא ניסן כמו שביארנו במה שקדם בפרשת בא אל פרעה:
@839 **בין הערבים פסח ליי'.** ר"ל ששחיטת הפסח הוא בין הערבים והוא מחצות היום ואילך כמו שבארנו בפרשת בא אל פרעה:
@840 **שבעת ימים מצות תאכלו.** הכונה בזה שיהיה מה שיאכלו מהלחם באלו השבעה ימים מצה לא חמץ לא שיהיה מצות לאכול מצה כל אלו הז' ימים ולזה אמר במקום אחר מצות יאכל שבעת ימים שהוא מורה שזאת האכילה היא רשות וכבר בארנו זה בשלמות בפרשת בא אל פרעה:
@841 **כל מלאכת עבודה לא תעשו.** כבר בארנו ענינה בפרשת בא אל פרעה:
@842 **והקרבתם אשה ליי' שבעת ימים.** כבר נתבאר בפרשת פנחס שזה האשה הוא עולה פרים בני בקר שנים ואיל אחד ושבעה כבשים. וזה יהיה מוסף היום בכל יום מאלו הימים ולפי שאמר בזה המקום אשה ליי' ולא ביאר בזה יותר למדנו שהמספר הנאמר בזה בפרשת פנחס הוא למצוה לא לעכב והמשל שאם אין להם שנים פרים מקריבים אחד אין להם פרים מקריבים כבשים ואיל אין להם איל מקריבים כבשים אין להם ז' כבשים מקריבים ששה שנאמר והקרבתם אשה ליי' מכל מקום:
@844 **כי תבאו אל הארץ אשר אני נותן לכם וקצרתם את קצירה.** למדנו שאין העומר בא אל מהקציר שבאר ישראל והוא מבואר מצד הזמן שה הקציר הוא קציר שעורים כי קציר החטים לא יהיה בארץ ישראל בזה בזה הזמן:
@844 **והבאתם את עומר ראשית קצירכם אל הכהן.** למדנו מזה שזה העומר יחייב שיהיה ראשית לכל הנקצרים ולזה הוא מבואר שאסור לקצור מה שהוא ראוי להביא ממנו עומר קודם קצירת העומר אלא אם היה זה למצוה שנאמר ראשית קצירכם אל הכהן לא ראשית קציר מצוה:
@845 **והניף את העומר לפני יי' וגו'.** כבר ביארנו במה שקדם שהתנופה הוא למזרח מוליך ומביא מעלה ומוריד והנה זאת התנופה איננה לעומר בעצמו כי כבר קדם בתנופה שהיא לדבר המתוקן להקריבו כאלו תאמר אשי החלבים ומה שידמה להם מה שנזכר בו התנופה ואולם היא לסולת העומ' כשהו' באופן מוכן להקריבו וכבר התבאר בפרשת ויקרא איך נעה מנחת העומר והוא מה שאמר ואם תקריב מנחת בכורים וזה מבואר שהמאמר בו במנחת העומר היא מנחת בכורים וזה היא שראשונה לכל המנחות הבאות מן החדש ואין לאומר שיאמר שיהיה הרצון בה ב' הלחם הבאים בחג השבועות שנקראו מנחת בכורים במה שאחר זה כי לא יצדק בה מה נאמר בזאת המנחה בפרשת ויקרא וזה כי היא בלתי שתעשה חמץ כי כבר יקריבו ממנה ליי' מגרש' ומשמנה על כל לבונתה וכבר נאמר שם במאמר כולל כל המנחה אשר תקריבו ליי' לא תעשה חמץ. ואמנם שתי הלחם הבאי' בעצרת הם חמץ כמו שיתבאר בזאת הפרשה ולזה הוא מבוארת שזאת המנחה היא מנחת העומר ושהיא באה מצה ואופן מעשיה היא באופן שנתבאר שם והוא שקולין את התבואה אשר בעומר ההוא באש כדי שייבש ויתכן לטחון אותו ולקחת הסלת ממנו וטוחנים אותו בריחים של גרוסו' כדי שתהי' הסולת יותר יפה וזהו אמרו גרש כרמל ואחרי כן יבדרו הסלת היותר יפה ממנה בכל הפנים שאפשר ויקחו ממנו עשרון שהוא השעור הקטן אשר ממנחות לפי שלא נזכר בתורה לזאת המנחה שעור ויבללו אותו בשמן בקטן השעור הנזכר בתורה והוא לוג כי לא נזכר שם שעור לשמן אשר יבללוהו בו ונותנין עליו קומץ לבונה ומניף הכהן זאת המנחה במזרח ומגישה למקום הגשת המנחות וקומץ מגרשה ומשמנה על כל לבונתה כמו שנזכ' בפרש' ויקרא ומקטיר זה הקומץ והשאר נאכל לכהנים ונאפה מצה כמשפט המנחה שהקריבו ממנה ליי' עם שזה העניין הוא ביום השני של פסח שאי אפשר לאכול חמץ ולמדנו שהתנופה היא בכהן שנאמר יניפנו הכהן אבל קודם התנופה כמו הקצירה וההבאה כשר בכל אדם ולמדנו שהבאת העומר היתה ביום שני של פסח שנאמר ממחרת השבת וזה השבת הוא בהכרח אם יום ראשון של פסח אם יום שביעי כי לכל אחד מהם שבת כמו שנזכ' במה שקדם וכבר יתבאר ממה שאמר בספר יהושע שהוא ממחר' יום ראשון של פסח שנאמר ויאכלו מעבור הארץ ממחר' הפסח מצות וקלוי וכבר עשו הפסח בי"ד יום לחדש בערב כמו שנזכר שם והנה היה יום י"ו בניסן מחרת הפסח כי בליל ט"ו היה נאכל והוא ממחרת השבת הנזכר בזה הפסוק ולזה הזכיר כי ביום ההוא אכלו מצו וקלוי כי כבר נאסר להם קודם הנפת העומר לאכול מהחד' לחם וקלי וכרמל כמו שיתבאר בזאת הפרשה והנה חוייב שיהיה מצות לפי שכר היה אסור להם לאכול חמץ וזה ג"כ לאות כי אמרו ממחרת השבת ירצה בו מחרת יום ראשון של פסח ולפי שהנפת העומר הוא ממחרת השבת והספירה שזכר אחר זה היא גם כן ממחרת השבת והיא גם כן מהחל חרמש בקמה למדנו שהקצירה לא תהיה אלא אחר יום ראשון של פסח ולפי שזאת המנחה קבוע זמנה והוא ממחרת השבת למדנו שזאת הקצירה דוחה שבת. ולפי שהראוי בספירה שתהיה בהתחלה אחרי הדבר הנספר לא באמצעם ויהיה התחלת הימים לפי התורה בתחלת הלילה למדנו שמצות הקצירה היא בתחלת ליל י"ו בניסן ולפי שאמר מהחל חרמש בקמה למדנו שמצות העומר לבא מן הקמח וכן מצותו להביאו מן הלח ולזה צותה התורה שיביא קלוי באש ליבשו אלא שהוא מבואר ממה שנאמר בזאת הפרשה שאם לא מצאו מהקמה אפשר להביא מהעמרים אף על פי שהם יבשים שנאמר והבאתם את עומר ראשית קצירכם כיון שהוא ראשית הקצירים הנה אין קצירתו בי"ו בניסן מעכבת:
@846 **ועשיתם ביום הניפכם את העומר כבש תמים בן שנתו וגו'.** זה הקרבן יתר הוא על קרבן מוסף היום והיתה מנחתו כפל מנחת הכבש ולפי שאמר בלולה בשמן למדנו שהיא תהיה בלולה בשמן שהגבילה תורה לשני עשרונים והיא שלישית ההין ואמנם נסכו לא נכפל לפי מה שיתבאר מענין הנסכים בפרשת פנחס ושם נבאר בג"ה איך תהיה זאת ההקרבה לנסכים וראוי שתדע שהסלת הזאת הבלולה בשמן היתה כלה נשרפת על מזבח העולה שנאמר אישי ליי' ואולם היין אסור לנסכו על מערכת האש שלא יבכה אש המזבח אבל הכהן יוצק משם על היסוד למקום שיהיה נפשך בו שירי הדם והיה היין מסיר עפוש הדם ההוא שנאמר בפרשת פנחס בקדש הסך נסך שכר ליי' ולזה לא יחוייב שיהיה נשפך על המזבח':
@848 **ולחם וקלי וכרמל לא תאכלו וגו'.** הזהיר מאכילת לחם מהתבוא' חדשה ולא קלי ולא כרמל והוא הגרש. ר"ל שנפרך בריחים של גרוסות קודם הקרבת העומר ולפי שבא זכר האזהרה אחר זכרונם למדנו שהם שלשה לאוין כי אמרו לא תאכלו שב לכל אחד מהם ביחוד לא למה שיכללם ולו היתה האזהרה ראשונה היינו אומרים שהכל לאו אחד אלא שזכרה התורה הפרטים מפני שלא נמצא שם אחד שיכללם וזהו אחד מהשרשים הכוללים ולפי שאמר עד עצם היום הזה למדנו שמתיר החדש אף על פי שלא הביאו מנחת העומר יותר החדש תכף ביום ההוא בעצמו ואם לא יביאו מנחת העומר לא יותר עד עבור י"ו בניסן שנאמר עד עצם היום הזה והוא מבואר שהיום הזה בכלל האסור שאם היה מותר החדש בהגיע יום הנפת העומר הנה יהיה החדש מותר קודם הנפת העומר וזה הפך מה שאמרה התורה ולפי שנא' שאיסור החדש נוהג בכל מושבות למדנו שאיסור החדש נוהג מן התורה בין בארץ בין בחוצה לארץ והוא מבואר מזה המקום שהעומר מתיר החרש בכללו אע"פ שלא נקצר אבל הוא מחובר בקרקע והוא מבואר שאין העומר מתיר עד שלא היה מחובר לקרקע בעת הנפת העומר וצמח אחר זה כי אינו מתיר הוא כי אם הנקצרים והעומדים ליקצר שהחלו בצמיחה אף על פי שלא נשלמה ולזה יתיר העומר קציר החטים להדיוט אף על פי שהוא נקצר זמן ארך אחר הנפת העומר:
@849 **וספרתם לכם ממחרת השבת וגו'.** למדנו שיום הבאת העומר בכלל הימים הנספרים כי ממחרת יום ראשון של פסח יחל המספר והנה שבע השבתות הם שבעה שבועות של ימים שהם מ"ט יום כבר אמר תמורת זה בפרש' ראה שבעה שבועות תספור לך ואמר תמימות תהיינה כדי שלא נחשוב שיהיה הרצון בשבתות האלה שבת בראשית כי כבר יקרה שיהיו ז' מאלו השבועות בפחות משבעה שבתות ולזה בארה התורה שאלו השבע שבתות יהיו מ"ט יום ולזה אמר עד ממחרת השבת השביעית תספרו חמשים יום. ר"ל עד ממחרת השבוע השביעי תספרו שהוא יום החמשים והנה אינו בכלל המספרים כי כבר אמר שבע שבתות תמימות תהיינה שבעה שבועות תספור לך. וכבר נלמד זה גם כן מהיובל שנמנה תשע וארבעים שהם שבע שבתות שנים ואחד נקדש שנת החמשים כמו שנתבאר בפרשת בהר סיני ובזה נמנה בכאן מ"ט יום ונקדש יום החמשים והו' חג השבועות ולמדנו מזה שמצוה למנו' השבתו' והימים ואחשוב ספירת השבועות היא שנמנה שבוע א' בהגיע שבעת ימים ושני שבועות בהגיע י"ד יום וכן על זה הדרך עד שיהיו שבעה שבועות ואמנם במה שבין השבועות אין ראוי לספור שבועות כאלו תאמר שכאשר היו עשרה ימים אין ראוי לשוב לספור שהוא שבוע אחד ושלשה ימים כי המספר השבועות ראוי שיהיה בדרך המספר לא שימנה השבוע האחד ויחזור וימנהו ששה פעמים וזה מבואר בנפשו כי המספר לא יהיה בזה האופן:
@850 **עד ממחרת השבת השביעית תספרו חמשים יום.** ר"ל עד ממחרת השבועה השביעית תספרו שהוא יום הנ' ואז ביום החמשים תקריבו מנחה חדשה ליי' או יהיה הרצון באמרו חמשים יום עד חמשים יום כמו ארבעים יכנו שהרצון בו עד ארבעים יכנו כמו שנבאר שם בג"ה ובכא יום החמשים תקריבו מנחה חדשה ליי' ולפי שהוא קרא זאת מנחה חדשה למדנו שהיא חדשה למנחות החטים לא לכל המנחות כי כבר קדמה לה מנחת העומר ולמדנו מזה שאין ראוי להביא מנחת החטים קודם זאת המנחה והוא מבואר שאם הקריב מנחה קודם מנחת העומר שהיא פסולה שאפילו להדיוט לא הותר אז זה החדש ואולם אם הקריבה אחר מנחת העומר קודם זאת המנחה איננה פסולה כי לא זכרה התורה בביאור המנע זה:
@851 **ממושבותיכם תביאו לחם התנופה וגו'.** למדנו ששתי הלחם אינם באים אלא מן הארץ כי לא כלל בזה בכל מושבותיכם רק המושבו' המיוחדים ולמדנו שכל אחד משתי הלחם בא מעשרון אחד ויתבאר שהם באים מן החדש כי התורה קראה זאת המנחה מנחה חדשה:
@851 **חמץ תאפינה.** לפי שמדת העשרון יחוייב שתהיה מלאה סולת שנאמר שני עשרונים סלת למדנו שהוא מביא שאור ממקם אחר לחמצו שאם היה מודד הסלת עם השאור היתה המדה חסרה או יתרה ואם יקח מתוכה לחמצה עד שיעשה שאור הנה יהיה נפסל בלינה והנה יתבאר אחר זה איך תהיה תנופת ב' הלחם:
@851 **בכורים ליי'.** ר"ל שתהיה מנחה ראשונה לשאר המנחות שהם באים מן החטים והנה מפני זה בכורים שיובאו ליי' מראשית פרי האדמה ולזה ראוי שלא יביאו בכורים קודם שתי הלחם כי אלו הבכורי' הם שיובאו באופן שיותר שלם כמו שיתבאר מעניין שא הבכורים הם שיובאו באופן היותר שלם כמו שיתבאר מעניין שאר הבכורים עם שאלו הבכורים הם של צבור ושאר הבכורים הם של יחיד ויש לצבור קדימה על היחיד אלא מפני שנקרא העומר גם כן מנחת הבכורי' כמו שבארנו אם הביא בכוריו אחר העומר אינם פסולים ואמנם קודם זה הם פסולים כי כבר יהיה מהם מהחטים והשעורים כמו שיתבאר בעניין הבכורי' בפרשת כי תבא והם אסורין קודם מנחת העומר אפילו להדיוט:
@852 **והקרבתם על הלחם וגו'.** הנה זה הקרבן הוא בא בכלל הלחם מלבד מוסף היום הנזכר בפרשת פינחס:
@853 **ועשיתם שעיר עזים אחד לחטאת ושני כבשים לזבח השלמים.** ראוי שתדע שאלו הכבשים הם קדשי קדשים ולזה לא יהיה שחיטתם כי אם בצפון ואינם נאכלין כי אם לזכרים כשאר קדשי הקדשים כמו שנתבאר בפרשת צו ואולם יתבאר שאלו הכבשים הם קדשי קדשים לפי מה שיתבאר במה שנזכר מהם בפרשת ויקרא והנה ראוי שלא יהיו השלמים בקדושה פחות מהלחם הבא עמהם ועוד כי התורה אמרה באלו הכבשים קדש יהיו ליי' לכהן ואם לא נוספה בהם קדושה על קודשת שאר השלמים לא היתה התורה צריכה להודיע לנו שהם קדש ואמנם כונת התורה שהם קדש מבין שאר השלמים וזה מבואר מאד:
@854 **והניף הכהן אותם על לחם הבכורים תנופה לפני יי' על שני כבשים.** ר"ל שיניף הכהן הכבשים בעודם חיים ותנופתו אותם יהיה נוסף על נפתו לחם הבכורים או רצה בזה שיניפם ויניף להם הביכורים עמהם בטעם מגרשה ומשמנה על כל לבונתה ואמר על לחם הבכורים להורות שלחם הבכורים הוא העקר ואמנם מצב אלו הדברים בעת ההנפה הוא שיהיו שתי הלחם על שני הכבשים:
@854 **קדש יהיו ליי' לכהן.** ר"ל שקצתם הוא ליי' וקצם לכהן והם ליי' ולכהן במדרגת קדשי הקדשים ולזה ינהג בהם דין קדשי הקדשים כפל בכל ענייניהם. וראוי שתדע שאם לא נמצאו כבשים לא תבטל מפני זה מנחת שתי הלחם כי היא העקר לפי מה שזכרה התורה מעניינה ולזה הקדימה גם כן לזכרה קודם זכרון שני הכבשים להורות שאין לה התלות בהן אבל בלי ספק לכבשים האלו התלות בשתי הלחם כי אופן הקרבתם מתאחד עם שי הלחם כי הנפתם הוא עם שתי הלחם וכן הנפת אישי החלבים אשר להם וחזה ושוק מתאחדת עם שתי הלחם כמו שהתבאר במעט עיון ממה שנזכר בפרשת צו מתורת זבח השלמים ומזה המקום יתבאר שאם אין שם שתי הלחם לא תתכן הקרבת שני הכבשים ואולם שאר הקרבנות הנזכרים בזה המקום אף על פי שהם באין בגלל הלחם הנה אין להם התלות בו עד שיבטלו בבטולו כי לא נמצא להם קשר עם הלחם הזה באופן שיהיה להם התלות בו:
@855 **וקראתם בעצם היום הזה מקרא קדש יהיה לכם.** מגיד שקריאתו מקרא קדש מיוחסת לנו כי היא תלויה קדוש החדש שהוא מסור לב"ד וזה שאחר שקדשו ראש חדש ניסן יהיה יום הט"ו חג המצות ואחריו ימנו מ"ט יום והחמשים יום יהיה חג שבועות:
@855 **כל מלאכת עבודה לא תעשו.** היא המלאכה שאינה לצורך אוכל נפש כמו שקדם בפרשת בא אל פרעה:
@855 **חקת עולם בכל מושבותיכם לדורתיכם.** ר"ל השביתה ממלאכת עבודה ואולם הקרבנות אינם נוהגות בכל מושבות כי אם במקום אשר יבחר יי' והוא בית המקדש כמו שנתבאר במה שקדם:
@856 **ובקצרכם את קציר ארצכם וגו'.** כבר התבאר בפרשת קדושים ובא בזה המקום כי הכונה בעינה שצוה השם יתעלה שיקריב מנחת העומר ושתי הלחם מהקציר החדש להעיר כי הכל בא מהש' יתעלה והוא צוה גם כן להטיב מהם אל העניים קודם שיבא לידינו להעיר כי זה בא מהש' יתעלה והוא רצה שיזכרו עניים בזה החלק ואנחנו בשאר כי הכל בא מאתו ומאתו הכל:
@858 **בחדש השביעי באחד לחדש יהיה לכם וגו'.** ומזה המקום יתבאר שהתרועה על הצר הצורר יהיה אחריה ענוי נפש כי לזה התכלית תהיה לפי שבעשור לחדש הזה יהיה יום הכפורים כמו שנתבאר בפרשת אחרי מות הנה הקדימה התורה לעורר האנשים על התשובה והשבר חלב והכנעו מר"ה הזה והוא מבואר שהתקיעה בשופר נותנת חרדה בלב כמו שאמר אם יתקע שופר בעיר ועם לא יחרדו ובכלל הנה הקולות החזקים הם מרעידים מאד ובזה מביא להכנע הנפש הבהמית וכאלו העירנו בזה שיכנעו לבבנו ונפשפש במעשינו לתקן המעוו' בהם כדי שנהיה נכונים לכפרה ביום הכפורים וראוי שתדע כי התקיעה תהיה בזולת תרועה אמר בפשרת בהעלותך תתקעו ולא תריעו ואמנם התרועה לא תהיה בזולת תקיעה אמר שם בעניין תרועה ותקעתם תרועה תרועה יתקעו למדנו שמדרך התרועה שתהיה תקיעה לפניה ולאחריה ובכלל הנה מפני שהכונה בזה להחריד הלבבות ולעוררם על התשובה הנה רצתה התורה שיהיה זה הקול באופן שיתכן זה יותר ולזה אמר בו תרוע' וכן אמר בפרשת בהעלותך במה שהוא לזאת הכונה בעינה והרעותם בחצוצרות ונתבאר שזאת התרועה היא בשופר ממה שצותה התורה ביום הכפורים של יובל שהוא לזא' הסבה בעינה שנאמר בפרשת בהר סיני והעברת שופר תרועה בחדש השביעי וגו'. ושם נבאר בג"ה מה שיורה עליו שם השופר:
@859 **כל מלאכת עבודה לא תעשו והקרבתם אשה ליי'.** הנה המוסף הננזכר בפרשת פנחס ולמדנו מזה המקום שהפר והאיל והכבשים הנזכרים שם אינם מעכבים זה את זה שנאמר אשה ליי' מ"מ שיהיה שם אשה:
@861 **אך בעשור לחדש השביעי הזה.** כבר התבאר בפרש' אחרי מות ענין זה הענוי וזה האשה שזכר בכאן הוא מוסף הנזכר בפרש' פנחס:
@861 **ועניתם את נפשותיכם וגו'.** בארה התורה שהתחלת הענוי הזה הוא מהערב של יום התשיעי ויהיה מערב עד ערב באופן שיהיה יותר שלם זמן הענוי והשביתה מכל מלאכה ולזה אמר תשבתו שבתכם והיה זה כי ימינו הם מתחילין מן הערב מפני היותינו חושבין לחשבון הלבנה כמו שביארנו בפרשת בא אל פרעה ואף על פי שמצד השמש היה יותר ראוי שיהיה היום מתחיל מזריחת השמש כמו שיתבאר לתוכנים ולזאת הסבה גם כן היתה השנה אצלנו מתחדשת מן החדשים אשר לירח ואף על פי שאינה שנה באמת לפי השמש וכאלו היה זה מכון להעיר שאין האלהות והממשלה לשמש כמו שהיו חושבין עובדי השמש והיה חשבונינו לחשבון הכוכב אשר אי אפשר שיטעה בו אדם לראותו שנוי עניינו בכל חדש וחד שהוא הירח שיחסר אורו פעם ויוסיף פעם:
@862 **וכל מלאכה לא תעשו בעצם היום הזה כי יום כפורים הוא לכפר עליכם.** למדנו שהיום בעצמו מכפר ואף על פי שאין קרבנו קרב וראוי להיותכן כי הקרבנות אינם אלא להישירנו על התשובה ואם היושרנו אליה בזולת הקרבנות הנה מן הראוי שיכפר והנה באר בזה המקום שכבר יתחייבו על עשיית כל מלאכה בעצם היום הזה כרת וכן אם לא יתענו בעצם היום הזה ואמר והאבדתי את הנפש ההיא מקרב עמה תמורת הכרת להעיר על שכוון בכרת ובר בארנו עניינו במה שקדם והנה ביאר שהשביתה ממלאכה ביום הכפורים נוהגת בכל מושבות שנאמר כל מלאכה לא תעשו חקת עולם לדורותיכם בכל מושבותיכם וזכר אחר זה שנית חיוב הענוי להורות שהוא גם כן נוהג בכל מושבות עם שהוא מבואר בעצמו שאין לו התלות בארץ ולא בענין הקרבנות אבל אם היה אפשר היה ראוי שיחזק עניינו בבטול הקרבנות כדי שישלם לנו בזה מן ההישרה אל התשובה מה שנפקד ממנו בבטול הקרבנות מההישרה אליה:
@868 **בחמשה עשר יום לחדש השביעי וגו'.** הנה הסכות יתבאר לפי הוראת הגדר שהוא סכוך נעשה מעצים תלושים בזולת בנין והוא נעשה על הרוב מעצים שיש בהם עלים כדי שיהיו למחסה מהשמש אמר וסכה תהיה לצל יומם מחורב וכבר נאמר בספר עזרא צאו ההר והביאו עלי זית ועלי עץ שמן ועלי הדס ועלי תמרים ועלי עץ עבות לעשות סכת בכתוב ולזה הוא מבואר שזה הסכוך לא יהיה כי הם בתלוש ומבואר גם כן מצד הוראת הגדר שאינו תוך הבית שאם היה כן הנה אינו מסכך באלה אבל הבית הוא שיהיה מסך משיכנס בו השמש והיושב בו יושב בבית לא בסכות ומבואר גם כן מצד הוראת הגדר שאין הסכוך הזה נעשה מהכלים ולא מהאוכלין והנה חג הסוכות לא יתמיד כי אם שבעת ימים אולם וביום השמיני יהיה שבתון כמו שיתבאר אחר זה אך לא ישבו בסכות ואמנם שזה החג הוא ליי' כי הכונה בכל המועדים הוא לעבודתו יתעלה ולהתקרב אליו כפי היכולת כמו שיתבאר בג"ה:
@869 **ביום הראשון מקרא קודש.** כבר התבאר זה במה שקדם:
@870 **שבעת ימים תקריבו אשה ליי.** כבר נתבאר זה האשה בפרשת פנחס ומזה המקום יתבאר שהפרים והאלים והכבשים של מוסף היום אינם מעכבים קצתם קצת שנאמר אשה ליי' מ"מ ביום השמיני מקרא קדש יהיה לכם וגו'. כבר נתבאר בפרשת פינחס זה האשה והרצון באמרו עצרת הוא שיהיו נעצרים מעשיית מלאכת עבודה והם הלכות שאינם לצורך אוכל נפש:
@871 **אלה מועדי יי' וגו'.** ר"ל שאר המועדים זולת השבת כי אחר זכירתו השבת אמר אלה מועדי יי' אשר תקראו אותם במועדם וכאשר השלים המאמר בהם אמר שאלו המועדים שזכר הם המועדים שרמז אליהם בראש המאמר הזה שמיוחסת קריאתם אלינו:
@871 **עולה ומנחה.** כבר נזכר מנחת אלו העולות בפרשת פינחס. והנה העולה היא עקר והמנחה היא נמשכת לזה ולזה אין ראוי שתקריב מנחת העולה קודם העולה:
@871 **זבח ונסכים.** ידוע כי לעוה יהיו נסכים מוגבלים כמו שנתבאר בפרשת פינחס כמו שיש לה מחנחה מוגבלת ולזה ראוי שנעיין למה לא אמרה התורה עולה ומנחה ונסכים ונאמר כי ידמה שיהיה סבה בזה להורות כי הנסכים אינם מתאחדים עם העולה כהתאחדות המנחה לה כי אינם להקרבה אבל להסיר הזוהמא כמו שכתבנו ויהיה הרצון בזבח זבח השלמים כי כבר יחוייבו באלו המועדים להקריב שלמי חגיגה ושלמי שמחה כמו שיתבאר אלא שכבר יקשה לזה מפירוש מה שאמר אחר כן דבר יום ביומו והנה לא הוגבלו אלו השלמים בכל יום מאלו הימים ולזה היותר נאות שיאמר כי הרצון בזבח העולה גם כן אלא שהיא תהיה נקראת עולה מצד מה שיקטירו ממנה במזבח שהיא עולה עליו בכלליו ונקראת זבח מצד מה שיקטירו ממנה במזבח שהיא עולה עליו בכללות ונקראת זבח מצד הזביחה אשר בו יוקח דמה לזרוק על המזבח והוא מבואר שהמנחה מתאחדת עם הנקטר מהעולה והנסכים עם דמה הנשפך אל יסוד המזבח כי לזאת הסבה היו ולהורות על זה קראה התורה בשני אלו השמות מתחלפי' עם המנחה והנסכים':
@871 **דבר יום ביומו.** למדנוח מזה שקרבנות היום הם תמידין ומוספין אין להם תשלומין למחר:
@872 **מלבד שבתות יי'.** למדנו מזה שאלו הקרבנות יקריבו בכל יום מאלו מלבד הקרבנות המוגבלים בשבת והם מוסף שבת שאם היה שבת באחד מאלו הימים הנה יקריבו בו יותר על אלו הקרבנות המיוחדים לשבת:
@872 **מלבד מתנותיכם.** אחשוב שירמוז בזה מה שיתנו ליי' בזולת דר או נדבה כמו מעשר הבהמה ובכורות:
@872 **ומלבד כל נדריכם ומלבד כל נדבותיכם אשר תתנו לה'.** הקרבנות הבאים בנדר או נדבה כמו העולה והשלמים והמנחה ולמדנו מזה שכל קרבנות יחיד קרבים ביום טוב וידמה שהעולה שאן זמנה מוגבל ביום ההוא כמו עולת יחיד אינה רוחה יום טוב כי לא יעשה ביום טוב רק מה שהגבילה אותו התור' אם אינו לצורך אוכל נפש ואמנם השלמי' ומה שידמה להם יקריבו ביום טוב כי הם צורך אוכל נפש ואולם בחולו של מועד יקריבו כל הקרבנות:
@873 **אך בחמשה עשר יום לחדש השביעי באספכם את תבואת הארץ תחוגו את חג יי' שבעת ימים וגומ'.** ביאר בזה כי סבת זה החג מפני שאז אסף כל אחד ממנו תבואתו מגרנו ומיקבו כדי שיכיר בו כי הכל בא לו מה' ית' ולזה באה זאת המצוה:
@873 **תחוגו את חג יי' שבעת ימים.** כבר ביארנו במה שקדם כי זאת החגיגה היא זביחת שלמים ולזה תמצא שאמ' משה ויחוגו לי במדבר תמורת הזביחה כמו שזכרנו במה שקדם ואמר שבעת ימים ואם היא בחמשה עשר ימים לחדש השביעי כמו שזכרנו להורות שזאת החגיגה יש לה תשלומין כל שבעה:
@873 **ביום הראשון שבתון וביום השמיני שבתון.** ר"ל ביום השמיני לראשון שזכר כי בכל אחד מאלו שני הימים צוונו לשבות ממלאכה:
@874 **ולקחתם לכם ביום הראשון פרי עץ הדר כפות תמרים וענף עץ עבות וערבי נחל.** לפי שאין זאת המצוה כי אם ביום הראשון לפי זה המאמר ובסוף אמר שהוא ששבעה ימים למדנו שאמרו ולקחתם לכם ירצה בו כשלא תהיו לפני יי' והוא כשיהיו חוץ לבית המקדש ואמנם לפני יי' אלהים והוא בבית המקדש תהיה זאת המצוה שבעת ימים ולפי שאמר ולקחתם לכם ביום הראשון למדנו שאין אדם יוצא באלו הדברים שזכר אחר זה אם לא היו שלו ולזה הוצרכה התורה לאמור לכם. פרי עץ הדר כפות תמרים וגו'. יורה מצד הוראת הגדר באמרו פרי עץ הדר אל האתרוג וזכרה אותו התורה בזה הלשון להורות כי היא בחרה בו מצד שהוא הדר ולזה לא נצא אם לא היה הדר ומזה המקו' יתבאר ששאר הדברים הנלוים עמו יחוייב בכל אחד מהם ג"כ שיהיה הדר וזה מבואר מהשרשים הכוללים:
@874 **כפות תמרים.** הוא הלולב והוא נקרא בזה השם מצד מה שהתמידו עליו להחזיק קצת בקצת כמו הכף שמחזיק במה שמקיף בו אמנם אחר שיתפרדו עליו כאן ולכאן איננו נקרא בזה השם גם איננו אז הדר ולזה הוא פסול:
@874 **וענף עץ עבות.** הוא ההדס שהוא עבות ר"ל שיש לו עלים רבים מקיפים בו יוצאים ממקום אחד והמעט שיפול בו זה השם הוא כשהיו לו שלשה עלין מקיפין בו יוצאים בגבעול אחד ואולם אם יצאו שנים שנים אין זה עבות וזה מבואר מצד הוראת הגדר:
@874 **וערבי נחל.** הוא מין מן הצמחים גדל על הרוב בנחלים ולזה קראה אותו התורה ערבי נחל לא שתקפיד שיהיה גדל על נחל כי היא אמנם תקפיד על המין שילקח ממנו והנה הנקרא ערבי נחל הוא צמח שעלה שלו משוך ופיו חלק וקנה שלו אדום וממנו ימצא שבפי עלהו פגימות דקות מאד מאד וקטנות ואולם מה שעלה שלו עגול ופיו דומה למגל אינו נקר' עבי נחל ואיננו כשר וראוי שתדע כי מפני שאמר כפות תמרים וענף עץ עבות וערבי נחל הנה מן הראוי שיהיו שלשה אלו המינים יחד ועם כל זה אם לקחן אחד אחד יצא שהרי לקחה כלם ואמנם האתרוג ילקח לבדו ולזה לא אמרה תורה פרי עץ הדר וכפות תמרים והנה יקרא הלולב האחד כפות תמרים מצד עליו שבהם יתהוו התמרים ואולם מה שאמרה התור' וענף עץ עבות ידמה שהרצון בו ענף ועץ ר"ל שאין מתנאיו שיהיה ענף אבל יהיה מותר אע"פ שהו' העץ בכללו והנה זה אפשר בזה הצמח לקטנו ואפשר שיובן מזה ג"כ שילקח מזה הצמח ענף ועץ באופן שיהיה עבות מצד רבוי עליו ורבוי ענפיו ולזה ילקחו שלשה כדי הדס כי כבר יקרה בזה הצמח שלא יהיו בו יותר משלשה ענפים ולזה ילקח העץ בהלקחם ולפי שאמר וערבי נחל שרומז אל רבוי והפחות שיפול בו זה השם הוא שני הנה ילקח שני בדי ערבה. וידמה והוא הנכון שהרצון בזה שיקח ענף עץ עבות וערבי נחל ולזה לא יתחייב לקחת מכל אחד מהם כי אם בד אחד והוא מבואר שהלקיחה הנהוגה בהם הוא שילקחו דרך גדלתם ולזה אם לקחם של כדרך גדלם לא יצא כי התורה תצוה ענינם באופן הנהוג מהן כמו שהתבאר מהשרשים הכוללים וכאלו שב זה אל מה שהוא מחוייב מצד הוראת הגדר. וראוי שתדע שאלו המינים הארבעה מעכבין זה את זה כי התורה צותה שנקח אלו המינים כלם ולפי שהאתרוג יהיה לבדו ושאר המינים הם יחד הנה ראוי שילקחו בימין הג' מינין והאתרוג בשמאל:
@874 **ושמחתם לפני יי' אלהיכם שבעה ימים.** ירצה בזה שישמחו שם במקדש שבעה ימים בלקיחת אלו הארבעה מינין ובכל מיני השמחה ויתבאר שזאת השמחה אינה דוחה יום טוב וכל שכן שבת לפי שהתורה אמרה כי ביום הראשון לא ישמחו כי אם בלקיחת אלו הארבעה מינין אך בשאר מיני שמחות שיהיה בהם מה שלא יתכן העשותו וביום טוב לא יותר להם לשמוח והנה תכלול ג"כ זאת השמחה זביחת שלמים והם הנקראים שלמי חגיגה שנאמ' וזבחת שלמים וכלת שם ושמחת לפני יי' אלהיך ומזה המקום יבאר שאין שמחה זו אלא בבשר בהמה לא בבשר העוף כי השלמים אינם באים כי אם מהבהמה:
@875 **וחגותם** אותו חג ליי' שבעת ימים בשנה. הנה אמרו אותו שב אל היום הראשון שזכר בפסוק הקודם ואמר שבעת ימים בשנה להורות שיש לחגיגה זו תשלומין כל שבעה ואמר בשנה לפי מה שאחשוב להורות שאין חגיגת יום זה משתלמת בחג הסוכות של שנה אחרת:
@875 **חקת עולם לדורותיכם בחדש השביעי תחוגו אותו.** באר שזו המצוה נוהגת לדורות:
@876 **בסכות תשבו שבעת ימים כל האזרח בישראל ישבו בסכות.** צוה שנשב ז' ימים בסוכות באופן שבתנו בבית ולזה יחוייב שנאכל ונישן שם כי באלו העניני' נשתמש מהבית ולפי שזאת הישיבה מתיחסת לישיבה בבית והיא תמורתה והישיבה בבית להנאה לא צער הנה כשתהיה הישיבה בסכה בצער לא יתחייב לישב בסוכה ועוד שכבר חוייבנו לשמוח באלו השבעה ימים ולזה ראוי שיעזוב כל דבר שמצער שמבלבל השמחה ומזה המקום יתבאר שאם ירדו גשמים יצטערו בהם בשתם אז בסכה הנה יהיו הבעלים פטורים מהישיבה אז בסכה ולפי שהסכה היא אהל מה והיה מגדר האהל שיהיו לו שלשה דפנות האחד לאחריו והאחד בצד הימין והאחד בצד השמאלי והוא מבואר בנפשו מענין האהלים שיעשו מוכרי המסחרים הנה יספיק בסכה שיהיו לו שלשה דפנות ומזה ג"כ יתבאר שהדופן השלישי הוא שיהיה לו שיעור מעט כי כן דרך האהלים ולפי שאהל לא יקרא אהל אלא אם היה לו גג טפח הנה יחוייב בסכה שיהיה לה גג טפח ולפי שזה האהל הוא תמורת הבית שהוא עשוי לשבת האדם בו הנה לא יהיה גבהו פחות מעשרה טפחים כי גובה האדם הבינוני בהיותו יושב הוא זה השעור והוא המצב היותר מיוחד שיהיה לו בשבתו בבית ולפי שזה האהל עשוי לאכול בו הנה יחוייב שיהיה באופן שיחזיק ראשו ורובו ושלחנו וזה השיעור יהיה על המעט ז' טפחים על ז' טפחים והוא מבואר שהיושב בסכה שתחת הסכה אינו יושב בסכה שהוא רואה בהיות אותו בתוכה כי אינה מסככת עלו על דרך האמת והוא אינו יושב ג"כ בסכה העליונה כי הוא אינו רואה באוירה ולזה אינו יוצא ידי סכה וכ"ש אם היתה הסכה תחת הבית או תחת האילן:
@876 **כל האזרח בישראל ישבו בסכות.** אין ראוי שנלמוד מזה שלא תהיה זאת המצוה נוהגת בגר צדק כי דין הגר במצות התוריות כדין כל ישראל כמו שהתבאר ממקומות רבים מהתורה ואמנם זכר האזרח כי יחשב שיהיו קצת האזרחים פטורים מזאת המצוה והם השרים אשר לגודל מעלתם לא יאות להם לשבת בסכות כי אם בהיכלות יפות ושלמי הבניין באופן שיהיו חזקים מאד ולזה בארה התורה שדין כל האזרחים שוה בזאת המצוה:
@877 **למען ידעו דורותיכם כי בסכות הושבתי את בני ישראל בהוציאי אותם מארץ מצרים.** זה זכר אל המופת הנפלא שעשה הש' ית' לישראל בהוציאו אותם מארץ מצרים שהיה עננו עומד למסך שנאמ' ועננך עומד עליהם ולפי שזאת המצוה היא למען ידעו בעבור זה הפלא שעשה הש' יתע' אז לישראל הנה ראוי שיהיה זאת הסכה באופן שישלוט בה העין ולזה ראוי שלא תהיה גבוהה מכ' אמה:
@878 **וידבר משה את מועדי יי' וגו'.** ר"ל שכבר השלים מה שצוהו הש' ית' שידבר אל בני ישראל כמו שכתוב בראש העניין:
@880 **צו את בני ישראל ויקחו אליך שמן זית זך כתית למאור.** הנה התנה בשמן המאור והוא אשר ישימו במנורה שיהיה שמן זית לא שמן שאר הדברים שיעשו מהם שמן כגון האגוזים והשומשמין ומה שידמה להם ואמר זך כתית להורות שזה השמן יוציא מהזית על צד הכתישה מבלי טעינה בקורה כי השמן הזה הוא היותר זך בלי ספק וכבר יתבאר לך זה מהיין שיצא מהענבים אחר סחיטתן מעצמו כי הוא היותר נבחר מאד מהיין שיצא אחר זה מהם עם הטעינה בקורה כי כבר יתערב עמו טבע השמרים שיצא מהם וזה מבואר מן החוש ולפי שלא התנה שיהיה כתית כי אם למאור למדנו ששאר השמנים שיצאו מן הזית אחר השמן הנזכר כלם כשרין למנחות ולזה לא התנה דבר במנחות אבל אמר בשמן והוא מבואר ממה שנזכר במנחות בפרשת ויקרא ובזאת הפרשה ובפרשת פינחס ואף על פי שכבר נאמר שם במנחות תמיד של שחר בשמן כתית ונאמר ג"כ בפרשת ואתה תצוה הנה הוא למצוה לא לעכב ויעיד על זה מה שאמר בכאן כתית למאור הורה שלא יוצרכו לקחת שמן זית זך כתית כי אם למאור לא למנחות ועוד כי כבר תמצא כי כשנזכרו המנחות בכללם בפרשת שלח לך שלא הותנה בהן שיהיה השמן כתית. וכן תמצא במנחות הנזכרות בפרשת ויקרא שלא נזכר שם כי אם שמן ולא הותנה בו שיהיה כתית להעלות נר תמיד למדנו מזה שכבר תחוייב שתהיה זאת ההדלקה באופן שיעלה השלהבת תמיד ולזה היה מתנאי השמן שיהיה זך בזה האופן כי כל מה שיהיה יותר זך יהיה יותר אמתי בהעלת השלהבת ומזה המקו' יתבאר שהפתילה יחוייב ג"כ שתהיה באופן שיתכן שתעלה נר בקלות והוא מה שאמר להעלות נר תמיד מעיר שזאת המצוה דוחה את השבת כי לה זמן קבוע בכל יום והנה ידליקו המנורה בערב ובבקר כמו שביארנו בפרשת ואתה תצוה ושם פירשנו זה הפסוק ופסוק הבא אחריו וראוי שתדע כי עריכת המנורה יחוייב שיהיה לפני יי' ולזה ראוי שיהיה פני המנורה לצד המערה ושלא יערוך הכהן המנורה בחוץ ואחר כך יביאה בפנים אבל יחוייב שידליקה בפנים:
@882 **על המנורה הטהור' יערוך את הנרות לפני יי' תמיד.** למדנו שאין ראוי שיהיה דבר מפסיק בין הפתילה והמנורה כאלו תאמר צרור או קיסם אבל יחוייב שתהיה הפתילה בגוף המנורה:
@883 **ולקחת סלת ואפית אותם שתים עשרה חלות שני עשרונים יהיה החלה האחת.** הנה מפני שהסלת מורה על הקמח היותר דק והיותר לבן הנה נמשך לזה לכונת התורה לדקדק בענין שיהיה בתכלית היופי והדקות ולזאת הסבה בעינה דקדקה בחטים שיהיו נבחרים ושתתוקן בהם המלאכה בתכלית מה שאפשר באופן שתהיה הסלת יותר נקי וזה כולל לכל המקומות שנזכר בהם סלת והוא מבואר שאפיות אלו החלות הוא בעזרה וכן לישתו ועריכתם לאפות אותן וזה שאפילו בקדשים שנפסלו דקדקה התורה שלא ישדפו חוץ לעזרה כמו שנתבאר בהפרשה צו כ"ש שתדקדק באפייתן ובבושלן. ומזה המקום יתבאר שכן העניין בשאר המנחות כי הם כלם קדש קדשים:
@883 **שני עשרונים יהיה החלה האחת.** למדנו שלישת כל חלה וחלה בפני עצמה כדי שיהיו בכל אחת מהם שני עשרונים ולפי שזאת המדידה תהיה בעשרון שבמקדש הנה הכלי מקדש הסלת ויפסל אם יצא חוץ לעזרה ולזה יתחייב מזה הצד גם כן שתהיה לישתה ואפייתה בעזרה. ולפי שזה הלחם הוא לחם הפנים שהוא בתמונה שלא יתכן שיאפה בזולת שבירה ובזולת קלקול תמונתו אם לא היה נאפה בדפוס היו שם דפוסים של זהב היה נאפה בהם כמו שנזכר בפרשת תרומה והנ היה מחוייב לזאת הסבה שיהיה שם דפים ישימו בתוכה החלה כשהיא בצק ודפוס אחר מבפנים לשמור הבצק שלא תתקלקל תמונתו ובהן היה נאפה בתנור כל צרכו ואחרי כן יסירוה תחלה מאלו הדפוסי' שלא יקלקלוה חום הדפוסים וישרפוה לדקותה ולפי שהיא רכה עדיין בצאתה מן התנור הנה היו משימים אותה בדפוס צונן עד שתצטנן ותתחזק ולפי שהחום מועט יספיק לאפיית אלו החלות לדקותם הנה היה ראוי שיאפו בתנור קטן כדי שלא ישרפו ולא היה נאפה בשבת כי התורה לא חייבה שיהיה נעשה בשבת כי אם עריכת המערכת שנאמר ביום השבת יעריכנו לפני ה' תמיד. וכבר ביארנו בפרשה ויקחו לי תרומה זאת העריכה איך תהיה:
@884 **ושמת אותם שתים מערכות שש המערכת.** ר"ל ששה חלות תהיה המערכה מאלו המערכות באופן שיהיו שתים עשרה חלות בשתיהן:
@884 **על השלחן הטהור לפני ה'.** למדנו שאין הבדל בין החלה והשלחן אבל היא על שטח השלחן ואמנם בין החלות תהיינה המנקיות כמו שביארנו בפרש' ויקחו לי תרומה ולמדנו ממה שאמר לפני ה' שפני עורך אלו המערכות יחוייב שיהיו לפני ה' שהוא לצד המערבי ששם קדש הקדשים:
@885 **ונתת על המערכת לבונה זכה.** ר"ל אצל כל מערכת של אלו המערכות ישים לבונה זכה בכף אחת והם הכפות הנזכרות בפרשת תרומה:
@885 **והיתה ללחם לאזכרה וגומ'.** רוצה לומר שהלבונה תהיה ללחם לאזכרה כשיקטירנה להש' על מזבח העולה וזאת ההקטרה תתיר הלחם לכהנים כמו שיתיר הקומץ והלבונה שירי המנחה והיא תהיה נאכלת אחר זה לזכרי כהונה לבד לפנים מן הקלעים כמו שאמר אחר זה:
@886 **ביום השבת ביום השבת יערכנו לפני יי' תמיד מאת בני ישראל ברית עולם.** כבר נתבאר הסבה בעריכתה ביום השבת בפרשת תרומה ולפי שיחוייב שיהיה זה הלחם על השלחן תמיד חוייב שיהיו שם כהני' כבים אלו מושכין הלחם מעל השלחן ואלו מניחים הלחם שם בעת שהאחרים מושכים באופן שלא ימנע השלחן מזה הלחם כלל והנה יסירו כפות הלבונה משם ויקטירם בשבת להתיר הלחם לכהנים וישימו שם לבונה אחרת אצל המערכת כמשפט הראשון וזהו תמיד ויחוייב שישים אצל כל מערכת לבונה ביום השבת שסדר המערכת כי כבר ביאר כי מעניין המערכה שתחוייב להעשות בשבת יהיה נתינת הלבונה אצל המערכת ולזה זכר כל זה קודם שצוה שתעשה המערכת בשבת לפי שכבר אמר והיתה ללחם לאזכרה למדנו שבעת שהלבונה ראוי לאזכרה יחוייב שיהיה הלחם על עניינו רוצה לומר כל חלה שלמה לזה אם נפרסה חלה מן החלות בעוד שהלחם על השלחן לפי הראוי הנה הלחם פסול ואינו מקטיר עליו הלבונה שנאמר ללחם והוא לח המערכה שנערך על השלחן ומזה המקום יתבאר שאם אחר שהוסר הלחם מעל השלחן נפרסה חלה מהחלות או אחר שהגיע העת להסירו כי אז אינו לחם המערכה לפיכך הנה אף על פי שהוא פסול הנה יקטיר עליו הלבונה כי כבר היתה ללחם מה שהתמידה להיות אצלו לפי הראוי והיתה לאהרן ולבניו רוצה לומר אחר העשות מה שזכר והוא שיקטירו הלבונה להתיר הלחם לכהנים והגיד שאהרן קודם לבניו ולזה יהיה כהן גדול נוטל חלק בראש. ואכלוהו במקום קדוש. הוא לפנים מן הקלעים כמשפט קדשי הקדשים לפי מה שנתבאר בפרשת צו ואמרו ואכלוהו שם ללחם שזכר:
@888 **ויצא בן אשה ישראלית.** לא נתבאר לנו מן התורה על מה היו נצים והוא מבואר כי כבר יקרה זה לסבות רבות ואמנם רבותיי' אמרו כי הם היו נצים לפי ששבטו של דן לא היו מניחים אותו לעמוד ביניהם לפי שנ' איש על דגלו באותות לבית אבותם:
@889 **ויקוב בן אשה הישראלית את יי'.** רוצה לומר שכבר פירש השם המפורש וקלל אותו באופן הנהוג לקלל והוא בשם מהשמות המיוחדים לשם יתעלה כאלו תאמר שקלל שם בשם כמו שאמר יכה יוסי את יוסי והנה הביאוהו השומעים אל משה לבאר להם משפטו על פי השם והניחוהו במשמר עד שיבאר להם זה:
@892 **הוצא את המקלל מחוץ למחנה וסמכו כל השומעים את ידיהם על ראשו ורגמו אותו כל העדה.** למדנו שממתה מחוץ למחנה ולזה יחוייב שתהיה חוץ לב"ד ורחוק מהם עם שכזה תועלת שאם ימצא לו בין זה הזמן מי שידע לו זכות יחזירוהו והנה זאת הסמיכה היתה כאלו אמרו שהם נקיים מהחטא הזה בהמיתם אותו לפי שהוא היתה סבת מיתתו ולזה אומרי' לו בסמכם ידיהם על ראשו דמך בראך שאתה גרמת לך והנה העדים הם אשר תהיה ידם בו בראשונה להמיתו כמו שזכרנו במה שקדם ואמנם ורגמו אותו כל העדה שאם לא מת על ידי העדים כל העדה רוגמים אותו באבנים:
@893 **ואל בני ישראל תדבר לאמר איש כי יקלל אלהיו וגומר.** למדנו מזה שהמקלל הוא בכרת וכבר התבאר זה בפרשת בהעלותך ולזה אם לא היו שם עדים והתראה יתחייב כרת ואם היו שם עדים והתראה וקללו בשם מהשמות המיוחדים לשם יתעלה כמו אל אלהים שדי צבאות ומה שידמה להן הנה יהיה נסקל כמו שהתבאר פסוק הבא אחר זה והוצרכה התורה לכפול המאמר בה שלא נחשוב שיהיה מה שגזר על המקלל ההוא הוראת שעה ולא ינהג דין זה בכל מקלל:
@895 **ואיש כי יכה כל נפש אדם מות יומת.** כבר נתבאר בפרשת מפשטים שה הדין הוא בהורג אחד מאנשי התורה ושם נתבאר שזאת המיתה היא בסייף:
@896 **ומכה נפש בהמה ישלמנה וגו'.** רוצה לומר שישלם לו בהמה השוה לה או שוויה כי הכסף דינו כדין שוה כסף בכמו אלו הדברים כמו שזכרנו בפרשת משפטים ולהוסיף ביאור שהחובל בחברו יתחייב ממון לא שיעשה מום בו כאשר עשה בחברו כמו שאפשר יובן מלשון התורה זכרה התורה דין נתינת האדם מום בעמיתו אחר זכרה דין מכה בהמה שיתחייב ממון והנה לזאת הסבה גם כן שבה התורה להזכיר אחר כך שמכה בהמה הוא חייב בתשלומין להורות שמה שזכרה התורה בדין נותן מום בעמיתו הוא תשלומי ממון ואחר זה שב להזכיר שמכה אדם הוא חייב מיתה. וכבר ביארנו זה באופן שלם בפרשת משפטים ושם ביארנו האופן אשר ישוער בו מה שיתחייב החובל בחבירו לשלם לו מהממון:
@900 **משפט אחד יהיה לכם כגר כאזרח יהיה.** למדנו שהדין בזה שוה בגר צדק ובאיש מישראל וכבר נכפל זה במקומות רבים בתורה וראוי היה להיות כן כי התורה נימוס אחד יכוין בו לתכלית אחד במספר ומה שזה דרכו הוא בלתי מתחלק לזה יחוייב לגר שיקבל עליו כל מצות התורה בשלמות:
@901 **וידבר משה אל בני ישראל ויוציאו את המקלל אל מחוץ למחנה.** למדנו מזה שאין הדיינים יוצאים אחר מי שנתחייב מיתה בצאתו למות כי משה היה הדיין בזה והוא צוה לישראל שיוציאוהו חוץ למחנה וירגמו אותו אבן אך הוא לא יצא עמם לפי מה שיראה מזה. ובכאן נשלם זה הביאור במה שכללה אותו זאת הפרשה:
@919 **וידבר יי' אל משה בהר סיני לאמר.** אחשוב כי מפני שהפסיק המאמר בפרשת מקלל שלא היה המאמר בה בהר סיני זכר בה המקום שזה הדבור היה בהר סיני לא אחר דבור פרשת מקלל וזה לאות שכל שאר הדברים הקודמים היו בהר סיני ולזה עמד שם משה רבעים יום וארבעים לילה להגיע לו שם התורה על שלמותה:
@920 **כי תבאו אל הארץ אשר אני נותן לכם וגו'.** מגיד שאין המצוה הזאת נוהגת אלא בארץ ישראל אחר שיבאו בה כלם או רובם וזאת היא השביתה היא שתשבות הארץ מהמלאכה בשביעית בעבודת הארץ והאילנות כמו שיתבאר אחר זה:
@921 **שש שנים תזרע שדך ושש שנים תזמור כרמך.** רוצה לומר תוכל לזרוע שדך ולזמור כרמך ולאסוף תבואתה ולמדנו מזה שכיון שנעשית התבואה באלו השנים נוכל לאסוף ולאכול אותה אפילו בשביעית ואמנם אם לא נעשית התבואה עד בא השנה השביעית הנה יתבאר מזה שלא נוכל לאסוף אותה שנאמר ואספת את תבואתה והיא התבואה ההוא באלו השש שנים:
@922 **ובשנה השביעית שבת שבתון יהיה לארץ שבת להשם.** ר"ל שזאת השביתה תהיה לכבוד השם יתע' כמו הענין בשביתה במועדים הנזכרים במה שקדם כי היא מישרת אל השגתו יתע' כמו שנבאר:
@922 **שדך לא תזרע וכרמך לא תזמור.** ידוע כי הזריעה יותר עצמית בעבודת הארץ משאר העבודות שהם לצרך הזריעה כמו החרישה ולמדנו מזה לפי מה שהתבאר בשרשים הכוללים שעל הזריעה הוא מוזהר לא על החרישה וכן הזמירה שהיא עבודת האילנות היא יותר מועילה לאנשי' בשנה ההיא מפירות הנטיעה כי פירות הנטיעה יאסרו שלש שנים כמו שהתבאר במה שקדם כמו הענין בהרכבה והברכה ולפי שהמכוון בתורה שתשבות הארץ בשנת השמיטה באופן שלא יהיה בעל הקרקע עובד אותה ואוכל תבואתה הנה הזמירה היא היותר ראויה בזה הדין מהנטיעה וההברכה וההרכבה וכל שכן שאר עבודות האילן שהם מועילות לאילן באופן תועלת הזמירה כמו חתיכת הענפים היבשים והחתיכת הנובלת מהאילנות ומה שידמה לזה ולזה לא ינהג זה הדין אלא בזמירה כי אי שם עבודה לאילן מועילה באופן תועלת הזמירה לגפן וזה מבואר בחפוש:
@923 **את ספיח קצירך לא תקצר.** הם הספיחי' העולי' מאליהם בזולת זריעה וזה מבואר מצד הוראת הגדר וראוי שתדע כי דין מה שנזרע בשנה הששית דין הספיחים כי הם גם כן באים ממה שנזרע בשנה הששית באופן מה ואמנם דברה התורה בהווה כי אין בכאן דבר יחייב שיהיה זה הדין יותר ראוי בספיחים וזה מבואר בנפשו וראוי שתדע כי התורה לא צותה שנמנע מלקצור הטפיחים ומבצירת הענבים ההווים בכרם הבלתי נזמר וזה שכבר אמרה והיתה שבת הארץ לכם לאכלה ואם לא נקצור התבואה ולא נבצור הענבים הנה לא יתכן שיהיה לנו לאכלה ולזה יחוייב שתהיה הכונה בזה שלא נקצור אותם כדרך הקוצרים שקוצרים כלל התבואה ולא נבצור כדרך הבוצרים שבוצרים כלל הענבים אבל נקצור ונבצור מהם מעט ויהיה הפקר מה שיהיה בשדות ובכרמי' כמו שהתבאר בפרשת ואלה המשפטים ולזה אמרה התורה בה המקום כאשר ביארה איך תהיה לנו לאכלה ולבהמך ולחיה אשר בארצך תהיה כל תבואתה לאכול להעיר שאין הבעלים זוכין באכילה אלא בעת שנשאר ממנה לחוץ שתוכל לקחת ממנו החיה וכבר יתבאר בפרשת משפטים שכונת התורה בזה כדי שיאכלו ממנה העניים שנאמ' ואכלו אביוני עמך ויתרם תאכל חית השדה וזה גם כן מרה שאפילו העניים לא יהיו רשאין לקצור כל התבואה אבל ראוי שיניחו ממנה לזולתן באופן שתתכן לחית השדה לקחת ממנו:
@923 **ואת ענבי נזירך לא תבצור.** הנה קראה התורה נזירים הגפנים בלתי נזמרים והכונה בזה כמו שקדם שלא יבצור כדרך הבוצרים אבל יבצור מעט מעט באופן שיהיו שאר האנשים מושלים בבצירה מהן כשירצו:
@923 **שנת שבתון יהיה לארץ.** רוצה לומר שלא יעשו בארץ אלו המלאכות הנזכרו' והן הזריעה והקצירה והזמירה והבצירה:
@924 **והיתה שבת הארץ לכם לאכלה.** מגיד שהוא מותר לכל האנשים ואף על פי שאינם עניים והם יקחו מה שיקחו מתבואתה לאכלה לא לעשות בה סחורה כי כונת התורה תראה שהיא תשתדל שישאר מהתבואה ההיא בחוץ באופן שיהיה בה תועלת משותף לכל האנשים ולזה תא התירה התורה לאכול ממנה בבית כי אם בעת שנשאר ממנה לחוץ לחיה כי זהו סבה אל שלא ישתדלו האנשים לקחת ממנה הרבה יחד כי לא יועילו להם אחר שלא ימצא מהתבואות בחוץ בשדות ואלו היה מותר לסחור בפירות שביעית הנה יקחו מהם האנשים הרבה יחד וימהרו לאכלם אם בעיר ההיא או בזולתה ולזה ידמה שלא התירה התורה פירות שביעית לסחורה כי אם לאכילה והוא מבואר שהאכילה תכלול כל מיני הנאה מורגלת תלקח מהפירות בעצמם כמו השתיה והסיכה והצביעה ומה שידלה לזה ממה שתהיה בו ההנאה בפרי בעצמו אלא אם מפני שהתורה זכרה האכילה היא ההנאה היותר חזקה שיתכן שיהיה בדבר הנאכל הנה ראוי שיתבאר מזה שאין ראוי שנשתמש בפירות שביעית בהנאה תהיה הפסד בחק הפרות ההם לפי המורגל ומזה המקום יתבאר שאין ראוי לקצור פרות שביעית כשהן בוסר כי אין זה הפסד ואין זה האכילה הנהוגה בו אלא אם זה היה מעט מעט באופן הנהוג לקחת מהפרות כשהם בוסר ועוד שהתורה אמרה מן השדה תאכלו את תבואתה תהיה כל תבואתה לאכול והתבואה הוא הפירות הנגמרים:
@924 **לך ולעבדך ולאמתך ולשכירך וגו'.** הנה מפני שהתורה התנית שיהיו גרים עמו והם אשר מזונותיהן עליו למדנו שלא יותר לו למכור פרות שביעית כמו שביארנו במה שקדם אלא אם היתה המכירה לאכלה רוצה לומר לקנות ממנה אכל יאכלוהו הוא ואנשי ביתו:
@925 **ולבהמתך ולחיה אשר בארצך תהיה כל תבואתה לאכול.** למדנו מזה שמותר להאכיל פרות שביעית לבהמה אלא שראוי שלא יתנם האדם לבהמתו אם היו ראוים לאדם כי זה הפסד בחק הפרות ההן ואמנם יש לו להניח בהמתו לאכול משם כשהם מחוברין כי הם אינם בזה למטה מהחיה שחוייבנו להניח מכל הפרות מה שיתכן לו לאכל ממנו והוא מבואר שמכירת פירו' שביעית לא יוציא מהם קדושת שביעית כי התורה גזרה בפרות ההם שיהיו לאכלה להם ולאביונים בעת שתוכל לאכול חית השדה מהם לא אחר זה וכן מה שלקח בפירות שביעית הנה עליו קדושת שביעית גם כן עד שלא יוכל להשתמש בו כי אם לאכלה באופן שישתמש מפרות שביעית שנאמר והיתה שבת הארץ לכם לאכלה כמו שביארנו:
@926 **וספרתם לכם שבע שבתת שנים.** רוצה לומר ז' שמטות וזאת הספירה תהיה בשנה השביעית שימנו אז שבת אחת וכן עד שיהיו שבע ורצתה התורה שימנו עם זה השנים שנה אחר שנה מאלו שבע שמטות עד שיהיה מספר השנים מ"ט שנה והנה ענין זה המכפר שוה לענין מספר הימים והשבועו' ממחרת הפסח עד חג השבועות אלא שבכאן עניין נוסף שהשביעית בשנים היא שנת שבתון ואין העניין כן בשבועות הנמנות אחר הפסח:
@927 **והעברת שופר תרועה בחדש השביעי בעשור לחדש.** רוצה לומר אחר תום מ"ט שנה וזה יהיה בשנת היובל לבד שאם היה זה נוהג בכל שמטה ושמטה היתה התורה זוכרת בזאת הפרשה הקודמת שזכר בה דין שנת השמטה ואם היה נוהג זה בכל שנה ושנה היתה התורה זוכרת זה בפרשת אמור אל הכהנים שזכר בה דין המועדים האלו בכללם והנה נתבאר עניין זאת התרועה בפרשת אמור אל הכהנים והתועלת המגיע ממנה ובכלל הנה ביום הכפורים שהוא העשירי משנת החמשים תעשה זאת התרועה כדי שנתן לא לבנו מה שהעיר עליו קדוש שנת החמשים וקדוש העשירי מהימים כי זה יורה על ענין נפלא בחכמת האלהות כמו שהתבאר מדברינו במה שקדם וכבר התבאר שזה המנין בענין השמטות והיובל אינו נוהג אלא בארץ שכבר אמר בראש זה הענין כי תבואו אל הארץ. וראוי שתדע שזה הענין לא ינהג כי אם אחר שירשו הארץ וחלקו אותה שנאמר שש שנים תזרע שדך ושש שנים תזמור כרמך עד שחלק הארץ אין אני קורא בו שדך וכרמך. וראוי שלא יעלם ממנו שזאת הספירה היא בהכרח מיוחסת לבית דין הגדול כמו העניין מבקדוש החדש וגם כן הנה מפני שהשנה נכנסת בהכנסת החדש והיה קדוש החדש מיוחד לבית דין הגדול כמו שביארנו בפרשת בא אל פרעה הנה קדוש השנה ההיא מיוחס בהכרח להם וזה בלתי צריך אל ביאור:
@928 **וקראתם דרור בארץ לכל יושביה.** הנה ביאר שזה החירות שיסור אז מכל אחד מיושבי הארץ הממשלה שתהיה לזולתו עליו ועל אחזתו. רוצה לומר שאם מכר עצמו או שדהו יצא לחפשי בבא היובל וישוב אליו שדהו כמו שהתבאר אחר זה והנה קרא שנה הזאת יובל שהוא שב אל הקרן אשר בו יתקעו שנאמר במשוך היובל במשוך קרן היובל להעיר על התרועה הנעשית בה שישימו לב עליה על מה שהיא בזאת השנה ובזה היום שהיא בו ולפי שאמר לכל יושביה והיה מבואר שהמתוארים שהם יושביה הם כל השבטי' איש על מקומו אשר הגיע לו בגורל בעת חלוקת הארץ למדנו שאם אין כל יושביה עליה אין היובל נוהג וכן אם היו שם והיו מעורבבים לפי שאין השבט יושב בנחלתו ואין היושבין בארץ יושבים על דרך האמת לפי מה שהתבאר מהשרשים הכוללים וגו':
@929 **יובל היא שנת החמשים שנה תהיה לכם.** למדנו מזה שעבודות הארץ האסורות בשביעית אסורות ביובל ולא הזכיר בכאן איסור הזמירה כי הוא דומה לזריעה ועוד כי כבר רמז אליו במה שאמר ולא תבצרו את גזיריה כי זה מורה שלא יהיו הגפנים נזמרים בשנה היא ולזה יקראו גזירים כי יגזרו מהם האנשים אז ולא יעבדו אותם:
@930 **כי יובלו היא קדש תהיה לכם.** ראוי שתדע כי אין רצון התורה בזה שיהי קדש כי אם לענין שיאכלו מן השדה את תבואתה ולא יאספוה לביתם וזה אמנם היה כדי שיהיו כל האנשים שוים באוכל השנה ההיא כמו הענין בשנת השמיטה וזהו עניין קדושת פירות שנת היובל כי בבא הזמן שלא ימצא מהם בשדה יאסרו הנמצא בבית ושלא יותר להם לאספם אל ביתם כדרך הקוצרים והבוצרי':
@931 **בשנת היובל הזאת תשובו איש אל אחוזתו.** ר"ל אם מכרו אות':
@932 **וכי תמכרו ממכר לעמיתך.** לפי שמגדר הונאה יתבאר שהיא אינה נוהגת כי אם בדברים שיתכן שיהיה ידוע ערכם ומוגבל הנה הוא מבואר שאין אונאה בקרקעו' כי תבואותיהם בלתי מוגבלי' וידועים בעצמות באופן שנוכל לשפוט שתהיה שם אונאה כי הקרקע כחיי על פירות אין להם תכלית ועל פירות שונים יתחלף ענין הערך בהם מאד וכן הוא מבואר שאין אונאה בעבדי' כי לא יגרע התועל' שאפשר שיגיע מעבודתו ועצתו ויתבאר שאין אונאה בשטרות כי אין לשטר מצד עצמותו שום ערך אלא מצד שבסכתו יגבה המלוה את חובו או יהיה לו ראיה על מה שכלל אותו השטר ההוא ובכלל הנה כמו שדברי העדי' אין להם ערך כי אם לראיה לבד כן הענין בשטרות ולזה הסכימו רז"ל שהאונאה הנזכרת בזה הפסוק הוא המטלטלים וביארו זה ממה שאמר או קנה מיד עמיתך כי זה הלשון יתכן שיפול במטלטלין לא בקרקעות כי אינם נעתקים מיד המוכר לקונה והנה יתבאר שאין אונאה להקדש ממה שאמר אל תונו איש את אחיו והוא מבואר כי במטלטלין יש אונאה כי ענינה מוגבל וידוע אלא שכבר יתבאר כי למטה משתות אין שם אונאה לפי שדרך האנשים לתת בדבר שירצו אותו מאד לקנותו יותר מכדי שוויו עד שתות ולא יקפיד בזה וזה מבואר מן החוש וכן אם יש לנו הוראה שנתרצה בזה המקח עם ידיעתו שקנ' אותו יותר מכדי שוויו הרבה אין בו אונאה ואפילו לקח שוה דינר באלף דינר כי כמו שהאדם שליט לתת מתנה כן הוא שליט לתת במסחר יותר משוויו לרצותו בו ואולם עניין האונאה הזאת תהיה במה שחשב שיהיה ערך הדבר יותר ממה שהוא או פחות ומפני זה נתרצה לתת יותר בו או לתתו לפחות וראוי שתדע שזאת האונאה נתנה לחשבון ובזה האופן תסור כי הוא מונה אותו כל זמן שלא החזיר לו שיעור האונאה ולפי שלפי הנהוג אין ההוקרה והוזלה במסחרים בין האנשים בכמו אלו הדברים יותר משתות הנה אם היתה באונאה יותר משתת לא יחוייב שישאר המקח קיים אבל יהיה כאלו אין שם מקח ואמנם אם היה שתות יתקיים המקח ויחזיר האונאה ופחות משתות לא יחוייב להחזיר אונאה כמו שביארנו והנה עכ"פ נכלל בזה הפסוק שלא להונות בעניין הקרקעות כי התורה מדברת בזה המקום בקרקעות והנה האונאה שהזהירה עליו לפי מה שאחשוב הוא שלא יונה אותו במנין השנים אשר עד היובל וימכור לו מפני זה שדהו יותר ממה שראוי או יקנה אותו פחו' ממה שראוי וזה כי מפני שקנין הקרקעו' חוזר ביובל הנה ערכו יותר מעט בכל מה שקרבה שנת היובל ולזה אם הונהו והביאוהו לחשוב כי אין עד היובל כי אם מעט זמן ויש שם זמן יותר ארוך או הפך זה הנה תהיה בזה אונאה מזה הצד כי הוא אינו מוכר לו כי אם מספר שני תבואות אף על פי שהוא מוכר לו שדהו במוחלט והנה הטעהו במספר בענין הזה ולזה ביאר אחר זה שזה האופן מהאונאה יקרה בקרקעות מצד היובל ועליו הזהיר ובכלל הנה בקרקעות אפשר שתהיה אונאה מצד המספר או מצד המדה והאונאה אשר מצד המד' כבר הזהיר עליה באמרו לא תעשו עול במשפט במדה כמו שבארנו שם והאונאה אשר תהיה מצד המספר הזהיר עליה בזה המקום:
@933 **במספר שנים אחר היובל תקנה מאת עמיתך.** ר"ל כי מפני שהקרקע חוזר ביובל הנה אין נקנה לו אלא במספר שני' ולזה ראוי שיהיה הערך לפי השני' אשר עד היובל אם הרבה הרבה אם מעט מעט כמו שזכר בפסוק הבא אחר זה ולמדנו ממה שאמר אחר היובל שאין הקרקע נקנה ביובל וראוי הוא להיות כן כי הנמכר חוזר כ"ש שהוא ראוי שלא ימכר ביובל ולפי שאמר במספר שנים למדנו שאין הקרקע נקנה לצמיתות בפחות משתי שנים ואיננו נמכר גם כן בזה האופן לפחות משתי שנים שנאמר מספר שני תבואות ימכור לך וראוי היה להיו' כן כי התור העתיקה הממכר למספר שנים בלתי בעל תכלית אל מספר מוגבל אינו יותר ממ"ט שנה וראוי שלא יהיה נעתק אל מה שאינו מספר והוא האחד והמעט שיפול בו שם המספר הוא שנים ולזה לא יהיה נמכר בזה האופן בפחות משתי שנים וראוי שיהיו אלו שתי השנים שנים ראויים לתבואות שנאמר שני תבואות ולזה אם היתה אחת מהשנים בלי ראויה לתבואה מצד עצמותה כמו שהיתה שנת שביעית או שנת שדפון אינה עולה לו מן המנין ומזה המקו' נלמד שאף על פי שיש רשות למוכר לגאל שדהו כמו שנתבאר אחר זה הנה אינו גואל אלא אחר שנשארה ביד הקונה שתי שנים ראויות לתבואות:
@934 **לפי רוב השנים תרבה מקנתו.** הנה רמז בכאן אל איכות האונאה שהזהיר ממנה בפסוק הקודם:
@935 **ולא תונו איש את עמיתו וגו'.** הנה זאת האונאה היא אפילו בזולת מכר וקנין כמו אונאת דברי' ולזה לא זכר קודם לא מכר ולא קנין כמו שעשה זה באונאת הקודם:
@936 **ועשיתם את חקותי ואת משפטי תשמרו ועשיתם אותם.** אמר עשייה לחוקים ולא זכר בהם שמירה שהיא זכירתם בלב כי היה אפשר שיחשוב חושב שלא תצטרך בהם עשייה אבל יספיק שנזכיר עניינם בלב כדי שנעמוד על ההערה אשר בחקי' ההם כי יראה שעשייתם היא לזה התכלי' כמו שהתבאר בדברינו ולזה הוצרכה התורה לצוות בעשייתם ואמנם במשפטים והם המצוות המכוונים בעצמותם ויחייבם השכל לפי שכבר יחשב שלא יצטרך לנו למודם אבל יספיק שנעשה אותם הנה ולזה צותה התורה לזכור אותם בלב כי יהיה סבת העשייה כמו שאמרו ז"ל שהתלמוד מביא לידי מעשה:
@936 **וישבתם על הארץ לבטח.** ר"ל שלא תגלו מן הארץ אבל תשבו עליה לבטח ולא תפחדו משום דבר:
@937 **ונתנה הארץ פריה ואכלתם לשובע.** כבר בארנו בספר מלחמות ה' כי גם באלו הענינים יהיו מושגחים הדבקים בשם יתעלה וכי תאמרו מה נאכל בשנה שביעית ידוע שזה המאמר יתכן שיפול בכל שמטה ושמטה כי יצטרך שתספיק להם התבואה מהשנה השישית לשתי שנים ויותר ממה שתפול זאת המבוכה היא השמיטה אשר יבא אחרי' היובל כי יצטרך שתספיק אז תבואה השנה הששית לשלש שנים ועליו אמר וצויתי את ברכתי לכם בשנה הששית ועשת את התבואה לשלש השנים ואפשר שנאמר שהוא היותר נכון שזה הפסוק נאמר על כל שנת השמטה והנה תעשה התבואה לשלש השנים שכבר יאכלו ממנה בשנה הששית מעת בא תבואתה ועוד כי בה יזרעו מהבואה ההיא בשנה השמינית וזהו מה שאמר וזרעתם את השנ' השמינית ואכלתם מן התבואה ישן. ר"ל שכבר תספיק עוד התבואה ההיא לזרוע ממנה בשנה השמינית ולאכול ממנה ישן עד בא תבואת' ואמנם מה שאמר אחר זה עד השנה התשיעית עד בא תבואתה תאכלו ישן הוא שב לשנת השמטה שבא אחריה היובל:
@941 **והארץ לא תמכר לצמיתות.** זו היא מצות לא תעשה וכבר בארה התורה שלא יועילון לו אם מכרה לצמיתת שהרי היא חוזרת לבעליה ליובל:
@941 **כי לי האץ כי גרים ותושבים אתם עמדי.** ר"ל הנה שלי הארץ ולא השלטתי אתכם בה למכרה לצמיתת אף על פי שאתם מחזיקים בה כי אתם כמו גרים בארץ ההיא או כמו תושב שהוא ביד אדוניו שאין לו שולטנות במה שהוא מחזיק בו כטעם תושב כהן ושכיר לא יאכל בו:
@942 **ובכל ארץ אחוזתכם גאולה תתנו לארץ.** ר"ל שלא די שהארץ לא תמכר לצמיתות ותצא ביובל אבל יחוייב עוד שתתנו גאולה לארץ שאם מכרה אדם מכם ורצה לגאול אותה יהיה שליט בזה ולא יוכל הקונה למחות בידו וכבר יתבאר זאת הגאולה איך תהיה בפרשה הבאה:
@943 **כי ימוך אחיך ומכר מאחוזתו.** למדה תורה דרך ארץ שאין ראוי למכור אחוזתו אם לא יביאהו לזה הכרח וזה כי קנין קרקעותיו הוא יותר קיים משאר הקניינים אשר יהיו מחירו ואמר מאחוזתו להעיר כי כשיוכרח על זה לא ימכור ממנו אלא קצתו ויניח קצתו להסתפק בו:
@943 **ובא גואלו הקרוב אליו וגאל את ממכר אחיו.** למדנו שהיותר קרוב מגואליו קודם לזה הענין:
@944 **ואיש כי לא יהיה לו גואל והשיגה ידו ומצא כדי גאולתו.** ר"ל אם לא מצא אחד מקרוביו שיגאל את ממכרו והשיגה ידו משלו לגאול הנה הרשות בידו ולמדנו מזה שאין ראוי שימכר במקום אחד לגאול זה הקרקע ולא שילוה סך גאולתו שנאמר והשיגה ידו ולפי שאמר ומצא כדי גאולתו. למדנו שאינו גואל לחצאין אבל גואל את כלו או תשאר בידו הקונה עד היובל:
@945 **וחשב את שני ממכרו והשיב את העודף לאיש אשר מכר לו ושב לאחוזתו.** למדנו שאין ראוי לגאל עד שיאכל הקונה קצת התבואות שנאמר והשיב את העודף וממה שקדם נתבאר שהוא ראוי שיאכל הקונה שתי שנים קודם שישלוט המוכר לגאל ולמדנו ממה שאמר שני ממכרו שאם היו לו עשר שנים ראוים לתבואות עד היובל ואכל מהם הלוקח ב' מהם הנה יחשוב לכל שנה מהשנים הנותרות עשירית המקח. ואף על פי שאכל הלוקח שלש תבואות בשני שנים או שני תבואות בשלש שנים אין מונין לו למספר תבואות אבל מונין לו למספר שנים ולמדנו ממה שאמר לאיש אשר מכר לו שאם מכרה לאחר ומכרה האיש ההוא לאיש אחר בסך יותר גדול אינו מחשב אלא לפי הסך שמכר ראשון וזה מבואר גם כן מצד אחר כי מפני שלא השליטהו השם יתעלה למנוע המוכר מלגאול הנה אין לו רשות למכרו לאחר בסך יותר גדול להכביד עניין גאולת המוכר ואולם אם מכרה בפחות כיון שנסתלק ממנה הקונה הראשון הנה יגאל האדון מיד הקונה השני לפי מה שקנה כי אין לו זכות בזה הקניין יותר מזה השיעור אף על פי שקנהו מיד הבעלים ולדנו ממה שאמר ושב לאחוזתו שאם השביח הקונה הקרקע חייב המוכר להחזיר לו השבח כי אין השבח אחוזתו אבל המציאו הלוקח:
@946 **ואם לא מצאה ידו די השיב לו והיה ממכרו ביד הקונה אותו עד שנת היובל.** למדנו מזה גם כן שאין בידו ללוות ולגאל ולמכור ולגאל ולמדנו גם כן שאין השבח חוזר ביובל שנאמר והיה ממכרו ביד הקונה אותו עד שנת היובל ויצא ביובל ושב לאחוזתו ממכרו יוצא ביובל ולא שבה ולזה יחוייב שיחזיר לו השבח:
@946 **ויצא ביובל ושב לאחוזתו.** למדנו שהמוכר אילנו' אינם חוזרי' ביובלים כי אינם אחוזה ואמנ' הקרקע חוזר כי הוא אחוזה:
@947 **ואיש כי ימכור בית מושב עיר חומה.** לפי שאילו המצות תלויות בארץ כמו שהתבאר בראש העניין והיה מבואר מן השרשים הכוללים כי התארים הנזכרים בתורה אינם לפי המציאות אבל לפי מה שראוי שיתואר בו בעל התואר ההוא הנה למדנו כי מה שיתואר כשהוא עיר חומה בעת כבוש הארץ אף על פי שאחר זה לא יהיה מוקף חומה דינו דין ערי חומה והוא מבואר שעיר חומה הוא מה שהוא מוקף חומה ואחר כך נתיישב העיר בתוך החומה לא מה שהיה עיר תחלה ואחר כך הוקף חומה והוא מבואר שאם אין מה שמוקף חומה במדרגת עיר לא ינהג בה זה הדין וראוי שתדע כי הבתים יכללם החצר כי ימצאו בתים רבים בחצר אחד והעיר תכלול חצרות ובתיהם ואם לא היה בעיר חצרות רבים והם על המעט שלשה יכלול כל אחד מהם בתים לא ינהג בה דין ערי חומה וכן אם לא היה הבית תוך עיר החומה שנאמר וקם הבית אשר בעיר וכן אם לא היה בבניין ההוא דין הבית כמו שיהיה שדה או שלא היה כשיעור בית לא ינהג בו זה הדין אבל דינו דין שאר הקרקעות שחוזרי' ביובל:
@947 **והיתה גאולתו עד תום שנת ממכרו.** ידוע ממה שקדם בפרשת בא אל פרעה כי השנה היא פעם שתים עשרה חדש ופעם י"ג חדש ולזה היתה גאולתו מיום החדש ההוא עד כמו יום החדש ההוא מהשנה האחרת והמשל שאם נמכר באחד באדר תהיה גאולתו עד אחד באדר מהשנה האחרת שנא' עד מלאת לו שנה תמימה ולפי שלא התנה בכאן שתשיג ידו לגאל למדנו שיש לו למכור קרקע אחר לגאל וראוי היה להיות כן כי מפני שהבית הזה נחלט ואין העניין כן בשאר הקרקעות הנה יועיל לו אם ימכור במקום אחר לגאל אותו ואמנם אין בידו לגאל אותו חציין שנאמר גאולתו לא גולת קצתו ויתבאר שאין בידו ללות מעות לגאל אותו כי התורה לא הרשית קרוביו לגאל אותו כ"ש שאין ראוי שיגאלוהו מי שינם קרוביו ואלו היה אפשר לו ללות מעות לגאל אותו היה נגאל על יד מי שאינם קרוביו במעות שילוה מהם:
@947 **ימים תהיה גאולתו.** ר"ל שנה אחת כי הוא כמו יום ארוך כמו שהתבאר בחכמה הטבעית וראוי שתדע שלא יגרע מערכו דבר בעבור מה ישב בו הקונה אותו כי לא אמרה התורה שיחשב בזה דבר ועוד כי זה המכר הוא לדורות לאין תכלית ולזה לא יכול לגרוע ממנו דבר בעבור מה שישב בו מהשנה וזה מבואר בנפשו:
@948 **ואם לא יגאל עד מלאת לו שנה תמימה.** ר"ל מיום ליום:
@948 **וקם הבית אשר בעיר וגומ'.** למדנו מזה שאם לא נגאל תוך שנה שלמה באופן הנזכר הנה הוא מוחלט לקונה אותו. ר"ל שאינו יוצא ביובל ולפי שאמר לדורותיו למדנו שאם היה קונה הבית באופן שאין לו דורות כמו ההקדש הנה אינה מוחלט אמנם גאלו אחד מן ההקדש הנה הוא מוחלט במלאת לו שנה תמימה:
@949 **ובתי החצרים.** הם בתי העיירות אשר אינם מתוארות בשהם בתי ערי חומה והנה דינם כדין השדות לעניין הגאולה ולצאת ביובל כמו שזכר:
@950 **וערי הלויים בתי ערי אחוזתם גאולת עולם תהיה ללויים.** למדנו שהלויים גואלים באיזה עת שירצו אף על פי שלא היה שתי שנים ביד הקונה אותו:
@951 **ואשר יגאל מן הלויים.** למדנו מזה שמי שהוא מהלויים אף על פי שאינו לוי כמו שהיה בן בת לוי דינו בעניין הגאולה כדין הלויים והנה הרצון בזה גולת עולם תהיה ללויים ולאשר יגאל מן הלויים:
@951 **ויצא ממכר בית ועיר אחוזתו ביובל.** ר"ל שאם לא גאל ממכרו הנה הוא יוצא ביובל:
@951 **כי בתי ערי הלויים היא אחוזתם בתוך בני ישראל.** ר"ל שכבר יחוייב שיהיה ללויים חירות נוסף בזה העניין על שאר ישראל כי בתי עריהם היא בתוך בני ישראל כי אין להם נחלה בארץ כמו שנזכר בתורה אבל נתן להם כל אחד מהשבטים מחלקו ואם יקרה שימכרו בתיהם יתכן שיקנו אותם אנשי השבט שהיו אלו הערים מהם ובתוך נחלתם ויקרה מזה באורך הזמנים שתסוב נחלת הלויים לשאר השבטים ואולם בשאר שבטים לא יתכן שיקרה זה כי אנשי השבט יושבים בנחלתם ואם יקרה שימכור אחד מהם ביתו יקנהו אחד מאנשי השבט להיותם יושבים לבדם בארץ הוא:
@952 **ושדה מגרש עריהם לא ימכר כי אחוזת עולם הוא להם.** ראוי שתדע שאין הרצון בזה שלא ימכר כלל כי כבר בארה התורה כי גם בתיהם יש להם רשות למכרם אלא שיש לבתיהם גאולת עולם ואמנם הרצון בו שלא ישנו אותו לעשות שדה מגרש או הפך או מגרש עיר או הפך והה הושאל לזה העניין שם המכירה לפי שהמכירה ישתנה בה רשות בעל הקניין וישוב אל בעלי' אחרים ולזה הושאלה המכירה להשגות הקניין מן ההשתמשות לתכלית אחת אל השתמשות לתכלית אחרת ואמר אשר התמכר לעשות הרע. ר"ל שבאופן שהיה מיוחד לעשיי' הטוב בכמו האופן ההו' שב לעשות הרע כאלו יצא מרשות המנהיג הטוב אל רשות המנהיג הרע ומזה העניין השני נקרא בזה המקום מכירה העשיי' מהשדה מגרש או הפך ומה שידמה להם כי השתמשו בו לתכלית מקבלת אל התכלית אשר כוון בה ולזה אמר כי אחוזת עולם הוא ללויים ולזה אין ראוי לשנות אותו מענינו כי בזה האופן המשוער יאות להשתמש בו לעולם באופן שלם ואם ישתנה זה הסדר יפסד היישוב ההוא ויבלבל עניינו והמשל שאם עשה המגרש עיר או השדה מגרש לא יספיק להם ולבהמתם ולכל חייהם ואם עשו הפך זה ימעיטו יישוב המקום ההוא וכבר הקפידה התורה באלה מסעי שישתמשו הלויים באלו המקומות בתכלית המכוון להם ולא יעתיקום אל תכלית אחר אמר והיו הערים להם לשבת ומגרשיהם יהיו לבהמתם ולרכושם ולכל חייתם:
@953 **וכי ימוך אחיך ומטה ידו עמך והחזקת בו.** ר"ל שאם היה אצלך ראוי שתחזק בו להיטיב לו מהונך:
@953 **גר תושב וחי עמך.** ר"ל גר צדק או שהיה גר תושב את ראוי להחיותו עמך לא שתחיהו ותמית עצמך כי חייך קודמים ולזה גם כן זכרה התורה זה העניין בהדרגה וזכרה תחלה אחיך ואחר כך גר צדק ואם הוא גם כן אחיך אלא שאינו מזרע ישראל ואח"כ גר תושב:
@954 **אל תקח מאתו נשך ותרבית ויראת מאלהיך.** למדנו שזאת האזהרה אינה אלא במי שהוא אחיך כמו הישראל וגר צדק וכבר זכרה זה התורה במקום אחר אמר לנכרי תשיך ולאחיך לא תשיך וזה ראויה שלא הזהירה התורה מלקיחת נשך ותרבית אלא ממי שהוא אחיך וראוי שתדע כי בהלואת כסף יפול שם נשך כאלו תאמ' אם הלוה ארבע דנרין בחמש כי כמו שהנושך נשך דבר מחוץ כן העניין במי שמלוה כספו ברבי' כי אין מדרך הכסף לעשות פירות מעצמותו ובהלואת האוכל יפול שם מרבית אם ירבו בו שנ' את כספך לא תתן בנשך ובמרבית לא תתן אכלך משל נתינת האוכל מי שילוה ארבע סאין בחמש והוא מבואר שהעובר על אלו האזהרות יחוייב להשיב מה שלקח מנשך ותרבית כי כל עת שהוא מחזיק בו הוא לוקח מאתו נשך ותרבית:
@954 **ויראת מאלהיך וחי אחיך עמך.** אמר ויראת מאלהיך שלא תערים בזה שלא תתלה מעותיך בגוי כדי לקחת רבית מישראל ואמר וחי אחיך עמך שתחוייב להלוות לו כדי שיהיה עמך כמו שאמר אם כסף תלוה את עמי את העני עמך. ואולי לה אמר ויראת מאלהיך שאף על פי שלא תוכל לקחת תועלת בהלוואתך לעני אל תמנע מזה אבל השתדל שייה עמך. ואולם חייך קודמין ולזה אמר עמך:
@956 **אני יי' אלהיכם אשר הוצאתי אתכם מארץ מצרים לתת לכם את הארץ.** הטוב ומשלי תטיבו לעניים והנה הנחלתי לכם אלו הטובות שתתנהו בהם באלו התנאים שצויתי אתכם:
@956 **להיות לכם לאלהים.** רוצה לומר שאין ראוי שיכבד לכם מה שאגזור עליכם מההטבה לעניים אני הוא שהוצאתי אתכם מתכלית הדלו' לתת לכם הארץ הטובה:
@957 **וכי ימוך אחיך עמך ונמכר לך.** מגיד שאין ראוי לאדם למכור עצמו אם לא היה זה בסבת עוני וראוי גם כן שימכר לך כשיביא ההכרח לזה לא לנכרי ולזה הקדימה התורה המכרו לישראל קודם המכרו לנכרי:
@957 **לא תעבוד בו עבודת עבד.** ר"ל שלא יבזהו לקחת ממנו השירות שיקחו מהעבד הכנעני בחליצת מנעליו ומה שידמה להם מהעבודות הבזויות:
@958 **כשכיר כתושב יהיה עמך.** ר"ל שעניין עבודתו ממוצע בין עבודו' השכיר והתושב כי השכיר למעט זמן שכירתו לא יעבוד כי אם העבודה המיוחדת אשר שכרוהו לעשותה והתושב הוא הפך זה כי הוא מוכן לכל העבודות שירצה רבו והעבד העברי ממוצע בין שתי אלו העבדיות כי הוא לא ייוחד לעבודה מיוחדת כמו העניין בשכיר ולא לכל העבודות כמו הענין בתושב והוא מבואר שהמוכר עצמו יש לו מכור עצמו משש שנים לא נאמר שש שנים אלו בעבד עברי שמכרוהו ב"ד כמו שנתבאר בפרשת ואלה המשפטים ומה שאמר עד שנת היובל יעבוד עמך לא יחויי' שלא יוכל למכור עצמו בפחות מה הזמן אבל התחייב ממנו שלא יוכל למכור עצמו ליותר מזה הזמן:
@959 **ויצא מעמך הוא ובניו עמו.** למדנו שהקונה עבד עברי חייב במזונו' בניו והיה זה כן לפי שהוא חייב לזון את בניו כמו שבארנו בפרשת ואלה המשפטים וכל שכן שיחוייב במזונות אשתו כי כבר נתבאר בתורה התחייב האדם במזונות אשתו:
@959 **ושב אל משפחתו וגו'.** למדנו מזה שכל עבד שיוצא ביובל הוא שב אל משפחתו לחזקה שהיה בה ולזה אם היה העבד עברי כהן שמכרוהו ב"ד אינו נרצע שאם היה נרצע לא היה שב לחזקה שהיה בה כי הוא בעל מום ופסול לעבודה. ואמר ואל אחוזת אבותיו ישוב ללמד שאין ראוי לאדם למכור עצמו אם לא אחרי שלא נשאר לו מאחוזתו דבר למכור:
@960 **כי עבדי הם אשר הוצאתי אותם מארץ מצרים.** ר"ל כי מפני שהיו עבדים במצרים והוצאתי אותם משם הנה הם עדי ולזה לא ישלטו להמכ' לעבדים יותר מה הזמן וג"כ הנה קניתי אותם לעבדים במה שהראיתי להם מאותותי ונפלאותי בהוציאי אותם מארץ מצרים ואם ימכרו לעבדים עולמית הנה יסירו עול עבודתי מל צוארם:
@960 **לא ימכרו ממכרת עבד.** ר"ל שלא ימכרו עולמית כהמכר עבד כנעני ושלא ימכרו על אבן הלקח כמכור העבדים השבויים:
@961 **לא תרדה בו בפרך.** ר"ל שלא תכוין בעבודתו לענות גופו אבל תכוין בה לעשות מה שיצטרך לך ולזה אין ראוי לאדם שיצוה לעבדו העברי לעשות מלאכה והוא בלתי צריך כדי שלא ישב בטל ולזה אמר ויראת מאלהיך כי השם יתעלה הוא היודע כוונתך בזה:
@962 **ועבדך ואמתך אשר יהיו לך מאת הגוים אשר סביבותיכם.** ר"ל שהעבד והאמה יהיו לך ותמשו' בהם כחפצך הם מאת הגוים אשר סביבותיכם והם הכנעניים:
@962 **מהם תקנו עבד ואמה.** ר"ל שמהם תוכלו לקחת לקנות עבד ואמה קנין עולמים באופן קניין עבד שנקנה על אבן הלקח:
@963 **וגם מבני התושבים הגרים עמכם מהם תקנו.** שלא יחשוב שהותר זה באלו האומות שאינם גרים עמכם מצד שאינם מקיימים המצות שנצטוו בני נח ואמנם אשר הם גרים עמכם מהם לא יותר בהם זה להיותם מקיימי' המצות ההם ולזה הוצרך לבאר שכבר הותר זה גם בגרים עמכם וממשפחתם אשר עמכם הם אשר נולדו מהכנעניות ומזולתם מן האומות כי הנולדים הם ממשפחת האם אשר הולידו בארצכם הם הבנים שהולידו הכנענים מנשי שאר האמות כי האבות הם המולידים:
@963 **והיו לכם לאחוזה.** למדנו מזה המקום שקניין עבד הכנעני דומה לקניין האחוזה בתאר איכות הקניין והנה נתבאר בפרשה הבאה שקנין האחוזה יהיה בכסף ולזה יתבאר שקנין העבד הוא בכסף והתבאר מפרשת שפחה חרופה שהעבד קונה עצמו בשטר ולזה יחוייב שיהיה נקנה גם כן בשטר ויתבאר שהוא נקני' בחזקה לפי שהאחוזה נקנית בחזקה כמו שנזכר בכרם נבות:
@964 **והתנחלתם אותם לבניכם אחריכם לרשות אחוזת עולם.** זכר הבנים כי הם היותר ראויים ליירש וזה כי הבנות לא ינחלו אלא כאשר אין שם בן:
@964 **לעולם בהם תעבודו.** ידמה מהנמשך לה שהרצון בזה שראוי לנו לעבוד בעבד כנעני אף על פי שאין העבודה צריכה לנו ואין העניין כן בעבד עברי שהיה עובד ולזה אמר שבאחינו בני ישראל לא נרדה בפרך:
@965 **וכי תשיג יד גר ותושב עמך.** הגר הוא גר צדק ותושב הוא הדר בארצנו שקבל עליו שלא לעבוד ע"ז כי לא נניח לשבת בארצנו העובד ע"ז שנאמ' לא ישבו בארצך פן יחטיאו אותך לי:
@965 **או לעקר משפחת גר.** אחשוב כי עקר הוא הפך תושב ולפי שהתושב הוא שאפשר לו לשבת עמנו בארצנו לפי שאינו עובד ע"ז הנה יהיה עקר מי שיחוייב לנו לעקור אותו ולהעתיקו מארצנו לפי שהוא עובר ע"ז והנה הוא משפחת גר תושב אלא שגר תושב קבל שלא לעבוד ע"ז והוא לא קבל עליו זה:
@966 **אחרי נמכר גאולה תהיה לו עד או השיגה ידו ונגאל.** ר"ל שאין ראוי לעזוב אותו בידו שלא ילמד ממעשיו ולזה ראוי להשתדל בגאולתו היותר קרוב לו כמו אחיו או דודו או בן דודו או שאר קרוביו וזה בהדרגה כי היותר קרוב הוא קודם לגאולה ואם אין אחד מקרוביו גואלו הנה ישתדל הוא עצמו בגאולתו תכף שתשיג ידו ולפי שלא אמר ומצא כדי גאולתו כמו שאמר בפרשת הקודמת למדנו שהוא נגאל לחצאין. ר"ל שאם השיגה ידו לגאל הוא עצמו לקצת שוויו גואל עצמו לקצת שוויו. ובכלל הנה בארה התורה שראוי להשתדל שלא יהיה נשקע שם ולזה צותה התורה שיגאלו אותו קרוביו ומפני זה הוא מבואר שיש בידו ללוות או לגאל עצמו או למכור מנכסיו או לגאל עצמו לחצאין:
@968 **וחשב עם קונהו משנת המכרו לו עד שנת היובל.** אמר זה לפי שהוא אינו מחויב לעבוד כי אם קונו ולזה אם מת אדוניו אינו עובד את הבן וזה הדין הוא משותף לגר צדק ולתושב ולעקר כי בהם דברה זאת הפרשה:
@968 **והיה כסף ממכרו במספר שנים כימי שכיר יהיה עמו.** למדנו שהוא נגאל בכסף לא בשוה כסף ולזה זכרה התור' בזה המקו' כסף ולא זכרה זה בפרשת מוכר שדה אחוזה וזה מיושר התור כי מפני שהקלה התורה בעניין הגאולה הזאת שיגאלוהו קרוביו או ילוה לגואל או יגאל עצמו אם תשיג ידו הנה יקרה בזה מן העול אם יוכל לתת לאדוניו שוה כסף והוא שבזה האופן יתכן שיערימו האנשים לימכר מה שלא ימצא לו קונין לקנות ויהיה בזה עשוק מי שיקנה זה העבד ולזה לא רצתה התורה שלא יגאל אלא בכסף לא בשוה כסף ומה שאמר כימי שכיר יהיה עמו הרצון בו כימי שכיר שיודע סך שכירתו לשנה או לחדש ואינו נמכר עולמי':
@969 **אם עוד רבות בשנים לפיהן ישיב גאולתו מכסף מקנתו.** ר"ל שאם היו שנים רבות עד היובל לפי מה שיעלה שנה בשנה ישיב גאולתו לפי הערך שקנהו אדוניו והמשל שאם קנהו שבעים דנרין עד היובל והיו שם ז' שנים הנה ישיב לכל שנה עשר דנרי':
@970 **אם מעט נשאר בשנים.** זה הפסוק הוא מבואר כמו שביארנו בפסוק הקודם לו אמנם יתבאר ממנו עוד דבר לא נלמדהו מהפסוק הקודם וזה שאם היה כסף מקנתו עולה לשנה יותר ממה שהוא שוה עתה בעת רצותו לגאל עצמו הנה לא ישיב גאולתו אלא כפי שניו שהם עתה שנאמר וחשב לו כפי שניו ולא אמר וחשב לו כפי השנים:
@971 **כשכיר שנה בשנה יהיה עמו.** שאין רבו מושל בו באופן הממשלה שיש לאדון על העבד שנמכר לו עולמית וזה מבואר בנפשו:
@971 **לא ירדנו בפרך לעיניך.** הזהירתנו התורה שלא נניח הגוי לרדות בעבד עברי בפרך והוא העבדות שהכונה בו לענות גוף העבד כגון שצוהו לעשות מלאכה שאינו צריך לה כדי שלא ינוח או שצוה לעשות המלאכה שהוא צרך ולא נתן לה קצבה כדי שלא ינוח:
@972 **ואם לא יגאל באלה.** ר"ל שלא יגאלוהו קרוביו ולא השיגה ידו להגאל:
@972 **ויצא בשנת היובל הוא ובניו עמו.** ר"ל בזולת כסף ואמר שיצאו בניו עמו להורות שהגוי שנמכר לו חוייב במזונות אשתו ובניו:
@973 **כי לי בני ישראל עבדים.** כבר התבאר ענינו בפרשה הקודמת:
@974 **לא תעשו לכם אלילים.** הזהירה בזה המקם מע"ז להעיר שהכונה ביובל ובשמטה להעיר ולהישיר לעבודת השם יתעלה:
@974 **ופסל מסכה לא תקימו לכם.** אחשוב כי פסל הוא צורה נעשית לנוי לא לעבודה זרה. ומצבה הוא בנין שנהגו עובדי ע"ז לבנותו בבתי ע"ז והזהירתנו התורה מעשות זה אפילו להשם יתעלה כדי שלא נסתבך באלו הפעולות המגונות היו נשקעים בהם עובדי ע"ז באותם הזמנים:
@974 **ואבן משכית לא תתנו בארצכם להשתחות עליה.** לפי שהתנה ואמר בארצכ' למדנו שלא הוזהרנו על זה חוץ לארץ ישראל וענין איסור אבן משכית היה שכבר היה מנהג עובדי ע"ז להניח אבן לפני ע"ז ושם משתחוים ליראתם והנה ענין ההשתחואה הוא לפי הוראת הגדר היא פשוט ידים ורגלים:
@975 **את שבתותי תשמורו ומקדשי תיראו.** זכר בזה המקום שמירת השבתות ויראת המקדש להעיר כי זה כלי מביא להישירנו על עבודת השם יתע' ולהרחיק מעבוד זולתו כמו העניין בשבתות ובמקדש לפי מה שביארנו במה שקדם ובכאן נשלם ביאור זאת הפרשה:
@998 **אם בחקותי תלכו וגו'.** ר"ל שתעשו אותם ולא זכר בהם שמשירה לסבה שזכרנו בפרשה הקודמת בביאור ועשיתם את חקותי ואולם במצות שהם מכוונות לעצמם וזכר שמירה ועשייה כמו שביארנו שם:
@999 **ונתתי גשמיכם בעתם וגו'.** כבר ביארנו בספר מ"י שהדבקים בשם יתעלה תדבק בהם ההשגחה האלהית גם בכמו אלו הדברים הגופיים ולזה אמרנו שמאמר מי שיאמר בני חיי ומזוני לאו בזכותא תליא מילתא אלא במזלא תליא מלתא הם דברי יחיד ואינם נאותי' לפנות התוריות אלא אם יפורשו באופן אחר כאלו תאמר שהם אינם באים לבד מצד ההשגחה הפרטית אשר היא לויה בזכות המושגה אבל נמצאים באים גם כן מצד ההשגחה הכוללת אשר היא תלויה במזל ולזה נמצא הרבה מהאנשים מושגחים בכמו אלו הטובות מזולת זכות ימצא להם ואמ' שימשך להם מהטובו' בהתנהג אותם במנהגי המצות התורייות שיבואו להם גשמי השנה בעתם באופן שתתן הארץ יבולה הראוי לה ועץ השד' פריו הראוי לו לא יפול דבר ויהי' להם מרבוי התבואות עד שדיש הקציר יתמיד עד הבציר והבציר יתמיד עד עת הזרע:
@1000 **ואכלתם לחמכם לשובע.** ר"ל שהלחם הראוי לכם למזון תאכלוהו לשובע כי רבוי הטובות ישביע לאדם קודם מלוי כרסומהם ולזה תמצא שבעת החסרון המזון יאכל הרבה ולא ישבע:
@1000 **וישבתם לבטח בארצכם.** ר"ל שלא תפחדו מהעתים שיוזקו בהם תבואותיכם ועבודת הארץ אבל תבטחו שיתן השם יתעלה הטוב וארצכם תתן יבולה מצד עוצם דבקות השגחת השם יתעלה בכם בראותכם תמיד הגעת אלו הדברים בארצכם על הטוב שבאופנים ולזה לא תיראו והמשל כי מי שהורגל לבא בארצו אלו הנזקים יירא מאד בראותו העננים החשובים מאד סביב עת הקציר שיפול ברד וישחית תבואתו:
@1001 **ונתתי שלום בארץ ושכבתם ואין מחריד.** ר"ל שיהיה שלום בין איש לאחיו באופן שלא יירא איש מאחיו שיזיקהו באופ' מהאופנים :
@1001 **והשבתי חיה רעה מן הארץ.** באופן שלא יגיע ממנו היזק לבהמתכם ולטפכם:
@1001 **וחרב לא תעבור בארצכם.** ר"ל אפילו חרב של שלום כי כבר אפשר שיגיע ממנה היזק ופחד ליושבי הארץ כמו שהתפרסם מעניין יאשיהו כשעבר פרעה נכה וחילו בארץ ישראל:
@1002 **ורדפתם את אויבכם.** ר"ל מהאומות האחרות ותשיגו אותם עד שנפלו לפניכם לרב. ובזאת הרדיפה תהיה עוד לכם הצלחה עצומה והוא שכבר ירדפו' מכם חמשה משונאכם ומאה מכם ירדפו רבבה משונאכם ועם היותם בזה האופן מהריבוי ואתם בז האופן מהמיעוט כבר תשיגום ויפלו לפניכם לחרב וזה עניין נפלא בחוזק ההשגחה האלהית והנה לא הלך זה הענין ביחס ר"ל שאין יחס מאה אל רבבה כיחס חמש' אל מאה אבל הוא כיחס אחד אל מאה והיה זה כן כי כשינצחו מאה רבבה לא יחוייב שינצח אחד מאה אבל יותר נפלא אם ינצחו חמשה מאה מהנצוח המאה רבבה כי החיל יקנה מן החוזק מצד הרבוי מה שלא ימצא לחלקי החיל נפרדים והנה כשיגיע רבוי החיל לרבוי מופלא לא יתוסף חוזק החיל על יחס הכפל הרבוי אבל פחות מזה או יקרה שלא יתוסף כלל חזקו בהכפל רבוי וזה כלו מבואר בנפשו:
@1004 **ופניתי אליכם.** ר"ל שהשגחתי תדבק בכם באופן שתפדו ותרבו מאד שלא יהיה בכם עקר ועקרה כמו שזכרה התורה במקום אחר לא יהיה בך עקר ועקרה ובבהמתך. ואקים את ברכתי אתכם. להיות מתקיים בכם מה שיעדתי לאבות מירושת הארץ ותהיה השגחתי תמיד בכם דבקה באופן שתנצלו מהרעות הנכונות לבא עליכם ויגיע מדבקות השגחתי בכם גם בעניני הגופיים עד שבשנת השמטה יאכלו ישן ונושן כמו שהבטיח בפרשה הקודמת שנאמר וצויתי את ברכתי לכם בשנה הששית:
@1005 **וישן מפני חדש תוציאו.** ר"ל שמרוב התבואות והפירות יצטרך לפנות מהאוצרות הישן לשום בהם החדש כי לא ימצא להם מקום בזולת זה האופן לרבוים:
@1006 **ונתתי משכני בתוככם וגו'.** ירצה לפי מה שאחשוב כי בהנהגם בדרכי התורה באופן שירחיקו הפעולות המגונות שהם סבת מיאוס רצון השם יתעלה במי שיעשה אותם הנה אף על פישלא קנו מהשלמות המכוון בתורה בדיעות שהוא כל פרי התורה דבר מורגש הנה יהיה משכן השם יתעלה בהם והנה הרצון בזה שכבר אתן את משכני בתוככם כשתהיו באופן שלא תגעל נפשי אתכם ואף על פי שלא קניתם מהשלמות בדיעות מה שיתחייב שתדקב השגחתי בכם והיה זה כן לפי שזה הנימוס התוריי מישיר אל קניין השלמות ההוא הישרה נפלאה ולזה אי אפשר מזולת שימצאו באומה המתנהגת במנהגי זאת התורה רבים שהשיגו בקניין זה השלמות דבר מורגש או ירצה בה שכבר אתן משכני בתוככם ולא תגעל נפשי אתכם כשיקרה שתעברו על קצת המצות זה הנימוס אבל תדבק השגחתי בכם ליסר אתכם כאשר ייסר איש את בנו:
@1007 **והתהלכתי בתוככם.** שזה הנימוס התוריי יהיה סבה שאשגיח בכם באופן שאהיה לכם למנהיג תמיד ועל פי תהיינה פעולותיכם להציל אתכם מהרעות הנכונות לבא עליכם במה שאודיע לכם מה ע"י עבדי הנביאים וע"י הכ"ג כמו שנתבאר במה שקדם בבגדי כהן גדול:
@1007 **ואתם תהיו לי לעם.** ר"ל כי מבין שאר האומות היוחדו להיות לי לעם:
@1008 **אני יי' אלהיכם.** רוצה לומר שהו' ראוי שתתנהגו במצותי כי אני הוצאתי אתכם מן העבדות הנפלא שהייתם בו ושמתי אתכם בני חורין ובזה הנימוס התוריי לא שהעמסתי עליכם מה שיכבד עליכם כמו העניין בשאר הנימוסים אבל הם ענינים יקל עשייתם לאדם להיותם נבחרים מצד עצמותם ולזה היה זה הנימוס חירות לכם לא עבדות ולזה גם כן אין ראוי שיכבד לכם מה שנתתי מהחירו' בארץ בשנת השמטה והיובל כי אני הנחלתי אתכם הארץ באלו התנאים והנה לא יעדה התור' בזה המקום ההולכי' בדרכי התורה כי אם באלו הטובות הגופיות לפי שהגעת הטובות הנפשיות לשלמי השכל הוא דבר הכרחי והנביא לא ייעד במה שהוא נביא בדבר ההכרחיי אבל ייעד בדברים האפשריים וזה מבואר מאד:
@1009 **ואם לא תשמעו לי וגו'.** כבר מצאנו שקרא התורה ע"ז בזה הלשון בפרשת של לך לפי שהעובד ע"ז כאלו עובר על כל מצות התורה כי לא יאמין במצות התורה עם האמנת בע"ז וזה מבואר בנפשו. וכבר התבאר גם כן בזאת הפרשה שבאלו המצות תכלל ע"ז שנאמר והשמדתי את במותיכם:
@1010 **ואם בחקותי תמאסו.** רוצה לומר שתעזבום על צד המיאוס כי בזה הריסה לכללות התורה ואפילו לא עזבו כי אם מצוה אחת ממנה בזה האופן וזה מבואר בנפשו:
@1010 **לבלי עשות את כל מצותי להפרכם את בריתי.** ר"ל שיהיה מה שלא תשמע לי ותמאסו דברי על זה האופן סבה שתעבדו ע"ז או להפר את בריתי לעבור על מצותי על צד המיאוס בהם והנה הודיעתנו התורה כי כמו אלו העונשים הגדולים שזכר בזאת הפרשה לא יהיו לכלל האומה אם לא על כמו אלו העבירו' הגדולות אשר יהיה בהם הריסה לכללות התורה. הלא תראה שגם בעת שהיו ישראל עודים ע"ז האריך להם השם יתעלה העונש והוכיחם ע"י הנביאים עד שנתברר שמאנו לקחת מוסר באמרו על מה תוכו עוד תוסיפו סרה והנה לחזק השגחת השם יתעלה על ישראל יביא עליהם אלו העונשים ליסרם בהדרגה וזה שבראשונה ייסרם בהבאתו עליהם מיני חליים כמו השחפ' והקדחת ואם זרעו יבאו אויביהם לגזל מהם תבואותיהם ויכו אותם וימשלו בם באופן שינוסו ישראל מפניהם בראותם אותם ואף על פי שאינם רודפים אותם ואם לא ייוסרו ישראל בזה התוכחה הנה יוסיף השם יתעלה ליסר אותם בתוכחת יותר עצום מזה מאד עד שיהיה זה המוסר יותר נפלא ביחס שבעה אל אחת והוא שימנע מהן מזונם באופן כולל כי הגשמים ימנעו מהם והארץ לא תצמיח זרועיה ואמנם היה זה המוסר יותר חזק מהראשון ואם היה בו גם כן המעטת מזונם כי האויבים כשיגזלו התבואות בזה האופן הנה יהיה מעטי מה שיגזלו מזה ביחס אל מה שישאר ממנו ליושבי הארץ ואולם בזה האופן השני יעדר כל המזון ואם לא יוסרו ישראל בזה המוסר השני ולא יחשבו שיהיה בא על צד העונש אבל ייחסו באו אל הקרי והזדמן ולזה לא יוסרו:
@1010 והנה יביא עליהם השם יתעלה מוסר יותר נפלא והוא ישלח בהם חיה השדה ואכלה מטפם והכריתה בהמתם והמעיטה אותם באכלה מהם עד שיהיו הדרכים שוממין שלא ילך בהם אדם ליראתו מהחיות רעות שיאכלוהו וזה מבואר היותו עונש נפלא מהקודם לו כי יגיע ממנו הזיק בגופות מהאנשי' ובמזונותיהם ואם לא יוסרו ישראל בזה המוסר השלישי ולא יחשבו היותו בא על צד המוסר אבל על צד הקרי הנה יביא עליהם ה' מוסר יותר נפלא והוא שיביא עליהם חרב הורגת אותם להנקם מהם נקמת התורה שעברו עליה וכאשר יאספו אל עריהם כדי שלא תשלוט בהן יד האויב הנה לא יועיל זה להם כי ה' ית' ישלח שם דבר עד שלא יוכלו לשמור ערי המבצר וינתנו ביד האויב וכאשר יתן להם ה' משען להם יהיה מעט עד שכר יאפו י' נשים לחמם בתנור אחד למעוט מה שתאפה אחת א' מהם והשיבו לחמם במשקל שהיה כששמוהו בתנור כי לא יניחוהו לאפות כראוי כדי שיאכלו ממנו מעט או ירצה בזה שהלחם ההוא מרוב הסובין והמורסן אשר בו לא יתדבק אבל יהיה נפרך בתנור ולזה יצטרך לנשים ההם להשיב הלחם במשקל לא במספר ובמשקל יחלקוהו ביניהם ועוד שאשלח מארה במזון ואף על פי שיאכלו לא ישבעו וזה אמנם יקרה מצד חסרון המזון ואם בזאת יא יוסרו ישראל ויחסו זה הרע אל הקרי הנה ייסר אותם עוד ה' ית' בקשה שבענינים אשר אפשר שיתיחסו אל הקרי והוא שכבר יגיע מחזק הרעב שיאכלו בשר בניהם ובנותיהם וזה מבואר שהוא יותר קשה מהחרב ומשאר מה שקדם וכבר קרה זה הענין בחרבן בית ראשון ובחרבן בית שני לפי מה שנתפרסם ואש ישמיד ה' ית' הכמות שעשו ישראל לעבודה זרה ויכרית החמנים והם הע"ז שעשו להשתחוות לשמש ולצבא השמים ויהיה זה מצד נפלם ביד האויב והוא יהרוס כל בנייניהם וזה הגמול הראוי להם כי מפני שלא רצו לסור מעבודה זרה ברצונם יסורו ממנה על כרחם כי האויב יכרית במותיהם בהכרית עריהם:
@1025 **ונתתי את פגריכם על פגרי גלוליכם.** רוצה לומר שאצל פגרי ע"ז יפלו בחרב וברעב באופן שיפלו יחד הם ואלהיהם הזרים וזה ממה שיורה להם שאין כח באלהי' ההם להושיעם:
@1025 **וגעלה נפשי אתכם.** ר"ל שכבר ירחיק רצון ה' ית' מהם ולא יפנה אליהם להשגיח בהם ויתן את עריהם הרבה וישם מקדשיהם שוממין והם המיוחדים לעבוד השם ית' במקדש ואם יקריבו עליהם הקרבנו' לא יקבלם ברצון וזהו אמרו ולא אריח בריח ניחוחכם וכבר נתאמת כל זה הנמשך לו מאלו הקללות מעת חרבן הבית בעונות אבותינו:
@1027 **והשמותי אני את הארץ.** ר"ל שכבר אשים ארציכם שממה ואויביכם היושבים בה יתמהו מאד על מה שחלו בארץ ההיא מהמכות והנגעים ואפזר אתכם בגוים ושם אריק אחריכם חרב להרוג אתכם במקומות אשר נדחתם שם ותהיה ארצכם שממה ועריכם תהיינה חרבות מאין יושב:
@1029 ו **אז תשבת הארץ** מה שלא שבתה הארץ בשנת השמיטה בהיותכם עליה כי לא יהיה אז שם מי שיתעסק בעבודת הארץ והאלנות וזה הגמול הראוי לכם על אשר מאסתם בחקותי לבלתי שבות מעבודה בשנת השמטה:
@1031 **והנשארים בכם.** מן החרב יהיה בפחד בארצות אויביכם עד שכבר ירדוף אותם הקול החלוש שאפשר והוא קול העלה הנדף לרב המורך אשר בלבבם וינוסו כמו שינוס האדם מן החרב ונפלו ואין רודף אותם ובנוסם יכשלו איש באחיו ויפלו כאלו היו נסים מפני חרב ורודף אין ולא תהיה לכם תקומה לפני אויביכם מה שיתמיד הגלות ההוא:
@1033 **ואבדתם בגוים אשר נדחתם שם ואכלה אתכם ארץ אויביכם.** במינים רבים מהכליון:
@1034 **והנשארים בכם.** אחר אלו המקרים המכלים אותם יהיו הולכים ומתמעטין בארצות אויביהם:
@1034 **ואף בעונות אבותם אתם ימקו.** כי כבר יכשלו הבנים בעון אבותיהם במקרה מצד מה שהחלו בהן מהרעות אשר אי אפשר סורם אם לא כשהיו הבנים באופן מהשלמות שתדבק בהם השגחת ה' ית' להשיבם על אדמתם וזהו אמרו אבותינו חטאו ואינם וגומ':
@1035 **והתודו את עונם ואת עון אבותם.** ויכירו כי במעלם אשר מעלו בי לעבוד ע"ז ולמאוס חקותי ומשפטי ובמה שהלכו עמי בקרי בהביאו עליהם מוסרי ולא לקחו מוסר אבל אמרו שזה העונש הוא מקרה קרה להם היה מה שחל עליהם מהרעות כי זה היה סבה אל שהלכתי אף אני עמם בקרי והבאתי עליהן אלו הרעות והנפלאות והבאתי אותם בארץ אויביהם אשר יה סבה להתמדת הרע להם זמן ארוך:
@1036 **או אז יכנע לבבם הערל.** וישובו אל השם ית' בכל לבם ויכניסו צוארם תחת עול תורתי ואז יהיה נרצה עונם. ר"ל שיהיה נשלם ענשם הראוי להם ואז אפקח עיני עליהם ואזכור את בריתי את האבות ואזכור את הארץ שנשבעתי לאבות לתתה לזרעם והארץ תעזב מהם ותשלים שמטותיה בעת היתה שממה והם ישלימו לקבל ענשם על אשר מאסו בחקותי ומשפטי:
@1039 **ואף גם זאת.** עם כל מה שהפליגו במרי היתה השגחתי באופן מה בהם בהיותם בארץ אויביהם ולא השלטתי אויביהם לכלותם באופן שהופר בריתי אתם:
@1039 **כי אני הש' אלהיהם.** ואם אינם ראויי' שתדבק בהם השגחתי מצדם הנה תדבק בהם ההשגחה מה מצד האבות בדרך שלא יכלה זרעם ותופר בריתי אתם והנה דבקות השגחתו ית' בנו היום בהיותנו בגלות מבואר מאד כי עם משול אויבינו בנו ורצותם להזיקנו אנחנו חיים ביניהם והנה כל מה שנזכר באלו הקללות עבר עלינו ועל אבותינו בעונותינו ובעונות אבותינו לפי מה שנתפרסם לנו מספורי הקודמים ואחשוב שיהיה אמרו והשימותי את מקדשיכם מורה על חרבן בית ראשון ובית שני ומה שאמר ואתכם אזרה בגוים והריקותי אחריכם חרב מורה על הרוגי ביתר שהיה זמן מועט אחר חרבן בית שני ומה שאמר ואבדתם בגוי' ואכלה אתכם ארץ אויביכם מורה על הצרות הגדולות שעברו על עמנו שמתו מהם רבים מכללם להרג קצת הקהלות הקדושות וגרוש היהודים מארץ צרפת שמתו בסבתו כפלים כיוצאי מצרים ברעב ובדבר:
@1041 **אלה החקים והמשפטים והתורות אשר נתן יי' בינו ובין בני ישראל בהר סיני ביד משה.** נכלל בזה כל מה שנזכר מהמצות במה שזכר במה שקדם אחר עשרת הדברים בפרשת יתרו ושם נזכרו משפטים רבים בפרשת ואלה המשפטים והתורות הם הנימוס העשות החקים כאלו תאמר תורת החטאת תורת האשם תורת העולה והחקים הם עניני המועדים והשמטות והיובל וענין הטומאות והקרבנות ומה שידמה להם ממה שידמה שאינו מכוון מצד עצם הפעולה ההיא:
@1043 **דבר אל בני ישראל ואמרת אליהם איש כי יפליא לנדור.** ר"ל שיהיה לו דעת לפרש נדרו ולדעת לשם מי יהיה נדרו וכבר שיערו חכמים שזה יהיה על הרוב בזכר בהיותו בן י"ב שנה ויום אחד ובנקבה בהיותר בת י"א שנה ויום אחד ולדה אם נדרו בזה הזמן אע"פ שאינם גדולים אם ידעו למי נדרו נדריהם קיימים ואם אינם יודעים זה אין נדרם נדר עד שיגדלו ואין ראוי שנשפוט שלא ינהג זה הדין אלא באיש שכבר מצאנו בתורה בביאור בפרשת מטות שאשה נודרת כמו שהאיש נודר ואין ראוי שנשפוט שלא יהיה זה הדין נוהג אלא במי שהוא גדול כי בכמו אלו הענינים מצאנו שיכנס בגדר הקטן כמו שיראה מענין קרבן זב וזבה ולזה יתבאר כי הקטן כאשר יהיה מפליא לנדור יהיה נוהג בהם זה הדין:
@1043 **בערכך נפשות.** כמו שאמ' ערך פלוני עלי לה' ואם היה לו ציור מה במי שנדר לו זה הנדר אע"פ שאינו עדיין בערך הגדול בשלמות הנה יתחייב בזה הנדר כמו שקדם וראוי שנדע שאי זה שיהיה הנערך הנה יהיה דינו לפי מה שנזכר. ר"ל שאם היה זכר והיה מבן חדש ועד בן חמש שנים יהיה ערכו חמשת שקלים כסף צרוף משקל כל אחד שלשה מאות ופ"ד גרגירי שעורה ואם נקבה שלשה שקלים ואם מבן ה' שנים ועד בן כ' שנה יהיה ערך הזכר כ' שקלים וערך הנקבה י' שקלים ואם מבן כ' ועד בן ס' שנה יהיה ערך הזכר נ' שקלים וערך הנקבה שלשים שקלים ואם מבן ס' שני ומעלה יהיה ערך הזכר ט"ו שקלים וערך הנקבה י' שקלים וכבר ביארנו במה שקדם שהשנים הנזכרים בתורה הם פעם מי"ב חדש ופעם מי"ג ומאלו השנים נמנה כל השנים הנזכרות בתורה ולפי שלא נתנה התורה ערך לפחות מבן חדש ולא למי שאינו ודאי זכר או נקבה ודאית למדנו שאין ערך לפחות מבן חדש ולא לטומטום ולא לאנדרוגינוס אמנם הזכר והנקבה יהיה ערכם לפי הקצוב בתורה היו חולים או בריאי' היו מישראל או מזולת ישראל כמו הגוים והעבדים ואמנם אם היה בגדר המת כמו הגוסס ומי שנגמר דינו למיתה אין לו ערך וזה כי רוב הגוססים למיתה ולזה יהיה חשוב כמת והתורה אמרה בערכך נפשות ומי שנגמר דינו למיתה הנה הוא מת בכח אשר הכח ההוא הולך מהלך השלמות כי הנימוס התוריי יכריחנו להמיתו והכוחות שזה דרכם מדרגתן מדרגת מה שבפעל כמו שנתבאר בשרשים הכוללים:
@1049 **ואם מך הוא מערכך והעמידו לפני הכהן וגו'.** ר"ל שאם היה הנודר עני באופן שלא יוכל לפרוע זה הערך הקצוב הנה יעמוד הנערך לפני הכהן והעריך הכהן אותו לפי השג יד הנודר ולמדנו מאמרו ואם מך הוא מערכך שאעפ"י שיהיה הנודר עשיר מאד לא יוסיף על הערך הקצוב בתורה אמנם אם יהיה עני יחסר מהערך ההוא לפי עניו אבל יהיה זה בהעמדת הנערך לפני הכהן והיות הכהן מעריך אותו בזה האופן להורות כי מה שיפרע הוא הערך שדר כדי שלא יזלזלו האנשים בנדרים ולפי שראוי באלו הנדרים להעמיד הנערך ולהעריכו על פי אשר תשיג יד הנודר באופן שיראה מה יתחייב זה הנודר אם ערך שלם או פחות ממנו למדנו שאם מצת הנערך קודם שעמד הנודר בדין אין לו ערך כי אין ערך למתים ומזה המקום נלמד גם כן שהגוסס אין לו ערך לפי שאי אפשר לו ההעמדה לפני הכהן וראוי שתדע שאם נדר ערך אבר שהנשמה תלויה בו נותן הערך לפי הדין הנזכר אבל אם נדר ערך אבר שאין הנשמ' תלויה בו פטור שנאמר כערכך נפשות ליי' וראוי שנדע שהנודר כשהיה עני לא יפרע פחות משקל כי התורה דקדקה שיהיה הנפרע שקלים והפחות שבזה הסוג הוא שקל אחד והוא מבואר עוד שלפי השנים שיש לנערך בעת שנדר יעריכנו הכהן לא לפי השנים שיש להנערך בעת ההערכה וכן יתבאר שאם היה עשיר בעת הנדר ועני בעת ההערכה או הפך יתחייב ערך שלם שנאמר ואם מך הוא מערכך ר"ל שהוא מך בעת הנדר והערכה וזה כי לא אמר ואם היה מך ולזה הוא מבואר שכיון שאינו מך עתה יתחייב ערך שלם וכן אם לא היה מך בעת הנדר והיה מך אחר כן כי כבר יתחייב בערך שלם כעת הנדר לא יפטרנו ענין ממה שנתחייבו בו להקדש וראוי שיתבאר שזה הדין נוהג בערכין אבל מי שאמר דמי פלוני עלי ליי' יתן דמיו לפי מה שהוא נמכר בשוק היה איש או אשה ולזה יתחייב לתת דמים לפחות מבן חדש ולאבר אף על פי שאין הנשמה תלויה בו ויתחייב גם כן לתת הדמים לטומטום ולאנדרוגינוס אך לגוסס ולמי שנגמר דינו למיתה לא יתחייב לתת דמים כי אין להם דמים:
@1050 **ואם בהמה אשר יקריבו ממנה קרבן להשם.** ר"ל שאינה בעלת מום והוא מן הבקר או מן הבקר או מן הצאן כי ממנה יקריבו:
@1050 **כל אשר יתן ממנה להש' יהיה קדש.** ר"ל שאינו נגאלת כי מפני שהיא ראויה לקרבן כבר חלה קדושה בגוף הבהמה ויחוייב שתהיה קרבה למזבח והנה הוא מדבר בזה המקום בקדשי מזבח ולזה אמר אשר יקריבו ממנה קרבן להשם וראוי שתדע שאם הקדיש ממנה אבר למזבח הנה אם לא היתה הנשמה תלויה בו אינו קדוש אלא אותו האבר ותמכר הבהמה ודמיה חולין חוץ מדמי אותו האבר ואמנם הבהמה תקרב למזבח ויקנה אותה מי שהוא מחוייב קרבן שהבהמה ההיא ראויה לו ולזה אמרה התורה כל אשר יתן ממנו להשם יהיה קדש ומנם אם הקדיש אבר שהנשמה תלויה בו פשטה הקדושה בכל הבהמה כי אל יתכן שיאמר בזה האבר שהוא ממנו ר"ל מהב"ח ההוא כי הוא לא ישא ב"ח בסורו ולזה לא יתכן שיתואר זה האבר בשהוא מהנשאר מהב"ח ההוא אבל יתואר שהוא מהב"ח ההוא בכללותו ולפי שהתורה זכרה בזה המקום בהמה ובה אמרה זה הדין הנה יסופק אם ינהג זה הדין בעוף ר"ל שאם הקדיש אבר שהנשמה תלויה בו יהיה קדוש כלו כי אולי מצד חסרון הב"ח לא יהיה קדוש כלו אם לא הקדישו בכללותו ואולי דינו בזה שוה לדין בהמה:
@1051 **לא יחליפנו ולא ימיר וגו'.** ראוי שיתבאר מזה גם כן שהמאמר בזה המקום הוא מדבר בקדשי מזבח שאם היה מדבר בקדשי הבית הנה לא אשער למה הקפידה התורה שלא ימיר אותו והנה אינו קדוש כי אם לדמיו ועוד שהתורה ביארה זה הדין במעשר בהמה כמו שיבא אחר זה שהוא הקל שבקדשי מזבח וממנו יתבאר שכן ההקש בשאר קדשי מזבח ויתבאר ממנו לפי השרשים הכוללים שאינו נוהג בקדשי הבית כי אינם ראויין בזה הדין כמו קדשי מזבח וראוי שנעיין אם החלוף והתמור' תהיה אפשרית בקטן היודע להפליא וזה כי מצד שנדרו נדר ידמה שתמורתו תמורה ומצד שאינו כן אזהרה קודם היותו גדול ידמה שאינו ממיר אלא מי שהוא מוזהר מהמרה והוא הגדול ולזה יהיה העניין בספק אם תמורתו תמורה והנה ענין החלוף והתמורה הוא שיאמר זה תחת זה או זה תמורת זה או זה חלופי זה וראוי שימיר בהמת קדשים בבהמת חולין לא הפך זה וראוי שתהיה הבהמה שימיר בה שלו ואם לאו אין תמורתו תמורה ולזה אין אדם ממיר בבהמת חברו ולא בבהמת הקדש וכן הוא מבואר שאם לא היתה בהמת הקדש שלו אינו חייב אם המיר אותה כי אינו שליט בהמרת' אם לא השליטו בזה בעל הקרבן ההוא והנה הרצון באמרו טוב ברע תמים בבעל מום כי המום הוא דבר רע כאמרו לא תזבח להשם אלהיך שור ושה אשר בו מום כל דבר רע ולזה יקרא רע הבעל מום ומזה המקום יתבאר שכבר יתחייב אם המיר תמים בבעל מום או הפך וראוי שיתבאר שאין התמורה נוהגת אלא בבהמה שהיתה אפשרית להקרבה בעת שהקדישה שנאמר ואם בהמה אשר יקריבו ממנה קרבן להשם ולזה אם היתה בעלם מום קבוע בעת שהקדישה אין דין תמורה נוהג בה ועוד שהיא אינה מקדשי מזבח וכבר בארנו שמתנאי התמורה הוא שיהיה הקדש שימיר מקדשי מזבח ואולם אם היתה אז בעלת מום עובר הנה היא אפשרית ההקרבה ולזה ינהג בה דין התמורה וראוי שנדע שהבהמה שימיר בה אעפ"י שהיא בעלת מום קבוע ינהג בה דין התמורה שנאמר טוב ברע או רע בטוב אבל ראוי שתהיה מהבהמות שיקריבו מהם קרבן כי הנושא משותף יהיו כל ההפכי' הנזכרים בזה עד שלא יהיה הבדל בבם אם לא מזה מצד וזה מבואר מהשרשים הכוללים ולזה הוא מבואר שאין ממירין בכלאי' או ביוצא דופן ובמה שידמה להם כי אין אני קורא בהם טוב ברע:
@1051 **ואם המר ימיר בהמ' כבהמה והיא הוא ותמורתו יהיה קדש.** למדנו מזה שאין דין תמורה בעופות ובמנחות שנאמר בהמה בבהמה ולזה יחוייב שיהיה בהמה מה שימיר ומה שימיר בו גם כן ומזה המקום יתבאר שאין דין תמורה באברין ולא בעוברין כי הם אברים כמו שהתבאר מהשרשים הכוללים והנה האבר אינו בהמה ומזה המקום יתבאר שאין השותפין ולא הצבור עושין תמורה שאין אני קורא בכל אד מהם אם המר ימיר וגו'. אבל הוא ממיר חלקו בה והוא אבר או אברי' וראוי שיתבאר מזה שהוא חייב על כל בהמה ובהמה שהמיר בהם ואפילו היו אלף שנאמר בהמה בבהמה ולזה אם המיר בהמות רבות' באחת או הפך חייב על כל בהמה ובהמה וראוי שיתבאר שהבהמה שהקדיש הוא שינהג בה זה הדין התמורה לא בולדה שנאמר והיה הוא ולא ולדו ובזה יתבאר שאם המיר תמורתו אין תמורתו תמורה שנאמר ותמורתו יהיה קודש ולא תמורת תמורה וזה כי אין הולד תמורת התמורה ראויים בזה הדין כמו שראויין בזה תמורת ההקדש ותמורה. וראוי שנדע שאם היתה הבהמה שהמיר בה ראוייה לקרבן הנה היא תקרב באופן הקרב הבהמה שהמיר אותם רוצה לומר שאם היתה עולה או שלמים תהיה התמורה ג"כ עולה או שלמים שנא' והיה הוא ותמורתו יהיה קדש. ר"ל שהם קדש במדרגה אחת וזה מבוא עוד בנפשו כי הוא המירה לזה העניין ואמנם יקרה בקצת הקרבנות שלא יהיה אפשר בתמורתו שתהיה קרבה באופן ההוא וזה כי תמורת החטאת והאשם אי אפשר שתקרב כי הם באים לכפרה וכשלא יכופר בהם לא יתכן להקריבם ותמורת הבכור והמעשר לא יתכן הקרבתה באפן ההוא כי אי אפשר בבלתי בכור שיעשה דינו כדין בכור וכן הענין במעשר בהמה כי לא יקרא מעשר רק אשר יעבור תחת השבט הוא עשירי במניין כמו שיתבאר אח' זה וראוי שתדע כי זה הדין הוא אם המיר או החליף אבל אם חלל ההקדש על דבר אחד שחלל בהמה בבהמה אם היו קדשי מזבח והיתה הבהמה הראשונה לחולין וכן העניין בקדשי בדק הבית. ר"ל שאם חללו בדבר אחר הרי יצא לחולין וזה יתבאר ממה שאמרה התורה בפרשת ראשי המטות לא יחל דברו. רוצה לומר שלא השליטו הכתוב לחלל דבר בנדרי אחר כי אין שם דבר שיחללהו בו אבל יהיה חלולו בטול הנדר ואולם בנדרי ההקדש יהיה רשאי לחלל כי אין בחלולו בטול הנדר וזה יתבאר בביאור יותר שלם בהגיענו לשם ונאמר בזה המקום מעט ונאמר כי מפני שזכרה התורה בראשי המטות שהאדם שליט בהפרת נדרי בתו ואשו ושבועותיהם בנדר אשר זכרה תחלה שאינו שליט בהפרת נדרי עצמו ויתבאר מהשרשים הכוללים שאחרים שליטים בזה והם לפי מה שיתבאר מזה העניין האנשים שיש להם עליו קצת שררה ויתבאר מזה עוד שדברו הוא שאינו שליט לחלל אבל הוא שליט לחלל הקדשו לסבה שזכרנו:
@1052 **ואם כל בהמה טמאה אשר לא יקריבו ממנה ליי'.** למדנו ממה שאמר אשר לא יקריבו ממנה קרבן ליי' שהוא מדבר במיני הבהמות שיש בהן קרבן ואמנם נעדרה מהם ההקרבה מצד היותם בעלי מום וראוי שתדע שבבעל מום קבוע הכתוב מדבר ולזה קרא הבהמה ההיא טמאה כי כמו הבהמה הטמאה לא יתכן בה שתקרב לעולם כן העניין בזאת הבהמה ועוד שבעלת מום עובר אין אני קורא בה לא יקריבו ממנה אשה ליי' שהרי תבריא למחר ותהיה ראויה לקרבן:
@1052 **והעמיד את הבהמה לפני הכהן.** למדנו מזה שאם מתה אין פודין אותה כי אי אפשר להעמידה. והיה זה כי אין ראוי שנפדה הקדשים להאכילו לכלבים ואמנם נפדה אותם לשחטם ולאכלם:
@1053 **והעריך הכהן אותה בין טוב ובין רע כערכך וגומ'.** למדנו מזה שצריך שתהיה הבהמה לפני הכהן כשיעריכנה כדי שידוקדק יותר בהערכתה ומזה יתבאר שצריך לדקדק בהערכתה ולזה הסכימו רז"ל שזאת ההערכה תהיה ע"י ג' ואחד מהם כהן כי התור' הקפידה שיהיה המעריך כהן ומה שאמר בין טוב ובין רע ירצה לפי מה שאחשוב שאיך שיעריכנו אם ערך תמים הוא שוה יותר כי הוא ראוי למחוייבי קרבן אם ערך בעל מום שהו' אין ראוי אלא לחולין הנה יהיה ערך הכהן קיים או יהיה הרצון בזה והוא היותר נאות שאם יעריכנו ערך טוב להקדש. ר"ל שיהיה בו תועלת להקדש או יעריכנו ערך שיהיה הפסד להקדש הנה יהיה ערך הכהן קיים או ירצה בזה שיעריכנו לפי מה שהוא אם טוב ואם רע ולזה ראוי לו שידקדק להעריכו כשוויו וכבר יתבאר גם כן במה שקדם שאין אונאה להקדש שאם שמו אותה הפחות משוויה הרי היא יוצאת לחולין אלא שהוא מבוא מזה המקום שהוא ראוי שיחללו אותה בשוויה:
@1054 **ואם גאול יגאלנה ויסף חמישיתו על ערכך.** רוצה לומר שיפרו אותה הבעלי' מיד גזברי ההקדש יוסיפו החומש על הערך שאמרו לתת. ר"ל שאם אמרו לתת בה עשרים דינרין נותנין כ"ה דינרין וכבר ביארנו הטעם בתוספת החומש בפרשת ויקרא:
@1055 **ואיש כי יקדיש את ביתו קדש ליי'.** למדנו שאמרו ואיש כי יקדיש את ביתו שאין האדם שליט להקדיש אלא מה שהוא במדרגת ביתו. רוצה לומר שהוא שלו ויהיה ברשותו ואמנם המטלטלין שאינם ברשותו אף על פי שהם שלו לא יוכל להקדיש אותם והנה התועלת בזה הדין מבואר שאם היה האדם שליט להקדיש מה שיש לו דין בו אף על פי שאינו ברשותו הנה כאשר תרבינ הקטטות בין האנשים בטענותיהם זה על זה ולא ישלטו להוציאם מידם יקדישו ולהיות האנשים נבדלים מענייני ההקדש בתכלי' מה שאפשר יהיה זה סבה שיתחייב הנתבע עצמו להקדיש במה שלא היה לחבירו דין עליו:
@1055 **והעריכנו הכהן בין טוב ובין רע כאשר יעריך אותו הכהן כן יקום.** רוצה לומר שאיך שיעריכנו הכהן אם ערך שיש בו תועלת להקדש אם ערך שיש בו הפסד להקדש הנה יהיה ערך הכהן קיי' ויצא בערך ההוא הבית לחולין או ירצה בזה שיעריכנו לפי מה שהוא בין טוב ובין רע וזה יהיה כשיעריכנו כשוויו:
@1056 **ואם המקדיש יגאל את ביתו.** למדנו מזה שההקדש אינו נפדה אלא בכסף או במה שידמה לו והם המטלטלי' לא בקרקעות ועבדים ושטרות כמו שהתבאר בדומה לזה במקומות רבים במה שקדם ולמנו מזה שאין הבדל בזה העניין בין בתי ערי חומה ובין בתי החצרים ושהם נגאלים לעולם בין קודם היובל בין אחר היובל בין שעמדו ביד הקדש זמן ערוך או שלא עמדו בידו כי אם זמן מועט ולמדנו מזה ממה שקדם בבהמה הטמאה שהבעלי' מוסיפין חומש בהקדש ראשון לבד לא במה שיחללוהו עליו כי אינו ראוי בבזה הדין כמו ההקדש הראשון והתורה אמרה ואם המקדיש יגאל את ביתו שהוא הקדש הראשון ולמדנו מזה שאינו נקנה לו ההקדש אלא אחר שיפרע הכסף או שוויו וזה שהתורה אמרה ויסף חמישית כסף ערכך והיה לו ר"ל שאח"כ יהיה לו לא קודם זה ולמדנו מזה שהקדש אינו נפדה אלא בדבר שהוא נתן לעין לגזברי ההקדש כמו הכסף ומה שידמה לו ולזה אין הקדש נפדה בשכירות כי אולי יביא זה לחשוב שיהיה הקדש יוצא בלא פדיון וראוי שיתבאר מזה גם כן שהמקדיש מטלטלין או בהמה טמאה לבדק הבית ממה שהוא שלו והוא ברשותו יהיה דינו הדין הזה שנזכר בבית בענין הערכת הכהן אותו ובתוספת הבעלים חומש וביתר הדיני' שנתבארו מזה המקום וזה מהשרשי' הכוללים:
@1057 **ואם משדה אחוזתו יקדיש איש להשם.** הנה שדה אחוזה הוא השה שבאה לו בירושה והרצון באמרו יקדיש איש להשם שיקדישה לבדק הבית כי אי אפשר שיהיה מקדשי מזבח ואין שם קדש להשם זולתי קדשי המזבח וקדשי בדק הבית:
@1057 **והיה ערכך לפי זרעו.** למדנו שאם לא היה ראוי לזרע אינו נדון בזה הדין ר"ל בדין הערך הקצוב בתורה אבל נפדה כשוויו כמו הענין בבית זרע חומר שעורים בחמשים שקל כסף הנה החומר הוא לפי הוראה הגדר שלשים סאין והנה המקום שיפלו שם שלשים סאין לזרע יהיה ערכו חמשי' שקל כסף היתה השדה שמנה או רזה וזה הערך הוא אם הקדישה אחר שנת היובל אבל אם עבר זמן מה משנת היובל לא יהיה ערכו כי אם על פי השנים הנותרות עד היובל כמו שיזכור אחר זה ולפי שאמר על פי השנים הנותרות עד שנת היובל למדנו ששנת השמיטה עולה למניין אלו השנים ולזה הוא מבואר שאלו הנ' שקל כסף היה ערך מ"ט שנה ולזה יגיע לכל שנה שקל ואחד ממ"ט בשקל:
@1058 **ואם משנת היובל יקדיש איש שדהו כערכך יקום ואם אחר היובל וגו'.** ר"ל שיקדישה משנת היובל ואילך ויתבאר משם שאם הקדישה בשנת היובל אינה מקודשת כי אינה ראויה אז בזה הדין כמו שהיא ראויה אם הקדישה זולת בשנת היובל וזה שכבר ימצא לפי זה הפדיון שהיובל מפסיק באופן מה זה ההקדש ומסיר אותו ולזה לא היה הפדיון כי אם על פי השנים הנותרות עד שנת היובל:
@1059 **ואם אחר היובל יקדיש שדהו וגומ'.** ר"ל שיחשב לו הכהן את הכסף שהוא חמשים שקל למ"ט שנה על פי השנים הנותרות עד היובל ויחשוב לכל שנה שקל ואחד ממ"ט בשקל ומזה המקום יתבאר שאינה נפדית בגרעון כסף אם לא נשארו ב' שנים עד היובל שנאמר על פי השנים הנותרות ונגרע מערכך ואולם אם לא נשארו שתי שנים עד היובל אינה נפדית בגרעון כסף אבל אם ירצה לפדותה נותן נ' שקל כסף בזולת גרעון כלל ולמדנו עוד ממה שאמ' על פי השנים הנותרות שאין גורעין מהחמשי' שקל כסף לפדיו' שדה שיפול בו זרע חומר שעורים אם לא עברה שנה שלמה או שנים מאחר היובל ר"ל אם עברו קצת חדשים אינו גורע בעבורם דבר מפדיון השנה ההיא:
@1060 **ואם גאול יגאל את השדה המקדיש אותו ויסף חמישית כסף ערכך עליו וקם לו.** למדנו שהמקדיש הוא שמוסיף חומש כשפודה שדהו מיד ההקדש והם הבעלים ולזה הוא מבואר שאם פדה אותו בנו או אשתו מוסיפין חומש כשפודה שדהו מיד ההקדש וזה מבואר עוד מהסבה שנתננו בתוספת החומש בפרשת ויקרא:
@1061 **ואם לא יגאל את השדה ואם מכר את השדה לאיש אחר לא יגאל עוד.** והיה השדה וגומ'. רוצה לומר שאם לא יגאלוהו הבעלים קודם בא היובל ונשאר ביד ההקדש או אם מכר גזבר ההקדש את השדה לאיש אחר שאינו מהקמים תחת המקדיש לגאל את השדה לא יגאל עוד ולא ישוב לבעלים אבל יהיה בצאתו ביובל קדש לה' בשדה החרם שהחרימוהו לה' ר"ל שיהיה הקדש לבדק הבית אלא שאין ראוי שישאר ביד הקדש תמיד כי זה יהיה סבה שימעלו בו האנשים ולזה אמר לכהן תהיה אחוזתו וזה יהיה כשיפדוהו הכהנים מיד ההקדש ובזה האופן יהיה קדש לה' ותהיה אחוזתו לכהן והנה התבאר במה שקדם שהלוים לא ינהג בהם זה הדין אבל הם גואלין לעולם שנאמר גאלת עולם תהיה ללוים. ולזה ראוי שיתבאר שאם הקדישה באי זה עת שיהיה מקודשת אפילו בשנת היובל שכיון שגואלים לעולם מקדשין לעולם:
@1063 **ואם את שדה מקנתו אשר לא משדה אחוזתו יקדיש להשם.** הנה שדה מקנה הוא השדה שקנהו מזולתו או שנתן לו במתנה כי הוא איננו משדה אחוזתו ולפי שאמר אשר לא משדה אחוזתו למדנו שיש שם שדה מקנה שהוא משדה אחוזה כגון שלקח שדה ממורישיו ומתו מורישיו קודם שישוב השדה להם הנה דינה דין שדה אחוזה אם הקדישה:
@1064 **וחשב לו הכהן את מכסת הערכך אשר עד שנת וגומר.** הנה הטעם בזה מבואר כי אין אדם מקדיש דבר שאינו שלו ולפי שאין השדה שלו כי אם עד היובל ישוב השדה לבעליו ביובל:
@1066 **וכל ערכך יהיה בשקל הקדש וגומ'.** למדנו מזה שאין בערכין פחות משקל ואף עלפי שכבר נאמר בערכי אדם ואם מך הוא מערכך והעמיד לפני הכהן הנה אי אפשר לכהן להעריך אותו פחות משקל והוא מבואר שערכי השדה וערכי אדם הכתובין בזאת הפרשה הם קדשי בדק הבית ובזה ביארה התורה אלו הערכין ואולם אם הקדישו למזבח ראוי שיפדה אותם בשויים כי לא נודע אם אלו הערכים נוהגין גם כן בקדשי מזבח לפי שאין גופן קדוש למזבח כמו שאין גופן קדוש לבדק הבית או יהיה הענין בזה בקדשי מזבח בצד יותר חמור ולזה נלך בזה העניין להחמיר. רוצה לומר שאם היה ערכן יותר מאלו הערכין הקצובין יפדה אותם בשווייהן ואם היה שויו פחות יפדה אותן באלו הערכין הקצובין:
@1067 **אך בכור אשר יבוכר להשם מן הבהמה לא יקדיש איש אותו אם שור אם שה להשם הוא.** ראוי שתדע שאין האזהרה הזאת שלא יקדישהו להיות בכור כי זה הוא מה שצוה עליו שנאמר כל בכור אשר יולד בבקרך ובצאנך הזכר תקדיש להשם אלהיך והנה התועלת בזאת ההקדשה מבואר ואף על פי שהוא קדוש מצד עצמו הוא שזה יזכיר לאנשים קדושת זה הבכור מפני זה יותר נשמרים יהיו מחטוא בו בגזה ובעבודה ובמה שידמה להם אמנם האזהרה הזאת היא שלא יקדישוהו קדושה אחרת באופן שישנהו מקדושה לקדושה והנה לדמנו שאין זאת האזהרה אלא בבכור שגופו קדוש כמו בכור שור ושה כדי שלא ישנו אותו מקדושה לקדושה ואמנם בכור בהמה טמאה או בכור החיה לא ינהג בו זה הדין כי אינו קדוש וראוי שתדע כי קודם שיבוכר והוא קודם שילד אפשר להקדיש אותו שנאמ' אשר יבוכר לה' ולזה לא בוכר עדיין ולזה אם אמר שאם תלד מבכרת זו זכר יהיה עולה הרי זו עולה מפני שכבר זכה בו ההקדש קודם שיזכו בו הכהנים כי הכהנים אינם זוכין בו כי אם בעת הלידה כמו שזכרנו בפרשת בא אל פרעה והוא מבואר שאין בידו להקדיש אותו לשלמים אפילו קודם הלידה כי אין בידו לעשות חקם מהכהנים ולקחת אותו לעצמו כי התורה זכתה לכהנים בבכור מאת הבעלים ואולם כשהקדישה קודם הלידה להשם הנה אין הכהנים זוכים בו מההקדש ולפי שביארה התורה זה הדין בביאור שהו' מהקדשי' היותר קלים כמו שיתבאר הנה הוא מבואר מהשרשים הכוללים שזה הדין ינהג גם כן בשאר קדשי מזבח ר"ל שאסור לשנותם מקדושתם לקדוש ואף על פי שיעתיקו אותם לקדושה יותר חמורה וראוי שיתבאר מזה שהוא ראוי גם כן שלא ישנו קדשי בדק הבית מקדושה לקדוש אבל ראוי שישאר ההקדש על עניינו הראשון. והמשל שמי שהקדיש דבר לכלי מה מהמקדש אינו ראוי שישנה אותו לדבר אחר מהמקדש וראוי שתדע שיש לאדם להקדיש הזכות שיש לו בקדשים ולזה יהיה לו רשות להקדיש הבכור לבדק הבית ויהיה מקודש לבדק הבית הזכות שיש לו בו ליתן אותו לכל כהן שירצה ומי שיתן אדם בזה הזכות כדי שתהיה לו זאת הבחירה הוא יהיה לבדק הבית והבכור יהיה לאי זה כהן שירצה אף גוף הבכור אינו הקדש אם אינו שלו ואין אדם מקדיש דבר שאינו שלו ומזה המקום יתבאר שאם הקדיש קדשי בדק הבית למזבח אין הקדש חל עליהם אמנם אם הקדיש קדשי מזבח מבדק הבית מהקדשי' שהוא חייב באחריותם הנה הם קדושים כי אין בזה שנוי מקדושה לקדושה כי אי אפשר שיקרבו למה שהיא ויפלו דמיהן לבדק הבית והנה התורה לא הקפידה אלא שלא ישתנה ממה שהיה בו מתחלה מהקדושה לפי שהוא להשם וראוי שלא יזלזלו בו להסיר קדושתו ואמנם לא הזהיר שלא יוסיף בו עניין קדושה בזולת הסרת קדושה הראשונה:
@1068 **ואם בהמה הטמאה ופדה בערכך וגומ'.** רוצה לומר שאם יקדיש בהמה טמאה לבדק הבית הנה אם יפדו הבעלים מוסיפים חומש וכבר התבאר שאין החומש מעכב בפרשת ויקרא ומזה המקום נלמד שכיון שנתן את הקרן אע"פ שלא נתן את החומש יצא ההקדש לחולין ואפשר שיתבאר מזה המקום גם כן שנ' ופדה בערכך. ר"ל שכיון שנתן הערך כבר נפדה אלא שכבר יחוייב אחר זה להוסיף חומש שנאמר ויסף חמישיתו עליו:
@1068 **ואם לא יגאל ונמכר בערכך.** למדנו מזה המקום שהבעלים קודמים בזה העניין ואם לא רצו לגאלי מכר לאיש אחר והוא לא יוסיף חומש אבל יפרע הערך לבד והנה היו הבעלים קודמים לשתי סבות האחת לפי שאין מוסיפין חומש והשנית שהוא מן הראוי שתהיה להם קדימה בזה העני' מפני שזה הקנין היה להם ונתנוהו להקדש ומן היושר התוריי יתחייב שלא ישולם להם רעה תחת טובה וראוי שתדע שאם שמו זה המקדש לשה מומחים שהוא ראוי שתהיה זאת השומה על פיהם כמו שזכרנו בזאת הפרש' הנה יוסיפו הבעלי חומש על ערכם ואם לא רצו יקחוהו אחרי' בערך ההוא בזולת תוספת חומש כי כמו זה מצינו במה שערכו קצוב בתורה שהבעלים מוסיפין חומש והנכרים לוקחים אותו בערך ההוא בזולת תוספת חומש ואולם אם הכריזו הגזברי' שכל הרוצה לקח יבא ויקח ובאו הבעלים ואמרו דרך משל הרי הוא שלי בשמנה דינרין ובא אחר ואמר הרי הוא שלי בתשעה דנרים או בעשר דנרים הבעלים קודמים ונותנין העשרה דנרים לבד כי כן אמרו לתת עם תוספת חומש ואם אמר אחד הרי הוא שלי בעשרה דינרים ופרוטה ורצו הבעלים והוסיפו אפילו שוה פרוטה הרי היא שלהם ונותנין יותר על זה חומש הערך שאמרו לתת תחלה אבל אין מוסיפים חומש על עלויו של זה וזה יתבאר ממה שאומ' וזה שכבר אמ' בבמה שאחר זה ואם גאול יגאל איש ממעשרו שאינו גואלו מיד זולתו כי הוא שלו ועל הערך ששם בו יוסיף חומש וכן התבא' במה שקדם שעל הערך הקצוב מיד זולתו יוסיף חומש היה שיהיה זה קצוב מד התורה או שיעריכנו הכהן ולזה יתבאר שבשני אלו הפנים לבד יוסיפו הבעלים חומש אבל יוסיפו חומש על עליו של זה הרוצה לקנותו מיד ההקדש וראוי היה להיות כן וזה כי הבעלים יוסיפו חומש לאהבתם קניינם כמו שביארנו בפרשת ויקרא וכבר ביאו הבעלים מה שהדבר שוה לפי מחשבתם ועל מה ששוה לפי מחשבתם ראוי שיוסיף חומש לזאת הסבה ואמנם מה שיעלה אותו השני לא יתנוהו הבעלים מפני היות הדבר שוה לפי מחשבתם הסך ההוא אבל יתנוהו כדי שישאר הקנין ההוא תח ידם ולא יבא ליד זולת' ולזה די שיתנו הסך ההוא שהסכימו לתת על עלויו של שני לא שיוסיפו עליו חומש אבל יוסיפו חומש על הסך הראשון לבד כמו שזכרנו:
@1069 **אך כל חרם אשר יחרים איש להשם.** הנה זה החרם הוא מה שיקדיש איש בזה הלשון שמורה על השחתה והפסד והרצון בו שלא יגיע ממנו תועלת עוד לבעלים ולפי שביארה התורה דין קדשי אדם ובהמה ושדה אחוזה בזה וקדשי לבדק הבית או למזבח ביארה בזה המקום מין אחר מן ההקדש והוא מה שיקדיש איש לתת לכהנים לכבוד השם יתעלה כי החרמים בסתם הם לכהנים כמו שנ' כל חרם בישראל לך יהיה והנה ירדה התורה בזה בהדרגה כי בראשונה זכרה ההקדשות שהם ליי' ואחר כך זכרה ההקדשות שהם לכהני' ואחר כך זכרה ההקדשות שהם לבעלים כגון מעשר דגן ומעשר במה אבל אשר לו מאדם ובהמה ומשדה אחוזתו לא ימכר ולא יגאל הנה האדם אשר לו מאדם ובהמה ומשדה אחוזתו לא ימכר ולא יגאל הנה האדם אשר לו הוא עבדו ואמתו הכנעניים שגופם קנוי לו ואמרה התורה מכל אשר להעיר שאין ראוי לאדם שיחרים כל אשר לו ויצטרך אחר זה לבריות ולזאת הסבה אמרה מאדם ובהמה ומשדה אחוזתו להורות שאין ראוי שיחרים כי אם קצת קניינו ולזאת הסבה אמרה מאדם ובהמה לזאת הסבה בעינ' התקינו רז"ל בעניין הצדקה שהמבזבז אל יבזבז יותר מחומש ואמר לא ימכר ולא יגאל כדי שישאר לכהנים כי אין להם חלק ונחלה בתוך בני ישראל ולזה ראוי שתתוסף נחלתם בזה האופן כדי שתספיק להם עם תרבותם ולזה הקפידה התורה שתהיה גאלת עולם ללוים ויהיה הרצון באמרו ימכר שלא יקנהו מהם איש אחר ולפי שכבר היה אפשר שיביא זה לחשוב שהבעלים יוכלו לגאל אותו אמר אחריו ולא יגאל:
@1069 **כל חרם קדש קדשים הוא להשם.** לפי שאין האנשים יראים מלעכב בידם ממון שלא כדין אולי יחזיקו בזה החרם הבעלים ולא יתנוהו לכהנים ולזה צותה התורה שיהיה קדש קדשים כדי שירחיקוהו האנשים פן ימעלו בו אמנם אשר הגיעו ליד הכהנים הרי הוא כחולין לכל דבריו ועליו נאמר כל חרם בישראל לא יהיה ר"ל שישתמש בו לכל צרכו:
@1070 **כל חרם אשר יחרם מן האדם לא יפדה מות יומת.** ירצה לפי מה שאחשוב שכבר יצוו מהשם יתעלה להחרים מן האדם מדינה מה או עם מה או ידרו ישראל זה כמו שנזכר מנדר ישראל בפרשת חקת וידר ישראל נדר אם נתון תתן את העם הזה בידי והחרמתי את עריהם וכמו שצוו ישראל על ידי יהושע להחרים את יריחו וכמו שצוו ע"י שמואל להחרי' את עמלק שכבר נזכר שם שנמשך למצוה הזאת להמית כל האדם והבהמה שיש לאנשים ההם אשר חוייבו להחרים הנה לא יפדה דבר מן החרם ההוא אבל מות יומת כל מה שהחרימו מן האדם והם הב"ח אשר שם והיה זה כן כי כמו זאת המלחמה ראוי שתהיה לכלות הרעים לא לאהבת התועלת ולזה חייבה התורה שלא לחיות כל נשמה משבעה עממין ולמחות זכר עמלק:
@1071 **וכל מעשר הארץ מזרע הארץ מפרי העץ להשם הוא קדש להשם.** רצ הש' יתע' שנפריש מעשר מן הזרע והפירות אחר שהפרשנו ממנו תרומה לכהנים ומעשר ראשון ללוים וזה המעשר נקרא מעשה שני והוא נאכל לבעלים בירושלם כמו שנתבאר בפרשת ראה אנכי ושם התבאר שאפשר לבעלים לשאת אותו שנאמר וכי ירבה ממך הדרך כי לא תוכל שאתו וגו'. ועניין קדושתו הוא שאינו נאכל אלא בירושלם ואינו נאכל באנינות ובטומאה כשאר הקדשים כמו שיתבאר במה שיבא:
@1072 **ואם גאול יגאל איש ממעשרו חמישיתו יוסף עליו.** כבר זכרה התורה בזה ממה שקדם ולפי שאמרה התורה בזה המקום איש מה שלא אמרה כן בשאר הדברים שקדמו שגואלים הבעלים והוא שכבר אמר בבהמה ואם גאול יגאלנה ובבית אמרה ואם המקדיש יגאל את ביתו ובשדה אמר ואם גאול יגאל את השדה המקדיש אותו למדנו מזה שאין דין תוספת חומש נוהג בפדיון מעשה שני אלא כשהיה הגואל איש ואמנם האשה פטורה מתוספת חומש ולפי שאמרה איש ממעשרו למדנו שפדיון מעשה שני שיוסיפו בו חומש כשיהיה הפודה בעל המעשר כדרך שהיה הפדיון והמעשר שלו והנה התועלת בזה המעשר הוא התועלת אשר בשאר המעשרות ועוד יש בו תועלת להטיב לעניים כמו שהתבאר בפרשת ראה אנכי וזה שכבר ימצאו רבים שיעלה מעשרם לחשבון גדול ולפי שיחוייב להם לאכלו בירושלם הנה לפי שלא יתעכבו שם מאד יתנו ממנו לעניים לאכלו שם:
@1073 **וכל מעשר בקר וצאן כל אשר וגומ'.** מצד ענינו למדנו שזה המעשר נאכלים לבעלים ג"כ בירושלם ולמדנו שאין זה המעשר נוהג אלא בבקר ובצאן והיה זה כן כי הם ראויין לקרבן מבין שאר הבהמות ולפי שאמר כל אשר יעבור תחת שבט שהוא מורה שיעבור מעצמו. למדנו שמעמידין אמותיהם בחוץ כדי שיבאו הטלאים והעגלי' מעצמם לקולם ומונין אותם אחד אחד ומקדשין העשירי והוא מבואר שאי מעשרין אלא הטלאים משנה זו כי התורה הקפידה גם בזרעים שלא יעשרו מזרע השנה על חברתה שנאמ' עשר תעשר את כל תבואת זרעך היוצא השד' שנה שנה וכ"ש שתקפיד בזה בבהמה שמשתנה ענינה יותר בשנה שנה ומזה ג"כ יתבאר שאין מעשרין מהצאן על הבקר ולא מהבקר על הצאן ולפי שאמ' העשירי יהיה קדש לה'. למדנו שאינו נוהג במוקדשין כי הם קדש קודם עברם תחת השבט ולמדנו עוד מזה שהעשירי יחוייב שיהיה לו צד אפשרות להיות קדש אל לא יחוייב שיהיה תמים שכבר אמר אחר זה לא יבקר בין טוב לרע להורות שאף על פי שהוא בעל מום כבר יהיה מעשר ולזה לא יתכן שיהיה מעשה בהמה מי שלא היה לו שעת הכושר להיותו קדש כמו כלאים ונדמה ויתום ויוצא דופן ומחוסר זמן והטרפה גם כן אינה מעשר שנאמר כל אשר יעבור והטרפה אינה עוברת רוצה לומר שאין מדרכה להיות עוברת שהרי היא הולכת למות. וראוי שתדע שהעוברים תחת השבט שהוא ראוי שימצא שם עשירי בעת צאתם נפטרו ביד מעשר ואף על פי שלא יהיה שם עשירי בסוף המנין ומה שיעבור מהם שאין ראוי שימצא לו עשירי לא נפטר מיד מעשר ומתעשרים כשימצאו לו נולדים אחרים להשלים המנין והוא מבואר שהעשירי הוא מה שהוא עשירי לפי מאמר המונה והוא אשר אפשר בו הטעות כמו הט' והי"א והנה אלו הם קדשים מצד המאמר אבל אינם מעשר בהמה כי אינם עשירי על דרך האמת וראוי שתדע שמה שהוא פק אם הוא חייב במעשר אם לא הוא פטור מן המעשר כי אולי הוא פטור מן המעשר ואין אני קורא בו העשירי יהיה קדש ולזה יהיה לפי מה שאחשוב הלקוח והנתן במתנה פטור מן המעשר שמא נתעשר מיד בעליו אלא אם היה לקוח או נתן והוא עדיין מחוסר זמן כי אז ידוע שלא נתעשרו עדיין וכבר יתבא' זה באופן אחר והוא שהתורה לא חייבה במעשר אלא מה שיעבור תחת השבט שנאמר כל אשר יעבור תחת השבט העשירי יהיה קדש ולזה יתבאר שכל מה שמכר או נתן או אכל קודם שיעבור תחת השבט פטור מן המעשר והנה יעבור תחת השבט משעת כניסת לדיר להתעשר והנה הנתינה והלקיחה לא יפטרו מהמעברה תחת השבט אלא כשהיה ראוי לזה ביד הבעלים כמו מחוסר זמן לא נפטר מן המעשר בלקיחה ומתנה כי אמרו כל אשר יעבור תחת השבט ייחד בו אשר עבר תחת השבט מן הראוים לעבור וזה מבואר מצד השרשים הוללים ובכלל הנה התורה ביארה אסור טבל בזרעים והם יותר ראוים בזה הדין מהבהמה כי יש בהם חיוב תרומה ומעשר ותרומת מעשר ולזה הוא מבואר שאין אסור טבל בבהמה ולזה לא יאסר לו לאכל ממנה ולמכור ולתת קודם שנתעשר. והנה התור' ביאה במחוסר זמן שהזמן מונעו מלהקריב ולא זכר זולת זה כי מיום השמיני ירצה לקרבן אשה אף על פי שלא נתעשר וזה מה שיורה שהלקיחה והנתינה פטורים ממעשר בהמה:
@1074 **לא יבקר בין טוב לרע וגומ'.** רוצה לומר שאפילו אם היה העשירי בעל מום או כחוש אין ראוי להמתין שיעבור תמים או שמן ויקדשנו אלא העשירי בעצמו יהיה קדש היה בעל מום או תמים כחוש או שמן והנה הזהירה התורה שלא לשנות מעשר בהמה מה שלא הזהיר זה במעשר שני לפי שיש במעשר בהמה דבר הוא קדוש למזבח ולזה היתה קדושתו יותר חמורה ולזאת הסבה בעיני צוה שלא ימירנו שאם ימירנו יהיה קודש הוא ותמורתו כמו העניין בשאר קדשי מזבח ואמר בו לזאת הסבה גם כן שלא יגאל לבעלים ולזה הוא מבואר שאינו נמכר לאחרי' כי אם היה אפשר שימכר לאחרים היה ראוי שיהיו הבעלים קודמים בזה והוא מבואר שזה האסור הוא כשהיה תמים אמנם היה בעל מום הרי הוא נאכל במומו והרי הוא חולין לכל דבר כמו העניין בבכור בעל מום כמו שיתבאר בפרשת ראה אנכי. ובכאן נשלם הביאור בזאת הפרשה:
@1075 **וידבר יי אל משה במדבר סיני לאמר.** דע כי כבר נמנו ישראל קודם זה והיה מספרם זה המספר בעינו שהיה בה המספר הנזכר בזה המקום וזה כי בשנה השנית באחד לחדש הוקם המשכן כמו שנזכר בפרשת פקודי וקודם זה נמנו ישראל והביאו בקע לגלגולת כמו שנזכר שם לעשות האדנים וווי העמודים ושאר הדברים שנזכרים והנה היו או ו' מאות אל וג' אלפים ות"ק וחמשים וכן היה מספרם בזה המקום כמו שתמצא וזה ממה שיראה ממנו כי האנשי' הקרובים לעשרים שנה היו שוי המספר לאנשים הקרובים לס' שנה עד שהיה מספר מה שנוסף בהם מבני עשרי' כמספר מה שחסר מהם מבני ששים שנה וזה מורה על עוצם השגחה השם יתעלה בהם להחיותם הזמן האפשרי וזה שאתה תמצא לפי הנהוג כי האנשים הקרובים לעשרים שנה הם רבי המספר מאד מאנשים הקרובים לששים שנה כי מה שיגיעו מזה המספר הם מעטי המספר. ואחשוב כי במספר הראשון לא נמנו הלוים ולא נהנו בקע לגלגלת למלאכת המשכן כי הוא רחוק שיסכים במקרה המספר הראשון עם הלויים למספר השני בזולת הלויים ואולם כשהיה הראשון בזולת הלויים גם כן היה אפשר לפי מה שזכרנו וכבר יורה שישראל היו מושגחים בזה האופן גם בהיותם במצרים מהרבוי העצום שנתרבו שם במעט מהזמן. שאו את ראש כל עדת בני ישראל וגומ'. אחשוב כי הרצון באמרו במספר שמות שהם מנו השמות לכל זכר ולא מנו האנשים בעצמם כדי שלא יהיה בהם נגף בפקוד אותם כמו שהתבאר מדברינו בפרשת כי תשא וזה אמנם היה באמצעות נשיאי השבטים שלקחו שמות כל שבט לגלגלותם ומנו כל השמות הנכתבים כדי שלא ימנו האנשים בעצמם ונמנו כל יוצא צבא כי הכונה היתה שילחמו עם שבע עממין ויכבשו הארץ ורצה השם ית' שיפקוד אותם כדי שיתברר להם הפלגת השגחת השם ית' כשיפקדו אחר המלחמה ולא יפקד מהם איש כמו שנמצא זה העניין במלחמת מדין אלא שגרם החטא ונתאחרו במדבר עד תום ארבעים שנה ונכלל תועלת שני והוא שכבר נתיחסו כלם על משפחותם לבית אבותם על ידי משה ואהרן שהיו נביאים.

@1 **יאזרני אל גבור ונורא**:
@1 **בכתבי ספר ויקרא**:
@1 **ויקרא אל משה וגו' עד ונפש כי תקריב קרבן מנחה וגו'.**
@1 **וראוי** שלא יעלם ממנו למה היה זכר הקרבנות בזאת הפרשה בזה הסדור אשר בא בו כי ראוי שיהיה זה לסבה והנה נתן הסבה בזה לפי מה שאפשר לנו ונאמר כי מפני שהיו קצת הקרבנות מכוונים בעצמם כמו קרבן העולה וקצתם על הכונה השנית והם הקרבנות הבאים לכפרה כמו שביארנו במה שקדם הנה הקדימה התורה לזכור הקרבנות המכונים בעצמם. ואופן עשייתם רוצה לומר העולה עם שהיא עם זה מכפרת על העונות הקלי' ולמדנו שהיא מכפרת מאמרו ונרצה לו לכפר עליו ולא נוכל לומר שתכפר על החטאים העצומים שהרי מצאנו שכבר יביאו עליהם חטאות קבועה או קרבן עולה ויורד או אשם לפי מה שנתבאר בזאת הפרשה והנה זכר מיני העולה על סדרם בגדול החל ובקטן כלה וזה שהוא הקדים תחלה הבקר לפי שהוא היותר חשוב ואחר כך הכבשים ואח"כ העזים ואחר כך התורים ואחר כך בני היונה ולפי שזכר העולה שבאה בנדר ונדבה השלימה המאמר בקרבנות הבאים בנדר ונדבה וזכר תחלה מה שהיה מהם קדש קדשים והיא מנחת הסלת והיא עם זה למטה מקרבן העוף כי הב"ח יותר נכבד מהצמח וכל שכן שהוא יותר נכבד מפרי הצמח וכן מצינו גם כן בקרבן עולה ויורד שבא זכר מנחת הסולת בזולת אפיה כי הסולת הוא הקודם לכל מה שנעשה ממנו אחר כך הקדים מאפה תנור לכל מיני האפיה כי הוא היותר נהוג ויותר שלם ולזאת הסבה בעינה הקדי' הנאפה על המחבת לנאפה על מרחשת כי הנאפה על המחבת יותר מתיחס למאפה תנור מהנאפת על המרחשת וזה מבואר ממה שביארנו בזה ואחר שזכר מנחת החיטים זכר מנחת השעורים כי החטים יותר נכבדים מהשעורים ואחר שהשלים זכר קדשי הקדשים הבאים בנדר ונדבה זכר קדשים קלים הבאים בדר ונדבה והם השלמים וזכר מיניהם על הסדר והראוי בגדול החל ובקטן כלה רוצה לומר שהוא זכר תחלה הבקר ואחר כך הצאן ואחר כך העז ואחר השלים זכר הקרבנות הבאים בנדר ונדבה שב להשלים הקרבנות הבאים לכפרה והחל מהיותר קשה והוא הקרבן הבא על שגגת קצת העבירו' שחייבין על זדונם כרת והוא קרבן חטאת קבועה והקדים לזכור תחלה שגגת הוראה עם זדון המעשה כמו הענין בפר כהן משיח ופר העלם דבר של צבור לפי שזה החטא הוא יותר עצום משגגת המעשה לבד וזה יתבאר מפנים מהם שהחטא בשגגת ההוראה הוא מביא אל חטאים רבים כי ההוראה היא בסבת המעשים מה שאין כן בשגגת המעשה ומהם כי ההוראה סבה שיחטא האדם ההוא וזולתו ממי שיתנהג על פי הוראתו ואמנם שגגת המעשה יחטא בה החוטא ההוא לא זולתו ואם לא היה זה במקרה ומהם כי החוטאים בשגגת ההוראה הם הנכבדים שבאנשים ולזה יהיה החטא יותר עצום כי הוא מבואר שהחטא האחד יהיה יותר עצום כל מה שהיה החוטא יותר נכבד ומזה המקום יתבאר מעניין סדור מה שבא בזאת הפרשה שחטא כהן משוח הוא בשגגת ההוראה עם זדון המעשה כמו העניין בפר העלם דבר של צבור והנה הקדים הכהן המשיח בהיותו יותר נכבד ואח"כ זכר שגגת המעשה וזכר תחלה קרבן הנשיא למעלתו ורוממותו על שאר האנשים וזכר אחר כך העברות שיביאו עליו חטאת בלתי קבועה והם גם כן מהחטאים העצומים והם שבועת העדות כשיעברו עליה בזדון או בשגגה והנה העברה על השבועה מהעבירות הגדולות לפי שכל עבירות שבתורה כתוב בהם ונקה וכאן לא ינקה. וכבר ביארנו הסבה בפשרת וישמע יתרו. ומנה עוד עמה שגגת טמאה מקדש וקדשיו שחייבים על זדונו כרת כמו שיתבאר ושגגת שבועת בטוי והנה הבדילה התורה טמאת מקדש וקדשיו מבין שאר מצות לא תעשה שחייבין על זדונם כרת לפי שרוב עניין הטומאות הוא מכוון על הכונה השנית ולקושי החזק אשר יהיה להשמר מן הטמאות כמו שיתבאר בענינם ולזה הקלה התורה כאלו לפי מה שאחשוב רוצה לומר שיביאו עליהם חטאת בלתי קבועה וזה אמנם יהיה כשהיתה שם ידיעה בתחלה וידיעה בסוף ונעלם בנתים ואמנם כשלא היה בזה התואר סודרו שם קרבנות אחרי' לכפר עליהם כמו שיתבאר בפרשת אחרי מות ואחר כך זכר קרבן הנהנה מקדשי השם בשגגה כי הוא מהעבירות החמורות ואם הוא למטה מהקודמת ואחר כך זכר קרבן מי שנסתפק לו אם חטא בשגגת המעשה בעברות שחייבים על שגגתן חטאת קבועה וזה בלתי ספק למטה מהעברות הקודמות ואחר כך זכר קרבן מי שכפר ממון לחבירו ונשבע על שקר במזיד. וראוי שנעין מה הסבה שבשבועת בטוי לא יתכפר בקרבן כי אם על שגגתה ובשבועת העדות ובשבועת הפקדון יתכפר בקרבן על זדונו ולמה יביאו בשבועת העדות. קרבן על שגגתו ובשבועת פקדון פטר על שגגתה ונאמר שהוא מבואר שאין ההבדל באלו העברות מצד השבועת כי הם מסכימות בזה ולזה הוא מבואר שההבדל הוא ביניהם מפני הנושא אשר בו השבועה והנה יראה ששבועת בטוי תהיה על הרוב במה שיזדרז האדם לעבוד השם יתעלה ולהתרחק ממה שיבלבל עבודתו וזה נקרא בתורה שבועת אסר או שבועת בטוי ולזה תמצא בפרט אחר שזכרה התורה מזה בנדר אסר שהוא בעבור זאת הכונה והוא הנזירות כי היין סבה חזקה כשיתמידו בו להתרחק האדם מעבודת השם יתע' ואמנם שבועת העדו' ושבועת הפקדון הם בממון ולפי שעבודת השם יתעלה יותר נכבדת מאסיפת הקניינים היה עניין שבועת הבטוי יותר חמור משבועת העדות ושבועת הפקדון ולזה לא יתכפר על זדונה בקרבן כמו הענין כאו אבל יתחייב על זדונה מלקות שהוא עונש בגוף החוטא לא בממונו והנה מרי מי שיעבור על שבועת העדות יותר עצום ממרי מי שיעבור על שבועת הפקדון כי העובר על שבועת העדות אל יביאהו לזה הנאת ממון רוצה לומר שאינו נהנה ממון בהשבעו על שקר וכבשו עדותו. ואמנם העובר על שבועת הפקדון הנה יביאהו לזה הנאת ממון כדי שישאר הממון ההוא בידו ולזה הוא מבואר שמרי העובר על שבועת העדות יותר עצום ולזה יתחייב על השגגה בו קרבן מה שאין כן בשגגת שבועת הפקדון ולזה גם כן יתחייב על שבועת העדות חטאת בלתי קבועה ועל שבועת הפקדון לא יתחייב כי אם אשם כי החטאת באה על עבירה יורת חמורה מהאשם וזה יתבאר מהעבריות שחייבין על שגגתן חטאת שכבר יתחייבו על ספק שגגתן אשם וזה ממה שיורה שהחטאת בא על עביר היותר חמורה מהאשם וזה יתבאר עוד כשניתן הסבה למה נעשים הקרבנות באופן אשר צותה התורה והנה התועלות אשר במה שנזכר בזאת הפרשה הם רבים:
@1 **השרש** השני הוא שאין עולת בהמה באה אלא מן הבקר או מן הצאן ר"ל בצאן מן הכבשים או מן העזים ויהיה עם זה זכר ולא נקבה ולא טומטום ולא אנדרוגינוס כי אין אחד מהם זכר וראוי כמו שנזכר בספרא ויהיה עם זה תמים ולא בעל מום וזה כולל כל הקרבנות מהבהמה כמו שיתבאר בפרשת אמור ומזה יתבאר שאין מקריבין זקן כי אינו צמים בטבעו והבקר יהיה זקן משעברו עליו ז' שנים וזה מבואר מן החוש עם ארך החקירה ר"ל שאחר זה הזמן יתחילו להחלש פעולותיהם הטבעיות. כבר נתבאר זה בכ"א מפרה. ובזה תמצא שהקפידה התורה במיני העוף שיקריבו מהם קרבן לה' והם התורים ובני היונה שהיו קרבים כעת אשר הם יותר נבחרים והם הגדולים בתורים וקטנים בבני יונה אף על פי שלא הקפידה בהם שיהיו תמימים כמו שזכר בספרא והנה התחלת הצהוב שבזה פסול כי הוא ממוצע בין הגדולים ובין הקטנים ואחר שיצהיבו התורים הם כשרי' והיונים נקרא בני יונה כל זמן שיתלוש נוצה מהכנף ומלא המקום עקרה וזהו כולל לכל קרבנות העוף כבר נזכר זה השרש בראשון מחולין:
@1 **השרש** השלישי הוא שצריך שתהיה כל בהמה בעזרה קודם שישחטנה שנאמר יקריבנו אל פתח אהל מועד וזה גם כן שרש כולל לכל הקרבנות כבר נזכר זה בפרק שני מזבחים ומזה המקו' יתבאר גם כן שהבעלי' מטפלין בהבאת הקרבן עד העזרה כמו שנזכר בספרי:
@1 **השרש** הרביעי הוא שבית דין מכריחין הבעלים להביא הקרבן שנתחייבו בו כנדר או בנדבה וכופין אותו עד שיאמר רוצה אני שנאמר יקריבו אותו וזה יהיה ע"י ב"ד כי להם לבדם כח להכריחו כבר נתבאר זה השרש בא' מערכין:
@1 **השרש** החמישי הוא שצריך שיהיו פני הקרבן לצד מערב ששם קדש הקדשים שנאמר לפני השם וזה היה להעיד שהקרבן הוא לה' כבר נזכר זה בראשון מיומא ולזאת הסבה גם כן חוייב שיהיו פני השוחט לצד המערב שנאמ' ושחט את בן הבקר לפני השם כבר נזכר זה השרש בחמישי מזבחים וברביעי מיומא:
@1 **השרש** השישי הוא ששחיטת קדשים כשרה בזרים שנ' ושחט את בן הבקר לפני יי' ולא התנה בשוחט שיהיה כהן כמו שהתנה בהקרבת הדם ועריכת הנתחים והקטרתם כבר נתבאר זה בחמישי מזבחים ולזאת הסבה גם כן יהיה התפשט והנתוח כשרים בזר כמו שכבר נתבאר וראוי שתדע שהפעולות הנזכרות בקדשים צריך שתהיינה שלמות רוצה לומר שיהא השוחט מכוין לשחוט ולזה הוא מבואר שאם שחט כמתעסק בזולת כוונה לשחוט הקרבן פסול ולזאת הסבה יהיה הקטן פסול לשחיטת הקדשים אעפ"י שהגדול עומד על גביו כי אין לקטן כוונה ראוי מה שאין בשחיטת החולין והוא מבוא' מלשון התורה שצרך שיהיה כל הנשחט בעזרה כשנשחט שכבר קדם אמרו יקריבנו אל פתח אהל מועד ואמר גם כן ושחט אותו על ירך המזבח צפונה לפי' אם לא היה כל הנשחט בעזרה הקרבן פסול כבר נתב' זה בב' מחולין. וראוי שתדע שהשחיטה והזביחה והכונה בהם לפי הוראת הגדר מבואר שתהיה בדבר בלתי מחובר לקרקע על יד איש או אשה בהולכה ובהובאה לא בדרסה ולא בהכאה ובנקיבה ולא בדבר פגום כי זה יקרא נחור לא שחיטה. וזאת החתיכה ראוי שתהיה באופן שתמות הבהמה אחר זה שיעור מועט וזה אמנם יהיה בחתיכת סמני' שהם הקנה והוושט או רוב כל אחד מהם ואולם העוף ימות בחתיכת סמן אחד או רובו לפי שהוא יותר חלוש החיים מהב"ח המהלך כמו שנזכר בפרשת בראשית. ואולם הדגים שהם יותר חלושי החיים לא יצטרכו לשחיטה כי כשיצאו מהמים ימותו אחר זמן מועט ולזה די להם האסיפה לבד שנאמר הצאן ובקר ישחט להם ומצא להם ואם את כל דגי הים יאסף להם ומצא להם והוא מבואר שלא יקרא זביחה או שחיטה החתיכה בצואר הבהמה מתה או שהיא קרובה למות וזה שרש כולל לקדשים ולחולין אין הבדל ביניהם בזה אלא ששחיטת החולין יחוייב שתהיה חוץ העזרה כבר נתבאר זה השרש כלו בראשון ובשני מחולין:
@1 **השרש** השביעי הוא שצריך שתהיה השחיטה בקרקע העזרה בצפון על ירך המזבח צפונה ואם שחט בגג של היכל פסול שאין זה מבוא אהל מועד ואין חוששין למקום השוחט לפי שהשחיטה כשרה כזר כבר נתבאר זה השרש בשני מזבחים:
@1 **השרש** השמיני הוא שהבעלים סומכים בשתי ידים על ראש הקרבן לא על הצואר ולא על הצדדים ולא יהא דבר חוצץ בינו ובין הבהמה ואפילו היו רבים שותין בקרבן אחד כל אחד סומך ידו עליו ובקרבן צבור אין בו סמיכה וזאת הסמיכה היא להתודות החטאים שהקרבן מכפר עליהם כמו שביארנו וזה כולל בכל הקרבנות שאינם של צבור והוא מבוא' במה שאין ספק בו שצריך שיהיו פני הסומך לפאת המערב ששם קדש הקדשים וכבר דקדקה התורה גם בבהמה בביאתה לעזרה ובשחיטתה. וכבר נזכר שהסמיכה היא לכפרה על האופן שזכרנו יחוייב שיהיה בעל הקרבן סומך לא בנו ולא שלוחו לא עבדו ולא אשתו ויתבאר שאין העבד סומך ולא הנכרי ולפי שכבר אמר דבר אל בני ישראל. והוא אינו מבני ישראל. ויתבאר גם כן שאין האשה סומכת לזאת הסבה ולא נלמד זה הדין מן האיש לפי שאיש יותר ראוי בזה הדין מן האשה להיותה חסרת הדעת ביחס אל האיש ויתבאר שאין הסומא סומך בו כי אין לו מעצמו הרגש ובחינה לסמוך ידו על ראש קרבנו ויתבאר שאין חרש ושוטה סומכין כי אינם בני דעת כבר נתבאר זה בעשר' ממנחות. וראוי שתדע שאין הסמיכה מעכבת הכפרה אף על פי שכבר אמ' על הסמיכה ונרצה לו לכפר עליו שהרי ביאר בפרש' אחרי מות שהדם הנתן על המזבח נתן לכפר על נפשותיכם ואולם היתה הסמיכה על צד היותר טוב לתת רושם בנפש שכבר הוסרו העונות ההם ממנו והושמו על ראש הב"ח ההוא כבר נתבא' זה השרש בראשון מזבחים ומיומא:
@1 **השרש** התשיעי הוא שקבלת הדם והולכתו לא יהיה אלא בכהן שנאמר והקריבו בני אהרן אלא כשהם לפנים למדנו שצריך המקבל את הדם או המולק ואתו שיהיה כלו בפני' ויהיה לבוש בגדי כהונה ולפי שהשחיטה היא לצפון הנה יחוייב שתהיה הקבלה בצפון ולפי שזה הענין הוא שרות הנה יחוייב שתהיה בכלי שרת כי בהם ישרתו בקדש כמו שנזכר במה שקדם והנה הקבלה יחוייב שתהיה בימין כמו שהתבאר השרשים הכוללים ויחוייב גם כן שתהיה ההולכה ברגל ולא בזריקה כי זה הוא הנהוג ממנה ואם לא יהיה כל זה בזה האופן שזכרנו שהוא הנהוג מאלו הפעלות ובו תהיינה יותר שלמות הנה יהיה הזבח פסול כבר נתבאר זה השרש בא' ובה' מזבחים:
@1 **השרש** העשירי הוא שאפילו לא קבל הכהן מן הדם אלא מקצתו מצואר בהמת הזבח כשר והוא שיהיה דם הנפש לא דם התמצית ולא דם העור שנאמ' והקריבו בני אהרן הכהנים את הדם וגו' כבר נזכר זה השרש בא' ובג' מזבחים ובד' מיומא ולפי שכבר הגבילה התורה מקום מוגבל לאלו הפעלות והוא המקדש ודקדקה גם בחיים שתהיה הבהמה שם קודם שתשחט ושיהיו כל מעשיה שם שאם יצא דבר ממחיצתן אחר שנשחט' לחוץ ר"ל חוץ למחיצתו נפסל ביוצ' היה דם או חלבי' או בשר לפיכך אם יצא הדם כולו לחוץ קוד' זריקה נפסל הזבח כי הדם מתיר חלק המזבח למזבח כבר נזכר זה השש בב' מזבחי':
@1 **השרש** האחד עשר הוא שצריך שתהיה הבהמה שלמה בשעת קבלת הדם שנ' בפרשת אתה תצוה ולקח מדם הפר שיהיה שלם בשעת קבלה ובזאת הפרשה אמר ולקח הכהן המשיח מדם הפר ואולם אם היתה חסרה אחר קבלת הדם לא נפסל הזבח אם נשאר כזית לאכול במזבח במה שכלו למזבח ובמה שאינו כלו למזבח יחוייב שישאר ג"כ כזית לאוכלי' מהזבח ההוא ואפשר שיזרוק הדם להתיר לק המזבח למזבח ויותר אחר זה חלק הכהנים לכהנים וחלק הבעלים לבעלי' כבר נתבאר זה השרש בי"ג מזבחים:
@1 **השרש** השנים עשר הוא שזריקת דם העולה היה סביב בחלק התחתון מהמזבח החיצון ונותן שם שני זריקות שהן ארבע לשתי הזאות המקובלות והוא הדין לשלמי' שנ' בהם סביב לזריקתן כבר נזכר זה השרש בה' מזבחים. וראוי שתדע שכל הדמים הנתנים על המזבח החיצון אם נתן הכהן מתנה אחת לבד תתיר ואפילו בשפיכה שנא' ודם זבחיך ישפך וגו' מגיד ששפיכת הדם על המזבח הוא העקר ואמר ואני נתתיו לכם על המזבח לכפר על נפשותיכם מגיד שנתן על המזבח לכפר ואולם הדמין הנתנים על המזבח הפנימי אם חסר בו מתנה אחת לא כפר שהרי הכתוב הקפיד במנינם שנא' ז' פעמים כבר נזכר זה ברביעי מזבחים ואם שנה מקום המתנה אפילו במזבח החצון נפסל בשר הזבח כי התורה דקדקה בתאר הזריק שתהיה בקצתם מהקרבנות למטה ומקצתם למעלה סביב ודקדקה בדם הנפשך שיהיה נפשך ליסוד מזבח העולה ואע"פ שנתכפרו הבעלים כין שהגיע הדם למזבח כבר נתבאר זה השרש בשלישי מזבחים:
@1 **השרש** השלשה עשר הוא שהעולה טעונה הפשט ונתוח לנתחיה הראשונים לא שינתחוהו לנתחים וזה ההפשט והנתוח כשר בזר כי לא הקפידה התורה שיעשה ע"י כהן כבר נתבאר זה:
@1 **השרש** הי"ד הוא שנתינה על המזבח ועריכת העצי' עליו הוא בכהן לא בזר שנ' ונתנו בני אהרן הכהן אש על המזבח והנה יחוייב לעולת תמיד שיערכו שם ב' גזירי עצים קודם שיערכו נתחי העולה על האש כדי שתהא עריכת העולה על העצי' כי בזה הערה גדולה להגעת הנבואה אשר היתה כונת התורה בזה כמו שנבאר כבר נתבאר זה בשני מיומא לפי שלא ידוקדק בזאת ההערה כי אם בעולת התמיד כי היא לבדה היתה מכוונת בהערת הנבואה הנה לא ידוקדק בדברים שהיא בעולה התמיד כאלו תאמר חיות עריכת הנתחים ע"י בספר מוגבל מהכהני' באופן שתשלם בזה מה שכונה התורה מן ההערה בזה הקרבן כאלו תאמר שהצאן מוליכין אותן למזבח י"ח כהנים כבר נתבאר זה השרש ברביעי מתמיד:
@1 **השרש** הט"ו הוא שהולכת הנתחי' למזבח היה לפי הראוי מצד גודל הנתחים וקטנם וזה שהנתחי' הגדולים שהיה דרכם שישאום ג' כהנים או שנים ולזה אמר בשור וערכו בני אהרן את הנתחים. והנתחים הקטנים שהיו דרכם שישא מהם הכהן שני' בימינו ואחד בשמאלו נושא כהן שני' ולזה אמ' בצאן וערך הכהן אותם ואלו הנתחים היו עשרה באופן שהיה נוהג לנתח הב"ח לנתחיו הראשוני' שהיה הראש נתח אחד ואע"פ שבו אברים רכים והנה הריאה והלב והכבד היו החוברים עם הנתחים הנלוים להם כי אין הכונה שיהיה שם אבר נפרד. אבל יהיה כל נתח מורכב מהאברים רבים כדי שיכיר התועלת אשר בהרכבת האברים אשר בתנה האחד על התועלות אשר באבר אבר והנה היה החזה נתח אחד וחגיו נתח אחר והעקץ נתח אחר ועמו האליה ואצבע הכבד ושתי הכליות ומסיר הכרעים וקרבו והיה רוחץ אותם במים לא בשאר משקים באופן שיהיה מנקה אותם מהלכלוך והיה היד עם הכתף נתח אחד והשנית לה נתח אחר והרגל הימנים ושתי בצים שעמה נתח אחד והשמאלית נתח אחד והנה היו שני הבצי' יחד בנתח אחד כי הם היו מכווני' יחד לפעל אחד ולזה גם כן היו ברגל הימיני הפעל המסודר מן הימיני הוא היותר שלם והיו שתי הדפנות ב' נתחים נמצאו הנתחים עשרה מלבד הקרב והכרעים כבר נתבאר זה השרש ברביעי מתמיד ובשני מיומא:
@1 **השרש** הי"ו הוא שכשעורכין הנתחים על המזבח זורקי אותם שם תחלה שנ' ועשית עולתיך הבשר והדם כשם שהדם בזריקה ואח"כ עורך אום על האש כבר נתבא' זה:
@1 **השרש** הי"ז הוא שהשער והצמח והעצמו' והגידי' והקרני' הטלפי' בזמן שאינם מחוברי' אינו חייב להקטירם שנ' ועשית עולותיך הבשר והדם כבר נתבאר זה מט' מזבחים ולזאת הסבה היו מסירין גיד הנשה כי אין דרכו שיהיה מחובר לבשר כבר נזכר זה השרש בז' מחולין:
@1 **השרש** הי"ח הוא שהמליק' היא ממול העורף לא מן הצדדי' והיא לפי הוראת הגדר בצפורן לא בסכין וקוצץ ויורד אם בהולכ' והובא' ואם בדריסה ואם נעקרו הסמנין אינו חושש וחותך השדרה ומפרקת בלא רוב בשר שעמה כדי שלא תהיה מתה קודם מליקה וחותך שני סימנין אם היה העוף עולה כי יחוייב בעולת העוף שיבדיל הראש מהגוף אולם בחטאת העוף לא יצטרך רק בדין עוף והוא סימן אחד או רוב ולפי שיחוייב בחטא' העוף שלא יבדיל הראש מהגוף כמו שיתבאר בראשון מחולין וב' מזבחי':
@1 **השרש** הי"ט הוא שהמליקה היתה במקום שממנו יוכל להקטיר שנאמ' ומלק את ראשו והקטיר וגו' ולכך היתה בדרום כי שם היה הכבש אשר בו יעלו למזבח ובזאת המליקה היה מבדיל הראש מגוף העוף ומלק את ראשו ממול ערפו לא יבדיל ואם היתה כונת התור' שלא יבדיל בעוף העוף שהוא ראוי יותר להבדיל כי העולה היתה מנותחת לנתי' ולזה הוא מבואר כי בעולת העוף חייב להבדיל ולזה אמר לא יבדיל להורות שלא יצטרך בעוף אלו הנתחים ואף על פי שהוא עולה ולזה תמצא באברהם שלא בתר העוף במראה בין הבתרים ואולם אם הבדיל כשישסע אותו בכנפיו כשר כי אמרו לא יבדיל במה שמצד עצמותו יראה שהו' מחוייב להבדיל שול החיוב והכונה בו שאינו מחוייב שיבדיל הנה נתבאר זה מזבחים:
@1 **השרש** הכ' הוא מחוייב שימצה דמו על קיר המזבח למעלה מחוט הסקרא רוצה לומר בחלק העליון אחר שסלקו מן הראוי שימצא דם הגוף ודם הראש שנא' ונמצה דמו ולזה הוא מכו' שאם נמצה דם הגוף לבד כשר שאני קורא בו דמו וזה מבואר בנפשו כבר נתבאר זה השרש בזבחים:
@1 **השרש** הכ"א הוא שהוא ראוי שיסירו מוראת העוף בנוצתה והוא הדין לבני מעיים כי העניין אחר בעינו ומשליך אותו לצד מזרח להפך צד הקדשים למאוס זה הדבר ולכלוכו והוא מבואר שאם לא הסיר המראה על זה האופן כשר מאחר שנמצה דמו כראוי כי התורה לא דקדקה בזה אם לא על צד היותר כשר וטוב וזה מבואר במעט עיון כבר התבאר זה כו' מזבחים:
@1 **השרש** הכ"ב הוא שהעוף אינו זכר או נקבה פסול לקרבן כי הנהוג בב"ח הוא שיהיו זכרים או נקבות. ועוד שהתורה דקדקה בקרב שיהיה זכר או נקבה ולזה אם היה העוף טומטום או אנדרוגינס הוא פסול לקרבן ואף על פי שלא ידקדק בו שיהיה תמים מזולת מום ואם כן היה חסר אבר מן האברים הנראים כמו שיבש גופו או נמת עינו וזה שרש כולל לכל קרבן העוף וכבר נתבאר זה בספרא:
@1 **השרש** הכ"ג הוא שצריך שיהיה חטא מה בזאת השגגה ואם יתחייב השוגג כה קרבן חטאת שנאמ' נפש כי תחטא בשגגה ולזה יהיה פטור מקרבן מי שיהיה עושה מצוה ונמשך מעשיתה עברה מן אלו העברות כמו שבא על יבמתו והיא נדה או שהיה לו חטא מה לפי כונתו ונזדמן לו שהיה במעשה ההוא מצוה כגון שפירש מצודה להעלות דגים מן הים והעלה תנוק פטור אף על פי שעלו דגים עמו לפי שאין בזה המעשה מצד עצמותו חטא וכבר יתבאר זה השרש בר יעי מכריתות ובט' משבת:
@1 **השרש** הכ"ד הוא שאם לא עשה מזאת העברה בשגגה כי אם קצתה לא יתחייב קרבן חטאת שנאמר בעשותה כולה. ולא מקצתה כבר נתבאר זה כי"א משבת:
@1 **השרש** הכ"ה הו' שאם בזה הפעל עברה ולא ידע שחייבין עליה כרת הנה זאת שגגה ויביא קרבן כשיודע לו שחטא כי התורה הבדילה העבירו' שחייבין על זדונן כרת מבין שאר אלו העברות לעצם העש הנמשך מהם כי זה ממה שחייב שידקדק האדם בעניניו די שלא יחטא בהם ואולם כשלא ידע שהוא מאלו העברות החמורות הנה היה סבה שלא דקדק כראוי בענינה והרי זה שגגה שאלו היה יודע עצם העונש הנמשך היה נשמר מעשייתה בבד נתבאר זה בז' משבת וכ"ט שתהיה השגגה אם לא יודע כלל שזה הענין אסור כאו תאמר שחלה אסור לאכלו ואח"כ יודע לו שחייבין על זדונן כרת והנה יהיה זה הענין נחשב לו לחטא לפי שלא השתדל ללמוד מצות התורה כדי שידע לשמור עצמו מהדברים האסורים כבר נתבאר זה בשלישי מכריתות:
@1 **השרש** הכ"ו הוא שצריך שידע עצמו של חטא שחטא בו שנ' ונודעה החטאת אשר חטאו עליה ואז יתחייב קרבן ואף על פי שלא ידע הנושא שחטא בו כאלו תאמר שהיו שתי אחיותיו בבית ואינו יודע על אי זה מהם בא כבר נתבאר זה ברביעי מכריתות:
@1 **השרש** הכ"ז הוא שעל חטא אחד לא יתחייב כי אם חטאת אחת אע"פ שיחטא בו פעמים רבות בהעלם אחת ואפי' אם קרה שיהיה החטא האחת משמות רבי' כמו שאכל חלב והוא נותר הנה יהיה מניין החטאו' כמניין השמות ההם אם היו האסורים כלם באים באחד כי אז הם תלים יחד או היה אסור מוסיף כמו שבא על אשת איש והיא נדה או אם היה אסור כולל ואולם בעריות לפי שהתאוה תשתנה לפי המקבל הנה יתחייב על שגגה בו פעמים רבות כמספר הגופים הנחלקים היו נשים או בהמות כבר נתבאר זה בשלישי וחמשי מכריתות:
@1 **השרש** הכ"ח הוא שעל שגגה אחת מביא חטא' על השגגו' הרבה מביא חטאת כמספר השגגות שהרי בכל המקומות אמר חטאתו אשר חטא ולזה יקרה שאם חטא מה על חטאת פעולות שונות תהיה השגגה על הדבר המשותף לכולם ולא יתחייב כי אם קרבן אחת ואם היתה השגגה על כל אחת מהפעולות ההם יתחייב חטאות כמספר השגגות והמשל שאם לא ידע אדם מה שזו ע"ז והשתחוה וזבח ונסך לפניה וידע שאלו העבודות אסור לעשות עבוד' זרה והנה אין בכאן כי אם שגגה אחת ואולם אם הזיד בע"ז ושגג בעבודות אלו חייב על כל אחת ואחת כבר נתבאר בראשון מכריתות:
@1 **השרש** הכ"ט הוא שמה שאפשר שיהיה יחד בעת אחת אע"פ שהוא בהעלם אחד ומשם אחד הוא שגגות רבות ולזה יתבאר שאם בא על הנדה וטבלה וחזר ובא עליה כשהיא נדה שנתחייב על כל אחת ואחת שהרי זמן הנדו' האחד הוא זולת זמן הנדות השנית ובזה תהיינה שגגות נחלקו' לחטאת כבר נתבאר זה בשלישי מכריתות:
@1 **השרש** הל' הוא שאם שגגו ב"ד הגדול שהם שבעים ואחד בהוראה ועשו הקהל על פיהם או רובו ר"ל רוב ישראל אם בע"ז שגגו מביאין קרבן הנזכר בפרשת שלח לך פר ושעיר על כל שבט ושבט שהשבט נקרא קהל שנאמר כל קהל יהודה ואם בשאר המצות שגגו מביאי' קרבן הנזכ' בזאת הפרשה והוא פר על כל שבט ושבט שנאמר והקריבו הקהל וזה הקרבן מביאים הסנהדרין שנאמר בפרשת שלח שלך ועשו כל העדה והם הסנהדרין ואם כל עדת ישראל ישגו ואמר גם כן על הסנהדרין ושפטו העדה והצילו העדה ולזה גם כן אמר וסמכו העד' את ידיהם על ראש הפר כי הם בעלי הקרבן והם החוטאים בזאת השגגה כבר נתבאר זה באחד מהוריות:
@1 **השרש** השלשים ואחד הוא שצריך שיהיו אלו השוגגין בהוראה עיני הקהל בעצמותם ולזה לא יהיה אם לא היה ראש הקהל עמהם ואם לא היו כלם ראויין להוראה וצריך שיהיו כלם בלתי שוגגים שנאמר ואם כל עדת ישראל ישגו ולפי שנאמר ונעלם דבר מעיני הקהל הוא מבואר שהוא ראוי שיטעו רבים בדבר זה שהורו בו עליו לפי שאמר ונעלם דבר למדנו שההעלם הזה הוא שיורו לבטל קצת מהמצוה הזאת ולקיים קצתה לא שתעלם מהעדה השלמה הזאת מה שלא יעלם מקטני המעיינים ולפי שחטא הסנהדרין הה הוא מה שיעשו הקהל מזה על פיהם ראוי שיאמר לעם השומעים מפיהם מותרים אתם ולפי שאמר ועשו ששב אל הקהל ראוי שיהיו העושים ע"פ זאת ההוראה רוב ישראל בשעת מעשה מזולת עיני העדה שאינם נכללים בזה להשלימם עמם לרוב וצריך גם כן שיהיה אחר כן נודע גוף שטעו בו מעצמם שלא שיודיעו להם זה אחרים ואז יתחייבו סנהדרין קרבן הנזכר והעושים פטורין מפני ישראל בב"ד ואם חסר מאלו התנאים יהיו הב"ד פטורים מן הקרבן וכל אחד מהעושים בשגגה חייב חטאת. וכן אם אמר אחד מן הסנהדרין לחברו טועים אתם ורבו להם חבריו וטעו והתירו הם פטורין מן הקרבן שאין כולן שוגגין ואולם אם שתקו מעוט הסנהדרין ויודעין שטעו בהם שלא היה חולק בזאת ההוראה הרי ב"ד חייבין בקרבן וכל העושים על פיהם לראות אם הם כת ישראל אם לא משגיחין אלא ליושבי הארץ שאין קרוי קהל אלא שבארץ ישראל לפיכך אם עשו רוב אנשי ארץ ישראל על פיהם אף על פי שלא חטא אלא שבט אחד או שעשו בו השבטים אף על פי שהם מעוט הקהל הרי ב"ד חייבים ומביאין קרבן על כל שבט ושבט אף על פי שלא חטאו כלם כבר התבאר זה בראשון ובשני מהוריות. וראוי שתדע שאם לא היתה סבה השגגה בהוראת העלם בביאור עניין המצוה אלא שנתחדש דבר הטועה אותם כגון שנתכסה השמש בעכין ודמו שהוא לילה ואחר כך זרחה או שבא עד אחד ואמר שמת פלוני והתירו אשתו להנשא אין זה הוראה אלא טעות כבר נתבאר זה בששי מיבמות ואם הורו בית דין באחד משני דברים זה אחר זה ועשו ממנו הקהל על פיהם באחד אחד וכשהצטרפו העושים היו רוב כיון ששגגת הוראתם היתה סבת להחטיא רוב הקהל הרי אלו מצטרפין ויתחייבו בית דין קרבן אף על פי שהיתה להם ידיעה בנתים ולזה לא היתה כן אם היו המורי' שני בתי דינין אף על פי שהשגגה היא נדבר אחד בעינו כבר נזכר זה בראשון מהוריות:
@1 **השרש** הל"ב הוא כל שגגה שההדיוט מביא עליה חטאת קבועה כשבה ושעירה אם שגג בה הנשיא מביא שעיר ואם שגג בה כהן משיח מביא פר שנאמ' אם הכהן המשיח יחטא לאשמת העם הנה דין כהן משיח הוא כדין אשם העם ר"ל שראוי שיהיה שוגג בה ראה כדמיון שגגת ב"ד בהוראה ר"ל שיורה לעקור מקצת הגוף ושיהיה ראוי להוראה ויעשה על פי הוראתו והוא בלתי יודע שטעה ואולם בשגגת ע"ז ועשו על פי הוראתו והוא בלתי יודע בשגגת בית דין הכהן המשיח דין ההדיוט ואם שגג במעשה לבד לא בהוראה בין בעבודה זרה בין בשאר מצות אינו מביא קרבן כלל כבר התבאר זה בהוריות:
@1 **השרש** השלשים ושלשה הוא שהכהן המשיחי הוא הכהן הגדול שנמשח בשמן המשחה אף על פי שעבר מעבודתו מפני מום או מפני זקנה וכיוצא בהם לא המרובה בבגדים ולא נמשח אע"פ שהוא משמש בכהונה גדולה ונשיא הוא המלך מישראל שאן עליו אלא אלהיו אף על פי שהיו בישראל מלכים שאין אחד מהם נכנס תחת חברו וצריך שיהיה זה נשיא בשעת החטא שנאמ' אשר נשיא יחטא וכן צריך שיהיה כהן המשיח כהן משיח בשעת שחטא שנאמר אם הכהן המשיח יחטא ואם לא היה הרי דין כל אחד מהם כהדיוט. ונשיא שנצטרע עבר מנשיאותו והרי הוא כהדיוט כבר נתבאר זה בשלישי מהוריות:
@1 **השרש ה** שלשים וארבעה הוא שאם הורה כהן משיח עם ב"ד ושגג הוא והם בהורא' אחת אף על פי שיעשה ע"פ ההוראה הזאת פטור מקרבן שהרי לא סמך לה על הוראתו לבדה כבר נתבאר זה בשני מהוריות:
@1 **השרש** השלשים וחמשה הוא שנשיא שיעשה עם הצבור בהוראת בית דין הרי זה מתכפר לו בכלל העם ואם היו העושין מביאים קרבן על שגגתן הרי הוא מביא שעיר כבר נזכר זה בשלשה מהוריות:
@1 **השרש** השלשים וששה הוא שמעשה פר כהן משיח כשרי' בכל כהן שנאמר וטבל הכהן וגו' ונתן הכהן מדם וגו' ולא נאמר כהן משיח אלא שמצתו שיקבל כהן משיח ואם כהן אחר כשר כבר נזכר זה בספרא בפרשת כהן משיח:
@1 **השרש** השלשים ושבעה הוא אחר שהפשיט אותה אם היא נאכלת או אחר שקרעה אם היא נשרפת מוציא את האמורין והקטיר אותן על מזבח העולה אחר זריקת הדם והשאר בנשרפת מוציא חוץ לשלש מחנות ומנתה שם כנתח עולה כענין שנאמר ואת כל בשרו על כרעיו ועל קרבו ופרשו ושורפין אותו שם בבית הדשן וכל העצי' כשרי' לשרפתה שנאמר על העצים אפילו קש וגבבה שנאמר עצים ממש ובכלל הנה שם מבואר מכונה התורה שהיא שתדלה להסיר הכבוד מזה הקרבן ולזה הוא מבוא' שלא דקדקה אלא שתהיה השרפה על עצים אי זה שיהיו כבר נזכר זה בספרא בפרשת כהן משיח:
@1 **השרש** השלשים ושמנה הוא שזריקת דם החטאות הנאכלות היתה על ארבע קרנות מזבח העולה וזה יהיה בזה האופן וטבל הכהן באצבעו הימנית הסמוכה לגודל בדם ומחטא ויורד כנגד חודה של קרן עד שיכלה כל הדם שבאצבעו ואם נתן סמוך קרן עד שכבו אמה בפר סמוך וצריך לטבול אצבעו על כל קרן וקרן שנאמר בפר כהן משיח וטבל והזה וכן מצינו בפסח מצרים וכן נלמד זה הדין בשאר וגו' בקרן מערבית דרומית. ואולם החטאות הנשרפות כגון פרים הנשרפים ושעירים הנשרפין חוץ מפר ושעיר של ים הכפורי' שהוגבל בהם דין מיוחד הדם הנכנס לפנים ההיכל ומזים ממנו שם כמו שכתוב בתורה רוצה לומר שהזורק ממנו שבע הזאות על הכפרת המבדלת בין הקדש ובין קדש הקדשים וארבע הזאות על ארבע קרנות מזבח הזהב מתחיל מקרן מזרחית צפונית וגו' במזרחית ושירי הדם שופך אל יסוד מזבח החצון שפוגע בו תחלה והוא מערבי דרומי כבר נזכר זה בספרא בפרשת כהן משיח ובח' ובי"א מזבחים:
@1 **השרש** השלשים ותשעה הוא ששריפת החטאת אע"פ שהוא חוץ לשלשה מחנות על שפך הדשן הנה יחוייב שיהיה המקום טהור ואם יהיה טמא יטהרנו כבר נזכר זה בספרא בפרש' כהן משיח ואולם שאר החטאו' יתבארו בפרש' צו:
@1 **השרש** הארבעים הוא שלא יתחייב האדם באשם תלוי עם שיהיה שם אסור קבוע שנ' ועשה אחת מכל מצות יי' אשר לא תעשנה ולא ידע וגו' כאלו תאמ' שבא על אשת איש שעד אחד אומר מת בעלה ועד אחר אומר לא מת שהרי נקבע האסור וכן אם היו לפניו שתי חתיכו' אחת של חלב ואחת של שמן ואכל אחת מהם ואינו יודע איזו מהם אכל אם היתה לפניו חתיכה שהיא ספק חלב לא היה בה פטור באשם תלוי שאין כאן אסור קבוע וכן אם הוא יודע בודאי שחטא אבל אינו יודע בעצמו שלא חטא והתורה אמרה ואם נפש אחת תחט' וגו' ולא ידע. רוצה לומ' שלא ידע שחטא אם היו לפניו שתי חתיכות אחת של חלב ואחת של חלב נותר ואכל אחת בשגגה מביא חטאת על החלב ואשם תלוי על הנותר שהרי אינו יודע אם חטא בו אם לאו כבר התבאר זה בשלישי ובד' ובכה' מכריתות:
@1 **השרש** האחת וארבעים הוא שכל דבר שחייבן על ודאי חטאת אחת קבועה חייבים על לא הודע שלו אשם תלוי אחת קבועה ומה שחייבין עליו ודאיי חטאות הרבה חייבין עליו אשמות תלויות כמנין החטאות והנה ידיע' ספק מחלקת לשם תלוי כמו שידיעת ודאי מחלקת לקרבן חטאת כבר נתבא' זה בד' כריתות וראוי שתדע שכהן משיח אם נסתפק לו אם שגג שגגה שהיא שגגה הוראה עם המעשה או לא שגג אינו מביא אשם תלוי על לא הודע לפי שהוא שאין מביאים אשם תלוי על לא הודע על שגגת ההוראה אבל הנשיא אם נסתפק לו אם חטא או לא חטא מביא אשם תלוי כהדיוט בר נזכר זה בשני מהוריות וסבת זה מבוארת בעצמה:
@1 **השרש** הארבעים ושתים הוא שמי שנהנה מקדשי יי' בשוה פרוטה בשגגה חייב להביא קרבן מעילה ומשלם מה שנהנה בתוספת חומש מלבד שהוא מרביעית מלוג וקדשי מזבח וקדשי בדק הבית מצטרפין זה עם זה להשלים זה השעור אם היה זה בהעלם אחד ואפילו לזמן מרובה ואפי' נהנה קצת בהנהנה קצת שאני קורא וחטאה בשגגה במהנה בנהנה כבר נתבאר זה בח' ממעילה ומציעה. והאוכל מדבר שמועילין בו בה מתמחויין אף על פי שהם מזבח אחד ובהעלם אחד חייב אשם על כל תמחוי ותמחוי שכל אחד מהם אני קורא ואת אשר חטא מן הקדש ישלם כבר נתבאר זה בשלישי מכריתות:
@1 **השרש** הארבעים ושלשה הוא הקדשי' קלי' אינם נקראי' אישי יי' אלא מה שהיה מהם למזבח אחר שקרבו מתיריו. רוצה לומר שנזרק הדם שנ' והקריב מזבח השלמי' אשה ליי' אחר שזכר זריקת הדם למדנו שעד שנזרק הדם לא יקרא דבר ממנו אשה ליי'. ואולם קדשי קדשים כגון עולה וחטאת ואשם הם בהפך כי הם בכללם קדשי השם עד שיזכו הכהנים בחלקם משלחן גבוה אחר שקרבו המתירים ולזה אמר והנותרת מן המנחה לאהרן ולבניו קדש קדשים מאשי השם למדנו שלא זכו בהם אהרן ובניו עד שתהיה נותרת ושהמנח' בכללה נקראת אשה להשם ולא ימעלו בקדשים קלים גם באימורין כי אם אחר שיקריבו מתירים ואולם בקדש הקדשים ימעלו בכל חלק מהם משהוקדשו עד שיותר לכהנים חלקם כי אז לא ימעלו. בחלק הכהנים כי אינם נקראים קדשי ה' ואף על פי שנפסלו אחר זה כיון שהיה להם שעת התר ואם כן היתה להם שעת ראויה להתיר כי בכמו אלו הדברים נחשב העומד להתיר בנתר כמו שהתבאר בשרשים הכוללים ואולם קדשי בדק הבית הם בכללם קדשי השם ומה שתהיה מהקדשים להשם אין מועילים בו אחר שנגמרה המלאכה בו רוצה לומר שמה שנשרף מהם כיון ששב אפר ויצא לבית הדשן אין מועילין בו וכן העניין כפרים הנשרפין ושעירים הנשרפים בבית הדשן ר"ל שמועילין בהם עד שתגמר שרפתן שם וכן הנסכי' מועלין בהם עד שירדו לשיתין כי אז נגמרה מלאכתן ולזאת הסבה אין מעילה בקדשי מזבח שמתו ולא חטאות אשר דינם שימותו ולא יקרבו כגון חטאת שמתו בעליה וכיוצא בה ולא בתורים שלא הגיעו זמנם לפי שאינן ראוין לפדיון אך קדשי' בעלי מומין שראויין לפדותן הן עדיין נקרקין קדשי השם עד שיפדו כבר נתבאר זה בראשון ובשלישי ממעילה. וראוי שתדע שאין מועילין בדם הקדשים היוצא מהם בעת השחיטה או אחריה כי אינו מגוף הקדשים כמו שאין מועלין בפרש הקדשים ואינו גם כן מיוחד להיות ממנו אשה להשם אבל היה מיוחד לכפר. ואולם דם היוצא מהם בחייהם מועלין בו לפי שהוא כגופם שהוא ראוי אז לזון האברים באופן שישוב חלק מבעל נפש כבר התבאר זה בשלש' ממעילה וח' מיומא וכן העצמות הגידים והקרנים והטלפין שפרשו שאפילו מקרבן עולה שהוא כולו כליל לאחר זריקת דמים אין מועלין בהם ואולם אם פרשו קודם זריקת דמי' מועלין בהם כי הם עדין נקראים קדשי יי' כבר נתבאר זה בט' מזבחים. וראוי שתדע שחלב קדשי מזבח וביצהן אין מועלין בהם כי אינם מגוף הקדשים ואין בהם צד מזבח ואולם חלק קדשי בדק הבית וביצהן מועלין בהם כי הם קדשי יי' וכן הענין אם הוקדשו דמי בהמה ועוף למזבח לנסכים כי יש בדמים צד מזבח. ואולם אם הוקדשו דמיהם לשלמים אין מעילה בשלמים כי אם באמורים אחר שקרבו המתירין כבר נתבאר זה בראשון ובג' ממעילה:
@1 **השרש** הארבעים וארבעה הוא שכל המנחות הקרבות למזבח יחוייב שתהיה מצה וכן שיריה שנאמר לא תאפה חמץ ואמר בפרשת צו לא תאפה חמץ חלקם נתתי וגו' לחייב על מעשה שבא בה כגון הלישה והאפיה והקטוף והנחת שאור על גבי העסה ואפילו מחמץ אחר מחמץ לוקה אם היתה כשירה ואינו לוקה על הפסולה שנאמר כל המנחה אשר תקריבו להשם לא תעשה חמץ ולזה הוא מבואר שאם חמץ מנחת נסכי' לוקה שהמים פוסלין אותה ובזולת מים לא תעשה חמץ וזה מבואר מן החוש כבר נזכר זה בה' ממנחות:
@1 **השרש** הארבעים וחמשה הוא שהקמיצה הוא כדרך שבני אדם קומצים ומה שבראשי אצבעותיו או בראשי הצדדין לא יקשיר לכתחלה שאינו מכלל הקמץ ואם הקטיר כשר ואם הוסיף הקמץ כגון שהרחיק אצבעותיו וקמץ הרי זה פסל כי אינו קמצו ומזה יתבאר שאם חלק הקמץ לשני חלקים אינו קדוש והנה הקמיצה כשר' בכל מקום מהעזרה ואפילו קמץ המנחה מכי שעל גבי הקרקע הרי אני קורא בו וקמץ משם ואין מקדשין הקמץ בכלי שעל גבי הקרקע כבר נזכר זה כלו בראשון ממנחות:
@1 **השרש** הארבעים וששה הוא שהמנחות הנזכרות פתות אותה פתים ועושין שכל עשרון עשר חלות וזה נלמד מלחמי התודה ואם רבה או חסר כשרה וכשפותת החלה כופלה לשנים והשנים לארבע ומבדילן וכלן פתיתין כזית ואם היו יותר או פחות כשרה ואם המנחה היתה של זכרי כהונה אינו מבדיל כבר נתבאר זה בשביעי ממנחות:
@1 **השרש** הארבעים ושבע הוא שמנחת מרחשת בצקה רך שהרי יש לה שפה והיו כלולו' בשמן ויוצק עליהם השמן הנשאר מן הלוג לכל עשרון אחר שנתון בכלי שרת. ואולם מנחת מאפה תנור היתה בלולה בשמן ואין בה יציקת שמן והיתה באה פתיתין כמו העניין במנחת מחבת או מרחשת כי הסבה אחת ואם עשאה רקיקין מושח אותו בשמן לוג לכל עשרון כי זה השיעור הוא אשר אפשר בו לפי הנהוג מענין אלו החלות ואולם מנחת הסלת בלולה בשמן ועוד יש בה יציקת שמן ואחר כך ניתן עליה לבונה כבר נזכר זה בששי ובה' ובי' ממנחות:
@1 **השרש** הארבעים ושמנה הוא שהקומץ את המנחה מסלק את כל לבונתה לצד אחד וקומץ ממקום שנתרבה שמנה שנאמר מסלתה ומשמנה וחוזר ומלקט את כל לבונתה ונותנה על הקומץ שבכלי ומעלה אותה על גבי המזבח כבר נתבאר זה בשני מסוטה:
@1 **השרש** הארבעים ותשעה הוא שהקמץ והלבונה מעכבין זה את זה וכן הסלת והשמן ואולם הבלילה והפתיתה וההגשה ומשיחת הקיקין אין מעכבין כבר נתבאר זה בשלישי ממנחות:
@1 **השרש** החמישים הוא ששאור ודבש אוסרין בכל שהם אם נתערבו בקרבן ואולם לא ילקה על הקטרתו על המזבח הפנימי ולא על החיצון אם לא היה בהן כזית כי אין הקטר פחותה מכזית כבר נתבאר זה בשלישי מפסחי' וזה יהיה כשהקטירן לשם קרבן אבל אם הקטירן לשם עצמן אינו לוקה שנאמר ואל המזבח לא יעלו לריח ניחח כבר נתבאר זה:
@1 **השרש** החמשים ואחד הוא שאם הקטיר דבר שראוי להקטיר מינו אע"פ שאינו ראוי להקטיר בעצמו וערב בו שאור או דבש כגון שהעלה בשר חטאת ואשם וכיוצא בהם שאינם ראויים להקטיר חייב שהרי הן עצמן ראוין לקרבן שנאמר קרבן ראשית תקריבו אותם לה' כבר התבאר זה ברביעי ממנחות:
@1 **השרש** הנ"ב הוא שאין הבדל בחיוב הקרבן מפני שבועת העדות בין זדון לשגגה כי לא אמרה בו התורה ונעלם ממנו והנה השגגה שיתחייב עליה קרבן הוא שידעו שהיא אסורה אבל לא ידעו שחייבין עליה קרבן הוא שידעו אבל אם לא ידעו ששבועה זו אסורה או שלא ידעו שהוא שקר הרי אלו פטורין אף מן הקרבן כי הם כמו אנוסים כבר נתבאר זה בשני משבועות:
@1 **השרש** הנ"ג הוא שעל שגגת טומאת מקדש וקדשיו לא יתחייב קרבן עלה ויורד אם לא היתה לו ידיעה בתחלה וכל העניינים אשר לא יהיה החטא בזולתה כאלו תאמר לטמאה ולקדש או למקדש ר"ל שידע שנטמ' שזה קדש או שזה מקדש ויהיה לו אחר כך העלם בנתים וידיעה בסוף שנ' ונעלם ממנו והוא ידע ואשם והוא מבואר שהידיעה שנתחדש שכבר אשם לא תשלם אם לא ידע כל הענינים הנזכרים ולפי שידיעת החטא' יחוייב שיהיה בנושא אשר היה בו ההעלם למדנו שהעלם היה בענין אלו הענייני' אשר לא יהיה בזה הפעל חטא לזולתם כאלו תאמר שנעלם ממנו שנטמא או נעלם ממנו שזה קדש או מקדש ולפי שההעלם לא יהיה אלא במה שהיתה בו ידיעה בתהלה. למדנו שהיתה לו ידיעה בתחלה בכל אלו העניני'. והמשל שאם יעלם ממנו שכבר נטמא ולא ידע מעולם שזה קדש הנה לא יחוייב שיהיה זה ההעלם סבת החטא. שאף על פי שלא נעלם ממנו שהוא טמא היה אוכל זה הקדש ולשון התורה יורה שההעלם הוא סבה חטאו ולזה לא יחוייב שתהיה לו ידיעה בתחלה בכל אלו העניינים ואם יאמר אומר שכזה גם כן בשגגת ב"ד בהוראה שנאמר ונעלם דבר ונודעה אמרנו לו שאין הענין אחד כי שגגת ב"ד הוא בדבר ובו יפול שם העלם גם במה שלא נודע ולא יתכן שנודע כאמרו ונעלמה מעיני כל חי ואלו באלו הענינים לא יתכן שיאמ' העלם במה שלא נודע ולא יתכן שיודע כאמ' ונעלמה מעיני כל חי ועוד שזה הלשון לא תמצאהו בשגגת ב"ד בהוראה בע"ז ולא בשגגת כהן משיח בהוראה מגיד שלא דקדקה התורה שתהיה בהן ידיע' בתחלה ואולם בזה המקו' כפל המאמר בחלקם שזכר ונעלם שני פעמים להורות שזה העניין הוא תנאי בחיוב זה הקרבן והנה נפל ספק בזה אם ידע ששרץ מטמא ונגע בה בהודעה ממנה ולא ידע ששרץ מטמא כבעדשה אם זאת תקרא ידיעה בטמאה אם לא כי לאומר שיאמר שזו ידיעה לטמאה לפי שאם לא תעלם ממנו היה ראוי שישאל לחכמים אם זה השעור מטמא קדם שיאכל את הקדש או יכנס למקדש ולזה יהיה זה ההעלם סבת החטא וכבר אפשר שיאמר שכיון שלא ידע שזה השעור מטמא הנה אין זו ידיעה לטמאה כי אין לפי דעתי להתרחק מפני זה מאכילת הקדש או מהכנס למקדש. וזה הספק בעינו יקרה במי שידע שיש מקדש בעולם אבל לא שזה מקדש אם זה העניין יקרא ידיעה למקדש אם לא כי לאומר שיאמר כי לא יתרחק האדם הטמא מהכנס למקדש אם לא ידע תחלה שזה מקדש כבר נתבאר זה כלו בראשון ובשני משבועות וכמו ששעור אכילת הקדש הוא כזית כי הוא השעור הקטן אשר יפול בענינים אשר בעבורם יכנס האדם למקדש והוא מבואר שהשעור הקטן הוא שעור השתחואה כי כל הנכנסים שם אחר שעשו חפציהם שם משתחוים וכבר יכנס האדם למקדש להשתחוות לבד כבר נתבאר זה בשני משבועות והוא שכבר ישארו שלשה סוגים בעברות שגגה טומאת מקדש וקדשיו עם זדון טמאת מקדש וקדשיו והנה השגיחה התורה במה שיתכפרו כלם והנה מה שהיתה בו ידיעה בתהלה ולא בסוף שעיר של יום הכפורים תלויה בו עד שיודע לו ויביא קרבן עולה ויורד ושאין בה ידיעה בסוף שעיר הנעשה בחוץ בה' ויום הכפורים מכפרים על זדון טמאה מקדש וקדשיו פר כהן גדול של יום הכפורים מכפר לכהנים ועל שאין בה ידיעה לא בתחלה ולא בסוף שעירי הרגלים ושעיר ראש חדש מכפרי' ודם השעיר הנעשה בפנים ויום הכפורים מכפר לישראל שנאמר וכפרל על הקדש מטמאות בני ישראל וגו' כבר נזכר זה בראשון משבועו' ויתבאר עוד בג"ה במקום מקום מאלו והסבה בזה כדי שיוכר עון כל הטמאות בכללות מישראל כי לרוב המצאו ראוי שתשגיח התורה בו יותר כמו שהשגיחה בהמצאת מה שיכופר בו עון שבועה אפילו היה בזדון לרוב המצאו בדברי' אשר יתכן שימצא יותר כמו הענין בשבועת העדות ושבועת הפקדון כי הרבה נמצא שישבעו על שקר באלו הדברים לחמדת הממון לרוב רגילותם בשבועת כי זה ממה שיביאם להקל בה:
@1 **השרש** החמשים וארבעה הוא שההעלם אשר בשבועת בטוי הו' ההעלם השבוע' ונעלם ממנו שלא יזכור השבועה ונעלם ממנו שזה החפץ הנשבע לה' כאלו תאמ' שנשבע שלא יאכל פת חטים ולא הכיר שזה הפת הוא פת חטים ואכלו והוא מבואר שזה לא יקרה כמה שיהיה מענין שבוע' בטוי להבא ואולם במה שיהיה מזה לשעבר יהיה חייב בו תכף שנשבע עשה זה החטא ואז יהיה ההעלם וכן אם זכר את השבועה והוא מצטער מאד וחשב שמותר לעבור על שבועתו מפני הצער וזה כי אין סבת זה החטא העלם השבועה ממנו וכן אם נעלמה השבועה ממנו ונעלם ממנו היום הנוש' הזה מה שהוא באופן שאף על פי שהוא זכר השבוע' לא יהיה נזכר ממנו כגון שנשבע שלא יאכל פת חטים ודמה פת כוסמין כבר נתבאר זה בשני משבועות:
@1 **השרש** החמשים וחמשה הוא שבטוי שבועות הוא שבועות שאני קורא בהן לכל אשר יבטא האדם בשבועה כבר נתבאר זה בראשון מנדרים. וכן האומר לאו לאו או הין הין דרך שבועה והזכיר שם או כנוי הרי זו שבועה לסבה הקודמת בעינה כבר נזכר זה בד' משבועות:
@1 **השרש** החמשים וששה הוא שהנשבע חייב במה שיוציא בשפתיו ויהיה בשפתיו מה שיסכים למה שהיה בלבו באופן שיהיה פיו ולבו שוים באופן מה שנאמר לבטא בשפתים והמורגל והבטוי בשפתים הוא זה ואם לא היה כן לא חלה עליו השבועה כגון שנשבע שלא לאכול פת חטים ובלבו היה פת שעורים כבר נזכר זה בשני משבועות. וצריך שיעמוד בזה הדעת אחר שבועתו שאם חזר בו תוך כדי דבור לא חלה עליו השבועה כי אין כמו זה בטוי נהוג עמו בלב והתורה אמרה לכל אשר יבטא האדם בשבועה ומזה גם כן יתבאר שהנשבע שבועות הבאי כגון שנשבע שראה עיר גדולה ובצורה. עד לב השמים כי המכוון מזה שהוא בלבו גבוהה לא שיהיה ראשו בשמים וכן אם היה זה אנוס על שבועתו או שעבר עליה באונס פטור כמו שהתבא' בשרשי' הכוללים וכן אם היה מוטעה שאין אני קורא בו לכל אשר יבטא האדם בשבועה כגון שנשבע שלא תהיה לו אשה בעבור שגנבה כיסו או הכת בנו ונמצא שלא עשתה כן או שנשבע שלא אכל לפי שהוא שכח שכבר אכל כי אין מדרך האנשי' שישכחו וג הענין אבל ישכחו מינו ר"ל שלא ישכח האדם אם אכל כשאכל לפי הנהו' אבל אפשר שישכח מה שאכל או שנשבע שלא יאכל ושכח השבועה הזאת בכללה ואכל שהרי הוא דומה לשגגת אשר לשעבר והנה הדין בזה ראוי להיות אחד ר"ל הטעות אשר לשעבר עם הטעות שהוא להכא אבל הדברים ק"ו כי ידמה שיהיה החטא יותר עצו' כשהיה האשם בעת השבועה כמו שימצא זה בשבועה אשר לשעבר כבר נזכר זה בשלישי מנדרים. ואולם שגגת שבועה בטוי לשעבר שחייבין עליה קרבן הוא שידע שהוא נשבע לשקר ולא ידע שחייבין על זאת השבועה קרבן ולהבא הוא כגון שנשבע שלא יאכל פת חטים והרי הוא זוכר שכבר נשבע על פת חטים וחשב ששבועתו היתה שיאכל פת חטים כבר נזכר זה בשני משבועות:
@1 **השרש** החמישים ושבעה הוא שאין השבועה חלה כי אם על דבר שהוא רשות שנ' להרע או להטיב מקיש הטוב לרע מה הרעה רשות אף הטובה רשות לפי לא תהיה השבועה הזאת דבר נוסף כאלו תאמר שנשבע שלא יאכל שתי ככרות אלו וחזר ונשבע שיאכל אחת מהם או שנשבע שלא ישב בסכה עשרים יום והיה חג הסכות נכלל בהם או שלא ישב בסכה עשרים יום וחזר ונשבע על ד' מעשרים יום וצריך גם כן שיהיה בידו לקיים השבועה כאלו תאמ' שישבע שיאכל או שלא יאכל לא שלא יאכלו אחרים שאין זה ברשותי ואין זה האשם כשלא תתקיים השבועה תלוי בהעלם השבועה ממנו ואולם לשעבר כבר תהיה השבועה בטוי בענין המצות כגון שנשבע שהניח תפלין בזמן מה שכבר עבר ולא הניח או מזה ג"כ יתבאר שאם נשבע על מה שאי אפשר לו לקיימה לא יתחייב משום שבועת בטוי כי טבעו יאנסהו כגון שנשבע שלא ישן ג' ימים שאין אשמו תלוי בהעלם השבועה ממנו ולזה היה זאת השבוע' שבועת שוא לא שבועת בטוי כבר נזכר זה השרש בב' משבועות':
@1 **השרש** החמישים ושמנה הוא שקרבן עולה ויורד שהגבילה תורה בשבועת העדות אפי' בזדון ובשגגת מקדש וקדשיו ושל שגגת שבועת בטוי אם הביא מי שהשיגה ידו קרבן עני ביחס אל לא השיג ידו לא יצא שנאמר ואם לא תשיג ידו ואולם אם הביא עני קרבן עשיר יצא והנה השג היד כשיעדהו לפי עת הבאת הקרבנות מביא קרבן עני כבר נזכר זה השרש בששי מכריתות:
@1 **השרש** החמשים ותשעה הוא שכל מקום שיש בו חיוב הבאת קרבן חטאת ועולה יחויב שתהיה חטאת קודמת לעולה וכבר התבאר הסבה בזה בפרשת צו והבריק את אשר לחטאת ראשונה ומזה גם כן אחד לחטאת ואחר לעולה ומזה גם כן נלמד שצריך שיהיו כל מעשיו לשם חטאת כבר נזכר זה בספרא:
@1 **השרש** הששים הוא שהוא מזה מדם חטאת העוף על קיר ושירי הדם מתמצה על היסוד וזה המצוי מעכב בחטאת העוף כבר נזכר זה בחמישי ובששי מזבחים ובא' מחולין:
@1 **השרש** הששים ואחד הוא שכל מקום מהמזבח כשר למליקה ובלבד שיזה דמה למטה באמצע המזבח ואם הזה בכל מקום כשרה והוא שיתן למטה מדם הנפש שנאמר והזה מדם החטאת וגו' והנשאר בדם ימצה אל יסוד המזבח כבר נזכר זה השרש בששי מזבחים:
@1 **השרש** הששים ושנים הוא שמה שהוא מקדשי יי' בהקש אל זה האיש החוטא בשגגה כמו הענין במי שנדר ואמר כבר זה עלי כקרבן יש בו מעילה אם נתנה האיש ההוא כבר נתבאר זה השרש בד' מסנהדרין:
@1 **השרש** הששים ושלשה הוא שהמועל משוה פרוטה בשוגג או במזיד חייב לשלם את הקרן והוא פטור מן החומש והקרבן כבר נתבאר זה השרש בספרא:
@1 **השרש** הששים וחמשה הוא שאין מעילה אלא בתלוש מן הקרקע של הקדש אם לא תלש ממנו ונהנה בו והיה זה כן כי התורה אמרה וחטאה בשגגה וגומ' ואת אשר חטא מן הקדש ישלם וגו' ואם ימצא דבר בקרקעות כשיהנו בו יכלה כי אם במטלטל כמו הענין בפירות וכלים אבל מועלין בגבולי הקדש כגון עשבי שדה שג' הקדש אם הקדיש למזבח מה שאינו ראוי לו אבל אם הקדיש שובך ונתמלאה יונים אין מועלי' ביונים שהרי אינן גדולי הקדש כבר נתבאר זה בשלישי וברביעי ובחמישי ממעילה:
@1 **השרש** הששה וששים הוא שהדבר של הקדש שיהנו בו בזולת פגם כמו המשתמש בכלי הזהב של הקדש כיון שנהנה בו בשוה פרוטה מעל והדבר שיפגם כשיהנו בו כגון בגדים וכן ברזל והדומה להם אין בהם מעילה עד שיהנה בשוה פרוטה באותה ההנאה בעצמה שנהנה בה שנ' ואת אשר חטא מן הקדש ישלם ולא יקרא חטא הזיקו להקדש וזה מבו' בנפשו ולזה ראוי שיהיה החטא ההנאה הוה תשלומין הפגם כבר נתבאר זה בחמישי ממעילה:
@1 **השרש** הששים ושבעה הוא שהמועל בקדשים שאין בהם קדושת גוף בשגגה כגון קדשי מזבח שנפל בהם מום הרי הם עומדים לפדיון או בקדש בדק הבית שכבר נתחלל ההקדש רוצה לומר שיצא לחולין ולזה אל יהיה בו מועל אחר מועל ואולם אם היה זה במזיד לא נתחלל המקדש כי אין ההקדש מתחלל בזה האופן וכן אם נשתמש בו בזולת שיוציאוהו לחולין כאלו תאמר שנשתמש בקדרות של הקדש זה אחר זה וכן יהיה בקדשי מזבח שאין בהם מום רוצה לומר שאחר יהיה בהם מועל אחר מועל והוא מבואר מאד כבר נתבאר זה בחמישי ממעילה:
@1 **השרש** הששים ושמנה הוא ששלוחו של אדם כמוהו בעניין המעילה וזה כי החטא הוא מבואר שהכוונה בו שנשתמש בו והנה בו כאלו היה חולין והוא מבואר שההשתמשות וההנאה אשר יהנה האדם בקניניו הוא שאם שיאכלם או שישתמש בהם או ישאילם ויתנם והרבה פעמים יהיה זה ע"י שליח וזה מבואר בנפשו ולזה הוא מבואר שאם עשה השליח שליחותו המשלח מעל אם לא ידע שהוא הקדש עד שיצא לחולן ואם ידע זה קודם צאת הדבר לחולין הנה אינו החוטא בשגגה בזה ויתחייב השליח כי הוא השוגג כבר נתבאר זה השרש בששי ממעילה:
@1 **השרש** הששים ותשע הוא שמי שנתחייב קרבן מעילה מביא בשתי סלעי' ומקריבו אשם ומתכפר לו אך צריך שישלם תחלה הקרן בתוספת חומש שנאמר ואת אשר חטא מן הקדש ישלם וגו' והכהן יכפר עליו באיל האשם איל אשם מעכבי' ואין חומש מעכב ואם הביא מעילתו ולא הביא אשמו לא יצא לידי קרבן כי איך יכופר לו והוא מחזיק בחטא כבר נזכר זה השרש בספרא:
@1 **השרש** השבעים הוא שהכופר לחברו או לשלוחו ממון המטלטל שאם הודה בו הוא מחוייב לשלם ונשבע על שקר על זאת הכפירה בב"ד באופן שהועילה לו הכפירה והשבועה הרי זה בשוגג או במזיד משלם קרן וחומש ומביא קרבן אשם והנה מלשון הכתוב למדנו שזה הדין לא ינהג במה שאינו ממן מטלטל אין הבדל בזה בין שנשבע מעצמו או שהשביעו התובע ואע"פ שלא ענה אמן שכפירתו אחר שהשביעו היא בעניית אמן כי זה יורה שעל דעת ההיא אמר מה שאמר כבר נתבאר זה ברביעי ובחמישי משבועות. ומזה יתבאר שאם כפר ונשבע על ממון אחד אפילו כמה פעמים חייב שאם הודה באי זה שיהיה מהם חייב לשלם. וכבר יתבאר שאם כלל בשבועה אחר כפירת ממון לרבים שהיו תובעים אותו כל אחד מהם ממון מה וכפר ונשבע שבועה שאין לכם בידי כלום אינו חייב אלא אחת. ולפיכך אם היה בכלם שוה פרוטה חייב אחת שאין בכל ממון שבאחת מהם שוה פרוטה וזה מבאר חיובו ובזה יתבאר שאם נתבע לאחר שבועות רבות על כפירו' רבות חייב על כל אחת ואחת כגון שנתבעו גזל ועשק ופקדון ותשומת יד ואבדה ואמר לו בפני בית דין שבועה שאין לך בידי גזל ועשק ופקדון ותשומת יתד ואבדה ואמר לו בפני ב"ד חייב ה' אשמות. ואם אמר לו שבועה שאין לך בידי כלום לא היה חייב ה' אשמות. ואם אמר לו שבועה שאין לך ידי כלום לא היה חייב אלא אחת כבר נתבאר זה ברביעי ובחמישי משבועות וראוי שתדע שאיך שיהיה שתועיל לו הכפירה חייב כשנשבע על שקר וזה מבואר מלשון התורה לפיכך אם שכר שור מחברו וטען ששאלו חייב שהרי הועילה לו כפירתו לפטרו ממיתה מחמת מלאכה כבר נתבאר זה בחמישי ובט' מקמא וכן אם חייב מלוה בעדים וכפר ונשבע חייב שהרי הועילה לו כפירתו שלא חוייב להשלם עתה עד שיבאו העדים ושמא לא יביאו העדים או יבאו העדים ולא תתקיים עדותן או יפסלו כבר נזכר זה בחמישי משבועות והוא מבואר עוד שלא יקרא נשבע לשקר כשהשביעו התובע אם לא השביעו בלשון שהוא מכירה כבר נתבאר זה השרש בששי מסוטה:
@1 **השרש** האחד ושבעים הוא שלא ינהג זה הדין אלא לישראל ולא לגוי שנאמר וכחש בעמיתו וכן הגוזל פחות פחות משוה פרוטה לא ינהג בו זה הדין ולא ינהג גם כן בקרקעות וכמה שאין גופו ממון ובעבדים כבר התבאר זה בט' ובעשירי מקמא אבל יתחייב באלה מפני שבועת בטוי שהרי נשבע על שקר כבר נתבאר זה בספרא:
@1 **השרש** השבעים ושנים הוא שאין מקריבין את האשם אלא אחר השבתו הגזלה או הממון שכפר שנ' והשיב את הגזלה אשר גזל וגומ' ואת אשמו יביא ואין החומש מעכב את הכפרה כמו שזכרנו באשם מעילות כבר נתבאר בט' מקמא והוא מבואר שהשבתו הגזלה הוא שיחזירנה בעינה אם לא נשתנית ואם נשתנית או מוכרה ישיב דמיה. ולא תקרא השבה אם לא תתננה לנגזל בעצמו או לבנו ולא לשלוחו כי אין זה הזבה אם לא מת הנגזל כי יחוייב שישיבה ליורשיו שנ' לאשר הוא לו יתננו ביום אשמתו ואולם אם אינם שם והוא נחפז להביא אשמו מביא הגזלה והחומש לבית דין שבעירו והם מטפלין בה עד שתגיע לבעליה שכיון שנתן לד' הרי זה כאלו הגיע ליד הנגזל ואולם בגזלן לא נשבע על שקר לא יחוייב שירדוף אחר הנגזל להשיב לו גזלתו אך ישיבה לו כשישאלנה ואמנם היה זה הדין כשנשבע על שקר לפי שכבר נתיאשו הבעלים מלשאול לו הגזלה בהשבעו לשקר עליה כבר נתבאר זה בתשיעי מקמא. וראוי שתדע שאף על פי שירש הגזלן את הנגזל ראוי שיוציא הגזלה מתחת ידו קודם שיביא אשמו ולזה יחוייב לו שיפרעה בחובו או יתננה לבניו או לצדקה כבר נזכר זה בתשיעי מקמא:
@1 **השרש** השבעים ושלשה הוא שלא ינהג זה בגזל אביו או בשק אביו אע"פ שכבר בו ונשבע על שקר שנ' אשר גזל אשר עשק פרט לגזל אביו או לעשק אביו האלהים אם לא היתה הגזלה בעינה ביד הבן כי אז אני קרא בו אשר עשק כיון שאינו משיב אותה לו ואם כפר האב ונשבע והודה או שהודה היורש משלם קרן וחמש ואינו מביא אשם אין כפרה לאחר מיתה כבר נזכר זה בספרא ובתשיעי מקמא:
@1 **השרש** השבעים וארבעה הוא שמי שהודה אחר כפירתו והשבעו על שקר הוא שיתחייב חמש ואשם אם לא באו עדים והוא עומד עדיין בכפירתו לפי שהחמש והקרבן הם באים לכפרה ואינו מביא אותם אלא על פי עצמו והוא שדין החמש הוא כדין הקרן אם כפר ונשבע על שקר שהרי החמש הוא גם כן ממון שיתחייב בו אם יודה כבר נזכר זה בט' מקמא:
@1 **השרש** השבעים וחמשה הוא שכבר יתחייב אדם להשיב את הגזלה אשר גזל אע"פ שלא נשבע בה על שקר וזה נלמד מזה המקו' משני צדדין ואחד שכבר יראה שמה שהחמירה התורה להוסיף חמש ולהביא אשם בכסף שקים הוא כשכפר ונשבע על שקר אמנם בזולת זה יתחייב להשיב ממון שנתחייב וזה מבואר בנפשו והשני הוא שאנחנו נראה באבדה שהיא אחת מן הפרטים הנזכרים בזה המקום שכבר יחוייב להשיב אותה לבעליה והוא הדין בגזלה ועשק ויתר הדברים אבל יראה שהדברי' ק"ו ולזה הוא מבואר שהגזלן יחוייב להשיב הגזלה אם לא נשתנית ואש נשתנית או מכרה או נתנה משלם דמיה ואם היתה הגזלה בקרקעות ואכל פירותיהם או תלש האילנות משלם דמיהן כי הקרקע היא בחזקת בעליה ואינה נגזלת אך פרותיה נגזלין וכן אם השחית הקרקע בידיו אך אם נשחת הקרקע מעצמו לוקחין הבעלין את אלהן ואם השביחה מאליה השבח לבעלים ואם הוציאה בה הוצאות והשביחה יד הגוזל על התחתונה אם השבה יותר על ההוצאה נוטל ההוצאה ואם ההוצאה יתרה נוטל השבח כי מה שעשה עשה שלא ברשות כבר נזכר זה בששי מקמא ובי' ממציאה והנה הרמב"ם ז"ל מנה השבת הגזל מצוה בפני עצמה ולא נגלה לי עדיין חיוב זה מהעקרי' שהשריש הר"ם בזה בספר המצות ועוד שלפי זה הדעת היה לו למנות השבת העשק והשבת הפקדון כל אחת מהם מצוה בפני עצמה וגם היה לו למנות ואת אשר חטא מן הקדש ישלם מצוה עשה כי ממנו למדו שהנהנה מקדשי השם במזיד או בפחות משוה פרוטה משלם את הקרן:
@1 **השרש** השבעים וששה הוא שלשון אלה היא שבועה או קללה ולא תהיה אלא בשם המיוחד או בכנוי מן הכנוים וזה נלמד באופן מה מעניין הסוטה כבר נזכר זה ברביעי משבועות וזה שרש כולל לכל השבועות ואם ענה אמן הרי הוא כאלו נשבע וזה נלמד גם כן מסוטה כבר נזכר זה בשני משבועות וזה גם כן שרש כולל לכל השבועות:
@1 **השרש** השבעים ושבעה הוא ששמיעת קול אלה כבר תהיה אפילו חוץ לב"ד והוא שיענה אמן אמנם הכפירה לא תהיה כי אם בפני ב"ד. כי במקום ההוא לבד תועיל לו עדות העדים ויגיעהו היזק בספירתם וזה יתבאר ממה שאומ' והוא עד והנה לא יקרא עד על הגדתו בזולת המקום ההוא ויתבאר מהעניינים הנלוים לזה שאם ינהג לבד בטענת הממון המטלטל וזה יתבאר ממה שנזכר בשבועת הפקדון שנזכרו בה בפרט דברים שהם ממון מטלטל לא תהיה כפירת העד חמורה מכפירת מי שהפקדון בידו ובהיות העניין כן הנה יחוייב שננהג זה לבד בדבר שבממון אשר ינזק הטוען בכפירת העד ויתחייב הנתבע בעדותן לבדה לפיכך אם היה יכול להתקיים העדות מזולתו או אם לא יחוייב הנתבע לבד בעדותן ממון לא יהיה זה הדין וכן אם היה העד קרוב או פסול כי אז אינו עד לפי האמת וצריך גם כן שיחד עדיו בעת השבועה או בעת התביעה לא יאמ' דרך כללות משביע אני בש' ית' כל מי שידע לי עדות שיבא ויגיד שנאמר ונפש כי תחטא ושמעה קול אלה והוא עד מגיד שצריך שישמע הסומך קול האלה ולפי שלא תהיה השמיעה הזאת מזולת הבנת הדברים למדנו שצריך שישביעם בלשון שיבינוהו העדים ואם חסר אחד מאלו התנאים לא יהיו העדים חייבין בקרבן עולה ויורד מפני שבועת העדות כבר נתבאר זה כלו בד' ובה' משבועות:
@143 **צו את אהרן זאת תורת העולה וגומ'.**
@143 **ואמנם** סבת הסדור אשר היה לזכור הקרבנות בזאת הפרשה היא מבוארת ממה שזכרנו בפרשת ויקרא כי סדורם בזה המקום הוא סדורם אשר בפר' ויקרא זולתי השלמים אשר בא זכרונם כזאת הפרשה אחר שאר הקרבנות והסבה בזה כי התורה זכרה קדשי הקדשים תחלה בזה המקום וזכרה חקה כהנים מהם ושהם שותפים כשהנאכל מהם לכהנים נאכל במקום קדוש ואחר זכר משפט הקדשים הקלים וזכר עם תורת המנחה מנחת מחבת של כהן גדול להשלים הביאור בעניין המנחה ואחר שנשלם פה הביאור באופן עשיית הקרבנות ראוי שנתן הסבה למה היתה עשותם בזה האופן לפי מה שאפשר לנו ונציע בכאן כי המזבח היה נחלק גבהו לשני חלקים כמו שנזכר בפרשת ויקחו לי תרומה והחלק העליון היה כלה לארבע קרנות ושהם היו מהמזבח בעינו כמו שאמר בפרשת תרומה ובו היה הסובב למטה ממקום המערכה שלשה אמות והחצי התחתון כלה היסוד שהוא מקיף ברוחות כלם וקשרם והנה היה זה כן לפי מה שאחשוב כי מפני שהיה בחלק העיון השרפה והכליון לדברים הנקטרים שם והנה סבת ההפסד החמר מפני היותו מורכב מהפכים שהם היסודות הארבעה היו שם ארבע קרנות בפעל נבדלים להעיר על מציאות היסודות והיו אלו הקרנות ממנו לפי שאלו היסודות הוא מורכב בכח קרוב כמו שהתבאר בטבעיות והיה למטה הסובב בחלק העליון להעיר כי המורכב מהם עם היותו אחד מצד ההרכבה יכלה ויפסד אליהם וזה יהיה כשישום כל יסוד ליסודו ואולם החלק התחתון הוא יסוד המזבח הוא מעיר על הצורה כי בה יהיה קיום המורכב הזמן האפשרי מצד הכוחות אשר בה לשמור מציאותו בכלים אשר הכין לה הטבע לזה ולפי שהצורה תשים המורכב אחד ומקפת בו כמו שהתבאר בטבעיות הנה היה כלה חצי המזבח השפל אל יסוד המקיף אותו בכללות ולזה הצד אפשר שנשלים הסבה בהיות הזאות חטאות בהמה בחלק העליון מן המזבח על ארבע קרנות והזאות עולת בהמה בחלק השפל סביב וזה כי החטאת בא על העברות החמורות ואולם העולה באה אם בנדר אם בנדבה אם לכפרה על העבירות הקלות ולפי שסבת העברות הוא החומר כמו שהתבאר בספר מלחמות השם הנה בקרבן החטאת שהוא בא על הערות החמורות יזו הדם שהוא כלי לנפש להוביל המזון והחום היסודי לאברי בעל נפש על ארבע קרנות קיר מזבח העולה היא בחלק העליון המורה על החמר והפרדו ליסודותיו ובזה האופן תהיה ההזאה שם רוצה לומר באופן מורה על ההפרדה לא על הקשר ולזה היו אלו ההזאות בארך על קרנות קיר מזבח העולה להעיר שראוי שיתן אל לבו המביא זה הקרבן שימשול נפשו על חמרו באופן שיהיה נשמר מהחטאים עד שאפילו בעניינים החמריים ישתדל לעבודת השם יתעלה ובהם יעבדוהו כי מי שיהיה בזה התואר לא יתכן שיקרה לו כמו זה החטא אשר יביאו עליו חטאת והמשל כי כשיתן אל לבו כשיבעול שלא תהיה בעילתו כי אם לעובודת השם יתעלה לא תביאהו תאותו אל המשגל שיכניס עצמו בספר אם זאת הנבעלת היא אשתו או היא ערוה עליו אבל ידקדק בכל הפנים שאפשר שלא צהיה בפעולתו זאת המרי אחר שתכלית כונתו בה היא לעבודת השם יתעלה וכן הענין בשאר המאכלים אשר יתחייב עליהם כרת ר"ל שלא ביאהו תאותו לאכול ושיכנס עצמו בספק אם זה המאכל מותר לו או אסור לו אבל ידקדק בכל הפנים שאפשר שלא יהיה בפעולתו זאת המרי אחר שתכלית כונתו בה היא לעבודת השם יתעלה וכן העניין בע"ז כי מי שזה דרכו ישמור בכל הפנים שאפשר מנתינת האלהות לזולת השם יתעלה שכל תאותו היה לעבוד השם יתעלה ולזאת הסבה יוקטרו החלבים במזבח ויאכלו זכרי כהנים שאר הבשר במקום קדוש להעיר שיתדל לעבוד השם באלו העניינים החמריים בעצמם ביותר שלם שאפשר והוא שיקח מהם מה שיקנה בו השכל שלמותו כי זה היותר נבחר מהם כמו שהיו החלבי' לפי המפורסם היותר נבחר שבגוף הב"ח ולזה היו קרבים לשם יתע' והיה בשר החטאת נאכל לכהנים להעיר זה האיש שיתקרב אל יודעי ה' להישירו אל השלמות בזה ולהודיעו משפטי התורה כי בזה יהיה נשמר מכמו אלו החטאים וזה כי הכהנים היו עובדים השם יתעלה תמיד והיו משתדלים בעיון תמיד ולזה נתנו להם מתנות כהונה כדי שלא יהיו טרודים במה שיצטרך להם מהמזון והלבוש והיו מיוחדים מפני זה להורות משפטי השם ותורתו לישראל כמו שאמר יורו משפטיך ליעקב ותורתך לישראל ואמר כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו כי מלאך ה' צבאות הוא ולזה היה בשר החטאת נאכל לזכרי כהונה לא לנשים כי אין מחק הנשים להשיג השלמות בעיון והיה נאכל במקום קדוש להעיר עליו שהיה התקרבו להם להשיג השלמות האנושי אשר בו תהיה הקדושה האמתית והנה לא יזכו מכהנים בשר החטאת אם לא אחר הקטרת החלבים לשם יתעלה להעיר שלא יהיה התקרבו לכהנים ההם אלא מפני מה שהישירו אליו מעבודת השם יתעלה ומזה הצד יזכו הכהנים בזה הבשר ולזה יחויב שיהיה קרב תחלה מה שהיה ממנו לשם יתעלה ואולם החטאת הבא על השלמים כמו כהן משיח וב"ד הגדול שטעו בהוראה לא היה בשרו נאכל לכהנים כי הם אינם צריכים אל שיתקרבו למי שלמטה מהם בעיון להשיג השלמות והיה הזאתו שבע פעמים לפני הפרכת ואצל קרנות מזבח הזהב מפני מה שאומר אמנם היה מזה אצל קרנות מזבח הזהב התבארה סבתו במה שאמרנו בהזאת דם החטאת אצל קרנות מזבח העולה ואולם ייוחד לאלו השלמים הזריקה על קרנות זה המזבח כי עניין זה המזבח ירה על נמצא יות' שלם ממה שיורה עליו מזבח העולה החיצון כמו שביארנו בפרש' ואתה תצוה ולפי שאלו האנשים השלימו נפשם והיו משיגים המושכלות בפעל יוחד להם זריקת הדם על זה המזבח המורה על מציאות הצורה האנושית כמו שביארנו במה שקדם וכאלו תהיה הערה בזה שאם היה סבת המרי מצד שסדון שלמות הנפש בעיון אשר סבתו החמר והדברים החמרים ישתדל בכל הפנים שאפשר להכניע הכחות החמריות שלא ישתדלו בפעולותיהם כי אם לעבודת השם יתע' ואמנם הסבה בשבע הזאות אשר לפני הפרכת היא כי כבר ידעת אתה המעיין בביאורנו זה שמגרמים השמימיים יושפעו תאות ובחירות ודעות פעם נאותות ופעם בלתי נאותות ושהשכל האנושי ימשול על אלו התאות והבחירות והדעות כי אם לעבודת השם יתעלה ובזה יתחזק לעמוד כנגד מה שאפשר שיהיה בו יציאה מעבודתו וידקדק בדעותיו שלא היה בהם כי אם מה שהכונה בו לעבודת השם יתעלה ובזה ימלט מכמו אלו הטעיות הבאות בסבה מה שיושפע לו מהגרמים השמימיים והנה היו אלו ההזאות ז' כי כן מספר כוכבי לכת אשר מהם יושפעו אלו הדברים לפי המקומות שהם בהם מגלגל המזלות ולפי מבטיהם קצתם עם קצת כמו שביארנו במ"י ואמנם היתה ההזאה שם קודמת להזאה בד' קרנות מזבח הזהב לפי שהמקום ההוא יותר נכבד לפי שהוא יותר קרוב לקדש הקדשים וההזאה שם כנגד קדשי הקדשים ועוד שהוא יותר ראוי שייוחס זה המרי לכמו אלו האנשים השלמים מחד מה שיושפע להם מהתאות והבחירות והדעות מהגרמים השמימים משיוחס להם מצד חסרונם בעיון ואולם הקטרת אלו חטאות הנה הסבה במה שקדם מהם במזבח העולה היא הסבה בעינה שזכר בחטאות הנאכלות וזה כי בו הערה שלא ישתמשו בדברים החמרים כי אם היותר טוב מהם והוא מה שילקח בו תועלת להשגת השלמות האנושי ושאר הדברים החמרים כלו ישנאום לברחם מתאוות החמר והנאותיו ולזה ישרף שאר החטאת חוץ לשלשה מחנות במגונה שבפנים רוצה לומ' שכבר ישרף שם הבשר עם עורו ועם פרשו להעיר שאלו הדברים ראוי שיהיו אצלם מגונים מאד ובזה האופן ישתדל השכל להכניע אלו התאוות אשר מצד הגרמים השמימיים ומצד המזג שהיו סבת זה החטא להיות אצלו נמאסים ומרוחקות בתכלית מה שאפשר ולהעיר שיקח המקריב זה הקרבן זאת הערה מעניין הקרבת הב"ח היתה הסמיכה קודם זה על ראש הב"ח ההוא עם ודוי העונות להורות שהעונות האלו הוסרו מעל החוטא והושמו על זה הב"ח ולזה יעשה ענין זה החוטא בעינו ואולם העולה היתה הזריקה בחלק השפל מהמזבח שהוא מורה על הצורה והיותה שם סביב להיותה הצורה מקפת בחמר ומשימה אותו אחר והכונה בזה שישים כלל תנועת נפשו להשלים צורתו והיה זה כן להיות הצורה מקפת בחמר כמו דורון ורצון לשם יתעלה והרצוי לשם יתע' הוא מצד הצורה והיתה מנותחת לנתחי' והיה כליל על מזבח העולה להעיר שגם בעניני' החמריים ישתדל שיהיו לעבודת השם יתעלה וזה כי הנתחים מורים על ההפרדה שתהיה מצד החמר כי הנפש תקשור אלו הנתחים ותשימם דבר אחד במספר מצד שכללם יכוון בהם עניין אחד והוא שמירת הב"ח ההוא ואמנם היה רבוי אלו הכלים והפרדס מצד החמר ולזה יורה זה שכל כונתו בעניינים המריים תהיה לעבודת השם יתעלה ולא ישתמש בחמריות כי אם מזה הצד וכבר ביארנו במה שקדם כי בעניין העולה עוד תועלת להגע' הנבואה עם מה שנמשך ממנה מה תועלת בעניין במה שיתמיד במזבח ממנה והוא תמיד של שחר ותמיד של בין הערבים לפי מה שביא' בספר ואלה שמות ולהיות העולה באה על רצוי ודורון לא יוכל המחוייב חטאת ועולה להקריב העולה באה על רצוי ודורון לא יוכל המחוייב חטאת ועולה להקריב העולה אם לא אחר החטאת כדי שיהיה מוכן אל הרצוי קודם הקריבו את העולה ולפי שהעולה יותר נכבדת מהחטאת. היתה העולה זכר והחטאת נקבה מהיחיד וזה שהעולה היא לפי מה שבארנו הערה להשלים הנפש המשכלת ולהמשך לעבודתה בכל כחות הגוף והחטאת או להסיר המרי מהפעלות החמריות ולכוין שיהיו בתכלית היושר והנכונה לעבודת השם יתעלה ולזה יחס הצורה אל החומר הוא יחס הזכר אל הנקבה ואמנם חטאת כהן משיח ובד' שטעו בהוראה היתה פר למעלתם והיה בעבוד' זרה שעיר מצד עצם ע"ז כמו שאמר ולא יזבחו עוד זבחיהם לשעירים וכן היה חטאת נשיא זכר למעלתו במלכות וכן חטאת צבור לכבוד הרבוי והנה היה מקום השחיטה בצון לעולת ולחטאת ולאשם וההקרבה למה שיוקטר על המזבח בדרום כי השחיטה היא קודם פעל הרצון והקרב היא הרצוי ויהיה בזה העדה כי בהשתדלו להתקרב לשם יתעלה באופן שיהיה נרצה יעתק מהשמאל אל הימין רוצה לומר שיעתק מהפעולות הנוטות מהיושר והנכונה ויתקרב אל הפעולות הטובות והישנות ולזה גם כן יעתק מהשמאל אל הימין בהגשתו הדם למזבח להשלים פעל הרצוי ואולם קדשים קלים להיותם בלתי באים על חטא אבל על נתינת תודה והשמחה במה שהשפיע השם יתעלה מהטובות לא חוייב בשחיטתם שתהיה בצפון. והנה שירי הדם נשפכים כלם אל יסוד מערבי דרומי של מזבח העולה לסכות האחד לכבות הדם הנזרק שהיתה הכפרה בו שאם היה זה הדם נשפך באופן אחר היה זה מביא להקל בעניין הדם אשר בו היתה הכפרה ולא יחשוב להמון שתשלם בו הכפרה כי דם אחר היה עם זה הדם הנשפך ושנית כי בו הערה אל שישים בעל הקרבן כל כונתו בענין הצורה ולא יפנה אל הדברים החמריים ולזה היה נשפך למטה אל היסוד שהוא מעיר אל הצורה כמו שקדם השלישית כי בזה האופן יסור לכלוך הדם ועפושו מזה המקום הנכבד כי שם היה ביסוד ההוא נקב יכנס בו זה הדם תחת הקרקע והיה שם עוד נסוך היין בזה המקום בעינו כמו שיתב' להסיר זוהמת הדם ועפושו מזה המקום אשר היו נשפכים בו שירי הדם והנה במה ששמה התורה הדם מכפר העידה על מציאות הנפש כי הדם הוא הנושא באופן מה לחוס היסודי אשר הוא הכלי הראשון לנפש והנה יתבאר כי בדם יתלה חיות הב"ח מן החוש עד שהוא יעיר על מציאות הנפש כי הקודמים טעו ולא חשבו שיהיה בכאן צורה כמו שזכרנו במה שקדם ולזה שמו קצתם הנפש אש והוא מבואר שאין די בחום לעשות זה הפעל אשר בו ישוב המזון דם אבל זה מפעולות הנפש והחום המשוער הוא הכלי לזה ולישב בנפשותינו גודל עניינו לא הותר לנו לאכלו ועל זה אמרה התורה כי הדם הוא הנפש כי בו יתלה מציאות הנפש וממנו הוראה אל מציאתו ולזה גם כן אמרה כי הדם הוא בנפש יכפר והנה אין זאת ההערה מעטת התועלת בעיון אבל היא רבה מאד כי מי לי שלא יאמין במציאות הצורה יסיר ממנו כל מושכל עם שלא יהיה שם אלוה לפי זאת ההנחה ולזה יסרה התורה עניינים רבים במקדש לקיים הדעה האמתי כשהצורות נמצאות על מדרגותיהם כמו שזכרנו בפרשת תרומה ובפרשת תצוה ואמנם בחטאת העוף ועולת עוף לא מצאנו העניין הולך כזה הסדור אשר זכרנו בבהמה וזה שעולת העוף היה דמה נתן למעלה ודם חטאת העוף למטה מהפך העניין בבהמה ועוד שמליקת עולת העוף היה דמה נתן למעלה וחטאת העוף לא דקדקה התורה שתהיה בצפון כמו שדקדקה בזה בשחיטת בהמה אבל יראה מלשון התורה שהוא בדרום כמו שביארנו. וראוי שנאמר בסבת זה לפי מה שיראה לנו ונאמר כי מפני שלמעוט דם העוף לא יתכן קבלת דמו בכלי שרת להגישו אל המזבח להזה היה מן ההכרח שתהיה מליקתו אצל המקום מהמזבח שיזו דמו באופן שיהיה הדם שותת שם מן העוף בעצמו ולזאת הסבה היה מחוייב שתהיה מליקתו על ידי כהן כי המליקה בו הוא כלי בעצמות אל הזריקה שישלם הרצוי בקרבן בסבתה כי מהמכה היא יוציא הדם אם כשימצה מעצמו שם כמו שנזכר בעולה אם כשיזה כשיניע העוף ויוזה דמו כמו שנזכר בחטאות ולזה היתה המליקה ע"י כהן כי מה שלא יחוייב היותו כן כשחיטה כי השחיטה כשרה בזר ובהיות הענין כן הנה לא היה מחוייב במליקה שתהיה בצפון כי הוא מפעל רצוי בעצמו אשר מקומו בדרו' ולזה ייוחד למליקה מצד הדרומי מערבי מהמזבח ובזה נשלמה הסבה למה לא יחושב במליקה שתהיה בצפון כמו הענין בשחיטת עולת בהם וחטאת בהמה ואחשוב שלזאת הסבה בעינה היתה המליקה ממול עורף וזה כי למעוט דם העוף לא היה נאות שיקובל דמו בכלי להזאת ממנו כמו הענין בבהמה אבל היה העוף בעצמו הוא הכלי כי ממני ימצה הדם ולזה יחוייב שלא יהיה לכלי ההוא התחלה להתנועע מעצמו בעת ההזאה שאם היה הדבר כן היה אפשר שיוזה דמו ברוחב כשיכון שיהיה בארך וההפך ולזה לא יפסק חוט השדרה תחלה בו באופן שיבטל החוש והתנועה במה שאחריו מאברי העוף ובעת החתך הוורידין בזה העוף הנה יהיה העוף במדרגת הכלי שלא יתנוע' ולא יפרכס כלל ולזה יזה דמו בצורה אשר ירצה הכהן ולזה תמצא שמה שהיה מהעוף שיקבל דמו בכלי ישחט ולא ימלק כמו שתראה בצפורי מצורע ואולם למה היו מעשה חטאת העוף למטה ועולה העוף למעלה בהפך הענין בעולת בהמה וחטאת בהמה הנה בזה עיון עמוק ונאמר כי מפני שלא היה בחטאת העוף דבר נקטר לשם יתעלה והיתה הכונה בחטאת כמו שהקדמנו שישתדל החוטא בעבודת השם יתעלה ויתקרב אל יודעיו למען יביאהו אל השלמות והיתה העבודה השלמה לשם יתעלה בצורה הנה ראוי שיזרק דם זה החטאת במה שהיה מהמזבח מעיר הצורה והכונה בזה כדי שלא תהיה תאותו ונפשו כי אם בשלמיות המיוחסים לצורתו וינתן בשר זה החטאת לכהנים שיאכלוהו במקום קדוש לסבה בעינה אשר היה זה העניין בחטא' בהמה ולפי שלא נשלמה בזה ההערה השלמה אשר היתה בחטאת בהמה שתמשול הנפש בחמר אשר הוא סבת החטאים האלה ובו ישתדל גם כן לעבוד ה' יתע' תמצא שיהיה מהכרח חטאת העוף כשהיה תמורת חטאת בהמה שיהיה עמו עולת העוף ובו תשלם זאת הכונה וזה כי דמו היה שותת בחלק העליון מהמזבח מלמעלה למטה באופן מורה על ההפרד' אשר הוא מפאת החמר ולא על ההקשר שהוא מפאת הצורה כי מה שיורה על ההקשר הוא כשהיה רושם הדם הולך ברחב כאלו יקיף המזבח ולזה היתה זאת המתנה בחלק העליון מהמזבח כי הוא מודה על החמר ויעיר שישתדל שתמשול נפש זה החוטא בחמרו שהוא סבת החטאי' ובו יעבוד ה' יתע' והנה היתה כלה כליל לסבה בעינה שהיה זה העניין בעולת בהמה ולא צותה התורה לנתח העוף לנתחים להורות על ההפסד אשר יהיה מצד החמר כי כבר נשלמה כונת אלה העניינים במה שנמצה דמו על קיר בארך שיור' על ההפרדה שתהי' מצד החמר כמו שביארנו. ולזאת הסבה לא תמצא חטאת העוף שלא תהיה עמו עולת העוף תמצא זה בחטאת חוטא בשבועת העדו' וטומא' מקד' וקדשיו ושבוע בטוי ובקרבן זב וזב' ובקרבן נזיר אשרם מצורע הנה והוא מה שנרא' לנו בנתינת הסבה בזה והוא נפלא מאד כמו שתראה והנה לא היה אפשר שינתן דם העוף על קרנות המזבח ולא כשינתנו ממנו שתי מתנות ברוחב בשתי צדי האלכסון כמו העניין בבהמה כי למעוט דמו לא יהיה אפשר לקבל דמו בכלי להוליכו מקום אלו המתנות ולזה חוייב שלא תהיה כי אם מתנה אחת יוצא מגוף העוף בעצמו וראוי שנעיין למה היתה ההזא' כחטאה בהמה בא צבע הכהן הימנית ואין העני כן בזריקה בעולה ובשאר הקרבנות ונאמר כי מפני שהיתה הכונה במתנת חטאת בהמה שיתן אל לבו מביא זה הקרבן שימשיל נפשו על חמדו באופן שיהיה נשמר מהחטאים עד שאפילו בעניינים החמריים ישתדל לעבודת השם יתעלה ובהם יעבדוה והנה היתה זאת הנתינה לדם באצבע הימנית להעיר שתהינה פעולותיו החמריות כלם נוטות אל היושר והנכונה ובזה האופן ישלם לו שיעבוד בהם השם יתע' כי האצבע הוא כלי להרבה מהפעולו ולזה תמצא שגם בה' ית' אמר דוד עליו השלום כי אראה שמיך מעשה אצבעותיך ואומ' בתורה על הלוחות כתובים באצבע אלהים. אצבע אלהים היא והיה זה כן לפי שבידים יעשה האדם רוב הפעולות והמלאכו' והנה יושמו על המערכת עצים בעת הבאת נתחי התמיד על האש כדי שתאכל האש העצים ובאמצעותם תאכל אברי העולה והיה זה כן להעיר על שההפסד יהיה לחי מצד מה שילך ממנו מדרגה ההיולי והו' הגשם הצומח לא מצד מה שילך ממנו מדרגת הצורה ולזה היה הכליון לאברי החי בסבת העצים כי הצורה ההוא אשר תשתדל בשמירת הנמצא שהיא לו צורה כפי מה שאפשר ובכלל הנה הטובות הם לדבר מצד הצורה והרעות מצד החמר והנה יביא זה העניין אל העיון בצורה על מדרגותיה ויכלה העייון בזה אל השם יתעלה ובזה האופן יהיה גם כן מיישיר עניין קרבן עולת התמיד להגעת הנבואה למוכן לה וכבר ביארנו בפרשת נח בזה סבה אחרת ר"ל להתישר בענין הקרבת הקרבנות להגעת הנבואה והנה היה האשם זכר לפי שהחטא בו למטה מהחטא אשר יביאו עליו אשם חטאת כי כל מה אשר היה החטא יותר מגונה ראוי שיהיה הקרבן עליו יותר פחות ולזאת הסבה ג"כ היתה זריקת דמו למטה כמו הענין בעולה להעיר על שישים כל תאוות נפשו להשלים צורתו והיו נקטרים החלבים על מזבח העולה והבשר נאכל לזכרי כהונה במקום קדוש לסבה בעינה אשר היה זה הענין בחטאת ואולם חיוב היותו בא בכסף שקלים אחשוב כי הסבה בזה מבוארת באשם מעילות ואשם גזלות וזה כי מפני שהיה רוצה להנות במה שאינו שלו כאשם גזלות או שהיה נהנה במה שראוי שישמר מלהנות ממנו רצתה התורה לענשו בזה הממון עד שלא יוכל לייהנות להביא קרבנו בפחות משתי סלעים של כסף נקי למען ירפא מזאת התכונה הרעה ולזאת הסבה בעינה נענש בשיוסיף חמש על מה שרצה להחזיק בו שלא כדין או שנתנה בו שלא כדין למען יזהר מזאת התכונה הרעה ויפליג לחקור בדברים שיהנה מהם שלא יהיה שום מרי בהנאתו מהם ואולם באשם שפתח חרופה יתבא' גם כן מצד הזה באופן מה וזה שכבר היה זה לענשו בכסף באופן שישמר שלא תביאהו תאותות אל כמו אלו ההנאות בבעילות שלא יתרחק מצד מה שיש בו צד איסור ובזה האופן בעינו היה אפשר שתנתן הסבה באשם על אשר לא הודע למה שהיה בכסף שקלים כי זה יהיה לענשו כסף באופן שישמר שלא תביאהו תאותו אל כמו אלו ההנאות והתאוות בבעילות ובמאכלים שלא ידקדק בתכלית מה שאפשר אם יש בהם שום חשש אסור ועוד כי מפני שלא היה ראוי שיביא על זה חטא' כי החטא או למטה מהחטא שהודע אליו שחטא הנה ראוי שיהיה קרבנו הקרבן הבא על החטאים הגדולים אשר הם למטה מהחטאים שיתחייב עליהם חטאת ובמה שהוא בזה התואר הוא אשם ולזה יהיה דינו דין אשם מעילות ואשם גזלות שהם באים על החטאים הגדולים אשר הם למטה מהחטאי' שיתחייבו עליהם חטאת והנה היו המנחות הנאפות באות פתים לא מצות שלמות כי פתיתת המצות יורה על ההפרדה שתהיה מצד החומר ולזה היה הקומץ הבא מן הפתיתים ההם מודה על החומר ובאה עמו לבונה להורות על הצורה המדברת כמו העניין בקטרת הסמים לפי מה שביארנו בפרשת ויקחו לי תרומה ובזה קבץ זה הקרבן תועלת העולה באופן מה כי הכונה בו שצורתו וחמרו ישים לעבודת השם יתעלה ובבאה עמה שמן להעיר על שבנבחר שבעניינים החמרים ישתמש לעבודות השם יתעלה כמו העניין בהקטרת החלבים מהחטאת ונאכל שיירי המנחה לכהנים במקום קדוש לסבה בעינה אשר היה בשר החטאת נאכל לכהנים והנה היתה מנחת כהן גדל התמידיית והיא מנחת של כהן גדול באופן שנזכר להעיר על הכונה בעינה אשר תעיר עליה תמיד של שחר ותמיד של בין הערבים וכבר נזכר זה במה שקדם והנה היה עמה לסבה הנזכרת לבונה כמנחה והיה בה רבוי השמן למעלה זה הקרבן והיה פתים לבונה בעינה שהיה תמיד המנותח לנתחים והיתה כלה נשרפת כמנהג העולה שהיא באה עמו ועוד שלא היה ראוי שיהיה שירי המנחה הזאת לכהני' כי לא יתכן שיעשה זה להישרה שיתקרב אל הכהנים ללמוד דרכי התורה כמו הענין במנחה הנאכלת ובחטאת ובאשם כי הוא מהם והוא עם זה היותר נבחר שבכהני' וזה ממה שיוסיף הרחקה בזה ולזאת הסבה בעינה היתה כל המנחת כהן כליל אלא שכבר היה עמה קומץ לבונה כי זה מחק המנחה כמו שנבאר בתורת המנחה אלא אם נתבאר בה שלא ישים עליהם לבונה כמו הענין במנחת חוטא ובמנחת סוטה והנה מנחת הסולת היה עם שמן ולבונה כמו הענין במנחות הנאפות לסבה ההיא בעינה ולא הוצרך בה לדבר יעיר על ההפרדה שתהיה מצד החמר כי הסלת בעינו יעיר על זה כי הם חלקים נפרדים ואין שם מה שיקשור אותם וכן הענין במנחת בכורים שהיא גרש כרמל ובאה עם שמן ולבונה והנה גרשה יורה על ההפרדה כי חלקיו נפרדים קצתם מקצת ואין שם מה שיקשור אותם. והנה לא היתה במנחת חוטא לא שמן ולא לבונה מפני שהיא חטאת כמו שאמרה תורה לא ישים עליה שמן ולאיתן עליה לבונה כי חטאת היא וזה שהחטאת הוא מעיר על הדברים החמריים לא על הצורה ולזה היתה זריקת דמו למעלה על ארבע קרנות מזבח העולה כמו שזכרנו ולזה היתה שם לבנה לפי שהקטרתה מעיר על הצורה לא היה עמה שמן שאין אלו העניינים החמריים אשר עליהם בא זה הקרבן באופן שיתוארו בשהם מיטב הפעולות החמריות אשר ישתמשו בהם להגעת המושכלות אבל די בהם שישתדל החוטא שיסיר המרי מהם ושיהיה השתמשו בהם לעבודת השם יתע' כמו שזכרנו בכונה הזאת דם החטאת והנה היתה הסלת שירה על ההפרדה שהיא מצד החומר והנה נאכל שירי המנחה הזאת לזכרי כהונה במקום קדוש לסבה בעינה אשר היה נאכל בשר החטאות לזכרי כהונה ואמנם מנחת סוטה לא היתה לכפר אבל היה הכונה בה להביא הענש על האשה אם נטמאת כמו שאמר שם כי מנחת קנאות היא מזכרת עון ולגנות העניין ההוא היתה נעשית המנחה ההיא במגונה שבפני' כמו שנבאר שם בג"ה ואולם השמלי' מפני שאינם באים על החטא לא היתה שחיטתם בצפון ולפי שהיתה נאכל לבעלים היה קדשים קלים כי לא יתכן שיאכלו מקדשי קדשים כי אם זכרי כהונה והנה הסבה בהיותו נאכל לבעלים קצתו וקצתו לכהנים וקצתו למזבח להורות על שזה האיש מכבד השם יתעלה ויודעיו ממה שחננו השם יתע' ושהוא מורה שכל הטובות מאתו ולזה יתקרב אליו וליודעיו כפי היכולת ויתקרב אליהם ויחלק לו מטובתו עד שיאכלו יחד על שלחן אחד ולפי שזה ההתעוררות יבא לאדם מצד הצורה היתה זריקת דמו בחלק השפל מהמזבח וסביב באופן שיורה על הצורה. ובזה האופן יהיה קרבנו נרצה ולזאת הסבה היה מניף קרבנו להשם יתעלה וליודעיו בהולכה והבאה והעלאה והורדה להורות על שהשם יתעלה משגיח בעליונים ובתחתוני' בכל פנות שהם בו והנה בזה עוד הערה על מציאות הצורה אשר תישיר השגתה בשיש בכאן צורה ראשונה היא שכל וזה כי החזה אשר תיוחס אליו התנופה הוא מתנועע בב"ח ההולך על ארבע בהולכה והבאה לשאוף האויר הקר אשר בסבתו יתקיים החום היסודי בלב כמו שיתבאר בטבעיות והשוק אשר תיוחס אליו התרומה הוא מתנועע בהעלאה והורדה ובזה האופן תשלם ההליכה לזה הב"ח ובהיות הענין כן שיש לב"ח התחלה להתנועע בצדדין הפכיי' בכל מיני ההפכיו' הנה ידענו שאין הסבה זה כובד וקלות כמו העניין בתנועת היסודות כי מה שזה דרכו לא תהיה לו כי אם תנועה אחת ממיני התנועות לא כלם ובכלל הנה זה יורה על מציאות הנפש וממנה השתלשל העיון אל הצורה הראשונה שהוא האלוה ית' ועוד כי אלו התנועות יביאו על העיון במניע הראשון שלא יתנועע וזה כי עם שאלו התנועו' מורות על תנועת המתנועע מעצמו והוא הבעל נפש שיעיר על מציאות השם יתעל כמו שיתבאר בטבעיות הנה הם מורות גם כן על כל מיני התנועות הפשוטות וזה כי ההנפה מפני היותה לפני השם ר"ל שפני המניף הם לצד המערב הנה היתה ההולכה ממזרח למערב והבאה ממערב למזרח ואילו הן צדדי תנועות הגלגלים כי קצתם מתנועעים ממערב למזרח כמו שהתבארה בספרי התכונה וכבר תמצא זאת התנוע' תמידית לבעל חי ר"ל תנוע' מה שהתמיד היותו נמצא כמו הענין בתנועת הגרמים השמימיים והתרומה היתה כוללת התנועה מן האמצע ואל האמצע והם התנועות הפשוטות אשר תמצאנה ליסודות והיא תמצא לשוק פעם ופעם לא תמצא כמו הענין בזה ביסודות ר"ל שהם ינוחו פעם ויתנועע פעם וכבר ידעה כי מהתנועות האלו ילקח מופת חזק על מציאות המניע הראשון כמו שהתבאר בטבעיות ובמה שאחר הטבע. והנה היתה התנופה ע"י הכהן בידי הבעלים כאלו הכהן יישיר הבעלים אל השגת זה הדעת האמתי יתקרבו אליו הבעלים והיה הכהן לוקח חלק ה' יתע' וחלקו מן ידי הבעלים להעיר הבעלים מרצונם נותנים לשם יתע' ולכהנים ובעבור זה עשו זה הקרבן להתקרב לשם יתעלה וליודעיו למען יישירום להשיג בשלמות כי מהשם ית' יושפעו כל הטובות ולפי שה ההתעוררות להבאת זה הקרבן לא יהיה כי אם מצד הצורה ולא הגיע גם כן למעלה העולה והמנחה עד שיהיה שם מה שיורה על שלא ישתמש בחמריות כי אם להשלמת השכל ולעבוד השם יתעלה לא היה הלחם הבא עם תודה זבחי השלמים פיתים כמו הענין במנחה הנאפת בתנור או במרחשת או במחבת אבל לחם שלם ומצות שלמות ולהיות השלמים קדשים קלים לא הקפידה התורה בזמן אכילתם שיהיה נפסל בלינה כמו הענין בשאר הקדשים והקפידה התורה בזה בזבח התודה לפי שבו מהשלמות יותר ממה שימצא בשאר זבחי השלמים עד שלא יחסר עמו דבר ממיני הלחם ולזה ראוי שידוקדק יותר בתקונו שיהיה בשלם שבפנים עם שכבר אפשר שיהיה הבאת התודה על הטובות הנפשיות והשלמים על השמחות והטובות הגופיות ולזה היו שלמי שמחה ושלמי חגיגה במועדים אשר צונו לשמוח בהם ולחוג בהם ונמצאת התודה באה על קדוש העיר והעזרות כמו שנזכר בעזרא או תהיה התודה על נתינה ההוראה לשם יתעלה במה שהשפיע מהטובות כשיתעורר בעל הקרבן בזה בעצמו. והשלמים באה על עניני שמחה למען נזכור השם יתעלה בעת משמחות האלו הגופיות כמו שאמר וגילו ברעדה ואמרו ז"ל במקום גילה שם תהא רעדה כי רוב השמחה יביא אל הבעיטה בשם יתעלה ולזה יצטרך אל זה הקרבן ואיך שיהיה מזה הנה התודה היא יותר נכבדת ולזה הקפידה התורה בענינה יותר ולזה היה חלק הכהנים החזה והשוק כי מהיישרה אשר תהיה לבעלים במה שתעיר עליו זאת התנופה והתרומה תהיה להם מצד הכהנים במה שיודיע אותם מהדעות האמתיות בזה ולזה היו שני אלו האברים אשר תמצאנה להם אלו התנועות בטבע לכהנים והנה היתה האליה מן הצאן קרבן למזבח עם שאר החלבים כחטאת ואשם והשלמים להיותה החלק השמן יותר מהבעל חי וכל שכן בארץ ישראל כי שם ימצא מהשומל מאד באליות הכבשים ולזה היתה הסבה בהיותה נקטרה למזבח הסבה בעינה אשר יוקטרו בעבורה שם החלבים וראוי שנעיין למה היו נקטרין שם שתי הכליו' והיותרת עם מעט מהכבד כי זה איננו ממיטב הבעל חי ההוא והשמן שבו אלא הענין בו בהפך ונאמר כי זאת החקירה ואם היא קשה מאד הנה אפשר שנשלי' הסבה בה במה שהקדמנו בזה וזה שכבר בארנו שההערה בהקטר' אלו החלבים לשם יתע' הוא שישתמשו בעבודת השם יתעלה במיטב הדברים החמריים והוא מה שהיתה מהם מיישיר לשלמות השכל להשכיל ולדעת השם יתעלה כפי היכולת ומה שבזה התואר הם ההשגות החושיות שנקנה מהם המושכלות הראשונות עם ההשגות כשנפשיט מהם המשיגים ההיולאניים שהיו בהם הדברים המושגים פרטיים כמו שהתבאר במקומות' הנה העירה התורה על זאת הבריר' וההפשטה באלו הדברים שצותה להקטירם מן החלבים וזה כי הכליות הוא אחד מן האברים אשר בהם יופטו מדם הכבד מה שבו מן המותרות והשמרים כדי שישאר הדם בכבד נקי מן השמרים כמו שהתבאר בטבעיות. והיותרת גם כן יבדיל כלי המותרות והם המעיים מהאברים הנכבדים העליונים והם הלב וכבד והראה וכאלו יעיר בזה אל שיפליג העיון בלקיחת אלו ההקדמות הראשונות מהמוחשות שלא נקח דברים המקריים תמורת העצמיים עד שנבדיל הדבר המקרי מהעצמי. והדבר המדומה מהמושכל כי בזה נתישר אל הנכונה במושכלות ויהיו נשמרים מטעיות הדמיון אשר ירחיקו מהנכונה בהרבה מהדברים והנה בחרה התור' הכליות מבין שאר האיברים אשר תשלם להם הברירה לדם מכבד כמו הטחול והמרה מפני לקחה החלב שעל הכליות ולזה היו הכליות נלקחים עמו והנה לא היה בשלמים עוף כי לא יתכן למיעוט כמותו שיאכלו ממנו יחד הבעלים והכהנים והשם יתעלה ר"ל המזבח וזה מבואר מעצמו והנה היו חטאות הצבור והנשיא שעיר לפי שכבר נעתק הענין בהם למעלתם אל שיהיה החטאת זכר ולזה חוייב לגנות הענין שבא עליו זה הקרבן שימצא בו הפחיתות מצד אחד ולזה היה חטאתם מן המין הפחו' שבמיני הבהמה אשר יקריבו מהם קרבן רוצה לומר מן העזים ולזה תמצא בחטאת יחיד שהקדימה התורה שעירה לכשבה לבקשת התורה שיהיה זה הקרבן פחות מאוד לגנות הענין אשר הוא בא עליו. ואולם קרבן כהן גדול היה פר למעלתו במעלה במה שהיא מעלה אנושי וכן קרבן בית דין שטעו בהוראה ועשו רוב ישראל על פיהם אלא אם היתה השגגה בע"ז שאז יביאו שעיר מצד עצם ע"ז כמו שאמר ולא יזבחו עוד את זבחיהם לשעירי' ואולם האשם לא היה בא רק מהצאן והיה זכר להיות הגנות אשר בענין שבא עליו האשם למטה מהגנות אשר עליו בענין החטאת. ולא יבא מהעזים ולא נקבה עם שהתורה כונה בו להסר ממון החוטא ולזה צותה שיהיה בא בכסף שקלים והוא מבוא כי הזכר מן הצאן הוא יותר יקר ממה שיבא מן העזים וכל שכן בארץ ישראל אשר נמצא זה השומן המופלג באליות הצאן והנה הקפידה התורה במחשבות בענין הקרבנות בזה האופן הנפלא הנזכר בפגול לכבוד הקרבנות כי כמו שחוייב בקרבנו' שיהיו תמימים וישאכלו בעת היותם יותר נבחרים. ושתהיה הקרבתם על יד הבלתי בעלי מומין. והטהורה מזאת המשפח' הנכבדת שנבדלו לעבודת השם יתע' במקום המיוחד לזה והוא בית המקדש ובבגדים המיוחדים לזה כן תחוייב לא שתהיה מחשבתם במה שיחסר מעלת הקרבן.ועוד כי רוב התועלת אשר בקרבנות הוא מפני המחשבות כי ההערות אשר זכרנו בענין הקרבנות התחלתם היא המחשבה וזדה כשנחשוב בענינם למה היו בזה האופן והמחשבה ההיא תביא אל מה שאליו היתה הכונה בהקרבת הקרבנות וכבר העירנו מה שהקפידה התורה באלו המחשבות שלא נחשוב שלא יהיה מרי במחשבות המגונות אחר שאין בהם מעשים ונתיר מפני זה לשלח מחשבתנו בענינים הבלתי ראוי' כי המחשבה היא סבת החטאים וזה כי האדם יחשוב בדבר המגונה ואחר יתעורר לעשותו ויעשהו ולזה אמרו רז"ל הרהורי עבירה קשים מעבירה כי הם סבת העבירה והאדם יקל בזה לחשבו שאין זה חטא והנה בא הצווי לשרוף פסולי המוקדשים במקום הקדש למעלת הקדשים ולכבודם ולפי שדם החטאת יזרק באופן מורה על החומר החמירה התורה בו שאם הוזה ממנו על הבגד יתכבס במקום קדוש לגנות ענינו ולהורות שהוא נושא המרי עליו ולזה לא יתכן שישאירו ממנו רושם בבגד וכן לגנו' ענינו נפסל החטאת אם הובא ממנו אל הקדש פנימ' להרחיק מה שיעיר על השלמות והנה לא הושם בבגדי כהונה שום בגד ברגלים לפי שמתנאי הכהונה בגדי כהונ ובית המקדש וכמו שחוייב שלא יהיה דבר חוצץ בין בשרם לבגדי כהונה שנאמר ומכנסי בד יהיו על בשרו כן חוייב שלא יהיה דבר חוצץ בין בשרם ובית המקדש בהולכתם הדם והאברים ובשאר העבודות. והנה היה אש מזבח הקטרת לקוח מכעל המזבח העולה להורות על שההפסד יקרה לאדם מצד מה שילך ממנו מדרגת החומר לא מצד הצורה ולזה היה לקוח ממזבח העולה שיורה על הפסד החי המרגיש שהולך מדרגת החומר מהצורה המדבר והנה לא היה נחלק מזבח הקטרת כמו החלק מזבח העולה לפי שההפסד אשר יהיה בו מציאו' הנפש המדברת על שלמותה בהפרדה מהחמר ולזה היו מקטירים שם הקטרת כמו שבארנו במה שקדם והנה כמו שהיתה מערכת האש שיקחו ממנו אש מזבח הזהב זולת מערכת אש הקרבנות להיותו יותר קדוש ויותר קרוב מקדש הקדשים כן היה מחוייב שתהיה שם מערכ' שלישית לקטרת הנכנס לפני לפנים והיה ראוי שתהיה זאת המערכה ביום הכפורים לבד והיה בהכרח היותר מערבית במזבח העולה וזו היא הסבה בהיות שם ארבע מערכות ביום הכפורים והנה באש התמידיי' שהיה במזבח העולה שלא היו מקטירים בו דבר אחשוב שתהיה ההוראה בו על החום היסודיי אשר בנמצא נמצא שהוא סבת קיומו וזה כי כמו שהיה בעולת תמיד של שחר רמז אל ההויה ותמיד של בין הערבים רמז אל ההפסד כמו שהתבאר בפרשת אתה תצוה כן היה שם אש מורה על ההויה והוא אשר לא יקטירו בו דבר. ואש מורה על ההפסד והוא אש המערכה אשר עליו תהיה ההקטרה והנה היה זה נאות למה שימצא מזה כי החום הנכרי תמצאנו תמיד כלי להפסד והחום היסודיי כלי להויה ולקיו' ושני מיני החום האלו יתחדשו מיסוד האש לפי מה שיתמזג בו משאר היסודות ההפכים כמו שיתבאר למי שעיין עיון מעט בטבעיות' והנה באה האזהרה שלא לכבות אלו האשים להורות על תמידות עניינם מצד הסבות התמידיות אשר שם השם יתעלה בהם ביום ברא זה המציאות כן הסבות המתחדשות זה באמצעות הגלגל הנוטה הם שבות בסבות על ענין אחר אולי היתה הכונה בהקרבת מלח על כל קרבן שלא נחשוב עניין הקרבנות דבר תפל שאין בו טעם ולזה בא עמם המלח להורות שיש בעניינם טעם כבר תמצא תפל מה שהוא בלי סבה ובלי טעם אמר ולא נתן תפלה לאלהים והתפל הוא הפך המלוח ולזה יערנו עניין המלח הבא עם הקרבנו' על שנבקש טעמם נעמוד מפני זה על כוונתם ואפשר שיהיה בה סבה אחרת זולתי מה שזכרתי. ובכאן נשלם מה שיעדנו לבאר בענין הקרבנות לפי מה שאפשר לנו בזה המקום ואולם המאמר בקרבנות הנשארים וביתר הדברים אשר באלו הקרבנות יהיה בג"ה בהגיענו אל מקומם וראוי שתדע שהתורה תשתמש בעניי' אחד לתועלת רבות כמו שהתבאר בתורה מעניין השבת כמו שזכרנו במה שקדם והנה אחת מהכונות היתה להרחיקם ממה שגדלו עליו מקרבת הקרבנות לע"ז כמו שזכרה זה התורה בפרש' אחרי מות בביאור אמר שם למען אשר יביאו בני ישראל את זבחיהם אשר הם זובחים על פני השדה והביאום ליי' וגו'. ולא יזבחו עוד את זבחיהם לשעירים אשר הם זונים אחריהם. ולזה גם כן ידמה שתהיה אחת מהכוונות בעשיית המקדש והבדל הכהנים לאלו העבודות אלא שעם כל זה איננו ראוי שלא יהיה בענינים תועלת בעצמות שאם היה הענין כך לא היה נימוס אלא העבודות בזה האופן הנפלא אבל תהיה הצואה להקריב הקרבנות ליי' לא זולת זה ובכלל התחכמה התורה שיתחדש מהם תועלת בעצמות כמו שיעשה הרופא השלם כשירא' העלול בלתי מקבל מוסרו בהנהגתו הרעה הנה ישתדל שנדבר הרע בעינו יגיעהו אל הבריאו' אם היה אפשר לו זה משל זה שאם רצה לאכול מאכל בלתי נאו' לו מצד חוליו יחבר אליו הרופא דברים יסירו רוע המאכל ההו' וישיבוהו באופן שירפ' חוליו ולזה סדר הש"י נימוסי אלו העבודות בקרבנות בזה האופן הנפלא להעיר על זה העניין הנפלא אשר העירונו עליו וכן היה סדור ענייני המקדש בזה האופן הנפלא להעיר על מי שהערונו אליו מענינם כי ענייני אלו הדברים בעצמם מעירים אל מה שיטיב העיון בהם שזאת היתה הכוונה בהם עם הודאת בעל דין לא נצטרך לעדים ועם זה היה בזה תועלת אחר להתמיד השלמות האנושי באומה הזאת כשהיה שם משפחה מיוחדת לעבודת יי' המשתדלים בעיון תמיד ובחכמת התור' עם מה שהישיר אותם מה שבמקדש ומענין הקרבנות אל השלמות בהערות נפלאות אשר יעירו המעיינים בהם ומזה הצד גם כן יהיה תועלת שלישי בעניין הקרבנות והוא כי בהם ישיגו הכהנים עם שאר מתנות כהונה מה שיצטרך להם מהטרף והלבוש ויהיו יותר מוכנים אל שישלמו בעיון ובזה ישלם לישראל הגעת השלמות בכלל בעינו אשר היו מתרחקים ממנו והם הקרבנות לע"ז ישתבח צור הכל כעל כל אשר גמלנו ורב טוב לכל ישראל ואנחנו נותנים לו תודה על מה שגלה לנו ברחמיו וכרוב חסדיו מסבות אלו העניינים העמוקים אשר לא מצאנו בהם דבר לזולתנו יתכן שתהיה לנו השגה ופתח להשגתם אבל מצאנו מה שירחיקנו מחקור בהם בזה האופן והנה עזרנו השם ושלמנו המאמר בזה הזמן המועט עם רוב הטרדות אשר לנו והנה השלמנו המאמר בזה בסוף מרחשון של שנת תשעים ושלשה לפרט האלף השישי ליצירה ישתבח יוצר הכל אשר נתן כזאת בלבנו:
@259 **וראינו** לבאר בזה המקום הסבה במה שזכרה התורה בענייני הטומאות והטהרות קודם שנשלים ביאור מה שנזכר בתורה מהם כי עמידתנו על הסבה בזה יישרנו לעמוד על אמתת הביאור במה שזכרה התורה מזה ונאמר שכבר התחכמה התורה להעמידנו על אמתת הנמצאות לפי מה שאפשר כי זה פרי כל אדם אשר אין לו יתרון מבלעדיו ולפי שהשרש היותר גדול בזה הוא שנאמין במציאות הצורות שאם לא נודה שתהיה בכאן צורה לא תהיה בכאן חכמה כלל כמו שזכרנו בתחילת ביאור זה הספר הנה הישירתנו התורה בזה האופן הנפלא שזכרנו בעניין בית המקדש והקרבנות והנה סמך להם ענייני הטומאה והטהרה כי הם מעירים אותנו לזה העניין בעינו ונזכיר תחלה מה שנבאר בתורה בעניין הטמאות והטהרות כדי שיתכן לנו לתת הסבות בזה כי ידיעת המציאות בדבר קדמת בהכרה לידיעת סבת המציאות הוא וכל שכן בכמו אלו הענינים והנה הטמאות שנזכרו בתורה מצאנו שהחמורה מכלם היא טומאת מת והיא מטמאה במגע ובמשא ובאהל והמתטמא ממנו הוא אב הטומאה ויטמא טומאת שבעה ואחריה מצאנו טומאת מצורע יותר חמורה וזה שהמצורע מטמא בביאה ובמגע ובמשא והמטמא ממנו הול ולד הטומאה ויטמא טומאת ערב ומטמא משכב ומושב וישימם אב הטומאה ואחריה טומאת זב וזבה ונדה ויולדת שהם מטמאים במגע ובמשא והמטמא מהן הוא ולד הטומאה ומטמאים משכב ומושב וישמום אב הטומאה ואינם מטמאין בביאה כמו שיטמ הצרעת כל הבא אל הבית אשר הוא בו ואחריהן הטמאות הפורשות מהן כמו משקה זבה ונדה ויולדת וזב ובועל נדה וזבה ויולדת וכבר נתבאר דינם במקומם. ואחריהם טומאת נבלת בהמה שהיא מטמאה במגע ובמשא טומאת ערב. ואחריה טומאת שמנה שרצים ושכבת זרע שמטמאין אדם וכלים במגע ואינם מטמאין במשא ולא יטמא המטמא מהם באופן שיטמאו בגדיו. ואחריה טומאת נבלת עוף טהור שיטמאו בהיותה בבית הבליעה לטמא בגדים ואינה מטמאה במגע ובמשא ובקבול הטומאה מצאנו מדרגות חלוקות וזה שאדם וכלים לא יקבלו טומאה כי אם מאב הטומאה ויטמאו זולתם כשנטמאו. רוצה לומר שהם יטמאו האוכלין והמשקין המיוחדים לאדם ואמנם האוכלין והמשקין שיהיו חולין יקבלו טומאה מאב הטומאה או מולד הטומאה אלא שאליהם תכלה זאת הטומאה בחולין איך שיקבלוה ואמנם אוכלי קדשים הם יותר חזקין לקבל הטומאה ומה שהיתה קדושתם יותר חזקה יגדל בהם זה הכח ולזה תמצא שהשני עושה שלישי בתרומה והשלישי עושה רביעי בקדש ובעניין הכלים מצאנו הבדל וזה שכלי חרס אינו מקבל טמאה כי אם מתוכו וכלי עץ ובגד ועור ושק ועצם מטמאין אפילו מגבם וכלם אינם מקבלים טומאה אם אין להם בית קבול ואולם כלי מתכות יקבלו טומאה פשוטיהם ומקבליהם וכלי זכוכית אינם מקבלים טומאה ולא כלי אבנים וכלי גללים וכלי אדמה לפי מה שנראה מדברי התורה. וטהרה אלו הטמאות מצאנו בטמאת מת בשיזו ביום השלישי וביום השביעי ממי החטאת שהושם בו מאפר הפרה כשיטבלו בו האזוב וממנו תהיה בו ההזאה על המטהר ואחר יטבול במים ויכבס בגדיו ויטהר והפרה ההיא היא אדומה בכללותה בלי מום ושלא ישתמשו בה לתועלת האדם כלל וכבר ישחטנה חוץ למחנה ישראל וישרפוה שם וישליכו אל תוך שרפת הפרה עץ ארז ואזוב אגודים בשני תולעת וישרפו יחד עם הפרה ואחר יקחו האפר ההוא ויקחו מים חיים שלא השתמשו בהם כלל בכלי ובו נותנים מזה האפר ואחר יזו מהמים ההם על המטהר באופן הנזכר וכל המתעסקים בפרה עד שנשרפה יטמאו וטעונין כבוס בגדים והנוגע במי חטאת שלא לצורך הזאה טומא ומתטמאים במשא גם כן אם היה בהם שיעור הזאה ונשאום שלא לצורך הזאה וזו הפרה היא חטאת כמו שנזכר שם וישרפוה עם עורה ועם פרשה כמשפט חטאות הנשרפות אך לא ישחטו אותה בעזרה ולא יקטירו החלבים על מזבח העולה ויזה מדמה כשנשחטה במקום ההוא נכח פני האהל שבע פעמים. וטהרת המצורע היא גם כן באופן מתיחס לזה וזה שכבר יקחו שתי צפורים חיות טהורות וישחטו אחת מהם אל מחוץ למחנה וישפוך דמו אל כלי חרש על מים חיים שלא השתמשו בהם כלל ואחר כך יקחו עץ ארז ואזוב אגודים בשני תולעת ואחר זה יקשרו עמהם בשירי הלשון של זהורית הצפור החיה ויטבלו הצפור החיה ועץ הארז והאזוב ושני תולעת במים שנתערב בהם דם הצפור ויזו מזה שבע פעמים על המטהר חוץ למחנה ואחר זה ישלחו הצפור החיה על פני השדה ואחר זה יגלח המצורע כל שערו ויטבול ואחר יבא אל המחנה ואולם הקרבנות שיקריב אחר זה להשלים הטהרה אין צורך לנו לזכרם בזה המקום וכבר נתן הסבה בזה במקומו בגזרת הצור וראוי שנדע שזאת הצפור השחוטה היא חטאת ולזה נשחטה מחוץ למנחה והיה ממין פחות והוא העוף ומהפחות שבו ולפי שאינה נשרפת יחוייב שתהיה נקברת בכללותה עם נוצתה ועם פרשה באופן שלא יהיה בה תקלה וכזה מצאנו בטהרה הבית המנוגע שיעשה בכמו זה האופן בעינו וכבר מצאנו בטהרת הזב שהוא במים חיים רוצה לומר במי מעיין במקומו ובזה קצת התייחסות עם טהרת המצורע וטומאת מת כבר דקדקה התורה בהזאה הנעשת לטהרתם שתהיה במים חיים ומצאנו בו קרבנות להשלים הטהרה וכן העניין בזבה ויולדת רוצה לומר שהם יקריבו קרבנות להשלים טוהרתם אחר שטבלו אלא שלא דקדקה התורה בזה שיטבלו במעיין וביתר הטומאות לא מצאנו בהם קרבן אך תהיה הטהרה בהן בטבילה לבד זה הוא מה שראינו להקדימו בזה המקום מענין אלו הטמאות והטהרות וכאשר התישב לנו זה כלו מדברי התורה ראוי שנבאר סבות זה הענין כמו שידענו ונאמר כי מפני שהאדם המת נעדרה ממנו הצורה האנושית ובסבת הפקדה השיגהו המות הנה טמאה אותו התורה בתכלית כדי שנתעורר מפני זה לדעת כי המעלה והכבוד הנמצא באדם על כל המורכבות איננו מפני החומר אבל הוא מפני הצורה וזה שאנחנו לא נראה שנפקד מהמת דבר זולתי הצורה כי לו כל האיברים לא נפקד מהם כי אם הצורה אשר ממנה יסודרו פעולותיהם וזה גם כן יעמידנו על שהחמר חסר מאד ביחס אל הצורה ואמנם שאר הבעלי חיים המתים הנה הבעל חיי ההולך היותר שלם לקורבה חמרו מחמר האדם טמאה אותו התורה גם כן אך למטה מטומאת האדם המת כי הצורה שנפקדה ממנו היא שפלה מאד מהצורה שנפקדה מאדם המת והעירנו בזה כי אין הרצון באלו הבעלי חיים כי אם בעבור האדם למה שיקח מהתועלת בהם וכשנפקדה מהם צורתם נפקד מהם זה התועלת וזה עם שהישירנו לעמוד על מציאות הצורה הנה יישירנו לעמוד על שבכאן צורת יותר נכבדות קצתם מקצת וכאשר נתבונן בזה ונמצא צורת הב"ח ההולך באדם עם המצא בו הצורה שבה נבדל מהם נדע כי צורת האדם הולכת במדרגת השלמות לצורת בח' ההולך ולזה תמצא שבשר בהמה השחוטה אינו מטמא כלל כי כבר ימשך ממנו התועלת המכוון בו לאדם והוא שכבר יזון ממנו ולזאת הסבה תמצא השיעור בטמאת הנבלה כשעור האכילה והוא כזית להורות על הפקד ממנו התועלת המכוון בה לאדם ואולם הב"ח ההולך החסד והם השרצים הנה היותר שלם מהם והם השמנה שרצים שזכרה התורה טמאה אותם התורה אך למטה מטומאת נבלות הבהמה הטהורה כי הצורה הנפקדת מהם היא חסרה ביחס אל הצורה שנפקדה מנבלת הבהמה כי הם יותר עבי החמר כמו שבאר' והנה יחס החמר אל החמר הוא יחס הצורה אל הצורה ואולם שאר השרצים ההולכים לרחק חמרם מחמר האדם לא טמאה התורה נבלתם כלל להעיר על חסרון צורתם והנה במעופף לא טמאה התורה נבלת המינים הבלתי נאכלים ממנו נבלתם כלל להעיר על נאכלים ממנו ולא נבלת נאכלים משרץ העוף לחסרון צורתם ומפני היות חמרם רחוק מאד מחמר האדם ואמנם נבלת המינים הנאכלים היותר שלמים ממנו תטמא כשתאכל לא במגע ובמשא להעיר שאלו המינים הנאכלים הם יותר שלמי החמר והצורה מהשאר ואם כולם חסרים מאד וחמרם רחוק מחמר האדם ולזה יטמאו בהאכילה לבד עם שבה הערה אל שנפקד' מהם במותן בזה האופן התועלת אשר בעבורו נמצאו רוה לומר היות האדם נזון מהם וזה עם שיישירנו למצאות הצורה הנפקדת מזה העוף במותו הנה יישירנו למצאות הצורה הנפקדת מזה העוף במותו הנה יישירנו גם כן אל שהצורות תתחלפנה קצתם מקצת בכבוד וזולת כבוד והשם קצתם בעבור קצת ואולם כדגים לא טמאה התורה נבלתם כלל לחסרונם ולרוחק חומרם מחומר האדם בתכלית מה שאפשר מסוג החי וזה גם כן יישירנו לעמוד על שהצורות מתחלפות מאד בשלמות והחסרון ולזה לא תטמא נבלת זה הסוג מהחי עם הפקד ממנו צורתו במותו לחסרון צורתו וכבר ידעת אתה המעיין אמיתת כל זה ממה שהתבאר בטבעיות וזה ששם התבאר שהחי היותר שלם הוא האדם ואחריו החי ההולך ואחריו המעופף והיותר חסר מכלם הוא המימיי והוה לעצם מעלת האדם היה קצת המותרות והעפושים החמריים המתחדשין בו מטמאין מה שאין כן בשאר בעל חי והחמור מאלו הוא הצרעת כי הוא הפסד נפלא מתחדש מפאת החומר מצד ממשלת החום הנכרי על האיש הזה ומשול הכוחות המתפעלו' על הפועלו' ויתחדש מזה הפסד בכללות הדם ויתפשט מפני זה בכללות הגוף ולהעיר שזה ההפסד בא מפאת החומר טמאה אותו התורה בזה האופן הנפלא שהוא מתיחס לטמאת המת אשר אין בו כי אם החומר לבד ולזה גם כן היתה טהרתו מתיחסת לטהרת טמא מת וזה יישרינו אל שהטוב בדברים מצד הצור והרע וההפסד הוא מצד החמר עם שבזה תועלת שירחקו מן המצורע שאר האנשים כי זה החלי הוא מהחוליים המתדבקים ולזה צותה התורה שיהיה מחוץ למחנה ישראל מה שאין כן במת ואמנם זוב הזב הוא מהמותר הזרעי כשנעדר הבשול ויורה על זה שהוא כלובן בצה המוזרת והשכבת זרע הוא בלובן ביצה הבלתי מוזרת כי דבקות והעובי אשר בשכנת זרע מורה על טוב הבשול וההצטמקות בכלי הולדה ולפי שנעדר מזה המותר הכח על ההולדה לחולשת החומר היסודי והעדר כשולו רוצה לומר שנפרד ממנו מה שיתחדש בו ממנו איש מאישי האדם טמאה אותו התורה בזה האופן המתיחס באופן מה לטומאת מת וכן זוב הזבה הוא מהעדר הבשול בדם הבא ממקורה אשר לא יאות מפני זה להולדה וכן העניין בדם הנדה אלא שזה המותר הוא טבעי באשה ואין העניין כן בזוב הזב והזבה ודם היולדת הוא גם כן בלתי נאות להולדה והוא המותר הדמי ושלא יאות שיזון ממנו הולד לנאוו ולהעדר בשולו וידחהו הטבע בעת הלידה וכאלו הוא דם הנדות והזיבה שהיה ראוי שיצא מאשה בכל ימי עבודה כמו שהבתאר בטבעיות ולפי שאין ההפסד באלו העניינים כהפסד אשר יקרה מהצרעת כי הוא מתפשט בכללות הגוף מה שאין כן באלו ולא יקרה גם כן מהם הפסד לזולתם היתה טומאתם למטה מטמאת צרעת רוצה לומר שלא יצטרכו לצאת חוץ למחנה ישראל ולא יטמאו הבא אל הבית אשר הם בו כי זה ידמה שהיה במצורע לסבב שיתרחקו האנשים ממנו ולא יזוקו בחליו והנה היתה הנדה והזבה והיולדת מטמאה את בועלה בה האופן החמור אשר יטמא בו מפני ההפסד שיקרה בהולדה אם תתעבר האשה אז וכבר הגידו הרופאים שהאשה ההרה בימי נדותה יהיה הנולד מצורע ובכלל הנה אם תתעבר אז הנה יקרה לנולד הפסד נפלא אם צרעת אם מה שידמה לו מההפסדים הנפלאים כמו האש הפרסי ומה שידמה לו כי לא ימשול הכח הפועל אשר בזרע על שיעשה מהדם ההוא חומר שלם הבריאות ואמנם שכבת זרע יטמא גם כן מפני שנפקד ממנו התועלת אשר בעבורו היה והוא ההולדה וזה כלו חוזר אל הסבה אשר בטמאת המת והיתה טומאתו למטה מטמאת הזוב לפי שמהזוב נפקד זה התועלת מצד עצמותו שאיננו ראוי להולדה ואין הענין כן בשכבת זרע היוצא מן האדם כי הוא ראוי להולדה מצד עצמותו אלא שאין עמו המקבל אשר בו יתחזק על ההולדה והנה יטמא האיש והאשה בשכבם יחד שכבת זרע להעיר על שזה הפעל הוא באדם מצד החמר כי אין לאדם זה הפעל במה שהוא אדם אבל הוא לו מצד שהוא בעל חי עם שבזה תועלת להרחיק המשגל שלא ישתמשו בו כי אם לצורך לא לבקשת התענוג כמו שיעשו המון האנשים עם שכבר ישחיתו בהם עצמם וימנעו מהם השלמות האנושי לרוב תשוקתם בזה הפעל המגונה. ובכאן נשלם מה שיעדנו לדבר בו בסבות אבות הטומאה ואולם מה הסבה בטהרתם בזה האופן אשר זכרה התורה הנה ראוי שנאמר בזה לפי מה שיעדנו ונאמר כי מהנראה שטהרתם היה ממה שיעיר על כמו זאת ההערה בעינה אשר זכרנו בטמאות ונתחיל בזה בטהרת המת כי היא להיותה באה על ישראל בכללם ועל הכהנים. היתה ממין היותר נכבד והוא הפר כי חטאת הכהן הוא פר וכן חטאת העלם דבר של צבור ולפי שהמכוון בה להעיר על חמר חסר מאד והוא חומר האדם המת שהוא דומם היתה נקבה כמשפט חטאת יחיד ולזאת הסבה היתה נשחטת חוץ לשלש מחנות ולא היה קרב ממנה דבר על מזבח העולה אבל היתה נשרפת כלה חוץ לשלשה מחנות והנה היו מזים מדמה שבע פעמים נכח אהל מועד שם חוץ לשלשה מחנות להעיר כי זה ההפסד קרה מהכוחות השופעות מהגרמים השמימיים לפי מה שיסד השם יתעלה שישפע שהם ביום הבראם ולהעיר שאין זה מכוון מהם היתה זאת ההזאה מרחוק ממקו' קדש הקדשי והיה זאת ההזאה בדם לפי שהדם הוא סבת זה ההפסד אשר יקרה ממנו המות מצד העפוש שיקרה בו ולזאת הסבה היתה הפרה אדומ' והיה הצמר הבא עם הארז והאזוב אדו' להורו' זאת הפרה על החמר לבד היה הצואה שימנע ממנה בכללות מה שבו תועלת לאדם ולזה היה בלתי נאכל ממנה דבר אבל היתה נשרפת עם עורה ועם פרשה ולזאת הסבה היתה התנאי בה שלא נעשית בה מלאכה כלל לתועלת האדם ולזאת הסבה היתה המלאכה פוסלת בה בכלל מעשיה וגם במי החטאת כמו שיתבאר בפרש' פרה בג"ה ולזה גם כן יבואו המים בהיותן אל הכלי שלא נשתמשו בהם כלל והנה הארז והאזוב והצמר הם מסוג הצומח והפרה מסוג החי והנה יתחילו לשרוף הפרה ואחר ישליכו אל תוך שרפת הפרה הארז והאזוב והצמר להעיר שזה ההפסד קרה לאדם מצד מה שילך ממנו במדרגת ההיולי כאלו תאמר מצד מה שהוא חי וקרא לחי מצד מה שילך ממנו במדרגת ההיולי והוא היותו צומח כמו שיתבאר כל זה בטבעיות ומפני זה נפסדו מהאדם המת כל אלו הצורות אשר הם מתאחדות בו להיותם קצתם שלמות לקצת ולזה יעירנו על זה על מציאות הצורו' על מדרגתם הערה נפלאה ומפני היות הוראה זאת הפרה על זה החומר החסר תכלית החסרון היו כל המתעסקין בו טמאים על חסרון החומר כמו הענין בטומאת מת ולזאת הסבה יטמאו מי חטאת במגע ובמשא כשלא היה זה לצורך הזאה ואמנם כשהיה לצורך הזאה לא היה ראוי שיטמא שאם היה הדבר כן לא תשלם ממנו טהרה וזה הפך מה שכונה התורה בזה. וראוי שתדע שהארז הוא גדול בצמחים והאזוב הוא הקטן כמו שאמר מן הארז אשר בלבנון עד האזוב אשר בקיר והצמר הוא באופן יצמח אלא שאין מציאותו כי אם בהכרח החמר ולזה קשר אלו הצמחים יחד בו להעיר שקצתם יותר שלמים מקצת ושצדותיהם הולכות במדרגת השלמות קצתם לקצת ושכבר ישיגם ההפסד מהכרח החומר לא מצד צורת הצומח עם שבזה הוראה שחלופי הכחות אשר בצמיחה הם סבות ההפסד וזה כי החזון כשהיה באופן שלם יתוסף בו גודל הזן להחליפו בשיעור יותר ממה שיותך ממנו וכשהיה באופן ממוצע יעמוד גודל הזן עד שהגיע העניין אל שלא ימשול על ההזנה כלל ואז יקרה המות בהכרח ובזה יקרה כשהיה המות בסבת חלי רוצה לומר שכבר יחסר כח הזן על שלא ימשול על ההזנה כלל ואז יקרה המות בהכרח ולהעיר על זה גם כן נקשרו שם המינין האלו שהם מתחלפי הכחות מאד בענין הצמיחה. והנה יזו על הטמא מת ממי החטאת שלישי ושביעי באמצעות האזוב שהוא חלוש הכח בצמיחה להעיר אותו שזה ההפסד קרה לאדם מצד מה שהוא צומח והוא מה שילך ממנו במדרג' ההיולי באופן רחוק כי בחולשת זה הכח ובהעדר פעולתו יקרה המות ולזה שב דומם במותו כי בהעדר הנפש הצומח יעדרו שאר הצורות אשר הם לה במדרגת הצורה רוצה לומר הנפש המרגשת והשכל ההיולני והיו במי חטאת מים ואפר שהוא יסוד הארצי אשר בזאת ההויה להעיר שיתנקה מטמאה זה החומר וחסרונו וישתדל בשלמות הנפש ולא יזו עליו מהמים והאפר באמצעות האזוב כי האפר הוא החומר היותר רחוק שיהיה מורגש רוצה לומר היסו הארצי עד שהרבה מהקודמים חשבו בו שהוא החומר הראשון וכאלו גם כן השלים ההודאה בזה כי היסודות הם סבת ההפסד הנמצא במורכבות וזה הוא האמת כמו שהתבאר בטבעיות כי ההפסד לא יגיע מצד הצורה אבל קרה לצורה מצד החמר והיתה ההזאה נשלמה בז' ימים לשלמות מספר השבעה עם שבו הערה אל מה שהיתה ההערה בו בהזאת דם הפרה שבע פעמים עם של אורך הזמן אשר תשלם בו זאת ההזאה יתכן שיעמוד המטהר על הכונה הזאת כמו שזכרנו בפסח מצרים שהיה מקחו קדם לשחיטתו ארבע ימים לזאת הסבה בעינה וכבר תקדם בו ההזאה ראשונה ושניה ארבעה ימים והנה בזה גם כן תועלת ליישב בלב המטהר חוזק זאת הטמאה שהיא באופן מהחזק שלא יתכן שתסור יחד ולזה חייב שתהיה ההזאה פעם אחר פעם והנה יטבול בסוף להשלים טהרתו להערה שזאת הטמאה לא היה כי אם מצד החמר ולזה ירחץ בשרו כי אין ברחיצת הנקות אל הגוף וכשיראה שלא נתלכלך גופו מפני הטמא במת אז יתעורר להבין שהכונה בזה הוא שיתרחק מחסרונות החור וישתדל בשלמות הנפש ואולם טהרת המצורע מפני שהוא חטאת יחיד ולחוזק הוראתו על חמר חסר היה זאת החטאת ממין פחות רוצה לומר מסוג המעופש וממנו היה בלתי ראוי לקרבן כי הקרבן לא יעשה מהעוף כי אם מהתורים ובני היונה והיה זה צפור אלא שהיא טהורה ובחיית על החיות רוצה לומר שאינה טורפה באופן שתהיה ממנה שכמות נאכלת לישראל והנה ישחטוה חוץ לשלשה מחנות מפני חסרון החמר שתורה עליו. ולזה גם כן ישימו דמה בכלי חרס שהוא כלי פחות והיה נפשך על מים חיים שלא השתמשו בו כלל לסבה בעינה שהיה זה בפרה אדומה ולזא הסבה גם כן למד שהכלי חרס ראוי שיהיה חרש שלא נשתמשו בו כלל והנה לא נשרף זה הצפור כי אין אנו צריכין בזאת הטהרה לאפרו כי הפסד שקרה מהצרעת איננו מות אבל הוא הפסד בדם בסבה חלש' חום היסודי ומושל עליו החום הנכרי והנה יקשרו עץ הארז והאזוב בשני תולעת יחד המו הענין בפרה ואחר כך יקשרו עמהם הצפור החיה להעיר שה הפסד בא לחי מצד שהלך ממנו במדרגת החמר רוצה לומר מצד היותו צומח ומפני חלשת הכח הזן בו אשר בו תהיה הצמיחה ולזה היו בכאן מהצמחים השלמים והחסדים כמו שזכרה במה שקדם והנה לא ישרפו בכאן זה הצפור ולא הארז והאזוב ושני תולעת כי זה נשאר קיים על ענינו אלא שכבר קרה לו זה העפו' הנפלא וטהר ממנו והנה הצפור ששחטו להיות החטאת נעשית בזה האופן המגונה ראוי שהפסד בכללה עם פרשה ונוצתה באופן שלא יהנו ממנה ולפי שאינה נשרפת כי לא יזו מדמה בכאן באפר כמו הענין בפרה אדומה הנה יחוייב שתהיה נקברת כדי שלא יארע בה הקלה אם כשיהנו ממנו בני אדם אם כשתהיה מאכל לעוף השמים ולבהמת הארץ ויזו מדמה על המטהר עם המים החיים באמצעות הצפור החיה ועץ הארז והאזוב ושני התולעת להעיר שיתנקה מחסרון החמר אשר בסבתו בא לו זה ההפסד בדמו ולחסרון היותו בעת היות בו זה העפוש לוקח דם הצפור תמורת דמו שהוא חלוש החיות לפי מה שיתבאר בטבעיות וזכרנוהו עם זה במה שקדם. ולזה גם כן היה זה החטאת צפור. ולזאת הסבה ישלחו זה הצפור החיה על פני השדה חוץ מהעיר להעיר שזה החיות החסר שיהיה לאדם בסבת החמר כבר סר ושב לשלמותו וגם כן הנה בשלמות בזה המקום לפי שהיה התכלית בריאות שהוא מצד הצורה הנה יקחו הצפור החיה מבין שאר אלו הדברים הנאגדים יחד המורים על כח הצמיחה כי הוא מורה על מה שילך מדרגת הצורה מהצומח וישלחו אותה להעיר כי הבריאות שהוא הטוב היה מחלק הבריאות אשר במצורע כמו שהתבאר במה שאחר הטבע ר"ל שהבריאות יתחדש לחולה מצד החלק אשר לו מהבריאות שהוא מצד הצורה ובעניין המת לפי שהיה התכלית מות והפסד שהוא מצד החמר היו לוקחין האזוב מבין אלו הדברים הנאגדי' יחד שהוא מורה על מה שילך מדרגת ההיולי והיתה נכפלת ההזאה הזאת שבע פעמים כדי שיתעוררו בזה ההכפל הנפלא אל מה שכוון בזה עם שבה הערה לממשלת הכוכבים על המורכבות אשר בזה העולם ומהם יסודרו להם במקרה אלו ההפסדי' ויסודר מהם בעצם ההנקו' מהם לפי מה שנתן להם מהכח מהשם יתע' לשמירת אלו המורכבות והנה יגלח כל שערו ביום הנקותו מזאת הטמאה לפי שהשער גדל במצורע מזה הדם המעופש ולזה ימצא בו רשם מזה כמו שנזכר בתורה בסימני הצרעת ולזה היה ראוי שיוסר כי הוא כאלו היה מחומר הצרעת ולזה לט יטהר אלא כשישוב להתגלח שנית אחר עבור שבעת ימים כי מה שנשאר מהשערות בשרשיהן בעור כבר יוסר בזאת התגלחת השנית כי השער גדל משרשו ולזה תמצא כי בהתהפך השער ללבן בסבת ממשלת החום הנכרי יתחיל להתלבן משרשו והנה יטבול אחר התגלחת הראשונה והשנית להעיר כי זאת הטומאה חזקה מאד ולזה לא יתכן שתור יחד בפעם אחת אבל תסו' קצתה בטבילה הראשונה וקצתה בטבילה השנית ואמנם הזב לפי שלא היה זה ההפסד בכל גופו אבל כמותר הזרעי שנעדר ממנו התועלת אשר בעבורו היה הנה היה טומאתו למטה מטומאות המצורע ולא יצטרך בטהרתו כי אם טבילה והיתה במים חיים שלא נשתמשו בהם לתועלת להעיר על מה שיעיר זה בטהרת המת והמצורע והיה זה מיוחד בזב ולא בזבה נדה ויולדת ולא בבעל קרי לפי שדם הנדה ויולדת והזבה ואם אינו נאות להולדה הנה לא חסר ממנו דבר נכבד כי דם הנקבה אין לו כח בהולדה כי אם עד שיתבעל כי הוא הולך מדרגת ההיולי מההוייה ואולם זרע הזכר להיותו פועל כמו שנתבאר בטבעיות הנה כשחסר ממנו זאת הפעולה בסבת החמר ראוי שתהיה ההטהרה בו במים חיים ואולם הבעל קרי הנה לא נעדר משכבת זרע תועלת השכבת זרע אם לא במקרה כאלו תאמר מצד שאין עמו המקבל אשר בו יתחזק על ההולדה ולזה לא יצטרך שתהיה טבילתו במים חיים ולפי שזרע הנקבה אין לו מבוא בהולדה כי אם להכין החמר לקבל פועל הזרע הזכר לפי דעתנו כמו שבארנו בביאורינו לספר בעל חי לא היה מטמא כלל וכן דם הנקבה הנאות להולדה והוא הנקרא בתורה דם טוהר איננו מטמא כי הוא פחות מאד ביחס אל זרע האדם בחסרון החומר מהצורה ולזה לא תנהג טומאה בו כלל והנה נשתתפו בעניין הבא' הקרבנות המצורע והזב והזבה והיולדת רוצה לומר שכלם יצטרכו להביא קרבן להשלים טהרתם מה שאין כן בעניין הנדה כי אלו המותרות ואם הם כלם מהכרח החמר הנה הוא בנדה כמו עניין טבעי על צד הנקיון כמו שהתבאר בטבעיות מה שאין כן בזב וזבה וזה מבוא מאד וכן יתבאר שכן הענין ביולדת כי תהיה מפני זה בתכלית הסכנה והנה נשלים המאמר בג"ה בסבת אלו הקרבנות במקומותיהם והנה לא יקבל טומאה שום חי זולתי האדם כי חורת חי נראית תכלית ההראות בחי ולזה לא יטמא מפני אלו הענינים החמריי' אשר יגע בהם ואמנם האדם יטמא בנגעו בהם כדי שיתעורר מפני זאת הטומאה אל מה שיכוון בה. ואמנם הכלים המשמשים את האדם יטמאו באבות הטומאה לבד כי הם לא ישמשו האדם בעצמותם אם לא במקרה מפני תמונתם כמו העניין בכלים אשר ישימו בהם האוכלין והמשקין והתכשיטים והלבוש גם כן אינו מועיל לאדם בעצמותו אלא שהוא יהיה מסך ומסתור מהאויר המקיף ואמנם האוכלין והמשקין והתכשיטים והלבוש גם כן אינו מועיל לאדם בעצמותו אלא הוא יהיה מסך ומסתור מהאויר המקיף ואמנם האוכלין והמשקין יטמאו אפילו מולד הטומאה להיותם משמשים את האדם בעצמותם עד שכבר ישובו חלק ממנו בחזונו מהם וידמה כי מפני היות הכלים המשמשים את האדם מצד מה שילך מהם מדרגת הצורה והוא התמונה הנעשית במלאכה הנה כל נטמאו יתכן שיטמא זולתם מצד שנעדר מהם אז התועלת הנמשך מהם מפני צורתם כמו העניין בשאר הטמאות ואולם האכולים והמשקין הם מפני שלא ישמשו את אדם כי אם מפני מה שילך מהם מדרגת ההיולי לא יתכן שתגיע בהם טמאה לזולתם אם לא היה זה מפני יתרון מעלה האוכלין והמשקין אשר יגעו בהם כמו העניין בקדש והנה לאר יקבלו טומאה האוכלין אלא כשהיו מוכשרין לקבל טומאה בסבת המשקה הנתן להם בסבות האחת כי האוכלין אי אפשר שיוצנע בכלים באופן שיהיו נשמרים מנגיעת הטומאה בהם וזה מבואר מאד בזרעים ואם היו מקבלים טמאה בזולת הבשר הנה יקרה מהם מההפסד בזה הרבה והשנית להעיר כי האוכלין אמנם היו נאותים אל החזון מפני היותם לחים בפועל וכבר התאמת אמתת זה בטבעיות כי מפני הלחות יתפעלו בקלות וישובו אל עצם הנזון ולזה תמצא ההזון בבעל חי באמצעות שוב המזון דם וכן ימצא בצמחים שישוב מזונם מימיי ומצד ההוא יתכן גם כן שיתפשט בכל עורקי הצומח היה שיהיה חי או צומח כי בכלם ימצאו דמיון עורקים יבא בהם המזון לכל חלקי הצומח ולפי שאין האכלין מקבלין טומאה אם לא מצר מה שישתמש בהם האדם לתועלות בהזון היה שלא יקבלו טומאה כי אם בזה הענין להעיר על מה שזכרנו ולזאת הסבה ראוי שיהיה המשקה אשר בו ראוי שיוכשרו להזון ולזה היה הדם מכשיר כי הוא בעצמותו היותר מיוחד להזון ושאר המשקין המכשירין גם כן נאותים להזון ויורגל ההזון בהם והנה יקבלו טומאת הכלים הנעשים מעץ שהוא מסופף הצומח או הבגד והשק והעור שהם מהכרח החומר בעלי חיים ההולך וממנו יעשו לפי הנהוג או מהצומח כמו העניין בבגד פשתן או מעצמות הב"ח ההולך להיות חמרם נכבד באופן מה וכן העניין בכלי מתכת להיותו נכבד על צד ההסכמה לרוב השתמשות האדם בו ולפי שהוא יהיה מחיר כל הדברים ההכרחיים לאדם מהמזון והלבוש וממנו יעשו רבים מהתכשיטין ולפי שחמרו נכבד באופן מה ולא יקבלו טומאה הכלים עשוי' מצמר הב"ח הגדולים ועורו ועצמו ולא מעצמות העוף לפי שאלו הדברים הם בלתי נהוגים לעשות מהם כלים עם שהם המותר הארצי אשר במיני החי החסרים ביחס אל הב"ח ההולך ואולם כלי חרס לחסרון החומר אשר ממנו נהיה כי הוא מהיסוד הארצי אשר הוא היותר פחות שבכל הנמצאים המורגשים לא יקבל טומאה אלא מדרך מה שהוא מועיל והוא מצד התוך שחדשתהו בו המלאכה ולזה לא יטמא כי אם מתוכו ולזה יטמא אפילו מאוירו ואולם כלי אבנים וכלי אדמה וכלי גללים שהיו יותר חסרים כי מיוסרי העפר בעצמו והמלאכה לא חדשה דבר מחמרם זולתי התמונה והנה לא יקבלו טומאה כלל אמנם בכלי חרס חדשה המלאכה בחומר באופן מה מצד מה שערבו המים עם העפר ונאפה הטיט ההוא באופן שנתן לו קיום ועמידה ואמנם כלי זכוכית עם שהם מן חמר פחות הנה ימעט השתמשות האדם בהם לקלות שכירותם ולזה לא יקבלו טומאה מן התורה הנה זהו מה שראינו לזכרו בזה המקום וכבר הגענו בו אל תכלית המאמר במה שיקיפו בו ענייני הטמאות והטהרות הנזכרות בתורה והיתה השלמת המאמר בזה בי"ו לירח כסלו של שנת תשעים ושלשה לפרט האלף השישי יתברך ויתעלה האל המיישר אותנו אל הנכונה אשר גלה לנו אלו העמוקות כי לא מצאנו בבזה לקודמים מאמר נאות ובמעט שמצאנוהו בזה להם הוא יותר ראוי שירחיקנו מעמוד אל הנכונה משיישירנו על זה והנה עלו בידינו סבות כל זה באופן שיעיר אמתתו אל מה שאמרנו בכל מה שנזכר בזה בתורה מעניין הטמאות והטהרות כמו שתראה וזהו מטבע האמת רוצה לומר שהוא מעיר על עצמו מכל צד ומכל פנה והנה התועלות המגיעות מזאת הפרשה הם י"ג:
@259 **השרש** הראשון הוא שהנבלה מטמאה אדם וכלים במגע וכלי חרס במגע תוכו והרי הנוגע בה הוא ראשון לטמאה והנבלה היא אב הטמאה ולא יטמא הנוגע בה לא אדם ולא כלים כי אינם מקבלים טמאה כי אם מאב הטמאה ואמנם טמא אוכלים ומשקין ואולם הנושא את הנבלה הרי הוא מטמא כלי' שנוגע בהם בשעת המשא שנאמר וכל הנושא מנבלתם יכבס בגדיו ואינו מטמא אז כלי חרש אם נגע בתוכן שאין כלי חרש מקבל טמא אלא כשנפל בתוכו אב הטמאה שנא' וכל כלי חשרש אשר יפול מהם אל תוכו וגו' והנה זה האדם אינו אב הטמאה שנ' וכל כלי חרש אלא הוא ראשון לטמאה והוא מבואר שכבר תקרא נבלה הבהמה הטמאה אע"פ שנאמר שנשחטה כי אין השחיטה מועילה בה כלל ולזה לא תועיל השחיטה בשליל כי אין בו דין השחיטה אבל הוא נתר בשחיטת אמו ולא תקרא נבלה הבהמה הטהורה השחוטה כהוגן אף על פי שהיתה טרפה כי הטרפה אינה נקראת נבלה שנאמר נבלה וטרפה לא יאכל כבר נתבאר זה כלו בספרא:
@259 **השרש** השני הוא שלא תטמא הנבלה אם לא היה בה שיעור אכילה שהוא כזית ותהיה עם זה ראויה לאכילה שנ' מבשרם לא תאכלו ובנבלתם לא תגעו מגי שלא יטמא ממנו אלא מה שראוי לאכילה לפיכך הקרנים והטלפי' ומה שאינו ראוי לאכילה מהעור והעצמות אינו מטמא וכן העניין בבשר הנבאש שאין ראוי לאכלו אפי' על ידי הדחק כגון שנפסל מלאכול לכלב וכן העניין בבשר הנבאש שאינו ראוי לאכילה אע"פ ששרו אותו בפושרי' מעת לעת וכן הנבלה שהיתה סרוחה מתחלתה ואינה ראויה למאכל אדם אינה מטמאה משום נבלה שנאמר לגר אשר בשעריך תתננה ואכלה מה שתהא מתחלתה ראויה לגר כבר נתבאר זה בתשיעי מחולין ומזה יתבאר שהנוגע בחלקי' מבשר נבלה שאין באחד מהם כזית אף על פי שדבקם זה בזה בקסם ובכיוצא בו אינו טמא אם לא היו דבוקים זה בזה מעצמם כי חבור אדם אינו חבור. ואולם אם נשאם טמא שהרי נשא כזית כבר נתבאר זה בתשיעי מחולין:
@259 **השרש** השלישי הוא שהאבר הפורש מן החיים שהוא כלי רוצה לומר שיש בו בשר גידים ועצמות דינו כדין הנבלה ואפילו היה מן השלישי שבבטנו שהרי יש לאבר הזה צורה מתייחס לצורה והוא שהיה בו בשר כדי להעלות ארוכה בחי ואולם הבשר הפורש ממנו מחיים אינו מטמא שאין אני קורא נבלתו וזה הדין משותף גם כן לשקץ והנה האבר אין לו שעור שהרי הוא נבלה בעצמו כבר נתבאר זה בספרי ובראשון מאהלו' ובתשיעי מחולי' והנה הבשר הפורש מן החי אינו מטמא בכזית או בכעדשה כשרץ כי לא היתה הטמאה בו אלא מפני כללות האבר המורכב מבשר גידים ועצמות לא מצד הפשוטי' אשר מהן הורכב כבר נתבאר זה בתשיעי מחולין ואין דין האבר המדולדל בבהמה שאין יכול להחיות ולהדבק בשאר הגוף כדין האבר הפורש מן החי אם לא מתה הבהמ' אחר זה ואולם אם נשחטה הטהורה דינה דין האוכלין כשהוכשרו לטמאה כי השחיטה מכשרת זה האבר לקבל טמאה ולא יהיה דינו דין הנבלה וכן הענין בשוחט הבהמה ונמצא בה עובר מת כבר נתבאר זה ברביעי ובתשיעי מחולין:
@259 **השרש** הרביעי הוא שדם הנבלה אינו כבשרה אבל דינו דין המשקה הטמא שאינו מטמא מדיני תורה לא אדם ולא כלים וזה מאמרו הבשרם לא תאכלו וכו' והנה הדם הוא בלתי דומה לבשר כי הבשר הוא אכל והדם הוא משקה והבשר הוא מעצם הב"ח והדם הוא מזון לו כבר נתבאר זה ביט ממנחות ולזאת הסב' בעינה תהיה שליה של נבלה בלתי מטמאה הנבלה כי היא דבר זה ממנה כבר נתבא' זה ברביעי מחולין ולזאת הסבה יהיו הקבה והחלב של נבלה בלתי טמאין שהם דבר זר ממנה:
@259 **השרש** החמישי הוא שחלב הבהמ' הטהורה אינה כבשרה לעניין טמאה שנאמר וחלב נבלה וחלב טרפה יעשה לכל מלאכה ואכול לא תאכלוהו ולזה הוא מבואר שאינו מט מטמאת נבלה כבר נתבאר זה בשלישי מעוקצי' והוא מבואר שאין בבהמה הטמאה חלב חלוק מהשומן ולזה לא ננהג אסור חלב אלא בשור וכשב ועז כמו שהתבאר ממה שקדם כבר נתבאר זה בשלישי מעוקצין:
@259 **השרש** הששי הוא שבהמה המתה לא יטמא משום נבלה מה שהתמידה להיות מפרכסת שנאמר וכי ימות מן הבהמה ובכלל הנה לא תקרא נבלה כל זמן שימצא בה חיות מה אם לא יהיה הנעשה בה ממה שאפשר שתחיה אחריו זמן מורגש כגון שעשאה ניסטרא או שנקרעה מגבה או שנטלה ירך בחלל שלא או שנשבתרה מפרקת ורב בשר עמה כבר נתבאר זה בראשון מחולין:
@259 **השרש** השביעי הוא שקולית הנבלה שהוא סתום משני צדדיו אף על פי שיש בו מוח כשיעור אינו מטמא במגע לא במשא כי מה שאינו מטמא במגע אינו מטמא במשא שנאמר וכל הנוגע בנבלתם יטמא וגו' וכל הנושא מנבלתם וגו' והיה זה כן כי מה שהוא בבית הסתרים איננו מטמא אם לא יצא לאויר העולם ואולם אם נקב במשהו מטמא במגע ובמשא ואם חשב לנקבו ולא נקבו הדבר בספק אם מחוסר נקובה או מחוסר מעשה כיון שאין זה הכח פונה אל השלמות מצד לקיחת המזון מזה העצם ולזאת הסבה אם מת עובר הבהמה בתוך מעיה ונגע אדם בו לא נטמא כל זמן שלא יצא לחוץ ומה שאמרנו מזה הענין אמנם הוא כשהיה המוח מקשקש בתוך הקולית שהרי אינו מעלה ארוכה לעצם אבל אם היה עומד במקומו אם יש בו כדי להעלות ארוכה לעצם אם היה עומד במקומו מטמא במגע ובמשא בכל האיברי' כבר הבא זה בתשיעי מחולין וזה השרש כול בנבלת השרץ גם כן כמו שהתבאר שם והנה למד זה העניין מצמיד פתיל שמציל בכלי חדש כיון שהכלי טהור מציל מה שבתוכו וכן העצם מן הנבלה או האשה ההרה כיון שהיא טהורה היא מצלת מה שבתוכה וכבר נבאר זה בג"ה באופן יותר שלם במה שיבא והנה לא נזכרה התורה טמאה בנבלת עוף טמא ואולם נבלת עוף טהור מטמא טומאה חמורה בהיותה בבית הבליעה לבד ואינה מטמא במגע ובמשא כמו שיתבאר בפשרת אחרי מות ובפרשת אמור אל הכהנים כבר נתבאר זה בספרא ובשמיני מפרה ובחמישי מזבחים:
@259 **השרש** השמיני שאין נבלת השרץ מטמאה אלא בעודו לח שנאמר כמותם שהיה כעין מותם שהם לחים ולזה יבשו באון שאם נשרו במים פושרין מעת לעת לא יחזרו לחים כשהיו הרי אלו טהורים כבר נתבאר זה בז' מנדרי' וכן גם כן מה שאינו ראוי לאכילה מהם כגון העצמות והעור הבלתי ראוי לאכילה או שנפסד מלאכל לכלב כבר נתבאר זה בתשיעי מחולין:
@259 **השרש** התשיעי הוא שהשרץ אינו מטמא עד שימות או שיתבאר בו שאי אפשר שיהיה זמן מורגש כמו העניין בנבלת הבהמה שנ' במותם כבר נתבאר זה בא' מאהלות:
@259 **השרש** העשירי הוא שהשרץ מטמא בכעדשה לא בפחות אם לא היה אבר שלם כבר נתבאר זה בראשון מחגיגה:
@259 **השרש** הי"א הוא שאלו שמונה שרצים הם אב הטומאה מטמאין אדם וכלים במגע כמו נבלת הבהמה ואינם מטמאין במשא כבר נזכר זה בא' מכלים:
@259 **השרש** הי"ב הוא שבשר השרץ שהיה פחות מכעדשה מתלתו הרי הוא טהור ואפילו שנתפח אחר זה ושב כשעור וכן העניין בנבלה אם היה מתחלתו פחות מכזית ואולם אם היה כשעור וצמקו וחזרו ותפחו שבו לטמאתם כבר נתבאר זה בג' מטהרות:
@259 **השרש** הי"ג הוא שדם השרץ כבשרו כי אין בו דם לפי האמת אך הוא כמו תמצית הבשר הלא תראה כי התורה לא מנעה מהדם כי אם דם בהמה וחיה ועוף כבר נזכר זה בספרא:
@259 **השרש** הי"ד הוא שכלי עץ או בגד או עור או שק או כלי חרש הדומה להם מהכלים הראוים לטמאה כמו אלו הכלים הם מקבלים טומאה מאב הטומאה באופן הנזכר בתורה שנאמר מכל כלי עץ או בגד או עור או שק כל כלי אשר יעשה מלאכה בהם וכבר אמרה התורה בפרשת מטו' וכל בגד וכל כלי עור וכל מעשה עזים וכלי כלי עץ תתחטאו. ולפי שזכר בגד הוא מבואר שאי אפשר שתהיה הכוונה באמרו בכל מעשה עזים הבגד הנעשה מהעזים. ולזה הוא מבואר שהוא רומז בזה אל הכלים הנעשים מהקרנים והטלפים והעצמות כבר נתבאר זה בא' מחולין עם שהם יותר ראוים בזה מכלי עץ להיותם יותר נכבדים ולפי שהבגד אינו נהוג להעשות אם אל מהגדל ביבשה עם שאיננו נהוג העשותו מעוף ודגים. וכן הענין בכלי עצם שכבר סמכן לבגד ועור עם שאינן נהוגין העשותן כי אם בגדל ביבש' והוא יותר ראוי לטמאה מהגדל באויר או במי' לפי מה שבארנו בסבת הטומאות כבר נתבאר זה ביז' מכלים ובי' ממנו. ואולם כלי חרש ביארה התורה בהם שאינם מקבלים טמאה אם לא היה להם תוך ר"ל שיהיה להם בית קבול ר"ל כל אשר יפול מהם אל תוכו ואולם שק מבואר מעניינו שישלו בית קבול כי הוא אם ללבוש אם לשאות בו התבואות והסחורות אמר ויהי הם מריקים שקיהם ולפי שאמר בכללות על כל אלו הכלים וזה מבואר מאד ולזה לא יקבלו כמו זאת הטומאה כי עץ וכלי עור אם לא היה בהם בית קבול כבר נתבאר זה בב' מכלים והוא מבואר שהכלים הנעשים מאי זה צמח מצמחי האדמה כגון המחצלת והכברה ומה שידמה להם דינם דין כלי עץ כבר נתבאר זה בי"ו מכלים והנה כלי אבנים וכלי אדמה וכלי גללים בלתי ראוין לטמאה ככלי חש כי החרש עשתה ממנו המלאה כלי באופן מתיחס להויות הטבעיות כי הכינה החמר ועצרה בו הלחות אשר תדבק חלקו באופן מתיחס לממשלת החום הטבעי על הלחויות' ונתינתו להם גופיות ועמידה מה שאין כן באלו עם שהם מחמר פחות בלתי ראויים לטמאה לפחיתותו כבר נתבאר בי' מכלים וב' משם וכן כלי זכוכית הם כזה הדין למטה מכלי חרש להיותם בלתי מתקיימים באופן התקיים כלי חרש ולא הכינה המלאכה בהם החמר באופן שהכינתהו בכלי חרש כי ערבה בו המים עם העפר וגבלה אותו מה שאין כן בכלי זכוכית ולזה לא יהיה כלי זכוכית מקבלין טומאה כבר נתבאר זה בב' משבת ואולם כלי מתכות הם כלם מקבלין טמאה פשוטיהן מקבליהן כמו שהתבאר בפרשת מטות שנ' אך את הזהב ואת הכסף ואת הנחשת וגו'. אך במי נדה יתחטא וגו'. כל דבר אשר יבא באש תעבירו באש וגו'מ. מגיד שכלי מתכות כלן מקבלין טמאה פשוטיהם ומקבליהן כבר נתבאר זה בי"א מכלים והוא מבואר ממה שזכרנו שכל כלי נעשה מן העפרות ויגבלוה במים ואחר ישרפום לעצור בהם קצת לחות דין כלי' חרש כבר נתבאר זה בו' מכלים וראוי שתדע שהכלי שעשה מדבר שאינו מתקיים אלא מעט כגון העושה כלים מן הלפת ואתרוג ומה שידמה לזה כי לא יפול שם כלי על כמו אלו בעבור שמושן זמן מועט כי בזה האופן שיפול שם כלי על הכלים המתקיימי' המשמשין זמן ארוך כבר נתבאר זה בי"ד מתוספו' כלים:
@259 **השרש** הט"ו הוא שהכלי שאינו מטלט' מלא וריקן לא יקבל טמאה כי בזה האופן יקרא כלי וזה מבואר משק שהטלט' מלא וריקן וכבר אמר בכל אלו הכלים אשר יעשה מלאכה בהן ולזה ראוי שתהיה העשות המלאכה בהם נאמר בכל אלו הכלים לכונה אחת וכזה אמר בכלי מתכות כל דבר אשר יבא באש וגו' מגיד שבמטלטל הכתוב מדבר ואולם אם היה כלי העשוי לנחת או שאינו מטלטל מלא וריקן אינו מקבל טומאה ואין לך כלי מחובר לקרקע שהיה מקבל טומאה כי אם תנור וכירים שהם מקבלין טמאה בין מחוברים לקרקע בין שאינם מחוברים כבר נתבאר זה השרש בב' ממגילה וראוי שתדע כי עם כל זה לא תקבל טמאה ספינה בשל חרש כי אין תנועתה שיניעוה בעצמותה כשאר הכלים אבל היא קימת על שטח המים ותתנועע בהתנועע המים הנושאים אותם כבר נתבאר בב' זה מכלים ובט' משבת ואין צריך לומר שלא תקבל טמאה ספינה של עץ כי היא כלי העשוי לנחת כמו שביארנו:
@259 **השרש** הי"ו הוא שכל קבול שאין מכוון ראשונה להשתמש בקבולו על דרך הקבול אינו מקבל טומאה כמו בית קבול העשוי למלאו' כגון בקעת של עץ שחוקקין בה בית קול ותוקעין בה הסדן של נפחין או כלי עור העשוי לידים מפני הזיעה כדי שלא יפסד הדבר שהוא מתעסק בו בזיעת ידיו או שהיה הבית קבול בלי עשוי לקבלה כבר נתבאר זה בו' ובז' מכלים וראוי שתדע שאם נעשה הכלי עור לידים כדי שלא יכהו הקוץ בלקטו הפירות או כדי שיאחוז יפה הרי הוא עשוי לקבול כי בלתו לא יכול לעשות מלאכתו כבר נתבאר זה בי"ו מכלים:
@259 **השרש** הי"ז הוא שהכלי לא יקבל טומאה אם לא היתה צורת כלי עליו ושתגמר מלאכתו באופן שיאות להשתמש בו מה שכוון בו מהמלאכה או שיכניס להשתמש בו כי בזולת זה האופן לא יקרא כלי כבר נתבאר זה השרש בי"ו מכלים ומזה המקום יתבאר שהכלי שלא נעשה לקבלה וחשב עליו להשתמר בבית קבולו הנה זא' המחשבה תשימהו כלי וכן הענין במה שדומה לזה והנה זאת המחשבה לא תשימהו כלי אם לא היתה מכן דעת אבל חרש שוטה וקטן אין להם מחשבה ואולם המעשה מהם יועיל להשים מה שאינו כלי רוצה לומר אם עשו בו דבר לעשותו כלי ועשוהו ראוי להשתמר בו השמוש ההוא שחרש שוטה וקטן יש להם מעשה ואין להם מחשבה ואולם לא תוציאהו המחשבה מהיותו כלי ר"ל אם חשב שלא להשתמש בו אלא אם כן עשה בו מעשה לזה התכלית כבר נתבאר זה בכ"ח מכלים ובא' מחולין:
@259 **השרש** הי"ח הוא שהכלי שלא תעשה בו המלאכ' אינו מקבל טומאה לזה הוא מבואר שחפויי הכלי' אינם מקבלים טמא' ואפי' היה הכלי מצופה במתכת וישתמשו בבית קבולו אינו מקבל טמאה כי הצפוי אשר המלאכ' נעשית בו אינו כלי בעצמותו כבר נתבאר זה השרש בי"ח מכלים ובי"א ממנחות וספרא:
@259 **השרש** הי"ט הוא שהנלוה לכלי שהוא צריך לכלי בשע' מלאכה כגון ידות הכלים ותלויי כברה של גרנות ומי שימה לה מתטמא עם הכלי והכי עם ואם נבדל היד עם הכל אינו מטמא מטמאתו והוא מבואר שלא יחשב מהכלי מה שנלוה לו מהידות והתלויין ומהטפלה שעל התנור לחזקו ומחבל הדלי וכיוצא בהם רק מה שצריך לכלי מהם והשאר לא יטמא בטומאת הכי ואינו מקבל טמאה אם לא היה כלי בפני עצמו וזה מבואר בנפשו מצד הוראה הגדר כבר נתבאר זה השרש בב' ובה' וי' בכ"ה ובכ"ט מכלים:
@259 **השרש** הכ' הוא שהכלי השלם שאין לו שם ייחדוהו במה שהוא כלי אינו במדרג' הכלי אם לא היה לו בית קבול מים כי אז הוא כלי וזה מבואר בנפשו כי כמו זה לא יהיה כלי כי אם בדרך רחוק' וכ"ש שיהיה זה הדין במה שהוא חלק מכלי שאין לו שם בעצמו אבל הוא חלק מכלי אלא אם לא היה לו בית קבול כבר נתבאר זה השרש בי"א מכלים:
@259 **השרש** הכ"א הוא שהרצון בכלי הוא שיהיה משמש את האדם אם לעשות בו מלאכתו אם להתענג בקולו כגון כלי שי' או להיות לו תכשיט אך מה שהוא תכשיט לבהמה או לבית או לכלי אחר או משמיע קול לבהמה לא יקרא כלי כי אינו משמש לאדם אלא אם היה עם זה משמש לאדם שמוש מה ולזה לא יהיו הכלי זמר שבמקדש מקבלים טומאה כי הם כלים לשם יתע' לא לאדם כבר נתבאר זה בי"א ובט"ו מכלים ובה' ובו' משבת ומזה המקום יתבאר שהמטפחות המיוחדות לספרים והם המצויירות אינם מקבלות טמאה כבר נתבאר זה בכ"ח מכלים והקש על זה:
@259 **השרש** הכ"ב הוא שמה שיהיה חלק בלתי מקבל טמאה אם לא היה כלי בעצמו כיון שהוא דבר נלוה כלי הטהור ומשמש לולא יהיה הנמשך גדול מכח הקודש והמשל שאנקלי של דרגש טמאה כי הדרגש הוא כלי קבול מעץ ושל נקליטי המטה טהורה כי המטה היא טהורה ואם היה הענין בהפך יהיה הכל מקבל טומאה כגון מפתח של עץ ושניה של ברזל כי העץ הוא בה דבר נלוה לשנים של ברזל כי הם העקר במפתח במה שהוא מפתח כבר נתבאר זה בי"ב מכלים:
@259 **השרש** הכ"ג הוא שהכלי הדבק לקרקע או הכלי העשוי לנחת אינו מקבל טומאה כי אינו מטלטל ואולם אם היה כלי קודם שיקבעו שם ואחר כך קבעו שם באופן נכון לשמש השמוש שהיה משמש קודם לא נתבטל מתורת כלי ועדין הוא מקבל טמאה ואם שב חלק מהקרקע ההוא אע"פ שהוא משמש מעין מלאכתו נתבטל והמשל שהקורה אשר יקשרו בה כותלי הבית יש בשני ראשיה כסאות וקודם שהוקבעו יקבלו טומאת מדרס ואח"כ לא יקבלו טומאה כבר נתבאר זה בט"ו ובכ' מכלים ולא עו' אלא אפילו הלכים העשוין לשמש את הקרקע אינן מקבלין טומאה אפילו קודם שיוקבעו כגון הדלת של מתכת והבגד והמנעול והפותח והציר והקורה והצינור והמסמרים העשויים לחזק את התקרה שכל אלו הם משמשים את הבית כבר נתבאר זה בי"א מכלים:
@259 **השרש** הכ"ד הוא שהכלי שיעש' לשמוש מה והוא קצתו משמש מעין שמוש הכל והם צורת כלי עליו כגון הקופה של ערבבה ושל גמי שלא תקנה צורת כלי ומהותו מצד תוספת גבהה אבל תקנה מזה חזקה יותר הנה החלק מהגובה מסכים לכל בשם ובגדר ולזה תקבל טמאה משנראת לעשות מעין מלאכתה אע"פ שדעתו להוסיף על זה הכלי כבר נתבאר זה השרש בי"ו מכלים ולזאת הסבה יהיה הבגד של צמר ופשתין מקבל טמאה משיארוג בו ג' אצבעות על ג' אצבעות אע"פ שלא השלים לארוג מה שכוון שהרי הוא משמש מעין שמות הכל ואולם אם לא נשלמה המלאכה בחלק ההוא כמו העניין בארוג במחט אינו מקבל טמאה כי תשחת מלאכתו ולא תתקיים כרגע ואולם אם היה ארוג על גבי מחט הרי זה מקבל טומאת כיון שעשה בו בית קבול מלאכתו אע"פ שלא השלימו לשיעור שכיון כבר נתב' זה בי"ג מתוספות כלים ואולם בגדים של צמר ופשתים שהן עבים ביות' או בגדי פשתים של מצרים שהם דקים ביותר הנה הם אינם משמשי' מעין מלאכתם אם לא היה בהם ג' טפחים על ג' טפחים וכן העניין בבגדים שאינם של צמר ופשתים וזה מבואר ממנהג השמוש באלו הבגדים כבר נתבאר זה בכ"ח ובב' משבת ולזאת הסבה יתבאר שהכלי שנפחת ועדיין הוא משמש מעין מלאכתו הראשונה לא סר שם כלי מעליו כבר נתבאר זה בי"ו מכלים:
@259 **השרש** הכ"ח הוא שהכלי הטמא שנשבר טהור שנאמר וכל כלי חדש וגומ'. כל אשר בתוכו יטמא ואתו תשברו וממנו נלמד זה הדין לשאר הכלים והיה זה כן לפי שכבר סר שם כלי מעליו ולזה יחוייב שלא ישאר בכלי דבר משמש מעין מלאכתו הראשונה שאם היה זה כן הנה יהיה החלק ההוא בטמאתו כמו שקדם ולזה הוא מבואר שכלי עץ שחלקו לשנים טהור כיןו שאין אחד מחלקים משמש מעין מלאכתו וראוי שתדע שאיך שיהיה שיסור הכלי מלשמש כגון שהעלה חלודה באופן שלא יוכל לשמש או שנכפפו הכלים הפשוטים ונפשטו הכלים הכפופים באופן שלא יוכלו לשמש מעין מלאכתם סרה הטומאה מהם ואולם כלי של חליו' שפרקו וההדיוט יוכל להחזירו אן זו שבירה וזה מבוא' מאד כי הוא כלי בכח קרוב אלא אם היתה צריך אומן להחזירו או שנגנבו קצת פרקיות או אבדו והקש על זה כבר נתבאר בו' ובי"ב וי"ז וי"ח מכלים וראוי שתד' שאין הבדל בין ששבר הכלי בזה האופן בעת אחת או בעתים רבים שנאמר ואותו תשבורו וכיון שסר מהכלי בפעמם רבות מה שלא ישאר בו שיעור משמש מעין מלאכתו הראשונה טהור והמשל שאם נשבר ממנו חלק קטן לא יטהר הכלי בו ותקנו מחדש ואחר שבר אצל התקון חלק אח' קטן ושב לתקונו מחדש ולא סר מעשות כזה עד שהסיר ממנו מה שיבטלהו מהיות כלי אם לא היה שם מה שחדש בו לתקון הכלי כפעם בפעם הנה הכלי הוא טהור שהרי שבר אותו והרי זה כלי אחר אלא שאם היה זה טמא טמאה חמורה כטמאת מדרס או שיהיה טמא מת הנה יהיה זה הכלי המתוקן טמא מגע מדרס או מגע טמא כיון שנשארו כלי כפעם בפעם כבר נתבאר זה בי"ח מכלים ובט"ו משבת:
@259 **השרש** הכ"ו הוא שהכלים הטמא המתאחד עם כלי אחר בתשמיש כמו הכרע עם המטה והשן של מעדר עם המעדר הנה בהתאחדותו כמו ישוב הכלי טמא בטומא' זה החלק לפי שאי אפשר בכלי האחד שיהיה קצתו טמא טומאה קלה וקצתו טומאה חמורה ואולם כשפירש ממנו זה החלק הטמא ישוב הכח שהתאחד בו טמ' מגע הכלי משפרש ממנו והסב' מצד האחדות הכלי שכאשר נגעה טומאה בחלק ממנו יטמא כלו כבר נתבאר זה בי"ח מכלים:
@259 **השרש** הכ"ז הוא שאין כלי חרש מקב' טומאה מהטומאות אלא מתוכו שנאמר וכלי חרש אשר יפול מהן אל תוכו וגו' ולפי שתוכו כולל כל האויר אשר בבית קבולו למדנו שבאי זה חלק מהאויר ההוא אם היה בו אב הטומאה כמו השרץ והדומה לו הוא יטמא הכלי ההוא שאני קורא בו אל תוכו מה שאין כן בשאר הכלים כי הם אינן מקבלין טומאה אם לא נגעה בהם הטמאה ומאוירו ג"כ מטמא אוכלי' הוא מטמא ואינו מטמא כלים אבל הוא מטמא אוכלין ומשקין אם נגעו בו אפילו מאחוריו או מצדיו הצריכים לכלי כמו העניין בשאר הכלים כבר נתבאר זה בספרא ובב' מכלים ומזה המקום יתבאר שאם היה תוך הכלי חרש כלי אחר והיה הכלי ההוא בלתי מעורב לאויר הכלי החצון עודפת על שפתי הכלי הפנימי הנה אם היתה הטומאה באויר הכלי הפנימי לא נטמא החיצון שאין אני קורא בו אל תוכו והוא תוך תוכו ולזה גם כן אם היה החיצון טמא והיו אוכלים ומשקין באויר הכלי הפנימי לא נטמאו ואולם אם לא היה הפנימי כלי כגון שנשבר או נקב באופן שלא ישמש מעין מלאכתו כיון שאינו כלי הנה לא יציל האוכלים והמשקים שבתוכו ואם היתה הטומא' בתוכו נטמא הכלי החיצון כבר נתבאר זו בא' מכלים ובספרא ומזה המקום יתבאר שאם היה כלי חרש מוקף צמיד פתיל תוך הכלי חרש הטמא אע"פ ששפתי הכלי החיצון עודפים על שפתיו הציל על האוכלין ומשקין שבתוכו ואם היתה הטמאה בתוכו לא נטמא החיצון שהרי אוירו נבדל בכללו מאויר הכלי החיצון וזה יתבאר מאהל המת שלא יקרא תוך האהל מה שהיה תוך הכלי חרש המוקף צמיד פתיל אשר בתוך האהל ולזה היה הכלי ההוא מציל על מה שבתוכו מהתטמא באהל המת וכ"ש שיציל מטומאת שרץ הקלה ואולם אם היה הכלי הפנימי נקו' נקב ימנעהו מלשמש מעין מלאכתו אע"פ שמוקף צמיד פתיל אינו מציל כבר נזכר זה בא' מכלים ומזה המקום יתבאר שהדם שהיתה טמאה בלועה בו והיה באויר כלי חרש לא טמאהו שהרי אין זה תוכו אלא תוך הגוף ההוא כי אין לו שמוש עוד בו וכן הענין אם נבלעה הטמא' בטיט ובכיוצא בו ונפל הטיט לאויר כלי חרש טמאהו שהרי הוא תום הכלי ההוא כי אין לטיט תוך בעצמו ישתמש בו והוא מבואר שהדברים שבתוך פה הב"ח או בתוך הקמטים אינם כבלועים שלא נחשוב זה תוך לב"ח ההוא וכן ספוג שבלע משקין טמאין כגון דם נדה אע"פ שהוא נגוב מבחוץ אם נפל לאויר כלי חרש טמאהו לפי שסוף המשקים לצא' והרי הוא כאלו יצאו והקש על זה כבר נתבאר זה בא' ובט' מכלים:
@259 **השרש** הכ"ח הוא שבלי חרש שחלקו במחיצה עד שפתו לא יהיה לו דין שני כלים מחוברין זה לזה אבל אם נטמא החלק האחד נטמא השני כי יש לו דין כלי אחד כי אין דרך בני אדם לחלוק כלי חרש וכן הענין בתנור כי הוא מכלי חרש כבר נתבאר זה השרש בא' מכלים:
@259 **השרש** הכ"ט הוא שהתנור הוא דומה לכירים אפשר בו הטלטול אף תנור שיהיה אפשר בו הטלטול יצא הכבשן שאינה אפשר להטלטל ואין משתמשין בו אלא על גבי קרקע ויצאו יורות הערביים שאין הטיח יכול לעמוד בפני עצמו כבר נתבאר זה השרש בה' ובא' מכלים ומזה המקום יתבאר שאין מתנאי התנוא המטמא שיהיה דבק לקרקע אבל יקבל טומאה גם כן אם היה מטלטל כבר נתבאר זה בה' מכלים:
@259 **השרש** הל' הוא שאין דת תנור וכירים אלא במה שאי אפשר בו הנתיצה יצא תנור אבן ותנור של מתכת ואם היו תנור אל אבן ושל מתכת בלתי ראויים לעשות מלאכתם והשלימם במה שעושין ממנו תנורים הרי הם מטמאין כדין התנור להטמא ולטמא מאוירם שהרי אפשר בהם הנתיצה ואם לא היה כן יהיה התנור של אבן טהור ושל מתכת טמא טמאת כלי מתכות וכן הענין בכירים כבר נתבאר זה השרש בה' מכלים וראוי שתדע שאין הבדל בכירים בין שיהיו מחוברין אחד לאחד או שיהיו מפורדין ומחוברין לקרקע יש לה כירים כי מין הנהוג לעשותה בזה האופן גם כן אבל אם היה חלקה האחד דבק לקרקע וחלקה השני נפרד מהקרקע או שהיה דבק באופן לא יתכן בו הנתיצה או הטלטול הנה אין שני אלו החלקים חלק אחד ואין האחד מהן כירים ולזה לא יקבלו טומאה כבר נתב' זה בו' מכלים:
@259 **השרש** הל"א הוא שהנתיצה שאמרה התורה בתנור וכירים הוא שיפרידם לחלקים לא יהיו ראויים לעשות מעין מלאכה ושיסיר הטפלה המחברת אותם בארץ כי זה הוא מגדר הנתיצה וזה מבואר בנפשו כבר נתבאר זה השרש בה' ובז' מכלים והוא מבואר שאם היו התנור או הכירה באופן שאינם ראויים לשמש מעין מלאכתם כגון שנפחת תחתיהם באופן שלא יתכן בו ההסק או שמעט חללן באופן שלא יוכלו לשמש מעין מלאכתם הרי הם בלתי מקבלים טמאה כבר נתבאר זה בחמישי מכלים:
@259 **השרש** הל"ב הדבר שאין עושים התנור ממנו אינו מדבק חלקי התנור ממנו להשים אותם כלי אחד אבל הם נפרדים ואינם מקבלים טומאה והמשל שחוליו' התנור ששם חול או צרור ביניהם ובין הטפלה אינם מקבלין טומאה כי דרך התנור שידובקו חלקיו בטיט ואחר יוסק עד שיהיה לטיט ההוא עמידה וקיום ומפני זה לבד היה התנור הנעשה באבנים מכלל כלי חרש כבר נתבאר זה השרש בה' מכלים ואולם אם נעשה התנור חליות חליות של חרש כיון שדבקו בטיט שעושין בו התנורים הרי הו מקבל טומאה אע"פ שלא הסיקו שנים שהרי הוסק כל אחד מחלקיו והרי הוא ראוי לשמש מעין מלאכתו כבר נתבאר זה בח' מכלים ואולם שאר כלי חרש הנהוג בהם שתלשו בכללם מהטיט המוגבל ואחר יאפה ולזה הוא מובא' שהכלי חרש שנשבר ודבק חלקיו בטיט ואפו אותו אינו מקבל טומאה כי לא נעשה באון מעשה כלי חדש מה שאין כן בשאר הכלים שנשברו כבר נתבאר זה בב' ובד' ובט"ו מכלים והסבה מבוארת בזה ממה שקדם בנתינתנו הסבה בטמאת כלי חרש:
@259 **השרש** הל"ג הוא שלא יקרא תוך התנור החלל שיהיה בו שאינו משמש בו מלאכת התנור כמו העניין בעינו של תנור ומקום הנחת עצים וזה מבואר בנפשו חייובו כבר נתבאר זה השרש בח' מכלים:
@259 **השרש** הל"ד הוא שאין לכלי חרש טהרה אלא השבירה ואע"פ שקבעו מקרקע או שמלאו עפר שנאמר ואותו תשבורו. מלמד שאין לו טהרה אלא בשבירה אלא במה שלמטה ממנה בבטול הכלי מהיות כלי ואין להם טהרה בטבילה שהרי בשאר הכלים אמר במים יובא וטמא עד הערב וטהר ובכלי חרש אמר ואותו תשבורו:
@259 **השרש** הל"ה הוא שכל אכל המיוחד למאכל אדם מצד עצמותו אע"פ שמנעה התורה מלאכלו או שחשב עליו לאכל והיה ראוי לאכילה באופן מה הרי הוא מקבל טומאה מהראשון לטומאה כמו שזכרה התורה בכלי רש והוא הדין לשאר הכים שקבלו טומאה מאב הטומאה שנאמר אשר יאכל יצא מאכל שאינו ראוי לאדם או מאכל שהוא סרוח ונפסד כבר נתבאר זה השרש בא' מטהרות ובי"ב ממנחות ובא' ובג' מפסחים וראוי שתדע שהאכל אינו מקבל טומאה עד שיוכשר שנאמר אשר יבא עליו מי' כבר נתבאר זה בספרא ומזה המקום יתבאר שמה שאין ראוי לאכילה לשום אדם אף על פי שכיון אחד לאכלם בטלה דעתו כגון חרצנים והזגים שכנסם לאוכלים ולזה אינן מטמאים טומאת אוכלים כבר נתבאר זה בג' מתוספות עוקצין:
@259 **השרש** הל"ו הוא שאכל המוכשר שעורו בכל שהוא לקבל טומאה שנאמר וכל זרע אפי' שומשום או חרדל כבר נתבאר זה השרש בספרא והנה אין האוכלין או המשקין מטמאין זולתם למנות בהם שלישי ורביעי אם לא מדברי סופרים ואע"פ שמצאנו שאמרה התור' בקדשים והבשר אשר יגע בכל טמא לא יאכל באש ישרף הנה לא זכרה התורה שיהיה טמא הבשר ההוא הנוגע באכל. טמא אבל הוא פסול לאוכלו וכן מה שמצאנו בטבול יום ומחוסר כפורים שאינן טהורים לעניין הקדשים לא יתבאר ממנו שיטמאום במגעם בן אבל יפסלום והיה זה כן כי מפני שהיתה ההערה בטמאה ובענין הקדשים אחת בעינה הנה ראוי שתרוחק בקדשים תכלית ההרחקה כי בזולת זה לא יגיע התועלת המכוון בענין הקדשים וזה מבואר במעט עיון מדברינו בנתינתינו סבות אלו הדברים:
@259 **השרש** הל"ז הוא שהאכל שאינו מורגל לאכלו במדינה ההוא לא יהיה ראוי לקבל טומאה אם לא חשב עליו לאכלו או שעשה בו מעשה להכינו לאכילה וזא' המחשבה יש ראוי שתהיה מבן דעת לא מחרש שוטה וקטן ואולם המעשה יספיק אם נעשה על ידיהן כי החרש שוטה וקטן להם מעשה ואין להם מחשבה אין צריך שיוכשר אחר המחשבה או המעשה כי אין קרוי אוכל עד העת ההיא והתורה הגבילה שיוכשר אחר היותו אבל ר"ל מכל האכל אשר יאכל כי אינו אשר יבא עליו מים וגו'. וצריך שיהיה המחשבה בו בתלוש לא במחובר שאין אני קורא בו אשר יאכל כי אינו אכל עד שיתלש כבר נתבאר זה בשמיני מטהרות ובט' מחולין ובו' מנדה:
@259 **השרש** הל"ח הוא שאין קרוי אכל אלא שהמכוון בעצמותו שיאכל לא מה שנתן באכל להטיב ריחו או טעמו או מראהו כי אינו מכוון להיות אוכל מצד עצמות כגון הקשט והבשמים ומה שידמה להם ואולם מה שהוא אכל בעצמו כגון התמרים והגרונות ונתנן בקדרה לתת טעם לא לאכילה עדין לא יצאו מתורת אוכל אם לא אחר שיפסלו מלאכול לאדם כבר נתבאר זה בשלישי מעוקצים:
@259 **השרש** הל"ט הוא שאין בב"ח בעודם חיים טומאה זולתי באדם אם לא זכרה התורה בהם טומאה ואע"פ שהם מאכל אדם אחר שימותו כי אינם קרואים אכל בהיותם חיים וזה מבואר בנפשו וכן העניין בצמחים ר"ל שאינן קרויים אכל בעודם מחוברים לקרקע עד שיתלשו ולזה הוא מבואר שהב"ח אינו מטמא טמאת אוכלין עד שימות או ישחט מה שראוי לאכלו אח השחיטה ואז יקרא אכל אף על פי שהוא מפרכס כי הוא מותר לאכלו כמו שיתבאר בענין השחיטה ואם היתה הבהמה טרפה יש בדבר ספק אם תקרא אכל בעודה מפרכס' כיון שאינה ראויה לאכילה לישראל ולזולתם לא תקרא אכל על היותה מתה ואפילו אבר ובשר המדולדלין בבהמה שאינם יכולים לחיות הרי הם כאלו נתלשו ומקבלין טומאה במקומם שהרי הם אכל מצד עצמותם לא חלק מב"ח וכן הפרי המחובר לאילן שאינו נזון מהאילן כאלו תאמר שנשלמה הויתו או שיבש הענף שהוא גדל ממנו הרי הוא כתלוש ומקבל טומאה שהרי אני קורא בו אשר יזרע כבר נתבאר זה כלו בד' ובט' מחולין והנה הפרי הנטוע בכלי שאינו נקוב הרי הוא בתלוש כיון שהוא בכלי הלא תראה שהמים אשר בקרקע אינן מקבלין טמאה כבר נתבאר זה בשני מעוקצין:
@259 **השרש** ה"מ הוא שידות האוכלין כגו' עוקצי תאנים ואגוזי' וכיוצא מהם מהדברים שהאכל צריך מהם וכן שומרי האכלים שהאכל צריך להם כגון קליפי פולין שעורין מטמאין עמהן כל זמן שלא פרשו מהן ובהכשרן יוכשר האוכל ואין יד ליד ולא לשומר שומר לזה העניין אבל השומר המחובר לאכל לבדו הוא נקרא שומר לזה העניין לא השומר לשומר ההוא שנאמר על כל זרע זרוע אשר יזרע ואם הנה דרך בני אד לזרוע זרע בקליפהן וכן הענין בידות האוכלין שהכל קרוי אכל יחד וכן הענין בעצמות עם הבשר שהרי הם אם ידו' אם שומר כבר נתבאר זה בט' מחולין ובא' ובב' מעוקצין:
@259 **השרש** המ"א הוא שהאוכל הפרוד אינו חבור זה לזה להטמא זה בטמאת זה ואפילו אכל שנדפס ומעורה במקצת ונטמא קצתו באויר כלי חרש או בשא' הטמאות לא נטמא החלק השני אלא אם היה באופן כשיאחז כשיאחז בזה החלק שנטמ' יהיה השני עולה עמו ואם לאו הרי הוא כאלו נפרד ממנו כבר נתבאר זה בשלשה מטבול יום וראוי שתדע שהאכל הפרוד אם עשאו גוף אינו חבור אלא אם היה זה באחד מהמשקין המקבלין טומאה ולזה הוא שאם נגע בו הטומאה במקום מה ממנו הנה יטמא החלק ההוא לבד לא המחובר לו ע"י הלחות ההוא כמו דבלה ומה שידמה לה והנה ככרות הנושכות זו בזו לפי שלא היה דעתו להשים אותו האכל גוף אחד כבר נתבאר זה השרש בא' מתוספות עוקצן ובא' מטהרות ומטבול יום:
@259 **השרש** המ"ב הוא שהאכל הטמא אינו יוצא מידי טומאה עד שיפסל מלאכול לכלב שנאמ' מכל האוכל אשר יאכל יטמא ר"ל כל זמן שהוא אכל וזה אינו יאכל אפילו על ידי הדחק ובכלל הנה כמו שהכלי יטהר כשסר שם כלי מעליו כזה יחוייב שיהיה באוכלין ובמשקין כי הם למטה מהכלים בטומאה כבר נתבאר זה בח' מטהרות ומזה המקום יתבאר שאין לטמאת משקין טהרה בזה האופן כי המשקה לא יהיה נפסל מלשתות לכלב בשום פנים והוא מבואר שאין לאוכלין ומשקין טהרה כמי מקוה כי התורה זכרה טבילה באדם וכלים ולא זכר' אום באוכלי' ומשקים ואמנם יקרה שיהיה למי' טהרה במקוה לא מצד הטבילה אך מצד התאחדותם עם המקוה שהם טהורים ר"ל שאם ישקיע הכלי שבו המים הטמאים במקוה באופן שתהיה נשיקה ממי המקוה להם והנה התמד על של החמיץ דינו כמים לזה הענין כבר נתבאר זה בי' ממקואות ובא' מחולין:
@259 **השרש** המ"ג הוא שז' משקי' מכשירין האוכלין לטומאה כשנפלו עליהם באופן שיתבאר כי כלם נקראים מים בזולת שם לווי והתורה לא דקדקה באלו המים ביותר מזה השיעור ולזה אמר אשר יבא עליו מים וכי יותן מים בזולת ה"א הידיעה אך בבניין הטבילה אמר במים יובא ורחץ את בשרו במים והנה המים והטל והשמן והיין והחלב והדם והדבש של דבורים והם לבדם מקבלים טומאת משקים כי ראוי שיהיה המכשיר לקבל טומאה מהמשקין מקבל טומאה בעצמו ואלו המשקים הם הנהוגים לשתות' לפי הטבע לולא מנעה התורה קצם כמו הדם כי הוא נקרא משקה אשר ישתה ובכלל הנה הוא המשקה היותר נאהב מצד עצמותו כי המזון לא יקחוה האברים אלא באמצעות היותו דם כב' נתבאר זה בו' ממכשירין והתבא' גם כן מספרא וכמו שלא יקבלו טומאה אלא אם היו תלושין שנאמר וכל כלי לא מחוברין לקרקע שנאמר אך מעיין ובור מקוה מים יהיה טהור כן אינן מכשירין אלא אם היו תלוישין וזה מבואר בנפשו חייובו עם מה שקדם כבר נתבאר זה בספרא ובראשון ממקואות:
@259 **השרש** המ"ד הוא שהמים התלושין אינן מכשירין אם לא היו תלושין ברצון או שיתחייב היותם תלושים ברצון כי לפי הנהוג אי אפשר לשותה לשתותם מזולת זה אבל המים העולים בחטמו ובראשו וזקנו אינם תלושין כרצון ולזה לא יהיו מכשירים הסבה בזה שהרי אמר במשקין המקבלין טומאה בכל כלי ומדרך המים אשר בכלי שיהיו נותנים שם ברצון שאין ראוי שיובן מזה שלא יהיו מקבלים טומאה או מכשירין אם אל היו בכלי שהרי ביאר שלא הוצא מזה הכלל כי אם המים מחוברים לקרקע שנאמר אך מעיין ובור מקוה מים יהיה טהור כבר נתבאר זה השרש ברביעי ממכשירין:
@259 **השרש** המ"ה הוא שאין המים התלושי' מכשירין האוכלים אם לא נפלו עליהם ברצון הבעלים שנאמר וכי יותן מים על זרע וזה אמנם יהיה על ידי פעל מכוון ולזה צריך שיהיה ברצונם בתחלה או בסוף ומזה גם כן יתבאר שצריך שיהיו תלושין ברצון כי אמרנו יותן מים עם שהוא מכוון אל הנתינה הוא מכוון גם כן אל לקיחת המים אשר יותנו עליו ואינו מחויב שתהי הנתינה הזאת על ידי הבעלים כי לא אמרה התור' כי יתן אבל אמרה וכי יותן וזה הרצון צריך שיהיה בעצם לא מפני האגם ומפני דבר מורה שלא יהיו רצונו לבטל פירותיו במים כגון הטומן פירותיו במים מפני הלסטין והגנבין או הנותן פירותיו לשבלת הנהר להביאם עמו כבר נתבאר זה השרש באחד ממכשירין וממה שקדם יתבאר שהדם היוצא בשעת השחיטה מכשיר הנשחט לקבל טומאה כבר נתבאר זה בתשיעי מחולין:
@259 **השרש** המ"ו הוא שלא נקרא המים המחוברים לקרקע אלא אם כן היו בקרקע עולם לא בכותל בנוי שהרי אין דרך המים להיות שם ואולם כותל מערה הוא קרקע אולם כבר נתבאר זה בא' מחולין:
@259 **השרש** הארבעים ושבעה הוא שתולדות המים מטמאים ומכשירין המים והנה תולדות המים הן כמו מה שיצא מהמשקין מהאדם מהמקומות שהכין להן הטבע מקום יצאו ממנו כמו העניין במה שיצא מהעין והאזן והחט' והפה ומי רגלי האדם שהרי הם כלם יאותו ממותר האדם לא פרות אמנם הזיעה ולחת המוגלא והראי אינם מתולדות המים כי הראי הוא מהמותר היבש אף על פי שנתך וכן תמצית הבשר מאי זה בא שיהיה הוא מי פרות וזה מבואר מאד וכן מי רגלי הבהמה דינו כדין מי פרות למאיסותם כבר נתב' זה השרש בו' ממכשיר' ובג' מתוספות מכשירין ותולדת הדם הוא דם הקזה של אדם שהוציאו לשתיה לא אם הוציאו לרפואה ומזה יתבאר שהדם המנוי מהמשקין הוא דם שהנפש יוצאה בו והוא הדם השותת בשעת שחיטה לא דם הקלוח שעדיין חי הוא ודומה לדם מכה או לדם הקזה לפיכך השוחט ונתן דם על האוכלין ונתקנה הדם בין סימן לסימן הרי זה ספק אם הוא מכשיר והנה דם שחיטה בבהמה וחיה ועוף הטמאין לא מטמא ולא מכשיר כי מפני שלא סודר בהם שיהיו נשחטים הנה יהיה הדם ההוא כדם מכה שהוא מי פרות והדם היוצא עם הלחה והראי והיוצא בהם לא מטומא ולא מכשיר ואולם דם השקץ אינו מכשיר אבל הוא מטמא כמו הענין בבשרו כמו שזכרנו במה שקדם ולזה הוא מבואר שאינו מכשיר כבר נתבאר זה בו' ממכשירין ובב' מחולין וכן מי החלב הרי הם כחלב ואולם חלב הזכר אינו משקה שהרי אינו צריך לו והנה בין שאינו צריך לו הרי הוא ראוי לתנוק אבל חלב בהמה שיצא שלא לרצון אינו משקה כבר נתבאר זה בו' ממכשירין וממה שנזכר בזה השרש יתבאר שהנופה בעדשים לבדקן אם הם יפות הוכשרו בהבל פיו וכן זיעת המרחץ הרי הוא משקה כי מן המים נתהותה ואולם זיעת בתים שיחין ומערות אינה כן כבר נתבאר זה בב' ממכשירין:
@259 **השרש** המ"ח הוא שהמשקין הטמאים בעצמן כגון זוב הזב וזובו ורקו ומה שידמה להם מטמאין האוכלין בלא הכשר שהרי הטמאה והכשר באין כאחד כבר נתבאר זה בו' ממכשרין וכן האוכלים הטמאים בעצמם אין צריכין הכשר כגון נבלת בהמה ונבלת העוף טהור וזה מבואר בעצמו לפיכך אם נתיחדו עם אוכלין טהורים באופן שנעשה הכל גוף אחד אין המעורב צריך הכשר לפי שאין צריך שיבא המשקה המכשיר בכל חלקי האכל המוכשר והרי קצת זה האכל מוכשר כבר נתבאר זה בט' מחולין:
@259 **השרש** המ"ט הוא שהנצוק חבור במשקים הדבקי' הנמשכי' כמו ריר דבק כמו הדבש ומה שידמה לו לא במה שאין לו ריר כגון תבשיל גריסין והחלב הנתך כבר נתבאר זה השרש בחמישי ממכשירין ובשביעי מנזי':
@259 **השרש** החמשים הוא שמשקה בית המטבחיים שבעזרת המקדש כגון דמי הזבחים והמים שמשתמשין בהם שם טהורין לא מתטמאין לא מכשירין כבר נתבאר זה השרש בט"ו מכלים והיה זה כן לפי שאחשוב לפי שאין נכנסים תחת כלל משקה אשר ישתה כי הדמים הוגבלו לתתם על המזבח והמים ההם הוגבלו להדיח בשר הקדשים והכהנים זריזין במצות השם יתעלה ולזה לא יתכן שיהיה אפשרות בזה המשקה שישתה:
@259 **השרש** הנ"א הוא שכלי שטף וכל הכלים זולת כלי חרש יש להן טהרה כשבאו בכללותם במים שנאמר במים יובא כולו לא קצתו כבר נתבאר זה בספרא והיה זה כן כי כמו שהכלי נטמא בכללו מחוייב שיהיו המים שיוכ' בהם בכללו לטהרו ויהיו בלתי מקבלין טומא' והן מעיין ובור מקוה מים שאם היו מקבלים היה הכי מטמאן בבאו בהם ולזה לא יתכן שיהיו המים ההם סבה לטהרם והנה נלמד מצד הורא' הגדר כי מקוה המים אינו מטהר אל הכלים אם לא היו מ' סאה או יותר כי לא יפול שם מקוה מים בפחות מזה השעור עם שכבר נלמד זה השעור מטבילת אדם שנאמר בו ורחץ בשרו במים כמו שנאמר בזה המקום במים יובא והנה המים שיהיה כל בשר האדם עולה בהם הנה הוא אמה על אמה ברום שלש אמות וזה השעור הוא מכיל מ' סאה כבר נתבאר זה בה' מפסחים ובא' מחגיגה וזה אמנם יהיה במקוה אמנם מעיין מטהר בכל שהוא כיון שבא בו המטהר בכללותו כבר נתבאר זה בא' ממקואות ומזה השרש שאין ראוי שיהיה דבר חוצץ בין המטהר ובין המים שנאמר במים יובא וזה לא בא במים בכללותו לפיכך אם היה על הכי זפת או טיט או מה שידמה להן ממה שלא ימנע בו הכלי מלשמש מעין מלאכתו ואן בעלים מקפידין עליו להסירו משם אינו חוצץ הרי הכל הוא כלי וכן העניין בטבילת האדם שהרי הוא בשרו ואם היה מקפיד עליו ואינו על רובו אינו חוצץ שכיון שאינו מונע ממנו שמושו ובא כלו במים הרי הוא קורא בו המים יובא ואולם אם היה על רובו ומקפיד עליו הרי הוא חוצץ שהרי סר תורת כלי מרובו לפי מחשבת הבעלים ורובו הוא ככלו כמו שהתבאר בשרשים הכוללים כבר נתבאר זה בא' מערובין וראוי שתדע שאין צריך שיבאו המים בבית הסתרים כאלו תאמר זה שהיה דרכו בכלי שיהי סתום ולא ישתמשו בו להכניס ולהוציא או באדם מה שהוא בין הקמטין ותוך הפה ומה שידמה להם שהרי נאמר בזב וידיו לא שטף במים ולמדנו משם כמו שיתבאר שאין חיוב הטבילה אלא בנגלה משטח ידיו כמו ידיו עם שהנהוג מהרחיצה במים היא על האופן ר"ל שלא ידקדקו להכניס המים בין הקמטים ומה שידמה להם:
@259 **השרש** החמישים ושנים הוא שהמקוה צריך שיהיו מימיו נקוין שנאמר מקוה ובזה האופן הוא טהר אבל המעיין מטהר בזולחין הנמשכין ממנו כי לא נאמר בו מקוה והנה מי המעיין הם בכח בשעור ראוי להטיב בהם הדם כי מימיו הם נזחלים תמיד ואולם אם היו נזחלים על גבי הכלים אין מקבלין טומא' ואם היו מימיו נוטפין הנה כבר נבדלו מהמעין ולזה יהיה דינם דין המקוה לא דין המעין כבר נתבאר זה השרש בח' ממקואות:
@259 **השרש** החמישים ושלש' הוא שמעורב למקוה הרי הוא כמקוה להטביל בו כגון גומות הסמוכות לפי שהמקוה ומקות רגלי הבהמה שהיה בהן מים והן מעורבים עם המקוה כשפופרת הנוד שהוא כרחב שתי האצבעות הראשונות שבפס היד והם נקראים אצבע אמה הרי הם כמקוה והטובל בהם עלתה בו טבילה כבר נתבאר זה בחמישי ובו' ממקואות:
@259 **השרש** החמישים וארבע הוא שמי הב"ח שתחלת הויתן מן המים כגון יבחושין אדומים שנתמססו והיו למים מטבילין בהם אם היו בקרקע כי ממים היו למים שבו כבר נתבאר זה השרש ביב' מזבחים וכן טיט רך שהפרה שוחה ושותה ממנו הרי הוא נקרא מים ומטבילין בו כבר נתבאר זה בשני ממקואות:
@259 **השרש** החמישים וחמשה הוא כי מפני שנאמר במים יובא למדנו שאין כל מים במשמע ולזה לא יכשר המקוה הנעשה מיין ושמן וחלב ושאר מי פרות ואם נתערב במים מאלו פסלו המקוה אם שנו מראהו כי זה יסור מעליו שם המים ולא יקרא מים לפי הנהוג אבל יקרא בשם בעל המראה ההוא ר"ל שאם היה מראהו מראה יין הנה יקרא יין מזוג אבל הם היה שם בעל המראה הוא מים כמו מי הצבע ואולם אם שנו מי המקוה בטעם או ריח לא פסלוה שהרי עדיין הם נקראים מים לפי הנהוג וכבר ימצאו מהמימות מטעמים רבים ומריחות רבים וזה מבואר מן החוש כבר נתבאר זה השרש בחמישי ממקוואות:
@390 **אשה כי תזריע:**
@390 **השרש** הא' הוא שהיולדת זכר אע"פ שלא ראתה דם טמאה לידה שבעת ימים ואחר זה יהיו לה דמי טוהר שלמות מ' יום ואולם אם היתה יולדת נקבה תטמא לידה י"ד ימים ואחר זה יהיו דמיה טהורים עד סוף שמונים וזה כלו נזכר בביאור התורה וכבר נתבאר זה בספרא וראוי שיתבאר מזה שאם תקר' לה לידה אחרת בימי טהרה נה היא טמאה לידה כבר נזכר זה ברביעי מנדה והוא מבואר ממה שזכרנו כי ממעיין אחד יצאו אלו הדמים הטהרים והטמאים אלא שפעם נמשך לו דם מבושל ופעם דם נא ולזה יהיה זה הזמן שהגבילה לו התורה הוא המשים אותו טהור או טמא לסבה שזכרנו כבר זה נתבאר ברביעי מנדה:
@390 **השרש** הב' הוא שאין לידה קודם יצירת הולד וזה מבואר בנפשו ולפי שאין היצירה לולד נשלמת קודם ארבעים יום הנה הוא מבואר שהמפלת קודם זה לא תהיה טמאה לידה ולפי שמלשון התורה יראה שתהיה הויה שלמה לפי שכבר אמר בזכר וביום השמיני ימול והנה יראה מזה שלא נשפוט על היות זאת ההויה שלמה באופן שינתן לה דמי טוהר עד שישעיר הולד וזה מבואר חיובו מהסבה שנתננו בדמי טוהר ולפי שהוא מסופק אם כונה התורה במה שאמרה וביום השמיני ימול שתהיה זאת ההויה שלמה או אמרה זה להודיע מצות המילה לפי דרכה הנה נשפוט בזה להחמיר ולא יהיה לה דמי טהר אם ילדה מעת מ' יום להריונה עד שישעיר הולד כבר נתבאר זה בג' מנדה וראוי שיתבאר מהשרשים הכוללים שהיולדת מה שהוא ספק אם זכר או נקבה הנה תהיה טומאה לידה מספק י"ד יום ואם השעיר הולד לא יהיו לה ימי טוהר כי אם שלמות מ' יום כבר נתבאר זה בג' מנדה:
@390 **השרש** הג' הוא שהוא ראוי שתלד מה שהוא מין אדם שנאמר וילדה זכר וגו'. וביום השמיני ימול בשר וגו'. וזהו גם כן הנהוג בלידה אבל אם ילדה מה שהוא ממין אחד כגון בהמה חיה ועוף אין זאת נקראת לידה שאין זאת נקראת לידה שאין זה מדרך הזרעתה אבל הוא מותר העפוש אף על פי שתהיה שם שלייא וכבר נשפוט שיהיה ממין אדם בצורת הפנים אם היו פני אדם באופן מה כבר נתבאר זה בג' מנדה:
@390 **השרש** הד' הוא שלא תקרא לידה אם לא היתה דרך הרחם וזה מבואר מצד הוראת הגדר ועם זה יש בזה ראיה מלשון התורה שנאמר אשה כי תזריע וילדה זכר עד שתלד ממקום שמזרעת לפיכך יוצא דופן אין אמו טמאה לידה ואין לה דמי טהר ואף על פי שיצא דם מהרחם בעת צאת הולד דרך דופן הנה דינו כדין דם שיצא משאר נשים שאינה יולדות כבר נתבאר זה בחמישי מנדה והוא מבואר שאף על פי שהיה הלידה דרך הרחם אין נקראת לידה עד שיצא רובו או עד שיצא ראשו כי אז גם כן הוא כילוד כי יש לו כח למשוך מהאויר המקיף בכלי הנשימה ויוכל לחיות אע"פ שתמות אמו ובכלל הנה לא ימות הנולד שנולד בשלמות אם ישוב להיות קצתו תוך מעי אשה כיון שראשו הוא לחוץ ולזה יתחיל למנות מהעת ההיא ימי טמאה וימי טהרה והעת שיפול בו מצות מילה כבר נתבאר זה בג' ובה' מנידה:
@390 **השרש** הא' הוא שזאת המצוה ראוי שתעשה ביום ולא בלילה שנאמר וביום השמיני ימול בשר וגומ'. והכונה ביום ולא בלילה עם שזה העת היותר נהוג שתעשנה בו כמו אלו הפעולות כבר נתבאר זה בשני ממגלה:
@390 **השרש** הב' הוא שהמצוה היא למולו לאב בן ח' ימים כי אי אפשר שתהיה זאת המצוה לנולד כי אינו בן דעת ותשוב בהכרח זאת המצוה למי שהבן ברשותו לעשות ממנו בחפצו והוא האב ואולם האם עם שאינה שולטת בזה הנה אין לנשים בקיאות בכמו אלו הפעולות לחסרון דעתם ואינם גם כן בגדר זאת המצוה מצד עצמותם והוא שראוי שיהיה השליח בפעל מה שראוי לפועל ההוא מצד עצמו כבר נתבאר זה בא' מקדושי' ומזה גם כן יתבאר שהרב חייב למול את העבד שהוא יליד בית בשמיני כי החיוב למול יליד בית בשמיני שנ' בפרשת לך לך בן שמונת ימים ימול לכם כל זכר לדורותיכם יליד בית ומקנת כסף והוא מבואר שאי אפשר שישוב אמרו בן שמונת ימים למקנת כסף כי על הרוב כבר יהיה מקנת כס אחר היותו בן שמונת ימים ולזה הוא מבואר שזה ישוב ליליד בית לבד ואולם למקנת כסף ראוי שימול אותו הרב ביום שהוא מקנת כסף כי התורה לא הגבילה בזה זמן ראוי שיהיה האדם זריז בענין המצו' כבר נתבאר זה בי"ט בשבת וראוי שיתבאר מזה שמילת הבן ויליד בית בשמיני דוחה את השבת ואת הי"ט כי התורה הגבילה זה לזה ויחוייב מזה שיהיו הדברים העצמיים למילה אפשר לעשותם קודם זה כמו האיזמל שמלין בו ומה שידמה לזה רוצה לומר שאין עושין האזמל בשבת לצורך המילה כי הם מכשירי מילה אבל הדברים העצמיים למילה שאי אפשר לעשותם קודם זה דוחין שבת וי"ט כבר נתבאר זה בי"ט משבת ובט' מפסחים והוא מבואר אם היה בזה ספק אם מצד הזמן שהוא ספק שמיני אם מצד הנושא שהוא ספק אם הוא חייב למול כמו הענין במי שנולד מהול שכיון שאי לו בשר ערלה ידמה שלא יתחיי' למול שנ' ימול בשר ערלתו ולפי שלא מל ידמה שיצטרך להטיף דם ברית אין מילתו דוחה את השבת ואת הי"ט כבר נתבאר זה בי"ט משבת:
@390 **השרש** הג' הוא שאין מתנאי המחוייב רק שתמצא לו ערלה ר"ל האבר אשר הוא בו שנאמר ימול בשר ערלתו ומזה יתבאר שאם היו שתי ערלות כדמיון האברים הנוספים יתחייב למול כל אחד מהם וכן אם היה אנדרוגינוס שהרי יש לו ערלה ועוד שהתורה אמרה בן שמונה ימים ימול לכם כל זכר והוא מבואר שאנדרוגינוס נכנס בזה הגדר שהרי יש לו פועל הזכר באופן מה ומזה גם כן יתבאר שאין מתנאי המחוייב למול שתהיה לידתו דרך רחם אבל אע"פ שיצא דרך דופן הרי הוא חייב למול שהרי הוא זכר וראוי שתדע שאין דוחה את השבת מילה אחת מאלו שזכרנו בזה השרש והוא יוצא דופן ואנדרוגינוס ומי שיש לו שתי ערלות שהרי בכל אחד מהם ספק וזה כי מפני שאמר וביום השמיני ימול בשר ערלתו אחר אמרו אשה כי תזריע וילדה זכר ידמה שלא ינהג זה ביוצא סופן ושלא ינהג באנדרוגנוס לפי שאינו זכר וכן מי שיש לו ב' ערלות הנה יסופק באי זה מקום הוא זכר כבר נתבאר זה בי"ט משבת:
@390 **השרש** הד' הוא שהמחוייב למול יחוייב שלא יהיה נפל כאלו תאמר שהוא בן ח' חדשים ששערו לקוי ואין צפורניו שלמים כברייתו שהרי לא נגמרה הויתו והרי הוא כאבן כי אין לו כח לחיות ובר נתבאר בפר' לך לך מאמרו וערל זכר אשר לא ימול בשר ערלתו שהנמול ראוי שיהיה אפשרי להיות גדול באופן שיווה בעצמו על זאת המצוה ולזה הוא מבואר שאין מילתו דוחה את השבת כבר נתבאר זה בי"ט משבת:
@390 **השרש** הה' הוא שהמחוייב למול שמל אותו איזה שיהיה יצא ידי מצות מילה הלא תראה כי צפורה מלה את בנה וסר מעל משה הענש הנפלא שהיה מגיע לו על שנתעצל במילת בנו כבר נתבאר זה בב' מע"ז:
@390 **השרש** הו' הא שמי שלא נמול והגדיל חייב כרת אם לא מל קודם שימות אם היה מזיד אך קודם זה לא יתחייב כרת כי התורה לא הגבילה לו זמן שנאמר וערל זכר אשר לא ימול בשר ערלתו ונכרתה כבר נתבאר זה בו' מפסחים וראוי שתדע שענין המילה היא הסרת הערלה המכסה העטרה והוא מבואר מהשרשים הכוללים שאם גלה רוב העטרה בעת המילה לא יתחייב מן התורה לחזור בחתוך העור ופריעת העטרה כבר נתבאר זה בי"ט משבת והוא מבואר ג"כ מהשרשים הכוללים שאם היה סכנה לנולד אם ימול הנה תהיה המילה נדחית מפני סכנת נפשות שהרי אפשר לקיימה לאחר זמן כבר נתבאר זה בי"ט משבת:
@390 **השרש** הא' הוא שאין היולדת מביאה קרבן אלא אחר ימי מלאת כדי שלא תחסר לטהרתה כי אם הכפרה שג' ובמלאת ימי טהרה וגו'. וכפר עליה הכהן וטהרה לפיכך אם ילדה ולדות הרבה זה אחר זה והביאה כפרתה אחר ימי מלאת הראשונים קודם ימי מלאת האחרונים לא יצאת לפי שאינה טהורה שהיא תוך ימי מלאת כבר נתבאר זה בתשיעי מנזיר ומזה יתבאר שהיולדת או המפלת ולדות הרבה זה תוך ימי מלאת של זה מביאה קרבן אחד לכלם אבל אם לא היה זה תוך ימי מלאת של זה מביאה קרבן אחד על כל לידה ולידה כבר נתבאר זה בראשון ובשני מכריתות:
@390 **השרש** הב' הוא שהחטאת הוא מעכב הכפרה לא העולה שנאמר והקריבו לפני השם וכפר עליה מגיד שבאחד מהם תשלם הכפרה והוא החטאת כי בו היו הדברים שנ' ובן יונה או תור לחטאת והקריבו עוד שהחטאת יותר ראוי לכפר' מהעולה וזה מבואר בנפשו כבר נתבאר זה בספרא ומזה המקום יתבאר שהעולה אפשר שתקרב לאחר מיתת היולדת לא החטאת כי אין כפרה לאחר מיתה ולזה הוא מבוא שאם קרבה חטאתה ומתה יקריבו היורשים עולתה כי כבר נתחייבו נכסיה בזה הקרבן כבר נתבאר זה בא' ממנחות ומזבחים וראוי שתדע שאם עבר יום הכפורים על היולדת קודם שתביא קרבנה אינה פוטרת מקרבן לידה לפי שזה הקרבן משלים הטהרה ומכשירה לאכול בקדשים והנה יום הכפורים אינו מטהר האנשים הטמאים אבל הוא מכפר החטאים והפשעים כבר נתבאר זה בו' מכריתות ולפי שאין קרבנות יולדת וזב וזבה ומצורע באים על חטא הנה אפשר שיקריבם זולתם על ידם שלא מדעתם תדע שהאדם מביא קרבן על בניו ועל בנותיו הקטנים אם היו מחוסרי כפרה ומאכילן בזבחים כמו שנתבאר זב בד' מנדרים:
@390 **השרש** הא' הוא שטמאת הנגע וטהרתו תלויה בכהן שנאמ' וטהרו הכהן וטמאו הכהן וגו'. ואולם ראיתו אפשר שבישראל שהרי אמר בפרשת שפטים כי יפלא ממך דבר למשפט בין נגע לנגע וגו'. ובאת אל הכהנים הלוים ואל השופט אשר יהיה בימים הם מגיד שישראל יכו לראות הנגע להוציא משפטו לאור אך משפטי לנגוע לטהרו או לטמאו יהיה על יד כהן לבד כמו שהתבאר ואע"פ שהראייה גם כן מצאנו שדקדקה התורה בזה המקום שתהיה בכהן הנה על כל פנים יחוייב ממה שאמר בין נגע לנגע שתהיה הראייה כשרה בישראל שאם אמר אומר שזה יהיה לשפוט לנגוע אם הוא טמא או טהור הנה הורה בזה שהראייה אפשר שתהיה בישראל כי לא יתכן להכריח בין החולקים בז הנגע בזולת ראייה וכבר יתבאר גם כן שזה המשפט לא יהיה לנגוע בזולת כהן ממה שאמר בפרשת כי תצא השמר בנגע הצרעת לשמור מאד ולעשות ככל אשר יורו אתכם הכהנים וגו'. כבר נתבאר זה בג' מנגעים ובא' מערכין וראוי שיתבאר מזה שאין הנוגע טמא או טהור עד שיטמאנו הכהן או יטהרנו ולזה תמצא שאמרה התורה בנגעי בים וצוה הכהן ופנו את הבית וגו'. מגיד שאין הכלים אשר שם טמאים עד שיטמא הכהן את הבית כבר נתבאר זה בספרא וראוי שתדע שהכהן שטהר את הטמא או טמא את הטהור לא עשה כלום שנאמר טמא הוא וטמאו הכהן כבר נתבאר זה בספרא וראוי שתדע שכהן חלל פסול לראות את הנגעים לפי שכבר סרה הכהנה ממנו וכבר אמר וטהרו הכהן:
@390 **השרש** הב' הוא שאין רואין את הנגעים אם לא היתה הראיה שלמה שנאמר לכל מראה עיני הכהן ר"ל שתהיה הראייה שלמה אך בלילה ומי שכהה מאור עיניו או שהוא סומא באחד מעיניו אינו רואה הנגעים כבר נתבאר זה בא' ממועד קטן ולזאת הסבה גם כן אין רואין את הנגעים ביום המעונן ולא בערב ולא בשחרית ולא בתוך הבית לפי שכהה נראת עזה ולא בצהרים שעזה נראה כהה ולזה אין רואי' אותם אלא בשעה רביעית וחמישית ושמינית ותשיעית כבר נתבאר זה בב' מנגעים ולזה גם כן אין רואין שני נגעים כאחד אפילו באיש אחד כי האות לא ישלוט בשלמות על שני הנגעים יחד שנאמר וראה הכהן את הנגע לא יותר מנגע אחת ולזה גם כן אין הכהן רואה נגעי עצמו כי ראייתו תהיה בלתי שלמה ומשפטו עליה גם כן בלתי שלם לעוצם תשוקתו שלא יהיה טמא כבר נתבאר זה בב' מנגעים:
@390 **השרש** הג' הוא שאין רואין את הנגעים בעת שהנגוע מצווה באופן מה לשמוח בו כדי שלא יצטער אז אם יטמאנו הכהן כמו העניין בחתן תוך ימי שמחתו ובשבת ובי"ט בכל אדם שנאמר בנגעי בתים וצוה הכהן ופנו את הבית אם חסה התורה על פכי' קטנים שלא לצער בעל הבית כ"ש שתחוס לדבר מצוה כבר נתבאר זה בב' מנגעים:
@390 **השרש** הד' הוא שאין הכהן רשאי לטמא את הטמא עד שיהיו עיניו במקום הנגע ובעור הבשר שחוצה לו שנאמר וראה הכהן את הנגע בעור הבשר והיה זה כן כי בזה תהיה הראייה יותר שלמה לכל הענינים שצריך לראות בנגע כבר נתבאר זה בספרא:
@390 **השרש** הה' הוא שכל אחד מישראל מטמא בנגעים אפילו קטן בן יומו הלא תראה כי גם כן הבגדים מטמאין בנגעים ואולם גרים וגר תושב אינן מטמאין בנגעים שהרי בני ישראל כתוב בפרשה שנאמר דבר אל בני ישראל לאמר אשה כי תזריע וגו'. כבר נתבאר זה בג' מנגעים ובא' מערכין:
@390 **השרש** הו' הוא שמראות נגעי צרעת עור בשר הנה היותר חזק לובן שבהם הוא הבהרת והנה מראה שפל מן העור כמראה חמה עמוק מהצל והיע עזה כשלג שנאמ' מצורע' כשלג ואחריה לובן השאת והוא אינו נראה שפל מן העור כמו הבהרת ולזה נקרא שאת והוא כצמר היותר לבן והנה תמצא מתחבולות המציירים הצורות שמה שירצו שיראה היותו בולט ישימוהו בצבע לבן בלתי מופלג הלבן ואחריהם ספחת הבהרת ומראה היא כסיד ההיכל ואחריה ספחת השאת ומראה כקרום ביצה ולזה לא יקרא נגע רעת מה שהוא פחות לבן מקרום ביצה ואם נתערב באלו המראות אדמימות גם הוא נקא נגע צרעת שנאמר או בהרת לבונה אדמדמת והוא הדין לשאר הנגעים והיה זה כן לפי שזה הוא מדרך עפוש הדם אשר במצורע והנה זה המרא' נקרא פתוך והנה מראה הפתוך בד' מראות אלו הוא ביותר חזק לובן יותר חזק האדמימות ולזה אמר לבנה אדמדמת ר"ל מופלגת האודם כאלו היו בכאן ד' כוסות מלאות חלב ונתערב בכוס האחד י"ו טפי דם ובשני ח' טפין ובשלישי ד' טפין וברביעי שני טפין הנה הראשון הוא הבהרת האדמדמת והשני הוא השאת האדומה והשלישי הוא הפתוך שבספחת הבהרת והרביעי הוא הפתוך שבספחת השאת וכל מראות הלבן והפתוך מצטרפין זה עם זה להשלים שיעור הנגע ולכל הדברים כאלו הוא הכל נגע אחד כיון הם דבקים זה לזה והנה מנו אותם החכמים ללמדך שאין הכהן רואה את הנגעים עד שיהא בקי בהם ובשמותיהם כבר נתבאר זה כלו בא' מנגעים ומשב ומשבועות ובספרא. וראוי שתדע שאין משערין לובן הנגע בעור הנגע אלא בעור הבינוני לא לבן ולא שחור וזה כי טבע הנגע לא יתחלף מפני חלוף צבע עור המקבל ואם נשער בעור הנגוע הנה יקרה כשיהיה הנגוע לבן ביותר שתראה בו כהה הבהרת שהיא עזה כשלג כבר נתבאר זה בב' מנגעים:
@390 **השרש** הז' הוא שהשער הנזכר בנגעים אינו פחות משתי שערו' וזה מבואר מהשרשי' הכוללים והנה שעורם באורך ראוי שיהיה כדי לכוף ראשן לעקרן כי בפחות מזה לא יהיה בגדר השער וזה גם כן שרש גדול כולל כבר נתבאר זה בשני מנדה:
@390 **השרש** הח' הוא שג' סימני טמאה יש בצרעת עור בשר שער לבן ומחיה והם אפשר שיראו בתחלה ובכל אחד מהן מחליטו הכהן לטמאה והשלישי הוא השפיון והוא לא יהיה אלא אחר ההסגר והוא מבואר בנפשו ואין בנגעי עור ובשר הסגר יותר על שתי שבועות וזה מלשון התורה והוא מבוא שאם אחר שפטרו הכהן נולד לו אחד מסימני טמא' אלו הרי הכהן מחליטו לטמאה כבר נתבאר זה בג' מנגעים והוא מבואר שאם היה כהה אינו סימן טהרה אם לא היה כהה מכל מראות צרעת עור בשר כבר נתבאר זה בד' מנגעים:
@390 **השרש** הט' הוא ששער לבן שהוא סימן טמאה הוא שקדם נגע לשער לבן שנאמר והיא הפכה שער לבן כי אז יהיה הנגע הוא ההופך אותו ללבן לא נגע אחר כאלו תאמר שהיתה בו בהרת ובה שער לבן ונרפאת ונשאר משער הלבן ואחר נולד שם נגע אחר והיה זה השער הלבן בתוכו והוא מבוא גם כן מזה שאין שער לבן סימן טמאה אם לא היתה עקרו לבין ואז הוא סימן טמאה אע"פ שראשו משחיר וזה כי הנגע הופך אותו ללבן מעקרו לא מראשו כבר נתבאר זה בספרא ולזה גם כן הוא מבואר שהוא מחוייב שיהיה עקר השער הלבן בתוך הבהרת לא חוצה לה ואז יהיה סימן טמאה כבר נתבא זה בד' ובה' מנגעים ולפי שלא הגבילה התורה מראה מיוחד לשער הלבן הרי כל לובן הוא בו סימן טמאה כבר נתבאר זה בספרא:
@390 **השרש** הי' הוא שהמחיה שבתוך הבהרת היא סימן טמאה באי זה צבע שתהיה והו' שלא תהיה כמראה צרעת עור בשר כבר נתבאר זה בא' מתוספות נגעים והיא סימן טמאה בין שקדמה הבהרת לה ובין שקדמה היא לבהרת שהרי לא נאמ' בה והיא הפכה מחית בשר חי כבר נתבאר זה בד' מנגעי' ולפי שאמרה תורה היא הפכה שער לבן ומחית בשר חי בשאת הוא מבוא שהוא ראוי שתהיה המחית כשעור ראוי לצמוח בו שער לבן והוא כדי צמיחת ב' שערות באורך וברוחב והוא כעדשה לפי מה ששיעור חכמים כבר נתבאר זה בספרא ולפי שאמר ומחית בשר חי למדנו שהוא מחוייב שתהיה במקום אחד לא מפוזרת זעיר שם זעיר שם כבר נתבאר זה בספרא והוא מחוייב שתהיה באמצע השאת שנאמר בשאת ר"ל שתהיה השאת מקפת אותה מכל צדדיה ולזה יחוייב שיהיה בכל סביבותיה מן השאת מה שראוי להפיכת שער לבן ולפי שהנגע יחוייב שיהיה ראוי למחית למדנו מזה שהנגע הוא נקרא צרעת אם לא היה שעורו באורך וברוחב כגריס הקלקי שהו' מרובע ושעורו הוא כמו צמיחת שש שערת באורך ושש שערות ברוחב כבר נתבאר זה בספרא ובששי מנגעי':
@390 **השרש** הי"א הוא שהפשיון הוא סימן טמאה יחוייב שידבקו בו אלו התנאין שאמר הראשון שיהיה בנגע שעור נגע צרעת כשיראה לכהן קודם הפשיון ויהיה מה שיראה שיפשה ממראה נגע צרעת כי בזולת זה לא יהיה שם פשיון לנגע צרעת וזה מבואר בנפשו כבר נתבאר זה בד' מנגעים. ומזה יבאר שאם סר הנגע אחר שנראה לכהן ונתחדש אחר זה נגע גדול ממנו אין זה פשיון כי אין שם נגע פושה ואע"פ שפשה קודם הראותו לכהן וסר אותו הנגע הפושה ונשאר הפשיון לבד כשראהו הכהן אין זה פשיון כי אין שם שהנגע הפושה כבר נתבאר זה בד' מנגעים. השני הוא שיהיה הפשיון דבק לבהרת לא נבדל ממנו כי בזולת זה תהיה הויה שנית לא פשיון וזה מבואר בנפשו ומזה יבתאר שראוי שיהיה החלק המגיע מהנגע שיהיה השפיון דבק בו באופן שיהיה ראוי להיות חלק מהנגע כאלו תאמר שייה ראוי לצמיחת ב' שערות כרוחב כבר נתבאר זה כלו בד' מנגעים. השלישי הוא שיפשה חוץ לנגע לא בתוכו אם היה מקום בלתי נגוע וזה כי הפשיון שהוא בתוכו עם שהוא אינו נקרא פשיון לפי הנהוג כבר יתכן שיהיה סימן טהרה כשהיה בשר חי תוך הנגע ופשה הנגע לתוכו ונתמעטה המחייה מהשעור הראוי לה כבר נתבאר זה בד' מנגעים. ואולם כהן בעל מום רואה את הנגעים כי אין זה עובדה לשם יתע' שירוחק בה כהן בעל מום והוא מבואר שלא סרה הכהונה ממנו ולזה יהיה בנו אשר יוליד ראוי לשרת במקדש או הוא בעצמו כשיסור מומו כבר נתבאר זה בספרא. הרביעי הוא שהפשיון לא יתכן שיהיה אלא אחר ההסגר מהכהן הרואה הפשיון וזה כי השופט בפשיון הוא הכהן ויחוייב שתהיינה לו בו ראייות ויראה לו הנגע בשנית יותר גדול ממה שנראה לו בראשונה לא שתהיה הראיה האחת לכהן האחד והשנית לזולתו אך שער לבן ומחיה יתכן שיראו בתחלה בזולת הסגר כבר נתבאר זה בא' מנגעים ומזה יתבאר שאם נתמעט הנגע אחרי שסר מלפני הכהן ואח"כ חזר לשעורו הראשון כשנראה לכהן אין זה פשיון כי השופט בפשיון הוא הכהן בשתי ראיותיו ואליו לא נראה בזה הנגע פשיון כבר נתבאר זה בד' ובה' מנגעים. החמישי הוא שיהיה פושה הנגע למקום ראוי לסוג זה הנגע באופן שיהיו הפשיון והנגע לטבע אחד וזה שאם פשה לראש או זקן או לשחין או למכוה או למה שידמה להם שאינו ראוי לטבע נגעי עור בשר אין זה פשיון כי היא הויה שנית ולזה אמר אם פשה תפשה המספחת בעור ומזה המקום יתבאר בכל סוגי הצרעת שהבדילה התורה קצתן מקצת שאינם פושין זה לתוך זה ולזה גם כן יתבאר שאין מצטרפים זה עם זה להשלים שיעור הנגע כבר נתבאר זה בט' ובי' מנגעים ובג' מתוספות נגעים. הששי הוא שיהיה הנגע תחלה ראוי לפשיון מכל צדדיו ואם לא לא יטמא שנאמר וראה הכהן את הנגע בעור הבשר ר"ל שיהיה עור הבשר מקיף אותו באופן שיהיה ראוי לפשיון לזה הנגע כבר נתבאר זה השרש בספרא:
@390 **השרש** הי"ב הוא שנגע הצרעת ראוי שיהיה במקום נגלה ואם לא לא יטמא בו שנאמר וראה הכהן את הנגע בעור הבשר וזה יהיה בעמדו לפניו לפי הנהוג פרט לתוך העין ולתוך האוזן ותוך הפה ותוך הקמטים ותחת הדד ותחת השחי ומה שידמה לזה אך המגולח מהשפתים דינו כדין עור בשר ולזאת הסבה בעינה אין הנגע פושה לתוכו ואין מטמאין משום מחייה ואין מעכבים את ההופך כאלו לבן כבר נתבאר זה בב' מנגעין וראוי שתדע שהנגע שלא היה טמא לאי זו סבה שתהי' וסרה הסבה ההיא ונשאר הנגע ההוא בעינו הנה הנגע ההוא טהור כיון שטהר שעה אחת כאלו תאמר שהיה בעובר וולד או בראש ואחר כך נשר השער ונתגלה הרי זה בטהרתו כבר נתבאר זה בשני מנגעים:
@390 **השרש** הי"ג הוא שהוא שראוי שיהיה הנגע במקום שיראהו הכהן כלו כאחד פרט לראשי איברים שאין מקומן יושב כגריס כגון אצבעות ידים ורגלים וראשי אזנים וראש החוטם והדומה להם ולזה גם כן אין מטמאין משום מחיה כי היא אינה נראת שם באמצע הנגע אבל נראת כאלו היא חולקת את הנגע לפי שהוא משופע ויורד סביבות המחיה כבר נתבאר זה בששי מנגעים:
@390 **השרש** הי"ד הוא שיום השביעי עולה לכאן ולכאן בכל הנגעים ואין מסגירין בתוך ימי ההסגר ואין מחליטין בתוך ימי ההסגר אם נולדו לו סמני חלט וזה מבואר מלשון התורה ולא מחליטין המוחלט אם נולד לו נגע ואין מסגירין אףותו תוך ימי חלוטו אם נולד לו נגע אחר שנאמר לא יסגירנו כי טמא הוא אבל אם היו בו שתי נגעים וראה זה וחזר וראה זה הרי הוא מותר לומר הרי אתה מוסגר בזה ומוחלט בזה וכן כיוצא בזה כבר נתבאר זה בשלישי מנגעים וכן ההקש בכל מה שידמה לזה:
@390 **השרש** הט"ו הוא שנאמן הכהן לומר נגע זה פשה או לא פשה או שער לבן זה קדם אחר הבהרת או הפך כבר נתבאר זה בראשון מתוספות נגעים:
@390 **השרש** הששה עשרה הוא שההופך כלו לבן הוא סימן טהרה כשהיה זה אחר ההסגר או אחר החלט ואינו מטמא אחר כי אם במחיה שנאמר וביום הראות בו בשר חי יטמא בבשר חי מטמא ואינו מטמא בשער לבן וזה מבואר מלשון התורה ואולם הבא מתחלה והוא כלו הפך לבן אם היה בו שער לבן או מחיה מחלטו לטמאה וזה מבואר גם כן מלשון התורה ואם לא היה בו סימן טמאה מסגירין אותו כמו הענין בבהרת קטנה או אם אחר הפטור הפך כלו לבן הרי זה מוחלט משום פשיון וראוי שתדע שאין הבהק נקרא בשר חי לעכב את ההפך כלו לבן וכן ראשי אברים שאין מטמאין בבהרת אם נראה בהם בשר חי טמא שנאמר והנה נהפך כלומר למראה צרעת ואולם שאר המקומות שאין ראוי' לבהרת אין מעכבין את ההפך כלו לכן כמו הראש והזקן שיש בהן שיער ושחין ומכוה שהן מוציאין לחה והם נקראין מורדין כבר נתבאר זה בשני מנגעים:
@390 **השרש** הי"ז הוא שהשחין והמכוה שנרפאו רפוי בלתי שלם והוא כשאינו מכות טריות ונעשת עליהם קליפה דקה כקליפת השום ואחר זה נראה בהם נגע צרעת הרי הם מטמאין בנגעם וזו היא צרבת השחין ומחיית המכוה האמור בתורה ואז לא יהיה בהם הסגר אלא שבוע אחד ומטמאין בשני סימנין לבד והא שער לבן ופשיון כמו שנתבאר בתורה וחלקם הכתוב ללמדך שאין מצטרפין זה עם זה ואין פושין זה לתוך זה והנה יקרא שחין מה שנפסד קצת עור הבשר בסבת צמח או מכה שנתחדש שם חום עפושי מבפנים ומכוה יקרא מה שהיה מזה בסבת אש כמו שנכוה בגחלת או מרמץ וכיוצא בהם שבא החום הנכרי שם מבחוץ כבר נתבאר זה בשני מנגעי' והוא מבואר שאם נעשה השחין מכוה או המכוה שחין בטל האחרון את הראשון כבר נתבאר זה בראשון מחולין וכן ההקש בשאר מיני נגעים כאלו תאמר אם נעשה נגע עור בשר שחין או ההפך כאלו תאמ' שנרפא צרבת השחין רפוי גמור והרי הוא עור בשר הנה יבא הדין לפי האחרון כאלו התחיל עתה בעת הראתו לכהן וראוי שתדע שאם היה בכפו צרבת השחין כגריס ובה בהרת כגריס יסגיר אף על פי שאינה ראויה לשער לבן או לפשיון שמא יולד לו שחין אחר בצדה ותוכל לפשות לתוכו כבר נתבאר זה בתשיעי מנגעים:
@390 **השרש** השמנה עשרה הוא שכל אדם שנשר שער ראשו לאי זו סבה שתהיה אף על פי שעתיד לגדל לאחר זמן אם נשר שערו מהקדקד ולמטה השופע לאחריו עד פיקה של צואר נקרא קרח ואם נשר מהקדקד ולמטה ושופע לפניו כנגד פדחתו נקרא גבח והוא מבואר שאין הקרחת והגבחת מטמאתה בשער לבן אם היה בהם נגע צרעת כי אם אין שם שער מעולם ובשאר המקומות שאין בהם שער יהפכוהו הנגעים ללבן וכן הדין בראש הזקן שלא היה בהן שער מעולם ובשאר המקומות שאין בהם שער אבל מטמאין בפשיון ובמחייה ויש בם הסגר שני שבועות כמו העניין בצרעת עור בשר שנאמר כמראה צרעת עור בשר ואין מצטרפין זה עם זה ואין פושין מזה לזה שנ' בקרחתו או בגבחתו מגיד שהם חלוקים זה מזה והיה זה כן לפי שטבע המקומות האלו הוא מתחלף כבר נתבאר זה בעשירי ובשלישי ובתשיעי מנגעים וראוי שיתבאר מזה שאם נולד שחין או מכוה בקרחת או בגבחת הה יהיה דינם כדין שחין או מכוה אשר בשאר עור בשר אלא שלא יטמאו בשער לבן כבר נתבאר זה ברביעי מתוספות נגעים וכן נגעי הראש והזקן אין מצטרפין זה לזה ואין פושין זה לתוך זה שנאמר בראש או בזקן ואיזהו ראש ואיזהו זקן מן הפרק של לחי ולמעלה זהו הראש ומן הפרק של לחי ולמטה הוא זקן והוא מלפניו ותח לה החוט מאזן לאזן ומן החוט ולמעלה הוא הראש מן החוט ולמטה הוא הזקן ואולם מאחריו מפיקה של פרקה ולמעלה זהו הראש מפיקה של פרקה ולמטה אף על פי שהוא מגדל שער הרי הוא בעור בשר לכל דבר ואולם מלפניו מחוליא של גרגרת ולמעלה הוא הזקן מחוליא של גרגרת ולמטה אע"פ שהוא מגדל שער הרי הוא בעור בשר כבר נתבאר זה מתוספות נגעים:
@390 **השרש** הי"ט הוא שהנתק שיהיה בראש או בזקן הוא שיפול השער שבהם מעקרו וישאר מקומו פנוי. וראוי שיהיה זה בידי שמים לא שנתקו אדם וזה מבואר כי אין אז הסבה בו עפוש מה בנגוע שיהיה ראוי מפני זה להיות שערו לקוי כבר נתבאר זה בספרא ובראשון מקדושין התבאר שזה ינהג גם כן בזקן האשה והסריס אם היה בהם שער:
@390 **השרש** הכ' הוא שהנתקים יהיה בהם הסגר שני שבועות ומטמאים בשני סימנין כפשיון ובשער צהוב לקוי וקצר כשיהיו בו שתי שערות בזה התער בין שיהיה הנתק קדם להם או שיקדמו הן לנתק כי זה מורה על עפוש הדם ושאינו באופן ראוי להוליד שער טבעי והוא סימן טמאה באי זה מקום שיהיה הנתק היו שתי שערות מפוזרות או מקובצות וזה מבואר בעצמו והנה אם היו בו שתי שערות שחורות הרי הם מצילות מהטמאה אלא שאם נשארו שם בעת חדוש הנתק לא יצילו אם לא היה נתק בכל סביבם ראוי לצמוח בו שני שערות ברוחב כי בזולת זה לא יאמר שיהיה זה השער השחור בנתק והתורה אמרה ושער שחור אין בו מגיד שהשער השחור המציל ראוי שיהיה בנתק ואם נולד שם שער שהו' אחר חדוש הנתק מציל באי זה מקום שיתחדש מהנתק כי זה יורה שכבר נרפא הנתק וכבר יתבאר זה בעשירי מנגעים ומזה המקום יתבאר ששעור הנתק כשיעור שני נגעים כשהיה השער השחור באמצע יחוייב שיהיה שם שיעור צמיחת שש שעורות כבג נתבאר זה בספרא:
@390 **השרש** האחד ועשרים הוא שהנתק שפשה בכל הראש או בכל הזקן הרי זה טהור אפילו נתקבלו אחר החלט או אחר הפטור שנאמר קרח הוא טהור הוא וזה יהיה לפי סדור התורה אחר ההסגר על הנתק אמנם אם בא בתחלה כל ראשו נתוק או כל זקנו יסגיר ואם נולד בו שער צהוב דק יחליט אם לא נולד שער שחור. נולד שם שער שחור בצדו והלך לו אחר זה ונשאר כלו נתוק כשהיה הרי זה טמא משום פשיון כבר נתבאר זה בד' מתוספות נגעי' ובי' מנגעים והוא מבואר ממה שקדם שהשער השחור הנולד בנתקים מציל משער הצהוב ופשיון אף על פי שהלך לו השער השחור שנ' נרפא הנתק טהור הוא כבר נתבאר זה מרביעי מתוספות נגעים וכבר יתבאר במה שקדם שהנתק שהיה חוט של נתק דבק לו זקקו לפשיון ולשער צהוב דק ושער שחור הנולד שהוא מציל מסימני טמאה אם היה ברחבו כדי צמיחת שתי שערו' אבל השער השחור הנשאר אינו מציל עד שיהיה ברחבו כגריס הקלקי כבר נתבאר זה הרביעי מתוספות נגעים:
@390 **השרש** הכ"ב הוא שאחר שהסגיר נגע הנתק ז' ימים ולא פשה ולא נולד בו שער צהוב לא שער שחור מגלח סביבות הנתק ואינו מגלח מה שהיה מהשערות את הנתק כדי שיכיר אם פשה ולזה יחוייב שיניח שני שערות סביב לו כבר נתבאר זה בג' ובעשירי מנגעים וראוי שתדע שתגלחתו כשרה בכל אדם שלא נאמר וגלחו הכהן והיא כשרה אפילו שלא בתער ואף על פי שהיה נזיר הרי זה מגלח שנאמר והתגלח והוא מבואר שאם הסגירו ולא גלחו הרי זה מוסגר שהרי בשבוע ראשון עליו להכיר אם פשה אף על פי שלא גלח כבר נתבאר זה ברביעי מתוספות נגעים:
@390 **השרש** הראשון הוא שיהיו הצפורים לקוחים לשם המטהר מטמאת צרעת שנאמר וצוה הכהן ולקח למטהר וגו' לפיכך אם היו לקוחים לשם מטהר אחר מותר לטהר בהן מטהר אחר והמשל שאם היו לוקחים לשם איש מטהר בהם את האשה או בית המנוגע או הפך כבר נתבאר זה בספרא:
@390 **השרש** הב' הוא שיהיו צפורי דרור וזה נלמד ממה שאמר ושלח את הצפור החיה על פני שדה ואם לא היה הצפור דרור הרי הוא משולח מעצמו כשיעזבהו ואין צרי שישלחהו ושלא תהינה טרפות שנאמ' שתי צפורים חיות טהורות לפיכך אם נמצאה אחת שאינה דרור או שהיא טרפה יקח זוג לשני כי מפני שאמר שתי צפורים והאחדים הנמנין בזה האופן הם מסכימים הנה יחוייב שיהיו שני אלו הצפורים ממין אחד ושיהיה כל אחד מהם חי כבר נתבאר זה בי"ד מנגעים וצריך גם כן שתהינה טהורות לא טמאות כבר נתבאר זה בספרא:
@390 **השרש** הג' הוא שישחוט הצפור האחד בתך כלי חרס אשר נתן בתוכו מים חיים כמו הענין במי חטאת כדי שתהיה דם הצפור השחוטה על מים החיים שנ' בדם הצפור השחוטה על מים החיים וראוי שיהיה שעור המי' באופן שיתכן מה שהוגבל לטבול בהם בזאת הטהרה כבר נתבאר זה בי"ד מנגעים ולזה הוא ראוי שיהיה ממצה דם השחוטה עד שיהיה דמה נכר במים כבר נתבאר זה משני מסוטה:
@390 **השרש** הרביעי הוא שיקח עץ ארז שיהיה בשעור יוכר בו שהוא עץ ארז ואזוב שאין לו שם לווי ויהיה בתאר שיוכר בו שיהיה אזוב ושני תולעת שיהיה גם כן בשעור לקשור משיריו הצפור החיה עם עץ הארז והאזוב ושני התולעת ויקיף לצפור החיה ראשי האגפים וראשי הזנב כדי שלא תפרכס ותזה מעצמה כי המכוון הוא שיהיה הכהן הוא המזה על המטהר לא שיזה הצפור מעצמו ויטבלם אחר כן בדם הצפור השחוטה אשר על מים החיים ויזה מאלו הד' הטבולין שבעה פעמים על אחורי ידו של המטהר מן הצרעת כבר נתבאר זה בי"ד מנגעים:
@390 **השרש** החמישי הוא שא נשפך הדם קודם הטבילה וההזאה שזכרנו תמות המשתלחת יקח שתים אחרות כי לא באה לכלל שלוח ואת מתה משתלחת קודם הטבילה והזאה יקח שתים אחרות וזה מבואר בנפשו כבר נזכר זה בי"ד מנגעים:
@390 **השרש** הששי הוא שלוח הצפור החיה יחוייב שיהיה מתוך העיר אל פני השדה לא כנגד ים או מדבר שנ' אל מחוץ לעיר אל פני השדה כבר נתבאר זה בשני מקדושין ובי"ד מנגעים והוא מבואר מזה שאם שלחה וחזרה שצריך לשלחה אפילו כמה פעמים בדרך שתהיה משולחת בעת התגלחת שנאמ' ושלח את הצפור החיה וגו' וגלח את כל שערו:
@390 **השרש** השביעי הוא שהצווי לקחת הצפורים הוא בכהן והלקיחה בכל אדם וכן שחיטת הצפור והטבילה בדם הצפור והזאה והתגלחת הוא בכהן כמו שביארנו ואולם השלוח לצפור החיה הוא בכל אדם הוא מבואר מהשרשי' הכוללים שאלו העניינים שיחוייב היותם בכהן יהיו נעים ביום ולא בלילה כבר נתבאר זה בספרא:
@390 **השרש** השמיני הוא שתגלחת המצורע הוא שהכהן מביא תער על כל בשרו הנראה ואפי' בית השחי ובית הערוה ולא נאמר ראשו וזקנו וגבות עיניו אלא למעט השער שבתוך החוטם לפי שאינו נראה כבר נזכר זה בשני מסוטה:
@390 **השרש** התשיעי הוא שאחר שגלח וכבס בגדיו וטבל טהור מלטמא בביאה ויכנס לפנים מהחומה ואולם לשאר הענינים הרי הוא בטמאתו הראשונה כי התורה ביארה שהטהרה אשר תהיה לו בזולת הטבילה הוא שיבא אל המחנה ולזה הוא מבואר שהוא טהור מלטמא משכב ומושב ואולם מה שאמר שישב ז' ימים חוץ לאהלו הוא לאסור לו תשמיש המטה כי הוא מזיק לבעלי זה החלי ולפי שה ההיזק אינו במצורעת באופן שהוא במצורע לא נלמד מזה שתהיה המצורעת אסורה בתשמיש המטה כבר נתבאר זה בי"ד מנגעים וכבר יתבאר שבאלו השבעה ימים הוא מטמא כלים במגע שנאמר יכבס בגדיו ולזה הוא מבואר שהוא אב הטמאה לטמא אדם וכלים במגע כר נתבאר זה בראשון מכלים והיא התגלחת השנית היא כמו התגלחת הראשונה ובכלל אם שייר שתי שערות לא עשה כלום שנאמר כל שערו כבר נתבאר זה בי"ד מנגעים:
@390 **השרש** הי' הוא שטהרת המצורע אינה אלא בכהן והוא מטהרו אע"פ שהוא זב או טמא מת מכיון שאינו מצורע שנאמר והעמיד הכהן המטהר את האיש המטהר ואם היה הכהן מצורע הרי אני קורא בו מיטהר לא מטהר כבר נתבאר זה בשמיני מתוספות נגעים:
@390 **השרש** הי"א הוא שהצפור השחוטה היא אסורה בהנאה כי התורה לא הגבילה שתאכל בכלל הנה יראה שהיא הפך המשולח ואולם המשולחת מותרת בהנאה כי התורה לא אמר' שישלח להקלה ולזה תהיה השחוטה אסור' ולפי שהמשולחת משולחת על פני השדה הנה אם כן השחוטה נקברת שם לפני המצורע כבר נתבאר זה בשני מקדושן ובי"ד מנגעים:
@390 **השרש** הראשון הוא ששעור נגע הבגדים הוא כגריס כמו הענין בנגעי אדם כבר נתבאר זה בי"א מנגעים:
@390 **השרש** השני הוא שג' סימני טומאה יש בבגדים והם ירקרק שהוא ירוק מאד ככנף הטוס והאדמדם והוא אדום שבאדומים והפשיון ובר נתבאר תנאי הפשיון ומהם נלמד בזה המקום כיצד בגד שנראה בו מראה ירקרק או אדמדם מסגירו ובשביעי רואהו אם פשה מחליטו ושורף את כל הבגד ואם לא פשה ועמד במראהו או שפשה וכהה משני המראות שהוסגר בהן או שהוסיף המראה להוריק ולהאדים ולא פשה יכבס מקום הנגע ויסגיר ובסוף שבוע שנית שהוא יום י"ג רואהו ואם כהה למראה שלישית הרי זה טעון כבוס והוא טהור ואם נשתנה הנגע למראה אחר כמו שהיה ירקרק ונעשה אדמדם או הפך קורע מקום הנגע ושורף מה שקרע ותופר מטלית במקום הקרע ופוטר שאר הבגד ומכבסו כלו כבוס שני ומטבילו וטהר ואם עמד כמראה שהוסגר בו בתחילה יחליטו ושורף את כלו היה ירקרק ופשה או אדמדם ופשה הרי זה פשיון ושיעור הפשיון הסמוך כל שהוא והרחוק או שחוזר כשהוסר הנגע הראשון שיעורם כגריס כבר נתבאר זה בשלשה ובאחד עשר מנגעים. וראוי שתדע שאלו המראות מצטרפות זו עם זו כבר נתבאר זה בסיפרא:
@390 **השרש** השלישי הוא שהמכבס את הנגע מכבס את הבגד המקיף את הנגע עמו שנאמר את אשר בו הנגע כבר ביארו זה בסיפרא וכשמכבסים את הבגדים מכבסים אותם בסממנין המעבירין על הכתמים שנאמר אם תכבסי בנתר וכבר נתבאר זה בי"א מנגעים:
@390 **השרש** הרביעי הוא שהנגע החוזר על הבגד אחר שטלו בו מלית אם חזר עור על הבגד ישרף ומציל את המטלית ואם חזר על המטלית ישרף הבגד עמו ואם טלה מן המוסגר בטהור וחזר הנגע על הבגד המוסגר ישרף והמטלית תשמש את הבגד שהיא תפורה בו בסמנין ר"ל שאם עמד בעינו שתי שבועות או פשה שורפין הכל כבר נתבאר זה בי"א מנגעים:
@390 **השרש** החמישי הוא שהבגד שבא בתחלה כלו ירקרק או אדמדם יזגיר אבל אם בא כלו ירקרק או אדמדם אחר ההסגר או אחר הפטור הרי זה טהור ואם אחר שכבס פשה ישרף כבר נתבאר זה בחמישי מתוספות בנגעים:
@390 **השרש** הששי הוא שאין מטמא בנגעים אלא בגד צמר ובגד פשתים כבר נתבאר זה בתשיעי מכלאים והוא מבואר שאם לא היה בו שיעור ראוי להשתמש בו לדבר מה כגון שיהיה פחות משלש אצבעות על שלש אצבעות לא יטמא כבר נתבאר זה בי"ב מנגעים ואין הבגד מקבל טמאת נגעים אם היה צבוע אפילו בידי שמים ואם היו נראים לבנים אפי' ששתים או ערבם צבוע הכל הולך אחר הנראה והנה נתפור הוא כארוג להשלים שעור בגד ואם תפר בגד מטלאים קטנים קצתם לבנים קצתם צבועים ונראה נגע בלבן ונתפשט ללבן אחר אף על פי שהצבוע ביניהם הרי זה פשיון והקש על זה ערב צמר או פשתים עם מין שאינו צמר ולא פשתים כגון צמר גמלים וצמר ארנבים או קנבס או צמר רחל בת עז הולכין אחר הרוב כבר נתבאר זה בי"א מנגעים ובשני מבכורות. ואולם כלי העור מקבלים טמאה פשוטיהן ומקבליהן כשהיו כלי לדבר מה שנאמ' כלי עור והוא שיהיה מעובד שנ' לכל אשר יעשה העור למלאכה כבר נתבאר זה בספרא והוא שיהיה מעור הב"ח הגדל בארץ כמו הפשתים שגדלין בארץ ואולם אם חבר להם מהגדל בארץ כל שהוא הרי הן מטמאין בנגעים אף על פי שהיה העור צבוע בידי שמים הרי זה מטמא בנגעים ויש פשיון בכלי עור בעוביו כאלו תאמר שפשה הנגע מתוכו לאחוריו או מאחוריו לתוכו כבר נתבאר זה בי"א מנגעים. וראוי שתדע שצמר ופשתים מטמאין בנגעים מיד שיטוו ואף על פי שלא לובן כיון שיש בפקעת כדי לארוג ממנה שלש על שלש שתי וערב בין שהיתה כלה שי או ערב היתה הפקעת מחוטין פסוקין אינה מטמאה בנגעים ואם היו שני פקועיות וחוט אחד מחברתן ונראה אחד כשתיהן שתיהן טמאות ואם נראה כאחד לבד היא לבדה טמאה וכן העניין בארוג אם השתי עומד המחובר לו ואם פשה מזה לזה שניהם טמאים כבר נתבאר זה בי"א מנגעים:
@390 **השרש** הז' הוא שהבגד המוסגר הוא מותר בהנאה אך המוחלט אסור בהנאה כי התורה חייבה שריפה לבגד המוחלט ולזה הוא מבואר שאם נתערב באחרים כלן אסורי' וכן אם חלקו לטלאים פחותין משלש על שלש כבר נתבא זה מי"א מנגעים:
@390 **השרש** הח' הוא שהבגד המנוגע בין מוסגר בין מוחלט אם בא אל הבית טמאהו וכבר יקרא בא אל הבית אם בא רובו שם וכן אם נכנס כזית ממנו טמאהו שנאמר אל נא תהי כמת כמו שהמת מטמא בכזית כן הענין בצרעת כבר נתבאר זה בי"ב מיבמות ובי"ג מנגעים:
@390 **השרש** הראשון הוא שהמצורע עומד חוץ לעזרת ישר' כנגד פתח המזרחי ומכניס ידיו לעזרה לסמוך על האשם אחר שהניפו הכהן עם לוג השמן כבר נתבאר זה בי"ד מנגעים ובשלישי מזבחים ובששי ממנחות:
@587 **ואולם** למה היתה זאת הכפרה בזה האופן הנה ראוי שנאמר בזה לפי מנהגנו והשגתנו ואם יש בזה מן העומק והקושי החזק. ונציע תחלה ונאמר כי מזבח הקטרת מורה על המציאות וההויה וקטרת של בין הערבים מורה על ההפסד כמו שהתבאר בפרשת ואתה תצוה והיו ממנה ארבע קרנות להורות על שההפסד לא יקרה לאדם מצד צורתו אך יקרה לו מצד ההיולי והם היסודות אשר בהמזגם קבל אלו הצורות קצתם באמצעות קצת והנה הקטרת אשר יקטירו עליו מור' על השכל ההיולאני אשר מדרכו שיתעצם במה שיריח האדם מאלו דברים המוחשים רוצה לומר מאופן החכמה אשר ביצירתם כשיופרדו מהם המשיגים ההיולאנים והנה השכל יקח זה המושג מהחוש והדמיון ויפשיטהו ממשיגיו ההיולאנים ובזה האופן ישוב המושכל בכח מושכל בפועל כמו שישים האש מצד הפרדה בקטרת אשר היה מורח בכח מורח בפועל ומזה האופן היו הסמים משל למושכלות כמו שבארנו בפירוש שיר השירים וזה המשל נכפל שם הרבה. והנה המנורה מורה על האופן שיוצא בו השכל ההיולאני מהכח אל הפעל מצד מה שתבין לו הנפש המרגשת והמדמה מהמורגשות כמו שביארנו בפרשת ויקחו לי תרומה ולזאת הסבה המנורה יותר קרובה לקדש הקדשים ממזבח הקטרת ולזאת הסבה היתה בפרכת צורת כרובים להעיר כי מה שבמונרה הוא הערה להשגת השכל ההיולאני שכל בפועל באופן שיהיה במדרגת הכרובים שהם שכלים נבדלים משיגים עצמותם ולזאת הסבה גם כן היתה המנורה מאירה למול קדש הקדשים ששם הכרובים פורשי כנפים למעלה ולפי שההשלמה בזה האופן לשכל היא יותר חזקה בעת המורה על ההפסד וחולשת הכוחות הגופיות והוא עת הזקנה והישישות כמו שנזכר בספר מלחמות יי' הנה העת שנתחנך בו המנור' בערב כמו שביארנו במה שקדם. והנה הכרובי' אשר בקדש הקדשים מורה על השכל הנקנה והשכל הפועל והנה השפע שיקבל השכל הנקנה מהשכל הפועל הגיע בנבואה ולזה היו פניהם איש אל אחיו אל הכפורת אשר על הארון להעיר על אפשרות הגעת הנבואה כי התורה נתנה על יד נביא ואם לא יאמן בנבואה תפול כל התור' וכבר התבאר בספר מלחמו' יי' כי המזגים יתחדשו במורכבות מפני מה שיתחדש מההתמזגות מה שיושפע מהכוכבים באמצעות ניצוציהם לפי מה שנתן להם השם יתע' מהכח ביום הבראם וכמו שיתחדש מההתמזגות כחות הגלגלים אלו המזגים המקבלים כפי כח ככב מהכוכבים ההולכי' ולפי מקומותיו מגלגל המזלות כן יתחדש ממניעיהם שכל הוא נימוס מהשיתחדש מהמזג כחותיה' ובאמצעותו ינתנו הצורו' באלו הדברים ההוים םוהוא השכל הפועל לפי מה שביארנו שם הנה זה מה שראינו להציעו בזה המקום קודם נתינתנו הסבו' במה שנזכר בזאת הפרשה ואחר זאת הצעה נאמר שכבר היה מן ההכרח שיהי' שם מה שיעיר שכבר יכפר השם יתעלה לחוטא כל עונותיו לא השגגות לבד וזה שאם יחשוב האדם שלא יתכפרו לו כמו אלו העונות יהיה מגיע מזה הפסד נפלא וזה שהחוטא מפני האמינו שלא יכפרו לו עונותיו ואם יכבס כתמי חטאיו בנתר התשובה והמעשים טובים הנה נתיאש מן הטוב ולא ישתדל בתקון מעשיו ודעותיו בראותו שכאשר אבד אבד ולזה סבב השם יתע' שיהיה שם יום אחד שיתכפרו בו כל העונות אחר השבר לב החוטא והכנעו בצום ובתשובה ולפי שזה הענין גדול וקשה ראוי שלא ישלם כי אם על יד היותר נבחר כי ליור נכבד יחסו הפעולות היותר גדולות בסוג ההוא ולזאת הסבה בעינה חייב שיהיה זה גם כן בנכבד שבמקומות והנה היתה זאת העבודה בבגדי לבן כי לגנות מה שיכפר עליו באלו העבודות היה בלתי ראוי שישלם הכבוד בזה הקרבן ולזאת הסבה בעינה היה הפר והשעיר נשרפים בזה האופן המגונה חוץ לג' מחנות והיה גם כן מת השעיר המשתלח בתכלית הגנות ובמקום שאין בו הנאה כלל שנאמר אל ארץ גזרה עד הגיע מהגנות בו שלא יוקח דבר ממנו לעבוד בו שום עובדה באופן מהאופנים והנה היה חטאת הכהן פר וחטאת ישראל שעיר לסבה בעינה שהיה חטאת כהן משיח פר וחטאת נשיא שעיר וזה היה לגודל מעלת הכהן כמו שביא' שם עד שהנכבד שבב"ח הוא אצלו בתכלית הפחיתות לחוזק המשכו אל השכל ומאסו ענייני החמר ולפי שכפרת שני השעירים היתה מיוחדת למה שיכפר עליו הפר היה ראוי שיוקחו שניה' יחד לכונה ההיא ולזה לא יתבאר אז אי זה מהם יכפר על הטמאה ואי זה מהם יכפר על כלל העונות ואולם יתברר זה באמצעות נתינת הגורל על יד הכהן הגדול לישב יותר בנפשותינו על שה מכפר על הטמאה וזה מכפר על כלל העונות כאלו היה מוגבל מהשם יתעלה מה שנתברר מפני הגורל כמו שאמ' בחיק יוטל את הגורל ומה' כל משפטו והנה היה המכפר על הטמאה ליי' מה שאין כן במכפר על כל העונות לפי שהעברה אשר בטמאה איננה מצד הענין בעצמו אבל היא כמו שביארנו שהיא להעיר על מציאות הצורה כדי שנעמוד מזה על מציאות השם יתעלה ולזה היה קרב ממנו דבר מה לשם יתעלה מדמו וחלבו ואולם המכפר על כלל העונות לא היה ממנו קרב לשם יתעלה כי אותם העונות מרוחקין מצד עצמותם וכל שכן הזדון בהן שיהיה השעיר ההוא מכפר עליהם והנה יטבול הכהן בכל עת שילבש בגדים להורות שהמכוון מהעבודה כלה שיתנקה מטמאות החמר ומהמרי המיוחס לו ולהורות על חוזק מעלת המכפר הזה בנקיות והנה היו לפי מה שאחשוב שני מיני אלו הטבלות הנזכרות לכונות שונות וזה שהטבילה תהיה בלבשו בגדי לבן הוא להעיר על חוזק טומאת הדבר שיכפר עליו וחלאתו ולזה יצטרך המכפר עליו לתכלית הטהרה כדי שיהיה נכון לטהר כמו זאת הטומאה הנפלאה והטבילה אשר תהיה אחר הפשיטו בגדי לבן הוא להעיר על חוזק טמאת מה שיכפר עליו וחלאתו ולזה כאלו השיגהו דבר מצטרף ליטפל עליו ולזאת הסבה היה שורף הפרים והשעירים הנשרפים טמא. והנה היתה הטבילה במקום קדוש כדי שתשלם העבודה הזאת הנכבדת בזולת יציאת בית המקדש כדי שלא יראה שהניח עניין העבודה ויצא חוץ למקדש וזה ממה שיוסיף כוונה לכהן בענין זאת העבודה והנה אחר שישחט כהן הגדול חטאתו יקטיר קטרת סמים דקה מבית לפרכת כי שם הדברים המורים על השכל שהוא בפועל והוא שכל הנקנה והנה תהיה הקטרת יותר דקה מהקטרת אשר יקטירו על מזבח הזהב לפי שהקטרת ההיא תורה על הכנת השכל היולאני ושכבר תצא אל הפועל וזה אמנם יהיה בהתלמדות וחקירה ואמנם הקטרת אשר יקטיר לפני לפנים מורה על השכל שיצא אל הפעל אבל יעתק מהעדר ההשתמשות בהשגתו אל שישתמש בהשגתו וזה דבר יותר קל מאד מהתלמדות ולהעיר על זה העניין היתה הקטרת ההיא יותר דקה כי אז ימשול בה האש בקלות יותר מהיר ותעלה עשנה בקלות והיתה הקטרת ההוא מלא חפניו כי השכל הנקנה הוא מה שהשיגה ידו במושכלות והיתה הכונה בהקטרת הכהן הגדול זה הקטרת לפני לפנים הוא להורו' שהוא ינהיג עצמו לפי מה שיחייבהו השכל הנקנה הלקוח ממה שיתנו מריחם אלו הדברים המוחשי' אשר בכאן אשר בא מהסידור והיושר ומהפלגת חכמת השם יתעלה והשפעתו הטובות הנפלאות מה שלא יעלם ובזה האופן יתנהג בדרכי השם יתעלה ויהיה זה סבה אל שישמר מהחטאים אשר סבתם הנטיה מהשם יתעלה ולפי שזה השכל ר"ל השכל הנקנה יעלה למעלה אל הנבדלים ויתאחד בזה ובזה האופן תגיע הנבואה אשר תביא ההאמנה בה להאמין בתורה הנה יעמד שם הכהן הגדול עד שיכסה ענן הקטרת אשר הכפרת עליו הם הכרובים כי מזה יעמוד על זאת הכונה ולזה חויב שיהי' בקטרת מעלה עשן כדי שיהיה מוחש עליית זה העשן לזה המקום ושיהיה העשן המורה על השכל הנקנה מורגש עם שזה יתבאר ממנו ששלמות זאת השפעה תהיה גם כן מצד הכח כאשר על הכפרת המעיר על השכל הפו על באמצעות הדברים המוחשי' אשר סמי הקטרת מעירים עליהם כמו שזכרנו במה שקדם והיה זה גם כן אצל התורה שהיתה בארון כי גם היא מישרת אל זאת ההשפעה הישרה נפלאה כמו שביארנו בתחלת זה הספר והנה לא היתה התורה מעכבת זה כי ההישרה אשר היא מצדה על צד היותר טוב לא שתהיה מהסבות ההכרחיות בזאת ההשפעה והנה יזה אחר כן מדם הפר על הכפרת הזאת אחת ולפני הכפרת שבע הזאות להורות כי מחשובתיו ותשוקותיו ופעלותיו המסודרות מגלגל המזלות ושבעה ככבי לכת לפי מקומותיהם מגלגל המזלות אשר בם באופן מה סבה הרבה מהחטאי' והפשעים ואם היה זה במקרה כמו שביארנו בספר מלחמות השם הנה ינהיגם לפי מה שיתנהו השכל השופע מה' ית' אשר הגיעה ממנה התור' וכאלו יתנקה השלם בעל השכל הנקנה מחטאיו בזה האופן ויהיה שכלו נקי מהחטאים אשר חטא ומחלאתם ולזה היתה זאת ההזאה באצבעו הימנית להעיר שיכוין בפעלותיו ודעותיו כלם שיהיו אל הימין לא נוטות ממנו ואח"כ ישחט שעיר החטאת אשר לעם ויזה ממנו בזה האופן בעינו אלא שלא יכפר בו שם כי אם על ענין הטמאה אשר אין המרי בהם מרי מצד עצמותם אלא מצד מה שכהן מההישרה לשכל בדעות האמתיות והיה זה כן כי גדלו עונותיהם מאד ובהם מהרחוק מהשם יתע' זה הקרוב הנפלא ואולם הכהנים למעלתם בעיון ובתורה הנה יהיו חטאיהם מועטי' וקלין ולזה יכפר עליהם יחד הפר בזה המקום הנכבד כי הם אם היה שיחטאו לא יהיה בחטא ההוא מהרחוק מהשם יתעלה הרבה כמו שהוא ראוי בחק השלמים. והנה לא תהיה טענה עלינו בזה אם לא היה שימצאו כהנים בלתי שלמים בזה האופן כי התורה אמנם תדבר בענינים מצד המציאות אשר ראוי שיהיו בו לא מצד הפעל כמו שהצענו בשרשים הכוללים. ואולם המון העם יחטאו הרבה וראוי שיהיה שם מה שיעירם על שאלו החטאים ראוי שירוחקו מאד כדי שישובו מחטאם ויכנע לבבם ולזה ימות השעיר הנושא אלו העונו' בזה האופן המגונה שלא יגיע בו תועלת ובמקום שלא יגיע ממנו תועלת להעיר כי החוטא המחזיק בחטאים ההם לא יהיה במציאותו תועלת כלל ולהורות שאלו העברות יהיו מועטות בכהנים לפי הראוי בהם לא זכרה התורה בביאור ענין הטמאות והחטאים כי אם בישראל. ואמר וכפר על הקדש מטמאות בני ישראל והתודה עליו את כל עונות בני ישראל את כל פשעיהם לכל חטאותם ואמנם בכהנים לא זכר זה אבל אמר וכפר בעדו ובעד ביתו והנה לזאת הסבה ג"כ היה ראוי שיהיה חטאת הכהנים יותר נכבד כי אין להם חטאין באופן מהגנות אשר ימצאו להמון העם ואחר כך יזה כמו שאלו ההזאות על הפרכת ולפני הפרכת מדם הפר תחלה ואחרי כן מדם השעיר לפי שבז' העניין יש הבדל גם כן בין הכהנים והעם וזה כי המקום ההוא מורה על ההשתדלו' במה שיצא בו השכל ההיולאני מהכח אל הפעל ולזה היתה שם המנורה והיו בכפרת הכרובים כמו שביארנו במה שקדם והוא מבואר שכמו שיש הבדל נפלא בין היחידים והממון בשכל הנקנ' כן יש הבדל נפלא ביניהם בהשתדלות בדרכים אשר הם הצעה להגעתו ואולם ההזאות אשר תהיה על מזבח הזהב להיותו מורה על מציאו' השכל ההיולאני והיה מציאות זה השכל שוה באנשים כלם הנה לא תהיה לכהני' לבד ולישר' לבד אבל תהיה להם יחד כשיערבו דם הפר ודם השעיר והנה כשיהיה על קרנות המזבח שהו' מור' על היסודו' שהם סבת ההפסד להעיר שיתנקה זה השכל ההיולאני מטמאת החמר ואח"כ יזו שבע פעמים על שטחו אשר בו יוקטר הקטרת המור' על הכנת זה השכל בהשגה להורו' שזה השכל יתנקה מהמחשבות והתשוקות והפעולות המסודרות לו מהגרמים השמימיים באמצעות החומר שיהיו סבה באופן מה לטעותו בהשגותיו ודעותיו והנה בהזאה הנעשית לפני לפנים ובפרכת שהיא אחת ואחר כן שבעה הערה על זה השכל הפועל שהוא נאצל מן השם יתעלה באמצעות מניע גלגל המזלות ומניעי ככבי לכת כמו שהצענו. והנה לא יהיה אדם באהל מועד בבאו לכפר בקדש כדי שישלם לו ההתבודדו' ויהיה יותר מוכן מפני זה להשיג הסבה אשר בעבורה צותה התורה זה ולזאת הסבה בעינה חוייב שלא יהיה אדם בין האולם והמזבח בבאו לכפר על אהל מועד וראוי שתדע שהשכל ההיולאני נפסד וכן ההשתדלות אל הפעל מאלו הדברים המוחשים כי בהפסד הנפש המרגשת יפסדו כחותיה אשר בהם תעזור אל השכל ההיולאני בהשגתו ולזה לא יהיה אחר המות תוספת שלמו' לשכל הנקנה כי אבדו כליו אשר בהם יוכן לו זה ולזאת הסב' היה במזבח הקטרת ובמנורה מה שיורה על ההויה וההפסד כמו שביארנו בפרשת ואתה תצוה ואמנם השכל הנקנה אינו נפסד כמו שביארנו בספר מלחמות ה' ולזה לא היה בו מה שיורה על ההפסד אבל היתה הקטרתו בבקר לבד שהוא מורה על ההויה כמו שביארנו בפרש' ואתה תצוה ולהעיר של זאת הסבה לא היתה הקטרתו כי אם בבקר היה ראוי שיהיה הסרת הכף והמחתה מקדש הקדשי' בעת הקטרת הקטר' של בין הערבים להעיר אז הכהן המקטיר זה הקטרת על ההבדל שיש בין שני אלו המיני' מהקטרת כי זה לא יוקטר בעת הערב כמו העניין בקטרת אשר יקטירו על מזבח קטרת הסמים ויתעורר מפני זה אל מה שכונה התורה בזה והנה לא היתה הקטרת זה הקטרת המורה על השכל הנקנה כי אם פעם אחת בשנה למעוט המצא זה העניין בשלמות להמון האנשים. ולזה תמצא האנשים שלמי השכל מעטי המספר והנה היתה זאת ההקטר' בחדש השביעי שיכנס בו השמש במזלות הדרומיי' שיש בו רושם אל ההפסד כמו שיתבאר בטבעייות לפי ששלמות זה השכל הוא נמצא יותר עם חולשת כח הגו כמו שביארנו בספר מלחמות ה' ובביאורנו לספר הנפש וכבר היה זה בעשור לחדש להורות על שמספר השכלים הנבדלים הם עשר' והעשירי הוא קודש והוא הש"י והנה היה היום ההוא אסור בהתעסקו' בצרכים הגופיים והמחוייב בענוי נפש כדי שיכנעו יותר ויעשו תשובה כי בה תלוי עניין הכפרה כמו שביארנו ולזאת הסבה היתה התרועה בר"ח הזה כמו שיתבאר במה שיבא ובכאן נשלמה הסבה במה שנוהג ביום הזה מהעבודות ויתר העניינים והוא נפלא מאד ומסכים לענייניהם עד שנעיין זאת העבודה מכל צדדיה יעיר במה שאין ספק בו שהכונה בה הוא מה שזכרה וזה הוא מסגולות האמת ר"ל שהוא מעיד לעצמו מכל צד ומכל פנה:
@587 **והנה** זכר בתחלת סדר עבודת יום הכפורים שהוא הולך במדרגת ההשלמה לענייני הקרבנות והטהרות כמו שהתבאר מדברנו וכבר התבאר מענין העבודה ההיא שהיא היתה במקום מיוחד וע"י איש מיוחד ולא היתה כי אם פעם אחת בשנה וכי זה כלו ממה שיישיר אל שאין בכאן כי אם אלוה אחד ולא לבדו תהיה העבודה ולזה סמך לזה האזהרה מעשיית הקרבנות בזולת המקום המיוחד אף על פי שיעשהו להשם כי זה אולי יביא להאמין רבוי באלהות ולזה תמצא בישראל כשהיו עובדים ע"ז שכבר היתה עבודתה נעשית בכל אחד ממקומותיהם כמ"ש כי מספר עריך היו אלהיך יהודה ולפי שהזביחה שהיתה נהוגה בזמנים ההם לשדי' לא היה בעניינה עבודה אחרת זולת השחיטה שהיתה נעשית לכונה שיתחברו עם השדים ויודיעום העתידות כמו שזכרנו הנה זכר זאת האזהרה אחר הזהרת שחיטת קדשים בחוץ ואחר שזכר זאת הזהיר מהעלאת הקרבנות חוץ לעזרה ואף על פי שיקריבום לשם יתעלה לסבה שזכרנו והוא לישב יותר בלבנו אמונ' הייחוד ואחר כך הזהיר האזהר' מאכילת הדם כי בזה תשלם יותר הכונה אשר בעניין הקרבנות כמו שזכרנו כי בזה יגדל ענינו בעיני האנשים ולזאת הסבה צוה לכסו' דם חיה ועוף עם שבו תועלת להרחיק שלא יזבחו זבחיה' לשעירי' כמו שביארנו ואחר שנשלם לו זה בא להשלי' דין טמאה אחת לא זכרה עם שאר הטמאות והוא טמאת נבלת עוף טהור לפי שענינה נבדל משאר הטמאות וזה שהיא לא תטמא מצד שנעדרה צורתה מפני כי צורתה רחוקה מאד מצורת האדם ולזה לא ינהג בעוף טמאה כמו שינהג בחי ההולך ואמנם תטמא מצד שנעדר ממנו תועלת ההזון לבעלי התורה ולזה לא תטמא אלא בהיותה בבית הבליעה וידמה כי סמך עניינה לענין הדם כי הדם אינו בעצמותו בלתי נאות למזון אבל הוא היותר אמתי במזון כשהיה חלק מהב"ח ואולם יקרה לו שיהיה בלתי נאות למזון מפני קלות הפרד ממנו החלק האוירי והאשיי ולזה יהיה ארציי בעת שיזון האדם ממנו ובלתי נאות להזון ממנו כמו שהתבאר בספר ב"ח הנה אם כן ענין הדם אשר הוא רע הוא מפני טבעו בעת התאכל לא מפני טבעו בעצמותו וסמך עניין העריות לענין הטמאות כי הם גם כן להרחקה מהנטיה מהחסרונות החמר שהוא סבת הטמאה עם שכבר יקרה בהרבה מהם שיעדר מהמשגל ההוא התועלת אשר בעבורו הוכן זה הכח לאדם והוא מבואר במשכב זכור ובמשכב הבהמה וזה יקרה ג"כ הרבה משאר העריות כי אשר ישכב עם שאר בשרי ישתדל לכסות קלונם שלא יהיה מהמשכב ההוא פרי עם שיקרה מזה שאר הפסדים שזכרנו והנה זכר עניין העריות בהדרגה וזה שהוא הקדים ערות אב לערות אם כי יחס הולד לאב יותר חזק מיחסו לאם כי האב נותן מה שהוא במדרגת הפועל להולדה והאם נותנת מה שהיא במדרגת המתפעלת בהולדה כמו שהתבאר בטבעיות ולא אמר אביך הוא לא תגלה ערותו כמו שאמר אמך היא לא תגלה ערותה לפי שאף על פי שלא יהיה אביו היה גלוי ערותו מרוחק ממנו מה שאין כן באמו. ואח"כ זכר ערות אשת אביו אף על פי שאינה אמו כי הוא ערות אביו אלא שהיה בזה העני למטה מערות אמו ומערות אביו וזה מבואר בנפשו כי אין אשת הקרוב קרוב בקרובתו ואחר שזכר מה שיתרחק ממנו מההורי' זכר ערו' האחות איך שתהיה אחותו כי היא שאר בשרו והמשיך לה הרחקת הבעילה לנולדים ממנו שהם בשר מבשרו כמו בת בנו ובת בתו כי הם מאוחרים בזמן ולזה זכרם בסוף ושתקה התורה מבתו כאלו תאמר כי לגודל הגנות בזה אצל כל האנשים לא תצטרך התורה להזכיר זה ואחר זה זכר ערות האחות מצד מה שהיא בת אשת אב עם היותה אחות כי מצד היותה אחות כבר קדמה האזהרה בה ואולם עתה יוסיף להזהיר בה כשקרה עם זה שתהי' בת אשת האב ומזה הצד שהיא למטה מאד מכל מה שקדם באלו העריות ואחר שהשלים המאמר בערות האחות שהיא שארו זכר הערוה שתהיה בשאר האב והאם כי השארו יותר קרוב משאר ההורים וזכר תחלה שאר האב לסבה בעינה שזכר תחלה ערות האב וראוי לעיין למה מנעה ערות אב ואחי האב ולא מנעה שאר הזרים שהם שאר בשר בזולת הצווי הכולל במשכב זכור. ואח"כ זכר ערו' אחי האב כי הוא כמו בשר אחד עם ערות האב ואחר שהזכיר עניינו להיות המשגל ההו' זר מאד רוצה לומר משכב זכור ולפי שזכר ענינו השלים המאמר בערות אשתו שהוא למטה ממנו בקרבה ולמטה מאחות אב ואחות אם ואחר שזכר ערות מה שימשך מההורים משאר בשר ומצד האישות אשר לשאר הבשר בא להשלים מה שימשך מצד האישות לשאר הקרובים והוא ראוי שיקדים אשת אחיו לאשת בנו לפי הסדור הקודם ואמנם זכר תחלה אשת בנו לפי שאשת אחיו תהיה בקצת העתי' מותרת והו' כשמת בלא ולד כמו שיתבא' בפרשת יבמה ולזה הקדימה התורה ערות אשת הבן לערות אשת האח ואחר שזכרה העריות הנאסרות לו מצדו זכר העריות הנאסרות לו מפני היותם שאר אשת כי הם בזה העניין למטה מהעריות שהם שארו ושאר הוריו והקדים לזכור מה שהיה משאר אשתו שאין בו התר לעולם ואחר זכר ערות אחות אשתו כי היא תהיה מותר' לו לאחר מיתתה ואחר כך זכר ערות הנדה וערות אשת איש כי הן דומו' בזה הענין לערות אחות אשה וזה שכמו שערות אחות אשה אינה אסורה אלא בעת היותה אחות האשה וזה יהיה בחיי אשתו כי אחר מיתתו אינה אחות אשתו כן ערות הנדה לא תהיה אסורה אלא בעת היות טומאתה בה וערות אשת איש לא תהיה אסורה אלא בעת היות ואשת איש והנה זכרה התורה ערות אשת איש בסוף אלא העריות לפי שכבר היה מפורסם גם בשמנים ההם גנות הבא על אשת איש ולזה אמר אברהם על אשתו שהיא אחותו כדי שלא ימיתוהו למען ישכבו אחד זה עם אשתו וכאלו ביאר' התורה בזה שאלו העריות הם יותר מגונות מערות אשת איש עם היותה בתכלית הגנות למה שיגיע מזה בענייני' האנושיים כי האדם כשלא ידע שאשר תלד אשתו הוא בנו לא ישתדל במוסרו ובתקו' הנהגתו ויהיה זה סבה להבצר השלמו' מהנולדים כי יצר לב האדם רע מנעוריו ואולם בעניינים המדיניים הוא מבואר כי זה יהיה סבה להריגת האנשים קצתם קצת ברצות האחד לקחת אשת חבירו בחזקה עם שזה יהיה סבה אל שלא תהיה בכאן משפחה כי לא יהיה יודע האדם אי זה הוא אביו ואי זהו בנו ואיזה אחיו והנה התועלת בענין המשפחה בדברים המדיניים הוא במואר והנה זכר אחר זה עניין המולך וערות הזכר וערות הבהמה לסבה שזכרנו בביאורנו בזה במקום:
@587 **ואחר** שנשלם לנו הסדור בזה הענין ראוי שנעיין בהתר ספר אחד יסופק במה שנזכר מהעריות בזה שכבר זכרה התורה בעריות הזכור ערות אביו ואחי האם לא זולתם מהזכרים שהם שאר בשר כמו האח והבן והנה לא זכרה התורה גם כן ערות אחי אם ואשת אחי אם כמו שזכרה ערו' אחי האב ואשת אחי האב והנה יראה שכבר היה ראוי שיהיה היחס בזה אחד כי הוא שאר האם ונאמר כי העזות יותר נפלא כשיבעל ענף השרש ממה שהוא כשבעל הענף הענף או כשיבעל השר' ההענף והוא מבואר בנפשו וכ"ש כשהיה השרש מי שהוא השרש האמתי בהולדה והוא האב שהוא השרש הפועל בהולדה ולזה היה יותר חזק הגנות כשיבעלהו הבן מגנות בעילת האח והבן וזה שהבעילה יש בה שררה מה לבועל על הנבעל ומי שישתרר על אדוניו הוא יותר חזק הגנות מהשתרר על בני גילו אל על מצרפו ועוד שהוא ישים בזה הפעל אותו מתפעל ממנו וזה בתכלי' הגנות ולהעיר שיחס הבן לאב יותר חזק מיחסו לאם כמו שיתבא' בטבעיות היתה ערות אשת אב אסורה מצד מה שהיא אשת אב ולזה לא היתה ערות בעל אמו ואסורה מצד מה שהוא בעל אמו אבל תאסר עליו לבד מצד היותו זכר ולזאת הסבה ג"כ נאסרה ער'ות אחי האב כי הוא כמו בשר אחד עם האב ולא נאסרה ערות אחי האם כדי שנתעורר מפני זה אל שהמבוא אשר בהולדה לאב ולאם הוא יותרק אמתי לאב ממה שהוא לאם ומזה המקום יתבאר שלא נסר מהזכרים מפני שאר בשר כי אם האב ואחי האב שאם היתה כונת התורה שינהג זה האור בכל הזכרים שהם שאר בשר היה ראוי שתזכור זה בזכרים אשר זה הדין ראוי שיהיה בהם יותר חלוש לא הזכרים שזה הדין ראוי שיהיה בהן יותר חזק וכבר נשלמה הסבה בסדור מה שנזכר בזאת הפרשה וראוי שתדע שענייני זאת הפרשה כולם השתתפו בשיש בהם חיוב כרת או יתלה בהם מה שיתחייבו בו כרת וזה שענוי יום הכפורים והשביתה בו ממלאכה ושחיטת הקדשים בחוץ והעלאתם בחוץ ואכילת הדם יתחייבו בהם כרת וכסוי הדם בחיה ובעוף הוא לשמירת שלא יאכל הדם שיש בו חיוב כרת כמו שנזכר שם וטמאת נבלת עוף טהור יתלה בה מי שיתחייבו בו כרת אם לא יטהר ממנ' כמו שאמר ואם לא יכבס ובשרו לא ירחץ ונשא עונו וכן הקריבה אל העריות לגלות ערוה נתלה בו' מה שיתחייבו בו כרת והוא גלוי ערוה וכן גלוי העריות וההעברה למולך יש בהם חיוב כרת כמו שנזכר בזאת הפרשה ואולם התועלו' המגיעו' מזאת הפרשה הם תשעה:
@686 וראוי שנזכור הסבה בסדור דבריה קודם שנזכיר התועלת המגיעי' ממנו ואמר כי מפני שזכר העריות אשר התחלתם הוא ערות הורים בא להזכיר בזה המקו' הצווי ביראת ההורים ולהעיר שהכונה בכל אלו הוא להתקרב אל השם יתע' לפי מה שאפשר כמו שהתבאר מדברנו המשיך המאמר בהדרגה מזאת המצוה שהיא תחת דבור כבד את אביך ואת אמך עד שהגיע המאמ' אל הדבור הראשון שהוא אנכי יי' אלהיך ולזה זכר שמירת השבתות אחר זה כי היא קודמת למצות כבד. ואולם לא תשא היא מצד מה שהיה ממנה בדעות תחת לא יהיה לך כמו שהתבאר מדברינו במה שקדם ולזה השמיט זכרונה וזכר עניין ע"ז אמ' אל תפנו אל האלילי' ולהעיר שהמכוון בקרבנות הוא להשיג הש"י כמו שהתבאר מדברינו בהם זכר אחר זה קצת דיני השלמים והנה בחר להזכיר בכאן השלמי' מבין שאר הקרבנות לפי שאינם באים על חטא ולזה יתפרסם יותר בהם שהם לעבודת השם יתע' ולתכלית שנשיג מענינו מה שאפשר ולזה היתה בהם התנופה שהיא מעירה על זה ההערה נפלאה ולפי שכבר נשלמה זאת ההערה בזה שב להזכיר קצת המצות שהם תחת כבד באופן מה אשר בהם תועלת נפלא בעניינים המדיניים והוא חנינת העניים ממה שהשפיע השם יתע' לאדם מהטובות ואחר שזכר אלו המצות שהם תחת דבור כבד זכר קצת המצות שהם תחת הדברות שהם אחריו ולפי שדיני מה שתחת לא תרצח התבארו באופן שלם בפרש' ואלה המשפטי' ודיני מה שתחת לא תנאף התבארו בפרשה הקודמת הנה נעתק המאמר אל מה שתחת לא תגנוב והוא גנבה הממון ומה שיעכב בידו מממון חבירו שלא כדין היה שיהיה זה בגנבה או בגזל או באיחור נתינת לבעל חק חקו נכלל עם זה שבועת שקר מצד מה שימשך ממנה מההפסד בדברי' המדיניים ואחר כך זכר קצת המצות שהם תחת לא תענה ברעך עד שקר שהם באופן מה והוא מה שיחטא איש לאיש בדבור היה שיהיה זה בקללה או שיתעה אותו בדבריו מדרכי התורה או שיעות הדין באיזה אופן שיהיה או שיספר לו לשון הרע ואחר כך זכר קצת המצות שהם תחת לא תחמוד באופן מה והם המצות אשר עקרן בלב אשר בהם ישלם הקבוץ המדיני בשלם שבפנים והוא מה שיחטא איש לאיש בשנאתו אותו בלבבו והמשיך לזה האזהרה מהעניינים המביאים אל השנאה בלב וצוה לעשות הפך זה והוא שיאהב האדם רעהו כמהו. ואחר שנשלם לנו זה בסדור הדברות במה שבין בני אדם והיה שהזהיר בעניין העריות מערות הבהמה הוסיף בזה המקום לגלות טעם זאת האזהרה כי עם שהיא מביאה להמשך לעניין משגל אשר בו הרחקה מכל שלמות אנושי הנה בזה עוד הפסד בדברים הטבעיים ובדעות כמו שהתבאר מדברינו ולזה הזהיר מהרבעת הבהמה כלאים כי זה יגיע להפסד שתפסק ההולדה עם שזה יביא אל שנסכל מציאות הצורה אשר בה יוחד מין מין ויהיה זה סבה אל שנכחש במציאו' השם יתע' כמו שביארנו במה שקדם ולזה המשיך לזאת האזהרה מזריעה השדה כלאים ומלבישת שעטנז ואף על פי שאין בזה הפסד בדברים הטבעיים מפני הפסד שיקרה מזה בדעות והמשיך לזה האזהרה מהמשגל עם האשה שהשיא כמו כלאים רוצה לומר שיש בה צד שהיה בו אשת איש וצד אחר איננה בו אשת איש והיא שפחה חרופה ולפי שהזהיר מענין הצמחים ממה שיש בו הפסד בדעות המשיך אחר זה הצווי בהם במה שיש בו תועלת דעות והוא עניין הערלה ונטע רבעי כי זה עם שיישירנו להאמין שיש בכאן אלוה הוא הפועל על כל אלו הדברים הנה יעמידנו על סוד מסודות הטבעיים והוא שהזרע בצמחים לפי שהוא מותר המזון המצומק והמבושל כמו שהתבאר בטבעיו' הנה בראשית העניין לא יתחזק הטבע על זה כי מזונו יכלה בגדול גופו ולזה אם היה שיהיה שם מותר לא יהיה באופן שישלם החום היסודי בו עם שבזה תועלת להרחיק מהפעולות המגונות שהיו עושין עובדי עבודה זרה למהר הוצאת האילנות פרים כמו שזכר הרב המורה אשר מכללם היה מה שיביא לחלל הבנות להזנותם כמו שזכר ולזה זכר אחר זה אל תחלל בתם להזנותה אחר שהזכיר קצת דברים שיהיו מחקות עובדי עבודה זרה כמו האכילה עם הדם והנחש והעוננות ומה שנמשך לזה מאלו האזהרות עם שבאלו האזהרות תועלת בדעות והוא שאלו הדברי' כלם יביאו להכחיש במציאות השכל ולהאמין שלא תהיה בכאן התחלה כי אם החמר כמו שהתבאר מבאורנו לאלו האזהרות ולזה המשיך לזה הצווי לשמור השבתות ולירא המקדש כי הישיר אל ההאמנה במציאות הצורות ובמציאות הצורה הראשונה והוא השם יתע' וסמך לזה האזהרה מהאוב והידעוני כי הם מביאים להפך זאת הכונה ולזה החמירה התורה בהם והיה ענשה הקשה שבמתות והיא הסקילה להעיר על שאין הטוב בנמצאות מצד החמור כי אם מצד הצורה צותה התורה אחר זה לכבד איש שיבה כי אז הוא בתכלית החסרון מהחמר חולשת הכלים הטבעיים וזה ממה שיורה כי הוא יכובד אז כבוד נוסף מפני התחלה אחרת והיא הצורה המשכלת כי פעולתה היא יותר חזקה אז כמו שנזכר בספר הנפש וכבר אמ' אליהוא בביאור זה אמר בישישים חכמה וארך ימים תבונה ולזאת הסבה צוה לכבד החכם ולפי שזאת המצוה היא תחת דבור כבד באופן מה המשיך לה האזהר' מהונות הגר בממון ומעשיית העול במשפט והמידה והמשקל והמשורה שהוא תחת לא תגנוב באופן מה והשמיט לא תרצח ולא תנאף לסבה שזכרנו במה שקדם ואחר שנשלם לו זה שב להזכיר מדרגות העונשים על הרבה מאלו האזהרות והתחיל מהמולך לחזק ההפסד אשר בעניינו בשלמות האנושי ולזה היה ענשו בקשה שבמיתות ואחר זה המשיך לו עניין האוב והידעוני וביאר שהוא בכרת להעיר כי הם גם כן יבאו לכמו זאת האמונה הנפסדת כמו שהתבאר מדברינו ובסוף העניין ביאר עוד שהעונש עליהם הוא סקילה והמתין זה עד סוף הפרשה לשתי תועלות האחד הוא כי בזכירת זה במקומות רבים תועלת להתרחק יותר מהם כמו שיעשה הרופא שיזהיר החולה מן המאכלים הרעים בתכלית שיוסיף להזהירו על זה פעמים רבות. והשנית היא כי בזה התועלת להעמידנו על כונת התורה בעריות ובמאכלות האסורות ובעניין האוב והידעוני כמו שנבאר אחר זה ולפי שהוא בא לזכור אחר זה הענש על ענייני העריות אשר היתה התחלתם ערות ההורים והיה בגלוי ערות ההורים הבא ממעוט היראה מהם עד שימשך מהם ההפסד גם כן שיקרה בשאר העריות כמו שהתבאר מדברינו במה שקדם באר תחלה עש המקלל הוריו וזכר תחלה שהוא בסקילה ואח כך זכר ענש גלוי ערו' אשת איש כי הוא יותר כולל עד שהבא על הרבה מהעריות יתכן שיתחייבו עליהם משום אשת איש ומשו' ערוה והמשל שהבא על אשת האב בעת היותה אשתו יתחייב עליה משו' אשת איש ומשום אשת אב ואחר כך זכר עונש גלוי ערות אשת אב והמשיך לזה עונש העריו' שהם במין האנושי בסקילה והם הכלה והזכור והמשיך להם מה שהיה מהם בשרפה כי היא היותר קשה שבמיתות אחר הסקילה ואחר זה זכר עונש הערוה שאינה במין האנושי והיא השכיבה עם הבהמה והקדים זכרונה לשאר העריות לחוזק הגנות בה לחוזק העונש אשר בה על ידי ב"ד ואחר הוסיף להזכיר שנית שהעונש על שאר העריות הוא כרת להוסיף הרחקה מהם וביאר שאם זה העונש יקרה כשיתפשט זאת העברה באומה שתקיא הארץ אותם כאשר קאה את הגוי אשר לפניהם וסמך אל זה העניין המאכלות האסורות והאוב והידעוני להעיר על הכונה אשר בעבודה באו המצות באלו הדברים כלם והוא שנהיה נכונים לשלמות השכל בעיון באופן שנהיה לשם יתע' והוא מבואר שעניין האוב והידעוני הוא לזאת הסבה בעינה כמו שהתבאר מדברינו בהם וממה שקדם מדברינו בזה התבאר התועלות המגיעות מהם ואולם שרשי אלו המצות הנה המצוה הראשונה הוא ליראה מההורים:
@778 **והנה** זכר תחלה מה שהוזהרו הכהנים מהטמא למתים מפני שהשלים הפרשה הקודמת במה שיש בו אזהרה מהנטיה אחר חסרונות החמר כמו שביארנו הנה הזהיר הכהנים מלטמא למתים להעיר אותם על מה שיש בחמר מהחסרונות למען ישתדלו בהשלמת הצורה והיו הם יותר נזהרים בזה משאר האנשים לפי שהם נבדלו לעבוד השם יתע' ולהורות משפטיו ותורתו לישראל ולזה היו עושים העבודות שזכר במקדש ליסד בלבן מציאות הצורות על מדרגותיהם אשר מהם יעמדו על מציאות השם יתעלה ועוד כי מפני שהם עומדים במקדש ולא יוכלו לעבוד בטמאה הנה ראוי גם כן שיהיו נזהרים על זה יותר משאר האנשים והנה גם כן אחר שזכר עניין הטמאות והקרבנות והנמשך להם מהמצות שזכרנו בסדור ובהדרגה שב להזכיר תנאי מה בכהנים המקריבים מצד היותם מקריבים קרבנות השם יתעלה והתחיל להזכיר שלא יטמא למתים לסבה שזכרנו והוא להעיר אותם על חסרון מחמר ועל מציאות הצורה ולזה יהיה מחמר נתעב בזה האופן בסור הצורה ממנו ואחר זה הזהירם מקרוח קרחה בראשם על מת כמו שהיו עושים הגוים הקודמים וזה היה להעיר על מציאות הצורה ושובה אל האלהים אשר נתנה ולא תאבד באבוד הגוף ולזה אין ראוי לאדם שיתבעל במיתת רוביו בכמו זה האון מההפעלות כל שכן אלו האנשים מצד מעלתם וכן הענין בשריטה בבשר על המת לזאת הסבה בעינה והנה הוצרכה התורה להזהיר הכהנים מאלו הדברים ואף על פי שהם מכלל ישראל שהם מוזהרים על זה ואולי יחשב כי למעלתם יהיו ראוי שיתפעלו מאד במות להן מת מצד שנפקד ממנו השלמות אשר היה ראוי שיקננה מצד זאת הכנה הנוספת בקנין השלמות האנושי ועוד כי מפני שאי אפשר לכהנים להתעסק בקבורת קרובים זולתי הקרובים הנמנים בתורה אולי יחשבו שיהיה ראוי להם שיעשו כמו אלו הפעולות על מתיהם להראות עוצם הפעלותם על הפקדם כדי שישלימו בזה האופן מה שחסר להם מהאנינות על מתם מפני היותם בלתי מתעסקים בקבורתו והמשיך האזהרה מלגלח פאת זקן אל האזהרה מקרוח קרחה בראשם מצד שהנושא לאלו האזהרות יחד הוא השער ופאות הזקן תלויות גם כן אל שער הראש וכבר נתבארה הסבה אשר בעבורה ביארה התורה וצותה שלא לגלח פאת הזקן במה שקדם עם שכבר אפשר שנכפל זה הצווי בכהנים כי לפי מה שאחשוב היה זה דרך כומרי עבודה זרה כמו שהיה דרכם להקיף פאת ראשם והיה אפשר שיחשב מפני זה שיעשו כן כהנים השם יתעלה להיותם נבדלים לעבודתו אם שבזה יהיה היופי והנוי נמצא בהם יותר והוא מה שרצתה התורה בהם ולזה צותה לעשות להם בגדי קדש לכבוד ולתפארת ולזה הוצרכה התורה לכפול האזהרה בזה בכהנים. והזהירם אחר זה מלקיחת אשה זונה וחללה וגרושה כדי שיהיה זרעם יותר נבחר כדי שיהיה ראוי לעבודת השם יתעלה ובא זה בסדור ראוי כי הזנוה היא היותר מגונה כי היא נבעלת למי שהוא אסור לה אסור שוה בכל ישראל ואחר כך החללה כי היא נבעלת למי שאסור לה מצד תוספת קדושתו וזה בלתי מגונה כמו הראשונה כל מה שמרוחק אצל כל האנשים הוא יותר מגונה בעצמותו ממה שאינו מרוחק כי אם מקצת האנשים לתוספת מעלתם ואחר כך זכר הגרושה שאין בבעילתה אסור אבל יורה היותה גרושה כי היא בלתי נאותה בתכונתה וענינה ואחר כך זכר שיהיו גדלי המעלה בעיני ישראל כי בזה תועלת לישראל להישרים לעבודת השם יתעלה כי מפני ראותם כי אלו הם מכובדים מפני היותם עובדים השם יתעלה יתבאר להם עוצם מעלת השם יתע' ויתיישרו מפני זה לעבודתו ולעצם כבודם הפליגה התורה בענש בת כהן כי תחל לזנות כי היא מחללת כבוד אביה אשר לו כבוד נוסף על כבוד ישראל ולזה ראוי שיהיה ענשה יותר עצום מעונש בת ישראל. ואחר כך הפליגה התורה באלו הענינים בכהן גדול ליתרון מעלתו וצותה שלא יפרע ראשו כלל ולא יפרום בגדיו כלל לפי שהוא תמיד במקדש כי הציץ הוא על מצחו תמיד לשאת את עון העדה כמו שהתבאר במה שקדם ואולם שאר הכהנים אינם מוזהרים בזה אלא בשעת עבודה לפי שאינם עובדים תמיד והרחיקתהו התורה יותר משאר הכהנים מלטמא למתים לעצם מעלתו כי הוא ראוי שיתרחק יותר משאר האנשים מחסרונות החמר כאלו ביארה התורה שכל מה שיהיה האדם יותר שלם בעיון ראוי יותר שלא יתפעל מחסרונות החמר וכאלו ביארה שכל מה שיהיה האדם יותר שלם בעיון ראוי שיתפעל יותר מעט ממקרה המות כשיקרה לאחד מקרוביו ולזה ביארה שהאנינות לא תמנעהו מעבודה ואף על פי שתצטרך הכונה בעבודה כמו שקדם עד שכבר הרחיקה התורה כל מה שיבלבל הכונה בבא כהן לעבוד ולזה היה שתוי יין נמנע מעבוד עבודתו ואולם שאר הכהנים שאין מעלתם בזאת המדרגה העצומה לא הותר להם לעבוד באנינות הנה בענין לקיחת אשה הפליגה התורה בו למעלתו יותר משאר הכהנים. ולזה לא התירו לו שום בעולה ולא אלמנה אפילו מן הארוסין להעיר על עצם מעלתו ואחר זה הזהיר שלא יגש להקריב כהן בעל מום כי בזה האופן יגיע הפך כונת התורה והוא כי התורה צותה שיהיו להם בגדי קודש לכבוד ולתפארת באופן שימצאו להם הנוי והיופי לכבוד השם יתע' כי זה ממה שיישיר לעבודתו יתעלה ולזה גם כן צוה שנכבדם לכבודו יתעלה ואלו היו הבעלי מומין עובדים היה זה מבוא לבזותם ולבזות מעשיהם לפחיתות צורתם כי הרבה תמצא שיהיו נבזים בעיני האנשים הבעלי מום לפחיתות תמונתם ואחר זה צוה שלא יעבדו הכהנים הטמאים כי הטומאה באה מצד החומר כמו שביארנו בעניין הטומאות וזה הפך המכוון בעבודת הכהנים כמו שהתבאר מדברינו בענין הקרבנות ולזאת הסבה בעינה הזהירה התורה מאכילת קדשים בטומאה והמשיך לזה השלמת הביאור בדיני מי שאפשר בו אכילת הקדשים ומי שאי אפשר בו זה והמשיך לזה דין אוכל תרומה בשגגה ואחר שהשלים הביאור בתנאי הכהנים המקריבים והאוכלים הקדשים והתרומה ביאר תנאי הדברי' הקרבים וביארה התורה שאין ראוי להקריב בעל מום וזה לסבה בעינה אשר הזהירה התורה שלא יהיה הכהן המקריב בעל מום והמשיך לזה האזהרה מלסרס הב"ח מצד מה שזר שאלו העניינים אשר ישחתו בהם כלי ההולדה הם מומין בקרבנות ולזה השלים אותו המאמר בכללות שאותו הפעל מהסרוס ראוי שירוחק מאד ואחר כך השלים המאמר בתנאי הקרבנות ומנע מי שלא יולד לידה טבעית ומחוסר זמן כי אולי הוא בלתי שלם הבריא' כמו שביארנו במה שקדם והזהיר אחר זה משחיטת אותו ואת בנו שלא ידמה שתהיה הקרבתנו באו הבעלי חיים לשנאתנו אותם ולרצותנו לכלותם ולזה לא נשחט האם והבן ביום אחד כי זה יביא אל שתעלם הכונה בקרבנות וזה מבואר מאד וכבר מנעה התורה זה הענין אפילו בחולין כדי שלא יחשב שיהיה זבחנו אלו הבעלי חיים להיותם שנואים ולזה נשתדל לכלותם כי אין העניין כן אבל הם מכוונים אצל הטבע ובמציאותם תועלת מבואר ולזה ישתדל לקיים מינן כדי שיהיו נמצאים למין האנושי תמיד להזון מהם כי הוא התכלית אשר בעבורו נמצאו ואחר זה צותה התורה שבעת הזביחה לקדשים תהיה המחשבה בהן בלתי מפסדת ולזה אמר שבזבחנו זבח תודה ביום ההוא יאכל רוצה לומר שנחשוב עליו בזאת הזביחה שיאכל ביום ההוא ולא נחשוב לאכלו חוץ לזמנו כי בזה יהיה פגול כמו שהתבאר במה שקדם והנה נשלמו בזה מיני תנאי הדברים הקרבים ולפי שהמכוון באלו המצות היא ההוראה על קדושת השם יתעלה כמו שיתבאר בזה הזהירה התורה אחר זה מלחלל השם יתעלה וצוה לקדשו עד שנראה לאנשים עוצם אהבתנו אותו והכנע לבבנו אל מצותיו באופן שיקל סבול המות כדי שלא נמרה את פיו ולא נחלל שמו וכבר התבאר מדברינו שהמכוון בבית המקדש ובעבודה הנעשית שם ובענין הטמאות והטהרות הוא ההישרה להשגת סודות המציאות אשר יעמידנו על מציאות הסבה הצוריית שנעמוד על מציאות השם יתעלה עם שבהם עוד תועלת בדברים המדיניים כמו שהבתאר מדברינו ולזה המשיכה התורה לזה זכרון המועדים כי הם לזה התכלית בעינו כמו שנבאר וזכרה תחלה עניין השבת לרוב התועלות המגיעות ממנו ובדברים המדיניים כמו שזכרנו בפרשת בראשית והוא מעיר על סודות מעשה בראשית ועל האופן אשר ישפיע השם יתעלה אחר חדוש העולם מה שישפיע תמיד על המציאות על מה שהוא עליו כמו שביארנו שם ואחר זה זכרה התורה שאר המועדים והתחילה מחג המצות כי הוא המועד הראשון אשר נצטוינו בו עד שכבר נצטוינו בו קודם מתן תורה כמו שהתבאר מדרכי התורה ועוד כי ראש השנה האמתי ראוי שיהיה בהכנס השמש בראש טלה כי אז יקרב השמש אל הישוב ואז יראה כח בצמחים ובשאר המורכבים והנה נמצא בדברים הטבעיים ההוים הנפסדים שהם חוקי הכח בהולדה בהתחלה ואחר זמן מוגבל יחלש בהם כחם מדרגה אחר מדרגה וכן ראוי שיהיה העניין בתקופת השנה השמשית רצוני שהוא ראוי שתהיה התחלה מהעת שהוא חזק הכח ולזה אין ראוי שתהיה התחלה בעת היותו בראש מאזנים ולפי שאין שם כי אם שני אלו הזמני להיות התחלת השנה הנה יתבאר כי התחלת השנה על דרך האמת הוא בהיות השמש בראש טלה ואמנם בחרה התורה ראש השנה באופן אחר בהיות השמש בראש מאזנים מצד הויית הצמחים כי הזריעה ראוי שתהיה בשנה שבה הקצירה ושתהיה קוד' הקצירה ומזה הצד הושם תשרי ראש השנה לענייני' הנתלים בזרעים ובעבודת הארץ כמו שיתבאר ועוד כי יראה באלו המועדים הערה על העניינים נפלאי' יתבאר ממה שיחוייב שיהיה הקודם בסדר חג המצות כמו שיתבאר מדברינו וקודם שנדבר בענין אלו המועדים נקדים הצעה אחת והוא שהתורה תכוין במצוה אחת לתועלות רבות כבר זכרה זה בביאור מצות שבת וזה כי במקום אחד אמרה שהוא להעיר על חדוש העולם ובמקום אחר שהיא זכר ליציאת מצרים ולזה לא תהיה טענה עלינו אם נמצא באלו המצות יותר מתועלת אחד ונאמר שהוא מבואר בחג המצות שהוא זכר ליציאת מצרים כי בזה תועלת נפלא בדעות כמו שהתבאר מדברינו בפרשת בא אל פרעה. והנה נתבאר שם התועלת שהיה באכילת מצה והוא להזכיר נפלאות השם יתע' שסבב כמו שהקשה לבו בזה האופן הנפלא ומאן לשלח את העם שגרש את העם במהירות עד שלא יוכלו להתמהמה לחמץ בצקם ואפו אותו מפני זה עוגות מצות ואחשוב שיהיו במצות תועלת שני העירנו להשיג זה התועלת מה שצותה התורה במנחת חג שבועות שתהיה חמץ והוא כי חג השבועות הוא כמו שאמרנו בפרשת יתרו זכר למתן תורה שהפליא בה השם יתע' חסדו עמנו לקרבנו לעבודתו יתעלה להנחילנו החיים הנצחיים ונמשך לה גם כן השפעת הטובות הגופיות כמו ירושת הארץ ומה שידמה להם מהטובות הגופיות שיבאו על צד ההשגחה האלהית ולפי שקודם שיתוקנו פעולות האדם ודעותיו בנימוס התוריי הנה פעולותי ודעותיו הם חסרות כמו לחם המצה שחסר תקון החמץ ואחר שיתוקנו פעולותיו ודעותיו הן שלמו' התקון כמו לחם המזון המתוקן בתכלית מה שאפש' הנה צוה השם יתע' באכילה מצה עם בשר הפסח ובחג המצות וצותה להביא מנחת חמץ ביום מתן תורה ולהעמידנו על זאת הכונה יחדה התורה מנחת חג השבועות להיות חמץ מבין שאר מנחות כדי שנפקח עינינו ונשיג אמתת הכונה בזה. ובזה גם כן תועלת לבאר מהות התורה ועניינה והוא כי היא אינה במדרגת הדברים הטבעיים אבל היא משלמת אותנו כמו העניינים בהרבה מהמלאכות שירשתוהו הטבע וישלימוהו כמו עבודת האדמה ומה שידמה לה מהמלאכות וכן תמצא התורה בעינה כי ההכנה אשר באדם בטבע לקניין השלמות ואנושיות תצא אל הפעל בנימוס התוריי למי שיבחר הנהגתו בו באופן שלם והוא כמו שהמלאכות המשרתות לטבע הם בחריות כן הענין בנימוס התוריי ולזה הקישה התורה בשלמו' המגיע באמצעו' התורה לשלמו' המגיע באמצעות המלאכה כמו שצותה התורה להיות המנחה הנעשית ביום מתן תורה לחם חמץ ומזה המקום יסור הספק למה יעניש השם יתעלה העוברים על מצות התורה וזה כי הן אינן מוכרחים לעבור על דבריה אבל להם התחלה בחירית לחלוק על התשוקה הדמיונית שתביאם לחטא כמו שיתבאר מדברנו בספר מלחמות שם ולזה לא יהיה עול אם יעניש אותן על עברם על דבר השם יתע' אבל הוא יושר והנה היו הקרבנות נוספים במועדים להעיר על שהכונה במועדים ובקרבנות היא אחת בעינה והיא לעבוד אותו יתע' ולהעמיד על אמתת מציאותו ולזה באה האזהרה מעשות בהם מלאכת עבודה כדי שיהיה לנו אז פנאי מטרדת אלו הפעלות הגופיות ויוכל לנו יותר התבודדות בענינים והעמידה על סודם מצד דרישתנו וחקירתנו בהם ולזאת הסבה בעינה חוייבנו כל זכרינו לעלות בבית המקדש בפסח ושבועות וסכות כי בו הערה על הכונה בעינה אשר יישירו אליה המועדי' כמו שהתבאר מדברינו בו. והנה היתה מתן תורה ביום חמשים אחר יום הפסח שאז תשלם ביום הקודם לו ספירת ז' שבועות לפי שכבר ביארנו בספר מלחמות השם כי מהככבים והגלגלים יסודרו לאדם תשוקו' ובחירות יקרה בקצם שתהיינה בלתי נאותות והנה היה האדם בעל שכל יעמוד בו כנגד אותם הבחירו' בלתי נאותות והנה התורה היא המישרת אל זה ולפי שהככבים אשר מהם יסודרו אלו העניינים לפי מקומם מגלגל המזלות הם ז' והיו לכל אחד מהם גלגלים רבים ישלמו בהם תנועותיהם אלו הז' שבועות להורות על רבוי הגלגלים אשר לככב ככב אשר מצדם יתחדשו ממנו עניינים מתחלפים רבים עד שכבר אפשר שיקרה מהן דברים בלתי נאותין מזה הצד וזהו אמנם הוא במקרה לא בעצם כמו שביאנו שם והיה ביום החמשי' מתן תורה להעיר על ההתחלה המושלת על אלו הגלגלים אשר מאתה השפיע התורה אשר ישלם בה לאדם מה שחסר לו מצד הרע שיגיע במקרה מגרמים השמימיים כמו שבארנו בספר מ"י ולהעיר על עצם זאת ההתחלה צונו השם יתע' לספור ממחרת הפסח מ"ט יום ולקדש את יום החמשים וזה כי מספר השכלים העלולים מהשם יתע' הם מ"ט כמו שביארנו בתשיעי מספר מ"י והנה השם יתע' הוא השכל התחלת החמשים אשר הוא התחלת שא הנמצאות כלם ומאתו שפעה זאת התורה האלהית כי היא משלמת מה שכיון השם יתעלה בבריאה האנושית במה שנתן לו מהכח וההכנה לקנין השלמות האנושי ולזאת הסבה שזכרנו היתה באה מנחת העומר ממחרת הפסח מהשעורים ומצה ומנחת יום מתן תורה היתה באה מן החטים. והיתה חמץ. להעיר על העדר השלמות אשר לאדם קודם התישרו בנימוס התוריי ועל שלמותו אשר יקנה מצד התורה והנה היה עוד תועלת בקרבן העומר להעיר שכל הטובות השופעות בזה העולם שופעות מאת השם יתע' ולזה לא יותר לאכול מן החדש קודם זה הקרבן והנה התועלת בעינו יהיה בשתי הלחם הבאים בעצרת עם שהם יישירונו שמה שנביא מן המנחות הבאים מהחטים להשם והם כל מנחות קרבנות לא יהיה אלא אחר התישרנו בנימוס התוריי כי הוא יישירנו אל המכוון בקרבנות וזה מבואר במה שקדם לנו בזה הספר ולזה היתה זאת המנחה חדשה ולהעיר שהמכוון בקרבן העמר ושתי הלחם הוא עם שאר התועלות אשר יגיעו מהם להעיר על שפל הטובות הם שופעות מהשם יתע' סמך לזה עניין מתנות עניים אשר בקציר כמו הפאה והלקט ומה שידמה להם כי הם לזאת הכוונה בעינה כמו שביארנו במה שקדם אצל המאמר באלו המתנות והנה בחדש השביעית יחל להחלש כח השמש בישוב מהפאה המיושבת והוא דומה מתקופות שנות האדם לתקופה אשר היא בסוף חייו והוא מבואר שהאדם שיתיישר בנימוס התוריי והגיע לה הזמן שיכנעו בו הכחות ויתחלשו הנה אז יחזק שכלו ויזך אורו כמו שביארנו בביאורנו לספר הנפש בספר מלחמות השם ולזה כאלו הישירה התורה במה שסדרה בו מאלו המועדים ששם השכלים הנפרדים מספרן עשרה והעשירי הוא הש"י כמו שביארנו בספר מלחמות השם ולזה נתקדש היום העשירי לחדש הזה ולהעיר אותנו על מה שהישירתנו התורה בזה צותה לתקוע בשופר באחד לחדש הזה כאלו תעיר הישני להתבונן על זה המכוון ולזאת הסבה צותה לתקוע ביום הכפורים של יובל כי בו יתקבצו שתי ההערות כי הוא שנת החמשי' שנת המורה על השם יתע' והוא היום העשירי המורה עליו גם כן מזה הצד השני שזכרנו בזה המקום וכבר התבאר בספר מ"י שמניעי הגלגלים אשר בהם הככבים יותר נכבדים מאד ממניעי הגלגלים שאין בהם כוכב המשרתים אותם באופן שישלם בהם רבוי התנועות לככב ככב. ולזה היה המספר כשנמנו אלו הראשונים לככב ככב שבעה לככבים הרצי' ואחד לגלגל הככבי' הקיימים והשכל הפועל אשר השפיעו הש"י באמצעותם והעשירי הוא הש"י ולהורות על נקייות הש"י מחמר בכל הפנים היה היום העשירי אסור באכילה ובשתיה להרחיק ביו' הזה הפעולות החמריו' לפי מה שאפשר ולהיות זה הענוי מעיר על זאת ההערה הנפלאה היה העונש עליו עצום ראוי שתדע כי זאת ההערה היא נפלאה מאד לפי התורה והעיון וזה שאם הונח השם יתע' ממניעי הגרמים השמימיים הנה יהיה מציאותו חסר כי לא תהיה השגתו מקפת בכללו' בכל הנמצאת כמו שיתבא' מדברנו במ"י ויתחייב גם כן מזה שיהיה העולם קדום ויתחייב ג"כ מזה רבוי ההתחלות ושיגיע מהם במקרה זה הנימוס והאחד השלם בתכלית השלמות הנמצא בנמצאות ולפי שזה העניין הוא כלו בתכלית מה שאפשר מהבטול והגנות הנה יחוייב שינח בכאן שכל אחד קדם להם הוא אשר המציאם והמציא להם אלו הכלים אשר בהם ישפע מה שישפע בנמצאות כי מהרבים לא יגיע פעל אחד כי אם בזה האופן רוצה לומ' שיהיה שם אחד קודם להם הוא המישיר אותם אל שיעשוהו כמו שתמצ' הענין במלאכה הראשיית עם המלאכות המשרתת והנה זה האחד הראשון לא יוחס אל חלק אחד מהעולם כמו שיוחסו מניעי הגרמים השמימיים אבל הגרמים להם אשר הם להם במדרגת הצורה וכבר ביארנו זה הענין כלו במה שאין ספק בחמישי מספר מ"י ומזה המקום יתעו המתענין באלו העשרה ימים כי התורה כונה בענוי לעשור ליחד זה היום מבין שאר הימי' האלו להעיר על עצם מדרגת השם יתע' על מדרגת שאר השכלים האלו ולזה שבחו רז"ל האוכל ושותה בט' בו להורות כי גם התשיעי והוא מניע גלגל הככבים הקיימים אשר הוא נכבד מאד מן השכלים האחרים העלולוים מהשם יתע' כמו שבארנו בספר מ"י תרחק מדרגתו מאד ממדרגת השם יתעלה עד שאין יחס ביניהם כלל ולהיות הכונה באלו העשרה ימים להעיר על זה הענין הנפלא אשר הוא פרי החכמה האלהית ותכליתה כמו שביארנו בחמישי ממ"י אמרו ז"ל במדרש תלים תודיעני ארח חיים אלו עשרה ימים שבין ר"ה ליום הכפורים כי ידיעת זה העני הרוחני אשר יעידו עליו הוא קנין החיים הנצחיים וזה מבואר מאד למעיין בזה הספר ואחר כך צוה בחג הסכות שהוא הנמשך לאלו המועדים בסדר לפי זמנו אשר הוא בו ובו תועלות רבות האחד להזכיר הפלא העצום שעשה השם יתעלה לאבותינו אשר הנחה אותם בעמוד אשר וענן בהיותר במדבר כי בזה תועלת להאמין בשם יתע' ושהוא משגיח בדבקי' בו בזה האופן הנפלא ואלו הב' האמונו' הם מהגדולו' שבפנות התוריות והעיוניו' וזה מבואר מאד מדברינו בספר מלחמות השם. והתועלת השני הוא כי בזה העת נשלמה אסיפת תבואת הארץ כמו שאמ' באספכם את תבואת הארץ ואמר במקום אחר באספך מגרנך ומיקבך ואולם תהיה רבוי הטובה סבת הבעיטה בשם יתע' כמו שאמר וישמן ישורון ויבעט ולזה רצה השם יתע' שיניחו בתיהם וישבו בסכות להזכירם כי מתחלה לא היה להם לא בית ולא שדה אבל היו יושבים באהלים במדבר והיה ענן השם יתע' עומד עליהם והוא הנחילם אחר זה הארץ הטובה הזאת אשר ממנה יצאו אלו התבואות ולזה ראוי שיתנו תודה נפלאה לשם יעת' כעל כל אשר גמלם מהטובות לא שיבעטו בו ולזה ישמחו לפני השם ז' ימים עלם לקיחת פרי עץ הדר ומיני הענפים המתחלפים אשר יקחו עמו להראות מה שהשפיעם השם יתעלה מהטובה בתתו להם הארץ הזאת הנבחרת שימצאו בכל מיני הצמחים בשלם שבפנים אחר היותן במדבר שהיה ארץ ציה ולא היה שם בה צמח מהצמחים גם מים לא היו להם שם ולזה תמצא שצמא שם העם למים ולזה אחשוב שהיה בכלל אלו הצמחים ערבי נחל להיותו גדל על המים ושם ימצא רענן ודשן לזאת הסבה גם כן היה נסוך המים בכח והוא הנסוך הנוסף הנזכר ביום השני בפרש' פינחס כמו שנבאר שם בג"ה. והנה מזה המקום נלמד שהנסוך הנוסף הוא מים והנה היה זה החג בז הזמן לסבה שזכרנו ונבחר האתרוג ליפיו וערבותו ולהיותו נמצא באילן בזה העת עם שהוא מורכב משלש עצמים מתחלפים ונכר מאד חלופם בחוש והם הקלפה והכשר והבוסר אשר באמצעותו כי אלו החלופים יעידו על מציאות הצורה כי הצורה היא סבת יחוד הדברים קצתם מקצת ולזאת הסבה ג"כ קבצה התורה בזה מהעלים מה שיתחלפו תכלית החלוף וזה כי עלי הלולב הם מתחלפים מאד משאר עלי הצמחים ועלי הדס וערבה מתחלפים קצתם מקצת כי עלי ההדס הם בעלי ריח טוב ועלי הערבה אין להם ריח ולולי היתה בכאן הצורה כמו שהיו החושבים קודמים היה מחוייב בכל המרכבות שיהיו מתדמים החלקים ומסכימים קצתם לקצת ולא היה נמצא חלוף בין חלקי הפרי ולא בין חלקי הצמח לצמח בין עלי זה הצמח לעלי זה הצמח וכבר הודענוך כי התורה תכוון בהרבה מהמצות להעמידנו על אמתת זה העניין ולרוב התועלת המגיע ממנו כי אם לא נאמין במציאות הצורה תפול התורה ולא תהיה בכאן חכמה כלל כמו שביארנו במה שקדם. והתועלת השלישי הוא לפי מה שאחשוב כי בזאת התקופ' אשר היא מתיחסת לתקופת סוף חיי האדם הוסר הרבה מהמהסך אשר היה לשכל מפאת החמר והוא אז חלוש כמו סכוך הסכה שהוא חלוש מאד מסכוך הבית וקירויו עד שכבר יעבור בו ניצוץ השמש ולזה ראוי שיכנס אז הדם בכמו אלו ההשגות האלהיות עם מה שהגיע לידו מההשגה בסודות הדברים הטבעיים אשר תשלם לו בחקירה בעניני מציאות אלו הצורות הנמצאות ולא יקצר בזה ויחשוב שאין ראוי לאדם שיחקור כי אם במציאות הדברים הנכבדי' כמו הב"ח ומה שלמעלה מהם להיות הצעה ומבוא להשגת השם יתע' אבל ראוי שישים חקירתו גם כן בצמחים מהצמח היותר שלם והוא היותר גבוה ועושה פרי כמו התמר עם היותר שפל ופריו פחות כמו ההדס ולא יקצר מלעיין גם בשאר הצמחים שאינם עושים פרי כערבי נחל וישתדל בחקירתו שיוציא פרי ר"ל שישיג הסבות אשר בעבורם נמצאו וזה ביותר שלם שאפשר כי זה יביאהו אל ההשגה בסבה הראשונה וזה כי מה שנדע יותר מנימוס הנמצאות וסדרם וישרם תהיה השגתו בשם יתע' יותר חזקה כמו שביארנו בספר מלחמות השם ולזה יקח אלו המינים מהצמחים לבד והפרי לבד להורות שיוציא מהם פרים ביותר שלם שאפשר ולזה היה זה הפרי היותר הדר והיה גם כן בעל עצמין מתחלפים להורות שיוציא מהם זה הפרי בכל הצדדי' שאפשר לו זה ולפי שאלו המועדים היה המכוון מהם ההישרה להשלמת השכל זכר אחר זה המנורה שהוא מעיר על האופן שיצא בו הכל מהכח אל הפעל מצד השגות החוש וכאלו העיר זה על זה האופן שבו ישלם השכל בהשגתו אלו הצמחי' שצוה לקחת בחג הסכות ומה שידמה להם ואחר זה זכר ענין לחם הפנים המורה על נפש הזנה הושמה שם לבונה אצל המערכת להעיר על זאת הצורה מצד האופן היותר נכבד בה והוא הצד שתהיה בה במדרגת ההיולי לנפש המדברת ר"ל מצד מה שהיא נפש זנה לאדם כי מזה הצד תשרת הנפש המרגשת ותשרת הנפש המדברת באופן אשר תעיר עליו המנורה כמו שביארו אצל המאמ' בה והנה סמך לזה ענין המקלל להעיר שאלו המצות אשר נזכרו בזה המקום על ההמשך מישירות האדם להשגת השם יתע' אשר הוא סבה שיירא ממנו ויכבדהו בתכלית מה שאפשר ולזה ראוי שיענה מי שיעשה הפך זה הענש היותר נפלא והוא סקילה ולפי שזה הענש יהיה ע"י העדים להמיתו הזכירה התורה אחר זה ענש מכה אדם כדי שישמרו העדים מהעיד שקר בזה כמו שנתפרסם מעניין נבות שהעידו עליו שברך אלהים ומלך והמיתוהו בעול וחמס ולזה זכר אחר זה עניין מכה בהמה להעיד על ההבדל שיש בין הריגת אדם להריגת הבהמה כי בהריגת הבהמה לא יתחייב כ"א ממון ובהריגת האדם יתחייב מית' והיה זה כן מצד עצם מעלת האדם והנה המשיך אחר זה דין ההבלות שיגיע לאדם להשלמת הביאור בזה הענין וגם כן הנה מפני שהכעס יביא האדם לפעמים לברך השם יתברך ואף על פי שהוא משיג עצם מדרגתו המשיך לזה מה שימשך מהכעס מהפעולות המגונות בעניניהם המדינים והתחיל ביותר קשה והוא הריגת האנשים וזכר אחריו דין הריגת הבהמה להעיר על ההבדל שיש בין האדם והבהמה ואחר כך זכר דין החבלות ואולם התועלות המגיעות מזאת הפרשה הם י"ח:
@919 והנה צותה התורה למנות שמטה לכונה בעצמה שנצטוינו לשבות ביום השביעי אלא שלא נאסרה השמטה בעשיית כל מלאכה כמו העניין ביום השבת לפי שלא יתכן שישבות האדם מכל מלאכה שנה אחת וכבר היה זה כן לפי שאין השמטה מורה על השם יתעלה כמו שיורה עליו יום השבת לפי מה שבארנו בפרשת בראשית. ואמנם הוראת השמטה על מציאות שכל נבדל עלול מהשם יתעלה ובכלל הנה העניין בשמטות וביובל כמו העניין בספירת שבעת שבועות ממחרת הפסח לקדש החמשים לפי מה שבארנו במה שקדם והנה נתקדשה השנה השביעית להעיר על מניעת הגלגל שבו כוכב מהכוכבים הרצים שהוא נכבד מאד ממניעי שאר גלגליו שירתוהו ברבוי התנועות לכוכב ההוא כמו שבארנו בספר מ"י. ולזה נתקדשו שבעה שמטות להעיר על עלוי אלו המניעים על מניעי שאר הגלגלים אשר יעבדום ולהעיר על היותם בני חורין באופן מה ביחס על אותם אשר ישרתום היה חירות מה לארץ בשנת השמטה בעניין התבואה והמלוה ונתקדשה שנת החמשים להעיר על שבכאן עלה עליונה על כל אלו המניעים הנבדלים שהם מ"ט כמו שבארנו בספר מ"י והוא השם יתעלה ולפי שהוא העשירי כשנמנה אלו הנבדלים באופן אחר כמו שזכרנו במה שקדם נתקדש יום העשירי משנת היובל והיו תוקעים בו בשופר להעיר קצת נרדמים שיתכונו במה שהעירה התורה בזה ולהורות על שררת אלו המניעים על השאר ושהן מושגחים בעניין מה שיושפע מכללות התנועות על שאר הגלגלים והמניעים כלים להם צותה התורה שתהיה השררה אשר בקרקעות כוללת ומשותפת לכל האנשים בזאת השנה כמו שזכרנו עם שבזה תועלת להטיב הדלים האמללים מתבואות השנה הזאת ולזאת הסבה בעינה צוה להשמיט המלוה בשנת השמטה כדי שתסור השררה המיוחדת על איש בזאת השנה להורות על טובות אלו המגיעים במה שישפיעו שהיא כוללת ומשותפת ואולם בשנת החמשים היה זה העניין באופן יותר שלם לפי ששררת זאת העלה היא הכוללת באמת ומאתה יושפעו השאר כמו שבארנו בשני ובחמישי מספר מלחמות השם ולזה תסר בזאת השנה כל שררה מחודשת וישוב איש לאחוזתו למשפחתו להעיר שאי לזולתו שררה על דרך האמת ומפני זה בארה התורה איך יהיה הדין בקניין הקרקעות עם שמירת זה השרש ר"ל שתשוב האחוזה לבעליה ביובל ונתן חירות עוד לבעל הקרקע לגאל הקרקע קודם בא היובל והקדים לזכור דין מכירת קרקעות קודם זכרו דין מכירתו עצמו לפי שראוי לאדם כשיצר לו שימכור קרקעותיו קודם שימכור עצמו ולזאת הסבה גם כן הקדים המכרו לישראל לדין המכרו לגר צדק או לגר תושב או לגוי עובד ע"ז כי כשיבואהו ההכרח שימכור עצמו ראוי שיבחר שימכר לישראל ולא לגר צדק כי מפני שבע מבעלי הדעות הפחותות והמדות המגונות אולי הוא נשקע בהם ויצא לתרבות רעה זה האיש בהמכרו לו כי ילמד ממעשיו וכ"ש שראוי שירחיק יותר המכר לגר תושב שאין מאמין בתורת משה וכ"ש שראוי שירחיק יותר ההמכר לגוי עובד ע"ז והנה מה שהחמירה התורה בעניין מכירת בית מושב עיר חומה שלא תהיה לו גאולה כי אם עד שנה אחד ולא יצא ביובל הוא מבואר התועלת והוא לפי מה שאחשוב כדי להעמיד ישוב זה המקום הנכבד המוקף וזה שאם היה יוצא ביובל לא יהיה הקונה משגיח בעניין תקון הבית ההוא ויתקלקל ויפול ויהיה זה סבה אל חורבן המקום ההו' והנה בעניין שוב האחוזה לבעליה ביובל ושוב האדם למשפחתו תועלת אחר וזה כי יהיה סבה שלא יהיו נואשים מטוב האנשים הקשי יום דעתם כי בבא היובל ישובו אל קנייניהם ולזה יהיה בהם חריצות להשתדל לאסוף ולכנוס מה שייצטרך למחיתם ולא יתרשלו ותרפינה ידיהם לחשבם שאין להם תקומה עוד כמו שתראה בקצת האנשים שהם נואשים מטוב לזאת הסבה והיה זה הסבה אל התמדת חסרונם ולפי שזה העניין היה להשגחה על הדלים סמך לזה האזהרה מליקח מאתם נשך ותרבית עם שכבר זכר זה גם כן לפי שכבר יזכור במה שיבא שבשנ' השמטה תשמט המלוה והנה זכר דין עבד כנעני שאינו יוצא ביובל עם זכירתו יציאת עבד עברי ביובל להשלמת הביאור בזה הענין. עם שבזה למדתנו התורה כי זה החירות נתן לישראל מפני היותם נמשכים לעבודתו ית' כי זה ממה שיישירם לעבודתו כמו שהתבאר מדברינו ולזה לא נתן זה החירות לזולתם מן האומות בהמכרם והמשיך לזה האזהרה מעבוד ע"ז להעיר שזאת המצוה היא מישירה אל ההרחקה מתת האלהות לזולת השם יתעלה והמשל כי מי שיחשוב שהשם יתעלה שהוא המניע אשר לגלגל הכוכבים הקיימים כמו שחשבו הרבה מהפילוסופים כבר נתן האלהו' למי שאינו אלוה ולזה הישירתנו התורה בזה הדעת האמתי משני פנים האלה ר"ל בקדוש החמשים ובקדוש העשירי וזה כי כשנמנו כל השכלים הנפרדים בכללם היו חמשים עם השם יתעלה שהוא התחלתם וכאשר לא נמנו המשרתים למניעי גלגל הכוכבים היו עשרה עם השם יתעלה שהוא העשירי שיושפעו ממנו השאר כמו שביארנו בספר מלחמות הש' והמשיך לזה ג"כ הצואה בשמירת השבתו' ובשמירת המקדש כי הם גם כן מישירי' על זה העניין בעינו כמו שתתבאר מדברינו במה שקדם ואמנם התועלות המגיעות מזאת הפרשה הם שמנה:
@998 והנה הקדימה התורה לזכור בזה המקום קצת הטובות שיביא השם יתעלה להולכים בחקותיו וקצת הרעות שימשכו לאשר עזבום להעמידנו על כונת הש' יתע' באלו המצות והחקים כי לא דבר רק הוא והנה המשיך לזה דיני הנדרים וההקדשות שהם למזבח או לבדק הבית כדי להשלים המאמר בעניין הקדשים והקרבנות עם שבזה גם כן מה שישלם בו המאמר בעניין היובל אשר היו בו הדברים כמו העניין בשדה אחוזה ובשדה מקנה והנה היה זה המאמ' בהדרגה בנכבד החל והם ערכי אדם ואחר כך זכר בבהמה ודבר תחלה ביותר שלמ' מנה והיא הבהמה התמימה שהקדישה למזבח ואחר כך דבר בבעלת מום ואחר כך בקרקעות והתחיל ביותר נכבד והוא הבית ואחריו דבר בשדה אחוזה שהוא למטה ממנו ואח' כך דבר בשדה מקנה שהוא למטה משדה אחוזה בעניין ההתקיים לבעליו ואח' כך זכר מה שאין ראוי להקדיש כמו קדשי מזבח שאין ראוי לשנות קדושתם וזכר זה ביותר קל מהם ואחר כך זכר דין מה שיחשב שאין ראוי להקדישו למזבח או לבדק הבית והוא הבהמה הטמאה ואחר שהשלים המאמר בקדשי השם יתעלה ביאר עניין קדשי הכהנים ואח' כך ביאר דין קדשי ישראל כמו מעשר שני ומעשר בהמה ובזה נשלם המאמר בזה הספר ואולם התועלות המגיעות מזאת הפרשה:

@1 **התועלת** הראשון הוא להישיר האנשים כאשר חטאו שישובו אל השם יתעלה והוא יכפר להם עונותיהם ובזה תועלת נפלא להגיע האנשים אל השלמות האנושי וזה כי אין צדיק בארץ אשר לא יחטא ואם יאמינו האנשים שחטאו חטא מה שיהיה נכתם עונם תמיד לפני השם יתעלה יוסיפו לחטא לחשבם שכבר אבדו בסבת מה שחטאו ולא יועלם השמרם מחטא במה שעתיד ואמנם כאשר ידעו שבשובם מדרכם הרעה וישובו לדרכי השם יתעלה יכופרו להם עונותם אז יהיו נזהרים מחטא עוד וישובו אל השם יתעלה כדי שירחמם ויכפר עליהם מה שחטאו בו והנה רצה השם ית' שיהיה עם התשובה הקרבת הקרבן כדי שיתישב יותר בלב החוטא שכבר נתכפר לו אותו החטא כי לא יצוייר אצל המון האנשים שיהיה האדם רשע ואחר כך יתנקה מרשעו בתשובתו בלבבו בזולת מעשה כלל ולזה צוה השם יתע' שיעשו אלו הקרבנות בבית הנכבד אשר בו שכינתו וע"י הנכבד הנבדל לעבודת השם יתעלה להשלים הכפרה לחוטא עם התשובה וציוה מפני זה שיסמך שתי ידיו על ראש קרבנו ויתודה עליו עונותיו לישב בלבבו שאותם החטאים כלל לאו נעתקו ממנו ובאו על ראש הבעל חי ההוא עם שבאופן עשית הקרבנות הערה להיישיר האדם לעבודת השם יתעלה ולהרחיקו מההליכה אחר יצרו הרע כמו כשנתבאר הסבה למה היו מעשה הקרנות הנזכרים בזאת הפרשה בזה האופן אשר יצוה השם יתעלה:
@1 **התועלת** השני הוא בדעות. והוא להיישיר האנשים שאין השמש האלוה כמו שחשבו רבים מהקודמי' ולזה היו כל הפעולות הנכבדות במקדש לפאת מערב שהוא להפך מקום זריחת השמש והדברים הפחותים היו לפאת מזרח ולזה צוה להשליך מראת העוף ונוצתה לפאת מזרח מהמזבח ושם היה מקום חדשן לזאת הסבה בעינה:
@1 **התועלת** השלישי הוא במצות. והוא לבאר קצת דיני קרבן העולה והיא מצות עשה ר"ל שתעשה העולה באופן הנזכר בתורה והנה התועלת לזאת המצוה היא בעצמות להכין הראוי לנבואה מהכהנים העובדי' לקבול השפע האלהי כמו שביארנו במה שקדם עם שימשך מעניין הקרבן העולה התועלת שימשך ממזבח הקטורת והמנורה והשלחן בנתינת הדעות האמתיות כמו שביארנו במה שקדם ובקרבן העולה עוד תועלת שלישי והוא שהוא מכפר על קצת החטאים וכבר זכרנו התועלת המגיע ממנו אצל זכירתנו התועל' הראשון מאלו התועלות ובזה עוד תועלת רביעי וזה כי בעולת הנדבה ירגיל האדם נפשו לתת כבוד לה' מהונו ובזה תועלת לשוב בלבו כי כל הטובות הם באות מאתו עם שבזה ירגיל עצמו למדת הנדיבות ויסיר מתכונת הכילות וזה התועלת כולל כל הקרבנות האלו וזה יהיה בפרשת צו בגזרת הצור:
@1 **התועלת** הרביעי הוא במצו' והוא לזכור אופני עשיית המנחה הבאה בנדר ונדבה וכבר קדם התועלת המגיע מזה:
@1 **התועלת** החמישי הוא במצות. והוא האזהרה שלא נקטיר משאור ושלא נקטיר מדבש אשה ליי'. והנה התועלת המגיע מאלו האזהרות הוא לפי מה שזכר ממנו הרב המורה כי עובדי ע"ז היו עושים זה ורצה השם יתע' שלא נעבדהו באופן שהיו עובדי' אלהיהם ולזאת הסבה בעינ' רצה שנקריב מלח על כל קרבן כי עובדי ע"ז לא היו מקריבים מלח כלל כמו שזכר הרב המורה וזה הטעם הוא כולל רוב מה שבא בעניין הקרבנות ובהרבה מקומות המצות זולתם כמו שזכר הרב המורה. וכבר אפשר שנתן אנחנו עוד בזה סבה מיוחדת והוא כי הקודמים חשבו שיהיה מציאו' כל הדברי' הטבעיים בקרי ולא השיגו שיהיה שם סבה פועלת לא צוריית ולא תכליתיית ומהדעות ההוא היה מתחייב שתהיה המלאכה יותר נכבדת מהטבע כי היא תעשה מה שתעשה לתכלית מוגבל ולפי שזה הדעת נפסד הוא הורס הפנות התוריו' ומרחיק האדם מכל שלמות הנה יסדה לנו התורה שהענין בזה נהפך רוצה לומר שהטבע יותר נכבד מהמלאכה לפי שהוא עשה מה שיעש' בתכלית מוגבל וכבר נעירתנו תורה בזה לפי שאנחנו נמצא שהיא תדקדק שיהיו מיני הקרבנו' מהדברי' היותר נכבדים והרחיקה עם זה הקטרת אשר להשם מהשאור שחדושו מן המלאכה וכן מהדבש שתחדשהו הדבורה במלאכה להורו' שאלו הדברים המתחדשים במלאכה הם מאוחרים מהדברים הטבעיים ואחשוב עוד שיהיה תעולת מיוחד בהקרבת המלה עם כל הקרבנות לפי שהמלה דוחה העפושים אשר היה ראוי שיחדשהו שם בסבת הקטרת הבשר והחלבים ושאר הדברים הנקטרי' שם ואפשר שיהיה בזה תועלת אחר אך לא ידעתיו עד היום:
@1 **התועלת** הששי הוא במצות. והוא להודיע מעשה קרבן השלמי' וכבר קדם לנו זכרון התועלת המגיע מזאת המצוה במה שקדם:
@1 **התועלת** השביעי הוא במצו' והיא האזהרה שהזהירנו מאכילת חלב ודם והנה נתבאר בפרשת צו שכבר יתחייבו על זדון אלו העברו' כרת ואולם התועלת המגיע באלו האזהרות אמנם באכילת הדם הוא התרחק מהתנהג בנימוסי עובדי ע"ז שהיו אוכלים הדם והיו חושבים שהוא מזון השדים ושכבר השתתפו עמהם כאשר אכלו הדם ויבאו להם ויודיעום העתידות וקצתם לא היו אוכלים הדם אבל עושים חפירה ומקבלים שם הדם או בכלי וסביב הדם ההוא יאכלו הבשר ויחשבו שישתתפו בהם עם השדים כי הם אוכלים הבשר והשדים אוכלים הדם ואוכלים יחד על שלחן אחד ולזה צותה התורה שלא נאכל כל דם ושלא נאכל כל דם ושלא נאכל על הדם שנ' לא תאכלו על הדם זה הוא הטעם אשר זכר בזה הרב המורה. ואולם בחלה נתן הסבה להגדלת הקרבן ולולא יראת העונש הגדול לא יפרדו ממנו לרוב ההנאה המגעת באכילתו והנה זאת הסבה בעינה אפשר שתנתן בדם כי מפני שנת' הדם על המזבח לכפר בזה האופן הנפלא שיראה בעניין הקרבנות מנע מלאכלו להגדיל עניינו שתשלם להם האמונה כשהכפרה תשלם על ידי זריקת הדם ולרוב ההנאה המגעת על אכילתו שם העונש על אכילתם חמור מאד כדי שיתרחקו ממנו האנשים ולפי שכבר גדלו יוצא מצרי' באכילתם חייב השם יתע' שלא יאכלו במדבר בשר אם לא יהיה שלמי' כדי שיקריבו החלב והדם לא יאכלום והנה במניעת החלב והדם אצלי תועלת אחר והוא שכבר התבאר בטבעיו' שהדם יפרד ממנו החלק האוירי והאשי בקלות כשנפרד מהבעל חי וישוב ארציי ולזה ימצא בו הקדוש וכן העניין בחלב ומה שזה דרכו בלתי נאות להיות מזון וכ"ש למין האנושי והנה הפליגה התורה לענוש באלו העברות כי לרוב התאוה על אכילתם לא ימנעו מאכילתם אם לא ליראת עונש הגדול והנה זכר אסור החלב והדם אחר זכרון קרבן השלמים בזאת הפרשה ובפרשת צו כאלו העירתנו התורה שאחת מן הכונות בקרבן השלמים היתה להרחיקנו מאכילת החלב והדם ולזה לא הותר לדור המדבר בשר אם לא יהיה שלמי' זולתי בשר חיה ועוף שאין לה חלב ובדמם צותה התורה שנכסהו בעפר:
@1 **התועלת** השמיני הוא במצות. והוא המצוה שצונו להקריב קרבן על השגגה שתפול בהרבה מהעבירות שחייבים על זדונן כרת. והתועלת המגיע מזאת המצוה להודיע שאדם הוא אשם על שגגתו בדברים שאפשר שיהיה בעניינם חטא כי מי שהוא ירא ה' כראוי יזהר בענייניו עד שלא יקרהו עון בהם ובה התועלת מבואר להביא האנשים אל שיפליגו לחקור בעניניהם באופן שלא יצאו מדרכי התורה והמשל כי מי שתהיה אשו ואחותו עמו בבית אם לא יפליג לחקור על מי יבא מהם אולי יבא על אחותו ואולם כשיפליג להזהר בזה ויזכור שאחותו שם או לא יתיר עצמו לבא על אחת מהם אם לא יתבאר לו שאשר יבא עליה היא אשו והודיעתנו התורה בזה שני מינים מהשגגו' שגגת ההוראה ושגגת המעשה והנה לא נכון בשגגת ההורא' רק ליותר עליוני' באופן ההוראה כמו כהן משיח או ב"ד הגדול אך לזולתם יהיה הטעות ההוראת זדון לא שגגה כי אין להם לסמוך על הוראתם כמו הענין באלו והיה ראוי שישאלו זה לגבוהים בהם ולא יהרג זקן ממרא ע"פ ב"ד כשטעו בהוראה כמו שיתבאר במשנה תורה ולא נדונהו בדין שגגת ההוראה ולזה לא יתחייבו קרבן על שגגת ההוראה עם זדון המעשה זולתי הכהן המשיח וב"ד הגדול והנה הקדים בזכרון קרבן יחיד הדיוט זכרון השעירה קודם זכרו הנשבה לפי שהכונה היא באלו החטאים העצומים שיהי ההקרבן פחות ולזה הקדים הפחות לנכבד בזה המקום והנה בזאת המצוה תועלת עוד לישב בלב החוטא שכבר נתכפר לו חטאו כי בזה תועלת מבואר כמו שזכרנו בתועלת הראשון שמנינו בזה:
@1 **התועלת** התשיעי הוא במצות והוא המצוה שצונו להקריב קרבן עולה ויורד על שבוע' העדות וטומאת מקדש וקדשיו ושבועת הבטוי. והנה התועלת המגיע מזאת המצוה זכרנוהו בתועלת הראשון שמנינו והנה בזה התועלת עוד במה שאמר בענין שבועות העדות אם לא יגיד ונשא עונו וזה שכבר יתבאר מזה שמצוה להגיד ולולי זה לא יהיה לו עון כשלא יגיד ואולי יאמר אומר כי אין המצוה הזאת אלא אחר שמיעת קול האלה. אלא שכבר יתבאר שהתור לא הקפידה מזה מפני השבועה לבד שאם היה הדבר כן לא יהיה זה נוהג בעדות בלבד אבל בכל דבר שישביעוהו עליו. ולפי שהקפידה בזה מפני העדות למדנו שרצון התורה הוא שיגיד גם אם לא ישביעוהו אלא שלא יתחייב קרבן כשלא יגיד אם לא אחר שמיעת קול האלה:
@1 **התועלת** העשירי הוא במצו' והוא מה שהזהירנו מהשים על מנחת החוטא שמן או לבונה וכבר זכרנו סבת זה אצל ביאורנו זאת האזהרה:
@1 **התועלת** האחת עשרה הוא במצו' והוא מה שצוה שיקריב קרבן מעילה מי שנהנה מקדשי השם בשגגה כמשלם קרן וחמש והנה התועלת המגיע מזה הקרבן כבר זכרנוהו בתועלת הראשון. ואולם הסבה בתוספת החמש הוא לפי דעתי שמי שיחשוק קניין דבר מה יתכן שיתן יותר מדמיו כמו חמישיתו וכדי שלא יהנה בסבת חטאו צור להוסיף חמה ולזאת הסבה היה שיעור האונאה במקח וממכר עד שתות כי יאמרו החכמי' בין מוכר וקונה הם שליש וחמש ושתות הם בזה האופן שליש:
@1 **התועלת** השתים עשרה הוא במצות והוא שיביא החוטא בספק שגגת הרבה מהעבירו' שחייבין על זדונן כרת אשם וכבר נזכר התועלת בזה במה שקדם:
@1 **התועלת** השלש עשרה הוא במצו' והוא שיביא הנשבע על שקר על כפירת ממון אשם וכבר נזכר תועלת זאת המצוה במה שקדם ומוסיף חמש לסבה שזכרנו באשם מעילה או יהיה החמש בזה המקום קנס והוא היותר נכון הנה כמו שהגנב יעש בשישלם כפל או ארבעה וחמשה אם טבח או מכר כן יענש הכופר ממון להוסיף חמש ואולם שרשי המצות הנזכרות בזאת הפרשה הנה ראוי שנזכירם לפי מנהגנו והנה המצוה הראשונה שבאת בזאת הפרשה הוא להקריב העולה באופן הנזכר בזאת הפרשה:
@1 **והנה השרש** הראשון בה הוא שאין מקבלי' קרבן עולה מישראל משומד לעבודה זרה או מחלל שבתות בפרהסיא כי התורה אמרה אדם כי יקריב מכם ולא בא הכתוב להתנות שלא יקובל קרבן עולה מן הגוי שכבר מנע בפרשת אמור שלא יקובל מן הגוי בעל מום שנאמר ומיד בן נכר לא תקריבו את לחם אלהיכם מכל אלה וזכר שכבר יקובל מהם בנדר ונדבה קרבן עולה אם היה תמים ולזה הוא מבואר ממה שאמר מכם להוציא ישראל שאינו מכם ומודה בעבודה זרה או הכופר במצות שבת כי אינו מכלל ישראל וזה מבואר במי שהוא מודה בעבודה זרה. ואולם מי שהוא כופר במצות רבות או אם כופר במציאות האלוה או אם כפר בחדוש העולם אשר כל אחד מאלו יביא לכפור בכלל התורה כבר נזכר זה השרש בכ"א מחולין ומזה השרש יתבאר כי אין מקבלים קרבן על שגגת חטא ממי שהוא משומד לאותו החטא כי גודל עונו מנשא בקרבן אחר שהוא משומד לעברה ההיא במזיד כבר נתבאר זה השרש בכ"א מחולין:
@143 ואולם התועלות המגיעות מזה הספור הם י"ג
@143 **התועלת** הראשון הוא במצות והוא להודיע קצת דיני העולה ומה שהיה מהם לכהנים וכבר התבאר התועלת המגיע מזאת המצוה ממה שקדם:
@143 **התועלת** השני הוא במצות והוא להודיע דיני הבערת האש במזבח העולה והאזהרה שלא תכבהו וכבר נתבאר התועלת המגיע מזה במה שקדם:
@143 **התועלת** השלישי הוא במצות והוא להודיע הנשאר מדיני המנחה והנאכל ממנה לכהנים וכבר יתבאר מה שיגיע מתועלת זאת המצוה במה שקדם:
@143 **התועלת** הרביעי הוא במצות והוא להודיע דיני המנחה התמידית שיקריב כהן גדול בכל יום בקר וערב וכבר נתבאר התועלת המגיע מזאת המצוה ממה שקדם:
@143 **התועלת** החמישי הוא במצות והוא להודיע הנשאר מדיני החטאות והנאכל ממנו לכהנים וכבר התבאר התועלת המגיע מזאת המצוה ממה שקדם:
@143 **התועלת** השישי הוא במצות והוא להודיע הנשאר מדיני האשם והנאכל ממנו לכהנים וכבר נתבאר התועלת המגיע מזאת המצוה ממה שקדם:
@143 **התועלת** השביעי הוא במצות והוא להודיע הנשאר מדיני השלמים והנאכל ממנו לכהנים וכבר התבאר התועלת המגיע מזאת המצוה במה שקדם:
@143 **התועלת** השמיני הוא במצות והוא האזהרה מלהותיר הקדשים אחר זמן אכילתם ולשרפם אם נתרו וכבר התבאר התועלת מזאת האזהרה במה שקדם:
@143 **התועלת** התשיעי הוא במצות והוא שלא יחשוב הכהן מחשבות בעשיית הקרבן שיפסל הקרבן בעבורם ותועלת זאת המצות מבואר והתבאר עם זה במה שקדם:
@143 **התועלת** העשירי הוא במצות והוא האזהרה שלא לאכול פגול וכבר נתבאר התועלת המגיע מזאת האזהרה במה שקדם:
@143 **התועלת** האחת עשרה הוא במצות האזהרה שלא לאכול קדשים שנטמאו והצואה לשרפם באש וכבר יתבאר התועלת המגיע מזאת האזהרה במה שקדם:
@143 **התועלת** השתים עשרה הוא במצות האזהרה שלא יאכל הטמא קדשים וכבר התבאר התועלת המגיע מזאת האזהרה ממה שקדם:
@143 **התועלת** השלש עשרה הוא במצות והוא להשלים דיני איסור החלב והדם וכבר בארנו התועלת המגיע מאלו האזהרות במה שקדם:
@259 **התועלת** הראשון הוא בדעות והוא שהשם יתע' יעשה המופתים על צד ההשגחה כשהיה המקבל ראוי לזה ולזה תמצא שכאשר רצה השם יתעלה להראות כבודו לבני ישראל על צד המופת למשכן לעבודתו ולהרחיק אותם ממה שטעו בו קצתם בעניין העגל צוה שיקריבו תחלה קרבנות לכפר עליה' ובזה האופן יתכן להם בהתקרבם לעבודת השם יתע' שישגיח השם יתע' בהם בזה האופן הנפלא לישב בלבם האמונה האמתית ולזה אמר זה הדבר אשר צוה יי' תעשו וירא אליכם כבוד יי':
@259 **התועלת** השני הוא בדעות והוא להעמיד אותנו על כוונת הקרבנות ולזה האריך מזכירת אופן עשיית אהרן אלו הקרבנות כדי שיתבאר לנו שכבר עשה אותם באופן שצותה התורה לא הפיל דבר וזה ממה שיעיר אותנו כי הכל מכוון ולולא זה לא הקפידה התורה בסדר המעשה בהם כמו זה ההקפדה על שכבר מתו נדב ואביהו מפני שנות אותם הסדור הבא בתורה בזה ולפי שהם נשתבשו בזה מפני שלא עמדו על הכונה בעניין הקרבנות אם מצד קצורם אם מצד בלתי התישבם בזה באה בזה המקום לכהני' האזהרה משתיית יין ושכר בבואם לשרת בקדש וזה כלו ממה שיורה שמעשה הקרבנות הנזכרי' בתור המכוונים יצטרך לעמוד על הכוונה ההיא השמירה ממה שיבלבל השכל והמחשבה לזאת הסבה אמר משה על מיתת נדב ואביהו בקרובי אקדש ועל פי כל העם אכבד לפי מה שפירש' ומזה המקום נלמד שמענייני הקרבנות נתישר להשיג קדושת השם והובדלו מחמר כשנעמוד על כוונת' בשלמות ולזאת הסבה זכר בזה המקום שעם זאת העבודה ברך אהרון את העם בהרמת ידיו כאלו יעיר שענייני הפעולות אשר יעשו בזאת העבודה הם מכוונות להשיג הנמצאות העליונות במעלה ובכבוד והם הצורות הנכבדות ובאמצעות זה הרוממות הגיע הברכה לישראל וכבר התבאר אמיתת זה ברביעי ממ"י והנה יתבאר עניין זאת בברכה בפרשת נשא כי שם נזכרה והנה זאת הסבה שזכרנו היתה זאת הברכה בנשיאות ידים אצל החוש כאלו יורה עם זה שאלו העבודות כלם הם מחשביות ומכוונות ולזה הושמו הידים אצל המוח שבו המחשבה והדמיון ולזאת הכונה היתה המחשבה פוסלת בהם כשהיתה בזולת מה שראוי בו הכונה באלו העבודות הוא ממה שיחשב בהם ממה שיעירו עליו לאלו הפעולות בעצמם כמו שביארנו:
@259 **התועלת** השלישי הוא במצות והוא האזהרה לכהנים מלשמע פרועי הראש וקרועי בגדים כי כמו שהקפידה התורה שיהיו להם בגדי' לכבוד ולתפארת לכבוד השם יתע' ובזולת' לא ישמשו כן הקפידה שלא יהיו פרועי ראש וקרועי בגדים כדי שלא יבזום ישראל בלבם ויבזו מפני זאת העבודה הנכבדת הלא ידעת כי ישראל בתעותם בדעותיהם אשר מפני הטעות ההוא נסתבכו בע"ז אמרו כי שלחן יי' מגואל הוא וניבו נבזה אלו:
@259 **התועלת** הרביעי הוא במצות והוא האזהרה מהניח הכהנים עבודתם כשהיו ראוים לה כי זה בזיון נפלא בחק זאת העבודה הנכבדת ולזה אמר מפתח אוהל מועל לא תצאו פן תמותו והנה התועלת בזאת האזהרה הוא תועלת באזהרה שלא ישמשו פרועי ראש פרומי בגדים:
@259 **התועלת** החמישי הוא במצות והוא האזהרה משישמשו הכהן שתויי יין ומהורו' משפט ה' ותורתו למי שישאל ההוראה מהם בהיותם שתויי יין והנה התועלת בזאת הזהרה מבואר:
@259 **התועלת** הששי הוא בדעות והוא ללמדנו כי מה שהוא תמידיי הוא יותר נכבד ממה שאינו נוהג אלא לשעה ואף על פי שהם שוי' בענינם ולא יתחלפו אלא בזה האופן ולזה תמצא שהותר לאונן לאכול החטאת והמנחה שהם קדשי שעה עם היותם קדש קדשים ולא הותר לו לאכול החטאת שהוא נוהג תמיד כמו שיתבאר מדברינו ממה שאמר אהרן למשה ואכלתי חטאת היום הייטב בעיני ה' ומזה המקו' יבתאר שהעצם הנצחי הוא יותר נכבד מהנפסד ושמהות האדם דרך משל יותר נכבד מזה האדם האישי:
@259 **התועלת** השביעי הוא ללמדנו עוצם התבודדות שכל משה בשכליות אשר בעבורו הגיע לזאת המדרגה הנפלאה שנתייחד בזה מבין שאר הנביאים עד שכבר טעה במה שכעס עליו על אלעזר ועל איתמר עם היותו מקור אלו הדינין אשר בתורה בשפע השופע עליו מהם אך היה זה למעוט השתמשות באלו הפעולות עם שגם דבורו החיצוני לא היה יכול לסדרו באופן ראוי כמו שנזכר בפרשת ואלה שמות עם שהורגו בזה לרוב דקדוקו להתנהג במצות התורה ולזה כעס תכף על מה שנראה לו בתחלת מחשבתו שיש בו נטייה ממצות השם יתעלה לא נמנעו מזה מפני מה שחל עליהם מזה המקרה הרע אשר מתו בו נדב ואביהו כאלו יאמר שאין להם מצד זה התנצלות בזה כי יחוייב להם התנהג במצות השם יתע' באופן שלא ימנעם מזה טרדת מחשבתם במה שחל עליהם מהרע כי לעבוד השם יתע' יתחייבו ליישב דעתם ולהסיר ממחשבתם זה העניין באופן שיוכלו למלאות מצות השם יתע' בזאת העבודה הנכבדת:
@259 **התועלת** השמיני הוא במצות והוא להבדיל בין הנאכל ובין הבלתי נאכל בב"ח ההולך וכבר נתבאר התועלת בזה במה שקדם:
@259 **התועלת** התשיעי הוא במצות והוא להבדיל בין הנאכל ובלתי נאכל בב"ח המימיי וכבר נתבאר התועלת בזה ממה שקדם:
@259 **התועלת** העשירי הוא במצות והוא להבדיל בין הנאכל ובלתי נאכל בעף ובשרץ העוף וכבר בארנו התועלת המגיע מזה במה שקדם:
@259 **התועלת** הי"א הוא להודיע דין טמאת נבלת הבהמה ודין טמאת נבלת קצת השרצים ההולכי' על ארבע ושנבלת העוף הטמא ושרץ העוף והב"ח המימיי לא יטמאו כלל וכבר בארנו התועלת המגיע מעניין אלו הטמאות בכללם:
@259 **התועלת** הי"ב הוא במצות והוא להודיע דיני המאכלין והמשקין ודין טומאת הכלים והכשרם וכבר נתבאר מדברינו התועלת המגיע מעניני אלו הטמאות:
@259 **התועלת** הי"ג הוא להודיע הסבה אשר בעבורה מנעה התורה המינים הבלתי נאכלים כי הם ישקצו הנפש המשכלת ויסירו אורה באופן שלא תוכל להתחזק להשיג המושכלות שהם שלמותה מצד העבוי שיקרה מזה לחמר ולזה אמר אל תשקצו את נפשותיכם בכל השרץ וגו' ולמדנו כי זה יהיה סבה אל שלא נוכל להשיג השם יתעלה באופן שיהיה לנו לאלהים וזה גם כן יהיה סבה אל שלא תוכל נפשינו להתקדש ולהתרומם מאלו העניינים החמריים ולהתנקות מהם ולזה אמר נותן סבה במניעתו אלו המאכלין. כי אני השם המעלה אתכם מארץ מצרים להיות לכם לאלהים והייתם קדושים כי קדוש אני כמו שזכרנו בביאור בזאת הפרשה. ואולם שרשי המצות הנזכרות באת הפרשה הנם הם אלו:
@390 וראוי שנתן סבה בסדור אשר היה בענינים הנזכרים בסדר אשה כי תזריע ובסדר זאת תהיה תורת המצורע כמו שיעדנו ואחר נזכיר בע"ה התועלות היוצאות ממה שנזכר באלו הפרשיות לפי מנהגינו:
@390 **ונאמר** כי כבר היה הסדר נותן לפי מה שהשרשנו בסוף פרשת ביום השמיני שיזכיר טמאת הצרעת ואחריה טמאת הזב ואחריה טמאת הזבה ואחריה טמאת הנדה ואחריה טמאת יולדת מפני דמי טוהר שלה ואמנם הקדימה התורה טמאת היולדת לטמאת המצורע להעיר על התועלת המגיע מטמאת הנדה והזבה באופן שתאסר לבעלה והוא שאם תתעבר אז יהיה הנולד מצורע לעפוש הדם אשר יתהוה ממנו ולזה האשה מותרת לבעלה בימי דמי טהרה כי אז לא יקרה מזה זה ההפסד כמו שבארנו במה שקדם וכאלו העירה התורה שיפקח הנרדמים להעמידם על כונתה מפני שנותה הסדור הראוי בזה כי זה ממה שיפקח עיניהם לבקש הסב' והנה בעניין הצרעת הקדימה התורה לזכור דין צרעת עור בשר להיותה מקומה יותר כולל וזכרה ממנו תחלת הצרעת שתתחדש בסבת חום נכרי בא מחוץ והו' השחין והמכוה והקדימה לזכור צרעת השחין כי החו' אשר תתחד' ממנו הוא יותר מתיחס אל החום הנכרי בפנימי הגוף מחום האש אשר תתחדש ממנו צרעת המכוה והנה לא היה בשחין ובמכוה הסגר כי אם בשבוע אחד לפי שמציאות החום הנכרי בהם ידוע ומבואר ולזה יחלט הטמאה קודם החלט לטמאה שאר נגעי צרעת עור בשר ואחרי כן זכרה דין צרעת הראש והזקן לפי שמקומה יותר מעטי ולפי שזכרה התורה טומאת מה שיתבאר בו שהוא צרעת עור בשר ואחרי כן זכרה טומאת מה שיתבאר בו שהוא צרעת הראש או הזקן מפני נשירת השער בכללו מהראש אינו צרע' אבל יהיה דינו דין עור בשר להטמא בנגע צרעת ולהעיר שענין הצרע' איננו בא מצד הצור' כי אם מצד החומר זכרה התורה דין הצרעת בבגד והעור והבית והנה נבחרו הבגד והעור להטמא בצרעת מרוב השתמשות האדם בהם סביב בשרו בלבוש ובמשכב ומושב ולהיותם באים מהצמר והחי הקדים לזכר דין הצרעת בהם לדין הצרעת בבית שהוא מהדומם רוצה לומר מהאבנים והנה זכרה התורה צרעת הבגד והעור קודם זכרה תורה האדם המצורע להעיר הנרדמי' על הכונה אשר בעבור היתה הטהרה בו בשתי צפורים ועץ ארז ואזוב ושני תולעת כי הוא לזאת הסבה בעינה אשר בעבורה רצתה התורה דין צרעת הבגד ובעור ואחר זה זכרה דין צרעת הבית להעיר שההפסד והעפוש לא יהיה בדברים כי אם מצוי טבע החומר והיה מחוייב בנגעי הבית שיהיה בשני הבנים כי האבן אינו חלק מהבית במה שהוא בית אם לא מצד הרבוי. והרבוי הראשון הוא שנים והיה בו הסגר שלשה שבועות לסבה שזכרנו ואחר שנשלם זכר דיני הצרעת זכרה התורה החמורה אחר הצרעת והוא טומאת הזב כמו שבארנו בסוף פרשת שמיני ולחמר טמאתו החמירה התורה בטהרתו עד שלא יטהר כי אם במי מעיין ויצטרך לספירה שבעה נקיים אע"פ שלא היה כי אם בעל שתי ראיות כמו שבארנו אצל טמאתו לא החמירה התורה יותר ממה שהחמירה בטמא' זבה ונדה ויולדת לפי שטמאתו אין בה כי אם תועלת עיוני להעיר על מציאות הצורה הנעדרת מהזוב כמו שבארנו במה שקדם וטמאת זבה ונדה ויולדת יש בה תועלת להסיר ההפסד מולדותיהן ולזה תמצא בענין בעילתן איסור כרת וטמאת בועלין לטמא משכב ומושב מה שאין כן בבעילת הזבה כי לא יקרה ממנה כמו זה ההפסד והנה היה ראוי שיזכור אחר טמאת הזב טמאת הזבה והנדה אבל הקדים לזכור טמאת שכבת זרע לשתי סבות האחד כי מפני שזכר בטמאות הפורשות מהזכר הנה היה ראוי שישלים המאמר בהן קודם שיכנס בספור הטמאות הפורשות מהנקבה והשנית כי שנמצא טמאת הזב חמור' בזה האופן וטמא' שכבר זרע קלה הנה יעירנו זה למצוא הסב' אשר בעבורה היה ענין הטמאות וזה שהזוב והשכבת זרע נושאם אחד אלא שמהזוב נעדרה הצורה אשר בה יהיה נאות להולדה ולזה יתבאר לנו מזה כי הטמאות האלו הם לזאת הכונה ויישירנו זה לעמוד על כונת התורה בזה ויהיה זה סבה להגיע לנו בזה זהז התועלת הנפלא אשר כוונה התורה בו והנה היה ראוי שתזכור התורה תחלה דין הזבה קודם דין הנדה כי טומאתה יותר חמורה בשהית' זבה גדולה ואמנם הקדימה לזכור דין הנדה לפי שהאשה לא תהיה זבה אלא אם כן היתה קודם זה נדה כמו שבארנו וזכרה אחרי כן דיני הזיבה ואופן טהרתה שהוא יותר חמור כשהיתה זבה גדולה מטומאת נדה עם שכבר תתחייב קרבן להורות על חוזק טמאתה שלא תסור בטבילה אם לא יתחבר אליה קרבן ואולם התועלו' ההגיעות מאלו הפרשיו' הנה הם עשר':
@390 **התועלת** הראשון הוא בדעות והוא מה שלמדתנו התור' במה שאמר אשה כי תזריע וילדה זכר של זרע הנקבה מבוא בהולדה כמו שבארנו:
@390 **התועלת** השני הוא במצות והוא להודיע דין טמאת היולד' וטהרתה וכבר ביארנו התועלת המגיע מזאת המצוה בדעות ובבריאות גוף הנולדים והנה שרשי זאת המצות הם ארבעה:
@390 **התועלת** השלישי הוא במצות והוא מה שצוה למול את הבן ביום השמיני והנה התועלת בזאת המצוה הוא כמו שזכר הרב המורה להחליש כח האבר ההוא שלא ימשך האדם אל זה הפעל המגונה אם לא לקיון המין כי כל שוגה בו לא יחכם וימנע ממנו כל שלמות לרוב המשכו לזה הפעל המגונה וטרדתו בו והוא מבואר מאד מן החוש ולזה אמר נואף אשה חסר לב משחית נפשו הוא יעשנה ואמר מי פתי יסור הנה ואמר שם כי האויל הולך אחריה פתאום כשור לטבח יובל והוא בלתי מרגיש כי בנפשו הוא והנה לא הסכימה התורה להחלישו באופן שימנע זה הפעל לגמרי אבל הזהירה מזה אפילו בשאר בעלי חיים והנה היתה המילה בשמיני כמו שזכר הרב המורה לפי שאז התחזק כה הנולד קצת חיזוק ולו עדיין מן הרכות מה שיסבב שלא יקשה לו מאד זה החתוך עם שאז לא התחזקה מאד האהבה הדמיונית בין הוריו ובינו ולזה יקלו בו אז למלאת מצות השם יתע' ויהיה זה סבה מביאה להשלמת זאת המצה ואלו באה המצה הראשונה לילוד הנה כשיכנס בגדר החיוב במצות יהיה לו מהקושי בזה הפועל מה שאפשר שיהיה סבה אל שלא ישלים המצוה הזאת והנה זה גם כן אות ברית יוכרו בו אנשי התורה השלמה וזה ממה שישלים קיום התורה כמו שזכר הרב המורה בספרו הנכבד מורה הנבוכים ואולם שרשי זאת המצוה הם ששה:
@390 **התועלת** הרביעי הוא במצות והוא מה שצוה שתקריב היולדת קרבן להשלי' טהרתה והנה התועלת בזאת המצוה הוא להעיר על חוזק זאת הטמאה שלא תטהר כמו העניין בטמאות מת ומצורע וזב וזבה וכבר זכרנו התועלת המגיע בדעות מענין הטמאות והטהרו' והנה שרשי זאת המצוה הם שני':
@390 **התועלת** החמישי הוא במצות והוא מה שצוה שיהיה המצורע טמא באופן הנזכר בתורה וכבר התבאר במה שקדם התועלת המגיע מזאת המצוה ואולם שרשי זאת המצוה הם כ"ב:
@390 **התועלת** הו' הוא במצות והוא מה שצוה שלא יגלח השערות שהן סביב הנתק כדי שיכיר הכהן אם פשה הנתק שנאמר והתגלח ואת הנתק לא יגלח ולזה חוייב כמו שזכרנו שישאיר שני שערות בכל סיבות הנתק והתועלת בזאת המצוה הוא מבואר ומזה המקום נלמד שהתולש סימני טמאה עובר בלא תעשה וזה שאם הזהירה התורה שלא יגלח השערו' ההם כדי שלא תנעול דלת בחינת הפשיון אם יהיה שם בפני כהן כ"ש שתזהיר מהשחית סימני הטמאה עצמם וזה מבואר בנפשו כבר נתבאר זה בי' משבת ובספרא וכן ההקש בצרעת בגדים ובבתים כבר נתבאר זה בשלישי מתוספות נגעים והוא מבואר שהתולש סימני טמאה אחר החלט לא יטהר מפני זה כי לא תהיה מפני זה ראיה שנרפא הנגע אם לא יתבאר באופן אחר שכבר נרפא ואולם אם נשחתו מעצמם בזולת כוונה כגון שנשא משא על כתפו שיש בו צרעת והלכו סימני טמאה הרי זה טהור כבר נתבאר בשלישי מנגעים ובשלישי מתוספות נגעים:
@390 **התועלת** הז' הוא במצות והוא מה שצוה שיהיה המצורע ידוע לכל כדי שירחקו האנשים ממנו ולזה גם כן צוה שישב חוץ לשלשה מחנו' שנאמר והצרוע אשר בו הנגע בגדיו וגו' בדד ישב מחוץ למחנה מושבו ולפי שכבר אמר איש צרוע הוא שהוא מורה שאינו דבר באשה למדנו כי לעניינים הנזכרים בזה שאין האשה ראויה בהם כמו האיש לא ישוה בהם דין האשה לדין האש ולזה יתבאר שאין האשה פורעת ופורמת ואינה עוטה על שפם אבל יושבת חוץ לעיר ומודיעה לכל שהיא טמאה ובכלל הנה כל טמא יחוייב שיודיע לכל שהוא טמא שנ' וטמא טמא יקרא. והוא מבואר שפריעה ופרימה נוהגת אפילו בכהן גדול אם היה מנוגע והוא מבואר עוד שדין הקטן ודי' הגדול שוים בענייני הצרעת והטמאות שינהגו מנהגו וראוי שתדע שאלו העניינים מהפריעה והפרימה ועטיה על שפם והנמשך להם הם נוהגים כל ימי הנגע בו אבל אם נרפא נגעו או סר בלא מתכוין או אם סר אפי' במתכוין אם נולד שם אחר זה סימן מורה שכבר נרפא כאלו תאמר שהיתה לו בהרת והוחלט בה לטמאה וקצצה בצמצום ואחר זה פרחה הצרעת בכל גופו אין דבר מאלו הדברים נוהג בו שנאמר כל ימי אשר הנגע בו כבר נתבאר זה כלו מספרא ולפי שאמר בזה המקום בגדיו יהיו פרומים וראשו יהיה פרוע ואמר בכהן גדול על ענין האבל את ראשו לא יפרע ובגדיו לא יפרום שמורה ששאר האבלים חייבים בזה למדנו שכל דיני האבל נוהגין במצורע המוחלט והיה זה כן כדי שיתן אל לבו שבסבת חטא מה קרה לו הענש אשר הוא כמו מיתה כמו שאמר במרים אל נא תהי כמת כבר נתבאר זה בשלישי ממעוד קטן וראוי שתדע שהמצורע הוא מטמא באהל שנאמר בדד ישב מחוץ למחנה מושבו מגיד שמושבו הוא טמא וכבר נלמד שזה הדין נוהג גם כן במצורע מוסגר ממה שאמר כדומה לזה בבית המנוגע והבא אל הבית כל ימי הסגיר אותו וגומר. הוא מבואר ממה שאמרנו מענייני הטמאות שהאדם המנוגע הוא יותר ראוי בזה הדין אך לא ישלחוהו מחוץ למחנה אם לא היה מוחלט ואולם התגלחת והצפורים ושאר דברים שזכרנו לא ינהגו אלא במצורע מוחלט שנאמר בזה העניין ויצא הכהן אל מחוץ למחנה וגו' מגיד שהמנוגע הוא אז מחוץ למחנה כבר נתבאר זה בשמיני מנגעים ובראשון ממגלה וראוי שתדע שהשלוח חוץ למחנה ינהג בארץ ישראל לבד בעיירות המוקפות חומה כי הם אשר להם חוץ כבר נבתאר זה בראשון מתוספות כלים וראוי שתדע שהמצורע מטמא בטמאת הזב והזבה רוצה לומר שהוא מטמא משכב ומושב אפי' תחת האבן ומטמא בהיבט כמו הזב ואינו צריך לומר הוא מטמא במגע ובמשא וזה כלו למדנו ממה שמצאנו שהחמיר במצורע שיהיה מטמא ביאתו לבית כל אשר בבית בין אדם בין כלים כבר נתבאר זה בראשון ובי"ג מכלים ולפי שאמר מושבו למדנו שאם לא נתישב שם ר"ל שלא עמד ולא ישב שם תחת האילן או תחת האהל אבל עבר דרך שם לא נטמא כל אשר תחת האהל שאין אני קורא לזה שיהיה זה מושב כבר נתבאר זה בשלש עשרה מנגעים. התועלת הח' והט' הוא במצות והוא מה שצוה לטהר המצורע המוחלט בתגלחת וצפורי וכל אחד מאלו הדברים הם מצות עשה לפי מה שזכר הרב המורה ובזה עיון וכבר נתבאר התועלת בזאת המצוה במה שקדם ואולם שרשי המצות הם י"א:
@390 **התועלת** העשירי הוא במצות והוא שצוה שיהיה הבגד המנוגע טמא וכבר נתבאר התועלת המגיע מזאת המצוה במה שקדם ואולם שרשי זאת המצוה הם שמנה:
@390 **התועלת** הי"א הוא במצות והוא מה שצוה שיביא המצורע קרבנותיו אחר שיטהר וכבר בארנו התועלת בזה במה שקדם ואולם שרשי זאת המצוה הם א':
@587 **התועלת** הראשון הוא במצות והוא האזהרה מלבא לפני לפנים שלא לצורך עבודה ותועלת זאת ההזהרה מבואר כי מה שיורגל האדם בראייתו לא יפליג לחקור על עניינו ולתת ללבו למה היה זה כן בזה האופן לחשבו שכבר אפשר לו לראותו תמיד כמו הענין שיפליג במה שלא יראה אותו כי אם לעתים רחוקים ולזה יהיה זה סבה לעמוד על סוד הענין ההוא אשר כונה בו התורה על מה שלא יותר לו לאדם לראותו בכל עת שירצה כי אם פעם אחת בשנה ועם כמו זאת העבודה הנפלאה תגדל מעלתו מאד בנפש ויהיה זה סבה שיתבונן בענינו ויחקור על סודו ובזה יגיע התועלת אשר כונה התורה בו וכבר יתבאר לך מעוט הבנת האדם בדבר המורגל שאתה תראה באלו התפלות הנפלאות אשר סדרו' לנו אנשי כנסת הגדולה שלרוב הרגילנו בהם נדבר בהם תמיד ולא נשתדל לעמוד על סודם שיהיה זה סבה לרבים מחכמנו שיטעו בהם הרבה בדבר' בהם למעוט עמידתם על המכוון בהם וכן תמצא בתורתנו השלמה שלרוב הרגילנו בזה הסתפקנו בקריאתה לבד ולא נעמיק לעמוד על כוונתה עד שאין לרבים מבקיאי חכמינו שום ציור מהרבה מענייניה כמו מלאכת המשכן וכליו ועניין הקרבנות והטמאות והטהרות ומה שידמה להם ומכלל זאת האזהרה גם כן שלא יכנס אדם לאהל מועד שלא לצורך עבודה לזאת הסבה בעינה אלא שיתחייבו על זה מיתה כמו העניין במי שנכנס לפני לפנים שלא לצורך עבודה כמו שביארנו בביאורנו לזאת האזהרה מהמקומות הכוללים:
@587 **התועלת** הב' הוא במצות גם כן והוא הצווי בעבודת יום הכפורים וכבר ביארנו התועלת המגיע מזאת המצוה:
@587 **התועלת** הג' הוא במצות והוא הצווי להתענות ביום הכפורים ולשבות בו מכל מלאכה וכבר נתבאר התועלת המגיע מאלו המצות:
@587 **התועלת** הד' הוא במצות והוא שהוזהרנו מלשחוט הקרבנות חוץ לעזרה ולהקריב חוץ לעזרה וכבר ביארנו במה שקדם התועלת המגיע מאלו האזהרות:
@587 **התועלת** הה' הוא במצות והוא מה שצונו לכסות דם חיה ועוף הראויים לאכילה כבר ביארנו התועלת המגיע מזאת המצוה:
@587 **התועלת** הו' הוא במצות הוא לדין בנבלת עוף טהור בטומאתה שלה באופן שצותה התורה וכבר נתבאר התועלת המגיע בזאת המצוה בסוף פרשת ויהי ביום השמיני ובביאורנו לזאת הפרשה:
@587 **התועלת** הז' הוא במצות והוא האזהרה שלא נקרב לשאר בשר ושלא נגלה ערוה מאלו העריות שזכרה התורה או שהם בכח הבריה וכבר נתבאר התועלת המגיע מאלו האזהרות בביאורנו לזאת הפרשה ולפרשת אשה כי תזריע:
@587 **התועלת** הח' הוא במצות והוא האזהרה שהוזהרנו מלהעביר מזרענו למולך והתועלת בזאת האזהרה הוא נפלא מאד כי הטעות בהתחלה הראשונה הוא השם יתעלה מונע כל שלמות האנושי וכ"ש כשהיה התעות בו בזה האופן אשר לא תתכן עמו שום חכמה ושום ידיעה וזה כי כשלא נודה שתהיה בכאן סבה פועלת היא שכל תסור מהדברים הסבה התכליתית והצוריית שהם הנכבדות שבסבות וזה מבואר מאד:
@587 **התועלת** הט' הוא בדיעות והוא שכאשר יביא ההכרח להביא הרע על קצת האנשים להשגחה על הטובים הנה לא יסכים השם להביא הרע על האנשים ההם אם לא היו ראויים לו וזה ראוי בחק היושר האלהי וחוזק חנינתו לנמצאות עד שלא יביא רע ממנו כי אם מצד מה שהוא טוב ולזה ביאר כי הורשת ה' יתע' הגוים ההם מפני ישראל היתה מצד הפלגת רוע מעשיהם ובזאת הסבה הקיאה הארץ אותם ובזה המאמר עם זה הערה לחוזק הארץ ההיא אל שישפע בה השפע האלהי עד שלמעלתה לא תוכל להכיל כמו אלו הפעולות המגונות וזה שהוא מבואר כי המקומות היותר נכבדים ראוי שתנהגו בהם בקדושה נוספת:
@778 **התועלת** הראשון הוא במצות והוא שלא יטמא אחד מהכהנים למת זולתי לקרוביו הנזכרים בזאת הפרשה ולא כהן גדול למת אפילו היה מקרוביו וכבר התבאר התועלת המגיע מזאת האזהרה במה שקדם:
@778 **התועלת** השני הוא במצות והוא האזהרה מקרוח הכהנים קרחה בראשם למת ומשרוט בשרם שריטה לנפש וזה מדרכי האמוריים ובר התבארו התורה באלו האזהרות במה שקדם:
@778 **התועלת** השלישי הוא במצות והוא האזהרה מלגלח הכהנים פאת זקנם וכבר נתבאר התועלת המגיע מזאת האזהרה במה שקדם בזאת הפרשה:
@778 **התועלת** הרביעי הוא במצות והוא שלא יקח אחד מהכהנים אשה זונה וחללה וגרושה ולא כהן גדול אלמנה כי אם בתולה מעמיו וכבר התבאר התועלת המגיע מאלו המצות אצל המאמר בהם:
@778 **התועלת** החמישי הוא במצות והוא שנדין בשרפה בת כהן שתהיה אשת איש שזנתה התועלת מבואר בזאת המצוה:
@778 **התועלת** הששי הוא במצות והוא האזהרה שלא יפרע כהן גדול ראשו בעת מהעתים ושלא יפרום בגדיו כי הוא היה תמיד במקדש ולזה ראוי שיהיה תמיד ראוי לעבודה וכבר התבאר התועלת המגיע מאלו האזהרות בפרשת ויהיה ביום השמיני:
@778 **התועלת** השביעי הוא במצות והוא האזהרה שלא יניח כהן גדול עבודתו מפני אנינותו על מות אחד מקרוביו כי הוא בלתי מחלל עבודתו בזה והתועלת בזאת האזהרה הוא להעיר שאין ראוי לשלם שיכאיב לבו מאד על כמו אלו העניינים כי אין בהכאבת לבו תועלת כלל ולא יוכל להשיב מה שהיה ולזה לא יניח עבודתו כהן גדול מפני האנינות כי לגודל מעלתו הוא בלתי מתפעל באלו המקרים באופן שיבלבל כונתו אשר בזאת העבודה הנכבדת לשם יתע' ואין ראוי גם כן שלא יתן אל לבו זה הענין כלל ולזה לא יתכן לו שיאכל קדשים באנינות כמו שהתבאר בפרשת שמיני כי אם תביאהו עוצם אהבתו השם יתע' לבלתי תת לבו כלל באנינות בעת שמושו במקדש הנה בעת אכל ולא יוכל על זה כי ראוי שיתן החי אל לבו אלו הענינים וידאג דאגה מה במיתת קרוביו כמו שביארנו בענין ספוד אברהם לשרה ובכותו עליה לזאת הסבה נמנעו שאר הכהנים מלשמש באנינות כמו שהתבאר מזה המקום:
@778 **התועלת** השמיני הוא במצות והוא שלא יקרב כהן גדל בעל מום לעבודה ולא יבא אל הפרוכת ואל המזבח לא יגש ואף על פי שלא עבד וכבר התבא' התועלת המגיע מאלו האזהרות אצל המאמר בהם:
@778 **התועלת** התשיעי הוא במצות והוא האזהרה שלא יקרב כהן בלתי טהור לעבודה ושלא יאכל כהן טמא קדשים על מדרגותיהם רוצה לומר שלא יאכל תרומה אפילו טבל אם לא העריב שמשו ולא יאכל קדש אפילו העריב שמשו אם לא הביא כפרתו וכבר בארנו התועלת המגיע מאלו האזהרות אצל המאמר בהם:
@778 **התועלת** העשירי הוא במצות והוא אזהרה שלא יאכל זר קדש ולא תרומה אלא אם כן היה קנין כספו של כהן כמו עבדו הכנעני או אשתו או בהמתו וכן תאכל בתרומה בתו אם לא היתה לזר או אפילו אם היתה לזר ומת וזרע אין לה והתועלת באלו המצות מבואר:
@778 **התועלת** הי"א הוא במצות והוא לבאר דין זר אוכל בתרומ' בשגגה והתועלת בזאת המצוה מבואר:
@778 **התועלת** הי"ב הוא במצות והוא האזהרה שלא להקדיש בעל מום למזבח ושלא לזרוק דמו על המזבח ושלא להקטיר ממנו אשה על המזבח והתועלת באלו המצות מבואר מדברנו בהם:
@778 **התועלת** הי"ג הוא במצות והוא האזהרה שלא להשחית כלי הולדה מאיזה שיהיה מהבעל חי וכבר ביארנו התועלת המגיע מזאת האזהרה במה שקד' מזאת הפרשה:
@778 **התועלת** הי"ד הוא במצות והוא לבאר הבלתי ראוי לקבל מהבלתי בעל מום כמו הכלאים ויוצא דופן והיתום אשר הוא מבן שמנה ימים וכבר ביארנו הסבה בזה אצל ביאורנו לזאת המצוה:
@778 **התועלת** הט"ו הוא במצות והוא האזהרה שלא לשחוט אותו ואת בנו ביום אחד וכבר ביארנו סבת זה במה שקדם:
@778 **התועלת** הי"ו הוא במצות והוא האזהרה שלא לחלל את השם הנכבד לעבור על מצותיו על צד המרד בו אבל ראוי שימסור עצמו למיתה אם כריחו בזה מכריח לבזות השם יתעלה כמו שהתפרסם מהאומות שגזרו שמד על ישראל וזאת היא המצוה שצונו לקדש שמו ברבים והנה התועלת באלו המצות מבואר כי בזה האופן תשאר התורה קיימת תמיד ולולי זה היה אפשר שתסור ממנו לרוב שונאים הקמים עליה יסור ממנה בסורה זה הטב הנפלא המגיע מהתורה אשר אין לשאר הטובות יחס אליו כלל:
@778 **התועלת** הי"ז הוא במצות הם המצות באו בעניין המועדים בכללם וכבר ביארנו התועלת המגיע מהם במה שקדם:
@778 **התועלת** השמנה עשרה הוא במצות והוא להודיע דין המברך את השם והנה התועלת בזאת המצוה הוא מבואר בנפשו:
@919 **התועלת** הראשון הוא במצות והוא מה שנצטוינו על שביתת הארץ והאילנות בשנת השמטה והוזהרנו מהזריעה והקצירה והזמירה והבצירה וכבר נתבאר מדברינו התועלת מזאת המצוה:
@919 **התועלת** הב' הוא במצות והוא מה שנצטוינו לקדש שנת היובל אחר עבור מ"ט שנה ולקרא דרור בארץ לכל יושביה באופן שישוב איש אל אחוזתו ואיש אל משפחתו ולבות הארץ מהעבודה כמו העניין בשנת השמטה ולתקוע בשופר עשור לחדש השביעי בשנת היובל וכבר נתבאר מדברינו התועלות המגיעות מאלו המצות:
@919 **התועלת** הג' הוא במצות והוא מה שהוזהרנו מלהונות בענין מקח וממכר אפיל בדברים והנה התועלת בזאת המצוה מבואר בתקון הקבוץ המדינה:
@919 **התועלת** הד' הוא במצות והוא מה שזכרה התורה מדיני מוכר מאחוזתו ומוכר בית בערי חומר וכבר נתבאר מדברינו התועלת המגיע מזאת האזהרה במה שקדם:
@919 **התועלת** הה' הוא במצות והוא מה שהזהירה התורה מלשנות בערי הלויים דבר ממה שהוא עליו ר"ל שלא נשיב שדה מגרש או הפך ושלא להשיב השדה או המגרש עיר או הפך וכבר ביארנו התועלת המגיע מזאת האזהרה במה שקדם:
@919 **התועלת** הו' הוא במצות והוא מה שהזהירה התורה מליקח איש מאחיו נשך ותרבית כי בזה מההפסד בקבוץ המדיני מה שלא יעלם עם שבזה הענין יקנה לאדם תכונות מגונות לרוב השתדלותו באסיפת הממון עם שכבר יתחכם תמיד להמציא מעות למי שיראה שיוכל להרויח עמו מצד חסרון דעתו ורבוי קנייניו וישתדל בתחבולות רבות שיקח מעות ממנו להשיג מבוקשיו:
@919 **התועלת** הז' הוא במצות והוא מה שבארה התור' מדיני הנמכר לעבד מישראל לישראל או לגר צדק או לגוי ודיני הנמכר לישראל משאר האומות וכבר נתבאר מדברינו התועלת המגיע מאלו המצות:
@919 **התועלת** הח' הוא במצות והוא מה שהזהירה התורה מהקים מצבה ומהשתחוות על אבן משכית אפילו לש"י מאלו וכבר נתבאר מדברינו התועלת המגיע האזהרות ואולם שרשי המצות הנזכרות בזאת הפרשה הנה ממצוה הראשונה הוא מה שצונו לשבות הארץ ממלאכה בשנת השמטה:
@998 **התועלת** הראשון הוא בדעות והוא להודיע שההשגחה האלהית תדבק לטובים גם בענינים הגופיים להביא להם הטובות בהם ושכבר ימשך לעוצם ההשגחה לטובי' שתמשך לזרעם אחריהם באופן שכאש יסורו מדרכי התור אשר הוא סבת סור כל שלמות מהם ייסרם השם יתעלה מוסר אחר מוסר באופן שלא ישתקעו בדעות הנפסדות ההם וישובו לקנות השלמות אשר סרו ממנה:
@998 **התועלת** השני הוא במצות והוא מה שצונו לדון בערכי אדם לפי מה שזכרה התורה והנה התועלת בזאת המצוה מבואר כי הרבה פעמים יעלה בלב האנשים לתת ערך אדם מה להש' יתע' למען ישמרהו השם ויחייהו עד שתמצא שקצתם יתנו משקלם לזאת הסבה ולפי שהאדם נכבד מאד ביחס אל הכסף והזהב היה חושב שלא יהיה בין ערכו והכסף והזהב יחס ולזה הגבילה התורה זה הערך אשר לא יקשה מאד וגם בו הקלה אם לא תשיג יד הנודר והנה למדתנו התורה באלו הערכים סודות מהדברים הטבעיים וזה כי מפני שהיה ערך הנקבה תמיד פחות מערך הזכר למדנו שהאשה חסרת הבריאה ביחס אל האיש כמו שהתבאר זה בטבעיות. ולמדנו עוד מזה כי קודם הגיעם לעשרים שנה הם בזמן הצמיחה ולזה הם דורכים אל החסרון והפסד ומפני זה היה הערך יותר גדול מבן כ' ועד בן ס' שנה ועד בהיותו בן חדש לא היה לו ערך כי אולי הוא נפל ומבן חדש ועד בן חמש שנים לחוזק החסרון אשר בבריאתו לא היה ערכו כי אם עשירית הערך השלם לזכר ולנקבה ואולם מבן ה' ועד בן כ' שנה שהחל להתחזק ולמאוס ברע ובחור בטוב כי הוא דורך על השלמות היה ערך הזכר יותר ממי שהוא מבן ס' ומעלה כי הוא דורך אל החסרון וההפסד ואמנם ערך הנקבה לא היה מתחלף אל ערכה מבת ששים שנה ומעלה להעיר שהמשגל לזולת פרי הראוי הוא בלתי נבחר ולפי שהנקבה היא היותר חשוקה למשגל בהיותה למטה מבת כ' הפחיתה התורה ערכה יותר מהיחס הנמשך לערך הנקבה עם ערך הזכר כי המשגל העושה פרי שלם בה הוא מהיותה מבת כ' שנה ולמעלה ולהשלים ההערה בזה לא הפחיתה התורה ערכה מבת ששים שנה ומעלה לפי היחס הקודם אבל שמה ערכה יותר משלשת חמשיות ערך הזכר באון שיהיה ערכה בהיותה מבת ס' ומעלה שוה לערכה בהיותה למטה מעשרי' שנה עד היותה אז בלתי ראויה למשגל כלל שאין המשגל לזולת הפרי הראוי היותר נבחר מהעדרו:
@998 **התועלת** השלישי הוא במצות והוא מה שצונו לדון בהקדשי הבהמה הטהורה אשר אינה ראויה לקרבן. והנה התועלת בזאת המצוה מבואר והנה הזהירה התורה מהמיר ומהחליף בהמה בבהמה כדי שלא יקלו האנשים בעניין ההקדשות ויביאו תמורתה הפחות שבדברים כי דעתו של אדם קרובה אל ממונו עם חשבו שאין בזה הזק כלל כי כבר יקריב זה הבעל חיים תמורת הב"ח ההוא ויחשב גם כן כי מפני שזה הב"ח הקרב הולך לאיבוד טוב שימירו אותו בפחות ממנו ויביא זה להפחית מעלת הקרבנות ולבזותם ומפני זה קנסה אותו התורה שיהיה הוא ותמורתו קדש:
@998 **התועלת** הרביעי הוא במצות והוא מה שצונו לדון בהקדשי הבית ושאר הקרקעות היו שדה אחזה או שדה מקנה ולא רצתה התורה שישוב שדה אחזה בשנת היובל למקדי שאותו כדי שלא להקל בעניין ההקדש כי אם היה אז שב לבעלים היה דומה לאנשים שיהיה הקדש יוצא בלא פדיון ויקרה מפני זה מן ההקל בעניין הקדשים מה שלא יעלם:
@998 **התועלת** החמשי הוא במצות והוא מה שצונו שלא לשנות הקדשי' מקדושה לקדושה וזה מבואר התועלת לתת מעלה גדולה בנפש לקדשים:
@998 **התועלת** הששי הוא במצות והוא מה שצונו לדון בחרמי הכהנים ושלא ימכר ושלא יגאל באופן שתתוסף נחלתם תמיד בדרך שתוכל להספיק להם עם התרבות' כי זה ממה שיתעוררו האנשים לתת מהונם בזה האופן לזאת המשפחה הנכבדת אשר כל מגמת פניהם הוא לעבודת הש' יתע':
@998 **התועלת** הז' הוא במצו' והוא מה שצונו להפריש מעשר שני מן הפירות והזרעים ומעשר בהמה וכבר ביארנו התועלת באלו המצות במה שקדם ואולם שרשי המצות הנזכרות בזאת הפרשה הנה המצוה הראשונה הוא בערכי אדם והנה השרש הראשון הוא:
@998 **תם ונשלם ספר ויקרא תהלה לאל גבור ונורא:**

@365 והנה מרוב השמחה היה דוד מרקד ומפזז לפני ה' כאילו לא היה מלך ולזה בזתהו בלבה מיכל בת שאול והנה לתת תודה לש"י הקריב דוד כמה קרבנות אז בהוליך הלוים ארון ברית ה' ובסוף הענין בבא ארון ה' למקומו אשר הכין לו דוד העלה עולות ושלמים לכבוד השם ית' לפי מה שאפשר ואחר זה ברך דוד את העם בשם ה' צבאות ונתן לכל אחד מנה יפה לאכול ולשתות, והנה אשפר אחד הרצון בו לפי מה שבארו ז"ל אחד מששה בפר ולפי הפשט נראה שהיתה מנה יפה נהוגה לתת לאיש אחד בסעודות הגדולות וענינו מענין שפרה עלי והאל"ף נוסף ר"ל שהיתה המנה הזאת בתכלית היופי לפי המנות הנהוגות לתת כמו אלו המנות הגדולות הנהוגות לתת לאורחים הבאים אצלם:
@369 והנה מיכל בת שאול דברה שלא כהוגן אל המלך ונתבאר מדברי דוד שמה שעשה עשה כהוגן לכבוד הש"י והמשיך בדבריו מה שהכאיב לבה בו כי זה הגמול היה ראוי לה על מה שהטיחה דברים כנגד דוד ר"ל מה שאמר שבחר הש"י בו מאביה ומכל בית אביה והיה מפרי דבריה שאמר לה דוד וכללה עם האמהות ולזה אמר ועם האמהות אשר אמרת עמם אכבדה וכבר אמר והודה שכבר רמז בזה המאמר אל מיכל מה שאמר אחר זה ולמיכל בת שאול לא היה לה ולד עד יום מותה כאילו יאמר שזה המאמר היה סבה להמנע ממנה פרי בטן כי לא אהב אותה דוד באופן שהיה אוהב אותה קודם זה:
@374 וכבר התעורר דוד לבנות בית לה' יהיה בו ארון האלהים ונועץ בזה עם נתן הנביא וענהו בכללות שיעשה כל אשר בלבבו כי ה' עמו:
@376 ואחר זה באהו דבר ה' על יד נתן הנביא שאין ראוי לבנות לו בית לש"י כי מן היום אשר העלה בני ישראל מארץ מצרים התהלך הארון באהל ובמשכן ולא שלח הש"י לאמר לאחד מן הרועים והשופטים למה לא בנו בית ארזים ועתה די לדוד לקחו הש"י מאחרי הצאן להיות נגיד על בית ישראל והיה עמו בכל אשר הלך וכרת שונאיו ועשה לו שם גדול כשם הגדולים אשר בארץ לרוב הצלחתו ורוב עמידת מלכותו ושם על ידו מקום מנוחה לישראל ולא צרו לישראל שונאיהם כמו שעשו בראשונה ובימי השופטים והניח לו השם מכל אויביו והגיד לו ה' כי בית יעשה לו קיים בדרך שתהיה לו המלוכה כל מה שהתמיד מלוכה ובהיות הענין כן הנה די לו במה שהגיע בו מן ההצלחה ולא ישאל לו גדולות שיהיה נבנה בית המקדש על ידו אבל בנו שימלוך אחריו הוא יבננו והוא שלמה וכבר נתבאר בספר דברי הימים שהסבה שלא הסכים הש"י שיבנה דוד בית המקדש הוא מפני ששפך דמים הרבה:
@384 וזכר שזרע דוד אשר יקום אחריו יכונן את כסא ממלכתו עד עולם ואף על פי שיחטא לו לא יסור חסדו ממנו בדרך שתפסוק ממנו הממלכה לגמרי כמו שנפסקה משאול:
@457 **לחם בכורים.** הוא מקציר השעורים כי הם נקצרים ראשונה: **וכרמל בצקלינו.** אחשוב שכבר היו קולין השעורים ואח"כ שוברין אותם והיו קושרים אותם לחלקי' גדולים והוא הנקרא כרמל ואמר שהוא בצקלונו ר"ל בכלי שהיה לו לשאת בו אלו הדברים:
@460 **כי בו נתן ה' תשועה לארם.** ידמה שהתשועה הזאת היא הריגת אחאב שנצחם שני פעמים והנה התשועה היא כי בלי מתכוין משך בקשת לתמו והמית אחאב:
@461 **וארם יצאו גדודים.** ר"ל שמבני ארם יצאו גדודים: **נערה קטנה.** הנה יקרא נער הקטן אמר בשמואל והנער נער ולא היו לו כי אם שתי שנים ולזה אמר ונער קטון נוהג בם ולזאת הסבה גם כן בזה המקום נערה קטנה: **ותהי לפני אשת נעמן.** רוצה לומר לשרתה:
@462 **אחלי אדני לפני הנביא וגו'.** ר"ל אם תהיינה תחנות אדני ובקשותיו לפני הנביא אשר בשומרון אז יאסוף אותו מצרעתו:
@463 **ויבא ויגד לאדניו.** ר"ל שנעמן בא והגיד זה לאדניו למלך ארם:
@465 **ואספתו מצרעתו.** ר"ל שתרפאהו מצרעתו ונקרא הרפואה מהצרעת אסיפה כי הצרעת תעשה מהאחד רבים כי מפני תגבורת החום העפושי יחלש מאד החום הטבעי הקושר איברי הבעלי חיים ומשים אותם אחד ולזה תמצא במצורע שכבר יפלו אבריו ולזה אמר בזה המקום ברפואת המצורע וישוב בשרך לך וטהר כי המצורע אין בשרו לו כמו שזכרנו כי אין בו הדבר שקושר בשרו בו:
@466 **כי מתאנה הוא לי.** ר"ל מבקש תואנה כדי שילחם עמי:
@470 **והניף ידו אל המקום.** ר"ל אל המקום אשר הוא עובד הש"י:
@471 **הלא ארחץ בהם וטהרתי.** ר"ל הלא אני רוחץ בהם תמיד האם טהרתי מצרעתי מפני רחיצתי בהם:
@472 **אבי דבר גדול הנביא דבר אליך.** ר"ל אילו דבר אליך הנביא לעשות דבר גדול הלא תעשה כדי שתרפא אף כי אמר אליך שתרפא בדבר קל כזה והיא הרחיצה בירדן שבע פעמים שיש לך לעשות דבריו:
@474 **קח נא ברכה מאת עבדך.** רוצה לומר מנחה:
@476 **ולא יתן נא לעבדך צמד פרדים אדמה.** רוצה לומר נניח זה אחר שאין רצונך לקחת גמול על זה שעשית לי מן הטוב אך אשאל ממך שתתן לי דרך אוכל לעבוד בו השם יתברך שעשה לי זאת הטובה ולזה שאל מאלישע שיותן לו מביתו מה שיוכל לשאת שני פרדים מאדמה לבנות בה מזבח לה' כי לא יעבוד עוד אלהים אחרים כי אם השם יתברך לבדו ובקש לאלישע שיתפלל לש"י שיסלח לו לדבר הזה והוא השתחוייתו בית רמון אשר הוא מוכרח בה מפני היות אדוניו נשען עליו בבאו בית רמון להשתחוות:
@478 **ויאמר לו לך לשלום.** קצר הכתוב אך המובן מזה שנתן לו בקשתו במה שבקש לו לעבוד את השם יתברך: **וילך מאתו כברת ארץ.** היא הארץ הנעבדת אשר סביב העיר והרצון בו שלא הרחיק מן העיר כי לא היה בינו ובין העיר כי אם שדות העיר וכרמיה וגניה:
@569 **וארבעה אנשים היו מצורעים פתח השער.** לפי שהיו מוכרחים לעמוד מחוץ למחנה והיה שם מקום להם תוך שער העיר סמוך לפתח השער:
@571 **ויקומו וינוסו בנשף.** רוצה לומר כי בלילה שמעו הקולות אשר השמיעם השם יתברך על דרך המופת ובלילה ההוא נסו תכף ומרוב פחדם עזבו סוסיהם וחמוריהם וברחו ברגליהם:
@575 **לא כן אנחנו עושים.** ר"ל אין אנחנו עושים דבר ראוי היום הזה הוא יום ראוי לבשר ואם אנחנו שותקים ונמתין עד אור הבקר ידעו זה ישראל וימצאנו עונש על אשר לא בשרנו הבשורה הזאת והנה אז היה עדיין לילה:
@577 **ויקרא השוערים.** רוצה לומר ששוער העיר קרא השוערים אשר שומרים שער המלך:
@579 **הנם ככל המון ישראל.** הנה ההמון כתוב והמון קרי והכל ענין אחד והרצון בכתבו ההמון המון ישראל כמו והנבואה עודד הנביא והרצון בזה אם ימלטו הנם ככל המון ישראל אשר נשארו בה בעיר ואין בזה נזק ואם יפסדו הנם ככל המון ישראל אשר תמו ולא יוכר ההפסד הזה ביחס אל כל מה שנפסד מפני הרעב והנה לא הסכימו לשלוח כי אם שני רכב סוסים כי די בהם לעמד על אמתת זה:
@581 **אשר השליכו ארם בחפזם.** ר"ל מפני היותם נחפזים ללכת:
@583 **והמלך הפקיד את השליש.** ר"ל שכבר הפקידו לאנשים שישמרוהו שם באופן שבעבור העם שם ירמסוהו בעבור מה שדבר כנגד הנביא:
